static void SetApprenticeId_apprentice(void)
{
    if (gSaveBlock2Ptr->apprentices[0].number == 0)
    {
        do
        {
            PLAYER_APPRENTICE_apprentice.id = sInitialApprenticeIds[Random() % ARRAY_COUNT(sInitialApprenticeIds)];
        } while (PLAYER_APPRENTICE_apprentice.id == gSaveBlock2Ptr->apprentices[0].id);
    }
    else
    {
        do
        {
            PLAYER_APPRENTICE_apprentice.id = Random() % (NUM_APPRENTICES);
        } while (PLAYER_APPRENTICE_apprentice.id == gSaveBlock2Ptr->apprentices[0].id);
    }
}

