static void InitQuestionData_apprentice(void)
{
    u8 i;
    u8 count = 0;
    u8 id1, id2;

    for (i = 0; i < APPRENTICE_MAX_QUESTIONS && (PLAYER_APPRENTICE_apprentice.questions[i].questionId != QUESTION_ID_WIN_SPEECH); count++, i++)
        ;

    gApprenticeQuestionData = AllocZeroed(sizeof(*gApprenticeQuestionData));
    if (gSpecialVar_0x8005 == APPRENTICE_QUESTION_WHICH_MON)
    {
        if (PLAYER_APPRENTICE_apprentice.questionsAnswered < NUM_WHICH_MON_QUESTIONS)
        {
            // For the first MULTI_PARTY_SIZE (3) questions, a mon is asked to be selected for the Apprentice's party
            id1 = PLAYER_APPRENTICE_apprentice.speciesIds[PLAYER_APPRENTICE_apprentice.questionsAnswered] >> 4;
            gApprenticeQuestionData->altSpeciesId = gApprentices[PLAYER_APPRENTICE_apprentice.id].species[id1];

            id2 = PLAYER_APPRENTICE_apprentice.speciesIds[PLAYER_APPRENTICE_apprentice.questionsAnswered] & 0xF;
            gApprenticeQuestionData->speciesId = gApprentices[PLAYER_APPRENTICE_apprentice.id].species[id2];
        }
    }
    else if (gSpecialVar_0x8005 == APPRENTICE_QUESTION_WHICH_MOVE)
    {
        if (PLAYER_APPRENTICE_apprentice.questionsAnswered >= NUM_WHICH_MON_QUESTIONS
            && PLAYER_APPRENTICE_apprentice.questionsAnswered < count + NUM_WHICH_MON_QUESTIONS
            && PLAYER_APPRENTICE_apprentice.questions[CURRENT_QUESTION_NUM_apprentice].questionId == QUESTION_ID_WHICH_MOVE)
        {
            // count re-used as monId
            count = PLAYER_APPRENTICE_apprentice.questions[CURRENT_QUESTION_NUM_apprentice].monId;
            APPRENTICE_SPECIES_ID_NO_COND_apprentice(id1, count);
            gApprenticeQuestionData->speciesId = gApprentices[PLAYER_APPRENTICE_apprentice.id].species[id1];
            gApprenticeQuestionData->moveId1 = GetDefaultMove_apprentice(count, id1, PLAYER_APPRENTICE_apprentice.questions[CURRENT_QUESTION_NUM_apprentice].moveSlot);
            gApprenticeQuestionData->moveId2 = PLAYER_APPRENTICE_apprentice.questions[CURRENT_QUESTION_NUM_apprentice].data;
        }
    }
    else if (gSpecialVar_0x8005 == APPRENTICE_QUESTION_WHAT_ITEM)
    {
        if (PLAYER_APPRENTICE_apprentice.questionsAnswered >= NUM_WHICH_MON_QUESTIONS
            && PLAYER_APPRENTICE_apprentice.questionsAnswered < count + NUM_WHICH_MON_QUESTIONS
            && PLAYER_APPRENTICE_apprentice.questions[CURRENT_QUESTION_NUM_apprentice].questionId == QUESTION_ID_WHAT_ITEM)
        {
            // count re-used as monId
            count = PLAYER_APPRENTICE_apprentice.questions[CURRENT_QUESTION_NUM_apprentice].monId;
            APPRENTICE_SPECIES_ID_NO_COND_apprentice(id2, count);
            gApprenticeQuestionData->speciesId = gApprentices[PLAYER_APPRENTICE_apprentice.id].species[id2];
        }
    }
}

