static bool32 HasSuperEffectiveMoveAgainstOpponents_battle_ai_switch_items(u32 battler, bool32 noRng);
static bool32 FindMonWithFlagsAndSuperEffective_battle_ai_switch_items(u32 battler, u16 flags, u32 moduloPercent);
