static inline bool32 IsMoveSleepClauseTrigger_battle_ai_util(u32 move)
{
    u32 i, effect = GetMoveEffect(move);

    // Sleeping effects like Sleep Powder, Yawn, Dark Void, etc.
    switch (effect)
    {
    case EFFECT_SLEEP:
    case EFFECT_YAWN:
    case EFFECT_DARK_VOID:
        return TRUE;
    }

    // Sleeping effects like G-Max Befuddle, G-Max Snooze, etc.
    u32 additionalEffectCount = GetMoveAdditionalEffectCount(move);
    for (i = 0; i < additionalEffectCount; i++)
    {
        const struct AdditionalEffect *additionalEffect = GetMoveAdditionalEffectById(move, i);
        switch (additionalEffect->moveEffect)
        {
        case MAX_EFFECT_EFFECT_SPORE_FOES:
        case MAX_EFFECT_YAWN_FOE:
            return TRUE;
        }
    }
    return FALSE;
}

