#undef tInBg2_battle_anim
#undef tActive_battle_anim
#undef tIsPartner_battle_anim

#undef t2_SpriteId_battle_anim
#undef t2_SpriteX_battle_anim
#undef t2_SpriteY_battle_anim
#undef t2_BgX_battle_anim
#undef t2_BgY_battle_anim
#undef t2_InBg2_battle_anim
