static void Cmd_setarg_battle_anim(void)
{
    // Save original address to return to
    // after the T1_READ_16, + 4.
    // They could have equivalently just advanced
    // sBattleAnimScriptPtr_battle_anim by 2 afterwards.
    const u8 *addr = sBattleAnimScriptPtr_battle_anim;
    u16 value;
    u8 argId;

    sBattleAnimScriptPtr_battle_anim++;
    argId = sBattleAnimScriptPtr_battle_anim[0];
    sBattleAnimScriptPtr_battle_anim++;
    value = T1_READ_16(sBattleAnimScriptPtr_battle_anim);
    sBattleAnimScriptPtr_battle_anim = addr + 4;
    gBattleAnimArgs[argId] = value;
}

