#define tInitialPan_battle_anim     data[0]
#define tTargetPan_battle_anim      data[1]
#define tIncrementPan_battle_anim   data[2]
#define tFramesToWait_battle_anim   data[3]
#define tCurrentPan_battle_anim     data[4]
#define tFrameCounter_battle_anim   data[8]

static void Cmd_panse_battle_anim(void)
{
    u16 songNum;
    s8 currentPanArg, incrementPan, incrementPanArg, currentPan, targetPan;
    u8 framesToWait;
    u8 taskId;

    sBattleAnimScriptPtr_battle_anim++;
    songNum = T1_READ_16(sBattleAnimScriptPtr_battle_anim);
    currentPanArg = sBattleAnimScriptPtr_battle_anim[2];
    incrementPan = sBattleAnimScriptPtr_battle_anim[3]; // targetPan, var is re-used
    incrementPanArg = sBattleAnimScriptPtr_battle_anim[4];
    framesToWait = sBattleAnimScriptPtr_battle_anim[5];

    currentPan = BattleAnimAdjustPanning(currentPanArg);
    targetPan = BattleAnimAdjustPanning(incrementPan);
    incrementPan = CalculatePanIncrement(currentPan, targetPan, incrementPanArg);

    taskId = CreateTask(Task_PanFromInitialToTarget, 1);
    gTasks[taskId].tInitialPan_battle_anim = currentPan;
    gTasks[taskId].tTargetPan_battle_anim = targetPan;
    gTasks[taskId].tIncrementPan_battle_anim = incrementPan;
    gTasks[taskId].tFramesToWait_battle_anim = framesToWait;
    gTasks[taskId].tCurrentPan_battle_anim = currentPan;

    PlaySE12WithPanning(songNum, currentPan);

    gAnimSoundTaskCount++;
    sBattleAnimScriptPtr_battle_anim += 6;
}

void Task_PanFromInitialToTarget(u8 taskId)
{
    bool32 destroyTask = FALSE;
    if (gTasks[taskId].tFrameCounter_battle_anim++ >= gTasks[taskId].tFramesToWait_battle_anim)
    {
        s16 pan;
        s16 initialPanning, targetPanning, currentPan, incrementPan;

        gTasks[taskId].tFrameCounter_battle_anim = 0;
        initialPanning = gTasks[taskId].tInitialPan_battle_anim;
        targetPanning = gTasks[taskId].tTargetPan_battle_anim;
        currentPan = gTasks[taskId].tCurrentPan_battle_anim;
        incrementPan = gTasks[taskId].tIncrementPan_battle_anim;
        pan = currentPan + incrementPan;
        gTasks[taskId].tCurrentPan_battle_anim = pan;

        if (incrementPan == 0) // If we're not incrementing, just cancel the task immediately.
        {
            destroyTask = TRUE;
        }
        else if (initialPanning < targetPanning) // Panning increasing.
        {
            if (pan >= targetPanning) // Target reached.
                destroyTask = TRUE;
        }
        else // Panning decreasing.
        {
            if (pan <= targetPanning) // Target reached.
                destroyTask = TRUE;
        }

        if (destroyTask)
        {
            pan = targetPanning;
            DestroyTask(taskId);
            gAnimSoundTaskCount--;
        }

        SE12PanpotControl(pan);
    }
}

