static void Cmd_waitsound_battle_anim(void)
{
    if (gAnimSoundTaskCount != 0)
    {
        sSoundAnimFramesToWait_battle_anim = 0;
        sAnimFramesToWait_battle_anim = 1;
    }
    else if (IsSEPlaying())
    {
        if (++sSoundAnimFramesToWait_battle_anim > 90)
        {
            m4aMPlayStop(&gMPlayInfo_SE1);
            m4aMPlayStop(&gMPlayInfo_SE2);
            sSoundAnimFramesToWait_battle_anim = 0;
        }
        else
        {
            sAnimFramesToWait_battle_anim = 1;
        }
    }
    else
    {
        sSoundAnimFramesToWait_battle_anim = 0;
        sBattleAnimScriptPtr_battle_anim++;
        sAnimFramesToWait_battle_anim = 0;
    }
}

