void AnimTask_MoonlightEndFade(u8 taskId)
{
    int a = GetBattlePalettesMask(TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE) & 0xFFFF;
    int b;
    int c;
    int d;

    gTasks[taskId].data[0] = 0;
    gTasks[taskId].data[1] = 0;
    gTasks[taskId].data[2] = 0;
    gTasks[taskId].data[3] = a;
    gTasks[taskId].data[4] = 0;
    gTasks[taskId].data[5] = 0;
    gTasks[taskId].data[6] = 0;
    gTasks[taskId].data[7] = 13;
    gTasks[taskId].data[8] = 14;
    gTasks[taskId].data[9] = 15;
    b = GetBattleMonSpritePalettesMask(1, 1, 1, 1);
    c = a | b;
    StorePointerInVars(&gTasks[taskId].data[14], &gTasks[taskId].data[15], (void *)c);
    b = b | (0x10000 << IndexOfSpritePaletteTag(ANIM_TAG_MOON));
    d = IndexOfSpritePaletteTag(ANIM_TAG_GREEN_SPARKLE);
    BeginNormalPaletteFade((0x10000 << d) | b, 0, 0, 16, RGB(27, 29, 31));
    gTasks[taskId].func = AnimTask_MoonlightEndFade_Step_battle_anim_effects_1;
    gTasks[taskId].func(taskId);
}

static void AnimTask_MoonlightEndFade_Step_battle_anim_effects_1(u8 taskId)
{
    struct Task *task = &gTasks[taskId];
    switch (task->data[0])
    {
    case 0:
        if (++task->data[1] > 0)
        {
            u16 color;
            u16 bitmask;
            u16 r3;
            u16 i;
            u16 j;
            task->data[1] = 0;
            if (++task->data[2] <= 15)
            {
                u16 red;
                u16 green;
                u16 blue;
                task->data[4] += task->data[7];
                task->data[5] += task->data[8];
                task->data[6] += task->data[9];
                red = task->data[4] >> 3;
                green = task->data[5] >> 3;
                blue = task->data[6] >> 3;
                color = RGB(red, green, blue);
            }
            else
            {
                color = RGB(27, 29, 31);
                task->data[0]++;
            }

            bitmask = 1;
            r3 = 0;
            for (i = 0; i <= 15; i++)
            {
                if (task->data[3] & bitmask)
                {
                    for (j = 1; j <= 15; j++)
                    {
                        gPlttBufferFaded[r3 + j] = color;
                    }
                }

                bitmask <<= 1;
                r3 += 16;
            }
        }
        break;
    case 1:
        if (!gPaletteFade.active)
        {
            u8 spriteId;
            for (spriteId = 0; spriteId < MAX_SPRITES; spriteId++)
            {
                if (gSprites[spriteId].template == &gMoonSpriteTemplate || gSprites[spriteId].template == &gMoonlightSparkleSpriteTemplate)
                    gSprites[spriteId].data[0] = 1;
            }

            task->data[1] = 0;
            task->data[0]++;
        }
        break;
    case 2:
        if (++task->data[1] > 30)
        {
            BeginNormalPaletteFade((u32)LoadPointerFromVars(task->data[14], task->data[15]), 0, 16, 0, RGB(27, 29, 31));
            task->data[0]++;
        }
        break;
    case 3:
        if (!gPaletteFade.active)
            DestroyAnimVisualTask(taskId);
        break;
    }
}

static void AnimHornHit_battle_anim_effects_1(struct Sprite *sprite)
{
    if (gBattleAnimArgs[2] < 2)
        gBattleAnimArgs[2] = 2;

    if (gBattleAnimArgs[2] > 0x7F)
        gBattleAnimArgs[2] = 0x7F;

    sprite->data[0] = 0;
    sprite->data[1] = gBattleAnimArgs[2];
    sprite->x = GetBattlerSpriteCoord(gBattleAnimTarget, BATTLER_COORD_X_2) + gBattleAnimArgs[0];
    sprite->y = GetBattlerSpriteCoord(gBattleAnimTarget, BATTLER_COORD_Y_PIC_OFFSET) + gBattleAnimArgs[1];
    sprite->data[6] = sprite->x;
    sprite->data[7] = sprite->y;
    if (IsContest())
    {
        sprite->oam.matrixNum = ST_OAM_HFLIP;
        sprite->x += 40;
        sprite->y += 20;
        sprite->data[2] = sprite->x << 7;
        sprite->data[3] = -0x1400 / sprite->data[1];
        sprite->data[4] = sprite->y << 7;
        sprite->data[5] = -0xA00 / sprite->data[1];
    }
    else if (GetBattlerSide(gBattleAnimAttacker) == B_SIDE_PLAYER)
    {
        sprite->x -= 40;
        sprite->y += 20;
        sprite->data[2] = sprite->x << 7;
        sprite->data[3] = 0x1400 / sprite->data[1];
        sprite->data[4] = sprite->y << 7;
        sprite->data[5] = -0xA00 / sprite->data[1];
    }
    else
    {
        sprite->x += 40;
        sprite->y -= 20;
        sprite->data[2] = sprite->x << 7;
        sprite->data[3] = -0x1400 / sprite->data[1];
        sprite->data[4] = sprite->y << 7;
        sprite->data[5] = 0xA00 / sprite->data[1];
        sprite->oam.matrixNum = (ST_OAM_HFLIP | ST_OAM_VFLIP);
    }

    sprite->callback = AnimHornHit_Step_battle_anim_effects_1;
}

static void AnimHornHit_Step_battle_anim_effects_1(struct Sprite *sprite)
{
    sprite->data[2] += sprite->data[3];
    sprite->data[4] += sprite->data[5];
    sprite->x = sprite->data[2] >> 7;
    sprite->y = sprite->data[4] >> 7;
    if (--sprite->data[1] == 1)
    {
        sprite->x = sprite->data[6];
        sprite->y = sprite->data[7];
    }

    if (sprite->data[1] == 0)
        DestroyAnimSprite(sprite);
}

// Double Team and Ally Switch.
#define tBattlerSpriteId_battle_anim_effects_1    data[0]
#define tSpoonPal_battle_anim_effects_1           data[1]
#define tBlendSpritesCount_battle_anim_effects_1  data[3]
#define tBattlerId_battle_anim_effects_1          data[4]
#define tIsAllySwitch_battle_anim_effects_1       data[5]

#define sCounter_battle_anim_effects_1            data[0]
#define sSinIndex_battle_anim_effects_1           data[1]
#define sTaskId_battle_anim_effects_1             data[2]
#define sCounter2_battle_anim_effects_1           data[3]
#define sSinAmplitude_battle_anim_effects_1       data[4]
#define sSinIndexMod_battle_anim_effects_1        data[5]
#define sBattlerFlank_battle_anim_effects_1       data[6]

void PrepareDoubleTeamAnim(u32 taskId, u32 animBattler, bool32 forAllySwitch)
{
    s32 i, spriteId;
    u16 palOffsetBattler, palOffsetSpoon;
    struct Task *task = &gTasks[taskId];

    task->tBattlerSpriteId_battle_anim_effects_1 = GetAnimBattlerSpriteId(animBattler);
    task->tSpoonPal_battle_anim_effects_1 = AllocSpritePalette(ANIM_TAG_BENT_SPOON);
    task->tBattlerId_battle_anim_effects_1 = GetAnimBattlerId(animBattler);
    task->tIsAllySwitch_battle_anim_effects_1 = forAllySwitch;
    palOffsetSpoon = OBJ_PLTT_ID(task->tSpoonPal_battle_anim_effects_1);
    palOffsetBattler = OBJ_PLTT_ID2(gSprites[task->tBattlerSpriteId_battle_anim_effects_1].oam.paletteNum);
    for (i = 1; i < 16; i++)
        gPlttBufferUnfaded[palOffsetSpoon + i] = gPlttBufferUnfaded[palOffsetBattler + i];

    BlendPalette(palOffsetSpoon, 16, 11, RGB_BLACK);
    task->tBlendSpritesCount_battle_anim_effects_1 = 0;
    for (i = 0; i < ((forAllySwitch == TRUE) ? 1 : 2); i++)
    {
        spriteId = CloneBattlerSpriteWithBlend(animBattler);
        if (spriteId < 0)
            break;
        gSprites[spriteId].oam.paletteNum = task->tSpoonPal_battle_anim_effects_1;
        gSprites[spriteId].sCounter_battle_anim_effects_1 = 0;
        gSprites[spriteId].sSinIndex_battle_anim_effects_1 = i << 7;
        gSprites[spriteId].sTaskId_battle_anim_effects_1 = taskId;
        // Which direction
        if (gBattleAnimAttacker & BIT_FLANK)
            gSprites[spriteId].sBattlerFlank_battle_anim_effects_1 = (animBattler != ANIM_ATTACKER);
        else
            gSprites[spriteId].sBattlerFlank_battle_anim_effects_1 = (animBattler == ANIM_ATTACKER);

        // correct direction on opponent side
        if (GetBattlerSide(gBattleAnimAttacker) == B_SIDE_OPPONENT)
            gSprites[spriteId].sBattlerFlank_battle_anim_effects_1 ^= 1;

        gSprites[spriteId].callback = AnimDoubleTeam_battle_anim_effects_1;
        task->tBlendSpritesCount_battle_anim_effects_1++;
    }

    task->func = AnimTask_DoubleTeam_Step_battle_anim_effects_1;
    if (GetBattlerSpriteBGPriorityRank(task->tBattlerId_battle_anim_effects_1) == 1)
        ClearGpuRegBits(REG_OFFSET_DISPCNT, DISPCNT_BG1_ON);
    else
        ClearGpuRegBits(REG_OFFSET_DISPCNT, DISPCNT_BG2_ON);
}

void AnimTask_DoubleTeam(u8 taskId)
{
    PrepareDoubleTeamAnim(taskId, ANIM_ATTACKER, FALSE);
}

static inline void SwapStructData_battle_anim_effects_1(void *s1, void *s2, void *data, u32 size)
{
    memcpy(data, s1, size);
    memcpy(s1, s2, size);
    memcpy(s2, data, size);
}

static void ReloadBattlerSprites_battle_anim_effects_1(u32 battler, struct Pokemon *party)
{
    struct Pokemon *mon = &party[gBattlerPartyIndexes[battler]];
    BattleLoadMonSpriteGfx(mon, battler);
    CreateBattlerSprite(battler);
    UpdateHealthboxAttribute(gHealthboxSpriteIds[battler], mon, HEALTHBOX_ALL);
    // If battler has an indicator for a gimmick, hide the sprite until the move animation finishes.
    UpdateIndicatorVisibilityAndType(gHealthboxSpriteIds[battler], TRUE);

    // Try to recreate shadow sprite
    if (B_ENEMY_MON_SHADOW_STYLE >= GEN_4 && P_GBA_STYLE_SPECIES_GFX == FALSE)
    {
        // Both of these *should* be true, but use an OR just to be certain
        if (gBattleSpritesDataPtr->healthBoxesData[battler].shadowSpriteIdPrimary < MAX_SPRITES
            || gBattleSpritesDataPtr->healthBoxesData[battler].shadowSpriteIdSecondary < MAX_SPRITES)
        {
            DestroySprite(&gSprites[gBattleSpritesDataPtr->healthBoxesData[battler].shadowSpriteIdPrimary]);
            DestroySprite(&gSprites[gBattleSpritesDataPtr->healthBoxesData[battler].shadowSpriteIdSecondary]);
            gBattleSpritesDataPtr->healthBoxesData[battler].shadowSpriteIdPrimary = MAX_SPRITES;
            gBattleSpritesDataPtr->healthBoxesData[battler].shadowSpriteIdSecondary = MAX_SPRITES;
            CreateEnemyShadowSprite(battler);
            SetBattlerShadowSpriteCallback(battler, GetMonData(mon, MON_DATA_SPECIES));
        }
    }
    else
    {
        if (gBattleSpritesDataPtr->healthBoxesData[battler].shadowSpriteIdPrimary < MAX_SPRITES)
        {
            DestroySprite(&gSprites[gBattleSpritesDataPtr->healthBoxesData[battler].shadowSpriteIdPrimary]);
            gBattleSpritesDataPtr->healthBoxesData[battler].shadowSpriteIdPrimary = MAX_SPRITES;
            CreateEnemyShadowSprite(battler);
            SetBattlerShadowSpriteCallback(battler, GetMonData(mon, MON_DATA_SPECIES));
        }
    }
}

static void TrySwapSkyDropTargets_battle_anim_effects_1(u32 battlerAtk, u32 battlerPartner)
{
    u32 i, temp;

    // battlerAtk is using Ally Switch
    // check if our partner is the target of sky drop
    // If so, change that index to battlerAtk
    for (i = 0; i < gBattlersCount; i++) {
        if (gBattleStruct->skyDropTargets[i] == battlerPartner) {
            gBattleStruct->skyDropTargets[i] = battlerAtk;
            break;
        }
    }

    // Then swap our own sky drop targets with the partner in case our partner is mid-skydrop
    SWAP(gBattleStruct->skyDropTargets[battlerAtk], gBattleStruct->skyDropTargets[battlerPartner], temp);
}

#define TRY_SIDE_TIMER_BATTLER_ID_SWAP_battle_anim_effects_1(battlerAtk, battlerPartner, side, field)    \
    if (gSideTimers[side].field == battlerAtk)                      \
        gSideTimers[side].field = battlerPartner;                   \
    else if (gSideTimers[side].field == battlerPartner)             \
        gSideTimers[side].field = battlerAtk;

static void TrySwapStickyWebBattlerId_battle_anim_effects_1(u32 battlerAtk, u32 battlerPartner)
{
    u32 atkSide = GetBattlerSide(battlerAtk);
    u32 oppSide = GetBattlerSide(BATTLE_OPPOSITE(battlerAtk));

    // not all of these are needed to be swapped, but are done so to be robust to anything in the future that might care about them
    TRY_SIDE_TIMER_BATTLER_ID_SWAP_battle_anim_effects_1(battlerAtk, battlerPartner, atkSide, reflectBattlerId);
    TRY_SIDE_TIMER_BATTLER_ID_SWAP_battle_anim_effects_1(battlerAtk, battlerPartner, atkSide, lightscreenBattlerId);
    TRY_SIDE_TIMER_BATTLER_ID_SWAP_battle_anim_effects_1(battlerAtk, battlerPartner, atkSide, mistBattlerId);
    TRY_SIDE_TIMER_BATTLER_ID_SWAP_battle_anim_effects_1(battlerAtk, battlerPartner, atkSide, safeguardBattlerId);
    TRY_SIDE_TIMER_BATTLER_ID_SWAP_battle_anim_effects_1(battlerAtk, battlerPartner, atkSide, auroraVeilBattlerId);
    TRY_SIDE_TIMER_BATTLER_ID_SWAP_battle_anim_effects_1(battlerAtk, battlerPartner, atkSide, tailwindBattlerId);
    TRY_SIDE_TIMER_BATTLER_ID_SWAP_battle_anim_effects_1(battlerAtk, battlerPartner, atkSide, luckyChantBattlerId);

    // if we've set sticky web on the opposing side, need to swap stickyWebBattlerId for mirror armor
    TRY_SIDE_TIMER_BATTLER_ID_SWAP_battle_anim_effects_1(battlerAtk, battlerPartner, oppSide, stickyWebBattlerId);
}
#undef TRY_SIDE_TIMER_BATTLER_ID_SWAP_battle_anim_effects_1

static void TrySwapWishBattlerIds_battle_anim_effects_1(u32 battlerAtk, u32 battlerPartner)
{
    u32 i, temp;
    u32 oppSide = GetBattlerSide(BATTLE_OPPOSITE(battlerAtk));

    // if used future sight on opposing side, properly track who used it
    if (gSideStatuses[oppSide] & SIDE_STATUS_FUTUREATTACK) {
        for (i = 0; i < gBattlersCount; i++) {
            if (IsAlly(i,battlerAtk))
                continue;   // only on opposing side
            if (gWishFutureKnock.futureSightBattlerIndex[i] == battlerAtk) {
                // if target was attacked with future sight from us, now they'll be the partner slot
                gWishFutureKnock.futureSightBattlerIndex[i] = battlerPartner;
                gWishFutureKnock.futureSightPartyIndex[i] = gBattlerPartyIndexes[battlerPartner];
                break;
            } else if (gWishFutureKnock.futureSightBattlerIndex[i] == battlerPartner) {
                gWishFutureKnock.futureSightBattlerIndex[i] = battlerAtk;
                gWishFutureKnock.futureSightPartyIndex[i] = gBattlerPartyIndexes[battlerAtk];
                break;
            }
        }
    }

    // swap wish party indices
    if (gWishFutureKnock.wishCounter[battlerAtk] > 0
            || gWishFutureKnock.wishCounter[battlerPartner] > 0) {
        SWAP(gWishFutureKnock.wishPartyId[battlerAtk], gWishFutureKnock.wishPartyId[battlerPartner], temp);
    }
}

static void AnimTask_AllySwitchDataSwap_battle_anim_effects_1(u8 taskId)
{
    s32 i, j;
    struct Pokemon *party;
    u32 temp;
    u32 battlerAtk = gBattlerAttacker;
    u32 battlerPartner = BATTLE_PARTNER(battlerAtk);

    void *data = Alloc(0x200);
    if (data == NULL)
    {
        SoftReset(1);
    }

    SwapStructData_battle_anim_effects_1(&gBattleMons[battlerAtk], &gBattleMons[battlerPartner], data, sizeof(struct BattlePokemon));
    SwapStructData_battle_anim_effects_1(&gDisableStructs[battlerAtk], &gDisableStructs[battlerPartner], data, sizeof(struct DisableStruct));
    SwapStructData_battle_anim_effects_1(&gSpecialStatuses[battlerAtk], &gSpecialStatuses[battlerPartner], data, sizeof(struct SpecialStatus));
    SwapStructData_battle_anim_effects_1(&gProtectStructs[battlerAtk], &gProtectStructs[battlerPartner], data, sizeof(struct ProtectStruct));
    SwapStructData_battle_anim_effects_1(&gBattleSpritesDataPtr->battlerData[battlerAtk], &gBattleSpritesDataPtr->battlerData[battlerPartner], data, sizeof(struct BattleSpriteInfo));
    SwapStructData_battle_anim_effects_1(&gBattleStruct->illusion[battlerAtk], &gBattleStruct->illusion[battlerPartner], data, sizeof(struct Illusion));

    SWAP(gBattleSpritesDataPtr->battlerData[battlerAtk].invisible, gBattleSpritesDataPtr->battlerData[battlerPartner].invisible, temp);
    SWAP(gTransformedPersonalities[battlerAtk], gTransformedPersonalities[battlerPartner], temp);
    SWAP(gTransformedShininess[battlerAtk], gTransformedShininess[battlerPartner], temp);
    SWAP(gStatuses3[battlerAtk], gStatuses3[battlerPartner], temp);
    SWAP(gStatuses4[battlerAtk], gStatuses4[battlerPartner], temp);
    SWAP(gBattleStruct->chosenMovePositions[battlerAtk], gBattleStruct->chosenMovePositions[battlerPartner], temp);
    SWAP(gChosenMoveByBattler[battlerAtk], gChosenMoveByBattler[battlerPartner], temp);
    SWAP(gLockedMoves[battlerAtk], gLockedMoves[battlerPartner], temp);
    SWAP(gBattleStruct->moveTarget[battlerAtk], gBattleStruct->moveTarget[battlerPartner], temp);
    SWAP(gMoveSelectionCursor[battlerAtk], gMoveSelectionCursor[battlerPartner], temp);
    // Swap turn order, so that all the battlers take action
    SWAP(gChosenActionByBattler[battlerAtk], gChosenActionByBattler[battlerPartner], temp);
    for (i = 0; i < MAX_BATTLERS_COUNT; i++)
    {
        if (gBattlerByTurnOrder[i] == battlerAtk || gBattlerByTurnOrder[i] == battlerPartner)
        {
            for (j = i + 1; j < MAX_BATTLERS_COUNT; j++)
            {
                if (gBattlerByTurnOrder[j] == battlerAtk || gBattlerByTurnOrder[j] == battlerPartner)
                    break;
            }
            SWAP(gBattlerByTurnOrder[i], gBattlerByTurnOrder[j], temp);
            SWAP(gActionsByTurnOrder[i], gActionsByTurnOrder[j], temp);
            break;
        }
    }

    party = GetBattlerParty(battlerAtk);
    SwitchTwoBattlersInParty(battlerAtk, battlerPartner);
    SWAP(gBattlerPartyIndexes[battlerAtk], gBattlerPartyIndexes[battlerPartner], temp);

    TrySwapSkyDropTargets_battle_anim_effects_1(battlerAtk, battlerPartner);
    TrySwapStickyWebBattlerId_battle_anim_effects_1(battlerAtk, battlerPartner);
    TrySwapWishBattlerIds_battle_anim_effects_1(battlerAtk, battlerPartner);

    // For Snipe Shot and abilities Stalwart/Propeller Tail - keep the original target.
    for (i = 0; i < MAX_BATTLERS_COUNT; i++)
    {
        u16 ability = GetBattlerAbility(i);
        if (gChosenMoveByBattler[i] == MOVE_SNIPE_SHOT || ability == ABILITY_PROPELLER_TAIL || ability == ABILITY_STALWART)
            gBattleStruct->moveTarget[i] ^= BIT_FLANK;
    }

    // For some reason the order in which the sprites are created matters. Looks like an issue with the sprite system, potentially with the Sprite Template.
    if ((battlerAtk & BIT_FLANK) != 0)
    {
        ReloadBattlerSprites_battle_anim_effects_1(battlerAtk, party);
        ReloadBattlerSprites_battle_anim_effects_1(battlerPartner, party);
    }
    else
    {
        ReloadBattlerSprites_battle_anim_effects_1(battlerPartner, party);
        ReloadBattlerSprites_battle_anim_effects_1(battlerAtk, party);
    }

    Free(data);

    gBattleScripting.battler = battlerPartner;
    DestroyAnimVisualTask(taskId);
}

static void AnimTask_DoubleTeam_Step_battle_anim_effects_1(u8 taskId)
{
    struct Task *task = &gTasks[taskId];
    if (task->tBlendSpritesCount_battle_anim_effects_1 == 0)
    {
        if (GetBattlerSpriteBGPriorityRank(task->tBattlerId_battle_anim_effects_1) == 1)
            SetGpuRegBits(REG_OFFSET_DISPCNT, DISPCNT_BG1_ON);
        else
            SetGpuRegBits(REG_OFFSET_DISPCNT, DISPCNT_BG2_ON);

        FreeSpritePaletteByTag(ANIM_TAG_BENT_SPOON);
        // Swap attacker and partner data-wise and visually
        if (task->tIsAllySwitch_battle_anim_effects_1 && task->tBattlerId_battle_anim_effects_1 == BATTLE_PARTNER(gBattlerAttacker))
            gTasks[taskId].func = AnimTask_AllySwitchDataSwap_battle_anim_effects_1;
        else
            DestroyAnimVisualTask(taskId);
    }
}

static void AnimDoubleTeam_battle_anim_effects_1(struct Sprite *sprite)
{
    if (++sprite->sCounter2_battle_anim_effects_1 > 1)
    {
        sprite->sCounter2_battle_anim_effects_1 = 0;
        sprite->sCounter_battle_anim_effects_1++;
    }

    if (sprite->sCounter_battle_anim_effects_1 > 64)
    {
        gTasks[sprite->sTaskId_battle_anim_effects_1].tBlendSpritesCount_battle_anim_effects_1--;
        // If Ally Switch - destroy the mon sprites, they'll be created again later.
        if (gTasks[sprite->sTaskId_battle_anim_effects_1].tIsAllySwitch_battle_anim_effects_1 && gTasks[sprite->sTaskId_battle_anim_effects_1].tBattlerId_battle_anim_effects_1 == BATTLE_PARTNER(gBattlerAttacker))
        {
            DestroySprite(&gSprites[gBattlerSpriteIds[gBattlerAttacker]]);
            DestroySprite(&gSprites[gBattlerSpriteIds[BATTLE_PARTNER(gBattlerAttacker)]]);
        }
        DestroySpriteWithActiveSheet(sprite);
    }
    else
    {
        sprite->sSinAmplitude_battle_anim_effects_1 = gSineTable[sprite->sCounter_battle_anim_effects_1] / 6;
        sprite->sSinIndexMod_battle_anim_effects_1 = gSineTable[sprite->sCounter_battle_anim_effects_1] / 13;
        sprite->sSinIndex_battle_anim_effects_1 = (sprite->sSinIndex_battle_anim_effects_1 + sprite->sSinIndexMod_battle_anim_effects_1) & 0xFF;
        sprite->x2 = Sin(sprite->sSinIndex_battle_anim_effects_1, sprite->sSinAmplitude_battle_anim_effects_1);
        if (gTasks[sprite->sTaskId_battle_anim_effects_1].tIsAllySwitch_battle_anim_effects_1)
        {
            if (sprite->sBattlerFlank_battle_anim_effects_1)
                sprite->x2 = abs(sprite->x2);
            else
                sprite->x2 = -(abs(sprite->x2));
        }
    }
}

void AnimTask_AllySwitchAttacker(u8 taskId)
{
    PrepareDoubleTeamAnim(taskId, ANIM_ATTACKER, TRUE);
    gSprites[gBattlerSpriteIds[gBattlerAttacker]].invisible = TRUE;
    gSprites[gBattlerSpriteIds[BATTLE_PARTNER(gBattlerAttacker)]].invisible = TRUE;
    // Edge case: Partner's sprite is invisible(i.e. after using Dig).
    if (gBattleSpritesDataPtr->battlerData[BATTLE_PARTNER(gBattlerAttacker)].invisible)
    {
        gBattleSpritesDataPtr->battlerData[BATTLE_PARTNER(gBattlerAttacker)].invisible = FALSE;
        gBattleSpritesDataPtr->battlerData[gBattlerAttacker].invisible = TRUE;
    }
}

void AnimTask_AllySwitchPartner(u8 taskId)
{
    PrepareDoubleTeamAnim(taskId, ANIM_ATK_PARTNER, TRUE);
}

