#undef tSpoonPal_battle_anim_effects_1
#undef tBlendSpritesCount_battle_anim_effects_1
#undef tBattlerId_battle_anim_effects_1
#undef tIsAllySwitch_battle_anim_effects_1

#undef sCounter_battle_anim_effects_1
#undef sSinIndex_battle_anim_effects_1
#undef sTaskId_battle_anim_effects_1
#undef sCounter2_battle_anim_effects_1
#undef sSinAmplitude_battle_anim_effects_1
#undef sSinIndexMod_battle_anim_effects_1
