        PrepareAffineAnimInTaskData(&gTasks[taskId], GetAnimBattlerSpriteId(ANIM_TARGET), sAffineAnims_StretchBattlerUp_battle_anim_effects_2);
        gSprites[spriteId].x2 = 4;
