#undef tTimer_battle_anim_effects_3
#undef tActiveSprites_battle_anim_effects_3
#undef tNumSquishes_battle_anim_effects_3
#undef tBaseX_battle_anim_effects_3
#undef tBaseY_battle_anim_effects_3
