// Moves a noise line from the mon.
// arg 0: initial x pixel offset
// arg 1: initial y pixel offset
// arg 2: which direction (0 = upward, 1 = downward, 2 = horizontal)
static void AnimRoarNoiseLine_battle_anim_effects_3(struct Sprite *sprite)
{
    if (GetBattlerSide(gBattleAnimAttacker) == B_SIDE_OPPONENT)
        gBattleAnimArgs[0] = -gBattleAnimArgs[0];

    sprite->x = GetBattlerSpriteCoord(gBattleAnimAttacker, BATTLER_COORD_X) + gBattleAnimArgs[0];
    sprite->y = GetBattlerSpriteCoord(gBattleAnimAttacker, BATTLER_COORD_Y) + gBattleAnimArgs[1];
    if (gBattleAnimArgs[2] == 0)
    {
        sprite->data[0] = 0x280;
        sprite->data[1] = -0x280;
    }
    else if (gBattleAnimArgs[2] == 1)
    {
        sprite->vFlip = 1;
        sprite->data[0] = 0x280;
        sprite->data[1] = 0x280;
    }
    else
    {
        StartSpriteAnim(sprite, 1);
        sprite->data[0] = 0x280;
    }

    if (GetBattlerSide(gBattleAnimAttacker) != B_SIDE_PLAYER)
    {
        sprite->data[0] = -sprite->data[0];
        sprite->hFlip = 1;
    }

    sprite->callback = AnimRoarNoiseLine_Step_battle_anim_effects_3;
}

static void AnimRoarNoiseLine_Step_battle_anim_effects_3(struct Sprite *sprite)
{
    sprite->data[6] += sprite->data[0];
    sprite->data[7] += sprite->data[1];
    sprite->x2 = sprite->data[6] >> 8;
    sprite->y2 = sprite->data[7] >> 8;
    if (++sprite->data[5] == 14)
        DestroyAnimSprite(sprite);
}

#define IDX_ACTIVE_SPRITES_battle_anim_effects_3 10  // Used by the sprite callback to modify the number of active sprites

// Task data for AnimTask_GlareEyeDots
#define tState_battle_anim_effects_3         data[0]
#define tTimer_battle_anim_effects_3         data[1]
#define tPairNum_battle_anim_effects_3       data[2]
#define tPairMax_battle_anim_effects_3       data[5]
#define tDotOffset_battle_anim_effects_3     data[6]
#define tIsContest_battle_anim_effects_3     data[7]
#define tActiveSprites_battle_anim_effects_3 data[IDX_ACTIVE_SPRITES_battle_anim_effects_3]
#define tStartX_battle_anim_effects_3        data[11]
#define tStartY_battle_anim_effects_3        data[12]
#define tEndX_battle_anim_effects_3          data[13]
#define tEndY_battle_anim_effects_3          data[14]

// Sprite data for AnimGlareEyeDot_battle_anim_effects_3
#define sTimer_battle_anim_effects_3            data[0]
#define sTaskId_battle_anim_effects_3           data[1]
#define sActiveSpritesIdx_battle_anim_effects_3 data[2]

// Makes a series of dots in a trail from the attacker to the target.
// arg 0: unused
void AnimTask_GlareEyeDots(u8 taskId)
{
    struct Task *task = &gTasks[taskId];

    if (IsContest())
    {
        task->tPairMax_battle_anim_effects_3 = 8;
        task->tDotOffset_battle_anim_effects_3 = 3;
        task->tIsContest_battle_anim_effects_3 = TRUE;
    }
    else
    {
        task->tPairMax_battle_anim_effects_3 = 12;
        task->tDotOffset_battle_anim_effects_3 = 3;
        task->tIsContest_battle_anim_effects_3 = FALSE;
    }

    if (GetBattlerSide(gBattleAnimAttacker) == B_SIDE_PLAYER)
        task->tStartX_battle_anim_effects_3 = GetBattlerSpriteCoord(gBattleAnimAttacker, BATTLER_COORD_X_2) + GetBattlerSpriteCoordAttr(gBattleAnimAttacker, BATTLER_COORD_ATTR_HEIGHT) / 4;
    else
        task->tStartX_battle_anim_effects_3 = GetBattlerSpriteCoord(gBattleAnimAttacker, BATTLER_COORD_X_2) - GetBattlerSpriteCoordAttr(gBattleAnimAttacker, BATTLER_COORD_ATTR_HEIGHT) / 4;

    task->tStartY_battle_anim_effects_3 = GetBattlerSpriteCoord(gBattleAnimAttacker, BATTLER_COORD_Y_PIC_OFFSET) - GetBattlerSpriteCoordAttr(gBattleAnimAttacker, BATTLER_COORD_ATTR_HEIGHT) / 4;
    task->tEndX_battle_anim_effects_3 = GetBattlerSpriteCoord(gBattleAnimTarget, BATTLER_COORD_X_2);
    task->tEndY_battle_anim_effects_3 = GetBattlerSpriteCoord(gBattleAnimTarget, BATTLER_COORD_Y_PIC_OFFSET);
    task->func = AnimTask_GlareEyeDots_Step_battle_anim_effects_3;
}

static void AnimTask_GlareEyeDots_Step_battle_anim_effects_3(u8 taskId)
{
    u8 i;
    s16 x, y;
    struct Task *task = &gTasks[taskId];

    switch (task->tState_battle_anim_effects_3)
    {
    case 0:
        // Wait to create next pair of dots
        if (++task->tTimer_battle_anim_effects_3 > 3)
        {
            task->tTimer_battle_anim_effects_3 = 0;
            GetGlareEyeDotCoords_battle_anim_effects_3(
                task->tStartX_battle_anim_effects_3,
                task->tStartY_battle_anim_effects_3,
                task->tEndX_battle_anim_effects_3,
                task->tEndY_battle_anim_effects_3,
                task->tPairMax_battle_anim_effects_3,
                task->tPairNum_battle_anim_effects_3,
                &x,
                &y);

            // Create dot pair
            for (i = 0; i < 2; i++)
            {
                u8 spriteId = CreateSprite(&gGlareEyeDotSpriteTemplate, x, y, 35);
                if (spriteId != MAX_SPRITES)
                {
                    if (!task->tIsContest_battle_anim_effects_3)
                    {
                        if (i == 0)
                            gSprites[spriteId].x2 = gSprites[spriteId].y2 = -task->tDotOffset_battle_anim_effects_3;
                        else
                            gSprites[spriteId].x2 = gSprites[spriteId].y2 = task->tDotOffset_battle_anim_effects_3;
                    }
                    else
                    {
                        if (i == 0)
                        {
                            gSprites[spriteId].x2 = -task->tDotOffset_battle_anim_effects_3;
                            gSprites[spriteId].y2 = task->tDotOffset_battle_anim_effects_3;
                        }
                        else
                        {
                            gSprites[spriteId].x2 = task->tDotOffset_battle_anim_effects_3;
                            gSprites[spriteId].y2 = -task->tDotOffset_battle_anim_effects_3;
                        }
                    }

                    gSprites[spriteId].sTimer_battle_anim_effects_3 = 0;
                    gSprites[spriteId].sTaskId_battle_anim_effects_3 = taskId;
                    gSprites[spriteId].sActiveSpritesIdx_battle_anim_effects_3 = IDX_ACTIVE_SPRITES_battle_anim_effects_3;
                    task->tActiveSprites_battle_anim_effects_3++;
                }
            }

            if (task->tPairNum_battle_anim_effects_3 == task->tPairMax_battle_anim_effects_3)
                task->tState_battle_anim_effects_3++;

            task->tPairNum_battle_anim_effects_3++;
        }
        break;
    case 1:
        // Wait for sprites to be destroyed before ending task
        if (task->tActiveSprites_battle_anim_effects_3 == 0)
            DestroyAnimVisualTask(taskId);
        break;
    }
}

static void GetGlareEyeDotCoords_battle_anim_effects_3(s16 startX, s16 startY, s16 endX, s16 endY, u8 pairMax, u8 pairNum, s16 *x, s16 *y)
{
    int x2;
    int y2;

    if (pairNum == 0)
    {
        *x = startX;
        *y = startY;
        return;
    }

    if (pairNum >= pairMax)
    {
        *x = endX;
        *y = endY;
        return;
    }

    pairMax--;
    x2 = (startX << 8) + pairNum * (((endX - startX) << 8) / pairMax);
    y2 = (startY << 8) + pairNum * (((endY - startY) << 8) / pairMax);
    *x = x2 >> 8;
    *y = y2 >> 8;
}

static void AnimGlareEyeDot_battle_anim_effects_3(struct Sprite *sprite)
{
    if (++sprite->sTimer_battle_anim_effects_3 > 36)
    {
        gTasks[sprite->sTaskId_battle_anim_effects_3].data[sprite->sActiveSpritesIdx_battle_anim_effects_3]--;
        DestroySprite(sprite);
    }
}

