static void AnimLavaPlumeOrbitScatter_battle_anim_fire(struct Sprite *sprite)
{
    sprite->x = GetBattlerSpriteCoord(gBattleAnimAttacker, 2);
    sprite->y = GetBattlerSpriteCoord(gBattleAnimAttacker, 3);
    sprite->data[0] = Sin(gBattleAnimArgs[0], 10);
    sprite->data[1] = Cos(gBattleAnimArgs[0], 7);
    sprite->callback = AnimLavaPlumeOrbitScatterStep_battle_anim_fire;
}

static void AnimLavaPlumeOrbitScatterStep_battle_anim_fire(struct Sprite *sprite)
{
    sprite->x2 += sprite->data[0];
    sprite->y2 += sprite->data[1];
    if (sprite->x + sprite->x2 + 16 > 272u || sprite->y + sprite->y2 > 160 || sprite->y + sprite->y2 < -16)
        DestroyAnimSprite(sprite);
}

// For the first stage of Fire Punch
static void AnimFireSpiralInward_battle_anim_fire(struct Sprite *sprite)
{
    sprite->data[0] = gBattleAnimArgs[0];
    sprite->data[1] = 0x3C;
    sprite->data[2] = 0x9;
    sprite->data[3] = 0x1E;
    sprite->data[4] = 0xFE00;

    StoreSpriteCallbackInData6(sprite, DestroyAnimSprite);

    sprite->callback = TranslateSpriteInGrowingCircle;
    sprite->callback(sprite);
}

// For the impact spread of fire sprites for moves like Blaze Kick or Fire Punch
void AnimFireSpread(struct Sprite *sprite)
{
    SetAnimSpriteInitialXOffset(sprite, gBattleAnimArgs[0]);

    sprite->y += gBattleAnimArgs[1];
    sprite->data[0] = gBattleAnimArgs[4];
    sprite->data[1] = gBattleAnimArgs[2];
    sprite->data[2] = gBattleAnimArgs[3];

    sprite->callback = TranslateSpriteLinearFixedPoint;
    StoreSpriteCallbackInData6(sprite, DestroyAnimSprite);
}

void AnimFirePlume(struct Sprite *sprite)
{
    SetSpriteCoordsToAnimAttackerCoords(sprite);

    if (GetBattlerSide(gBattleAnimAttacker))
    {
        sprite->x -= gBattleAnimArgs[0];
        sprite->y += gBattleAnimArgs[1];
        sprite->data[2] = -gBattleAnimArgs[4];
    }
    else
    {
        sprite->x += gBattleAnimArgs[0];
        sprite->y += gBattleAnimArgs[1];
        sprite->data[2] = gBattleAnimArgs[4];
    }

    sprite->data[1] = gBattleAnimArgs[2];
    sprite->data[4] = gBattleAnimArgs[3];
    sprite->data[3] = gBattleAnimArgs[5];

    sprite->callback = AnimLargeFlame_Step_battle_anim_fire;
}

static void AnimLargeFlame_battle_anim_fire(struct Sprite *sprite)
{
    if (GetBattlerSide(gBattleAnimAttacker))
    {
        sprite->x -= gBattleAnimArgs[0];
        sprite->y += gBattleAnimArgs[1];
        sprite->data[2] = gBattleAnimArgs[4];
    }
    else
    {
        sprite->x += gBattleAnimArgs[0];
        sprite->y += gBattleAnimArgs[1];
        sprite->data[2] = -gBattleAnimArgs[4];
    }

    sprite->data[1] = gBattleAnimArgs[2];
    sprite->data[4] = gBattleAnimArgs[3];
    sprite->data[3] = gBattleAnimArgs[5];

    sprite->callback = AnimLargeFlame_Step_battle_anim_fire;
}

static void AnimLargeFlame_Step_battle_anim_fire(struct Sprite *sprite)
{
    if (++sprite->data[0] < sprite->data[4])
    {
        sprite->x2 += sprite->data[2];
        sprite->y2 += sprite->data[3];
    }

    if (sprite->data[0] == sprite->data[1])
        DestroySpriteAndMatrix(sprite);
}

static void AnimUnusedSmallEmber_battle_anim_fire(struct Sprite *sprite)
{
    SetSpriteCoordsToAnimAttackerCoords(sprite);

    if (GetBattlerSide(gBattleAnimAttacker))
    {
        sprite->x -= gBattleAnimArgs[0];
    }
    else
    {
        sprite->x += gBattleAnimArgs[0];
        sprite->subpriority = 8;
    }

    sprite->y += gBattleAnimArgs[1];
    sprite->data[0] = gBattleAnimArgs[2];
    sprite->data[1] = gBattleAnimArgs[3];
    sprite->data[2] = gBattleAnimArgs[4];
    sprite->data[3] = gBattleAnimArgs[5];
    sprite->data[4] = gBattleAnimArgs[6];
    sprite->data[5] = 0;

    sprite->callback = AnimUnusedSmallEmber_Step_battle_anim_fire;
}

static void AnimUnusedSmallEmber_Step_battle_anim_fire(struct Sprite *sprite)
{
    if (sprite->data[3])
    {
        if(sprite->data[5] > 10000)
            sprite->subpriority = 1;

        sprite->x2 = Sin(sprite->data[0], sprite->data[1] + (sprite->data[5] >> 8));
        sprite->y2 = Cos(sprite->data[0], sprite->data[1] + (sprite->data[5] >> 8));

        sprite->data[0] += sprite->data[2];
        sprite->data[5] += sprite->data[4];

        if (sprite->data[0] > 255)
            sprite->data[0] -= 256;
        else if (sprite->data[0] < 0)
            sprite->data[0] += 256;

        sprite->data[3]--;
    }
    else
    {
        DestroySpriteAndMatrix(sprite);
    }
}

// Sunlight from Sunny Day / sunny weather
static void AnimSunlight_battle_anim_fire(struct Sprite *sprite)
{
    sprite->x = 0;
    sprite->y = 0;
    sprite->data[0] = 60;
    sprite->data[2] = 140;
    sprite->data[4] = 80;
    sprite->callback = StartAnimLinearTranslation;
    StoreSpriteCallbackInData6(sprite, DestroyAnimSprite);
}

// Animates the secondary effect of MOVE_EMBER, where the flames grow and slide
// horizontally a bit.
// arg 0: initial x pixel offset
// arg 1: initial y pixel offset
// arg 2: target x pixel offset
// arg 3: target y pixel offset
// arg 4: duration
// arg 5: ? (todo: something related to which mon the pixel offsets are based on)
// arg 6: ? (todo: something related to which mon the pixel offsets are based on)
static void AnimEmberFlare_battle_anim_fire(struct Sprite *sprite)
{
    if (GetBattlerSide(gBattleAnimAttacker) == GetBattlerSide(gBattleAnimTarget)
        && (gBattleAnimAttacker == GetBattlerAtPosition(B_POSITION_PLAYER_RIGHT)
            || gBattleAnimAttacker == GetBattlerAtPosition(B_POSITION_OPPONENT_RIGHT)))
            gBattleAnimArgs[2] = -gBattleAnimArgs[2];

    sprite->callback = AnimTravelDiagonally;
    sprite->callback(sprite);
}

static void AnimBurnFlame_battle_anim_fire(struct Sprite *sprite)
{
    gBattleAnimArgs[0] = -gBattleAnimArgs[0];
    gBattleAnimArgs[2] = -gBattleAnimArgs[2];

    sprite->callback = AnimTravelDiagonally;
}

// Animates the a fire sprite in the first-half of the MOVE_FIRE_BLAST
// animation.  The fire sprite first moves in a circle around the mon,
// and then it is translated towards the target mon, while still rotating.
// Lastly, it moves in a circle around the target mon.
// arg 0: initial x pixel offset
// arg 1: initial y pixel offset
// arg 2: initial wave offset
//void AnimFireRing(struct Sprite *sprite)
void AnimFireRing(struct Sprite *sprite)
{
    InitSpritePosToAnimAttacker(sprite, TRUE);

    sprite->data[7] = gBattleAnimArgs[2];
    sprite->data[0] = 0;

    sprite->callback = AnimFireRing_Step1_battle_anim_fire;
}

static void AnimFireRing_Step1_battle_anim_fire(struct Sprite *sprite)
{
    UpdateFireRingCircleOffset_battle_anim_fire(sprite);

    if (++sprite->data[0] == 0x12)
    {
        sprite->data[0] = 0x19;
        sprite->data[1] = sprite->x;
        sprite->data[2] = GetBattlerSpriteCoord(gBattleAnimTarget, BATTLER_COORD_X_2);
        sprite->data[3] = sprite->y;
        sprite->data[4] = GetBattlerSpriteCoord(gBattleAnimTarget, BATTLER_COORD_Y_PIC_OFFSET);

        InitAnimLinearTranslation(sprite);

        sprite->callback = AnimFireRing_Step2_battle_anim_fire;
    }
}

static void AnimFireRing_Step2_battle_anim_fire(struct Sprite *sprite)
{
    if (AnimTranslateLinear(sprite))
    {
        sprite->data[0] = 0;

        sprite->x = GetBattlerSpriteCoord(gBattleAnimTarget, BATTLER_COORD_X_2);
        sprite->y = GetBattlerSpriteCoord(gBattleAnimTarget, BATTLER_COORD_Y_PIC_OFFSET);
        sprite->y2 = 0;
        sprite->x2 = 0;

        sprite->callback = AnimFireRing_Step3_battle_anim_fire;
        sprite->callback(sprite);
    }
    else
    {
        sprite->x2 += Sin(sprite->data[7], 28);
        sprite->y2 += Cos(sprite->data[7], 28);

        sprite->data[7] = (sprite->data[7] + 20) & 0xFF;
    }
}

static void AnimFireRing_Step3_battle_anim_fire(struct Sprite *sprite)
{
    UpdateFireRingCircleOffset_battle_anim_fire(sprite);

    if (++sprite->data[0] == 0x1F)
        DestroyAnimSprite(sprite);
}

static void UpdateFireRingCircleOffset_battle_anim_fire(struct Sprite *sprite)
{
    sprite->x2 = Sin(sprite->data[7], 28);
    sprite->y2 = Cos(sprite->data[7], 28);

    sprite->data[7] = (sprite->data[7] + 20) & 0xFF;
}

// arg 0: initial x pixel offset
// arg 1: initial y pixel offset
// arg 2: duration
// arg 3: x delta
// arg 4: y delta
// AnimFireCross(struct Sprite *sprite)
void AnimFireCross(struct Sprite *sprite)
{
    sprite->x += gBattleAnimArgs[0];
    sprite->y += gBattleAnimArgs[1];

    sprite->data[0] = gBattleAnimArgs[2];
    sprite->data[1] = gBattleAnimArgs[3];
    sprite->data[2] = gBattleAnimArgs[4];

    StoreSpriteCallbackInData6(sprite, DestroyAnimSprite);

    sprite->callback = TranslateSpriteLinear;
}

void AnimFireSpiralOutward(struct Sprite *sprite)
{
    InitSpritePosToAnimAttacker(sprite, TRUE);

    sprite->data[1] = gBattleAnimArgs[2];
    sprite->data[0] = gBattleAnimArgs[3];

    sprite->invisible = TRUE;
    sprite->callback = WaitAnimForDuration;

    StoreSpriteCallbackInData6(sprite, AnimFireSpiralOutward_Step1_battle_anim_fire);
}

static void AnimFireSpiralOutward_Step1_battle_anim_fire(struct Sprite *sprite)
{
    sprite->invisible = FALSE;

    sprite->data[0] = sprite->data[1];
    sprite->data[1] = 0;

    sprite->callback = AnimFireSpiralOutward_Step2_battle_anim_fire;
    sprite->callback(sprite);
}

static void AnimFireSpiralOutward_Step2_battle_anim_fire(struct Sprite *sprite)
{
    sprite->x2 = Sin(sprite->data[1], sprite->data[2] >> 8);
    sprite->y2 = Cos(sprite->data[1], sprite->data[2] >> 8);

    sprite->data[1] = (sprite->data[1] + 10) & 0xFF;
    sprite->data[2] += 0xD0;

    if (--sprite->data[0] == -1)
        DestroyAnimSprite(sprite);
}

#define IDX_ACTIVE_SPRITES_battle_anim_fire 6  // Used by the sprite callback to modify the number of active sprites

#define tState_battle_anim_fire            data[0]
#define tTimer1_battle_anim_fire           data[1]
#define tTimer2_battle_anim_fire           data[2]
#define tTimer3_battle_anim_fire           data[3]
#define tAttackerY_battle_anim_fire        data[4]
#define tAttackerSide_battle_anim_fire     data[5]
#define tActiveSprites_battle_anim_fire    data[IDX_ACTIVE_SPRITES_battle_anim_fire]
// data[8]-data[15] used by PrepareEruptAnimTaskData / UpdateEruptAnimTask
#define tAttackerSpriteId_battle_anim_fire data[15]

#define sSpeedDelay_battle_anim_fire       data[0]
#define sLaunchStage_battle_anim_fire      data[1]
#define sX_battle_anim_fire                data[2]
#define sY_battle_anim_fire                data[3]
#define sSpeedX_battle_anim_fire           data[4]
#define sSpeedY_battle_anim_fire           data[5]
#define sTaskId_battle_anim_fire           data[6]
#define sActiveSpritesIdx_battle_anim_fire data[7]

// Animates first stage of Eruption where the attacker squishes and launches rocks away from themself
void AnimTask_EruptionLaunchRocks(u8 taskId)
{
    struct Task *task = &gTasks[taskId];

    task->tAttackerSpriteId_battle_anim_fire = GetAnimBattlerSpriteId(ANIM_ATTACKER);

    task->tState_battle_anim_fire = 0;
    task->tTimer1_battle_anim_fire = 0;
    task->tTimer2_battle_anim_fire = 0;
    task->tTimer3_battle_anim_fire = 0;
    task->tAttackerY_battle_anim_fire = gSprites[task->tAttackerSpriteId_battle_anim_fire].y;
    task->tAttackerSide_battle_anim_fire = GetBattlerSide(gBattleAnimAttacker);
    task->tActiveSprites_battle_anim_fire = 0;

    PrepareBattlerSpriteForRotScale(task->tAttackerSpriteId_battle_anim_fire, ST_OAM_OBJ_NORMAL);

    task->func = AnimTask_EruptionLaunchRocks_Step_battle_anim_fire;
}

static void AnimTask_EruptionLaunchRocks_Step_battle_anim_fire(u8 taskId)
{
    struct Task *task = &gTasks[taskId];

    switch (task->tState_battle_anim_fire)
    {
    case 0:
        PrepareEruptAnimTaskData(task, task->tAttackerSpriteId_battle_anim_fire, 0x100, 0x100, 0xE0, 0x200, 32);
        task->tState_battle_anim_fire++;
    case 1:
        if (++task->tTimer1_battle_anim_fire > 1)
        {
            task->tTimer1_battle_anim_fire = 0;

            if (++task->tTimer2_battle_anim_fire & 1)
                gSprites[task->tAttackerSpriteId_battle_anim_fire].x2 = 3;
            else
                gSprites[task->tAttackerSpriteId_battle_anim_fire].x2 = -3;
        }

        if (task->tAttackerSide_battle_anim_fire != B_SIDE_PLAYER)
        {
            if (++task->tTimer3_battle_anim_fire > 4)
            {
                task->tTimer3_battle_anim_fire = 0;
                gSprites[task->tAttackerSpriteId_battle_anim_fire].y++;
            }
        }

        if(!UpdateEruptAnimTask(task))
        {
            SetBattlerSpriteYOffsetFromYScale(task->tAttackerSpriteId_battle_anim_fire);
            gSprites[task->tAttackerSpriteId_battle_anim_fire].x2 = 0;

            task->tTimer1_battle_anim_fire = 0;
            task->tTimer2_battle_anim_fire = 0;
            task->tTimer3_battle_anim_fire = 0;
            task->tState_battle_anim_fire++;
        }
        break;
    case 2:
        if (++task->tTimer1_battle_anim_fire > 4)
        {
            if (task->tAttackerSide_battle_anim_fire != B_SIDE_PLAYER)
                PrepareEruptAnimTaskData(task, task->tAttackerSpriteId_battle_anim_fire, 0xE0, 0x200, 0x180, 0xF0, 6);
            else
                PrepareEruptAnimTaskData(task, task->tAttackerSpriteId_battle_anim_fire, 0xE0, 0x200, 0x180, 0xC0, 6);

            task->tTimer1_battle_anim_fire = 0;
            task->tState_battle_anim_fire++;
        }
        break;
    case 3:
        if (!UpdateEruptAnimTask(task))
        {
            CreateEruptionLaunchRocks_battle_anim_fire(task->tAttackerSpriteId_battle_anim_fire, taskId, IDX_ACTIVE_SPRITES_battle_anim_fire);
            task->tState_battle_anim_fire++;
        }
        break;
    case 4:
        if (++task->tTimer1_battle_anim_fire > 1)
        {
            task->tTimer1_battle_anim_fire = 0;

            if (++task->tTimer2_battle_anim_fire & 1)
                gSprites[task->tAttackerSpriteId_battle_anim_fire].y2 += 3;
            else
                gSprites[task->tAttackerSpriteId_battle_anim_fire].y2 -= 3;
        }

        if (++task->tTimer3_battle_anim_fire > 24)
        {
            if (task->tAttackerSide_battle_anim_fire != B_SIDE_PLAYER)
                PrepareEruptAnimTaskData(task, task->tAttackerSpriteId_battle_anim_fire, 0x180, 0xF0, 0x100, 0x100, 8);
            else
                PrepareEruptAnimTaskData(task, task->tAttackerSpriteId_battle_anim_fire, 0x180, 0xC0, 0x100, 0x100, 8);

            if (task->tTimer2_battle_anim_fire & 1)
                gSprites[task->tAttackerSpriteId_battle_anim_fire].y2 -= 3;

            task->tTimer1_battle_anim_fire = 0;
            task->tTimer2_battle_anim_fire = 0;
            task->tTimer3_battle_anim_fire = 0;
            task->tState_battle_anim_fire++;
        }
        break;
    case 5:
        if (task->tAttackerSide_battle_anim_fire != B_SIDE_PLAYER)
            gSprites[task->tAttackerSpriteId_battle_anim_fire].y--;

        if (!UpdateEruptAnimTask(task))
        {
            gSprites[task->tAttackerSpriteId_battle_anim_fire].y = task->tAttackerY_battle_anim_fire;
            ResetSpriteRotScale(task->tAttackerSpriteId_battle_anim_fire);
            task->tTimer2_battle_anim_fire = 0;
            task->tState_battle_anim_fire++;
        }
        break;
    case 6:
        if (task->tActiveSprites_battle_anim_fire == 0)
            DestroyAnimVisualTask(taskId);
        break;
    default:
        break;
    }
}

static void CreateEruptionLaunchRocks_battle_anim_fire(u8 spriteId, u8 taskId, u8 activeSpritesIdx)
{
    u16 i, j;
    s8 sign;

    u16 y = GetEruptionLaunchRockInitialYPos_battle_anim_fire(spriteId);
    u16 x = gSprites[spriteId].x;

    if(GetBattlerSide(gBattleAnimAttacker) == B_SIDE_PLAYER)
    {
        x -= 12;
        sign = 1;
    }
    else
    {
        x += 16;
        sign = -1;
    }

    for (i = 0, j = 0; i <= 6; i++)
    {
        u8 spriteId = CreateSprite(&gEruptionLaunchRockSpriteTemplate, x, y, 2);

        if (spriteId != MAX_SPRITES)
        {
            gSprites[spriteId].oam.tileNum += j * 4 + 0x40;

            if (++j >= 5)
                j = 0;

            InitEruptionLaunchRockCoordData_battle_anim_fire(&gSprites[spriteId], sEruptionLaunchRockSpeeds_battle_anim_fire[i][0] * sign, sEruptionLaunchRockSpeeds_battle_anim_fire[i][1]);
            gSprites[spriteId].sTaskId_battle_anim_fire = taskId;
            gSprites[spriteId].sActiveSpritesIdx_battle_anim_fire = activeSpritesIdx;

            gTasks[taskId].data[activeSpritesIdx]++;
        }
    }
}

static void AnimEruptionLaunchRock_battle_anim_fire(struct Sprite *sprite)
{
    UpdateEruptionLaunchRockPos_battle_anim_fire(sprite);

    if (sprite->invisible)
    {
        gTasks[sprite->sTaskId_battle_anim_fire].data[sprite->sActiveSpritesIdx_battle_anim_fire]--;
        DestroySprite(sprite);
    }
}

static u16 GetEruptionLaunchRockInitialYPos_battle_anim_fire(u8 spriteId)
{
    s16 y = gSprites[spriteId].y + gSprites[spriteId].y2 + gSprites[spriteId].centerToCornerVecY;

    if (GetBattlerSide(gBattleAnimAttacker) == B_SIDE_PLAYER)
        y += 74;
    else
        y += 44;

    return y;
}

static void InitEruptionLaunchRockCoordData_battle_anim_fire(struct Sprite *sprite, s16 speedX, s16 speedY)
{
    sprite->sSpeedDelay_battle_anim_fire = 0;
    sprite->sLaunchStage_battle_anim_fire = 0;
    sprite->sX_battle_anim_fire = (u16)sprite->x * 8;
    sprite->sY_battle_anim_fire = (u16)sprite->y * 8;
    sprite->sSpeedX_battle_anim_fire = speedX * 8;
    sprite->sSpeedY_battle_anim_fire = speedY * 8;
}

static void UpdateEruptionLaunchRockPos_battle_anim_fire(struct Sprite *sprite)
{
    int extraLaunchSpeed;
    if (++sprite->sSpeedDelay_battle_anim_fire > 2)
    {
        sprite->sSpeedDelay_battle_anim_fire = 0;
        ++sprite->sLaunchStage_battle_anim_fire;
        extraLaunchSpeed = (u16)sprite->sLaunchStage_battle_anim_fire * (u16)sprite->sLaunchStage_battle_anim_fire;
        sprite->sY_battle_anim_fire += extraLaunchSpeed;
    }

    sprite->sX_battle_anim_fire += sprite->sSpeedX_battle_anim_fire;
    sprite->x = sprite->sX_battle_anim_fire >> 3;
    sprite->sY_battle_anim_fire += sprite->sSpeedY_battle_anim_fire;
    sprite->y = sprite->sY_battle_anim_fire >> 3;

    if (sprite->x < -8 || sprite->x > DISPLAY_WIDTH + 8 || sprite->y < -8 || sprite->y > 120)
        sprite->invisible = TRUE;
}

