#define sState_battle_anim_fire       data[0]
#define sBounceTimer_battle_anim_fire data[1]
#define sBounceDir_battle_anim_fire   data[2]
#define sEndTimer_battle_anim_fire    data[3]
#define sFallDelay_battle_anim_fire   data[6]
#define sTargetY_battle_anim_fire     data[7]

void AnimEruptionFallingRock(struct Sprite *sprite)
{
    sprite->x = gBattleAnimArgs[0];
    sprite->y = gBattleAnimArgs[1];

    sprite->sState_battle_anim_fire = 0;
    sprite->sBounceTimer_battle_anim_fire = 0;
    sprite->sBounceDir_battle_anim_fire = 0;
    sprite->sFallDelay_battle_anim_fire = gBattleAnimArgs[2];
    sprite->sTargetY_battle_anim_fire = gBattleAnimArgs[3];

    sprite->oam.tileNum += gBattleAnimArgs[4] * 16;
    sprite->callback = AnimEruptionFallingRock_Step_battle_anim_fire;
}

static void AnimEruptionFallingRock_Step_battle_anim_fire(struct Sprite *sprite)
{
    switch (sprite->sState_battle_anim_fire)
    {
    case 0:
        // Wait to begin falling
        if (sprite->sFallDelay_battle_anim_fire != 0)
        {
            sprite->sFallDelay_battle_anim_fire--;
            return;
        }

        sprite->sState_battle_anim_fire++;
        // fall through
    case 1:
        // Rock is falling
        sprite->y += 8;
        if (sprite->y >= sprite->sTargetY_battle_anim_fire)
        {
            sprite->y = sprite->sTargetY_battle_anim_fire;
            sprite->sState_battle_anim_fire++;
        }
        break;
    case 2:
        // Bounce up and down on landing spot
        if (++sprite->sBounceTimer_battle_anim_fire > 1)
        {
            sprite->sBounceTimer_battle_anim_fire = 0;
            if ((++sprite->sBounceDir_battle_anim_fire & 1) != 0)
                sprite->y2 = -3;
            else
                sprite->y2 = 3;
        }

        if (++sprite->sEndTimer_battle_anim_fire > 16)
            DestroyAnimSprite(sprite);
        break;
    }
}

#undef sState_battle_anim_fire
#undef sBounceTimer_battle_anim_fire
#undef sBounceDir_battle_anim_fire
#undef sEndTimer_battle_anim_fire
#undef sFallDelay_battle_anim_fire
#undef sTargetY_battle_anim_fire

void AnimWillOWispOrb(struct Sprite *sprite)
{
    switch (sprite->data[0])
    {
    case 0:
        InitSpritePosToAnimAttacker(sprite, FALSE);
        StartSpriteAnim(sprite, gBattleAnimArgs[2]);
        sprite->data[7] = gBattleAnimArgs[2];

        if (GetBattlerSide(gBattleAnimAttacker) != B_SIDE_PLAYER)
        {
            sprite->data[4] = 4;
        }
        else
        {
            sprite->data[4] = -4;
        }

        sprite->oam.priority = GetBattlerSpriteBGPriority(gBattleAnimTarget);
        sprite->data[0]++;
        break;
    case 1:
        sprite->data[1] += 192;
        if (GetBattlerSide(gBattleAnimAttacker) != B_SIDE_PLAYER)
        {
            sprite->y2 = -(sprite->data[1] >> 8);
        }
        else
        {
            sprite->y2 = sprite->data[1] >> 8;
        }

        sprite->x2 = Sin(sprite->data[2], sprite->data[4]);
        sprite->data[2] = (sprite->data[2] + 4) & 0xFF;

        if (++sprite->data[3] == 1)
        {
            sprite->data[3] = 0;
            sprite->data[0]++;
        }
        break;
    case 2:
        sprite->x2 = Sin(sprite->data[2], sprite->data[4]);
        sprite->data[2] = (sprite->data[2] + 4) & 0xFF;

        if (++sprite->data[3] == 31)
        {
            sprite->x += sprite->x2;
            sprite->y += sprite->y2;
            sprite->y2 = 0;
            sprite->x2 = 0;

            sprite->data[0] = 256;
            sprite->data[1] = sprite->x;
            sprite->data[2] = GetBattlerSpriteCoord(gBattleAnimTarget, BATTLER_COORD_X_2);
            sprite->data[3] = sprite->y;
            sprite->data[4] = GetBattlerSpriteCoord(gBattleAnimTarget, BATTLER_COORD_Y_PIC_OFFSET);

            InitAnimLinearTranslationWithSpeed(sprite);
            sprite->callback = AnimWillOWispOrb_Step_battle_anim_fire;
        }
        break;
    }
}

static void AnimWillOWispOrb_Step_battle_anim_fire(struct Sprite *sprite)
{
    s16 initialData5;
    s16 newData5;

    if (!AnimTranslateLinear(sprite))
    {
        sprite->x2 += Sin(sprite->data[5], 16);
        initialData5 = sprite->data[5];
        sprite->data[5] = (sprite->data[5] + 4) & 0xFF;
        newData5 = sprite->data[5];

        if ((initialData5 == 0 || initialData5 > 196) && newData5 > 0 && sprite->data[7] == 0)
        {
            PlaySE12WithPanning(SE_M_FLAME_WHEEL, gAnimCustomPanning);
        }
    }
    else
    {
        DestroyAnimSprite(sprite);
    }
}

static void AnimWillOWispFire_battle_anim_fire(struct Sprite *sprite)
{
    if (!sprite->data[0])
    {
        sprite->data[1] = gBattleAnimArgs[0];
        sprite->data[0] += 1;
    }

    sprite->data[3] += 0xC0 * 2;
    sprite->data[4] += 0xA0;

    sprite->x2 = Sin(sprite->data[1], sprite->data[3] >> 8);
    sprite->y2 = Cos(sprite->data[1], sprite->data[4] >> 8);

    sprite->data[1] = (sprite->data[1] + 7) & 0xFF;

    if (!IsContest())
    {
        if (sprite->data[1] < 64 || sprite->data[1] > 195)
            sprite->oam.priority = GetBattlerSpriteBGPriority(gBattleAnimTarget);
        else
            sprite->oam.priority = GetBattlerSpriteBGPriority(gBattleAnimTarget) + 1;
    }
    else
    {
        if (sprite->data[1] < 64 || sprite->data[1] > 195)
            sprite->subpriority = 0x1D;
        else
            sprite->subpriority = 0x1F;
    }

    if (++sprite->data[2] > 0x14)
        sprite->invisible ^= 1;

    if (sprite->data[2] == 0x1E)
        DestroyAnimSprite(sprite);
}

void AnimTask_MoveHeatWaveTargets(u8 taskId)
{
    struct Task *task = &gTasks[taskId];

    task->data[12] = GetBattlerSide(gBattleAnimAttacker) == B_SIDE_PLAYER ? 1 : -1;
    task->data[13] = IsBattlerSpriteVisible(BATTLE_PARTNER(gBattleAnimTarget)) + 1;
    task->data[14] = GetAnimBattlerSpriteId(ANIM_TARGET);
    task->data[15] = GetAnimBattlerSpriteId(ANIM_DEF_PARTNER);

    task->func = AnimTask_MoveHeatWaveTargets_Step_battle_anim_fire;
}

static void AnimTask_MoveHeatWaveTargets_Step_battle_anim_fire(u8 taskId)
{
    struct Task *task = &gTasks[taskId];

    switch (task->data[0])
    {
        case 0:
            task->data[10] += task->data[12] * 2;
            if (++task->data[1] >= 2)
            {
                task->data[1] = 0;
                task->data[2]++;
                if (task->data[2] & 1)
                    task->data[11] = 2;
                else
                    task->data[11] = -2;
            }

            for (task->data[3] = 0; task->data[3] < task->data[13]; task->data[3]++)
            {
                gSprites[task->data[task->data[3] + 14]].x2 = task->data[10] + task->data[11];
            }

            if (++task->data[9] == 16)
            {
                task->data[9] = 0;
                task->data[0]++;
            }
            break;
        case 1:
            if (++task->data[1] >= 5)
            {
                task->data[1] = 0;
                task->data[2]++;

                if (task->data[2] & 1)
                    task->data[11] = 2;
                else
                    task->data[11] = -2;
            }

            for (task->data[3] = 0; task->data[3] < task->data[13]; task->data[3]++)
            {
                gSprites[task->data[task->data[3] + 14]].x2 = task->data[10] + task->data[11];
            }

            if (++task->data[9] == 96)
            {
                task->data[9] = 0;
                task->data[0]++;
            }
            break;
        case 2:
            task->data[10] -= task->data[12] * 2;

            if (++task->data[1] >= 2)
            {
                task->data[1] = 0;
                task->data[2]++;

                if (task->data[2] & 1)
                    task->data[11] = 2;
                else
                    task->data[11] = -2;
            }

            for (task->data[3] = 0; task->data[3] < task->data[13]; task->data[3]++)
            {
                gSprites[task->data[task->data[3] + 14]].x2 = task->data[10] + task->data[11];
            }

            if (++task->data[9] == 16)
            {
                task->data[0]++;
            }
            break;
        case 3:
            for (task->data[3] = 0; task->data[3] < task->data[13]; task->data[3]++)
            {
                gSprites[task->data[task->data[3] + 14]].x2 = 0;
            }

            DestroyAnimVisualTask(taskId);
            break;
    }
}

// Used to add a color mask to the battle background.
// arg 0: opacity
// arg 1: color code
void AnimTask_BlendBackground(u8 taskId)
{
    struct BattleAnimBgData animBg;
    GetBattleAnimBg1Data(&animBg);
    BlendPalette(BG_PLTT_ID(animBg.paletteId), 16, gBattleAnimArgs[0], gBattleAnimArgs[1]);
    DestroyAnimVisualTask(taskId);
}

#define tShakeNum_battle_anim_fire    data[0]
#define tMaxShakes_battle_anim_fire   data[1]
#define tShakeOffset_battle_anim_fire data[2] // Never read, gBattleAnimArgs[1] is used directly instead
#define tVertical_battle_anim_fire    data[3]
#define tPatternId_battle_anim_fire   data[4]

// Shakes target horizontally or vertically tMaxShakes_battle_anim_fire times, following a set pattern of alternations
void AnimTask_ShakeTargetInPattern(u8 taskId)
{
    s8 dir;
    u8 spriteId;

    if (gTasks[taskId].tShakeNum_battle_anim_fire == 0)
    {
        gTasks[taskId].tMaxShakes_battle_anim_fire = gBattleAnimArgs[0];
        gTasks[taskId].tShakeOffset_battle_anim_fire = gBattleAnimArgs[1];
        gTasks[taskId].tVertical_battle_anim_fire = gBattleAnimArgs[2];
        gTasks[taskId].tPatternId_battle_anim_fire = gBattleAnimArgs[3];
    }
    gTasks[taskId].tShakeNum_battle_anim_fire++;

    spriteId = gBattlerSpriteIds[gBattleAnimTarget];

    if (gTasks[taskId].tPatternId_battle_anim_fire == 0)
        dir = sShakeDirsPattern0_battle_anim_fire[gTasks[taskId].tShakeNum_battle_anim_fire % 10];
    else
        dir = sShakeDirsPattern1_battle_anim_fire[gTasks[taskId].tShakeNum_battle_anim_fire % 10];

    if (gTasks[taskId].tVertical_battle_anim_fire == TRUE)
        gSprites[spriteId].y2 = gBattleAnimArgs[1] * dir < 0 ? -(gBattleAnimArgs[1] * dir) : gBattleAnimArgs[1] * dir;
    else
        gSprites[spriteId].x2 = gBattleAnimArgs[1] * dir;

    if (gTasks[taskId].tShakeNum_battle_anim_fire == gTasks[taskId].tMaxShakes_battle_anim_fire)
    {
        gSprites[spriteId].x2 = 0;
        gSprites[spriteId].y2 = 0;
        DestroyAnimVisualTask(taskId);
    }
}
