// Moves a bone projectile towards the target mon, which moves like
// a boomerang. After hitting the target mon, it comes back to the user.
static void AnimBonemerangProjectile_battle_anim_ground(struct Sprite *sprite)
{
    sprite->x = GetBattlerSpriteCoord(gBattleAnimAttacker, BATTLER_COORD_X_2);
    sprite->y = GetBattlerSpriteCoord(gBattleAnimAttacker, BATTLER_COORD_Y_PIC_OFFSET);
    sprite->data[0] = 20;
    sprite->data[2] = GetBattlerSpriteCoord(gBattleAnimTarget, BATTLER_COORD_X_2);
    sprite->data[4] = GetBattlerSpriteCoord(gBattleAnimTarget, BATTLER_COORD_Y_PIC_OFFSET);
    sprite->data[5] = -40;
    InitAnimArcTranslation(sprite);
    sprite->callback = AnimBonemerangProjectile_Step_battle_anim_ground;
}

static void AnimBonemerangProjectile_Step_battle_anim_ground(struct Sprite *sprite)
{
    if (TranslateAnimHorizontalArc(sprite))
    {
        sprite->x += sprite->x2;
        sprite->y += sprite->y2;
        sprite->y2 = 0;
        sprite->x2 = 0;
        sprite->data[0] = 20;
        sprite->data[2] = GetBattlerSpriteCoord(gBattleAnimAttacker, BATTLER_COORD_X_2);
        sprite->data[4] = GetBattlerSpriteCoord(gBattleAnimAttacker, BATTLER_COORD_Y_PIC_OFFSET);
        sprite->data[5] = 40;
        InitAnimArcTranslation(sprite);
        sprite->callback = AnimBonemerangProjectile_End_battle_anim_ground;
    }
}

static void AnimBonemerangProjectile_End_battle_anim_ground(struct Sprite *sprite)
{
    if (TranslateAnimHorizontalArc(sprite))
        DestroyAnimSprite(sprite);
}

// Moves a bone projectile towards the target mon, starting right next to
// the target mon.
// arg 0: initial x pixel offset
// arg 1: initial y pixel offset
// arg 2: target x pixel offset
// arg 3: target y pixel offset
// arg 4: duration
static void AnimBoneHitProjectile_battle_anim_ground(struct Sprite *sprite)
{
    InitSpritePosToAnimTarget(sprite, TRUE);
    if (GetBattlerSide(gBattleAnimAttacker) != B_SIDE_PLAYER)
        gBattleAnimArgs[2] = -gBattleAnimArgs[2];

    sprite->data[0] = gBattleAnimArgs[4];
    sprite->data[2] = GetBattlerSpriteCoord(gBattleAnimTarget, BATTLER_COORD_X_2) + gBattleAnimArgs[2];
    sprite->data[4] = GetBattlerSpriteCoord(gBattleAnimTarget, BATTLER_COORD_Y_PIC_OFFSET) + gBattleAnimArgs[3];
    sprite->callback = StartAnimLinearTranslation;
    StoreSpriteCallbackInData6(sprite, DestroyAnimSprite);
}

// Moves a small dirt projectile towards the target mon.
// arg 0: initial x pixel offset
// arg 1: initial y pixel offset
// arg 2: duration
// arg 3: target x pixel offset
// arg 4: target y pixel offset
void AnimDirtScatter(struct Sprite *sprite)
{
    u8 targetXPos, targetYPos;
    s16 xOffset, yOffset;

    InitSpritePosToAnimAttacker(sprite, TRUE);

    targetXPos = GetBattlerSpriteCoord2(gBattleAnimTarget, BATTLER_COORD_X_2);
    targetYPos = GetBattlerSpriteCoord2(gBattleAnimTarget, BATTLER_COORD_Y_PIC_OFFSET);

    xOffset = Random2() & 0x1F;
    yOffset = Random2() & 0x1F;
    if (xOffset > 16)
        xOffset = 16 - xOffset;
    if (yOffset > 16)
        yOffset = 16 - yOffset;

    sprite->data[0] = gBattleAnimArgs[2];
    sprite->data[2] = targetXPos + xOffset;
    sprite->data[4] = targetYPos + yOffset;
    sprite->callback = StartAnimLinearTranslation;
    StoreSpriteCallbackInData6(sprite, DestroySpriteAndMatrix);
}

// Moves a particle of dirt in the Mud Sport animation.
// The dirt can either be rising upward, or falling down.
// arg 0: 0 = dirt is rising into the air, 1 = dirt is falling down
// arg 1: initial x pixel offset
// arg 2: initial y pixel offset
void AnimMudSportDirt(struct Sprite *sprite)
{
    sprite->oam.tileNum++;
    if (gBattleAnimArgs[0] == 0)
    {
        sprite->x = GetBattlerSpriteCoord(gBattleAnimAttacker, BATTLER_COORD_X_2) + gBattleAnimArgs[1];
        sprite->y = GetBattlerSpriteCoord(gBattleAnimAttacker, BATTLER_COORD_Y_PIC_OFFSET) + gBattleAnimArgs[2];
        sprite->data[0] = gBattleAnimArgs[1] > 0 ? 1 : -1;
        sprite->callback = AnimMudSportDirtRising;
    }
    else
    {
        sprite->x = gBattleAnimArgs[1];
        sprite->y = gBattleAnimArgs[2];
        sprite->y2 = -gBattleAnimArgs[2];
        sprite->callback = AnimMudSportDirtFalling_battle_anim_ground;
    }
}

void AnimMudSportDirtRising(struct Sprite *sprite)
{
    if (++sprite->data[1] > 1)
    {
        sprite->data[1] = 0;
        sprite->x += sprite->data[0];
    }

    sprite->y -= 4;
    if (sprite->y < -4)
        DestroyAnimSprite(sprite);
}

static void AnimMudSportDirtFalling_battle_anim_ground(struct Sprite *sprite)
{
    switch (sprite->data[0])
    {
    case 0:
        sprite->y2 += 4;
        if (sprite->y2 >= 0)
        {
            sprite->y2 = 0;
            sprite->data[0]++;
        }
        break;
    case 1:
        if (++sprite->data[1] > 0)
        {
            sprite->data[1] = 0;
            sprite->invisible ^= 1;
            if (++sprite->data[2] == 10)
                DestroyAnimSprite(sprite);
        }
        break;
    }
}

void AnimTask_DigDownMovement(u8 taskId)
{
    struct Task *task = &gTasks[taskId];

    if (gBattleAnimArgs[0] == FALSE)
        task->func = AnimTask_DigBounceMovement_battle_anim_ground;
    else
        task->func = AnimTask_DigEndBounceMovementSetInvisible_battle_anim_ground;

    task->func(taskId);
}

static void AnimTask_DigBounceMovement_battle_anim_ground(u8 taskId)
{
    u8 y;
    struct Task *task = &gTasks[taskId];

    switch (task->data[0])
    {
    case 0:
        task->data[10] = GetAnimBattlerSpriteId(ANIM_ATTACKER);
        task->data[11] = GetBattlerSpriteBGPriorityRank(gBattleAnimAttacker);
        if (task->data[11] == 1)
        {
            task->data[12] = gBattle_BG1_X;
            task->data[13] = gBattle_BG1_Y;
        }
        else
        {
            task->data[12] = gBattle_BG2_X;
            task->data[13] = gBattle_BG2_Y;
        }

        y = GetBattlerYCoordWithElevation(gBattleAnimAttacker);
        task->data[14] = y - 32;
        task->data[15] = y + 32;
        if (task->data[14] < 0)
            task->data[14] = 0;

        gSprites[task->data[10]].invisible = TRUE;
        task->data[0]++;
        break;
    case 1:
        SetDigScanlineEffect_battle_anim_ground(task->data[11], task->data[14], task->data[15]);
        task->data[0]++;
        break;
    case 2:
        task->data[2] = (task->data[2] + 6) & 0x7F;
        if (++task->data[4] > 2)
        {
            task->data[4] = 0;
            task->data[3]++;
        }

        task->data[5] = task->data[3] + (gSineTable[task->data[2]] >> 4);
        if (task->data[11] == 1)
            gBattle_BG1_Y = task->data[13] - task->data[5];
        else
            gBattle_BG2_Y = task->data[13] - task->data[5];

        if (task->data[5] > 63)
        {
            task->data[5] = 120 - task->data[14];
            if (task->data[11] == 1)
                gBattle_BG1_Y = task->data[13] - task->data[5];
            else
                gBattle_BG2_Y = task->data[13] - task->data[5];

            gSprites[task->data[10]].x2 = DISPLAY_WIDTH + 32 - gSprites[task->data[10]].x;
            task->data[0]++;
        }
        break;
    case 3:
        gScanlineEffect.state = 3;
        task->data[0]++;
        break;
    case 4:
        DestroyAnimVisualTask(taskId);
        gSprites[task->data[10]].invisible = TRUE;
        break;
    }
}

static void AnimTask_DigEndBounceMovementSetInvisible_battle_anim_ground(u8 taskId)
{
    u8 spriteId = GetAnimBattlerSpriteId(ANIM_ATTACKER);
    gSprites[spriteId].invisible = TRUE;
    gSprites[spriteId].x2 = 0;
    gSprites[spriteId].y2 = 0;

    if (GetBattlerSpriteBGPriorityRank(gBattleAnimAttacker) == 1)
        gBattle_BG1_Y = 0;
    else
        gBattle_BG2_Y = 0;

    DestroyAnimVisualTask(taskId);
}

void AnimTask_DigUpMovement(u8 taskId)
{
    struct Task *task = &gTasks[taskId];

    if (gBattleAnimArgs[0] == FALSE)
        task->func = AnimTask_DigSetVisibleUnderground_battle_anim_ground;
    else
        task->func = AnimTask_DigRiseUpFromHole_battle_anim_ground;

    task->func(taskId);
}

static void AnimTask_DigSetVisibleUnderground_battle_anim_ground(u8 taskId)
{
    struct Task *task = &gTasks[taskId];

    switch (task->data[0])
    {
    case 0:
        task->data[10] = GetAnimBattlerSpriteId(ANIM_ATTACKER);
        gSprites[task->data[10]].invisible = FALSE;
        gSprites[task->data[10]].x2 = 0;
        gSprites[task->data[10]].y2 = DISPLAY_HEIGHT - gSprites[task->data[10]].y;
        task->data[0]++;
        break;
    case 1:
        DestroyAnimVisualTask(taskId);
    }
}

static void AnimTask_DigRiseUpFromHole_battle_anim_ground(u8 taskId)
{
    u8 var0;
    struct Task *task = &gTasks[taskId];

    switch (task->data[0])
    {
    case 0:
        task->data[10] = GetAnimBattlerSpriteId(ANIM_ATTACKER);
        task->data[11] = GetBattlerSpriteBGPriorityRank(gBattleAnimAttacker);
        if (task->data[11] == 1)
            task->data[12] = gBattle_BG1_X;
        else
            task->data[12] = gBattle_BG2_X;

        var0 =  GetBattlerYCoordWithElevation(gBattleAnimAttacker);
        task->data[14] = var0 - 32;
        task->data[15] = var0 + 32;
        task->data[0]++;
        break;
    case 1:
        SetDigScanlineEffect_battle_anim_ground(task->data[11], 0, task->data[15]);
        task->data[0]++;
        break;
    case 2:
        gSprites[task->data[10]].y2 = 96;
        task->data[0]++;
        break;
    case 3:
        gSprites[task->data[10]].y2 -= 8;
        if (gSprites[task->data[10]].y2 == 0)
        {
            gScanlineEffect.state = 3;
            task->data[0]++;
        }
        break;
    case 4:
        DestroyAnimVisualTask(taskId);
        break;
    }
}

static void SetDigScanlineEffect_battle_anim_ground(u8 useBG1, s16 y, s16 endY)
{
    s16 bgX;
    struct ScanlineEffectParams scanlineParams;

    if (useBG1 == 1)
    {
        bgX = gBattle_BG1_X;
        scanlineParams.dmaDest = &REG_BG1HOFS;
    }
    else
    {
        bgX = gBattle_BG2_X;
        scanlineParams.dmaDest = &REG_BG2HOFS;
    }

    if (y < 0)
        y = 0;

    while (y < endY)
    {
        gScanlineEffectRegBuffers[0][y] = bgX;
        gScanlineEffectRegBuffers[1][y] = bgX;
        y++;
    }

    while (y < DISPLAY_HEIGHT)
    {
        gScanlineEffectRegBuffers[0][y] = bgX + DISPLAY_WIDTH;
        gScanlineEffectRegBuffers[1][y] = bgX + DISPLAY_WIDTH;
        y++;
    }

    scanlineParams.dmaControl = SCANLINE_EFFECT_DMACNT_16BIT;
    scanlineParams.initState = 1;
    scanlineParams.unused9 = 0;
    ScanlineEffect_SetParams(scanlineParams);
}

// Moves a particle of dirt in a plume of dirt. Used in Fissure and Dig.
// arg 0: which mon (0 = attacker, 1 = target)
// arg 1: which side of mon (0 = left, 1 = right)
// arg 2: target x offset
// arg 3: target y offset
// arg 4: wave amplitude
// arg 5: duration
void AnimDirtPlumeParticle(struct Sprite *sprite)
{
    s8 battler;
    s16 xOffset;

    if (gBattleAnimArgs[0] == 0)
        battler = gBattleAnimAttacker;
    else
        battler = gBattleAnimTarget;

    xOffset = 24;
    if (gBattleAnimArgs[1] == 1)
    {
        xOffset *= -1;
        gBattleAnimArgs[2] *= -1;
    }

    sprite->x = GetBattlerSpriteCoord(battler, BATTLER_COORD_X_2) + xOffset;
    sprite->y = GetBattlerYCoordWithElevation(battler) + 30;
    sprite->data[0] = gBattleAnimArgs[5];
    sprite->data[2] = sprite->x + gBattleAnimArgs[2];
    sprite->data[4] = sprite->y + gBattleAnimArgs[3];
    sprite->data[5] = gBattleAnimArgs[4];
    InitAnimArcTranslation(sprite);
    sprite->callback = AnimDirtPlumeParticle_Step_battle_anim_ground;
}

static void AnimDirtPlumeParticle_Step_battle_anim_ground(struct Sprite *sprite)
{
    if (TranslateAnimHorizontalArc(sprite))
        DestroyAnimSprite(sprite);
}

// Displays the dirt mound seen in the move Dig for set duration.
// The dirt mound image is too large for a single sprite, so two
// sprites are lined up next to each other.
// arg 0: which mon (0 = attacker, 1 = target)
// arg 1: oam tile num (0 = left half of image, 1 = right half of image)
// arg 2: duration
static void AnimDigDirtMound_battle_anim_ground(struct Sprite *sprite)
{
    s8 battler;

    if (gBattleAnimArgs[0] == 0)
        battler = gBattleAnimAttacker;
    else
        battler = gBattleAnimTarget;

    sprite->x = GetBattlerSpriteCoord(battler, BATTLER_COORD_X) - 16 + (gBattleAnimArgs[1] * 32);
    sprite->y = GetBattlerYCoordWithElevation(battler) + 32;
    sprite->oam.tileNum += gBattleAnimArgs[1] * 8;
    StoreSpriteCallbackInData6(sprite, DestroyAnimSprite);
    sprite->data[0] = gBattleAnimArgs[2];
    sprite->callback = WaitAnimForDuration;
}

#define tState_battle_anim_ground               data[0]
#define tDelay_battle_anim_ground               data[1]
#define tTimer_battle_anim_ground               data[2]
#define tMaxTime_battle_anim_ground             data[3]
#define tbattlerSpriteIds_battle_anim_ground(i) data[9 + (i)]
#define tNumBattlers_battle_anim_ground         data[13] // AnimTask_ShakeBattlers_battle_anim_ground
#define tInitialX_battle_anim_ground            data[13] // AnimTask_ShakeTerrain_battle_anim_ground
#define tHorizOffset_battle_anim_ground         data[14]
#define tInitHorizOffset_battle_anim_ground     data[15]

// Shakes battler(s) or the battle terrain back and forth horizontally. Used by e.g. Earthquake, Eruption
// arg0: What to shake. 0-3 for any specific battler, MAX_BATTLERS_COUNT for all battlers, MAX_BATTLERS_COUNT + 1 for the terrain
// arg1: Shake intensity, used to calculate horizontal pixel offset (if 0, use move power instead)
// arg2: Length of time to shake for
void AnimTask_HorizontalShake(u8 taskId)
{
    u16 i;
    struct Task *task = &gTasks[taskId];

    if (gBattleAnimArgs[1] != 0)
        task->tHorizOffset_battle_anim_ground = task->tInitHorizOffset_battle_anim_ground = gBattleAnimArgs[1] + 3;
    else
        task->tHorizOffset_battle_anim_ground = task->tInitHorizOffset_battle_anim_ground = (gAnimMovePower / 10) + 3;

    task->tMaxTime_battle_anim_ground = gBattleAnimArgs[2];
    switch (gBattleAnimArgs[0])
    {
    case MAX_BATTLERS_COUNT + 1: // Shake terrain
        task->tInitialX_battle_anim_ground = gBattle_BG3_X;
        task->func = AnimTask_ShakeTerrain_battle_anim_ground;
        break;
    case MAX_BATTLERS_COUNT: // Shake all battlers
        task->tNumBattlers_battle_anim_ground = 0;
        for (i = 0; i < MAX_BATTLERS_COUNT; i++)
        {
            if (IsBattlerSpriteVisible(i))
            {
                task->tbattlerSpriteIds_battle_anim_ground(task->tNumBattlers_battle_anim_ground) = gBattlerSpriteIds[i];
                task->tNumBattlers_battle_anim_ground++;
            }
        }
        task->func = AnimTask_ShakeBattlers_battle_anim_ground;
        break;
    default: // Shake specific battler
        task->tbattlerSpriteIds_battle_anim_ground(0) = GetAnimBattlerSpriteId(gBattleAnimArgs[0]);
        if (task->tbattlerSpriteIds_battle_anim_ground(0) == SPRITE_NONE)
        {
            DestroyAnimVisualTask(taskId);
        }
        else
        {
            task->tNumBattlers_battle_anim_ground = 1;
            task->func = AnimTask_ShakeBattlers_battle_anim_ground;
        }
        break;
    }
}

static void AnimTask_ShakeTerrain_battle_anim_ground(u8 taskId)
{
    struct Task *task = &gTasks[taskId];

    switch (task->tState_battle_anim_ground)
    {
    case 0:
        if (++task->tDelay_battle_anim_ground > 1)
        {
            task->tDelay_battle_anim_ground = 0;
            if ((task->tTimer_battle_anim_ground & 1) == 0)
                gBattle_BG3_X = task->tInitialX_battle_anim_ground + task->tInitHorizOffset_battle_anim_ground;
            else
                gBattle_BG3_X = task->tInitialX_battle_anim_ground - task->tInitHorizOffset_battle_anim_ground;

            if (++task->tTimer_battle_anim_ground == task->tMaxTime_battle_anim_ground)
            {
                task->tTimer_battle_anim_ground = 0;
                task->tHorizOffset_battle_anim_ground--;
                task->tState_battle_anim_ground++;
            }
        }
        break;
    case 1:
        if (++task->tDelay_battle_anim_ground > 1)
        {
            task->tDelay_battle_anim_ground = 0;
            if ((task->tTimer_battle_anim_ground & 1) == 0)
                gBattle_BG3_X = task->tInitialX_battle_anim_ground + task->tHorizOffset_battle_anim_ground;
            else
                gBattle_BG3_X = task->tInitialX_battle_anim_ground - task->tHorizOffset_battle_anim_ground;

            if (++task->tTimer_battle_anim_ground == 4)
            {
                task->tTimer_battle_anim_ground = 0;
                if (--task->tHorizOffset_battle_anim_ground == 0)
                    task->tState_battle_anim_ground++;
            }
        }
        break;
    case 2:
        gBattle_BG3_X = task->tInitialX_battle_anim_ground;
        DestroyAnimVisualTask(taskId);
        break;
    }
}

static void AnimTask_ShakeBattlers_battle_anim_ground(u8 taskId)
{
    u16 i;
    struct Task *task = &gTasks[taskId];

    switch (task->tState_battle_anim_ground)
    {
    case 0:
        if (++task->tDelay_battle_anim_ground > 1)
        {
            task->tDelay_battle_anim_ground = 0;
            SetBattlersXOffsetForShake_battle_anim_ground(task);
            if (++task->tTimer_battle_anim_ground == task->tMaxTime_battle_anim_ground)
            {
                task->tTimer_battle_anim_ground = 0;
                task->tHorizOffset_battle_anim_ground--;
                task->tState_battle_anim_ground++;
            }
        }
        break;
    case 1:
        if (++task->tDelay_battle_anim_ground > 1)
        {
            task->tDelay_battle_anim_ground = 0;
            SetBattlersXOffsetForShake_battle_anim_ground(task);
            if (++task->tTimer_battle_anim_ground == 4)
            {
                task->tTimer_battle_anim_ground = 0;
                if (--task->tHorizOffset_battle_anim_ground == 0)
                    task->tState_battle_anim_ground++;
            }
        }
        break;
    case 2:
        for (i = 0; i < task->tNumBattlers_battle_anim_ground; i++)
            gSprites[task->tbattlerSpriteIds_battle_anim_ground(i)].x2 = 0;

        DestroyAnimVisualTask(taskId);
        break;
    }
}

static void SetBattlersXOffsetForShake_battle_anim_ground(struct Task *task)
{
    u16 i;
    u16 xOffset;

    if ((task->tTimer_battle_anim_ground & 1) == 0)
        xOffset = (task->tHorizOffset_battle_anim_ground / 2) + (task->tHorizOffset_battle_anim_ground & 1);
    else
        xOffset = -(task->tHorizOffset_battle_anim_ground / 2);

    for (i = 0; i < task->tNumBattlers_battle_anim_ground; i++)
    {
        gSprites[task->tbattlerSpriteIds_battle_anim_ground(i)].x2 = xOffset;
    }
}

#undef tState_battle_anim_ground
#undef tDelay_battle_anim_ground
#undef tTimer_battle_anim_ground
#undef tMaxTime_battle_anim_ground
#undef tbattlerSpriteIds_battle_anim_ground
#undef tNumBattlers_battle_anim_ground
#undef tInitialX_battle_anim_ground
#undef tHorizOffset_battle_anim_ground
#undef tInitHorizOffset_battle_anim_ground

void AnimTask_IsPowerOver99(u8 taskId)
{
    gBattleAnimArgs[ARG_RET_ID] = gAnimMovePower > 99;
    DestroyAnimVisualTask(taskId);
}

void AnimTask_PositionFissureBgOnBattler(u8 taskId)
{
    struct Task *newTask;
    u8 battler = (gBattleAnimArgs[0] & ANIM_TARGET) ? gBattleAnimTarget : gBattleAnimAttacker;

    if (gBattleAnimArgs[0] > ANIM_TARGET)
        battler = BATTLE_PARTNER(battler);

    newTask = &gTasks[CreateTask(WaitForFissureCompletion_battle_anim_ground, gBattleAnimArgs[1])];
    newTask->data[1] = (32 - GetBattlerSpriteCoord(battler, BATTLER_COORD_X_2)) & 0x1FF;
    newTask->data[2] = (64 - GetBattlerSpriteCoord(battler, BATTLER_COORD_Y_PIC_OFFSET)) & 0xFF;
    gBattle_BG3_X = newTask->data[1];
    gBattle_BG3_Y = newTask->data[2];
    newTask->data[3] = gBattleAnimArgs[2];
    DestroyAnimVisualTask(taskId);
}

static void WaitForFissureCompletion_battle_anim_ground(u8 taskId)
{
    struct Task *task = &gTasks[taskId];

    // Holds the BG3 offsets until gBattleAnimArgs[7]
    // is set to a special terminator value.
    if (gBattleAnimArgs[7] == task->data[3])
    {
        gBattle_BG3_X = 0;
        gBattle_BG3_Y = 0;
        DestroyTask(taskId);
    }
    else
    {
        gBattle_BG3_X = task->data[1];
        gBattle_BG3_Y = task->data[2];
    }
}
