const struct SpriteTemplate gSnowFlakesSpriteTemplate =
{
    .tileTag = ANIM_TAG_SNOWFLAKES,
    .paletteTag = ANIM_TAG_SNOWFLAKES,
    .oam = &gOamData_AffineOff_ObjNormal_16x32,
    .anims = sAnims_Snowflakes_battle_anim_ice,
    .images = NULL,
    .affineAnims = gDummySpriteAffineAnimTable,
    .callback = AnimSnowflakes_battle_anim_ice,
};

void AnimTask_CreateSnowflakes(u8 taskId)
{
    u8 x, y;

    if (gTasks[taskId].data[0] == 0)
    {
        gTasks[taskId].data[1] = gBattleAnimArgs[0];
        gTasks[taskId].data[2] = gBattleAnimArgs[1];
        gTasks[taskId].data[3] = gBattleAnimArgs[2];
    }
    gTasks[taskId].data[0]++;
    if (gTasks[taskId].data[0] % gTasks[taskId].data[2] == 1)
    {
        x = Random2() % DISPLAY_WIDTH;
        y = Random2() % (DISPLAY_HEIGHT / 2);
        CreateSprite(&gSnowFlakesSpriteTemplate, x, y, 4);
    }
    if (gTasks[taskId].data[0] == gTasks[taskId].data[3])
        DestroyAnimVisualTask(taskId);
}

static void AnimSnowflakes_battle_anim_ice(struct Sprite *sprite)
{
    sprite->callback = AnimSnowflakes_Step_battle_anim_ice;
}

static void AnimSnowflakes_Step_battle_anim_ice(struct Sprite *sprite)
{
    if (++sprite->data[0] <= 13)
    {
        sprite->x2++;
        sprite->y2 += 2;
        sprite->x2--;
    }
    if (sprite->animEnded)
        DestroySprite(sprite);
}
