#define sActiveSprites_battle_anim_smokescreen data[0]
#define sPersist_battle_anim_smokescreen       data[1]

#define sMainSpriteId_battle_anim_smokescreen data[0]

u8 SmokescreenImpact(s16 x, s16 y, bool8 persist)
{
    u8 mainSpriteId;
    u8 spriteId1, spriteId2, spriteId3, spriteId4;
    struct Sprite *mainSprite;

    if (GetSpriteTileStartByTag(sSmokescreenImpactSpriteSheet_battle_anim_smokescreen.tag) == 0xFFFF)
    {
        LoadCompressedSpriteSheetUsingHeap(&sSmokescreenImpactSpriteSheet_battle_anim_smokescreen);
        LoadCompressedSpritePaletteUsingHeap(&sSmokescreenImpactSpritePalette_battle_anim_smokescreen);
    }

    mainSpriteId = CreateInvisibleSpriteWithCallback(SpriteCB_SmokescreenImpactMain_battle_anim_smokescreen);
    mainSprite = &gSprites[mainSpriteId];
    mainSprite->sPersist_battle_anim_smokescreen = persist;

    // Top left sprite
    spriteId1 = CreateSprite(&sSmokescreenImpactSpriteTemplate_battle_anim_smokescreen, x - 16, y - 16, 2);
    gSprites[spriteId1].sMainSpriteId_battle_anim_smokescreen = mainSpriteId;
    mainSprite->sActiveSprites_battle_anim_smokescreen++;
    AnimateSprite(&gSprites[spriteId1]);

    // Top right sprite
    spriteId2 = CreateSprite(&sSmokescreenImpactSpriteTemplate_battle_anim_smokescreen, x, y - 16, 2);
    gSprites[spriteId2].sMainSpriteId_battle_anim_smokescreen = mainSpriteId;
    mainSprite->sActiveSprites_battle_anim_smokescreen++;
    StartSpriteAnim(&gSprites[spriteId2], 1);
    AnimateSprite(&gSprites[spriteId2]);

    // Bottom left sprite
    spriteId3 = CreateSprite(&sSmokescreenImpactSpriteTemplate_battle_anim_smokescreen, x - 16, y, 2);
    gSprites[spriteId3].sMainSpriteId_battle_anim_smokescreen = mainSpriteId;
    mainSprite->sActiveSprites_battle_anim_smokescreen++;
    StartSpriteAnim(&gSprites[spriteId3], 2);
    AnimateSprite(&gSprites[spriteId3]);

    // Bottom right sprite
    spriteId4 = CreateSprite(&sSmokescreenImpactSpriteTemplate_battle_anim_smokescreen, x, y, 2);
    gSprites[spriteId4].sMainSpriteId_battle_anim_smokescreen = mainSpriteId;
    mainSprite->sActiveSprites_battle_anim_smokescreen++;
    StartSpriteAnim(&gSprites[spriteId4], 3);
    AnimateSprite(&gSprites[spriteId4]);

    return mainSpriteId;
}

static void SpriteCB_SmokescreenImpactMain_battle_anim_smokescreen(struct Sprite *sprite)
{
    if (sprite->sActiveSprites_battle_anim_smokescreen == 0)
    {
        FreeSpriteTilesByTag(sSmokescreenImpactSpriteSheet_battle_anim_smokescreen.tag);
        FreeSpritePaletteByTag(sSmokescreenImpactSpritePalette_battle_anim_smokescreen.tag);
        if (!sprite->sPersist_battle_anim_smokescreen)
            DestroySprite(sprite);
        else
            sprite->callback = SpriteCallbackDummy;
    }
}

static void SpriteCB_SmokescreenImpact_battle_anim_smokescreen(struct Sprite *sprite)
{
    if (sprite->animEnded)
    {
        gSprites[sprite->sMainSpriteId_battle_anim_smokescreen].sActiveSprites_battle_anim_smokescreen--;
        DestroySprite(sprite);
    }
}
