// Safari Zone throw / Wally's throw
void AnimTask_ThrowBall_StandingTrainer(u8 taskId)
{
    s16 x, y;
    enum PokeBall ballId;
    u8 subpriority;
    u8 spriteId;

    if (gBattleTypeFlags & BATTLE_TYPE_WALLY_TUTORIAL)
    {
        x = 32;
        y = 11;
    }
    else
    {
        x = 23;
        y = 5;
    }

    ballId = ItemIdToBallId(gLastUsedItem);
    subpriority = GetBattlerSpriteSubpriority(GetBattlerAtPosition(B_POSITION_OPPONENT_LEFT)) + 1;
    spriteId = CreateSprite(&gBallSpriteTemplates[ballId], x + 32, y | 80, subpriority);
    gSprites[spriteId].sDuration_battle_anim_throw = 34;
    gSprites[spriteId].sTargetX_battle_anim_throw = GetBattlerSpriteCoord(gBattleAnimTarget, BATTLER_COORD_X);
    gSprites[spriteId].sTargetY_battle_anim_throw = GetBattlerSpriteCoord(gBattleAnimTarget, BATTLER_COORD_Y) - 16;
    gSprites[spriteId].callback = SpriteCallbackDummy;
    gSprites[gBattlerSpriteIds[GetBattlerAtPosition(B_POSITION_PLAYER_LEFT)]].callback = SpriteCB_TrainerThrowObject;
    gTasks[taskId].tSpriteId_battle_anim_throw = spriteId;
    gTasks[taskId].func = AnimTask_ThrowBall_StandingTrainer_Step_battle_anim_throw;
}

static void AnimTask_ThrowBall_StandingTrainer_Step_battle_anim_throw(u8 taskId)
{
    if (gSprites[gBattlerSpriteIds[GetBattlerAtPosition(B_POSITION_PLAYER_LEFT)]].animCmdIndex == 1)
    {
        PlaySE12WithPanning(SE_BALL_THROW, 0);
        gSprites[gTasks[taskId].tSpriteId_battle_anim_throw].callback = SpriteCB_Ball_Throw_battle_anim_throw;
        CreateTask(Task_PlayerThrow_Wait_battle_anim_throw, 10);
        gTasks[taskId].func = AnimTask_ThrowBall_Step_battle_anim_throw;
    }
}

