static void SpriteCB_Ball_Arc_battle_anim_throw(struct Sprite *sprite)
{
    u32 i;

    if (TranslateAnimHorizontalArc(sprite))
    {
        if (gBattleSpritesDataPtr->animationData->ballThrowCaseId == BALL_TRAINER_BLOCK)
        {
            sprite->callback = SpriteCB_Ball_Block_battle_anim_throw;
        }
        else
        {
            StartSpriteAnim(sprite, 1);
            sprite->x += sprite->x2;
            sprite->y += sprite->y2;
            sprite->x2 = 0;
            sprite->y2 = 0;

            for (i = 0; i < 8; i++)
                sprite->data[i] = 0;

            sprite->sTimer_battle_anim_throw = 0;
            sprite->callback = SpriteCB_Ball_MonShrink_battle_anim_throw;

            enum PokeBall ballId = ItemIdToBallId(gLastUsedItem);
            AnimateBallOpenParticles(sprite->x, sprite->y - 5, 1, 28, ballId);
            LaunchBallFadeMonTask(FALSE, gBattleAnimTarget, 14, ballId);
        }
    }
}

static void SpriteCB_Ball_MonShrink_battle_anim_throw(struct Sprite *sprite)
{
    if (++sprite->sTimer_battle_anim_throw == 10)
    {
        sprite->sTaskId_battle_anim_throw = CreateTask(TaskDummy, 50);
        sprite->callback = SpriteCB_Ball_MonShrink_Step_battle_anim_throw;
        gSprites[gBattlerSpriteIds[gBattleAnimTarget]].data[1] = 0;
    }
}

#undef sTimer_battle_anim_throw
#undef sTaskId_battle_anim_throw

#define tState_battle_anim_throw  data[0]
#define sTimer_battle_anim_throw  data[1]
#define sTaskId_battle_anim_throw data[5]

static void SpriteCB_Ball_MonShrink_Step_battle_anim_throw(struct Sprite *sprite)
{
    u8 spriteId;
    u8 taskId;

    spriteId = gBattlerSpriteIds[gBattleAnimTarget];
    taskId = sprite->sTaskId_battle_anim_throw;

    if (++gTasks[taskId].sTimer_battle_anim_throw == 11)
        PlaySE(SE_BALL_TRADE);

    switch (gTasks[taskId].tState_battle_anim_throw)
    {
    case MON_SHRINK_battle_anim_throw:
        PrepareBattlerSpriteForRotScale(spriteId, ST_OAM_OBJ_NORMAL);
        gTasks[taskId].data[10] = 256;
        gMonShrinkDuration = 28;
        gMonShrinkDistance = (gSprites[spriteId].y + gSprites[spriteId].y2) - (sprite->y + sprite->y2);
        gMonShrinkDelta = (u32)(gMonShrinkDistance * 256) / gMonShrinkDuration;
        gTasks[taskId].data[2] = gMonShrinkDelta;
        gTasks[taskId].tState_battle_anim_throw++; // MON_SHRINK_STEP_battle_anim_throw
        break;
    case MON_SHRINK_STEP_battle_anim_throw:
        gTasks[taskId].data[10] += 32;
        SetSpriteRotScale(spriteId, gTasks[taskId].data[10], gTasks[taskId].data[10], 0);
        gTasks[taskId].data[3] += gTasks[taskId].data[2];
        gSprites[spriteId].y2 = -gTasks[taskId].data[3] >> 8;
        if (gTasks[taskId].data[10] >= 1152)
            gTasks[taskId].tState_battle_anim_throw++; // MON_SHRINK_INVISIBLE_battle_anim_throw
        break;
    case MON_SHRINK_INVISIBLE_battle_anim_throw:
        ResetSpriteRotScale(spriteId);
        gSprites[spriteId].invisible = TRUE;
        gTasks[taskId].tState_battle_anim_throw++; // MON_SHRINK_FREE_battle_anim_throw
        break;
    case MON_SHRINK_FREE_battle_anim_throw:
    default:
        if (gTasks[taskId].data[1] > 10)
        {
            DestroyTask(taskId);
            StartSpriteAnim(sprite, 2);
            sprite->data[5] = 0;
            sprite->callback = SpriteCB_Ball_Bounce_battle_anim_throw;
        }
        break;
    }
}

#undef sTimer_battle_anim_throw
#undef tState_battle_anim_throw
#undef sTaskId_battle_anim_throw

#define sState_battle_anim_throw     data[3]
#define sAmplitude_battle_anim_throw data[4]
#define sPhase_battle_anim_throw     data[5]

static void SpriteCB_Ball_Bounce_battle_anim_throw(struct Sprite *sprite)
{
    if (sprite->animEnded)
    {
        sprite->sState_battle_anim_throw = 0;
        sprite->sAmplitude_battle_anim_throw = 40;
        sprite->sPhase_battle_anim_throw = 0;
        sprite->y += Cos(0, 40);
        sprite->y2 = -Cos(0, sprite->sAmplitude_battle_anim_throw);
        if (IsCriticalCapture())
            sprite->callback = CB_CriticalCaptureThrownBallMovement_battle_anim_throw;
        else
            sprite->callback = SpriteCB_Ball_Bounce_Step_battle_anim_throw;
    }
}

#undef sState_battle_anim_throw
#undef sAmplitude_battle_anim_throw
#undef sPhase_battle_anim_throw

#define DIRECTION_battle_anim_throw(state)   (state & 0xFF)
#define PHASE_DELTA_battle_anim_throw(state) (state >> 8)
#define BOUNCES_battle_anim_throw(state)     (state >> 8)
#define FALL_battle_anim_throw(state)        (state &= -0x100)
#define RISE_FASTER_battle_anim_throw(state) (state += 257)

#define BALL_FALLING_battle_anim_throw 0
#define BALL_RISING_battle_anim_throw  1

#define sState_battle_anim_throw     data[3]
#define sAmplitude_battle_anim_throw data[4]
#define sPhase_battle_anim_throw     data[5]
#define sTimer_battle_anim_throw     data[5] // re-use

// Animates the Poké Ball dropping to ground and bouncing.
static void SpriteCB_Ball_Bounce_Step_battle_anim_throw(struct Sprite *sprite)
{
    bool8 lastBounce;
    s16 bounceCount;

    lastBounce = FALSE;

    switch (DIRECTION_battle_anim_throw(sprite->sState_battle_anim_throw))
    {
    case BALL_FALLING_battle_anim_throw:
        sprite->y2 = -Cos(sprite->sPhase_battle_anim_throw, sprite->sAmplitude_battle_anim_throw);
        sprite->sPhase_battle_anim_throw += PHASE_DELTA_battle_anim_throw(sprite->sState_battle_anim_throw) + 4;
        // Once the ball touches the ground
        if (sprite->sPhase_battle_anim_throw >= 64)
        {
            sprite->sAmplitude_battle_anim_throw -= 10;
            RISE_FASTER_battle_anim_throw(sprite->sState_battle_anim_throw);

            bounceCount = BOUNCES_battle_anim_throw(sprite->sState_battle_anim_throw);
            if (bounceCount == 4)
                lastBounce = TRUE;

            switch (bounceCount)
            {
            case 1:
                PlaySE(SE_BALL_BOUNCE_1);
                break;
            case 2:
                PlaySE(SE_BALL_BOUNCE_2);
                break;
            case 3:
                PlaySE(SE_BALL_BOUNCE_3);
                break;
            default:
                PlaySE(SE_BALL_BOUNCE_4);
                break;
            }
        }
        break;
    case BALL_RISING_battle_anim_throw:
        sprite->y2 = -Cos(sprite->sPhase_battle_anim_throw, sprite->sAmplitude_battle_anim_throw);
        sprite->sPhase_battle_anim_throw -= PHASE_DELTA_battle_anim_throw(sprite->sState_battle_anim_throw) + 4;
        // Once ball reaches max height
        if (sprite->sPhase_battle_anim_throw <= 0)
        {
            // Set to BALL_FALLING_battle_anim_throw
            sprite->sPhase_battle_anim_throw = 0;
            FALL_battle_anim_throw(sprite->sState_battle_anim_throw);
        }
        break;
    }

    if (lastBounce)
    {
        sprite->sState_battle_anim_throw = 0;
        sprite->y += Cos(64, 40);
        sprite->y2 = 0;
        if (gBattleSpritesDataPtr->animationData->ballThrowCaseId == BALL_NO_SHAKES)
        {
            sprite->sTimer_battle_anim_throw = 0;
            sprite->callback = SpriteCB_Ball_Release_battle_anim_throw;
        }
        else
        {
            sprite->callback = SpriteCB_Ball_Wobble_battle_anim_throw;
            sprite->data[4] = 1;
            sprite->data[5] = 0;
        }
    }
}

#undef sState_battle_anim_throw
#undef sAmplitude_battle_anim_throw
#undef sPhase_battle_anim_throw
#undef sTimer_battle_anim_throw

#undef DIRECTION_battle_anim_throw
#undef PHASE_DELTA_battle_anim_throw
#undef BOUNCES_battle_anim_throw
#undef FALL_battle_anim_throw
#undef RISE_FASTER_battle_anim_throw

#define sTimer_battle_anim_throw data[3]
#define sState_battle_anim_throw data[3] // re-use

static void SpriteCB_Ball_Wobble_battle_anim_throw(struct Sprite *sprite)
{
    if (++sprite->sTimer_battle_anim_throw == 31)
    {
        sprite->sState_battle_anim_throw = 0;
        sprite->affineAnimPaused = TRUE;
        StartSpriteAffineAnim(sprite, BALL_ROTATE_RIGHT);
        gBattleSpritesDataPtr->animationData->ballSubpx = 0;
        sprite->callback = SpriteCB_Ball_Wobble_Step_battle_anim_throw;
        PlaySE(SE_BALL);
    }
}

#undef sTimer_battle_anim_throw
#undef sState_battle_anim_throw

#define sState_battle_anim_throw     data[3]
#define sDirection_battle_anim_throw data[4]
#define sTimer_battle_anim_throw     data[5]

#define STATE_battle_anim_throw(state)       (state & 0xFF)
#define SHAKES_battle_anim_throw(state)      (state >> 8)
#define SHAKE_INC_battle_anim_throw(state)   (state += 0x100)
#define RESET_STATE_battle_anim_throw(state) (state &= -0x100)

static void SpriteCB_Ball_Wobble_Step_battle_anim_throw(struct Sprite *sprite)
{
    s8 shakes;
    u16 frame;

    switch (STATE_battle_anim_throw(sprite->sState_battle_anim_throw))
    {
    case BALL_ROLL_1_battle_anim_throw:
        // Rolling effect: every frame in the rotation, the sprite shifts 176/256 of a pixel.
        if (gBattleSpritesDataPtr->animationData->ballSubpx > 255)
        {
            sprite->x2 += sprite->sDirection_battle_anim_throw;
            gBattleSpritesDataPtr->animationData->ballSubpx &= 0xFF;
        }
        else
        {
            gBattleSpritesDataPtr->animationData->ballSubpx += 176;
        }

        sprite->sTimer_battle_anim_throw++;
        sprite->affineAnimPaused = FALSE;
        frame = sprite->sTimer_battle_anim_throw + 7;
        if (frame > 14)
        {
            gBattleSpritesDataPtr->animationData->ballSubpx = 0;
            sprite->sState_battle_anim_throw++; // BALL_PIVOT_1_battle_anim_throw
            sprite->sTimer_battle_anim_throw = 0;
        }
        break;
    case BALL_PIVOT_1_battle_anim_throw:
        if (++sprite->sTimer_battle_anim_throw == 1)
        {
            sprite->sTimer_battle_anim_throw = 0;
            sprite->sDirection_battle_anim_throw = -sprite->sDirection_battle_anim_throw;
            sprite->sState_battle_anim_throw++; // BALL_ROLL_2_battle_anim_throw
            sprite->affineAnimPaused = FALSE;
            if (sprite->sDirection_battle_anim_throw < 0)
                ChangeSpriteAffineAnim(sprite, BALL_ROTATE_LEFT);
            else
                ChangeSpriteAffineAnim(sprite, BALL_ROTATE_RIGHT);
        }
        else
        {
            sprite->affineAnimPaused = TRUE;
        }
        break;
    case BALL_ROLL_2_battle_anim_throw:
        if (gBattleSpritesDataPtr->animationData->ballSubpx > 255)
        {
            sprite->x2 += sprite->sDirection_battle_anim_throw;
            gBattleSpritesDataPtr->animationData->ballSubpx &= 0xFF;
        }
        else
        {
            gBattleSpritesDataPtr->animationData->ballSubpx += 176;
        }

        sprite->sTimer_battle_anim_throw++;
        sprite->affineAnimPaused = FALSE;
        frame = sprite->sTimer_battle_anim_throw + 12;
        if (frame > 24)
        {
            gBattleSpritesDataPtr->animationData->ballSubpx = 0;
            sprite->sState_battle_anim_throw++; // BALL_PIVOT_2_battle_anim_throw
            sprite->sTimer_battle_anim_throw = 0;
        }
        break;
    case BALL_PIVOT_2_battle_anim_throw:
        if (sprite->sTimer_battle_anim_throw++ < 0)
        {
            sprite->affineAnimPaused = TRUE;
            break;
        }

        sprite->sTimer_battle_anim_throw = 0;
        sprite->sDirection_battle_anim_throw = -sprite->sDirection_battle_anim_throw;
        sprite->sState_battle_anim_throw++; // BALL_ROLL_3_battle_anim_throw
        sprite->affineAnimPaused = FALSE;
        if (sprite->sDirection_battle_anim_throw < 0)
            ChangeSpriteAffineAnim(sprite, BALL_ROTATE_LEFT);
        else
            ChangeSpriteAffineAnim(sprite, BALL_ROTATE_RIGHT);
        // fall through
    case BALL_ROLL_3_battle_anim_throw:
        if (gBattleSpritesDataPtr->animationData->ballSubpx > 0xFF)
        {
            sprite->x2 += sprite->sDirection_battle_anim_throw;
            gBattleSpritesDataPtr->animationData->ballSubpx &= 0xFF;
        }
        else
        {
            gBattleSpritesDataPtr->animationData->ballSubpx += 176;
        }

        sprite->sTimer_battle_anim_throw++;
        sprite->affineAnimPaused = FALSE;
        frame = sprite->sTimer_battle_anim_throw + 4;
        if (frame > 8)
        {
            gBattleSpritesDataPtr->animationData->ballSubpx = 0;
            sprite->sState_battle_anim_throw++; // BALL_NEXT_MOVE_battle_anim_throw
            sprite->sTimer_battle_anim_throw = 0;
            sprite->sDirection_battle_anim_throw = -sprite->sDirection_battle_anim_throw;
        }
        break;
    case BALL_NEXT_MOVE_battle_anim_throw:
        SHAKE_INC_battle_anim_throw(sprite->sState_battle_anim_throw);
        shakes = SHAKES_battle_anim_throw(sprite->sState_battle_anim_throw);
        if (IsCriticalCapture())
        {
            if (gBattleSpritesDataPtr->animationData->criticalCaptureSuccess)
            {
                sprite->callback = SpriteCB_Ball_Capture_battle_anim_throw;
                sprite->affineAnimPaused = TRUE;
            }
            else
            {
                sprite->affineAnimPaused = TRUE;
                sprite->callback = SpriteCB_Ball_Release_battle_anim_throw;
            }
        }
        else
        {
            if (shakes == gBattleSpritesDataPtr->animationData->ballThrowCaseId)
            {
                sprite->affineAnimPaused = TRUE;
                sprite->callback = SpriteCB_Ball_Release_battle_anim_throw;
            }
            else
            {
                if (gBattleSpritesDataPtr->animationData->ballThrowCaseId == BALL_3_SHAKES_SUCCESS && shakes == 3)
                {
                    sprite->callback = SpriteCB_Ball_Capture_battle_anim_throw;
                    sprite->affineAnimPaused = TRUE;
                }
                else
                {
                    sprite->sState_battle_anim_throw++; // BALL_WAIT_NEXT_SHAKE_battle_anim_throw
                    sprite->affineAnimPaused = TRUE;
                }
            }
        }
        break;
    case BALL_WAIT_NEXT_SHAKE_battle_anim_throw:
    default:
        if (++sprite->sTimer_battle_anim_throw == 31)
        {
            sprite->sTimer_battle_anim_throw = 0;
            RESET_STATE_battle_anim_throw(sprite->sState_battle_anim_throw);
            StartSpriteAffineAnim(sprite, 3);
            if (sprite->sDirection_battle_anim_throw < 0)
                StartSpriteAffineAnim(sprite, BALL_ROTATE_LEFT);
            else
                StartSpriteAffineAnim(sprite, BALL_ROTATE_RIGHT);

            PlaySE(SE_BALL);
        }
        break;
    }
}

#undef STATE_battle_anim_throw
#undef SHAKES_battle_anim_throw
#undef SHAKE_INC_battle_anim_throw
#undef RESET_STATE_battle_anim_throw

#undef sState_battle_anim_throw

#define sTimer_battle_anim_throw data[5]

static void SpriteCB_Ball_Release_battle_anim_throw(struct Sprite *sprite)
{
    if (++sprite->sTimer_battle_anim_throw == 31)
    {
        sprite->data[5] = 0;
        sprite->callback = SpriteCB_Ball_Release_Step_battle_anim_throw;
    }
}
#undef sTimer_battle_anim_throw

#define sState_battle_anim_throw data[0]
#define sTimer_battle_anim_throw data[4]

static void SpriteCB_Ball_Capture_battle_anim_throw(struct Sprite *sprite)
{
    sprite->animPaused = TRUE;
    sprite->callback = SpriteCB_Ball_Capture_Step_battle_anim_throw;
    sprite->data[3] = 0;
    sprite->sTimer_battle_anim_throw = 0;
    sprite->data[5] = 0;
}

// Fade and unfade ball, create star animations, play sound effects
static void SpriteCB_Ball_Capture_Step_battle_anim_throw(struct Sprite *sprite)
{
    u8 *battler = &gBattleAnimTarget;

    sprite->sTimer_battle_anim_throw++;
    if (sprite->sTimer_battle_anim_throw == 40)
    {
        PlaySE(SE_RG_BALL_CLICK);
        BlendPalettes(0x10000 << sprite->oam.paletteNum, 6, RGB_BLACK);
        MakeCaptureStars_battle_anim_throw(sprite);
    }
    else if (sprite->sTimer_battle_anim_throw == 60)
    {
        BeginNormalPaletteFade(0x10000 << sprite->oam.paletteNum, 2, 6, 0, RGB_BLACK);
    }
    else if (sprite->sTimer_battle_anim_throw == 95)
    {
        gDoingBattleAnim = FALSE;
        UpdateOamPriorityInAllHealthboxes(1, FALSE);
        m4aMPlayAllStop();
        PlaySE(MUS_RG_CAUGHT_INTRO);
    }
    else if (sprite->sTimer_battle_anim_throw == 315)
    {
        FreeOamMatrix(gSprites[gBattlerSpriteIds[*battler]].oam.matrixNum);
        DestroySprite(&gSprites[gBattlerSpriteIds[*battler]]);

        sprite->sState_battle_anim_throw = 0;
        sprite->callback = SpriteCB_Ball_FadeOut_battle_anim_throw;
    }
}

#undef sTimer_battle_anim_throw
#undef sState_battle_anim_throw

#define sState_battle_anim_throw data[0]
#define sFrame_battle_anim_throw data[0] // re-use

static void SpriteCB_Ball_FadeOut_battle_anim_throw(struct Sprite *sprite)
{
    u8 paletteIndex;

    switch (sprite->sState_battle_anim_throw)
    {
    case 0:
        sprite->data[1] = 0;
        sprite->data[2] = 0;
        sprite->oam.objMode = ST_OAM_OBJ_BLEND;
        SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_EFFECT_BLEND | BLDCNT_TGT2_ALL);
        SetGpuReg(REG_OFFSET_BLDALPHA, BLDALPHA_BLEND(16, 0));
        paletteIndex = IndexOfSpritePaletteTag(sprite->template->paletteTag);
        BeginNormalPaletteFade(1 << (paletteIndex + 0x10), 0, 0, 16, RGB_WHITE);
        sprite->sState_battle_anim_throw++;
        break;
    case 1:
        if (sprite->data[1]++ > 0)
        {
            sprite->data[1] = 0;
            sprite->data[2]++;
            SetGpuReg(REG_OFFSET_BLDALPHA, BLDALPHA_BLEND(16 - sprite->data[2], sprite->data[2]));
            if (sprite->data[2] == 16)
                sprite->sState_battle_anim_throw++;
        }
        break;
    case 2:
        sprite->invisible = TRUE;
        sprite->sState_battle_anim_throw++;
        break;
    default:
        if (!gPaletteFade.active)
        {
            SetGpuReg(REG_OFFSET_BLDCNT, 0);
            SetGpuReg(REG_OFFSET_BLDALPHA, 0);

            sprite->sFrame_battle_anim_throw = 0;
            sprite->callback = DestroySpriteAfterOneFrame_battle_anim_throw;
        }
        break;
    }
}

#undef sState_battle_anim_throw
#undef sFrame_battle_anim_throw

#define sFrame_battle_anim_throw data[0]

static void DestroySpriteAfterOneFrame_battle_anim_throw(struct Sprite *sprite)
{
    if (sprite->sFrame_battle_anim_throw == 0)
    {
        sprite->sFrame_battle_anim_throw = -1;
    }
    else
    {
        FreeSpriteOamMatrix(sprite);
        DestroySprite(sprite);
    }
}
#undef sFrame_battle_anim_throw

#define sDuration_battle_anim_throw  data[0]
#define sTargetX_battle_anim_throw   data[2]
#define sTargetY_battle_anim_throw   data[4]
#define sAmplitude_battle_anim_throw data[5]

static void MakeCaptureStars_battle_anim_throw(struct Sprite *sprite)
{
    u32 i;
    u8 subpriority;

    if (sprite->subpriority)
    {
        subpriority = sprite->subpriority - 1;
    }
    else
    {
        subpriority = 0;
        sprite->subpriority = 1;
    }

    LoadBallParticleGfx_battle_anim_throw(BALL_MASTER);
    for (i = 0; i < ARRAY_COUNT(sCaptureStars_battle_anim_throw); i++)
    {
        u8 spriteId = CreateSprite(&sBallParticleSpriteTemplates_battle_anim_throw[BALL_MASTER], sprite->x, sprite->y, subpriority);
        if (spriteId != MAX_SPRITES)
        {
            gSprites[spriteId].sDuration_battle_anim_throw = 24;
            gSprites[spriteId].sTargetX_battle_anim_throw = sprite->x + sCaptureStars_battle_anim_throw[i].xOffset;
            gSprites[spriteId].sTargetY_battle_anim_throw = sprite->y + sCaptureStars_battle_anim_throw[i].yOffset;
            gSprites[spriteId].sAmplitude_battle_anim_throw = sCaptureStars_battle_anim_throw[i].amplitude;
            InitAnimArcTranslation(&gSprites[spriteId]);
            gSprites[spriteId].callback = SpriteCB_CaptureStar_Flicker_battle_anim_throw;
            StartSpriteAnim(&gSprites[spriteId], sBallParticleAnimNums_battle_anim_throw[BALL_MASTER]);
        }
    }
}

#undef sDuration_battle_anim_throw
#undef sTargetX_battle_anim_throw
#undef sTargetY_battle_anim_throw
#undef sAmplitude_battle_anim_throw

static void SpriteCB_CaptureStar_Flicker_battle_anim_throw(struct Sprite *sprite)
{
    sprite->invisible = !sprite->invisible;
    if (TranslateAnimHorizontalArc(sprite))
        DestroySprite(sprite);
}

#define sFrame_battle_anim_throw   data[0]
#define sOffsetY_battle_anim_throw data[1]

// Poké Ball didn't catch - starts:
// - Ball particle animations
// - Wild mon fade to normal color
// - Wild mon emerge from Poké Ball
static void SpriteCB_Ball_Release_Step_battle_anim_throw(struct Sprite *sprite)
{
    StartSpriteAnim(sprite, 1);
    StartSpriteAffineAnim(sprite, 0);
    sprite->callback = SpriteCB_Ball_Release_Wait_battle_anim_throw;

    enum PokeBall ballId = ItemIdToBallId(gLastUsedItem);
    AnimateBallOpenParticles(sprite->x, sprite->y - 5, 1, 28, ballId);
    LaunchBallFadeMonTask(TRUE, gBattleAnimTarget, 14, ballId);

    // Animate Pokémon emerging from Poké Ball
    gSprites[gBattlerSpriteIds[gBattleAnimTarget]].invisible = FALSE;
    StartSpriteAffineAnim(&gSprites[gBattlerSpriteIds[gBattleAnimTarget]], BATTLER_AFFINE_EMERGE);
    AnimateSprite(&gSprites[gBattlerSpriteIds[gBattleAnimTarget]]);
    gSprites[gBattlerSpriteIds[gBattleAnimTarget]].sOffsetY_battle_anim_throw = 4096;
}

static void SpriteCB_Ball_Release_Wait_battle_anim_throw(struct Sprite *sprite)
{
    bool8 released = FALSE;

    if (sprite->animEnded)
        sprite->invisible = TRUE;

    if (gSprites[gBattlerSpriteIds[gBattleAnimTarget]].affineAnimEnded)
    {
        StartSpriteAffineAnim(&gSprites[gBattlerSpriteIds[gBattleAnimTarget]], BATTLER_AFFINE_NORMAL);
        released = TRUE;
    }
    else
    {
        gSprites[gBattlerSpriteIds[gBattleAnimTarget]].sOffsetY_battle_anim_throw -= 288;
        gSprites[gBattlerSpriteIds[gBattleAnimTarget]].y2 = gSprites[gBattlerSpriteIds[gBattleAnimTarget]].sOffsetY_battle_anim_throw >> 8;
    }

    if (sprite->animEnded && released)
    {
        gSprites[gBattlerSpriteIds[gBattleAnimTarget]].y2 = 0;
        gSprites[gBattlerSpriteIds[gBattleAnimTarget]].invisible = gBattleSpritesDataPtr->animationData->wildMonInvisible;
        sprite->sFrame_battle_anim_throw = 0;
        sprite->callback = DestroySpriteAfterOneFrame_battle_anim_throw;
        gDoingBattleAnim = 0;
        UpdateOamPriorityInAllHealthboxes(1, FALSE);
    }
}

#undef sFrame_battle_anim_throw
#undef sOffsetY_battle_anim_throw

static void SpriteCB_Ball_Block_battle_anim_throw(struct Sprite *sprite)
{
    s32 i;

    sprite->x += sprite->x2;
    sprite->y += sprite->y2;
    sprite->y2 = 0;
    sprite->x2 = 0;
    for (i = 0; i < 6; i++)
        sprite->data[i] = 0;

    sprite->callback = SpriteCB_Ball_Block_Step_battle_anim_throw;
}

#define sDy_battle_anim_throw    data[0]
#define sDx_battle_anim_throw    data[1]

#define sFrame_battle_anim_throw data[0] // re-use

// Poké Ball moves down off screen after being blocked. The x-speed oscillates.
static void SpriteCB_Ball_Block_Step_battle_anim_throw(struct Sprite *sprite)
{
    s16 dy = sprite->sDy_battle_anim_throw + 0x800;
    s16 dx = sprite->sDx_battle_anim_throw + 0x680;
    sprite->x2 -= dx >> 8;
    sprite->y2 += dy >> 8;
    sprite->sDy_battle_anim_throw = (sprite->sDy_battle_anim_throw + 0x800) & 0xFF;
    sprite->sDx_battle_anim_throw = (sprite->sDx_battle_anim_throw + 0x680) & 0xFF;

    if (sprite->y + sprite->y2 > DISPLAY_HEIGHT
     || sprite->x + sprite->x2 < -8)
    {
        sprite->sFrame_battle_anim_throw = 0;
        sprite->callback = DestroySpriteAfterOneFrame_battle_anim_throw;
        gDoingBattleAnim = 0;
        UpdateOamPriorityInAllHealthboxes(1, FALSE);
    }
}

#undef sDy_battle_anim_throw
#undef sDx_battle_anim_throw

#undef sFrame_battle_anim_throw

static void LoadBallParticleGfx_battle_anim_throw(u8 ballId)
{
    if (GetSpriteTileStartByTag(sBallParticleSpriteSheets_battle_anim_throw[ballId].tag) == 0xFFFF)
    {
        LoadCompressedSpriteSheetUsingHeap(&sBallParticleSpriteSheets_battle_anim_throw[ballId]);
        LoadCompressedSpritePaletteUsingHeap(&sBallParticlePalettes_battle_anim_throw[ballId]);
    }
}

u8 AnimateBallOpenParticles(u8 x, u8 y, u8 priority, u8 subpriority, u8 ballId)
{
    u8 taskId;

    LoadBallParticleGfx_battle_anim_throw(ballId);
    taskId = CreateTask(sBallParticleAnimationFuncs_battle_anim_throw[ballId], 5);
    gTasks[taskId].data[1] = x;
    gTasks[taskId].data[2] = y;
    gTasks[taskId].data[3] = priority;
    gTasks[taskId].data[4] = subpriority;
    gTasks[taskId].data[15] = ballId;
    PlaySE(SE_BALL_OPEN);

    return taskId;
}

static void IncrBallParticleCount_battle_anim_throw(void)
{
    if (gMain.inBattle)
        gBattleSpritesDataPtr->animationData->numBallParticles++;
}

static void PokeBallOpenParticleAnimation_battle_anim_throw(u8 taskId)
{
    u8 spriteId;
    u8 x, y;
    u8 priority, subpriority;
    u8 ballId;
    u8 var0;

    ballId = gTasks[taskId].data[15];
    if (gTasks[taskId].data[0] < 16)
    {
        x = gTasks[taskId].data[1];
        y = gTasks[taskId].data[2];
        priority = gTasks[taskId].data[3];
        subpriority = gTasks[taskId].data[4];

        spriteId = CreateSprite(&sBallParticleSpriteTemplates_battle_anim_throw[ballId], x, y, subpriority);
        if (spriteId != MAX_SPRITES)
        {
            IncrBallParticleCount_battle_anim_throw();
            StartSpriteAnim(&gSprites[spriteId], sBallParticleAnimNums_battle_anim_throw[ballId]);
            gSprites[spriteId].callback = PokeBallOpenParticleAnimation_Step1_battle_anim_throw;
            gSprites[spriteId].oam.priority = priority;

            var0 = (u8)gTasks[taskId].data[0];
            if (var0 >= 8)
                var0 -= 8;

            gSprites[spriteId].data[0] = var0 * 32;
        }

        if (gTasks[taskId].data[0] == 15)
        {
            if (!gMain.inBattle)
                gSprites[spriteId].data[7] = 1;

            DestroyTask(taskId);
            return;
        }
    }

    gTasks[taskId].data[0]++;
}

static void PokeBallOpenParticleAnimation_Step1_battle_anim_throw(struct Sprite *sprite)
{
    if (sprite->data[1] == 0)
        sprite->callback = PokeBallOpenParticleAnimation_Step2_battle_anim_throw;
    else
        sprite->data[1]--;
}

static void PokeBallOpenParticleAnimation_Step2_battle_anim_throw(struct Sprite *sprite)
{
    sprite->x2 = Sin(sprite->data[0], sprite->data[1]);
    sprite->y2 = Cos(sprite->data[0], sprite->data[1]);
    sprite->data[1] += 2;
    if (sprite->data[1] == 50)
        DestroyBallOpenAnimationParticle_battle_anim_throw(sprite);
}

