void TryShinyAnimation(u8 battler, struct Pokemon *mon)
{
    bool8 isShiny;
    u8 taskCirc, taskDgnl;
    struct Pokemon* illusionMon;

    isShiny = GetMonData(mon, MON_DATA_IS_SHINY);
    gBattleSpritesDataPtr->healthBoxesData[battler].triedShinyMonAnim = TRUE;
    illusionMon = GetIllusionMonPtr(battler);
    if (illusionMon != NULL)
        mon = illusionMon;

    if (IsBattlerSpriteVisible(battler) && IsValidForBattle(mon))
    {
        if (isShiny)
        {
            if (GetSpriteTileStartByTag(ANIM_TAG_GOLD_STARS) == 0xFFFF)
            {
                LoadCompressedSpriteSheetUsingHeap(&gBattleAnimPicTable[ANIM_TAG_GOLD_STARS - ANIM_SPRITES_START]);
                LoadCompressedSpritePaletteUsingHeap(&gBattleAnimPaletteTable[ANIM_TAG_GOLD_STARS - ANIM_SPRITES_START]);
            }

            taskCirc = CreateTask(Task_ShinyStars_battle_anim_throw, 10);
            taskDgnl = CreateTask(Task_ShinyStars_battle_anim_throw, 10);
            gTasks[taskCirc].tBattler_battle_anim_throw = battler;
            gTasks[taskDgnl].tBattler_battle_anim_throw = battler;
            gTasks[taskCirc].tStarMove_battle_anim_throw = SHINY_STAR_ENCIRCLE_battle_anim_throw;
            gTasks[taskDgnl].tStarMove_battle_anim_throw = SHINY_STAR_DIAGONAL_battle_anim_throw;
            return;
        }
    }

    gBattleSpritesDataPtr->healthBoxesData[battler].finishedShinyMonAnim = TRUE;
}

static void Task_ShinyStars_battle_anim_throw(u8 taskId)
{
    u8 battler;
    u8 x, y;
    u8 spriteId;
    u16 timer;
    s16 starIdx;
    u8 pan;

    if (gTasks[taskId].tTimer_battle_anim_throw < 60)
    {
        gTasks[taskId].tTimer_battle_anim_throw++;
        return;
    }

    // Wait until the ball particles have despawned
    if (gBattleSpritesDataPtr->animationData->numBallParticles)
        return;

    timer = gTasks[taskId].tStarTimer_battle_anim_throw++;
    if (timer % 4) // Create sprite 1 of every 4 frames
        return;

    battler = gTasks[taskId].tBattler_battle_anim_throw;
    x = GetBattlerSpriteCoord(battler, BATTLER_COORD_X);
    y = GetBattlerSpriteCoord(battler, BATTLER_COORD_Y);

    starIdx = gTasks[taskId].tStarIdx_battle_anim_throw;
    if (starIdx == 0) // Big star
    {
        spriteId = CreateSprite(&gWishStarSpriteTemplate, x, y, 5);
    }
    else if (starIdx >= 0 && gTasks[taskId].tStarIdx_battle_anim_throw < 4) // Medium star
    {
        spriteId = CreateSprite(&gMiniTwinklingStarSpriteTemplate, x, y, 5);
        gSprites[spriteId].oam.tileNum += 4;
    }
    else // Small star
    {
        spriteId = CreateSprite(&gMiniTwinklingStarSpriteTemplate, x, y, 5);
        gSprites[spriteId].oam.tileNum += 5;
    }

    if (gTasks[taskId].tStarMove_battle_anim_throw == SHINY_STAR_ENCIRCLE_battle_anim_throw)
    {
        gSprites[spriteId].callback = SpriteCB_ShinyStars_Encircle_battle_anim_throw;
    }
    else
    {
        gSprites[spriteId].callback = SpriteCB_ShinyStars_Diagonal_battle_anim_throw;
        gSprites[spriteId].x2 = -32;
        gSprites[spriteId].y2 = 32;
        gSprites[spriteId].invisible = TRUE;
        if (gTasks[taskId].tStarIdx_battle_anim_throw == 0)
        {
            if (GetBattlerSide(battler) == B_SIDE_PLAYER)
                pan = -64;
            else
                pan = 63;

            PlaySE12WithPanning(SE_SHINY, pan);
        }
    }

    gSprites[spriteId].sTaskId_battle_anim_throw = taskId;
    gTasks[taskId].tStarIdx_battle_anim_throw++;
    if (spriteId != MAX_SPRITES)
        gTasks[taskId].tNumStars_battle_anim_throw++;

    if (gTasks[taskId].tStarIdx_battle_anim_throw == 5)
        gTasks[taskId].func = Task_ShinyStars_Wait_battle_anim_throw;
}

static void Task_ShinyStars_Wait_battle_anim_throw(u8 taskId)
{
    u8 battler;

    if (gTasks[taskId].tNumStars_battle_anim_throw == 0)
    {
        if (gTasks[taskId].tStarMove_battle_anim_throw == SHINY_STAR_DIAGONAL_battle_anim_throw)
        {
            battler = gTasks[taskId].tBattler_battle_anim_throw;
            gBattleSpritesDataPtr->healthBoxesData[battler].finishedShinyMonAnim = TRUE;
        }

        DestroyTask(taskId);
    }
}

static void SpriteCB_ShinyStars_Encircle_battle_anim_throw(struct Sprite *sprite)
{
    sprite->x2 = Sin(sprite->sPhase_battle_anim_throw, 24);
    sprite->y2 = Cos(sprite->sPhase_battle_anim_throw, 24);
    sprite->sPhase_battle_anim_throw += 12;
    if (sprite->sPhase_battle_anim_throw > 255)
    {
        gTasks[sprite->sTaskId_battle_anim_throw].tNumStars_battle_anim_throw--;
        FreeSpriteOamMatrix(sprite);
        DestroySprite(sprite);
    }
}

static void SpriteCB_ShinyStars_Diagonal_battle_anim_throw(struct Sprite *sprite)
{
    // Delayed four frames to de-sync from encircling stars
    if (sprite->sTimer_battle_anim_throw < 4)
    {
        sprite->sTimer_battle_anim_throw++;
    }
    else
    {
        sprite->invisible = FALSE;
        sprite->x2 += 5;
        sprite->y2 -= 5;
        if (sprite->x2 > 32)
        {
            gTasks[sprite->sTaskId_battle_anim_throw].tNumStars_battle_anim_throw--;
            FreeSpriteOamMatrix(sprite);
            DestroySprite(sprite);
        }
    }
}

