void AnimTask_BlendBattleAnimPal(u8 taskId)
{
    u32 selectedPalettes = UnpackSelectedBattlePalettes(gBattleAnimArgs[0]);
    selectedPalettes |= GetBattleMonSpritePalettesMask((gBattleAnimArgs[0] >>  7) & 1,
                                    (gBattleAnimArgs[0] >>  8) & 1,
                                    (gBattleAnimArgs[0] >>  9) & 1,
                                    (gBattleAnimArgs[0] >> 10) & 1);
    StartBlendAnimSpriteColor(taskId, selectedPalettes);
}

void AnimTask_BlendBattleAnimPalExclude(u8 taskId)
{
    u8 battler;
    u32 selectedPalettes;
    u8 animBattlers[2];

    animBattlers[1] = 0xFF;
    selectedPalettes = UnpackSelectedBattlePalettes(F_PAL_BG);
    switch (gBattleAnimArgs[0])
    {
    case 2:
        selectedPalettes = 0;
        // fall through
    case ANIM_ATTACKER:
#ifdef UBFIX
    default:
#endif
        animBattlers[0] = gBattleAnimAttacker;
        break;
    case 3:
        selectedPalettes = 0;
        // fall through
    case ANIM_TARGET:
        animBattlers[0] = gBattleAnimTarget;
        break;
    case 4:
        animBattlers[0] = gBattleAnimAttacker;
        animBattlers[1] = gBattleAnimTarget;
        break;
    case 5:
        animBattlers[0] = 0xFF;
        break;
    case 6:
        selectedPalettes = 0;
        animBattlers[0] = BATTLE_PARTNER(gBattleAnimAttacker);
        break;
    case 7:
        selectedPalettes = 0;
        animBattlers[0] = BATTLE_PARTNER(gBattleAnimTarget);
        break;
    }

    for (battler = 0; battler < MAX_BATTLERS_COUNT; battler++)
    {
        if (battler != animBattlers[0] && battler != animBattlers[1] && IsBattlerSpriteVisible(battler))
            selectedPalettes |= 0x10000 << GetSpritePalIdxByBattler(battler);
    }

    StartBlendAnimSpriteColor(taskId, selectedPalettes);
}

void AnimTask_SetCamouflageBlend(u8 taskId)
{
    u32 selectedPalettes = UnpackSelectedBattlePalettes(gBattleAnimArgs[0]);
    switch (gBattleTerrain)
    {
    case BATTLE_TERRAIN_GRASS:
        gBattleAnimArgs[4] = RGB(12, 24, 2);
        break;
    case BATTLE_TERRAIN_LONG_GRASS:
        gBattleAnimArgs[4] = RGB(0, 15, 2);
        break;
    case BATTLE_TERRAIN_SAND:
        gBattleAnimArgs[4] = RGB(30, 24, 11);
        break;
    case BATTLE_TERRAIN_UNDERWATER:
        gBattleAnimArgs[4] = RGB(0, 0, 18);
        break;
    case BATTLE_TERRAIN_WATER:
        gBattleAnimArgs[4] = RGB(11, 22, 31);
        break;
    case BATTLE_TERRAIN_POND:
        gBattleAnimArgs[4] = RGB(11, 22, 31);
        break;
    case BATTLE_TERRAIN_MOUNTAIN:
        gBattleAnimArgs[4] = RGB(22, 16, 10);
        break;
    case BATTLE_TERRAIN_CAVE:
        gBattleAnimArgs[4] = RGB(14, 9, 3);
        break;
    case BATTLE_TERRAIN_BUILDING:
        gBattleAnimArgs[4] = RGB_WHITE;
        break;
    case BATTLE_TERRAIN_PLAIN:
    default:
        gBattleAnimArgs[4] = RGB_WHITE;
        break;
    }

    StartBlendAnimSpriteColor(taskId, selectedPalettes);
}

void AnimTask_BlendParticle(u8 taskId)
{
    u8 paletteIndex = IndexOfSpritePaletteTag(gBattleAnimArgs[0]);
    u32 selectedPalettes = 1 << (paletteIndex + 16);
    StartBlendAnimSpriteColor(taskId, selectedPalettes);
}

void StartBlendAnimSpriteColor(u8 taskId, u32 selectedPalettes)
{
    gTasks[taskId].data[0] = selectedPalettes;
    gTasks[taskId].data[1] = selectedPalettes >> 16;
    gTasks[taskId].data[2] = gBattleAnimArgs[1];
    gTasks[taskId].data[3] = gBattleAnimArgs[2];
    gTasks[taskId].data[4] = gBattleAnimArgs[3];
    gTasks[taskId].data[5] = gBattleAnimArgs[4];
    gTasks[taskId].data[10] = gBattleAnimArgs[2];
    gTasks[taskId].func = AnimTask_BlendSpriteColor_Step2_battle_anim_utility_funcs;
    gTasks[taskId].func(taskId);
}

static void AnimTask_BlendSpriteColor_Step2_battle_anim_utility_funcs(u8 taskId)
{
    u32 selectedPalettes;
    u16 singlePaletteOffset = 0;

    if (gTasks[taskId].data[9] == gTasks[taskId].data[2])
    {
        gTasks[taskId].data[9] = 0;
        selectedPalettes = gTasks[taskId].data[0] | (gTasks[taskId].data[1] << 16);
        while (selectedPalettes != 0)
        {
            if (selectedPalettes & 1)
                BlendPalette(singlePaletteOffset, 16, gTasks[taskId].data[10], gTasks[taskId].data[5]);
            singlePaletteOffset += 16;
            selectedPalettes >>= 1;
        }

        if (gTasks[taskId].data[10] < gTasks[taskId].data[4])
            gTasks[taskId].data[10]++;
        else if (gTasks[taskId].data[10] > gTasks[taskId].data[4])
            gTasks[taskId].data[10]--;
        else
            DestroyAnimVisualTask(taskId);
    }
    else
    {
        gTasks[taskId].data[9]++;
    }
}

void AnimTask_HardwarePaletteFade(u8 taskId)
{
    BeginHardwarePaletteFade(
        gBattleAnimArgs[0],
        gBattleAnimArgs[1],
        gBattleAnimArgs[2],
        gBattleAnimArgs[3],
        gBattleAnimArgs[4]);

    gTasks[taskId].func = AnimTask_HardwarePaletteFade_Step_battle_anim_utility_funcs;
}

static void AnimTask_HardwarePaletteFade_Step_battle_anim_utility_funcs(u8 taskId)
{
    if (!gPaletteFade.active)
        DestroyAnimVisualTask(taskId);
}

// Used to leave blended traces of a mon, usually to imply speed as in Agility or Aerial Ace
void AnimTask_TraceMonBlended(u8 taskId)
{
    struct Task *task = &gTasks[taskId];

    task->data[0] = gBattleAnimArgs[0];
    task->data[1] = 0;
    task->data[2] = gBattleAnimArgs[1];
    task->data[3] = gBattleAnimArgs[2];
    task->data[4] = gBattleAnimArgs[3];
    task->data[5] = 0;
    task->func = AnimTask_TraceMonBlended_Step_battle_anim_utility_funcs;
}

static void AnimTask_TraceMonBlended_Step_battle_anim_utility_funcs(u8 taskId)
{
    struct Task *task = &gTasks[taskId];

    if (task->data[4])
    {
        if (task->data[1])
        {
            task->data[1]--;
        }
        else
        {
            task->data[6] = CloneBattlerSpriteWithBlend(task->data[0]);
            if (task->data[6] >= 0)
            {
                gSprites[task->data[6]].oam.priority = task->data[0] ? 1 : 2;
                gSprites[task->data[6]].data[0] = task->data[3];
                gSprites[task->data[6]].data[1] = taskId;
                gSprites[task->data[6]].data[2] = 5;
                gSprites[task->data[6]].callback = AnimMonTrace_battle_anim_utility_funcs;
                task->data[5]++;
            }

            task->data[4]--;
            task->data[1] = task->data[2];
        }
    }
    else if (task->data[5] == 0)
    {
        DestroyAnimVisualTask(taskId);
    }
}

static void AnimMonTrace_battle_anim_utility_funcs(struct Sprite *sprite)
{
    if (sprite->data[0])
    {
        sprite->data[0]--;
    }
    else
    {
        gTasks[sprite->data[1]].data[sprite->data[2]]--;
        DestroySpriteWithActiveSheet(sprite);
    }
}

// Only used by Curse for non-Ghost mons
void AnimTask_DrawFallingWhiteLinesOnAttacker(u8 taskId)
{
    u16 species;
    int spriteId, newSpriteId;
    u16 var0;
    u32 bg1Cnt;
    struct BattleAnimBgData animBgData;

    var0 = 0;
    gBattle_WIN0H = 0;
    gBattle_WIN0V = 0;
    SetGpuReg(REG_OFFSET_WININ, WININ_WIN0_BG_ALL | WININ_WIN0_OBJ | WININ_WIN0_CLR
                              | WININ_WIN1_BG_ALL | WININ_WIN1_OBJ | WININ_WIN1_CLR);
    SetGpuReg(REG_OFFSET_WINOUT, WINOUT_WIN01_BG0 | WINOUT_WIN01_BG2 | WINOUT_WIN01_BG3 | WINOUT_WIN01_OBJ | WINOUT_WIN01_CLR
                               | WINOUT_WINOBJ_BG_ALL | WINOUT_WINOBJ_OBJ | WINOUT_WINOBJ_CLR);
    SetGpuRegBits(REG_OFFSET_DISPCNT, DISPCNT_OBJWIN_ON);
    SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_TGT1_BG1 | BLDCNT_TGT2_ALL | BLDCNT_EFFECT_BLEND);
    SetGpuReg(REG_OFFSET_BLDALPHA, BLDALPHA_BLEND(8, 12));
    bg1Cnt = GetGpuReg(REG_OFFSET_BG1CNT);
    ((struct BgCnt *)&bg1Cnt)->priority = 0;
    ((struct BgCnt *)&bg1Cnt)->screenSize = 0;
    SetGpuReg(REG_OFFSET_BG1CNT, bg1Cnt);

    if (!IsContest())
    {
        ((struct BgCnt *)&bg1Cnt)->charBaseBlock = 1;
        SetGpuReg(REG_OFFSET_BG1CNT, bg1Cnt);
    }

    if (IsDoubleBattle() && !IsContest())
    {
        if (GetBattlerPosition(gBattleAnimAttacker) == B_POSITION_OPPONENT_RIGHT
         || GetBattlerPosition(gBattleAnimAttacker) == B_POSITION_PLAYER_LEFT)
        {
            if (IsBattlerSpriteVisible(BATTLE_PARTNER(gBattleAnimAttacker)) == TRUE)
            {
                gSprites[gBattlerSpriteIds[BATTLE_PARTNER(gBattleAnimAttacker)]].oam.priority -= 1;
                ((struct BgCnt *)&bg1Cnt)->priority = 1;
                SetGpuReg(REG_OFFSET_BG1CNT, bg1Cnt);
                var0 = 1;
            }
        }
    }

    if (IsContest())
    {
        species = gContestResources->moveAnim->species;
    }
    else
    {
        if (GetBattlerSide(gBattleAnimAttacker) != B_SIDE_PLAYER)
            species = GetMonData(&gEnemyParty[gBattlerPartyIndexes[gBattleAnimAttacker]], MON_DATA_SPECIES);
        else
            species = GetMonData(&gPlayerParty[gBattlerPartyIndexes[gBattleAnimAttacker]], MON_DATA_SPECIES);
    }

    spriteId = GetAnimBattlerSpriteId(ANIM_ATTACKER);
    newSpriteId = CreateInvisibleSpriteCopy(gBattleAnimAttacker, spriteId, species);
    GetBattleAnimBg1Data(&animBgData);
    AnimLoadCompressedBgTilemapHandleContest(&animBgData, gBattleAnimMaskTilemap_Curse, FALSE);
    AnimLoadCompressedBgGfx(animBgData.bgId, gBattleAnimMaskImage_Curse, animBgData.tilesOffset);
    LoadPalette(sCurseLinesPalette_battle_anim_utility_funcs, BG_PLTT_ID(animBgData.paletteId) + 1, PLTT_SIZEOF(1));

    gBattle_BG1_X = -gSprites[spriteId].x + 32;
    gBattle_BG1_Y = -gSprites[spriteId].y + 32;
    gTasks[taskId].data[0] = newSpriteId;
    gTasks[taskId].data[6] = var0;
    gTasks[taskId].func = AnimTask_DrawFallingWhiteLinesOnAttacker_Step_battle_anim_utility_funcs;
}

static void AnimTask_DrawFallingWhiteLinesOnAttacker_Step_battle_anim_utility_funcs(u8 taskId)
{
    struct BattleAnimBgData animBgData;
    struct Sprite *sprite;
    u32 bg1Cnt;

    gTasks[taskId].data[10] += 4;
    gBattle_BG1_Y -= 4;
    if (gTasks[taskId].data[10] == 64)
    {
        gTasks[taskId].data[10] = 0;
        gBattle_BG1_Y += 64;
        if (++gTasks[taskId].data[11] == 4)
        {
            ResetBattleAnimBg(FALSE);
            gBattle_WIN0H = 0;
            gBattle_WIN0V = 0;
            SetGpuReg(REG_OFFSET_WININ, WININ_WIN0_BG_ALL | WININ_WIN0_OBJ | WININ_WIN0_CLR
                                      | WININ_WIN1_BG_ALL | WININ_WIN1_OBJ | WININ_WIN1_CLR);
            SetGpuReg(REG_OFFSET_WINOUT, WINOUT_WIN01_BG_ALL  | WINOUT_WIN01_OBJ  | WINOUT_WIN01_CLR
                                       | WINOUT_WINOBJ_BG_ALL | WINOUT_WINOBJ_OBJ | WINOUT_WINOBJ_CLR);
            if (!IsContest())
            {
                bg1Cnt = GetGpuReg(REG_OFFSET_BG1CNT);
                ((struct BgCnt *)&bg1Cnt)->charBaseBlock = 0;
                SetGpuReg(REG_OFFSET_BG1CNT, bg1Cnt);
            }

            SetGpuReg(REG_OFFSET_DISPCNT, GetGpuReg(REG_OFFSET_DISPCNT) ^ DISPCNT_OBJWIN_ON);
            SetGpuReg(REG_OFFSET_BLDCNT, 0);
            SetGpuReg(REG_OFFSET_BLDALPHA, 0);
            sprite = &gSprites[GetAnimBattlerSpriteId(0)]; // unused
            sprite = &gSprites[gTasks[taskId].data[0]];
            DestroySprite(sprite);

            GetBattleAnimBg1Data(&animBgData);
            ClearBattleAnimBg(animBgData.bgId);
            if (gTasks[taskId].data[6] == 1)
                gSprites[gBattlerSpriteIds[BATTLE_PARTNER(gBattleAnimAttacker)]].oam.priority++;

            gBattle_BG1_Y = 0;
            DestroyAnimVisualTask(taskId);
        }
    }
}

// Defines for data array in sAnimStatsChangeData_battle_anim_utility_funcs
#define aDecrease_battle_anim_utility_funcs         data[0]
#define aAnimStatId_battle_anim_utility_funcs       data[1]
#define aIsTarget_battle_anim_utility_funcs         data[2]
#define aMultipleBattlers_battle_anim_utility_funcs data[3] // Always false. Changes for multiple battlers are instead run sequentially.
#define aSharply_battle_anim_utility_funcs          data[4]

// Task data defines for InitStatsChangeAnimation
#define tAnimSpriteId1_battle_anim_utility_funcs    data[0]
#define tVelocity_battle_anim_utility_funcs         data[1]
#define tMultipleBattlers_battle_anim_utility_funcs data[2]
#define tAnimSpriteId2_battle_anim_utility_funcs    data[3]
#define tTargetBlend_battle_anim_utility_funcs      data[4]
#define tWaitTime_battle_anim_utility_funcs         data[5]
#define tHidBattler2_battle_anim_utility_funcs      data[6]
#define tBattler2SpriteId_battle_anim_utility_funcs data[7]
#define tWaitTimer_battle_anim_utility_funcs        data[10]
#define tFadeTimer_battle_anim_utility_funcs        data[11]
#define tBlend_battle_anim_utility_funcs            data[12]
#define tState_battle_anim_utility_funcs            data[15]

void InitStatsChangeAnimation(u8 taskId)
{
    u8 i;

    sAnimStatsChangeData_battle_anim_utility_funcs = AllocZeroed(sizeof(struct AnimStatsChangeData));
    for (i = 0; i < ARRAY_COUNT(sAnimStatsChangeData_battle_anim_utility_funcs->data); i++)
        sAnimStatsChangeData_battle_anim_utility_funcs->data[i] = gBattleAnimArgs[i];

    gTasks[taskId].func = StatsChangeAnimation_Step1_battle_anim_utility_funcs;
}

static void StatsChangeAnimation_Step1_battle_anim_utility_funcs(u8 taskId)
{
    if (!sAnimStatsChangeData_battle_anim_utility_funcs->aIsTarget_battle_anim_utility_funcs)
        sAnimStatsChangeData_battle_anim_utility_funcs->battler1 = gBattleAnimAttacker;
    else
        sAnimStatsChangeData_battle_anim_utility_funcs->battler1 = gBattleAnimTarget;

    sAnimStatsChangeData_battle_anim_utility_funcs->battler2 = BATTLE_PARTNER(sAnimStatsChangeData_battle_anim_utility_funcs->battler1);
    if (IsContest() || (sAnimStatsChangeData_battle_anim_utility_funcs->aMultipleBattlers_battle_anim_utility_funcs && !IsBattlerSpriteVisible(sAnimStatsChangeData_battle_anim_utility_funcs->battler2)))
        sAnimStatsChangeData_battle_anim_utility_funcs->aMultipleBattlers_battle_anim_utility_funcs = FALSE;

    gBattle_WIN0H = 0;
    gBattle_WIN0V = 0;
    SetGpuReg(REG_OFFSET_WININ, WININ_WIN0_ALL | WININ_WIN1_ALL);
    SetGpuReg(REG_OFFSET_WINOUT, (WINOUT_WIN01_ALL & ~WINOUT_WIN01_BG1) | WINOUT_WINOBJ_ALL);
    SetGpuRegBits(REG_OFFSET_DISPCNT, DISPCNT_OBJWIN_ON);
    SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_TGT1_BG1 | BLDCNT_TGT2_ALL | BLDCNT_EFFECT_BLEND);
    SetGpuReg(REG_OFFSET_BLDALPHA, BLDALPHA_BLEND(0, 16));
    SetAnimBgAttribute(1, BG_ANIM_PRIORITY, 0);
    SetAnimBgAttribute(1, BG_ANIM_SCREEN_SIZE, 0);
    if (!IsContest())
        SetAnimBgAttribute(1, BG_ANIM_CHAR_BASE_BLOCK, 1);

    if (IsDoubleBattle() && !sAnimStatsChangeData_battle_anim_utility_funcs->aMultipleBattlers_battle_anim_utility_funcs)
    {
        if (GetBattlerPosition(sAnimStatsChangeData_battle_anim_utility_funcs->battler1) == B_POSITION_OPPONENT_RIGHT
         || GetBattlerPosition(sAnimStatsChangeData_battle_anim_utility_funcs->battler1) == B_POSITION_PLAYER_LEFT)
        {
            if (IsBattlerSpriteVisible(sAnimStatsChangeData_battle_anim_utility_funcs->battler2) == TRUE)
            {
                // Push the battler not being animated back so it doesn't receive the animation.
                gSprites[gBattlerSpriteIds[sAnimStatsChangeData_battle_anim_utility_funcs->battler2]].oam.priority--;
                SetAnimBgAttribute(1, BG_ANIM_PRIORITY, 1);
                sAnimStatsChangeData_battle_anim_utility_funcs->hidBattler2 = TRUE;
            }
        }
    }

    if (IsContest())
    {
        sAnimStatsChangeData_battle_anim_utility_funcs->species = gContestResources->moveAnim->species;
    }
    else
    {
        if (GetBattlerSide(sAnimStatsChangeData_battle_anim_utility_funcs->battler1) != B_SIDE_PLAYER)
            sAnimStatsChangeData_battle_anim_utility_funcs->species = GetMonData(&gEnemyParty[gBattlerPartyIndexes[sAnimStatsChangeData_battle_anim_utility_funcs->battler1]], MON_DATA_SPECIES);
        else
            sAnimStatsChangeData_battle_anim_utility_funcs->species = GetMonData(&gPlayerParty[gBattlerPartyIndexes[sAnimStatsChangeData_battle_anim_utility_funcs->battler1]], MON_DATA_SPECIES);
    }

    gTasks[taskId].func = StatsChangeAnimation_Step2_battle_anim_utility_funcs;
}

static void StatsChangeAnimation_Step2_battle_anim_utility_funcs(u8 taskId)
{
    struct BattleAnimBgData animBgData;
    u8 spriteId, spriteId2;
    u8 battlerSpriteId;

    spriteId2 = 0;
    battlerSpriteId = gBattlerSpriteIds[sAnimStatsChangeData_battle_anim_utility_funcs->battler1];
    spriteId = CreateInvisibleSpriteCopy(sAnimStatsChangeData_battle_anim_utility_funcs->battler1, battlerSpriteId, sAnimStatsChangeData_battle_anim_utility_funcs->species);
    if (sAnimStatsChangeData_battle_anim_utility_funcs->aMultipleBattlers_battle_anim_utility_funcs)
    {
        battlerSpriteId = gBattlerSpriteIds[sAnimStatsChangeData_battle_anim_utility_funcs->battler2];
        spriteId2 = CreateInvisibleSpriteCopy(sAnimStatsChangeData_battle_anim_utility_funcs->battler2, battlerSpriteId, sAnimStatsChangeData_battle_anim_utility_funcs->species);
    }

    GetBattleAnimBg1Data(&animBgData);
    if (!sAnimStatsChangeData_battle_anim_utility_funcs->aDecrease_battle_anim_utility_funcs)
        AnimLoadCompressedBgTilemapHandleContest(&animBgData, gStatAnim_Increase_Tilemap, FALSE);
    else
        AnimLoadCompressedBgTilemapHandleContest(&animBgData, gStatAnim_Decrease_Tilemap, FALSE);

    AnimLoadCompressedBgGfx(animBgData.bgId, gStatAnim_Gfx, animBgData.tilesOffset);
    switch (sAnimStatsChangeData_battle_anim_utility_funcs->aAnimStatId_battle_anim_utility_funcs)
    {
    case STAT_ANIM_PAL_ATK:
        LoadCompressedPalette(gStatAnim_Attack_Pal, BG_PLTT_ID(animBgData.paletteId), PLTT_SIZE_4BPP);
        break;
    case STAT_ANIM_PAL_DEF:
        LoadCompressedPalette(gStatAnim_Defense_Pal, BG_PLTT_ID(animBgData.paletteId), PLTT_SIZE_4BPP);
        break;
    case STAT_ANIM_PAL_ACC:
        LoadCompressedPalette(gStatAnim_Accuracy_Pal, BG_PLTT_ID(animBgData.paletteId), PLTT_SIZE_4BPP);
        break;
    case STAT_ANIM_PAL_SPEED:
        LoadCompressedPalette(gStatAnim_Speed_Pal, BG_PLTT_ID(animBgData.paletteId), PLTT_SIZE_4BPP);
        break;
    case STAT_ANIM_PAL_EVASION:
        LoadCompressedPalette(gStatAnim_Evasion_Pal, BG_PLTT_ID(animBgData.paletteId), PLTT_SIZE_4BPP);
        break;
    case STAT_ANIM_PAL_SPATK:
        LoadCompressedPalette(gStatAnim_SpAttack_Pal, BG_PLTT_ID(animBgData.paletteId), PLTT_SIZE_4BPP);
        break;
    case STAT_ANIM_PAL_SPDEF:
        LoadCompressedPalette(gStatAnim_SpDefense_Pal, BG_PLTT_ID(animBgData.paletteId), PLTT_SIZE_4BPP);
        break;
    default:
 // case STAT_ANIM_PAL_MULTIPLE:
        LoadCompressedPalette(gStatAnim_Multiple_Pal, BG_PLTT_ID(animBgData.paletteId), PLTT_SIZE_4BPP);
        break;
    }

    gBattle_BG1_X = 0;
    gBattle_BG1_Y = 0;

    if (sAnimStatsChangeData_battle_anim_utility_funcs->aDecrease_battle_anim_utility_funcs == TRUE)
    {
        gBattle_BG1_X = 64;
        gTasks[taskId].tVelocity_battle_anim_utility_funcs = -3;
    }
    else
    {
        gTasks[taskId].tVelocity_battle_anim_utility_funcs = 3;
    }

    if (!sAnimStatsChangeData_battle_anim_utility_funcs->aSharply_battle_anim_utility_funcs)
    {
        gTasks[taskId].tTargetBlend_battle_anim_utility_funcs = 10;
        gTasks[taskId].tWaitTime_battle_anim_utility_funcs = 20;
    }
    else
    {
        gTasks[taskId].tTargetBlend_battle_anim_utility_funcs = 13;
        gTasks[taskId].tWaitTime_battle_anim_utility_funcs = 30;
    }

    gTasks[taskId].tAnimSpriteId1_battle_anim_utility_funcs = spriteId;
    gTasks[taskId].tMultipleBattlers_battle_anim_utility_funcs = sAnimStatsChangeData_battle_anim_utility_funcs->aMultipleBattlers_battle_anim_utility_funcs;
    gTasks[taskId].tAnimSpriteId2_battle_anim_utility_funcs = spriteId2;
    gTasks[taskId].tHidBattler2_battle_anim_utility_funcs = sAnimStatsChangeData_battle_anim_utility_funcs->hidBattler2;
    gTasks[taskId].tBattler2SpriteId_battle_anim_utility_funcs = gBattlerSpriteIds[sAnimStatsChangeData_battle_anim_utility_funcs->battler2];
    gTasks[taskId].func = StatsChangeAnimation_Step3_battle_anim_utility_funcs;

    if (!sAnimStatsChangeData_battle_anim_utility_funcs->aDecrease_battle_anim_utility_funcs)
        PlaySE12WithPanning(SE_M_STAT_INCREASE, BattleAnimAdjustPanning2(SOUND_PAN_ATTACKER));
    else
        PlaySE12WithPanning(SE_M_STAT_DECREASE, BattleAnimAdjustPanning2(SOUND_PAN_ATTACKER));
}

static void StatsChangeAnimation_Step3_battle_anim_utility_funcs(u8 taskId)
{
    gBattle_BG1_Y += gTasks[taskId].tVelocity_battle_anim_utility_funcs;

    switch (gTasks[taskId].tState_battle_anim_utility_funcs)
    {
    case 0:
        // Fade in
        if (gTasks[taskId].tFadeTimer_battle_anim_utility_funcs++ > 0)
        {
            gTasks[taskId].tFadeTimer_battle_anim_utility_funcs = 0;
            gTasks[taskId].tBlend_battle_anim_utility_funcs++;
            SetGpuReg(REG_OFFSET_BLDALPHA, BLDALPHA_BLEND(gTasks[taskId].tBlend_battle_anim_utility_funcs, 16 - gTasks[taskId].tBlend_battle_anim_utility_funcs));
            if (gTasks[taskId].tBlend_battle_anim_utility_funcs == gTasks[taskId].tTargetBlend_battle_anim_utility_funcs)
                gTasks[taskId].tState_battle_anim_utility_funcs++;
        }
        break;
    case 1:
        // Wait
        if (++gTasks[taskId].tWaitTimer_battle_anim_utility_funcs == gTasks[taskId].tWaitTime_battle_anim_utility_funcs)
            gTasks[taskId].tState_battle_anim_utility_funcs++;
        break;
    case 2:
        // Fade out
        if (gTasks[taskId].tFadeTimer_battle_anim_utility_funcs++ > 0)
        {
            gTasks[taskId].tFadeTimer_battle_anim_utility_funcs = 0;
            gTasks[taskId].tBlend_battle_anim_utility_funcs--;
            SetGpuReg(REG_OFFSET_BLDALPHA, BLDALPHA_BLEND(gTasks[taskId].tBlend_battle_anim_utility_funcs, 16 - gTasks[taskId].tBlend_battle_anim_utility_funcs));
            if (gTasks[taskId].tBlend_battle_anim_utility_funcs == 0)
            {
                ResetBattleAnimBg(FALSE);
                gTasks[taskId].tState_battle_anim_utility_funcs++;
            }
        }
        break;
    case 3:
        // Reset
        gBattle_WIN0H = 0;
        gBattle_WIN0V = 0;
        SetGpuReg(REG_OFFSET_WININ, WININ_WIN0_ALL | WININ_WIN1_ALL);
        SetGpuReg(REG_OFFSET_WINOUT, WINOUT_WIN01_ALL | WINOUT_WINOBJ_ALL);

        if (!IsContest())
            SetAnimBgAttribute(1, BG_ANIM_CHAR_BASE_BLOCK, 0);

        SetGpuReg(REG_OFFSET_DISPCNT, GetGpuReg(REG_OFFSET_DISPCNT) ^ DISPCNT_OBJWIN_ON);
        SetGpuReg(REG_OFFSET_BLDCNT, 0);
        SetGpuReg(REG_OFFSET_BLDALPHA, 0);

        DestroySprite(&gSprites[gTasks[taskId].tAnimSpriteId1_battle_anim_utility_funcs]);
        if (gTasks[taskId].tMultipleBattlers_battle_anim_utility_funcs)
            DestroySprite(&gSprites[gTasks[taskId].tAnimSpriteId2_battle_anim_utility_funcs]);

        // Restore battler 2's priority
        if (gTasks[taskId].tHidBattler2_battle_anim_utility_funcs == TRUE)
            gSprites[gTasks[taskId].tBattler2SpriteId_battle_anim_utility_funcs].oam.priority++;

        FREE_AND_SET_NULL(sAnimStatsChangeData_battle_anim_utility_funcs);
        DestroyAnimVisualTask(taskId);
        break;
    }
}

