static inline bool32 IsAcePokemon_battle_controller_opponent(u32 chosenMonId, u32 pokemonInBattle, u32 battler)
{
    return AI_THINKING_STRUCT->aiFlags[battler] & AI_FLAG_ACE_POKEMON
        && (chosenMonId == CalculateEnemyPartyCountInSide(battler) - 1)
        && CountAIAliveNonEggMonsExcept_battle_controller_opponent(PARTY_SIZE) != pokemonInBattle;
}

static inline bool32 IsDoubleAcePokemon_battle_controller_opponent(u32 chosenMonId, u32 pokemonInBattle, u32 battler)
{
    return AI_THINKING_STRUCT->aiFlags[battler] & AI_FLAG_DOUBLE_ACE_POKEMON
        && (chosenMonId == CalculateEnemyPartyCountInSide(battler) - 1)
        && (chosenMonId == CalculateEnemyPartyCountInSide(battler) - 2)
        && CountAIAliveNonEggMonsExcept_battle_controller_opponent(PARTY_SIZE) != pokemonInBattle
        && CountAIAliveNonEggMonsExcept_battle_controller_opponent(PARTY_SIZE-1) != pokemonInBattle;
}

static void OpponentHandleChoosePokemon_battle_controller_opponent(u32 battler)
{
    s32 chosenMonId;
    s32 pokemonInBattle = 1;

    // Choosing Revival Blessing target
    if ((gBattleResources->bufferA[battler][1] & 0xF) == PARTY_ACTION_CHOOSE_FAINTED_MON)
    {
        chosenMonId = gSelectedMonPartyId = GetFirstFaintedPartyIndex(battler);
    }
    // Switching out
    else if (gBattleStruct->AI_monToSwitchIntoId[battler] == PARTY_SIZE)
    {
        chosenMonId = GetMostSuitableMonToSwitchInto(battler, TRUE);
        if (chosenMonId == PARTY_SIZE)
        {
            s32 battler1, battler2, firstId, lastId;

            if (!IsDoubleBattle())
            {
                battler2 = battler1 = GetBattlerAtPosition(B_POSITION_OPPONENT_LEFT);
            }
            else
            {
                battler1 = GetBattlerAtPosition(B_POSITION_OPPONENT_LEFT);
                battler2 = GetBattlerAtPosition(B_POSITION_OPPONENT_RIGHT);
                pokemonInBattle = 2;
            }

            GetAIPartyIndexes(battler, &firstId, &lastId);
            for (chosenMonId = (lastId-1); chosenMonId >= firstId; chosenMonId--)
            {
                if (!IsValidForBattle(&gEnemyParty[chosenMonId])
                 || chosenMonId == gBattlerPartyIndexes[battler1]
                 || chosenMonId == gBattlerPartyIndexes[battler2])
                    continue;

                if (!IsAcePokemon_battle_controller_opponent(chosenMonId, pokemonInBattle, battler)
                 && !IsDoubleAcePokemon_battle_controller_opponent(chosenMonId, pokemonInBattle, battler))
                    break;
            }
        }
        gBattleStruct->monToSwitchIntoId[battler] = chosenMonId;
    }
    else
    {
        chosenMonId = gBattleStruct->AI_monToSwitchIntoId[battler];
        gBattleStruct->AI_monToSwitchIntoId[battler] = PARTY_SIZE;
        gBattleStruct->monToSwitchIntoId[battler] = chosenMonId;
    }
    #if TESTING
    TestRunner_Battle_CheckSwitch(battler, chosenMonId);
    #endif // TESTING
    BtlController_EmitChosenMonReturnValue(battler, BUFFER_B, chosenMonId, NULL);
    OpponentBufferExecCompleted_battle_controller_opponent(battler);
}

static u8 CountAIAliveNonEggMonsExcept_battle_controller_opponent(u8 slotToIgnore)
{
    u16 i, count;

    for (i = 0, count = 0; i < PARTY_SIZE; i++)
    {
        if (i != slotToIgnore
            && IsValidForBattle(&gEnemyParty[i]))
        {
            count++;
        }
    }

    return count;
}

