static void WallyHandleSuccessBallThrowAnim_battle_controller_wally(u32 battler)
{
    BtlController_HandleSuccessBallThrowAnim(battler, GetBattlerAtPosition(B_POSITION_OPPONENT_LEFT), B_ANIM_BALL_THROW_WITH_TRAINER, FALSE);
}

static void WallyHandleBallThrowAnim_battle_controller_wally(u32 battler)
{
    BtlController_HandleBallThrowAnim(battler, GetBattlerAtPosition(B_POSITION_OPPONENT_LEFT), B_ANIM_BALL_THROW_WITH_TRAINER, FALSE);
}

static void WallyHandleMoveAnimation_battle_controller_wally(u32 battler)
{
    BtlController_HandleMoveAnimation(battler, FALSE);
}

static void WallyHandlePrintString_battle_controller_wally(u32 battler)
{
    BtlController_HandlePrintString(battler, FALSE, FALSE);
}

static void WallyHandlePrintSelectionString_battle_controller_wally(u32 battler)
{
    if (GetBattlerSide(battler) == B_SIDE_PLAYER)
        WallyHandlePrintString_battle_controller_wally(battler);
    else
        WallyBufferExecCompleted_battle_controller_wally(battler);
}

static void HandleChooseActionAfterDma3_battle_controller_wally(u32 battler)
{
    if (!IsDma3ManagerBusyWithBgCopy())
    {
        gBattle_BG0_X = 0;
        gBattle_BG0_Y = DISPLAY_HEIGHT;
        gBattlerControllerFuncs[battler] = WallyHandleActions_battle_controller_wally;
    }
}

static void WallyHandleChooseAction_battle_controller_wally(u32 battler)
{
    s32 i;

    gBattlerControllerFuncs[battler] = HandleChooseActionAfterDma3_battle_controller_wally;
    BattlePutTextOnWindow(gText_BattleMenu, B_WIN_ACTION_MENU);

    for (i = 0; i < 4; i++)
        ActionSelectionDestroyCursorAt(i);

    ActionSelectionCreateCursorAt(gActionSelectionCursor[battler], 0);
    BattleStringExpandPlaceholdersToDisplayedString(gText_WhatWillWallyDo);
    BattlePutTextOnWindow(gDisplayedStringBattle, B_WIN_ACTION_PROMPT);
}

static void WallyHandleChooseMove_battle_controller_wally(u32 battler)
{
    switch (gBattleStruct->wallyMovesState)
    {
    case 0:
        InitMoveSelectionsVarsAndStrings(battler);
        gBattleStruct->wallyMovesState++;
        gBattleStruct->wallyMoveFrames = 80;
        break;
    case 1:
        if (!IsDma3ManagerBusyWithBgCopy())
        {
            gBattle_BG0_X = 0;
            gBattle_BG0_Y = DISPLAY_HEIGHT * 2;
            gBattleStruct->wallyMovesState++;
        }
        break;
    case 2:
        if (--gBattleStruct->wallyMoveFrames == 0)
        {
            PlaySE(SE_SELECT);
            BtlController_EmitTwoReturnValues(battler, BUFFER_B, 10, 0x100);
            WallyBufferExecCompleted_battle_controller_wally(battler);
        }
        break;
    }
}

static void WallyHandleChooseItem_battle_controller_wally(u32 battler)
{
    BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 0x10, RGB_BLACK);
    gBattlerControllerFuncs[battler] = OpenBagAfterPaletteFade_battle_controller_wally;
    gBattlerInMenuId = battler;
}

static void WallyHandleHealthBarUpdate_battle_controller_wally(u32 battler)
{
    BtlController_HandleHealthBarUpdate(battler, TRUE);
}

// For some reason Wally's SE don't take side into account and pan is always the same. Possibly a bug
static void WallyHandlePlaySE_battle_controller_wally(u32 battler)
{
    PlaySE(gBattleResources->bufferA[battler][1] | (gBattleResources->bufferA[battler][2] << 8));
    WallyBufferExecCompleted_battle_controller_wally(battler);
}

// All of the other controllers use CRY_MODE_FAINT.
// Wally's Pokémon during the tutorial is never intended to faint, so that's probably why it's different here.
static void WallyHandleFaintingCry_battle_controller_wally(u32 battler)
{
    u16 species = GetMonData(&gPlayerParty[gBattlerPartyIndexes[battler]], MON_DATA_SPECIES);

    PlayCry_Normal(species, 25);
    WallyBufferExecCompleted_battle_controller_wally(battler);
}

static void WallyHandleIntroTrainerBallThrow_battle_controller_wally(u32 battler)
{
    const u32 *trainerPal = gTrainerBacksprites[TRAINER_BACK_PIC_WALLY].palette.data;
    BtlController_HandleIntroTrainerBallThrow(battler, 0xD6F8, trainerPal, 31, Intro_TryShinyAnimShowHealthbox_battle_controller_wally);
}

static void WallyHandleDrawPartyStatusSummary_battle_controller_wally(u32 battler)
{
    BtlController_HandleDrawPartyStatusSummary(battler, B_SIDE_PLAYER, FALSE);
}

static void WallyHandleBattleAnimation_battle_controller_wally(u32 battler)
{
    BtlController_HandleBattleAnimation(battler, TRUE, FALSE);
}

static void WallyHandleEndLinkBattle_battle_controller_wally(u32 battler)
{
    gBattleOutcome = gBattleResources->bufferA[battler][1];
    FadeOutMapMusic(5);
    BeginFastPaletteFade(3);
    WallyBufferExecCompleted_battle_controller_wally(battler);

    if (!(gBattleTypeFlags & BATTLE_TYPE_IS_MASTER) && gBattleTypeFlags & BATTLE_TYPE_LINK)
        gBattlerControllerFuncs[battler] = SetBattleEndCallbacks;
}
