static const u8 *GetHoldEffectName(u16 holdEffect)
{
    if (holdEffect > ARRAY_COUNT(sHoldEffectNames_battle_debug))
        return sHoldEffectNames_battle_debug[0];
    return sHoldEffectNames_battle_debug[holdEffect];
}
