#define LINE_CORNER_R_battle_dome      (LINE_PAL_battle_dome | 0x23) // Horizontal into a right-side vertical
#define LINE_CORNER_L_battle_dome      (LINE_PAL_battle_dome | 0x25) // Horizontal into a left-side vertical
#define LINE_V_R_battle_dome           (LINE_PAL_battle_dome | 0x27) // Right-side vertical
#define LINE_V_L_battle_dome           (LINE_PAL_battle_dome | 0x29) // Left-side vertical
#define LINE_H_BOTTOM_battle_dome      (LINE_PAL_battle_dome | 0x2B) // Horizontal on the bottom of the tree
#define LINE_H_LOGO1_battle_dome       (LINE_PAL_battle_dome | 0x2C) // Horizontal, logo behind
#define LINE_H_LOGO2_battle_dome       (LINE_PAL_battle_dome | 0x2D) // Horizontal, logo behind
#define LINE_H_LOGO3_battle_dome       (LINE_PAL_battle_dome | 0x2E) // Horizontal, logo behind
