static void SetFacilityTrainerAndMonPtrs_battle_dome(void)
{
    gFacilityTrainerMons = gBattleFrontierMons;
    gFacilityTrainers = gBattleFrontierTrainers;
}

static void ResetSketchedMoves_battle_dome(void)
{
    int i, moveSlot;

    for (i = 0; i < DOME_BATTLE_PARTY_SIZE; i++)
    {
        int playerMonId = gSaveBlock2Ptr->frontier.selectedPartyMons[gSelectedOrderFromParty[i] - 1] - 1;
        int count;

        for (moveSlot = 0; moveSlot < MAX_MON_MOVES; moveSlot++)
        {
            count = 0;
            while (count < MAX_MON_MOVES)
            {
                if (GetMonData(&gSaveBlock1Ptr->playerParty[playerMonId], MON_DATA_MOVE1 + count, NULL) == GetMonData(&gPlayerParty[i], MON_DATA_MOVE1 + moveSlot, NULL))
                    break;
                count++;
            }
            if (count == MAX_MON_MOVES)
                SetMonMoveSlot(&gPlayerParty[i], MOVE_SKETCH, moveSlot);
        }

        gSaveBlock1Ptr->playerParty[playerMonId] = gPlayerParty[i];
    }
}

static void RestoreDomePlayerPartyHeldItems_battle_dome(void)
{
    int i;

    for (i = 0; i < DOME_BATTLE_PARTY_SIZE; i++)
    {
        int playerMonId = gSaveBlock2Ptr->frontier.selectedPartyMons[gSelectedOrderFromParty[i] - 1] - 1;
        u16 item = GetMonData(&gSaveBlock1Ptr->playerParty[playerMonId], MON_DATA_HELD_ITEM, NULL);
        SetMonData(&gPlayerParty[i], MON_DATA_HELD_ITEM, &item);
    }
}

static void ReduceDomePlayerPartyToSelectedMons_battle_dome(void)
{
    ReducePlayerPartyToSelectedMons();
}

static void GetPlayerSeededBeforeOpponent_battle_dome(void)
{
    // A higher tournament ID is a worse seed
    if (TrainerIdToTournamentId_battle_dome(gTrainerBattleOpponent_A) > TrainerIdToTournamentId_battle_dome(TRAINER_PLAYER))
        gSpecialVar_Result = 1;
    else
        gSpecialVar_Result = 2;
}

static void BufferLastDomeWinnerName_battle_dome(void)
{
    int i;

    SetFacilityTrainerAndMonPtrs_battle_dome();
    for (i = 0; i < DOME_TOURNAMENT_TRAINERS_COUNT; i++)
    {
        if (!DOME_TRAINERS_battle_dome[i].isEliminated)
            break;
    }
    CopyDomeTrainerName_battle_dome(gStringVar1, DOME_TRAINERS_battle_dome[i].trainerId);
}

// For showing the previous tourney results before the player has entered a challenge
static void InitRandomTourneyTreeResults_battle_dome(void)
{
    int i, j, k;
    int monLevel;
    int species[FRONTIER_PARTY_SIZE];
    int monTypesBits;
    int trainerId;
    int monId;
    int zero1;
    int zero2;
    u8 lvlMode;
    u16 *statSums;
    int *statValues;
    u8 ivs = 0;

    species[0] = 0;
    species[1] = 0;
    species[2] = 0;
    if ((gSaveBlock2Ptr->frontier.domeLvlMode != -gSaveBlock2Ptr->frontier.domeBattleMode) && gSaveBlock2Ptr->frontier.challengeStatus != CHALLENGE_STATUS_SAVING)
        return;

    statSums = AllocZeroed(sizeof(u16) * DOME_TOURNAMENT_TRAINERS_COUNT);
    statValues = AllocZeroed(sizeof(int) * NUM_STATS);
    lvlMode = gSaveBlock2Ptr->frontier.lvlMode;
    gSaveBlock2Ptr->frontier.lvlMode = FRONTIER_LVL_50;
    zero1 = 0;
    zero2 = 0;

    gSaveBlock2Ptr->frontier.domeLvlMode = zero1 + 1;
    gSaveBlock2Ptr->frontier.domeBattleMode = zero2 + 1;

    for (i = 0; i < DOME_TOURNAMENT_TRAINERS_COUNT; i++)
    {
        do
        {
            if (i < 5)
                trainerId = Random() % 10;
            else if (i < 15)
                trainerId = Random() % 20 + 10;
            else
                trainerId = Random() % 10 + 30;

            for (j = 0; j < i; j++)
            {
                if (DOME_TRAINERS_battle_dome[j].trainerId == trainerId)
                    break;
            }
        } while (j != i);

        DOME_TRAINERS_battle_dome[i].trainerId = trainerId;
        for (j = 0; j < FRONTIER_PARTY_SIZE; j++)
        {
            do
            {
                monId = GetRandomFrontierMonFromSet(trainerId);
                for (k = 0; k < j; k++)
                {
                    // Make sure the mon is valid.
                    int alreadySelectedMonId = DOME_MONS_battle_dome[i][k];
                    if (alreadySelectedMonId == monId
                        || species[0] == gFacilityTrainerMons[monId].species
                        || species[1] == gFacilityTrainerMons[monId].species
                        || gFacilityTrainerMons[alreadySelectedMonId].heldItem == gFacilityTrainerMons[monId].heldItem)
                        break;
                }
            } while (k != j);

            DOME_MONS_battle_dome[i][j] = monId;
            species[j] = gFacilityTrainerMons[monId].species;
        }
        DOME_TRAINERS_battle_dome[i].isEliminated = FALSE;
        DOME_TRAINERS_battle_dome[i].eliminatedAt = 0;
        DOME_TRAINERS_battle_dome[i].forfeited = FALSE;
    }

    monLevel = FRONTIER_MAX_LEVEL_50;
    for (i = 0; i < DOME_TOURNAMENT_TRAINERS_COUNT; i++)
    {
        monTypesBits = 0;
        statSums[i] = 0;
        ivs = GetDomeTrainerMonIvs_battle_dome(DOME_TRAINERS_battle_dome[i].trainerId);
        for (j = 0; j < FRONTIER_PARTY_SIZE; j++)
        {
            CalcDomeMonStats_battle_dome(&gFacilityTrainerMons[DOME_MONS_battle_dome[i][j]],
                             monLevel, ivs, statValues);

            statSums[i] += statValues[STAT_ATK];
            statSums[i] += statValues[STAT_DEF];
            statSums[i] += statValues[STAT_SPATK];
            statSums[i] += statValues[STAT_SPDEF];
            statSums[i] += statValues[STAT_SPEED];
            statSums[i] += statValues[STAT_HP];
            monTypesBits |= 1u << gSpeciesInfo[gFacilityTrainerMons[DOME_MONS_battle_dome[i][j]].species].types[0];
            monTypesBits |= 1u << gSpeciesInfo[gFacilityTrainerMons[DOME_MONS_battle_dome[i][j]].species].types[1];
        }

        // Because GF hates temporary vars, trainerId acts like monTypesCount here.
        for (trainerId = 0, j = 0; j < 32; j++)
        {
            if (monTypesBits & 1)
                trainerId++;
            monTypesBits >>= 1;
        }
        statSums[i] += (trainerId * monLevel) / 20;
    }

    for (i = 0; i < DOME_TOURNAMENT_TRAINERS_COUNT - 1; i++)
    {
        for (j = i + 1; j < DOME_TOURNAMENT_TRAINERS_COUNT; j++)
        {
            if (statSums[i] < statSums[j])
            {
                SwapDomeTrainers_battle_dome(i, j, statSums);
            }
            else if (statSums[i] == statSums[j])
            {
                if (DOME_TRAINERS_battle_dome[i].trainerId > DOME_TRAINERS_battle_dome[j].trainerId)
                    SwapDomeTrainers_battle_dome(i, j, statSums);
            }
        }
    }

    Free(statSums);
    Free(statValues);

    for (i = 0; i < DOME_ROUNDS_COUNT; i++)
        DecideRoundWinners_battle_dome(i);

    gSaveBlock2Ptr->frontier.lvlMode = lvlMode;
}

static int TrainerIdToTournamentId_battle_dome(u16 trainerId)
{
    int i;

    for (i = 0; i < DOME_TOURNAMENT_TRAINERS_COUNT; i++)
    {
        if (DOME_TRAINERS_battle_dome[i].trainerId == trainerId)
            break;
    }

    return i;
}

// The same as the above one, but has global scope.
int TrainerIdToDomeTournamentId(u16 trainerId)
{
    int i;

    for (i = 0; i < DOME_TOURNAMENT_TRAINERS_COUNT; i++)
    {
        if (DOME_TRAINERS_battle_dome[i].trainerId == trainerId)
            break;
    }

    return i;
}

static u8 GetOpposingNPCTournamentIdByRound_battle_dome(u8 tournamentId, u8 round)
{
    u8 tournamentIds[2];
    BufferDomeWinString_battle_dome(sTrainerAndRoundToLastMatchCardNum_battle_dome[sTournamentIdToPairedTrainerIds_battle_dome[tournamentId] / 2][round] - 16, tournamentIds);
    if (tournamentId == tournamentIds[0])
        return tournamentIds[1];
    else
        return tournamentIds[0];
}

// Determines which trainers won in the NPC vs NPC battles
static void DecideRoundWinners_battle_dome(u8 roundId)
{
    int i;
    int moveSlot, monId1, monId2;
    int tournamentId1, tournamentId2;
    int species;
    int points1 = 0, points2 = 0;

    for (i = 0; i < DOME_TOURNAMENT_TRAINERS_COUNT; i++)
    {
        if (DOME_TRAINERS_battle_dome[i].isEliminated || DOME_TRAINERS_battle_dome[i].trainerId == TRAINER_PLAYER)
            continue;

        tournamentId1 = i;
        tournamentId2 = TournamentIdOfOpponent_battle_dome(roundId, DOME_TRAINERS_battle_dome[tournamentId1].trainerId);
        // Frontier Brain always wins, check tournamentId1.
        if (DOME_TRAINERS_battle_dome[tournamentId1].trainerId == TRAINER_FRONTIER_BRAIN && tournamentId2 != 0xFF)
        {
            DOME_TRAINERS_battle_dome[tournamentId2].isEliminated = TRUE;
            DOME_TRAINERS_battle_dome[tournamentId2].eliminatedAt = roundId;
            gSaveBlock2Ptr->frontier.domeWinningMoves[tournamentId2] = GetWinningMove_battle_dome(tournamentId1, tournamentId2, roundId);
        }
        // Frontier Brain always wins, check tournamentId2.
        else if (tournamentId2 != 0xFF && DOME_TRAINERS_battle_dome[tournamentId2].trainerId == TRAINER_FRONTIER_BRAIN && tournamentId1 != 0xFF)
        {
            DOME_TRAINERS_battle_dome[tournamentId1].isEliminated = TRUE;
            DOME_TRAINERS_battle_dome[tournamentId1].eliminatedAt = roundId;
            gSaveBlock2Ptr->frontier.domeWinningMoves[tournamentId1] = GetWinningMove_battle_dome(tournamentId2, tournamentId1, roundId);
        }
        // Decide which one of two trainers wins!
        else if (tournamentId2 != 0xFF)
        {
            // BUG: points1 and points2 are not cleared at the beginning of the loop resulting in not fair results.
            #ifdef BUGFIX
            points1 = 0;
            points2 = 0;
            #endif

            // Calculate points for both trainers.
            for (monId1 = 0; monId1 < FRONTIER_PARTY_SIZE; monId1++)
            {
                for (moveSlot = 0; moveSlot < MAX_MON_MOVES; moveSlot++)
                {
                    for (monId2 = 0; monId2 < FRONTIER_PARTY_SIZE; monId2++)
                    {
                        points1 += GetTypeEffectivenessPoints_battle_dome(gFacilityTrainerMons[DOME_MONS_battle_dome[tournamentId1][monId1]].moves[moveSlot],
                                                gFacilityTrainerMons[DOME_MONS_battle_dome[tournamentId2][monId2]].species, EFFECTIVENESS_MODE_AI_VS_AI_battle_dome);
                    }
                }
                species = gFacilityTrainerMons[DOME_MONS_battle_dome[tournamentId1][monId1]].species;
                points1 += ( gSpeciesInfo[species].baseHP
                           + gSpeciesInfo[species].baseAttack
                           + gSpeciesInfo[species].baseDefense
                           + gSpeciesInfo[species].baseSpeed
                           + gSpeciesInfo[species].baseSpAttack
                           + gSpeciesInfo[species].baseSpDefense) / 10;
            }
            // Random part of the formula.
            points1 += (Random() & 0x1F);
            // Favor trainers with higher id;
            points1 += tournamentId1;

            for (monId1 = 0; monId1 < FRONTIER_PARTY_SIZE; monId1++)
            {
                for (moveSlot = 0; moveSlot < MAX_MON_MOVES; moveSlot++)
                {
                    for (monId2 = 0; monId2 < FRONTIER_PARTY_SIZE; monId2++)
                    {
                        points2 += GetTypeEffectivenessPoints_battle_dome(gFacilityTrainerMons[DOME_MONS_battle_dome[tournamentId2][monId1]].moves[moveSlot],
                                                gFacilityTrainerMons[DOME_MONS_battle_dome[tournamentId1][monId2]].species, EFFECTIVENESS_MODE_AI_VS_AI_battle_dome);
                    }
                }
                species = gFacilityTrainerMons[DOME_MONS_battle_dome[tournamentId2][monId1]].species;
                points2 += ( gSpeciesInfo[species].baseHP
                           + gSpeciesInfo[species].baseAttack
                           + gSpeciesInfo[species].baseDefense
                           + gSpeciesInfo[species].baseSpeed
                           + gSpeciesInfo[species].baseSpAttack
                           + gSpeciesInfo[species].baseSpDefense) / 10;
            }
            // Random part of the formula.
            points2 += (Random() & 0x1F);
            // Favor trainers with higher id;
            points2 += tournamentId2;

            if (points1 > points2)
            {
                DOME_TRAINERS_battle_dome[tournamentId2].isEliminated = TRUE;
                DOME_TRAINERS_battle_dome[tournamentId2].eliminatedAt = roundId;
                gSaveBlock2Ptr->frontier.domeWinningMoves[tournamentId2] = GetWinningMove_battle_dome(tournamentId1, tournamentId2, roundId);
            }
            else if (points1 < points2)
            {
                DOME_TRAINERS_battle_dome[tournamentId1].isEliminated = TRUE;
                DOME_TRAINERS_battle_dome[tournamentId1].eliminatedAt = roundId;
                gSaveBlock2Ptr->frontier.domeWinningMoves[tournamentId1] = GetWinningMove_battle_dome(tournamentId2, tournamentId1, roundId);
            }
            // Points are the same, so we favor the one with the higher id.
            else if (tournamentId1 > tournamentId2)
            {
                DOME_TRAINERS_battle_dome[tournamentId2].isEliminated = TRUE;
                DOME_TRAINERS_battle_dome[tournamentId2].eliminatedAt = roundId;
                gSaveBlock2Ptr->frontier.domeWinningMoves[tournamentId2] = GetWinningMove_battle_dome(tournamentId1, tournamentId2, roundId);
            }
            else
            {
                DOME_TRAINERS_battle_dome[tournamentId1].isEliminated = TRUE;
                DOME_TRAINERS_battle_dome[tournamentId1].eliminatedAt = roundId;
                gSaveBlock2Ptr->frontier.domeWinningMoves[tournamentId1] = GetWinningMove_battle_dome(tournamentId2, tournamentId1, roundId);
            }
        }
    }
}

static void CopyDomeTrainerName_battle_dome(u8 *str, u16 trainerId)
{
    int i = 0;
    SetFacilityPtrsGetLevel();

    if (trainerId == TRAINER_FRONTIER_BRAIN)
    {
        CopyFrontierBrainTrainerName(str);
    }
    else
    {
        if (trainerId == TRAINER_PLAYER)
        {
            for (i = 0; i < PLAYER_NAME_LENGTH; i++)
                str[i] = gSaveBlock2Ptr->playerName[i];
        }
        else if (trainerId < FRONTIER_TRAINERS_COUNT)
        {
            for (i = 0; i < PLAYER_NAME_LENGTH; i++)
                str[i] = gFacilityTrainers[trainerId].trainerName[i];
        }
        str[i] = EOS;
    }
}
