static u8 Select_RunMenuOptionFunc_battle_factory_screen(void)
{
    gFactorySelect_CurrentOptionFunc = sSelect_MenuOptionFuncs[sFactorySelectScreen->menuCursorPos];
    return gFactorySelect_CurrentOptionFunc();
}

static u8 Select_OptionRentDeselect_battle_factory_screen(void)
{
    u8 selectedId = sFactorySelectScreen->mons[sFactorySelectScreen->cursorPos].selectedId;
    u16 monId  = sFactorySelectScreen->mons[sFactorySelectScreen->cursorPos].monId;
    if (selectedId == 0 && !Select_AreSpeciesValid_battle_factory_screen(monId))
    {
        Select_PrintCantSelectSameMon_battle_factory_screen();
        Select_ErasePopupMenu_battle_factory_screen(SELECT_WIN_OPTIONS_battle_factory_screen);
        return SELECT_INVALID_MON_battle_factory_screen;
    }
    else
    {
        CloseMonPic_battle_factory_screen(sFactorySelectScreen->monPics[1], &sFactorySelectScreen->monPicAnimating, FALSE);
        Select_HandleMonSelectionChange_battle_factory_screen();
        Select_PrintSelectMonString_battle_factory_screen();
        Select_ErasePopupMenu_battle_factory_screen(SELECT_WIN_OPTIONS_battle_factory_screen);
        if (sFactorySelectScreen->selectingMonsState > FRONTIER_PARTY_SIZE)
            return SELECT_CONFIRM_MONS_battle_factory_screen;
        else
            return SELECT_CONTINUE_CHOOSING_battle_factory_screen;
    }
}

static u8 Select_DeclineChosenMons_battle_factory_screen(void)
{
    Select_HideChosenMons_battle_factory_screen();
    Select_HandleMonSelectionChange_battle_factory_screen();
    Select_PrintSelectMonString_battle_factory_screen();
    Select_ErasePopupMenu_battle_factory_screen(SELECT_WIN_OPTIONS_battle_factory_screen);
    if (sFactorySelectScreen->selectingMonsState > FRONTIER_PARTY_SIZE)
        return 2;
    else
        return 1;
}

static u8 Select_OptionSummary_battle_factory_screen(void)
{
    return SELECT_SUMMARY_battle_factory_screen;
}

static u8 Select_OptionOthers_battle_factory_screen(void)
{
    CloseMonPic_battle_factory_screen(sFactorySelectScreen->monPics[1], &sFactorySelectScreen->monPicAnimating, FALSE);
    Select_ErasePopupMenu_battle_factory_screen(SELECT_WIN_OPTIONS_battle_factory_screen);
    return SELECT_CONTINUE_CHOOSING_battle_factory_screen;
}

static void Select_PrintMonCategory_battle_factory_screen(void)
{
    u16 species;
    u8 text[30];
    u8 x;
    u8 monId = sFactorySelectScreen->cursorPos;
    if (monId < SELECTABLE_MONS_COUNT_battle_factory_screen)
    {
        PutWindowTilemap(SELECT_WIN_MON_CATEGORY_battle_factory_screen);
        FillWindowPixelBuffer(SELECT_WIN_MON_CATEGORY_battle_factory_screen, PIXEL_FILL(0));
        species = GetMonData(&sFactorySelectScreen->mons[monId].monData, MON_DATA_SPECIES, NULL);
        CopyMonCategoryText(species, text);
        x = GetStringRightAlignXOffset(FONT_NORMAL, text, 118);
        AddTextPrinterParameterized(SELECT_WIN_MON_CATEGORY_battle_factory_screen, FONT_NORMAL, text, x, 1, 0, NULL);
        CopyWindowToVram(SELECT_WIN_MON_CATEGORY_battle_factory_screen, COPYWIN_GFX);
    }
}

static void Select_CreateMonSprite_battle_factory_screen(void)
{
    u8 monId = sFactorySelectScreen->cursorPos;
    struct Pokemon *mon = &sFactorySelectScreen->mons[monId].monData;
    u16 species = GetMonData(mon, MON_DATA_SPECIES, NULL);
    u32 personality = GetMonData(mon, MON_DATA_PERSONALITY, NULL);
    bool8 isShiny = GetMonData(mon, MON_DATA_IS_SHINY, NULL);

    sFactorySelectScreen->monPics[1].monSpriteId = CreateMonPicSprite(species, isShiny, personality, TRUE, 88, 32, 15, TAG_NONE);
    gSprites[sFactorySelectScreen->monPics[1].monSpriteId].centerToCornerVecX = 0;
    gSprites[sFactorySelectScreen->monPics[1].monSpriteId].centerToCornerVecY = 0;

    sFactorySelectScreen->monPicAnimating = FALSE;
}

static void Select_SetMonPicAnimating_battle_factory_screen(bool8 animating)
{
    sFactorySelectScreen->monPicAnimating = animating;
}

static void Select_ReshowMonSprite_battle_factory_screen(void)
{
    struct Pokemon *mon;
    u16 species;
    u32 personality;
    bool8 isShiny;

    sFactorySelectScreen->monPics[1].bgSpriteId = CreateSprite(&sSpriteTemplate_Select_MonPicBgAnim_battle_factory_screen, 120, 64, 1);
    StartSpriteAffineAnim(&gSprites[sFactorySelectScreen->monPics[1].bgSpriteId], 2);

    mon = &sFactorySelectScreen->mons[sFactorySelectScreen->cursorPos].monData;
    species = GetMonData(mon, MON_DATA_SPECIES, NULL);
    personality = GetMonData(mon, MON_DATA_PERSONALITY, NULL);
    isShiny = GetMonData(mon, MON_DATA_IS_SHINY, NULL);

    sFactorySelectScreen->monPics[1].monSpriteId = CreateMonPicSprite(species, isShiny, personality, TRUE, 88, 32, 15, TAG_NONE);
    gSprites[sFactorySelectScreen->monPics[1].monSpriteId].centerToCornerVecX = 0;
    gSprites[sFactorySelectScreen->monPics[1].monSpriteId].centerToCornerVecY = 0;

    gSprites[sFactorySelectScreen->monPics[1].bgSpriteId].invisible = TRUE;
}

static void Select_CreateChosenMonsSprites_battle_factory_screen(void)
{
    u8 i, j;

    for (i = 0; i < FRONTIER_PARTY_SIZE; i++)
    {
        for (j = 0; j < SELECTABLE_MONS_COUNT_battle_factory_screen; j++)
        {
            if (sFactorySelectScreen->mons[j].selectedId == i + 1)
            {
                struct Pokemon *mon = &sFactorySelectScreen->mons[j].monData;
                u16 species = GetMonData(mon, MON_DATA_SPECIES, NULL);
                u32 personality = GetMonData(mon, MON_DATA_PERSONALITY, NULL);
                bool8 isShiny = GetMonData(mon, MON_DATA_IS_SHINY, NULL);

                sFactorySelectScreen->monPics[i].monSpriteId = CreateMonPicSprite(species, isShiny, personality, TRUE, (i * 72) + 16, 32, i + 13, TAG_NONE);
                gSprites[sFactorySelectScreen->monPics[i].monSpriteId].centerToCornerVecX = 0;
                gSprites[sFactorySelectScreen->monPics[i].monSpriteId].centerToCornerVecY = 0;
                break;
            }
        }
    }
    sFactorySelectScreen->monPicAnimating = FALSE;
}

static void SpriteCB_OpenChosenMonPics_battle_factory_screen(struct Sprite *sprite)
{
    u8 taskId;

    // Current sprite is monPics[1]
    if (sprite->affineAnimEnded
        && gSprites[sFactorySelectScreen->monPics[0].bgSpriteId].affineAnimEnded
        && gSprites[sFactorySelectScreen->monPics[2].bgSpriteId].affineAnimEnded)
    {
        sprite->invisible = TRUE;
        gSprites[sFactorySelectScreen->monPics[0].bgSpriteId].invisible = TRUE;
        gSprites[sFactorySelectScreen->monPics[2].bgSpriteId].invisible = TRUE;

        taskId = CreateTask(Select_Task_OpenChosenMonPics_battle_factory_screen, 1);
        gTasks[taskId].func(taskId);

        sprite->callback = SpriteCallbackDummy;
    }
}

static void SpriteCB_CloseChosenMonPics_battle_factory_screen(struct Sprite *sprite)
{
    // Current sprite is monPics[1]
    if (sprite->affineAnimEnded
        && gSprites[sFactorySelectScreen->monPics[0].bgSpriteId].affineAnimEnded
        && gSprites[sFactorySelectScreen->monPics[2].bgSpriteId].affineAnimEnded)
    {
        FreeOamMatrix(sprite->oam.matrixNum);
        FreeOamMatrix(gSprites[sFactorySelectScreen->monPics[0].bgSpriteId].oam.matrixNum);
        FreeOamMatrix(gSprites[sFactorySelectScreen->monPics[2].bgSpriteId].oam.matrixNum);

        sFactorySelectScreen->monPicAnimating = FALSE;

        DestroySprite(&gSprites[sFactorySelectScreen->monPics[0].bgSpriteId]);
        DestroySprite(&gSprites[sFactorySelectScreen->monPics[2].bgSpriteId]);
        DestroySprite(sprite);
    }
}

// Task data for Select_Task_OpenChosenMonPics_battle_factory_screen, Select_Task_CloseChosenMonPics_battle_factory_screen, Task_CloseMonPic_battle_factory_screen, and Task_OpenMonPic_battle_factory_screen
#define tWinLeft_battle_factory_screen      data[3]
#ifndef UBFIX
#define tWinRight_battle_factory_screen     data[24] // UB: Typo? Likely meant data[4], 24 is out of bounds
#else
#define tWinRight_battle_factory_screen     data[4]
#endif
#define tWinTop_battle_factory_screen       data[5]
#define tWinBottom_battle_factory_screen    data[8]
#define tSpriteId_battle_factory_screen     data[6] // TODO: Clarify, what sprite
#define tIsSwapScreen_battle_factory_screen data[7]

static void Select_Task_OpenChosenMonPics_battle_factory_screen(u8 taskId)
{
    struct Task *task = &gTasks[taskId];
    switch (task->tState_battle_factory_screen)
    {
    case 0:
        task->tWinLeft_battle_factory_screen = 16;
        task->tWinRight_battle_factory_screen = DISPLAY_WIDTH - 16;
        task->tWinTop_battle_factory_screen = 64;
        task->tWinBottom_battle_factory_screen = 65;
        SetGpuRegBits(REG_OFFSET_DISPCNT, DISPCNT_WIN0_ON);
        SetGpuReg(REG_OFFSET_WIN0H, WIN_RANGE(task->tWinLeft_battle_factory_screen, task->tWinRight_battle_factory_screen));
        SetGpuReg(REG_OFFSET_WIN0V, WIN_RANGE(task->tWinTop_battle_factory_screen, task->tWinBottom_battle_factory_screen));
        SetGpuReg(REG_OFFSET_WININ, WININ_WIN0_BG_ALL | WININ_WIN0_CLR | WININ_WIN0_OBJ);
        SetGpuReg(REG_OFFSET_WINOUT, WINOUT_WIN01_BG0 | WINOUT_WIN01_BG1 | WINOUT_WIN01_BG2 | WINOUT_WIN01_CLR | WINOUT_WIN01_OBJ);
        break;
    case 1:
        ShowBg(3);
        SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_TGT1_BG3 | BLDCNT_EFFECT_BLEND | BLDCNT_TGT2_BG1 | BLDCNT_TGT2_OBJ);
        SetGpuReg(REG_OFFSET_BLDALPHA, BLDALPHA_BLEND(11, 4));
        break;
    case 2:
        task->tWinTop_battle_factory_screen -= 4;
        task->tWinBottom_battle_factory_screen += 4;
        if (task->tWinTop_battle_factory_screen <= 32 || task->tWinBottom_battle_factory_screen >= 96)
        {
            task->tWinTop_battle_factory_screen = 32;
            task->tWinBottom_battle_factory_screen = 96;
            ClearGpuRegBits(REG_OFFSET_DISPCNT, DISPCNT_WIN0_ON);
        }
        SetGpuReg(REG_OFFSET_WIN0V, WIN_RANGE(task->tWinTop_battle_factory_screen, task->tWinBottom_battle_factory_screen));
        if (task->tWinTop_battle_factory_screen != 32)
            return;
        break;
    default:
        DestroyTask(taskId);
        Select_CreateChosenMonsSprites_battle_factory_screen();
        return;
    }
    task->tState_battle_factory_screen++;
}

static void Select_Task_CloseChosenMonPics_battle_factory_screen(u8 taskId)
{
    struct Task *task = &gTasks[taskId];
    switch (task->tState_battle_factory_screen)
    {
    case 0:
        task->tWinLeft_battle_factory_screen = 16;
        task->tWinRight_battle_factory_screen = DISPLAY_WIDTH - 16;
        task->tWinTop_battle_factory_screen = 32;
        task->tWinBottom_battle_factory_screen = 96;
        SetGpuRegBits(REG_OFFSET_DISPCNT, DISPCNT_WIN0_ON);
        SetGpuReg(REG_OFFSET_WIN0H, WIN_RANGE(task->tWinLeft_battle_factory_screen, task->tWinRight_battle_factory_screen));
        SetGpuReg(REG_OFFSET_WIN0V, WIN_RANGE(task->tWinTop_battle_factory_screen, task->tWinBottom_battle_factory_screen));
        SetGpuReg(REG_OFFSET_WININ, WININ_WIN0_BG_ALL | WININ_WIN0_CLR | WININ_WIN0_OBJ);
        SetGpuReg(REG_OFFSET_WINOUT, WINOUT_WIN01_BG0 | WINOUT_WIN01_BG1 | WINOUT_WIN01_BG2 | WINOUT_WIN01_CLR | WINOUT_WIN01_OBJ);
        task->tState_battle_factory_screen++;
        break;
    case 1:
        task->tWinTop_battle_factory_screen += 4;
        task->tWinBottom_battle_factory_screen -= 4;
        if (task->tWinTop_battle_factory_screen >= 64 || task->tWinBottom_battle_factory_screen <= 65)
        {
            task->tWinTop_battle_factory_screen = 64;
            task->tWinBottom_battle_factory_screen = 65;
        }
        SetGpuReg(REG_OFFSET_WIN0V, WIN_RANGE(task->tWinTop_battle_factory_screen, task->tWinBottom_battle_factory_screen));
        if (task->tWinTop_battle_factory_screen == 64)
            task->tState_battle_factory_screen++;
        break;
    default:
        HideBg(3);
        gSprites[sFactorySelectScreen->monPics[1].bgSpriteId].invisible = FALSE;
        gSprites[sFactorySelectScreen->monPics[1].bgSpriteId].callback = SpriteCB_CloseChosenMonPics_battle_factory_screen;
        gSprites[sFactorySelectScreen->monPics[0].bgSpriteId].invisible = FALSE;
        gSprites[sFactorySelectScreen->monPics[0].bgSpriteId].callback = SpriteCallbackDummy;
        gSprites[sFactorySelectScreen->monPics[2].bgSpriteId].invisible = FALSE;
        gSprites[sFactorySelectScreen->monPics[2].bgSpriteId].callback = SpriteCallbackDummy;
        StartSpriteAffineAnim(&gSprites[sFactorySelectScreen->monPics[1].bgSpriteId], 1);
        StartSpriteAffineAnim(&gSprites[sFactorySelectScreen->monPics[0].bgSpriteId], 1);
        StartSpriteAffineAnim(&gSprites[sFactorySelectScreen->monPics[2].bgSpriteId], 1);
        ClearGpuRegBits(REG_OFFSET_DISPCNT, DISPCNT_WIN0_ON);
        DestroyTask(taskId);
        break;
    }
}

static void Select_ShowChosenMons_battle_factory_screen(void)
{
    sFactorySelectScreen->monPics[1].bgSpriteId = CreateSprite(&sSpriteTemplate_Select_MonPicBgAnim_battle_factory_screen, 120, 64, 1);
    sFactorySelectScreen->monPics[0].bgSpriteId = CreateSprite(&sSpriteTemplate_Select_MonPicBgAnim_battle_factory_screen,  44, 64, 1);
    sFactorySelectScreen->monPics[2].bgSpriteId = CreateSprite(&sSpriteTemplate_Select_MonPicBgAnim_battle_factory_screen, 196, 64, 1);

    gSprites[sFactorySelectScreen->monPics[1].bgSpriteId].callback = SpriteCB_OpenChosenMonPics_battle_factory_screen;
    gSprites[sFactorySelectScreen->monPics[0].bgSpriteId].callback = SpriteCallbackDummy;
    gSprites[sFactorySelectScreen->monPics[2].bgSpriteId].callback = SpriteCallbackDummy;

    sFactorySelectScreen->monPicAnimating = TRUE;
}

static void Select_HideChosenMons_battle_factory_screen(void)
{
    u8 taskId;

    FreeAndDestroyMonPicSprite(sFactorySelectScreen->monPics[0].monSpriteId);
    FreeAndDestroyMonPicSprite(sFactorySelectScreen->monPics[1].monSpriteId);
    FreeAndDestroyMonPicSprite(sFactorySelectScreen->monPics[2].monSpriteId);

    taskId = CreateTask(Select_Task_CloseChosenMonPics_battle_factory_screen, 1);
    gTasks[taskId].func(taskId);

    sFactorySelectScreen->monPicAnimating = TRUE;
}

static void Select_SetWinRegs_battle_factory_screen(s16 mWin0H, s16 nWin0H, s16 mWin0V, s16 nWin0V)
{
    SetGpuRegBits(REG_OFFSET_DISPCNT, DISPCNT_WIN0_ON);
    SetGpuReg(REG_OFFSET_WIN0H, WIN_RANGE(mWin0H, nWin0H));
    SetGpuReg(REG_OFFSET_WIN0V, WIN_RANGE(mWin0V, nWin0V));
    SetGpuReg(REG_OFFSET_WININ, WININ_WIN0_BG_ALL | WININ_WIN0_CLR | WININ_WIN0_OBJ);
    SetGpuReg(REG_OFFSET_WINOUT, WINOUT_WIN01_BG0 | WINOUT_WIN01_BG1 | WINOUT_WIN01_BG2 | WINOUT_WIN01_CLR | WINOUT_WIN01_OBJ);
}

static bool32 Select_AreSpeciesValid_battle_factory_screen(u16 monId)
{
    u8 i, j;
    u32 species = gFacilityTrainerMons[monId].species;
    u8 selectState = sFactorySelectScreen->selectingMonsState;

    for (i = 1; i < selectState; i++)
    {
        for (j = 0; j < SELECTABLE_MONS_COUNT_battle_factory_screen; j++)
        {
            if (sFactorySelectScreen->mons[j].selectedId == i)
            {
                if (gFacilityTrainerMons[sFactorySelectScreen->mons[j].monId].species == species)
                    return FALSE;

                break;
            }
        }
    }
    return TRUE;
}

static void Select_Task_FadeSpeciesName_battle_factory_screen(u8 taskId)
{
    switch (gTasks[taskId].tState_battle_factory_screen)
    {
    case FADESTATE_INIT_battle_factory_screen:
        sFactorySelectScreen->fadeSpeciesNameCoeffDelay = 0;
        sFactorySelectScreen->fadeSpeciesNameCoeff = 0;
        sFactorySelectScreen->fadeSpeciesNameFadeOut = TRUE;
        gTasks[taskId].tState_battle_factory_screen = FADESTATE_RUN_battle_factory_screen;
        break;
    case FADESTATE_RUN_battle_factory_screen:
        if (sFactorySelectScreen->fadeSpeciesNameActive)
        {
            if (sFactorySelectScreen->faceSpeciesNameDelay)
            {
                gTasks[taskId].tState_battle_factory_screen = FADESTATE_DELAY_battle_factory_screen;
            }
            else
            {
                sFactorySelectScreen->fadeSpeciesNameCoeffDelay++;
                if (sFactorySelectScreen->fadeSpeciesNameCoeffDelay > 6)
                {
                    sFactorySelectScreen->fadeSpeciesNameCoeffDelay = 0;
                    if (!sFactorySelectScreen->fadeSpeciesNameFadeOut)
                        sFactorySelectScreen->fadeSpeciesNameCoeff--;
                    else
                        sFactorySelectScreen->fadeSpeciesNameCoeff++;
                }
                BlendPalettes(1 << PALNUM_FADE_TEXT_battle_factory_screen, sFactorySelectScreen->fadeSpeciesNameCoeff, 0);
                if (sFactorySelectScreen->fadeSpeciesNameCoeff > 5)
                {
                    sFactorySelectScreen->fadeSpeciesNameFadeOut = FALSE;
                }
                else if (sFactorySelectScreen->fadeSpeciesNameCoeff == 0)
                {
                    gTasks[taskId].tState_battle_factory_screen = FADESTATE_DELAY_battle_factory_screen;
                    sFactorySelectScreen->fadeSpeciesNameFadeOut = TRUE;
                }
            }
        }
        break;
    case FADESTATE_DELAY_battle_factory_screen:
        if (sFactorySelectScreen->faceSpeciesNameDelay > 14)
        {
            sFactorySelectScreen->faceSpeciesNameDelay = 0;
            gTasks[taskId].tState_battle_factory_screen = FADESTATE_RUN_battle_factory_screen;
        }
        else
        {
            sFactorySelectScreen->faceSpeciesNameDelay++;
        }
        break;
    }
}

