    gTasks[taskId].tFollowUpTaskPtrLo_battle_factory_screen = (u32)(Swap_Task_HandleChooseMons_battle_factory_screen);
    gTasks[taskId].tFollowUpTaskState_battle_factory_screen = STATE_CHOOSE_MONS_HANDLE_INPUT_battle_factory_screen;
