#define DOUBLES_GIMMICK_TRIGGER_POS_X_OPTIMAL_battle_gimmick (30)
#define DOUBLES_GIMMICK_TRIGGER_POS_X_PRIORITY_battle_gimmick (31)
#define DOUBLES_GIMMICK_TRIGGER_POS_X_SLIDE_battle_gimmick (15)
#define DOUBLES_GIMMICK_TRIGGER_POS_Y_DIFF_battle_gimmick (-4)

#define tBattler_battle_gimmick    data[0]
#define tHide_battle_gimmick       data[1]

void ChangeGimmickTriggerSprite(u32 spriteId, u32 animId)
{
    StartSpriteAnim(&gSprites[spriteId], animId);
}

void CreateGimmickTriggerSprite(u32 battler)
{
    const struct GimmickInfo * gimmick = &gGimmicksInfo[gBattleStruct->gimmick.usableGimmick[battler]];

    // Exit if there shouldn't be a sprite produced.
    if (GetBattlerSide(battler) == B_SIDE_OPPONENT
     || gBattleStruct->gimmick.usableGimmick[battler] == GIMMICK_NONE
     || gimmick->triggerSheet == NULL
     || HasTrainerUsedGimmick(battler, gBattleStruct->gimmick.usableGimmick[battler]))
    {
        return;
    }

    LoadSpritePalette(gimmick->triggerPal);
    if (GetSpriteTileStartByTag(TAG_GIMMICK_TRIGGER_TILE) == 0xFFFF)
        LoadSpriteSheet(gimmick->triggerSheet);

    if (gBattleStruct->gimmick.triggerSpriteId == 0xFF)
    {
        if (IsDoubleBattle())
            gBattleStruct->gimmick.triggerSpriteId = CreateSprite(gimmick->triggerTemplate,
                                                                  gSprites[gHealthboxSpriteIds[battler]].x - DOUBLES_GIMMICK_TRIGGER_POS_X_SLIDE_battle_gimmick,
                                                                  gSprites[gHealthboxSpriteIds[battler]].y - DOUBLES_GIMMICK_TRIGGER_POS_Y_DIFF_battle_gimmick, 0);
        else
            gBattleStruct->gimmick.triggerSpriteId = CreateSprite(gimmick->triggerTemplate,
                                                                  gSprites[gHealthboxSpriteIds[battler]].x - SINGLES_GIMMICK_TRIGGER_POS_X_SLIDE_battle_gimmick,
                                                                  gSprites[gHealthboxSpriteIds[battler]].y - SINGLES_GIMMICK_TRIGGER_POS_Y_DIFF_battle_gimmick, 0);
    }

    gSprites[gBattleStruct->gimmick.triggerSpriteId].tBattler_battle_gimmick = battler;
    gSprites[gBattleStruct->gimmick.triggerSpriteId].tHide_battle_gimmick = FALSE;

    ChangeGimmickTriggerSprite(gBattleStruct->gimmick.triggerSpriteId, 0);
}

bool32 IsGimmickTriggerSpriteActive(void)
{
    if (GetSpriteTileStartByTag(TAG_GIMMICK_TRIGGER_TILE) == 0xFFFF)
        return FALSE;
    else if (IndexOfSpritePaletteTag(TAG_GIMMICK_TRIGGER_PAL) != 0xFF)
        return TRUE;
    else
        return FALSE;
}

void HideGimmickTriggerSprite(void)
{
    if (gBattleStruct->gimmick.triggerSpriteId != 0xFF)
    {
        ChangeGimmickTriggerSprite(gBattleStruct->gimmick.triggerSpriteId, 0);
        gSprites[gBattleStruct->gimmick.triggerSpriteId].tHide_battle_gimmick = TRUE;
    }
}

void DestroyGimmickTriggerSprite(void)
{
    FreeSpritePaletteByTag(TAG_GIMMICK_TRIGGER_PAL);
    FreeSpriteTilesByTag(TAG_GIMMICK_TRIGGER_TILE);
    if (gBattleStruct->gimmick.triggerSpriteId != 0xFF)
        DestroySprite(&gSprites[gBattleStruct->gimmick.triggerSpriteId]);
    gBattleStruct->gimmick.triggerSpriteId = 0xFF;
}

static void SpriteCb_GimmickTrigger_battle_gimmick(struct Sprite *sprite)
{
    s32 xSlide, xPriority, xOptimal;
    s32 yDiff;

    if (IsDoubleBattle())
    {
        xSlide = DOUBLES_GIMMICK_TRIGGER_POS_X_SLIDE_battle_gimmick;
        xPriority = DOUBLES_GIMMICK_TRIGGER_POS_X_PRIORITY_battle_gimmick;
        xOptimal = DOUBLES_GIMMICK_TRIGGER_POS_X_OPTIMAL_battle_gimmick;
        yDiff = DOUBLES_GIMMICK_TRIGGER_POS_Y_DIFF_battle_gimmick;
    }
    else
    {
        xSlide = SINGLES_GIMMICK_TRIGGER_POS_X_SLIDE_battle_gimmick;
        xPriority = SINGLES_GIMMICK_TRIGGER_POS_X_PRIORITY_battle_gimmick;
        xOptimal = SINGLES_GIMMICK_TRIGGER_POS_X_OPTIMAL_battle_gimmick;
        yDiff = SINGLES_GIMMICK_TRIGGER_POS_Y_DIFF_battle_gimmick;
    }

    if (sprite->tHide_battle_gimmick)
    {
        if (sprite->x != gSprites[gHealthboxSpriteIds[sprite->tBattler_battle_gimmick]].x - xSlide)
            sprite->x++;

        if (sprite->x >= gSprites[gHealthboxSpriteIds[sprite->tBattler_battle_gimmick]].x - xPriority)
            sprite->oam.priority = 2;
        else
            sprite->oam.priority = 1;

        sprite->y = gSprites[gHealthboxSpriteIds[sprite->tBattler_battle_gimmick]].y - yDiff;
        sprite->y2 = gSprites[gHealthboxSpriteIds[sprite->tBattler_battle_gimmick]].y2 - yDiff;
        if (sprite->x == gSprites[gHealthboxSpriteIds[sprite->tBattler_battle_gimmick]].x - xSlide)
            DestroyGimmickTriggerSprite();
    }
    else
    {
        if (sprite->x != gSprites[gHealthboxSpriteIds[sprite->tBattler_battle_gimmick]].x - xOptimal)
            sprite->x--;

        if (sprite->x >= gSprites[gHealthboxSpriteIds[sprite->tBattler_battle_gimmick]].x - xPriority)
            sprite->oam.priority = 2;
        else
            sprite->oam.priority = 1;

        sprite->y = gSprites[gHealthboxSpriteIds[sprite->tBattler_battle_gimmick]].y - yDiff;
        sprite->y2 = gSprites[gHealthboxSpriteIds[sprite->tBattler_battle_gimmick]].y2 - yDiff;
    }
}

#undef tBattler_battle_gimmick
#undef tHide_battle_gimmick

// for sprite data fields
#define tBattler_battle_gimmick        data[0]
#define tPosX_battle_gimmick           data[2]
#define tLevelXDelta_battle_gimmick    data[3] // X position depends whether level has 3, 2 or 1 digit

// data fields for healthboxMain
// oam.affineParam holds healthboxRight spriteId
#define hMain_Battler_battle_gimmick               data[6]

void LoadIndicatorSpritesGfx(void)
{
    u32 gimmick;
    for (gimmick = 0; gimmick < GIMMICKS_COUNT; ++gimmick)
    {
        if (gimmick == GIMMICK_TERA) // special case
            LoadSpriteSheets(sTeraIndicatorSpriteSheets);
        else if (gGimmicksInfo[gimmick].indicatorSheet != NULL)
            LoadSpriteSheet(gGimmicksInfo[gimmick].indicatorSheet);

        if (gGimmicksInfo[gimmick].indicatorPal != NULL)
            LoadSpritePalette(gGimmicksInfo[gimmick].indicatorPal);
    }
    // Primal reversion graphics aren't loaded as part of gimmick data
    LoadSpriteSheet(&sSpriteSheet_AlphaIndicator);
    LoadSpriteSheet(&sSpriteSheet_OmegaIndicator);
}

static void SpriteCb_GimmickIndicator_battle_gimmick(struct Sprite *sprite)
{
    u32 battler = sprite->tBattler_battle_gimmick;

    sprite->x = gSprites[gHealthboxSpriteIds[battler]].x + sprite->tPosX_battle_gimmick + sprite->tLevelXDelta_battle_gimmick;
    sprite->x2 = gSprites[gHealthboxSpriteIds[battler]].x2;
    sprite->y2 = gSprites[gHealthboxSpriteIds[battler]].y2;
}

static inline u32 GetIndicatorSpriteId_battle_gimmick(u32 healthboxId)
{
    return gBattleStruct->gimmick.indicatorSpriteId[gSprites[healthboxId].hMain_Battler_battle_gimmick];
}

u32 GetIndicatorTileTag(u32 battler)
{
    u32 gimmick = GetActiveGimmick(battler);

    if (IsBattlerPrimalReverted(battler))
    {
        if (gBattleMons[battler].species == SPECIES_GROUDON_PRIMAL)
            return TAG_OMEGA_INDICATOR_TILE;
        else
            return TAG_ALPHA_INDICATOR_TILE;
    }
    else if (gimmick == GIMMICK_TERA) // special case
    {
        return sTeraIndicatorSpriteSheets[GetBattlerTeraType(battler)].tag;
    }
    else if (gGimmicksInfo[gimmick].indicatorSheet != NULL)
    {
        return gGimmicksInfo[gimmick].indicatorSheet->tag;
    }
    else
    {
        return TAG_NONE;
    }
}

u32 GetIndicatorPalTag(u32 battler)
{
    u32 gimmick = GetActiveGimmick(battler);
    if (IsBattlerPrimalReverted(battler))
        return TAG_MISC_INDICATOR_PAL;
    else if (gGimmicksInfo[gimmick].indicatorPal != NULL)
        return gGimmicksInfo[gimmick].indicatorPal->tag;
    else
        return TAG_NONE;
}

void UpdateIndicatorVisibilityAndType(u32 healthboxId, bool32 invisible)
{
    u32 battler = gSprites[healthboxId].hMain_Battler_battle_gimmick;
    u32 tileTag = GetIndicatorTileTag(battler);
    u32 palTag = GetIndicatorPalTag(battler);
    struct Sprite *sprite = &gSprites[GetIndicatorSpriteId_battle_gimmick(healthboxId)];

    if (GetIndicatorSpriteId_battle_gimmick(healthboxId) == 0) // safari zone means the player doesn't have an indicator sprite id
        return;

    if (tileTag != TAG_NONE && palTag != TAG_NONE)
    {
        sprite->oam.tileNum = GetSpriteTileStartByTag(tileTag);
        sprite->oam.paletteNum = IndexOfSpritePaletteTag(palTag);
        sprite->invisible = invisible;
    }
    else // in case of error
    {
        sprite->invisible = TRUE;
    }
}

void UpdateIndicatorOamPriority(u32 healthboxId, u32 oamPriority)
{
    gSprites[GetIndicatorSpriteId_battle_gimmick(healthboxId)].oam.priority = oamPriority;
}

void UpdateIndicatorLevelData(u32 healthboxId, u32 level)
{
    s32 xDelta = 0;

    if (level >= 100)
        xDelta -= 4;
    else if (level < 10)
        xDelta += 5;

    gSprites[GetIndicatorSpriteId_battle_gimmick(healthboxId)].tLevelXDelta_battle_gimmick = xDelta;
}

static const s8  sIndicatorPositions_battle_gimmick[][2] =
{
    [B_POSITION_PLAYER_LEFT] = {53, -9},
    [B_POSITION_OPPONENT_LEFT] = {44, -9},
    [B_POSITION_PLAYER_RIGHT] = {52, -9},
    [B_POSITION_OPPONENT_RIGHT] = {44, -9},
};

void CreateIndicatorSprite(u32 battler)
{
    u32 position, spriteId;
    s16 xHealthbox = 0, x = 0, y = 0;

    position = GetBattlerPosition(battler);
    GetBattlerHealthboxCoords(battler, &xHealthbox, &y);

    x = sIndicatorPositions_battle_gimmick[position][0];
    y += sIndicatorPositions_battle_gimmick[position][1];

    spriteId = CreateSpriteAtEnd(&sSpriteTemplate_GimmickIndicator, 0, y, 0);
    gBattleStruct->gimmick.indicatorSpriteId[battler] = spriteId;
    gSprites[spriteId].tBattler_battle_gimmick = battler;
    gSprites[spriteId].tPosX_battle_gimmick = x;
    gSprites[spriteId].invisible = FALSE;
}

#undef tBattler_battle_gimmick
#undef tPosX_battle_gimmick
#undef tLevelXDelta_battle_gimmick

#undef hMain_Battler_battle_gimmick
