static inline void CopyPixels_battle_interface(u8 *dest, const u8 *src, u32 pixelCount)
{
    u32 i = 0;

    if (pixelCount & 1)
    {
        while (pixelCount != 0)
        {
            dest[i] &= ~(0xF);
            dest[i] |= (src[i] & 0xF);
            if (--pixelCount != 0)
            {
                dest[i] &= ~(0xF0);
                dest[i] |= (src[i] & 0xF0);
                pixelCount--;
            }
            i++;
        }
    }
    else
    {
        for (i = 0; i < pixelCount / 2; i++)
            dest[i] = src[i];
    }
}

static void RestoreOverwrittenPixels_battle_interface(u8 *tiles)
{
    u32 i;
    u8 *buffer = Alloc(sizeof(sAbilityPopUpGfx_battle_interface) * 2);

    CpuCopy32(tiles, buffer, sizeof(sAbilityPopUpGfx_battle_interface));

    for (i = 0; i < ARRAY_COUNT(sOverwrittenPixelsTable_battle_interface); i++)
    {
        CopyPixels_battle_interface(buffer + sOverwrittenPixelsTable_battle_interface[i][0],
                   sAbilityPopUpGfx_battle_interface + sOverwrittenPixelsTable_battle_interface[i][0],
                   sOverwrittenPixelsTable_battle_interface[i][1]);
    }

    CpuCopy32(buffer, tiles, sizeof(sAbilityPopUpGfx_battle_interface));
    Free(buffer);
}

void CreateAbilityPopUp(u8 battlerId, u32 ability, bool32 isDoubleBattle)
{
    const s16 (*coords)[2];
    u8 spriteId1, spriteId2, battlerPosition, taskId;

    if (B_ABILITY_POP_UP == FALSE)
        return;

    if (gBattleScripting.abilityPopupOverwrite != 0)
        ability = gBattleScripting.abilityPopupOverwrite;

    if (gTestRunnerEnabled)
    {
        TestRunner_Battle_RecordAbilityPopUp(battlerId, ability);
        if (gTestRunnerHeadless)
            return;
    }

    if (!gBattleStruct->activeAbilityPopUps)
    {
        LoadSpriteSheet(&sSpriteSheet_AbilityPopUp_battle_interface);
        LoadSpritePalette(&sSpritePalette_AbilityPopUp_battle_interface);
    }
    gBattleStruct->activeAbilityPopUps |= 1u << battlerId;
    battlerPosition = GetBattlerPosition(battlerId);

    if (isDoubleBattle)
        coords = sAbilityPopUpCoordsDoubles_battle_interface;
    else
        coords = sAbilityPopUpCoordsSingles_battle_interface;

    if ((battlerPosition & BIT_SIDE) == B_SIDE_PLAYER)
    {
        spriteId1 = CreateSprite(&sSpriteTemplate_AbilityPopUp_battle_interface,
                                coords[battlerPosition][0] - ABILITY_POP_UP_POS_X_SLIDE_battle_interface,
                                coords[battlerPosition][1], 0);
        spriteId2 = CreateSprite(&sSpriteTemplate_AbilityPopUp_battle_interface,
                                coords[battlerPosition][0] - ABILITY_POP_UP_POS_X_SLIDE_battle_interface + ABILITY_POP_UP_POS_X_DIFF_battle_interface,
                                coords[battlerPosition][1], 1); //Appears below

        gSprites[spriteId1].tRightToLeft_battle_interface = TRUE;
        gSprites[spriteId2].tRightToLeft_battle_interface = TRUE;
    }
    else
    {
        spriteId1 = CreateSprite(&sSpriteTemplate_AbilityPopUp_battle_interface,
                                coords[battlerPosition][0] + ABILITY_POP_UP_POS_X_SLIDE_battle_interface,
                                coords[battlerPosition][1], 0);
        spriteId2 = CreateSprite(&sSpriteTemplate_AbilityPopUp_battle_interface,
                                coords[battlerPosition][0] + ABILITY_POP_UP_POS_X_SLIDE_battle_interface + ABILITY_POP_UP_POS_X_DIFF_battle_interface,
                                coords[battlerPosition][1], 1); //Appears below

        gSprites[spriteId1].tRightToLeft_battle_interface = FALSE;
        gSprites[spriteId2].tRightToLeft_battle_interface = FALSE;
    }

    gSprites[spriteId1].tOriginalX_battle_interface = coords[battlerPosition][0];
    gSprites[spriteId2].tOriginalX_battle_interface = coords[battlerPosition][0] + ABILITY_POP_UP_POS_X_DIFF_battle_interface;
    gSprites[spriteId2].oam.tileNum += (8 * 4); //Second half of pop up

    gBattleStruct->abilityPopUpSpriteIds[battlerId][0] = spriteId1;
    gBattleStruct->abilityPopUpSpriteIds[battlerId][1] = spriteId2;

    taskId = CreateTask(Task_FreeAbilityPopUpGfx_battle_interface, 5);
    gTasks[taskId].tSpriteId1_battle_interface = spriteId1;
    gTasks[taskId].tSpriteId2_battle_interface = spriteId2;

    gSprites[spriteId1].tIsMain_battle_interface = TRUE;
    gSprites[spriteId1].tBattlerId_battle_interface = battlerId;
    gSprites[spriteId2].tBattlerId_battle_interface = battlerId;

    StartSpriteAnim(&gSprites[spriteId1], 0);
    StartSpriteAnim(&gSprites[spriteId2], 0);

    PrintBattlerOnAbilityPopUp_battle_interface(battlerId, spriteId1, spriteId2);
    PrintAbilityOnAbilityPopUp_battle_interface(ability, spriteId1, spriteId2);
    RestoreOverwrittenPixels_battle_interface((void*)(OBJ_VRAM0) + (gSprites[spriteId1].oam.tileNum * 32));
}

void UpdateAbilityPopup(u8 battlerId)
{
    u8 spriteId1 = gBattleStruct->abilityPopUpSpriteIds[battlerId][0];
    u8 spriteId2 = gBattleStruct->abilityPopUpSpriteIds[battlerId][1];
    u16 ability = (gBattleScripting.abilityPopupOverwrite != 0) ? gBattleScripting.abilityPopupOverwrite : gBattleMons[battlerId].ability;

    PrintAbilityOnAbilityPopUp_battle_interface(ability, spriteId1, spriteId2);
    RestoreOverwrittenPixels_battle_interface((void*)(OBJ_VRAM0) + (gSprites[spriteId1].oam.tileNum * 32));
}

#define FRAMES_TO_WAIT_battle_interface 48

static void SpriteCb_AbilityPopUp_battle_interface(struct Sprite *sprite)
{
    if (!sprite->tHide_battle_interface) // Show
    {
        if (sprite->tIsMain_battle_interface && ++sprite->tFrames_battle_interface == 4)
            PlaySE(SE_BALL_TRAY_ENTER);
        if ((!sprite->tRightToLeft_battle_interface && (sprite->x -= 4) <= sprite->tOriginalX_battle_interface)
            || (sprite->tRightToLeft_battle_interface && (sprite->x += 4) >= sprite->tOriginalX_battle_interface)
           )
        {
            sprite->x = sprite->tOriginalX_battle_interface;
            sprite->tHide_battle_interface = TRUE;
            sprite->tFrames_battle_interface = FRAMES_TO_WAIT_battle_interface;
        }
    }
    else // Hide
    {
        if (sprite->tFrames_battle_interface == 0)
        {
            if ((!sprite->tRightToLeft_battle_interface && (sprite->x += 4) >= sprite->tOriginalX_battle_interface + ABILITY_POP_UP_POS_X_SLIDE_battle_interface)
                ||(sprite->tRightToLeft_battle_interface && (sprite->x -= 4) <= sprite->tOriginalX_battle_interface - ABILITY_POP_UP_POS_X_SLIDE_battle_interface)
               )
            {
                gBattleStruct->activeAbilityPopUps &= ~(1u << sprite->tBattlerId_battle_interface);
                DestroySprite(sprite);
            }
        }
        else
        {
            if (!gBattleScripting.fixedPopup)
                sprite->tFrames_battle_interface--;
        }
    }
}

void DestroyAbilityPopUp(u8 battlerId)
{
    if (gBattleStruct->activeAbilityPopUps & (1u << battlerId))
    {
        gSprites[gBattleStruct->abilityPopUpSpriteIds[battlerId][0]].tFrames_battle_interface = 0;
        gSprites[gBattleStruct->abilityPopUpSpriteIds[battlerId][1]].tFrames_battle_interface = 0;
    }
    gBattleScripting.fixedPopup = FALSE;
}

static void Task_FreeAbilityPopUpGfx_battle_interface(u8 taskId)
{
    if (!gSprites[gTasks[taskId].tSpriteId1_battle_interface].inUse
        && !gSprites[gTasks[taskId].tSpriteId2_battle_interface].inUse
        && !gBattleStruct->activeAbilityPopUps)
    {
        FreeSpriteTilesByTag(ABILITY_POP_UP_TAG_battle_interface);
        FreeSpritePaletteByTag(ABILITY_POP_UP_TAG_battle_interface);
        DestroyTask(taskId);
    }
}

