#define LAST_USED_BALL_X_F_battle_interface    14
#define LAST_USED_BALL_X_0_battle_interface    -14
#define LAST_USED_BALL_Y_battle_interface      ((IsDoubleBattle()) ? 78 : 68)
#define LAST_USED_BALL_Y_BNC_battle_interface  ((IsDoubleBattle()) ? 76 : 66)

#define LAST_BALL_WIN_X_F_battle_interface       (LAST_USED_BALL_X_F_battle_interface - 0)
#define LAST_BALL_WIN_X_0_battle_interface       (LAST_USED_BALL_X_0_battle_interface - 0)
#define LAST_USED_WIN_Y_battle_interface         (LAST_USED_BALL_Y_battle_interface - 8)

#define sHide_battle_interface  data[0]
#define sTimer_battle_interface  data[1]
#define sMoving_battle_interface data[2]
#define sBounce_battle_interface data[3] // 0 = Bounce down; 1 = Bounce up

#define sState_battle_interface     data[0]
#define sSameBall_battle_interface  data[1]

bool32 CanThrowLastUsedBall(void)
{
    if (B_LAST_USED_BALL == FALSE)
        return FALSE;
    if (!CanThrowBall())
        return FALSE;
    if (gBattleTypeFlags & (BATTLE_TYPE_TRAINER | BATTLE_TYPE_FRONTIER))
        return FALSE;
    if (!CheckBagHasItem(gBallToDisplay, 1))
        return FALSE;

    return TRUE;
}

void TryAddLastUsedBallItemSprites(void)
{
    if (B_LAST_USED_BALL == FALSE)
        return;
    if (gLastThrownBall == 0
      || (gLastThrownBall != 0 && !CheckBagHasItem(gLastThrownBall, 1)))
    {
        // we're out of the last used ball, so just set it to the first ball in the bag
        u16 firstBall;

        // we have to compact the bag first bc it is typically only compacted when you open it
        CompactItemsInBagPocket(&gBagPockets[BALLS_POCKET]);

        firstBall = gBagPockets[BALLS_POCKET].itemSlots[0].itemId;
        if (firstBall > ITEM_NONE)
            gBallToDisplay = firstBall;
    }

    if (!CanThrowLastUsedBall())
        return;

    // ball
    if (gBattleStruct->ballSpriteIds[0] == MAX_SPRITES)
    {
        gBattleStruct->ballSpriteIds[0] = AddItemIconSprite(102, 102, gBallToDisplay);
        gSprites[gBattleStruct->ballSpriteIds[0]].x = LAST_USED_BALL_X_0_battle_interface;
        gSprites[gBattleStruct->ballSpriteIds[0]].y = LAST_USED_BALL_Y_battle_interface;
        gSprites[gBattleStruct->ballSpriteIds[0]].sHide_battle_interface = FALSE;   // restore
        gLastUsedBallMenuPresent = TRUE;
        gSprites[gBattleStruct->ballSpriteIds[0]].callback = SpriteCB_LastUsedBall_battle_interface;
    }

    // window
    LoadSpritePalette(&sSpritePalette_AbilityPopUp_battle_interface);
    if (GetSpriteTileStartByTag(LAST_BALL_WINDOW_TAG_battle_interface) == 0xFFFF)
        LoadSpriteSheet(&sSpriteSheet_LastUsedBallWindow_battle_interface);

    if (gBattleStruct->ballSpriteIds[1] == MAX_SPRITES)
    {
        gBattleStruct->ballSpriteIds[1] = CreateSprite(&sSpriteTemplate_LastUsedBallWindow_battle_interface,
                                                       LAST_BALL_WIN_X_0_battle_interface,
                                                       LAST_USED_WIN_Y_battle_interface, 5);
        gSprites[gBattleStruct->ballSpriteIds[1]].sHide_battle_interface = FALSE;   // restore
        gLastUsedBallMenuPresent = TRUE;
    }
    if (B_LAST_USED_BALL_CYCLE == TRUE)
        ArrowsChangeColorLastBallCycle(0); //Default the arrows to be invisible
}

static void DestroyLastUsedBallWinGfx_battle_interface(struct Sprite *sprite)
{
    FreeSpriteTilesByTag(LAST_BALL_WINDOW_TAG_battle_interface);
    FreeSpritePaletteByTag(ABILITY_POP_UP_TAG_battle_interface);
    DestroySprite(sprite);
    gBattleStruct->ballSpriteIds[1] = MAX_SPRITES;
}

static void DestroyLastUsedBallGfx_battle_interface(struct Sprite *sprite)
{
    FreeSpriteTilesByTag(102);
    FreeSpritePaletteByTag(102);
    DestroySprite(sprite);
    gBattleStruct->ballSpriteIds[0] = MAX_SPRITES;
}

static void SpriteCB_LastUsedBallWin_battle_interface(struct Sprite *sprite)
{
    if (sprite->sHide_battle_interface)
    {
        if (sprite->x != LAST_BALL_WIN_X_0_battle_interface)
            sprite->x--;

        if (sprite->x == LAST_BALL_WIN_X_0_battle_interface)
            DestroyLastUsedBallWinGfx_battle_interface(sprite);
    }
    else
    {
        if (sprite->x != LAST_BALL_WIN_X_F_battle_interface)
            sprite->x++;
    }
}

static void SpriteCB_LastUsedBall_battle_interface(struct Sprite *sprite)
{
    if (sprite->sHide_battle_interface)
    {
        if (sprite->y < LAST_USED_BALL_Y_battle_interface) // Used to recover from an incomplete bounce before hiding the window
            sprite->y++;

        if (sprite->x != LAST_USED_BALL_X_0_battle_interface)
            sprite->x--;

        if (sprite->x == LAST_USED_BALL_X_0_battle_interface)
            DestroyLastUsedBallGfx_battle_interface(sprite);
    }
    else
    {
        if (sprite->x != LAST_USED_BALL_X_F_battle_interface)
            sprite->x++;
    }
}

static void TryHideOrRestoreLastUsedBall_battle_interface(u8 caseId)
{
    if (B_LAST_USED_BALL == FALSE)
        return;
    if (gBattleStruct->ballSpriteIds[0] == MAX_SPRITES)
        return;

    switch (caseId)
    {
    case 0: // hide
        if (gBattleStruct->ballSpriteIds[0] != MAX_SPRITES)
            gSprites[gBattleStruct->ballSpriteIds[0]].sHide_battle_interface = TRUE;   // hide
        if (gBattleStruct->ballSpriteIds[1] != MAX_SPRITES)
            gSprites[gBattleStruct->ballSpriteIds[1]].sHide_battle_interface = TRUE;   // hide
        gLastUsedBallMenuPresent = FALSE;
        break;
    case 1: // restore
        if (gBattleStruct->ballSpriteIds[0] != MAX_SPRITES)
            gSprites[gBattleStruct->ballSpriteIds[0]].sHide_battle_interface = FALSE;   // restore
        if (gBattleStruct->ballSpriteIds[1] != MAX_SPRITES)
            gSprites[gBattleStruct->ballSpriteIds[1]].sHide_battle_interface = FALSE;   // restore
        gLastUsedBallMenuPresent = TRUE;
        break;
    }
    if (B_LAST_USED_BALL_CYCLE == TRUE)
        ArrowsChangeColorLastBallCycle(0); //Default the arrows to be invisible
}

void TryHideLastUsedBall(void)
{
    if (B_LAST_USED_BALL == TRUE)
        TryHideOrRestoreLastUsedBall_battle_interface(0);
}

void TryRestoreLastUsedBall(void)
{
    if (B_LAST_USED_BALL == FALSE)
        return;

    if (gBattleStruct->ballSpriteIds[0] != MAX_SPRITES)
        TryHideOrRestoreLastUsedBall_battle_interface(1);
    else
        TryAddLastUsedBallItemSprites();
}

static void SpriteCB_LastUsedBallBounce_battle_interface(struct Sprite *sprite)
{
    if ((sprite->sTimer_battle_interface++ % 4) != 0)  // Change the image every 4 frame
        return;
    if (sprite->sBounce_battle_interface)
    {
        if (sprite->y > LAST_USED_BALL_Y_BNC_battle_interface)
            sprite->y--;
        else
            sprite->sMoving_battle_interface = FALSE;
    }
    else
    {
        if (sprite->y < LAST_USED_BALL_Y_battle_interface)
            sprite->y++;
        else
            sprite->sMoving_battle_interface = FALSE;
    }
}

static void Task_BounceBall_battle_interface(u8 taskId)
{
    struct Sprite *sprite = &gSprites[gBattleStruct->ballSpriteIds[0]];
    struct Task *task = &gTasks[taskId];
    switch(task->sState_battle_interface)
    {
    case 0:  // Bounce up
        sprite->sBounce_battle_interface = TRUE;
        sprite->sMoving_battle_interface = TRUE;
        sprite->callback = SpriteCB_LastUsedBallBounce_battle_interface;
        if (task->sSameBall_battle_interface)
            task->sState_battle_interface = 3;
        else
            task->sState_battle_interface = 1;
        break;
    case 1:  // Destroy Icon
        if (!sprite->sMoving_battle_interface)
        {
            DestroyLastUsedBallGfx_battle_interface(sprite);
            task->sState_battle_interface++;
        }  // Passthrough
    case 2: //Create New Icon
        if (!sprite->inUse)
        {
            gBattleStruct->ballSpriteIds[0] = AddItemIconSprite(102, 102, gBallToDisplay);
            gSprites[gBattleStruct->ballSpriteIds[0]].x = LAST_USED_BALL_X_F_battle_interface;
            gSprites[gBattleStruct->ballSpriteIds[0]].y = LAST_USED_BALL_Y_BNC_battle_interface;
            task->sState_battle_interface++;
        }  // Fallthrough
    case 3: // Bounce Down
        if (!sprite->sMoving_battle_interface)
        {
            sprite->sBounce_battle_interface = FALSE;
            sprite->sMoving_battle_interface = TRUE;
            sprite->callback = SpriteCB_LastUsedBallBounce_battle_interface; //Show and bounce down
            task->sState_battle_interface++;
        }
        break;
    case 4:  // Destroy Task
        if(!sprite->sMoving_battle_interface)
        {
            sprite->callback = SpriteCB_LastUsedBall_battle_interface;
            DestroyTask(taskId);
        }
    }
    if (!gLastUsedBallMenuPresent)
    {
        // Used to check if the R button was released before the animation was complete
        sprite->callback = SpriteCB_LastUsedBall_battle_interface;
        DestroyTask(taskId);
    }
}

void SwapBallToDisplay(bool32 sameBall)
{
    u8 taskId;
    taskId = CreateTask(Task_BounceBall_battle_interface, 10);
    gTasks[taskId].sSameBall_battle_interface = sameBall;
}

void ArrowsChangeColorLastBallCycle(bool32 showArrows)
{
#if B_LAST_USED_BALL == TRUE && B_LAST_USED_BALL_CYCLE == TRUE
    u16 paletteNum = 16 + gSprites[gBattleStruct->ballSpriteIds[1]].oam.paletteNum;
    struct PlttData *defaultPlttArrow;
    struct PlttData *defaultPlttOutline;
    struct PlttData *pltArrow;
    struct PlttData *pltOutline;
    if (gBattleStruct->ballSpriteIds[1] == MAX_SPRITES)
        return;
    paletteNum *= 16;
    pltArrow = (struct PlttData *)&gPlttBufferFaded[paletteNum + 9];  // Arrow color is in idx 9
    pltOutline = (struct PlttData *)&gPlttBufferFaded[paletteNum + 8];  // Arrow outline is in idx 8
    if (!showArrows) //Make invisible
    {
        defaultPlttArrow = (struct PlttData *)&gPlttBufferFaded[paletteNum + 13];  // Background color is idx 13
        pltArrow->r = defaultPlttArrow->r;
        pltArrow->g = defaultPlttArrow->g;
        pltArrow->b = defaultPlttArrow->b;
        pltOutline->r = defaultPlttArrow->r;
        pltOutline->g = defaultPlttArrow->g;
        pltOutline->b = defaultPlttArrow->b;
    }
    else // Make gray
    {
        defaultPlttArrow = (struct PlttData *)&gPlttBufferFaded[paletteNum + 11];  // Grey color is idx 11
        defaultPlttOutline = (struct PlttData *)&gPlttBufferFaded[paletteNum + 10];  //Light grey color for outline is idx 10
        pltArrow->r = defaultPlttArrow->r;
        pltArrow->g = defaultPlttArrow->g;
        pltArrow->b = defaultPlttArrow->b;
        pltOutline->r = defaultPlttOutline->r;
        pltOutline->g = defaultPlttOutline->g;
        pltOutline->b = defaultPlttOutline->b;
    }
#endif
}

void CategoryIcons_LoadSpritesGfx(void)
{
    LoadCompressedSpriteSheet(&gSpriteSheet_CategoryIcons);
    LoadSpritePalette(&gSpritePal_CategoryIcons);
}
