#define sSinIndex_battle_main           data[3]
#define sDelta_battle_main              data[4]
#define sAmplitude_battle_main          data[5]
#define sBouncerSpriteId_battle_main    data[6]
#define sWhich_battle_main              data[7]

void DoBounceEffect(u8 battler, u8 which, s8 delta, s8 amplitude)
{
    u8 invisibleSpriteId;
    u8 bouncerSpriteId;

    switch (which)
    {
    case BOUNCE_HEALTHBOX:
    default:
        if (gBattleSpritesDataPtr->healthBoxesData[battler].healthboxIsBouncing)
            return;
        break;
    case BOUNCE_MON:
        if (gBattleSpritesDataPtr->healthBoxesData[battler].battlerIsBouncing)
            return;
        break;
    }

    invisibleSpriteId = CreateInvisibleSpriteWithCallback(SpriteCB_BounceEffect_battle_main);
    if (which == BOUNCE_HEALTHBOX)
    {
        bouncerSpriteId = gHealthboxSpriteIds[battler];
        gBattleSpritesDataPtr->healthBoxesData[battler].healthboxBounceSpriteId = invisibleSpriteId;
        gBattleSpritesDataPtr->healthBoxesData[battler].healthboxIsBouncing = 1;
        gSprites[invisibleSpriteId].sSinIndex_battle_main = 128; // 0
    }
    else
    {
        bouncerSpriteId = gBattlerSpriteIds[battler];
        gBattleSpritesDataPtr->healthBoxesData[battler].battlerBounceSpriteId = invisibleSpriteId;
        gBattleSpritesDataPtr->healthBoxesData[battler].battlerIsBouncing = 1;
        gSprites[invisibleSpriteId].sSinIndex_battle_main = 192; // -1
    }
    gSprites[invisibleSpriteId].sDelta_battle_main = delta;
    gSprites[invisibleSpriteId].sAmplitude_battle_main = amplitude;
    gSprites[invisibleSpriteId].sBouncerSpriteId_battle_main = bouncerSpriteId;
    gSprites[invisibleSpriteId].sWhich_battle_main = which;
    gSprites[invisibleSpriteId].sBattler_battle_main = battler;
    gSprites[bouncerSpriteId].x2 = 0;
    gSprites[bouncerSpriteId].y2 = 0;
}

void EndBounceEffect(u8 battler, u8 which)
{
    u8 bouncerSpriteId;

    if (which == BOUNCE_HEALTHBOX)
    {
        if (!gBattleSpritesDataPtr->healthBoxesData[battler].healthboxIsBouncing)
            return;

        bouncerSpriteId = gSprites[gBattleSpritesDataPtr->healthBoxesData[battler].healthboxBounceSpriteId].sBouncerSpriteId_battle_main;
        DestroySprite(&gSprites[gBattleSpritesDataPtr->healthBoxesData[battler].healthboxBounceSpriteId]);
        gBattleSpritesDataPtr->healthBoxesData[battler].healthboxIsBouncing = 0;
    }
    else
    {
        if (!gBattleSpritesDataPtr->healthBoxesData[battler].battlerIsBouncing)
            return;

        bouncerSpriteId = gSprites[gBattleSpritesDataPtr->healthBoxesData[battler].battlerBounceSpriteId].sBouncerSpriteId_battle_main;
        DestroySprite(&gSprites[gBattleSpritesDataPtr->healthBoxesData[battler].battlerBounceSpriteId]);
        gBattleSpritesDataPtr->healthBoxesData[battler].battlerIsBouncing = 0;
    }

    gSprites[bouncerSpriteId].x2 = 0;
    gSprites[bouncerSpriteId].y2 = 0;
}

static void SpriteCB_BounceEffect_battle_main(struct Sprite *sprite)
{
    u8 bouncerSpriteId = sprite->sBouncerSpriteId_battle_main;
    s32 index = sprite->sSinIndex_battle_main;
    s32 y = Sin(index, sprite->sAmplitude_battle_main) + sprite->sAmplitude_battle_main;

    gSprites[bouncerSpriteId].y2 = y;
    sprite->sSinIndex_battle_main = (sprite->sSinIndex_battle_main + sprite->sDelta_battle_main) & 0xFF;
}

#undef sSinIndex_battle_main
#undef sDelta_battle_main
#undef sAmplitude_battle_main
#undef sBouncerSpriteId_battle_main
#undef sWhich_battle_main

