static void HealMon_battle_pike(struct Pokemon *mon)
{
    u8 i;
    u16 hp;
    u8 ppBonuses;
    u8 data[4];

    for (i = 0; i < 4; i++)
        data[i] = 0;

    hp = GetMonData(mon, MON_DATA_MAX_HP);
    data[0] = hp;
    data[1] = hp >> 8;
    SetMonData(mon, MON_DATA_HP, data);

    ppBonuses = GetMonData(mon, MON_DATA_PP_BONUSES);
    for (i = 0; i < MAX_MON_MOVES; i++)
    {
        u16 move = GetMonData(mon, MON_DATA_MOVE1 + i);
        data[0] = CalculatePPWithBonus(move, ppBonuses, i);
        SetMonData(mon, MON_DATA_PP1 + i, data);
    }

    data[0] = 0;
    data[1] = 0;
    data[2] = 0;
    data[3] = 0;
    SetMonData(mon, MON_DATA_STATUS, data);
}

static bool8 DoesAbilityPreventStatus_battle_pike(struct Pokemon *mon, u32 status)
{
    u16 ability = GetMonAbility(mon);
    bool8 ret = FALSE;

    if (ability == ABILITY_COMATOSE)
        return TRUE;

    switch (status)
    {
    case STATUS1_FREEZE:
    case STATUS1_FROSTBITE:
        if (ability == ABILITY_MAGMA_ARMOR)
            ret = TRUE;
        break;
    case STATUS1_BURN:
        if (ability == ABILITY_WATER_VEIL || ability == ABILITY_WATER_BUBBLE)
            ret = TRUE;
        break;
    case STATUS1_PARALYSIS:
        if (ability == ABILITY_LIMBER)
            ret = TRUE;
        break;
    case STATUS1_SLEEP:
        if (ability == ABILITY_INSOMNIA || ability == ABILITY_VITAL_SPIRIT)
            ret = TRUE;
        break;
    case STATUS1_TOXIC_POISON:
        if (ability == ABILITY_IMMUNITY || ability == ABILITY_PASTEL_VEIL)
            ret = TRUE;
        break;
    }
    return ret;
}

static bool8 DoesTypePreventStatus_battle_pike(u16 species, u32 status)
{
    bool8 ret = FALSE;

    switch (status)
    {
    case STATUS1_TOXIC_POISON:
        if (gSpeciesInfo[species].types[0] == TYPE_STEEL || gSpeciesInfo[species].types[0] == TYPE_POISON
            || gSpeciesInfo[species].types[1] == TYPE_STEEL || gSpeciesInfo[species].types[1] == TYPE_POISON)
            ret = TRUE;
        break;
    case STATUS1_FREEZE:
    case STATUS1_FROSTBITE:
        if (gSpeciesInfo[species].types[0] == TYPE_ICE || gSpeciesInfo[species].types[1] == TYPE_ICE)
            ret = TRUE;
        break;
    case STATUS1_PARALYSIS:
        if (gSpeciesInfo[species].types[0] == TYPE_GROUND || gSpeciesInfo[species].types[1] == TYPE_GROUND
            || (B_PARALYZE_ELECTRIC >= GEN_6 && (gSpeciesInfo[species].types[0] == TYPE_ELECTRIC || gSpeciesInfo[species].types[1] == TYPE_ELECTRIC)))
            ret = TRUE;
        break;
    case STATUS1_BURN:
        if (gSpeciesInfo[species].types[0] == TYPE_FIRE || gSpeciesInfo[species].types[1] == TYPE_FIRE)
            ret = TRUE;
        break;
    case STATUS1_SLEEP:
        break;
    }
    return ret;
}

static bool8 TryInflictRandomStatus_battle_pike(void)
{
    u8 j, i;
    u8 count;
    u8 indices[FRONTIER_PARTY_SIZE];
    u32 status;
    u16 species;
    bool8 statusChosen;
    struct Pokemon *mon;

    for (i = 0; i < FRONTIER_PARTY_SIZE; i++)
        indices[i] = i;

    Shuffle(indices, FRONTIER_PARTY_SIZE, sizeof(indices[0]));

    if (gSaveBlock2Ptr->frontier.curChallengeBattleNum <= 4)
        count = 1;
    else if (gSaveBlock2Ptr->frontier.curChallengeBattleNum <= 9)
        count = 2;
    else
        count = 3;

    status = 0;
    do
    {
        u8 rand;

        statusChosen = FALSE;
        rand = Random() % 100;

        if (rand < 35)
            sStatusFlags_battle_pike = STATUS1_TOXIC_POISON;
        else if (rand < 60)
            sStatusFlags_battle_pike = B_USE_FROSTBITE ? STATUS1_FROSTBITE : STATUS1_FREEZE;
        else if (rand < 80)
            sStatusFlags_battle_pike = STATUS1_PARALYSIS;
        else if (rand < 90)
            sStatusFlags_battle_pike = STATUS1_SLEEP;
        else
            sStatusFlags_battle_pike = STATUS1_BURN;

        if (status != sStatusFlags_battle_pike)
        {
            status = sStatusFlags_battle_pike;
            j = 0;
            for (i = 0; i < FRONTIER_PARTY_SIZE; i++)
            {
                mon = &gPlayerParty[indices[i]];
                if (GetAilmentFromStatus(GetMonData(mon, MON_DATA_STATUS)) == AILMENT_NONE
                    && GetMonData(mon, MON_DATA_HP) != 0)
                {
                    j++;
                    species = GetMonData(mon, MON_DATA_SPECIES);
                    if (!DoesTypePreventStatus_battle_pike(species, sStatusFlags_battle_pike))
                    {
                        statusChosen = TRUE;
                        break;
                    }
                }
                if (j == count)
                    break;
            }
            if (j == 0)
                return FALSE;
        }
    } while (!statusChosen);

    switch (sStatusFlags_battle_pike)
    {
    case STATUS1_FREEZE:
    case STATUS1_FROSTBITE:
        sStatusMon_battle_pike = PIKE_STATUSMON_DUSCLOPS;
        break;
    case STATUS1_BURN:
        if (Random() % 2 != 0)
            sStatusMon_battle_pike = PIKE_STATUSMON_DUSCLOPS;
        else
            sStatusMon_battle_pike = PIKE_STATUSMON_KIRLIA;
        break;
    case STATUS1_PARALYSIS:
    case STATUS1_SLEEP:
    case STATUS1_TOXIC_POISON:
    default:
        sStatusMon_battle_pike = PIKE_STATUSMON_KIRLIA;
        break;
    }

    j = 0;
    for (i = 0; i < FRONTIER_PARTY_SIZE; i++)
    {
        mon = &gPlayerParty[indices[i]];
        if (GetAilmentFromStatus(GetMonData(mon, MON_DATA_STATUS)) == AILMENT_NONE
            && GetMonData(mon, MON_DATA_HP) != 0)
        {
            j++;
            species = GetMonData(mon, MON_DATA_SPECIES);
            if (!DoesAbilityPreventStatus_battle_pike(mon, sStatusFlags_battle_pike) && !DoesTypePreventStatus_battle_pike(species, sStatusFlags_battle_pike))
                SetMonData(mon, MON_DATA_STATUS, &sStatusFlags_battle_pike);
        }
        if (j == count)
            break;
    }

    return TRUE;
}

static bool8 AtLeastOneHealthyMon_battle_pike(void)
{
    u8 i;
    u8 healthyMonsCount;
    u8 count;

    if (gSaveBlock2Ptr->frontier.curChallengeBattleNum <= 4)
        count = 1;
    else if (gSaveBlock2Ptr->frontier.curChallengeBattleNum <= 9)
        count = 2;
    else
        count = 3;

    healthyMonsCount = 0;
    for (i = 0; i < FRONTIER_PARTY_SIZE; i++)
    {
        struct Pokemon *mon = &gPlayerParty[i];
        if (GetAilmentFromStatus(GetMonData(mon, MON_DATA_STATUS)) == AILMENT_NONE
            && GetMonData(mon, MON_DATA_HP) != 0)
        {
            healthyMonsCount++;
        }
        if (healthyMonsCount == count)
            break;
    }

    if (healthyMonsCount == 0)
        return FALSE;
    else
        return TRUE;
}

static u8 GetNextRoomType_battle_pike(void)
{
    bool8 roomTypesDisabled[NUM_PIKE_ROOM_TYPES - 1]; // excludes Brain room, which cant be disabled
    u8 i;
    u8 nextRoomType;
    u8 roomHint;
    u8 numRoomCandidates;
    u8 *roomCandidates;
    u8 id;

    if (gSaveBlock2Ptr->frontier.pikeHintedRoomType == PIKE_ROOM_BRAIN)
        return gSaveBlock2Ptr->frontier.pikeHintedRoomType;

    // Check if the player walked into the same room that the lady gave a hint about.
    if (gSpecialVar_0x8007 == gSaveBlock2Ptr->frontier.pikeHintedRoomIndex)
    {
        if (gSaveBlock2Ptr->frontier.pikeHintedRoomType == PIKE_ROOM_STATUS)
            TryInflictRandomStatus_battle_pike();
        return gSaveBlock2Ptr->frontier.pikeHintedRoomType;
    }

    for (i = 0; i < ARRAY_COUNT(roomTypesDisabled); i++)
        roomTypesDisabled[i] = FALSE;

    numRoomCandidates = NUM_PIKE_ROOM_TYPES - 1;

    // The other two room types cannot be the same type as the one associated with the lady's hint
    roomHint = sRoomTypeHints_battle_pike[gSaveBlock2Ptr->frontier.pikeHintedRoomType];
    for (i = 0; i < ARRAY_COUNT(roomTypesDisabled); i++)
    {
        if (sRoomTypeHints_battle_pike[i] == roomHint)
        {
            roomTypesDisabled[i] = TRUE;
            numRoomCandidates--;
        }
    }

    // Remove room type candidates that would have no effect on the player's party.
    if (roomTypesDisabled[PIKE_ROOM_DOUBLE_BATTLE] != TRUE && !AtLeastTwoAliveMons_battle_pike())
    {
        roomTypesDisabled[PIKE_ROOM_DOUBLE_BATTLE] = TRUE;
        numRoomCandidates--;
    }
    if (roomTypesDisabled[PIKE_ROOM_STATUS] != TRUE && !AtLeastOneHealthyMon_battle_pike())
    {
        roomTypesDisabled[PIKE_ROOM_STATUS] = TRUE;
        numRoomCandidates--;
    }

    // Remove healing room type candidates if healing rooms are disabled.
    if (gSaveBlock2Ptr->frontier.pikeHealingRoomsDisabled)
    {
        if (roomTypesDisabled[PIKE_ROOM_HEAL_FULL] != TRUE)
        {
            roomTypesDisabled[PIKE_ROOM_HEAL_FULL] = TRUE;
            numRoomCandidates--;
        }
        if (roomTypesDisabled[PIKE_ROOM_HEAL_PART] != TRUE)
        {
            roomTypesDisabled[PIKE_ROOM_HEAL_PART] = TRUE;
            numRoomCandidates--;
        }
    }

    roomCandidates = AllocZeroed(numRoomCandidates);
    id = 0;
    for (i = 0; i < ARRAY_COUNT(roomTypesDisabled); i++)
    {
        if (roomTypesDisabled[i] == FALSE)
            roomCandidates[id++] = i;
    }

    nextRoomType = roomCandidates[Random() % numRoomCandidates];
    Free(roomCandidates);
    if (nextRoomType == PIKE_ROOM_STATUS)
        TryInflictRandomStatus_battle_pike();

    return nextRoomType;
}

