static void SetPickupItem_battle_pyramid(void)
{
    int i;
    int itemIndex;
    int rand;
    u8 id;
    u32 lvlMode = gSaveBlock2Ptr->frontier.lvlMode;
    u32 floor = gSaveBlock2Ptr->frontier.curChallengeBattleNum;
    u32 round = (gSaveBlock2Ptr->frontier.pyramidWinStreaks[lvlMode] / FRONTIER_STAGES_PER_CHALLENGE) % TOTAL_PYRAMID_ROUNDS;

    if (round >= TOTAL_PYRAMID_ROUNDS)
        round = TOTAL_PYRAMID_ROUNDS - 1;

    id = GetPyramidFloorTemplateId_battle_pyramid();
    itemIndex = (gSpecialVar_LastTalked - sPyramidFloorTemplates_battle_pyramid[id].numTrainers) - 1;
    rand = gSaveBlock2Ptr->frontier.pyramidRandoms[itemIndex / 2];
    SeedRng2(rand);

    for (i = 0; i < itemIndex + 1; i++)
        rand = Random2() % 100;

    for (i = sPickupItemOffsets_battle_pyramid[floor]; i < ARRAY_COUNT(sPickupItemSlots_battle_pyramid); i++)
    {
        if (rand < sPickupItemSlots_battle_pyramid[i][0])
            break;
    }

    if (lvlMode != FRONTIER_LVL_50)
        gSpecialVar_0x8000 = sPickupItemsLvlOpen_battle_pyramid[round][sPickupItemSlots_battle_pyramid[i][1]];
    else
        gSpecialVar_0x8000 = sPickupItemsLvl50_battle_pyramid[round][sPickupItemSlots_battle_pyramid[i][1]];

    // Quantity of item to give
    gSpecialVar_0x8001 = 1;
}

static void HidePyramidItem_battle_pyramid(void)
{
    struct ObjectEventTemplate *events = gSaveBlock1Ptr->objectEventTemplates;
    int i = 0;

    for (;;)
    {
        if (events[i].localId == gSpecialVar_LastTalked)
        {
            // Rather than using event flags to hide the item object event,
            // it moves them far off the map bounds.
            events[i].x = SHRT_MAX;
            events[i].y = SHRT_MAX;
            break;
        }
        i++;
        if (events[i].localId == 0)
            break;
    }
}

