static void PrintItemQuantity_battle_pyramid_bag(u8 windowId, u32 itemIndex, u8 y)
{
    s32 xAlign;
    if (itemIndex == LIST_CANCEL)
        return;

    if (gPyramidBagMenu->toSwapPos != POS_NONE_battle_pyramid_bag)
    {
        // Performing a swap. Keep a gray selector arrow on the position to swap to
        // and erase the selector arrow anywhere else
        if (gPyramidBagMenu->toSwapPos == (u8)(itemIndex))
            PrintSelectorArrowAtPos_battle_pyramid_bag(y, COLORID_LIGHT_GRAY_battle_pyramid_bag);
        else
            PrintSelectorArrowAtPos_battle_pyramid_bag(y, COLORID_NONE_battle_pyramid_bag);
    }

    ConvertIntToDecimalStringN(gStringVar1,
                               gSaveBlock2Ptr->frontier.pyramidBag.quantity[gSaveBlock2Ptr->frontier.lvlMode][itemIndex],
                               STR_CONV_MODE_RIGHT_ALIGN,
                               MAX_PYRAMID_ITEM_DIGITS);
    StringExpandPlaceholders(gStringVar4, gText_xVar1);
    xAlign = GetStringRightAlignXOffset(FONT_NARROW, gStringVar4, 119);
    PyramidBagPrint_Quantity_battle_pyramid_bag(windowId, gStringVar4, xAlign, y, 0, 0, TEXT_SKIP_DRAW, COLORID_DARK_GRAY_battle_pyramid_bag);
}

