static void SwapItems_battle_pyramid_bag(u8 id1, u8 id2)
{
    u16 temp;
    u16 *itemIds = gSaveBlock2Ptr->frontier.pyramidBag.itemId[gSaveBlock2Ptr->frontier.lvlMode];
#if MAX_PYRAMID_BAG_ITEM_CAPACITY > 255
    u16 *quantities = gSaveBlock2Ptr->frontier.pyramidBag.quantity[gSaveBlock2Ptr->frontier.lvlMode];
#else
    u8 *quantities = gSaveBlock2Ptr->frontier.pyramidBag.quantity[gSaveBlock2Ptr->frontier.lvlMode];
#endif

    SWAP(itemIds[id1], itemIds[id2], temp);
    SWAP(quantities[id1], quantities[id2], temp);
}

static void MovePyramidBagItemSlotInList_battle_pyramid_bag(u8 from, u8 to)
{
    u16 *itemIds = gSaveBlock2Ptr->frontier.pyramidBag.itemId[gSaveBlock2Ptr->frontier.lvlMode];
#if MAX_PYRAMID_BAG_ITEM_CAPACITY > 255
    u16 *quantities = gSaveBlock2Ptr->frontier.pyramidBag.quantity[gSaveBlock2Ptr->frontier.lvlMode];
#else
    u8 *quantities = gSaveBlock2Ptr->frontier.pyramidBag.quantity[gSaveBlock2Ptr->frontier.lvlMode];
#endif

    if (from != to)
    {
        s16 i;
        u16 firstSlotItemId = itemIds[from];
        u8 firstSlotQuantity = quantities[from];

        if (to > from)
        {
            to--;
            for (i = from; i < to; i++)
            {
                itemIds[i] = itemIds[i + 1];
                quantities[i] = quantities[i + 1];
            }
        }
        else
        {
            for (i = from; i > to; i--)
            {
                itemIds[i] = itemIds[i - 1];
                quantities[i] = quantities[i - 1];
            }
        }
        itemIds[to] = firstSlotItemId;
        quantities[to] = firstSlotQuantity;
    }
}

static void CompactItems_battle_pyramid_bag(void)
{
    u8 i, j;
    u16 *itemIds = gSaveBlock2Ptr->frontier.pyramidBag.itemId[gSaveBlock2Ptr->frontier.lvlMode];
#if MAX_PYRAMID_BAG_ITEM_CAPACITY > 255
    u16 *quantities = gSaveBlock2Ptr->frontier.pyramidBag.quantity[gSaveBlock2Ptr->frontier.lvlMode];
#else
    u8 *quantities = gSaveBlock2Ptr->frontier.pyramidBag.quantity[gSaveBlock2Ptr->frontier.lvlMode];
#endif

    for (i = 0; i < PYRAMID_BAG_ITEMS_COUNT; i++)
    {
        if (itemIds[i] == ITEM_NONE || quantities[i] == 0)
        {
            itemIds[i] = ITEM_NONE;
            quantities[i] = 0;
        }
    }
    for (i = 0; i < PYRAMID_BAG_ITEMS_COUNT - 1; i++)
    {
        for (j = i + 1; j < PYRAMID_BAG_ITEMS_COUNT; j++)
        {
            if (itemIds[i] == ITEM_NONE || quantities[i] == 0)
                SwapItems_battle_pyramid_bag(i, j);
        }
    }
}

void UpdatePyramidBagList(void)
{
    u16 i;
    u16 *itemIds = gSaveBlock2Ptr->frontier.pyramidBag.itemId[gSaveBlock2Ptr->frontier.lvlMode];

    CompactItems_battle_pyramid_bag();
    gPyramidBagMenu->listMenuCount = 0;
    for (i = 0; i < PYRAMID_BAG_ITEMS_COUNT; i++)
    {
        if (itemIds[i] != ITEM_NONE)
            gPyramidBagMenu->listMenuCount++;
    }
    gPyramidBagMenu->listMenuCount++;
    if (gPyramidBagMenu->listMenuCount > 8)
        gPyramidBagMenu->listMenuMaxShown = 8;
    else
        gPyramidBagMenu->listMenuMaxShown = gPyramidBagMenu->listMenuCount;
}

void UpdatePyramidBagCursorPos(void)
{
    if (gPyramidBagMenuState.scrollPosition != 0 && gPyramidBagMenuState.scrollPosition + gPyramidBagMenu->listMenuMaxShown > gPyramidBagMenu->listMenuCount)
        gPyramidBagMenuState.scrollPosition = gPyramidBagMenu->listMenuCount - gPyramidBagMenu->listMenuMaxShown;

    if (gPyramidBagMenuState.scrollPosition + gPyramidBagMenuState.cursorPosition >= gPyramidBagMenu->listMenuCount)
    {
        if (gPyramidBagMenu->listMenuCount == 0)
            gPyramidBagMenuState.cursorPosition = 0;
        else
            gPyramidBagMenuState.cursorPosition = gPyramidBagMenu->listMenuCount - 1;
    }
}

static void InitPyramidBagScroll_battle_pyramid_bag(void)
{
    u8 i;

    if (gPyramidBagMenuState.cursorPosition > 4)
    {
        for (i = 0; i <= gPyramidBagMenuState.cursorPosition - 4; i++)
        {
            if (gPyramidBagMenuState.scrollPosition + gPyramidBagMenu->listMenuMaxShown == gPyramidBagMenu->listMenuCount)
                break;

            gPyramidBagMenuState.cursorPosition--;
            gPyramidBagMenuState.scrollPosition++;
        }
    }
}

static void PrintSelectorArrow_battle_pyramid_bag(u8 listMenuTaskId, u8 colorId)
{
    u8 y = ListMenuGetYCoordForPrintingArrowCursor(listMenuTaskId);
    PrintSelectorArrowAtPos_battle_pyramid_bag(y, colorId);
}

static void PrintSelectorArrowAtPos_battle_pyramid_bag(u8 y, u8 colorId)
{
    if (colorId == COLORID_NONE_battle_pyramid_bag) // If 'no color', erase arrow
        FillWindowPixelRect(WIN_LIST_battle_pyramid_bag, PIXEL_FILL(0), 0, y, GetMenuCursorDimensionByFont(FONT_NORMAL, 0), GetMenuCursorDimensionByFont(FONT_NORMAL, 1));
    else
        PyramidBagPrint_battle_pyramid_bag(WIN_LIST_battle_pyramid_bag, gText_SelectorArrow2, 0, y, 0, 0, 0, colorId);
}

void CloseBattlePyramidBag(u8 taskId)
{
    BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
    gTasks[taskId].func = Task_ClosePyramidBag_battle_pyramid_bag;
}

static void Task_ClosePyramidBag_battle_pyramid_bag(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    if (!gPaletteFade.active)
    {
        DestroyListMenuTask(tListTaskId_battle_pyramid_bag, &gPyramidBagMenuState.scrollPosition, &gPyramidBagMenuState.cursorPosition);

        // If ready for a new screen (e.g. party menu for giving an item) go to that screen
        // Otherwise exit the bag and use callback set up when the bag was first opened
        if (gPyramidBagMenu->newScreenCallback != NULL)
            SetMainCallback2(gPyramidBagMenu->newScreenCallback);
        else
            SetMainCallback2(gPyramidBagMenuState.exitCallback);
        RemoveScrollArrow_battle_pyramid_bag();
        ResetSpriteData();
        FreeAllSpritePalettes();
        FreeAllWindowBuffers();
        Free(gPyramidBagMenu);
        DestroyTask(taskId);
    }
}

static void Task_HandlePyramidBagInput_battle_pyramid_bag(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    if (MenuHelpers_ShouldWaitForLinkRecv() == TRUE || gPaletteFade.active)
        return;

    if (JOY_NEW(SELECT_BUTTON))
    {
        if (gPyramidBagMenuState.location != PYRAMIDBAG_LOC_PARTY)
        {
            ListMenuGetScrollAndRow(tListTaskId_battle_pyramid_bag, &gPyramidBagMenuState.scrollPosition, &gPyramidBagMenuState.cursorPosition);
            if (gPyramidBagMenuState.scrollPosition + gPyramidBagMenuState.cursorPosition != gPyramidBagMenu->listMenuCount - 1)
            {
                PlaySE(SE_SELECT);
                Task_BeginItemSwap_battle_pyramid_bag(taskId);
            }
        }
    }
    else
    {
        s32 listId = ListMenu_ProcessInput(tListTaskId_battle_pyramid_bag);
        ListMenuGetScrollAndRow(tListTaskId_battle_pyramid_bag, &gPyramidBagMenuState.scrollPosition, &gPyramidBagMenuState.cursorPosition);
        switch (listId)
        {
        case LIST_NOTHING_CHOSEN:
            break;
        case LIST_CANCEL:
            PlaySE(SE_SELECT);
            gSpecialVar_ItemId = ITEM_NONE;
            CloseBattlePyramidBag(taskId);
            break;
        default:
            PlaySE(SE_SELECT);
            gSpecialVar_ItemId = gSaveBlock2Ptr->frontier.pyramidBag.itemId[gSaveBlock2Ptr->frontier.lvlMode][listId];
            tListPos_battle_pyramid_bag = listId;
            tQuantity_battle_pyramid_bag = gSaveBlock2Ptr->frontier.pyramidBag.quantity[gSaveBlock2Ptr->frontier.lvlMode][listId];
            if (gPyramidBagMenuState.location == PYRAMIDBAG_LOC_PARTY)
                TryCloseBagToGiveItem_battle_pyramid_bag(taskId);
            else
                OpenContextMenu_battle_pyramid_bag(taskId);
            break;
        }
    }
}

static void OpenContextMenu_battle_pyramid_bag(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    RemoveScrollArrow_battle_pyramid_bag();
    PrintSelectorArrow_battle_pyramid_bag(tListTaskId_battle_pyramid_bag, COLORID_LIGHT_GRAY_battle_pyramid_bag);
    switch (gPyramidBagMenuState.location)
    {
    default:
//  case PYRAMIDBAG_LOC_FIELD:
//  case PYRAMIDBAG_LOC_PARTY:
        gPyramidBagMenu->menuActionIds = sMenuActionIds_Field_battle_pyramid_bag;
        gPyramidBagMenu->menuActionsCount = ARRAY_COUNT(sMenuActionIds_Field_battle_pyramid_bag);
        break;
    case PYRAMIDBAG_LOC_BATTLE:
        if (ItemId_GetBattleUsage(gSpecialVar_ItemId))
        {
            gPyramidBagMenu->menuActionIds = sMenuActionIds_Battle_battle_pyramid_bag;
            gPyramidBagMenu->menuActionsCount = ARRAY_COUNT(sMenuActionIds_Battle_battle_pyramid_bag);
        }
        else
        {
            gPyramidBagMenu->menuActionIds = sMenuActionIds_BattleCannotUse_battle_pyramid_bag;
            gPyramidBagMenu->menuActionsCount = ARRAY_COUNT(sMenuActionIds_BattleCannotUse_battle_pyramid_bag);
        }
        break;
    case PYRAMIDBAG_LOC_CHOOSE_TOSS:
        gPyramidBagMenu->menuActionIds = sMenuActionIds_ChooseToss_battle_pyramid_bag;
        gPyramidBagMenu->menuActionsCount = ARRAY_COUNT(sMenuActionIds_ChooseToss_battle_pyramid_bag);
        break;
    }

    CopyItemName(gSpecialVar_ItemId, gStringVar1);
    StringExpandPlaceholders(gStringVar4, gText_Var1IsSelected);
    FillWindowPixelBuffer(WIN_INFO_battle_pyramid_bag, PIXEL_FILL(0));
    PyramidBagPrint_battle_pyramid_bag(WIN_INFO_battle_pyramid_bag, gStringVar4, 3, 0, 0, 1, 0, COLORID_DARK_GRAY_battle_pyramid_bag);
    if (gPyramidBagMenu->menuActionsCount == 1)
        PrintMenuActionText_SingleRow_battle_pyramid_bag(OpenMenuActionWindowById_battle_pyramid_bag(MENU_WIN_1x1_battle_pyramid_bag));
    else if (gPyramidBagMenu->menuActionsCount == 2)
        PrintMenuActionText_SingleRow_battle_pyramid_bag(OpenMenuActionWindowById_battle_pyramid_bag(MENU_WIN_1x2_battle_pyramid_bag));
    else
        PrintMenuActionText_MultiRow_battle_pyramid_bag(OpenMenuActionWindowById_battle_pyramid_bag(MENU_WIN_2x2_battle_pyramid_bag), 2, 2);

    if (gPyramidBagMenu->menuActionsCount == 2 * 2) // Assumes any non 2x2 menu is single-row
        gTasks[taskId].func = HandleMenuActionInput_2x2_battle_pyramid_bag;
    else
        gTasks[taskId].func = HandleMenuActionInput_SingleRow_battle_pyramid_bag;
}

static void PrintMenuActionText_SingleRow_battle_pyramid_bag(u8 windowId)
{
    PrintMenuActionTexts(windowId, FONT_NARROW, 8, 1, 0, 0x10, gPyramidBagMenu->menuActionsCount, sMenuActions_battle_pyramid_bag, gPyramidBagMenu->menuActionIds);
    InitMenuInUpperLeftCornerNormal(windowId, gPyramidBagMenu->menuActionsCount, 0);
}

static void PrintMenuActionText_MultiRow_battle_pyramid_bag(u8 windowId, u8 horizontalCount, u8 verticalCount)
{
    PrintMenuActionGrid(windowId, FONT_NARROW, 8, 1, 56, horizontalCount, verticalCount, sMenuActions_battle_pyramid_bag, gPyramidBagMenu->menuActionIds);
    InitMenuActionGrid(windowId, 56, horizontalCount, verticalCount, 0);
}

static void HandleMenuActionInput_SingleRow_battle_pyramid_bag(u8 taskId)
{
    if (MenuHelpers_ShouldWaitForLinkRecv() != TRUE)
    {
        s32 id = Menu_ProcessInputNoWrap();
        switch (id)
        {
        case MENU_NOTHING_CHOSEN:
            break;
        case MENU_B_PRESSED:
            PlaySE(SE_SELECT);
            sMenuActions_battle_pyramid_bag[ACTION_CANCEL_battle_pyramid_bag].func.void_u8(taskId);
            break;
        default:
            PlaySE(SE_SELECT);
            if (sMenuActions_battle_pyramid_bag[gPyramidBagMenu->menuActionIds[id]].func.void_u8 != NULL)
                sMenuActions_battle_pyramid_bag[gPyramidBagMenu->menuActionIds[id]].func.void_u8(taskId);
            break;
        }
    }
}

static void HandleMenuActionInput_2x2_battle_pyramid_bag(u8 taskId)
{
    if (MenuHelpers_ShouldWaitForLinkRecv() != TRUE)
    {
        s8 id = Menu_GetCursorPos();
        if (JOY_NEW(DPAD_UP))
        {
            if (id > 0 && IsValidMenuAction_battle_pyramid_bag(id - 2))
            {
                PlaySE(SE_SELECT);
                ChangeMenuGridCursorPosition(MENU_CURSOR_DELTA_NONE, MENU_CURSOR_DELTA_UP);
            }
        }
        else if (JOY_NEW(DPAD_DOWN))
        {
            if (id < gPyramidBagMenu->menuActionsCount - 2 && IsValidMenuAction_battle_pyramid_bag(id + 2))
            {
                PlaySE(SE_SELECT);
                ChangeMenuGridCursorPosition(MENU_CURSOR_DELTA_NONE, MENU_CURSOR_DELTA_DOWN);
            }
        }
        else if (JOY_NEW(DPAD_LEFT) || GetLRKeysPressed() == MENU_L_PRESSED)
        {
            if (id & 1 && IsValidMenuAction_battle_pyramid_bag(id - 1))
            {
                PlaySE(SE_SELECT);
                ChangeMenuGridCursorPosition(MENU_CURSOR_DELTA_LEFT, MENU_CURSOR_DELTA_NONE);
            }
        }
        else if (JOY_NEW(DPAD_RIGHT) || GetLRKeysPressed() == MENU_R_PRESSED)
        {
            if (!(id & 1) && IsValidMenuAction_battle_pyramid_bag(id + 1))
            {
                PlaySE(SE_SELECT);
                ChangeMenuGridCursorPosition(MENU_CURSOR_DELTA_RIGHT, MENU_CURSOR_DELTA_NONE);
            }
        }
        else if (JOY_NEW(A_BUTTON))
        {
            PlaySE(SE_SELECT);
            if (sMenuActions_battle_pyramid_bag[gPyramidBagMenu->menuActionIds[id]].func.void_u8 != NULL)
                sMenuActions_battle_pyramid_bag[gPyramidBagMenu->menuActionIds[id]].func.void_u8(taskId);
        }
        else if (JOY_NEW(B_BUTTON))
        {
            PlaySE(SE_SELECT);
            sMenuActions_battle_pyramid_bag[ACTION_CANCEL_battle_pyramid_bag].func.void_u8(taskId);
        }
    }
}

static bool8 IsValidMenuAction_battle_pyramid_bag(s8 actionTableId)
{
    if (actionTableId < 0)
        return FALSE;
    else if (actionTableId > gPyramidBagMenu->menuActionsCount)
        return FALSE;
    else if (gPyramidBagMenu->menuActionIds[actionTableId] == ACTION_DUMMY_battle_pyramid_bag)
        return FALSE;
    else
        return TRUE;
}

