{
    s16 *data = gTasks[taskId].data;

    tListPos_battle_pyramid_bag = gPyramidBagMenuState.scrollPosition + gPyramidBagMenuState.cursorPosition;
    gPyramidBagMenu->toSwapPos = tListPos_battle_pyramid_bag;
    ListMenuSetUnkIndicatorsStructField(tListTaskId_battle_pyramid_bag, 0x10, 1);
    CopyItemName(gSaveBlock2Ptr->frontier.pyramidBag.itemId[gSaveBlock2Ptr->frontier.lvlMode][tListPos_battle_pyramid_bag], gStringVar1);
    StringExpandPlaceholders(gStringVar4, gText_MoveVar1Where);
    FillWindowPixelBuffer(WIN_INFO_battle_pyramid_bag, PIXEL_FILL(0));
    PyramidBagPrint_battle_pyramid_bag(WIN_INFO_battle_pyramid_bag, gStringVar4, 3, 0, 0, 1, 0, COLORID_DARK_GRAY_battle_pyramid_bag);
    PrintSelectorArrow_battle_pyramid_bag(tListTaskId_battle_pyramid_bag, COLORID_LIGHT_GRAY_battle_pyramid_bag);
    UpdateSwapLinePos_battle_pyramid_bag(tListPos_battle_pyramid_bag);
    gTasks[taskId].func = Task_ItemSwapHandleInput_battle_pyramid_bag;
}

static void Task_ItemSwapHandleInput_battle_pyramid_bag(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    if (MenuHelpers_ShouldWaitForLinkRecv() != TRUE)
    {
        if (JOY_NEW(SELECT_BUTTON))
        {
            PlaySE(SE_SELECT);
            ListMenuGetScrollAndRow(tListTaskId_battle_pyramid_bag, &gPyramidBagMenuState.scrollPosition, &gPyramidBagMenuState.cursorPosition);
            PerformItemSwap_battle_pyramid_bag(taskId);
        }
        else
        {
            s32 id = ListMenu_ProcessInput(tListTaskId_battle_pyramid_bag);
            ListMenuGetScrollAndRow(tListTaskId_battle_pyramid_bag, &gPyramidBagMenuState.scrollPosition, &gPyramidBagMenuState.cursorPosition);
            SetSwapLineInvisibility_battle_pyramid_bag(FALSE);
            UpdateSwapLinePos_battle_pyramid_bag(gPyramidBagMenuState.cursorPosition);
            switch (id)
            {
            case LIST_NOTHING_CHOSEN:
                break;
            case LIST_CANCEL:
                PlaySE(SE_SELECT);
                if (JOY_NEW(A_BUTTON))
                    PerformItemSwap_battle_pyramid_bag(taskId);
                else
                    CancelItemSwap_battle_pyramid_bag(taskId);
                break;
            default:
                PlaySE(SE_SELECT);
                PerformItemSwap_battle_pyramid_bag(taskId);
                break;
            }
        }
    }
}

static void PerformItemSwap_battle_pyramid_bag(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    u16 *scrollOffset = &gPyramidBagMenuState.scrollPosition;
    u16 *selectedRow = &gPyramidBagMenuState.cursorPosition;
    u16 swapPos = *scrollOffset + *selectedRow;

    if (tListPos_battle_pyramid_bag == swapPos || tListPos_battle_pyramid_bag == swapPos - 1)
    {
        CancelItemSwap_battle_pyramid_bag(taskId);
    }
    else
    {
        MovePyramidBagItemSlotInList_battle_pyramid_bag(tListPos_battle_pyramid_bag, swapPos);
        gPyramidBagMenu->toSwapPos = POS_NONE_battle_pyramid_bag;
        SetSwapLineInvisibility_battle_pyramid_bag(TRUE);
        DestroyListMenuTask(tListTaskId_battle_pyramid_bag, scrollOffset, selectedRow);
        if (tListPos_battle_pyramid_bag < swapPos)
            gPyramidBagMenuState.cursorPosition--;
        SetBagItemsListTemplate_battle_pyramid_bag();
        tListTaskId_battle_pyramid_bag = ListMenuInit(&gMultiuseListMenuTemplate, *scrollOffset, *selectedRow);
        SetTaskToMainPyramidBagInputHandler_battle_pyramid_bag(taskId);
    }
}

static void CancelItemSwap_battle_pyramid_bag(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    u16 *scrollOffset = &gPyramidBagMenuState.scrollPosition;
    u16 *selectedRow = &gPyramidBagMenuState.cursorPosition;

    gPyramidBagMenu->toSwapPos = POS_NONE_battle_pyramid_bag;
    SetSwapLineInvisibility_battle_pyramid_bag(TRUE);
    DestroyListMenuTask(tListTaskId_battle_pyramid_bag, scrollOffset, selectedRow);
    if (tListPos_battle_pyramid_bag < *scrollOffset + *selectedRow)
        gPyramidBagMenuState.cursorPosition--;
    SetBagItemsListTemplate_battle_pyramid_bag();
    tListTaskId_battle_pyramid_bag = ListMenuInit(&gMultiuseListMenuTemplate, *scrollOffset, *selectedRow);
    SetTaskToMainPyramidBagInputHandler_battle_pyramid_bag(taskId);
}

void TryStoreHeldItemsInPyramidBag(void)
{
    u8 i;
    struct Pokemon *party = gPlayerParty;
    u16 *newItems = Alloc(PYRAMID_BAG_ITEMS_COUNT * sizeof(*newItems));
#if MAX_PYRAMID_BAG_ITEM_CAPACITY > 255
    u16 *newQuantities = Alloc(PYRAMID_BAG_ITEMS_COUNT * sizeof(*newQuantities));
#else
    u8 *newQuantities = Alloc(PYRAMID_BAG_ITEMS_COUNT * sizeof(*newQuantities));
#endif
    u16 heldItem;

    memcpy(newItems, gSaveBlock2Ptr->frontier.pyramidBag.itemId[gSaveBlock2Ptr->frontier.lvlMode], PYRAMID_BAG_ITEMS_COUNT * sizeof(*newItems));
    memcpy(newQuantities, gSaveBlock2Ptr->frontier.pyramidBag.quantity[gSaveBlock2Ptr->frontier.lvlMode], PYRAMID_BAG_ITEMS_COUNT * sizeof(*newQuantities));
    for (i = 0; i < FRONTIER_PARTY_SIZE; i++)
    {
        heldItem = GetMonData(&party[i], MON_DATA_HELD_ITEM);
        if (heldItem != ITEM_NONE && !AddBagItem(heldItem, 1))
        {
            // Cant store party held items in pyramid bag because bag is full
            memcpy(gSaveBlock2Ptr->frontier.pyramidBag.itemId[gSaveBlock2Ptr->frontier.lvlMode], newItems, PYRAMID_BAG_ITEMS_COUNT * sizeof(*newItems));
            memcpy(gSaveBlock2Ptr->frontier.pyramidBag.quantity[gSaveBlock2Ptr->frontier.lvlMode], newQuantities, PYRAMID_BAG_ITEMS_COUNT * sizeof(*newQuantities));
            Free(newItems);
            Free(newQuantities);
            gSpecialVar_Result = 1;
            return;
        }
    }

    heldItem = ITEM_NONE;
    for (i = 0; i < FRONTIER_PARTY_SIZE; i++)
        SetMonData(&party[i], MON_DATA_HELD_ITEM, &heldItem);
    gSpecialVar_Result = 0;
    Free(newItems);
    Free(newQuantities);
}

