static bool8 SlideInLevelUpBanner_battle_script_commands(void)
{
    if (IsDma3ManagerBusyWithBgCopy())
        return TRUE;

    if (gBattle_BG2_X == LEVEL_UP_BANNER_END_battle_script_commands)
        return FALSE;

    if (gBattle_BG2_X == LEVEL_UP_BANNER_START_battle_script_commands)
        DrawLevelUpBannerText_battle_script_commands();

    gBattle_BG2_X += 8;
    if (gBattle_BG2_X >= LEVEL_UP_BANNER_END_battle_script_commands)
        gBattle_BG2_X = LEVEL_UP_BANNER_END_battle_script_commands;

    return (gBattle_BG2_X != LEVEL_UP_BANNER_END_battle_script_commands);
}

static void DrawLevelUpBannerText_battle_script_commands(void)
{
    struct TextPrinterTemplate printerTemplate;
    u8 *txtPtr;
    u32 var;

    struct Pokemon *mon = &gPlayerParty[gBattleStruct->expGetterMonId];
    u32 monLevel = GetMonData(mon, MON_DATA_LEVEL);
    u8 monGender = GetMonGender(mon);
    GetMonNickname(mon, gStringVar4);

    printerTemplate.currentChar = gStringVar4;
    printerTemplate.windowId = B_WIN_LEVEL_UP_BANNER;
    printerTemplate.fontId = FONT_SMALL;
    printerTemplate.x = 32;
    printerTemplate.y = 0;
    printerTemplate.currentX = 32;
    printerTemplate.currentY = 0;
    printerTemplate.letterSpacing = 0;
    printerTemplate.lineSpacing = 0;
    printerTemplate.unk = 0;
    printerTemplate.fgColor = TEXT_COLOR_WHITE;
    printerTemplate.bgColor = TEXT_COLOR_TRANSPARENT;
    printerTemplate.shadowColor = TEXT_COLOR_DARK_GRAY;

    AddTextPrinter(&printerTemplate, TEXT_SKIP_DRAW, NULL);

    txtPtr = gStringVar4;
    *(txtPtr)++ = CHAR_EXTRA_SYMBOL;
    *(txtPtr)++ = CHAR_LV_2;

    var = (u32)(txtPtr);
    txtPtr = ConvertIntToDecimalStringN(txtPtr, monLevel, STR_CONV_MODE_LEFT_ALIGN, 3);
    var = (u32)(txtPtr) - var;
    txtPtr = StringFill(txtPtr, CHAR_SPACER, 4 - var);

    if (monGender != MON_GENDERLESS)
    {
        if (monGender == MON_MALE)
        {
            txtPtr = WriteColorChangeControlCode(txtPtr, 0, TEXT_DYNAMIC_COLOR_3);
            txtPtr = WriteColorChangeControlCode(txtPtr, 1, TEXT_DYNAMIC_COLOR_4);
            *(txtPtr++) = CHAR_MALE;
        }
        else
        {
            txtPtr = WriteColorChangeControlCode(txtPtr, 0, TEXT_DYNAMIC_COLOR_5);
            txtPtr = WriteColorChangeControlCode(txtPtr, 1, TEXT_DYNAMIC_COLOR_6);
            *(txtPtr++) = CHAR_FEMALE;
        }
        *(txtPtr++) = EOS;
    }

    printerTemplate.y = 10;
    printerTemplate.currentY = 10;
    AddTextPrinter(&printerTemplate, TEXT_SKIP_DRAW, NULL);

    CopyWindowToVram(B_WIN_LEVEL_UP_BANNER, COPYWIN_GFX);
}

static bool8 SlideOutLevelUpBanner_battle_script_commands(void)
{
    if (gBattle_BG2_X == LEVEL_UP_BANNER_START_battle_script_commands)
        return FALSE;

    if (gBattle_BG2_X - 16 < LEVEL_UP_BANNER_START_battle_script_commands)
        gBattle_BG2_X = LEVEL_UP_BANNER_START_battle_script_commands;
    else
        gBattle_BG2_X -= 16;

    return (gBattle_BG2_X != LEVEL_UP_BANNER_START_battle_script_commands);
}

#define sDestroy_battle_script_commands data[0]
#define sXOffset_battle_script_commands data[1]

static void PutMonIconOnLvlUpBanner_battle_script_commands(void)
{
    u8 spriteId;
    struct SpriteSheet iconSheet;
    struct SpritePalette iconPalSheet;

    struct Pokemon *mon = &gPlayerParty[gBattleStruct->expGetterMonId];
    u32 species = GetMonData(mon, MON_DATA_SPECIES);
    u32 personality = GetMonData(mon, MON_DATA_PERSONALITY);

    iconSheet.data = GetMonIconPtr(species, personality);
    iconSheet.size = 0x200;
    iconSheet.tag = TAG_LVLUP_BANNER_MON_ICON_battle_script_commands;

    iconPalSheet.data = GetValidMonIconPalettePtr(species);
    iconPalSheet.tag = TAG_LVLUP_BANNER_MON_ICON_battle_script_commands;

    LoadSpriteSheet(&iconSheet);
    LoadSpritePalette(&iconPalSheet);

    spriteId = CreateSprite(&sSpriteTemplate_MonIconOnLvlUpBanner_battle_script_commands, 256, 10, 0);
    gSprites[spriteId].sDestroy_battle_script_commands = FALSE;
    gSprites[spriteId].sXOffset_battle_script_commands = gBattle_BG2_X;
}

static void SpriteCB_MonIconOnLvlUpBanner_battle_script_commands(struct Sprite *sprite)
{
    sprite->x2 = sprite->sXOffset_battle_script_commands - gBattle_BG2_X;

    if (sprite->x2 != 0)
    {
        sprite->sDestroy_battle_script_commands = TRUE;
    }
    else if (sprite->sDestroy_battle_script_commands)
    {
        DestroySprite(sprite);
        FreeSpriteTilesByTag(TAG_LVLUP_BANNER_MON_ICON_battle_script_commands);
        FreeSpritePaletteByTag(TAG_LVLUP_BANNER_MON_ICON_battle_script_commands);
    }
}

#undef sDestroy_battle_script_commands
#undef sXOffset_battle_script_commands

