static inline void SetU8_battle_setup(void *ptr, u8 value)
{
    *(u8 *)(ptr) = value;
}

static inline void SetU16_battle_setup(void *ptr, u16 value)
{
    *(u16 *)(ptr) = value;
}

static inline void SetU32_battle_setup(void *ptr, u32 value)
{
    *(u32 *)(ptr) = value;
}

static inline void SetPtr_battle_setup(const void *ptr, const void *value)
{
    *(const void **)(ptr) = value;
}

static void TrainerBattleLoadArgs_battle_setup(const struct TrainerBattleParameter *specs, const u8 *data)
{
    while (1)
    {
        switch (specs->ptrType)
        {
        case TRAINER_PARAM_LOAD_VAL_8BIT_battle_setup:
            SetU8_battle_setup(specs->varPtr, TrainerBattleLoadArg8_battle_setup(data));
            data += 1;
            break;
        case TRAINER_PARAM_LOAD_VAL_16BIT_battle_setup:
            SetU16_battle_setup(specs->varPtr, TrainerBattleLoadArg16_battle_setup(data));
            data += 2;
            break;
        case TRAINER_PARAM_LOAD_VAL_32BIT_battle_setup:
            SetU32_battle_setup(specs->varPtr, TrainerBattleLoadArg32_battle_setup(data));
            data += 4;
            break;
        case TRAINER_PARAM_CLEAR_VAL_8BIT_battle_setup:
            SetU8_battle_setup(specs->varPtr, 0);
            break;
        case TRAINER_PARAM_CLEAR_VAL_16BIT_battle_setup:
            SetU16_battle_setup(specs->varPtr, 0);
            break;
        case TRAINER_PARAM_CLEAR_VAL_32BIT_battle_setup:
            SetU32_battle_setup(specs->varPtr, 0);
            break;
        case TRAINER_PARAM_LOAD_SCRIPT_RET_ADDR_battle_setup:
            SetPtr_battle_setup(specs->varPtr, data);
            return;
        }
        specs++;
    }
}

void SetMapVarsToTrainer(void)
{
    if (sTrainerObjectEventLocalId_battle_setup != 0)
    {
        gSpecialVar_LastTalked = sTrainerObjectEventLocalId_battle_setup;
        gSelectedObjectEvent = GetObjectEventIdByLocalIdAndMap(sTrainerObjectEventLocalId_battle_setup, gSaveBlock1Ptr->location.mapNum, gSaveBlock1Ptr->location.mapGroup);
    }
}

const u8 *BattleSetup_ConfigureTrainerBattle(const u8 *data)
{
    if (TrainerBattleLoadArg8_battle_setup(data) != TRAINER_BATTLE_SET_TRAINER_B)
        InitTrainerBattleVariables_battle_setup();
    sTrainerBattleMode_battle_setup = TrainerBattleLoadArg8_battle_setup(data);

    switch (sTrainerBattleMode_battle_setup)
    {
    case TRAINER_BATTLE_SINGLE_NO_INTRO_TEXT:
        TrainerBattleLoadArgs_battle_setup(sOrdinaryNoIntroBattleParams_battle_setup, data);
        return EventScript_DoNoIntroTrainerBattle;
    case TRAINER_BATTLE_DOUBLE:
        TrainerBattleLoadArgs_battle_setup(sDoubleBattleParams_battle_setup, data);
        SetMapVarsToTrainer();
        return EventScript_TryDoDoubleTrainerBattle;
    case TRAINER_BATTLE_CONTINUE_SCRIPT:
        if (gApproachingTrainerId == 0)
        {
            TrainerBattleLoadArgs_battle_setup(sContinueScriptBattleParams_battle_setup, data);
            SetMapVarsToTrainer();
        }
        else
        {
            TrainerBattleLoadArgs_battle_setup(sTrainerBContinueScriptBattleParams_battle_setup, data);
        }
        return EventScript_TryDoNormalTrainerBattle;
    case TRAINER_BATTLE_CONTINUE_SCRIPT_NO_MUSIC:
        TrainerBattleLoadArgs_battle_setup(sContinueScriptBattleParams_battle_setup, data);
        SetMapVarsToTrainer();
        return EventScript_TryDoNormalTrainerBattle;
    case TRAINER_BATTLE_CONTINUE_SCRIPT_DOUBLE:
    case TRAINER_BATTLE_CONTINUE_SCRIPT_DOUBLE_NO_MUSIC:
        TrainerBattleLoadArgs_battle_setup(sContinueScriptDoubleBattleParams_battle_setup, data);
        SetMapVarsToTrainer();
        return EventScript_TryDoDoubleTrainerBattle;
#if FREE_MATCH_CALL == FALSE
    case TRAINER_BATTLE_REMATCH_DOUBLE:
        TrainerBattleLoadArgs_battle_setup(sDoubleBattleParams_battle_setup, data);
        SetMapVarsToTrainer();
        gTrainerBattleOpponent_A = GetRematchTrainerId_battle_setup(gTrainerBattleOpponent_A);
        return EventScript_TryDoDoubleRematchBattle;
    case TRAINER_BATTLE_REMATCH:
        TrainerBattleLoadArgs_battle_setup(sOrdinaryBattleParams_battle_setup, data);
        SetMapVarsToTrainer();
        gTrainerBattleOpponent_A = GetRematchTrainerId_battle_setup(gTrainerBattleOpponent_A);
        return EventScript_TryDoRematchBattle;
#endif //FREE_MATCH_CALL
    case TRAINER_BATTLE_PYRAMID:
        if (gApproachingTrainerId == 0)
        {
            TrainerBattleLoadArgs_battle_setup(sOrdinaryBattleParams_battle_setup, data);
            SetMapVarsToTrainer();
            gTrainerBattleOpponent_A = LocalIdToPyramidTrainerId(gSpecialVar_LastTalked);
        }
        else
        {
            TrainerBattleLoadArgs_battle_setup(sTrainerBOrdinaryBattleParams_battle_setup, data);
            gTrainerBattleOpponent_B = LocalIdToPyramidTrainerId(gSpecialVar_LastTalked);
        }
        return EventScript_TryDoNormalTrainerBattle;
    case TRAINER_BATTLE_SET_TRAINER_A:
        TrainerBattleLoadArgs_battle_setup(sOrdinaryBattleParams_battle_setup, data);
        return sTrainerBattleEndScript_battle_setup;
    case TRAINER_BATTLE_SET_TRAINER_B:
        TrainerBattleLoadArgs_battle_setup(sTrainerBOrdinaryBattleParams_battle_setup, data);
        return sTrainerBattleEndScript_battle_setup;
    case TRAINER_BATTLE_HILL:
        if (gApproachingTrainerId == 0)
        {
            TrainerBattleLoadArgs_battle_setup(sOrdinaryBattleParams_battle_setup, data);
            SetMapVarsToTrainer();
            gTrainerBattleOpponent_A = LocalIdToHillTrainerId(gSpecialVar_LastTalked);
        }
        else
        {
            TrainerBattleLoadArgs_battle_setup(sTrainerBOrdinaryBattleParams_battle_setup, data);
            gTrainerBattleOpponent_B = LocalIdToHillTrainerId(gSpecialVar_LastTalked);
        }
        return EventScript_TryDoNormalTrainerBattle;
    case TRAINER_BATTLE_TWO_TRAINERS_NO_INTRO:
        gNoOfApproachingTrainers = 2; // set TWO_OPPONENTS gBattleTypeFlags
        gApproachingTrainerId = 1; // prevent trainer approach
        TrainerBattleLoadArgs_battle_setup(sTrainerTwoTrainerBattleParams_battle_setup, data);
        return EventScript_DoNoIntroTrainerBattle;
    default:
        if (gApproachingTrainerId == 0)
        {
            TrainerBattleLoadArgs_battle_setup(sOrdinaryBattleParams_battle_setup, data);
            SetMapVarsToTrainer();
        }
        else
        {
            TrainerBattleLoadArgs_battle_setup(sTrainerBOrdinaryBattleParams_battle_setup, data);
        }
        return EventScript_TryDoNormalTrainerBattle;
    }
}

