static void InitPatternWeaveTransition_battle_transition(struct Task *task)
{
    s32 i;

    InitTransitionData_battle_transition();
    ScanlineEffect_Clear();

    task->tBlendTarget1_battle_transition = 16;
    task->tBlendTarget2_battle_transition = 0;
    task->tSinIndex_battle_transition = 0;
    task->tAmplitude_battle_transition = 0x4000;
    sTransitionData_battle_transition->WININ = WININ_WIN0_ALL;
    sTransitionData_battle_transition->WINOUT = 0;
    sTransitionData_battle_transition->WIN0H = DISPLAY_WIDTH;
    sTransitionData_battle_transition->WIN0V = DISPLAY_HEIGHT;
    sTransitionData_battle_transition->BLDCNT = BLDCNT_TGT1_BG0 | BLDCNT_EFFECT_BLEND | BLDCNT_TGT2_ALL;
    sTransitionData_battle_transition->BLDALPHA = BLDALPHA_BLEND(task->tBlendTarget2_battle_transition, task->tBlendTarget1_battle_transition);

    for (i = 0; i < DISPLAY_HEIGHT; i++)
        gScanlineEffectRegBuffers[1][i] = DISPLAY_WIDTH;

    SetVBlankCallback(VBlankCB_PatternWeave_battle_transition);
}

static bool8 Aqua_Init_battle_transition(struct Task *task)
{
    u16 *tilemap, *tileset;

    task->tEndDelay_battle_transition = 60;
    InitPatternWeaveTransition_battle_transition(task);
    GetBg0TilesDst(&tilemap, &tileset);
    CpuFill16(0, tilemap, BG_SCREEN_SIZE);
    LZ77UnCompVram(sTeamAqua_Tileset_battle_transition, tileset);
    LoadPalette(sEvilTeam_Palette_battle_transition, BG_PLTT_ID(15), sizeof(sEvilTeam_Palette_battle_transition));

    task->tState_battle_transition++;
    return FALSE;
}

