static bool8 BigPokeball_SetGfx_battle_transition(struct Task *task)
{
    s16 i, j;
    u16 *tilemap, *tileset;
    const u16 *bigPokeballMap;

    GetBg0TilesDst(&tilemap, &tileset);
    bigPokeballMap = sBigPokeball_Tilemap_battle_transition;
    for (i = 0; i < 20; i++)
    {
        for (j = 0; j < 30; j++, bigPokeballMap++)
            SET_TILE_battle_transition(tilemap, i, j, *bigPokeballMap);
    }

    SetSinWave_battle_transition((s16*)gScanlineEffectRegBuffers[0], 0, task->tSinIndex_battle_transition, 132, task->tAmplitude_battle_transition, DISPLAY_HEIGHT);

    task->tState_battle_transition++;
    return TRUE;
}

