    SetSinWave_battle_transition((s16*)gScanlineEffectRegBuffers[0], 0, task->tSinIndex_battle_transition, 132, task->tAmplitude_battle_transition, DISPLAY_HEIGHT);

    task->tState_battle_transition++;
