// The PatternWeave_ functions are used by several different transitions.
// They create an effect where a pattern/image (such as the Magma emblem) is
// formed by a shimmering weave effect.
static bool8 PatternWeave_Blend1_battle_transition(struct Task *task)
{
    sTransitionData_battle_transition->VBlank_DMA = FALSE;
    if (task->tBlendDelay_battle_transition == 0 || --task->tBlendDelay_battle_transition == 0)
    {
        task->tBlendTarget2_battle_transition++;
        task->tBlendDelay_battle_transition = 2;
    }
    sTransitionData_battle_transition->BLDALPHA = BLDALPHA_BLEND(task->tBlendTarget2_battle_transition, task->tBlendTarget1_battle_transition);
    if (task->tBlendTarget2_battle_transition > 15)
        task->tState_battle_transition++;
    task->tSinIndex_battle_transition += 8;
    task->tAmplitude_battle_transition -= 256;

    SetSinWave_battle_transition((s16*)gScanlineEffectRegBuffers[0], 0, task->tSinIndex_battle_transition, 132, task->tAmplitude_battle_transition >> 8, DISPLAY_HEIGHT);

    sTransitionData_battle_transition->VBlank_DMA++;
    return FALSE;
}

static bool8 PatternWeave_Blend2_battle_transition(struct Task *task)
{
    sTransitionData_battle_transition->VBlank_DMA = FALSE;
    if (task->tBlendDelay_battle_transition == 0 || --task->tBlendDelay_battle_transition == 0)
    {
        task->tBlendTarget1_battle_transition--;
        task->tBlendDelay_battle_transition = 2;
    }
    sTransitionData_battle_transition->BLDALPHA = BLDALPHA_BLEND(task->tBlendTarget2_battle_transition, task->tBlendTarget1_battle_transition);
    if (task->tBlendTarget1_battle_transition == 0)
        task->tState_battle_transition++;
    task->tSinIndex_battle_transition += 8;
    task->tAmplitude_battle_transition -= 256;

    SetSinWave_battle_transition((s16*)gScanlineEffectRegBuffers[0], 0, task->tSinIndex_battle_transition, 132, task->tAmplitude_battle_transition >> 8, DISPLAY_HEIGHT);

    sTransitionData_battle_transition->VBlank_DMA++;
    return FALSE;
}

static bool8 PatternWeave_FinishAppear_battle_transition(struct Task *task)
{
    sTransitionData_battle_transition->VBlank_DMA = FALSE;
    task->tSinIndex_battle_transition += 8;
    task->tAmplitude_battle_transition -= 256;

    SetSinWave_battle_transition((s16*)gScanlineEffectRegBuffers[0], 0, task->tSinIndex_battle_transition, 132, task->tAmplitude_battle_transition >> 8, DISPLAY_HEIGHT);

    if (task->tAmplitude_battle_transition <= 0)
    {
        task->tState_battle_transition++;
        task->tRadius_battle_transition = DISPLAY_HEIGHT;
        task->tRadiusDelta_battle_transition = 1 << 8;
        task->tVBlankSet_battle_transition = FALSE;
    }

    sTransitionData_battle_transition->VBlank_DMA++;
    return FALSE;
}

static bool8 FramesCountdown_battle_transition(struct Task *task)
{
    if (--task->tEndDelay_battle_transition == 0)
        task->tState_battle_transition++;
    return FALSE;
}

static bool8 WeatherTrio_BgFadeBlack_battle_transition(struct Task *task)
{
    BeginNormalPaletteFade(PALETTES_BG, 1, 0, 16, RGB_BLACK);
    task->tState_battle_transition++;
    return FALSE;
}

static bool8 WeatherTrio_WaitFade_battle_transition(struct Task *task)
{
    if (!gPaletteFade.active)
        task->tState_battle_transition++;
    return FALSE;
}

// Do a shrinking circular mask to go to a black screen after the pattern appears.
static bool8 PatternWeave_CircularMask_battle_transition(struct Task *task)
{
    sTransitionData_battle_transition->VBlank_DMA = FALSE;
    if (task->tRadiusDelta_battle_transition < (4 << 8))
        task->tRadiusDelta_battle_transition += 128; // 256 is 1 unit of speed. Speed up every other frame (128 / 256)
    if (task->tRadius_battle_transition != 0)
    {
        task->tRadius_battle_transition -= task->tRadiusDelta_battle_transition >> 8;
        if (task->tRadius_battle_transition < 0)
            task->tRadius_battle_transition = 0;
    }
    SetCircularMask_battle_transition(gScanlineEffectRegBuffers[0], DISPLAY_WIDTH / 2, DISPLAY_HEIGHT / 2, task->tRadius_battle_transition);
    if (task->tRadius_battle_transition == 0)
    {
        SetVBlankCallback(NULL);
        DmaStop(0);
        FadeScreenBlack_battle_transition();
        DestroyTask(FindTaskIdByFunc(task->func));
    }
    else
    {
        if (!task->tVBlankSet_battle_transition)
        {
            task->tVBlankSet_battle_transition++;
            SetVBlankCallback(VBlankCB_CircularMask_battle_transition);
        }
        sTransitionData_battle_transition->VBlank_DMA++;
    }
    return FALSE;
}

static void VBlankCB_SetWinAndBlend_battle_transition(void)
{
    DmaStop(0);
    VBlankCB_BattleTransition_battle_transition();
    if (sTransitionData_battle_transition->VBlank_DMA)
        DmaCopy16(3, gScanlineEffectRegBuffers[0], gScanlineEffectRegBuffers[1], DISPLAY_HEIGHT * 2);
    REG_WININ = sTransitionData_battle_transition->WININ;
    REG_WINOUT = sTransitionData_battle_transition->WINOUT;
    REG_WIN0V = sTransitionData_battle_transition->WIN0V;
    REG_BLDCNT = sTransitionData_battle_transition->BLDCNT;
    REG_BLDALPHA = sTransitionData_battle_transition->BLDALPHA;
}

static void VBlankCB_PatternWeave_battle_transition(void)
{
    VBlankCB_SetWinAndBlend_battle_transition();
    DmaSet(0, gScanlineEffectRegBuffers[1], &REG_BG0HOFS, B_TRANS_DMA_FLAGS_battle_transition);
}

static void VBlankCB_CircularMask_battle_transition(void)
{
    VBlankCB_SetWinAndBlend_battle_transition();
    DmaSet(0, gScanlineEffectRegBuffers[1], &REG_WIN0H, B_TRANS_DMA_FLAGS_battle_transition);
}

