static void Task_RectangularSpiral_battle_transition(u8 taskId)
{
    while (sRectangularSpiral_Funcs_battle_transition[gTasks[taskId].tState_battle_transition](&gTasks[taskId]));
}

static bool8 RectangularSpiral_Init_battle_transition(struct Task *task)
{
    u16 *tilemap, *tileset;

    GetBg0TilesDst(&tilemap, &tileset);
    CpuCopy16(sShrinkingBoxTileset_battle_transition, tileset, 0x20);
    CpuCopy16(&sShrinkingBoxTileset_battle_transition[0x70], &tileset[0x20], 0x20);
    CpuFill16(0xF0 << 8, tilemap, BG_SCREEN_SIZE);
    LoadPalette(sFieldEffectPal_Pokeball_battle_transition, BG_PLTT_ID(15), sizeof(sFieldEffectPal_Pokeball_battle_transition));

    task->data[3] = 1;
    task->tState_battle_transition++;

    // Line starting in top left
    sRectangularSpiralLines_battle_transition[0].state = SPIRAL_INWARD_START_battle_transition;
    sRectangularSpiralLines_battle_transition[0].position = -1;
    sRectangularSpiralLines_battle_transition[0].moveIdx = 1;
    sRectangularSpiralLines_battle_transition[0].reboundPosition = 308;
    sRectangularSpiralLines_battle_transition[0].outward = FALSE;

    // Line starting in bottom right
    sRectangularSpiralLines_battle_transition[1].state = SPIRAL_INWARD_START_battle_transition;
    sRectangularSpiralLines_battle_transition[1].position = -1;
    sRectangularSpiralLines_battle_transition[1].moveIdx = 1;
    sRectangularSpiralLines_battle_transition[1].reboundPosition = 308;
    sRectangularSpiralLines_battle_transition[1].outward = FALSE;

    // Line starting in top right
    sRectangularSpiralLines_battle_transition[2].state = SPIRAL_INWARD_START_battle_transition;
    sRectangularSpiralLines_battle_transition[2].position = -3;
    sRectangularSpiralLines_battle_transition[2].moveIdx = 1;
    sRectangularSpiralLines_battle_transition[2].reboundPosition = 307;
    sRectangularSpiralLines_battle_transition[2].outward = FALSE;

    // Line starting in bottom left
    sRectangularSpiralLines_battle_transition[3].state = SPIRAL_INWARD_START_battle_transition;
    sRectangularSpiralLines_battle_transition[3].position = -3;
    sRectangularSpiralLines_battle_transition[3].moveIdx = 1;
    sRectangularSpiralLines_battle_transition[3].reboundPosition = 307;
    sRectangularSpiralLines_battle_transition[3].outward = FALSE;

    return FALSE;
}

static bool8 RectangularSpiral_Main_battle_transition(struct Task *task)
{
    u16 *tilemap, *tileset;
    u8 i;
    u16 j;
    bool32 done = TRUE;

    GetBg0TilesDst(&tilemap, &tileset);

    // Draw 2 tiles at a time for each spiral line
    for (i = 0; i < 2; i++)
    {
        for (j = 0; j < ARRAY_COUNT(sRectangularSpiralLines_battle_transition); j++)
        {
            s16 position = 0;
            s16 x = 0, y = 0;

            if (UpdateRectangularSpiralLine_battle_transition(sRectangularSpiral_MoveDataTables[j / 2], &sRectangularSpiralLines_battle_transition[j]))
            {
                // The line moved to a new position, draw the tile.
                done = FALSE;
                position = sRectangularSpiralLines_battle_transition[j].position;

                // Invert position for the two lines that start at the bottom.
                if ((j % 2) == 1)
                    position = 637 - position;

                x = position % 32;
                y = position / 32;

                SET_TILE_battle_transition(tilemap, y, x, 2);
            }
        }
    }

    if (done == TRUE)
        task->tState_battle_transition++;
    return FALSE;
}

static bool8 RectangularSpiral_End_battle_transition(struct Task *task)
{
    DmaStop(0);
    FadeScreenBlack_battle_transition();
    DestroyTask(FindTaskIdByFunc(task->func));
    return FALSE;
}

// Returns TRUE if a tile should be drawn, FALSE otherwise
static bool16 UpdateRectangularSpiralLine_battle_transition(const s16 * const *moveDataTable, struct RectangularSpiralLine *line)
{
    const s16 *moveData = moveDataTable[line->state];

    // Has spiral finished?
    // Note that most move data arrays endsin SPIRAL_END_battle_transition but it is
    // only ever reached on the final array of spiraling outward.
    if (moveData[line->moveIdx] == SPIRAL_END_battle_transition)
        return FALSE;

    // Presumably saving data for debug.
    sDebug_RectangularSpiralData_battle_transition = moveData[0];
    sDebug_RectangularSpiralData_battle_transition = moveData[1];
    sDebug_RectangularSpiralData_battle_transition = moveData[2];
    sDebug_RectangularSpiralData_battle_transition = moveData[3];

    // Note that for the two lines originating at the bottom the
    // position is inverted, so the directions are flipped.
    // i.e. position += 1 is right for the top lines and left
    // for their inverted partners on the bottom.
    switch (moveData[0])
    {
    case MOVE_RIGHT_battle_transition:
        line->position += 1;
        break;
    case MOVE_LEFT_battle_transition:
        line->position -= 1;
        break;
    case MOVE_UP_battle_transition:
        line->position -= 32;
        break;
    case MOVE_DOWN_battle_transition:
        line->position += 32;
        break;
    }

    // Below check is never true.
    // SPIRAL_END_battle_transition was already checked, and position is never >= 640
    if (line->position >= 640 || moveData[line->moveIdx] == SPIRAL_END_battle_transition)
        return FALSE;

    if (!line->outward && moveData[line->moveIdx] == SPIRAL_REBOUND_battle_transition)
    {
        // Line has reached the final point of spiraling inward.
        // Time to flip and start spiraling outward.
        line->outward = TRUE;
        line->moveIdx = 1;
        line->position = line->reboundPosition;
        line->state = SPIRAL_OUTWARD_START_battle_transition;
    }

    // Reached move target, advance to next movement.
    if (line->position == moveData[line->moveIdx])
    {
        line->state++;
        if (line->outward == TRUE)
        {
            if (line->state > SPIRAL_OUTWARD_END_battle_transition)
            {
                // Still spiraling outward, loop back to the first state
                // but use the second set of move targets.
                // For example, the 28 in sRectangularSpiral_Major_OutwardUp_battle_transition
                line->moveIdx++;
                line->state = SPIRAL_OUTWARD_START_battle_transition;
            }
        }
        else
        {
            if (line->state > SPIRAL_INWARD_END_battle_transition)
            {
                // Still spiraling inward, loop back to the first state
                // but use the second set of move targets.
                // For example, the 275 in sRectangularSpiral_Major_InwardRight_battle_transition
                line->moveIdx++;
                line->state = SPIRAL_INWARD_START_battle_transition;
            }
        }
    }
    return TRUE;
}

