#define tTimer_battle_transition     data[1]
#define tGrowSpeed_battle_transition data[2] // Shared from B_TRANSITION_BLACKHOLE
#define tFlag_battle_transition      data[7] // Shared from B_TRANSITION_BLACKHOLE

static void Task_Rayquaza_battle_transition(u8 taskId)
{
    while (sRayquaza_Funcs_battle_transition[gTasks[taskId].tState_battle_transition](&gTasks[taskId]));
}

static bool8 Rayquaza_Init_battle_transition(struct Task *task)
{
    u16 *tilemap, *tileset;
    u16 i;

    InitTransitionData_battle_transition();
    ScanlineEffect_Clear();

    SetGpuReg(REG_OFFSET_BG0CNT, BGCNT_CHARBASE(2) | BGCNT_SCREENBASE(26) | BGCNT_TXT256x512);
    GetBg0TilesDst(&tilemap, &tileset);
    CpuFill16(0, tilemap, BG_SCREEN_SIZE);
    CpuCopy16(sRayquaza_Tileset_battle_transition, tileset, 0x2000);

    sTransitionData_battle_transition->counter = 0;
    task->tState_battle_transition++;
    LoadPalette(&sRayquaza_Palette_battle_transition[80], BG_PLTT_ID(15), PLTT_SIZE_4BPP);

    for (i = 0; i < DISPLAY_HEIGHT; i++)
    {
        gScanlineEffectRegBuffers[0][i] = 0;
        gScanlineEffectRegBuffers[1][i] = 0x100;
    }

    SetVBlankCallback(VBlankCB_Rayquaza_battle_transition);
    return FALSE;
}

static bool8 Rayquaza_SetGfx_battle_transition(struct Task *task)
{
    u16 *tilemap, *tileset;

    GetBg0TilesDst(&tilemap, &tileset);
    CpuCopy16(sRayquaza_Tilemap_battle_transition, tilemap, sizeof(sRayquaza_Tilemap_battle_transition));
    task->tState_battle_transition++;
    return FALSE;
}

static bool8 Rayquaza_PaletteFlash_battle_transition(struct Task *task)
{
    if ((task->tTimer_battle_transition % 4) == 0)
    {
        u16 value = task->tTimer_battle_transition / 4;
        const u16 *palPtr = &sRayquaza_Palette_battle_transition[(value + 5) * 16];
        LoadPalette(palPtr, BG_PLTT_ID(15), PLTT_SIZE_4BPP);
    }
    if (++task->tTimer_battle_transition > 40)
    {
        task->tState_battle_transition++;
        task->tTimer_battle_transition = 0;
    }

    return FALSE;
}

static bool8 Rayquaza_FadeToBlack_battle_transition(struct Task *task)
{
    if (++task->tTimer_battle_transition > 20)
    {
        task->tState_battle_transition++;
        task->tTimer_battle_transition = 0;
        BeginNormalPaletteFade(PALETTES_OBJECTS | (1 << 15), 2, 0, 16, RGB_BLACK);
    }

    return FALSE;
}

static bool8 Rayquaza_WaitFade_battle_transition(struct Task *task)
{
    if (!gPaletteFade.active)
    {
        sTransitionData_battle_transition->counter = 1;
        task->tState_battle_transition++;
    }
    return FALSE;
}

static bool8 Rayquaza_SetBlack_battle_transition(struct Task *task)
{
    BlendPalettes(PALETTES_BG & ~(1 << 15), 8, RGB_BLACK);
    BlendPalettes(PALETTES_OBJECTS | (1 << 15), 0, RGB_BLACK);

    task->tState_battle_transition++;
    return FALSE;
}

static bool8 Rayquaza_TriRing_battle_transition(struct Task *task)
{
    if ((task->tTimer_battle_transition % 3) == 0)
    {
        u16 value = task->tTimer_battle_transition / 3;
        const u16 *palPtr = &sRayquaza_Palette_battle_transition[(value + 0) * 16];
        LoadPalette(palPtr, BG_PLTT_ID(15), PLTT_SIZE_4BPP);
    }
    if (++task->tTimer_battle_transition >= 40)
    {
        u16 i;

        sTransitionData_battle_transition->WININ = 0;
        sTransitionData_battle_transition->WINOUT = WINOUT_WIN01_ALL;
        sTransitionData_battle_transition->WIN0H = DISPLAY_WIDTH;
        sTransitionData_battle_transition->WIN0V = DISPLAY_HEIGHT;

        for (i = 0; i < DISPLAY_HEIGHT; i++)
            gScanlineEffectRegBuffers[1][i] = 0;

        SetVBlankCallback(VBlankCB_CircularMask_battle_transition);
        task->tState_battle_transition++;
        task->tGrowSpeed_battle_transition = 1 << 8;
        task->tFlag_battle_transition = FALSE;
        ClearGpuRegBits(REG_OFFSET_DISPCNT, DISPCNT_BG0_ON);
    }

    return FALSE;
}

static void VBlankCB_Rayquaza_battle_transition(void)
{
    void *dmaSrc;

    DmaStop(0);
    VBlankCB_BattleTransition_battle_transition();

    if (sTransitionData_battle_transition->counter == 0)
        dmaSrc = gScanlineEffectRegBuffers[0];
    else if (sTransitionData_battle_transition->counter == 1)
        dmaSrc = gScanlineEffectRegBuffers[1];
    else
        dmaSrc = gScanlineEffectRegBuffers[0];

    DmaSet(0, dmaSrc, &REG_BG0VOFS, B_TRANS_DMA_FLAGS_battle_transition);
}

#undef tTimer_battle_transition
#undef tGrowSpeed_battle_transition
#undef tFlag_battle_transition

//------------------------------
// B_TRANSITION_WHITE_BARS_FADE
//------------------------------

#define sFade_battle_transition            data[0]
#define sFinished_battle_transition        data[1]
#define sDestroyAttempts_battle_transition data[2]
#define sDelay_battle_transition           data[5]
#define sIsMainSprite_battle_transition    data[6]

#define FADE_TARGET_battle_transition (16 << 8)

static void Task_WhiteBarsFade_battle_transition(u8 taskId)
{
    while (sWhiteBarsFade_Funcs_battle_transition[gTasks[taskId].tState_battle_transition](&gTasks[taskId]));
}

static bool8 WhiteBarsFade_Init_battle_transition(struct Task *task)
{
    u16 i;

    InitTransitionData_battle_transition();
    ScanlineEffect_Clear();

    sTransitionData_battle_transition->BLDCNT = BLDCNT_TGT1_ALL | BLDCNT_EFFECT_LIGHTEN;
    sTransitionData_battle_transition->BLDY = 0;
    sTransitionData_battle_transition->WININ = WININ_WIN0_BG1 | WININ_WIN0_BG2 | WININ_WIN0_BG3 | WININ_WIN0_OBJ;
    sTransitionData_battle_transition->WINOUT = WINOUT_WIN01_ALL;
    sTransitionData_battle_transition->WIN0V = DISPLAY_HEIGHT;

    for (i = 0; i < DISPLAY_HEIGHT; i++)
    {
        gScanlineEffectRegBuffers[1][i] = 0;
        gScanlineEffectRegBuffers[1][i + DISPLAY_HEIGHT] = DISPLAY_WIDTH;
    }

    EnableInterrupts(INTR_FLAG_HBLANK);
    SetHBlankCallback(HBlankCB_WhiteBarsFade_battle_transition);
    SetVBlankCallback(VBlankCB_WhiteBarsFade_battle_transition);

    task->tState_battle_transition++;
    return FALSE;
}

static bool8 WhiteBarsFade_StartBars_battle_transition(struct Task *task)
{
    s16 i, posY;
    s16 delays[ARRAY_COUNT(sWhiteBarsFade_StartDelays_battle_transition)];
    struct Sprite *sprite;
    memcpy(delays, sWhiteBarsFade_StartDelays_battle_transition, sizeof(sWhiteBarsFade_StartDelays_battle_transition));

    for (i = 0, posY = 0; i < NUM_WHITE_BARS_battle_transition; i++, posY += DISPLAY_HEIGHT / NUM_WHITE_BARS_battle_transition)
    {
        sprite = &gSprites[CreateInvisibleSprite(SpriteCB_WhiteBarFade_battle_transition)];
        sprite->x = DISPLAY_WIDTH;
        sprite->y = posY;
        sprite->sDelay_battle_transition = delays[i];
    }

    // Set on one sprite only. This one will enable the DMA
    // copy in VBlank and wait for the others to destroy.
    sprite->sIsMainSprite_battle_transition++;

    task->tState_battle_transition++;
    return FALSE;
}

static bool8 WhiteBarsFade_WaitBars_battle_transition(struct Task *task)
{
    sTransitionData_battle_transition->VBlank_DMA = 0;
    if (sTransitionData_battle_transition->counter >= NUM_WHITE_BARS_battle_transition)
    {
        BlendPalettes(PALETTES_ALL, 16, RGB_WHITE);
        task->tState_battle_transition++;
    }
    return FALSE;
}

static bool8 WhiteBarsFade_BlendToBlack_battle_transition(struct Task *task)
{
    sTransitionData_battle_transition->VBlank_DMA = 0;

    DmaStop(0);
    SetVBlankCallback(0);
    SetHBlankCallback(0);

    sTransitionData_battle_transition->WIN0H = DISPLAY_WIDTH;
    sTransitionData_battle_transition->BLDY = 0;
    sTransitionData_battle_transition->BLDCNT = 0xFF;
    sTransitionData_battle_transition->WININ = WININ_WIN0_ALL;

    SetVBlankCallback(VBlankCB_WhiteBarsFade_Blend_battle_transition);

    task->tState_battle_transition++;
    return FALSE;
}

static bool8 WhiteBarsFade_End_battle_transition(struct Task *task)
{
   if (++sTransitionData_battle_transition->BLDY > 16)
   {
       FadeScreenBlack_battle_transition();
       DestroyTask(FindTaskIdByFunc(Task_WhiteBarsFade_battle_transition));
   }
   return FALSE;
}

static void VBlankCB_WhiteBarsFade_battle_transition(void)
{
    DmaStop(0);
    VBlankCB_BattleTransition_battle_transition();
    REG_BLDCNT = sTransitionData_battle_transition->BLDCNT;
    REG_WININ = sTransitionData_battle_transition->WININ;
    REG_WINOUT = sTransitionData_battle_transition->WINOUT;
    REG_WIN0V = sTransitionData_battle_transition->WIN0V;
    if (sTransitionData_battle_transition->VBlank_DMA)
        DmaCopy16(3, gScanlineEffectRegBuffers[0], gScanlineEffectRegBuffers[1], DISPLAY_HEIGHT * 4);
    DmaSet(0, &gScanlineEffectRegBuffers[1][DISPLAY_HEIGHT], &REG_WIN0H, B_TRANS_DMA_FLAGS_battle_transition);
}

static void VBlankCB_WhiteBarsFade_Blend_battle_transition(void)
{
    VBlankCB_BattleTransition_battle_transition();
    REG_BLDY = sTransitionData_battle_transition->BLDY;
    REG_BLDCNT = sTransitionData_battle_transition->BLDCNT;
    REG_WININ = sTransitionData_battle_transition->WININ;
    REG_WINOUT = sTransitionData_battle_transition->WINOUT;
    REG_WIN0H = sTransitionData_battle_transition->WIN0H;
    REG_WIN0V = sTransitionData_battle_transition->WIN0V;
}

static void HBlankCB_WhiteBarsFade_battle_transition(void)
{
    REG_BLDY = gScanlineEffectRegBuffers[1][REG_VCOUNT];
}

static void SpriteCB_WhiteBarFade_battle_transition(struct Sprite *sprite)
{
    if (sprite->sDelay_battle_transition)
    {
        sprite->sDelay_battle_transition--;
        if (sprite->sIsMainSprite_battle_transition)
            sTransitionData_battle_transition->VBlank_DMA = 1;
    }
    else
    {
        u16 i;
        u16 *ptr1 = &gScanlineEffectRegBuffers[0][sprite->y];
        u16 *ptr2 = &gScanlineEffectRegBuffers[0][sprite->y + DISPLAY_HEIGHT];
        for (i = 0; i < DISPLAY_HEIGHT / NUM_WHITE_BARS_battle_transition; i++)
        {
            ptr1[i] = sprite->sFade_battle_transition >> 8;
            ptr2[i] = (u8)sprite->x;
        }
        if (sprite->x == 0 && sprite->sFade_battle_transition == FADE_TARGET_battle_transition)
            sprite->sFinished_battle_transition = TRUE;

        sprite->x -= 16;
        sprite->sFade_battle_transition += FADE_TARGET_battle_transition / 32;

        if (sprite->x < 0)
            sprite->x = 0;
        if (sprite->sFade_battle_transition > FADE_TARGET_battle_transition)
            sprite->sFade_battle_transition = FADE_TARGET_battle_transition;

        if (sprite->sIsMainSprite_battle_transition)
            sTransitionData_battle_transition->VBlank_DMA = 1;

        if (sprite->sFinished_battle_transition)
        {
            // If not the main sprite, destroy self. Otherwise, wait until the
            // others have destroyed themselves, or until enough time has elapsed.
            if (!sprite->sIsMainSprite_battle_transition || (sTransitionData_battle_transition->counter >= NUM_WHITE_BARS_battle_transition - 1 && sprite->sDestroyAttempts_battle_transition++ > 7))
            {
                sTransitionData_battle_transition->counter++;
                DestroySprite(sprite);
            }
        }
    }
}

#undef sFade_battle_transition
#undef sFinished_battle_transition
#undef sDestroyAttempts_battle_transition
#undef sDelay_battle_transition
#undef sIsMainSprite_battle_transition

//---------------------------
// B_TRANSITION_GRID_SQUARES
//---------------------------

#define tDelay_battle_transition       data[1]
#define tShrinkStage_battle_transition data[2]

static void Task_GridSquares_battle_transition(u8 taskId)
{
    while (sGridSquares_Funcs_battle_transition[gTasks[taskId].tState_battle_transition](&gTasks[taskId]));
}

static bool8 GridSquares_Init_battle_transition(struct Task *task)
{
    u16 *tilemap, *tileset;

    GetBg0TilesDst(&tilemap, &tileset);
    CpuSet(sShrinkingBoxTileset_battle_transition, tileset, 16);
    CpuFill16(0xF0 << 8, tilemap, BG_SCREEN_SIZE);
    LoadPalette(sFieldEffectPal_Pokeball_battle_transition, BG_PLTT_ID(15), sizeof(sFieldEffectPal_Pokeball_battle_transition));

    task->tState_battle_transition++;
    return FALSE;
}

static bool8 GridSquares_Main_battle_transition(struct Task *task)
{
    u16 *tileset;

    if (task->tDelay_battle_transition == 0)
    {
        GetBg0TilemapDst_battle_transition(&tileset);
        task->tDelay_battle_transition = 3;
        task->tShrinkStage_battle_transition++;
        CpuSet(&sShrinkingBoxTileset_battle_transition[task->tShrinkStage_battle_transition * 8], tileset, 16);
        if (task->tShrinkStage_battle_transition > 13)
        {
            task->tState_battle_transition++;
            task->tDelay_battle_transition = 16;
        }
    }

    task->tDelay_battle_transition--;
    return FALSE;
}

static bool8 GridSquares_End_battle_transition(struct Task *task)
{
    if (--task->tDelay_battle_transition == 0)
    {
        FadeScreenBlack_battle_transition();
        DestroyTask(FindTaskIdByFunc(Task_GridSquares_battle_transition));
    }
    return FALSE;
}

#undef tDelay_battle_transition
#undef tShrinkStage_battle_transition

//---------------------------
// B_TRANSITION_ANGLED_WIPES
//---------------------------

#define tWipeId_battle_transition data[1]
#define tDir_battle_transition    data[2]
#define tDelay_battle_transition  data[3]

static void Task_AngledWipes_battle_transition(u8 taskId)
{
    while (sAngledWipes_Funcs_battle_transition[gTasks[taskId].tState_battle_transition](&gTasks[taskId]));
}

static bool8 AngledWipes_Init_battle_transition(struct Task *task)
{
    u16 i;

    InitTransitionData_battle_transition();
    ScanlineEffect_Clear();

    sTransitionData_battle_transition->WININ = WININ_WIN0_ALL;
    sTransitionData_battle_transition->WINOUT = 0;
    sTransitionData_battle_transition->WIN0V = DISPLAY_HEIGHT;

    for (i = 0; i < DISPLAY_HEIGHT; i++)
        gScanlineEffectRegBuffers[0][i] = DISPLAY_WIDTH;

    CpuSet(gScanlineEffectRegBuffers[0], gScanlineEffectRegBuffers[1], DISPLAY_HEIGHT);
    SetVBlankCallback(VBlankCB_AngledWipes_battle_transition);

    task->tState_battle_transition++;
    return TRUE;
}

static bool8 AngledWipes_SetWipeData_battle_transition(struct Task *task)
{
    InitBlackWipe_battle_transition(sTransitionData_battle_transition->data,
                  sAngledWipes_MoveData_battle_transition[task->tWipeId_battle_transition][0],
                  sAngledWipes_MoveData_battle_transition[task->tWipeId_battle_transition][1],
                  sAngledWipes_MoveData_battle_transition[task->tWipeId_battle_transition][2],
                  sAngledWipes_MoveData_battle_transition[task->tWipeId_battle_transition][3],
                  1, 1);
    task->tDir_battle_transition = sAngledWipes_MoveData_battle_transition[task->tWipeId_battle_transition][4];
    task->tState_battle_transition++;
    return TRUE;
}

static bool8 AngledWipes_DoWipe_battle_transition(struct Task *task)
{
    s16 i;
    bool8 finished;

    sTransitionData_battle_transition->VBlank_DMA = 0;

    for (i = 0, finished = FALSE; i < 16; i++)
    {
        s16 r3 = gScanlineEffectRegBuffers[0][sTransitionData_battle_transition->tWipeCurrY_battle_transition] >> 8;
        s16 r4 = gScanlineEffectRegBuffers[0][sTransitionData_battle_transition->tWipeCurrY_battle_transition] & 0xFF;
        if (task->tDir_battle_transition == 0)
        {
            // Moving down
            if (r3 < sTransitionData_battle_transition->tWipeCurrX_battle_transition)
                r3 = sTransitionData_battle_transition->tWipeCurrX_battle_transition;
            if (r3 > r4)
                r3 = r4;
        }
        else
        {
            // Moving up
            if (r4 > sTransitionData_battle_transition->tWipeCurrX_battle_transition)
                r4 = sTransitionData_battle_transition->tWipeCurrX_battle_transition;
            if (r4 <= r3)
                r4 = r3;
        }
        gScanlineEffectRegBuffers[0][sTransitionData_battle_transition->tWipeCurrY_battle_transition] = (r4) | (r3 << 8);
        if (finished)
        {
            task->tState_battle_transition++;
            break;
        }
        finished = UpdateBlackWipe_battle_transition(sTransitionData_battle_transition->data, TRUE, TRUE);
    }

    sTransitionData_battle_transition->VBlank_DMA++;
    return FALSE;
}

static bool8 AngledWipes_TryEnd_battle_transition(struct Task *task)
{
    if (++task->tWipeId_battle_transition < NUM_ANGLED_WIPES_battle_transition)
    {
        // Continue with next wipe
        task->tState_battle_transition++;
        task->tDelay_battle_transition = sAngledWipes_EndDelays_battle_transition[task->tWipeId_battle_transition - 1];
        return TRUE;
    }
    else
    {
        // End transition
        DmaStop(0);
        FadeScreenBlack_battle_transition();
        DestroyTask(FindTaskIdByFunc(Task_AngledWipes_battle_transition));
        return FALSE;
    }
}

static bool8 AngledWipes_StartNext_battle_transition(struct Task *task)
{
    if (--task->tDelay_battle_transition == 0)
    {
        // Return to AngledWipes_SetWipeData_battle_transition
        task->tState_battle_transition = 1;
        return TRUE;
    }

    return FALSE;
}

static void VBlankCB_AngledWipes_battle_transition(void)
{
    DmaStop(0);
    VBlankCB_BattleTransition_battle_transition();
    if (sTransitionData_battle_transition->VBlank_DMA)
        DmaCopy16(3, gScanlineEffectRegBuffers[0], gScanlineEffectRegBuffers[1], DISPLAY_HEIGHT * 2);
    REG_WININ = sTransitionData_battle_transition->WININ;
    REG_WINOUT = sTransitionData_battle_transition->WINOUT;
    REG_WIN0V = sTransitionData_battle_transition->WIN0V;
    REG_WIN0H = gScanlineEffectRegBuffers[1][0];
    DmaSet(0, gScanlineEffectRegBuffers[1], &REG_WIN0H, B_TRANS_DMA_FLAGS_battle_transition);
}

#undef tWipeId_battle_transition
#undef tDir_battle_transition
#undef tDelay_battle_transition

//-----------------------------------
// Transition intro
//-----------------------------------

#define tFadeToGrayDelay_battle_transition       data[1]
#define tFadeFromGrayDelay_battle_transition     data[2]
#define tNumFades_battle_transition              data[3]
#define tFadeToGrayIncrement_battle_transition   data[4]
#define tFadeFromGrayIncrement_battle_transition data[5]
#define tDelayTimer_battle_transition            data[6]
#define tBlend_battle_transition                 data[7]

static void CreateIntroTask_battle_transition(s16 fadeToGrayDelay, s16 fadeFromGrayDelay, s16 numFades, s16 fadeToGrayIncrement, s16 fadeFromGrayIncrement)
{
    u8 taskId = CreateTask(Task_BattleTransition_Intro, 3);
    gTasks[taskId].tFadeToGrayDelay_battle_transition = fadeToGrayDelay;
    gTasks[taskId].tFadeFromGrayDelay_battle_transition = fadeFromGrayDelay;
    gTasks[taskId].tNumFades_battle_transition = numFades;
    gTasks[taskId].tFadeToGrayIncrement_battle_transition = fadeToGrayIncrement;
    gTasks[taskId].tFadeFromGrayIncrement_battle_transition = fadeFromGrayIncrement;
    gTasks[taskId].tDelayTimer_battle_transition = fadeToGrayDelay;
}

static bool8 IsIntroTaskDone_battle_transition(void)
{
    if (FindTaskIdByFunc(Task_BattleTransition_Intro) == TASK_NONE)
        return TRUE;
    else
        return FALSE;
}

void Task_BattleTransition_Intro(u8 taskId)
{
    while (sTransitionIntroFuncs_battle_transition[gTasks[taskId].tState_battle_transition](&gTasks[taskId]));
}

static bool8 TransitionIntro_FadeToGray_battle_transition(struct Task *task)
{
    if (task->tDelayTimer_battle_transition == 0 || --task->tDelayTimer_battle_transition == 0)
    {
        task->tDelayTimer_battle_transition = task->tFadeToGrayDelay_battle_transition;
        task->tBlend_battle_transition += task->tFadeToGrayIncrement_battle_transition;
        if (task->tBlend_battle_transition > 16)
            task->tBlend_battle_transition = 16;
        BlendPalettes(PALETTES_ALL, task->tBlend_battle_transition, RGB(11, 11, 11));
    }
    if (task->tBlend_battle_transition >= 16)
    {
        // Fade to gray complete, start fade back
        task->tState_battle_transition++;
        task->tDelayTimer_battle_transition = task->tFadeFromGrayDelay_battle_transition;
    }
    return FALSE;
}

static bool8 TransitionIntro_FadeFromGray_battle_transition(struct Task *task)
{
    if (task->tDelayTimer_battle_transition == 0 || --task->tDelayTimer_battle_transition == 0)
    {
        task->tDelayTimer_battle_transition = task->tFadeFromGrayDelay_battle_transition;
        task->tBlend_battle_transition -= task->tFadeFromGrayIncrement_battle_transition;
        if (task->tBlend_battle_transition < 0)
            task->tBlend_battle_transition = 0;
        BlendPalettes(PALETTES_ALL, task->tBlend_battle_transition, RGB(11, 11, 11));
    }
    if (task->tBlend_battle_transition == 0)
    {
        if (--task->tNumFades_battle_transition == 0)
        {
            // All fades done, end intro
            DestroyTask(FindTaskIdByFunc(Task_BattleTransition_Intro));
        }
        else
        {
            // Fade from gray complete, start new fade
            task->tDelayTimer_battle_transition = task->tFadeToGrayDelay_battle_transition;
            task->tState_battle_transition = 0;
        }
    }
    return FALSE;
}

#undef tFadeToGrayDelay_battle_transition
#undef tFadeFromGrayDelay_battle_transition
#undef tNumFades_battle_transition
#undef tFadeToGrayIncrement_battle_transition
#undef tFadeFromGrayIncrement_battle_transition
#undef tDelayTimer_battle_transition
#undef tBlend_battle_transition

//-----------------------------------
// General transition functions
//-----------------------------------

static void InitTransitionData_battle_transition(void)
{
    memset(sTransitionData_battle_transition, 0, sizeof(*sTransitionData_battle_transition));
    GetCameraOffsetWithPan(&sTransitionData_battle_transition->cameraX, &sTransitionData_battle_transition->cameraY);
}

static void VBlankCB_BattleTransition_battle_transition(void)
{
    LoadOam();
    ProcessSpriteCopyRequests();
    TransferPlttBuffer();
}

static void GetBg0TilemapDst_battle_transition(u16 **tileset)
{
    u16 charBase = REG_BG0CNT >> 2;
    charBase <<= 14;
    *tileset = (u16 *)(BG_VRAM + charBase);
}

void GetBg0TilesDst(u16 **tilemap, u16 **tileset)
{
    u16 screenBase = REG_BG0CNT >> 8;
    u16 charBase = REG_BG0CNT >> 2;

    screenBase <<= 11;
    charBase <<= 14;

    *tilemap = (u16 *)(BG_VRAM + screenBase);
    *tileset = (u16 *)(BG_VRAM + charBase);
}

static void FadeScreenBlack_battle_transition(void)
{
    BlendPalettes(PALETTES_ALL, 16, RGB_BLACK);
}

static void SetSinWave_battle_transition(s16 *array, s16 sinAdd, s16 index, s16 indexIncrementer, s16 amplitude, s16 arrSize)
{
    u8 i;
    for (i = 0; arrSize > 0; arrSize--, i++, index += indexIncrementer)
        array[i] = sinAdd + Sin(index & 0xFF, amplitude);
}

static void SetCircularMask_battle_transition(u16 *buffer, s16 centerX, s16 centerY, s16 radius)
{
    s16 i;

    memset(buffer, 10, DISPLAY_HEIGHT * sizeof(u16));
    for (i = 0; i < 64; i++)
    {
        s16 sinResult, cosResult;
        s16 drawXLeft, drawYBottNext, drawYTopNext, drawX, drawYTop, drawYBott;

        sinResult = Sin(i, radius);
        cosResult = Cos(i, radius);

        drawXLeft = centerX - sinResult;
        drawX = centerX + sinResult;
        drawYTop = centerY - cosResult;
        drawYBott = centerY + cosResult;

        if (drawXLeft < 0)
            drawXLeft = 0;
        if (drawX > DISPLAY_WIDTH)
            drawX = DISPLAY_WIDTH;
        if (drawYTop < 0)
            drawYTop = 0;
        if (drawYBott > DISPLAY_HEIGHT - 1)
            drawYBott = DISPLAY_HEIGHT - 1;

        drawX |= (drawXLeft << 8);
        buffer[drawYTop] = drawX;
        buffer[drawYBott] = drawX;

        cosResult = Cos(i + 1, radius);
        drawYTopNext = centerY - cosResult;
        drawYBottNext = centerY + cosResult;

        if (drawYTopNext < 0)
            drawYTopNext = 0;
        if (drawYBottNext > DISPLAY_HEIGHT - 1)
            drawYBottNext = DISPLAY_HEIGHT - 1;

        while (drawYTop > drawYTopNext)
            buffer[--drawYTop] = drawX;
        while (drawYTop < drawYTopNext)
            buffer[++drawYTop] = drawX;

        while (drawYBott > drawYBottNext)
            buffer[--drawYBott] = drawX;
        while (drawYBott < drawYBottNext)
            buffer[++drawYBott] = drawX;
    }
}

static void InitBlackWipe_battle_transition(s16 *data, s16 startX, s16 startY, s16 endX, s16 endY, s16 xMove, s16 yMove)
{
    tWipeStartX_battle_transition = startX;
    tWipeStartY_battle_transition = startY;
    tWipeCurrX_battle_transition = startX;
    tWipeCurrY_battle_transition = startY;
    tWipeEndX_battle_transition = endX;
    tWipeEndY_battle_transition = endY;
    tWipeXMove_battle_transition = xMove;
    tWipeYMove_battle_transition = yMove;
    tWipeXDist_battle_transition = endX - startX;
    if (tWipeXDist_battle_transition < 0)
    {
        // If end was less than start, reverse direction
        tWipeXDist_battle_transition = -tWipeXDist_battle_transition;
        tWipeXMove_battle_transition = -xMove;
    }
    tWipeYDist_battle_transition = endY - startY;
    if (tWipeYDist_battle_transition < 0)
    {
        // If end was less than start, reverse direction
        tWipeYDist_battle_transition = -tWipeYDist_battle_transition;
        tWipeYMove_battle_transition = -yMove;
    }
    tWipeTemp_battle_transition = 0;
}

static bool8 UpdateBlackWipe_battle_transition(s16 *data, bool8 xExact, bool8 yExact)
{
    u8 numFinished;

    if (tWipeXDist_battle_transition > tWipeYDist_battle_transition)
    {
        // X has further to move, move it first
        tWipeCurrX_battle_transition += tWipeXMove_battle_transition;

        // If it has been far enough since Y's
        // last move then move it too
        tWipeTemp_battle_transition += tWipeYDist_battle_transition;
        if (tWipeTemp_battle_transition > tWipeXDist_battle_transition)
        {
            tWipeCurrY_battle_transition += tWipeYMove_battle_transition;
            tWipeTemp_battle_transition -= tWipeXDist_battle_transition;
        }
    }
    else
    {
        // Y has further to move, move it first
        tWipeCurrY_battle_transition += tWipeYMove_battle_transition;

        // If it has been far enough since X's
        // last move then move it too
        tWipeTemp_battle_transition += tWipeXDist_battle_transition;
        if (tWipeTemp_battle_transition > tWipeYDist_battle_transition)
        {
            tWipeCurrX_battle_transition += tWipeXMove_battle_transition;
            tWipeTemp_battle_transition -= tWipeYDist_battle_transition;
        }
    }

    numFinished = 0;

    // Has X coord reached end?
    if ((tWipeXMove_battle_transition > 0 && tWipeCurrX_battle_transition >= tWipeEndX_battle_transition)
     || (tWipeXMove_battle_transition < 0 && tWipeCurrX_battle_transition <= tWipeEndX_battle_transition))
    {
        numFinished++;
        if (xExact)
            tWipeCurrX_battle_transition = tWipeEndX_battle_transition;
    }

    // Has Y coord reached end?
    if ((tWipeYMove_battle_transition > 0 && tWipeCurrY_battle_transition >= tWipeEndY_battle_transition)
     || (tWipeYMove_battle_transition < 0 && tWipeCurrY_battle_transition <= tWipeEndY_battle_transition))
    {
        numFinished++;
        if (yExact)
            tWipeCurrY_battle_transition = tWipeEndY_battle_transition;
    }

    // Return TRUE if both coords have reached end
    if (numFinished == 2)
        return TRUE;
    else
        return FALSE;
}

