static bool8 FrontierLogoWave_Init_battle_transition(struct Task *task)
{
    u16 *tilemap, *tileset;

    InitTransitionData_battle_transition();
    ScanlineEffect_Clear();
    ClearGpuRegBits(REG_OFFSET_DISPCNT, DISPCNT_WIN0_ON | DISPCNT_WIN1_ON);
    task->tAmplitudeVal_battle_transition = 32 << 8;
    task->tSinVal_battle_transition = 0x7FFF;
    task->tBlendTarget2_battle_transition = 0;
    task->tBlendTarget1_battle_transition = 16;
    task->tSinDecrement_battle_transition = 2560;
    sTransitionData_battle_transition->BLDCNT = BLDCNT_TGT1_BG0 | BLDCNT_EFFECT_BLEND | BLDCNT_TGT2_ALL;
    sTransitionData_battle_transition->BLDALPHA = BLDALPHA_BLEND(task->tBlendTarget2_battle_transition, task->tBlendTarget1_battle_transition);
    REG_BLDCNT = sTransitionData_battle_transition->BLDCNT;
    REG_BLDALPHA = sTransitionData_battle_transition->BLDALPHA;
    GetBg0TilesDst(&tilemap, &tileset);
    CpuFill16(0, tilemap, BG_SCREEN_SIZE);
    LZ77UnCompVram(sFrontierLogo_Tileset_battle_transition, tileset);
    LoadPalette(sFrontierLogo_Palette_battle_transition, BG_PLTT_ID(15), sizeof(sFrontierLogo_Palette_battle_transition));
    sTransitionData_battle_transition->cameraY = 0;

    task->tState_battle_transition++;
    return FALSE;
}

static bool8 FrontierLogoWave_SetGfx_battle_transition(struct Task *task)
{
    u16 *tilemap, *tileset;

    GetBg0TilesDst(&tilemap, &tileset);
    LZ77UnCompVram(sFrontierLogo_Tilemap_battle_transition, tilemap);

    task->tState_battle_transition++;
    return TRUE;
}

static bool8 FrontierLogoWave_InitScanline_battle_transition(struct Task *task)
{
    u8 i;

    for (i = 0; i < DISPLAY_HEIGHT; i++)
        gScanlineEffectRegBuffers[1][i] = sTransitionData_battle_transition->cameraY;

    SetVBlankCallback(VBlankCB_FrontierLogoWave_battle_transition);
    SetHBlankCallback(HBlankCB_FrontierLogoWave_battle_transition);
    EnableInterrupts(INTR_FLAG_HBLANK);

    task->tState_battle_transition++;
    return TRUE;
}

static bool8 FrontierLogoWave_Main_battle_transition(struct Task *task)
{
    u8 i;
    u16 sinVal, amplitude, sinSpread;

    sTransitionData_battle_transition->VBlank_DMA = FALSE;

    amplitude = task->tAmplitudeVal_battle_transition >> 8;
    sinVal = task->tSinVal_battle_transition;
    sinSpread = 384;

    task->tSinVal_battle_transition -= task->tSinDecrement_battle_transition;

    if (task->tTimer_battle_transition >= 70)
    {
        // Decrease amount of logo movement and distortion
        // until it rests normally in the middle of the screen.
        if (task->tAmplitudeVal_battle_transition - 384 >= 0)
            task->tAmplitudeVal_battle_transition -= 384;
        else
            task->tAmplitudeVal_battle_transition = 0;
    }

    if (task->tTimer_battle_transition >= 0 && task->tTimer_battle_transition % 3 == 0)
    {
        // Blend logo into view
        if (task->tBlendTarget2_battle_transition < 16)
            task->tBlendTarget2_battle_transition++;
        else if (task->tBlendTarget1_battle_transition > 0)
            task->tBlendTarget1_battle_transition--;

        sTransitionData_battle_transition->BLDALPHA = BLDALPHA_BLEND(task->tBlendTarget2_battle_transition, task->tBlendTarget1_battle_transition);
    }

    // Move logo up and down and distort it
    for (i = 0; i < DISPLAY_HEIGHT; i++, sinVal += sinSpread)
    {
        s16 index = sinVal / 256;
        gScanlineEffectRegBuffers[0][i] = sTransitionData_battle_transition->cameraY + Sin(index & 0xff, amplitude);
    }

    if (++task->tTimer_battle_transition == 101)
    {
        task->tStartedFade_battle_transition++;
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
    }

    if (task->tStartedFade_battle_transition && !gPaletteFade.active)
        DestroyTask(FindTaskIdByFunc(Task_FrontierLogoWave_battle_transition));

    task->tSinDecrement_battle_transition -= 17;
    sTransitionData_battle_transition->VBlank_DMA++;
    return FALSE;
}

static void VBlankCB_FrontierLogoWave_battle_transition(void)
{
    VBlankCB_BattleTransition_battle_transition();
    REG_BLDCNT = sTransitionData_battle_transition->BLDCNT;
    REG_BLDALPHA = sTransitionData_battle_transition->BLDALPHA;

    if (sTransitionData_battle_transition->VBlank_DMA)
        DmaCopy16(3, gScanlineEffectRegBuffers[0], gScanlineEffectRegBuffers[1], DISPLAY_HEIGHT * 2);
}

static void HBlankCB_FrontierLogoWave_battle_transition(void)
{
    u16 var = gScanlineEffectRegBuffers[1][REG_VCOUNT];
    REG_BG0VOFS = var;
}

