static bool8 FrontierSquares_Init_battle_transition(struct Task *task)
{
    u16 *tilemap, *tileset;

    GetBg0TilesDst(&tilemap, &tileset);
    LZ77UnCompVram(sFrontierSquares_FilledBg_Tileset_battle_transition, tileset);

    FillBgTilemapBufferRect_Palette0(0, 0, 0, 0, 32, 32);
    FillBgTilemapBufferRect(0, 1, 0, 0, MARGIN_SIZE_battle_transition, 32, 15);
    FillBgTilemapBufferRect(0, 1, 30 - MARGIN_SIZE_battle_transition, 0, MARGIN_SIZE_battle_transition, 32, 15);
    CopyBgTilemapBufferToVram(0);
    LoadPalette(sFrontierSquares_Palette_battle_transition, BG_PLTT_ID(15), sizeof(sFrontierSquares_Palette_battle_transition));

    task->tPosX_battle_transition = MARGIN_SIZE_battle_transition;
    task->tPosY_battle_transition = 0;
    task->tRowPos_battle_transition = 0;
    task->tShrinkDelay_battle_transition = 10;

    task->tState_battle_transition++;
    return FALSE;
}

static bool8 FrontierSquares_Draw_battle_transition(struct Task *task)
{
    CopyRectToBgTilemapBufferRect(0, sFrontierSquares_Tilemap_battle_transition, 0, 0,
                                  SQUARE_SIZE_battle_transition, SQUARE_SIZE_battle_transition,
                                  task->tPosX_battle_transition, task->tPosY_battle_transition,
                                  SQUARE_SIZE_battle_transition, SQUARE_SIZE_battle_transition,
                                  15, 0, 0);
    CopyBgTilemapBufferToVram(0);

    task->tPosX_battle_transition += SQUARE_SIZE_battle_transition;
    if (++task->tRowPos_battle_transition == NUM_SQUARES_PER_ROW_battle_transition)
    {
        task->tPosX_battle_transition = MARGIN_SIZE_battle_transition;
        task->tPosY_battle_transition += SQUARE_SIZE_battle_transition;
        task->tRowPos_battle_transition = 0;
        if (task->tPosY_battle_transition >= NUM_SQUARES_PER_COL_battle_transition * SQUARE_SIZE_battle_transition)
            task->tState_battle_transition++;
    }

    return FALSE;
}

static bool8 FrontierSquares_Shrink_battle_transition(struct Task *task)
{
    u8 i;
    u16 *tilemap, *tileset;

    GetBg0TilesDst(&tilemap, &tileset);
    if (task->tShrinkDelayTimer_battle_transition++ >= task->tShrinkDelay_battle_transition)
    {
        switch (task->tShrinkState_battle_transition)
        {
        case 0:
            for (i = BG_PLTT_ID(15) + 10; i < BG_PLTT_ID(15) + 15; i++)
            {
                gPlttBufferUnfaded[i] = RGB_BLACK;
                gPlttBufferFaded[i] = RGB_BLACK;
            }
            break;
        case 1:
            BlendPalettes(PALETTES_ALL & ~(1 << 15), 16, RGB_BLACK);
            LZ77UnCompVram(sFrontierSquares_EmptyBg_Tileset_battle_transition, tileset);
            break;
        case 2:
            LZ77UnCompVram(sFrontierSquares_Shrink1_Tileset_battle_transition, tileset);
            break;
        case 3:
            LZ77UnCompVram(sFrontierSquares_Shrink2_Tileset_battle_transition, tileset);
            break;
        default:
            FillBgTilemapBufferRect_Palette0(0, 1, 0, 0, 32, 32);
            CopyBgTilemapBufferToVram(0);
            task->tState_battle_transition++;
            return FALSE;
        }

        task->tShrinkDelayTimer_battle_transition = 0;
        task->tShrinkState_battle_transition++;
    }

    return FALSE;
}

