static bool8 FrontierSquaresSpiral_Outward_battle_transition(struct Task *task)
{
    u8 pos = sFrontierSquaresSpiral_Positions_battle_transition[task->tSquareNum_battle_transition];
    u8 x = pos % NUM_SQUARES_PER_ROW_battle_transition;
    u8 y = pos / NUM_SQUARES_PER_ROW_battle_transition;
    CopyRectToBgTilemapBufferRect(0, sFrontierSquares_Tilemap_battle_transition, 0, 0,
                                  SQUARE_SIZE_battle_transition, SQUARE_SIZE_battle_transition,
                                  SQUARE_SIZE_battle_transition * x + MARGIN_SIZE_battle_transition, SQUARE_SIZE_battle_transition * y,
                                  SQUARE_SIZE_battle_transition, SQUARE_SIZE_battle_transition,
                                  15, 0, 0);
    CopyBgTilemapBufferToVram(0);

    if (--task->tSquareNum_battle_transition < 0)
        task->tState_battle_transition++;
    return FALSE;
}

// Now that the overworld is completely covered by the squares,
// set it to black so it's not revealed when the squares are removed.
static bool8 FrontierSquaresSpiral_SetBlack_battle_transition(struct Task *task)
{
    BlendPalette(BG_PLTT_ID(14), 16, 3, RGB_BLACK);
    BlendPalettes(PALETTES_ALL & ~(1 << 15 | 1 << 14), 16, RGB_BLACK);

    task->tSquareNum_battle_transition = 0;
    task->tFadeFlag_battle_transition = 0;

    task->tState_battle_transition++;
    return FALSE;
}

// Spiral inward erasing the squares
static bool8 FrontierSquaresSpiral_Inward_battle_transition(struct Task *task)
{
    // Each square is faded first, then the one that was faded last move is erased.
    if (task->tFadeFlag_battle_transition ^= 1)
    {
        // Shade square
        CopyRectToBgTilemapBufferRect(0, sFrontierSquares_Tilemap_battle_transition, 0, 0,
                                      SQUARE_SIZE_battle_transition, SQUARE_SIZE_battle_transition,
                                      SQUARE_SIZE_battle_transition * (sFrontierSquaresSpiral_Positions_battle_transition[task->tSquareNum_battle_transition] % NUM_SQUARES_PER_ROW_battle_transition) + MARGIN_SIZE_battle_transition,
                                      SQUARE_SIZE_battle_transition * (sFrontierSquaresSpiral_Positions_battle_transition[task->tSquareNum_battle_transition] / NUM_SQUARES_PER_ROW_battle_transition),
                                      SQUARE_SIZE_battle_transition, SQUARE_SIZE_battle_transition,
                                      14, 0, 0);
    }
    else
    {
        if (task->tSquareNum_battle_transition > 0)
        {
            // Erase square
            FillBgTilemapBufferRect(0, 1,
                                    SQUARE_SIZE_battle_transition * (sFrontierSquaresSpiral_Positions_battle_transition[task->tSquareNum_battle_transition - 1] % NUM_SQUARES_PER_ROW_battle_transition) + MARGIN_SIZE_battle_transition,
                                    SQUARE_SIZE_battle_transition * (sFrontierSquaresSpiral_Positions_battle_transition[task->tSquareNum_battle_transition - 1] / NUM_SQUARES_PER_ROW_battle_transition),
                                    SQUARE_SIZE_battle_transition, SQUARE_SIZE_battle_transition,
                                    15);
        }
        task->tSquareNum_battle_transition++;
    }

    if (task->tSquareNum_battle_transition >= NUM_SQUARES_battle_transition)
        task->tState_battle_transition++;

    CopyBgTilemapBufferToVram(0);
    return FALSE;
}

static bool8 FrontierSquares_End_battle_transition(struct Task *task)
{
    FillBgTilemapBufferRect_Palette0(0, 1, 0, 0, 32, 32);
    CopyBgTilemapBufferToVram(0);
    BlendPalettes(PALETTES_ALL, 16, RGB_BLACK);
    DestroyTask(FindTaskIdByFunc(task->func));
    return FALSE;
}

