static void Task_ScrollBg_battle_transition(u8 taskId)
{
    if (!(gTasks[taskId].tScrollUpdateFlag_battle_transition ^= 1))
    {
        SetGpuReg(REG_OFFSET_BG0VOFS, gBattle_BG0_X);
        SetGpuReg(REG_OFFSET_BG0HOFS, gBattle_BG0_Y);
        gBattle_BG0_X += gTasks[taskId].tScrollXDir_battle_transition;
        gBattle_BG0_Y += gTasks[taskId].tScrollYDir_battle_transition;
    }
}

static bool8 FrontierSquaresScroll_Init_battle_transition(struct Task *task)
{
    u8 taskId = 0;
    u16 *tilemap, *tileset;

    GetBg0TilesDst(&tilemap, &tileset);
    LZ77UnCompVram(sFrontierSquares_FilledBg_Tileset_battle_transition, tileset);
    FillBgTilemapBufferRect_Palette0(0, 0, 0, 0, 32, 32);
    CopyBgTilemapBufferToVram(0);
    LoadPalette(sFrontierSquares_Palette_battle_transition, BG_PLTT_ID(15), sizeof(sFrontierSquares_Palette_battle_transition));

    gBattle_BG0_X = 0;
    gBattle_BG0_Y = 0;
    SetGpuReg(REG_OFFSET_BG0VOFS, gBattle_BG0_X);
    SetGpuReg(REG_OFFSET_BG0HOFS, gBattle_BG0_Y);

    task->tSquareNum_battle_transition = 0;

    // Start scrolling bg in a random direction.
    taskId = CreateTask(Task_ScrollBg_battle_transition, 1);
    switch (Random() % 4)
    {
    case 0: // Down/right
        gTasks[taskId].tScrollXDir_battle_transition = 1;
        gTasks[taskId].tScrollYDir_battle_transition = 1;
        break;
    case 1: // Up/left
        gTasks[taskId].tScrollXDir_battle_transition = -1;
        gTasks[taskId].tScrollYDir_battle_transition = -1;
        break;
    case 2: // Up/right
        gTasks[taskId].tScrollXDir_battle_transition = 1;
        gTasks[taskId].tScrollYDir_battle_transition = -1;
        break;
    default: // Down/left
        gTasks[taskId].tScrollXDir_battle_transition = -1;
        gTasks[taskId].tScrollYDir_battle_transition = 1;
        break;
    }

    task->tState_battle_transition++;
    return FALSE;
}

static bool8 FrontierSquaresScroll_Draw_battle_transition(struct Task *task)
{
    u8 pos = sFrontierSquaresScroll_Positions_battle_transition[task->tSquareNum_battle_transition];
    u8 x = pos / (NUM_SQUARES_PER_ROW_battle_transition + 1); // +1 because during scroll an additional column covers the margin.
    u8 y = pos % (NUM_SQUARES_PER_ROW_battle_transition + 1);

    CopyRectToBgTilemapBufferRect(0, &sFrontierSquares_Tilemap_battle_transition, 0, 0,
                                  SQUARE_SIZE_battle_transition, SQUARE_SIZE_battle_transition,
                                  SQUARE_SIZE_battle_transition * x + MARGIN_SIZE_battle_transition, SQUARE_SIZE_battle_transition * y,
                                  SQUARE_SIZE_battle_transition, SQUARE_SIZE_battle_transition,
                                  15, 0, 0);
    CopyBgTilemapBufferToVram(0);

    if (++task->tSquareNum_battle_transition >= (int)ARRAY_COUNT(sFrontierSquaresScroll_Positions_battle_transition))
        task->tState_battle_transition++;
    return 0;
}

// Now that the overworld is completely covered by the squares,
// set it to black so it's not revealed when the squares are removed.
static bool8 FrontierSquaresScroll_SetBlack_battle_transition(struct Task *task)
{
    BlendPalettes(PALETTES_ALL & ~(1 << 15), 16, RGB_BLACK);

    task->tSquareNum_battle_transition = 0;

    task->tState_battle_transition++;
    return FALSE;
}

static bool8 FrontierSquaresScroll_Erase_battle_transition(struct Task *task)
{
    u8 pos = sFrontierSquaresScroll_Positions_battle_transition[task->tSquareNum_battle_transition];
    u8 x = pos / (NUM_SQUARES_PER_ROW_battle_transition + 1);
    u8 y = pos % (NUM_SQUARES_PER_ROW_battle_transition + 1);

    FillBgTilemapBufferRect(0, 1,
                            SQUARE_SIZE_battle_transition * x + MARGIN_SIZE_battle_transition, SQUARE_SIZE_battle_transition * y,
                            SQUARE_SIZE_battle_transition, SQUARE_SIZE_battle_transition,
                            15);
    CopyBgTilemapBufferToVram(0);

    if (++task->tSquareNum_battle_transition >= (int)ARRAY_COUNT(sFrontierSquaresScroll_Positions_battle_transition))
    {
        DestroyTask(FindTaskIdByFunc(Task_ScrollBg_battle_transition));
        task->tState_battle_transition++;
    }

    return FALSE;
}

static bool8 FrontierSquaresScroll_End_battle_transition(struct Task *task)
{
    gBattle_BG0_X = 0;
    gBattle_BG0_Y = 0;
    SetGpuReg(REG_OFFSET_BG0VOFS, 0);
    SetGpuReg(REG_OFFSET_BG0HOFS, gBattle_BG0_Y);

    FillBgTilemapBufferRect_Palette0(0, 1, 0, 0, 32, 32);
    CopyBgTilemapBufferToVram(0);
    BlendPalettes(PALETTES_ALL, 16, RGB_BLACK);

    DestroyTask(FindTaskIdByFunc(task->func));
    task->tState_battle_transition++; // Changing value of a destroyed task

    return FALSE;
}

#undef tScrollXDir_battle_transition
#undef tScrollYDir_battle_transition
#undef tScrollUpdateFlag_battle_transition
#undef tSquareNum_battle_transition
