static bool8 AreBlenderBerriesSame_berry_blender(struct BlenderBerry* berries, u8 a, u8 b)
{
    // First check to itemId is pointless (and wrong anyway?), always false when this is called
    // Only used to determine if two enigma berries are equivalent
    if (berries[a].itemId != berries[b].itemId
     || (StringCompare(berries[a].name, berries[b].name) == 0
      && (berries[a].flavors[FLAVOR_SPICY] == berries[b].flavors[FLAVOR_SPICY]
       && berries[a].flavors[FLAVOR_DRY] == berries[b].flavors[FLAVOR_DRY]
       && berries[a].flavors[FLAVOR_SWEET] == berries[b].flavors[FLAVOR_SWEET]
       && berries[a].flavors[FLAVOR_BITTER] == berries[b].flavors[FLAVOR_BITTER]
       && berries[a].flavors[FLAVOR_SOUR] == berries[b].flavors[FLAVOR_SOUR]
       && berries[a].flavors[FLAVOR_COUNT] == berries[b].flavors[FLAVOR_COUNT])))
        return TRUE;
    else
        return FALSE;
}

static u32 CalculatePokeblockColor_berry_blender(struct BlenderBerry* berries, s16 *_flavors, u8 numPlayers, u8 negativeFlavors)
{
    s16 flavors[FLAVOR_COUNT + 1];
    s32 i, j;
    u8 numFlavors;

    for (i = 0; i < FLAVOR_COUNT + 1; i++)
        flavors[i] = _flavors[i];

    j = 0;
    for (i = 0; i < FLAVOR_COUNT; i++)
    {
        if (flavors[i] == 0)
            j++;
    }

    // If all 5 flavors are 0, or if 4-5 flavors were negative,
    // or if players used the same berry, color is black
    if (j == FLAVOR_COUNT || negativeFlavors > 3)
        return PBLOCK_CLR_BLACK;

    for (i = 0; i < numPlayers; i++)
    {
        for (j = 0; j < numPlayers; j++)
        {
            if (berries[i].itemId == berries[j].itemId && i != j
                && (berries[i].itemId != ITEM_ENIGMA_BERRY_E_READER || AreBlenderBerriesSame_berry_blender(berries, i, j)))
                    return PBLOCK_CLR_BLACK;
        }
    }

    numFlavors = 0;
    for (numFlavors = 0, i = 0; i < FLAVOR_COUNT; i++)
    {
        if (flavors[i] > 0)
            numFlavors++;
    }

    // Check for special colors (White/Gray/Gold)
    if (numFlavors > 3)
        return PBLOCK_CLR_WHITE;

    if (numFlavors == 3)
        return PBLOCK_CLR_GRAY;

    for (i = 0; i < FLAVOR_COUNT; i++)
    {
        if (flavors[i] > 50)
            return PBLOCK_CLR_GOLD;
    }

    // Only 1 flavor present, return corresponding color
    if (numFlavors == 1 && flavors[FLAVOR_SPICY] > 0)
        return PBLOCK_CLR_RED;
    if (numFlavors == 1 && flavors[FLAVOR_DRY] > 0)
        return PBLOCK_CLR_BLUE;
    if (numFlavors == 1 && flavors[FLAVOR_SWEET] > 0)
        return PBLOCK_CLR_PINK;
    if (numFlavors == 1 && flavors[FLAVOR_BITTER] > 0)
        return PBLOCK_CLR_GREEN;
    if (numFlavors == 1 && flavors[FLAVOR_SOUR] > 0)
        return PBLOCK_CLR_YELLOW;

    if (numFlavors == 2)
    {
        // Determine which 2 flavors are present
        s32 idx = 0;
        for (i = 0; i < FLAVOR_COUNT; i++)
        {
            if (flavors[i] > 0)
                sPokeblockPresentFlavors_berry_blender[idx++] = i;
        }
        // Use the stronger flavor to determine color
        // The weaker flavor is returned in the upper 16 bits, but this is ignored in the color assignment
        if (flavors[sPokeblockPresentFlavors_berry_blender[0]] >= flavors[sPokeblockPresentFlavors_berry_blender[1]])
        {
            if (sPokeblockPresentFlavors_berry_blender[0] == FLAVOR_SPICY)
                return (sPokeblockPresentFlavors_berry_blender[1] << 16) | PBLOCK_CLR_PURPLE;
            if (sPokeblockPresentFlavors_berry_blender[0] == FLAVOR_DRY)
                return (sPokeblockPresentFlavors_berry_blender[1] << 16) | PBLOCK_CLR_INDIGO;
            if (sPokeblockPresentFlavors_berry_blender[0] == FLAVOR_SWEET)
                return (sPokeblockPresentFlavors_berry_blender[1] << 16) | PBLOCK_CLR_BROWN;
            if (sPokeblockPresentFlavors_berry_blender[0] == FLAVOR_BITTER)
                return (sPokeblockPresentFlavors_berry_blender[1] << 16) | PBLOCK_CLR_LITE_BLUE;
            if (sPokeblockPresentFlavors_berry_blender[0] == FLAVOR_SOUR)
                return (sPokeblockPresentFlavors_berry_blender[1] << 16) | PBLOCK_CLR_OLIVE;
        }
        else
        {
            if (sPokeblockPresentFlavors_berry_blender[1] == FLAVOR_SPICY)
                return (sPokeblockPresentFlavors_berry_blender[0] << 16) | PBLOCK_CLR_PURPLE;
            if (sPokeblockPresentFlavors_berry_blender[1] == FLAVOR_DRY)
                return (sPokeblockPresentFlavors_berry_blender[0] << 16) | PBLOCK_CLR_INDIGO;
            if (sPokeblockPresentFlavors_berry_blender[1] == FLAVOR_SWEET)
                return (sPokeblockPresentFlavors_berry_blender[0] << 16) | PBLOCK_CLR_BROWN;
            if (sPokeblockPresentFlavors_berry_blender[1] == FLAVOR_BITTER)
                return (sPokeblockPresentFlavors_berry_blender[0] << 16) | PBLOCK_CLR_LITE_BLUE;
            if (sPokeblockPresentFlavors_berry_blender[1] == FLAVOR_SOUR)
                return (sPokeblockPresentFlavors_berry_blender[0] << 16) | PBLOCK_CLR_OLIVE;
        }
    }
    return PBLOCK_CLR_NONE;
}

