extern const u8 gMultiBootProgram_BerryGlitchFix_Start[0x3BF4];
extern const u8 gMultiBootProgram_BerryGlitchFix_End[];

enum {
    MAINSTATE_INIT_berry_fix_program,
    MAINSTATE_BEGIN_berry_fix_program,
    MAINSTATE_CONNECT_berry_fix_program,
    MAINSTATE_INIT_MULTIBOOT_berry_fix_program,
    MAINSTATE_MULTIBOOT_berry_fix_program,
    MAINSTATE_TRANSMIT_berry_fix_program,
    MAINSTATE_EXIT_berry_fix_program,
    MAINSTATE_FAILED_berry_fix_program,
};

void CB2_InitBerryFixProgram(void)
{
    DisableInterrupts(0xFFFF); // all
    EnableInterrupts(INTR_FLAG_VBLANK);
    m4aSoundVSyncOff();
    SetVBlankCallback(NULL);
    ResetSpriteData();
    ResetTasks();
    ScanlineEffect_Stop();
    SetGpuReg(REG_OFFSET_DISPCNT, 0);
    sBerryFix = AllocZeroed(sizeof(*sBerryFix));
    sBerryFix->state = MAINSTATE_INIT_berry_fix_program;
    sBerryFix->curScene = SCENE_NONE_berry_fix_program;
    SetMainCallback2(BerryFix_Main_berry_fix_program);
}

#define TryScene_berry_fix_program(sceneNum) BerryFix_TrySetScene_berry_fix_program(sceneNum) == (sceneNum)

static void BerryFix_Main_berry_fix_program(void)
{
    switch (sBerryFix->state)
    {
        case MAINSTATE_INIT_berry_fix_program:
            BerryFix_GpuSet_berry_fix_program();
            sBerryFix->state = MAINSTATE_BEGIN_berry_fix_program;
            break;
        case MAINSTATE_BEGIN_berry_fix_program:
            if (TryScene_berry_fix_program(SCENE_BEGIN_berry_fix_program) && JOY_NEW(A_BUTTON))
                sBerryFix->state = MAINSTATE_CONNECT_berry_fix_program;
            break;
        case MAINSTATE_CONNECT_berry_fix_program:
            if (TryScene_berry_fix_program(SCENE_ENSURE_CONNECT_berry_fix_program) && JOY_NEW(A_BUTTON))
                sBerryFix->state = MAINSTATE_INIT_MULTIBOOT_berry_fix_program;
            break;
        case MAINSTATE_INIT_MULTIBOOT_berry_fix_program:
            if (TryScene_berry_fix_program(SCENE_TURN_OFF_POWER_berry_fix_program))
            {
                sBerryFix->mb.masterp = gMultiBootProgram_BerryGlitchFix_Start;
                sBerryFix->mb.server_type = 0;
                MultiBootInit(&sBerryFix->mb);
                sBerryFix->timer = 0;
                sBerryFix->state = MAINSTATE_MULTIBOOT_berry_fix_program;
            }
            break;
        case MAINSTATE_MULTIBOOT_berry_fix_program:
            MultiBootMain(&sBerryFix->mb);
            if (sBerryFix->mb.probe_count != 0 || (!(sBerryFix->mb.response_bit & 2) || !(sBerryFix->mb.client_bit & 2)))
            {
                sBerryFix->timer = 0;
            }
            else if (++sBerryFix->timer > 180)
            {
                MultiBootStartMaster(&sBerryFix->mb,
                                     gMultiBootProgram_BerryGlitchFix_Start + ROM_HEADER_SIZE,
                                     (u32)(gMultiBootProgram_BerryGlitchFix_End - (gMultiBootProgram_BerryGlitchFix_Start + ROM_HEADER_SIZE)),
                                     4,
                                     1);
                sBerryFix->state = MAINSTATE_TRANSMIT_berry_fix_program;
            }
            break;
        case MAINSTATE_TRANSMIT_berry_fix_program:
            if (TryScene_berry_fix_program(SCENE_TRANSMITTING_berry_fix_program))
            {
                MultiBootMain(&sBerryFix->mb);

                if (MultiBootCheckComplete(&sBerryFix->mb))
                    sBerryFix->state = MAINSTATE_EXIT_berry_fix_program;
                else if (!(sBerryFix->mb.client_bit & 2))
                    sBerryFix->state = MAINSTATE_FAILED_berry_fix_program;
            }
            break;
        case MAINSTATE_EXIT_berry_fix_program:
            if (TryScene_berry_fix_program(SCENE_FOLLOW_INSTRUCT_berry_fix_program) && JOY_NEW(A_BUTTON))
                DoSoftReset();
            break;
        case MAINSTATE_FAILED_berry_fix_program:
            if (TryScene_berry_fix_program(SCENE_TRANSMIT_FAILED_berry_fix_program) && JOY_NEW(A_BUTTON))
                sBerryFix->state = MAINSTATE_BEGIN_berry_fix_program;
            break;
    }
}

static void BerryFix_GpuSet_berry_fix_program(void)
{
    s32 width, left;

    SetGpuReg(REG_OFFSET_BG0CNT, 0);
    SetGpuReg(REG_OFFSET_BG1CNT, 0);
    SetGpuReg(REG_OFFSET_BG0HOFS, 0);
    SetGpuReg(REG_OFFSET_BG0VOFS, 0);
    SetGpuReg(REG_OFFSET_BG1HOFS, 0);
    SetGpuReg(REG_OFFSET_BG1VOFS, 0);
    SetGpuReg(REG_OFFSET_BLDCNT, 0);

    DmaFill32(3, 0, VRAM, VRAM_SIZE);
    DmaFill32(3, 0, OAM, OAM_SIZE);
    DmaFill32(3, 0, PLTT, PLTT_SIZE);
    ResetBgsAndClearDma3BusyFlags(0);

    InitBgsFromTemplates(0, sBerryFixBgTemplates_berry_fix_program, ARRAY_COUNT(sBerryFixBgTemplates_berry_fix_program));
    ChangeBgX(0, 0, BG_COORD_SET);
    ChangeBgY(0, 0, BG_COORD_SET);
    ChangeBgX(1, 0, BG_COORD_SET);
    ChangeBgY(1, 0, BG_COORD_SET);
    InitWindows(sBerryFixWindowTemplates_berry_fix_program);
    DeactivateAllTextPrinters();

    DmaCopy32(3, sText_Pal_berry_fix_program, BG_PLTT + PLTT_OFFSET_4BPP(15), sizeof(sText_Pal_berry_fix_program));
    SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_OBJ_1D_MAP);
    FillWindowPixelBuffer(WIN_GAME_NAMES, PIXEL_FILL(0));
    FillWindowPixelBuffer(WIN_TURN_OFF_TITLE, PIXEL_FILL(0));
    FillWindowPixelBuffer(WIN_TITLE, PIXEL_FILL(10));

    width = GetStringWidth(FONT_SMALL, sText_Emerald_berry_fix_program, 0);
    left = (120 - width) / 2;
    AddTextPrinterParameterized3(WIN_GAME_NAMES, FONT_SMALL, left, 3, sGameTitleTextColors_berry_fix_program, TEXT_SKIP_DRAW, sText_Emerald_berry_fix_program);

    width = GetStringWidth(FONT_SMALL, sText_RubySapphire_berry_fix_program, 0);
    left = (120 - width) / 2 + 120;
    AddTextPrinterParameterized3(WIN_GAME_NAMES, FONT_SMALL, left, 3, sGameTitleTextColors_berry_fix_program, TEXT_SKIP_DRAW, sText_RubySapphire_berry_fix_program);

    width = GetStringWidth(FONT_SMALL, sText_RubySapphire_berry_fix_program, 0);
    left = (112 - width) / 2;
    AddTextPrinterParameterized3(WIN_TURN_OFF_TITLE, FONT_SMALL, left, 0, sGameTitleTextColors_berry_fix_program, TEXT_SKIP_DRAW, sText_RubySapphire_berry_fix_program);

    width = GetStringWidth(FONT_NORMAL, sText_BerryProgramUpdate_berry_fix_program, 0);
    left = (208 - width) / 2;
    AddTextPrinterParameterized3(WIN_TITLE, FONT_NORMAL, left, 2, sBerryProgramTextColors_berry_fix_program, TEXT_SKIP_DRAW, sText_BerryProgramUpdate_berry_fix_program);

    CopyWindowToVram(WIN_GAME_NAMES, COPYWIN_GFX);
    CopyWindowToVram(WIN_TURN_OFF_TITLE, COPYWIN_GFX);
    CopyWindowToVram(WIN_TITLE, COPYWIN_GFX);
}

static int BerryFix_TrySetScene_berry_fix_program(int scene)
{
    if (sBerryFix->curScene == scene)
        return scene;

    if (sBerryFix->curScene == SCENE_NONE_berry_fix_program)
    {
        BerryFix_SetScene_berry_fix_program(scene);
        sBerryFix->curScene = scene;
    }
    else
    {
        BerryFix_HideScene_berry_fix_program();
        sBerryFix->curScene = SCENE_NONE_berry_fix_program;
    }
    return sBerryFix->curScene;
}

static void BerryFix_SetScene_berry_fix_program(int scene)
{
    FillBgTilemapBufferRect_Palette0(0, 0, 0, 0, 32, 32);
    FillWindowPixelBuffer(WIN_MSG_BODY_berry_fix_program, PIXEL_FILL(10));
    AddTextPrinterParameterized3(WIN_MSG_BODY_berry_fix_program, FONT_NORMAL, 0, 0, sBerryProgramTextColors_berry_fix_program, TEXT_SKIP_DRAW, sBerryProgramTexts_berry_fix_program[scene]);
    PutWindowTilemap(WIN_MSG_BODY_berry_fix_program);
    CopyWindowToVram(WIN_MSG_BODY_berry_fix_program, COPYWIN_GFX);
    switch (scene)
    {
    case SCENE_ENSURE_CONNECT_berry_fix_program:
    case SCENE_TRANSMITTING_berry_fix_program:
    case SCENE_FOLLOW_INSTRUCT_berry_fix_program:
    case SCENE_TRANSMIT_FAILED_berry_fix_program:
        PutWindowTilemap(WIN_GAME_NAMES);
        break;
    case SCENE_TURN_OFF_POWER_berry_fix_program:
        PutWindowTilemap(WIN_TURN_OFF_TITLE);
        break;
    case SCENE_BEGIN_berry_fix_program:
        PutWindowTilemap(WIN_TITLE);
        break;
    }
    CopyBgTilemapBufferToVram(0);
    LZ77UnCompVram(sBerryFixGraphics_berry_fix_program[scene].gfx, (void *)BG_CHAR_ADDR(1));
    LZ77UnCompVram(sBerryFixGraphics_berry_fix_program[scene].tilemap, (void *)BG_SCREEN_ADDR(31));
    // These palettes range in size from 32-48 colors, so the below is interpreting whatever
    // follows the palette (by default, the corresponding tiles) as the remaining 80-96.
    CpuCopy32(sBerryFixGraphics_berry_fix_program[scene].palette, (void *)BG_PLTT, PLTT_SIZEOF(128));
    ShowBg(0);
    ShowBg(1);
}

static void BerryFix_HideScene_berry_fix_program(void)
{
    HideBg(0);
    HideBg(1);
}
