// code
void DoBerryTagScreen(void)
{
    sBerryTag_berry_tag_screen = AllocZeroed(sizeof(*sBerryTag_berry_tag_screen));
    sBerryTag_berry_tag_screen->berryId = ItemIdToBerryType(gSpecialVar_ItemId);
    SetMainCallback2(CB2_InitBerryTagScreen_berry_tag_screen);
}

static void CB2_BerryTagScreen_berry_tag_screen(void)
{
    RunTasks();
    AnimateSprites();
    BuildOamBuffer();
    DoScheduledBgTilemapCopiesToVram();
    UpdatePaletteFade();
}

static void VblankCB_berry_tag_screen(void)
{
    LoadOam();
    ProcessSpriteCopyRequests();
    TransferPlttBuffer();
}

static void CB2_InitBerryTagScreen_berry_tag_screen(void)
{
    while (1)
    {
        if (MenuHelpers_ShouldWaitForLinkRecv() == TRUE)
            break;
        if (InitBerryTagScreen_berry_tag_screen() == TRUE)
            break;
        if (MenuHelpers_IsLinkActive() == TRUE)
            break;
    }
}

static bool8 InitBerryTagScreen_berry_tag_screen(void)
{
    switch (gMain.state)
    {
    case 0:
        SetVBlankHBlankCallbacksToNull();
        ResetVramOamAndBgCntRegs();
        ClearScheduledBgCopiesToVram();
        gMain.state++;
        break;
    case 1:
        ScanlineEffect_Stop();
        gMain.state++;
        break;
    case 2:
        ResetPaletteFade();
        gPaletteFade.bufferTransferDisabled = 1;
        gMain.state++;
        break;
    case 3:
        ResetSpriteData();
        gMain.state++;
        break;
    case 4:
        FreeAllSpritePalettes();
        gMain.state++;
        break;
    case 5:
        if (!MenuHelpers_IsLinkActive())
            ResetTasks();
        gMain.state++;
        break;
    case 6:
        HandleInitBackgrounds_berry_tag_screen();
        sBerryTag_berry_tag_screen->gfxState = 0;
        gMain.state++;
        break;
    case 7:
        if (LoadBerryTagGfx_berry_tag_screen())
            gMain.state++;
        break;
    case 8:
        HandleInitWindows_berry_tag_screen();
        gMain.state++;
        break;
    case 9:
        AddBerryTagTextToBg0_berry_tag_screen();
        gMain.state++;
        break;
    case 10:
        PrintAllBerryData_berry_tag_screen();
        gMain.state++;
        break;
    case 11:
        CreateBerrySprite_berry_tag_screen();
        gMain.state++;
        break;
    case 12:
        CreateFlavorCircleSprites_berry_tag_screen();
        SetFlavorCirclesVisiblity_berry_tag_screen();
        gMain.state++;
        break;
    case 13:
        CreateTask(Task_HandleInput_berry_tag_screen, 0);
        gMain.state++;
        break;
    case 14:
        BlendPalettes(PALETTES_ALL, 0x10, RGB_BLACK);
        gMain.state++;
        break;
    case 15:
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0x10, 0, RGB_BLACK);
        gPaletteFade.bufferTransferDisabled = 0;
        gMain.state++;
        break;
    default: // done
        SetVBlankCallback(VblankCB_berry_tag_screen);
        SetMainCallback2(CB2_BerryTagScreen_berry_tag_screen);
        return TRUE;
    }

    return FALSE;
}

static void HandleInitBackgrounds_berry_tag_screen(void)
{
    ResetBgsAndClearDma3BusyFlags(0);
    InitBgsFromTemplates(0, sBackgroundTemplates_berry_tag_screen, ARRAY_COUNT(sBackgroundTemplates_berry_tag_screen));
    SetBgTilemapBuffer(2, sBerryTag_berry_tag_screen->tilemapBuffers[0]);
    SetBgTilemapBuffer(3, sBerryTag_berry_tag_screen->tilemapBuffers[1]);
    ResetAllBgsCoordinates();
    ScheduleBgCopyTilemapToVram(2);
    ScheduleBgCopyTilemapToVram(3);
    SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_OBJ_1D_MAP | DISPCNT_OBJ_ON);
    SetGpuReg(REG_OFFSET_BLDCNT, 0);
    ShowBg(0);
    ShowBg(1);
    ShowBg(2);
    ShowBg(3);
}

#define BG_TILE_berry_tag_screen 0x42

static bool8 LoadBerryTagGfx_berry_tag_screen(void)
{
    u16 i;

    switch (sBerryTag_berry_tag_screen->gfxState)
    {
    case 0:
        ResetTempTileDataBuffers();
        DecompressAndCopyTileDataToVram(2, gBerryCheck_Gfx, 0, 0, 0);
        sBerryTag_berry_tag_screen->gfxState++;
        break;
    case 1:
        if (FreeTempTileDataBuffersIfPossible() != TRUE)
        {
            LZDecompressWram(gBerryTag_Gfx, sBerryTag_berry_tag_screen->tilemapBuffers[0]);
            sBerryTag_berry_tag_screen->gfxState++;
        }
        break;
    case 2:
        LZDecompressWram(gBerryTag_Pal, sBerryTag_berry_tag_screen->tilemapBuffers[2]);
        sBerryTag_berry_tag_screen->gfxState++;
        break;
    case 3:
        // Palette of the bg tiles changes depending on the player's gender
        if (gSaveBlock2Ptr->playerGender == MALE)
        {
            for (i = 0; i < ARRAY_COUNT(sBerryTag_berry_tag_screen->tilemapBuffers[1]); i++)
                sBerryTag_berry_tag_screen->tilemapBuffers[1][i] = (4 << 12) | BG_TILE_berry_tag_screen;
        }
        else
        {
            for (i = 0; i < ARRAY_COUNT(sBerryTag_berry_tag_screen->tilemapBuffers[1]); i++)
                sBerryTag_berry_tag_screen->tilemapBuffers[1][i] = (5 << 12) | BG_TILE_berry_tag_screen;
        }
        sBerryTag_berry_tag_screen->gfxState++;
        break;
    case 4:
        LoadCompressedPalette(gBerryCheck_Pal, BG_PLTT_ID(0), 6 * PLTT_SIZE_4BPP);
        sBerryTag_berry_tag_screen->gfxState++;
        break;
    case 5:
        LoadCompressedSpriteSheet(&gBerryCheckCircleSpriteSheet);
        sBerryTag_berry_tag_screen->gfxState++;
        break;
    default:
        LoadCompressedSpritePalette(&gBerryCheckCirclePaletteTable);
        return TRUE; // done
    }

    return FALSE;
}

static void HandleInitWindows_berry_tag_screen(void)
{
    u16 i;

    InitWindows(sWindowTemplates_berry_tag_screen);
    DeactivateAllTextPrinters();
    LoadPalette(sFontPalette_berry_tag_screen, BG_PLTT_ID(15), sizeof(sFontPalette_berry_tag_screen));
    for (i = 0; i < ARRAY_COUNT(sWindowTemplates_berry_tag_screen) - 1; i++)
        PutWindowTilemap(i);
    ScheduleBgCopyTilemapToVram(0);
    ScheduleBgCopyTilemapToVram(1);
}

static void PrintTextInBerryTagScreen_berry_tag_screen(u8 windowId, const u8 *text, u8 x, u8 y, s32 speed, u8 colorStructId)
{
    AddTextPrinterParameterized4(windowId, FONT_NORMAL, x, y, 0, 0, sTextColors_berry_tag_screen[colorStructId], speed, text);
}

static void AddBerryTagTextToBg0_berry_tag_screen(void)
{
    memcpy(GetBgTilemapBuffer(0), sBerryTag_berry_tag_screen->tilemapBuffers[2], sizeof(sBerryTag_berry_tag_screen->tilemapBuffers[2]));
    FillWindowPixelBuffer(WIN_BERRY_TAG_berry_tag_screen, PIXEL_FILL(15));
    PrintTextInBerryTagScreen_berry_tag_screen(WIN_BERRY_TAG_berry_tag_screen, sText_BerryTag_berry_tag_screen, GetStringCenterAlignXOffset(FONT_NORMAL, sText_BerryTag_berry_tag_screen, 0x40), 1, 0, 1);
    PutWindowTilemap(WIN_BERRY_TAG_berry_tag_screen);
    ScheduleBgCopyTilemapToVram(0);
}

static void PrintAllBerryData_berry_tag_screen(void)
{
    PrintBerryNumberAndName_berry_tag_screen();
    PrintBerrySize_berry_tag_screen();
    PrintBerryFirmness_berry_tag_screen();
    PrintBerryDescription1_berry_tag_screen();
    PrintBerryDescription2_berry_tag_screen();
}

static void PrintBerryNumberAndName_berry_tag_screen(void)
{
    const struct Berry *berry = GetBerryInfo(sBerryTag_berry_tag_screen->berryId);
    ConvertIntToDecimalStringN(gStringVar1, sBerryTag_berry_tag_screen->berryId, STR_CONV_MODE_LEADING_ZEROS, 2);
    StringCopy(gStringVar2, berry->name);
    StringExpandPlaceholders(gStringVar4, sText_NumberVar1Var2_berry_tag_screen);
    PrintTextInBerryTagScreen_berry_tag_screen(WIN_BERRY_NAME_berry_tag_screen, gStringVar4, 0, 1, 0, 0);
}

static void PrintBerrySize_berry_tag_screen(void)
{
    const struct Berry *berry = GetBerryInfo(sBerryTag_berry_tag_screen->berryId);
    AddTextPrinterParameterized(WIN_SIZE_FIRM_berry_tag_screen, FONT_NORMAL, sText_SizeSlash_berry_tag_screen, 0, 1, TEXT_SKIP_DRAW, NULL);
    if (berry->size != 0)
    {
        u32 inches, fraction;

        inches = 1000 * berry->size / 254;
        if (inches % 10 > 4)
            inches += 10;
        fraction = (inches % 100) / 10;
        inches /= 100;

        ConvertIntToDecimalStringN(gStringVar1, inches, STR_CONV_MODE_LEFT_ALIGN, 2);
        ConvertIntToDecimalStringN(gStringVar2, fraction, STR_CONV_MODE_LEFT_ALIGN, 2);
        StringExpandPlaceholders(gStringVar4, sText_Var1DotVar2_berry_tag_screen);
        AddTextPrinterParameterized(WIN_SIZE_FIRM_berry_tag_screen, FONT_NORMAL, gStringVar4, 0x28, 1, 0, NULL);
    }
    else
    {
        AddTextPrinterParameterized(WIN_SIZE_FIRM_berry_tag_screen, FONT_NORMAL, sText_ThreeMarks_berry_tag_screen, 0x28, 1, 0, NULL);
    }
}

