s32 ChangeBgX(u32 bg, s32 value, u8 op)
{
    u32 mode;
    u16 temp1;
    u16 temp2;

    if (IsInvalidBg(bg) || !GetBgControlAttribute_bg(bg, BG_CTRL_ATTR_VISIBLE_bg))
    {
        return -1;
    }

    switch (op)
    {
    case BG_COORD_SET:
    default:
        sGpuBgConfigs2_bg[bg].bg_x = value;
        break;
    case BG_COORD_ADD:
        sGpuBgConfigs2_bg[bg].bg_x += value;
        break;
    case BG_COORD_SUB:
        sGpuBgConfigs2_bg[bg].bg_x -= value;
        break;
    }

    mode = GetBgMode();

    switch (bg)
    {
    case 0:
        temp1 = sGpuBgConfigs2_bg[0].bg_x >> 0x8;
        SetGpuReg(REG_OFFSET_BG0HOFS, temp1);
        break;
    case 1:
        temp1 = sGpuBgConfigs2_bg[1].bg_x >> 0x8;
        SetGpuReg(REG_OFFSET_BG1HOFS, temp1);
        break;
    case 2:
        if (mode == 0)
        {
            temp1 = sGpuBgConfigs2_bg[2].bg_x >> 0x8;
            SetGpuReg(REG_OFFSET_BG2HOFS, temp1);
        }
        else
        {
            temp1 = sGpuBgConfigs2_bg[2].bg_x >> 0x10;
            temp2 = sGpuBgConfigs2_bg[2].bg_x & 0xFFFF;
            SetGpuReg(REG_OFFSET_BG2X_H, temp1);
            SetGpuReg(REG_OFFSET_BG2X_L, temp2);
        }
        break;
    case 3:
        if (mode == 0)
        {
            temp1 = sGpuBgConfigs2_bg[3].bg_x >> 0x8;
            SetGpuReg(REG_OFFSET_BG3HOFS, temp1);
        }
        else if (mode == 2)
        {
            temp1 = sGpuBgConfigs2_bg[3].bg_x >> 0x10;
            temp2 = sGpuBgConfigs2_bg[3].bg_x & 0xFFFF;
            SetGpuReg(REG_OFFSET_BG3X_H, temp1);
            SetGpuReg(REG_OFFSET_BG3X_L, temp2);
        }
        break;
    }

    return sGpuBgConfigs2_bg[bg].bg_x;
}

