void DoSealedChamberShakingEffect_Long(void)
{
    u8 taskId = CreateTask(Task_SealedChamberShakingEffect_braille_puzzles, 9);

    gTasks[taskId].tDelayCounter_braille_puzzles = 0;
    gTasks[taskId].tShakeCounter_braille_puzzles = 0;
    gTasks[taskId].tVerticalPan_braille_puzzles = 2;
    gTasks[taskId].tDelay_braille_puzzles = 5;
    gTasks[taskId].tNumShakes_braille_puzzles = 50;
    SetCameraPanningCallback(0);
}

void DoSealedChamberShakingEffect_Short(void)
{
    u8 taskId = CreateTask(Task_SealedChamberShakingEffect_braille_puzzles, 9);

    gTasks[taskId].tDelayCounter_braille_puzzles = 0;
    gTasks[taskId].tShakeCounter_braille_puzzles = 0;
    gTasks[taskId].tVerticalPan_braille_puzzles = 3;
    gTasks[taskId].tDelay_braille_puzzles = 5;
    gTasks[taskId].tNumShakes_braille_puzzles = 2;
    SetCameraPanningCallback(0);
}

static void Task_SealedChamberShakingEffect_braille_puzzles(u8 taskId)
{
    struct Task *task = &gTasks[taskId];

    task->tDelayCounter_braille_puzzles++;
    if (task->tDelayCounter_braille_puzzles % task->tDelay_braille_puzzles == 0)
    {
        task->tDelayCounter_braille_puzzles = 0;
        task->tShakeCounter_braille_puzzles++;
        task->tVerticalPan_braille_puzzles = -task->tVerticalPan_braille_puzzles;
        SetCameraPanning(0, task->tVerticalPan_braille_puzzles);
        if (task->tShakeCounter_braille_puzzles == task->tNumShakes_braille_puzzles)
        {
            DestroyTask(taskId);
            ScriptContext_Enable();
            InstallCameraPanAheadCallback();
        }
    }
}

