static void Task_LoadCableCar_cable_car(u8 taskId)
{
    if (!gPaletteFade.active)
    {
        SetMainCallback2(CB2_LoadCableCar_cable_car);
        DestroyTask(taskId);
    }
}

void CableCar(void)
{
    LockPlayerFieldControls();
    CreateTask(Task_LoadCableCar_cable_car, 1);
    BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
}

static void CB2_LoadCableCar_cable_car(void)
{
    u16 imebak;
    u8 i = 0;
    u32 sizeOut = 0;

    switch (gMain.state)
    {
    case 0:
    default:
        SetVBlankCallback(NULL);
        SetBgRegs_cable_car(FALSE);
        ScanlineEffect_Stop();
        DmaFillLarge16(3, 0, (void *)VRAM, VRAM_SIZE, 0x1000);
        DmaFill32Defvars(3, 0, (void *)OAM, OAM_SIZE);
        DmaFill16Defvars(3, 0, (void *)PLTT, PLTT_SIZE);
        sCableCar_cable_car = AllocZeroed(sizeof(*sCableCar_cable_car));
        gMain.state++;
        break;
    case 1:
        ResetSpriteData();
        ResetTasks();
        FreeAllSpritePalettes();
        ResetPaletteFade();
        ResetTempTileDataBuffers();
        StartWeather();
        for (i = 0; i < NUM_ASH_SPRITES; i++)
            gWeatherPtr->sprites.s2.ashSprites[i] = NULL;

        InitMapMusic();
        ResetMapMusic();
        ResetBgsAndClearDma3BusyFlags(0);
        InitBgsFromTemplates(0, sBgTemplates_cable_car, ARRAY_COUNT(sBgTemplates_cable_car));
        SetBgTilemapBuffer(0, sCableCar_cable_car->bgTilemapBuffers[0]);
        SetBgTilemapBuffer(1, sCableCar_cable_car->bgTilemapBuffers[1]);
        SetBgTilemapBuffer(2, sCableCar_cable_car->bgTilemapBuffers[2]);
        SetBgTilemapBuffer(3, sCableCar_cable_car->bgTilemapBuffers[3]);
        gSpriteCoordOffsetX = gSpriteCoordOffsetY = 0;
        gMain.state++;
        break;
    case 2:
        for (i = 0; i < ARRAY_COUNT(sSpriteSheets_cable_car) - 1; i++)
            LoadCompressedSpriteSheet(&sSpriteSheets_cable_car[i]);

        LoadSpritePalettes(sSpritePalettes_cable_car);
        sCableCar_cable_car->groundTilemap = malloc_and_decompress(sGround_Tilemap_cable_car, &sizeOut);
        sCableCar_cable_car->treesTilemap = malloc_and_decompress(sTrees_Tilemap_cable_car, &sizeOut);
        sCableCar_cable_car->bgMountainsTilemap = malloc_and_decompress(sBgMountains_Tilemap_cable_car, &sizeOut);
        sCableCar_cable_car->pylonPoleTilemap = malloc_and_decompress(sPylonPole_Tilemap_cable_car, &sizeOut);
        sCableCar_cable_car->pylonTopTilemap = sPylonTop_Tilemap_cable_car;
        DecompressAndCopyTileDataToVram(0, gCableCarBg_Gfx, 0, 0, 0);
        gMain.state++;
        break;
    case 3:
        if (!FreeTempTileDataBuffersIfPossible())
        {
            LoadPalette(gCableCarBg_Pal, BG_PLTT_ID(0), 4 * PLTT_SIZE_4BPP);
            gMain.state++;
        }
        break;
    case 4:
        CreateCableCarSprites_cable_car();
        RunTasks();
        gMain.state++;
        break;
    case 5:
        if (sCableCar_cable_car->weather == WEATHER_VOLCANIC_ASH)
        {
            gMain.state++;
        }
        else if (gWeatherPtr->sprites.s2.ashSprites[0])
        {
            for (i = 0; i < NUM_ASH_SPRITES; i++)
            {
                if (gWeatherPtr->sprites.s2.ashSprites[i])
                    gWeatherPtr->sprites.s2.ashSprites[i]->oam.priority = 0;
            }

            gMain.state++;
        }
        break;
    case 6:
        CopyToBgTilemapBufferRect_ChangePalette(1, sCableCar_cable_car->treesTilemap, 0, 17, 32, 15, 17);
        CopyToBgTilemapBufferRect_ChangePalette(2, sCableCar_cable_car->bgMountainsTilemap, 0, 0, 30, 20, 17);
        CopyToBgTilemapBufferRect_ChangePalette(3, sCableCar_cable_car->pylonTopTilemap, 0, 0, 5, 2, 17);
        CopyToBgTilemapBufferRect_ChangePalette(3, sCableCar_cable_car->pylonPoleTilemap, 0, 2, 2, 20, 17);
        gMain.state++;
        break;
    case 7:
        InitGroundTilemapData_cable_car(GOING_DOWN_cable_car);
        CopyToBgTilemapBufferRect_ChangePalette(0, sCableCar_cable_car->groundTilemap +  0x48,  0, 14, 12, 3, 17);
        CopyToBgTilemapBufferRect_ChangePalette(0, sCableCar_cable_car->groundTilemap +  0x6C, 12, 17, 12, 3, 17);
        CopyToBgTilemapBufferRect_ChangePalette(0, sCableCar_cable_car->groundTilemap +  0x90, 24, 20, 12, 3, 17);
        CopyToBgTilemapBufferRect_ChangePalette(0, sCableCar_cable_car->groundTilemap +   0x0,  0, 17, 12, 3, 17);
        CopyToBgTilemapBufferRect_ChangePalette(0, sCableCar_cable_car->groundTilemap +  0x24,  0, 20, 12, 3, 17);
        CopyToBgTilemapBufferRect_ChangePalette(0, sCableCar_cable_car->groundTilemap +   0x0, 12, 20, 12, 3, 17);
        CopyToBgTilemapBufferRect_ChangePalette(0, sCableCar_cable_car->groundTilemap +  0x24, 12, 23, 12, 3, 17);
        CopyToBgTilemapBufferRect_ChangePalette(0, sCableCar_cable_car->groundTilemap +   0x0, 24, 23, 12, 3, 17);
        gMain.state++;
        break;
    case 8:
        BeginNormalPaletteFade(PALETTES_ALL, 3, 16, 0, RGB_BLACK);
        FadeInNewBGM(MUS_CABLE_CAR, 1);
        SetBgRegs_cable_car(TRUE);
        gMain.state++;
        break;
    case 9:
        imebak = REG_IME;
        REG_IME = 0;
        REG_IE |= INTR_FLAG_VBLANK;
        REG_IME = imebak;
        SetVBlankCallback(VBlankCB_CableCar_cable_car);
        SetMainCallback2(CB2_CableCar_cable_car);
        CreateTask(Task_CableCar_cable_car, 0);
        if (!GOING_DOWN_cable_car)
            sCableCar_cable_car->bgTaskId = CreateTask(Task_AnimateBgGoingUp_cable_car, 1);
        else
            sCableCar_cable_car->bgTaskId = CreateTask(Task_AnimateBgGoingDown_cable_car, 1);
        break;
    }
}

static void CB2_CableCar_cable_car(void)
{
    RunTasks();
    AnimateSprites();
    BuildOamBuffer();
    UpdatePaletteFade();
    MapMusicMain();
}

static void CB2_EndCableCar_cable_car(void)
{
    u8 i = 0;

    HideBg(0);
    HideBg(1);
    HideBg(2);
    HideBg(3);
    SetBgRegs_cable_car(FALSE);
    gSpriteCoordOffsetX = 0;
    SetCurrentAndNextWeatherNoDelay(WEATHER_NONE);
    for (i = 0; i < NUM_ASH_SPRITES; i++)
        gWeatherPtr->sprites.s2.ashSprites[i] = NULL;

    ResetTasks();
    ResetSpriteData();
    ResetPaletteFade();
    UnsetBgTilemapBuffer(0);
    UnsetBgTilemapBuffer(1);
    UnsetBgTilemapBuffer(2);
    UnsetBgTilemapBuffer(3);
    ResetBgsAndClearDma3BusyFlags(0);
    sCableCar_cable_car->pylonTopTilemap = NULL;
    FREE_AND_SET_NULL(sCableCar_cable_car->pylonPoleTilemap);
    FREE_AND_SET_NULL(sCableCar_cable_car->bgMountainsTilemap);
    FREE_AND_SET_NULL(sCableCar_cable_car->treesTilemap);
    FREE_AND_SET_NULL(sCableCar_cable_car->groundTilemap);
    FREE_AND_SET_NULL(sCableCar_cable_car);
    DmaFillLarge16(3, 0, (void *)VRAM, VRAM_SIZE, 0x1000);
    DmaFill32Defvars(3, 0, (void *)OAM, OAM_SIZE);
    DmaFill16Defvars(3, 0, (void *)PLTT, PLTT_SIZE);
    WarpIntoMap();
    gFieldCallback = NULL;
    SetMainCallback2(CB2_LoadMap);
}

static void Task_CableCar_cable_car(u8 taskId)
{
    u8 i = 0;

    sCableCar_cable_car->timer++;
    switch (sCableCar_cable_car->state)
    {
    case 0:
        // Wait to change weather
        if (sCableCar_cable_car->timer == sCableCar_cable_car->weatherDelay)
        {
            SetNextWeather(sCableCar_cable_car->weather);
            sCableCar_cable_car->state = 1;
        }
        break;
    case 1:
        // Update ash sprites
        switch (sCableCar_cable_car->weather)
        {
        case WEATHER_VOLCANIC_ASH:
            if (gWeatherPtr->sprites.s2.ashSprites[0] != NULL && gWeatherPtr->sprites.s2.ashSprites[0]->oam.priority != 0)
            {
                for (; i < NUM_ASH_SPRITES; i++)
                {
                    if (gWeatherPtr->sprites.s2.ashSprites[i])
                        gWeatherPtr->sprites.s2.ashSprites[i]->oam.priority = 0;
                }

                sCableCar_cable_car->state = 2;
            }
            break;
        case WEATHER_SUNNY:
            if (gWeatherPtr->currWeather == WEATHER_SUNNY)
            {
                sCableCar_cable_car->state = 2;
            }
            else if (sCableCar_cable_car->timer >= sCableCar_cable_car->weatherDelay + 8)
            {
                for (; i < NUM_ASH_SPRITES; i++)
                {
                    if (gWeatherPtr->sprites.s2.ashSprites[i])
                        gWeatherPtr->sprites.s2.ashSprites[i]->invisible ^= 1;
                }
            }
            break;
        }
        break;
    case 2:
        // Wait to fade out
        if (sCableCar_cable_car->timer == 570)
        {
            sCableCar_cable_car->state = 3;
            BeginNormalPaletteFade(PALETTES_ALL, 3, 0, 16, RGB_BLACK);
            FadeOutBGM(4);
        }
        break;
    case 3:
        // Wait for fade out
        if (!gPaletteFade.active)
            sCableCar_cable_car->state = STATE_END_cable_car;
        break;
    case STATE_END_cable_car:
        SetVBlankCallback(NULL);
        DestroyTask(taskId);
        DestroyTask(sCableCar_cable_car->bgTaskId);
        SetMainCallback2(CB2_EndCableCar_cable_car);
        break;
    }
}

static void Task_AnimateBgGoingUp_cable_car(u8 taskId)
{
    if (sCableCar_cable_car->state != STATE_END_cable_car)
    {
        sCableCar_cable_car->bg3HorizontalOffset--;
        if ((sCableCar_cable_car->timer % 2) == 0)
            sCableCar_cable_car->bg3VerticalOffset--;

        if ((sCableCar_cable_car->timer % 8) == 0)
        {
            sCableCar_cable_car->bg1HorizontalOffset--;
            sCableCar_cable_car->bg1VerticalOffset--;
        }

        switch (sCableCar_cable_car->bg3HorizontalOffset)
        {
        case 175:
            FillBgTilemapBufferRect(3, 0, 0, 22, 2, 10, 17);
            break;
        case 40:
            FillBgTilemapBufferRect(3, 0, 3, 0, 2, 2, 17);
            break;
        case 32:
            FillBgTilemapBufferRect(3, 0, 2, 0, 1, 2, 17);
            break;
        case 16:
            CopyToBgTilemapBufferRect_ChangePalette(3, sCableCar_cable_car->pylonTopTilemap, 0, 0, 5,  2, 17);
            CopyToBgTilemapBufferRect_ChangePalette(3, sCableCar_cable_car->pylonPoleTilemap, 0, 2, 2, 30, 17);
            sCableCar_cable_car->bg3VerticalOffset = 64;
            break;
        }
    }

    AnimateGroundGoingUp_cable_car();
    gSpriteCoordOffsetX = (gSpriteCoordOffsetX + 1) % 128;
}

static void Task_AnimateBgGoingDown_cable_car(u8 taskId)
{
    if (sCableCar_cable_car->state != STATE_END_cable_car)
    {
        sCableCar_cable_car->bg3HorizontalOffset++;
        if ((sCableCar_cable_car->timer % 2) == 0)
            sCableCar_cable_car->bg3VerticalOffset++;

        if ((sCableCar_cable_car->timer % 8) == 0)
        {
            sCableCar_cable_car->bg1HorizontalOffset++;
            sCableCar_cable_car->bg1VerticalOffset++;
        }

        switch (sCableCar_cable_car->bg3HorizontalOffset)
        {
        case 176:
            CopyToBgTilemapBufferRect_ChangePalette(3, sCableCar_cable_car->pylonPoleTilemap, 0, 2, 2, 30, 17);
            break;
        case 16:
            FillBgTilemapBufferRect(3, 0, 2,  0, 3,  2, 17);
            FillBgTilemapBufferRect(3, 0, 0, 22, 2, 10, 17);
            sCableCar_cable_car->bg3VerticalOffset = 192;
            break;
        case 32:
            FillBgTilemapBufferRect(3, sCableCar_cable_car->pylonTopTilemap[2], 2, 0, 1, 1, 17);
            FillBgTilemapBufferRect(3, sCableCar_cable_car->pylonTopTilemap[3], 3, 0, 1, 1, 17);
            FillBgTilemapBufferRect(3, sCableCar_cable_car->pylonTopTilemap[7], 2, 1, 1, 1, 17);
            FillBgTilemapBufferRect(3, sCableCar_cable_car->pylonTopTilemap[8], 3, 1, 1, 1, 17);
            break;
        case 40:
            FillBgTilemapBufferRect(3, sCableCar_cable_car->pylonTopTilemap[4], 4, 0, 1, 1, 17);
            FillBgTilemapBufferRect(3, sCableCar_cable_car->pylonTopTilemap[9], 4, 1, 1, 1, 17);
            break;
        }
    }

    AnimateGroundGoingDown_cable_car();
    if (sCableCar_cable_car->timer < sCableCar_cable_car->weatherDelay)
        gSpriteCoordOffsetX = (gSpriteCoordOffsetX + 247) % 248;
    else
        gWeatherPtr->ashBaseSpritesX = (gWeatherPtr->ashBaseSpritesX + 247) % 248;
}

static void VBlankCB_CableCar_cable_car(void)
{
    CopyBgTilemapBufferToVram(0);
    CopyBgTilemapBufferToVram(3);
    SetGpuReg(REG_OFFSET_BG3HOFS, sCableCar_cable_car->bg3HorizontalOffset);
    SetGpuReg(REG_OFFSET_BG3VOFS, sCableCar_cable_car->bg3VerticalOffset);
    SetGpuReg(REG_OFFSET_BG1HOFS, sCableCar_cable_car->bg1HorizontalOffset);
    SetGpuReg(REG_OFFSET_BG1VOFS, sCableCar_cable_car->bg1VerticalOffset);
    SetGpuReg(REG_OFFSET_BG0HOFS, sCableCar_cable_car->bg0HorizontalOffset);
    SetGpuReg(REG_OFFSET_BG0VOFS, sCableCar_cable_car->bg0VerticalOffset);
    LoadOam();
    ProcessSpriteCopyRequests();
    TransferPlttBuffer();
}

static void SpriteCB_Cable_cable_car(struct Sprite *sprite)
{

}

#define sXPos_cable_car  data[0]
#define sYPos_cable_car  data[1]

static void SpriteCB_CableCar_cable_car(struct Sprite *sprite)
{
    if (sCableCar_cable_car->state != STATE_END_cable_car)
    {
        if (!GOING_DOWN_cable_car)
        {
            sprite->x = sprite->sXPos_cable_car - (u8)(0.14f * S16TOPOSFLOAT(sCableCar_cable_car->timer));
            sprite->y = sprite->sYPos_cable_car - (u8)(0.067f * S16TOPOSFLOAT(sCableCar_cable_car->timer));
        }
        else
        {
            sprite->x = sprite->sXPos_cable_car + (u8)(0.14f * S16TOPOSFLOAT(sCableCar_cable_car->timer));
            sprite->y = sprite->sYPos_cable_car + (u8)(0.067f * S16TOPOSFLOAT(sCableCar_cable_car->timer));
        }
    }
}

#define sState_cable_car data[2]
#define sTimer_cable_car data[3]

static void SpriteCB_Player_cable_car(struct Sprite *sprite)
{
    if (sCableCar_cable_car->state != STATE_END_cable_car)
    {
        // Move along with cable car
        if (!GOING_DOWN_cable_car)
        {
            sprite->x = sprite->sXPos_cable_car - (u8)(0.14f * S16TOPOSFLOAT(sCableCar_cable_car->timer));
            sprite->y = sprite->sYPos_cable_car - (u8)(0.067f * S16TOPOSFLOAT(sCableCar_cable_car->timer));
        }
        else
        {
            sprite->x = sprite->sXPos_cable_car + (u8)(0.14f * S16TOPOSFLOAT(sCableCar_cable_car->timer));
            sprite->y = sprite->sYPos_cable_car + (u8)(0.067f * S16TOPOSFLOAT(sCableCar_cable_car->timer));
        }

        // Bounce up and down
        switch (sprite->sState_cable_car)
        {
        case 0:
            sprite->y2 = 17;
            if (sprite->sTimer_cable_car++ > 9)
            {
                sprite->sTimer_cable_car = 0;
                sprite->sState_cable_car++;
            }
            break;
        default:
            sprite->y2 = 16;
            if (sprite->sTimer_cable_car++ > 9)
            {
                sprite->sTimer_cable_car = 0;
                sprite->sState_cable_car = 0;
            }
            break;
        }
    }
}

#undef sState_cable_car
#undef sTimer_cable_car

#define sTimer_cable_car      data[0]
#define sSameDir_cable_car    data[1] // Whether or not the hiker is headed the same dir as the Cable Car
#define sDelay_cable_car      data[2]

static void SpriteCB_HikerGoingUp_cable_car(struct Sprite *sprite)
{
    if (sprite->sTimer_cable_car == 0)
    {
        sprite->x += 2 * sprite->centerToCornerVecX;
        sprite->y += 16 + sprite->centerToCornerVecY;
    }

    if (++sprite->sTimer_cable_car >= sprite->sDelay_cable_car)
    {
        switch (sprite->sSameDir_cable_car)
        {
        case FALSE:
            sprite->x++;
            if ((sprite->sTimer_cable_car % 4) == 0)
                sprite->y++;
            break;
        case TRUE:
            // Hiker moves slower if travelling with the Cable Car
            if ((sprite->sTimer_cable_car % 2) != 0)
            {
                sprite->x++;
                if ((sprite->x % 4) == 0)
                    sprite->y++;
            }
            break;
        }

        if (sprite->y > DISPLAY_HEIGHT)
            DestroySprite(sprite);
    }
}

static void SpriteCB_HikerGoingDown_cable_car(struct Sprite *sprite)
{
    if (sprite->sTimer_cable_car == 0)
        sprite->y += 16 + sprite->centerToCornerVecY;

    if (++sprite->sTimer_cable_car >= sprite->sDelay_cable_car)
    {
        switch (sprite->sSameDir_cable_car)
        {
        case FALSE:
            sprite->x--;
            if ((sprite->sTimer_cable_car % 4) == 0)
                sprite->y--;
            break;
        case TRUE:
            // Hiker moves slower if travelling with the Cable Car
            if ((sprite->sTimer_cable_car % 2) != 0)
            {
                sprite->x--;
                if ((sprite->x % 4) == 0)
                    sprite->y--;
            }
            break;
        }

        if (sprite->y < 80)
            DestroySprite(sprite);
    }
}

#undef sTimer_cable_car

static void SetBgRegs_cable_car(bool8 active)
{
    switch (active)
    {
    case FALSE:
    default:
        SetGpuReg(REG_OFFSET_WININ, 0);
        SetGpuReg(REG_OFFSET_WINOUT, 0);
        SetGpuReg(REG_OFFSET_WIN0H, 0);
        SetGpuReg(REG_OFFSET_WIN1H, 0);
        SetGpuReg(REG_OFFSET_WIN0V, 0);
        SetGpuReg(REG_OFFSET_WIN1V, 0);
        SetGpuReg(REG_OFFSET_DISPCNT, 0);
        SetGpuReg(REG_OFFSET_BG3CNT, 0);
        SetGpuReg(REG_OFFSET_BG2CNT, 0);
        SetGpuReg(REG_OFFSET_BG1CNT, 0);
        SetGpuReg(REG_OFFSET_BG0CNT, 0);
        SetGpuReg(REG_OFFSET_BG3HOFS, 0);
        SetGpuReg(REG_OFFSET_BG3VOFS, 0);
        SetGpuReg(REG_OFFSET_BG2HOFS, 0);
        SetGpuReg(REG_OFFSET_BG2VOFS, 0);
        SetGpuReg(REG_OFFSET_BG1HOFS, 0);
        SetGpuReg(REG_OFFSET_BG1VOFS, 0);
        SetGpuReg(REG_OFFSET_BG0HOFS, 0);
        SetGpuReg(REG_OFFSET_BG0VOFS, 0);
        SetGpuReg(REG_OFFSET_BLDCNT, 0);
        break;
    case TRUE:
        SetGpuReg(REG_OFFSET_WININ, 0);
        SetGpuReg(REG_OFFSET_WINOUT, 0);
        SetGpuReg(REG_OFFSET_WIN0H, 0);
        SetGpuReg(REG_OFFSET_WIN1H, 0);
        SetGpuReg(REG_OFFSET_WIN0V, 0);
        SetGpuReg(REG_OFFSET_WIN1V, 0);
        if (!GOING_DOWN_cable_car)
        {
            sCableCar_cable_car->bg3HorizontalOffset = 176;
            sCableCar_cable_car->bg3VerticalOffset = 16;
            sCableCar_cable_car->bg1HorizontalOffset = 0;
            sCableCar_cable_car->bg1VerticalOffset = 80;
            sCableCar_cable_car->bg0VerticalOffset = 0;
            sCableCar_cable_car->bg0VerticalOffset = 0;
        }
        else
        {
            sCableCar_cable_car->bg3HorizontalOffset = 96;
            sCableCar_cable_car->bg3VerticalOffset = 232;
            sCableCar_cable_car->bg1HorizontalOffset = 0;
            sCableCar_cable_car->bg1VerticalOffset = 4;
            sCableCar_cable_car->bg0VerticalOffset = 0;
            sCableCar_cable_car->bg0VerticalOffset = 0;
        }

        SetGpuReg(REG_OFFSET_BG3HOFS, sCableCar_cable_car->bg3HorizontalOffset);
        SetGpuReg(REG_OFFSET_BG3VOFS, sCableCar_cable_car->bg3VerticalOffset);
        SetGpuReg(REG_OFFSET_BG2HOFS, 0);
        SetGpuReg(REG_OFFSET_BG2VOFS, 0);
        SetGpuReg(REG_OFFSET_BG1HOFS, sCableCar_cable_car->bg1HorizontalOffset);
        SetGpuReg(REG_OFFSET_BG1VOFS, sCableCar_cable_car->bg1VerticalOffset);
        SetGpuReg(REG_OFFSET_BG0HOFS, sCableCar_cable_car->bg0HorizontalOffset);
        SetGpuReg(REG_OFFSET_BG0VOFS, sCableCar_cable_car->bg0VerticalOffset);
        SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_OBJ_ON | DISPCNT_OBJ_1D_MAP);
        CopyBgTilemapBufferToVram(1);
        CopyBgTilemapBufferToVram(2);
        ShowBg(0);
        ShowBg(1);
        ShowBg(2);
        ShowBg(3);
        SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_TGT2_ALL);
        break;
    }
}

static void CreateCableCarSprites_cable_car(void)
{
    u8 spriteId;
    u8 i;

    u16 playerGraphicsIds[2] = {
        [MALE]   = OBJ_EVENT_GFX_RIVAL_BRENDAN_NORMAL,
        [FEMALE] = OBJ_EVENT_GFX_RIVAL_MAY_NORMAL
    };
    u16 rval = Random();
    u16 hikerGraphicsIds[4] = {
        OBJ_EVENT_GFX_HIKER,
        OBJ_EVENT_GFX_CAMPER,
        OBJ_EVENT_GFX_PICNICKER,
        OBJ_EVENT_GFX_ZIGZAGOON_1
    };
    s16 hikerCoords[2][2] = {
        {   0,  80 }, // Going up
        { 240, 146 }  // Going down
    };
    u8 hikerMovementDelayTable[4] = { 0, 60, 120, 170};
    void (*hikerCallbacks[2])(struct Sprite *) = {
        SpriteCB_HikerGoingUp_cable_car,
        SpriteCB_HikerGoingDown_cable_car
    };

    switch (GOING_DOWN_cable_car)
    {
        case FALSE:
        default:
            // Create player sprite
            spriteId = CreateObjectGraphicsSprite(playerGraphicsIds[gSaveBlock2Ptr->playerGender], SpriteCB_Player_cable_car, 200, 73, 102);
            if (spriteId != MAX_SPRITES)
            {
                gSprites[spriteId].oam.priority = 2;
                gSprites[spriteId].x2 = 8;
                gSprites[spriteId].y2 = 16;
                gSprites[spriteId].sXPos_cable_car = 200;
                gSprites[spriteId].sYPos_cable_car = 73;
            }
            // Create car sprite
            spriteId = CreateSprite(&sSpriteTemplates_CableCar_cable_car[0], 176, 43, 0x67);
            gSprites[spriteId].x2 = gSprites[spriteId].y2 = 32;
            gSprites[spriteId].sXPos_cable_car = 176;
            gSprites[spriteId].sYPos_cable_car = 43;
            // Create door sprite
            spriteId = CreateSprite(&sSpriteTemplates_CableCar_cable_car[1], 200, 99, 0x65);
            gSprites[spriteId].x2 = 8;
            gSprites[spriteId].y2 = 4;
            gSprites[spriteId].sXPos_cable_car = 200;
            gSprites[spriteId].sYPos_cable_car = 99;
            // Init weather
            sCableCar_cable_car->weather = WEATHER_VOLCANIC_ASH;
            sCableCar_cable_car->weatherDelay = 350;
            SetCurrentAndNextWeatherNoDelay(WEATHER_SUNNY);
            break;
        case TRUE:
            CopyToBgTilemapBufferRect_ChangePalette(0, sCableCar_cable_car->groundTilemap + 0x24, 24, 26, 12, 3, 17);
            // Create player sprite
            spriteId = CreateObjectGraphicsSprite(playerGraphicsIds[gSaveBlock2Ptr->playerGender], SpriteCB_Player_cable_car, 128, 39, 102);
            if (spriteId != MAX_SPRITES)
            {
                gSprites[spriteId].oam.priority = 2;
                gSprites[spriteId].x2 = 8;
                gSprites[spriteId].y2 = 16;
                gSprites[spriteId].sXPos_cable_car = 128;
                gSprites[spriteId].sYPos_cable_car = 39;
            }
            // Create car sprite
            spriteId = CreateSprite(&sSpriteTemplates_CableCar_cable_car[0], 104, 9, 0x67);
            gSprites[spriteId].x2 = gSprites[spriteId].y2 = 32;
            gSprites[spriteId].sXPos_cable_car = 104;
            gSprites[spriteId].sYPos_cable_car = 9;
            // Create door sprite
            spriteId = CreateSprite(&sSpriteTemplates_CableCar_cable_car[1], 128, 65, 0x65);
            gSprites[spriteId].x2 = 8;
            gSprites[spriteId].y2 = 4;
            gSprites[spriteId].sXPos_cable_car = 128;
            gSprites[spriteId].sYPos_cable_car = 65;
            // Init weather
            sCableCar_cable_car->weather = WEATHER_SUNNY;
            sCableCar_cable_car->weatherDelay = 265;
            SetCurrentAndNextWeatherNoDelay(WEATHER_VOLCANIC_ASH);
            break;
    }
    for (i = 0; i < 9; i++)
    {
        spriteId = CreateSprite(&sSpriteTemplate_Cable_cable_car, 16 * i + 96, 8 * i - 8, 0x68);
        gSprites[spriteId].x2 = 8;
        gSprites[spriteId].y2 = 8;
    }

    // 1/64 chance for an NPC to appear hiking on the ground below the Cable Car
    if ((rval % 64) == 0)
    {
        // BUGFIX: The - 1 in the below ARRAY_COUNT means the Zigzagoon is never used
#ifdef BUGFIX
        spriteId = CreateObjectGraphicsSprite(hikerGraphicsIds[rval % ARRAY_COUNT(hikerGraphicsIds)], hikerCallbacks[GOING_DOWN_cable_car], hikerCoords[GOING_DOWN_cable_car][0], hikerCoords[GOING_DOWN_cable_car][1], 106);
#else
        spriteId = CreateObjectGraphicsSprite(hikerGraphicsIds[rval % (ARRAY_COUNT(hikerGraphicsIds) - 1)], hikerCallbacks[GOING_DOWN_cable_car], hikerCoords[GOING_DOWN_cable_car][0], hikerCoords[GOING_DOWN_cable_car][1], 106);
#endif
        if (spriteId != MAX_SPRITES)
        {
            gSprites[spriteId].oam.priority = 2;
            gSprites[spriteId].x2 = -gSprites[spriteId].centerToCornerVecX;
            gSprites[spriteId].y2 = -gSprites[spriteId].centerToCornerVecY;

            // Randomly choose which direction the NPC is going
            if (!GOING_DOWN_cable_car)
            {
                if (rval % 2)
                {
                    StartSpriteAnim(&gSprites[spriteId], ANIM_STD_GO_WEST);
                    gSprites[spriteId].sSameDir_cable_car = TRUE;
                    gSprites[spriteId].y += 2;
                }
                else
                {
                    StartSpriteAnim(&gSprites[spriteId], ANIM_STD_GO_EAST);
                    gSprites[spriteId].sSameDir_cable_car = FALSE;
                }
            }
            else
            {
                if (rval % 2)
                {
                    StartSpriteAnim(&gSprites[spriteId], ANIM_STD_GO_EAST);
                    gSprites[spriteId].sSameDir_cable_car = TRUE;
                    gSprites[spriteId].y += 2;
                }
                else
                {
                    StartSpriteAnim(&gSprites[spriteId], ANIM_STD_GO_WEST);
                    gSprites[spriteId].sSameDir_cable_car = FALSE;
                }
            }
            gSprites[spriteId].sDelay_cable_car = hikerMovementDelayTable[rval % ARRAY_COUNT(hikerMovementDelayTable)];
        }
    }
}

static void BufferNextGroundSegment_cable_car(void)
{
    u8 i, j, k;
    u8 offset;

    for (i = 0, k = 0, offset = 0x24 * (sCableCar_cable_car->groundTilemapOffset + 2); i < 3; i++)
    {
        for (j = 0; j < ARRAY_COUNT(sCableCar_cable_car->groundTileBuffer[0]); j++)
        {
            sCableCar_cable_car->groundTileBuffer[i][j] = sCableCar_cable_car->groundTilemap[offset++];
            sCableCar_cable_car->groundTileBuffer[i + 3][j] = sCableCar_cable_car->groundTilemap[k];
            sCableCar_cable_car->groundTileBuffer[i + 6][j] = (sCableCar_cable_car->groundTilemap + 0x24)[k];
            k++;
        }
    }

    sCableCar_cable_car->groundTilemapOffset = (sCableCar_cable_car->groundTilemapOffset + 1) % 3;
}

static void AnimateGroundGoingUp_cable_car(void)
{
    sCableCar_cable_car->groundTimer = (sCableCar_cable_car->groundTimer + 1) % 96;
    sCableCar_cable_car->bg0HorizontalOffset = sCableCar_cable_car->groundXBase - sCableCar_cable_car->groundXOffset;
    sCableCar_cable_car->bg0VerticalOffset = sCableCar_cable_car->groundYBase - sCableCar_cable_car->groundYOffset;
    sCableCar_cable_car->groundXOffset++;
    if ((sCableCar_cable_car->groundXOffset % 4) == 0)
        sCableCar_cable_car->groundYOffset++;

    if (sCableCar_cable_car->groundXOffset > 16)
        DrawNextGroundSegmentGoingUp_cable_car();
}

static void AnimateGroundGoingDown_cable_car(void)
{
    sCableCar_cable_car->groundTimer = (sCableCar_cable_car->groundTimer + 1) % 96;
    sCableCar_cable_car->bg0HorizontalOffset = sCableCar_cable_car->groundXBase + sCableCar_cable_car->groundXOffset;
    sCableCar_cable_car->bg0VerticalOffset = sCableCar_cable_car->groundYBase + sCableCar_cable_car->groundYOffset;
    sCableCar_cable_car->groundXOffset++;
    if ((sCableCar_cable_car->groundXOffset % 4) == 0)
        sCableCar_cable_car->groundYOffset++;

    if (sCableCar_cable_car->groundXOffset > 16)
        DrawNextGroundSegmentGoingDown_cable_car();
}

static void DrawNextGroundSegmentGoingUp_cable_car(void)
{
    u8 i = 0;

    sCableCar_cable_car->groundXOffset = sCableCar_cable_car->groundYOffset = 0;
    sCableCar_cable_car->groundXBase = sCableCar_cable_car->bg0HorizontalOffset;
    sCableCar_cable_car->groundYBase = sCableCar_cable_car->bg0VerticalOffset;
    sCableCar_cable_car->groundSegmentXStart = (sCableCar_cable_car->groundSegmentXStart + 30) % 32;
    sCableCar_cable_car->groundTileIdx -= 2;
    sGroundSegmentY_Up_cable_car = (sCableCar_cable_car->groundSegmentYStart + 23) % 32;

    // Draw next segment
    for (i = 0; i < ARRAY_COUNT(sCableCar_cable_car->groundTileBuffer); i++)
    {
        sGroundX_Up_cable_car = sCableCar_cable_car->groundSegmentXStart;
        sGroundY_Up_cable_car = (sGroundSegmentY_Up_cable_car + i) % 32;
        FillBgTilemapBufferRect(0, sCableCar_cable_car->groundTileBuffer[i][sCableCar_cable_car->groundTileIdx], sGroundX_Up_cable_car, sGroundY_Up_cable_car, 1, 1, 17);
        sGroundX_Up_cable_car = (sGroundX_Up_cable_car + 1) % 32;
        FillBgTilemapBufferRect(0, sCableCar_cable_car->groundTileBuffer[i][sCableCar_cable_car->groundTileIdx + 1], sGroundX_Up_cable_car, sGroundY_Up_cable_car, 1, 1, 17);
    }

    // Erase old segment
    sGroundX_Up_cable_car = (sCableCar_cable_car->groundSegmentXStart + 30) % 32;
    FillBgTilemapBufferRect(0, 0, sGroundX_Up_cable_car, 0, 2, 32, 17);
    if (sCableCar_cable_car->groundTileIdx == 0)
    {
        sCableCar_cable_car->groundSegmentYStart = (sCableCar_cable_car->groundSegmentYStart + 29) % 32;
        sCableCar_cable_car->groundTileIdx = 12;
        BufferNextGroundSegment_cable_car();
        sGroundX_Up_cable_car = (sCableCar_cable_car->groundSegmentYStart + 1) % 32;
        FillBgTilemapBufferRect(0, 0, 0, sGroundX_Up_cable_car, 32, 9, 17);
    }
}

static void DrawNextGroundSegmentGoingDown_cable_car(void)
{
    u8 i = 0;

    sCableCar_cable_car->groundXOffset = sCableCar_cable_car->groundYOffset = 0;
    sCableCar_cable_car->groundXBase = sCableCar_cable_car->bg0HorizontalOffset;
    sCableCar_cable_car->groundYBase = sCableCar_cable_car->bg0VerticalOffset;
    sCableCar_cable_car->groundSegmentXStart = (sCableCar_cable_car->groundSegmentXStart + 2) % 32;
    sCableCar_cable_car->groundTileIdx += 2;
    sGroundSegmentY_Down_cable_car = sCableCar_cable_car->groundSegmentYStart;

    // Draw next segment
    for (i = 0; i < ARRAY_COUNT(sCableCar_cable_car->groundTileBuffer); i++)
    {
        sGroundX_Down_cable_car = sCableCar_cable_car->groundSegmentXStart;
        sGroundY_Down_cable_car = (sGroundSegmentY_Down_cable_car + i) % 32;
        FillBgTilemapBufferRect(0, sCableCar_cable_car->groundTileBuffer[i][sCableCar_cable_car->groundTileIdx], sGroundX_Down_cable_car, sGroundY_Down_cable_car, 1, 1, 17);
        sGroundX_Down_cable_car = (sGroundX_Down_cable_car + 1) % 32;
        FillBgTilemapBufferRect(0, sCableCar_cable_car->groundTileBuffer[i][sCableCar_cable_car->groundTileIdx + 1], sGroundX_Down_cable_car, sGroundY_Down_cable_car, 1, 1, 17);
    }

    // Erase old segment
    sGroundY_Down_cable_car = (sCableCar_cable_car->groundSegmentYStart + 23) % 32;
    FillBgTilemapBufferRect(0, 0, sCableCar_cable_car->groundSegmentXStart, sGroundY_Down_cable_car, 2, 9, 17);
    if (sCableCar_cable_car->groundTileIdx == 10)
    {
        sCableCar_cable_car->groundSegmentYStart = (sCableCar_cable_car->groundSegmentYStart + 3) % 32;
        sCableCar_cable_car->groundTileIdx = -2;
        BufferNextGroundSegment_cable_car();
    }
}

static void InitGroundTilemapData_cable_car(bool8 goingDown)
{
    switch (goingDown)
    {
        case FALSE:
        default:
            sCableCar_cable_car->groundTilemapOffset = 2;
            sCableCar_cable_car->groundSegmentXStart = 0;
            sCableCar_cable_car->groundSegmentYStart = 20;
            sCableCar_cable_car->groundTileIdx = 12;
            BufferNextGroundSegment_cable_car();
            DrawNextGroundSegmentGoingUp_cable_car();
            break;
        case TRUE:
            sCableCar_cable_car->groundTilemapOffset = 2;
            sCableCar_cable_car->groundSegmentXStart = 28;
            sCableCar_cable_car->groundSegmentYStart = 20;
            sCableCar_cable_car->groundTileIdx = 4;
            BufferNextGroundSegment_cable_car();
            DrawNextGroundSegmentGoingDown_cable_car();
            break;
    }

    sCableCar_cable_car->groundTimer = 0;
}
