// Functionally unused
static u16 GetMoveEffectSymbolTileOffset_contest(u16 move, u8 contestant)
{
    u16 offset;

    switch (gContestEffects[GetMoveContestEffect(move)].effectType)
    {
    case 0:
    case 1:
    case 8:
        offset = 0x9082;
        break;
    case 2:
    case 3:
        offset = 0x9088;
        break;
    default:
        offset = 0x9086;
        break;
    }
    offset += 0x9000 + (contestant << 12);
    return offset;
}

static void PrintContestMoveDescription_contest(u16 move)
{
    u8 category;
    u16 categoryTile;
    u8 numHearts;

    // The contest category icon is implemented as a 5x2 group of tiles.
    category = GetMoveContestCategory(move);
    if      (category == CONTEST_CATEGORY_COOL)
        categoryTile = 0x4040;
    else if (category == CONTEST_CATEGORY_BEAUTY)
        categoryTile = 0x4045;
    else if (category == CONTEST_CATEGORY_CUTE)
        categoryTile = 0x404A;
    else if (category == CONTEST_CATEGORY_SMART)
        categoryTile = 0x406A;
    else
        categoryTile = 0x408A;

    ContestBG_FillBoxWithIncrementingTile_contest(0, categoryTile,        0x0b, 0x1f, 0x05, 0x01, 0x11, 0x01);
    ContestBG_FillBoxWithIncrementingTile_contest(0, categoryTile + 0x10, 0x0b, 0x20, 0x05, 0x01, 0x11, 0x01);

    // Appeal hearts
    if (gContestEffects[GetMoveContestEffect(move)].appeal == 0xFF)
        numHearts = 0;
    else
        numHearts = gContestEffects[GetMoveContestEffect(move)].appeal / 10;
    if (numHearts > MAX_CONTEST_MOVE_HEARTS)
        numHearts = MAX_CONTEST_MOVE_HEARTS;
    ContestBG_FillBoxWithTile_contest(0, TILE_EMPTY_APPEAL_HEART_contest, 0x15, 0x1f, MAX_CONTEST_MOVE_HEARTS, 0x01, 0x11);
    ContestBG_FillBoxWithTile_contest(0, TILE_FILLED_APPEAL_HEART_contest, 0x15, 0x1f, numHearts, 0x01, 0x11);

    // Jam hearts
    if (gContestEffects[GetMoveContestEffect(move)].jam == 0xFF)
        numHearts = 0;
    else
        numHearts = gContestEffects[GetMoveContestEffect(move)].jam / 10;
    if (numHearts > MAX_CONTEST_MOVE_HEARTS)
        numHearts = MAX_CONTEST_MOVE_HEARTS;
    ContestBG_FillBoxWithTile_contest(0, TILE_EMPTY_JAM_HEART_contest, 0x15, 0x20, MAX_CONTEST_MOVE_HEARTS, 0x01, 0x11);
    ContestBG_FillBoxWithTile_contest(0, TILE_FILLED_JAM_HEART_contest, 0x15, 0x20, numHearts, 0x01, 0x11);

    FillWindowPixelBuffer(WIN_MOVE_DESCRIPTION_contest, PIXEL_FILL(0));
    Contest_PrintTextToBg0WindowStd_contest(WIN_MOVE_DESCRIPTION_contest, gContestEffectDescriptionPointers[GetMoveContestEffect(move)]);
    Contest_PrintTextToBg0WindowStd_contest(WIN_SLASH_contest, gText_Slash);
}

