static u16 GetAppealHeartTileOffset_contest(u8 contestant)
{
    u16 offset;

    if (contestant == 0)
        offset = 0x5011;
    else if (contestant == 1)
        offset = 0x6011;
    else if (contestant == 2)
        offset = 0x7011;
    else
        offset = 0x8011;
    return offset + 1;
}

static s8 GetNumHeartsFromAppealPoints_contest(s16 appeal)
{
    s8 hearts = appeal / 10;

    if (hearts > 16)
        hearts = 16;
    else if (hearts < -16)
        hearts = -16;
    return hearts;
}

#define tNumHearts_contest   data[0]
#define tHeartsDelta_contest data[1]
#define tHeartsSign_contest  data[2]
#define tContestant_contest  data[3]
#define tDelayTimer_contest  data[10]

static u8 UpdateAppealHearts_contest(s16 startAppeal, s16 appealDelta, u8 contestant)
{
    u8 taskId;
    s8 startHearts;
    s8 heartsDelta;

    eContestGfxState[contestant].updatingAppealHearts = TRUE;
    taskId = CreateTask(Task_UpdateAppealHearts_contest, 20);
    startHearts = GetNumHeartsFromAppealPoints_contest(startAppeal);
    heartsDelta = GetNumHeartsFromAppealPoints_contest(startAppeal + appealDelta) - startHearts;
    GetAppealHeartTileOffset_contest(contestant);  // unused return value
    gTasks[taskId].tNumHearts_contest = abs(startHearts);
    gTasks[taskId].tHeartsDelta_contest = heartsDelta;
    if (startHearts > 0 || (startHearts == 0 && heartsDelta > 0))
        gTasks[taskId].tHeartsSign_contest = 1;
    else
        gTasks[taskId].tHeartsSign_contest = -1;
    gTasks[taskId].tContestant_contest = contestant;
    return taskId;
}

static void Task_UpdateAppealHearts_contest(u8 taskId)
{
    u8 contestant = gTasks[taskId].tContestant_contest;
    s16 startHearts = gTasks[taskId].tNumHearts_contest;
    s16 heartsDelta = gTasks[taskId].tHeartsDelta_contest;

    if (++gTasks[taskId].tDelayTimer_contest > 14)
    {
        u16 heartOffset;
        u8 newNumHearts;
        u8 pitchMod;
        bool8 onSecondLine;

        gTasks[taskId].tDelayTimer_contest = 0;
        if (gTasks[taskId].tHeartsDelta_contest == 0)
        {
            // No more hearts to add/remove, end
            DestroyTask(taskId);
            eContestGfxState[contestant].updatingAppealHearts = FALSE;
            return;
        }
        else if (startHearts == 0)
        {
            if (heartsDelta < 0)
            {
                // Losing hearts, get black heart offset
                heartOffset = GetAppealHeartTileOffset_contest(contestant) + 2;
                gTasks[taskId].tHeartsDelta_contest++;
            }
            else
            {
                // Gaining hearts, get red heart offset
                heartOffset = GetAppealHeartTileOffset_contest(contestant);
                gTasks[taskId].tHeartsDelta_contest--;
            }
            newNumHearts = gTasks[taskId].tNumHearts_contest++;
        }
        else
        {
            if (gTasks[taskId].tHeartsSign_contest < 0)
            {
                // Hearts currently black (negative)
                if (heartsDelta < 0)
                {
                    // Losing points, add black heart
                    newNumHearts = gTasks[taskId].tNumHearts_contest++;
                    gTasks[taskId].tHeartsDelta_contest++;
                    heartOffset = GetAppealHeartTileOffset_contest(contestant) + 2;
                }
                else
                {
                    // Gaining points, remove black heart
                    newNumHearts = --gTasks[taskId].tNumHearts_contest;
                    heartOffset = 0;
                    gTasks[taskId].tHeartsDelta_contest--;
                }
            }
            else
            {
                // Hearts currently red (positive)
                if (heartsDelta < 0)
                {
                    // Losing points, remove red heart
                    newNumHearts = --gTasks[taskId].tNumHearts_contest;
                    heartOffset = 0;
                    gTasks[taskId].tHeartsDelta_contest++;
                }
                else
                {
                    // Gaining points, add red heart
                    newNumHearts = gTasks[taskId].tNumHearts_contest++;
                    gTasks[taskId].tHeartsDelta_contest--;
                    heartOffset = GetAppealHeartTileOffset_contest(contestant);
                }
            }
        }
        pitchMod = newNumHearts;
        onSecondLine = FALSE;

        // Check if wrapping to second line of hearts
        if (newNumHearts > 7)
        {
            onSecondLine = TRUE;
            newNumHearts -= 8;
        }
        ContestBG_FillBoxWithTile_contest(0, heartOffset, newNumHearts + 22, gContestantTurnOrder[contestant] * 5 + 2 + onSecondLine,  1, 1, 17);
        if (heartsDelta > 0)
        {
            PlaySE(SE_CONTEST_HEART);
            m4aMPlayImmInit(&gMPlayInfo_SE1);
            m4aMPlayPitchControl(&gMPlayInfo_SE1, TRACKS_ALL, pitchMod * 256);
        }
        else
        {
            PlaySE(SE_BOO);
        }

        if (!onSecondLine && newNumHearts == 0 && heartOffset == 0)
            gTasks[taskId].tHeartsSign_contest = -gTasks[taskId].tHeartsSign_contest;
    }
}

