#define sTargetX_contest    data[1]
#define sMoveX_contest      data[2]

static void UpdateHeartSlider_contest(u8 contestant)
{
    u8 spriteId;
    s16 slideTarget;

    eContestGfxState[contestant].sliderUpdating = TRUE;
    spriteId = eContestGfxState[contestant].sliderHeartSpriteId;
    slideTarget = eContestantStatus[contestant].pointTotal / 10 * 2;
    if (slideTarget > 56)
        slideTarget = 56;
    else if (slideTarget < 0)
        slideTarget = 0;
    gSprites[spriteId].invisible = FALSE;
    gSprites[spriteId].sContestant_contest = contestant;
    gSprites[spriteId].sTargetX_contest = slideTarget;
    if (gSprites[spriteId].sTargetX_contest > gSprites[spriteId].x2)
        gSprites[spriteId].sMoveX_contest = 1;
    else
        gSprites[spriteId].sMoveX_contest = -1;
    gSprites[spriteId].callback = SpriteCB_UpdateHeartSlider_contest;
}

static void UpdateHeartSliders_contest(void)
{
    s32 i;

    for (i = 0; i < CONTESTANT_COUNT; i++)
        UpdateHeartSlider_contest(i);
}

static bool8 SlidersDoneUpdating_contest(void)
{
    s32 i;

    for (i = 0; i < CONTESTANT_COUNT; i++)
    {
        if (eContestGfxState[i].sliderUpdating)
            break;
    }
    if (i == CONTESTANT_COUNT)
        return TRUE;
    else
        return FALSE;
}

static void SpriteCB_UpdateHeartSlider_contest(struct Sprite *sprite)
{
    if (sprite->x2 == sprite->sTargetX_contest)
    {
        eContestGfxState[sprite->sContestant_contest].sliderUpdating = FALSE;
        sprite->callback = SpriteCallbackDummy;
    }
    else
    {
        sprite->x2 += sprite->sMoveX_contest;
    }
}

