bool8 AreMovesContestCombo(u16 lastMove, u16 nextMove)
{
    int i;
    u8 lastMoveComboStarterId = GetMoveContestComboStarter(lastMove);

    if (lastMoveComboStarterId == 0)
    {
        return FALSE;
    }
    else
    {
        for (i = 0; i < MAX_COMBO_MOVES; i++)
        {
            if (lastMoveComboStarterId == GetMoveContestComboMoves(nextMove, i))
                return TRUE;
        }
        return FALSE;
    }
}

// A highly appealing move.
static void ContestEffect_HighlyAppealing_contest_effect(void)
{
}

// After this move, the user is more easily startled.
static void ContestEffect_UserMoreEasilyStartled_contest_effect(void)
{
    eContestantStatus[eContestAppealResults.contestant].moreEasilyStartled = TRUE;
    SetContestantEffectStringID(eContestAppealResults.contestant, CONTEST_STRING_MORE_CONSCIOUS);
}

