static void Task_LinkContest_StartInitFlags_contest_link(u8);
static void Task_LinkContest_InitFlags_contest_link(u8);

#define tState_contest_link         data[0]
#define tDelayTimer_contest_link    data[1]
#define tCategories_contest_link(i) data[(i) + 1]
#define tLeaderIds_contest_link(i)  data[(i) + 5]
