{
    int i;

    if (!LinkContest_TryLinkStandby(&gTasks[taskId].tStandbyState_contest_link))
        return;

    switch (gTasks[taskId].tState_contest_link)
    {
    case 0:
        gBlockSendBuffer[0] = gTasks[taskId].tCategory_contest_link;
        if (GetMultiplayerId() == 0)
        {
            if (IsLinkTaskFinished())
                gTasks[taskId].tState_contest_link = 10;
        }
        else
        {
            gTasks[taskId].tState_contest_link++;
        }
        break;
    case 1:
        if (LinkContest_GetBlockReceivedFromAllPlayers())
        {
            for (i = 0; i < gNumLinkContestPlayers; i++)
                gTasks[taskId].tCategories_contest_link(i) = gBlockRecvBuffer[i][0];

            gTasks[taskId].tState_contest_link++;
        }
        break;
    case 10:
        if (++gTasks[taskId].tTimer_contest_link > 10)
        {
            SendBlockRequest(BLOCK_REQ_SIZE_100);
            gTasks[taskId].tState_contest_link = 1;
        }
        break;
    default:
        gTasks[taskId].tState_contest_link = 0;
        gTasks[taskId].tTimer_contest_link = 0;
        gTasks[taskId].tStandbyState_contest_link = 0;
        SwitchTaskToFollowupFunc(taskId);
        break;
    }
}

