void CB2_ContestPainting(void)
{
    ShowContestPainting_contest_painting();
}

static void CB2_HoldContestPainting_contest_painting(void)
{
    HoldContestPainting_contest_painting();
    RunTextPrinters();
    UpdatePaletteFade();
}

static void CB2_QuitContestPainting_contest_painting(void)
{
    SetMainCallback2(gMain.savedCallback);
    FREE_AND_SET_NULL(gContestPaintingMonPalette);
    FREE_AND_SET_NULL(gContestMonPixels);
    RemoveWindow(sWindowId_contest_painting);
    Free(GetBgTilemapBuffer(1));
    FreeMonSpritesGfx();
}

static void ShowContestPainting_contest_painting(void)
{
    switch (gMain.state)
    {
    case 0:
        ScanlineEffect_Stop();
        SetVBlankCallback(NULL);
        AllocateMonSpritesGfx();
        gContestPaintingWinner = &gCurContestWinner;
        InitContestPaintingVars_contest_painting(TRUE);
        InitContestPaintingBg_contest_painting();
        gMain.state++;
        break;
    case 1:
        ResetPaletteFade();
        DmaFillLarge32(3, 0, (void *)VRAM, VRAM_SIZE, 0x1000);
        ResetSpriteData();
        gMain.state++;
        break;
    case 2:
        SeedRng(gMain.vblankCounter1);
        InitKeys();
        InitContestPaintingWindow_contest_painting();
        gMain.state++;
        break;
    case 3:
        CreateContestPaintingPicture_contest_painting(gCurContestWinnerSaveIdx, gCurContestWinnerIsForArtist);
        gMain.state++;
        break;
    case 4:
        PrintContestPaintingCaption_contest_painting(gCurContestWinnerSaveIdx, gCurContestWinnerIsForArtist);
        SetBackdropFromPalette(sBgPalette_contest_painting);
        DmaClear32(3, PLTT, PLTT_SIZE);
        BeginFastPaletteFade(2);
        SetVBlankCallback(VBlankCB_ContestPainting_contest_painting);
        sHoldState_contest_painting = 0;
        SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_MODE_0 | DISPCNT_OBJ_1D_MAP | DISPCNT_BG0_ON | DISPCNT_BG1_ON | DISPCNT_OBJ_ON);
        SetMainCallback2(CB2_HoldContestPainting_contest_painting);
        break;
    }
}

static void HoldContestPainting_contest_painting(void)
{
    switch (sHoldState_contest_painting)
    {
    case 0:
        if (!gPaletteFade.active)
            sHoldState_contest_painting = 1;
        if (sVarsInitialized_contest_painting && sFadeCounter_contest_painting)
            sFadeCounter_contest_painting--;
        break;
    case 1:
        if ((JOY_NEW(A_BUTTON)) || (JOY_NEW(B_BUTTON)))
        {
            sHoldState_contest_painting++;
            BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
        }

        if (sVarsInitialized_contest_painting)
            sFadeCounter_contest_painting = 0;
        break;
    case 2:
        if (!gPaletteFade.active)
            SetMainCallback2(CB2_QuitContestPainting_contest_painting);
        if (sVarsInitialized_contest_painting && sFadeCounter_contest_painting < 30)
            sFadeCounter_contest_painting++;
        break;
    }
}

static void InitContestPaintingWindow_contest_painting(void)
{
    ResetBgsAndClearDma3BusyFlags(0);
    InitBgsFromTemplates(0, sBgTemplates_contest_painting, ARRAY_COUNT(sBgTemplates_contest_painting));
    ChangeBgX(1, 0, BG_COORD_SET);
    ChangeBgY(1, 0, BG_COORD_SET);
    SetBgTilemapBuffer(1, AllocZeroed(BG_SCREEN_SIZE));
    sWindowId_contest_painting = AddWindow(&sWindowTemplate_contest_painting);
    DeactivateAllTextPrinters();
    FillWindowPixelBuffer(sWindowId_contest_painting, PIXEL_FILL(0));
    PutWindowTilemap(sWindowId_contest_painting);
    CopyWindowToVram(sWindowId_contest_painting, COPYWIN_FULL);
    ShowBg(1);
}

static void PrintContestPaintingCaption_contest_painting(u8 contestType, bool8 isForArtist)
{
    int x;
    u8 category;

    // Artist's painting has no caption
    if (isForArtist == TRUE)
        return;

    category = gContestPaintingWinner->contestCategory;
    if (contestType < MUSEUM_CONTEST_WINNERS_START)
    {
        // Contest Hall caption
        BufferContestName(gStringVar1, category);
        StringAppend(gStringVar1, gText_Space);
        StringAppend(gStringVar1, sContestRankNames_contest_painting[gContestPaintingWinner->contestRank]);
        StringCopy(gStringVar2, gContestPaintingWinner->trainerName);
        ConvertInternationalContestantName(gStringVar2);
        StringCopy(gStringVar3, gContestPaintingWinner->monName);
        StringExpandPlaceholders(gStringVar4, gContestHallPaintingCaption);
    }
    else
    {
        // Museum caption
        StringCopy(gStringVar1, gContestPaintingWinner->monName);
        StringExpandPlaceholders(gStringVar4, sMuseumCaptions[category]);
    }

    x = GetStringCenterAlignXOffset(FONT_NORMAL, gStringVar4, 208);
    AddTextPrinterParameterized(sWindowId_contest_painting, FONT_NORMAL, gStringVar4, x, 1, 0, 0);
    CopyBgTilemapBufferToVram(1);
}

static void InitContestPaintingBg_contest_painting(void)
{
    SetGpuReg(REG_OFFSET_DISPCNT, 0);
    REG_IE |= INTR_FLAG_VBLANK;
    SetGpuReg(REG_OFFSET_BG0CNT, BGCNT_PRIORITY(2) | BGCNT_CHARBASE(0) | BGCNT_SCREENBASE(12) | BGCNT_MOSAIC | BGCNT_16COLOR | BGCNT_TXT256x256);
    SetGpuReg(REG_OFFSET_BG1CNT, BGCNT_PRIORITY(1) | BGCNT_CHARBASE(1) | BGCNT_SCREENBASE(10) | BGCNT_MOSAIC | BGCNT_16COLOR | BGCNT_TXT256x256);
    SetGpuReg(REG_OFFSET_BLDCNT, 0);
    SetGpuReg(REG_OFFSET_BLDALPHA, 0);
    SetGpuReg(REG_OFFSET_BLDY, 0);
}

static void InitContestPaintingVars_contest_painting(bool8 reset)
{
    if (reset == FALSE)
    {
        // Never reached
        sVarsInitialized_contest_painting = FALSE;
        sMosaicVal_contest_painting = 0;
        sFadeCounter_contest_painting = 0;
    }
    else
    {
        sVarsInitialized_contest_painting = TRUE;
        sMosaicVal_contest_painting = 15;
        sFadeCounter_contest_painting = 30;
    }
}

static void UpdateContestPaintingMosaicEffect_contest_painting(void)
{
    if (!sVarsInitialized_contest_painting)
    {
        SetGpuReg(REG_OFFSET_MOSAIC, 0);
    }
    else
    {
        SetGpuReg(REG_OFFSET_BG1CNT, BGCNT_PRIORITY(1) | BGCNT_CHARBASE(1) | BGCNT_SCREENBASE(10) | BGCNT_MOSAIC | BGCNT_16COLOR | BGCNT_TXT256x256);
        sMosaicVal_contest_painting = sFadeCounter_contest_painting / 2;
        SetGpuReg(REG_OFFSET_MOSAIC, (sMosaicVal_contest_painting << 12) | (sMosaicVal_contest_painting << 8) | (sMosaicVal_contest_painting << 4) | (sMosaicVal_contest_painting << 0));
    }
}

static void VBlankCB_ContestPainting_contest_painting(void)
{
    UpdateContestPaintingMosaicEffect_contest_painting();
    LoadOam();
    ProcessSpriteCopyRequests();
    TransferPlttBuffer();
}

static void InitContestMonPixels_contest_painting(u16 species, bool8 backPic)
{
    const void *pal = GetMonSpritePalFromSpeciesAndPersonality(species, gContestPaintingWinner->isShiny, gContestPaintingWinner->personality);
    LZDecompressVram(pal, gContestPaintingMonPalette);
    if (!backPic)
    {
        HandleLoadSpecialPokePic(TRUE,
                                gMonSpritesGfxPtr->spritesGfx[B_POSITION_OPPONENT_LEFT],
                                species,
                                gContestPaintingWinner->personality);
        _InitContestMonPixels_contest_painting(gMonSpritesGfxPtr->spritesGfx[B_POSITION_OPPONENT_LEFT], gContestPaintingMonPalette, (void *)gContestMonPixels);
    }
    else
    {
        HandleLoadSpecialPokePic(FALSE,
                                gMonSpritesGfxPtr->spritesGfx[B_POSITION_PLAYER_LEFT],
                                species,
                                gContestPaintingWinner->personality);
        _InitContestMonPixels_contest_painting(gMonSpritesGfxPtr->spritesGfx[B_POSITION_PLAYER_LEFT], gContestPaintingMonPalette, (void *)gContestMonPixels);
    }
}

static void _InitContestMonPixels_contest_painting(u8 *spriteGfx, u16 *palette, u16 (*destPixels)[64][64])
{
    u16 tileY, tileX, pixelY, pixelX;
    u8 colorIndex;

    for (tileY = 0; tileY < 8; tileY++)
    {
        for (tileX = 0; tileX < 8; tileX++)
        {
            for (pixelY = 0; pixelY < 8; pixelY++)
            {
                for (pixelX = 0; pixelX < 8; pixelX++)
                {
                    colorIndex = spriteGfx[32 * (tileY * 8 + tileX) + (pixelY << 2) + (pixelX >> 1)];
                    if (pixelX & 1)
                        colorIndex >>= 4;
                    else
                        colorIndex &= 0xF;

                    if (colorIndex == 0) // transparent pixel
                        (*destPixels)[8 * tileY + pixelY][tileX * 8 + pixelX] = 0x8000;
                    else
                        (*destPixels)[8 * tileY + pixelY][tileX * 8 + pixelX] = palette[colorIndex];
                }
            }
        }
    }
}

#define VRAM_PICTURE_DATA_contest_painting(x, y) (((u16 *)(BG_SCREEN_ADDR(12)))[(y) * 32 + (x)])

static void LoadContestPaintingFrame_contest_painting(u8 contestWinnerId, bool8 isForArtist)
{
    u8 x, y;

    LoadPalette(sPictureFramePalettes_contest_painting, BG_PLTT_ID(0), 8 * PLTT_SIZE_4BPP);
    if (isForArtist == TRUE)
    {
        // Load Artist's frame
        switch (gContestPaintingWinner->contestCategory / NUM_PAINTING_CAPTIONS)
        {
        case CONTEST_CATEGORY_COOL:
            RLUnCompVram(sPictureFrameTiles_Cool_contest_painting, (void *)VRAM);
            RLUnCompWram(sPictureFrameTilemap_Cool_contest_painting, gContestMonPixels);
            break;
        case CONTEST_CATEGORY_BEAUTY:
            RLUnCompVram(sPictureFrameTiles_Beauty_contest_painting, (void *)VRAM);
            RLUnCompWram(sPictureFrameTilemap_Beauty_contest_painting, gContestMonPixels);
            break;
        case CONTEST_CATEGORY_CUTE:
            RLUnCompVram(sPictureFrameTiles_Cute_contest_painting, (void *)VRAM);
            RLUnCompWram(sPictureFrameTilemap_Cute_contest_painting, gContestMonPixels);
            break;
        case CONTEST_CATEGORY_SMART:
            RLUnCompVram(sPictureFrameTiles_Smart_contest_painting, (void *)VRAM);
            RLUnCompWram(sPictureFrameTilemap_Smart_contest_painting, gContestMonPixels);
            break;
        case CONTEST_CATEGORY_TOUGH:
            RLUnCompVram(sPictureFrameTiles_Tough_contest_painting, (void *)VRAM);
            RLUnCompWram(sPictureFrameTilemap_Tough_contest_painting, gContestMonPixels);
            break;
        }

        // Set the background
        for (y = 0; y < 20; y++)
        {
            for (x = 0; x < 32; x++)
                VRAM_PICTURE_DATA_contest_painting(x, y) = 0x1015;
        }

        // Copy the image frame
        for (y = 0; y < 10; y++)
        {
            for (x = 0; x < 18; x++)
                VRAM_PICTURE_DATA_contest_painting(x + 6, y + 2) = (*gContestMonPixels)[y + 2][x + 6];
        }

        // Re-set the entire top row to the first top frame part
        for (x = 0; x < 16; x++)
            VRAM_PICTURE_DATA_contest_painting(x + 7, 2) = (*gContestMonPixels)[2][7];
    }
    else if (contestWinnerId < MUSEUM_CONTEST_WINNERS_START)
    {
        // Load Contest Hall lobby frame
        RLUnCompVram(sPictureFrameTiles_HallLobby_contest_painting, (void *)VRAM);
        RLUnCompVram(sPictureFrameTilemap_HallLobby_contest_painting, (void *)(BG_SCREEN_ADDR(12)));
    }
    else
    {
        // Load Museum frame
        switch (gContestPaintingWinner->contestCategory / NUM_PAINTING_CAPTIONS)
        {
        case CONTEST_CATEGORY_COOL:
            RLUnCompVram(sPictureFrameTiles_Cool_contest_painting, (void *)VRAM);
            RLUnCompVram(sPictureFrameTilemap_Cool_contest_painting, (void *)(BG_SCREEN_ADDR(12)));
            break;
        case CONTEST_CATEGORY_BEAUTY:
            RLUnCompVram(sPictureFrameTiles_Beauty_contest_painting, (void *)VRAM);
            RLUnCompVram(sPictureFrameTilemap_Beauty_contest_painting, (void *)(BG_SCREEN_ADDR(12)));
            break;
        case CONTEST_CATEGORY_CUTE:
            RLUnCompVram(sPictureFrameTiles_Cute_contest_painting, (void *)VRAM);
            RLUnCompVram(sPictureFrameTilemap_Cute_contest_painting, (void *)(BG_SCREEN_ADDR(12)));
            break;
        case CONTEST_CATEGORY_SMART:
            RLUnCompVram(sPictureFrameTiles_Smart_contest_painting, (void *)VRAM);
            RLUnCompVram(sPictureFrameTilemap_Smart_contest_painting, (void *)(BG_SCREEN_ADDR(12)));
            break;
        case CONTEST_CATEGORY_TOUGH:
            RLUnCompVram(sPictureFrameTiles_Tough_contest_painting, (void *)VRAM);
            RLUnCompVram(sPictureFrameTilemap_Tough_contest_painting, (void *)(BG_SCREEN_ADDR(12)));
            break;
        }
    }
}

#undef VRAM_PICTURE_DATA_contest_painting

static void InitPaintingMonOamData_contest_painting(u8 contestWinnerId)
{
    gMain.oamBuffer[0] = sContestPaintingMonOamData_contest_painting;
    gMain.oamBuffer[0].tileNum = 0;

    if (contestWinnerId > 1)
    {
        gMain.oamBuffer[0].x = 88;
        gMain.oamBuffer[0].y = 24;
    }
    else
    {
        gMain.oamBuffer[0].x = 88; // Duplicated code
        gMain.oamBuffer[0].y = 24;
    }
}

static u8 GetImageEffectForContestWinner_contest_painting(u8 contestWinnerId)
{
    u8 contestCategory;

    if (contestWinnerId < MUSEUM_CONTEST_WINNERS_START)
        contestCategory = gContestPaintingWinner->contestCategory;
    else
        contestCategory = gContestPaintingWinner->contestCategory / NUM_PAINTING_CAPTIONS;

    switch (contestCategory)
    {
    case CONTEST_CATEGORY_COOL:
        return IMAGE_EFFECT_OUTLINE_COLORED;
    case CONTEST_CATEGORY_BEAUTY:
        return IMAGE_EFFECT_SHIMMER;
    case CONTEST_CATEGORY_CUTE:
        return IMAGE_EFFECT_POINTILLISM;
    case CONTEST_CATEGORY_SMART:
        return IMAGE_EFFECT_CHARCOAL;
    case CONTEST_CATEGORY_TOUGH:
        return IMAGE_EFFECT_GRAYSCALE_LIGHT;
    }

    return contestCategory;
}

static void AllocPaintingResources_contest_painting(void)
{
    gContestPaintingMonPalette = AllocZeroed(OBJ_PLTT_SIZE);
    gContestMonPixels = AllocZeroed(0x2000);
}

static void DoContestPaintingImageProcessing_contest_painting(u8 imageEffect)
{
    gImageProcessingContext.canvasPixels = gContestMonPixels;
    gImageProcessingContext.canvasPalette = gContestPaintingMonPalette;
    gImageProcessingContext.paletteStart = 0;
    gImageProcessingContext.personality = gContestPaintingWinner->personality % 256;
    gImageProcessingContext.columnStart = 0;
    gImageProcessingContext.rowStart = 0;
    gImageProcessingContext.columnEnd = 64;
    gImageProcessingContext.rowEnd = 64;
    gImageProcessingContext.canvasWidth = 64;
    gImageProcessingContext.canvasHeight = 64;

    switch (imageEffect)
    {
    case IMAGE_EFFECT_CHARCOAL:
    case IMAGE_EFFECT_GRAYSCALE_LIGHT:
        gImageProcessingContext.quantizeEffect = QUANTIZE_EFFECT_GRAYSCALE;
        break;
    case IMAGE_EFFECT_OUTLINE_COLORED:
    case IMAGE_EFFECT_SHIMMER:
    case IMAGE_EFFECT_POINTILLISM:
    default:
        gImageProcessingContext.quantizeEffect = QUANTIZE_EFFECT_STANDARD_LIMITED_COLORS;
        break;
    }

    gImageProcessingContext.var_16 = 2;
    gImageProcessingContext.effect = imageEffect;
    gImageProcessingContext.dest = (void *)OBJ_VRAM0;

    ApplyImageProcessingEffects(&gImageProcessingContext);
    ApplyImageProcessingQuantization(&gImageProcessingContext);
    ConvertImageProcessingToGBA(&gImageProcessingContext);
    LoadPalette(gContestPaintingMonPalette, OBJ_PLTT_ID(0), 16 * PLTT_SIZE_4BPP);
}

static void CreateContestPaintingPicture_contest_painting(u8 contestWinnerId, bool8 isForArtist)
{
    AllocPaintingResources_contest_painting();
    InitContestMonPixels_contest_painting(gContestPaintingWinner->species, FALSE);
    DoContestPaintingImageProcessing_contest_painting(GetImageEffectForContestWinner_contest_painting(contestWinnerId));
    InitPaintingMonOamData_contest_painting(contestWinnerId);
    LoadContestPaintingFrame_contest_painting(contestWinnerId, isForArtist);
}

