static void Task_FlashStarsAndHearts_contest_util(u8 taskId)
{
    if (++gTasks[taskId].tDelay_contest_util == 2)
    {
        gTasks[taskId].tDelay_contest_util = 0;
        if (!gTasks[taskId].tDecreasing_contest_util)
            gTasks[taskId].tCoeff_contest_util++;
        else
            gTasks[taskId].tCoeff_contest_util--;

        if (gTasks[taskId].tCoeff_contest_util == 16)
            gTasks[taskId].tDecreasing_contest_util = TRUE;
        else if (gTasks[taskId].tCoeff_contest_util == 0)
            gTasks[taskId].tDecreasing_contest_util = FALSE;

        BlendPalette(BG_PLTT_ID(6) + 11, 1, gTasks[taskId].tCoeff_contest_util, RGB(30, 22, 11));
        BlendPalette(BG_PLTT_ID(6) + 8, 1, gTasks[taskId].tCoeff_contest_util, RGB_WHITE);
        BlendPalette(BG_PLTT_ID(6) + 14, 1, gTasks[taskId].tCoeff_contest_util, RGB(30, 29, 29));
    }

    if (gTasks[taskId].tCoeff_contest_util == 0)
        sContestResults_contest_util->data->pointsFlashing = FALSE;
    else
        sContestResults_contest_util->data->pointsFlashing = TRUE;
}

static void LoadContestMonIcon_contest_util(u16 species, u8 monIndex, u8 srcOffset, u8 useDmaNow, u32 personality)
{
    const u8 *iconPtr;
    u16 var0, var1;

    iconPtr = GetMonIconPtr(species, personality);
    iconPtr += srcOffset * 0x200 + 0x80;
    if (useDmaNow)
    {
        RequestDma3Copy(iconPtr, (void *)BG_CHAR_ADDR(1) + monIndex * 0x200, 0x180, 1);
        var0 = ((monIndex + 10) << 12);
        var1 = (monIndex * 0x10 + 0x200);
        WriteSequenceToBgTilemapBuffer(1, var1 | var0, 3, monIndex * 3 + 4, 4, 3, 17, 1);
    }
    else
    {
        RequestDma3Copy(iconPtr, (void *)BG_CHAR_ADDR(1) + monIndex * 0x200, 0x180, 1);
    }
}

