static s32 DrawResultsTextWindow_contest_util(const u8 *text, u8 spriteId)
{
    u16 windowId;
    int tileWidth;
    int strWidth;
    u8 *spriteTilePtrs[4];
    u8 *dst;

    struct WindowTemplate windowTemplate;
    memset(&windowTemplate, 0, sizeof(windowTemplate));
    windowTemplate.width = DISPLAY_TILE_WIDTH;
    windowTemplate.height = 2;
    windowId = AddWindow(&windowTemplate);
    FillWindowPixelBuffer(windowId, PIXEL_FILL(1));

    strWidth = GetStringWidth(FONT_NORMAL, text, 0);
    tileWidth = (strWidth + 9) / 8;
    if (tileWidth > DISPLAY_TILE_WIDTH)
        tileWidth = DISPLAY_TILE_WIDTH;

    AddTextPrinterParameterized3(windowId, FONT_NORMAL, (tileWidth * 8 - strWidth) / 2, 1, sContestLinkTextColors_contest_util, TEXT_SKIP_DRAW, text);
    {
        s32 i;
        struct Sprite *sprite;
        const u8 *src, *windowTilesPtr;
        windowTilesPtr = (u8 *)GetWindowAttribute(windowId, WINDOW_TILE_DATA);
        src = (u8 *)sResultsTextWindow_Gfx_contest_util;

        sprite = &gSprites[spriteId];
        spriteTilePtrs[0] = (u8 *)(sprite->oam.tileNum * 32 + OBJ_VRAM0);

        for (i = 1; i < (int)ARRAY_COUNT(spriteTilePtrs); i++)
            spriteTilePtrs[i] = (void *)(gSprites[sprite->data[i - 1]].oam.tileNum * 32 + OBJ_VRAM0);

        for (i = 0; i < (int)ARRAY_COUNT(spriteTilePtrs); i++)
            CpuFill32(0, spriteTilePtrs[i], 0x400);

        dst = spriteTilePtrs[0];
        CpuCopy32(src, dst, 0x20);
        CpuCopy32(src + 128, dst + 0x100, 0x20);
        CpuCopy32(src + 128, dst + 0x200, 0x20);
        CpuCopy32(src + 64,  dst + 0x300, 0x20);

        for (i = 0; i < tileWidth; i++)
        {
            dst = &spriteTilePtrs[(i + 1) / 8][((i + 1) % 8) * 32];
            CpuCopy32(src + 192, dst, 0x20);
            CpuCopy32(windowTilesPtr, dst + 0x100, 0x20);
            CpuCopy32(windowTilesPtr + 960, dst + 0x200, 0x20);
            CpuCopy32(src + 224, dst + 0x300, 0x20);
            windowTilesPtr += 0x20;
        }

        dst = &spriteTilePtrs[(i + 1) / 8][((i + 1) % 8) * 32];
        CpuCopy32(src + 32,  dst, 0x20);
        CpuCopy32(src + 160, dst + 0x100, 0x20);
        CpuCopy32(src + 160, dst + 0x200, 0x20);
        CpuCopy32(src + 96,  dst + 0x300, 0x20);
    }
    RemoveWindow(windowId);

    return (DISPLAY_WIDTH - (tileWidth + 2) * 8) / 2;
}

static void CreateResultsTextWindowSprites_contest_util(void)
{
    int i;
    struct SpriteTemplate template;
    u8 spriteIds[ARRAY_COUNT(sSpriteSheets_ResultsTextWindow_contest_util)];

    template = sSpriteTemplate_ResultsTextWindow_contest_util;
    for (i = 0; i < (int)ARRAY_COUNT(sSpriteSheets_ResultsTextWindow_contest_util); i++)
        LoadSpriteSheet(&sSpriteSheets_ResultsTextWindow_contest_util[i]);

    LoadSpritePalette(&sSpritePalette_ResultsTextWindow_contest_util);

    // Create sprites for the two window types, each made up of 4 sprites
    for (i = 0; i < (int)ARRAY_COUNT(sSpriteSheets_ResultsTextWindow_contest_util); i++)
    {
        spriteIds[i] = CreateSprite(&template, TEXT_BOX_X_contest_util, TEXT_BOX_Y_contest_util, 10);
        template.tileTag++;
    }

    // Save sprite ids of the sliding text box onto its leftmost sprite
    gSprites[spriteIds[0]].data[0] = spriteIds[1];
    gSprites[spriteIds[0]].data[1] = spriteIds[2];
    gSprites[spriteIds[0]].data[2] = spriteIds[3];

    // Save sprite ids of the link text box onto its leftmost sprite
    gSprites[spriteIds[4]].data[0] = spriteIds[5];
    gSprites[spriteIds[4]].data[1] = spriteIds[6];
    gSprites[spriteIds[4]].data[2] = spriteIds[7];

    sContestResults_contest_util->data->slidingTextBoxSpriteId = spriteIds[0];
    sContestResults_contest_util->data->slidingTextBoxState = SLIDING_TEXT_OFFSCREEN_contest_util;
    sContestResults_contest_util->data->linkTextBoxSpriteId = spriteIds[4];
    HideLinkResultsTextBox_contest_util();
}

#define sTargetX_contest_util        data[4]
#define sSlideOutTimer_contest_util  data[5]
#define sSlideIncrement_contest_util data[6]
#define sDistance_contest_util       data[7]

// If slideOutTimer is -1, it will not automatically slide out
static void StartTextBoxSlideIn_contest_util(s16 x, u16 y, u16 slideOutTimer, u16 slideIncrement)
{
    struct Sprite *sprite = &gSprites[sContestResults_contest_util->data->slidingTextBoxSpriteId];
    sprite->x = TEXT_BOX_X_contest_util;
    sprite->y = y;
    sprite->x2 = 0;
    sprite->y2 = 0;
    sprite->sTargetX_contest_util = x + 32;
    sprite->sSlideOutTimer_contest_util = slideOutTimer;
    sprite->sSlideIncrement_contest_util = slideIncrement;
    sprite->sDistance_contest_util = 0;
    sprite->callback = SpriteCB_TextBoxSlideIn_contest_util;
    sContestResults_contest_util->data->slidingTextBoxState = SLIDING_TEXT_ENTERING_contest_util;
}

static void StartTextBoxSlideOut_contest_util(u16 slideIncrement)
{
    struct Sprite *sprite = &gSprites[sContestResults_contest_util->data->slidingTextBoxSpriteId];
    sprite->x += sprite->x2;
    sprite->y += sprite->y2;
    sprite->y2 = 0;
    sprite->x2 = 0;
    sprite->sSlideIncrement_contest_util = slideIncrement;
    sprite->sDistance_contest_util = 0;
    sprite->callback = SpriteCB_TextBoxSlideOut_contest_util;
    sContestResults_contest_util->data->slidingTextBoxState = SLIDING_TEXT_EXITING_contest_util;
}

static void EndTextBoxSlideOut_contest_util(struct Sprite *sprite)
{
    sprite->x = TEXT_BOX_X_contest_util;
    sprite->y = TEXT_BOX_Y_contest_util;
    sprite->y2 = 0;
    sprite->x2 = 0;
    sprite->callback = SpriteCallbackDummy;
    sContestResults_contest_util->data->slidingTextBoxState = SLIDING_TEXT_OFFSCREEN_contest_util;
}

static void SpriteCB_TextBoxSlideIn_contest_util(struct Sprite *sprite)
{
    int i;

    s16 delta = sprite->sDistance_contest_util + sprite->sSlideIncrement_contest_util;
    sprite->x -= delta >> 8;
    sprite->sDistance_contest_util += sprite->sSlideIncrement_contest_util;
    sprite->sDistance_contest_util &= 0xFF;

    // Prevent overshooting target
    if (sprite->x < sprite->sTargetX_contest_util)
        sprite->x = sprite->sTargetX_contest_util;

    for (i = 0; i < 3; i++)
    {
        struct Sprite *sprite2 = &gSprites[sprite->data[i]];
        sprite2->x = sprite->x + sprite->x2 + (i + 1) * 64;
    }

    if (sprite->x == sprite->sTargetX_contest_util)
        sprite->callback = SpriteCB_EndTextBoxSlideIn_contest_util;
}

static void SpriteCB_EndTextBoxSlideIn_contest_util(struct Sprite *sprite)
{
    sContestResults_contest_util->data->slidingTextBoxState = SLIDING_TEXT_ARRIVED_contest_util;
    if ((u16)sprite->sSlideOutTimer_contest_util != 0xFFFF)
    {
        if (--sprite->sSlideOutTimer_contest_util == -1)
            StartTextBoxSlideOut_contest_util(sprite->sSlideIncrement_contest_util);
    }
}

static void SpriteCB_TextBoxSlideOut_contest_util(struct Sprite *sprite)
{
    int i;
    s16 delta;

    delta = sprite->sDistance_contest_util + sprite->sSlideIncrement_contest_util;
    sprite->x -= delta >> 8;
    sprite->sDistance_contest_util += sprite->sSlideIncrement_contest_util;
    sprite->sDistance_contest_util &= 0xFF;
    for (i = 0; i < 3; i++)
    {
        struct Sprite *sprite2 = &gSprites[sprite->data[i]];
        sprite2->x = sprite->x + sprite->x2 + (i + 1) * 64;
    }

    if (sprite->x + sprite->x2 < -224)
        EndTextBoxSlideOut_contest_util(sprite);
}

static void ShowLinkResultsTextBox_contest_util(const u8 *text)
{
    int i;
    u16 x;
    struct Sprite *sprite;

    x = DrawResultsTextWindow_contest_util(text, sContestResults_contest_util->data->linkTextBoxSpriteId);
    sprite = &gSprites[sContestResults_contest_util->data->linkTextBoxSpriteId];
    sprite->x = x + 32;
    sprite->y = 80;
    sprite->invisible = FALSE;
    for (i = 0; i < 3; i++)
    {
        gSprites[sprite->data[i]].x = sprite->x + sprite->x2 + (i + 1) * 64;
        gSprites[sprite->data[i]].y = sprite->y;
        gSprites[sprite->data[i]].invisible = FALSE;
    }

    gBattle_WIN0H = WIN_RANGE(0, DISPLAY_WIDTH);
    gBattle_WIN0V = WIN_RANGE(sprite->y - 16, sprite->y + 16);
    SetGpuReg(REG_OFFSET_WININ, WININ_WIN1_BG_ALL | WININ_WIN1_OBJ | WININ_WIN1_CLR
        | WININ_WIN0_BG1 | WININ_WIN0_BG2 | WININ_WIN0_BG3 | WININ_WIN0_OBJ | WININ_WIN0_CLR);
}

static void HideLinkResultsTextBox_contest_util(void)
{
    int i;
    struct Sprite *sprite;

    sprite = &gSprites[sContestResults_contest_util->data->linkTextBoxSpriteId];
    sprite->invisible = TRUE;
    for (i = 0; i < 3; i++)
        gSprites[sprite->data[i]].invisible = TRUE;

    gBattle_WIN0H = 0;
    gBattle_WIN0V = 0;
    SetGpuReg(REG_OFFSET_WIN0H, gBattle_WIN0H);
    SetGpuReg(REG_OFFSET_WIN0V, gBattle_WIN0V);
    SetGpuReg(REG_OFFSET_WININ, WININ_WIN0_BG_ALL | WININ_WIN0_OBJ | WININ_WIN0_CLR
        | WININ_WIN1_BG_ALL | WININ_WIN1_OBJ | WININ_WIN1_CLR);
}

