static void SpriteCB_WinnerMonSlideIn_contest_util(struct Sprite *sprite)
{
    if (sprite->data[0] < 10)
    {
        if (++sprite->data[0] == 10)
        {
            PlayCry_Normal(sprite->data[1], 0);
            sprite->data[1] = 0;
        }
    }
    else
    {
        s16 delta = sprite->data[1] + 0x600;
        sprite->x -= delta >> 8;
        sprite->data[1] += 0x600;
        sprite->data[1] &= 0xFF;
        if (sprite->x < DISPLAY_WIDTH / 2)
            sprite->x = DISPLAY_WIDTH / 2;

        if (sprite->x == DISPLAY_WIDTH / 2)
        {
            sprite->callback = SpriteCallbackDummy;
            sprite->data[1] = 0;
            sContestResults_contest_util->data->winnerMonSlidingState = SLIDING_MON_ENTERED_contest_util;
        }
    }
}

static void SpriteCB_WinnerMonSlideOut_contest_util(struct Sprite *sprite)
{
    s16 delta = sprite->data[1] + 0x600;
    sprite->x -= delta >> 8;
    sprite->data[1] += + 0x600;
    sprite->data[1] &= 0xFF;
    if (sprite->x < -32)
    {
        sprite->callback = SpriteCallbackDummy;
        sprite->invisible = TRUE;
        sContestResults_contest_util->data->winnerMonSlidingState = SLIDING_MON_EXITED_contest_util;
    }
}

static void Task_CreateConfetti_contest_util(u8 taskId)
{
    if (++gTasks[taskId].data[0] == 5)
    {
        gTasks[taskId].data[0] = 0;
        if (sContestResults_contest_util->data->confettiCount < 40)
        {
            u8 spriteId = CreateSprite(&sSpriteTemplate_Confetti_contest_util, (Random() % DISPLAY_WIDTH) - 20, 44, 5);
            gSprites[spriteId].data[0] = Random() % 512;
            gSprites[spriteId].data[1] = (Random() % 24) + 16;
            gSprites[spriteId].data[2] = (Random() % 256) + 48;
            gSprites[spriteId].oam.tileNum += Random() % 17;
            sContestResults_contest_util->data->confettiCount++;
        }
    }

    if (sContestResults_contest_util->data->destroyConfetti)
        DestroyTask(taskId);
}

static void SpriteCB_Confetti_contest_util(struct Sprite *sprite)
{
    s16 delta;

    sprite->data[3] += sprite->data[0];
    sprite->x2 = Sin(sprite->data[3] >> 8, sprite->data[1]);
    delta = sprite->data[4] + sprite->data[2];
    sprite->x += delta >> 8;
    sprite->data[4] += sprite->data[2];
    sprite->data[4] &= 0xff;

    sprite->y++;
    if (sContestResults_contest_util->data->destroyConfetti)
        sprite->invisible = TRUE;

    if (sprite->x > DISPLAY_WIDTH + 8 || sprite->y > 116)
    {
        DestroySprite(sprite);
        sContestResults_contest_util->data->confettiCount--;
    }
}

