static void CalculateContestantsResultData_contest_util(void)
{
    int i, relativePoints;
    u32 barLength;
    s16 highestPoints;
    s8 round2Points;

    highestPoints = gContestMonTotalPoints[0];
    for (i = 1; i < CONTESTANT_COUNT; i++)
    {
        if (highestPoints < gContestMonTotalPoints[i])
            highestPoints = gContestMonTotalPoints[i];
    }

    if (highestPoints < 0)
    {
        highestPoints = gContestMonTotalPoints[0];
        for (i = 1; i < CONTESTANT_COUNT; i++)
        {
            if (highestPoints > gContestMonTotalPoints[i])
                highestPoints = gContestMonTotalPoints[i];
        }
    }

    for (i = 0; i < CONTESTANT_COUNT; i++)
    {
        relativePoints = (gContestMonRound1Points[i] * 1000) / abs(highestPoints);
        if (relativePoints % 10 > 4)
            relativePoints += 10;
        (*sContestResults_contest_util->monResults)[i].relativePreliminaryPoints = relativePoints / 10;

        relativePoints = (abs(gContestMonRound2Points[i]) * 1000) / abs(highestPoints);
        if (relativePoints % 10 > 4)
            relativePoints += 10;
        (*sContestResults_contest_util->monResults)[i].relativeRound2Points = relativePoints / 10;

        if (gContestMonRound2Points[i] < 0)
            (*sContestResults_contest_util->monResults)[i].lostPoints = TRUE;

        barLength = ((*sContestResults_contest_util->monResults)[i].relativePreliminaryPoints * 0x5800) / 100;
        if ((barLength & 0xFF) > 0x7F)
            barLength += 0x100;
        (*sContestResults_contest_util->monResults)[i].barLengthPreliminary = barLength >> 8;

        barLength = ((*sContestResults_contest_util->monResults)[i].relativeRound2Points * 0x5800) / 100;
        if ((barLength & 0xFF) > 0x7F)
            barLength += 0x100;
        (*sContestResults_contest_util->monResults)[i].barLengthRound2 = barLength >> 8;

        (*sContestResults_contest_util->monResults)[i].numStars = GetNumPreliminaryPoints_contest_util(i, TRUE);
        round2Points = GetNumRound2Points_contest_util(i, TRUE);
        (*sContestResults_contest_util->monResults)[i].numHearts = abs(round2Points);

        if (gContestFinalStandings[i])
        {
            s16 barLengthPreliminary = (*sContestResults_contest_util->monResults)[i].barLengthPreliminary;
            s16 barLengthRound2 = (*sContestResults_contest_util->monResults)[i].barLengthRound2;

            if ((*sContestResults_contest_util->monResults)[i].lostPoints)
                barLengthRound2 *= -1;

            if (barLengthPreliminary + barLengthRound2 == MAX_BAR_LENGTH_contest_util)
            {
                if (barLengthRound2 > 0)
                    (*sContestResults_contest_util->monResults)[i].barLengthRound2--;
                else if (barLengthPreliminary > 0)
                    (*sContestResults_contest_util->monResults)[i].barLengthPreliminary--;
            }
        }
    }
}

#define tMonId_contest_util      data[0]
#define tTarget_contest_util     data[1]
#define tDecreasing_contest_util data[2]

static void UpdateContestResultBars_contest_util(bool8 isRound2, u8 numUpdates)
{
    int i, taskId;
    u32 target;
    u8 numIncreasing = 0, numDecreasing = 0;

    if (!isRound2)
    {
        for (i = 0; i < CONTESTANT_COUNT; i++)
        {
            u8 numStars = (*sContestResults_contest_util->monResults)[i].numStars;
            if (numUpdates < numStars)
            {
                FillBgTilemapBufferRect_Palette0(1, 0x60B3, ((19 + numStars) - numUpdates) - 1, i * 3 + 5, 1, 1);
                taskId = CreateTask(Task_UpdateContestResultBar_contest_util, 10);

                target = (((*sContestResults_contest_util->monResults)[i].barLengthPreliminary << 16) / (*sContestResults_contest_util->monResults)[i].numStars) * (numUpdates + 1);
                if ((target & 0xFFFF) > 0x7FFF)
                    target += 0x10000;

                gTasks[taskId].tMonId_contest_util = i;
                gTasks[taskId].tTarget_contest_util = target >> 16;
                sContestResults_contest_util->data->numBarsUpdating++;
                numIncreasing++;
            }
        }
    }
    else
    {
        for (i = 0; i < CONTESTANT_COUNT; i++)
        {
            s8 numHearts = (*sContestResults_contest_util->monResults)[i].numHearts;
            u32 tile = (*sContestResults_contest_util->monResults)[i].lostPoints ? 0x60A5 : 0x60A3;
            if (numUpdates < numHearts)
            {
                FillBgTilemapBufferRect_Palette0(1, tile, ((19 + numHearts) - numUpdates) - 1, i * 3 + 6, 1, 1);
                taskId = CreateTask(Task_UpdateContestResultBar_contest_util, 10);

                target = (((*sContestResults_contest_util->monResults)[i].barLengthRound2 << 16) / (*sContestResults_contest_util->monResults)[i].numHearts) * (numUpdates + 1);
                if ((target & 0xFFFF) > 0x7FFF)
                    target += 0x10000;

                gTasks[taskId].tMonId_contest_util = i;
                if ((*sContestResults_contest_util->monResults)[i].lostPoints)
                {
                    gTasks[taskId].tDecreasing_contest_util = TRUE;
                    numDecreasing++;
                }
                else
                {
                    numIncreasing++;
                }

                if ((*sContestResults_contest_util->monResults)[i].lostPoints)
                    gTasks[taskId].tTarget_contest_util = -(target >> 16) + (*sContestResults_contest_util->monResults)[i].barLengthPreliminary;
                else
                    gTasks[taskId].tTarget_contest_util = (target >> 16) + (*sContestResults_contest_util->monResults)[i].barLengthPreliminary;

                sContestResults_contest_util->data->numBarsUpdating++;
            }
        }
    }

    if (numDecreasing)
        PlaySE(SE_BOO);
    if (numIncreasing)
        PlaySE(SE_PIN);
}

static void Task_UpdateContestResultBar_contest_util(u8 taskId)
{
    int i;
    bool32 minMaxReached = FALSE;
    bool32 targetReached = FALSE;
    u8 monId = gTasks[taskId].tMonId_contest_util;
    s16 target = gTasks[taskId].tTarget_contest_util;
    s16 decreasing = gTasks[taskId].tDecreasing_contest_util;

    // Has the results bar reached the limit?
    if (decreasing)
    {
        if (sContestResults_contest_util->data->barLength[monId] <= 0)
            minMaxReached = TRUE;
    }
    else
    {
        if (sContestResults_contest_util->data->barLength[monId] >= MAX_BAR_LENGTH_contest_util)
            minMaxReached = TRUE;
    }

    if (sContestResults_contest_util->data->barLength[monId] == target)
        targetReached = TRUE;

    if (!targetReached)
    {
        // Target length has not been reached, update bar length
        if (minMaxReached)
            sContestResults_contest_util->data->barLength[monId] = target;
        else if (decreasing)
            sContestResults_contest_util->data->barLength[monId]--;
        else
            sContestResults_contest_util->data->barLength[monId]++;
    }

    // Update the tiles of the results bar if it's still changing
    if (!minMaxReached && !targetReached)
    {
        u8 tileOffset;
        u16 tileNum;
        for (i = 0; i < NUM_BAR_SEGMENTS_contest_util; i++)
        {
            if (sContestResults_contest_util->data->barLength[monId] >= (i + 1) * BAR_SEGMENT_LENGTH_contest_util)
                tileOffset = 8; // Bar segment is full
            else if (sContestResults_contest_util->data->barLength[monId] >= i * BAR_SEGMENT_LENGTH_contest_util)
                tileOffset = sContestResults_contest_util->data->barLength[monId] % 8; // Bar segment is between full and empty
            else
                tileOffset = 0; // Bar segment is empty

            // The first 4 bar segment tiles are not adjacent in the tileset to the
            // remaining bar segment tiles; choose the base tile number accordingly.
            if (tileOffset < 4)
                tileNum = 0x504C + tileOffset;
            else
                tileNum = 0x5057 + tileOffset;

            FillBgTilemapBufferRect_Palette0(2, tileNum, i + 7, monId * 3 + 6, 1, 1);
        }
    }

    if (targetReached)
    {
        sContestResults_contest_util->data->numBarsUpdating--;
        DestroyTask(taskId);
    }
}

