static void VBlankCB_Credits_credits(void)
{
    LoadOam();
    ProcessSpriteCopyRequests();
    TransferPlttBuffer();
}

static void CB2_Credits_credits(void)
{
    RunTasks();
    AnimateSprites();

    if ((JOY_HELD(B_BUTTON))
     && gHasHallOfFameRecords
     && gTasks[sSavedTaskId_credits].func == Task_CreditsMain_credits)
    {
        // Speed up credits
        VBlankCB_Credits_credits();
        RunTasks();
        AnimateSprites();
        sUsedSpeedUp_credits = TRUE;
    }
    BuildOamBuffer();
    UpdatePaletteFade();
}

static void InitCreditsBgsAndWindows_credits(void)
{
    ResetBgsAndClearDma3BusyFlags(0);
    InitBgsFromTemplates(0, sBackgroundTemplates_credits, ARRAY_COUNT(sBackgroundTemplates_credits));
    SetBgTilemapBuffer(0, AllocZeroed(BG_SCREEN_SIZE));
    LoadPalette(sCredits_Pal_credits, BG_PLTT_ID(8), 2 * PLTT_SIZE_4BPP);
    InitWindows(sWindowTemplates_credits);
    DeactivateAllTextPrinters();
    PutWindowTilemap(0);
    CopyWindowToVram(0, COPYWIN_FULL);
    ShowBg(0);
}

static void FreeCreditsBgsAndWindows_credits(void)
{
    void *ptr;
    FreeAllWindowBuffers();
    ptr = GetBgTilemapBuffer(0);
    if (ptr)
        Free(ptr);
}

static void PrintCreditsText_credits(const u8 *string, u8 y, bool8 isTitle)
{
    u8 x;
    u8 color[3];

    color[0] = TEXT_COLOR_TRANSPARENT;

    if (isTitle == TRUE)
    {
        color[1] = TEXT_COLOR_LIGHT_GRAY;
        color[2] = TEXT_COLOR_RED;
    }
    else
    {
        color[1] = TEXT_COLOR_WHITE;
        color[2] = TEXT_COLOR_DARK_GRAY;
    }

    x = GetStringCenterAlignXOffsetWithLetterSpacing(FONT_NORMAL, string, DISPLAY_WIDTH, 1);
    AddTextPrinterParameterized4(0, FONT_NORMAL, x, y, 1, 0, color, TEXT_SKIP_DRAW, string);
}

#define tMainTaskId_credits data[1]

void CB2_StartCreditsSequence(void)
{
    u8 taskId;
    s16 bikeTaskId;
    u8 pageTaskId;

    ResetGpuAndVram_credits();
    SetVBlankCallback(NULL);
    InitHeap(gHeap, HEAP_SIZE);
    ResetPaletteFade();
    ResetTasks();
    InitCreditsBgsAndWindows_credits();

    taskId = CreateTask(Task_WaitPaletteFade_credits, 0);

    gTasks[taskId].tEndCredits_credits = FALSE;
    gTasks[taskId].tSceneNum_credits = SCENE_OCEAN_MORNING;
    gTasks[taskId].tNextMode_credits = MODE_NONE_credits;
    gTasks[taskId].tCurrentMode_credits = MODE_BIKE_SCENE_credits;

    while (TRUE)
    {
        if (LoadBikeScene_credits(SCENE_OCEAN_MORNING, taskId))
            break;
    }

    bikeTaskId = gTasks[taskId].tTaskId_BikeScene_credits;
    gTasks[bikeTaskId].tState_credits = 40;

    SetGpuReg(REG_OFFSET_BG0VOFS, 0xFFFC);

    pageTaskId = CreateTask(Task_UpdatePage_credits, 0);

    gTasks[pageTaskId].tMainTaskId_credits = taskId;
    gTasks[taskId].tTaskId_UpdatePage_credits = pageTaskId;

    BeginNormalPaletteFade(PALETTES_ALL, 0, 16, 0, RGB_BLACK);
    EnableInterrupts(INTR_FLAG_VBLANK);
    SetVBlankCallback(VBlankCB_Credits_credits);
    m4aSongNumStart(MUS_CREDITS);
    SetMainCallback2(CB2_Credits_credits);
    sUsedSpeedUp_credits = FALSE;
    sCreditsData_credits = AllocZeroed(sizeof(struct CreditsData));

    DeterminePokemonToShow_credits();

    sCreditsData_credits->imgCounter = 0;
    sCreditsData_credits->nextImgPos = POS_LEFT_credits;
    sCreditsData_credits->currShownMon = 0;

    sSavedTaskId_credits = taskId;
}

static void Task_WaitPaletteFade_credits(u8 taskId)
{
    if (!gPaletteFade.active)
        gTasks[taskId].func = Task_CreditsMain_credits;
}

static void Task_CreditsMain_credits(u8 taskId)
{
    u16 mode;

    if (gTasks[taskId].tEndCredits_credits)
    {
        s16 bikeTaskId = gTasks[taskId].tTaskId_BikeScene_credits;
        gTasks[bikeTaskId].tState_credits = 30;

        gTasks[taskId].tTheEndDelay_credits = 256;
        gTasks[taskId].func = Task_CreditsTheEnd1_credits;
        return;
    }

    sUnkVar_credits = 0;
    mode = gTasks[taskId].tNextMode_credits;

    if (gTasks[taskId].tNextMode_credits == MODE_BIKE_SCENE_credits)
    {
        // Start a bike cutscene
        gTasks[taskId].tCurrentMode_credits = mode;
        gTasks[taskId].tNextMode_credits = MODE_NONE_credits;
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
        gTasks[taskId].func = Task_ReadyBikeScene_credits;
    }
    else if (gTasks[taskId].tNextMode_credits == MODE_SHOW_MONS_credits)
    {
        // Start a Pokémon interlude
        gTasks[taskId].tCurrentMode_credits = mode;
        gTasks[taskId].tNextMode_credits = MODE_NONE_credits;
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
        gTasks[taskId].func = Task_ReadyShowMons_credits;
    }
}

static void Task_ReadyBikeScene_credits(u8 taskId)
{
    if (!gPaletteFade.active)
    {
        SetGpuReg(REG_OFFSET_DISPCNT, 0);
        ResetCreditsTasks_credits(taskId);
        gTasks[taskId].func = Task_SetBikeScene_credits;
    }
}

static void Task_SetBikeScene_credits(u8 taskId)
{
    SetVBlankCallback(NULL);

    if (LoadBikeScene_credits(gTasks[taskId].tSceneNum_credits, taskId))
    {
        BeginNormalPaletteFade(PALETTES_ALL, 0, 16, 0, RGB_BLACK);
        EnableInterrupts(INTR_FLAG_VBLANK);
        SetVBlankCallback(VBlankCB_Credits_credits);
        gTasks[taskId].func = Task_WaitPaletteFade_credits;
    }
}

static void Task_ReadyShowMons_credits(u8 taskId)
{
    if (!gPaletteFade.active)
    {
        SetGpuReg(REG_OFFSET_DISPCNT, 0);
        ResetCreditsTasks_credits(taskId);
        gTasks[taskId].func = Task_LoadShowMons_credits;
    }
}

static void Task_LoadShowMons_credits(u8 taskId)
{
    switch (gMain.state)
    {
    default:
    case 0:
    {
        u16 i;
        u16 *temp;

        ResetSpriteData();
        ResetAllPicSprites();
        FreeAllSpritePalettes();
        gReservedSpritePaletteCount = 8;
        LZ77UnCompVram(gBirchBagGrass_Gfx, (void *)VRAM);
        LZ77UnCompVram(gBirchGrassTilemap, (void *)(BG_SCREEN_ADDR(7)));
        LoadPalette(gBirchBagGrass_Pal + 1, BG_PLTT_ID(0) + 1, PLTT_SIZEOF(2 * 16 - 1));

        for (i = 0; i < MON_PIC_SIZE; i++)
            gDecompressionBuffer[i] = 0x11;
        for (i = 0; i < MON_PIC_SIZE; i++)
            (gDecompressionBuffer + MON_PIC_SIZE)[i] = 0x22;
        for (i = 0; i < MON_PIC_SIZE; i++)
            (gDecompressionBuffer + MON_PIC_SIZE * 2)[i] = 0x33;

        temp = (u16 *)(&gDecompressionBuffer[MONBG_OFFSET_credits]);
        temp[0] = RGB_BLACK;
        temp[1] = RGB(31, 31, 20); // light yellow
        temp[2] = RGB(31, 20, 20); // light red
        temp[3] = RGB(20, 20, 31); // light blue

        LoadSpriteSheet(sSpriteSheet_MonBg_credits);
        LoadSpritePalette(sSpritePalette_MonBg_credits);

        gMain.state++;
        break;
    }
    case 1:
        gTasks[taskId].tTaskId_ShowMons_credits = CreateTask(Task_ShowMons_credits, 0);
        gTasks[gTasks[taskId].tTaskId_ShowMons_credits].tState_credits = 1;
        gTasks[gTasks[taskId].tTaskId_ShowMons_credits].tMainTaskId_credits = taskId;
        gTasks[gTasks[taskId].tTaskId_ShowMons_credits].data[2] = gTasks[taskId].tSceneNum_credits; // data[2] never read

        BeginNormalPaletteFade(PALETTES_ALL, 0, 16, 0, RGB_BLACK);
        SetGpuReg(REG_OFFSET_BG3HOFS, 0);
        SetGpuReg(REG_OFFSET_BG3VOFS, 32);
        SetGpuReg(REG_OFFSET_BG3CNT, BGCNT_PRIORITY(3)
                                   | BGCNT_CHARBASE(0)
                                   | BGCNT_SCREENBASE(7)
                                   | BGCNT_16COLOR
                                   | BGCNT_TXT256x256);
        SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_MODE_0
                                    | DISPCNT_OBJ_1D_MAP
                                    | DISPCNT_BG0_ON
                                    | DISPCNT_BG3_ON
                                    | DISPCNT_OBJ_ON);

        gMain.state = 0;
        gIntroCredits_MovingSceneryState = INTROCRED_SCENERY_NORMAL;
        gTasks[taskId].func = Task_WaitPaletteFade_credits;
        break;
    }
}

static void Task_CreditsTheEnd1_credits(u8 taskId)
{
    if (gTasks[taskId].tTheEndDelay_credits)
    {
        gTasks[taskId].tTheEndDelay_credits--;
        return;
    }

    BeginNormalPaletteFade(PALETTES_ALL, 12, 0, 16, RGB_BLACK);
    gTasks[taskId].func = Task_CreditsTheEnd2_credits;
}

static void Task_CreditsTheEnd2_credits(u8 taskId)
{
    if (!gPaletteFade.active)
    {
        ResetCreditsTasks_credits(taskId);
        gTasks[taskId].func = Task_CreditsTheEnd3_credits;
    }
}

#define tDelay_credits data[0]

static void Task_CreditsTheEnd3_credits(u8 taskId)
{
    ResetGpuAndVram_credits();
    ResetPaletteFade();
    LoadTheEndScreen_credits(0, 0x3800, BG_PLTT_ID(0));
    ResetSpriteData();
    FreeAllSpritePalettes();
    BeginNormalPaletteFade(PALETTES_ALL, 8, 16, 0, RGB_BLACK);

    SetGpuReg(REG_OFFSET_BG0CNT, BGCNT_PRIORITY(0)
                               | BGCNT_CHARBASE(0)
                               | BGCNT_SCREENBASE(7)
                               | BGCNT_16COLOR
                               | BGCNT_TXT256x256);
    EnableInterrupts(INTR_FLAG_VBLANK);
    SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_MODE_0
                                | DISPCNT_OBJ_1D_MAP
                                | DISPCNT_BG0_ON);

    gTasks[taskId].tDelay_credits = 235; //set this to 215 to actually show "THE END" in time to the last song beat
    gTasks[taskId].func = Task_CreditsTheEnd4_credits;
}

static void Task_CreditsTheEnd4_credits(u8 taskId)
{
    if (gTasks[taskId].tDelay_credits)
    {
        gTasks[taskId].tDelay_credits--;
        return;
    }

    BeginNormalPaletteFade(PALETTES_ALL, 6, 0, 16, RGB_BLACK);
    gTasks[taskId].func = Task_CreditsTheEnd5_credits;
}

static void Task_CreditsTheEnd5_credits(u8 taskId)
{
    if (!gPaletteFade.active)
    {
        DrawTheEnd_credits(0x3800, 0);

        BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 0, RGB_BLACK);
        gTasks[taskId].tDelay_credits = 7200;
        gTasks[taskId].func = Task_CreditsTheEnd6_credits;
    }
}

static void Task_CreditsTheEnd6_credits(u8 taskId)
{
    if (!gPaletteFade.active)
    {
        if (gTasks[taskId].tDelay_credits == 0 || gMain.newKeys)
        {
            FadeOutBGM(4);
            BeginNormalPaletteFade(PALETTES_ALL, 8, 0, 16, RGB_WHITEALPHA);
            gTasks[taskId].func = Task_CreditsSoftReset_credits;
            return;
        }

        if (gTasks[taskId].tDelay_credits == 7144)
            FadeOutBGM(8);

        if (gTasks[taskId].tDelay_credits == 6840)
            m4aSongNumStart(MUS_END);

        gTasks[taskId].tDelay_credits--;
    }
}

#undef tDelay_credits

static void Task_CreditsSoftReset_credits(u8 taskId)
{
    if (!gPaletteFade.active)
        SoftReset(RESET_ALL);
}

static void ResetGpuAndVram_credits(void)
{
    SetGpuReg(REG_OFFSET_DISPCNT, 0);

    SetGpuReg(REG_OFFSET_BG3HOFS, 0);
    SetGpuReg(REG_OFFSET_BG3VOFS, 0);
    SetGpuReg(REG_OFFSET_BG2HOFS, 0);
    SetGpuReg(REG_OFFSET_BG2VOFS, 0);
    SetGpuReg(REG_OFFSET_BG1HOFS, 0);
    SetGpuReg(REG_OFFSET_BG1VOFS, 0);
    SetGpuReg(REG_OFFSET_BG0HOFS, 0);
    SetGpuReg(REG_OFFSET_BG0VOFS, 0);

    SetGpuReg(REG_OFFSET_BLDCNT, 0);
    SetGpuReg(REG_OFFSET_BLDALPHA, 0);
    SetGpuReg(REG_OFFSET_BLDY, 0);

    DmaFill16(3, 0, (void *)VRAM, VRAM_SIZE);
    DmaFill32(3, 0, (void *)OAM, OAM_SIZE);
    DmaFill16(3, 0, (void *)(PLTT + 2), PLTT_SIZE - 2);
}

#define tCurrentPage_credits data[2]
#define tDelay_credits       data[3]

static void Task_UpdatePage_credits(u8 taskId)
{
    int i;

    switch (gTasks[taskId].tState_credits)
    {
    case 0:
    case 6:
    case 7:
    case 8:
    case 9:
    default:
        if (!gPaletteFade.active)
        {
            gTasks[taskId].tState_credits = 1;
            gTasks[taskId].tDelay_credits = 72;
            gTasks[gTasks[taskId].tMainTaskId_credits].tPrintedPage_credits = FALSE;
            sUnkVar_credits = 0;
        }
        return;
    case 1:
        if (gTasks[taskId].tDelay_credits != 0)
        {
            gTasks[taskId].tDelay_credits--;
            return;
        }
        gTasks[taskId].tState_credits++;
        return;
    case 2:
        if (gTasks[gTasks[taskId].tMainTaskId_credits].func == Task_CreditsMain_credits)
        {
            if (gTasks[taskId].tCurrentPage_credits < PAGE_COUNT)
            {
                // Print text for this Credits page
                for (i = 0; i < ENTRIES_PER_PAGE; i++)
                    PrintCreditsText_credits(
                        sCreditsEntryPointerTable[gTasks[taskId].tCurrentPage_credits][i]->text,
                         5 + i * 16,
                         sCreditsEntryPointerTable[gTasks[taskId].tCurrentPage_credits][i]->isTitle);
                CopyWindowToVram(0, COPYWIN_GFX);

                gTasks[taskId].tCurrentPage_credits++;
                gTasks[taskId].tState_credits++;

                gTasks[gTasks[taskId].tMainTaskId_credits].tPrintedPage_credits = TRUE;

                if (gTasks[gTasks[taskId].tMainTaskId_credits].tCurrentMode_credits == MODE_BIKE_SCENE_credits)
                    BeginNormalPaletteFade(0x300, 0, 16, 0, COLOR_LIGHT_GREEN_credits);
                else // MODE_SHOW_MONS_credits
                    BeginNormalPaletteFade(0x300, 0, 16, 0, COLOR_DARK_GREEN_credits);
                return;
            }

            // Reached final page of Credits, end task
            gTasks[taskId].tState_credits = 10;
            return;
        }
        gTasks[gTasks[taskId].tMainTaskId_credits].tPrintedPage_credits = FALSE;
        return;
    case 3:
        if (!gPaletteFade.active)
        {
            gTasks[taskId].tDelay_credits = 115;
            gTasks[taskId].tState_credits++;
        }
        return;
    case 4:
        if (gTasks[taskId].tDelay_credits != 0)
        {
            gTasks[taskId].tDelay_credits--;
            return;
        }

        if (CheckChangeScene_credits((u8)gTasks[taskId].tCurrentPage_credits, (u8)gTasks[taskId].tMainTaskId_credits))
        {
            gTasks[taskId].tState_credits++;
            return;
        }
        gTasks[taskId].tState_credits++;
        if (gTasks[gTasks[taskId].tMainTaskId_credits].tCurrentMode_credits == MODE_BIKE_SCENE_credits)
            BeginNormalPaletteFade(0x300, 0, 0, 16, COLOR_LIGHT_GREEN_credits);
        else // MODE_SHOW_MONS_credits
            BeginNormalPaletteFade(0x300, 0, 0, 16, COLOR_DARK_GREEN_credits);
        return;
    case 5:
        if (!gPaletteFade.active)
        {
            // Still more Credits pages to show, return to state 2 to print
            FillWindowPixelBuffer(0, PIXEL_FILL(0));
            CopyWindowToVram(0, COPYWIN_GFX);
            gTasks[taskId].tState_credits = 2;
        }
        return;
    case 10:
        gTasks[gTasks[taskId].tMainTaskId_credits].tEndCredits_credits = TRUE;
        DestroyTask(taskId);
        FreeCreditsBgsAndWindows_credits();
        FREE_AND_SET_NULL(sCreditsData_credits);
        return;
    }
}

#undef tDelay_credits

#define PAGE_INTERVAL_credits (PAGE_COUNT / 9) // 9 scenes (5 bike scenes, 4 Pokémon interludes)

static u8 CheckChangeScene_credits(u8 page, u8 taskId)
{
    // Starts with bike + ocean + morning (SCENE_OCEAN_MORNING)

    if (page == PAGE_INTERVAL_credits * 1)
    {
        // Pokémon interlude
        gTasks[taskId].tNextMode_credits = MODE_SHOW_MONS_credits;
    }

    if (page == PAGE_INTERVAL_credits * 2)
    {
        // Bike + ocean + sunset
        gTasks[taskId].tSceneNum_credits = SCENE_OCEAN_SUNSET;
        gTasks[taskId].tNextMode_credits = MODE_BIKE_SCENE_credits;
    }

    if (page == PAGE_INTERVAL_credits * 3)
    {
        // Pokémon interlude
        gTasks[taskId].tNextMode_credits = MODE_SHOW_MONS_credits;
    }

    if (page == PAGE_INTERVAL_credits * 4)
    {
        // Bike + forest + sunset
        gTasks[taskId].tSceneNum_credits = SCENE_FOREST_RIVAL_ARRIVE;
        gTasks[taskId].tNextMode_credits = MODE_BIKE_SCENE_credits;
    }

    if (page == PAGE_INTERVAL_credits * 5)
    {
        // Pokémon interlude
        gTasks[taskId].tNextMode_credits = MODE_SHOW_MONS_credits;
    }

    if (page == PAGE_INTERVAL_credits * 6)
    {
        // Bike + forest + sunset
        gTasks[taskId].tSceneNum_credits = SCENE_FOREST_CATCH_RIVAL;
        gTasks[taskId].tNextMode_credits = MODE_BIKE_SCENE_credits;
    }

    if (page == PAGE_INTERVAL_credits * 7)
    {
        // Pokémon interlude
        gTasks[taskId].tNextMode_credits = MODE_SHOW_MONS_credits;
    }

    if (page == PAGE_INTERVAL_credits * 8)
    {
        // Bike + town + night
        gTasks[taskId].tSceneNum_credits = SCENE_CITY_NIGHT;
        gTasks[taskId].tNextMode_credits = MODE_BIKE_SCENE_credits;
    }

    if (gTasks[taskId].tNextMode_credits != MODE_NONE_credits)
    {
        // Returns true if changed
        return TRUE;
    }

    return FALSE;
}

#define tDelay_credits data[3]

static void Task_ShowMons_credits(u8 taskId)
{
    u8 spriteId;

    switch (gTasks[taskId].tState_credits)
    {
    case 0:
        break;
    case 1:
        if (sCreditsData_credits->nextImgPos == POS_LEFT_credits && gTasks[gTasks[taskId].tMainTaskId_credits].tPrintedPage_credits == FALSE)
            break;
        gTasks[taskId].tState_credits++;
        break;
    case 2:
        if (sCreditsData_credits->imgCounter == NUM_MON_SLIDES_credits || gTasks[gTasks[taskId].tMainTaskId_credits].func != Task_CreditsMain_credits)
            break;
        spriteId = CreateCreditsMonSprite_credits(sCreditsData_credits->monToShow[sCreditsData_credits->currShownMon],
                                    sMonSpritePos_credits[sCreditsData_credits->nextImgPos][0],
                                    sMonSpritePos_credits[sCreditsData_credits->nextImgPos][1],
                                    sCreditsData_credits->nextImgPos);
        if (sCreditsData_credits->currShownMon < sCreditsData_credits->numMonToShow - 1)
        {
            sCreditsData_credits->currShownMon++;
            gSprites[spriteId].data[3] = 50;
        }
        else
        {
            sCreditsData_credits->currShownMon = 0;
            gSprites[spriteId].data[3] = 512;
        }
        sCreditsData_credits->imgCounter++;

        if (sCreditsData_credits->nextImgPos == POS_RIGHT_credits)
            sCreditsData_credits->nextImgPos = POS_LEFT_credits;
        else
            sCreditsData_credits->nextImgPos++;

        gTasks[taskId].tDelay_credits = 50;
        gTasks[taskId].tState_credits++;
        break;
    case 3:
        if (gTasks[taskId].tDelay_credits != 0)
            gTasks[taskId].tDelay_credits--;
        else
            gTasks[taskId].tState_credits = 1;
        break;
    }
}

#undef tMainTaskId_credits
