#define tPlayer_credits data[2]
#define tRival_credits  data[3]
#define tDelay_credits  data[4]
#define tSinIdx_credits data[5]

static void Task_BikeScene_credits(u8 taskId)
{
    switch (gTasks[taskId].tState_credits)
    {
    case 0:
        gIntroCredits_MovingSceneryVOffset = Sin((gTasks[taskId].tSinIdx_credits >> 1) & 0x7F, 12);
        gTasks[taskId].tSinIdx_credits++;
        break;
    case 1:
        if (gIntroCredits_MovingSceneryVOffset != 0)
        {
            gIntroCredits_MovingSceneryVOffset = Sin((gTasks[taskId].tSinIdx_credits >> 1) & 0x7F, 12);
            gTasks[taskId].tSinIdx_credits++;
        }
        else
        {
            gSprites[gTasks[taskId].tPlayer_credits].data[0] = 2;
            gTasks[taskId].tSinIdx_credits = 0;
            gTasks[taskId].tState_credits++;
        }
        break;
    case 2:
        if (gTasks[taskId].tSinIdx_credits < 64)
        {
            gTasks[taskId].tSinIdx_credits++;
            gIntroCredits_MovingSceneryVOffset = Sin(gTasks[taskId].tSinIdx_credits & 0x7F, 20);
        }
        else
        {
            gTasks[taskId].tState_credits++;
        }
        break;
    case 3:
        gSprites[gTasks[taskId].tPlayer_credits].data[0] = 3;
        gSprites[gTasks[taskId].tRival_credits].data[0] = 1;
        gTasks[taskId].tDelay_credits = 120;
        gTasks[taskId].tState_credits++;
        break;
    case 4:
        if (gTasks[taskId].tDelay_credits != 0)
        {
            gTasks[taskId].tDelay_credits--;
        }
        else
        {
            gTasks[taskId].tSinIdx_credits = 64;
            gTasks[taskId].tState_credits++;
        }
        break;
    case 5:
        if (gTasks[taskId].tSinIdx_credits > 0)
        {
            gTasks[taskId].tSinIdx_credits--;
            gIntroCredits_MovingSceneryVOffset = Sin(gTasks[taskId].tSinIdx_credits & 0x7F, 20);
        }
        else
        {
            gSprites[gTasks[taskId].tPlayer_credits].data[0] = 1;
            gTasks[taskId].tState_credits++;
        }
        break;
    case 6:
        gTasks[taskId].tState_credits = 50;
        break;
    case 10:
        gSprites[gTasks[taskId].tRival_credits].data[0] = 2;
        gTasks[taskId].tState_credits = 50;
        break;
    case 20:
        gSprites[gTasks[taskId].tPlayer_credits].data[0] = 4;
        gTasks[taskId].tState_credits = 50;
        break;
    case 30:
        gSprites[gTasks[taskId].tPlayer_credits].data[0] = 5;
        gSprites[gTasks[taskId].tRival_credits].data[0] = 3;
        gTasks[taskId].tState_credits = 50;
        break;
    case 50:
        gTasks[taskId].tState_credits = 0;
        break;
    }
}

#define TIMER_STOP_credits  0x7FFF
#define tTimer_credits      data[1]
#define tMainTaskId_credits data[2]

static void Task_CycleSceneryPalette_credits(u8 taskId)
{
    s16 bikeTaskId;

    switch (gTasks[taskId].tState_credits)
    {
    default:
    case SCENE_OCEAN_MORNING:
        if (gTasks[taskId].tTimer_credits != TIMER_STOP_credits)
        {
            if (gTasks[gTasks[gTasks[taskId].tMainTaskId_credits].tTaskId_UpdatePage_credits].tCurrentPage_credits == 2)
            {
                gTasks[gTasks[gTasks[taskId].tMainTaskId_credits].tTaskId_BikeScene_credits].tState_credits = 20;
                gTasks[taskId].tTimer_credits = TIMER_STOP_credits;
            }
        }
        CycleSceneryPalette(0);
        break;
    case SCENE_OCEAN_SUNSET:
        CycleSceneryPalette(0);
        break;
    case SCENE_FOREST_RIVAL_ARRIVE:
        if (gTasks[taskId].tTimer_credits != TIMER_STOP_credits)
        {
            bikeTaskId = gTasks[gTasks[taskId].tMainTaskId_credits].tTaskId_BikeScene_credits;

            // Floor to multiple of 128
            if ((gTasks[bikeTaskId].tSinIdx_credits & -128) == 640)
            {
                gTasks[bikeTaskId].tState_credits = 1;
                gTasks[taskId].tTimer_credits = TIMER_STOP_credits;
            }
        }
        CycleSceneryPalette(1);
        break;
    case SCENE_FOREST_CATCH_RIVAL:
        if (gTasks[taskId].tTimer_credits != TIMER_STOP_credits)
        {

            if (gTasks[taskId].tTimer_credits == 584)
            {
                gTasks[gTasks[gTasks[taskId].tMainTaskId_credits].tTaskId_BikeScene_credits].tState_credits = 10;
                gTasks[taskId].tTimer_credits = TIMER_STOP_credits;
            }
            else
            {
                gTasks[taskId].tTimer_credits++;
            }
        }
        CycleSceneryPalette(1);
        break;
    case SCENE_CITY_NIGHT:
        CycleSceneryPalette(2);
        break;
    }
}

