static bool8 LoadBikeScene_credits(u8 scene, u8 taskId)
{
    u8 spriteId;

    switch (gMain.state)
    {
    default:
    case 0:
        SetGpuReg(REG_OFFSET_DISPCNT, 0);
        SetGpuReg(REG_OFFSET_BG3HOFS, 8);
        SetGpuReg(REG_OFFSET_BG3VOFS, 0);
        SetGpuReg(REG_OFFSET_BG2HOFS, 0);
        SetGpuReg(REG_OFFSET_BG2VOFS, 0);
        SetGpuReg(REG_OFFSET_BG1HOFS, 0);
        SetGpuReg(REG_OFFSET_BG1VOFS, 0);
        SetGpuReg(REG_OFFSET_BLDCNT, 0);
        SetGpuReg(REG_OFFSET_BLDALPHA, 0);
        ResetSpriteData();
        FreeAllSpritePalettes();
        gMain.state = 1;
        break;
    case 1:
        gIntroCredits_MovingSceneryVBase = 34;
        gIntroCredits_MovingSceneryVOffset = 0;
        LoadCreditsSceneGraphics(scene);
        gMain.state++;
        break;
    case 2:
        if (gSaveBlock2Ptr->playerGender == MALE)
        {
            LoadCompressedSpriteSheet(gSpriteSheet_CreditsBrendan);
            LoadCompressedSpriteSheet(gSpriteSheet_CreditsRivalMay);
            LoadCompressedSpriteSheet(gSpriteSheet_CreditsBicycle);
            LoadSpritePalettes(gSpritePalettes_Credits);

            spriteId = CreateIntroBrendanSprite(120, 46);
            gTasks[taskId].tPlayerSpriteId_credits = spriteId;
            gSprites[spriteId].callback = SpriteCB_Player_credits;
            gSprites[spriteId].anims = sAnims_Player_credits;

            spriteId = CreateIntroMaySprite(DISPLAY_WIDTH + 32, 46);
            gTasks[taskId].tRivalSpriteId_credits = spriteId;
            gSprites[spriteId].callback = SpriteCB_Rival_credits;
            gSprites[spriteId].anims = sAnims_Rival_credits;
        }
        else
        {
            LoadCompressedSpriteSheet(gSpriteSheet_CreditsMay);
            LoadCompressedSpriteSheet(gSpriteSheet_CreditsRivalBrendan);
            LoadCompressedSpriteSheet(gSpriteSheet_CreditsBicycle);
            LoadSpritePalettes(gSpritePalettes_Credits);

            spriteId = CreateIntroMaySprite(120, 46);
            gTasks[taskId].tPlayerSpriteId_credits = spriteId;
            gSprites[spriteId].callback = SpriteCB_Player_credits;
            gSprites[spriteId].anims = sAnims_Player_credits;

            spriteId = CreateIntroBrendanSprite(DISPLAY_WIDTH + 32, 46);
            gTasks[taskId].tRivalSpriteId_credits = spriteId;
            gSprites[spriteId].callback = SpriteCB_Rival_credits;
            gSprites[spriteId].anims = sAnims_Rival_credits;
        };
        gMain.state++;
        break;
    case 3:
        SetBikeScene_credits(scene, taskId);
        SetCreditsSceneBgCnt(scene);
        gMain.state = 0;
        return TRUE;
    }
    return FALSE;
}

static void ResetCreditsTasks_credits(u8 taskId)
{
    // Destroy Task_BicycleBgAnimation, if running
    if (gTasks[taskId].tTaskId_BgScenery_credits != 0)
    {
        DestroyTask(gTasks[taskId].tTaskId_BgScenery_credits);
        gTasks[taskId].tTaskId_BgScenery_credits = 0;
    }

    // Destroy Task_BikeScene_credits, if running
    if (gTasks[taskId].tTaskId_BikeScene_credits != 0)
    {
        DestroyTask(gTasks[taskId].tTaskId_BikeScene_credits);
        gTasks[taskId].tTaskId_BikeScene_credits = 0;
    }

    // Destroy Task_CycleSceneryPalette_credits, if running
    if (gTasks[taskId].tTaskId_SceneryPal_credits != 0)
    {
        DestroyTask(gTasks[taskId].tTaskId_SceneryPal_credits);
        gTasks[taskId].tTaskId_SceneryPal_credits = 0;
    }

    // Destroy Task_ShowMons_credits, if running
    if (gTasks[taskId].tTaskId_ShowMons_credits != 0)
    {
        DestroyTask(gTasks[taskId].tTaskId_ShowMons_credits);
        gTasks[taskId].tTaskId_ShowMons_credits = 0;
    }

    gIntroCredits_MovingSceneryState = INTROCRED_SCENERY_DESTROY;
}

static void LoadTheEndScreen_credits(u16 tileOffsetLoad, u16 tileOffsetWrite, u16 palOffset)
{
    u16 baseTile;
    u16 i;

    LZ77UnCompVram(sCreditsCopyrightEnd_Gfx_credits, (void *)(VRAM + tileOffsetLoad));
    LoadPalette(gIntroCopyright_Pal, palOffset, sizeof(gIntroCopyright_Pal));

    baseTile = (palOffset / 16) << 12;

    for (i = 0; i < 32 * 32; i++)
        ((u16 *) (VRAM + tileOffsetWrite))[i] = baseTile + 1;
}

static u16 GetLetterMapTile_credits(u8 baseTiles)
{
    u16 out = (baseTiles & 0x3F) + 80;

    if (baseTiles == 0xFF)
        return 1;

    if (baseTiles & (1 << 7))
        out |= 1 << 11;
    if (baseTiles & (1 << 6))
        out |= 1 << 10;

    return out;
}

static void DrawLetterMapTiles_credits(const u8 baseTiles[], u8 baseX, u8 baseY, u16 offset, u16 palette)
{
    u8 y, x;
    const u16 tileOffset = (palette / 16) << 12;

    for (y = 0; y < 5; y++)
    {
        for (x = 0; x < 3; x++)
            ((u16 *) (VRAM + offset + (baseY + y) * 64))[baseX + x] = tileOffset + GetLetterMapTile_credits(baseTiles[y * 3 + x]);
    }
}

static void DrawTheEnd_credits(u16 offset, u16 palette)
{
    u16 pos;
    u16 baseTile = (palette / 16) << 12;

    for (pos = 0; pos < 32 * 32; pos++)
        ((u16 *) (VRAM + offset))[pos] = baseTile + 1;

    DrawLetterMapTiles_credits(sTheEnd_LetterMap_T_credits, 3, 7, offset, palette);
    DrawLetterMapTiles_credits(sTheEnd_LetterMap_H_credits, 7, 7, offset, palette);
    DrawLetterMapTiles_credits(sTheEnd_LetterMap_E_credits, 11, 7, offset, palette);
    DrawLetterMapTiles_credits(sTheEnd_LetterMap_E_credits, 16, 7, offset, palette);
    DrawLetterMapTiles_credits(sTheEnd_LetterMap_N_credits, 20, 7, offset, palette);
    DrawLetterMapTiles_credits(sTheEnd_LetterMap_D_credits, 24, 7, offset, palette);
}

#define sState_credits data[0]

static void SpriteCB_Player_credits(struct Sprite *sprite)
{
    if (gIntroCredits_MovingSceneryState != INTROCRED_SCENERY_NORMAL)
    {
        DestroySprite(sprite);
        return;
    }

    switch (sprite->sState_credits)
    {
    case 0:
        StartSpriteAnimIfDifferent(sprite, 0);
        break;
    case 1:
        StartSpriteAnimIfDifferent(sprite, 1);
        if (sprite->x > -32)
            sprite->x--;
        break;
    case 2:
        StartSpriteAnimIfDifferent(sprite, 2);
        break;
    case 3:
        StartSpriteAnimIfDifferent(sprite, 3);
        break;
    case 4:
        StartSpriteAnimIfDifferent(sprite, 0);
        if (sprite->x > DISPLAY_WIDTH / 2)
            sprite->x--;
        break;
    case 5:
        StartSpriteAnimIfDifferent(sprite, 0);
        if (sprite->x > -32)
            sprite->x--;
        break;
    }
}

static void SpriteCB_Rival_credits(struct Sprite *sprite)
{
    if (gIntroCredits_MovingSceneryState != INTROCRED_SCENERY_NORMAL)
    {
        DestroySprite(sprite);
        return;
    }

    switch (sprite->sState_credits)
    {
    case 0:
        sprite->y2 = 0;
        StartSpriteAnimIfDifferent(sprite, 0);
        break;
    case 1:
        if (sprite->x > 200)
            StartSpriteAnimIfDifferent(sprite, 1);
        else
            StartSpriteAnimIfDifferent(sprite, 2);
        if (sprite->x > -32)
            sprite->x -= 2;
        sprite->y2 = -gIntroCredits_MovingSceneryVOffset;
        break;
    case 2:
        sprite->data[7]++;
        StartSpriteAnimIfDifferent(sprite, 0);
        if ((sprite->data[7] & 3) == 0)
            sprite->x++;
        break;
    case 3:
        StartSpriteAnimIfDifferent(sprite, 0);
        if (sprite->x > -32)
            sprite->x--;
        break;
    }
}

#define sPosition_credits data[1]
#define sSpriteId_credits data[6]

static void SpriteCB_CreditsMon_credits(struct Sprite *sprite)
{
    if (gIntroCredits_MovingSceneryState != INTROCRED_SCENERY_NORMAL)
    {
        FreeAndDestroyMonPicSprite(sprite->sSpriteId_credits);
        return;
    }

    sprite->data[7]++;
    switch (sprite->sState_credits)
    {
    case 0:
    default:
        sprite->oam.affineMode = ST_OAM_AFFINE_NORMAL;
        sprite->oam.matrixNum = sprite->sPosition_credits;
        sprite->data[2] = 16;
        SetOamMatrix(sprite->sPosition_credits, 0x10000 / sprite->data[2], 0, 0, 0x10000 / sprite->data[2]);
        sprite->invisible = FALSE;
        sprite->sState_credits = 1;
        break;
    case 1:
        if (sprite->data[2] < 256)
        {
            sprite->data[2] += 8;
            SetOamMatrix(sprite->sPosition_credits, 0x10000 / sprite->data[2], 0, 0, 0x10000 / sprite->data[2]);
        }
        else
        {
            sprite->sState_credits++;
        }
        switch (sprite->sPosition_credits)
        {
        case POS_LEFT_credits + 1:
            if ((sprite->data[7] & 3) == 0)
                sprite->y++;
            sprite->x -= 2;
            break;
        case POS_CENTER_credits + 1:
            break;
        case POS_RIGHT_credits + 1:
            if ((sprite->data[7] & 3) == 0)
                sprite->y++;
            sprite->x += 2;
            break;
        }
        break;
    case 2:
        if (sprite->data[3] != 0)
        {
            sprite->data[3]--;
        }
        else
        {
            SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_EFFECT_BLEND | BLDCNT_TGT2_BG0 | BLDCNT_TGT2_BG1 | BLDCNT_TGT2_BG2 | BLDCNT_TGT2_BG3);
            SetGpuReg(REG_OFFSET_BLDALPHA, BLDALPHA_BLEND(16, 0));
            sprite->oam.objMode = ST_OAM_OBJ_BLEND;
            sprite->data[3] = 16;
            sprite->sState_credits++;
        }
        break;
    case 3:
        if (sprite->data[3] != 0)
        {
            int data3;

            sprite->data[3]--;

            data3 = 16 - sprite->data[3];
            SetGpuReg(REG_OFFSET_BLDALPHA, (data3 << 8) + sprite->data[3]);
        }
        else
        {
            sprite->invisible = TRUE;
            sprite->sState_credits = 9;
        }
        break;
    case 9:
        sprite->sState_credits++;
        break;
    case 10:
        SetGpuReg(REG_OFFSET_BLDCNT, 0);
        SetGpuReg(REG_OFFSET_BLDALPHA, 0);
        FreeAndDestroyMonPicSprite(sprite->data[6]);
        break;
    }
}

#define sMonSpriteId_credits data[0]

static u8 CreateCreditsMonSprite_credits(u16 nationalDexNum, s16 x, s16 y, u16 position)
{
    u8 monSpriteId;
    u8 bgSpriteId;

    monSpriteId = CreateMonSpriteFromNationalDexNumber(nationalDexNum, x, y, position);
    gSprites[monSpriteId].oam.priority = 1;
    gSprites[monSpriteId].sPosition_credits = position + 1;
    gSprites[monSpriteId].invisible = TRUE;
    gSprites[monSpriteId].callback = SpriteCB_CreditsMon_credits;
    gSprites[monSpriteId].sSpriteId_credits = monSpriteId;

    bgSpriteId = CreateSprite(&sSpriteTemplate_CreditsMonBg_credits, gSprites[monSpriteId].x, gSprites[monSpriteId].y, 1);
    gSprites[bgSpriteId].sMonSpriteId_credits = monSpriteId;

    StartSpriteAnimIfDifferent(&gSprites[bgSpriteId], position);

    return monSpriteId;
}

static void SpriteCB_CreditsMonBg_credits(struct Sprite *sprite)
{
    if (gSprites[sprite->sMonSpriteId_credits].data[0] == 10
     || gIntroCredits_MovingSceneryState != INTROCRED_SCENERY_NORMAL)
    {
        DestroySprite(sprite);
        return;
    }

    // Copy sprite data from the associated Pokémon
    sprite->invisible = gSprites[sprite->sMonSpriteId_credits].invisible;
    sprite->oam.objMode = gSprites[sprite->sMonSpriteId_credits].oam.objMode;
    sprite->oam.affineMode = gSprites[sprite->sMonSpriteId_credits].oam.affineMode;
    sprite->oam.matrixNum = gSprites[sprite->sMonSpriteId_credits].oam.matrixNum;
    sprite->x = gSprites[sprite->sMonSpriteId_credits].x;
    sprite->y = gSprites[sprite->sMonSpriteId_credits].y;
}

static void DeterminePokemonToShow_credits(void)
{
    u16 starter = SpeciesToNationalPokedexNum(GetStarterPokemon(VarGet(VAR_STARTER_MON)));
    u16 page;
    u16 dexNum;
    u16 j;

    // Go through the Pokédex, and anything that has gotten caught we put into our massive array.
    // This basically packs all of the caught Pokémon into the front of the array
    for (dexNum = 1, j = 0; dexNum < NATIONAL_DEX_COUNT; dexNum++)
    {
        if (GetSetPokedexFlag(dexNum, FLAG_GET_CAUGHT))
        {
            sCreditsData_credits->caughtMonIds[j] = dexNum;
            j++;
        }
    }

    // Fill the rest of the array with zeroes
    for (dexNum = j; dexNum < NATIONAL_DEX_COUNT; dexNum++)
        sCreditsData_credits->caughtMonIds[dexNum] = NATIONAL_DEX_NONE;

    // Cap the number of Pokémon we care about to NUM_MON_SLIDES_credits, the max we show in the credits scene (-1 for the starter)
    sCreditsData_credits->numCaughtMon = j;
    if (sCreditsData_credits->numCaughtMon < NUM_MON_SLIDES_credits)
        sCreditsData_credits->numMonToShow = j;
    else
        sCreditsData_credits->numMonToShow = NUM_MON_SLIDES_credits;

    // Loop through our list of caught Pokémon and select randomly from it to fill the images to show
    j = 0;
    do
    {
        // Select a random mon, insert into array
        page = Random() % sCreditsData_credits->numCaughtMon;
        sCreditsData_credits->monToShow[j] = sCreditsData_credits->caughtMonIds[page];

        // Remove the select mon from the array, and condense array entries
        j++;
        sCreditsData_credits->caughtMonIds[page] = 0;
        sCreditsData_credits->numCaughtMon--;
        if (page != sCreditsData_credits->numCaughtMon)
        {
            // Instead of looping through and moving everything down, just take from the end. Order doesn't matter after all.
            sCreditsData_credits->caughtMonIds[page] = sCreditsData_credits->caughtMonIds[sCreditsData_credits->numCaughtMon];
            sCreditsData_credits->caughtMonIds[sCreditsData_credits->numCaughtMon] = 0;
        }
    }
    while (sCreditsData_credits->numCaughtMon != 0 && j < NUM_MON_SLIDES_credits);

    // If we don't have enough Pokémon in the dex to fill everything, copy the selected mon into the end of the array, so it loops
    if (sCreditsData_credits->numMonToShow < NUM_MON_SLIDES_credits)
    {
        for (j = sCreditsData_credits->numMonToShow, page = 0; j < NUM_MON_SLIDES_credits; j++)
        {
            sCreditsData_credits->monToShow[j] = sCreditsData_credits->monToShow[page];

            page++;
            if (page == sCreditsData_credits->numMonToShow)
                page = 0;
        }
        // Ensure the last Pokémon is our starter
        sCreditsData_credits->monToShow[NUM_MON_SLIDES_credits - 1] = starter;
    }
    else
    {
        // Check to see if our starter has already appeared in this list, break if it has
        for (dexNum = 0; sCreditsData_credits->monToShow[dexNum] != starter && dexNum < NUM_MON_SLIDES_credits; dexNum++);

        // If it has, swap it with the last Pokémon, to ensure our starter is the last image
        if (dexNum < sCreditsData_credits->numMonToShow - 1)
        {
            sCreditsData_credits->monToShow[dexNum] = sCreditsData_credits->monToShow[NUM_MON_SLIDES_credits-1];
            sCreditsData_credits->monToShow[NUM_MON_SLIDES_credits - 1] = starter;
        }
        else
        {
            // Ensure the last Pokémon is our starter
            sCreditsData_credits->monToShow[NUM_MON_SLIDES_credits - 1] = starter;
        }
    }
    sCreditsData_credits->numMonToShow = NUM_MON_SLIDES_credits;
}
