#define tMenuListTaskId_daycare     data[0]
#define tWindowId_daycare           data[1]

static void Task_HandleDaycareLevelMenuInput_daycare(u8 taskId)
{
    u32 input = ListMenu_ProcessInput(gTasks[taskId].tMenuListTaskId_daycare);

    if (JOY_NEW(A_BUTTON))
    {
        switch (input)
        {
        case 0:
        case 1:
            gSpecialVar_Result = input;
            break;
        case DAYCARE_LEVEL_MENU_EXIT:
            gSpecialVar_Result = DAYCARE_EXITED_LEVEL_MENU;
            break;
        }
        DestroyListMenuTask(gTasks[taskId].tMenuListTaskId_daycare, NULL, NULL);
        ClearStdWindowAndFrame(gTasks[taskId].tWindowId_daycare, TRUE);
        RemoveWindow(gTasks[taskId].tWindowId_daycare);
        DestroyTask(taskId);
        ScriptContext_Enable();
    }
    else if (JOY_NEW(B_BUTTON))
    {
        gSpecialVar_Result = DAYCARE_EXITED_LEVEL_MENU;
        DestroyListMenuTask(gTasks[taskId].tMenuListTaskId_daycare, NULL, NULL);
        ClearStdWindowAndFrame(gTasks[taskId].tWindowId_daycare, TRUE);
        RemoveWindow(gTasks[taskId].tWindowId_daycare);
        DestroyTask(taskId);
        ScriptContext_Enable();
    }
}

void ShowDaycareLevelMenu(void)
{
    struct ListMenuTemplate menuTemplate;
    u8 windowId;
    u8 listMenuTaskId;
    u8 daycareMenuTaskId;

    windowId = AddWindow(&sDaycareLevelMenuWindowTemplate_daycare);
    DrawStdWindowFrame(windowId, FALSE);

    menuTemplate = sDaycareListMenuLevelTemplate_daycare;
    menuTemplate.windowId = windowId;
    listMenuTaskId = ListMenuInit(&menuTemplate, 0, 0);

    CopyWindowToVram(windowId, COPYWIN_FULL);

    daycareMenuTaskId = CreateTask(Task_HandleDaycareLevelMenuInput_daycare, 3);
    gTasks[daycareMenuTaskId].tMenuListTaskId_daycare = listMenuTaskId;
    gTasks[daycareMenuTaskId].tWindowId_daycare = windowId;
}

#undef tMenuListTaskId_daycare
#undef tWindowId_daycare

void ChooseSendDaycareMon(void)
{
    ChooseMonForDaycare();
    gMain.savedCallback = CB2_ReturnToField;
}

static u8 ModifyBreedingScoreForOvalCharm_daycare(u8 score)
{
    if (CheckBagHasItem(ITEM_OVAL_CHARM, 1))
    {
        switch (score)
        {
        case 20:
            return 40;
        case 50:
            return 80;
        case 70:
            return 88;
        }
    }

    return score;
}

