// Functions universal
void Debug_ShowMainMenu(void)
{
    sDebugBattleData_debug = AllocZeroed(sizeof(*sDebugBattleData_debug));
    sDebugMenuListData_debug = AllocZeroed(sizeof(*sDebugMenuListData_debug));
    Debug_InitDebugBattleData_debug();

    Debug_ShowMenu_debug(DebugTask_HandleMenuInput_Main_debug, sDebugMenu_ListTemplate_Main_debug);
}

static void Debug_ReShowMainMenu_debug(void)
{
    Debug_ShowMenu_debug(DebugTask_HandleMenuInput_Main_debug, sDebugMenu_ListTemplate_Main_debug);
}

#define tMenuTaskId_debug   data[0]
#define tWindowId_debug     data[1]
#define tSubWindowId_debug  data[2]
#define tInput_debug        data[3]
#define tDigit_debug        data[4]

static void Debug_ShowMenu_debug(void (*HandleInput)(u8), struct ListMenuTemplate LMtemplate)
{
    struct ListMenuTemplate menuTemplate;
    u8 windowId;
    u8 menuTaskId;
    u8 inputTaskId;

    // create window
    HideMapNamePopUpWindow();
    LoadMessageBoxAndBorderGfx();
    windowId = AddWindow(&sDebugMenuWindowTemplateMain_debug);
    DrawStdWindowFrame(windowId, FALSE);

    // create list menu
    menuTemplate = LMtemplate;
    menuTemplate.maxShowed = DEBUG_MENU_HEIGHT_MAIN_debug;
    menuTemplate.windowId = windowId;
    menuTemplate.header_X = 0;
    menuTemplate.item_X = 8;
    menuTemplate.cursor_X = 0;
    menuTemplate.upText_Y = 1;
    menuTemplate.cursorPal = 2;
    menuTemplate.fillValue = 1;
    menuTemplate.cursorShadowPal = 3;
    menuTemplate.lettersSpacing = 1;
    menuTemplate.itemVerticalPadding = 0;
    menuTemplate.scrollMultiple = LIST_NO_MULTIPLE_SCROLL;
    menuTemplate.fontId = DEBUG_MENU_FONT_debug;
    menuTemplate.cursorKind = 0;
    menuTaskId = ListMenuInit(&menuTemplate, 0, 0);

    // create input handler task
    inputTaskId = CreateTask(HandleInput, 3);
    gTasks[inputTaskId].tMenuTaskId_debug = menuTaskId;
    gTasks[inputTaskId].tWindowId_debug = windowId;
    gTasks[inputTaskId].tSubWindowId_debug = 0;

    Debug_RefreshListMenu_debug(inputTaskId);

    // draw everything
    CopyWindowToVram(windowId, COPYWIN_FULL);
}

static void Debug_DestroyMenu_debug(u8 taskId)
{
    DestroyListMenuTask(gTasks[taskId].tMenuTaskId_debug, NULL, NULL);
    RemoveWindow(gTasks[taskId].tWindowId_debug);
    DestroyTask(taskId);
}

static void Debug_DestroyMenu_Full_debug(u8 taskId)
{
    if (gTasks[taskId].tSubWindowId_debug != 0)
    {
        ClearStdWindowAndFrame(gTasks[taskId].tSubWindowId_debug, FALSE);
        DebugAction_DestroyExtraWindow_debug(taskId);
    }
    DestroyListMenuTask(gTasks[taskId].tMenuTaskId_debug, NULL, NULL);
    ClearStdWindowAndFrame(gTasks[taskId].tWindowId_debug, TRUE);
    RemoveWindow(gTasks[taskId].tWindowId_debug);
    DestroyTask(taskId);
    UnfreezeObjectEvents();
    Free(sDebugMenuListData_debug);
    Free(sDebugBattleData_debug);
}

static void Debug_DestroyMenu_Full_Script_debug(u8 taskId, const u8 *script)
{
    Debug_DestroyMenu_Full_debug(taskId);
    LockPlayerFieldControls();
    FreezeObjectEvents();
    ScriptContext_SetupScript(script);
}

static void DebugAction_Cancel_debug(u8 taskId)
{
    Debug_DestroyMenu_Full_debug(taskId);
    ScriptContext_Enable();
}

static void DebugAction_DestroyExtraWindow_debug(u8 taskId)
{
    ClearStdWindowAndFrame(gTasks[taskId].tWindowId_debug, TRUE);
    RemoveWindow(gTasks[taskId].tWindowId_debug);

    ClearStdWindowAndFrame(gTasks[taskId].tSubWindowId_debug, TRUE);
    RemoveWindow(gTasks[taskId].tSubWindowId_debug);

    DestroyListMenuTask(gTasks[taskId].tMenuTaskId_debug, NULL, NULL);
    DestroyTask(taskId);
    ScriptContext_Enable();
    UnfreezeObjectEvents();
}

static u8 Debug_CheckToggleFlags_debug(u8 id)
{
    u8 result = FALSE;

    switch (id)
    {
        case DEBUG_FLAGVAR_MENU_ITEM_TOGGLE_POKEDEX_debug:
            result = FlagGet(FLAG_SYS_POKEDEX_GET);
            break;
        case DEBUG_FLAGVAR_MENU_ITEM_TOGGLE_NATDEX_debug:
            result = IsNationalPokedexEnabled();
            break;
        case DEBUG_FLAGVAR_MENU_ITEM_TOGGLE_POKENAV_debug:
            result = FlagGet(FLAG_SYS_POKENAV_GET);
            break;
        case DEBUG_FLAGVAR_MENU_ITEM_TOGGLE_MATCH_CALL_debug:
            result = FlagGet(FLAG_ADDED_MATCH_CALL_TO_POKENAV) && FlagGet(FLAG_HAS_MATCH_CALL);
            break;
        case DEBUG_FLAGVAR_MENU_ITEM_TOGGLE_RUN_SHOES_debug:
            result = FlagGet(FLAG_SYS_B_DASH);
            break;
        case DEBUG_FLAGVAR_MENU_ITEM_TOGGLE_LOCATIONS_debug:
            result = FlagGet(FLAG_VISITED_LITTLEROOT_TOWN) &&
                FlagGet(FLAG_VISITED_OLDALE_TOWN) &&
                FlagGet(FLAG_VISITED_DEWFORD_TOWN) &&
                FlagGet(FLAG_VISITED_LAVARIDGE_TOWN) &&
                FlagGet(FLAG_VISITED_FALLARBOR_TOWN) &&
                FlagGet(FLAG_VISITED_VERDANTURF_TOWN) &&
                FlagGet(FLAG_VISITED_PACIFIDLOG_TOWN) &&
                FlagGet(FLAG_VISITED_PETALBURG_CITY) &&
                FlagGet(FLAG_VISITED_SLATEPORT_CITY) &&
                FlagGet(FLAG_VISITED_MAUVILLE_CITY) &&
                FlagGet(FLAG_VISITED_RUSTBORO_CITY) &&
                FlagGet(FLAG_VISITED_FORTREE_CITY) &&
                FlagGet(FLAG_VISITED_LILYCOVE_CITY) &&
                FlagGet(FLAG_VISITED_MOSSDEEP_CITY) &&
                FlagGet(FLAG_VISITED_SOOTOPOLIS_CITY) &&
                FlagGet(FLAG_VISITED_EVER_GRANDE_CITY) &&
                FlagGet(FLAG_LANDMARK_POKEMON_LEAGUE) &&
                FlagGet(FLAG_LANDMARK_BATTLE_FRONTIER);
            break;
        case DEBUG_FLAGVAR_MENU_ITEM_TOGGLE_BADGES_ALL_debug:
            result = FlagGet(FLAG_BADGE01_GET) &&
                FlagGet(FLAG_BADGE02_GET) &&
                FlagGet(FLAG_BADGE03_GET) &&
                FlagGet(FLAG_BADGE04_GET) &&
                FlagGet(FLAG_BADGE05_GET) &&
                FlagGet(FLAG_BADGE06_GET) &&
                FlagGet(FLAG_BADGE07_GET) &&
                FlagGet(FLAG_BADGE08_GET);
            break;
        case DEBUG_FLAGVAR_MENU_ITEM_TOGGLE_GAME_CLEAR_debug:
            result = FlagGet(FLAG_SYS_GAME_CLEAR);
            break;
        case DEBUG_FLAGVAR_MENU_ITEM_TOGGLE_FRONTIER_PASS_debug:
            result = FlagGet(FLAG_SYS_FRONTIER_PASS);
            break;
    #if OW_FLAG_NO_COLLISION != 0
        case DEBUG_FLAGVAR_MENU_ITEM_TOGGLE_COLLISION_debug:
            result = FlagGet(OW_FLAG_NO_COLLISION);
            break;
    #endif
    #if OW_FLAG_NO_ENCOUNTER != 0
        case DEBUG_FLAGVAR_MENU_ITEM_TOGGLE_ENCOUNTER_debug:
            result = FlagGet(OW_FLAG_NO_ENCOUNTER);
            break;
    #endif
    #if OW_FLAG_NO_TRAINER_SEE != 0
        case DEBUG_FLAGVAR_MENU_ITEM_TOGGLE_TRAINER_SEE_debug:
            result = FlagGet(OW_FLAG_NO_TRAINER_SEE);
            break;
    #endif
    #if B_FLAG_NO_BAG_USE != 0
        case DEBUG_FLAGVAR_MENU_ITEM_TOGGLE_BAG_USE_debug:
            result = FlagGet(B_FLAG_NO_BAG_USE);
            break;
    #endif
    #if B_FLAG_NO_CATCHING != 0
        case DEBUG_FLAGVAR_MENU_ITEM_TOGGLE_CATCHING_debug:
            result = FlagGet(B_FLAG_NO_CATCHING);
            break;
    #endif
        default:
            result = 0xFF;
            break;
    }

    return result;
}

static void Debug_InitDebugBattleData_debug(void)
{
    u32 i;
    sDebugBattleData_debug->submenu       = 0;
    sDebugBattleData_debug->battleType    = 0xFF;
    sDebugBattleData_debug->battleTerrain = 0xFF;

    for (i = 0; i < AI_FLAG_COUNT; i++)
        sDebugBattleData_debug->aiFlags[i] = FALSE;
}

static void Debug_GenerateListMenuNames_debug(u32 totalItems)
{
    const u8 sColor_Red[] = _("{COLOR RED}");
    const u8 sColor_Green[] = _("{COLOR GREEN}");
    u32 i, flagResult = 0;
    u8 const *name = NULL;

    // Copy item names for all entries but the last (which is Cancel)
    for (i = 0; i < totalItems; i++)
    {
        if (sDebugMenuListData_debug->listId == 1 && sDebugBattleData_debug->submenu > 1)
        {
            u16 species;
            if (i == 6)
            {
                name = sDebugText_Continue_debug;
                StringCopy(&sDebugMenuListData_debug->itemNames[i][0], name);
            }
            else if (GetMonData(&gEnemyParty[i], MON_DATA_SANITY_HAS_SPECIES))
            {
                species = GetMonData(&gEnemyParty[i], MON_DATA_SPECIES);
                StringCopy(gStringVar1, GetSpeciesName(species));
                StringCopy(&sDebugMenuListData_debug->itemNames[i][0], gStringVar1);
            }
            else
            {
                StringCopy(&sDebugMenuListData_debug->itemNames[i][0], sDebugText_Dashes_debug);
            }
        }
        else
        {
            if (sDebugMenuListData_debug->listId == 0)
            {
                flagResult = Debug_CheckToggleFlags_debug(i);
                name = sDebugMenu_Items_FlagsVars_debug[i].name;
            }
            else if (sDebugMenuListData_debug->listId == 1)
            {
                flagResult = sDebugBattleData_debug->aiFlags[i];
                if (i == totalItems - 1)
                    flagResult = 0xFF;
                name = sDebugMenu_Items_Battle_1_debug[i].name;
            }

            if (flagResult == 0xFF)
            {
                StringCopy(&sDebugMenuListData_debug->itemNames[i][0], name);
            }
            else if (flagResult)
            {
                StringCopy(gStringVar1, sColor_Green);
                StringExpandPlaceholders(gStringVar4, name);
                StringCopy(&sDebugMenuListData_debug->itemNames[i][0], gStringVar4);
            }
            else
            {
                StringCopy(gStringVar1, sColor_Red);
                StringExpandPlaceholders(gStringVar4, name);
                StringCopy(&sDebugMenuListData_debug->itemNames[i][0], gStringVar4);
            }
        }

        sDebugMenuListData_debug->listItems[i].name = &sDebugMenuListData_debug->itemNames[i][0];
        sDebugMenuListData_debug->listItems[i].id = i;
    }
}

static void Debug_RefreshListMenu_debug(u8 taskId)
{
    u8 totalItems = 0;

    if (sDebugMenuListData_debug->listId == 0)
    {
        gMultiuseListMenuTemplate = sDebugMenu_ListTemplate_FlagsVars_debug;
        totalItems = gMultiuseListMenuTemplate.totalItems;
    }
    else if (sDebugMenuListData_debug->listId == 1 && sDebugBattleData_debug->submenu <= 1)
    {
        gMultiuseListMenuTemplate = sDebugMenu_ListTemplate_Battle_1_debug;
        totalItems = gMultiuseListMenuTemplate.totalItems;
    }
    else if (sDebugMenuListData_debug->listId == 1 && sDebugBattleData_debug->submenu > 1)
    {
        gMultiuseListMenuTemplate = sDebugMenu_ListTemplate_Battle_2_debug;
        totalItems = 7;
    }

    // Failsafe to prevent memory corruption
    totalItems = min(totalItems, DEBUG_MAX_MENU_ITEMS_debug);
    Debug_GenerateListMenuNames_debug(totalItems);

    // Set list menu data
    gMultiuseListMenuTemplate.items = sDebugMenuListData_debug->listItems;
    gMultiuseListMenuTemplate.totalItems = totalItems;
    gMultiuseListMenuTemplate.maxShowed = DEBUG_MENU_HEIGHT_MAIN_debug;
    gMultiuseListMenuTemplate.windowId = gTasks[taskId].tWindowId_debug;
    gMultiuseListMenuTemplate.header_X = 0;
    gMultiuseListMenuTemplate.item_X = 8;
    gMultiuseListMenuTemplate.cursor_X = 0;
    gMultiuseListMenuTemplate.upText_Y = 1;
    gMultiuseListMenuTemplate.cursorPal = 2;
    gMultiuseListMenuTemplate.fillValue = 1;
    gMultiuseListMenuTemplate.cursorShadowPal = 3;
    gMultiuseListMenuTemplate.lettersSpacing = 1;
    gMultiuseListMenuTemplate.itemVerticalPadding = 0;
    gMultiuseListMenuTemplate.scrollMultiple = LIST_NO_MULTIPLE_SCROLL;
    gMultiuseListMenuTemplate.fontId = 1;
    gMultiuseListMenuTemplate.cursorKind = 0;
}

static void Debug_RedrawListMenu_debug(u8 taskId)
{
    u8 listTaskId = gTasks[taskId].tMenuTaskId_debug;
    u16 scrollOffset, selectedRow;
    ListMenuGetScrollAndRow(listTaskId, &scrollOffset, &selectedRow);

    DestroyListMenuTask(gTasks[taskId].tMenuTaskId_debug, &scrollOffset, &selectedRow);
    Debug_RefreshListMenu_debug(taskId);
    gTasks[taskId].tMenuTaskId_debug = ListMenuInit(&gMultiuseListMenuTemplate, scrollOffset, selectedRow);
}


