static void DebugTask_HandleBattleMenuReDraw_debug(u8 taskId)
{
    Debug_RefreshListMenu_debug(taskId);
    switch (sDebugBattleData_debug->submenu)
    {
    case 0:
        Debug_DestroyMenu_debug(taskId);
        Debug_ShowMenu_debug(DebugTask_HandleMenuInput_Battle_debug, sDebugMenu_ListTemplate_Battle_0_debug);
        break;
    case 1:
        Debug_DestroyMenu_debug(taskId);
        Debug_ShowMenu_debug(DebugTask_HandleMenuInput_Battle_debug, gMultiuseListMenuTemplate);
        break;
    case 2:
        Debug_DestroyMenu_debug(taskId);
        Debug_ShowMenu_debug(DebugTask_HandleMenuInput_Battle_debug, sDebugMenu_ListTemplate_Battle_2_debug);
        break;
    case 3:
        Debug_DestroyMenu_debug(taskId);
        Debug_ShowMenu_debug(DebugTask_HandleMenuInput_Battle_debug, gMultiuseListMenuTemplate);
        break;
    }
}

static void DebugTask_HandleMenuInput_Battle_debug(u8 taskId)
{
    u16 idx;
    u8 listTaskId = gTasks[taskId].tMenuTaskId_debug;
    ListMenu_ProcessInput(listTaskId);

    ListMenuGetCurrentItemArrayId(listTaskId, &idx);

    if (JOY_NEW(A_BUTTON))
    {
        PlaySE(SE_SELECT);

        switch (sDebugBattleData_debug->submenu)
        {
        case 0: // Battle type
            sDebugBattleData_debug->battleType = idx;
            sDebugBattleData_debug->submenu++;
            Debug_DestroyMenu_debug(taskId);

            if (sDebugBattleData_debug->battleType == DEBUG_BATTLE_0_MENU_ITEM_WILD_debug // Skip AI Flag selection if wild battle
             || sDebugBattleData_debug->battleType == DEBUG_BATTLE_0_MENU_ITEM_WILD_DOUBLE_debug)
            {
                sDebugBattleData_debug->submenu++;
                Debug_ShowMenu_debug(DebugTask_HandleMenuInput_Battle_debug, sDebugMenu_ListTemplate_Battle_2_debug);
            }
            else
            {
                Debug_ShowMenu_debug(DebugTask_HandleMenuInput_Battle_debug, gMultiuseListMenuTemplate);
            }
            break;
        case 1: // AI Flags
            if (idx == sDebugMenu_ListTemplate_Battle_1_debug.totalItems - 1)
            {
                sDebugBattleData_debug->submenu++;
                Debug_DestroyMenu_debug(taskId);
                Debug_ShowMenu_debug(DebugTask_HandleMenuInput_Battle_debug, sDebugMenu_ListTemplate_Battle_2_debug);
            }
            else
            {
                sDebugBattleData_debug->aiFlags[idx] = !sDebugBattleData_debug->aiFlags[idx];
                Debug_RedrawListMenu_debug(taskId);
            }

            break;
        case 2: // Terrain
            sDebugBattleData_debug->submenu++;
            sDebugBattleData_debug->battleTerrain = idx;
            Debug_DestroyMenu_debug(taskId);
            Debug_ShowMenu_debug(DebugTask_HandleMenuInput_Battle_debug, gMultiuseListMenuTemplate);
            break;
        case 3: // Enemy pokemon
            if (idx == 6)
                Debug_InitializeBattle_debug(taskId);
            break;
        }
    }
    else if (JOY_NEW(B_BUTTON))
    {
        switch (sDebugBattleData_debug->submenu)
        {
        case 0: // Return to Main menu
            PlaySE(SE_SELECT);
            Debug_DestroyMenu_debug(taskId);
            Debug_ReShowMainMenu_debug();
            break;
        case 2: // Skip AI Flag selection if wild battle
            if (sDebugBattleData_debug->battleType == DEBUG_BATTLE_0_MENU_ITEM_WILD_debug
             || sDebugBattleData_debug->battleType == DEBUG_BATTLE_0_MENU_ITEM_WILD_DOUBLE_debug)
            {
                sDebugBattleData_debug->submenu = 0;
            }
            else
                sDebugBattleData_debug->submenu--;
            DebugTask_HandleBattleMenuReDraw_debug(taskId);
            break;
        default:
            sDebugBattleData_debug->submenu--;
            DebugTask_HandleBattleMenuReDraw_debug(taskId);
            break;
        }
    }
}

static void Debug_InitializeBattle_debug(u8 taskId)
{
    u32 i;
    gBattleTypeFlags = 0;

    // Set main battle flags
    switch (sDebugBattleData_debug->battleType)
    {
    case DEBUG_BATTLE_0_MENU_ITEM_WILD_debug:
        break;
    case DEBUG_BATTLE_0_MENU_ITEM_SINGLE_debug:
        gBattleTypeFlags = (BATTLE_TYPE_TRAINER);
        break;
    case DEBUG_BATTLE_0_MENU_ITEM_DOUBLE_debug:
        gBattleTypeFlags = (BATTLE_TYPE_DOUBLE | BATTLE_TYPE_TWO_OPPONENTS | BATTLE_TYPE_TRAINER);
        break;
    case DEBUG_BATTLE_0_MENU_ITEM_MULTI_debug:
        gBattleTypeFlags = (BATTLE_TYPE_DOUBLE | BATTLE_TYPE_TWO_OPPONENTS | BATTLE_TYPE_TRAINER | BATTLE_TYPE_INGAME_PARTNER);
        break;
    }

    // Set terrain
    gBattleTerrain = sDebugBattleData_debug->battleTerrain;

    // Populate enemy party
    for (i = 0; i < PARTY_SIZE; i++)
    {
        ZeroMonData(&gEnemyParty[i]);
        if (GetMonData(&gPlayerParty[i], MON_DATA_SANITY_HAS_SPECIES))
            gEnemyParty[i] = gPlayerParty[i];
    }

    // Set AI flags
    for (i = 0; i < ARRAY_COUNT(sDebugBattleData_debug->aiFlags); i++)
    {
        if (sDebugBattleData_debug->aiFlags[i])
            gDebugAIFlags |= (1 << i);
    }

    gIsDebugBattle = TRUE;
    BattleSetup_StartTrainerBattle_Debug();


    Debug_DestroyMenu_Full_debug(taskId);
}

