        StringExpandPlaceholders(gStringVar4, sDebugText_Util_WarpToMap_SelectWarp_debug);
        AddTextPrinterParameterized(gTasks[taskId].tSubWindowId_debug, DEBUG_MENU_FONT_debug, gStringVar4, 0, 0, 0, NULL);
