static void DebugAction_Util_Weather_SelectId_debug(u8 taskId)
{
    if (JOY_NEW(DPAD_ANY))
    {
        PlaySE(SE_SELECT);

        if (JOY_NEW(DPAD_UP))
        {
            gTasks[taskId].tInput_debug += sPowersOfTen_debug[gTasks[taskId].tDigit_debug];
            if (gTasks[taskId].tInput_debug > WEATHER_ROUTE123_CYCLE)
                gTasks[taskId].tInput_debug = WEATHER_ROUTE123_CYCLE;
        }
        if (JOY_NEW(DPAD_DOWN))
        {
            gTasks[taskId].tInput_debug -= sPowersOfTen_debug[gTasks[taskId].tDigit_debug];
            if (gTasks[taskId].tInput_debug < WEATHER_NONE)
                gTasks[taskId].tInput_debug = WEATHER_NONE;
        }
        if (JOY_NEW(DPAD_LEFT))
        {
            if (gTasks[taskId].tDigit_debug > 0)
                gTasks[taskId].tDigit_debug -= 1;
        }
        if (JOY_NEW(DPAD_RIGHT))
        {
            if (gTasks[taskId].tDigit_debug < 2)
                gTasks[taskId].tDigit_debug += 1;
        }

        StringCopy(gStringVar2, gText_DigitIndicator[gTasks[taskId].tDigit_debug]);
        ConvertIntToDecimalStringN(gStringVar3, gTasks[taskId].tInput_debug, STR_CONV_MODE_LEADING_ZEROS, 2);

        if (gTasks[taskId].tInput_debug <= 15 || gTasks[taskId].tInput_debug >= 20)
            StringCopyPadded(gStringVar1, sWeatherNames_debug[gTasks[taskId].tInput_debug], CHAR_SPACE, 30);
        else
            StringCopyPadded(gStringVar1, sDebugText_WeatherNotDefined_debug, CHAR_SPACE, 30);

        StringExpandPlaceholders(gStringVar4, sDebugText_Util_Weather_ID_debug);
        AddTextPrinterParameterized(gTasks[taskId].tSubWindowId_debug, DEBUG_MENU_FONT_debug, gStringVar4, 0, 0, 0, NULL);
    }

    if (JOY_NEW(A_BUTTON))
    {
        if (gTasks[taskId].tInput_debug <= 14 || gTasks[taskId].tInput_debug >= 20)
        {
            gTasks[taskId].data[5] = gTasks[taskId].tInput_debug;
            SetWeather(gTasks[taskId].data[5]);
        }
    }
    else if (JOY_NEW(B_BUTTON))
    {
        PlaySE(SE_SELECT);
        DebugAction_DestroyExtraWindow_debug(taskId);
    }
}

