// Actions Give
#define ITEM_TAG_debug 0xFDF3
#define tItemId_debug    data[5]
#define tSpriteId_debug  data[6]

static void DebugAction_Give_Item_debug(u8 taskId)
{
    u8 windowId;

    ClearStdWindowAndFrame(gTasks[taskId].tWindowId_debug, TRUE);
    RemoveWindow(gTasks[taskId].tWindowId_debug);

    HideMapNamePopUpWindow();
    LoadMessageBoxAndBorderGfx();
    windowId = AddWindow(&sDebugMenuWindowTemplateExtra_debug);
    DrawStdWindowFrame(windowId, FALSE);

    CopyWindowToVram(windowId, COPYWIN_FULL);

    // Display initial item
    StringCopy(gStringVar2, gText_DigitIndicator[0]);
    ConvertIntToDecimalStringN(gStringVar3, 1, STR_CONV_MODE_LEADING_ZEROS, DEBUG_NUMBER_DIGITS_ITEMS_debug);
    u8* end = CopyItemName(1, gStringVar1);
    WrapFontIdToFit(gStringVar1, end, DEBUG_MENU_FONT_debug, WindowWidthPx(windowId));
    StringCopyPadded(gStringVar1, gStringVar1, CHAR_SPACE, 15);
    StringExpandPlaceholders(gStringVar4, sDebugText_ItemID_debug);
    AddTextPrinterParameterized(windowId, DEBUG_MENU_FONT_debug, gStringVar4, 0, 0, 0, NULL);

    gTasks[taskId].func = DebugAction_Give_Item_SelectId_debug;
    gTasks[taskId].tSubWindowId_debug = windowId;
    gTasks[taskId].tInput_debug = 1;
    gTasks[taskId].tDigit_debug = 0;
    gTasks[taskId].tSpriteId_debug = AddItemIconSprite(ITEM_TAG_debug, ITEM_TAG_debug, gTasks[taskId].tInput_debug);
    gSprites[gTasks[taskId].tSpriteId_debug].x2 = DEBUG_NUMBER_ICON_X_debug+10;
    gSprites[gTasks[taskId].tSpriteId_debug].y2 = DEBUG_NUMBER_ICON_Y_debug+10;
    gSprites[gTasks[taskId].tSpriteId_debug].oam.priority = 0;
}

static void DebugAction_Give_Item_SelectId_debug(u8 taskId)
{
    if (JOY_NEW(DPAD_ANY))
    {
        PlaySE(SE_SELECT);

        if (JOY_NEW(DPAD_UP))
        {
            gTasks[taskId].tInput_debug += sPowersOfTen_debug[gTasks[taskId].tDigit_debug];
            if (gTasks[taskId].tInput_debug >= ITEMS_COUNT)
                gTasks[taskId].tInput_debug = ITEMS_COUNT - 1;
        }
        if (JOY_NEW(DPAD_DOWN))
        {
            gTasks[taskId].tInput_debug -= sPowersOfTen_debug[gTasks[taskId].tDigit_debug];
            if (gTasks[taskId].tInput_debug < 1)
                gTasks[taskId].tInput_debug = 1;
        }
        if (JOY_NEW(DPAD_LEFT))
        {
            if (gTasks[taskId].tDigit_debug > 0)
                gTasks[taskId].tDigit_debug -= 1;
        }
        if (JOY_NEW(DPAD_RIGHT))
        {
            if (gTasks[taskId].tDigit_debug < DEBUG_NUMBER_DIGITS_ITEMS_debug - 1)
                gTasks[taskId].tDigit_debug += 1;
        }

        StringCopy(gStringVar2, gText_DigitIndicator[gTasks[taskId].tDigit_debug]);
        u8* end = CopyItemName(gTasks[taskId].tInput_debug, gStringVar1);
        WrapFontIdToFit(gStringVar1, end, DEBUG_MENU_FONT_debug, WindowWidthPx(gTasks[taskId].tSubWindowId_debug));
        StringCopyPadded(gStringVar1, gStringVar1, CHAR_SPACE, 15);
        ConvertIntToDecimalStringN(gStringVar3, gTasks[taskId].tInput_debug, STR_CONV_MODE_LEADING_ZEROS, DEBUG_NUMBER_DIGITS_ITEMS_debug);
        StringExpandPlaceholders(gStringVar4, sDebugText_ItemID_debug);
        AddTextPrinterParameterized(gTasks[taskId].tSubWindowId_debug, DEBUG_MENU_FONT_debug, gStringVar4, 0, 0, 0, NULL);

        FreeSpriteTilesByTag(ITEM_TAG_debug);                             //Destroy item icon
        FreeSpritePaletteByTag(ITEM_TAG_debug);                           //Destroy item icon
        FreeSpriteOamMatrix(&gSprites[gTasks[taskId].tSpriteId_debug]);   //Destroy item icon
        DestroySprite(&gSprites[gTasks[taskId].tSpriteId_debug]);         //Destroy item icon
        gTasks[taskId].tSpriteId_debug = AddItemIconSprite(ITEM_TAG_debug, ITEM_TAG_debug, gTasks[taskId].tInput_debug);
        gSprites[gTasks[taskId].tSpriteId_debug].x2 = DEBUG_NUMBER_ICON_X_debug+10;
        gSprites[gTasks[taskId].tSpriteId_debug].y2 = DEBUG_NUMBER_ICON_Y_debug+10;
        gSprites[gTasks[taskId].tSpriteId_debug].oam.priority = 0;
    }

    if (JOY_NEW(A_BUTTON))
    {
        gTasks[taskId].tItemId_debug = gTasks[taskId].tInput_debug;
        gTasks[taskId].tInput_debug = 1;
        gTasks[taskId].tDigit_debug = 0;

        StringCopy(gStringVar2, gText_DigitIndicator[gTasks[taskId].tDigit_debug]);
        ConvertIntToDecimalStringN(gStringVar1, gTasks[taskId].tInput_debug, STR_CONV_MODE_LEADING_ZEROS, DEBUG_NUMBER_DIGITS_ITEM_QUANTITY_debug);
        StringCopyPadded(gStringVar1, gStringVar1, CHAR_SPACE, 15);
        StringExpandPlaceholders(gStringVar4, sDebugText_ItemQuantity_debug);
        AddTextPrinterParameterized(gTasks[taskId].tSubWindowId_debug, DEBUG_MENU_FONT_debug, gStringVar4, 0, 0, 0, NULL);

        gTasks[taskId].func = DebugAction_Give_Item_SelectQuantity_debug;
    }
    else if (JOY_NEW(B_BUTTON))
    {
        FreeSpriteTilesByTag(ITEM_TAG_debug);                             //Destroy item icon
        FreeSpritePaletteByTag(ITEM_TAG_debug);                           //Destroy item icon
        FreeSpriteOamMatrix(&gSprites[gTasks[taskId].tSpriteId_debug]);   //Destroy item icon
        DestroySprite(&gSprites[gTasks[taskId].tSpriteId_debug]);         //Destroy item icon

        PlaySE(SE_SELECT);
        DebugAction_DestroyExtraWindow_debug(taskId);
    }
}

static void DebugAction_Give_Item_SelectQuantity_debug(u8 taskId)
{
    u32 itemId = gTasks[taskId].tItemId_debug;

    if (JOY_NEW(DPAD_ANY))
    {
        PlaySE(SE_SELECT);

        if (JOY_NEW(DPAD_UP))
        {
            gTasks[taskId].tInput_debug += sPowersOfTen_debug[gTasks[taskId].tDigit_debug];
            if (gTasks[taskId].tInput_debug > MAX_BAG_ITEM_CAPACITY)
                gTasks[taskId].tInput_debug = MAX_BAG_ITEM_CAPACITY;
        }
        if (JOY_NEW(DPAD_DOWN))
        {
            gTasks[taskId].tInput_debug -= sPowersOfTen_debug[gTasks[taskId].tDigit_debug];
            if (gTasks[taskId].tInput_debug < 1)
                gTasks[taskId].tInput_debug = 1;
        }
        if (JOY_NEW(DPAD_LEFT))
        {
            if (gTasks[taskId].tDigit_debug > 0)
                gTasks[taskId].tDigit_debug -= 1;
        }
        if (JOY_NEW(DPAD_RIGHT))
        {
            if (gTasks[taskId].tDigit_debug < MAX_ITEM_DIGITS)
                gTasks[taskId].tDigit_debug += 1;
        }

        StringCopy(gStringVar2, gText_DigitIndicator[gTasks[taskId].tDigit_debug]);
        ConvertIntToDecimalStringN(gStringVar1, gTasks[taskId].tInput_debug, STR_CONV_MODE_LEADING_ZEROS, DEBUG_NUMBER_DIGITS_ITEM_QUANTITY_debug);
        StringCopyPadded(gStringVar1, gStringVar1, CHAR_SPACE, 15);
        StringExpandPlaceholders(gStringVar4, sDebugText_ItemQuantity_debug);
        AddTextPrinterParameterized(gTasks[taskId].tSubWindowId_debug, DEBUG_MENU_FONT_debug, gStringVar4, 0, 0, 0, NULL);
    }

    if (JOY_NEW(A_BUTTON))
    {
        FreeSpriteTilesByTag(ITEM_TAG_debug);                             //Destroy item icon
        FreeSpritePaletteByTag(ITEM_TAG_debug);                           //Destroy item icon
        FreeSpriteOamMatrix(&gSprites[gTasks[taskId].tSpriteId_debug]);   //Destroy item icon
        DestroySprite(&gSprites[gTasks[taskId].tSpriteId_debug]);         //Destroy item icon

        PlaySE(MUS_LEVEL_UP);
        AddBagItem(itemId, gTasks[taskId].tInput_debug);
        DebugAction_DestroyExtraWindow_debug(taskId);
    }
    else if (JOY_NEW(B_BUTTON))
    {
        FreeSpriteTilesByTag(ITEM_TAG_debug);                             //Destroy item icon
        FreeSpritePaletteByTag(ITEM_TAG_debug);                           //Destroy item icon
        FreeSpriteOamMatrix(&gSprites[gTasks[taskId].tSpriteId_debug]);   //Destroy item icon
        DestroySprite(&gSprites[gTasks[taskId].tSpriteId_debug]);         //Destroy item icon

        PlaySE(SE_SELECT);
        DebugAction_DestroyExtraWindow_debug(taskId);
    }
}

