static void DebugAction_Give_Pokemon_SelectLevel_debug(u8 taskId)
{
    if (JOY_NEW(DPAD_ANY))
    {
        PlaySE(SE_SELECT);

        if (JOY_NEW(DPAD_UP))
        {
            gTasks[taskId].tInput_debug += sPowersOfTen_debug[gTasks[taskId].tDigit_debug];
            if (gTasks[taskId].tInput_debug > MAX_LEVEL)
                gTasks[taskId].tInput_debug = MAX_LEVEL;
        }
        if (JOY_NEW(DPAD_DOWN))
        {
            gTasks[taskId].tInput_debug -= sPowersOfTen_debug[gTasks[taskId].tDigit_debug];
            if (gTasks[taskId].tInput_debug < 1)
                gTasks[taskId].tInput_debug = 1;
        }
        if (JOY_NEW(DPAD_LEFT))
        {
            if (gTasks[taskId].tDigit_debug > 0)
                gTasks[taskId].tDigit_debug -= 1;
        }
        if (JOY_NEW(DPAD_RIGHT))
        {
            if (gTasks[taskId].tDigit_debug < 2)
                gTasks[taskId].tDigit_debug += 1;
        }

        StringCopy(gStringVar2, gText_DigitIndicator[gTasks[taskId].tDigit_debug]);
        ConvertIntToDecimalStringN(gStringVar1, gTasks[taskId].tInput_debug, STR_CONV_MODE_LEADING_ZEROS, 3);
        StringCopyPadded(gStringVar1, gStringVar1, CHAR_SPACE, 15);
        StringExpandPlaceholders(gStringVar4, sDebugText_PokemonLevel_debug);
        AddTextPrinterParameterized(gTasks[taskId].tSubWindowId_debug, DEBUG_MENU_FONT_debug, gStringVar4, 0, 0, 0, NULL);
    }

    if (JOY_NEW(A_BUTTON))
    {
        FreeMonIconPalettes();
        FreeAndDestroyMonIconSprite(&gSprites[gTasks[taskId].tSpriteId_debug]);
        if (gTasks[taskId].tIsComplex_debug == FALSE)
        {
            PlaySE(MUS_LEVEL_UP);
            ScriptGiveMon(sDebugMonData_debug->species, gTasks[taskId].tInput_debug, ITEM_NONE);
            // Set flag for user convenience
            FlagSet(FLAG_SYS_POKEMON_GET);
            Free(sDebugMonData_debug);
            DebugAction_DestroyExtraWindow_debug(taskId);
        }
        else
        {
            sDebugMonData_debug->level = gTasks[taskId].tInput_debug;
            gTasks[taskId].tInput_debug = 0;
            gTasks[taskId].tDigit_debug = 0;

            ConvertIntToDecimalStringN(gStringVar3, gTasks[taskId].tInput_debug, STR_CONV_MODE_LEADING_ZEROS, 0);
            StringCopyPadded(gStringVar3, gStringVar3, CHAR_SPACE, 15);
            StringCopyPadded(gStringVar2, sDebugText_False_debug, CHAR_SPACE, 15);
            StringExpandPlaceholders(gStringVar4, sDebugText_PokemonShiny_debug);
            AddTextPrinterParameterized(gTasks[taskId].tSubWindowId_debug, DEBUG_MENU_FONT_debug, gStringVar4, 0, 0, 0, NULL);

            gTasks[taskId].func = DebugAction_Give_Pokemon_SelectShiny_debug;
        }
    }
    else if (JOY_NEW(B_BUTTON))
    {
        PlaySE(SE_SELECT);
        Free(sDebugMonData_debug);
        FreeMonIconPalettes();
        FreeAndDestroyMonIconSprite(&gSprites[gTasks[taskId].tSpriteId_debug]);
        DebugAction_DestroyExtraWindow_debug(taskId);
    }
}

