static void DebugAction_Give_Pokemon_SelectAbility_debug(u8 taskId)
{
    u16 abilityId;
    u8 abilityCount = NUM_ABILITY_SLOTS - 1; //-1 for proper iteration
    u8 i = 0;

    if (JOY_NEW(DPAD_ANY))
    {
        PlaySE(SE_SELECT);

        if (JOY_NEW(DPAD_UP))
        {
            gTasks[taskId].tInput_debug += sPowersOfTen_debug[gTasks[taskId].tDigit_debug];
            if (gTasks[taskId].tInput_debug > abilityCount)
                gTasks[taskId].tInput_debug = abilityCount;
        }
        if (JOY_NEW(DPAD_DOWN))
        {
            gTasks[taskId].tInput_debug -= sPowersOfTen_debug[gTasks[taskId].tDigit_debug];
            if (gTasks[taskId].tInput_debug < 0)
                gTasks[taskId].tInput_debug = 0;
        }

        while (GetAbilityBySpecies(sDebugMonData_debug->species, gTasks[taskId].tInput_debug - i) == ABILITY_NONE && gTasks[taskId].tInput_debug - i < NUM_ABILITY_SLOTS)
        {
            i++;
        }
        abilityId = GetAbilityBySpecies(sDebugMonData_debug->species, gTasks[taskId].tInput_debug - i);
        StringCopy(gStringVar2, gText_DigitIndicator[gTasks[taskId].tDigit_debug]);
        ConvertIntToDecimalStringN(gStringVar3, gTasks[taskId].tInput_debug, STR_CONV_MODE_LEADING_ZEROS, 2);
        StringCopyPadded(gStringVar3, gStringVar3, CHAR_SPACE, 15);
        u8 *end = StringCopy(gStringVar1, gAbilitiesInfo[abilityId].name);
        WrapFontIdToFit(gStringVar1, end, DEBUG_MENU_FONT_debug, WindowWidthPx(gTasks[taskId].tSubWindowId_debug));
        StringExpandPlaceholders(gStringVar4, sDebugText_PokemonAbility_debug);
        AddTextPrinterParameterized(gTasks[taskId].tSubWindowId_debug, DEBUG_MENU_FONT_debug, gStringVar4, 0, 0, 0, NULL);
    }

    if (JOY_NEW(A_BUTTON))
    {
        sDebugMonData_debug->abilityNum = gTasks[taskId].tInput_debug - i;
        gTasks[taskId].tInput_debug = 0;
        gTasks[taskId].tDigit_debug = 0;

        StringCopy(gStringVar2, gText_DigitIndicator[gTasks[taskId].tDigit_debug]);
        ConvertIntToDecimalStringN(gStringVar3, gTasks[taskId].tInput_debug, STR_CONV_MODE_LEADING_ZEROS, 2);
        StringCopyPadded(gStringVar3, gStringVar3, CHAR_SPACE, 15);
        StringExpandPlaceholders(gStringVar4, sDebugText_IV_HP_debug);
        AddTextPrinterParameterized(gTasks[taskId].tSubWindowId_debug, DEBUG_MENU_FONT_debug, gStringVar4, 0, 0, 0, NULL);

        gTasks[taskId].func = DebugAction_Give_Pokemon_SelectIVs_debug;
    }
    else if (JOY_NEW(B_BUTTON))
    {
        PlaySE(SE_SELECT);
        Free(sDebugMonData_debug);
        DebugAction_DestroyExtraWindow_debug(taskId);
    }
}

