void InitDecorationContextItems(void)
{
    if (sCurDecorationCategory_decoration < DECORCAT_COUNT)
        gCurDecorationItems = gDecorationInventories[sCurDecorationCategory_decoration].items;

    if (sDecorationContext_decoration.isPlayerRoom == FALSE)
    {
        sDecorationContext_decoration.items = gSaveBlock1Ptr->secretBases[0].decorations;
        sDecorationContext_decoration.pos = gSaveBlock1Ptr->secretBases[0].decorationPositions;
    }

    if (sDecorationContext_decoration.isPlayerRoom == TRUE)
    {
        sDecorationContext_decoration.items = gSaveBlock1Ptr->playerRoomDecorations;
        sDecorationContext_decoration.pos = gSaveBlock1Ptr->playerRoomDecorationPositions;
    }
}

static u8 AddDecorationWindow_decoration(u8 windowIndex)
{
    u8 *windowId;
    struct WindowTemplate template;

    windowId = &sDecorMenuWindowIds_decoration[windowIndex];
    if (windowIndex == WINDOW_MAIN_MENU_decoration)
    {
        template = sDecorationWindowTemplates_decoration[WINDOW_MAIN_MENU_decoration];
        template.width = GetMaxWidthInMenuTable(sDecorationMainMenuActions_decoration, ARRAY_COUNT(sDecorationMainMenuActions_decoration));
        if (template.width > 18)
            template.width = 18;

        *windowId = AddWindow(&template);
    }
    else
    {
        *windowId = AddWindow(&sDecorationWindowTemplates_decoration[windowIndex]);
    }

    DrawStdFrameWithCustomTileAndPalette(*windowId, FALSE, 0x214, 14);
    ScheduleBgCopyTilemapToVram(0);
    return *windowId;
}

static void RemoveDecorationWindow_decoration(u8 windowIndex)
{
    ClearStdWindowAndFrameToTransparent(sDecorMenuWindowIds_decoration[windowIndex], FALSE);
    ClearWindowTilemap(sDecorMenuWindowIds_decoration[windowIndex]);
    RemoveWindow(sDecorMenuWindowIds_decoration[windowIndex]);
    ScheduleBgCopyTilemapToVram(0);
}

static void AddDecorationActionsWindow_decoration(void)
{
    u8 windowId = AddDecorationWindow_decoration(WINDOW_MAIN_MENU_decoration);
    PrintMenuTable(windowId, ARRAY_COUNT(sDecorationMainMenuActions_decoration), sDecorationMainMenuActions_decoration);
    InitMenuInUpperLeftCornerNormal(windowId, ARRAY_COUNT(sDecorationMainMenuActions_decoration), sDecorationActionsCursorPos_decoration);
}

static void InitDecorationActionsWindow_decoration(void)
{
    sDecorationActionsCursorPos_decoration = 0;
    LockPlayerFieldControls();
    AddDecorationActionsWindow_decoration();
    PrintCurMainMenuDescription_decoration();
}

void DoSecretBaseDecorationMenu(u8 taskId)
{
    InitDecorationActionsWindow_decoration();
    sDecorationContext_decoration.items = gSaveBlock1Ptr->secretBases[0].decorations;
    sDecorationContext_decoration.pos = gSaveBlock1Ptr->secretBases[0].decorationPositions;
    sDecorationContext_decoration.size = DECOR_MAX_SECRET_BASE;
    sDecorationContext_decoration.isPlayerRoom = FALSE;
    gTasks[taskId].func = HandleDecorationActionsMenuInput_decoration;
}

void DoPlayerRoomDecorationMenu(u8 taskId)
{
    InitDecorationActionsWindow_decoration();
    sDecorationContext_decoration.items = gSaveBlock1Ptr->playerRoomDecorations;
    sDecorationContext_decoration.pos = gSaveBlock1Ptr->playerRoomDecorationPositions;
    sDecorationContext_decoration.size = DECOR_MAX_PLAYERS_HOUSE;
    sDecorationContext_decoration.isPlayerRoom = TRUE;
    gTasks[taskId].func = HandleDecorationActionsMenuInput_decoration;
}

static void HandleDecorationActionsMenuInput_decoration(u8 taskId)
{
    if (!gPaletteFade.active)
    {
        s8 menuPos = Menu_GetCursorPos();
        switch (Menu_ProcessInput())
        {
        default:
            PlaySE(SE_SELECT);
            sDecorationMainMenuActions_decoration[sDecorationActionsCursorPos_decoration].func.void_u8(taskId);
            break;
        case MENU_NOTHING_CHOSEN:
            sDecorationActionsCursorPos_decoration = Menu_GetCursorPos();
            if (menuPos != sDecorationActionsCursorPos_decoration)
                PrintCurMainMenuDescription_decoration();
            break;
        case MENU_B_PRESSED:
            PlaySE(SE_SELECT);
            DecorationMenuAction_Cancel_decoration(taskId);
            break;
        }
    }
}

static void PrintCurMainMenuDescription_decoration(void)
{
    FillWindowPixelBuffer(0, PIXEL_FILL(1));
    AddTextPrinterParameterized2(0, FONT_NORMAL, sSecretBasePCMenuItemDescriptions_decoration[sDecorationActionsCursorPos_decoration], 0, 0, TEXT_COLOR_DARK_GRAY, TEXT_COLOR_WHITE, TEXT_COLOR_LIGHT_GRAY);
}

static void DecorationMenuAction_Decorate_decoration(u8 taskId)
{
    if (GetNumOwnedDecorations() == 0)
    {
        StringExpandPlaceholders(gStringVar4, gText_NoDecorations);
        DisplayItemMessageOnField(taskId, gStringVar4, ReturnToDecorationActionsAfterInvalidSelection_decoration);
    }
    else
    {
        gTasks[taskId].tDecorationMenuCommand_decoration = DECOR_MENU_PLACE_decoration;
        sCurDecorationCategory_decoration = DECORCAT_DESK;
        SecretBasePC_PrepMenuForSelectingStoredDecors_decoration(taskId);
    }
}

static void DecorationMenuAction_PutAway_decoration(u8 taskId)
{
    if (!HasDecorationsInUse_decoration(taskId))
    {
        StringExpandPlaceholders(gStringVar4, gText_NoDecorationsInUse);
        DisplayItemMessageOnField(taskId, gStringVar4, ReturnToDecorationActionsAfterInvalidSelection_decoration);
    }
    else
    {
        RemoveDecorationWindow_decoration(WINDOW_MAIN_MENU_decoration);
        ClearDialogWindowAndFrame(0, FALSE);
        FadeScreen(FADE_TO_BLACK, 0);
        gTasks[taskId].tState_decoration = 0;
        gTasks[taskId].func = Task_ContinuePuttingAwayDecorations_decoration;
    }
}

static void DecorationMenuAction_Toss_decoration(u8 taskId)
{
    if (GetNumOwnedDecorations() == 0)
    {
        StringExpandPlaceholders(gStringVar4, gText_NoDecorations);
        DisplayItemMessageOnField(taskId, gStringVar4, ReturnToDecorationActionsAfterInvalidSelection_decoration);
    }
    else
    {
        gTasks[taskId].tDecorationMenuCommand_decoration = DECOR_MENU_TOSS_decoration;
        sCurDecorationCategory_decoration = DECORCAT_DESK;
        SecretBasePC_PrepMenuForSelectingStoredDecors_decoration(taskId);
    }
}

static void DecorationMenuAction_Cancel_decoration(u8 taskId)
{
    RemoveDecorationWindow_decoration(WINDOW_MAIN_MENU_decoration);
    if (!sDecorationContext_decoration.isPlayerRoom)
    {
        ScriptContext_SetupScript(SecretBase_EventScript_PCCancel);
        DestroyTask(taskId);
    }
    else
    {
        ReshowPlayerPC(taskId);
    }
}

static void ReturnToDecorationActionsAfterInvalidSelection_decoration(u8 taskId)
{
    PrintCurMainMenuDescription_decoration();
    gTasks[taskId].func = HandleDecorationActionsMenuInput_decoration;
}

static void SecretBasePC_PrepMenuForSelectingStoredDecors_decoration(u8 taskId)
{
    LoadPalette(sDecorationMenuPalette_decoration, BG_PLTT_ID(13), sizeof(sDecorationMenuPalette_decoration));
    ClearDialogWindowAndFrame(0, FALSE);
    RemoveDecorationWindow_decoration(WINDOW_MAIN_MENU_decoration);
    InitDecorationCategoriesWindow_decoration(taskId);
}

static void InitDecorationCategoriesWindow_decoration(u8 taskId)
{
    u8 windowId = AddDecorationWindow_decoration(WINDOW_DECORATION_CATEGORIES_decoration);
    PrintDecorationCategoryMenuItems_decoration(taskId);
    InitMenuInUpperLeftCornerNormal(windowId, DECORCAT_COUNT + 1, sCurDecorationCategory_decoration);
    gTasks[taskId].func = HandleDecorationCategoriesMenuInput_decoration;
}

static void ReinitDecorationCategoriesWindow_decoration(u8 taskId)
{
    FillWindowPixelBuffer(sDecorMenuWindowIds_decoration[WINDOW_DECORATION_CATEGORIES_decoration], PIXEL_FILL(1));
    PrintDecorationCategoryMenuItems_decoration(taskId);
    InitMenuInUpperLeftCornerNormal(sDecorMenuWindowIds_decoration[WINDOW_DECORATION_CATEGORIES_decoration], DECORCAT_COUNT + 1, sCurDecorationCategory_decoration);
    gTasks[taskId].func = HandleDecorationCategoriesMenuInput_decoration;
}

static void PrintDecorationCategoryMenuItems_decoration(u8 taskId)
{
    u8 i;
    s16 *data = gTasks[taskId].data;
    u8 windowId = sDecorMenuWindowIds_decoration[WINDOW_DECORATION_CATEGORIES_decoration];
    bool8 isPlayerRoom = sDecorationContext_decoration.isPlayerRoom;
    bool8 shouldDisable = FALSE;
    if (isPlayerRoom == TRUE && tDecorationMenuCommand_decoration == DECOR_MENU_PLACE_decoration)
        shouldDisable = TRUE;

    for (i = 0; i < DECORCAT_COUNT; i++)
    {
        // Only DOLL and CUSHION decorations are enabled when decorating the player's room.
        if (shouldDisable == TRUE && i != DECORCAT_DOLL && i != DECORCAT_CUSHION)
            PrintDecorationCategoryMenuItem_decoration(windowId, i, 8, i * 16, TRUE, TEXT_SKIP_DRAW);
        else
            PrintDecorationCategoryMenuItem_decoration(windowId, i, 8, i * 16, FALSE, TEXT_SKIP_DRAW);
    }

    AddTextPrinterParameterized(windowId, FONT_NORMAL, gTasks[taskId].tDecorationMenuCommand_decoration == DECOR_MENU_TRADE_decoration ? gText_Exit : gText_Cancel, 8, i * 16 + 1, 0, NULL);
    ScheduleBgCopyTilemapToVram(0);
}

static void PrintDecorationCategoryMenuItem_decoration(u8 winid, u8 category, u8 x, u8 y, bool8 disabled, u8 speed)
{
    u8 width;
    u8 *str;

    width = x == 8 ? 104 : 96;
    y++;
    ColorMenuItemString_decoration(gStringVar4, disabled);
    str = StringLength(gStringVar4) + gStringVar4;
    StringCopy(str, sDecorationCategoryNames_decoration[category]);
    AddTextPrinterParameterized(winid, FONT_NORMAL, gStringVar4, x, y, speed, NULL);
    str = ConvertIntToDecimalStringN(str, GetNumOwnedDecorationsInCategory(category), STR_CONV_MODE_RIGHT_ALIGN, 2);
    *(str++) = CHAR_SLASH;
    ConvertIntToDecimalStringN(str, gDecorationInventories[category].size, STR_CONV_MODE_RIGHT_ALIGN, 2);
    x = GetStringRightAlignXOffset(FONT_NORMAL, gStringVar4, width);
    AddTextPrinterParameterized(winid, FONT_NORMAL, gStringVar4, x, y, speed, NULL);
}

static void ColorMenuItemString_decoration(u8 *str, bool8 disabled)
{
    StringCopy(str, gText_Color161Shadow161);
    if (disabled == TRUE)
    {
        str[2] = 4;
        str[5] = 5;
    }
    else
    {
        str[2] = 2;
        str[5] = 3;
    }
}

static void HandleDecorationCategoriesMenuInput_decoration(u8 taskId)
{
    if (!gPaletteFade.active)
    {
        s8 input = Menu_ProcessInput();
        switch (input)
        {
        case MENU_B_PRESSED:
        case DECORCAT_COUNT: // CANCEL
            PlaySE(SE_SELECT);
            ExitDecorationCategoriesMenu_decoration(taskId);
            break;
        case MENU_NOTHING_CHOSEN:
            break;
        default:
            PlaySE(SE_SELECT);
            sCurDecorationCategory_decoration = input;
            SelectDecorationCategory_decoration(taskId);
            break;
        }
    }
}

static void SelectDecorationCategory_decoration(u8 taskId)
{
    sNumOwnedDecorationsInCurCategory_decoration = GetNumOwnedDecorationsInCategory(sCurDecorationCategory_decoration);
    if (sNumOwnedDecorationsInCurCategory_decoration != 0)
    {
        CondenseDecorationsInCategory(sCurDecorationCategory_decoration);
        gCurDecorationItems = gDecorationInventories[sCurDecorationCategory_decoration].items;
        IdentifyOwnedDecorationsCurrentlyInUse_decoration(taskId);
        sDecorationsScrollOffset_decoration = 0;
        sDecorationsCursorPos_decoration = 0;
        gTasks[taskId].func = ShowDecorationItemsWindow_decoration;
    }
    else
    {
        RemoveDecorationWindow_decoration(WINDOW_DECORATION_CATEGORIES_decoration);
        StringExpandPlaceholders(gStringVar4, gText_NoDecorations);
        DisplayItemMessageOnField(taskId, gStringVar4, ReturnToDecorationCategoriesAfterInvalidSelection_decoration);
    }
}

static void ReturnToDecorationCategoriesAfterInvalidSelection_decoration(u8 taskId)
{
    ClearDialogWindowAndFrame(0, FALSE);
    InitDecorationCategoriesWindow_decoration(taskId);
}

static void ExitDecorationCategoriesMenu_decoration(u8 taskId)
{
    if (gTasks[taskId].tDecorationMenuCommand_decoration != DECOR_MENU_TRADE_decoration)
        ReturnToActionsMenuFromCategories_decoration(taskId);
    else
        ExitTraderDecorationMenu_decoration(taskId);
}

static void ReturnToActionsMenuFromCategories_decoration(u8 taskId)
{
    RemoveDecorationWindow_decoration(WINDOW_DECORATION_CATEGORIES_decoration);
    AddDecorationActionsWindow_decoration();
    DrawDialogueFrame(0, FALSE);
    PrintCurMainMenuDescription_decoration();
    gTasks[taskId].func = HandleDecorationActionsMenuInput_decoration;
}

void ShowDecorationCategoriesWindow(u8 taskId)
{
    LoadPalette(sDecorationMenuPalette_decoration, BG_PLTT_ID(13), sizeof(sDecorationMenuPalette_decoration));
    ClearDialogWindowAndFrame(0, FALSE);
    gTasks[taskId].tDecorationMenuCommand_decoration = DECOR_MENU_TRADE_decoration;
    sCurDecorationCategory_decoration = DECORCAT_DESK;
    InitDecorationCategoriesWindow_decoration(taskId);
}

void CopyDecorationCategoryName(u8 *dest, u8 category)
{
    StringCopy(dest, sDecorationCategoryNames_decoration[category]);
}

static void ExitTraderDecorationMenu_decoration(u8 taskId)
{
    RemoveDecorationWindow_decoration(WINDOW_DECORATION_CATEGORIES_decoration);
    ExitTraderMenu(taskId);
}

static void InitDecorationItemsMenuLimits_decoration(void)
{
    sDecorationItemsMenu_decoration->numMenuItems = sNumOwnedDecorationsInCurCategory_decoration + 1;
    if (sDecorationItemsMenu_decoration->numMenuItems > 8)
        sDecorationItemsMenu_decoration->maxShownItems = 8;
    else
        sDecorationItemsMenu_decoration->maxShownItems = sDecorationItemsMenu_decoration->numMenuItems;
}

static void InitDecorationItemsMenuScrollAndCursor_decoration(void)
{
    SetCursorWithinListBounds(&sDecorationsScrollOffset_decoration, &sDecorationsCursorPos_decoration, sDecorationItemsMenu_decoration->maxShownItems, sDecorationItemsMenu_decoration->numMenuItems);
}

static void InitDecorationItemsMenuScrollAndCursor2_decoration(void)
{
    SetCursorScrollWithinListBounds(&sDecorationsScrollOffset_decoration, &sDecorationsCursorPos_decoration, sDecorationItemsMenu_decoration->maxShownItems, sDecorationItemsMenu_decoration->numMenuItems, 8);
}

static void PrintDecorationItemMenuItems_decoration(u8 taskId)
{
    s16 *data;
    u16 i;

    data = gTasks[taskId].data;
    if ((sCurDecorationCategory_decoration < DECORCAT_DOLL || sCurDecorationCategory_decoration > DECORCAT_CUSHION) && sDecorationContext_decoration.isPlayerRoom == TRUE && tDecorationMenuCommand_decoration == DECOR_MENU_PLACE_decoration)
        ColorMenuItemString_decoration(gStringVar1, TRUE);
    else
        ColorMenuItemString_decoration(gStringVar1, FALSE);

    for (i = 0; i < sDecorationItemsMenu_decoration->numMenuItems - 1; i++)
    {
        CopyDecorationMenuItemName_decoration(sDecorationItemsMenu_decoration->names[i], gCurDecorationItems[i]);
        sDecorationItemsMenu_decoration->items[i].name = sDecorationItemsMenu_decoration->names[i];
        sDecorationItemsMenu_decoration->items[i].id = i;
    }

    StringCopy(sDecorationItemsMenu_decoration->names[i], gText_Cancel);
    sDecorationItemsMenu_decoration->items[i].name = sDecorationItemsMenu_decoration->names[i];
    sDecorationItemsMenu_decoration->items[i].id = LIST_CANCEL;
    gMultiuseListMenuTemplate = sDecorationItemsListMenuTemplate_decoration;
    gMultiuseListMenuTemplate.windowId = sDecorMenuWindowIds_decoration[WINDOW_DECORATION_CATEGORIES_decoration];
    gMultiuseListMenuTemplate.totalItems = sDecorationItemsMenu_decoration->numMenuItems;
    gMultiuseListMenuTemplate.items = sDecorationItemsMenu_decoration->items;
    gMultiuseListMenuTemplate.maxShowed = sDecorationItemsMenu_decoration->maxShownItems;
}

