static void HandleDecorationItemsMenuInput_decoration(u8 taskId)
{
    s16 *data;
    s32 input;

    data = gTasks[taskId].data;
    if (!gPaletteFade.active)
    {
        input = ListMenu_ProcessInput(tMenuTaskId_decoration);
        ListMenuGetScrollAndRow(tMenuTaskId_decoration, &sDecorationsScrollOffset_decoration, &sDecorationsCursorPos_decoration);
        switch (input)
        {
        case LIST_NOTHING_CHOSEN:
            break;
        case LIST_CANCEL:
            PlaySE(SE_SELECT);
            sSecretBasePC_SelectedDecorationActions_decoration[tDecorationMenuCommand_decoration][1](taskId);
            break;
        default:
            PlaySE(SE_SELECT);
            gCurDecorationIndex = input;
            RemoveDecorationItemsScrollIndicators_decoration();
            DestroyListMenuTask(tMenuTaskId_decoration, &sDecorationsScrollOffset_decoration, &sDecorationsCursorPos_decoration);
            RemoveDecorationWindow_decoration(WINDOW_DECORATION_CATEGORIES_decoration);
            RemoveDecorationItemsOtherWindows_decoration();
            Free(sDecorationItemsMenu_decoration);
            sSecretBasePC_SelectedDecorationActions_decoration[tDecorationMenuCommand_decoration][0](taskId);
            break;
        }
    }
}

