static bool8 IsDecorationIndexInSecretBase_decoration(u8 idx)
{
    u8 i;
    for (i = 0; i < ARRAY_COUNT(sSecretBaseItemsIndicesBuffer_decoration); i++)
    {
        if (sSecretBaseItemsIndicesBuffer_decoration[i] == idx)
            return TRUE;
    }

    return FALSE;
}

static bool8 IsDecorationIndexInPlayersRoom_decoration(u8 idx)
{
    u8 i;
    for (i = 0; i < ARRAY_COUNT(sPlayerRoomItemsIndicesBuffer_decoration); i++)
    {
        if (sPlayerRoomItemsIndicesBuffer_decoration[i] == idx)
            return TRUE;
    }

    return FALSE;
}

static void IdentifyOwnedDecorationsCurrentlyInUseInternal_decoration(u8 taskId)
{
    u16 i, j, k;
    u16 count;

    count = 0;
    memset(sSecretBaseItemsIndicesBuffer_decoration, 0, sizeof(sSecretBaseItemsIndicesBuffer_decoration));
    memset(sPlayerRoomItemsIndicesBuffer_decoration, 0, sizeof(sPlayerRoomItemsIndicesBuffer_decoration));

    for (i = 0; i < ARRAY_COUNT(sSecretBaseItemsIndicesBuffer_decoration); i++)
    {
        if (gSaveBlock1Ptr->secretBases[0].decorations[i] != DECOR_NONE)
        {
            for (j = 0; j < gDecorationInventories[sCurDecorationCategory_decoration].size; j++)
            {
                if (gCurDecorationItems[j] == gSaveBlock1Ptr->secretBases[0].decorations[i])
                {
                    for (k = 0; k < count && sSecretBaseItemsIndicesBuffer_decoration[k] != j + 1; k++)
                        ;

                    if (k == count)
                    {
                        sSecretBaseItemsIndicesBuffer_decoration[count] = j + 1;
                        count++;
                        break;
                    }
                }
            }
        }
    }

    count = 0;
    for (i = 0; i < ARRAY_COUNT(sPlayerRoomItemsIndicesBuffer_decoration); i++)
    {
        if (gSaveBlock1Ptr->playerRoomDecorations[i] != DECOR_NONE)
        {
            for (j = 0; j < gDecorationInventories[sCurDecorationCategory_decoration].size; j++)
            {
                if (gCurDecorationItems[j] == gSaveBlock1Ptr->playerRoomDecorations[i] && IsDecorationIndexInSecretBase_decoration(j + 1) != TRUE)
                {
                    for (k = 0; k < count && sPlayerRoomItemsIndicesBuffer_decoration[k] != j + 1; k++);
                    if (k == count)
                    {
                        sPlayerRoomItemsIndicesBuffer_decoration[count] = j + 1;
                        count++;
                        break;
                    }
                }
            }
        }
    }
}

static void IdentifyOwnedDecorationsCurrentlyInUse_decoration(u8 taskId)
{
    IdentifyOwnedDecorationsCurrentlyInUseInternal_decoration(taskId);
}

bool8 IsSelectedDecorInThePC(void)
{
    u16 i;
    for (i = 0; i < ARRAY_COUNT(sSecretBaseItemsIndicesBuffer_decoration); i++)
    {
        if (sSecretBaseItemsIndicesBuffer_decoration[i] == sDecorationsScrollOffset_decoration + sDecorationsCursorPos_decoration + 1)
            return FALSE;

        if (i < ARRAY_COUNT(sPlayerRoomItemsIndicesBuffer_decoration)
         && sPlayerRoomItemsIndicesBuffer_decoration[i] == sDecorationsScrollOffset_decoration + sDecorationsCursorPos_decoration + 1)
        {
            return FALSE;
        }
    }

    return TRUE;
}

