static u16 GetDecorationElevation_decoration(u8 decoration, u8 tileIndex)
{
    u16 elevation = -1;
    switch (decoration)
    {
    case DECOR_STAND:
        elevation = sDecorationStandElevations_decoration[tileIndex] << MAPGRID_ELEVATION_SHIFT;
        return elevation;
    case DECOR_SLIDE:
        elevation = sDecorationSlideElevation_decoration[tileIndex] << MAPGRID_ELEVATION_SHIFT;
        return elevation;
    default:
        return elevation;
    }
}

static void ShowDecorationOnMap__decoration(u16 mapX, u16 mapY, u8 decWidth, u8 decHeight, u16 decoration)
{
    u16 i, j;
    s16 x, y;
    u16 attributes;
    u16 impassableFlag;
    u16 overlapsWall;
    u16 elevation;

    for (j = 0; j < decHeight; j++)
    {
        y = mapY - decHeight + 1 + j;
        for (i = 0; i < decWidth; i++)
        {
            x = mapX + i;
            attributes = GetMetatileAttributesById(NUM_TILES_IN_PRIMARY + gDecorations[decoration].tiles[j * decWidth + i]);
            if (MetatileBehavior_IsSecretBaseImpassable(attributes & METATILE_ATTR_BEHAVIOR_MASK) == TRUE
             || (gDecorations[decoration].permission != DECORPERM_PASS_FLOOR && (attributes >> METATILE_ATTR_LAYER_SHIFT) != METATILE_LAYER_TYPE_NORMAL))
                impassableFlag = MAPGRID_COLLISION_MASK;
            else
                impassableFlag = 0;

            // Choose the metatile that has the wall background instead of the floor if overlapping a wall.
            if (gDecorations[decoration].permission != DECORPERM_NA_WALL && MetatileBehavior_IsSecretBaseNorthWall(MapGridGetMetatileBehaviorAt(x, y)) == TRUE)
                overlapsWall = 1;
            else
                overlapsWall = 0;

            elevation = GetDecorationElevation_decoration(gDecorations[decoration].id, j * decWidth + i);
            if (elevation != 0xFFFF)
                MapGridSetMetatileEntryAt(x, y, (gDecorations[decoration].tiles[j * decWidth + i] + (NUM_TILES_IN_PRIMARY | overlapsWall)) | impassableFlag | elevation);
            else
                MapGridSetMetatileIdAt(x, y, (gDecorations[decoration].tiles[j * decWidth + i] + (NUM_TILES_IN_PRIMARY | overlapsWall)) | impassableFlag);
        }
    }
}

void ShowDecorationOnMap(u16 mapX, u16 mapY, u16 decoration)
{
    switch (gDecorations[decoration].shape)
    {
    case DECORSHAPE_1x1:
        ShowDecorationOnMap__decoration(mapX, mapY, 1, 1, decoration);
        break;
    case DECORSHAPE_2x1:
        ShowDecorationOnMap__decoration(mapX, mapY, 2, 1, decoration);
        break;
    case DECORSHAPE_3x1: // unused
        ShowDecorationOnMap__decoration(mapX, mapY, 3, 1, decoration);
        break;
    case DECORSHAPE_4x2:
        ShowDecorationOnMap__decoration(mapX, mapY, 4, 2, decoration);
        break;
    case DECORSHAPE_2x2:
        ShowDecorationOnMap__decoration(mapX, mapY, 2, 2, decoration);
        break;
    case DECORSHAPE_1x2:
        ShowDecorationOnMap__decoration(mapX, mapY, 1, 2, decoration);
        break;
    case DECORSHAPE_1x3: // unused
        ShowDecorationOnMap__decoration(mapX, mapY, 1, 3, decoration);
        break;
    case DECORSHAPE_2x4:
        ShowDecorationOnMap__decoration(mapX, mapY, 2, 4, decoration);
        break;
    case DECORSHAPE_3x3:
        ShowDecorationOnMap__decoration(mapX, mapY, 3, 3, decoration);
        break;
    case DECORSHAPE_3x2:
        ShowDecorationOnMap__decoration(mapX, mapY, 3, 2, decoration);
        break;
    }
}

void SetDecoration(void)
{
    u8 i;
    u8 j;

    for (i = 0; i < NUM_DECORATION_FLAGS_decoration; i++)
    {
        if (FlagGet(FLAG_DECORATION_1 + i) == TRUE)
        {
            FlagClear(FLAG_DECORATION_1 + i);
            for (j = 0; j < gMapHeader.events->objectEventCount; j++)
            {
                if (gMapHeader.events->objectEvents[j].flagId == FLAG_DECORATION_1 + i)
                    break;
            }

            VarSet(
                VAR_OBJ_GFX_ID_0 + (gMapHeader.events->objectEvents[j].graphicsId - OBJ_EVENT_GFX_VAR_0),
                sPlaceDecorationGraphicsDataBuffer_decoration.decoration->tiles[0]);

            gSpecialVar_0x8005 = gMapHeader.events->objectEvents[j].localId;
            gSpecialVar_0x8006 = sCurDecorMapX_decoration;
            gSpecialVar_0x8007 = sCurDecorMapY_decoration;
            TrySpawnObjectEvent(gSpecialVar_0x8005, gSaveBlock1Ptr->location.mapNum, gSaveBlock1Ptr->location.mapGroup);
            TryMoveObjectEventToMapCoords(gSpecialVar_0x8005, gSaveBlock1Ptr->location.mapNum, gSaveBlock1Ptr->location.mapGroup, gSpecialVar_0x8006, gSpecialVar_0x8007);
            TryOverrideObjectEventTemplateCoords(gSpecialVar_0x8005, gSaveBlock1Ptr->location.mapNum, gSaveBlock1Ptr->location.mapGroup);
            break;
        }
    }
}

static bool8 HasDecorationSpace_decoration(void)
{
    u16 i;
    for (i = 0; i < sDecorationContext_decoration.size; i++)
    {
        if (sDecorationContext_decoration.items[i] == DECOR_NONE)
            return TRUE;
    }

    return FALSE;
}

static void DecorationItemsMenuAction_AttemptPlace_decoration(u8 taskId)
{
    if (sDecorationContext_decoration.isPlayerRoom == TRUE && sCurDecorationCategory_decoration != DECORCAT_DOLL && sCurDecorationCategory_decoration != DECORCAT_CUSHION)
    {
        StringExpandPlaceholders(gStringVar4, gText_CantPlaceInRoom);
        DisplayItemMessageOnField(taskId, gStringVar4, ReturnToDecorationItemsAfterInvalidSelection_decoration);
    }
    else if (IsSelectedDecorInThePC() == TRUE)
    {
        if (HasDecorationSpace_decoration() == TRUE)
        {
            FadeScreen(FADE_TO_BLACK, 0);
            gTasks[taskId].tState_decoration = 0;
            gTasks[taskId].func = Task_PlaceDecoration_decoration;
        }
        else
        {
            ConvertIntToDecimalStringN(gStringVar1, sDecorationContext_decoration.size, STR_CONV_MODE_RIGHT_ALIGN, 2);
            if (sDecorationContext_decoration.isPlayerRoom == FALSE)
            {
                StringExpandPlaceholders(gStringVar4, gText_NoMoreDecorations);
            }
            else
            {
                StringExpandPlaceholders(gStringVar4, gText_NoMoreDecorations2);
            }
            DisplayItemMessageOnField(taskId, gStringVar4, ReturnToDecorationItemsAfterInvalidSelection_decoration);
        }
    }
    else
    {
        StringExpandPlaceholders(gStringVar4, gText_InUseAlready);
        DisplayItemMessageOnField(taskId, gStringVar4, ReturnToDecorationItemsAfterInvalidSelection_decoration);
    }
}

static void Task_PlaceDecoration_decoration(u8 taskId)
{
    switch (gTasks[taskId].tState_decoration)
    {
        case 0:
            if (!gPaletteFade.active)
            {
                SetInitialPositions_decoration(taskId);
                gTasks[taskId].tState_decoration = 1;
            }
            break;
        case 1:
            RemoveFollowingPokemon();
            gPaletteFade.bufferTransferDisabled = TRUE;
            ConfigureCameraObjectForPlacingDecoration_decoration(&sPlaceDecorationGraphicsDataBuffer_decoration, gCurDecorationItems[gCurDecorationIndex]);
            SetUpDecorationShape_decoration(taskId);
            SetUpPlacingDecorationPlayerAvatar_decoration(taskId, &sPlaceDecorationGraphicsDataBuffer_decoration);
            FadeInFromBlack();
            gPaletteFade.bufferTransferDisabled = FALSE;
            gTasks[taskId].tState_decoration = 2;
            break;
        case 2:
            if (IsWeatherNotFadingIn() == TRUE)
            {
                gTasks[taskId].tDecorationItemsMenuCommand_decoration = DECOR_ITEMS_MENU_PLACE_decoration;
                ContinueDecorating_decoration(taskId);
            }
            break;
    }
}

static void ConfigureCameraObjectForPlacingDecoration_decoration(struct PlaceDecorationGraphicsDataBuffer *data, u8 decor)
{
    sDecor_CameraSpriteObjectIdx1_decoration = gSprites[gFieldCamera.spriteId].data[0];
    gFieldCamera.spriteId = gpu_pal_decompress_alloc_tag_and_upload_decoration(data, decor);
    gSprites[gFieldCamera.spriteId].oam.priority = 1;
    gSprites[gFieldCamera.spriteId].callback = InitializePuttingAwayCursorSprite_decoration;
    gSprites[gFieldCamera.spriteId].x = sDecorationMovementInfo_decoration[data->decoration->shape].cameraX;
    gSprites[gFieldCamera.spriteId].y = sDecorationMovementInfo_decoration[data->decoration->shape].cameraY;
}

static void SetUpPlacingDecorationPlayerAvatar_decoration(u8 taskId, struct PlaceDecorationGraphicsDataBuffer *data)
{
    u8 x;

    x = 16 * (u8)gTasks[taskId].tDecorWidth_decoration + sDecorationMovementInfo_decoration[data->decoration->shape].cameraX - 8 * ((u8)gTasks[taskId].tDecorWidth_decoration - 1);
    if (data->decoration->shape == DECORSHAPE_3x1 || data->decoration->shape == DECORSHAPE_3x3 || data->decoration->shape == DECORSHAPE_3x2)
        x -= 8;

    if (gSaveBlock2Ptr->playerGender == MALE)
        sDecor_CameraSpriteObjectIdx2_decoration = CreateObjectGraphicsSprite(OBJ_EVENT_GFX_BRENDAN_DECORATING, SpriteCallbackDummy, x, 72, 0);
    else
        sDecor_CameraSpriteObjectIdx2_decoration = CreateObjectGraphicsSprite(OBJ_EVENT_GFX_MAY_DECORATING, SpriteCallbackDummy, x, 72, 0);

    gSprites[sDecor_CameraSpriteObjectIdx2_decoration].oam.priority = 1;
    DestroySprite(&gSprites[sDecor_CameraSpriteObjectIdx1_decoration]);
    sDecor_CameraSpriteObjectIdx1_decoration = gFieldCamera.spriteId;
}

