static s16 GetSearchWindowY_dexnav(void)
{
    return (GetWindowAttribute(sDexNavSearchDataPtr_dexnav->windowId, WINDOW_TILEMAP_TOP) * 8);
}

#define SPECIES_ICON_X_dexnav 28
static void DrawDexNavSearchMonIcon_dexnav(u16 species, u8 *dst, bool8 owned)
{
    u8 spriteId;

    LoadMonIconPalette(species);
    spriteId = CreateMonIcon(species, SpriteCB_MonIcon, SPECIES_ICON_X_dexnav - 6, GetSearchWindowY_dexnav() + 8, 0, 0xFFFFFFFF);
    gSprites[spriteId].oam.priority = 0;
    *dst = spriteId;

    if (owned)
        sDexNavSearchDataPtr_dexnav->ownedIconSpriteId = CreateSprite(&sOwnedIconTemplate_dexnav, SPECIES_ICON_X_dexnav + 6, GetSearchWindowY_dexnav() + 4, 0);
}

static void AddSearchWindow_dexnav(u8 width)
{
    struct WindowTemplate template;
    u16 y = 16;

    if (sDexNavSearchDataPtr_dexnav->tileY > (gSaveBlock1Ptr->pos.y + 7))
        y = 1;  //draw at top if chosen tile is below

    LoadDexNavWindowGfx(sDexNavSearchDataPtr_dexnav->windowId, 0x1d5, 14 * 16);

    SetWindowTemplateFields(&template, 0, 1, y, width, 3, 14, 8);

    sDexNavSearchDataPtr_dexnav->windowId = AddWindow(&template);
    FillWindowPixelBuffer(sDexNavSearchDataPtr_dexnav->windowId, PIXEL_FILL(1));
    PutWindowTilemap(sDexNavSearchDataPtr_dexnav->windowId);
    CopyWindowToVram(sDexNavSearchDataPtr_dexnav->windowId, 3);

    DrawStdFrameWithCustomTileAndPalette(sDexNavSearchDataPtr_dexnav->windowId, TRUE, 0x214, 14);
}

#define WINDOW_COL_0_dexnav        (SPECIES_ICON_X_dexnav + 4)
#define WINDOW_COL_1_dexnav        (WINDOW_COL_0_dexnav + (GetFontAttribute(sDexNavSearchDataPtr_dexnav->windowId, FONTATTR_MAX_LETTER_WIDTH) * (POKEMON_NAME_LENGTH)))
#define WINDOW_MOVE_NAME_X_dexnav  (WINDOW_COL_1_dexnav + (GetFontAttribute(sDexNavSearchDataPtr_dexnav->windowId, FONTATTR_MAX_LETTER_WIDTH) * 6))
#define SEARCH_ARROW_X_dexnav      (WINDOW_MOVE_NAME_X_dexnav + 90)
#define SEARCH_ARROW_Y_dexnav      0

static void AddSearchWindowText_dexnav(u16 species, u8 proximity, u8 searchLevel, bool8 hidden)
{
    u8 windowId = sDexNavSearchDataPtr_dexnav->windowId;

    //species name - always present
    if (hidden)
    {
        StringCopy(gStringVar4, sText_ThreeQmarks_dexnav);
        AddTextPrinterParameterized3(sDexNavSearchDataPtr_dexnav->windowId, 0, WINDOW_COL_0_dexnav, 0, sSearchFontColor_dexnav, TEXT_SKIP_DRAW, gStringVar4);
        return;
    }
    else
    {
        StringCopy(gStringVar1, GetSpeciesName(species));
        AddTextPrinterParameterized3(sDexNavSearchDataPtr_dexnav->windowId, 0, WINDOW_COL_0_dexnav, 0, sSearchFontColor_dexnav, TEXT_SKIP_DRAW, gStringVar1);
    }

    //level - always present
    ConvertIntToDecimalStringN(gStringVar1, sDexNavSearchDataPtr_dexnav->monLevel, STR_CONV_MODE_LEFT_ALIGN, 3);
    StringExpandPlaceholders(gStringVar4, sText_MonLevel_dexnav);
    AddTextPrinterParameterized3(sDexNavSearchDataPtr_dexnav->windowId, 0, WINDOW_COL_1_dexnav, 0, sSearchFontColor_dexnav, TEXT_SKIP_DRAW, gStringVar4);

    if (proximity <= SNEAKING_PROXIMITY)
    {
        PlaySE(SE_POKENAV_ON);
        // move
        if (searchLevel > 1 && sDexNavSearchDataPtr_dexnav->moves[0])
        {
            StringCopy(gStringVar1, GetMoveName(sDexNavSearchDataPtr_dexnav->moves[0]));
            StringExpandPlaceholders(gStringVar4, sText_EggMove_dexnav);
            AddTextPrinterParameterized3(windowId, 0, WINDOW_MOVE_NAME_X_dexnav, 0, sSearchFontColor_dexnav, TEXT_SKIP_DRAW, gStringVar4);
        }

        if (searchLevel > 2)
        {
            // ability name
            StringCopy(gStringVar1, gAbilitiesInfo[GetAbilityBySpecies(species, sDexNavSearchDataPtr_dexnav->abilityNum)].name);
            AddTextPrinterParameterized3(windowId, 0, WINDOW_COL_1_dexnav + 16, 12, sSearchFontColor_dexnav, TEXT_SKIP_DRAW, gStringVar1);

            // item name
            if (sDexNavSearchDataPtr_dexnav->heldItem)
            {
                CopyItemName(sDexNavSearchDataPtr_dexnav->heldItem, gStringVar1);
                StringExpandPlaceholders(gStringVar4, sText_HeldItem_dexnav);
                AddTextPrinterParameterized3(windowId, 0, WINDOW_COL_0_dexnav, 12, sSearchFontColor_dexnav, TEXT_SKIP_DRAW, gStringVar4);
            }
        }
    }

    //chain level - always present
    ConvertIntToDecimalStringN(gStringVar1, gSaveBlock3Ptr->dexNavChain, STR_CONV_MODE_LEFT_ALIGN, 3);
    if (gSaveBlock3Ptr->dexNavChain > 99)
        StringExpandPlaceholders(gStringVar4, sText_DexNavChainLong_dexnav);
    else
        StringExpandPlaceholders(gStringVar4, sText_DexNavChain_dexnav);
    AddTextPrinterParameterized3(windowId, 0, SEARCH_ARROW_X_dexnav - 16, 12, sSearchFontColor_dexnav, TEXT_SKIP_DRAW, gStringVar4);

    CopyWindowToVram(sDexNavSearchDataPtr_dexnav->windowId, 2);
}

#define SEARCH_WINDOW_WIDTH_dexnav     28

static void DrawSearchWindow_dexnav(u16 species, u8 potential, bool8 hidden)
{
    u8 searchLevel = sDexNavSearchDataPtr_dexnav->searchLevel;

    AddSearchWindow_dexnav(SEARCH_WINDOW_WIDTH_dexnav);
    AddSearchWindowText_dexnav(species, sDexNavSearchDataPtr_dexnav->proximity, searchLevel, hidden);
}

#undef SEARCH_WINDOW_WIDTH_dexnav

static void RemoveDexNavWindowAndGfx_dexnav(void)
{
    u32 i;

    // try remove sprites
    if (sDexNavSearchDataPtr_dexnav->iconSpriteId != MAX_SPRITES)
        DestroySprite(&gSprites[sDexNavSearchDataPtr_dexnav->iconSpriteId]);
    if (sDexNavSearchDataPtr_dexnav->itemSpriteId != MAX_SPRITES)
        DestroySprite(&gSprites[sDexNavSearchDataPtr_dexnav->itemSpriteId]);
    if (sDexNavSearchDataPtr_dexnav->eyeSpriteId != MAX_SPRITES)
        DestroySprite(&gSprites[sDexNavSearchDataPtr_dexnav->eyeSpriteId]);
    if (sDexNavSearchDataPtr_dexnav->ownedIconSpriteId != MAX_SPRITES)
        DestroySprite(&gSprites[sDexNavSearchDataPtr_dexnav->ownedIconSpriteId]);
    if (sDexNavSearchDataPtr_dexnav->exclamationSpriteId != MAX_SPRITES)
        DestroySprite(&gSprites[sDexNavSearchDataPtr_dexnav->exclamationSpriteId]);

    for (i = 0; i < NELEMS(sDexNavSearchDataPtr_dexnav->starSpriteIds); i++)
    {
        if (sDexNavSearchDataPtr_dexnav->starSpriteIds[i] != MAX_SPRITES)
            DestroySprite(&gSprites[sDexNavSearchDataPtr_dexnav->starSpriteIds[i]]);
    }

    FreeSpriteTilesByTag(HELD_ITEM_TAG);
    FreeSpriteTilesByTag(OWNED_ICON_TAG);
    FreeSpriteTilesByTag(HIDDEN_SEARCH_TAG);
    FreeSpriteTilesByTag(HIDDEN_MON_ICON_TAG);
    FreeSpriteTilesByTag(LIT_STAR_TILE_TAG);
    FreeSpritePaletteByTag(HELD_ITEM_TAG);
    SafeFreeMonIconPalette(sDexNavSearchDataPtr_dexnav->species);

    // remove window
    ClearStdWindowAndFrameToTransparent(sDexNavSearchDataPtr_dexnav->windowId, FALSE);
    CopyWindowToVram(sDexNavSearchDataPtr_dexnav->windowId, 3);
    RemoveWindow(sDexNavSearchDataPtr_dexnav->windowId);
}


//////////////////////
////DEXNAV SEARCH/////
//////////////////////
static u8 GetPlayerDistance_dexnav(s16 x, s16 y)
{
    u16 deltaX = abs(x - (gSaveBlock1Ptr->pos.x + 7));
    u16 deltaY = abs(y - (gSaveBlock1Ptr->pos.y + 7));
    return deltaX + deltaY;
}

static void DexNavProximityUpdate_dexnav(void)
{
    sDexNavSearchDataPtr_dexnav->proximity = GetPlayerDistance_dexnav(sDexNavSearchDataPtr_dexnav->tileX, sDexNavSearchDataPtr_dexnav->tileY);
}

//Pick a specific tile based on environment
static bool8 DexNavPickTile_dexnav(u8 environment, u8 areaX, u8 areaY, bool8 smallScan)
{
    // area of map to cover starting from camera position {-7, -7}
    s16 topX = gSaveBlock1Ptr->pos.x - SCANSTART_X + (smallScan * 5);
    s16 topY = gSaveBlock1Ptr->pos.y - SCANSTART_Y + (smallScan * 5);
    s16 botX = topX + areaX;
    s16 botY = topY + areaY;
    u8 i;
    bool8 nextIter;
    u8 scale = 0;
    u8 weight = 0;
    u8 currMapType = GetCurrentMapType();
    u8 tileBehaviour;
    u8 tileBuffer = 2;
    u8 *xPos = AllocZeroed((botX - topX) * (botY - topY) * sizeof(u8));
    u8 *yPos = AllocZeroed((botX - topX) * (botY - topY) * sizeof(u8));
    u32 iter = 0;
    bool32 ret = FALSE;

    // loop through every tile in area and evaluate
    while (topY < botY)
    {
        while (topX < botX)
        {
            tileBehaviour = MapGridGetMetatileBehaviorAt(topX, topY);
            //Check for objects
            nextIter = FALSE;
            if (TestPlayerAvatarFlags(PLAYER_AVATAR_FLAG_BIKE))
                tileBuffer = SNEAKING_PROXIMITY + 3;
            else if (TestPlayerAvatarFlags(PLAYER_AVATAR_FLAG_DASH))
                tileBuffer = SNEAKING_PROXIMITY + 1;

            if (GetPlayerDistance_dexnav(topX, topY) <= tileBuffer)
            {
                // tile too close to player
                topX++;
                continue;
            }

            for (i = 0; i < OBJECT_EVENTS_COUNT; i++)
            {
                if (gObjectEvents[i].currentCoords.x == topX && gObjectEvents[i].currentCoords.y == topY)
                {
                    // cannot be on a tile where an object exists
                    nextIter = TRUE;
                    break;
                }
            }

            if (nextIter)
            {
                topX++;
                continue;
            }

            weight = 0; // initiliaze weight
            switch (environment)
            {
            case ENCOUNTER_TYPE_LAND:
                if (MetatileBehavior_IsLandWildEncounter(tileBehaviour))
                {
                    if (currMapType == MAP_TYPE_UNDERGROUND)
                    {
                        // inside (cave)
                        if (IsElevationMismatchAt(gObjectEvents[gPlayerAvatar.spriteId].currentElevation, topX, topY))
                            break; //occurs at same z coord

                        scale = 440 - (smallScan * 200) - (GetPlayerDistance_dexnav(topX, topY) / 2)  - (2 * (topX + topY));
                        weight = ((Random() % scale) < 1) && !MapGridGetCollisionAt(topX, topY);
                    }
                    else
                    {
                        // outdoors: grass
                        scale = 100 - (GetPlayerDistance_dexnav(topX, topY) * 2);
                        weight = (Random() % scale <= 5) && !MapGridGetCollisionAt(topX, topY);
                    }
                }
                break;
            case ENCOUNTER_TYPE_WATER:
                if (MetatileBehavior_IsSurfableWaterOrUnderwater(tileBehaviour))
                {
                    u8 scale = 320 - (smallScan * 200) - (GetPlayerDistance_dexnav(topX, topY) / 2);
                    if (IsElevationMismatchAt(gObjectEvents[gPlayerAvatar.spriteId].currentElevation, topX, topY))
                        break;

                    weight = (Random() % scale <= 1) && !MapGridGetCollisionAt(topX, topY);
                }
                break;
            default:
                break;
            }

            if (weight > 0)
            {
                xPos[iter] = topX;
                yPos[iter] = topY;
                iter++;
            }

            topX++;
        }

        topY++;
        topX = gSaveBlock1Ptr->pos.x - SCANSTART_X + (smallScan * 5);
    }

    if (iter > 0)
    {
        i = Random() % iter;
        sDexNavSearchDataPtr_dexnav->tileX = xPos[i];
        sDexNavSearchDataPtr_dexnav->tileY = yPos[i];
        ret = TRUE;
    }

    Free(xPos);
    Free(yPos);

    return ret;
}


static bool8 TryStartHiddenMonFieldEffect_dexnav(u8 environment, u8 xSize, u8 ySize, bool8 smallScan)
{
    u8 currMapType = GetCurrentMapType();
    u8 fldEffId = 0;

    if (DexNavPickTile_dexnav(environment, xSize, ySize, smallScan))
    {
        u8 metatileBehaviour = MapGridGetMetatileBehaviorAt(sDexNavSearchDataPtr_dexnav->tileX, sDexNavSearchDataPtr_dexnav->tileY);

        switch (environment)
        {
        case ENCOUNTER_TYPE_LAND:
            if (currMapType == MAP_TYPE_UNDERGROUND)
            {
                fldEffId = FLDEFF_CAVE_DUST;
            }
            else if (IsMapTypeIndoors(currMapType))
            {
                if (MetatileBehavior_IsTallGrass(metatileBehaviour)) //Grass in cave
                    fldEffId = FLDEFF_SHAKING_GRASS;
                else if (MetatileBehavior_IsLongGrass(metatileBehaviour)) //Really tall grass
                    fldEffId = FLDEFF_SHAKING_LONG_GRASS;
                else if (MetatileBehavior_IsSandOrDeepSand(metatileBehaviour))
                    fldEffId = FLDEFF_SAND_HOLE;
                else
                    fldEffId = FLDEFF_CAVE_DUST;
            }
            else //outdoor, underwater
            {
                if (MetatileBehavior_IsTallGrass(metatileBehaviour)) //Regular grass
                    fldEffId = FLDEFF_SHAKING_GRASS;
                else if (MetatileBehavior_IsLongGrass(metatileBehaviour)) //Really tall grass
                    fldEffId = FLDEFF_SHAKING_LONG_GRASS;
                else if (MetatileBehavior_IsSandOrDeepSand(metatileBehaviour)) //Desert Sand
                    fldEffId = FLDEFF_SAND_HOLE;
                else if (MetatileBehavior_IsMountain(metatileBehaviour)) //Rough Terrain
                    fldEffId = FLDEFF_CAVE_DUST;
                else
                    fldEffId = FLDEFF_BERRY_TREE_GROWTH_SPARKLE; //default
            }
            break;
        case ENCOUNTER_TYPE_WATER:
            fldEffId = FLDEFF_WATER_SURFACING;
            break;
        default:
            return FALSE;
        }

        if (fldEffId != 0)
        {
            gFieldEffectArguments[0] = sDexNavSearchDataPtr_dexnav->tileX;
            gFieldEffectArguments[1] = sDexNavSearchDataPtr_dexnav->tileY;
            gFieldEffectArguments[2] = 0xFF; // subpriority
            gFieldEffectArguments[3] = 2;   //priority
            sDexNavSearchDataPtr_dexnav->fldEffSpriteId = FieldEffectStart(fldEffId);
            if (sDexNavSearchDataPtr_dexnav->fldEffSpriteId == MAX_SPRITES)
                return FALSE;

            sDexNavSearchDataPtr_dexnav->fldEffId = fldEffId;
            return TRUE;
        }
    }

    return FALSE;
}

