static void Task_SetUpDexNavSearch_dexnav(u8 taskId)
{
    struct Task *task = &gTasks[taskId];

    u16 species = sDexNavSearchDataPtr_dexnav->species;
    u8 searchLevel = GetSearchLevel_dexnav(SpeciesToNationalPokedexNum(species));

    // init sprites
    sDexNavSearchDataPtr_dexnav->iconSpriteId = MAX_SPRITES;
    sDexNavSearchDataPtr_dexnav->itemSpriteId = MAX_SPRITES;
    sDexNavSearchDataPtr_dexnav->eyeSpriteId = MAX_SPRITES;
    sDexNavSearchDataPtr_dexnav->starSpriteIds[0] = MAX_SPRITES;
    sDexNavSearchDataPtr_dexnav->starSpriteIds[1] = MAX_SPRITES;
    sDexNavSearchDataPtr_dexnav->starSpriteIds[2] = MAX_SPRITES;
    sDexNavSearchDataPtr_dexnav->ownedIconSpriteId = MAX_SPRITES;
    sDexNavSearchDataPtr_dexnav->exclamationSpriteId = MAX_SPRITES;
    sDexNavSearchDataPtr_dexnav->searchLevel = searchLevel;

    DexNavGenerateMoveset_dexnav(species, searchLevel, sDexNavSearchDataPtr_dexnav->monLevel, &sDexNavSearchDataPtr_dexnav->moves[0]);
    sDexNavSearchDataPtr_dexnav->heldItem = DexNavGenerateHeldItem_dexnav(species, searchLevel);
    sDexNavSearchDataPtr_dexnav->abilityNum = DexNavGetAbilityNum_dexnav(species, searchLevel);
    sDexNavSearchDataPtr_dexnav->potential = DexNavGeneratePotential_dexnav(searchLevel);
    DexNavProximityUpdate_dexnav();

    LoadSearchIconData_dexnav();
    if (sDexNavSearchDataPtr_dexnav->hiddenSearch)
    {
        DexNavDrawHiddenIcons_dexnav();
    }
    else
    {
        DexNavDrawIcons_dexnav();
        DexNavUpdateSearchWindow_dexnav(sDexNavSearchDataPtr_dexnav->proximity, searchLevel);
    }

    FlagSet(FLAG_SYS_DEXNAV_SEARCH);
    gPlayerAvatar.creeping = TRUE;  //initialize as true in case mon appears beside you
    task->tProximity_dexnav = gSprites[gPlayerAvatar.spriteId].x;
    task->tFrameCount_dexnav = 0;
    task->func = Task_DexNavSearch_dexnav;
    IncrementGameStat(GAME_STAT_DEXNAV_SCANNED);
}

static void DexNavSearchBail_dexnav(u8 taskId, const u8 *script)
{
    TRY_FREE_AND_SET_NULL(sDexNavSearchDataPtr_dexnav);
    FreeMonIconPalettes();
    ScriptContext_SetupScript(script);
    DestroyTask(taskId);
}

static void Task_InitDexNavSearch_dexnav(u8 taskId)
{
    struct Task *task = &gTasks[taskId];
    u16 species = task->tSpecies_dexnav;
    u8 environment = task->tEnvironment_dexnav;

    sDexNavSearchDataPtr_dexnav = AllocZeroed(sizeof(struct DexNavSearch));
    if (sDexNavSearchDataPtr_dexnav == NULL)
    {
        DexNavSearchBail_dexnav(taskId, EventScript_NotFoundNearby);
        return;
    }

    // assign non-objects to struct
    sDexNavSearchDataPtr_dexnav->species = species;
    sDexNavSearchDataPtr_dexnav->environment = environment;  //updated in DexNavTryGenerateMonLevel_dexnav if hidden mon
    sDexNavSearchDataPtr_dexnav->isHiddenMon = (environment == ENCOUNTER_TYPE_HIDDEN) ? TRUE : FALSE;
    sDexNavSearchDataPtr_dexnav->monLevel = DexNavTryGenerateMonLevel_dexnav(species, environment);

    if (GetFlashLevel() > 0)
    {
        DexNavSearchBail_dexnav(taskId, EventScript_TooDark);
        return;
    }

    if (sDexNavSearchDataPtr_dexnav->monLevel == MON_LEVEL_NONEXISTENT || !TryStartHiddenMonFieldEffect_dexnav(sDexNavSearchDataPtr_dexnav->environment, 12, 12, FALSE))
    {
        DexNavSearchBail_dexnav(taskId, EventScript_NotFoundNearby);
        return;
    }

    sDexNavSearchDataPtr_dexnav->hiddenSearch = FALSE;
    task->tRevealed_dexnav = TRUE; //search window revealed
    task->func = Task_SetUpDexNavSearch_dexnav;
}

static void DexNavDrawPotentialStars_dexnav(u8 potential, u8* dst)
{
    u8 spriteId;
    u32 i;

    for (i = 0; i < NELEMS(sDexNavSearchDataPtr_dexnav->starSpriteIds); i++)
    {
        spriteId = MAX_SPRITES;
        if (potential > i)
            spriteId = CreateSprite(&sPotentialStarTemplate_dexnav, SPECIES_ICON_X_dexnav - 20, GetSearchWindowY_dexnav() + 4 + (i * 8), 0);

        dst[i] = spriteId;
        if (spriteId != MAX_SPRITES)
            gSprites[spriteId].invisible = TRUE;
    }
}

static void DexNavUpdateDirectionArrow_dexnav(void)
{
    u16 tileX = sDexNavSearchDataPtr_dexnav->tileX;
    u16 tileY = sDexNavSearchDataPtr_dexnav->tileY;
    u16 playerX = gSaveBlock1Ptr->pos.x + 7;
    u16 playerY = gSaveBlock1Ptr->pos.y + 7;
    u16 deltaX = abs(tileX - playerX);
    u16 deltaY = abs(tileY - playerY);
    const u8 *str;
    u8 windowId = sDexNavSearchDataPtr_dexnav->windowId;

    FillWindowPixelRect(windowId, PIXEL_FILL(1), SEARCH_ARROW_X_dexnav, SEARCH_ARROW_Y_dexnav, 12, 12);
    if (deltaX <= 1 && deltaY <= 1)
    {
        str = gText_EmptyString2;
    }
    else if (deltaX > deltaY)
    {
        if (playerX > tileX)
            str = sText_ArrowLeft_dexnav;  //player to right
        else
            str = sText_ArrowRight_dexnav; //player to left
    }
    else //greater Y diff
    {
        if (playerY > tileY)
            str = sText_ArrowUp_dexnav;    //player below
        else
            str = sText_ArrowDown_dexnav;  //player above
    }

    AddTextPrinterParameterized3(windowId, 1, SEARCH_ARROW_X_dexnav, SEARCH_ARROW_Y_dexnav, sSearchFontColor_dexnav, TEXT_SKIP_DRAW, str);
    CopyWindowToVram(windowId, 2);
}

static void DexNavDrawIcons_dexnav(void)
{
    u16 species = sDexNavSearchDataPtr_dexnav->species;

    DrawSearchWindow_dexnav(species, sDexNavSearchDataPtr_dexnav->potential, FALSE);
    DrawDexNavSearchMonIcon_dexnav(species, &sDexNavSearchDataPtr_dexnav->iconSpriteId, GetSetPokedexFlag(SpeciesToNationalPokedexNum(species), FLAG_GET_CAUGHT));
    DrawDexNavSearchHeldItem_dexnav(&sDexNavSearchDataPtr_dexnav->itemSpriteId);
    DexNavDrawPotentialStars_dexnav(sDexNavSearchDataPtr_dexnav->potential, &sDexNavSearchDataPtr_dexnav->starSpriteIds[0]);
    DexNavUpdateDirectionArrow_dexnav();
}

/////////////////////
//// SEARCH TASK ////
/////////////////////
bool8 TryStartDexNavSearch(void)
{
    u8 taskId;
    u16 val = VarGet(VAR_DEXNAV_SPECIES);

    if (FlagGet(FLAG_SYS_DEXNAV_SEARCH) || (val & DEXNAV_MASK_SPECIES) == SPECIES_NONE)
        return FALSE;

    HideMapNamePopUpWindow();
    ChangeBgY_ScreenOff(0, 0, 0);
    taskId = CreateTask(Task_InitDexNavSearch_dexnav, 0);
    gTasks[taskId].tSpecies_dexnav = val & DEXNAV_MASK_SPECIES;
    gTasks[taskId].tEnvironment_dexnav = val >> 14;
    PlaySE(SE_DEX_SEARCH);
    return FALSE;   //we dont actually want to enable the script context
}

void EndDexNavSearch(u8 taskId)
{
    FlagClear(FLAG_SYS_DEXNAV_SEARCH);
    DestroyTask(taskId);
    RemoveDexNavWindowAndGfx_dexnav();
    FieldEffectStop(&gSprites[sDexNavSearchDataPtr_dexnav->fldEffSpriteId], sDexNavSearchDataPtr_dexnav->fldEffId);
    Free(sDexNavSearchDataPtr_dexnav);
}

static void EndDexNavSearchSetupScript_dexnav(const u8 *script, u8 taskId)
{
    gSaveBlock3Ptr->dexNavChain = 0;   //reset chain
    EndDexNavSearch(taskId);
    ScriptContext_SetupScript(script);
}

static u8 GetMovementProximityBySearchLevel_dexnav(void)
{
    if (sDexNavSearchDataPtr_dexnav->searchLevel < 20)
        return 2;
    else if (sDexNavSearchDataPtr_dexnav->searchLevel < 50)
        return 3;
    else
        return 4;
}

static void Task_RevealHiddenMon_dexnav(u8 taskId)
{
    struct Task *task = &gTasks[taskId];
    u16 species = sDexNavSearchDataPtr_dexnav->species;

    // remove owned icon if it exists
    if (sDexNavSearchDataPtr_dexnav->ownedIconSpriteId != MAX_SPRITES)
    {
        DestroySprite(&gSprites[sDexNavSearchDataPtr_dexnav->ownedIconSpriteId]);
        sDexNavSearchDataPtr_dexnav->ownedIconSpriteId = MAX_SPRITES;
    }

    // remove exclamation if it exists
    if (sDexNavSearchDataPtr_dexnav->exclamationSpriteId != MAX_SPRITES)
    {
        DestroySprite(&gSprites[sDexNavSearchDataPtr_dexnav->exclamationSpriteId]);
        sDexNavSearchDataPtr_dexnav->exclamationSpriteId = MAX_SPRITES;
    }


    if (!GetSetPokedexFlag(SpeciesToNationalPokedexNum(species), FLAG_GET_SEEN))
    {
        u8 index;

        //if not seen, hide name and whiteout mon
        DrawSearchWindow_dexnav(species, sDexNavSearchDataPtr_dexnav->potential, TRUE);
        DrawDexNavSearchMonIcon_dexnav(species, &sDexNavSearchDataPtr_dexnav->iconSpriteId, FALSE);
        // whiteout icon
        index = IndexOfSpritePaletteTag(gSprites[sDexNavSearchDataPtr_dexnav->iconSpriteId].template->paletteTag);
        CpuCopy16(&gPlttBufferUnfaded[0x100 + index * 16], sDexNavSearchDataPtr_dexnav->palBuffer, 32);
        TintPalette_CustomTone(sDexNavSearchDataPtr_dexnav->palBuffer, 16, 510, 510, 510);
        LoadPalette(sDexNavSearchDataPtr_dexnav->palBuffer, 0x100 + index * 16, 32);
    }
    else
    {
        DrawSearchWindow_dexnav(species, sDexNavSearchDataPtr_dexnav->potential, FALSE);
        DrawDexNavSearchMonIcon_dexnav(species, &sDexNavSearchDataPtr_dexnav->iconSpriteId, GetSetPokedexFlag(SpeciesToNationalPokedexNum(species), FLAG_GET_CAUGHT));
    }

    DexNavUpdateDirectionArrow_dexnav();
    task->func = Task_DexNavSearch_dexnav;
    task->tFrameCount_dexnav = 0;  //restart search clock
}

static void Task_DexNavSearch_dexnav(u8 taskId)
{
    struct Task *task = &gTasks[taskId];

    if (sDexNavSearchDataPtr_dexnav->proximity > MAX_PROXIMITY)
    { // out of range
        if (sDexNavSearchDataPtr_dexnav->hiddenSearch && !task->tRevealed_dexnav)
            EndDexNavSearch(taskId);
        else
            EndDexNavSearchSetupScript_dexnav(EventScript_LostSignal, taskId);
        return;
    }

    if (sDexNavSearchDataPtr_dexnav->proximity <= CREEPING_PROXIMITY && !gPlayerAvatar.creeping && task->tFrameCount_dexnav > 60)
    { //should be creeping but player walks normally
        if (sDexNavSearchDataPtr_dexnav->hiddenSearch && !task->tRevealed_dexnav)
            EndDexNavSearch(taskId);
        else
            EndDexNavSearchSetupScript_dexnav(EventScript_MovedTooFast, taskId);
        return;
    }

    if (sDexNavSearchDataPtr_dexnav->proximity <= SNEAKING_PROXIMITY && TestPlayerAvatarFlags(PLAYER_AVATAR_FLAG_DASH | PLAYER_AVATAR_FLAG_BIKE))
    { // running/biking too close
        //always do event script, even if player hasn't revealed a hidden mon. It's assumed they would be creeping towards it
        EndDexNavSearchSetupScript_dexnav(EventScript_MovedTooFast, taskId);
        return;
    }

    if (ArePlayerFieldControlsLocked() == TRUE)
    { // check if script just executed
        EndDexNavSearch(taskId);
        return;
    }

    if (gTasks[taskId].tFrameCount_dexnav > DEXNAV_TIMEOUT * 60)
    { // player took too long
        if (sDexNavSearchDataPtr_dexnav->hiddenSearch && !task->tRevealed_dexnav)
            EndDexNavSearch(taskId);
        else
            EndDexNavSearchSetupScript_dexnav(EventScript_PokemonGotAway, taskId);
        return;
    }

    if (sDexNavSearchDataPtr_dexnav->proximity < 1)
    {
        gDexNavBattle = TRUE;
        CreateDexNavWildMon_dexnav(sDexNavSearchDataPtr_dexnav->species, sDexNavSearchDataPtr_dexnav->potential, sDexNavSearchDataPtr_dexnav->monLevel,
                            sDexNavSearchDataPtr_dexnav->abilityNum, sDexNavSearchDataPtr_dexnav->heldItem, sDexNavSearchDataPtr_dexnav->moves);

        FlagClear(FLAG_SYS_DEXNAV_SEARCH);
        ScriptContext_SetupScript(EventScript_StartDexNavBattle);
        Free(sDexNavSearchDataPtr_dexnav);
        DestroyTask(taskId);
        return;
    }

    if (sDexNavSearchDataPtr_dexnav->hiddenSearch && !task->tRevealed_dexnav &&
        (JOY_NEW(R_BUTTON) || (sDexNavSearchDataPtr_dexnav->proximity < CREEPING_PROXIMITY)))
    {
        PlaySE(SE_DEX_SEARCH);
        ClearStdWindowAndFrameToTransparent(sDexNavSearchDataPtr_dexnav->windowId, FALSE);
        CopyWindowToVram(sDexNavSearchDataPtr_dexnav->windowId, 3);
        RemoveWindow(sDexNavSearchDataPtr_dexnav->windowId);
        DestroySprite(&gSprites[sDexNavSearchDataPtr_dexnav->iconSpriteId]);
        task->tRevealed_dexnav = TRUE; //regular dexnav search
        //sDexNavSearchDataPtr_dexnav->hiddenSearch = FALSE; //now its a regular dexnav search
        task->func = Task_RevealHiddenMon_dexnav;
        return;
    }

    //Caves and water the pokemon moves around
    if ((sDexNavSearchDataPtr_dexnav->environment == ENCOUNTER_TYPE_WATER || GetCurrentMapType() == MAP_TYPE_UNDERGROUND)
        && sDexNavSearchDataPtr_dexnav->proximity < GetMovementProximityBySearchLevel_dexnav() && sDexNavSearchDataPtr_dexnav->movementCount < 2
        && task->tRevealed_dexnav)
    {
        FieldEffectStop(&gSprites[sDexNavSearchDataPtr_dexnav->fldEffSpriteId], sDexNavSearchDataPtr_dexnav->fldEffId);

        if (!TryStartHiddenMonFieldEffect_dexnav(sDexNavSearchDataPtr_dexnav->environment, 10, 10, TRUE))
        {
            EndDexNavSearchSetupScript_dexnav(EventScript_PokemonGotAway, taskId);
            return;
        }

        sDexNavSearchDataPtr_dexnav->movementCount++;
    }

    DexNavProximityUpdate_dexnav();
    if (task->tProximity_dexnav != sDexNavSearchDataPtr_dexnav->proximity)
    {
        //player has moved
        if (task->tRevealed_dexnav)    //update search window info only if hidden mon has been revealed (always true for search mode)
            DexNavUpdateSearchWindow_dexnav(sDexNavSearchDataPtr_dexnav->proximity, sDexNavSearchDataPtr_dexnav->searchLevel);

        task->tProximity_dexnav = sDexNavSearchDataPtr_dexnav->proximity;
    }

    task->tFrameCount_dexnav++;
}

static void DexNavUpdateSearchWindow_dexnav(u8 proximity, u8 searchLevel)
{
    bool8 hideName = FALSE;

    if (sDexNavSearchDataPtr_dexnav->hiddenSearch && !GetSetPokedexFlag(SpeciesToNationalPokedexNum(sDexNavSearchDataPtr_dexnav->species), FLAG_GET_SEEN))
        hideName = TRUE;    //if a detector mode hidden search and player hasn't seen the mon, hide info

    FillWindowPixelBuffer(sDexNavSearchDataPtr_dexnav->windowId, PIXEL_FILL(1));   //clear window
    AddSearchWindowText_dexnav(sDexNavSearchDataPtr_dexnav->species, proximity, searchLevel, hideName);

    DexNavUpdateDirectionArrow_dexnav();

    //init hidden sprites
    if (sDexNavSearchDataPtr_dexnav->itemSpriteId != MAX_SPRITES)
        gSprites[sDexNavSearchDataPtr_dexnav->itemSpriteId].invisible = TRUE;
    if (sDexNavSearchDataPtr_dexnav->starSpriteIds[0] != MAX_SPRITES)
        gSprites[sDexNavSearchDataPtr_dexnav->starSpriteIds[0]].invisible = TRUE;
    if (sDexNavSearchDataPtr_dexnav->starSpriteIds[1] != MAX_SPRITES)
        gSprites[sDexNavSearchDataPtr_dexnav->starSpriteIds[1]].invisible = TRUE;
    if (sDexNavSearchDataPtr_dexnav->starSpriteIds[2] != MAX_SPRITES)
        gSprites[sDexNavSearchDataPtr_dexnav->starSpriteIds[2]].invisible = TRUE;

    if (proximity <= SNEAKING_PROXIMITY)
    {
        if (searchLevel > 2 && sDexNavSearchDataPtr_dexnav->heldItem)
        {
            // toggle item view
            if (sDexNavSearchDataPtr_dexnav->itemSpriteId != MAX_SPRITES)
                gSprites[sDexNavSearchDataPtr_dexnav->itemSpriteId].invisible = FALSE;
        }

        if (searchLevel > 4)
        {
            if (sDexNavSearchDataPtr_dexnav->starSpriteIds[0] != MAX_SPRITES)
                gSprites[sDexNavSearchDataPtr_dexnav->starSpriteIds[0]].invisible = FALSE;

            if (sDexNavSearchDataPtr_dexnav->starSpriteIds[1] != MAX_SPRITES)
                gSprites[sDexNavSearchDataPtr_dexnav->starSpriteIds[1]].invisible = FALSE;

            if (sDexNavSearchDataPtr_dexnav->starSpriteIds[2] != MAX_SPRITES)
                gSprites[sDexNavSearchDataPtr_dexnav->starSpriteIds[2]].invisible = FALSE;
        }
    }
}

//////////////////////////////
//// DEXNAV MON GENERATOR ////
//////////////////////////////
static void CreateDexNavWildMon_dexnav(u16 species, u8 potential, u8 level, u8 abilityNum, u16 item, u16* moves)
{
    struct Pokemon* mon = &gEnemyParty[0];
    u8 iv[3] = {NUM_STATS};
    u8 i;
    u8 perfectIv = 31;

    CreateWildMon(species, level);  // shiny rate bonus handled in CreateBoxMon

    // Pick random, unique IVs to set to 31. The number of perfect IVs that are assigned is equal to the potential
    iv[0] = Random() % NUM_STATS;               // choose 1st perfect stat
    do {
        iv[1] = Random() % NUM_STATS;
        iv[2] = Random() % NUM_STATS;
    } while ((iv[1] == iv[0])                   // unique 2nd perfect stat
      || (iv[2] == iv[0] || iv[2] == iv[1]));   // unique 3rd perfect stat

    if (potential > 2 && iv[2] != NUM_STATS)
        SetMonData(mon, MON_DATA_HP_IV + iv[2], &perfectIv);
    if (potential > 1 && iv[1] != NUM_STATS)
        SetMonData(mon, MON_DATA_HP_IV + iv[1], &perfectIv);
    if (potential > 0 && iv[0] != NUM_STATS)
        SetMonData(mon, MON_DATA_HP_IV + iv[0], &perfectIv);

    //Set ability
    SetMonData(mon, MON_DATA_ABILITY_NUM, &abilityNum);

    // Set Held Item
    if (item)
        SetMonData(mon, MON_DATA_HELD_ITEM, &item);

    //Set moves
    for (i = 0; i < MAX_MON_MOVES; i++)
        SetMonMoveSlot(mon, moves[i], i);

    CalculateMonStats(mon);
}

// gets a random level of the species based on map data.
//if it was a hidden encounter, updates the environment it is to be found from the wildheader encounterRate
static u8 DexNavTryGenerateMonLevel_dexnav(u16 species, u8 environment)
{
    u8 levelBase = GetEncounterLevelFromMapData_dexnav(species, environment);
    u8 levelBonus = gSaveBlock3Ptr->dexNavChain / 5;

    if (levelBase == MON_LEVEL_NONEXISTENT)
        return MON_LEVEL_NONEXISTENT;   //species not found in the area

    if (Random() % 100 < 4)
        levelBonus += 10; //4% chance of having a +10 level

    if (levelBase + levelBonus > MAX_LEVEL)
        return MAX_LEVEL;
    else
        return levelBase + levelBonus;
}

static void DexNavGenerateMoveset_dexnav(u16 species, u8 searchLevel, u8 encounterLevel, u16* moveDst)
{
    bool8 genMove = FALSE;
    u16 randVal = Random() % 100;
    u16 i;
    u16 eggMoveBuffer[EGG_MOVES_ARRAY_COUNT];

    // see if first move slot should be an egg move
    if (searchLevel < 5)
    {
        if (SEARCHLEVEL0_MOVECHANCE != 0 && randVal < SEARCHLEVEL0_MOVECHANCE)
            genMove = TRUE;
    }
    else if (searchLevel < 10)
    {
        if (SEARCHLEVEL5_MOVECHANCE != 0 && randVal < SEARCHLEVEL5_MOVECHANCE)
            genMove = TRUE;
    }
    else if (searchLevel < 25)
    {
        if (SEARCHLEVEL10_MOVECHANCE != 0 && randVal < SEARCHLEVEL10_MOVECHANCE)
            genMove = TRUE;
    }
    else if (searchLevel < 50)
    {
        if (SEARCHLEVEL25_MOVECHANCE != 0 && randVal < SEARCHLEVEL25_MOVECHANCE)
            genMove = TRUE;
    }
    else if (searchLevel < 100)
    {
        if (SEARCHLEVEL50_MOVECHANCE != 0 && randVal < SEARCHLEVEL50_MOVECHANCE)
            genMove = TRUE;
    }
    else
    {
        if (SEARCHLEVEL100_MOVECHANCE != 0 && randVal < SEARCHLEVEL100_MOVECHANCE)
            genMove = TRUE;
    }

    // Generate a wild mon just to get the initial moveset (later overwritten by CreateDexNavWildMon_dexnav)
    CreateWildMon(species, encounterLevel);

    // Store generated mon moves into Dex Nav Struct
    for (i = 0; i < MAX_MON_MOVES; i++)
        moveDst[i] = GetMonData(&gEnemyParty[0], MON_DATA_MOVE1 + i, NULL);

    // set first move slot to a random egg move if search level is good enough
    if (genMove)
    {
        u8 numEggMoves = GetEggMoves(&gEnemyParty[0], eggMoveBuffer);
        if (numEggMoves != 0)
            moveDst[0] = eggMoveBuffer[Random() % numEggMoves];
    }
}

static u16 DexNavGenerateHeldItem_dexnav(u16 species, u8 searchLevel)
{
    u16 randVal = Random() % 100;
    u8 searchLevelInfluence = searchLevel >> 1;
    u16 item1 = gSpeciesInfo[species].itemCommon;
    u16 item2 = gSpeciesInfo[species].itemRare;

    // if both are the same, 100% to hold
    if (item1 == item2)
        return item1;

    // if no items can be held, then yeah...no items
    if (item2 == ITEM_NONE && item1 == ITEM_NONE)
        return ITEM_NONE;

    // if only one entry, 50% chance
    if (item2 == ITEM_NONE && item1 != ITEM_NONE)
        return (randVal < 50) ? item1 : ITEM_NONE;

    // if both are distinct item1 = 50% + srclvl/2; item2 = 5% + srchlvl/2
    if (randVal < (50 + searchLevelInfluence + 5 + searchLevel))
        return (randVal > 5 + searchLevelInfluence) ? item1 : item2;
    else
        return ITEM_NONE;

    return ITEM_NONE;
}

static u8 DexNavGetAbilityNum_dexnav(u16 species, u8 searchLevel)
{
    bool8 genAbility = FALSE;
    u16 randVal = Random() % 100;
    u8 abilityNum = 0;

    if (searchLevel < 5)
    {
        #if (SEARCHLEVEL0_ABILITYCHANCE != 0)
        if (randVal < SEARCHLEVEL0_ABILITYCHANCE)
            genAbility = TRUE;
        #endif
    }
    else if (searchLevel < 10)
    {
        #if (SEARCHLEVEL5_ABILITYCHANCE != 0)
        if (randVal < SEARCHLEVEL5_ABILITYCHANCE)
            genAbility = TRUE;
        #endif
    }
    else if (searchLevel < 25)
    {
        #if (SEARCHLEVEL10_ABILITYCHANCE != 0)
        if (randVal < SEARCHLEVEL10_ABILITYCHANCE)
            genAbility = TRUE;
        #endif
    }
    else if (searchLevel < 50)
    {
        #if (SEARCHLEVEL25_ABILITYCHANCE != 0)
        if (randVal < SEARCHLEVEL25_ABILITYCHANCE)
            genAbility = TRUE;
        #endif
    }
    else if (searchLevel < 100)
    {
        #if (SEARCHLEVEL50_ABILITYCHANCE != 0)
        if (randVal < SEARCHLEVEL50_ABILITYCHANCE)
            genAbility = TRUE;
        #endif
    }
    else
    {
        #if (SEARCHLEVEL100_ABILITYCHANCE != 0)
        if (randVal < SEARCHLEVEL100_ABILITYCHANCE)
            genAbility = TRUE;
        #endif
    }

    if (genAbility
            && gSpeciesInfo[species].abilities[2] != ABILITY_NONE
            && GetSetPokedexFlag(SpeciesToNationalPokedexNum(species), FLAG_GET_CAUGHT))
    {
        //Only give hidden ability if Pokemon has been caught before
        abilityNum = 2;
    }
    else
    {
        //Pick a normal ability of that Pokemon
        if (gSpeciesInfo[species].abilities[1] != ABILITY_NONE)
            abilityNum = Random() & 1;
        else
            abilityNum = 0;
    }

    return abilityNum;
}

static u8 DexNavGeneratePotential_dexnav(u8 searchLevel)
{
    u8 genChance = 0;
    int randVal = Random() % 100;

    if (searchLevel < 5)
    {
        genChance = SEARCHLEVEL0_ONESTAR + SEARCHLEVEL0_TWOSTAR + SEARCHLEVEL0_THREESTAR;
        if (randVal < genChance)
        {
            // figure out which star it is
            if (randVal < SEARCHLEVEL0_ONESTAR)
                return 1;
            else if (randVal < (SEARCHLEVEL0_ONESTAR + SEARCHLEVEL0_TWOSTAR))
                return 2;
            else
                return 3;
        }
    }
    else if (searchLevel < 10)
    {
        genChance = SEARCHLEVEL5_ONESTAR + SEARCHLEVEL5_TWOSTAR + SEARCHLEVEL5_THREESTAR;
        if (randVal < genChance)
        {
            // figure out which star it is
            if (randVal < SEARCHLEVEL5_ONESTAR)
                return 1;
            else if (randVal < (SEARCHLEVEL5_ONESTAR + SEARCHLEVEL5_TWOSTAR))
                return 2;
            else
                return 3;
        }
    }
    else if (searchLevel < 25)
    {
        genChance = SEARCHLEVEL10_ONESTAR + SEARCHLEVEL10_TWOSTAR + SEARCHLEVEL10_THREESTAR;
        if (randVal < genChance)
        {
            // figure out which star it is
            if (randVal < SEARCHLEVEL10_ONESTAR)
                return 1;
            else if (randVal < (SEARCHLEVEL10_ONESTAR + SEARCHLEVEL10_TWOSTAR))
                return 2;
            else
                return 3;
        }
    }
    else if (searchLevel < 50)
    {
        genChance = SEARCHLEVEL25_ONESTAR + SEARCHLEVEL25_TWOSTAR + SEARCHLEVEL25_THREESTAR;
        if (randVal < genChance)
        {
            // figure out which star it is
            if (randVal < SEARCHLEVEL25_ONESTAR)
                return 1;
            else if (randVal < (SEARCHLEVEL25_ONESTAR + SEARCHLEVEL25_TWOSTAR))
                return 2;
            else
                return 3;
        }
    }
    else if (searchLevel < 100)
    {
        genChance = SEARCHLEVEL50_ONESTAR + SEARCHLEVEL50_TWOSTAR + SEARCHLEVEL50_THREESTAR;
        if (randVal < genChance)
        {
            // figure out which star it is
            if (randVal < SEARCHLEVEL50_ONESTAR)
                return 1;
            else if (randVal < (SEARCHLEVEL50_ONESTAR + SEARCHLEVEL50_TWOSTAR))
                return 2;
            else
                return 3;
        }
    }
    else
    {
        genChance = SEARCHLEVEL100_ONESTAR + SEARCHLEVEL100_TWOSTAR + SEARCHLEVEL100_THREESTAR;
        if (randVal < genChance)
        {
            // figure out which star it is
            if (randVal < SEARCHLEVEL100_ONESTAR)
                return 1;
            else if (randVal < (SEARCHLEVEL100_ONESTAR + SEARCHLEVEL100_TWOSTAR))
                return 2;
            else
                return 3;
        }
    }

    return 0;   // No potential
}

static u8 GetEncounterLevelFromMapData_dexnav(u16 species, u8 environment)
{
    u16 headerId = GetCurrentMapWildMonHeaderId();
    const struct WildPokemonInfo *landMonsInfo = gWildMonHeaders[headerId].landMonsInfo;
    const struct WildPokemonInfo *waterMonsInfo = gWildMonHeaders[headerId].waterMonsInfo;
    const struct WildPokemonInfo *hiddenMonsInfo = gWildMonHeaders[headerId].hiddenMonsInfo;
    u8 min = 100;
    u8 max = 0;
    u8 i;

    switch (environment)
    {
    case ENCOUNTER_TYPE_LAND:    // grass
        if (landMonsInfo == NULL)
            return MON_LEVEL_NONEXISTENT; //Hidden pokemon should only appear on walkable tiles or surf tiles

        for (i = 0; i < LAND_WILD_COUNT; i++)
        {
            if (landMonsInfo->wildPokemon[i].species == species)
            {
                min = (min < landMonsInfo->wildPokemon[i].minLevel) ? min : landMonsInfo->wildPokemon[i].minLevel;
                max = (max > landMonsInfo->wildPokemon[i].maxLevel) ? max : landMonsInfo->wildPokemon[i].maxLevel;
            }
        }
        break;
    case ENCOUNTER_TYPE_WATER:    //water
        if (waterMonsInfo == NULL)
            return MON_LEVEL_NONEXISTENT; //Hidden pokemon should only appear on walkable tiles or surf tiles

        for (i = 0; i < WATER_WILD_COUNT; i++)
        {
            if (waterMonsInfo->wildPokemon[i].species == species)
            {
                min = (min < waterMonsInfo->wildPokemon[i].minLevel) ? min : waterMonsInfo->wildPokemon[i].minLevel;
                max = (max > waterMonsInfo->wildPokemon[i].maxLevel) ? max : waterMonsInfo->wildPokemon[i].maxLevel;
            }
        }
        break;
    case ENCOUNTER_TYPE_HIDDEN:
        if (hiddenMonsInfo == NULL)
            return MON_LEVEL_NONEXISTENT;

        for (i = 0; i < HIDDEN_WILD_COUNT; i++)
        {
            if (hiddenMonsInfo->wildPokemon[i].species == species)
            {
                min = (min < hiddenMonsInfo->wildPokemon[i].minLevel) ? min : hiddenMonsInfo->wildPokemon[i].minLevel;
                max = (max > hiddenMonsInfo->wildPokemon[i].maxLevel) ? max : hiddenMonsInfo->wildPokemon[i].maxLevel;
            }
        }

        // use encounter rate to signify is hidden pokemon are on land or in water
        if (hiddenMonsInfo->encounterRate == 1)
            sDexNavSearchDataPtr_dexnav->environment = ENCOUNTER_TYPE_WATER;
        else
            sDexNavSearchDataPtr_dexnav->environment = ENCOUNTER_TYPE_LAND;
        break;
    default:
        return MON_LEVEL_NONEXISTENT;
    }

    if (max == 0)
        return MON_LEVEL_NONEXISTENT;

    return RandomUniform(RNG_DEXNAV_ENCOUNTER_LEVEL, min, max);
}


