        sDexNavUiDataPtr_dexnav->environment = ENCOUNTER_TYPE_WATER;
        break;
    case ROW_LAND_TOP: //land 1
        x = ROW_LAND_ICON_X + (24 * sDexNavUiDataPtr_dexnav->cursorCol);
        y = ROW_LAND_TOP_ICON_Y;
        sDexNavUiDataPtr_dexnav->environment = ENCOUNTER_TYPE_LAND;
        break;
    case ROW_LAND_BOT: //land 2
        x = ROW_LAND_ICON_X + (24 * sDexNavUiDataPtr_dexnav->cursorCol);
        y = ROW_LAND_BOT_ICON_Y;
        sDexNavUiDataPtr_dexnav->environment = ENCOUNTER_TYPE_LAND;
        break;
    case ROW_HIDDEN:
        x = ROW_HIDDEN_ICON_X + (24 * sDexNavUiDataPtr_dexnav->cursorCol);
        y = ROW_HIDDEN_ICON_Y;
        sDexNavUiDataPtr_dexnav->environment = ENCOUNTER_TYPE_HIDDEN;
