static bool8 SpeciesInArray_dexnav(u16 species, u8 section)
{
    u32 i;
    u16 dexNum = SpeciesToNationalPokedexNum(species);

    switch (section)
    {
    case 0: //land
        for (i = 0; i < LAND_WILD_COUNT; i++)
        {
            if (SpeciesToNationalPokedexNum(sDexNavUiDataPtr_dexnav->landSpecies[i]) == dexNum)
                return TRUE;
        }
        break;
    case 1: //water
        for (i = 0; i < WATER_WILD_COUNT; i++)
        {
            if (SpeciesToNationalPokedexNum(sDexNavUiDataPtr_dexnav->waterSpecies[i]) == dexNum)
                return TRUE;
        }
        break;
    case 2: //hidden
        for (i = 0; i < HIDDEN_WILD_COUNT; i++)
        {
            if (SpeciesToNationalPokedexNum(sDexNavUiDataPtr_dexnav->hiddenSpecies[i]) == dexNum)
                return TRUE;
        }
        break;
    default:
        break;
    }

    return FALSE;
}

// get unique wild encounters on current map
static void DexNavLoadEncounterData_dexnav(void)
{
    u8 grassIndex = 0;
    u8 waterIndex = 0;
    u8 hiddenIndex = 0;
    u16 species;
    u32 i;
    u16 headerId = GetCurrentMapWildMonHeaderId();
    const struct WildPokemonInfo* landMonsInfo = gWildMonHeaders[headerId].landMonsInfo;
    const struct WildPokemonInfo* waterMonsInfo = gWildMonHeaders[headerId].waterMonsInfo;
    const struct WildPokemonInfo* hiddenMonsInfo = gWildMonHeaders[headerId].hiddenMonsInfo;

    // nop struct data
    memset(sDexNavUiDataPtr_dexnav->landSpecies, 0, sizeof(sDexNavUiDataPtr_dexnav->landSpecies));
    memset(sDexNavUiDataPtr_dexnav->waterSpecies, 0, sizeof(sDexNavUiDataPtr_dexnav->waterSpecies));
    memset(sDexNavUiDataPtr_dexnav->hiddenSpecies, 0, sizeof(sDexNavUiDataPtr_dexnav->hiddenSpecies));

    // land mons
    if (landMonsInfo != NULL && landMonsInfo->encounterRate != 0)
    {
        for (i = 0; i < LAND_WILD_COUNT; i++)
        {
            species = landMonsInfo->wildPokemon[i].species;
            if (species != SPECIES_NONE && !SpeciesInArray_dexnav(species, 0))
                sDexNavUiDataPtr_dexnav->landSpecies[grassIndex++] = landMonsInfo->wildPokemon[i].species;
        }
    }

    // water mons
    if (waterMonsInfo != NULL && waterMonsInfo->encounterRate != 0)
    {
        for (i = 0; i < WATER_WILD_COUNT; i++)
        {
            species = waterMonsInfo->wildPokemon[i].species;
            if (species != SPECIES_NONE && !SpeciesInArray_dexnav(species, 1))
                sDexNavUiDataPtr_dexnav->waterSpecies[waterIndex++] = waterMonsInfo->wildPokemon[i].species;
        }
    }

    // hidden mons
    if (hiddenMonsInfo != NULL) // no encounter rate check since 0 means land, 1 means water encounters
    {
        for (i = 0; i < HIDDEN_WILD_COUNT; i++)
        {
            species = hiddenMonsInfo->wildPokemon[i].species;
            if (species != SPECIES_NONE && !SpeciesInArray_dexnav(species, 2))
                sDexNavUiDataPtr_dexnav->hiddenSpecies[hiddenIndex++] = hiddenMonsInfo->wildPokemon[i].species;
        }
    }
}

static void TryDrawIconInSlot_dexnav(u16 species, s16 x, s16 y)
{
    if (species == SPECIES_NONE || species > NUM_SPECIES)
        CreateNoDataIcon_dexnav(x, y);   //'X' in slot
    else if (!GetSetPokedexFlag(SpeciesToNationalPokedexNum(species), FLAG_GET_SEEN))
        CreateMonIcon(SPECIES_NONE, SpriteCB_MonIcon, x, y, 0, 0xFFFFFFFF); //question mark
    else
        CreateMonIcon(species, SpriteCB_MonIcon, x, y, 0, 0xFFFFFFFF);
}

static void DrawSpeciesIcons_dexnav(void)
{
    s16 x, y;
    u32 i;
    u16 species;

    LoadCompressedSpriteSheetUsingHeap(&sNoDataIconSpriteSheet_dexnav);
    for (i = 0; i < LAND_WILD_COUNT; i++)
    {
        species = sDexNavUiDataPtr_dexnav->landSpecies[i];
        x = 20 + (24 * (i % 6));
        y = ROW_LAND_TOP_ICON_Y + (i > 5 ? 28 : 0);
        TryDrawIconInSlot_dexnav(species, x, y);
    }

    for (i = 0; i < WATER_WILD_COUNT; i++)
    {
        species = sDexNavUiDataPtr_dexnav->waterSpecies[i];
        x = 30 + 24 * i;
        y = ROW_WATER_ICON_Y;
        TryDrawIconInSlot_dexnav(species, x, y);
    }

    for (i = 0; i < HIDDEN_WILD_COUNT; i++)
    {
        species = sDexNavUiDataPtr_dexnav->hiddenSpecies[i];
        x = ROW_HIDDEN_ICON_X + 24 * i;
        y = ROW_HIDDEN_ICON_Y;
        if (FlagGet(FLAG_SYS_DETECTOR_MODE))
            TryDrawIconInSlot_dexnav(species, x, y);
       else if (species == SPECIES_NONE || species > NUM_SPECIES)
            CreateNoDataIcon_dexnav(x, y);
        else
            CreateMonIcon(SPECIES_NONE, SpriteCB_MonIcon, x, y, 0, 0xFFFFFFFF); //question mark if detector mode inactive
    }
}

static u16 DexNavGetSpecies_dexnav(void)
{
    u16 species;

    switch (sDexNavUiDataPtr_dexnav->cursorRow)
    {
    case ROW_WATER:
        species = sDexNavUiDataPtr_dexnav->waterSpecies[sDexNavUiDataPtr_dexnav->cursorCol];
        break;
    case ROW_LAND_TOP:
        species = sDexNavUiDataPtr_dexnav->landSpecies[sDexNavUiDataPtr_dexnav->cursorCol];
        break;
    case ROW_LAND_BOT:
        species = sDexNavUiDataPtr_dexnav->landSpecies[sDexNavUiDataPtr_dexnav->cursorCol + COL_LAND_COUNT];
        break;
    case ROW_HIDDEN:
        if (!FlagGet(FLAG_SYS_DETECTOR_MODE))
            species = SPECIES_NONE;
        else
            species = sDexNavUiDataPtr_dexnav->hiddenSpecies[sDexNavUiDataPtr_dexnav->cursorCol];
        break;
    default:
        return SPECIES_NONE;
    }

    if (!GetSetPokedexFlag(SpeciesToNationalPokedexNum(species), FLAG_GET_SEEN))
        return SPECIES_NONE;

    return species;
}

