// Contents of dma3_manager.c
#include "global.h"
#include "dma3.h"

#define MAX_DMA_REQUESTS_dma3_manager 128

#define DMA_REQUEST_COPY32_dma3_manager 1
#define DMA_REQUEST_FILL32_dma3_manager 2
#define DMA_REQUEST_COPY16_dma3_manager 3
#define DMA_REQUEST_FILL16_dma3_manager 4

struct Dma3Request
{
    const u8 *src;
    u8 *dest;
    u16 size;
    u16 mode;
    u32 value;
};

static struct Dma3Request  sDma3Requests_dma3_manager[MAX_DMA_REQUESTS_dma3_manager];

static vbool8  sDma3ManagerLocked_dma3_manager;
static u8  sDma3RequestCursor_dma3_manager;

void ClearDma3Requests(void)
{
    int i;

    sDma3ManagerLocked_dma3_manager = TRUE;
    sDma3RequestCursor_dma3_manager = 0;

    for (i = 0; i < MAX_DMA_REQUESTS_dma3_manager; i++)
    {
        sDma3Requests_dma3_manager[i].size = 0;
        sDma3Requests_dma3_manager[i].src = NULL;
        sDma3Requests_dma3_manager[i].dest = NULL;
    }

    sDma3ManagerLocked_dma3_manager = FALSE;
}

void ProcessDma3Requests(void)
{
    u16 bytesTransferred;

    if (sDma3ManagerLocked_dma3_manager)
        return;

    bytesTransferred = 0;

    // as long as there are DMA requests to process (unless size or vblank is an issue), do not exit
    while (sDma3Requests_dma3_manager[sDma3RequestCursor_dma3_manager].size != 0)
    {
        bytesTransferred += sDma3Requests_dma3_manager[sDma3RequestCursor_dma3_manager].size;

        if (bytesTransferred > 40 * 1024)
            return; // don't transfer more than 40 KiB
        if (*(u8 *)REG_ADDR_VCOUNT > 224)
            return; // we're about to leave vblank, stop

        switch (sDma3Requests_dma3_manager[sDma3RequestCursor_dma3_manager].mode)
        {
        case DMA_REQUEST_COPY32_dma3_manager: // regular 32-bit copy
            Dma3CopyLarge32_(sDma3Requests_dma3_manager[sDma3RequestCursor_dma3_manager].src,
                             sDma3Requests_dma3_manager[sDma3RequestCursor_dma3_manager].dest,
                             sDma3Requests_dma3_manager[sDma3RequestCursor_dma3_manager].size);
            break;
        case DMA_REQUEST_FILL32_dma3_manager: // repeat a single 32-bit value across RAM
            Dma3FillLarge32_(sDma3Requests_dma3_manager[sDma3RequestCursor_dma3_manager].value,
                             sDma3Requests_dma3_manager[sDma3RequestCursor_dma3_manager].dest,
                             sDma3Requests_dma3_manager[sDma3RequestCursor_dma3_manager].size);
            break;
        case DMA_REQUEST_COPY16_dma3_manager:    // regular 16-bit copy
            Dma3CopyLarge16_(sDma3Requests_dma3_manager[sDma3RequestCursor_dma3_manager].src,
                             sDma3Requests_dma3_manager[sDma3RequestCursor_dma3_manager].dest,
                             sDma3Requests_dma3_manager[sDma3RequestCursor_dma3_manager].size);
            break;
        case DMA_REQUEST_FILL16_dma3_manager: // repeat a single 16-bit value across RAM
            Dma3FillLarge16_(sDma3Requests_dma3_manager[sDma3RequestCursor_dma3_manager].value,
                             sDma3Requests_dma3_manager[sDma3RequestCursor_dma3_manager].dest,
                             sDma3Requests_dma3_manager[sDma3RequestCursor_dma3_manager].size);
            break;
        }

        // Free the request
        sDma3Requests_dma3_manager[sDma3RequestCursor_dma3_manager].src = NULL;
        sDma3Requests_dma3_manager[sDma3RequestCursor_dma3_manager].dest = NULL;
        sDma3Requests_dma3_manager[sDma3RequestCursor_dma3_manager].size = 0;
        sDma3Requests_dma3_manager[sDma3RequestCursor_dma3_manager].mode = 0;
        sDma3Requests_dma3_manager[sDma3RequestCursor_dma3_manager].value = 0;
        sDma3RequestCursor_dma3_manager++;

        if (sDma3RequestCursor_dma3_manager >= MAX_DMA_REQUESTS_dma3_manager) // loop back to the first DMA request
            sDma3RequestCursor_dma3_manager = 0;
    }
}

s16 RequestDma3Copy(const void *src, void *dest, u16 size, u32 mode)
{
    int cursor;
    int i = 0;

    sDma3ManagerLocked_dma3_manager = TRUE;
    cursor = sDma3RequestCursor_dma3_manager;

    while (i < MAX_DMA_REQUESTS_dma3_manager)
    {
        if (sDma3Requests_dma3_manager[cursor].size == 0) // an empty request was found.
        {
            sDma3Requests_dma3_manager[cursor].src = src;
            sDma3Requests_dma3_manager[cursor].dest = dest;
            sDma3Requests_dma3_manager[cursor].size = size;

            if (mode == 1)
                sDma3Requests_dma3_manager[cursor].mode = DMA_REQUEST_COPY32_dma3_manager;
            else
                sDma3Requests_dma3_manager[cursor].mode = DMA_REQUEST_COPY16_dma3_manager;

            sDma3ManagerLocked_dma3_manager = FALSE;
            return cursor;
        }
        if (++cursor >= MAX_DMA_REQUESTS_dma3_manager) // loop back to start.
            cursor = 0;
        i++;
    }
    sDma3ManagerLocked_dma3_manager = FALSE;
    return -1;  // no free DMA request was found
}

s16 RequestDma3Fill(s32 value, void *dest, u16 size, u32 mode)
{
    int cursor;
    int i = 0;

    cursor = sDma3RequestCursor_dma3_manager;
    sDma3ManagerLocked_dma3_manager = TRUE;

    while (i < MAX_DMA_REQUESTS_dma3_manager)
    {
        if (sDma3Requests_dma3_manager[cursor].size == 0) // an empty request was found.
        {
            sDma3Requests_dma3_manager[cursor].dest = dest;
            sDma3Requests_dma3_manager[cursor].size = size;
            sDma3Requests_dma3_manager[cursor].mode = mode;
            sDma3Requests_dma3_manager[cursor].value = value;

            if(mode == 1)
                sDma3Requests_dma3_manager[cursor].mode = DMA_REQUEST_FILL32_dma3_manager;
            else
                sDma3Requests_dma3_manager[cursor].mode = DMA_REQUEST_FILL16_dma3_manager;

            sDma3ManagerLocked_dma3_manager = FALSE;
            return cursor;
        }
        if (++cursor >= MAX_DMA_REQUESTS_dma3_manager) // loop back to start.
            cursor = 0;
        i++;
    }
    sDma3ManagerLocked_dma3_manager = FALSE;
    return -1;  // no free DMA request was found
}

s16 CheckForSpaceForDma3Request(s16 index)
{
    int i = 0;

    if (index == -1)  // check if all requests are free
    {
        while (i < MAX_DMA_REQUESTS_dma3_manager)
        {
            if (sDma3Requests_dma3_manager[i].size != 0)
                return -1;
            i++;
        }
        return 0;
    }
    else  // check the specified request
    {
        if (sDma3Requests_dma3_manager[index].size != 0)
            return -1;
        return 0;
    }
}
