static void HandleSound_Leader_dodrio_berry_picking(void)
{
    if (sGame_dodrio_berry_picking->players[sGame_dodrio_berry_picking->multiplayerId].comm.pickState == PICK_NONE)
    {
        if (!IsSEPlaying())
            sGame_dodrio_berry_picking->playingPickSound = FALSE;
    }
    else if (sGame_dodrio_berry_picking->players[sGame_dodrio_berry_picking->multiplayerId].comm.ateBerry == TRUE)
    {
        if (!sGame_dodrio_berry_picking->playingPickSound)
        {
            m4aSongNumStop(SE_SUCCESS);
            PlaySE(SE_SUCCESS);
            sGame_dodrio_berry_picking->playingPickSound = TRUE;
        }
    }
    else if (sGame_dodrio_berry_picking->players[sGame_dodrio_berry_picking->multiplayerId].comm.missedBerry == TRUE)
    {
        if (!sGame_dodrio_berry_picking->playingPickSound && !IsSEPlaying())
        {
            PlaySE(SE_BOO);
            StartDodrioMissedAnim_dodrio_berry_picking(1);
            sGame_dodrio_berry_picking->playingPickSound = TRUE;
        }
    }

    if (sGame_dodrio_berry_picking->endSoundState == 0 && sGame_dodrio_berry_picking->numGraySquares >= NUM_STATUS_SQUARES_dodrio_berry_picking)
    {
        // Ready to play game over sound
        StopMapMusic();
        sGame_dodrio_berry_picking->endSoundState = 1;
    }
    else if (sGame_dodrio_berry_picking->endSoundState == 1)
    {
        // Play game over sound
        PlayFanfareByFanfareNum(FANFARE_TOO_BAD);
        sGame_dodrio_berry_picking->endSoundState = 2;
    }
}

static void HandleSound_Member_dodrio_berry_picking(void)
{
    u8 berryStart = sGame_dodrio_berry_picking->berryColStart;
    u8 berryEnd = sGame_dodrio_berry_picking->berryColEnd;
    u8 i;
    if (sGame_dodrio_berry_picking->players[sGame_dodrio_berry_picking->multiplayerId].comm.pickState == PICK_NONE)
    {
        if (sGame_dodrio_berry_picking->players[sGame_dodrio_berry_picking->multiplayerId].comm.ateBerry != TRUE
         && sGame_dodrio_berry_picking->players[sGame_dodrio_berry_picking->multiplayerId].comm.missedBerry != TRUE)
            sGame_dodrio_berry_picking->playingPickSound = 0;
    }
    else if (sGame_dodrio_berry_picking->players[sGame_dodrio_berry_picking->multiplayerId].comm.ateBerry == TRUE)
    {
        if (!sGame_dodrio_berry_picking->playingPickSound)
        {
            m4aSongNumStop(SE_SUCCESS);
            PlaySE(SE_SUCCESS);
            sGame_dodrio_berry_picking->playingPickSound = TRUE;
        }
    }
    else if (sGame_dodrio_berry_picking->players[sGame_dodrio_berry_picking->multiplayerId].comm.missedBerry == TRUE)
    {
        if (!sGame_dodrio_berry_picking->playingPickSound && !IsSEPlaying())
        {
            PlaySE(SE_BOO);
            StartDodrioMissedAnim_dodrio_berry_picking(1);
            sGame_dodrio_berry_picking->playingPickSound = TRUE;
        }
    }
    for (i = berryStart; i < berryEnd; i++)
    {
        struct DodrioGame_Berries * berries = &sGame_dodrio_berry_picking->players[sGame_dodrio_berry_picking->multiplayerId].berries;
        if (berries->fallDist[i] >= MAX_FALL_DIST_dodrio_berry_picking)
        {
            if (!sGame_dodrio_berry_picking->playingSquishSound[i])
            {
                PlaySE(SE_BALLOON_RED + berries->ids[i]);
                sGame_dodrio_berry_picking->playingSquishSound[i] = TRUE;
            }
        }
        else
        {
            sGame_dodrio_berry_picking->playingSquishSound[i] = FALSE;
        }
    }
    if (sGame_dodrio_berry_picking->endSoundState == 0 && sGame_dodrio_berry_picking->numGraySquares >= NUM_STATUS_SQUARES_dodrio_berry_picking)
    {
        // Ready to play game over sound
        StopMapMusic();
        sGame_dodrio_berry_picking->endSoundState = 1;
    }
    else if (sGame_dodrio_berry_picking->endSoundState == 1)
    {
        // Play game over sound
        PlayFanfareByFanfareNum(FANFARE_TOO_BAD);
        sGame_dodrio_berry_picking->endSoundState = 2;
    }
}

