static void GetActiveBerryColumns_dodrio_berry_picking(u8 numPlayers, u8 *start, u8 *end)
{
    switch (numPlayers)
    {
    case 1:
        *start = 4, *end = 7;
        break;
    case 2:
        *start = 3, *end = 8;
        break;
    case 3:
        *start = 2, *end = 9;
        break;
    case 4:
        *start = 1, *end = 10;
        break;
    case 5:
        *start = 0, *end = 11;
        break;
    }
}

static bool32 AllPlayersReadyToStart_dodrio_berry_picking(void)
{
    u8 i, numPlayers;

    numPlayers = sGame_dodrio_berry_picking->numPlayers;
    for (i = 1; i < numPlayers; i++)
    {
        if (sGame_dodrio_berry_picking->readyToStart[i] == FALSE)
            sGame_dodrio_berry_picking->readyToStart[i] = RecvPacket_ReadyToStart_dodrio_berry_picking(i);
    }

    numPlayers = numPlayers; // Needed to force compiler to keep loop below

#ifdef BUGFIX
    i = 1; // i isn't reset, loop below never runs. As a result, game can begin before all players ready
#endif
    for (; i < numPlayers; i++)
    {
        if (sGame_dodrio_berry_picking->readyToStart[i] == FALSE)
            return FALSE;
    }

    return TRUE;
}

static void ResetReadyToStart_dodrio_berry_picking(void)
{
    u8 i;

    for (i = 0; i < MAX_RFU_PLAYERS; i++)
        sGame_dodrio_berry_picking->readyToStart[i] = FALSE;
}

static bool32 ReadyToEndGame_Leader_dodrio_berry_picking(void)
{
    if (sGame_dodrio_berry_picking->numGraySquares >= NUM_STATUS_SQUARES_dodrio_berry_picking && !sGame_dodrio_berry_picking->berriesFalling)
    {
        sGame_dodrio_berry_picking->numGraySquares = NUM_STATUS_SQUARES_dodrio_berry_picking;
        if (sGame_dodrio_berry_picking->allReadyToEnd)
            return TRUE;
    }

    return FALSE;
}

static bool32 ReadyToEndGame_Member_dodrio_berry_picking(void)
{
    u8 i, berryStart, berryEnd;

    if (sGame_dodrio_berry_picking->numGraySquares >= NUM_STATUS_SQUARES_dodrio_berry_picking)
    {
        berryStart = sGame_dodrio_berry_picking->berryColStart;
        berryEnd = sGame_dodrio_berry_picking->berryColEnd;
        sGame_dodrio_berry_picking->numGraySquares = NUM_STATUS_SQUARES_dodrio_berry_picking;
        if (sGame_dodrio_berry_picking->allReadyToEnd)
        {
            for (i = berryStart; i < berryEnd; i++)
            {
                struct DodrioGame_Player *player = &sGame_dodrio_berry_picking->players[sGame_dodrio_berry_picking->multiplayerId];
                u8 column = sActiveColumnMap_dodrio_berry_picking[sGame_dodrio_berry_picking->numPlayers - 1][sGame_dodrio_berry_picking->multiplayerId][i];

                if (player->berries.fallDist[column] != MAX_FALL_DIST_dodrio_berry_picking)
                    return FALSE;
            }
            return TRUE;
        }
    }

    return FALSE;
}

static void TryIncrementDifficulty_dodrio_berry_picking(u8 playerId)
{
    u8 threshold = sDifficultyThresholds_dodrio_berry_picking[sGame_dodrio_berry_picking->difficulty[playerId] % NUM_DIFFICULTIES_dodrio_berry_picking] + (sGame_dodrio_berry_picking->difficulty[playerId] / NUM_DIFFICULTIES_dodrio_berry_picking) * 100;
    if (sGame_dodrio_berry_picking->berriesEaten[playerId] >= threshold)
        sGame_dodrio_berry_picking->difficulty[playerId]++;
}

static u8 GetPlayerIdAtColumn_dodrio_berry_picking(u8 column)
{
    return sPlayerIdAtColumn_dodrio_berry_picking[sGame_dodrio_berry_picking->numPlayers - 1][column];
}

// Get a berry id for when a new falling berry is created.
// What type of berry it is depends on the current difficulty
// level of players who can pick berries from that column.
static u8 GetNewBerryId_dodrio_berry_picking(u8 playerId, u8 column)
{
    u8 i, highestDifficulty;
    u8 numPlayersIdx = sGame_dodrio_berry_picking->numPlayers - 1;
    u8 leftPlayer = sDodrioNeighborMap_dodrio_berry_picking[numPlayersIdx][playerId][0];
    u8 middlePlayer = sDodrioNeighborMap_dodrio_berry_picking[numPlayersIdx][playerId][1];
    u8 rightPlayer = sDodrioNeighborMap_dodrio_berry_picking[numPlayersIdx][playerId][2];

    for (i = 0; sUnsharedColumns_dodrio_berry_picking[numPlayersIdx][i] != 0; i++)
    {
        // If only one player can use this column, just use their difficulty
        if (column == sUnsharedColumns_dodrio_berry_picking[numPlayersIdx][i])
            return GetNewBerryIdByDifficulty_dodrio_berry_picking(sGame_dodrio_berry_picking->difficulty[middlePlayer], column);
    }

    // This column is shared, get the highest difficulty of adjacent players
    if (sGame_dodrio_berry_picking->difficulty[leftPlayer] > sGame_dodrio_berry_picking->difficulty[middlePlayer])
        highestDifficulty = sGame_dodrio_berry_picking->difficulty[leftPlayer];
    else
        highestDifficulty = sGame_dodrio_berry_picking->difficulty[middlePlayer];

    if (sGame_dodrio_berry_picking->difficulty[rightPlayer] > highestDifficulty)
        highestDifficulty = sGame_dodrio_berry_picking->difficulty[rightPlayer];

    return GetNewBerryIdByDifficulty_dodrio_berry_picking(highestDifficulty, column);
}

// The berry types cycle through different distributions depending on the difficulty
static u8 GetNewBerryIdByDifficulty_dodrio_berry_picking(u8 difficulty, u8 column)
{
    u8 prevBerryId = sGame_dodrio_berry_picking->prevBerryIds[column];
    switch (difficulty % NUM_DIFFICULTIES_dodrio_berry_picking)
    {
    default: return BERRY_BLUE_dodrio_berry_picking;
    case 0:  return BERRY_BLUE_dodrio_berry_picking;
    case 1:  return BERRY_GREEN_dodrio_berry_picking;
    case 2:  return BERRY_GOLD_dodrio_berry_picking;
    case 3:
        if (prevBerryId == BERRY_BLUE_dodrio_berry_picking)
            return BERRY_GREEN_dodrio_berry_picking;
        else
            return BERRY_BLUE_dodrio_berry_picking;
    case 4:
        if (prevBerryId == BERRY_BLUE_dodrio_berry_picking)
            return BERRY_GOLD_dodrio_berry_picking;
        else
            return BERRY_BLUE_dodrio_berry_picking;
    case 5:
        if (prevBerryId == BERRY_GOLD_dodrio_berry_picking)
            return BERRY_GREEN_dodrio_berry_picking;
        else
            return BERRY_GOLD_dodrio_berry_picking;
    case 6:
        if (prevBerryId == BERRY_BLUE_dodrio_berry_picking)
            return BERRY_GREEN_dodrio_berry_picking;
        else if (prevBerryId == BERRY_GREEN_dodrio_berry_picking)
            return BERRY_GOLD_dodrio_berry_picking;
        else
            return BERRY_BLUE_dodrio_berry_picking;
    }
}

static bool32 IsTotalBerriesMissedOver10_dodrio_berry_picking(u16 berryResults[MAX_RFU_PLAYERS][NUM_BERRY_IDS_dodrio_berry_picking])
{
    int missed = 0, i = 0;
    for (; i < GetLinkPlayerCount(); missed += berryResults[i][BERRY_MISSED_dodrio_berry_picking], i++)
        ;

    if (missed > 10)
        return TRUE;
    else
        return FALSE;
}

// Despite being set up to take a berry id as an argument, this
// function is only ever given BERRY_BLUE_dodrio_berry_picking or BERRY_MISSED_dodrio_berry_picking.
// It reads the actual berry id (if necessary) from ids
static void IncrementBerryResult_dodrio_berry_picking(u8 berryIdArg, u8 column, u8 playerId)
{
    u8 berryId;
    u8 numPlayers = sGame_dodrio_berry_picking->numPlayers;
    switch (berryIdArg)
    {
    case BERRY_BLUE_dodrio_berry_picking:
    case BERRY_GREEN_dodrio_berry_picking:
    case BERRY_GOLD_dodrio_berry_picking:
        berryId = sGame_dodrio_berry_picking->players[0].berries.ids[column];
        sGame_dodrio_berry_picking->berryResults[playerId][berryId] = IncrementWithLimit_dodrio_berry_picking(sGame_dodrio_berry_picking->berryResults[playerId][berryId], 20000);
        break;
    case BERRY_MISSED_dodrio_berry_picking:
        if (IsTotalBerriesMissedOver10_dodrio_berry_picking(sGame_dodrio_berry_picking->berryResults))
            break;
        switch (numPlayers)
        {
        case 5:
            switch (column)
            {
            case 0:
                sGame_dodrio_berry_picking->berryResults[2][BERRY_MISSED_dodrio_berry_picking]++;
                sGame_dodrio_berry_picking->berryResults[3][BERRY_MISSED_dodrio_berry_picking]++;
                break;
            case 1:
                sGame_dodrio_berry_picking->berryResults[3][BERRY_MISSED_dodrio_berry_picking]++;
                break;
            case 2:
                sGame_dodrio_berry_picking->berryResults[3][BERRY_MISSED_dodrio_berry_picking]++;
                sGame_dodrio_berry_picking->berryResults[4][BERRY_MISSED_dodrio_berry_picking]++;
                break;
            case 3:
                sGame_dodrio_berry_picking->berryResults[4][BERRY_MISSED_dodrio_berry_picking]++;
                break;
            case 4:
                sGame_dodrio_berry_picking->berryResults[4][BERRY_MISSED_dodrio_berry_picking]++;
                sGame_dodrio_berry_picking->berryResults[0][BERRY_MISSED_dodrio_berry_picking]++;
                break;
            case 5:
                sGame_dodrio_berry_picking->berryResults[0][BERRY_MISSED_dodrio_berry_picking]++;
                break;
            case 6:
                sGame_dodrio_berry_picking->berryResults[0][BERRY_MISSED_dodrio_berry_picking]++;
                sGame_dodrio_berry_picking->berryResults[1][BERRY_MISSED_dodrio_berry_picking]++;
                break;
            case 7:
                sGame_dodrio_berry_picking->berryResults[1][BERRY_MISSED_dodrio_berry_picking]++;
                break;
            case 8:
                sGame_dodrio_berry_picking->berryResults[1][BERRY_MISSED_dodrio_berry_picking]++;
                sGame_dodrio_berry_picking->berryResults[2][BERRY_MISSED_dodrio_berry_picking]++;
                break;
            case 9:
                sGame_dodrio_berry_picking->berryResults[2][BERRY_MISSED_dodrio_berry_picking]++;
                break;
            }
            break;
        case 4:
            switch (column)
            {
            case 1:
                sGame_dodrio_berry_picking->berryResults[2][BERRY_MISSED_dodrio_berry_picking]++;
                sGame_dodrio_berry_picking->berryResults[3][BERRY_MISSED_dodrio_berry_picking]++;
                break;
            case 2:
                sGame_dodrio_berry_picking->berryResults[3][BERRY_MISSED_dodrio_berry_picking]++;
                break;
            case 3:
                sGame_dodrio_berry_picking->berryResults[3][BERRY_MISSED_dodrio_berry_picking]++;
                sGame_dodrio_berry_picking->berryResults[0][BERRY_MISSED_dodrio_berry_picking]++;
                break;
            case 4:
                sGame_dodrio_berry_picking->berryResults[0][BERRY_MISSED_dodrio_berry_picking]++;
                break;
            case 5:
                sGame_dodrio_berry_picking->berryResults[0][BERRY_MISSED_dodrio_berry_picking]++;
                sGame_dodrio_berry_picking->berryResults[1][BERRY_MISSED_dodrio_berry_picking]++;
                break;
            case 6:
                sGame_dodrio_berry_picking->berryResults[1][BERRY_MISSED_dodrio_berry_picking]++;
                break;
            case 7:
                sGame_dodrio_berry_picking->berryResults[1][BERRY_MISSED_dodrio_berry_picking]++;
                sGame_dodrio_berry_picking->berryResults[2][BERRY_MISSED_dodrio_berry_picking]++;
                break;
            case 8:
                sGame_dodrio_berry_picking->berryResults[2][BERRY_MISSED_dodrio_berry_picking]++;
                break;
            }
            break;
        case 3:
            switch (column)
            {
            case 2:
                sGame_dodrio_berry_picking->berryResults[1][BERRY_MISSED_dodrio_berry_picking]++;
                sGame_dodrio_berry_picking->berryResults[2][BERRY_MISSED_dodrio_berry_picking]++;
                break;
            case 3:
                sGame_dodrio_berry_picking->berryResults[2][BERRY_MISSED_dodrio_berry_picking]++;
                break;
            case 4:
                sGame_dodrio_berry_picking->berryResults[2][BERRY_MISSED_dodrio_berry_picking]++;
                sGame_dodrio_berry_picking->berryResults[0][BERRY_MISSED_dodrio_berry_picking]++;
                break;
            case 5:
                sGame_dodrio_berry_picking->berryResults[0][BERRY_MISSED_dodrio_berry_picking]++;
                break;
            case 6:
                sGame_dodrio_berry_picking->berryResults[0][BERRY_MISSED_dodrio_berry_picking]++;
                sGame_dodrio_berry_picking->berryResults[1][BERRY_MISSED_dodrio_berry_picking]++;
                break;
            case 7:
                sGame_dodrio_berry_picking->berryResults[1][BERRY_MISSED_dodrio_berry_picking]++;
                break;
            }
            break;
        case 2:
            switch (column)
            {
            case 3:
                sGame_dodrio_berry_picking->berryResults[0][BERRY_MISSED_dodrio_berry_picking]++;
                sGame_dodrio_berry_picking->berryResults[1][BERRY_MISSED_dodrio_berry_picking]++;
                break;
            case 4:
                sGame_dodrio_berry_picking->berryResults[0][BERRY_MISSED_dodrio_berry_picking]++;
                break;
            case 5:
                sGame_dodrio_berry_picking->berryResults[0][BERRY_MISSED_dodrio_berry_picking]++;
                sGame_dodrio_berry_picking->berryResults[1][BERRY_MISSED_dodrio_berry_picking]++;
                break;
            case 6:
                sGame_dodrio_berry_picking->berryResults[1][BERRY_MISSED_dodrio_berry_picking]++;
                break;
            }
            break;
        }
        break;
    }
}

static void UpdateBerriesPickedInRow_dodrio_berry_picking(bool32 picked)
{
    // The 'berries picked in row' stat is only
    // counted for games with all 5 players
    if (sGame_dodrio_berry_picking->numPlayers != MAX_RFU_PLAYERS)
        return;

    if (picked == TRUE)
    {
        if (++sGame_dodrio_berry_picking->berriesPickedInRow > sGame_dodrio_berry_picking->maxBerriesPickedInRow)
            sGame_dodrio_berry_picking->maxBerriesPickedInRow = sGame_dodrio_berry_picking->berriesPickedInRow;
        if (sGame_dodrio_berry_picking->berriesPickedInRow > MAX_BERRIES_dodrio_berry_picking)
            sGame_dodrio_berry_picking->berriesPickedInRow = MAX_BERRIES_dodrio_berry_picking;
    }
    else // missed
    {
        if (sGame_dodrio_berry_picking->berriesPickedInRow > sGame_dodrio_berry_picking->maxBerriesPickedInRow)
            sGame_dodrio_berry_picking->maxBerriesPickedInRow = sGame_dodrio_berry_picking->berriesPickedInRow;
        sGame_dodrio_berry_picking->berriesPickedInRow = 0;
    }
}

static void SetMaxBerriesPickedInRow_dodrio_berry_picking(void)
{
    u8 i;
    for (i = 0; i < sGame_dodrio_berry_picking->numPlayers; i++)
        sGame_dodrio_berry_picking->berryResults[i][BERRY_IN_ROW_dodrio_berry_picking] = sGame_dodrio_berry_picking->maxBerriesPickedInRow;
}

static void ResetForPlayAgainPrompt_dodrio_berry_picking(void)
{
    u8 i, j;

    for (i = 0; i < MAX_RFU_PLAYERS; i++)
    {
        for (j = 0; j < NUM_BERRY_COLUMNS_dodrio_berry_picking; j++)
            sGame_dodrio_berry_picking->players[i].berries.fallDist[j] = 0;
        sGame_dodrio_berry_picking->players[i].comm.pickState = PICK_NONE;
        sGame_dodrio_berry_picking->players[i].comm.ateBerry = FALSE;
        sGame_dodrio_berry_picking->difficulty[i] = 0;
        sGame_dodrio_berry_picking->berriesEaten[i] = 0;
        sGame_dodrio_berry_picking->scoreResults[i].ranking = 0;
        sGame_dodrio_berry_picking->scoreResults[i].score = 0;
        sGame_dodrio_berry_picking->berryResults[i][BERRY_BLUE_dodrio_berry_picking] = 0;
        sGame_dodrio_berry_picking->berryResults[i][BERRY_GREEN_dodrio_berry_picking] = 0;
        sGame_dodrio_berry_picking->berryResults[i][BERRY_GOLD_dodrio_berry_picking] = 0;
        sGame_dodrio_berry_picking->berryResults[i][BERRY_MISSED_dodrio_berry_picking] = 0;
        sGame_dodrio_berry_picking->berryResults[i][BERRY_PRIZE_dodrio_berry_picking] = 0;
        sGame_dodrio_berry_picking->berryResults[i][BERRY_IN_ROW_dodrio_berry_picking] = 0;
    }
    sGame_dodrio_berry_picking->endSoundState = 0;
    sGame_dodrio_berry_picking->berriesPickedInRow = 0;
    sGame_dodrio_berry_picking->numGraySquares = 0;
    UpdateAllDodrioAnims_dodrio_berry_picking();
    UpdateBerrySprites_dodrio_berry_picking();
}

