#define tState_dodrio_berry_picking data[0]
#define tWindowId_dodrio_berry_picking data[1]

static void Task_ShowDodrioBerryPickingRecords_dodrio_berry_picking(u8 taskId)
{
    struct WindowTemplate window;
    s32 i, width, widthCurr;
    s16 *data = gTasks[taskId].data;

    switch (tState_dodrio_berry_picking)
    {
    case 0:
        window = sWindowTemplates_Records_dodrio_berry_picking;
        width = GetStringWidth(FONT_NORMAL, gText_BerryPickingRecords, 0);
        for (i = 0; i < ARRAY_COUNT(sRecordsTexts); i++)
        {
            widthCurr = GetStringWidth(FONT_NORMAL, sRecordsTexts[i], 0) + 50;
            if (widthCurr > width)
                width = widthCurr;
        }
        width = (width + 7) / 8;
        if (width & 1)
            width++;
        window.tilemapLeft = (30 - width) / 2;
        window.width = width;
        tWindowId_dodrio_berry_picking = AddWindow(&window);
        PrintRecordsText_dodrio_berry_picking(tWindowId_dodrio_berry_picking, width);
        CopyWindowToVram(tWindowId_dodrio_berry_picking, COPYWIN_FULL);
        tState_dodrio_berry_picking++;
        break;
    case 1:
        if (!IsDma3ManagerBusyWithBgCopy())
            tState_dodrio_berry_picking++;
        break;
    case 2:
        if (JOY_NEW(A_BUTTON | B_BUTTON))
        {
            rbox_fill_rectangle(tWindowId_dodrio_berry_picking);
            CopyWindowToVram(tWindowId_dodrio_berry_picking, COPYWIN_MAP);
            tState_dodrio_berry_picking++;
        }
        break;
    case 3:
        if (!IsDma3ManagerBusyWithBgCopy())
        {
            RemoveWindow(tWindowId_dodrio_berry_picking);
            DestroyTask(taskId);
            ScriptContext_Enable();
        }
        break;
    }
}

#undef tState_dodrio_berry_picking
#undef tWindowId_dodrio_berry_picking

static void PrintRecordsText_dodrio_berry_picking(u8 windowId, s32 width)
{
    s32 i, x, numWidth;
    s32 recordNums[NUM_RECORD_TYPES_dodrio_berry_picking];
    recordNums[0] = gSaveBlock2Ptr->berryPick.berriesPicked;
    recordNums[1] = gSaveBlock2Ptr->berryPick.bestScore;
    recordNums[2] = gSaveBlock2Ptr->berryPick.berriesPickedInRow;

    LoadUserWindowBorderGfx_(windowId, 0x21D, BG_PLTT_ID(13));
    DrawTextBorderOuter(windowId, 0x21D, 13);
    FillWindowPixelBuffer(windowId, PIXEL_FILL(1));
    AddTextPrinterParameterized(windowId, FONT_NORMAL, gText_BerryPickingRecords, GetStringCenterAlignXOffset(FONT_NORMAL, gText_BerryPickingRecords, width * 8), 1, TEXT_SKIP_DRAW, NULL);
    for (i = 0; i < NUM_RECORD_TYPES_dodrio_berry_picking; i++)
    {
        ConvertIntToDecimalStringN(gStringVar1, recordNums[i], STR_CONV_MODE_LEFT_ALIGN, sRecordNumMaxDigits_dodrio_berry_picking[i]);
        numWidth = GetStringWidth(FONT_NORMAL, gStringVar1, -1);
        AddTextPrinterParameterized(windowId, FONT_NORMAL, sRecordsTexts[i], 0, sRecordTextYCoords_dodrio_berry_picking[i][0], TEXT_SKIP_DRAW, NULL);
        x = (width * 8) - numWidth;
        AddTextPrinterParameterized(windowId, FONT_NORMAL, gStringVar1, x, sRecordNumYCoords_dodrio_berry_picking[i][0], TEXT_SKIP_DRAW, NULL);
    }
    PutWindowTilemap(windowId);
}

