#define sState_dodrio_berry_picking   data[0]
#define sTimer_dodrio_berry_picking   data[1]
#define sUnused1_dodrio_berry_picking data[2]
#define sUnused2_dodrio_berry_picking data[3]
#define sUnused3_dodrio_berry_picking data[4]

static void SpriteCB_Dodrio_dodrio_berry_picking(struct Sprite *sprite)
{
    switch (sprite->sState_dodrio_berry_picking)
    {
    case 0:
        break;
    case 1:
        DoDodrioMissedAnim_dodrio_berry_picking(sprite);
        break;
    case 2:
        DoDodrioIntroAnim_dodrio_berry_picking(sprite);
        break;
    }
}

static void StartDodrioMissedAnim_dodrio_berry_picking(u8 unused)
{
    struct Sprite *sprite = &gSprites[*sDodrioSpriteIds_dodrio_berry_picking[GetMultiplayerId()]];
    sprite->sState_dodrio_berry_picking = 1;
    sprite->sTimer_dodrio_berry_picking = 0;
    sprite->sUnused1_dodrio_berry_picking = 0;
    sprite->sUnused2_dodrio_berry_picking = 0;
    sprite->sUnused3_dodrio_berry_picking = 0;
}

static void StartDodrioIntroAnim_dodrio_berry_picking(u8 unused)
{
    struct Sprite *sprite = &gSprites[*sDodrioSpriteIds_dodrio_berry_picking[GetMultiplayerId()]];
    sprite->sState_dodrio_berry_picking = 2;
    sprite->sTimer_dodrio_berry_picking = 0;
    sprite->sUnused1_dodrio_berry_picking = 0;
    sprite->sUnused2_dodrio_berry_picking = 0;
    sprite->sUnused3_dodrio_berry_picking = 0;
}

// Do animation where Dodrio shakes horizontally after reaching for a berry and missing
static u32 DoDodrioMissedAnim_dodrio_berry_picking(struct Sprite *sprite)
{
    s8 x;
    u8 state = (++sprite->sTimer_dodrio_berry_picking / 2) % 4;

    if (sprite->sTimer_dodrio_berry_picking >= 3)
    {
        switch (state)
        {
        default:
            x = 1;
            break;
        case 1:
        case 2:
            x = -1;
            break;
        }

        sprite->x += x;
        if (++sprite->sTimer_dodrio_berry_picking >= 40)
        {
            sprite->sState_dodrio_berry_picking = 0;
            sprite->x = GetDodrioXPos_dodrio_berry_picking(0, GetNumPlayers_dodrio_berry_picking());
        }
    }

    return 0;
}

// Does the intro animation where the player's Dodrio
// cycles through extending each head twice
#define FRAMES_PER_STATE_dodrio_berry_picking  13
#define NUM_INTRO_PICK_STATES_dodrio_berry_picking PICK_DISABLED // Cycle through 'Normal' and each head, but exclude the Disabled state

static u32 DoDodrioIntroAnim_dodrio_berry_picking(struct Sprite *sprite)
{
    u8 pickState = (++sprite->sTimer_dodrio_berry_picking / FRAMES_PER_STATE_dodrio_berry_picking) % NUM_INTRO_PICK_STATES_dodrio_berry_picking;

    // Play a sound effect at the start of each head extension
    if (sprite->sTimer_dodrio_berry_picking % FRAMES_PER_STATE_dodrio_berry_picking == 0 && pickState != PICK_NONE)
        PlaySE(SE_M_CHARM);

    if (sprite->sTimer_dodrio_berry_picking >= FRAMES_PER_STATE_dodrio_berry_picking * NUM_INTRO_PICK_STATES_dodrio_berry_picking * 2)
    {
        // End animation
        sprite->sState_dodrio_berry_picking = 0;
        pickState = PICK_NONE;
    }
    SetDodrioAnim_dodrio_berry_picking(GetMultiplayerId(), pickState);
    return 0;
}

