// Progress an animation where each square of the
// status bar drops down into view, bounces up,
// then settles into position.
// Returns TRUE if the animation is complete
static bool32 DoStatusBarIntro_dodrio_berry_picking(void)
{
    u8 i;
    bool32 animActive = FALSE;
    for (i = 0; i < NUM_STATUS_SQUARES_dodrio_berry_picking; i++)
    {
        struct Sprite *sprite = &gSprites[sStatusBar_dodrio_berry_picking->spriteIds[i]];
        sStatusBar_dodrio_berry_picking->yChange[i] = 2;
        if (sStatusBar_dodrio_berry_picking->entered[i] && sprite->y == 8)
            continue;

        animActive = TRUE;
        if (sprite->y == 8)
        {
            if (sStatusBar_dodrio_berry_picking->entered[i])
                continue;

            // Square has entered screen, play click
            // sound and reverse direction
            sStatusBar_dodrio_berry_picking->entered[i] = TRUE;
            sStatusBar_dodrio_berry_picking->yChange[i] = -16;
            PlaySE(SE_CLICK);
        }
        sprite->y += sStatusBar_dodrio_berry_picking->yChange[i];
    }

    if (animActive)
        return FALSE;
    else
        return TRUE;
}

// The status bar at the top changes color depending on the game performance.
// The squares start out yellow. For every berry missed, a square is colored gray.
// If there are 4 or fewer yellow squares left they also flash red
static void UpdateStatusBarAnim_dodrio_berry_picking(u8 numEmpty)
{
    u8 i;

    if (numEmpty > NUM_STATUS_SQUARES_dodrio_berry_picking)
    {
        // All squares gray
        for (i = 0; i < NUM_STATUS_SQUARES_dodrio_berry_picking; i++)
            StartSpriteAnim(&gSprites[sStatusBar_dodrio_berry_picking->spriteIds[i]], STATUS_GRAY_dodrio_berry_picking);
    }
    else
    {
        // At least 1 square is yellow
        for (i = 0; i < NUM_STATUS_SQUARES_dodrio_berry_picking - numEmpty; i++)
        {
            if (numEmpty > 6)
            {
                // Flash the yellow squares red
                // The flash cycles faster the fewer yellow squares remain
                sStatusBar_dodrio_berry_picking->flashTimer += numEmpty - 6;
                if (sStatusBar_dodrio_berry_picking->flashTimer > 30)
                    sStatusBar_dodrio_berry_picking->flashTimer = 0;
                else if (sStatusBar_dodrio_berry_picking->flashTimer > 10)
                    StartSpriteAnim(&gSprites[sStatusBar_dodrio_berry_picking->spriteIds[i]], STATUS_RED_dodrio_berry_picking);
                else
                    StartSpriteAnim(&gSprites[sStatusBar_dodrio_berry_picking->spriteIds[i]], STATUS_YELLOW_dodrio_berry_picking);
            }
            else
            {
                // Set yellow squares, no flash
                StartSpriteAnim(&gSprites[sStatusBar_dodrio_berry_picking->spriteIds[i]], STATUS_YELLOW_dodrio_berry_picking);
            }
        }

        // Set remaining squares gray
        for (; i < NUM_STATUS_SQUARES_dodrio_berry_picking; i++)
            StartSpriteAnim(&gSprites[sStatusBar_dodrio_berry_picking->spriteIds[i]], STATUS_GRAY_dodrio_berry_picking);
    }
}

