static void Task_TryRunGfxFunc_dodrio_berry_picking(u8 taskId)
{
    // Continue calling function until it
    // has reached its finished state.
    // Another will not be called until
    // readied by SetGfxFunc_dodrio_berry_picking
    if (!sGfx_dodrio_berry_picking->finished)
        GetGfxFunc()();
}

static void LoadGfx_dodrio_berry_picking(void)
{
    switch (sGfx_dodrio_berry_picking->state)
    {
    case 0:
        InitBgs_dodrio_berry_picking();
        sGfx_dodrio_berry_picking->state++;
        break;
    case 1:
        if (LoadBgGfx_dodrio_berry_picking() == TRUE)
            sGfx_dodrio_berry_picking->state++;
        break;
    case 2:
        CopyToBgTilemapBuffer(BG_SCENERY_dodrio_berry_picking, sBg_Tilemap_dodrio_berry_picking, 0, 0);
        CopyToBgTilemapBuffer(BG_TREE_LEFT_dodrio_berry_picking, sTreeBorderLeft_Tilemap_dodrio_berry_picking, 0, 0);
        CopyToBgTilemapBuffer(BG_TREE_RIGHT_dodrio_berry_picking, sTreeBorderRight_Tilemap_dodrio_berry_picking, 0, 0);
        CopyBgTilemapBufferToVram(BG_SCENERY_dodrio_berry_picking);
        CopyBgTilemapBufferToVram(BG_TREE_LEFT_dodrio_berry_picking);
        CopyBgTilemapBufferToVram(BG_TREE_RIGHT_dodrio_berry_picking);
        sGfx_dodrio_berry_picking->state++;
        break;
    case 3:
        ShowBg(BG_INTERFACE_dodrio_berry_picking);
        ShowBg(BG_SCENERY_dodrio_berry_picking);
        ShowBg(BG_TREE_LEFT_dodrio_berry_picking);
        ShowBg(BG_TREE_RIGHT_dodrio_berry_picking);
        sGfx_dodrio_berry_picking->state++;
        break;
    case 4:
        LoadWindowFrameGfx_dodrio_berry_picking(gSaveBlock2Ptr->optionsWindowFrameType);
        LoadUserWindowFrameGfx_dodrio_berry_picking();
        sGfx_dodrio_berry_picking->state++;
        break;
    default:
        sGfx_dodrio_berry_picking->finished = TRUE;
        break;
    }
}

static void ShowNames_dodrio_berry_picking(void)
{
    u8 i, numPlayers, playerId, colorsId, *name;
    u32 left;
    struct WindowTemplate window;
    const struct WinCoords *coords;

    switch (sGfx_dodrio_berry_picking->state)
    {
    case 0:
        numPlayers = GetNumPlayers_dodrio_berry_picking();
        coords = sNameWindowCoords[numPlayers - 1];
        window.bg = BG_INTERFACE_dodrio_berry_picking;
        window.width = 7;
        window.height = 2;
        window.paletteNum = 13;
        window.baseBlock = 0x13;
        for (i = 0; i < numPlayers; coords++, i++)
        {
            colorsId = COLORID_GRAY_dodrio_berry_picking;
            playerId = GetPlayerIdByPos_dodrio_berry_picking(i);
            left = (56 - GetStringWidth(FONT_NORMAL, GetPlayerName(playerId), -1)) / 2u;
            window.tilemapLeft = coords->left;
            window.tilemapTop = coords->top;
            sGfx_dodrio_berry_picking->windowIds[i] = AddWindow(&window);
            ClearWindowTilemap(sGfx_dodrio_berry_picking->windowIds[i]);
            FillWindowPixelBuffer(sGfx_dodrio_berry_picking->windowIds[i], PIXEL_FILL(1));
            if (playerId == GetMultiplayerId())
                colorsId = COLORID_BLUE_dodrio_berry_picking;
            name = GetPlayerName(playerId);
            AddTextPrinterParameterized3(sGfx_dodrio_berry_picking->windowIds[i], FONT_NORMAL, left, 1, sTextColorTable_dodrio_berry_picking[colorsId], TEXT_SKIP_DRAW, name);
            CopyWindowToVram(sGfx_dodrio_berry_picking->windowIds[i], COPYWIN_GFX);
            window.baseBlock += 0xE;
            DrawMessageWindow_dodrio_berry_picking(&window);
        }
        sGfx_dodrio_berry_picking->state++;
        break;
    case 1:
        if (!IsDma3ManagerBusyWithBgCopy())
        {
            numPlayers = GetNumPlayers_dodrio_berry_picking();
            for (i = 0; i < numPlayers; i++)
                PutWindowTilemap(sGfx_dodrio_berry_picking->windowIds[i]);
            CopyBgTilemapBufferToVram(BG_INTERFACE_dodrio_berry_picking);
            sGfx_dodrio_berry_picking->state++;
        }
        break;
    default:
        if (++sGfx_dodrio_berry_picking->state > 180)
        {
            numPlayers = GetNumPlayers_dodrio_berry_picking();
            for (i = 0; i < numPlayers; i++)
            {
                ClearWindowTilemap(sGfx_dodrio_berry_picking->windowIds[i]);
                RemoveWindow(sGfx_dodrio_berry_picking->windowIds[i]);
            }
            FillBgTilemapBufferRect_Palette0(BG_INTERFACE_dodrio_berry_picking, 0, 0, 0, DISPLAY_TILE_WIDTH, DISPLAY_TILE_HEIGHT);
            CopyBgTilemapBufferToVram(BG_INTERFACE_dodrio_berry_picking);
            sGfx_dodrio_berry_picking->finished = TRUE;
        }
        break;
    }
}

static void PrintRankedScores_dodrio_berry_picking(u8 numPlayers_)
{
    u8 i, ranking = 0, rankedPlayers = 0;
    u8 numPlayers = numPlayers_; // Needed to match
    u8 *name;
    u32 x, numWidth;
    u8 numString[32];
    u8 playersByRanking[MAX_RFU_PLAYERS] = {0, 1, 2, 3, 4};
    struct DodrioGame_ScoreResults temp, scoreResults[MAX_RFU_PLAYERS];

    // Get all players scores and rankings
    for (i = 0; i < numPlayers; i++)
    {
        playersByRanking[i] = i;
        GetScoreResults_dodrio_berry_picking(&temp, i);
        scoreResults[i] = temp;
    }

    // Sort player ids by ranking
    if (GetHighestScore_dodrio_berry_picking() != 0)
    {
        do
        {
            for (i = 0; i < numPlayers; i++)
            {
                if (scoreResults[i].ranking == ranking)
                {
                    playersByRanking[rankedPlayers] = i;
                    rankedPlayers++;
                }
            }
            ranking = rankedPlayers;
        } while (rankedPlayers < numPlayers);
    }

    // Put any player with a score of 0 at lowest ranking
    for (i = 0; i < numPlayers; i++)
    {
        if (scoreResults[i].score == 0)
            scoreResults[i].ranking = numPlayers - 1;
    }

    // Print text
    x = 216 - GetStringWidth(FONT_NORMAL, gText_SpacePoints, 0);
    for (i = 0; i < numPlayers; i++)
    {
        u8 colorsId = COLORID_GRAY_dodrio_berry_picking;
        u8 playerId = playersByRanking[i];
        u32 points = scoreResults[playerId].score;

        AddTextPrinterParameterized(sGfx_dodrio_berry_picking->windowIds[1], FONT_NORMAL, sRankingTexts[scoreResults[playerId].ranking], 8, sRankingYCoords_dodrio_berry_picking[i], TEXT_SKIP_DRAW, NULL);
        if (playerId == GetMultiplayerId())
            colorsId = COLORID_BLUE_dodrio_berry_picking;
        name = GetPlayerName(playerId);
        AddTextPrinterParameterized3(sGfx_dodrio_berry_picking->windowIds[1], FONT_NORMAL, 28, sRankingYCoords_dodrio_berry_picking[i], sTextColorTable_dodrio_berry_picking[colorsId], TEXT_SKIP_DRAW, name);
        ConvertIntToDecimalStringN(numString, points, STR_CONV_MODE_LEFT_ALIGN, 7);
        numWidth = GetStringWidth(FONT_NORMAL, numString, -1);
        AddTextPrinterParameterized(sGfx_dodrio_berry_picking->windowIds[1], FONT_NORMAL, numString, x - numWidth, sRankingYCoords_dodrio_berry_picking[i], TEXT_SKIP_DRAW, NULL);
        AddTextPrinterParameterized(sGfx_dodrio_berry_picking->windowIds[1], FONT_NORMAL, gText_SpacePoints, x, sRankingYCoords_dodrio_berry_picking[i], TEXT_SKIP_DRAW, NULL);
    }
}

static void ShowResults_dodrio_berry_picking(void)
{
    u8 i, j, prizeState, numPlayers = GetNumPlayers_dodrio_berry_picking();
    u8 *name;
    u32 strWidth, x;

    switch (sGfx_dodrio_berry_picking->state)
    {
    case 0:
        SetScoreResults_dodrio_berry_picking();
        sGfx_dodrio_berry_picking->timer = 0;
        sGfx_dodrio_berry_picking->state++;
        break;
    case 1:
        sGfx_dodrio_berry_picking->windowIds[0] = AddWindow(&sWindowTemplates_Results_dodrio_berry_picking[0]);
        sGfx_dodrio_berry_picking->windowIds[1] = AddWindow(&sWindowTemplates_Results_dodrio_berry_picking[1]);
        ClearWindowTilemap(sGfx_dodrio_berry_picking->windowIds[0]);
        ClearWindowTilemap(sGfx_dodrio_berry_picking->windowIds[1]);
        DrawMessageWindow_dodrio_berry_picking(&sWindowTemplates_Results_dodrio_berry_picking[0]);
        DrawMessageWindow_dodrio_berry_picking(&sWindowTemplates_Results_dodrio_berry_picking[1]);
        sGfx_dodrio_berry_picking->state++;
        break;
    case 2:
        FillWindowPixelBuffer(sGfx_dodrio_berry_picking->windowIds[0], PIXEL_FILL(1));
        FillWindowPixelBuffer(sGfx_dodrio_berry_picking->windowIds[1], PIXEL_FILL(1));
        strWidth = GetStringWidth(FONT_NORMAL, gText_BerryPickingResults, -1);
        x = (224 - strWidth) / 2;
        AddTextPrinterParameterized(sGfx_dodrio_berry_picking->windowIds[0], FONT_NORMAL, gText_BerryPickingResults, x, 1, TEXT_SKIP_DRAW, NULL);
        AddTextPrinterParameterized(sGfx_dodrio_berry_picking->windowIds[1], FONT_NORMAL, gText_10P30P50P50P, 68, 17, TEXT_SKIP_DRAW, NULL);
        for (i = 0; i < numPlayers; i++)
        {
            u8 colorsId = COLORID_GRAY_dodrio_berry_picking;
            if (i == GetMultiplayerId())
                colorsId = COLORID_BLUE_dodrio_berry_picking;

            name = GetPlayerName(i);
            AddTextPrinterParameterized3(sGfx_dodrio_berry_picking->windowIds[1], FONT_NORMAL, 0, sResultsYCoords_dodrio_berry_picking[i], sTextColorTable_dodrio_berry_picking[colorsId], TEXT_SKIP_DRAW, name);
            for (j = 0; j < 4; j++)
            {
                u32 width;
                u16 berriesPicked = Min_dodrio_berry_picking(GetBerryResult_dodrio_berry_picking(i, j), MAX_BERRIES_dodrio_berry_picking);
                u16 maxBerriesPicked = Min_dodrio_berry_picking(GetHighestBerryResult_dodrio_berry_picking(j), MAX_BERRIES_dodrio_berry_picking);

                ConvertIntToDecimalStringN(gStringVar4, berriesPicked, STR_CONV_MODE_LEFT_ALIGN, 4);
                width = GetStringWidth(FONT_NORMAL, gStringVar4, -1);

                // If player got the most of a berry type, highlight their number in red
                if (maxBerriesPicked == berriesPicked && maxBerriesPicked != 0)
                    AddTextPrinterParameterized3(sGfx_dodrio_berry_picking->windowIds[1], FONT_NORMAL, sResultsXCoords_dodrio_berry_picking[j] - width, sResultsYCoords_dodrio_berry_picking[i], sTextColorTable_dodrio_berry_picking[COLORID_RED_dodrio_berry_picking], TEXT_SKIP_DRAW, gStringVar4);
                else
                    AddTextPrinterParameterized(sGfx_dodrio_berry_picking->windowIds[1], FONT_NORMAL, gStringVar4, sResultsXCoords_dodrio_berry_picking[j] - width, sResultsYCoords_dodrio_berry_picking[i], TEXT_SKIP_DRAW, NULL);
            }
        }
        CopyWindowToVram(sGfx_dodrio_berry_picking->windowIds[0], COPYWIN_GFX);
        CopyWindowToVram(sGfx_dodrio_berry_picking->windowIds[1], COPYWIN_GFX);
        sGfx_dodrio_berry_picking->state++;
        break;
    case 3:
        if (!IsDma3ManagerBusyWithBgCopy())
        {
            PutWindowTilemap(sGfx_dodrio_berry_picking->windowIds[0]);
            PutWindowTilemap(sGfx_dodrio_berry_picking->windowIds[1]);
        }
        CopyBgTilemapBufferToVram(BG_INTERFACE_dodrio_berry_picking);
        SetBerryIconsInvisibility_dodrio_berry_picking(FALSE);
        sGfx_dodrio_berry_picking->state++;
        break;
    case 4:
        if (++sGfx_dodrio_berry_picking->timer >= 30 && JOY_NEW(A_BUTTON))
        {
            sGfx_dodrio_berry_picking->timer = 0;
            PlaySE(SE_SELECT);
            SetBerryIconsInvisibility_dodrio_berry_picking(TRUE);
            sGfx_dodrio_berry_picking->state++;
        }
        break;
    case 5:
        FillWindowPixelBuffer(sGfx_dodrio_berry_picking->windowIds[0], PIXEL_FILL(1));
        FillWindowPixelBuffer(sGfx_dodrio_berry_picking->windowIds[1], PIXEL_FILL(1));
        strWidth = GetStringWidth(FONT_NORMAL, gText_AnnouncingRankings, -1);
        x = (224 - strWidth) / 2;
        AddTextPrinterParameterized(sGfx_dodrio_berry_picking->windowIds[0], FONT_NORMAL, gText_AnnouncingRankings, x, 1, TEXT_SKIP_DRAW, NULL);
        sGfx_dodrio_berry_picking->state++;
        break;
    case 6:
        PrintRankedScores_dodrio_berry_picking(numPlayers);
        CopyWindowToVram(sGfx_dodrio_berry_picking->windowIds[0], COPYWIN_GFX);
        CopyWindowToVram(sGfx_dodrio_berry_picking->windowIds[1], COPYWIN_GFX);
        sGfx_dodrio_berry_picking->state++;
        break;
    case 7:
        if (!IsDma3ManagerBusyWithBgCopy())
        {
            PutWindowTilemap(sGfx_dodrio_berry_picking->windowIds[0]);
            PutWindowTilemap(sGfx_dodrio_berry_picking->windowIds[1]);
        }
        CopyBgTilemapBufferToVram(BG_INTERFACE_dodrio_berry_picking);
        sGfx_dodrio_berry_picking->state++;
        break;
    case 8:
        if (++sGfx_dodrio_berry_picking->timer >= 30 && JOY_NEW(A_BUTTON))
        {
            sGfx_dodrio_berry_picking->timer = 0;
            PlaySE(SE_SELECT);
            if (GetHighestScore_dodrio_berry_picking() < PRIZE_SCORE_dodrio_berry_picking)
            {
                sGfx_dodrio_berry_picking->state = 127; // Skip to end, past giving prize
            }
            else
            {
                StopMapMusic();
                sGfx_dodrio_berry_picking->state++;
            }

            FillBgTilemapBufferRect_Palette0(BG_INTERFACE_dodrio_berry_picking, 0, 0, 5, DISPLAY_TILE_WIDTH, DISPLAY_TILE_HEIGHT - 5);
            RemoveWindow(sGfx_dodrio_berry_picking->windowIds[1]);
            sGfx_dodrio_berry_picking->windowIds[1] = AddWindow(&sWindowTemplate_Prize_dodrio_berry_picking);
            ClearWindowTilemap(sGfx_dodrio_berry_picking->windowIds[1]);
            DrawMessageWindow_dodrio_berry_picking(&sWindowTemplate_Prize_dodrio_berry_picking);
        }
        break;
    case 9:
        PlayNewMapMusic(MUS_LEVEL_UP);
        FillWindowPixelBuffer(sGfx_dodrio_berry_picking->windowIds[0], PIXEL_FILL(1));
        FillWindowPixelBuffer(sGfx_dodrio_berry_picking->windowIds[1], PIXEL_FILL(1));
        strWidth = GetStringWidth(FONT_NORMAL, gText_AnnouncingPrizes, -1);
        x = (224 - strWidth) / 2;
        AddTextPrinterParameterized(sGfx_dodrio_berry_picking->windowIds[0], FONT_NORMAL, gText_AnnouncingPrizes, x, 1, TEXT_SKIP_DRAW, NULL);
        DynamicPlaceholderTextUtil_Reset();
        CopyItemName(GetPrizeItemId_dodrio_berry_picking(), gStringVar1);
        DynamicPlaceholderTextUtil_SetPlaceholderPtr(0, gStringVar1);
        DynamicPlaceholderTextUtil_ExpandPlaceholders(gStringVar4, gText_FirstPlacePrize);
        AddTextPrinterParameterized(sGfx_dodrio_berry_picking->windowIds[1], FONT_NORMAL, gStringVar4, 0, 1, TEXT_SKIP_DRAW, NULL);
        prizeState = TryGivePrize_dodrio_berry_picking();
        if (prizeState != PRIZE_RECEIVED_dodrio_berry_picking && prizeState != NO_PRIZE_dodrio_berry_picking)
        {
            DynamicPlaceholderTextUtil_Reset();
            CopyItemName(GetPrizeItemId_dodrio_berry_picking(), gStringVar1);
            DynamicPlaceholderTextUtil_SetPlaceholderPtr(0, gStringVar1);
            if (prizeState == PRIZE_NO_ROOM_dodrio_berry_picking)
                DynamicPlaceholderTextUtil_ExpandPlaceholders(gStringVar4, gText_CantHoldAnyMore);
            else if (prizeState == PRIZE_FILLED_BAG_dodrio_berry_picking)
                DynamicPlaceholderTextUtil_ExpandPlaceholders(gStringVar4, gText_FilledStorageSpace);
            AddTextPrinterParameterized(sGfx_dodrio_berry_picking->windowIds[1], FONT_NORMAL, gStringVar4, 0, 41, TEXT_SKIP_DRAW, NULL);
        }
        CopyWindowToVram(sGfx_dodrio_berry_picking->windowIds[0], COPYWIN_GFX);
        CopyWindowToVram(sGfx_dodrio_berry_picking->windowIds[1], COPYWIN_GFX);
        sGfx_dodrio_berry_picking->state++;
        break;
    case 10:
        if (!IsDma3ManagerBusyWithBgCopy())
        {
            PutWindowTilemap(sGfx_dodrio_berry_picking->windowIds[0]);
            PutWindowTilemap(sGfx_dodrio_berry_picking->windowIds[1]);
        }
        CopyBgTilemapBufferToVram(BG_INTERFACE_dodrio_berry_picking);
        FadeOutAndFadeInNewMapMusic(MUS_RG_VICTORY_WILD, 20, 10);
        sGfx_dodrio_berry_picking->state++;
        break;
    case 11:
        if (++sGfx_dodrio_berry_picking->timer >= 30 && JOY_NEW(A_BUTTON))
        {
            sGfx_dodrio_berry_picking->timer = 0;
            PlaySE(SE_SELECT);
            sGfx_dodrio_berry_picking->state++;
        }
        break;
    default:
        ClearWindowTilemap(sGfx_dodrio_berry_picking->windowIds[0]);
        ClearWindowTilemap(sGfx_dodrio_berry_picking->windowIds[1]);
        RemoveWindow(sGfx_dodrio_berry_picking->windowIds[0]);
        RemoveWindow(sGfx_dodrio_berry_picking->windowIds[1]);
        FillBgTilemapBufferRect_Palette0(BG_INTERFACE_dodrio_berry_picking, 0, 0, 0, DISPLAY_TILE_WIDTH, DISPLAY_TILE_HEIGHT);
        CopyBgTilemapBufferToVram(BG_INTERFACE_dodrio_berry_picking);
        sGfx_dodrio_berry_picking->finished = TRUE;
        break;
    }
}

static void Msg_WantToPlayAgain_dodrio_berry_picking(void)
{
    u8 y;

    switch (sGfx_dodrio_berry_picking->state)
    {
    case 0:
        // Create windows
        sGfx_dodrio_berry_picking->windowIds[WIN_PLAY_AGAIN_dodrio_berry_picking] = AddWindow(&sWindowTemplates_PlayAgain_dodrio_berry_picking[WIN_PLAY_AGAIN_dodrio_berry_picking]);
        sGfx_dodrio_berry_picking->windowIds[WIN_YES_NO_dodrio_berry_picking] = AddWindow(&sWindowTemplates_PlayAgain_dodrio_berry_picking[WIN_YES_NO_dodrio_berry_picking]);
        ClearWindowTilemap(sGfx_dodrio_berry_picking->windowIds[WIN_PLAY_AGAIN_dodrio_berry_picking]);
        ClearWindowTilemap(sGfx_dodrio_berry_picking->windowIds[WIN_YES_NO_dodrio_berry_picking]);
        DrawMessageWindow_dodrio_berry_picking(&sWindowTemplates_PlayAgain_dodrio_berry_picking[WIN_PLAY_AGAIN_dodrio_berry_picking]);
        DrawYesNoMessageWindow_dodrio_berry_picking(&sWindowTemplates_PlayAgain_dodrio_berry_picking[WIN_YES_NO_dodrio_berry_picking]);
        sGfx_dodrio_berry_picking->state++;
        sGfx_dodrio_berry_picking->cursorSelection = PLAY_AGAIN_NONE_dodrio_berry_picking;
        sGfx_dodrio_berry_picking->playAgainState = PLAY_AGAIN_NONE_dodrio_berry_picking;
        break;
    case 1:
        // Print text
        FillWindowPixelBuffer(sGfx_dodrio_berry_picking->windowIds[WIN_PLAY_AGAIN_dodrio_berry_picking], PIXEL_FILL(1));
        FillWindowPixelBuffer(sGfx_dodrio_berry_picking->windowIds[WIN_YES_NO_dodrio_berry_picking], PIXEL_FILL(1));
        AddTextPrinterParameterized(sGfx_dodrio_berry_picking->windowIds[WIN_PLAY_AGAIN_dodrio_berry_picking], FONT_NORMAL, gText_WantToPlayAgain, 0, 5, TEXT_SKIP_DRAW, NULL);
        AddTextPrinterParameterized(sGfx_dodrio_berry_picking->windowIds[WIN_YES_NO_dodrio_berry_picking], FONT_NORMAL, gText_Yes, 8, 1, TEXT_SKIP_DRAW, NULL);
        AddTextPrinterParameterized(sGfx_dodrio_berry_picking->windowIds[WIN_YES_NO_dodrio_berry_picking], FONT_NORMAL, gText_No, 8, 17, TEXT_SKIP_DRAW, NULL);
        AddTextPrinterParameterized(sGfx_dodrio_berry_picking->windowIds[WIN_YES_NO_dodrio_berry_picking], FONT_NORMAL, gText_SelectorArrow2, 0, 1, TEXT_SKIP_DRAW, NULL);
        CopyWindowToVram(sGfx_dodrio_berry_picking->windowIds[WIN_PLAY_AGAIN_dodrio_berry_picking], COPYWIN_GFX);
        CopyWindowToVram(sGfx_dodrio_berry_picking->windowIds[WIN_YES_NO_dodrio_berry_picking], COPYWIN_GFX);
        sGfx_dodrio_berry_picking->state++;
        break;
    case 2:
        // Draw windows
        if (!IsDma3ManagerBusyWithBgCopy())
        {
            PutWindowTilemap(sGfx_dodrio_berry_picking->windowIds[WIN_PLAY_AGAIN_dodrio_berry_picking]);
            PutWindowTilemap(sGfx_dodrio_berry_picking->windowIds[WIN_YES_NO_dodrio_berry_picking]);
        }
        CopyBgTilemapBufferToVram(BG_INTERFACE_dodrio_berry_picking);
        sGfx_dodrio_berry_picking->state++;
        break;
    case 3:
        // Handle input
        y = sGfx_dodrio_berry_picking->cursorSelection;
        if (y == PLAY_AGAIN_NONE_dodrio_berry_picking)
            y = PLAY_AGAIN_YES_dodrio_berry_picking;
        FillWindowPixelBuffer(sGfx_dodrio_berry_picking->windowIds[WIN_YES_NO_dodrio_berry_picking], PIXEL_FILL(1));
        AddTextPrinterParameterized(sGfx_dodrio_berry_picking->windowIds[WIN_YES_NO_dodrio_berry_picking], FONT_NORMAL, gText_Yes, 8, 1, TEXT_SKIP_DRAW, NULL);
        AddTextPrinterParameterized(sGfx_dodrio_berry_picking->windowIds[WIN_YES_NO_dodrio_berry_picking], FONT_NORMAL, gText_No, 8, 17, TEXT_SKIP_DRAW, NULL);
        AddTextPrinterParameterized(sGfx_dodrio_berry_picking->windowIds[WIN_YES_NO_dodrio_berry_picking], FONT_NORMAL, gText_SelectorArrow2, 0, ((y - 1) * 16) + 1, TEXT_SKIP_DRAW, NULL);
        CopyWindowToVram(sGfx_dodrio_berry_picking->windowIds[WIN_YES_NO_dodrio_berry_picking], COPYWIN_FULL);

        // Increment state only if A or B button have been pressed.
        if (JOY_NEW(A_BUTTON))
        {
            PlaySE(SE_SELECT);
            if (sGfx_dodrio_berry_picking->cursorSelection == PLAY_AGAIN_NONE_dodrio_berry_picking)
                sGfx_dodrio_berry_picking->cursorSelection = PLAY_AGAIN_YES_dodrio_berry_picking;
            sGfx_dodrio_berry_picking->state++;
        }
        else if (JOY_NEW(DPAD_UP | DPAD_DOWN))
        {
            PlaySE(SE_SELECT);
            switch (sGfx_dodrio_berry_picking->cursorSelection)
            {
            case PLAY_AGAIN_NONE_dodrio_berry_picking:
                sGfx_dodrio_berry_picking->cursorSelection = PLAY_AGAIN_NO_dodrio_berry_picking;
                break;
            case PLAY_AGAIN_YES_dodrio_berry_picking:
                sGfx_dodrio_berry_picking->cursorSelection = PLAY_AGAIN_NO_dodrio_berry_picking;
                break;
            case PLAY_AGAIN_NO_dodrio_berry_picking:
                sGfx_dodrio_berry_picking->cursorSelection = PLAY_AGAIN_YES_dodrio_berry_picking;
                break;
            }
        }
        else if (JOY_NEW(B_BUTTON))
        {
            PlaySE(SE_SELECT);
            sGfx_dodrio_berry_picking->cursorSelection = PLAY_AGAIN_NO_dodrio_berry_picking;
            sGfx_dodrio_berry_picking->state++;
        }
        break;
    default:
        sGfx_dodrio_berry_picking->playAgainState = sGfx_dodrio_berry_picking->cursorSelection;
        ClearWindowTilemap(sGfx_dodrio_berry_picking->windowIds[WIN_PLAY_AGAIN_dodrio_berry_picking]);
        ClearWindowTilemap(sGfx_dodrio_berry_picking->windowIds[WIN_YES_NO_dodrio_berry_picking]);
        RemoveWindow(sGfx_dodrio_berry_picking->windowIds[WIN_PLAY_AGAIN_dodrio_berry_picking]);
        RemoveWindow(sGfx_dodrio_berry_picking->windowIds[WIN_YES_NO_dodrio_berry_picking]);
        FillBgTilemapBufferRect_Palette0(BG_INTERFACE_dodrio_berry_picking, 0, 0, 0, DISPLAY_TILE_WIDTH, DISPLAY_TILE_HEIGHT);
        CopyBgTilemapBufferToVram(BG_INTERFACE_dodrio_berry_picking);
        sGfx_dodrio_berry_picking->finished = TRUE;
        break;
    }
}

