// In addition to the task defines below, these two elements
// have their indexes used explicitly because they are 4-byte
// pointers, and occupy the next data element as well.
// SetWordTaskArg/GetWordTaskArg use these defines to
// read the pointer from the two elements
#define TASKIDX_WORDS_easy_chat         2
#define TASKIDX_EXIT_CALLBACK_easy_chat 4

#define tState_easy_chat        data[0]
#define tType_easy_chat         data[1]
#define tWords_easy_chat        data[TASKIDX_WORDS_easy_chat] // Occupies 2 and 3
#define tExitCallback_easy_chat data[TASKIDX_EXIT_CALLBACK_easy_chat] // Occupies 4 and 5
#define tFuncId_easy_chat       data[6]
#define tPersonType_easy_chat   data[7]

void DoEasyChatScreen(u8 type, u16 *words, MainCallback exitCallback, u8 displayedPersonType)
{
    u8 taskId;

    ResetTasks();
    taskId = CreateTask(Task_InitEasyChatScreen_easy_chat, 0);
    gTasks[taskId].tType_easy_chat = type;
    gTasks[taskId].tPersonType_easy_chat = displayedPersonType;
    SetWordTaskArg(taskId, TASKIDX_WORDS_easy_chat, (u32)words);
    SetWordTaskArg(taskId, TASKIDX_EXIT_CALLBACK_easy_chat, (u32)exitCallback);
    SetMainCallback2(CB2_EasyChatScreen_easy_chat);
}

static void CB2_EasyChatScreen_easy_chat(void)
{
    RunTasks();
    AnimateSprites();
    BuildOamBuffer();
    UpdatePaletteFade();
}

static void VBlankCB_EasyChatScreen_easy_chat(void)
{
    TransferPlttBuffer();
    LoadOam();
    ProcessSpriteCopyRequests();
}

static void StartEasyChatScreen_easy_chat(u8 taskId, TaskFunc taskFunc)
{
    gTasks[taskId].func = taskFunc;
    gTasks[taskId].tState_easy_chat = MAINSTATE_FADE_IN_easy_chat;
}

static void Task_InitEasyChatScreen_easy_chat(u8 taskId)
{
    if (!IsOverworldLinkActive())
    {
        while (InitEasyChatScreen_easy_chat(taskId));
    }
    else
    {
        if (InitEasyChatScreen_easy_chat(taskId) == TRUE)
            return;
    }
    StartEasyChatScreen_easy_chat(taskId, Task_EasyChatScreen_easy_chat);
}

// After loading, this is the 'main' Easy Chat task
static void Task_EasyChatScreen_easy_chat(u8 taskId)
{
    u16 funcId;
    s16 *data;

    data = gTasks[taskId].data;
    switch (tState_easy_chat)
    {
    case MAINSTATE_FADE_IN_easy_chat:
        SetVBlankCallback(VBlankCB_EasyChatScreen_easy_chat);
        BlendPalettes(PALETTES_ALL, 16, 0);
        BeginNormalPaletteFade(PALETTES_ALL, -1, 16, 0, RGB_BLACK);
        tState_easy_chat = MAINSTATE_WAIT_FADE_IN_easy_chat;
        break;
    case MAINSTATE_HANDLE_INPUT_easy_chat:
        funcId = HandleEasyChatInput_easy_chat();
        if (IsFuncIdForQuizLadyScreen_easy_chat(funcId))
        {
            // Fade to Quiz Lady screen
            BeginNormalPaletteFade(PALETTES_ALL, -2, 0, 16, RGB_BLACK);
            tState_easy_chat = MAINSTATE_TO_QUIZ_LADY_easy_chat;
            tFuncId_easy_chat = funcId;
        }
        else if (funcId == ECFUNC_EXIT_easy_chat)
        {
            // Fade and exit Easy Chat
            BeginNormalPaletteFade(PALETTES_ALL, -1, 0, 16, RGB_BLACK);
            tState_easy_chat = MAINSTATE_EXIT_easy_chat;
        }
        else if (funcId != ECFUNC_NONE_easy_chat)
        {
            PlaySE(SE_SELECT);
            StartEasyChatFunction_easy_chat(funcId);
            tState_easy_chat++; // MAINSTATE_RUN_FUNC_easy_chat
        }
        break;
    case MAINSTATE_RUN_FUNC_easy_chat:
        if (!RunEasyChatFunction_easy_chat())
            tState_easy_chat = MAINSTATE_HANDLE_INPUT_easy_chat;
        break;
    case MAINSTATE_TO_QUIZ_LADY_easy_chat:
        if (!gPaletteFade.active)
            EnterQuizLadyScreen_easy_chat(tFuncId_easy_chat);
        break;
    case MAINSTATE_EXIT_easy_chat:
        if (!gPaletteFade.active)
            ExitEasyChatScreen_easy_chat((MainCallback)GetWordTaskArg(taskId, TASKIDX_EXIT_CALLBACK_easy_chat));
        break;
    case MAINSTATE_WAIT_FADE_IN_easy_chat:
        if (!gPaletteFade.active)
            tState_easy_chat = MAINSTATE_HANDLE_INPUT_easy_chat;
        break;
    }
}

// Returns TRUE if still initializing, FALSE when finished
// If an allocation fails it will switch to the exit callback
static bool8 InitEasyChatScreen_easy_chat(u8 taskId)
{
    s16 *data;

    data = gTasks[taskId].data;
    switch (tState_easy_chat)
    {
    case 0:
        SetVBlankCallback(NULL);
        ResetSpriteData();
        FreeAllSpritePalettes();
        ResetPaletteFade();
        break;
    case 1:
        if (!InitEasyChatScreenWordData_easy_chat())
        {
            // Alloc failed, exit
            ExitEasyChatScreen_easy_chat((MainCallback)GetWordTaskArg(taskId, TASKIDX_EXIT_CALLBACK_easy_chat));
        }
        break;
    case 2:
        if (!InitEasyChatScreenStruct_easy_chat(tType_easy_chat, (u16 *)GetWordTaskArg(taskId, TASKIDX_WORDS_easy_chat), tPersonType_easy_chat))
        {
            // Alloc failed, exit
            ExitEasyChatScreen_easy_chat((MainCallback)GetWordTaskArg(taskId, TASKIDX_EXIT_CALLBACK_easy_chat));
        }
        break;
    case 3:
        if (!InitEasyChatScreenControl_easy_chat())
        {
            // Alloc failed, exit
            ExitEasyChatScreen_easy_chat((MainCallback)GetWordTaskArg(taskId, TASKIDX_EXIT_CALLBACK_easy_chat));
        }
        break;
    case 4:
        if (LoadEasyChatScreen_easy_chat())
        {
            return TRUE;
        }
        break;
    default:
        return FALSE;
    }
    tState_easy_chat++;
    return TRUE;
}

static void ExitEasyChatScreen_easy_chat(MainCallback callback)
{
    FreeEasyChatScreenControl_easy_chat();
    FreeEasyChatScreenStruct_easy_chat();
    FreeEasyChatScreenWordData_easy_chat();
    FreeAllWindowBuffers();
    SetMainCallback2(callback);
}

void ShowEasyChatScreen(void)
{
    int i;
    u16 *words;
    struct MauvilleManBard *bard;
    u8 displayedPersonType = EASY_CHAT_PERSON_DISPLAY_NONE;
    switch (gSpecialVar_0x8004)
    {
    case EASY_CHAT_TYPE_PROFILE:
        words = gSaveBlock1Ptr->easyChatProfile;
        break;
    case EASY_CHAT_TYPE_BATTLE_START:
        words = gSaveBlock1Ptr->easyChatBattleStart;
        break;
    case EASY_CHAT_TYPE_BATTLE_WON:
        words = gSaveBlock1Ptr->easyChatBattleWon;
        break;
    case EASY_CHAT_TYPE_BATTLE_LOST:
        words = gSaveBlock1Ptr->easyChatBattleLost;
        break;
    case EASY_CHAT_TYPE_MAIL:
        words = gSaveBlock1Ptr->mail[gSpecialVar_0x8005].words;
        break;
    case EASY_CHAT_TYPE_BARD_SONG:
        bard = &gSaveBlock1Ptr->oldMan.bard;
        for (i = 0; i < BARD_SONG_LENGTH; i ++)
            bard->temporaryLyrics[i] = bard->songLyrics[i];

        words = bard->temporaryLyrics;
        break;
    case EASY_CHAT_TYPE_INTERVIEW:
        words = gSaveBlock1Ptr->tvShows[gSpecialVar_0x8005].bravoTrainer.words;
        displayedPersonType = gSpecialVar_0x8006;
        break;
    case EASY_CHAT_TYPE_FAN_CLUB:
        words = &gSaveBlock1Ptr->tvShows[gSpecialVar_0x8005].fanclubOpinions.words[gSpecialVar_0x8006];
        displayedPersonType = EASY_CHAT_PERSON_REPORTER_FEMALE;
        break;
    case EASY_CHAT_TYPE_DUMMY_SHOW:
        words = gSaveBlock1Ptr->tvShows[gSpecialVar_0x8005].dummy.words;
        displayedPersonType = EASY_CHAT_PERSON_REPORTER_MALE;
        break;
    case EASY_CHAT_TYPE_TRENDY_PHRASE:
        words = (u16 *)gStringVar3;
        words[0] = gSaveBlock1Ptr->dewfordTrends[0].words[0];
        words[1] = gSaveBlock1Ptr->dewfordTrends[0].words[1];
        break;
    case EASY_CHAT_TYPE_GABBY_AND_TY:
        words = gSaveBlock1Ptr->gabbyAndTyData.quote;
        *words = EC_EMPTY_WORD;
        displayedPersonType = EASY_CHAT_PERSON_REPORTER_FEMALE;
        break;
    case EASY_CHAT_TYPE_CONTEST_INTERVIEW:
        words = &gSaveBlock1Ptr->tvShows[gSpecialVar_0x8005].bravoTrainer.words[gSpecialVar_0x8006];
        displayedPersonType = EASY_CHAT_PERSON_REPORTER_MALE;
        break;
    case EASY_CHAT_TYPE_BATTLE_TOWER_INTERVIEW:
        words = gSaveBlock1Ptr->tvShows[gSpecialVar_0x8005].bravoTrainerTower.words;
        displayedPersonType = EASY_CHAT_PERSON_REPORTER_FEMALE;
        break;
    case EASY_CHAT_TYPE_GOOD_SAYING:
        words = (u16 *)gStringVar3;
        InitializeEasyChatWordArray(words, 2);
        break;
    case EASY_CHAT_TYPE_FAN_QUESTION:
        words = gSaveBlock1Ptr->tvShows[gSpecialVar_0x8005].fanClubSpecial.words;
        words[0] = EC_EMPTY_WORD;
        displayedPersonType = EASY_CHAT_PERSON_BOY;
        break;
    case EASY_CHAT_TYPE_QUIZ_ANSWER:
        words = &gSaveBlock1Ptr->lilycoveLady.quiz.playerAnswer;
        break;
    case EASY_CHAT_TYPE_QUIZ_QUESTION:
        return;
    case EASY_CHAT_TYPE_QUIZ_SET_QUESTION:
        words = gSaveBlock1Ptr->lilycoveLady.quiz.question;
        break;
    case EASY_CHAT_TYPE_QUIZ_SET_ANSWER:
        words = &gSaveBlock1Ptr->lilycoveLady.quiz.correctAnswer;
        break;
    case EASY_CHAT_TYPE_APPRENTICE:
        words = gSaveBlock2Ptr->apprentices[0].speechWon;
        break;
    case EASY_CHAT_TYPE_QUESTIONNAIRE:
        words = GetQuestionnaireWordsPtr();
        break;
    default:
        return;
    }

    CleanupOverworldWindowsAndTilemaps();
    DoEasyChatScreen(gSpecialVar_0x8004, words, CB2_ReturnToFieldContinueScript, displayedPersonType);
}

