static bool8 InitEasyChatScreenStruct_easy_chat(u8 type, u16 *words, u8 displayedPersonType)
{
    u8 templateId;
    int i;

    sEasyChatScreen_easy_chat = Alloc(sizeof(*sEasyChatScreen_easy_chat));
    if (sEasyChatScreen_easy_chat == NULL)
        return FALSE;

    sEasyChatScreen_easy_chat->type = type;
    sEasyChatScreen_easy_chat->savedPhrase = words;
    sEasyChatScreen_easy_chat->mainCursorColumn = 0;
    sEasyChatScreen_easy_chat->mainCursorRow = 0;
    sEasyChatScreen_easy_chat->inAlphabetMode = FALSE;
    sEasyChatScreen_easy_chat->displayedPersonType = displayedPersonType;
    sEasyChatScreen_easy_chat->unused = 0;
    templateId = GetEachChatScreenTemplateId_easy_chat(type);
    if (type == EASY_CHAT_TYPE_QUIZ_QUESTION)
    {
        GetQuizTitle_easy_chat(sEasyChatScreen_easy_chat->quizTitle);
        sEasyChatScreen_easy_chat->titleText = sEasyChatScreen_easy_chat->quizTitle;
        sEasyChatScreen_easy_chat->inputState = INPUTSTATE_QUIZ_QUESTION_easy_chat;
    }
    else
    {
        sEasyChatScreen_easy_chat->inputState = INPUTSTATE_PHRASE_easy_chat;
        sEasyChatScreen_easy_chat->titleText = sEasyChatScreenTemplates_easy_chat[templateId].titleText;
    }

    sEasyChatScreen_easy_chat->numColumns = sEasyChatScreenTemplates_easy_chat[templateId].numColumns;
    sEasyChatScreen_easy_chat->numRows = sEasyChatScreenTemplates_easy_chat[templateId].numRows;
    sEasyChatScreen_easy_chat->maxWords = sEasyChatScreen_easy_chat->numColumns * sEasyChatScreen_easy_chat->numRows;
    sEasyChatScreen_easy_chat->templateId = templateId;
    if (sEasyChatScreen_easy_chat->maxWords > ARRAY_COUNT(sEasyChatScreen_easy_chat->currentPhrase))
        sEasyChatScreen_easy_chat->maxWords = ARRAY_COUNT(sEasyChatScreen_easy_chat->currentPhrase);

    if (words != NULL)
    {
        // Phrase starts with words filled in, copy to current phrase
        CpuCopy16(words, sEasyChatScreen_easy_chat->currentPhrase, sEasyChatScreen_easy_chat->maxWords * sizeof(u16));
    }
    else
    {
        // Phrase starts with no words, fill with empty words and save
        for (i = 0; i < sEasyChatScreen_easy_chat->maxWords; i ++)
            sEasyChatScreen_easy_chat->currentPhrase[i] = EC_EMPTY_WORD;

        sEasyChatScreen_easy_chat->savedPhrase = sEasyChatScreen_easy_chat->currentPhrase;
    }

    sEasyChatScreen_easy_chat->keyboardLastRow = (GetNumUnlockedEasyChatGroups_easy_chat() - 1) / 2 + 1;
    return TRUE;
}

static void FreeEasyChatScreenStruct_easy_chat(void)
{
    TRY_FREE_AND_SET_NULL(sEasyChatScreen_easy_chat);
}

// Returns the function ID of the action to take as a result of player's input.
// If no action is needed, returns ECFUNC_NONE_easy_chat
static u16 HandleEasyChatInput_easy_chat(void)
{
    switch (sEasyChatScreen_easy_chat->inputState)
    {
    case INPUTSTATE_PHRASE_easy_chat:
        return HandleEasyChatInput_Phrase_easy_chat();
    case INPUTSTATE_MAIN_SCREEN_BUTTONS_easy_chat:
        return HandleEasyChatInput_MainScreenButtons_easy_chat();
    case INPUTSTATE_KEYBOARD_easy_chat:
        return HandleEasyChatInput_Keyboard_easy_chat();
    case INPUTSTATE_WORD_SELECT_easy_chat:
        return HandleEasyChatInput_WordSelect_easy_chat();
    case INPUTSTATE_EXIT_PROMPT_easy_chat:
        return HandleEasyChatInput_ExitPrompt_easy_chat();
    case INPUTSTATE_DELETE_ALL_YES_NO_easy_chat:
        return HandleEasyChatInput_DeleteAllYesNo_easy_chat();
    case INPUTSTATE_CONFIRM_WORDS_YES_NO_easy_chat:
        return HandleEasyChatInput_ConfirmWordsYesNo_easy_chat();
    case INPUTSTATE_QUIZ_QUESTION_easy_chat:
        return HandleEasyChatInput_QuizQuestion_easy_chat();
    case INPUTSTATE_WAIT_FOR_MSG_easy_chat:
        return HandleEasyChatInput_WaitForMsg_easy_chat();
    case INPUTSTATE_START_CONFIRM_LYRICS_easy_chat:
        return HandleEasyChatInput_StartConfirmLyrics_easy_chat();
    case INPUTSTATE_CONFIRM_LYRICS_YES_NO_easy_chat:
        return HandleEasyChatInput_ConfirmLyricsYesNo_easy_chat();
    }
    return ECFUNC_NONE_easy_chat;
}

static bool32 IsCurrentFrame2x5_easy_chat(void)
{
    switch (GetEasyChatScreenFrameId_easy_chat())
    {
    case FRAMEID_MAIL_easy_chat:
    case FRAMEID_QUIZ_QUESTION_easy_chat:
    case FRAMEID_QUIZ_SET_QUESTION_easy_chat:
        return TRUE;
    }
    return FALSE;
}

// Handles main screen input while cursor is on a word in the phrase
static u16 HandleEasyChatInput_Phrase_easy_chat(void)
{
    do
    {
        if (JOY_NEW(A_BUTTON))
        {
            ClearUnusedField_easy_chat();
            sEasyChatScreen_easy_chat->inputState = INPUTSTATE_KEYBOARD_easy_chat;
            sEasyChatScreen_easy_chat->keyboardColumn = 0;
            sEasyChatScreen_easy_chat->keyboardRow = 0;
            sEasyChatScreen_easy_chat->keyboardScrollOffset = 0;
            return ECFUNC_OPEN_KEYBOARD_easy_chat;
        }
        else if (JOY_NEW(B_BUTTON))
        {
            return StartConfirmExitPrompt_easy_chat();
        }
        else if (JOY_NEW(START_BUTTON))
        {
            return TryConfirmWords_easy_chat();
        }
        else if (JOY_NEW(DPAD_UP))
        {
            sEasyChatScreen_easy_chat->mainCursorRow--;
            break;
        }
        else if (JOY_NEW(DPAD_LEFT))
        {
            sEasyChatScreen_easy_chat->mainCursorColumn--;
            break;
        }
        else if (JOY_NEW(DPAD_DOWN))
        {
            sEasyChatScreen_easy_chat->mainCursorRow++;
            break;
        }
        else if (JOY_NEW(DPAD_RIGHT))
        {
            sEasyChatScreen_easy_chat->mainCursorColumn++;
            break;
        }

        return ECFUNC_NONE_easy_chat;
    } while (0);

    // Handle D-Pad input

    // Wrap row
    if (sEasyChatScreen_easy_chat->mainCursorRow < 0)
        sEasyChatScreen_easy_chat->mainCursorRow = sEasyChatScreenTemplates_easy_chat[sEasyChatScreen_easy_chat->templateId].numRows;
    if (sEasyChatScreen_easy_chat->mainCursorRow > sEasyChatScreenTemplates_easy_chat[sEasyChatScreen_easy_chat->templateId].numRows)
        sEasyChatScreen_easy_chat->mainCursorRow = 0;

    if (sEasyChatScreen_easy_chat->mainCursorRow == sEasyChatScreenTemplates_easy_chat[sEasyChatScreen_easy_chat->templateId].numRows)
    {
        // Moved onto bottom row (buttons)
        if (sEasyChatScreen_easy_chat->mainCursorColumn > 2)
            sEasyChatScreen_easy_chat->mainCursorColumn = 2;

        sEasyChatScreen_easy_chat->inputState = INPUTSTATE_MAIN_SCREEN_BUTTONS_easy_chat;
        return ECFUNC_UPDATE_MAIN_CURSOR_ON_BUTTONS_easy_chat;
    }

    // Wrap column
    if (sEasyChatScreen_easy_chat->mainCursorColumn < 0)
        sEasyChatScreen_easy_chat->mainCursorColumn = sEasyChatScreenTemplates_easy_chat[sEasyChatScreen_easy_chat->templateId].numColumns - 1;
    if (sEasyChatScreen_easy_chat->mainCursorColumn >= sEasyChatScreenTemplates_easy_chat[sEasyChatScreen_easy_chat->templateId].numColumns)
        sEasyChatScreen_easy_chat->mainCursorColumn = 0;

    // All 2x5 phrases are only 9 words long, exclude the bottom right (10th) position
    if (IsCurrentFrame2x5_easy_chat() && sEasyChatScreen_easy_chat->mainCursorColumn == 1 && sEasyChatScreen_easy_chat->mainCursorRow == 4)
        sEasyChatScreen_easy_chat->mainCursorColumn = 0;

    return ECFUNC_UPDATE_MAIN_CURSOR_easy_chat;
}

// Handles main screen input while cursor is below the phrase on one of the buttons, e.g. Del. All or Cancel
static u16 HandleEasyChatInput_MainScreenButtons_easy_chat(void)
{
    do
    {
        if (JOY_NEW(A_BUTTON))
        {
            switch (sEasyChatScreen_easy_chat->mainCursorColumn)
            {
            case 0: // Del. All button
                return DoDeleteAllButton_easy_chat();
            case 1: // Cancel button
                return StartConfirmExitPrompt_easy_chat();
            case 2: // OK button
                return TryConfirmWords_easy_chat();
            case 3: // Quiz/Answer button
                return DoQuizButton_easy_chat();
            }
        }

        if (JOY_NEW(B_BUTTON))
        {
            return StartConfirmExitPrompt_easy_chat();
        }
        else if (JOY_NEW(START_BUTTON))
        {
            return TryConfirmWords_easy_chat();
        }
        else if (JOY_NEW(DPAD_UP))
        {
            sEasyChatScreen_easy_chat->mainCursorRow--;
            break;
        }
        else if (JOY_NEW(DPAD_LEFT))
        {
            sEasyChatScreen_easy_chat->mainCursorColumn--;
            break;
        }
        else if (JOY_NEW(DPAD_DOWN))
        {
            sEasyChatScreen_easy_chat->mainCursorRow = 0;
            break;
        }
        else if (JOY_NEW(DPAD_RIGHT))
        {
            sEasyChatScreen_easy_chat->mainCursorColumn++;
            break;
        }

        return ECFUNC_NONE_easy_chat;
    } while (0);

    if (sEasyChatScreen_easy_chat->mainCursorRow == sEasyChatScreenTemplates_easy_chat[sEasyChatScreen_easy_chat->templateId].numRows)
    {
        int numFooterColumns = FooterHasFourOptions_easy_chat() ? 4 : 3;
        if (sEasyChatScreen_easy_chat->mainCursorColumn < 0)
            sEasyChatScreen_easy_chat->mainCursorColumn = numFooterColumns - 1;

        if (sEasyChatScreen_easy_chat->mainCursorColumn >= numFooterColumns)
            sEasyChatScreen_easy_chat->mainCursorColumn = 0;

        return ECFUNC_UPDATE_MAIN_CURSOR_ON_BUTTONS_easy_chat;
    }

    if (sEasyChatScreen_easy_chat->mainCursorColumn >= sEasyChatScreenTemplates_easy_chat[sEasyChatScreen_easy_chat->templateId].numColumns)
        sEasyChatScreen_easy_chat->mainCursorColumn = sEasyChatScreenTemplates_easy_chat[sEasyChatScreen_easy_chat->templateId].numColumns - 1;

    // All 2x5 phrases are only 9 words long, exclude the bottom right (10th) position
    if (IsCurrentFrame2x5_easy_chat() && sEasyChatScreen_easy_chat->mainCursorColumn == 1 && sEasyChatScreen_easy_chat->mainCursorRow == 4)
        sEasyChatScreen_easy_chat->mainCursorColumn = 0;

    sEasyChatScreen_easy_chat->inputState = INPUTSTATE_PHRASE_easy_chat;
    return ECFUNC_UPDATE_MAIN_CURSOR_easy_chat;
}

static u16 HandleEasyChatInput_Keyboard_easy_chat(void)
{
    if (JOY_NEW(B_BUTTON))
        return ExitKeyboardToMainScreen_easy_chat();

    if (JOY_NEW(A_BUTTON))
    {
        if (sEasyChatScreen_easy_chat->keyboardColumn != -1)
            return SelectKeyboardGroup_easy_chat();

        // Cursor is in button window
        switch (sEasyChatScreen_easy_chat->keyboardRow)
        {
        case 0: // Mode button
            return StartSwitchKeyboardMode_easy_chat();
        case 1: // Delete button
            return DeleteSelectedWord_easy_chat();
        case 2: // Cancel button
            return ExitKeyboardToMainScreen_easy_chat();
        }
    }

    if (JOY_NEW(SELECT_BUTTON))
        return StartSwitchKeyboardMode_easy_chat();

    if (JOY_REPEAT(DPAD_UP))
        return MoveKeyboardCursor_easy_chat(INPUT_UP_easy_chat);

    if (JOY_REPEAT(DPAD_DOWN))
        return MoveKeyboardCursor_easy_chat(INPUT_DOWN_easy_chat);

    if (JOY_REPEAT(DPAD_LEFT))
        return MoveKeyboardCursor_easy_chat(INPUT_LEFT_easy_chat);

    if (JOY_REPEAT(DPAD_RIGHT))
        return MoveKeyboardCursor_easy_chat(INPUT_RIGHT_easy_chat);

    return ECFUNC_NONE_easy_chat;
}

// Input handling for the lower window after a word group has been selected
static u16 HandleEasyChatInput_WordSelect_easy_chat(void)
{
    if (JOY_NEW(B_BUTTON))
    {
        sEasyChatScreen_easy_chat->inputState = INPUTSTATE_KEYBOARD_easy_chat;
        return ECFUNC_RETURN_TO_KEYBOARD_easy_chat;
    }

    if (JOY_NEW(A_BUTTON))
        return SelectNewWord_easy_chat();

    if (JOY_NEW(START_BUTTON))
        return MoveWordSelectCursor_easy_chat(INPUT_START_easy_chat);

    if (JOY_NEW(SELECT_BUTTON))
        return MoveWordSelectCursor_easy_chat(INPUT_SELECT_easy_chat);

    if (JOY_REPEAT(DPAD_UP))
        return MoveWordSelectCursor_easy_chat(INPUT_UP_easy_chat);

    if (JOY_REPEAT(DPAD_DOWN))
        return MoveWordSelectCursor_easy_chat(INPUT_DOWN_easy_chat);

    if (JOY_REPEAT(DPAD_LEFT))
        return MoveWordSelectCursor_easy_chat(INPUT_LEFT_easy_chat);

    if (JOY_REPEAT(DPAD_RIGHT))
        return MoveWordSelectCursor_easy_chat(INPUT_RIGHT_easy_chat);

    return ECFUNC_NONE_easy_chat;
}

static u16 HandleEasyChatInput_ExitPrompt_easy_chat(void)
{
    switch (Menu_ProcessInputNoWrapClearOnChoose())
    {
    case MENU_B_PRESSED:
    case 1: // No (Continue)
        sEasyChatScreen_easy_chat->inputState = GetEasyChatBackupState_easy_chat();
        return ECFUNC_CLOSE_PROMPT_easy_chat;
    case 0: // Yes (Exit)
        gSpecialVar_Result = 0;
        if (sEasyChatScreen_easy_chat->type == EASY_CHAT_TYPE_QUIZ_SET_QUESTION
         || sEasyChatScreen_easy_chat->type == EASY_CHAT_TYPE_QUIZ_SET_ANSWER)
            SaveCurrentPhrase_easy_chat();

        return ECFUNC_EXIT_easy_chat;
    default:
        return ECFUNC_NONE_easy_chat;
    }
}

static u16 HandleEasyChatInput_ConfirmWordsYesNo_easy_chat(void)
{
    switch (Menu_ProcessInputNoWrapClearOnChoose())
    {
    case MENU_B_PRESSED:
    case 1: // No
        sEasyChatScreen_easy_chat->inputState = GetEasyChatBackupState_easy_chat();
        return ECFUNC_CLOSE_PROMPT_easy_chat;
    case 0: // Yes
        SetSpecialEasyChatResult_easy_chat();
        gSpecialVar_Result = GetEasyChatCompleted_easy_chat();
        SaveCurrentPhrase_easy_chat();
        return ECFUNC_EXIT_easy_chat;
    default:
        return ECFUNC_NONE_easy_chat;
    }
}

static u16 HandleEasyChatInput_DeleteAllYesNo_easy_chat(void)
{
    switch (Menu_ProcessInputNoWrapClearOnChoose())
    {
    case MENU_B_PRESSED:
    case 1: // No
        sEasyChatScreen_easy_chat->inputState = INPUTSTATE_MAIN_SCREEN_BUTTONS_easy_chat;
        return ECFUNC_CLOSE_PROMPT_easy_chat;
    case 0: // Yes
        ResetCurrentPhrase_easy_chat();
        sEasyChatScreen_easy_chat->inputState = INPUTSTATE_MAIN_SCREEN_BUTTONS_easy_chat;
        return ECFUNC_CLOSE_PROMPT_AFTER_DELETE_easy_chat;
    default:
        return ECFUNC_NONE_easy_chat;
    }
}

static u16 HandleEasyChatInput_QuizQuestion_easy_chat(void)
{
    if (JOY_NEW(A_BUTTON))
        return ECFUNC_QUIZ_ANSWER_easy_chat;

    if (JOY_NEW(B_BUTTON))
        return StartConfirmExitPrompt_easy_chat();

    return ECFUNC_NONE_easy_chat;
}

// A message has been printed. Wait for player to
// press A or B, then return to previous state
static u16 HandleEasyChatInput_WaitForMsg_easy_chat(void)
{
    if (JOY_NEW(A_BUTTON | B_BUTTON))
    {
        sEasyChatScreen_easy_chat->inputState = GetEasyChatBackupState_easy_chat();
        return ECFUNC_CLOSE_PROMPT_easy_chat;
    }

    return ECFUNC_NONE_easy_chat;
}

// Odd, could have been skipped. Just passes to HandleEasyChatInput_ConfirmLyricsYesNo_easy_chat
static u16 HandleEasyChatInput_StartConfirmLyrics_easy_chat(void)
{
    sEasyChatScreen_easy_chat->inputState = INPUTSTATE_CONFIRM_LYRICS_YES_NO_easy_chat;
    return ECFUNC_PROMPT_CONFIRM_easy_chat;
}

static u16 HandleEasyChatInput_ConfirmLyricsYesNo_easy_chat(void)
{
    switch (Menu_ProcessInputNoWrapClearOnChoose())
    {
    case MENU_B_PRESSED:
    case 1: // No
        ResetCurrentPhraseToSaved_easy_chat();
        sEasyChatScreen_easy_chat->inputStateBackup = INPUTSTATE_PHRASE_easy_chat;
        sEasyChatScreen_easy_chat->inputState = INPUTSTATE_WAIT_FOR_MSG_easy_chat;
        return ECFUNC_MSG_SONG_TOO_SHORT_easy_chat;
    case 0: // Yes
        gSpecialVar_Result = GetEasyChatCompleted_easy_chat();
        SaveCurrentPhrase_easy_chat();
        return ECFUNC_EXIT_easy_chat;
    default:
        return ECFUNC_NONE_easy_chat;
    }
}

static u16 StartConfirmExitPrompt_easy_chat(void)
{
    if (sEasyChatScreen_easy_chat->type == EASY_CHAT_TYPE_APPRENTICE
     || sEasyChatScreen_easy_chat->type == EASY_CHAT_TYPE_CONTEST_INTERVIEW)
    {
        sEasyChatScreen_easy_chat->inputStateBackup = sEasyChatScreen_easy_chat->inputState;
        sEasyChatScreen_easy_chat->inputState = INPUTSTATE_WAIT_FOR_MSG_easy_chat;
        return ECFUNC_MSG_CANT_EXIT_easy_chat;
    }
    else
    {
        sEasyChatScreen_easy_chat->inputStateBackup = sEasyChatScreen_easy_chat->inputState;
        sEasyChatScreen_easy_chat->inputState = INPUTSTATE_EXIT_PROMPT_easy_chat;
        return ECFUNC_PROMPT_EXIT_easy_chat;
    }
}

static int DoDeleteAllButton_easy_chat(void)
{
    sEasyChatScreen_easy_chat->inputStateBackup = sEasyChatScreen_easy_chat->inputState;
    if (sEasyChatScreen_easy_chat->type != EASY_CHAT_TYPE_BARD_SONG)
    {
        // Show Delete yes/no
        sEasyChatScreen_easy_chat->inputState = INPUTSTATE_DELETE_ALL_YES_NO_easy_chat;
        return ECFUNC_PROMPT_DELETE_ALL_easy_chat;
    }
    else
    {
        // Cannot delete lyrics when setting Bard's song
        sEasyChatScreen_easy_chat->inputStateBackup = sEasyChatScreen_easy_chat->inputState;
        sEasyChatScreen_easy_chat->inputState = INPUTSTATE_WAIT_FOR_MSG_easy_chat;
        return ECFUNC_MSG_CANT_DELETE_LYRICS_easy_chat;
    }
}

static u16 TryConfirmWords_easy_chat(void)
{
    sEasyChatScreen_easy_chat->inputStateBackup = sEasyChatScreen_easy_chat->inputState;
    if (sEasyChatScreen_easy_chat->type == EASY_CHAT_TYPE_QUIZ_SET_QUESTION)
    {
        if (IsQuizQuestionEmpty_easy_chat())
        {
            sEasyChatScreen_easy_chat->inputState = INPUTSTATE_WAIT_FOR_MSG_easy_chat;
            return ECFUNC_MSG_CREATE_QUIZ_easy_chat;
        }

        if (IsQuizAnswerEmpty_easy_chat())
        {
            sEasyChatScreen_easy_chat->inputState = INPUTSTATE_WAIT_FOR_MSG_easy_chat;
            return ECFUNC_MSG_SELECT_ANSWER_easy_chat;
        }

        sEasyChatScreen_easy_chat->inputState = INPUTSTATE_CONFIRM_WORDS_YES_NO_easy_chat;
        return ECFUNC_PROMPT_CONFIRM_easy_chat;
    }
    else if (sEasyChatScreen_easy_chat->type == EASY_CHAT_TYPE_QUIZ_SET_ANSWER)
    {
        if (IsQuizAnswerEmpty_easy_chat())
        {
            sEasyChatScreen_easy_chat->inputState = INPUTSTATE_WAIT_FOR_MSG_easy_chat;
            return ECFUNC_MSG_SELECT_ANSWER_easy_chat;
        }

        if (IsQuizQuestionEmpty_easy_chat())
        {
            sEasyChatScreen_easy_chat->inputState = INPUTSTATE_WAIT_FOR_MSG_easy_chat;
            return ECFUNC_MSG_CREATE_QUIZ_easy_chat;
        }

        sEasyChatScreen_easy_chat->inputState = INPUTSTATE_CONFIRM_WORDS_YES_NO_easy_chat;
        return ECFUNC_PROMPT_CONFIRM_easy_chat;
    }
    else if (sEasyChatScreen_easy_chat->type == EASY_CHAT_TYPE_TRENDY_PHRASE
          || sEasyChatScreen_easy_chat->type == EASY_CHAT_TYPE_GOOD_SAYING)
    {
        if (!IsCurrentPhraseFull_easy_chat())
        {
            sEasyChatScreen_easy_chat->inputState = INPUTSTATE_WAIT_FOR_MSG_easy_chat;
            return ECFUNC_MSG_COMBINE_TWO_WORDS_easy_chat;
        }

        sEasyChatScreen_easy_chat->inputState = INPUTSTATE_CONFIRM_WORDS_YES_NO_easy_chat;
        return ECFUNC_PROMPT_CONFIRM_easy_chat;
    }
    else if (sEasyChatScreen_easy_chat->type == EASY_CHAT_TYPE_APPRENTICE
          || sEasyChatScreen_easy_chat->type == EASY_CHAT_TYPE_CONTEST_INTERVIEW)
    {
        if (IsCurrentPhraseEmpty_easy_chat())
        {
            sEasyChatScreen_easy_chat->inputState = INPUTSTATE_WAIT_FOR_MSG_easy_chat;
            return ECFUNC_MSG_CANT_EXIT_easy_chat;
        }

        sEasyChatScreen_easy_chat->inputState = INPUTSTATE_CONFIRM_WORDS_YES_NO_easy_chat;
        return ECFUNC_PROMPT_CONFIRM_easy_chat;
    }
    else if (sEasyChatScreen_easy_chat->type == EASY_CHAT_TYPE_QUESTIONNAIRE)
    {
        sEasyChatScreen_easy_chat->inputState = INPUTSTATE_CONFIRM_WORDS_YES_NO_easy_chat;
        return ECFUNC_PROMPT_CONFIRM_easy_chat;
    }
    else
    {
        if (IsCurrentPhraseEmpty_easy_chat() == TRUE || !GetEasyChatCompleted_easy_chat())
        {
            sEasyChatScreen_easy_chat->inputState = INPUTSTATE_EXIT_PROMPT_easy_chat;
            return ECFUNC_PROMPT_EXIT_easy_chat;
        }

        sEasyChatScreen_easy_chat->inputState = INPUTSTATE_CONFIRM_WORDS_YES_NO_easy_chat;
        return ECFUNC_PROMPT_CONFIRM_easy_chat;
    }
}

static int DoQuizButton_easy_chat(void)
{
    sEasyChatScreen_easy_chat->inputStateBackup = sEasyChatScreen_easy_chat->inputState;
    switch (sEasyChatScreen_easy_chat->type)
    {
    case EASY_CHAT_TYPE_QUIZ_ANSWER:
        return ECFUNC_QUIZ_QUESTION_easy_chat;
    case EASY_CHAT_TYPE_QUIZ_SET_QUESTION:
        SaveCurrentPhrase_easy_chat();
        return ECFUNC_SET_QUIZ_ANSWER_easy_chat;
    case EASY_CHAT_TYPE_QUIZ_SET_ANSWER:
        SaveCurrentPhrase_easy_chat();
        return ECFUNC_SET_QUIZ_QUESTION_easy_chat;
    default:
        return ECFUNC_NONE_easy_chat;
    }
}

static u8 GetEasyChatBackupState_easy_chat(void)
{
    return sEasyChatScreen_easy_chat->inputStateBackup;
}

static int SelectKeyboardGroup_easy_chat(void)
{
    u16 numWords;

    if (!sEasyChatScreen_easy_chat->inAlphabetMode)
    {
        u8 groupId = GetUnlockedEasyChatGroupId_easy_chat(GetSelectedGroupIndex_easy_chat());
        SetSelectedWordGroup_easy_chat(FALSE, groupId);
    }
    else
    {
        SetSelectedWordGroup_easy_chat(TRUE, GetSelectedAlphabetGroupId_easy_chat());
    }

    numWords = GetNumWordsInSelectedGroup_easy_chat();
    if (numWords == 0)
        return ECFUNC_NONE_easy_chat;

    sEasyChatScreen_easy_chat->wordSelectLastRow = (numWords - 1) / 2;
    sEasyChatScreen_easy_chat->wordSelectScrollOffset = 0;
    sEasyChatScreen_easy_chat->wordSelectColumn = 0;
    sEasyChatScreen_easy_chat->wordSelectRow = 0;
    sEasyChatScreen_easy_chat->inputState = INPUTSTATE_WORD_SELECT_easy_chat;
    return ECFUNC_OPEN_WORD_SELECT_easy_chat;
}

static int ExitKeyboardToMainScreen_easy_chat(void)
{
    sEasyChatScreen_easy_chat->inputState = INPUTSTATE_PHRASE_easy_chat;
    return ECFUNC_CLOSE_KEYBOARD_easy_chat;
}

static int StartSwitchKeyboardMode_easy_chat(void)
{
    sEasyChatScreen_easy_chat->keyboardColumn = 0;
    sEasyChatScreen_easy_chat->keyboardRow = 0;
    sEasyChatScreen_easy_chat->keyboardScrollOffset = 0;
    if (!sEasyChatScreen_easy_chat->inAlphabetMode)
        sEasyChatScreen_easy_chat->inAlphabetMode = TRUE;
    else
        sEasyChatScreen_easy_chat->inAlphabetMode = FALSE;

    return ECFUNC_SWITCH_KEYBOARD_MODE_easy_chat;
}

static int DeleteSelectedWord_easy_chat(void)
{
    if (sEasyChatScreen_easy_chat->type == EASY_CHAT_TYPE_BARD_SONG)
    {
        PlaySE(SE_FAILURE);
        return ECFUNC_NONE_easy_chat;
    }
    else
    {
        SetSelectedWord_easy_chat(EC_EMPTY_WORD);
        return ECFUNC_REPRINT_PHRASE_easy_chat;
    }
}

static int SelectNewWord_easy_chat(void)
{
    u16 easyChatWord = GetWordFromSelectedGroup_easy_chat(GetSelectedWordIndex_easy_chat());
    if (DummyWordCheck_easy_chat(easyChatWord))
    {
        // Never reached. Would disallow selecting certain words
        PlaySE(SE_FAILURE);
        return ECFUNC_NONE_easy_chat;
    }
    else
    {
        SetSelectedWord_easy_chat(easyChatWord);
        if (sEasyChatScreen_easy_chat->type != EASY_CHAT_TYPE_BARD_SONG)
        {
            sEasyChatScreen_easy_chat->inputState = INPUTSTATE_PHRASE_easy_chat;
            return ECFUNC_CLOSE_WORD_SELECT_easy_chat;
        }
        else
        {
            sEasyChatScreen_easy_chat->inputState = INPUTSTATE_START_CONFIRM_LYRICS_easy_chat;
            return ECFUNC_PROMPT_CONFIRM_LYRICS_easy_chat;
        }
    }
}

static void SaveCurrentPhrase_easy_chat(void)
{
    int i;
    for (i = 0; i < sEasyChatScreen_easy_chat->maxWords; i++)
        sEasyChatScreen_easy_chat->savedPhrase[i] = sEasyChatScreen_easy_chat->currentPhrase[i];
}

static void ResetCurrentPhrase_easy_chat(void)
{
    int i;
    for (i = 0; i < sEasyChatScreen_easy_chat->maxWords; i++)
        sEasyChatScreen_easy_chat->currentPhrase[i] = EC_EMPTY_WORD;
}

static void ResetCurrentPhraseToSaved_easy_chat(void)
{
    int i;
    for (i = 0; i < sEasyChatScreen_easy_chat->maxWords; i++)
        sEasyChatScreen_easy_chat->currentPhrase[i] = sEasyChatScreen_easy_chat->savedPhrase[i];
}

static void SetSelectedWord_easy_chat(u16 easyChatWord)
{
    u16 index = GetWordIndexToReplace_easy_chat();
    sEasyChatScreen_easy_chat->currentPhrase[index] = easyChatWord;
}

// Compare current phrase to the original saved phrase
static bool8 DidPhraseChange_easy_chat(void)
{
    u16 i;
    for (i = 0; i < sEasyChatScreen_easy_chat->maxWords; i++)
    {
        if (sEasyChatScreen_easy_chat->currentPhrase[i] != sEasyChatScreen_easy_chat->savedPhrase[i])
            return TRUE;
    }

    return FALSE;
}

// 'Completed' if the phrase was changed, or in the case of making a quiz, the question and answer were filled out
static bool32 GetEasyChatCompleted_easy_chat(void)
{
    if (sEasyChatScreen_easy_chat->type == EASY_CHAT_TYPE_QUIZ_SET_QUESTION
     || sEasyChatScreen_easy_chat->type == EASY_CHAT_TYPE_QUIZ_SET_ANSWER)
    {
        if (IsQuizQuestionEmpty_easy_chat())
            return FALSE;

        if (IsQuizAnswerEmpty_easy_chat())
            return FALSE;

        return TRUE;
    }
    else
    {
        return DidPhraseChange_easy_chat();
    }
}

static u16 MoveKeyboardCursor_easy_chat(int input)
{
    if (sEasyChatScreen_easy_chat->keyboardColumn != -1)
    {
        if (!sEasyChatScreen_easy_chat->inAlphabetMode)
            return MoveKeyboardCursor_GroupNames_easy_chat(input);
        else
            return MoveKeyboardCursor_Alphabet_easy_chat(input);
    }
    else
    {
        return MoveKeyboardCursor_ButtonWindow_easy_chat(input);
    }
}

static int MoveKeyboardCursor_GroupNames_easy_chat(u32 input)
{
    switch (input)
    {
    case INPUT_UP_easy_chat:
        if (sEasyChatScreen_easy_chat->keyboardRow != -sEasyChatScreen_easy_chat->keyboardScrollOffset)
        {
            if (sEasyChatScreen_easy_chat->keyboardRow)
            {
                sEasyChatScreen_easy_chat->keyboardRow--;
                return ECFUNC_UPDATE_KEYBOARD_CURSOR_easy_chat;
            }
            else
            {
                sEasyChatScreen_easy_chat->keyboardScrollOffset--;
                return ECFUNC_GROUP_NAMES_SCROLL_UP_easy_chat;
            }
        }
        break;
    case INPUT_DOWN_easy_chat:
        if (sEasyChatScreen_easy_chat->keyboardRow + sEasyChatScreen_easy_chat->keyboardScrollOffset < sEasyChatScreen_easy_chat->keyboardLastRow - 1)
        {
            int funcId;
            if (sEasyChatScreen_easy_chat->keyboardRow < NUM_GROUP_NAME_ROWS_easy_chat - 1)
            {
                sEasyChatScreen_easy_chat->keyboardRow++;
                funcId = ECFUNC_UPDATE_KEYBOARD_CURSOR_easy_chat;
            }
            else
            {
                sEasyChatScreen_easy_chat->keyboardScrollOffset++;
                funcId = ECFUNC_GROUP_NAMES_SCROLL_DOWN_easy_chat;
            }

            ReduceToValidKeyboardColumn_easy_chat();
            return funcId;
        }
        break;
    case INPUT_LEFT_easy_chat:
        if (sEasyChatScreen_easy_chat->keyboardColumn)
            sEasyChatScreen_easy_chat->keyboardColumn--;
        else
            SetKeyboardCursorInButtonWindow_easy_chat();

        return ECFUNC_UPDATE_KEYBOARD_CURSOR_easy_chat;
    case INPUT_RIGHT_easy_chat:
        if (sEasyChatScreen_easy_chat->keyboardColumn < 1)
        {
            sEasyChatScreen_easy_chat->keyboardColumn++;
            if (IsSelectedKeyboardIndexInvalid_easy_chat())
                SetKeyboardCursorInButtonWindow_easy_chat();
        }
        else
        {
            SetKeyboardCursorInButtonWindow_easy_chat();
        }
        return ECFUNC_UPDATE_KEYBOARD_CURSOR_easy_chat;
    }

    return ECFUNC_NONE_easy_chat;
}

static int MoveKeyboardCursor_Alphabet_easy_chat(u32 input)
{
    switch (input)
    {
    case INPUT_UP_easy_chat:
        if (sEasyChatScreen_easy_chat->keyboardRow > 0)
            sEasyChatScreen_easy_chat->keyboardRow--;
        else
            sEasyChatScreen_easy_chat->keyboardRow = NUM_ALPHABET_ROWS_easy_chat - 1;

        ReduceToValidKeyboardColumn_easy_chat();
        return ECFUNC_UPDATE_KEYBOARD_CURSOR_easy_chat;
    case INPUT_DOWN_easy_chat:
        if (sEasyChatScreen_easy_chat->keyboardRow < NUM_ALPHABET_ROWS_easy_chat - 1)
            sEasyChatScreen_easy_chat->keyboardRow++;
        else
            sEasyChatScreen_easy_chat->keyboardRow = 0;

        ReduceToValidKeyboardColumn_easy_chat();
        return ECFUNC_UPDATE_KEYBOARD_CURSOR_easy_chat;
    case INPUT_RIGHT_easy_chat:
        sEasyChatScreen_easy_chat->keyboardColumn++;
        if (IsSelectedKeyboardIndexInvalid_easy_chat())
            SetKeyboardCursorInButtonWindow_easy_chat();

        return ECFUNC_UPDATE_KEYBOARD_CURSOR_easy_chat;
    case INPUT_LEFT_easy_chat:
        sEasyChatScreen_easy_chat->keyboardColumn--;
        if (sEasyChatScreen_easy_chat->keyboardColumn < 0)
            SetKeyboardCursorInButtonWindow_easy_chat();

        return ECFUNC_UPDATE_KEYBOARD_CURSOR_easy_chat;
    }

    return ECFUNC_NONE_easy_chat;
}

static int MoveKeyboardCursor_ButtonWindow_easy_chat(u32 input)
{
    switch (input)
    {
    case INPUT_UP_easy_chat:
        if (sEasyChatScreen_easy_chat->keyboardRow)
            sEasyChatScreen_easy_chat->keyboardRow--;
        else
            sEasyChatScreen_easy_chat->keyboardRow = NUM_BUTTON_ROWS_easy_chat - 1;

        return ECFUNC_UPDATE_KEYBOARD_CURSOR_easy_chat;
    case INPUT_DOWN_easy_chat:
        if (sEasyChatScreen_easy_chat->keyboardRow < NUM_BUTTON_ROWS_easy_chat - 1)
            sEasyChatScreen_easy_chat->keyboardRow++;
        else
            sEasyChatScreen_easy_chat->keyboardRow = 0;

        return ECFUNC_UPDATE_KEYBOARD_CURSOR_easy_chat;
    case INPUT_LEFT_easy_chat:
        sEasyChatScreen_easy_chat->keyboardRow++;
        SetKeyboardCursorToLastColumn_easy_chat();
        return ECFUNC_UPDATE_KEYBOARD_CURSOR_easy_chat;
    case INPUT_RIGHT_easy_chat:
        sEasyChatScreen_easy_chat->keyboardColumn = 0;
        sEasyChatScreen_easy_chat->keyboardRow++;
        return ECFUNC_UPDATE_KEYBOARD_CURSOR_easy_chat;
    }

    return ECFUNC_NONE_easy_chat;
}

static void SetKeyboardCursorInButtonWindow_easy_chat(void)
{
    sEasyChatScreen_easy_chat->keyboardColumn = -1;
    if (sEasyChatScreen_easy_chat->keyboardRow)
        sEasyChatScreen_easy_chat->keyboardRow--;
}

static void SetKeyboardCursorToLastColumn_easy_chat(void)
{
    if (!sEasyChatScreen_easy_chat->inAlphabetMode)
    {
        sEasyChatScreen_easy_chat->keyboardColumn = 1;
        ReduceToValidKeyboardColumn_easy_chat();
    }
    else
    {
        sEasyChatScreen_easy_chat->keyboardColumn = GetLastAlphabetColumn_easy_chat(sEasyChatScreen_easy_chat->keyboardRow);
    }
}

static u16 MoveWordSelectCursor_easy_chat(u32 input)
{
    u16 funcId;
    switch (input)
    {
    case INPUT_UP_easy_chat:
        if (sEasyChatScreen_easy_chat->wordSelectRow + sEasyChatScreen_easy_chat->wordSelectScrollOffset > 0)
        {
            if (sEasyChatScreen_easy_chat->wordSelectRow > 0)
            {
                sEasyChatScreen_easy_chat->wordSelectRow--;
                funcId = ECFUNC_UPDATE_WORD_SELECT_CURSOR_easy_chat;
            }
            else
            {
                sEasyChatScreen_easy_chat->wordSelectScrollOffset--;
                funcId = ECFUNC_WORD_SELECT_SCROLL_UP_easy_chat;
            }

            ReduceToValidWordSelectColumn_easy_chat();
            return funcId;
        }
        break;
    case INPUT_DOWN_easy_chat:
        if (sEasyChatScreen_easy_chat->wordSelectRow + sEasyChatScreen_easy_chat->wordSelectScrollOffset < sEasyChatScreen_easy_chat->wordSelectLastRow)
        {
            if (sEasyChatScreen_easy_chat->wordSelectRow < NUM_WORD_SELECT_ROWS_easy_chat - 1)
            {
                sEasyChatScreen_easy_chat->wordSelectRow++;
                funcId = ECFUNC_UPDATE_WORD_SELECT_CURSOR_easy_chat;
            }
            else
            {
                sEasyChatScreen_easy_chat->wordSelectScrollOffset++;
                funcId = ECFUNC_WORD_SELECT_SCROLL_DOWN_easy_chat;
            }

            ReduceToValidWordSelectColumn_easy_chat();
            return funcId;
        }
        break;
    case INPUT_LEFT_easy_chat:
        if (sEasyChatScreen_easy_chat->wordSelectColumn > 0)
            sEasyChatScreen_easy_chat->wordSelectColumn--;
        else
            sEasyChatScreen_easy_chat->wordSelectColumn = 1;

        ReduceToValidWordSelectColumn_easy_chat();
        return ECFUNC_UPDATE_WORD_SELECT_CURSOR_easy_chat;
    case INPUT_RIGHT_easy_chat:
        if (sEasyChatScreen_easy_chat->wordSelectColumn < 1)
        {
            sEasyChatScreen_easy_chat->wordSelectColumn++;
            if (IsSelectedWordIndexInvalid_easy_chat())
                sEasyChatScreen_easy_chat->wordSelectColumn = 0;
        }
        else
        {
            sEasyChatScreen_easy_chat->wordSelectColumn = 0;
        }
        return ECFUNC_UPDATE_WORD_SELECT_CURSOR_easy_chat;
    case INPUT_START_easy_chat:
        // Page scroll up
        if (sEasyChatScreen_easy_chat->wordSelectScrollOffset)
        {
            if (sEasyChatScreen_easy_chat->wordSelectScrollOffset >= NUM_WORD_SELECT_ROWS_easy_chat)
                sEasyChatScreen_easy_chat->wordSelectScrollOffset -= NUM_WORD_SELECT_ROWS_easy_chat;
            else
                sEasyChatScreen_easy_chat->wordSelectScrollOffset = 0;

            return ECFUNC_WORD_SELECT_PAGE_UP_easy_chat;
        }
        break;
    case INPUT_SELECT_easy_chat:
        // Page scroll down
        if (sEasyChatScreen_easy_chat->wordSelectScrollOffset <= sEasyChatScreen_easy_chat->wordSelectLastRow - NUM_WORD_SELECT_ROWS_easy_chat)
        {
            sEasyChatScreen_easy_chat->wordSelectScrollOffset += NUM_WORD_SELECT_ROWS_easy_chat;
            if (sEasyChatScreen_easy_chat->wordSelectScrollOffset > sEasyChatScreen_easy_chat->wordSelectLastRow - NUM_WORD_SELECT_ROWS_easy_chat + 1)
                sEasyChatScreen_easy_chat->wordSelectScrollOffset = sEasyChatScreen_easy_chat->wordSelectLastRow - NUM_WORD_SELECT_ROWS_easy_chat + 1;

            ReduceToValidWordSelectColumn_easy_chat();
            return ECFUNC_WORD_SELECT_PAGE_DOWN_easy_chat;
        }
        break;
    }

    return ECFUNC_NONE_easy_chat;
}

