static bool32 CanScrollDown_easy_chat(void)
{
    switch (sEasyChatScreen_easy_chat->inputState)
    {
    case INPUTSTATE_KEYBOARD_easy_chat:
        if (!sEasyChatScreen_easy_chat->inAlphabetMode && sEasyChatScreen_easy_chat->keyboardScrollOffset + NUM_GROUP_NAME_ROWS_easy_chat <= sEasyChatScreen_easy_chat->keyboardLastRow - 1)
            return TRUE;
        break;
    case INPUTSTATE_WORD_SELECT_easy_chat:
        if (sEasyChatScreen_easy_chat->wordSelectScrollOffset + NUM_WORD_SELECT_ROWS_easy_chat <= sEasyChatScreen_easy_chat->wordSelectLastRow)
            return TRUE;
        break;
    }

    return FALSE;
}

