static void GetQuizTitle_easy_chat(u8 *dst)
{
    u8 name[32];
    struct SaveBlock1 *saveBlock1 = gSaveBlock1Ptr;
    DynamicPlaceholderTextUtil_Reset();

    // Buffer author's name
    if (StringLength(saveBlock1->lilycoveLady.quiz.playerName) != 0)
    {
        TVShowConvertInternationalString(name, saveBlock1->lilycoveLady.quiz.playerName, saveBlock1->lilycoveLady.quiz.language);
        DynamicPlaceholderTextUtil_SetPlaceholderPtr(0, name);
    }
    else
    {
        DynamicPlaceholderTextUtil_SetPlaceholderPtr(0, gText_Lady);
    }

    // "<author>'s Quiz"
    DynamicPlaceholderTextUtil_ExpandPlaceholders(dst, gText_F700sQuiz);
}

static void BufferCurrentPhraseToStringVar2_easy_chat(void)
{
    int i;
    u16 *phrase;
    u8 *str;

    phrase = sEasyChatScreen_easy_chat->currentPhrase;
    str = gStringVar2;
    i = 0;
    while (i < sEasyChatScreen_easy_chat->maxWords)
    {
        str = CopyEasyChatWordPadded(str, *phrase, 0);
        *str = 0;
        str++;
        phrase++;
        i++;
    }

    str--;
    str[0] = EOS;
}

static void SetSpecialEasyChatResult_easy_chat(void)
{
    switch (sEasyChatScreen_easy_chat->type)
    {
    case EASY_CHAT_TYPE_PROFILE:
        FlagSet(FLAG_SYS_CHAT_USED);
        break;
    case EASY_CHAT_TYPE_QUESTIONNAIRE:
        if (DidPlayerInputMysteryGiftPhrase_easy_chat())
            gSpecialVar_0x8004 = 2;
        else
            gSpecialVar_0x8004 = 0;
        break;
    case EASY_CHAT_TYPE_TRENDY_PHRASE:
        BufferCurrentPhraseToStringVar2_easy_chat();
        gSpecialVar_0x8004 = TrySetTrendyPhrase(sEasyChatScreen_easy_chat->currentPhrase);
        break;
    case EASY_CHAT_TYPE_GOOD_SAYING:
        gSpecialVar_0x8004 = DidPlayerInputABerryMasterWifePhrase_easy_chat();
        break;
    }
}

