static bool8 LoadEasyChatScreen_easy_chat(void)
{
    switch (sScreenControl_easy_chat->funcState)
    {
    case 0:
        ResetBgsAndClearDma3BusyFlags(0);
        InitBgsFromTemplates(0, sEasyChatBgTemplates_easy_chat, ARRAY_COUNT(sEasyChatBgTemplates_easy_chat));
        SetBgTilemapBuffer(3, sScreenControl_easy_chat->bg3TilemapBuffer);
        SetBgTilemapBuffer(1, sScreenControl_easy_chat->bg1TilemapBuffer);
        InitWindows(sEasyChatWindowTemplates_easy_chat);
        DeactivateAllTextPrinters();
        LoadEasyChatPalettes_easy_chat();
        InitEasyChatBgs_easy_chat();
        CpuFastFill(0, (void *)OAM, OAM_SIZE);
        break;
    case 1:
        DecompressAndLoadBgGfxUsingHeap(3, gEasyChatWindow_Gfx, 0, 0, 0);
        CopyToBgTilemapBuffer(3, gEasyChatWindow_Tilemap, 0, 0);
        AdjustBgTilemapForFooter_easy_chat();
        BufferFrameTilemap_easy_chat(sScreenControl_easy_chat->bg1TilemapBuffer);
        AddPhraseWindow_easy_chat();
        AddMainScreenButtonWindow_easy_chat();
        CopyBgTilemapBufferToVram(3);
        break;
    case 2:
        DecompressAndLoadBgGfxUsingHeap(1, sTextInputFrame_Gfx_easy_chat, 0, 0, 0);
        CopyBgTilemapBufferToVram(1);
        break;
    case 3:
        PrintTitle_easy_chat();
        PrintInitialInstructions_easy_chat();
        PrintCurrentPhrase_easy_chat();
        DrawLowerWindow_easy_chat();
        break;
    case 4:
        LoadEasyChatGfx_easy_chat();
        if (GetEasyChatScreenType_easy_chat() != EASY_CHAT_TYPE_QUIZ_QUESTION)
            CreateMainCursorSprite_easy_chat();
        break;
    case 5:
        if (IsDma3ManagerBusyWithBgCopy())
        {
            return TRUE;
        }
        else
        {
            SetWindowDimensions_easy_chat(0, 0, 0, 0);
            SetGpuReg(REG_OFFSET_WININ, WININ_WIN0_BG_ALL | WININ_WIN0_OBJ | WININ_WIN0_CLR);
            SetGpuReg(REG_OFFSET_WINOUT, WINOUT_WIN01_BG0
                                       | WINOUT_WIN01_BG1
                                       | WINOUT_WIN01_BG3
                                       | WINOUT_WIN01_OBJ
                                       | WINOUT_WIN01_CLR);
            ShowBg(3);
            ShowBg(1);
            ShowBg(2);
            ShowBg(0);
            CreateScrollIndicatorSprites_easy_chat();
            CreateStartSelectButtonSprites_easy_chat();
            TryAddInterviewObjectEvents_easy_chat();
        }
        break;
    default:
        return FALSE;
    }

    sScreenControl_easy_chat->funcState++;
    return TRUE;
}

