static void StartEasyChatFunction_easy_chat(u16 funcId)
{
    sScreenControl_easy_chat->currentFuncId = funcId;
    sScreenControl_easy_chat->funcState = 0;
    RunEasyChatFunction_easy_chat();
}

// Returns FALSE when called function has finished
static bool8 RunEasyChatFunction_easy_chat(void)
{
    switch (sScreenControl_easy_chat->currentFuncId)
    {
    case ECFUNC_NONE_easy_chat: return FALSE;
    case ECFUNC_REPRINT_PHRASE_easy_chat: return ReprintPhrase_easy_chat();
    case ECFUNC_UPDATE_MAIN_CURSOR_easy_chat: return UpdateMainCursor_easy_chat();
    case ECFUNC_UPDATE_MAIN_CURSOR_ON_BUTTONS_easy_chat: return UpdateMainCursorOnButtons_easy_chat();
    case ECFUNC_PROMPT_DELETE_ALL_easy_chat: return ShowConfirmDeleteAllPrompt_easy_chat();
    case ECFUNC_PROMPT_EXIT_easy_chat: return ShowConfirmExitPrompt_easy_chat();
    case ECFUNC_PROMPT_CONFIRM_easy_chat: return ShowConfirmPrompt_easy_chat();
    case ECFUNC_CLOSE_PROMPT_easy_chat: return ClosePrompt_easy_chat();
    case ECFUNC_CLOSE_PROMPT_AFTER_DELETE_easy_chat: return ClosePromptAfterDeleteAll_easy_chat();
    case ECFUNC_OPEN_KEYBOARD_easy_chat: return OpenKeyboard_easy_chat();
    case ECFUNC_CLOSE_KEYBOARD_easy_chat: return CloseKeyboard_easy_chat();
    case ECFUNC_OPEN_WORD_SELECT_easy_chat: return OpenWordSelect_easy_chat();
    case ECFUNC_CLOSE_WORD_SELECT_easy_chat: return CloseWordSelect_easy_chat();
    case ECFUNC_PROMPT_CONFIRM_LYRICS_easy_chat: return ShowConfirmLyricsPrompt_easy_chat();
    case ECFUNC_RETURN_TO_KEYBOARD_easy_chat: return ReturnToKeyboard_easy_chat();
    case ECFUNC_UPDATE_KEYBOARD_CURSOR_easy_chat: return UpdateKeyboardCursor_easy_chat();
    case ECFUNC_GROUP_NAMES_SCROLL_DOWN_easy_chat: return GroupNamesScrollDown_easy_chat();
    case ECFUNC_GROUP_NAMES_SCROLL_UP_easy_chat: return GroupNamesScrollUp_easy_chat();
    case ECFUNC_UPDATE_WORD_SELECT_CURSOR_easy_chat: return UpdateWordSelectCursor_easy_chat();
    case ECFUNC_WORD_SELECT_SCROLL_UP_easy_chat: return WordSelectScrollUp_easy_chat();
    case ECFUNC_WORD_SELECT_SCROLL_DOWN_easy_chat: return WordSelectScrollDown_easy_chat();
    case ECFUNC_WORD_SELECT_PAGE_UP_easy_chat: return WordSelectPageScrollUp_easy_chat();
    case ECFUNC_WORD_SELECT_PAGE_DOWN_easy_chat: return WordSelectPageScrollDown_easy_chat();
    case ECFUNC_SWITCH_KEYBOARD_MODE_easy_chat: return SwitchKeyboardMode_easy_chat();
    case ECFUNC_EXIT_easy_chat: return FALSE;
    case ECFUNC_QUIZ_QUESTION_easy_chat: return FALSE;     // The 4 quiz functions
    case ECFUNC_QUIZ_ANSWER_easy_chat: return FALSE;       // 'finish' automatically
    case ECFUNC_SET_QUIZ_QUESTION_easy_chat: return FALSE; // because they switch to a
    case ECFUNC_SET_QUIZ_ANSWER_easy_chat: return FALSE;   // callback in sQuizLadyEasyChatScreens
    case ECFUNC_MSG_CREATE_QUIZ_easy_chat: return ShowCreateQuizMsg_easy_chat();
    case ECFUNC_MSG_SELECT_ANSWER_easy_chat: return ShowSelectAnswerMsg_easy_chat();
    case ECFUNC_MSG_SONG_TOO_SHORT_easy_chat: return ShowSongTooShortMsg_easy_chat();
    case ECFUNC_MSG_CANT_DELETE_LYRICS_easy_chat: return ShowCantDeleteLyricsMsg_easy_chat();
    case ECFUNC_MSG_COMBINE_TWO_WORDS_easy_chat: return ShowCombineTwoWordsMsg_easy_chat();
    case ECFUNC_MSG_CANT_EXIT_easy_chat: return ShowCantExitMsg_easy_chat();
    default:        return FALSE;
    }
}

