static void PrintTitle_easy_chat(void)
{
    int xOffset;
    const u8 *titleText = GetTitleText();
    if (!titleText)
        return;

    xOffset = GetStringCenterAlignXOffset(FONT_NORMAL, titleText, 144);
    FillWindowPixelBuffer(WIN_TITLE_easy_chat, PIXEL_FILL(0));
    PrintEasyChatTextWithColors_easy_chat(WIN_TITLE_easy_chat, FONT_NORMAL, titleText, xOffset, 1, TEXT_SKIP_DRAW, TEXT_COLOR_TRANSPARENT, TEXT_COLOR_DARK_GRAY, TEXT_COLOR_LIGHT_GRAY);
    PutWindowTilemap(WIN_TITLE_easy_chat);
    CopyWindowToVram(WIN_TITLE_easy_chat, COPYWIN_FULL);
}

