static void PrintEasyChatStdMessage_easy_chat(u8 msgId)
{
    const u8 *text2 = NULL;
    const u8 *text1 = NULL;
    switch (msgId)
    {
    case MSG_INSTRUCTIONS_easy_chat:
        GetEasyChatInstructionsText_easy_chat(&text1, &text2);
        break;
    case MSG_CONFIRM_EXIT_easy_chat:
        GetEasyChatConfirmExitText_easy_chat(&text1, &text2);
        break;
    case MSG_CONFIRM_easy_chat:
        GetEasyChatConfirmText_easy_chat(&text1, &text2);
        break;
    case MSG_CONFIRM_DELETE_easy_chat:
        GetEasyChatConfirmDeletionText_easy_chat(&text1, &text2);
        break;
    case MSG_CREATE_QUIZ_easy_chat:
        text1 = gText_CreateAQuiz;
        break;
    case MSG_SELECT_ANSWER_easy_chat:
        text1 = gText_SelectTheAnswer;
        break;
    case MSG_SONG_TOO_SHORT_easy_chat:
        text1 = gText_OnlyOnePhrase;
        text2 = gText_OriginalSongWillBeUsed;
        break;
    case MSG_CANT_DELETE_LYRICS_easy_chat:
        text1 = gText_LyricsCantBeDeleted;
        break;
    case MSG_COMBINE_TWO_WORDS_easy_chat:
        text1 = gText_CombineTwoWordsOrPhrases3;
        break;
    case MSG_CANT_QUIT_easy_chat:
        text1 = gText_YouCannotQuitHere;
        text2 = gText_SectionMustBeCompleted;
        break;
    }

    FillWindowPixelBuffer(WIN_MSG_easy_chat, PIXEL_FILL(1));
    if (text1)
        PrintEasyChatText_easy_chat(WIN_MSG_easy_chat, FONT_NORMAL, text1, 0, 1, TEXT_SKIP_DRAW, 0);

    if (text2)
        PrintEasyChatText_easy_chat(WIN_MSG_easy_chat, FONT_NORMAL, text2, 0, 17, TEXT_SKIP_DRAW, 0);

    CopyWindowToVram(WIN_MSG_easy_chat, COPYWIN_FULL);
}

