static bool8 ObjectEventCB2_BerryTree_event_object_movement(struct ObjectEvent *objectEvent, struct Sprite *sprite);
extern bool8 (*const gMovementTypeFuncs_BerryTreeGrowth[])(struct ObjectEvent *objectEvent, struct Sprite *sprite);

enum {
    BERRYTREEFUNC_NORMAL_event_object_movement,
    BERRYTREEFUNC_MOVE_event_object_movement,
    BERRYTREEFUNC_SPARKLE_START_event_object_movement,
    BERRYTREEFUNC_SPARKLE_event_object_movement,
    BERRYTREEFUNC_SPARKLE_END_event_object_movement,
};

#define sTimer_event_object_movement          data[2]
#define sBerryTreeFlags_event_object_movement data[7]

#define BERRY_FLAG_SET_GFX_event_object_movement     (1 << 0)
#define BERRY_FLAG_SPARKLING_event_object_movement   (1 << 1)
#define BERRY_FLAG_JUST_PICKED_event_object_movement (1 << 2)

void MovementType_BerryTreeGrowth(struct Sprite *sprite)
{
    struct ObjectEvent *objectEvent;

    objectEvent = &gObjectEvents[sprite->sObjEventId_event_object_movement];
    if (!(sprite->sBerryTreeFlags_event_object_movement & BERRY_FLAG_SET_GFX_event_object_movement))
    {
        SetBerryTreeGraphics_event_object_movement(objectEvent, sprite);
        sprite->sBerryTreeFlags_event_object_movement |= BERRY_FLAG_SET_GFX_event_object_movement;
    }
    UpdateObjectEventCurrentMovement(objectEvent, sprite, ObjectEventCB2_BerryTree_event_object_movement);
}
static bool8 ObjectEventCB2_BerryTree_event_object_movement(struct ObjectEvent *objectEvent, struct Sprite *sprite)
{
    return gMovementTypeFuncs_BerryTreeGrowth[sprite->sTypeFuncId_event_object_movement](objectEvent, sprite);
}

// BERRYTREEFUNC_NORMAL_event_object_movement
bool8 MovementType_BerryTreeGrowth_Normal(struct ObjectEvent *objectEvent, struct Sprite *sprite)
{
    u8 berryStage;
    ClearObjectEventMovement(objectEvent, sprite);
    objectEvent->invisible = TRUE;
    sprite->invisible = TRUE;
    berryStage = GetStageByBerryTreeId(objectEvent->trainerRange_berryTreeId);
    if (berryStage == BERRY_STAGE_NO_BERRY)
    {
        if (!(sprite->sBerryTreeFlags_event_object_movement & BERRY_FLAG_JUST_PICKED_event_object_movement) && sprite->animNum == BERRY_STAGE_FLOWERING)
        {
            gFieldEffectArguments[0] = objectEvent->currentCoords.x;
            gFieldEffectArguments[1] = objectEvent->currentCoords.y;
            gFieldEffectArguments[2] = sprite->subpriority - 1;
            gFieldEffectArguments[3] = sprite->oam.priority;
            FieldEffectStart(FLDEFF_BERRY_TREE_GROWTH_SPARKLE);
            sprite->animNum = berryStage;
        }
        return FALSE;
    }
    objectEvent->invisible = FALSE;
    sprite->invisible = FALSE;
    berryStage--;
    if (sprite->animNum != berryStage)
    {
        sprite->sTypeFuncId_event_object_movement = BERRYTREEFUNC_SPARKLE_START_event_object_movement;
        return TRUE;
    }
    SetBerryTreeGraphics_event_object_movement(objectEvent, sprite);
    ObjectEventSetSingleMovement_event_object_movement(objectEvent, sprite, MOVEMENT_ACTION_START_ANIM_IN_DIRECTION);
    sprite->sTypeFuncId_event_object_movement = BERRYTREEFUNC_MOVE_event_object_movement;
    return TRUE;
}

// BERRYTREEFUNC_MOVE_event_object_movement
bool8 MovementType_BerryTreeGrowth_Move(struct ObjectEvent *objectEvent, struct Sprite *sprite)
{
    if (ObjectEventExecSingleMovementAction_event_object_movement(objectEvent, sprite))
    {
        sprite->sTypeFuncId_event_object_movement = BERRYTREEFUNC_NORMAL_event_object_movement;
        return TRUE;
    }
    return FALSE;
}

// BERRYTREEFUNC_SPARKLE_START_event_object_movement
bool8 MovementType_BerryTreeGrowth_SparkleStart(struct ObjectEvent *objectEvent, struct Sprite *sprite)
{
    objectEvent->singleMovementActive = TRUE;
    sprite->sTypeFuncId_event_object_movement = BERRYTREEFUNC_SPARKLE_event_object_movement;
    sprite->sTimer_event_object_movement = 0;
    sprite->sBerryTreeFlags_event_object_movement |= BERRY_FLAG_SPARKLING_event_object_movement;
    gFieldEffectArguments[0] = objectEvent->currentCoords.x;
    gFieldEffectArguments[1] = objectEvent->currentCoords.y;
    gFieldEffectArguments[2] = sprite->subpriority - 1;
    gFieldEffectArguments[3] = sprite->oam.priority;
    FieldEffectStart(FLDEFF_BERRY_TREE_GROWTH_SPARKLE);
    return TRUE;
}

// BERRYTREEFUNC_SPARKLE_event_object_movement
bool8 MovementType_BerryTreeGrowth_Sparkle(struct ObjectEvent *objectEvent, struct Sprite *sprite)
{
    sprite->sTimer_event_object_movement++;
    objectEvent->invisible = (sprite->sTimer_event_object_movement & 2) >> 1;
    sprite->animPaused = TRUE;
    if (sprite->sTimer_event_object_movement > 64)
    {
        SetBerryTreeGraphics_event_object_movement(objectEvent, sprite);
        sprite->sTypeFuncId_event_object_movement = BERRYTREEFUNC_SPARKLE_END_event_object_movement;
        sprite->sTimer_event_object_movement = 0;
        return TRUE;
    }
    return FALSE;
}

// BERRYTREEFUNC_SPARKLE_END_event_object_movement
bool8 MovementType_BerryTreeGrowth_SparkleEnd(struct ObjectEvent *objectEvent, struct Sprite *sprite)
{
    sprite->sTimer_event_object_movement++;
    objectEvent->invisible = (sprite->sTimer_event_object_movement & 2) >> 1;
    sprite->animPaused = TRUE;
    if (sprite->sTimer_event_object_movement > 64)
    {
        sprite->sTypeFuncId_event_object_movement = BERRYTREEFUNC_NORMAL_event_object_movement;
        sprite->sBerryTreeFlags_event_object_movement &= ~BERRY_FLAG_SPARKLING_event_object_movement;
        return TRUE;
    }
    return FALSE;
}

