    ObjectEventSetSingleMovement_event_object_movement(objectEvent, sprite, GetFaceDirectionMovementAction(GetCopyDirection_event_object_movement(gInitialMovementTypeFacingDirections[objectEvent->movementType], objectEvent->directionSequenceIndex, playerDirection)));
    objectEvent->singleMovementActive = TRUE;
    sprite->sTypeFuncId_event_object_movement = 2;
    return TRUE;
