bool8 FollowablePlayerMovement_GoSpeed4(struct ObjectEvent *objectEvent, struct Sprite *sprite, u8 playerDirection, bool8 tileCallback(u8))
{
    u32 direction;
    s16 x;
    s16 y;

    direction = playerDirection;
    direction = GetCopyDirection_event_object_movement(gInitialMovementTypeFacingDirections[objectEvent->movementType], objectEvent->directionSequenceIndex, direction);
    ObjectEventMoveDestCoords(objectEvent, direction, &x, &y);
    ObjectEventSetSingleMovement_event_object_movement(objectEvent, sprite, GetJumpMovementAction(direction));
    if (GetCollisionAtCoords(objectEvent, x, y, direction) || (tileCallback != NULL && !tileCallback(MapGridGetMetatileBehaviorAt(x, y))))
        ObjectEventSetSingleMovement_event_object_movement(objectEvent, sprite, GetFaceDirectionMovementAction(direction));
    objectEvent->singleMovementActive = TRUE;
    sprite->sTypeFuncId_event_object_movement = 2;
    return TRUE;
}

bool8 FollowablePlayerMovement_Jump(struct ObjectEvent *objectEvent, struct Sprite *sprite, u8 playerDirection, bool8 tileCallback(u8))
{
    u32 direction;
    s16 x;
    s16 y;

    direction = playerDirection;
    x = objectEvent->currentCoords.x;
    y = objectEvent->currentCoords.y;
    MoveCoordsInDirection_event_object_movement(direction, &x, &y, 2, 2);
    ObjectEventSetSingleMovement_event_object_movement(objectEvent, sprite, GetJump2MovementAction(direction));
    objectEvent->singleMovementActive = TRUE;
    sprite->sTypeFuncId_event_object_movement = 2;
    return TRUE;
}

