u8 GetOppositeDirection(u8 direction)
{
    u8 directions[sizeof sOppositeDirections_event_object_movement];

    memcpy(directions, sOppositeDirections_event_object_movement, sizeof sOppositeDirections_event_object_movement);
    if (direction <= DIR_NONE || direction > (sizeof sOppositeDirections_event_object_movement))
        return direction;

    return directions[direction - 1];
}

// Takes the player's original and current direction and gives a direction the copy NPC should consider as the player's direction.
// See comments at the table's definition.
static u32 GetPlayerDirectionForCopy_event_object_movement(u8 initDir, u8 moveDir)
{
    return sPlayerDirectionsForCopy_event_object_movement[initDir - 1][moveDir - 1];
}

// copyInitDir is the initial facing direction of the copying NPC.
// playerInitDir is the direction the player was facing when the copying NPC was spawned, as set by MovementType_CopyPlayer_Step0.
// playerMoveDir is the direction the player is currently moving.
static u32 GetCopyDirection_event_object_movement(u8 copyInitDir, u32 playerInitDir, u32 playerMoveDir)
{
    u32 dir;
    u8 _playerInitDir = playerInitDir;
    u8 _playerMoveDir = playerMoveDir;
    if (_playerInitDir == DIR_NONE || _playerMoveDir == DIR_NONE
      || _playerInitDir > DIR_EAST || _playerMoveDir > DIR_EAST)
        return DIR_NONE;

    dir = GetPlayerDirectionForCopy_event_object_movement(_playerInitDir, playerMoveDir);
    return sPlayerDirectionToCopyDirection_event_object_movement[copyInitDir - 1][dir - 1];
}

static void ObjectEventExecHeldMovementAction_event_object_movement(struct ObjectEvent *objectEvent, struct Sprite *sprite)
{
    objectEvent->movementActionId = TryUpdateMovementActionOnStairs_event_object_movement(objectEvent, objectEvent->movementActionId);
    if (gMovementActionFuncs[objectEvent->movementActionId][sprite->sActionFuncId_event_object_movement](objectEvent, sprite))
        objectEvent->heldMovementFinished = TRUE;
}

static bool8 ObjectEventExecSingleMovementAction_event_object_movement(struct ObjectEvent *objectEvent, struct Sprite *sprite)
{
    objectEvent->movementActionId = TryUpdateMovementActionOnStairs_event_object_movement(objectEvent, objectEvent->movementActionId);
    if (gMovementActionFuncs[objectEvent->movementActionId][sprite->sActionFuncId_event_object_movement](objectEvent, sprite))
    {
        objectEvent->movementActionId = MOVEMENT_ACTION_NONE;
        sprite->sActionFuncId_event_object_movement = 0;
        return TRUE;
    }
    return FALSE;
}

static void ObjectEventSetSingleMovement_event_object_movement(struct ObjectEvent *objectEvent, struct Sprite *sprite, u8 animId)
{
    objectEvent->movementActionId = TryUpdateMovementActionOnStairs_event_object_movement(objectEvent, animId);
    sprite->sActionFuncId_event_object_movement = 0;
}

