#define JUMP_HALFWAY_event_object_movement  1
#define JUMP_FINISHED_event_object_movement ((u8)-1)

enum {
    JUMP_TYPE_HIGH_event_object_movement,
    JUMP_TYPE_LOW_event_object_movement,
    JUMP_TYPE_NORMAL_event_object_movement,
    JUMP_TYPE_FAST_event_object_movement,
    JUMP_TYPE_FASTER_event_object_movement,
};

static void InitJump_event_object_movement(struct ObjectEvent *objectEvent, struct Sprite *sprite, u8 direction, u8 distance, u8 type)
{
    s16 displacements[ARRAY_COUNT(sJumpInitDisplacements)];
    s16 x;
    s16 y;

    memcpy(displacements, sJumpInitDisplacements, sizeof sJumpInitDisplacements);
    x = 0;
    y = 0;
    SetObjectEventDirection(objectEvent, direction);
    MoveCoordsInDirection_event_object_movement(direction, &x, &y, displacements[distance], displacements[distance]);
    ShiftObjectEventCoords(objectEvent, objectEvent->currentCoords.x + x, objectEvent->currentCoords.y + y);
    SetJumpSpriteData_event_object_movement(sprite, direction, distance, type);
    sprite->sActionFuncId_event_object_movement = 1;
    sprite->animPaused = FALSE;
    objectEvent->triggerGroundEffectsOnMove = TRUE;
    objectEvent->disableCoveringGroundEffects = TRUE;
}

static void InitJumpRegular_event_object_movement(struct ObjectEvent *objectEvent, struct Sprite *sprite, u8 direction, u8 distance, u8 type)
{
    // For follower only, match the anim duration of the player's movement, whether dashing, walking or jumping
    if (objectEvent->localId == OBJ_EVENT_ID_FOLLOWER
      && type == JUMP_TYPE_HIGH_event_object_movement
      && distance == JUMP_DISTANCE_FAR_event_object_movement
      // In some areas (i.e Meteor Falls), the player can jump as the follower jumps, so preserve type in this case
      && PlayerGetCopyableMovement() != COPY_MOVE_JUMP2)
        type = TestPlayerAvatarFlags(PLAYER_AVATAR_FLAG_DASH) ? JUMP_TYPE_FASTER_event_object_movement : JUMP_TYPE_FAST_event_object_movement;
    InitJump_event_object_movement(objectEvent, sprite, direction, distance, type);
    SetStepAnimHandleAlternation(objectEvent, sprite, GetMoveDirectionAnimNum(objectEvent->facingDirection));
    DoShadowFieldEffect_event_object_movement(objectEvent);
}

#define sDistance_event_object_movement data[4]

static u8 UpdateJumpAnim_event_object_movement(struct ObjectEvent *objectEvent, struct Sprite *sprite, u8 callback(struct Sprite *))
{
    s16 displacements[ARRAY_COUNT(sJumpDisplacements)];
    s16 x;
    s16 y;
    u8 result;

    memcpy(displacements, sJumpDisplacements, sizeof sJumpDisplacements);
    result = callback(sprite);
    if (result == JUMP_HALFWAY_event_object_movement && displacements[sprite->sDistance_event_object_movement] != 0)
    {
        x = 0;
        y = 0;
        MoveCoordsInDirection_event_object_movement(objectEvent->movementDirection, &x, &y, displacements[sprite->sDistance_event_object_movement], displacements[sprite->sDistance_event_object_movement]);
        ShiftObjectEventCoords(objectEvent, objectEvent->currentCoords.x + x, objectEvent->currentCoords.y + y);
        objectEvent->triggerGroundEffectsOnMove = TRUE;
        objectEvent->disableCoveringGroundEffects = TRUE;
    }
    else if (result == JUMP_FINISHED_event_object_movement)
    {
        ShiftStillObjectEventCoords(objectEvent);
        objectEvent->triggerGroundEffectsOnStop = TRUE;
        objectEvent->landingJump = TRUE;
        sprite->animPaused = TRUE;
    }
    return result;
}

#undef sDistance_event_object_movement

static u8 DoJumpAnimStep_event_object_movement(struct ObjectEvent *objectEvent, struct Sprite *sprite)
{
    return UpdateJumpAnim_event_object_movement(objectEvent, sprite, DoJumpSpriteMovement_event_object_movement);
}

static u8 DoJumpSpecialAnimStep_event_object_movement(struct ObjectEvent *objectEvent, struct Sprite *sprite)
{
    return UpdateJumpAnim_event_object_movement(objectEvent, sprite, DoJumpSpecialSpriteMovement_event_object_movement);
}

static bool8 DoJumpAnim_event_object_movement(struct ObjectEvent *objectEvent, struct Sprite *sprite)
{
    if (DoJumpAnimStep_event_object_movement(objectEvent, sprite) == JUMP_FINISHED_event_object_movement)
        return TRUE;

    return FALSE;
}

static bool8 DoJumpSpecialAnim_event_object_movement(struct ObjectEvent *objectEvent, struct Sprite *sprite)
{
    if (DoJumpSpecialAnimStep_event_object_movement(objectEvent, sprite) == JUMP_FINISHED_event_object_movement)
        return TRUE;

    return FALSE;
}

static bool8 DoJumpInPlaceAnim_event_object_movement(struct ObjectEvent *objectEvent, struct Sprite *sprite)
{
    switch (DoJumpAnimStep_event_object_movement(objectEvent, sprite))
    {
        case JUMP_FINISHED_event_object_movement:
            return TRUE;
        case JUMP_HALFWAY_event_object_movement:
            SetObjectEventDirection(objectEvent, GetOppositeDirection(objectEvent->movementDirection));
            SetStepAnim(objectEvent, sprite, GetMoveDirectionAnimNum(objectEvent->facingDirection));
        default:
            return FALSE;
    }
}

