static const union AffineAnimCmd *const  sAffineAnims_PokeballFollower_event_object_movement[] =
{
    sAffineAnim_PokeballExit_event_object_movement,
    sAffineAnim_PokeballExitEast_event_object_movement,
    sAffineAnim_PokeballEnter_event_object_movement,
    sAffineAnim_PokeballEnterEast_event_object_movement,
};

bool8 MovementAction_ExitPokeball_Step1(struct ObjectEvent *objectEvent, struct Sprite *sprite)
{
    // for different speeds, anim steps occur on different frame #s
    u32 animStepFrame = (sprite->sSpeedFlip_event_object_movement & 1) ? 7 : 3; // 0 -> 3, 1 -> 7
    if (--sprite->sDuration_event_object_movement == 0)
    {
        sprite->sActionFuncId_event_object_movement = 2;
        sprite->animCmdIndex = 0;
        sprite->animPaused = TRUE;
        return TRUE;
    }
    // Set graphics, palette, and affine animation
    else if (sprite->sDuration_event_object_movement == animStepFrame)
    {
        FollowerSetGraphics_event_object_movement(objectEvent, OW_SPECIES(objectEvent), OW_FORM(objectEvent), objectEvent->shiny);
        LoadFillColorPalette_event_object_movement(RGB_WHITE, OBJ_EVENT_PAL_TAG_WHITE, sprite);
        // Initialize affine animation
        sprite->affineAnims = sAffineAnims_PokeballFollower_event_object_movement;
        if (OW_LARGE_OW_SUPPORT && !IS_POW_OF_TWO(-sprite->centerToCornerVecX))
            return FALSE;
        sprite->affineAnims = sAffineAnims_PokeballFollower_event_object_movement;
        sprite->oam.affineMode = ST_OAM_AFFINE_NORMAL;
        InitSpriteAffineAnim(sprite);
        StartSpriteAffineAnim(sprite, sprite->sSpeedFlip_event_object_movement >> 4);
    // Restore original palette & disable affine
    }
    else if (sprite->sDuration_event_object_movement == (animStepFrame >> 1))
    {
        sprite->affineAnimEnded = TRUE;
        FreeSpriteOamMatrix(sprite);
        sprite->oam.affineMode = ST_OAM_AFFINE_OFF;
        FollowerSetGraphics_event_object_movement(objectEvent, OW_SPECIES(objectEvent), OW_FORM(objectEvent), objectEvent->shiny);
    }
    return FALSE;
}

bool8 MovementAction_EnterPokeball_Step0(struct ObjectEvent *objectEvent, struct Sprite *sprite)
{
    u32 direction = objectEvent->facingDirection;
    StartSpriteAnimInDirection(objectEvent, sprite, direction, GetMoveDirectionFasterAnimNum(direction));
    sprite->sDuration_event_object_movement = 16;
    // If mon's right-facing sprite is h-flipped, we need to use a different affine anim
    if (direction == DIR_EAST && sprite->anims[ANIM_STD_FACE_EAST]->frame.hFlip)
        sprite->sSpeedFlip_event_object_movement = 3;
    else
        sprite->sSpeedFlip_event_object_movement = 2;
    EndFollowerTransformEffect_event_object_movement(objectEvent, sprite);
    return MovementAction_EnterPokeball_Step1(objectEvent, sprite);
}

bool8 MovementAction_EnterPokeball_Step1(struct ObjectEvent *objectEvent, struct Sprite *sprite)
{
    u16 graphicsId = objectEvent->graphicsId;
    if (--sprite->sDuration_event_object_movement == 0)
    {
        sprite->sActionFuncId_event_object_movement = 2;
        return FALSE;
    }
    else if (sprite->sDuration_event_object_movement == 11)
    {
        // Set palette to white & start affine
        LoadFillColorPalette_event_object_movement(RGB_WHITE, OBJ_EVENT_PAL_TAG_WHITE, sprite);
        sprite->subspriteTableNum = 0;
        // Only do affine if sprite width is power of 2
        // (effect looks weird on sprites composed of subsprites like 48x48, etc)
        if (OW_LARGE_OW_SUPPORT && !IS_POW_OF_TWO(-sprite->centerToCornerVecX))
            return FALSE;
        sprite->affineAnims = sAffineAnims_PokeballFollower_event_object_movement;
        sprite->oam.affineMode = ST_OAM_AFFINE_NORMAL;
        InitSpriteAffineAnim(sprite);
        StartSpriteAffineAnim(sprite, sprite->sSpeedFlip_event_object_movement);
    }
    else if (sprite->sDuration_event_object_movement == 7)
    {
        // Free white palette and change to pokeball, disable affine
        sprite->affineAnimEnded = TRUE;
        FreeSpriteOamMatrix(sprite);
        sprite->oam.affineMode = ST_OAM_AFFINE_OFF;
        ObjectEventSetPokeballGfx_event_object_movement(objectEvent);
        objectEvent->graphicsId = graphicsId;
        objectEvent->inanimate = FALSE;
    }
    return FALSE;
}

bool8 MovementAction_EnterPokeball_Step2(struct ObjectEvent *objectEvent, struct Sprite *sprite)
{
    FollowerSetGraphics_event_object_movement(objectEvent, OW_SPECIES(objectEvent), OW_FORM(objectEvent), objectEvent->shiny);
    objectEvent->invisible = TRUE;
    sprite->sTypeFuncId_event_object_movement = 0;
    sprite->sSpeedFlip_event_object_movement = 0;
    sprite->animPaused = TRUE;
    return TRUE;
}

