{
    ObjectEventUpdateMetatileBehaviors_event_object_movement(objEvent);
    GetGroundEffectFlags_Reflection_event_object_movement(objEvent, flags);
    GetGroundEffectFlags_TallGrassOnSpawn_event_object_movement(objEvent, flags);
    GetGroundEffectFlags_LongGrassOnSpawn_event_object_movement(objEvent, flags);
    GetGroundEffectFlags_SandHeap_event_object_movement(objEvent, flags);
    GetGroundEffectFlags_ShallowFlowingWater_event_object_movement(objEvent, flags);
    GetGroundEffectFlags_ShortGrass_event_object_movement(objEvent, flags);
    GetGroundEffectFlags_HotSprings_event_object_movement(objEvent, flags);
}

