    GetGroundEffectFlags_LongGrassOnBeginStep_event_object_movement(objEvent, flags);
    GetGroundEffectFlags_Tracks_event_object_movement(objEvent, flags);
    GetGroundEffectFlags_SandHeap_event_object_movement(objEvent, flags);
    GetGroundEffectFlags_ShallowFlowingWater_event_object_movement(objEvent, flags);
