static bool8 NpcTakeStep_event_object_movement(struct Sprite *sprite)
{
    if (sprite->sTimer_event_object_movement >= sStepTimes_event_object_movement[sprite->sSpeed_event_object_movement])
        return FALSE;

    sNpcStepFuncTables_event_object_movement[sprite->sSpeed_event_object_movement][sprite->sTimer_event_object_movement](sprite, sprite->sDirection_event_object_movement);

    sprite->sTimer_event_object_movement++;

    if (sprite->sTimer_event_object_movement < sStepTimes_event_object_movement[sprite->sSpeed_event_object_movement])
        return FALSE;

    return TRUE;
}

