static void SetJumpSpriteData_event_object_movement(struct Sprite *sprite, u8 direction, u8 distance, u8 type)
{
    sprite->sDirection_event_object_movement = direction;
    sprite->sDistance_event_object_movement = distance;
    sprite->sJumpType_event_object_movement = type;
    sprite->sTimer_event_object_movement = 0;
}

static u8 DoJumpSpriteMovement_event_object_movement(struct Sprite *sprite)
{
    s16 distanceToTime[] =
    {
        [JUMP_DISTANCE_IN_PLACE_event_object_movement] = 16,
        [JUMP_DISTANCE_NORMAL_event_object_movement] = 16,
        [JUMP_DISTANCE_FAR_event_object_movement] = 32,
    };
    u8 distanceToShift[] =
    {
        [JUMP_DISTANCE_IN_PLACE_event_object_movement] = 0,
        [JUMP_DISTANCE_NORMAL_event_object_movement] = 0,
        [JUMP_DISTANCE_FAR_event_object_movement] = 1,
    };
    u8 result = 0;

    if (sprite->sDistance_event_object_movement != JUMP_DISTANCE_IN_PLACE_event_object_movement)
        Step1_event_object_movement(sprite, sprite->sDirection_event_object_movement);

    if (sprite->sJumpType_event_object_movement == JUMP_TYPE_FASTER_event_object_movement)
    {
        Step3_event_object_movement(sprite, sprite->sDirection_event_object_movement);
        sprite->y2 = GetJumpY_event_object_movement(sprite->sTimer_event_object_movement >> distanceToShift[sprite->sDistance_event_object_movement], JUMP_TYPE_NORMAL_event_object_movement);
        sprite->sTimer_event_object_movement += 3;
    }
    else if (sprite->sJumpType_event_object_movement == JUMP_TYPE_FAST_event_object_movement)
    {
        Step1_event_object_movement(sprite, sprite->sDirection_event_object_movement);
        sprite->y2 = GetJumpY_event_object_movement(sprite->sTimer_event_object_movement >> distanceToShift[sprite->sDistance_event_object_movement], JUMP_TYPE_NORMAL_event_object_movement);
        sprite->sTimer_event_object_movement++;
    }
    else
    {
        sprite->y2 = GetJumpY_event_object_movement(sprite->sTimer_event_object_movement >> distanceToShift[sprite->sDistance_event_object_movement], sprite->sJumpType_event_object_movement);
    }

    sprite->sTimer_event_object_movement++;

    if (sprite->sTimer_event_object_movement == distanceToTime[sprite->sDistance_event_object_movement] >> 1)
        result = JUMP_HALFWAY_event_object_movement;

    if (sprite->sTimer_event_object_movement >= distanceToTime[sprite->sDistance_event_object_movement])
    {
        sprite->y2 = 0;
        result = JUMP_FINISHED_event_object_movement;
    }

    return result;
}

static u8 DoJumpSpecialSpriteMovement_event_object_movement(struct Sprite *sprite)
{
    s16 distanceToTime[] = {
        [JUMP_DISTANCE_IN_PLACE_event_object_movement] = 32,
        [JUMP_DISTANCE_NORMAL_event_object_movement] = 32,
        [JUMP_DISTANCE_FAR_event_object_movement] = 64,
    };
    u8 distanceToShift[] = {
        [JUMP_DISTANCE_IN_PLACE_event_object_movement] = 1,
        [JUMP_DISTANCE_NORMAL_event_object_movement] = 1,
        [JUMP_DISTANCE_FAR_event_object_movement] = 2,
    };
    u8 result = 0;

    if (sprite->sDistance_event_object_movement != JUMP_DISTANCE_IN_PLACE_event_object_movement && !(sprite->sTimer_event_object_movement & 1))
        Step1_event_object_movement(sprite, sprite->sDirection_event_object_movement);

    sprite->y2 = GetJumpY_event_object_movement(sprite->sTimer_event_object_movement >> distanceToShift[sprite->sDistance_event_object_movement], sprite->sJumpType_event_object_movement);

    sprite->sTimer_event_object_movement++;

    if (sprite->sTimer_event_object_movement == distanceToTime[sprite->sDistance_event_object_movement] >> 1)
        result = JUMP_HALFWAY_event_object_movement;

    if (sprite->sTimer_event_object_movement >= distanceToTime[sprite->sDistance_event_object_movement])
    {
        sprite->y2 = 0;
        result = JUMP_FINISHED_event_object_movement;
    }

    return result;
}

