void SetVirtualObjectGraphics(u8 virtualObjId, u16 graphicsId)
{
    int spriteId = GetVirtualObjectSpriteId_event_object_movement(virtualObjId);

    if (spriteId != MAX_SPRITES)
    {
        struct Sprite *sprite = &gSprites[spriteId];
        const struct ObjectEventGraphicsInfo *graphicsInfo = GetObjectEventGraphicsInfo(graphicsId);
        u16 tileNum = sprite->oam.tileNum;
        u8 i = FindObjectEventPaletteIndexByTag_event_object_movement(graphicsInfo->paletteTag);
        if (i != 0xFF)
            UpdateSpritePalette_event_object_movement(&sObjectEventSpritePalettes_event_object_movement[i], sprite);

        sprite->oam = *graphicsInfo->oam;
        sprite->oam.tileNum = tileNum;
        sprite->images = graphicsInfo->images;

        if (graphicsInfo->subspriteTables == NULL)
        {
            sprite->subspriteTables = NULL;
            sprite->subspriteTableNum = 0;
            sprite->subspriteMode = SUBSPRITES_OFF;
        }
        else
        {
            SetSubspriteTables(sprite, graphicsInfo->subspriteTables);
            sprite->subspriteMode = SUBSPRITES_IGNORE_PRIORITY;
        }
        StartSpriteAnim(sprite, 0);
    }
}

void SetVirtualObjectInvisibility(u8 virtualObjId, bool32 invisible)
{
    u8 spriteId = GetVirtualObjectSpriteId_event_object_movement(virtualObjId);

    if (spriteId == MAX_SPRITES)
        return;

    if (invisible)
        gSprites[spriteId].sInvisible_event_object_movement = TRUE;
    else
        gSprites[spriteId].sInvisible_event_object_movement = FALSE;
}

bool32 IsVirtualObjectInvisible(u8 virtualObjId)
{
    u8 spriteId = GetVirtualObjectSpriteId_event_object_movement(virtualObjId);

    if (spriteId == MAX_SPRITES)
        return FALSE;

    return (gSprites[spriteId].sInvisible_event_object_movement == TRUE);
}

void SetVirtualObjectSpriteAnim(u8 virtualObjId, u8 animNum)
{
    u8 spriteId = GetVirtualObjectSpriteId_event_object_movement(virtualObjId);

    if (spriteId != MAX_SPRITES)
    {
        gSprites[spriteId].sAnimNum_event_object_movement = animNum;
        gSprites[spriteId].sAnimState_event_object_movement = 0;
    }
}

static void MoveUnionRoomObjectUp_event_object_movement(struct Sprite *sprite)
{
    switch(sprite->sAnimState_event_object_movement)
    {
    case 0:
        sprite->y2 = 0;
        sprite->sAnimState_event_object_movement++;
    case 1:
        sprite->y2 -= 8;
        if (sprite->y2 == -DISPLAY_HEIGHT)
        {
            sprite->y2 = 0;
            sprite->sInvisible_event_object_movement = TRUE;
            sprite->sAnimNum_event_object_movement = 0;
            sprite->sAnimState_event_object_movement = 0;
        }
    }
}

static void MoveUnionRoomObjectDown_event_object_movement(struct Sprite *sprite)
{
    switch(sprite->sAnimState_event_object_movement)
    {
    case 0:
        sprite->y2 = -DISPLAY_HEIGHT;
        sprite->sAnimState_event_object_movement++;
    case 1:
        sprite->y2 += 8;
        if(sprite->y2 == 0)
        {
            sprite->sAnimNum_event_object_movement = 0;
            sprite->sAnimState_event_object_movement = 0;
        }
    }
}

static void VirtualObject_UpdateAnim_event_object_movement(struct Sprite *sprite)
{
    switch(sprite->sAnimNum_event_object_movement)
    {
    case UNION_ROOM_SPAWN_IN:
        MoveUnionRoomObjectDown_event_object_movement(sprite);
        break;
    case UNION_ROOM_SPAWN_OUT:
        MoveUnionRoomObjectUp_event_object_movement(sprite);
        break;
    case 0:
        break;
    default:
        sprite->sAnimNum_event_object_movement = 0;
        break;
    }
}

bool32 IsVirtualObjectAnimating(u8 virtualObjId)
{
    u8 spriteId = GetVirtualObjectSpriteId_event_object_movement(virtualObjId);

    if (spriteId == MAX_SPRITES)
        return FALSE;

    if (gSprites[spriteId].sAnimNum_event_object_movement != 0)
        return TRUE;

    return FALSE;
}

u32 StartFieldEffectForObjectEvent(u8 fieldEffectId, struct ObjectEvent *objectEvent)
{
    ObjectEventGetLocalIdAndMap(objectEvent, &gFieldEffectArguments[0], &gFieldEffectArguments[1], &gFieldEffectArguments[2]);
    return FieldEffectStart(fieldEffectId);
}

static void DoShadowFieldEffect_event_object_movement(struct ObjectEvent *objectEvent)
{
    if (!objectEvent->hasShadow)
    {
        objectEvent->hasShadow = TRUE;
        StartFieldEffectForObjectEvent(FLDEFF_SHADOW, objectEvent);
    }
}

static void DoRippleFieldEffect_event_object_movement(struct ObjectEvent *objectEvent, struct Sprite *sprite)
{
    const struct ObjectEventGraphicsInfo *graphicsInfo = GetObjectEventGraphicsInfo(objectEvent->graphicsId);
    gFieldEffectArguments[0] = sprite->x;
    gFieldEffectArguments[1] = sprite->y + (graphicsInfo->height >> 1) - 2;
    gFieldEffectArguments[2] = 151;
    gFieldEffectArguments[3] = 3;
    FieldEffectStart(FLDEFF_RIPPLE);
}

