        StartSlowRunningAnim_event_object_movement(objectEvent, sprite, objectEvent->directionOverwrite);
    else
        StartSlowRunningAnim_event_object_movement(objectEvent, sprite, DIR_WEST);
    return MovementActionFunc_RunSlow_Step1(objectEvent, sprite);
