#define sSpeed_evolution_graphics     data[3]
#define sAmplitude_evolution_graphics data[5]
#define sTrigIdx_evolution_graphics   data[6]
#define sTimer_evolution_graphics     data[7]

static void SpriteCB_Sparkle_SpiralUpward_evolution_graphics(struct Sprite *sprite)
{
    if (sprite->y > 8)
    {
        u8 matrixNum;

        sprite->y = 88 - (sprite->sTimer_evolution_graphics * sprite->sTimer_evolution_graphics) / 80;
        sprite->y2 = Sin((u8)sprite->sTrigIdx_evolution_graphics, sprite->sAmplitude_evolution_graphics) / 4;
        sprite->x2 = Cos((u8)sprite->sTrigIdx_evolution_graphics, sprite->sAmplitude_evolution_graphics);
        sprite->sTrigIdx_evolution_graphics += 4;
        if (sprite->sTimer_evolution_graphics & 1)
            sprite->sAmplitude_evolution_graphics--;
        sprite->sTimer_evolution_graphics++;
        if (sprite->y2 > 0)
            sprite->subpriority = 1;
        else
            sprite->subpriority = 20;
        matrixNum = sprite->sAmplitude_evolution_graphics / 4 + 20;
        if (matrixNum > 31)
            matrixNum = 31;
        sprite->oam.matrixNum = matrixNum;
    }
    else
    {
        DestroySprite(sprite);
    }
}

static void CreateSparkle_SpiralUpward_evolution_graphics(u8 trigIdx)
{
    u8 spriteId = CreateSprite(&sEvoSparkleSpriteTemplate_evolution_graphics, DISPLAY_WIDTH / 2, 88, 0);
    if (spriteId != MAX_SPRITES)
    {
        gSprites[spriteId].sAmplitude_evolution_graphics = 48;
        gSprites[spriteId].sTrigIdx_evolution_graphics = trigIdx;
        gSprites[spriteId].sTimer_evolution_graphics = 0;
        gSprites[spriteId].oam.affineMode = ST_OAM_AFFINE_NORMAL;
        gSprites[spriteId].oam.matrixNum = 31;
        gSprites[spriteId].callback = SpriteCB_Sparkle_SpiralUpward_evolution_graphics;
    }
}

static void SpriteCB_Sparkle_ArcDown_evolution_graphics(struct Sprite *sprite)
{
    if (sprite->y < 88)
    {
        sprite->y = 8 + (sprite->sTimer_evolution_graphics * sprite->sTimer_evolution_graphics) / 5;
        sprite->y2 = Sin((u8)sprite->sTrigIdx_evolution_graphics, sprite->sAmplitude_evolution_graphics) / 4;
        sprite->x2 = Cos((u8)sprite->sTrigIdx_evolution_graphics, sprite->sAmplitude_evolution_graphics);
        sprite->sAmplitude_evolution_graphics = 8 + Sin((u8)(sprite->sTimer_evolution_graphics * 4), 40);
        sprite->sTimer_evolution_graphics++;
    }
    else
    {
        DestroySprite(sprite);
    }
}

static void CreateSparkle_ArcDown_evolution_graphics(u8 trigIdx)
{
    u8 spriteId = CreateSprite(&sEvoSparkleSpriteTemplate_evolution_graphics, DISPLAY_WIDTH / 2, 8, 0);
    if (spriteId != MAX_SPRITES)
    {
        gSprites[spriteId].sAmplitude_evolution_graphics = 8;
        gSprites[spriteId].sTrigIdx_evolution_graphics = trigIdx;
        gSprites[spriteId].sTimer_evolution_graphics = 0;
        gSprites[spriteId].oam.affineMode = ST_OAM_AFFINE_NORMAL;
        gSprites[spriteId].oam.matrixNum = 25;
        gSprites[spriteId].subpriority = 1;
        gSprites[spriteId].callback = SpriteCB_Sparkle_ArcDown_evolution_graphics;
    }
}

static void SpriteCB_Sparkle_CircleInward_evolution_graphics(struct Sprite *sprite)
{
    if (sprite->sAmplitude_evolution_graphics > 8)
    {
        sprite->y2 = Sin((u8)sprite->sTrigIdx_evolution_graphics, sprite->sAmplitude_evolution_graphics);
        sprite->x2 = Cos((u8)sprite->sTrigIdx_evolution_graphics, sprite->sAmplitude_evolution_graphics);
        sprite->sAmplitude_evolution_graphics -= sprite->sSpeed_evolution_graphics;
        sprite->sTrigIdx_evolution_graphics += 4;
    }
    else
    {
        DestroySprite(sprite);
    }
}

