#define tPreEvoSpriteId_evolution_graphics     data[1]
#define tPostEvoSpriteId_evolution_graphics    data[2]
#define tPreEvoScale_evolution_graphics        data[3]
#define tPostEvoScale_evolution_graphics       data[4]
#define tShowingPostEvo_evolution_graphics     data[5]
#define tScaleSpeed_evolution_graphics         data[6]
#define tEvoStopped_evolution_graphics         data[8]

#define MATRIX_PRE_EVO_evolution_graphics  30
#define MATRIX_POST_EVO_evolution_graphics 31

#define MON_MAX_SCALE_evolution_graphics 256
#define MON_MIN_SCALE_evolution_graphics 16

// Alternately grow/shrink the pre-evolution and post-evolution mon sprites
u8 CycleEvolutionMonSprite(u8 preEvoSpriteId, u8 postEvoSpriteId)
{
    u16 i;
    u16 monPalette[16];
    u8 taskId;
    s32 toDiv;

    for (i = 0; i < ARRAY_COUNT(monPalette); i++)
        monPalette[i] = RGB_WHITE;

    taskId = CreateTask(Task_CycleEvolutionMonSprite_Init_evolution_graphics, 0);
    gTasks[taskId].tPreEvoSpriteId_evolution_graphics = preEvoSpriteId;
    gTasks[taskId].tPostEvoSpriteId_evolution_graphics = postEvoSpriteId;
    gTasks[taskId].tPreEvoScale_evolution_graphics = MON_MAX_SCALE_evolution_graphics;
    gTasks[taskId].tPostEvoScale_evolution_graphics = MON_MIN_SCALE_evolution_graphics;

    toDiv = 65536;
    SetOamMatrix(MATRIX_PRE_EVO_evolution_graphics, MON_MAX_SCALE_evolution_graphics, 0, 0, MON_MAX_SCALE_evolution_graphics);
    SetOamMatrix(MATRIX_POST_EVO_evolution_graphics, toDiv / gTasks[taskId].tPostEvoScale_evolution_graphics, 0, 0, toDiv / gTasks[taskId].tPostEvoScale_evolution_graphics);

    gSprites[preEvoSpriteId].callback = SpriteCB_EvolutionMonSprite_evolution_graphics;
    gSprites[preEvoSpriteId].oam.affineMode = ST_OAM_AFFINE_NORMAL;
    gSprites[preEvoSpriteId].oam.matrixNum = MATRIX_PRE_EVO_evolution_graphics;
    gSprites[preEvoSpriteId].invisible = FALSE;
    CpuSet(monPalette, &gPlttBufferFaded[OBJ_PLTT_ID(gSprites[preEvoSpriteId].oam.paletteNum)], 16);

    gSprites[postEvoSpriteId].callback = SpriteCB_EvolutionMonSprite_evolution_graphics;
    gSprites[postEvoSpriteId].oam.affineMode = ST_OAM_AFFINE_NORMAL;
    gSprites[postEvoSpriteId].oam.matrixNum = MATRIX_POST_EVO_evolution_graphics;
    gSprites[postEvoSpriteId].invisible = FALSE;
    CpuSet(monPalette, &gPlttBufferFaded[OBJ_PLTT_ID(gSprites[postEvoSpriteId].oam.paletteNum)], 16);

    gTasks[taskId].tEvoStopped_evolution_graphics = FALSE;
    return taskId;
}

static void Task_CycleEvolutionMonSprite_Init_evolution_graphics(u8 taskId)
{
    gTasks[taskId].tShowingPostEvo_evolution_graphics = FALSE;
    gTasks[taskId].tScaleSpeed_evolution_graphics = 8;
    gTasks[taskId].func = Task_CycleEvolutionMonSprite_TryEnd_evolution_graphics;
}

// Try to end sprite cycling
// If evo hasn't stopped or growth/shrink speed hasn't been maxed out, start another cycle
static void Task_CycleEvolutionMonSprite_TryEnd_evolution_graphics(u8 taskId)
{
    if (gTasks[taskId].tEvoStopped_evolution_graphics)
    {
        EndOnPreEvoMon_evolution_graphics(taskId);
    }
    else if (gTasks[taskId].tScaleSpeed_evolution_graphics == 128)
    {
        EndOnPostEvoMon_evolution_graphics(taskId);
    }
    else
    {
        gTasks[taskId].tScaleSpeed_evolution_graphics += 2;
        gTasks[taskId].tShowingPostEvo_evolution_graphics ^= 1;
        gTasks[taskId].func = Task_CycleEvolutionMonSprite_UpdateSize_evolution_graphics;
    }
}

static void Task_CycleEvolutionMonSprite_UpdateSize_evolution_graphics(u8 taskId)
{
    if (gTasks[taskId].tEvoStopped_evolution_graphics)
    {
        gTasks[taskId].func = EndOnPreEvoMon_evolution_graphics;
    }
    else
    {
        u16 oamMatrixArg;
        u8 numSpritesFinished = 0;
        if (!gTasks[taskId].tShowingPostEvo_evolution_graphics)
        {
            // Set pre-evo sprite growth
            if (gTasks[taskId].tPreEvoScale_evolution_graphics < MON_MAX_SCALE_evolution_graphics - gTasks[taskId].tScaleSpeed_evolution_graphics)
            {
                gTasks[taskId].tPreEvoScale_evolution_graphics += gTasks[taskId].tScaleSpeed_evolution_graphics;
            }
            else
            {
                gTasks[taskId].tPreEvoScale_evolution_graphics = MON_MAX_SCALE_evolution_graphics;
                numSpritesFinished++;
            }

            // Set post-evo sprite shrink
            if (gTasks[taskId].tPostEvoScale_evolution_graphics > MON_MIN_SCALE_evolution_graphics + gTasks[taskId].tScaleSpeed_evolution_graphics)
            {
                gTasks[taskId].tPostEvoScale_evolution_graphics  -= gTasks[taskId].tScaleSpeed_evolution_graphics;
            }
            else
            {
                gTasks[taskId].tPostEvoScale_evolution_graphics = MON_MIN_SCALE_evolution_graphics;
                numSpritesFinished++;
            }
        }
        else
        {
            // Set post-evo sprite growth
            if (gTasks[taskId].tPostEvoScale_evolution_graphics < MON_MAX_SCALE_evolution_graphics - gTasks[taskId].tScaleSpeed_evolution_graphics)
            {
                gTasks[taskId].tPostEvoScale_evolution_graphics += gTasks[taskId].tScaleSpeed_evolution_graphics;
            }
            else
            {
                gTasks[taskId].tPostEvoScale_evolution_graphics = MON_MAX_SCALE_evolution_graphics;
                numSpritesFinished++;
            }

            // Set pre-evo sprite shrink
            if (gTasks[taskId].tPreEvoScale_evolution_graphics > MON_MIN_SCALE_evolution_graphics + gTasks[taskId].tScaleSpeed_evolution_graphics)
            {
                gTasks[taskId].tPreEvoScale_evolution_graphics  -= gTasks[taskId].tScaleSpeed_evolution_graphics;
            }
            else
            {
                gTasks[taskId].tPreEvoScale_evolution_graphics = MON_MIN_SCALE_evolution_graphics;
                numSpritesFinished++;
            }
        }

        // Grow/shrink pre-evo sprite
        oamMatrixArg = 65536 / gTasks[taskId].tPreEvoScale_evolution_graphics;
        SetOamMatrix(MATRIX_PRE_EVO_evolution_graphics, oamMatrixArg, 0, 0, oamMatrixArg);

        // Grow/shrink post-evo sprite
        oamMatrixArg = 65536 / gTasks[taskId].tPostEvoScale_evolution_graphics;
        SetOamMatrix(MATRIX_POST_EVO_evolution_graphics, oamMatrixArg, 0, 0, oamMatrixArg);

        // Both sprites have reached their size extreme
        if (numSpritesFinished == 2)
            gTasks[taskId].func = Task_CycleEvolutionMonSprite_TryEnd_evolution_graphics;
    }
}

static void EndOnPostEvoMon_evolution_graphics(u8 taskId)
{
    gSprites[gTasks[taskId].tPreEvoSpriteId_evolution_graphics].oam.affineMode = ST_OAM_AFFINE_OFF;
    gSprites[gTasks[taskId].tPreEvoSpriteId_evolution_graphics].oam.matrixNum = 0;
    gSprites[gTasks[taskId].tPreEvoSpriteId_evolution_graphics].invisible = TRUE;

    gSprites[gTasks[taskId].tPostEvoSpriteId_evolution_graphics].oam.affineMode = ST_OAM_AFFINE_OFF;
    gSprites[gTasks[taskId].tPostEvoSpriteId_evolution_graphics].oam.matrixNum = 0;
    gSprites[gTasks[taskId].tPostEvoSpriteId_evolution_graphics].invisible = FALSE;

    DestroyTask(taskId);
}

static void EndOnPreEvoMon_evolution_graphics(u8 taskId)
{
    gSprites[gTasks[taskId].tPreEvoSpriteId_evolution_graphics].oam.affineMode = ST_OAM_AFFINE_OFF;
    gSprites[gTasks[taskId].tPreEvoSpriteId_evolution_graphics].oam.matrixNum = 0;
    gSprites[gTasks[taskId].tPreEvoSpriteId_evolution_graphics].invisible = FALSE;

    gSprites[gTasks[taskId].tPostEvoSpriteId_evolution_graphics].oam.affineMode = ST_OAM_AFFINE_OFF;
    gSprites[gTasks[taskId].tPostEvoSpriteId_evolution_graphics].oam.matrixNum = 0;
    gSprites[gTasks[taskId].tPostEvoSpriteId_evolution_graphics].invisible = TRUE;

    DestroyTask(taskId);
}
