static void CB2_BeginEvolutionScene_evolution_scene(void)
{
    UpdatePaletteFade();
    RunTasks();
}

#define tState_evolution_scene              data[0]
#define tPreEvoSpecies_evolution_scene      data[1]
#define tPostEvoSpecies_evolution_scene     data[2]
#define tCanStop_evolution_scene            data[3]
#define tBits_evolution_scene               data[3]
#define tLearnsFirstMove_evolution_scene    data[4]
#define tLearnMoveState_evolution_scene     data[6]
#define tLearnMoveYesState_evolution_scene  data[7]
#define tLearnMoveNoState_evolution_scene   data[8]
#define tEvoWasStopped_evolution_scene      data[9]
#define tPartyId_evolution_scene            data[10]

#define TASK_BIT_CAN_STOP_evolution_scene       (1 << 0)
#define TASK_BIT_LEARN_MOVE_evolution_scene     (1 << 7)

static void Task_BeginEvolutionScene_evolution_scene(u8 taskId)
{
    struct Pokemon *mon = NULL;
    switch (gTasks[taskId].tState_evolution_scene)
    {
    case 0:
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 0x10, RGB_BLACK);
        gTasks[taskId].tState_evolution_scene++;
        break;
    case 1:
        if (!gPaletteFade.active)
        {
            u16 postEvoSpecies;
            bool8 canStopEvo;
            u8 partyId;

            mon = &gPlayerParty[gTasks[taskId].tPartyId_evolution_scene];
            postEvoSpecies = gTasks[taskId].tPostEvoSpecies_evolution_scene;
            canStopEvo = gTasks[taskId].tCanStop_evolution_scene;
            partyId = gTasks[taskId].tPartyId_evolution_scene;

            DestroyTask(taskId);
            EvolutionScene(mon, postEvoSpecies, canStopEvo, partyId);
        }
        break;
    }
}

void BeginEvolutionScene(struct Pokemon *mon, u16 postEvoSpecies, bool8 canStopEvo, u8 partyId)
{
    u8 taskId = CreateTask(Task_BeginEvolutionScene_evolution_scene, 0);
    gTasks[taskId].tState_evolution_scene = 0;
    gTasks[taskId].tPostEvoSpecies_evolution_scene = postEvoSpecies;
    gTasks[taskId].tCanStop_evolution_scene = canStopEvo;
    gTasks[taskId].tPartyId_evolution_scene = partyId;
    SetMainCallback2(CB2_BeginEvolutionScene_evolution_scene);
}

void EvolutionScene(struct Pokemon *mon, u16 postEvoSpecies, bool8 canStopEvo, u8 partyId)
{
    u8 name[POKEMON_NAME_BUFFER_SIZE];
    u16 currSpecies;
    u32 personality;
    bool32 isShiny;
    u8 id;

    SetHBlankCallback(NULL);
    SetVBlankCallback(NULL);
    CpuFill32(0, (void *)(VRAM), VRAM_SIZE);

    SetGpuReg(REG_OFFSET_MOSAIC, 0);
    SetGpuReg(REG_OFFSET_WIN0H, 0);
    SetGpuReg(REG_OFFSET_WIN0V, 0);
    SetGpuReg(REG_OFFSET_WIN1H, 0);
    SetGpuReg(REG_OFFSET_WIN1V, 0);
    SetGpuReg(REG_OFFSET_WININ, 0);
    SetGpuReg(REG_OFFSET_WINOUT, 0);

    ResetPaletteFade();

    gBattle_BG0_X = 0;
    gBattle_BG0_Y = 0;
    gBattle_BG1_X = 0;
    gBattle_BG1_Y = 0;
    gBattle_BG2_X = 0;
    gBattle_BG2_Y = 0;
    gBattle_BG3_X = 256;
    gBattle_BG3_Y = 0;

    gBattleTerrain = BATTLE_TERRAIN_PLAIN;

    InitBattleBgsVideo();
    LoadBattleTextboxAndBackground();
    ResetSpriteData();
    ScanlineEffect_Stop();
    ResetTasks();
    FreeAllSpritePalettes();

    gReservedSpritePaletteCount = 4;

    sEvoStructPtr_evolution_scene = AllocZeroed(sizeof(struct EvoInfo));
    AllocateMonSpritesGfx();

    GetMonData(mon, MON_DATA_NICKNAME, name);
    StringCopy_Nickname(gStringVar1, name);
    StringCopy(gStringVar2, GetSpeciesName(postEvoSpecies));

    // preEvo sprite
    currSpecies = GetMonData(mon, MON_DATA_SPECIES);
    isShiny = GetMonData(mon, MON_DATA_IS_SHINY);
    personality = GetMonData(mon, MON_DATA_PERSONALITY);
    LoadSpecialPokePic(gMonSpritesGfxPtr->spritesGfx[B_POSITION_OPPONENT_LEFT],
                        currSpecies,
                        personality,
                        TRUE);
    LoadCompressedPalette(GetMonSpritePalFromSpeciesAndPersonality(currSpecies, isShiny, personality), OBJ_PLTT_ID(1), PLTT_SIZE_4BPP);

    SetMultiuseSpriteTemplateToPokemon(currSpecies, B_POSITION_OPPONENT_LEFT);
    gMultiuseSpriteTemplate.affineAnims = gDummySpriteAffineAnimTable;
    sEvoStructPtr_evolution_scene->preEvoSpriteId = id = CreateSprite(&gMultiuseSpriteTemplate, 120, 64, 30);

    gSprites[id].callback = SpriteCallbackDummy_2;
    gSprites[id].oam.paletteNum = 1;
    gSprites[id].invisible = TRUE;

    // postEvo sprite
    LoadSpecialPokePic(gMonSpritesGfxPtr->spritesGfx[B_POSITION_OPPONENT_RIGHT],
                        postEvoSpecies,
                        personality,
                        TRUE);
    LoadCompressedPalette(GetMonSpritePalFromSpeciesAndPersonality(postEvoSpecies, isShiny, personality), OBJ_PLTT_ID(2), PLTT_SIZE_4BPP);

    SetMultiuseSpriteTemplateToPokemon(postEvoSpecies, B_POSITION_OPPONENT_RIGHT);
    gMultiuseSpriteTemplate.affineAnims = gDummySpriteAffineAnimTable;
    sEvoStructPtr_evolution_scene->postEvoSpriteId = id = CreateSprite(&gMultiuseSpriteTemplate, 120, 64, 30);
    gSprites[id].callback = SpriteCallbackDummy_2;
    gSprites[id].oam.paletteNum = 2;
    gSprites[id].invisible = TRUE;

    LoadEvoSparkleSpriteAndPal();

    sEvoStructPtr_evolution_scene->evoTaskId = id = CreateTask(Task_EvolutionScene_evolution_scene, 0);
    gTasks[id].tState_evolution_scene = 0;
    gTasks[id].tPreEvoSpecies_evolution_scene = currSpecies;
    gTasks[id].tPostEvoSpecies_evolution_scene = postEvoSpecies;
    gTasks[id].tCanStop_evolution_scene = canStopEvo;
    gTasks[id].tLearnsFirstMove_evolution_scene = TRUE;
    gTasks[id].tEvoWasStopped_evolution_scene = FALSE;
    gTasks[id].tPartyId_evolution_scene = partyId;

    memcpy(&sEvoStructPtr_evolution_scene->savedPalette, &gPlttBufferUnfaded[BG_PLTT_ID(2)], sizeof(sEvoStructPtr_evolution_scene->savedPalette));

    SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_OBJ_ON | DISPCNT_BG_ALL_ON | DISPCNT_OBJ_1D_MAP);

    SetHBlankCallback(EvoDummyFunc_evolution_scene);
    SetVBlankCallback(VBlankCB_EvolutionScene_evolution_scene);
    m4aMPlayAllStop();
    SetMainCallback2(CB2_EvolutionSceneUpdate_evolution_scene);
}

