static void ExpansionIntro_StartBlend_expansion_intro(void)
{
    ShowBg(2);
    CreateTask(Task_ExpansionIntro_HandleBlend_expansion_intro, 0);
}

static void Task_ExpansionIntro_HandleBlend_expansion_intro(u8 taskId)
{
    if (GetGpuReg(REG_OFFSET_BLDY) != 0)
    {
        SetGpuReg(REG_OFFSET_BLDY, GetGpuReg(REG_OFFSET_BLDY) - 1);
    }
    else
    {
        SetGpuReg(REG_OFFSET_BLDCNT, 0);
        DestroyTask(taskId);
    }
}

#define sTimer_expansion_intro data[0]
static void SpriteCallback_DizzyWalking_expansion_intro(struct Sprite* sprite)
{
    sprite->x2--;

    if (sprite->x2 <= DIZZY_COLLISION_POS_X_expansion_intro)
    {
        StartSpriteAnim(sprite, ANIM_DIZZY_DIZZY_expansion_intro);
        sprite->callback = SpriteCallbackDummy;
    }

    if (sprite->sTimer_expansion_intro % 16 == 0 && sprite->sTimer_expansion_intro / 16 > 2)
        PlaySE(SE_BIKE_HOP);

    sprite->sTimer_expansion_intro++;
}


static void SpriteCallback_PorygonHit_expansion_intro(struct Sprite* sprite)
{
    sprite->x2-=2;
    sprite ->y2 = Sin2(180 + sprite->sTimer_expansion_intro * 4) / 128;

    if (sprite->sTimer_expansion_intro >= 48)
    {
        StartSpriteAnim(sprite, ANIM_PORY_GO_UP_expansion_intro);
        sprite->callback = SpriteCallbackDummy;
    }

    if (sprite->sTimer_expansion_intro % 8 == 0)
    {
        if (sprite->sTimer_expansion_intro % 16 == 0)
            LoadPalette(sSpritePal_PorygonShiny_expansion_intro, 0x10 * (16 + sprite->oam.paletteNum), 0x20);
        else
            LoadPalette(sSpritePal_Porygon_expansion_intro, 0x10 * (16 + sprite->oam.paletteNum), 0x20);
    }

    sprite->sTimer_expansion_intro++;
}

static void SpriteCallback_PorygonFlying_expansion_intro(struct Sprite* sprite)
{
    if (sprite->sTimer_expansion_intro >= PORYGON_WAIT_TIME_expansion_intro)
    {
        sprite->x2 += 6;

        if (sprite->sTimer_expansion_intro % 32 >= 16)
            sprite->y2--;
        else
            sprite->y2++;

        if (sprite->x2 >= PORYGON_COLLISION_POS_X_expansion_intro)
        {
            StartSpriteAnim(sprite, ANIM_PORY_HIT_expansion_intro);
            sprite->callback = SpriteCallback_PorygonHit_expansion_intro;
            sprite->sTimer_expansion_intro = 0;
            PlaySE(SE_M_DOUBLE_SLAP);
            PlayCryInternal(SPECIES_PORYGON, 0, 120, 10, 0);
        }
    }
    sprite->sTimer_expansion_intro++;
}
#undef sTimer_expansion_intro

