bool8 FldEff_PokecenterHeal(void)
{
    u32 nPokemon;
    struct Task *task;

    nPokemon = (OW_IGNORE_EGGS_ON_HEAL <= GEN_3) ? CalculatePlayerPartyCount() : CountPartyNonEggMons();
    task = &gTasks[CreateTask(Task_PokecenterHeal_field_effect, 0xff)];
    task->tNumMons_field_effect = nPokemon;
    task->tFirstBallX_field_effect = 93;
    task->tFirstBallY_field_effect = 36;
    task->tMonitorX_field_effect = 124;
    task->tMonitorY_field_effect = 24;
    return FALSE;
}

static void Task_PokecenterHeal_field_effect(u8 taskId)
{
    struct Task *task;
    task = &gTasks[taskId];
    sPokecenterHealEffectFuncs[task->tState_field_effect](task);
}

static void PokecenterHealEffect_Init_field_effect(struct Task *task)
{
    task->tState_field_effect++;
    task->tBallSpriteId_field_effect = CreateGlowingPokeballsEffect_field_effect(task->tNumMons_field_effect, task->tFirstBallX_field_effect, task->tFirstBallY_field_effect, TRUE);
    task->tMonitorSpriteId_field_effect = CreatePokecenterMonitorSprite_field_effect(task->tMonitorX_field_effect, task->tMonitorY_field_effect);
}

static void PokecenterHealEffect_WaitForBallPlacement_field_effect(struct Task *task)
{
    if (gSprites[task->tBallSpriteId_field_effect].sState_field_effect > 1)
    {
        gSprites[task->tMonitorSpriteId_field_effect].sState_field_effect++;
        task->tState_field_effect++;
    }
}

static void PokecenterHealEffect_WaitForBallFlashing_field_effect(struct Task *task)
{
    if (gSprites[task->tBallSpriteId_field_effect].sState_field_effect > 4)
    {
        task->tState_field_effect++;
    }
}

static void PokecenterHealEffect_WaitForSoundAndEnd_field_effect(struct Task *task)
{
    if (gSprites[task->tBallSpriteId_field_effect].sState_field_effect > 6)
    {
        DestroySprite(&gSprites[task->tBallSpriteId_field_effect]);
        FieldEffectActiveListRemove(FLDEFF_POKECENTER_HEAL);
        DestroyTask(FindTaskIdByFunc(Task_PokecenterHeal_field_effect));
    }
}

