{
    LockPlayerFieldControls();
    gPlayerAvatar.preventStep = TRUE;
    task->tState_field_effect++;
    return FALSE;
}

static bool8 WaterfallFieldEffect_ShowMon_field_effect(struct Task *task, struct ObjectEvent *objectEvent)
{
    LockPlayerFieldControls();
    if (!ObjectEventIsMovementOverridden(objectEvent))
    {
        ObjectEventClearHeldMovementIfFinished(objectEvent);
        gFieldEffectArguments[0] = task->tMonId_field_effect;
        FieldEffectStart(FLDEFF_FIELD_MOVE_SHOW_MON_INIT);
        task->tState_field_effect++;
    }
    return FALSE;
}

static bool8 WaterfallFieldEffect_WaitForShowMon_field_effect(struct Task *task, struct ObjectEvent *objectEvent)
{
    if (FieldEffectActiveListContains(FLDEFF_FIELD_MOVE_SHOW_MON))
    {
        return FALSE;
    }
    task->tState_field_effect++;
    return TRUE;
}

static bool8 WaterfallFieldEffect_RideUp_field_effect(struct Task *task, struct ObjectEvent *objectEvent)
{
    ObjectEventSetHeldMovement(objectEvent, GetWalkSlowMovementAction(DIR_NORTH));
    task->tState_field_effect++;
    return FALSE;
}

static bool8 WaterfallFieldEffect_ContinueRideOrEnd_field_effect(struct Task *task, struct ObjectEvent *objectEvent)
{
    if (!ObjectEventClearHeldMovementIfFinished(objectEvent))
        return FALSE;

    if (MetatileBehavior_IsWaterfall(objectEvent->currentMetatileBehavior))
    {
        // Still ascending waterfall, back to WaterfallFieldEffect_RideUp_field_effect
        task->tState_field_effect = 3;
        return TRUE;
    }

    UnlockPlayerFieldControls();
    gPlayerAvatar.preventStep = FALSE;
    DestroyTask(FindTaskIdByFunc(Task_UseWaterfall_field_effect));
    FieldEffectActiveListRemove(FLDEFF_USE_WATERFALL);
    return FALSE;
}

