#define tState_field_effect     data[0]
#define tSpinDelay_field_effect data[1]
#define tNumTurns_field_effect  data[2]
#define tTimer_field_effect     data[14]
#define tStartDir_field_effect  data[15]

void StartEscapeRopeFieldEffect(void)
{
    LockPlayerFieldControls();
    FreezeObjectEvents();
    HideFollowerForFieldEffect_field_effect(); // hide follower before warping
    CreateTask(Task_EscapeRopeWarpOut_field_effect, 80);
}

static void Task_EscapeRopeWarpOut_field_effect(u8 taskId)
{
    sEscapeRopeWarpOutEffectFuncs[gTasks[taskId].tState_field_effect](&gTasks[taskId]);
}

static void EscapeRopeWarpOutEffect_Init_field_effect(struct Task *task)
{
    task->tState_field_effect++;
    task->tTimer_field_effect = 64;
    task->tStartDir_field_effect = GetPlayerFacingDirection();
}

static void EscapeRopeWarpOutEffect_Spin_field_effect(struct Task *task)
{
    struct ObjectEvent *objectEvent;
    u8 spinDirections[5] =  {DIR_SOUTH, DIR_WEST, DIR_EAST, DIR_NORTH, DIR_SOUTH};
    if (task->tTimer_field_effect != 0 && (--task->tTimer_field_effect) == 0)
    {
        TryFadeOutOldMapMusic();
        WarpFadeOutScreen();
    }
    objectEvent = &gObjectEvents[gPlayerAvatar.objectEventId];
    if (!ObjectEventIsMovementOverridden(objectEvent) || ObjectEventClearHeldMovementIfFinished(objectEvent))
    {
        if (task->tTimer_field_effect == 0 && !gPaletteFade.active && BGMusicStopped() == TRUE)
        {
            SetObjectEventDirection(objectEvent, task->tStartDir_field_effect);
            SetWarpDestinationToEscapeWarp();
            WarpIntoMap();
            gFieldCallback = FieldCallback_EscapeRopeWarpIn_field_effect;
            SetMainCallback2(CB2_LoadMap);
            DestroyTask(FindTaskIdByFunc(Task_EscapeRopeWarpOut_field_effect));
        }
        else if (task->tSpinDelay_field_effect == 0 || (--task->tSpinDelay_field_effect) == 0)
        {
            ObjectEventSetHeldMovement(objectEvent, GetFaceDirectionMovementAction(spinDirections[objectEvent->facingDirection]));
            if (task->tNumTurns_field_effect < 12)
                task->tNumTurns_field_effect++;
            task->tSpinDelay_field_effect = 8 >> (task->tNumTurns_field_effect >> 2);
        }
    }
}

static void (*const sEscapeRopeWarpInEffectFuncs[])(struct Task *) = {
    EscapeRopeWarpInEffect_Init_field_effect,
    EscapeRopeWarpInEffect_Spin_field_effect
};

static void FieldCallback_EscapeRopeWarpIn_field_effect(void)
{
    Overworld_PlaySpecialMapMusic();
    WarpFadeInScreen();
    LockPlayerFieldControls();
    FreezeObjectEvents();
    gFieldCallback = NULL;
    gObjectEvents[gPlayerAvatar.objectEventId].invisible = TRUE;
    CreateTask(Task_EscapeRopeWarpIn_field_effect, 0);
}

static void Task_EscapeRopeWarpIn_field_effect(u8 taskId)
{
    sEscapeRopeWarpInEffectFuncs[gTasks[taskId].tState_field_effect](&gTasks[taskId]);
}

static void EscapeRopeWarpInEffect_Init_field_effect(struct Task *task)
{
    if (IsWeatherNotFadingIn())
    {
        task->tState_field_effect++;
        task->tStartDir_field_effect = GetPlayerFacingDirection();
    }
}

static void EscapeRopeWarpInEffect_Spin_field_effect(struct Task *task)
{
    u8 spinDirections[5] = {DIR_SOUTH, DIR_WEST, DIR_EAST, DIR_NORTH, DIR_SOUTH};
    struct ObjectEvent *objectEvent = &gObjectEvents[gPlayerAvatar.objectEventId];
    if (task->tSpinDelay_field_effect == 0 || (--task->tSpinDelay_field_effect) == 0)
    {
        if (ObjectEventIsMovementOverridden(objectEvent) && !ObjectEventClearHeldMovementIfFinished(objectEvent))
        {
            return;
        }
        if (task->tNumTurns_field_effect >= 32 && task->tStartDir_field_effect == GetPlayerFacingDirection())
        {
            objectEvent->invisible = FALSE;
            UnlockPlayerFieldControls();
            UnfreezeObjectEvents();
            DestroyTask(FindTaskIdByFunc(Task_EscapeRopeWarpIn_field_effect));
            return;
        }
        ObjectEventSetHeldMovement(objectEvent, GetFaceDirectionMovementAction(spinDirections[objectEvent->facingDirection]));
        if (task->tNumTurns_field_effect < 32)
            task->tNumTurns_field_effect++;
        task->tSpinDelay_field_effect = task->tNumTurns_field_effect >> 2;
    }
    objectEvent->invisible ^= 1;
}

#undef tState_field_effect
#undef tSpinDelay_field_effect
#undef tNumTurns_field_effect
#undef tTimer_field_effect
#undef tStartDir_field_effect

