static void (*const sFlyOutFieldEffectFuncs[])(struct Task *) = {
    FlyOutFieldEffect_FieldMovePose_field_effect,
    FlyOutFieldEffect_ShowMon_field_effect,
    FlyOutFieldEffect_BirdLeaveBall_field_effect,
    FlyOutFieldEffect_WaitBirdLeave_field_effect,
    FlyOutFieldEffect_BirdSwoopDown_field_effect,
    FlyOutFieldEffect_JumpOnBird_field_effect,
    FlyOutFieldEffect_FlyOffWithBird_field_effect,
    FlyOutFieldEffect_WaitFlyOff_field_effect,
    FlyOutFieldEffect_End_field_effect,
};

static void Task_FlyOut_field_effect(u8 taskId)
{
    sFlyOutFieldEffectFuncs[gTasks[taskId].tState_field_effect](&gTasks[taskId]);
}

static void FlyOutFieldEffect_FieldMovePose_field_effect(struct Task *task)
{
    struct ObjectEvent *objectEvent = &gObjectEvents[gPlayerAvatar.objectEventId];
    if (!ObjectEventIsMovementOverridden(objectEvent) || ObjectEventClearHeldMovementIfFinished(objectEvent))
    {
        task->tAvatarFlags_field_effect = gPlayerAvatar.flags;
        gPlayerAvatar.preventStep = TRUE;
        SetPlayerAvatarStateMask(PLAYER_AVATAR_FLAG_ON_FOOT);
        SetPlayerAvatarFieldMove();
        ObjectEventSetHeldMovement(objectEvent, MOVEMENT_ACTION_START_ANIM_IN_DIRECTION);
        task->tState_field_effect++;
    }
}

static void FlyOutFieldEffect_ShowMon_field_effect(struct Task *task)
{
    struct ObjectEvent *objectEvent = &gObjectEvents[gPlayerAvatar.objectEventId];
    if (ObjectEventClearHeldMovementIfFinished(objectEvent))
    {
        task->tState_field_effect++;
        gFieldEffectArguments[0] = task->tMonId_field_effect;
        if (!gSkipShowMonAnim)
            FieldEffectStart(FLDEFF_FIELD_MOVE_SHOW_MON_INIT);
    }
}

static void FlyOutFieldEffect_BirdLeaveBall_field_effect(struct Task *task)
{
    if (!FieldEffectActiveListContains(FLDEFF_FIELD_MOVE_SHOW_MON))
    {
        struct ObjectEvent *objectEvent = &gObjectEvents[gPlayerAvatar.objectEventId];
        if (task->tAvatarFlags_field_effect & PLAYER_AVATAR_FLAG_SURFING)
        {
            SetSurfBlob_BobState(objectEvent->fieldEffectSpriteId, BOB_JUST_MON);
            SetSurfBlob_DontSyncAnim(objectEvent->fieldEffectSpriteId, FALSE);
        }
        task->tBirdSpriteId_field_effect = CreateFlyBirdSprite_field_effect(); // Does "leave ball" animation by default
        task->tState_field_effect++;
    }
}

static void FlyOutFieldEffect_WaitBirdLeave_field_effect(struct Task *task)
{
    if (GetFlyBirdAnimCompleted_field_effect(task->tBirdSpriteId_field_effect))
    {
        task->tState_field_effect++;
        task->tTimer_field_effect = 16;
        SetPlayerAvatarTransitionFlags(PLAYER_AVATAR_FLAG_ON_FOOT);
        ObjectEventSetHeldMovement(&gObjectEvents[gPlayerAvatar.objectEventId], MOVEMENT_ACTION_FACE_LEFT);
    }
}

static void FlyOutFieldEffect_BirdSwoopDown_field_effect(struct Task *task)
{
    struct ObjectEvent *objectEvent = &gObjectEvents[gPlayerAvatar.objectEventId];
    if ((task->tTimer_field_effect == 0 || (--task->tTimer_field_effect) == 0) && ObjectEventClearHeldMovementIfFinished(objectEvent))
    {
        task->tState_field_effect++;
        PlaySE(SE_M_FLY);
        StartFlyBirdSwoopDown_field_effect(task->tBirdSpriteId_field_effect);
    }
}

static void FlyOutFieldEffect_JumpOnBird_field_effect(struct Task *task)
{
    if ((++task->tTimer_field_effect) >= 8)
    {
        struct ObjectEvent *objectEvent = &gObjectEvents[gPlayerAvatar.objectEventId];
        ObjectEventSetGraphicsId(objectEvent, GetPlayerAvatarGraphicsIdByStateId(PLAYER_AVATAR_STATE_SURFING));
        StartSpriteAnim(&gSprites[objectEvent->spriteId], ANIM_GET_ON_OFF_POKEMON_WEST);
        objectEvent->inanimate = TRUE;
        ObjectEventSetHeldMovement(objectEvent, MOVEMENT_ACTION_JUMP_IN_PLACE_LEFT);
        if (task->tAvatarFlags_field_effect & PLAYER_AVATAR_FLAG_SURFING)
        {
            DestroySprite(&gSprites[objectEvent->fieldEffectSpriteId]);
        }
        task->tState_field_effect++;
        task->tTimer_field_effect = 0;
    }
}

static void FlyOutFieldEffect_FlyOffWithBird_field_effect(struct Task *task)
{
    if ((++task->tTimer_field_effect) >= 10)
    {
        struct ObjectEvent *objectEvent = &gObjectEvents[gPlayerAvatar.objectEventId];
        ObjectEventClearHeldMovementIfActive(objectEvent);
        objectEvent->inanimate = FALSE;
        objectEvent->hasShadow = FALSE;
        SetFlyBirdPlayerSpriteId_field_effect(task->tBirdSpriteId_field_effect, objectEvent->spriteId);
        CameraObjectFreeze();
        task->tState_field_effect++;
    }
}

static void FlyOutFieldEffect_WaitFlyOff_field_effect(struct Task *task)
{
    if (GetFlyBirdAnimCompleted_field_effect(task->tBirdSpriteId_field_effect))
    {
        WarpFadeOutScreen();
        task->tState_field_effect++;
    }
}

static void FlyOutFieldEffect_End_field_effect(struct Task *task)
{
    if (!gPaletteFade.active)
    {
        FieldEffectActiveListRemove(FLDEFF_USE_FLY);
        DestroyTask(FindTaskIdByFunc(Task_FlyOut_field_effect));
    }
}

static u8 CreateFlyBirdSprite_field_effect(void)
{
    u8 spriteId;
    struct Sprite *sprite;
    spriteId = CreateSprite(gFieldEffectObjectTemplatePointers[FLDEFFOBJ_BIRD], 0xff, 0xb4, 0x1);
    sprite = &gSprites[spriteId];
    sprite->oam.paletteNum = LoadPlayerObjectEventPalette(gSaveBlock2Ptr->playerGender);
    sprite->oam.priority = 1;
    sprite->callback = SpriteCB_FlyBirdLeaveBall_field_effect;
    return spriteId;
}

static u8 GetFlyBirdAnimCompleted_field_effect(u8 spriteId)
{
    return gSprites[spriteId].sAnimCompleted_field_effect;
}

static void StartFlyBirdSwoopDown_field_effect(u8 spriteId)
{
    struct Sprite *sprite;
    sprite = &gSprites[spriteId];
    sprite->callback = SpriteCB_FlyBirdSwoopDown_field_effect;
    sprite->x = DISPLAY_WIDTH / 2;
    sprite->y = 0;
    sprite->x2 = 0;
    sprite->y2 = 0;
    memset(&sprite->data[0], 0, 8 * sizeof(u16) /* zero all data cells */);
    sprite->sPlayerSpriteId_field_effect = MAX_SPRITES;
}

static void SetFlyBirdPlayerSpriteId_field_effect(u8 birdSpriteId, u8 playerSpriteId)
{
    gSprites[birdSpriteId].sPlayerSpriteId_field_effect = playerSpriteId;
}

static const union AffineAnimCmd  sAffineAnim_FlyBirdLeaveBall_field_effect[] = {
    AFFINEANIMCMD_FRAME(8, 8, -30, 0),
    AFFINEANIMCMD_FRAME(28, 28, 0, 30),
    AFFINEANIMCMD_END
};

static const union AffineAnimCmd  sAffineAnim_FlyBirdReturnToBall_field_effect[] = {
    AFFINEANIMCMD_FRAME(256, 256, 64, 0),
    AFFINEANIMCMD_FRAME(-10, -10, 0, 22),
    AFFINEANIMCMD_END
};

static const union AffineAnimCmd *const  sAffineAnims_FlyBird_field_effect[] = {
    sAffineAnim_FlyBirdLeaveBall_field_effect,
    sAffineAnim_FlyBirdReturnToBall_field_effect
};

static void SpriteCB_FlyBirdLeaveBall_field_effect(struct Sprite *sprite)
{
    if (sprite->sAnimCompleted_field_effect == FALSE)
    {
        if (sprite->data[0] == 0)
        {
            sprite->oam.affineMode = ST_OAM_AFFINE_DOUBLE;
            sprite->affineAnims = sAffineAnims_FlyBird_field_effect;
            InitSpriteAffineAnim(sprite);
            StartSpriteAffineAnim(sprite, 0);
            sprite->x = 0x76;
            sprite->y = -0x30;
            sprite->data[0]++;
            sprite->data[1] = 0x40;
            sprite->data[2] = 0x100;
        }
        sprite->data[1] += (sprite->data[2] >> 8);
        sprite->x2 = Cos(sprite->data[1], 0x78);
        sprite->y2 = Sin(sprite->data[1], 0x78);
        if (sprite->data[2] < 0x800)
        {
            sprite->data[2] += 0x60;
        }
        if (sprite->data[1] > 0x81)
        {
            sprite->sAnimCompleted_field_effect++;
            sprite->oam.affineMode = ST_OAM_AFFINE_OFF;
            FreeOamMatrix(sprite->oam.matrixNum);
            CalcCenterToCornerVec(sprite, sprite->oam.shape, sprite->oam.size, ST_OAM_AFFINE_OFF);
        }
    }
}

static void SpriteCB_FlyBirdSwoopDown_field_effect(struct Sprite *sprite)
{
    sprite->x2 = Cos(sprite->data[2], 0x8c);
    sprite->y2 = Sin(sprite->data[2], 0x48);
    sprite->data[2] = (sprite->data[2] + 4) & 0xff;
    if (sprite->sPlayerSpriteId_field_effect != MAX_SPRITES)
    {
        struct Sprite *sprite1 = &gSprites[sprite->sPlayerSpriteId_field_effect];
        sprite1->coordOffsetEnabled = FALSE;
        sprite1->x = sprite->x + sprite->x2;
        sprite1->y = sprite->y + sprite->y2 - 8;
        sprite1->x2 = 0;
        sprite1->y2 = 0;
    }
    if (sprite->data[2] >= 0x80)
    {
        sprite->sAnimCompleted_field_effect = TRUE;
    }
}

static void SpriteCB_FlyBirdReturnToBall_field_effect(struct Sprite *sprite)
{
    if (sprite->sAnimCompleted_field_effect == FALSE)
    {
        if (sprite->data[0] == 0)
        {
            sprite->oam.affineMode = ST_OAM_AFFINE_DOUBLE;
            sprite->affineAnims = sAffineAnims_FlyBird_field_effect;
            InitSpriteAffineAnim(sprite);
            StartSpriteAffineAnim(sprite, 1);
            sprite->x = 0x5e;
            sprite->y = -0x20;
            sprite->data[0]++;
            sprite->data[1] = 0xf0;
            sprite->data[2] = 0x800;
            sprite->data[4] = 0x80;
        }
        sprite->data[1] += sprite->data[2] >> 8;
        sprite->data[3] += sprite->data[2] >> 8;
        sprite->data[1] &= 0xff;
        sprite->x2 = Cos(sprite->data[1], 0x20);
        sprite->y2 = Sin(sprite->data[1], 0x78);
        if (sprite->data[2] > 0x100)
        {
            sprite->data[2] -= sprite->data[4];
        }
        if (sprite->data[4] < 0x100)
        {
            sprite->data[4] += 24;
        }
        if (sprite->data[2] < 0x100)
        {
            sprite->data[2] = 0x100;
        }
        if (sprite->data[3] >= 60)
        {
            sprite->sAnimCompleted_field_effect++;
            sprite->oam.affineMode = ST_OAM_AFFINE_OFF;
            FreeOamMatrix(sprite->oam.matrixNum);
            sprite->invisible = TRUE;
        }
    }
}

static void StartFlyBirdReturnToBall_field_effect(u8 spriteId)
{
    StartFlyBirdSwoopDown_field_effect(spriteId); // Set up is the same, but overrwrites the callback below
    gSprites[spriteId].callback = SpriteCB_FlyBirdReturnToBall_field_effect;
}

u8 FldEff_FlyIn(void)
{
    CreateTask(Task_FlyIn_field_effect, 254);
    gSkipShowMonAnim = FALSE; // Clears this variable so flying via the party menu keeps the show mon animation
    return 0;
}

static void (*const sFlyInFieldEffectFuncs[])(struct Task *) = {
    FlyInFieldEffect_BirdSwoopDown_field_effect,
    FlyInFieldEffect_FlyInWithBird_field_effect,
    FlyInFieldEffect_JumpOffBird_field_effect,
    FlyInFieldEffect_FieldMovePose_field_effect,
    FlyInFieldEffect_BirdReturnToBall_field_effect,
    FlyInFieldEffect_WaitBirdReturn_field_effect,
    FlyInFieldEffect_End_field_effect,
};

static void Task_FlyIn_field_effect(u8 taskId)
{
    sFlyInFieldEffectFuncs[gTasks[taskId].tState_field_effect](&gTasks[taskId]);
}

static void FlyInFieldEffect_BirdSwoopDown_field_effect(struct Task *task)
{
    struct ObjectEvent *objectEvent;
    objectEvent = &gObjectEvents[gPlayerAvatar.objectEventId];
    if (!ObjectEventIsMovementOverridden(objectEvent) || ObjectEventClearHeldMovementIfFinished(objectEvent))
    {
        task->tState_field_effect++;
        task->tTimer_field_effect = 17;
        task->tAvatarFlags_field_effect = gPlayerAvatar.flags;
        gPlayerAvatar.preventStep = TRUE;
        SetPlayerAvatarStateMask(PLAYER_AVATAR_FLAG_ON_FOOT);
        if (task->tAvatarFlags_field_effect & PLAYER_AVATAR_FLAG_SURFING)
        {
            SetSurfBlob_BobState(objectEvent->fieldEffectSpriteId, BOB_NONE);
        }
        ObjectEventSetGraphicsId(objectEvent, GetPlayerAvatarGraphicsIdByStateId(PLAYER_AVATAR_STATE_SURFING));
        CameraObjectFreeze();
        ObjectEventTurn(objectEvent, DIR_WEST);
        StartSpriteAnim(&gSprites[objectEvent->spriteId], ANIM_GET_ON_OFF_POKEMON_WEST);
        objectEvent->invisible = FALSE;
        task->tBirdSpriteId_field_effect = CreateFlyBirdSprite_field_effect();
        StartFlyBirdSwoopDown_field_effect(task->tBirdSpriteId_field_effect);
        SetFlyBirdPlayerSpriteId_field_effect(task->tBirdSpriteId_field_effect, objectEvent->spriteId);
    }
}

static void FlyInFieldEffect_FlyInWithBird_field_effect(struct Task *task)
{
    struct ObjectEvent *objectEvent;
    struct Sprite *sprite;
    if (task->tTimer_field_effect == 0 || (--task->tTimer_field_effect) == 0)
    {
        objectEvent = &gObjectEvents[gPlayerAvatar.objectEventId];
        sprite = &gSprites[objectEvent->spriteId];
        SetFlyBirdPlayerSpriteId_field_effect(task->tBirdSpriteId_field_effect, MAX_SPRITES);
        sprite->x += sprite->x2;
        sprite->y += sprite->y2;
        sprite->x2 = 0;
        sprite->y2 = 0;
        task->tState_field_effect++;
        task->tTimer_field_effect = 0;
    }
}

static void FlyInFieldEffect_JumpOffBird_field_effect(struct Task *task)
{
    s16 sYPositions[18] = {
        -2,
        -4,
        -5,
        -6,
        -7,
        -8,
        -8,
        -8,
        -7,
        -7,
        -6,
        -5,
        -3,
        -2,
        0,
        2,
        4,
        8
    };
    struct Sprite *sprite = &gSprites[gPlayerAvatar.spriteId];
    sprite->y2 = sYPositions[task->tTimer_field_effect];

    if ((++task->tTimer_field_effect) >= (int)ARRAY_COUNT(sYPositions))
        task->tState_field_effect++;
}

static void FlyInFieldEffect_FieldMovePose_field_effect(struct Task *task)
{
    struct ObjectEvent *objectEvent;
    struct Sprite *sprite;
    if (GetFlyBirdAnimCompleted_field_effect(task->tBirdSpriteId_field_effect))
    {
        objectEvent = &gObjectEvents[gPlayerAvatar.objectEventId];
        sprite = &gSprites[objectEvent->spriteId];
        objectEvent->inanimate = FALSE;
        MoveObjectEventToMapCoords(objectEvent, objectEvent->currentCoords.x, objectEvent->currentCoords.y);
        sprite->x2 = 0;
        sprite->y2 = 0;
        sprite->coordOffsetEnabled = TRUE;
        SetPlayerAvatarFieldMove();
        ObjectEventSetHeldMovement(objectEvent, MOVEMENT_ACTION_START_ANIM_IN_DIRECTION);
        task->tState_field_effect++;
    }
}

static void FlyInFieldEffect_BirdReturnToBall_field_effect(struct Task *task)
{
    if (ObjectEventClearHeldMovementIfFinished(&gObjectEvents[gPlayerAvatar.objectEventId]))
    {
        task->tState_field_effect++;
        StartFlyBirdReturnToBall_field_effect(task->tBirdSpriteId_field_effect);
    }
}

static void FlyInFieldEffect_WaitBirdReturn_field_effect(struct Task *task)
{
    if (GetFlyBirdAnimCompleted_field_effect(task->tBirdSpriteId_field_effect))
    {
        DestroySprite(&gSprites[task->tBirdSpriteId_field_effect]);
        task->tState_field_effect++;
        task->data[1] = 16;
    }
}

static void FlyInFieldEffect_End_field_effect(struct Task *task)
{
    u8 state;
    struct ObjectEvent *objectEvent;
    if ((--task->data[1]) == 0)
    {
        objectEvent = &gObjectEvents[gPlayerAvatar.objectEventId];
        state = PLAYER_AVATAR_STATE_NORMAL;
        if (task->tAvatarFlags_field_effect & PLAYER_AVATAR_FLAG_SURFING)
        {
            state = PLAYER_AVATAR_STATE_SURFING;
            SetSurfBlob_BobState(objectEvent->fieldEffectSpriteId, BOB_PLAYER_AND_MON);
        }
        ObjectEventSetGraphicsId(objectEvent, GetPlayerAvatarGraphicsIdByStateId(state));
        ObjectEventTurn(objectEvent, DIR_SOUTH);
        gPlayerAvatar.flags = task->tAvatarFlags_field_effect;
        gPlayerAvatar.preventStep = FALSE;
        FieldEffectActiveListRemove(FLDEFF_FLY_IN);
        DestroyTask(FindTaskIdByFunc(Task_FlyIn_field_effect));
    }
}

