bool8 FldEff_DestroyDeoxysRock(void)
{
    u8 taskId;
    u8 objectEventId;
    if (!TryGetObjectEventIdByLocalIdAndMap(gFieldEffectArguments[0], gFieldEffectArguments[1], gFieldEffectArguments[2], &objectEventId))
    {
        taskId = CreateTask(Task_DestroyDeoxysRock_field_effect, 80);
        gTasks[taskId].tObjectEventId_field_effect = objectEventId;
        gTasks[taskId].tLocalId_field_effect = gFieldEffectArguments[0];
        gTasks[taskId].tMapNum_field_effect = gFieldEffectArguments[1];
        gTasks[taskId].tMapGroup_field_effect = gFieldEffectArguments[2];
    }
    else
    {
        FieldEffectActiveListRemove(FLDEFF_DESTROY_DEOXYS_ROCK);
    }
    return FALSE;
}

#define tShakeDelay_field_effect data[0]
#define tShakeUp_field_effect    data[1]
#define tShake_field_effect      data[5]
#define tEndDelay_field_effect   data[6]
#define tEnding_field_effect     data[7]

static void Task_DeoxysRockCameraShake_field_effect(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    if (tEnding_field_effect)
    {
        if (++tEndDelay_field_effect > 20)
        {
            tEndDelay_field_effect = 0;
            if (tShake_field_effect != 0)
                tShake_field_effect--;
        }
    }
    else
    {
        tShake_field_effect = 4;
    }

    if (++tShakeDelay_field_effect > 1)
    {
        tShakeDelay_field_effect = 0;

        if (++tShakeUp_field_effect & 1)
            SetCameraPanning(0, -tShake_field_effect);
        else
            SetCameraPanning(0, tShake_field_effect);
    }
    UpdateCameraPanning();
    if (tShake_field_effect == 0)
        DestroyTask(taskId);
}

static void StartEndingDeoxysRockCameraShake_field_effect(u8 taskId)
{
    gTasks[taskId].tEnding_field_effect = TRUE;
}

