static void CreateDeoxysRockFragments_field_effect(struct Sprite *sprite)
{
    int i;
    int xPos = (s16)gTotalCameraPixelOffsetX + sprite->x + sprite->x2;
    int yPos = (s16)gTotalCameraPixelOffsetY + sprite->y + sprite->y2 - 4;

    for (i = 0; i < 4; i++)
    {
        u8 spriteId = CreateSprite(&sSpriteTemplate_DeoxysRockFragment_field_effect, xPos, yPos, 0);
        if (spriteId != MAX_SPRITES)
        {
            StartSpriteAnim(&gSprites[spriteId], i);
            gSprites[spriteId].data[0] = i;
            gSprites[spriteId].oam.paletteNum = sprite->oam.paletteNum;
        }
    }
}

static void SpriteCB_DeoxysRockFragment_field_effect(struct Sprite *sprite)
{
    // 1 case for each fragment, fly off in 4 different directions
    switch (sprite->data[0])
    {
    case 0:
        sprite->x -= 16;
        sprite->y -= 12;
        break;
    case 1:
        sprite->x += 16;
        sprite->y -= 12;
        break;
    case 2:
        sprite->x -= 16;
        sprite->y += 12;
        break;
    case 3:
        sprite->x += 16;
        sprite->y += 12;
        break;
    }
    if (sprite->x < -4 || sprite->x > DISPLAY_WIDTH + 4 || sprite->y < -4 || sprite->y > DISPLAY_HEIGHT + 4)
        DestroySprite(sprite);
}

// Task data for Task_MoveDeoxysRock_field_effect
#define tState_field_effect      data[0]
#define tSpriteId_field_effect   data[1]
#define tTargetX_field_effect    data[2]
#define tTargetY_field_effect    data[3]
#define tCurX_field_effect       data[4]
#define tCurY_field_effect       data[5]
#define tVelocityX_field_effect  data[6]
#define tVelocityY_field_effect  data[7]
#define tMoveSteps_field_effect  data[8]
#define tObjEventId_field_effect data[9]

bool8 FldEff_MoveDeoxysRock(struct Sprite *sprite)
{
    u8 objectEventId;
    if (!TryGetObjectEventIdByLocalIdAndMap(gFieldEffectArguments[0], gFieldEffectArguments[1], gFieldEffectArguments[2], &objectEventId))
    {
        struct ObjectEvent *object;
        int xPos, yPos;
        u8 taskId;
        object = &gObjectEvents[objectEventId];
        xPos = object->currentCoords.x - MAP_OFFSET;
        yPos = object->currentCoords.y - MAP_OFFSET;
        xPos = (gFieldEffectArguments[3] - xPos) * 16;
        yPos = (gFieldEffectArguments[4] - yPos) * 16;
        ShiftObjectEventCoords(object, gFieldEffectArguments[3] + MAP_OFFSET, gFieldEffectArguments[4] + MAP_OFFSET);
        taskId = CreateTask(Task_MoveDeoxysRock_field_effect, 80);
        gTasks[taskId].tSpriteId_field_effect = object->spriteId;
        gTasks[taskId].tTargetX_field_effect = gSprites[object->spriteId].x + xPos;
        gTasks[taskId].tTargetY_field_effect = gSprites[object->spriteId].y + yPos;
        gTasks[taskId].tMoveSteps_field_effect = gFieldEffectArguments[5];
        gTasks[taskId].tObjEventId_field_effect = objectEventId;
    }
    return FALSE;
}

static void Task_MoveDeoxysRock_field_effect(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    struct Sprite *sprite = &gSprites[tSpriteId_field_effect];
    switch (tState_field_effect)
    {
        case 0:
            tCurX_field_effect = sprite->x << 4;
            tCurY_field_effect = sprite->y << 4;
            tVelocityX_field_effect = SAFE_DIV(tTargetX_field_effect * 16 - tCurX_field_effect, tMoveSteps_field_effect);
            tVelocityY_field_effect = SAFE_DIV(tTargetY_field_effect * 16 - tCurY_field_effect, tMoveSteps_field_effect);
            tState_field_effect++;
            // fallthrough
        case 1:
            if (tMoveSteps_field_effect != 0)
            {
                tMoveSteps_field_effect--;
                tCurX_field_effect += tVelocityX_field_effect;
                tCurY_field_effect += tVelocityY_field_effect;
                sprite->x = tCurX_field_effect >> 4;
                sprite->y = tCurY_field_effect >> 4;
            }
            else
            {
                struct ObjectEvent *object = &gObjectEvents[tObjEventId_field_effect];
                sprite->x = tTargetX_field_effect;
                sprite->y = tTargetY_field_effect;
                ShiftStillObjectEventCoords(object);
                object->triggerGroundEffectsOnStop = TRUE;
                FieldEffectActiveListRemove(FLDEFF_MOVE_DEOXYS_ROCK);
                DestroyTask(taskId);
            }
            break;
    }
}

u8 FldEff_CaveDust(void)
{
    u8 spriteId;
    
    SetSpritePosToOffsetMapCoords((s16 *)&gFieldEffectArguments[0], (s16 *)&gFieldEffectArguments[1], 8, 8);
    spriteId = CreateSpriteAtEnd(gFieldEffectObjectTemplatePointers[FLDEFFOBJ_CAVE_DUST], gFieldEffectArguments[0], gFieldEffectArguments[1], 0xFF);
    if (spriteId != MAX_SPRITES)
    {
        gSprites[spriteId].coordOffsetEnabled = TRUE;
        gSprites[spriteId].data[0] = 22;
    }
    
    return spriteId;
}

