{
    sUseVsSeekerEffectFuncs[gTasks[taskId].data[0]](&gTasks[taskId]);
}

static void UseVsSeeker_StopPlayerMovement_field_effect(struct Task *task)
{
    LockPlayerFieldControls();
    FreezeObjectEvents();
    gPlayerAvatar.preventStep = TRUE;
    task->data[0]++;
}

static void UseVsSeeker_DoPlayerAnimation_field_effect(struct Task *task)
{
    struct ObjectEvent * playerObj = &gObjectEvents[gPlayerAvatar.objectEventId];
    if ((ObjectEventIsMovementOverridden(playerObj) && (!(ObjectEventClearHeldMovementIfFinished(playerObj)))))
        return;

    if (gMapHeader.mapType != MAP_TYPE_UNDERWATER)
    {
        SetPlayerAvatarFieldMove();
        ObjectEventSetHeldMovement(playerObj, MOVEMENT_ACTION_START_ANIM_IN_DIRECTION);
    }
    task->data[0]++;
}

static void UseVsSeeker_ResetPlayerGraphics_field_effect(struct Task *task)
{
    struct ObjectEvent* playerObj = &gObjectEvents[gPlayerAvatar.objectEventId];

    if (!ObjectEventClearHeldMovementIfFinished(playerObj))
        return;

    if (gMapHeader.mapType != MAP_TYPE_UNDERWATER)
    {
        ObjectEventSetGraphicsId(&gObjectEvents[gPlayerAvatar.objectEventId], GetPlayerAvatarGraphicsIdByCurrentState());
        ObjectEventForceSetHeldMovement(playerObj, GetFaceDirectionMovementAction(playerObj->facingDirection));
    }
    task->data[0]++;
}

static void UseVsSeeker_CleanUpFieldEffect_field_effect(struct Task *task)
{
    struct ObjectEvent * playerObj = &gObjectEvents[gPlayerAvatar.objectEventId];
    if (!ObjectEventClearHeldMovementIfFinished(playerObj))
        return;

    gPlayerAvatar.preventStep = FALSE;
    FieldEffectActiveListRemove(FLDEFF_USE_VS_SEEKER);
    DestroyTask(FindTaskIdByFunc(Task_FldEffUseVsSeeker_field_effect));
}
