#define OBJ_EVENT_PAL_TAG_NONE_field_effect_helpers 0x11FF // duplicate of define in event_object_movement.c
#define PAL_TAG_REFLECTION_OFFSET_field_effect_helpers 0x2000 // reflection tag value is paletteTag + 0x2000
#define PAL_RAW_REFLECTION_OFFSET_field_effect_helpers 0x4000 // raw reflection tag is paletteNum + 0x4000
#define HIGH_BRIDGE_PAL_TAG_field_effect_helpers 0x4010
// Build a unique tag for reflection's palette based on based tag, or paletteNum
#define REFLECTION_PAL_TAG_field_effect_helpers(tag, num) ((tag) == TAG_NONE ? (num) + PAL_RAW_REFLECTION_OFFSET_field_effect_helpers : (tag) + PAL_TAG_REFLECTION_OFFSET_field_effect_helpers)

static void UpdateObjectReflectionSprite_field_effect_helpers(struct Sprite *);
static void LoadObjectReflectionPalette_field_effect_helpers(struct ObjectEvent *objectEvent, struct Sprite *sprite);
static void LoadObjectHighBridgeReflectionPalette_field_effect_helpers(struct ObjectEvent *, struct Sprite *sprite);
static void LoadObjectRegularReflectionPalette_field_effect_helpers(struct ObjectEvent *, struct Sprite *);

static void UpdateGrassFieldEffectSubpriority_field_effect_helpers(struct Sprite *, u8, u8);
static void FadeFootprintsTireTracks_Step0_field_effect_helpers(struct Sprite *);
static void FadeFootprintsTireTracks_Step1_field_effect_helpers(struct Sprite *);
static void UpdateFeetInFlowingWaterFieldEffect_field_effect_helpers(struct Sprite *);
static void UpdateAshFieldEffect_Wait_field_effect_helpers(struct Sprite *);
static void UpdateAshFieldEffect_Show_field_effect_helpers(struct Sprite *);
static void UpdateAshFieldEffect_End_field_effect_helpers(struct Sprite *);
static void SynchroniseSurfAnim_field_effect_helpers(struct ObjectEvent *, struct Sprite *);
static void SynchroniseSurfPosition(struct ObjectEvent *, struct Sprite *);
static void UpdateBobbingEffect_field_effect_helpers(struct ObjectEvent *, struct Sprite *, struct Sprite *);
static void SpriteCB_UnderwaterSurfBlob_field_effect_helpers(struct Sprite *);
static u32 ShowDisguiseFieldEffect_field_effect_helpers(u8, u8, u8);
u32 FldEff_Shadow(void);

// Data used by all the field effects that share UpdateJumpImpactEffect
#define sJumpElevation_field_effect_helpers  data[0]
#define sJumpFldEff_field_effect_helpers     data[1]

// Data used by all the field effects that share WaitFieldEffectSpriteAnim
#define sWaitFldEff_field_effect_helpers  data[0]

#define sReflectionObjEventId_field_effect_helpers       data[0]
#define sReflectionObjEventLocalId_field_effect_helpers  data[1]
#define sReflectionVerticalOffset_field_effect_helpers   data[2]
#define sIsStillReflection_field_effect_helpers          data[7]

void SetUpShadow(struct ObjectEvent *objectEvent, struct Sprite *sprite)
{
    gFieldEffectArguments[0] = objectEvent->localId;
    gFieldEffectArguments[1] = gSaveBlock1Ptr->location.mapNum;
    gFieldEffectArguments[2] = gSaveBlock1Ptr->location.mapGroup;
    FldEff_Shadow();
}

void SetUpReflection(struct ObjectEvent *objectEvent, struct Sprite *sprite, bool8 stillReflection)
{
    struct Sprite *reflectionSprite;

    reflectionSprite = &gSprites[CreateCopySpriteAt(sprite, sprite->x, sprite->y, 152)];
    reflectionSprite->callback = UpdateObjectReflectionSprite_field_effect_helpers;
    reflectionSprite->oam.priority = 3;
    reflectionSprite->usingSheet = TRUE;
    reflectionSprite->anims = gDummySpriteAnimTable;
    StartSpriteAnim(reflectionSprite, 0);
    reflectionSprite->affineAnims = gDummySpriteAffineAnimTable;
    reflectionSprite->affineAnimBeginning = TRUE;
    reflectionSprite->subspriteMode = SUBSPRITES_IGNORE_PRIORITY;
    reflectionSprite->subspriteTableNum = 0;
    reflectionSprite->sReflectionObjEventId_field_effect_helpers = sprite->sReflectionObjEventId_field_effect_helpers;
    reflectionSprite->sReflectionObjEventLocalId_field_effect_helpers = objectEvent->localId;
    reflectionSprite->sIsStillReflection_field_effect_helpers = stillReflection;
    LoadObjectReflectionPalette_field_effect_helpers(objectEvent, reflectionSprite);

    if (!stillReflection)
        reflectionSprite->oam.affineMode = ST_OAM_AFFINE_NORMAL;
}

static s16 GetReflectionVerticalOffset_field_effect_helpers(struct ObjectEvent *objectEvent)
{
    return GetObjectEventGraphicsInfo(objectEvent->graphicsId)->height - 2;
}

static void LoadObjectReflectionPalette_field_effect_helpers(struct ObjectEvent *objectEvent, struct Sprite *reflectionSprite)
{
    u8 bridgeType;
    u16 bridgeReflectionVerticalOffsets[] = {
        [BRIDGE_TYPE_POND_LOW - 1] = 12,
        [BRIDGE_TYPE_POND_MED - 1] = 28,
        [BRIDGE_TYPE_POND_HIGH - 1] = 44
    };
    reflectionSprite->sReflectionVerticalOffset_field_effect_helpers = 0;
    if ((bridgeType = MetatileBehavior_GetBridgeType(objectEvent->previousMetatileBehavior))
        || (bridgeType = MetatileBehavior_GetBridgeType(objectEvent->currentMetatileBehavior)))
    {
        reflectionSprite->sReflectionVerticalOffset_field_effect_helpers = bridgeReflectionVerticalOffsets[bridgeType - 1];
        LoadObjectHighBridgeReflectionPalette_field_effect_helpers(objectEvent, reflectionSprite);
    }
    else
    {
        LoadObjectRegularReflectionPalette_field_effect_helpers(objectEvent, reflectionSprite);
    }
}

// Apply a blue tint effect to a palette
static void ApplyPondFilter_field_effect_helpers(u8 paletteNum, u16 *dest)
{
    u32 i, r, g, b;
    // CpuCopy16(gPlttBufferUnfaded + 0x100 + paletteNum * 16, dest, 32);
    u16 *src = gPlttBufferUnfaded + OBJ_PLTT_ID(paletteNum);
    *dest++ = *src++; // copy transparency
    for (i = 0; i < 16 - 1; i++)
    {
        r = GET_R(src[i]);
        g = GET_G(src[i]);
        b = GET_B(src[i]);
        b += 10;
        if (b > 31)
            b = 31;
        *dest++ = RGB2(r, g, b);
    }
}

// Apply a ice tint effect to a palette
static void ApplyIceFilter_field_effect_helpers(u8 paletteNum, u16 *dest)
{
    u32 i, r, g, b;
    // CpuCopy16(gPlttBufferUnfaded + 0x100 + paletteNum * 16, dest, 32);
    u16 *src = gPlttBufferUnfaded + OBJ_PLTT_ID(paletteNum);
    *dest++ = *src++; // copy transparency
    for (i = 0; i < 16 - 1; i++)
    {
        r = GET_R(src[i]);
        r -= 5;
        if (r > 31)
            r = 0;
        g = GET_G(src[i]);
        g += 3;
        if (g > 31)
            g = 31;
        b = GET_B(src[i]);
        b += 16;
        if (b > 31)
            b = 31;
        *dest++ = RGB2(r, g, b);
    }
}

static void LoadObjectRegularReflectionPalette_field_effect_helpers(struct ObjectEvent *objectEvent, struct Sprite *sprite)
{
    const struct Sprite *mainSprite = &gSprites[objectEvent->spriteId];
    u16 baseTag = GetSpritePaletteTagByPaletteNum(mainSprite->oam.paletteNum);
    u16 paletteTag = REFLECTION_PAL_TAG_field_effect_helpers(baseTag, mainSprite->oam.paletteNum);
    u8 paletteNum = IndexOfSpritePaletteTag(paletteTag);
    if (paletteNum <= 16)
    {
        // Load filtered palette
        u16 filteredData[16];
        struct SpritePalette filteredPal = {.tag = paletteTag, .data = filteredData};
        if (sprite->sIsStillReflection_field_effect_helpers == FALSE)
            ApplyPondFilter_field_effect_helpers(mainSprite->oam.paletteNum, filteredData);
        else
            ApplyIceFilter_field_effect_helpers(mainSprite->oam.paletteNum, filteredData);
        paletteNum = LoadSpritePalette(&filteredPal);
        UpdateSpritePaletteWithWeather(paletteNum);
    }
    sprite->oam.paletteNum = paletteNum;
    sprite->oam.objMode = ST_OAM_OBJ_BLEND;
}

// When walking on a bridge high above water (Route 120), the reflection is a solid dark blue color.
// This is so the sprite blends in with the dark water metatile underneath the bridge.
static void LoadObjectHighBridgeReflectionPalette_field_effect_helpers(struct ObjectEvent *objectEvent, struct Sprite *sprite)
{
    u16 blueData[16];
    struct SpritePalette bluePalette = {.tag = HIGH_BRIDGE_PAL_TAG_field_effect_helpers, .data = blueData};
    CpuFill16(0x55C9, blueData, PLTT_SIZE_4BPP);
    sprite->oam.paletteNum = LoadSpritePalette(&bluePalette);
    UpdateSpritePaletteWithWeather(sprite->oam.paletteNum);
}

static void UpdateObjectReflectionSprite_field_effect_helpers(struct Sprite *reflectionSprite)
{
    struct ObjectEvent *objectEvent = &gObjectEvents[reflectionSprite->sReflectionObjEventId_field_effect_helpers];
    struct Sprite *mainSprite = &gSprites[objectEvent->spriteId];

    if (!objectEvent->active || !objectEvent->hasReflection || objectEvent->localId != reflectionSprite->sReflectionObjEventLocalId_field_effect_helpers)
    {
        reflectionSprite->inUse = FALSE;
        FieldEffectFreePaletteIfUnused(reflectionSprite->oam.paletteNum);
        return;
    }

    // Only filter palette if not using the high bridge blue palette
    // This is basically a copy of LoadObjectRegularReflectionPalette_field_effect_helpers
    if (IndexOfSpritePaletteTag(HIGH_BRIDGE_PAL_TAG_field_effect_helpers) != reflectionSprite->oam.paletteNum)
    {
        u16 baseTag = GetSpritePaletteTagByPaletteNum(mainSprite->oam.paletteNum);
        u16 paletteTag = REFLECTION_PAL_TAG_field_effect_helpers(baseTag, mainSprite->oam.paletteNum);
        u8 paletteNum = IndexOfSpritePaletteTag(paletteTag);
        if (paletteNum >= 16)
        {
            // Build filtered palette
            u16 filteredData[16];
            struct SpritePalette filteredPal = {.tag = paletteTag, .data = filteredData};
            // Free palette if unused
            reflectionSprite->inUse = FALSE;
            FieldEffectFreePaletteIfUnused(reflectionSprite->oam.paletteNum);
            reflectionSprite->inUse = TRUE;
            if (reflectionSprite->sIsStillReflection_field_effect_helpers == FALSE)
                ApplyPondFilter_field_effect_helpers(mainSprite->oam.paletteNum, filteredData);
            else
                ApplyIceFilter_field_effect_helpers(mainSprite->oam.paletteNum, filteredData);
            paletteNum = LoadSpritePalette(&filteredPal);
            UpdateSpritePaletteWithWeather(paletteNum);
        }
        reflectionSprite->oam.paletteNum = paletteNum;
    }
    reflectionSprite->oam.shape = mainSprite->oam.shape;
    reflectionSprite->oam.size = mainSprite->oam.size;
    reflectionSprite->oam.matrixNum = mainSprite->oam.matrixNum | ST_OAM_VFLIP;
    reflectionSprite->oam.tileNum = mainSprite->oam.tileNum;
    reflectionSprite->subspriteTables = mainSprite->subspriteTables;
    reflectionSprite->invisible = mainSprite->invisible;
    reflectionSprite->x = mainSprite->x;
    // sReflectionVerticalOffset_field_effect_helpers is only set for high bridges
    reflectionSprite->y = mainSprite->y + GetReflectionVerticalOffset_field_effect_helpers(objectEvent) + reflectionSprite->sReflectionVerticalOffset_field_effect_helpers;
    reflectionSprite->centerToCornerVecX = mainSprite->centerToCornerVecX;
    reflectionSprite->centerToCornerVecY = mainSprite->centerToCornerVecY;
    reflectionSprite->x2 = mainSprite->x2;
    reflectionSprite->y2 = -mainSprite->y2;
    reflectionSprite->coordOffsetEnabled = mainSprite->coordOffsetEnabled;

    if (objectEvent->hideReflection == TRUE)
        reflectionSprite->invisible = TRUE;

    // Support "virtual" sprites which can't be rotated via affines
    if (reflectionSprite->subspriteTables[0].subsprites)
    {
        reflectionSprite->oam.affineMode = ST_OAM_AFFINE_OFF;
        return;
    }
    if (reflectionSprite->sIsStillReflection_field_effect_helpers == FALSE)
    {
        // Sets the reflection sprite's rot/scale matrix to the correct
        // water reflection matrix based on the main sprite's facing direction.
        // If the sprite is facing east, then it's flipped, and its matrixNum is 1.
        reflectionSprite->oam.matrixNum = (mainSprite->oam.matrixNum & ST_OAM_HFLIP) ? 1 : 0;
    }
}

#undef sReflectionObjEventId_field_effect_helpers
#undef sReflectionObjEventLocalId_field_effect_helpers
#undef sReflectionVerticalOffset_field_effect_helpers
#undef sIsStillReflection_field_effect_helpers

extern const struct SpriteTemplate *const gFieldEffectObjectTemplatePointers[];

#define sPrevX_field_effect_helpers data[0]
#define sPrevY_field_effect_helpers data[1]

u8 CreateWarpArrowSprite(void)
{
    u8 spriteId = CreateSpriteAtEnd(gFieldEffectObjectTemplatePointers[FLDEFFOBJ_ARROW], 0, 0, 82);
    if (spriteId != MAX_SPRITES)
    {
        struct Sprite *sprite = &gSprites[spriteId];
        // Can use either gender's palette, so try to use the one that should be loaded
        sprite->oam.paletteNum = LoadPlayerObjectEventPalette(gSaveBlock2Ptr->playerGender);
        sprite->oam.priority = 1;
        sprite->coordOffsetEnabled = TRUE;
        sprite->invisible = TRUE;
    }
    return spriteId;
}

void SetSpriteInvisible(u8 spriteId)
{
    gSprites[spriteId].invisible = TRUE;
}

void ShowWarpArrowSprite(u8 spriteId, u8 direction, s16 x, s16 y)
{
    struct Sprite *sprite = &gSprites[spriteId];
    if (sprite->invisible || sprite->sPrevX_field_effect_helpers != x || sprite->sPrevY_field_effect_helpers != y)
    {
        s16 x2, y2;
        SetSpritePosToMapCoords(x, y, &x2, &y2);
        sprite = &gSprites[spriteId];
        sprite->x = x2 + 8;
        sprite->y = y2 + 8;
        sprite->invisible = FALSE;
        sprite->sPrevX_field_effect_helpers = x;
        sprite->sPrevY_field_effect_helpers = y;
        StartSpriteAnim(sprite, direction - 1);
    }
}

