#undef sPrevY_field_effect_helpers

static const u8  sShadowEffectTemplateIds_field_effect_helpers[] = {
    FLDEFFOBJ_SHADOW_S,
    FLDEFFOBJ_SHADOW_M,
    FLDEFFOBJ_SHADOW_L,
    FLDEFFOBJ_SHADOW_XL
};

const u16 gShadowVerticalOffsets[] = {
    4,
    4,
    4,
    16
};

// Sprite data for FLDEFF_SHADOW
#define sLocalId_field_effect_helpers  data[0]
#define sMapNum_field_effect_helpers   data[1]
#define sMapGroup_field_effect_helpers data[2]
#define sYOffset_field_effect_helpers  data[3]

u32 FldEff_Shadow(void)
{
    u8 objectEventId;
    const struct ObjectEventGraphicsInfo *graphicsInfo;
    u8 spriteId;
    u8 i;
    for (i = 0; i < MAX_SPRITES; i++)
    {
        // Return early if a shadow sprite already exists
        if (gSprites[i].data[0] == gFieldEffectArguments[0] && gSprites[i].callback == UpdateShadowFieldEffect)
            return 0;
    }
    objectEventId = GetObjectEventIdByLocalIdAndMap(gFieldEffectArguments[0], gFieldEffectArguments[1], gFieldEffectArguments[2]);
    graphicsInfo = GetObjectEventGraphicsInfo(gObjectEvents[objectEventId].graphicsId);
    if (graphicsInfo->shadowSize == SHADOW_SIZE_NONE) // don't create a shadow at all
        return 0;
    spriteId = CreateSpriteAtEnd(gFieldEffectObjectTemplatePointers[sShadowEffectTemplateIds_field_effect_helpers[graphicsInfo->shadowSize]], 0, 0, 0x94);
    if (spriteId != MAX_SPRITES)
    {
        // SetGpuReg(REG_OFFSET_BLDALPHA, BLDALPHA_BLEND(8, 12));
        gSprites[spriteId].oam.objMode = 1; // BLEND
        gSprites[spriteId].coordOffsetEnabled = TRUE;
        gSprites[spriteId].sLocalId_field_effect_helpers = gFieldEffectArguments[0];
        gSprites[spriteId].sMapNum_field_effect_helpers = gFieldEffectArguments[1];
        gSprites[spriteId].sMapGroup_field_effect_helpers = gFieldEffectArguments[2];
        #if OW_LARGE_OW_SUPPORT
        gSprites[spriteId].sYOffset_field_effect_helpers = gShadowVerticalOffsets[graphicsInfo->shadowSize];
        #else
        gSprites[spriteId].sYOffset_field_effect_helpers = (graphicsInfo->height >> 1) - gShadowVerticalOffsets[graphicsInfo->shadowSize];
        #endif
    }
    return 0;
}

void UpdateShadowFieldEffect(struct Sprite *sprite)
{
    u8 objectEventId;

    if (TryGetObjectEventIdByLocalIdAndMap(sprite->sLocalId_field_effect_helpers, sprite->sMapNum_field_effect_helpers, sprite->sMapGroup_field_effect_helpers, &objectEventId))
    {
        FieldEffectStop(sprite, FLDEFF_SHADOW);
    }
    else
    {
        struct ObjectEvent *objectEvent = &gObjectEvents[objectEventId];
        struct Sprite *linkedSprite = &gSprites[objectEvent->spriteId];
        sprite->oam.priority = linkedSprite->oam.priority;
        sprite->x = linkedSprite->x;
        #if OW_LARGE_OW_SUPPORT
        // Read 'live' size from linked sprite
        sprite->y = linkedSprite->y - linkedSprite->centerToCornerVecY - sprite->sYOffset_field_effect_helpers;
        #else
        sprite->y = linkedSprite->y + sprite->sYOffset_field_effect_helpers;
        #endif
        sprite->invisible = linkedSprite->invisible;
        if (!objectEvent->active || !objectEvent->hasShadow
         || MetatileBehavior_IsPokeGrass(objectEvent->currentMetatileBehavior)
         || MetatileBehavior_IsSurfableWaterOrUnderwater(objectEvent->currentMetatileBehavior)
         || MetatileBehavior_IsSurfableWaterOrUnderwater(objectEvent->previousMetatileBehavior))
        {
            FieldEffectStop(sprite, FLDEFF_SHADOW);
        }
    }
}

#undef sLocalId_field_effect_helpers
#undef sMapNum_field_effect_helpers
#undef sMapGroup_field_effect_helpers
#undef sYOffset_field_effect_helpers

