#define sElevation_field_effect_helpers   data[0]
#define sX_field_effect_helpers           data[1]
#define sY_field_effect_helpers           data[2]
#define sMapNum_field_effect_helpers      data[3]      // Lower 8 bits
#define sLocalId_field_effect_helpers     data[3] >> 8 // Upper 8 bits
#define sMapGroup_field_effect_helpers    data[4]
#define sCurrentMap_field_effect_helpers  data[5]
#define sObjectMoved_field_effect_helpers data[7]

u32 FldEff_TallGrass(void)
{
    u8 spriteId;
    s16 x = gFieldEffectArguments[0];
    s16 y = gFieldEffectArguments[1];
    SetSpritePosToOffsetMapCoords(&x, &y, 8, 8);
    spriteId = CreateSpriteAtEnd(gFieldEffectObjectTemplatePointers[FLDEFFOBJ_TALL_GRASS], x, y, 0);
    if (spriteId != MAX_SPRITES)
    {
        struct Sprite *sprite = &gSprites[spriteId];
        sprite->coordOffsetEnabled = TRUE;
        sprite->oam.priority = gFieldEffectArguments[3];
        sprite->sElevation_field_effect_helpers = gFieldEffectArguments[2];
        sprite->sX_field_effect_helpers = gFieldEffectArguments[0];
        sprite->sY_field_effect_helpers = gFieldEffectArguments[1];
        sprite->sMapNum_field_effect_helpers = gFieldEffectArguments[4]; // Also sLocalId_field_effect_helpers
        sprite->sMapGroup_field_effect_helpers = gFieldEffectArguments[5];
        sprite->sCurrentMap_field_effect_helpers = gFieldEffectArguments[6];

        if (gFieldEffectArguments[7])
            SeekSpriteAnim(sprite, 4); // Skip to end of anim
    }
    return 0;
}

void UpdateTallGrassFieldEffect(struct Sprite *sprite)
{
    u8 metatileBehavior;
    u8 localId;
    u8 objectEventId;
    u8 mapNum = sprite->sCurrentMap_field_effect_helpers >> 8;
    u8 mapGroup = sprite->sCurrentMap_field_effect_helpers;

    if (gCamera.active && (gSaveBlock1Ptr->location.mapNum != mapNum || gSaveBlock1Ptr->location.mapGroup != mapGroup))
    {
        sprite->sX_field_effect_helpers -= gCamera.x;
        sprite->sY_field_effect_helpers -= gCamera.y;
        sprite->sCurrentMap_field_effect_helpers = ((u8)gSaveBlock1Ptr->location.mapNum << 8) | (u8)gSaveBlock1Ptr->location.mapGroup;
    }
    localId = sprite->sLocalId_field_effect_helpers;
    mapNum = sprite->sMapNum_field_effect_helpers;
    mapGroup = sprite->sMapGroup_field_effect_helpers;
    metatileBehavior = MapGridGetMetatileBehaviorAt(sprite->sX_field_effect_helpers, sprite->sY_field_effect_helpers);

    if (TryGetObjectEventIdByLocalIdAndMap(localId, mapNum, mapGroup, &objectEventId)
     || !MetatileBehavior_IsTallGrass(metatileBehavior)
     || (sprite->sObjectMoved_field_effect_helpers && sprite->animEnded))
    {
        FieldEffectStop(sprite, FLDEFF_TALL_GRASS);
    }
    else
    {
        // Check if the object that triggered the effect has moved away
        struct ObjectEvent *objectEvent = &gObjectEvents[objectEventId];
        if ((objectEvent->currentCoords.x != sprite->sX_field_effect_helpers || objectEvent->currentCoords.y != sprite->sY_field_effect_helpers)
        && (objectEvent->previousCoords.x != sprite->sX_field_effect_helpers || objectEvent->previousCoords.y != sprite->sY_field_effect_helpers))
            sprite->sObjectMoved_field_effect_helpers = TRUE;

        // Metatile behavior var re-used as subpriority
        metatileBehavior = 0;
        if (sprite->animCmdIndex == 0)
            metatileBehavior = 4;

        UpdateObjectEventSpriteInvisibility(sprite, FALSE);
        UpdateGrassFieldEffectSubpriority_field_effect_helpers(sprite, sprite->sElevation_field_effect_helpers, metatileBehavior);
    }
}

