        sprite->sX_field_effect_helpers = gFieldEffectArguments[0];
        sprite->sY_field_effect_helpers = gFieldEffectArguments[1];
        sprite->sMapNum_field_effect_helpers = gFieldEffectArguments[4]; // Also sLocalId_field_effect_helpers
        sprite->sMapGroup_field_effect_helpers = gFieldEffectArguments[5];
