void UpdateLongGrassFieldEffect(struct Sprite *sprite)
{
    u8 metatileBehavior;
    u8 localId;
    u8 objectEventId;
    u8 mapNum = sprite->sCurrentMap_field_effect_helpers >> 8;
    u8 mapGroup = sprite->sCurrentMap_field_effect_helpers;

    if (gCamera.active && (gSaveBlock1Ptr->location.mapNum != mapNum || gSaveBlock1Ptr->location.mapGroup != mapGroup))
    {
        sprite->sX_field_effect_helpers -= gCamera.x;
        sprite->sY_field_effect_helpers -= gCamera.y;
        sprite->sCurrentMap_field_effect_helpers = ((u8)gSaveBlock1Ptr->location.mapNum << 8) | (u8)gSaveBlock1Ptr->location.mapGroup;
    }
    localId = sprite->sLocalId_field_effect_helpers;
    mapNum = sprite->sMapNum_field_effect_helpers;
    mapGroup = sprite->sMapGroup_field_effect_helpers;
    metatileBehavior = MapGridGetMetatileBehaviorAt(sprite->sX_field_effect_helpers, sprite->sY_field_effect_helpers);
    if (TryGetObjectEventIdByLocalIdAndMap(localId, mapNum, mapGroup, &objectEventId)
     || !MetatileBehavior_IsLongGrass(metatileBehavior)
     || (sprite->sObjectMoved_field_effect_helpers && sprite->animEnded))
    {
        FieldEffectStop(sprite, FLDEFF_LONG_GRASS);
    }
    else
    {
        // Check if the object that triggered the effect has moved away
        struct ObjectEvent *objectEvent = &gObjectEvents[objectEventId];
        if ((objectEvent->currentCoords.x != sprite->sX_field_effect_helpers || objectEvent->currentCoords.y != sprite->sY_field_effect_helpers)
         && (objectEvent->previousCoords.x != sprite->sX_field_effect_helpers || objectEvent->previousCoords.y != sprite->sY_field_effect_helpers))
            sprite->sObjectMoved_field_effect_helpers = TRUE;

        UpdateObjectEventSpriteInvisibility(sprite, FALSE);
        UpdateGrassFieldEffectSubpriority_field_effect_helpers(sprite, sprite->sElevation_field_effect_helpers, 0);
    }
}

