void (*const gFadeFootprintsTireTracksFuncs[])(struct Sprite *) = {
    FadeFootprintsTireTracks_Step0_field_effect_helpers,
    FadeFootprintsTireTracks_Step1_field_effect_helpers
};

void UpdateFootprintsTireTracksFieldEffect(struct Sprite *sprite)
{
    gFadeFootprintsTireTracksFuncs[sprite->sState_field_effect_helpers](sprite);
}

static void FadeFootprintsTireTracks_Step0_field_effect_helpers(struct Sprite *sprite)
{
    // Wait 40 frames before the flickering starts.
    if (++sprite->sTimer_field_effect_helpers > 40)
        sprite->sState_field_effect_helpers = 1;

    UpdateObjectEventSpriteInvisibility(sprite, FALSE);
}

static void FadeFootprintsTireTracks_Step1_field_effect_helpers(struct Sprite *sprite)
{
    sprite->invisible ^= 1;
    sprite->sTimer_field_effect_helpers++;
    UpdateObjectEventSpriteInvisibility(sprite, sprite->invisible);
    if (sprite->sTimer_field_effect_helpers > 56)
        FieldEffectStop(sprite, sprite->sFldEff_field_effect_helpers);
}

#undef sState_field_effect_helpers
#undef sTimer_field_effect_helpers
#undef sFldEff_field_effect_helpers

// Sprite data for FLDEFF_SPLASH
#define sLocalId_field_effect_helpers  data[0]
#define sMapNum_field_effect_helpers   data[1]
#define sMapGroup_field_effect_helpers data[2]

u32 FldEff_Splash(void)
{
    u8 objectEventId = GetObjectEventIdByLocalIdAndMap(gFieldEffectArguments[0], gFieldEffectArguments[1], gFieldEffectArguments[2]);
    struct ObjectEvent *objectEvent = &gObjectEvents[objectEventId];
    u8 spriteId = CreateSpriteAtEnd(gFieldEffectObjectTemplatePointers[FLDEFFOBJ_SPLASH], 0, 0, 0);
    if (spriteId != MAX_SPRITES)
    {
        struct Sprite *linkedSprite;
        const struct ObjectEventGraphicsInfo *graphicsInfo = GetObjectEventGraphicsInfo(objectEvent->graphicsId);
        struct Sprite *sprite = &gSprites[spriteId];
        sprite->coordOffsetEnabled = TRUE;
        linkedSprite = &gSprites[objectEvent->spriteId];
        sprite->oam.priority = linkedSprite->oam.priority;
        sprite->sLocalId_field_effect_helpers = gFieldEffectArguments[0];
        sprite->sMapNum_field_effect_helpers = gFieldEffectArguments[1];
        sprite->sMapGroup_field_effect_helpers = gFieldEffectArguments[2];
        sprite->y2 = (graphicsInfo->height >> 1) - 4;
        PlaySE(SE_PUDDLE);
    }
    return 0;
}

void UpdateSplashFieldEffect(struct Sprite *sprite)
{
    u8 objectEventId;

    if (sprite->animEnded || TryGetObjectEventIdByLocalIdAndMap(sprite->sLocalId_field_effect_helpers, sprite->sMapNum_field_effect_helpers, sprite->sMapGroup_field_effect_helpers, &objectEventId))
    {
        FieldEffectStop(sprite, FLDEFF_SPLASH);
    }
    else
    {
        sprite->x = gSprites[gObjectEvents[objectEventId].spriteId].x;
        sprite->y = gSprites[gObjectEvents[objectEventId].spriteId].y;
        UpdateObjectEventSpriteInvisibility(sprite, FALSE);
    }
}

