// Sprite data for FLDEFF_FEET_IN_FLOWING_WATER
#define sLocalId_field_effect_helpers  data[0]
#define sMapNum_field_effect_helpers   data[1]
#define sMapGroup_field_effect_helpers data[2]
#define sPrevX_field_effect_helpers    data[3]
#define sPrevY_field_effect_helpers    data[4]

u32 FldEff_FeetInFlowingWater(void)
{
    u8 objectEventId = GetObjectEventIdByLocalIdAndMap(gFieldEffectArguments[0], gFieldEffectArguments[1], gFieldEffectArguments[2]);
    struct ObjectEvent *objectEvent = &gObjectEvents[objectEventId];
    u8 spriteId = CreateSpriteAtEnd(gFieldEffectObjectTemplatePointers[FLDEFFOBJ_SPLASH], 0, 0, 0);
    if (spriteId != MAX_SPRITES)
    {
        const struct ObjectEventGraphicsInfo *graphicsInfo = GetObjectEventGraphicsInfo(objectEvent->graphicsId);
        struct Sprite *sprite = &gSprites[spriteId];
        sprite->callback = UpdateFeetInFlowingWaterFieldEffect_field_effect_helpers;
        sprite->coordOffsetEnabled = TRUE;
        sprite->oam.priority = gSprites[objectEvent->spriteId].oam.priority;
        sprite->sLocalId_field_effect_helpers = gFieldEffectArguments[0];
        sprite->sMapNum_field_effect_helpers = gFieldEffectArguments[1];
        sprite->sMapGroup_field_effect_helpers = gFieldEffectArguments[2];
        sprite->sPrevX_field_effect_helpers = -1;
        sprite->sPrevY_field_effect_helpers = -1;
        sprite->y2 = (graphicsInfo->height >> 1) - 4;
        StartSpriteAnim(sprite, 1);
    }
    return 0;
}

static void UpdateFeetInFlowingWaterFieldEffect_field_effect_helpers(struct Sprite *sprite)
{
    u8 objectEventId;

    if (TryGetObjectEventIdByLocalIdAndMap(sprite->sLocalId_field_effect_helpers, sprite->sMapNum_field_effect_helpers, sprite->sMapGroup_field_effect_helpers, &objectEventId) || !gObjectEvents[objectEventId].inShallowFlowingWater)
    {
        FieldEffectStop(sprite, FLDEFF_FEET_IN_FLOWING_WATER);
    }
    else
    {
        struct ObjectEvent *objectEvent = &gObjectEvents[objectEventId];
        struct Sprite *linkedSprite = &gSprites[objectEvent->spriteId];
        sprite->x = linkedSprite->x;
        sprite->y = linkedSprite->y;
        sprite->subpriority = linkedSprite->subpriority;
        UpdateObjectEventSpriteInvisibility(sprite, FALSE);
        if (objectEvent->currentCoords.x != sprite->sPrevX_field_effect_helpers || objectEvent->currentCoords.y != sprite->sPrevY_field_effect_helpers)
        {
            sprite->sPrevX_field_effect_helpers = objectEvent->currentCoords.x;
            sprite->sPrevY_field_effect_helpers = objectEvent->currentCoords.y;
            if (!sprite->invisible)
                PlaySE(SE_PUDDLE);
        }
    }
}

