// Sprite data for FLDEFF_ASH
#define sState_field_effect_helpers      data[0]
#define sX_field_effect_helpers          data[1]
#define sY_field_effect_helpers          data[2]
#define sMetatileId_field_effect_helpers data[3]
#define sDelay_field_effect_helpers      data[4]

void StartAshFieldEffect(s16 x, s16 y, u16 metatileId, s16 delay)
{
    gFieldEffectArguments[0] = x;
    gFieldEffectArguments[1] = y;
    gFieldEffectArguments[2] = 82; // subpriority
    gFieldEffectArguments[3] = 1; // priority
    gFieldEffectArguments[4] = metatileId;
    gFieldEffectArguments[5] = delay;
    FieldEffectStart(FLDEFF_ASH);
}

u32 FldEff_Ash(void)
{
    u8 spriteId;

    s16 x = gFieldEffectArguments[0];
    s16 y = gFieldEffectArguments[1];
    SetSpritePosToOffsetMapCoords(&x, &y, 8, 8);
    spriteId = CreateSpriteAtEnd(gFieldEffectObjectTemplatePointers[FLDEFFOBJ_ASH], x, y, gFieldEffectArguments[2]);
    if (spriteId != MAX_SPRITES)
    {
        struct Sprite *sprite = &gSprites[spriteId];
        sprite->coordOffsetEnabled = TRUE;
        sprite->oam.priority = gFieldEffectArguments[3];
        sprite->sX_field_effect_helpers = gFieldEffectArguments[0];
        sprite->sY_field_effect_helpers = gFieldEffectArguments[1];
        sprite->sMetatileId_field_effect_helpers = gFieldEffectArguments[4];
        sprite->sDelay_field_effect_helpers = gFieldEffectArguments[5];
    }
    return 0;
}

void (*const gAshFieldEffectFuncs[])(struct Sprite *) = {
    UpdateAshFieldEffect_Wait_field_effect_helpers,
    UpdateAshFieldEffect_Show_field_effect_helpers,
    UpdateAshFieldEffect_End_field_effect_helpers
};

void UpdateAshFieldEffect(struct Sprite *sprite)
{
    gAshFieldEffectFuncs[sprite->sState_field_effect_helpers](sprite);
}

static void UpdateAshFieldEffect_Wait_field_effect_helpers(struct Sprite *sprite)
{
    sprite->invisible = TRUE;
    sprite->animPaused = TRUE;
    if (--sprite->sDelay_field_effect_helpers == 0)
        sprite->sState_field_effect_helpers = 1;
}

static void UpdateAshFieldEffect_Show_field_effect_helpers(struct Sprite *sprite)
{
    sprite->invisible = FALSE;
    sprite->animPaused = FALSE;
    MapGridSetMetatileIdAt(sprite->sX_field_effect_helpers, sprite->sY_field_effect_helpers, sprite->sMetatileId_field_effect_helpers);
    CurrentMapDrawMetatileAt(sprite->sX_field_effect_helpers, sprite->sY_field_effect_helpers);
    gObjectEvents[gPlayerAvatar.objectEventId].triggerGroundEffectsOnMove = TRUE;
    sprite->sState_field_effect_helpers = 2;
}

static void UpdateAshFieldEffect_End_field_effect_helpers(struct Sprite *sprite)
{
    UpdateObjectEventSpriteInvisibility(sprite, FALSE);
    if (sprite->animEnded)
        FieldEffectStop(sprite, FLDEFF_ASH);
}

#undef sState_field_effect_helpers
#undef sX_field_effect_helpers
#undef sY_field_effect_helpers
#undef sMetatileId_field_effect_helpers
#undef sDelay_field_effect_helpers

// Sprite data for FLDEFF_SURF_BLOB
#define sBitfield_field_effect_helpers     data[0]
#define sPlayerOffset_field_effect_helpers data[1]
#define sPlayerObjId_field_effect_helpers  data[2]
#define sVelocity_field_effect_helpers     data[3]
#define sTimer_field_effect_helpers        data[4]
#define sIntervalIdx_field_effect_helpers  data[5]
#define sPrevX_field_effect_helpers        data[6]
#define sPrevY_field_effect_helpers        data[7]

u32 FldEff_SurfBlob(void)
{
    u8 spriteId;

    SetSpritePosToOffsetMapCoords((s16 *)&gFieldEffectArguments[0], (s16 *)&gFieldEffectArguments[1], 8, 8);
    spriteId = CreateSpriteAtEnd(gFieldEffectObjectTemplatePointers[FLDEFFOBJ_SURF_BLOB], gFieldEffectArguments[0], gFieldEffectArguments[1], 150);
    if (spriteId != MAX_SPRITES)
    {
        struct Sprite *sprite = &gSprites[spriteId];
        sprite->coordOffsetEnabled = TRUE;
        sprite->sPlayerObjId_field_effect_helpers = gFieldEffectArguments[2];
        // Can use either gender's palette, so try to use the one that should be loaded
        sprite->oam.paletteNum = LoadPlayerObjectEventPalette(gSaveBlock2Ptr->playerGender);
        sprite->sVelocity_field_effect_helpers = -1;
        sprite->sPrevX_field_effect_helpers = -1;
        sprite->sPrevY_field_effect_helpers = -1;
    }
    FieldEffectActiveListRemove(FLDEFF_SURF_BLOB);
    return spriteId;
}


void SetSurfBlob_BobState(u8 spriteId, u8 state)
{
    gSprites[spriteId].sBitfield_field_effect_helpers = (gSprites[spriteId].sBitfield_field_effect_helpers & ~0xF) | (state & 0xF);
}

void SetSurfBlob_DontSyncAnim(u8 spriteId, bool8 dontSync)
{
    gSprites[spriteId].sBitfield_field_effect_helpers = (gSprites[spriteId].sBitfield_field_effect_helpers & ~0xF0) | ((dontSync & 0xF) << 4);
}

void SetSurfBlob_PlayerOffset(u8 spriteId, bool8 hasOffset, s16 offset)
{
    gSprites[spriteId].sBitfield_field_effect_helpers = (gSprites[spriteId].sBitfield_field_effect_helpers & ~0xF00) | ((hasOffset & 0xF) << 8);
    gSprites[spriteId].sPlayerOffset_field_effect_helpers = offset;
}

static u8 GetSurfBlob_BobState_field_effect_helpers(struct Sprite *sprite)
{
    return sprite->sBitfield_field_effect_helpers & 0xF;
}

// Never TRUE
static u8 GetSurfBlob_DontSyncAnim_field_effect_helpers(struct Sprite *sprite)
{
    return (sprite->sBitfield_field_effect_helpers & 0xF0) >> 4;
}

static u8 GetSurfBlob_HasPlayerOffset_field_effect_helpers(struct Sprite *sprite)
{
    return (sprite->sBitfield_field_effect_helpers & 0xF00) >> 8;
}

void UpdateSurfBlobFieldEffect(struct Sprite *sprite)
{
    struct ObjectEvent *playerObj = &gObjectEvents[sprite->sPlayerObjId_field_effect_helpers];
    struct Sprite *playerSprite = &gSprites[playerObj->spriteId];
    SynchroniseSurfAnim_field_effect_helpers(playerObj, sprite);
    SynchroniseSurfPosition(playerObj, sprite);
    UpdateBobbingEffect_field_effect_helpers(playerObj, playerSprite, sprite);
    sprite->oam.priority = playerSprite->oam.priority;
}

static void SynchroniseSurfAnim_field_effect_helpers(struct ObjectEvent *playerObj, struct Sprite *sprite)
{
    // Indexes into sAnimTable_SurfBlob
    u8 surfBlobDirectionAnims[] = {
        [DIR_NONE] = 0,
        [DIR_SOUTH] = 0,
        [DIR_NORTH] = 1,
        [DIR_WEST] = 2,
        [DIR_EAST] = 3,
        [DIR_SOUTHWEST] = 0,
        [DIR_SOUTHEAST] = 0,
        [DIR_NORTHWEST] = 1,
        [DIR_NORTHEAST] = 1,
    };

    if (!GetSurfBlob_DontSyncAnim_field_effect_helpers(sprite))
        StartSpriteAnimIfDifferent(sprite, surfBlobDirectionAnims[playerObj->movementDirection]);
}

void SynchroniseSurfPosition(struct ObjectEvent *playerObj, struct Sprite *sprite)
{
    u8 i;
    s16 x = playerObj->currentCoords.x;
    s16 y = playerObj->currentCoords.y;
    s32 spriteY = sprite->y2;

    if (spriteY == 0 && (x != sprite->sPrevX_field_effect_helpers || y != sprite->sPrevY_field_effect_helpers))
    {
        // Player is moving while surfing, update position.
        sprite->sIntervalIdx_field_effect_helpers = 0;
        sprite->sPrevX_field_effect_helpers = x;
        sprite->sPrevY_field_effect_helpers = y;
        for (i = DIR_SOUTH; i <= DIR_EAST; i++, x = sprite->sPrevX_field_effect_helpers, y = sprite->sPrevY_field_effect_helpers)
        {
            MoveCoords(i, &x, &y);
            if (MapGridGetElevationAt(x, y) == 3)
            {
                // While dismounting the surf blob bobs at a slower rate
                sprite->sIntervalIdx_field_effect_helpers++;
                break;
            }
        }
    }
}

static void UpdateBobbingEffect_field_effect_helpers(struct ObjectEvent *playerObj, struct Sprite *playerSprite, struct Sprite *sprite)
{
    // The frame interval at which to update the blob's y movement.
    // Normally every 4th frame, but every 8th frame while dismounting.
    u16 intervals[] = {0x3, 0x7};

    u8 bobState = GetSurfBlob_BobState_field_effect_helpers(sprite);
    if (bobState != BOB_NONE)
    {
        // Update vertical position of surf blob
        if (((u16)(++sprite->sTimer_field_effect_helpers) & intervals[sprite->sIntervalIdx_field_effect_helpers]) == 0)
            sprite->y2 += sprite->sVelocity_field_effect_helpers;

        // Reverse bob direction
        if ((sprite->sTimer_field_effect_helpers & 15) == 0)
            sprite->sVelocity_field_effect_helpers = -sprite->sVelocity_field_effect_helpers;

        if (bobState != BOB_JUST_MON)
        {
            // Update vertical position of player
            if (!GetSurfBlob_HasPlayerOffset_field_effect_helpers(sprite))
                playerSprite->y2 = sprite->y2;
            else
                playerSprite->y2 = sprite->sPlayerOffset_field_effect_helpers + sprite->y2;
            sprite->x = playerSprite->x;
            sprite->y = playerSprite->y + 8;
        }
    }
}

#undef sBitfield_field_effect_helpers
#undef sPlayerOffset_field_effect_helpers
#undef sPlayerObjId_field_effect_helpers
#undef sVelocity_field_effect_helpers
#undef sTimer_field_effect_helpers
#undef sIntervalIdx_field_effect_helpers
#undef sPrevX_field_effect_helpers
#undef sPrevY_field_effect_helpers

#define sSpriteId_field_effect_helpers data[0]
#define sBobY_field_effect_helpers     data[1]
#define sTimer_field_effect_helpers    data[2]

u8 StartUnderwaterSurfBlobBobbing(u8 blobSpriteId)
{
    // Create a dummy sprite with its own callback
    // that tracks the actual surf blob sprite and
    // makes it bob up and down underwater
    u8 spriteId = CreateSpriteAtEnd(&gDummySpriteTemplate, 0, 0, -1);
    struct Sprite *sprite = &gSprites[spriteId];
    sprite->callback = SpriteCB_UnderwaterSurfBlob_field_effect_helpers;
    sprite->invisible = TRUE;
    sprite->sSpriteId_field_effect_helpers = blobSpriteId;
    sprite->sBobY_field_effect_helpers = 1;
    return spriteId;
}

static void SpriteCB_UnderwaterSurfBlob_field_effect_helpers(struct Sprite *sprite)
{
    struct Sprite *blobSprite = &gSprites[sprite->sSpriteId_field_effect_helpers];

    // Update vertical position of surf blob
    if (((sprite->sTimer_field_effect_helpers++) & 3) == 0)
        blobSprite->y2 += sprite->sBobY_field_effect_helpers;
    // Reverse direction
    if ((sprite->sTimer_field_effect_helpers & 15) == 0)
        sprite->sBobY_field_effect_helpers = -sprite->sBobY_field_effect_helpers;
}

#undef sSpriteId_field_effect_helpers
#undef sBobY_field_effect_helpers
#undef sTimer_field_effect_helpers

