void StartFishing(u8 rod)
{
    u8 taskId = CreateTask(Task_Fishing_field_player_avatar, 0xFF);

    gTasks[taskId].tFishingRod_field_player_avatar = rod;
    Task_Fishing_field_player_avatar(taskId);
}

static void Task_Fishing_field_player_avatar(u8 taskId)
{
    while (sFishingStateFuncs[gTasks[taskId].tStep_field_player_avatar](&gTasks[taskId]))
        ;
}

static bool32 Fishing_Init_field_player_avatar(struct Task *task)
{
    LockPlayerFieldControls();
    gPlayerAvatar.preventStep = TRUE;
    task->tStep_field_player_avatar = FISHING_GET_ROD_OUT_field_player_avatar;
    return FALSE;
}

static bool32 Fishing_GetRodOut_field_player_avatar(struct Task *task)
{
    struct ObjectEvent *playerObjEvent;
    const s16 minRounds1[] = {
        [OLD_ROD]   = 1,
        [GOOD_ROD]  = 1,
        [SUPER_ROD] = 1
    };
    const s16 minRounds2[] = {
        [OLD_ROD]   = 1,
        [GOOD_ROD]  = 3,
        [SUPER_ROD] = 6
    };

    task->tRoundsPlayed_field_player_avatar = 0;
    task->tMinRoundsRequired_field_player_avatar = minRounds1[task->tFishingRod_field_player_avatar] + (Random() % minRounds2[task->tFishingRod_field_player_avatar]);
    task->tPlayerGfxId_field_player_avatar = gObjectEvents[gPlayerAvatar.objectEventId].graphicsId;
    playerObjEvent = &gObjectEvents[gPlayerAvatar.objectEventId];
    ObjectEventClearHeldMovementIfActive(playerObjEvent);
    playerObjEvent->enableAnim = TRUE;
    SetPlayerAvatarFishing_field_player_avatar(playerObjEvent->facingDirection);
    task->tStep_field_player_avatar = FISHING_WAIT_BEFORE_DOTS_field_player_avatar;
    return FALSE;
}

static bool32 Fishing_WaitBeforeDots_field_player_avatar(struct Task *task)
{
    AlignFishingAnimationFrames_field_player_avatar();

    // Wait one second
    task->tFrameCounter_field_player_avatar++;
    if (task->tFrameCounter_field_player_avatar >= 60)
        task->tStep_field_player_avatar = FISHING_INIT_DOTS_field_player_avatar;
    return FALSE;
}

static bool32 Fishing_InitDots_field_player_avatar(struct Task *task)
{
    u32 randVal;

    LoadMessageBoxAndFrameGfx(0, TRUE);
    task->tStep_field_player_avatar = FISHING_SHOW_DOTS_field_player_avatar;
    task->tFrameCounter_field_player_avatar = 0;
    task->tNumDots_field_player_avatar = 0;
    randVal = Random();
    randVal %= 10;
    task->tDotsRequired_field_player_avatar = randVal + 1;
    if (task->tRoundsPlayed_field_player_avatar == 0)
        task->tDotsRequired_field_player_avatar = randVal + 4;
    if (task->tDotsRequired_field_player_avatar >= 10)
        task->tDotsRequired_field_player_avatar = 10;
    return TRUE;
}

static bool32 Fishing_ShowDots_field_player_avatar(struct Task *task)
{
    const u8 dot[] = _("·");

    AlignFishingAnimationFrames_field_player_avatar();
    task->tFrameCounter_field_player_avatar++;
    if (JOY_NEW(A_BUTTON))
    {
        if (!DoesFishingMinigameAllowCancel_field_player_avatar())
            return FALSE;

        task->tStep_field_player_avatar = FISHING_NOT_EVEN_NIBBLE_field_player_avatar;
        if (task->tRoundsPlayed_field_player_avatar != 0)
            task->tStep_field_player_avatar = FISHING_GOT_AWAY_field_player_avatar;
        return TRUE;
    }
    else
    {
        if (task->tFrameCounter_field_player_avatar >= 20)
        {
            task->tFrameCounter_field_player_avatar = 0;
            if (task->tNumDots_field_player_avatar >= task->tDotsRequired_field_player_avatar)
            {
                task->tStep_field_player_avatar = FISHING_CHECK_FOR_BITE_field_player_avatar;
                if (task->tRoundsPlayed_field_player_avatar != 0)
                    task->tStep_field_player_avatar = FISHING_GOT_BITE_field_player_avatar;
                task->tRoundsPlayed_field_player_avatar++;
            }
            else
            {
                AddTextPrinterParameterized(0, FONT_NORMAL, dot, task->tNumDots_field_player_avatar * 8, 1, 0, NULL);
                task->tNumDots_field_player_avatar++;
            }
        }
        return FALSE;
    }
}

static bool32 Fishing_CheckForBite_field_player_avatar(struct Task *task)
{
    bool32 bite, firstMonHasSuctionOrSticky;

    AlignFishingAnimationFrames_field_player_avatar();
    task->tStep_field_player_avatar = FISHING_GOT_BITE_field_player_avatar;
    bite = FALSE;

    if (!DoesCurrentMapHaveFishingMons())
    {
        task->tStep_field_player_avatar = FISHING_NOT_EVEN_NIBBLE_field_player_avatar;
        return TRUE;
    }

    firstMonHasSuctionOrSticky = Fishing_DoesFirstMonInPartyHaveSuctionCupsOrStickyHold_field_player_avatar();

    if(firstMonHasSuctionOrSticky)
        bite = Fishing_RollForBite_field_player_avatar(task->tFishingRod_field_player_avatar, firstMonHasSuctionOrSticky);

    if (!bite)
        bite = Fishing_RollForBite_field_player_avatar(task->tFishingRod_field_player_avatar, FALSE);

    if (!bite)
        task->tStep_field_player_avatar = FISHING_NOT_EVEN_NIBBLE_field_player_avatar;

    if (bite)
        StartSpriteAnim(&gSprites[gPlayerAvatar.spriteId], GetFishingBiteDirectionAnimNum(GetPlayerFacingDirection()));

    return TRUE;
}

static bool32 Fishing_GotBite_field_player_avatar(struct Task *task)
{
    AlignFishingAnimationFrames_field_player_avatar();
    AddTextPrinterParameterized(0, FONT_NORMAL, gText_OhABite, 0, 17, 0, NULL);
    task->tStep_field_player_avatar = FISHING_CHANGE_MINIGAME_field_player_avatar;
    task->tFrameCounter_field_player_avatar = 0;
    return FALSE;
}

static bool32 Fishing_ChangeMinigame_field_player_avatar(struct Task *task)
{
    switch (I_FISHING_MINIGAME)
    {
        case GEN_1:
        case GEN_2:
            task->tStep_field_player_avatar = FISHING_A_PRESS_NO_MINIGAME_field_player_avatar;
            break;
        case GEN_3:
        default:
            task->tStep_field_player_avatar = FISHING_WAIT_FOR_A_field_player_avatar;
            break;
    }
    return TRUE;
}

// We have a bite. Now, wait for the player to press A, or the timer to expire.
static bool32 Fishing_WaitForA_field_player_avatar(struct Task *task)
{
    const s16 reelTimeouts[3] = {
        [OLD_ROD]   = 36,
        [GOOD_ROD]  = 33,
        [SUPER_ROD] = 30
    };

    AlignFishingAnimationFrames_field_player_avatar();
    task->tFrameCounter_field_player_avatar++;
    if (task->tFrameCounter_field_player_avatar >= reelTimeouts[task->tFishingRod_field_player_avatar])
        task->tStep_field_player_avatar = FISHING_GOT_AWAY_field_player_avatar;
    else if (JOY_NEW(A_BUTTON))
        task->tStep_field_player_avatar = FISHING_CHECK_MORE_DOTS_field_player_avatar;
    return FALSE;
}

static bool32 Fishing_APressNoMinigame_field_player_avatar(struct Task *task)
{
    AlignFishingAnimationFrames_field_player_avatar();
    if (JOY_NEW(A_BUTTON))
        task->tStep_field_player_avatar = FISHING_MON_ON_HOOK_field_player_avatar;
    return FALSE;
}

// Determine if we're going to play the dot game again
static bool32 Fishing_CheckMoreDots_field_player_avatar(struct Task *task)
{
    const s16 moreDotsChance[][2] =
    {
        [OLD_ROD]   = {0, 0},
        [GOOD_ROD]  = {40, 10},
        [SUPER_ROD] = {70, 30}
    };

    AlignFishingAnimationFrames_field_player_avatar();
    task->tStep_field_player_avatar = FISHING_MON_ON_HOOK_field_player_avatar;
    if (task->tRoundsPlayed_field_player_avatar < task->tMinRoundsRequired_field_player_avatar)
    {
        task->tStep_field_player_avatar = FISHING_INIT_DOTS_field_player_avatar;
    }
    else if (task->tRoundsPlayed_field_player_avatar < 2)
    {
        // probability of having to play another round
        s16 probability = Random() % 100;

        if (moreDotsChance[task->tFishingRod_field_player_avatar][task->tRoundsPlayed_field_player_avatar] > probability)
            task->tStep_field_player_avatar = FISHING_INIT_DOTS_field_player_avatar;
    }
    return FALSE;
}

static bool32 Fishing_MonOnHook_field_player_avatar(struct Task *task)
{
    AlignFishingAnimationFrames_field_player_avatar();
    FillWindowPixelBuffer(0, PIXEL_FILL(1));
    AddTextPrinterParameterized2(0, FONT_NORMAL, gText_PokemonOnHook, 1, 0, TEXT_COLOR_DARK_GRAY, TEXT_COLOR_WHITE, TEXT_COLOR_LIGHT_GRAY);
    task->tStep_field_player_avatar = FISHING_START_ENCOUNTER_field_player_avatar;
    task->tFrameCounter_field_player_avatar = 0;
    return FALSE;
}

static bool32 Fishing_StartEncounter_field_player_avatar(struct Task *task)
{
    if (task->tFrameCounter_field_player_avatar == 0)
        AlignFishingAnimationFrames_field_player_avatar();

    RunTextPrinters();

    if (task->tFrameCounter_field_player_avatar == 0)
    {
        if (!IsTextPrinterActive(0))
        {
            struct ObjectEvent *playerObjEvent = &gObjectEvents[gPlayerAvatar.objectEventId];

            ObjectEventSetGraphicsId(playerObjEvent, task->tPlayerGfxId_field_player_avatar);
            ObjectEventTurn(playerObjEvent, playerObjEvent->movementDirection);
            if (gPlayerAvatar.flags & PLAYER_AVATAR_FLAG_SURFING)
                SetSurfBlob_PlayerOffset(gObjectEvents[gPlayerAvatar.objectEventId].fieldEffectSpriteId, FALSE, 0);
            gSprites[gPlayerAvatar.spriteId].x2 = 0;
            gSprites[gPlayerAvatar.spriteId].y2 = 0;
            ClearDialogWindowAndFrame(0, TRUE);
            task->tFrameCounter_field_player_avatar++;
            return FALSE;
        }
    }

    if (task->tFrameCounter_field_player_avatar != 0)
    {
        gPlayerAvatar.preventStep = FALSE;
        UnlockPlayerFieldControls();
        FishingWildEncounter(task->tFishingRod_field_player_avatar);
        RecordFishingAttemptForTV(TRUE);
        DestroyTask(FindTaskIdByFunc(Task_Fishing_field_player_avatar));
    }
    return FALSE;
}

static bool32 Fishing_NotEvenNibble_field_player_avatar(struct Task *task)
{
    gChainFishingDexNavStreak = 0;
    AlignFishingAnimationFrames_field_player_avatar();
    StartSpriteAnim(&gSprites[gPlayerAvatar.spriteId], GetFishingNoCatchDirectionAnimNum(GetPlayerFacingDirection()));
    FillWindowPixelBuffer(0, PIXEL_FILL(1));
    AddTextPrinterParameterized2(0, FONT_NORMAL, gText_NotEvenANibble, 1, 0, TEXT_COLOR_DARK_GRAY, TEXT_COLOR_WHITE, TEXT_COLOR_LIGHT_GRAY);
    task->tStep_field_player_avatar = FISHING_NO_MON_field_player_avatar;
    return TRUE;
}

static bool32 Fishing_GotAway_field_player_avatar(struct Task *task)
{
    gChainFishingDexNavStreak = 0;
    AlignFishingAnimationFrames_field_player_avatar();
    StartSpriteAnim(&gSprites[gPlayerAvatar.spriteId], GetFishingNoCatchDirectionAnimNum(GetPlayerFacingDirection()));
    FillWindowPixelBuffer(0, PIXEL_FILL(1));
    AddTextPrinterParameterized2(0, FONT_NORMAL, gText_ItGotAway, 1, 0, TEXT_COLOR_DARK_GRAY, TEXT_COLOR_WHITE, TEXT_COLOR_LIGHT_GRAY);
    task->tStep_field_player_avatar = FISHING_NO_MON_field_player_avatar;
    return TRUE;
}

static bool32 Fishing_NoMon_field_player_avatar(struct Task *task)
{
    AlignFishingAnimationFrames_field_player_avatar();
    task->tStep_field_player_avatar = FISHING_PUT_ROD_AWAY_field_player_avatar;
    return FALSE;
}

static bool32 Fishing_PutRodAway_field_player_avatar(struct Task *task)
{
    AlignFishingAnimationFrames_field_player_avatar();
    if (gSprites[gPlayerAvatar.spriteId].animEnded)
    {
        struct ObjectEvent *playerObjEvent = &gObjectEvents[gPlayerAvatar.objectEventId];

        ObjectEventSetGraphicsId(playerObjEvent, task->tPlayerGfxId_field_player_avatar);
        ObjectEventTurn(playerObjEvent, playerObjEvent->movementDirection);
        if (gPlayerAvatar.flags & PLAYER_AVATAR_FLAG_SURFING)
            SetSurfBlob_PlayerOffset(gObjectEvents[gPlayerAvatar.objectEventId].fieldEffectSpriteId, FALSE, 0);
        gSprites[gPlayerAvatar.spriteId].x2 = 0;
        gSprites[gPlayerAvatar.spriteId].y2 = 0;
        task->tStep_field_player_avatar = FISHING_END_NO_MON_field_player_avatar;
    }
    return FALSE;
}

static bool32 Fishing_EndNoMon_field_player_avatar(struct Task *task)
{
    RunTextPrinters();
    if (!IsTextPrinterActive(0))
    {
        gPlayerAvatar.preventStep = FALSE;
        UnlockPlayerFieldControls();
        UnfreezeObjectEvents();
        ClearDialogWindowAndFrame(0, TRUE);
        RecordFishingAttemptForTV(FALSE);
        DestroyTask(FindTaskIdByFunc(Task_Fishing_field_player_avatar));
    }
    return FALSE;
}

static bool32 DoesFishingMinigameAllowCancel_field_player_avatar(void)
{
    switch(I_FISHING_MINIGAME)
    {
        case GEN_1:
        case GEN_2:
            return FALSE;
        case GEN_3:
        default:
            return TRUE;
    }
}

static bool32 Fishing_DoesFirstMonInPartyHaveSuctionCupsOrStickyHold_field_player_avatar(void)
{
    u32 ability;

    if (GetMonData(&gPlayerParty[0], MON_DATA_SANITY_IS_EGG))
        return FALSE;

    ability = GetMonAbility(&gPlayerParty[0]);

    return (ability == ABILITY_SUCTION_CUPS || ability == ABILITY_STICKY_HOLD);
}

static bool32 Fishing_RollForBite_field_player_avatar(u32 rod, bool32 isStickyHold)
{
    return ((Random() % 100) > CalculateFishingBiteOdds_field_player_avatar(rod, isStickyHold));
}

static u32 CalculateFishingBiteOdds_field_player_avatar(u32 rod, bool32 isStickyHold)
{
    u32 odds;

    if (rod == OLD_ROD)
        odds = FISHING_OLD_ROD_ODDS_field_player_avatar;
    if (rod == GOOD_ROD)
        odds = FISHING_GOOD_ROD_ODDS_field_player_avatar;
    if (rod == SUPER_ROD)
        odds = FISHING_SUPER_ROD_ODDS_field_player_avatar;

    odds -= CalculateFishingFollowerBoost_field_player_avatar();

    if (isStickyHold)
    {
        if (I_FISHING_STICKY_BOOST >= GEN_4)
            odds -= (100 - odds);
        else
            odds -= FISHING_STICKY_BOOST_field_player_avatar;
    }

    odds -= CalculateFishingProximityBoost_field_player_avatar(odds);

    return odds;
}

static u32 CalculateFishingFollowerBoost_field_player_avatar()
{
    u32 friendship;
    struct Pokemon *mon = GetFirstLiveMon();

    if (!I_FISHING_FOLLOWER_BOOST || !mon)
        return 0;

    friendship = GetMonData(mon, MON_DATA_FRIENDSHIP);
    if (friendship >= 250)
        return 50;
    else if (friendship >= 200)
        return 40;
    else if (friendship >= 150)
        return 30;
    else if (friendship >= 100)
        return 20;
    else
        return 0;
}

static u32 CalculateFishingProximityBoost_field_player_avatar(u32 odds)
{
    s16 player[AXIS_COUNT], bobber[AXIS_COUNT];
    s16 surroundingTile[CARDINAL_DIRECTION_COUNT][AXIS_COUNT] = {{0, 0}};
    bool32 isTileLand[CARDINAL_DIRECTION_COUNT] = {FALSE};
    u32 facingDirection, numQualifyingTile = 0;
    struct ObjectEvent *objectEvent;

    if (!I_FISHING_PROXIMITY)
        return 0;

    objectEvent = &gObjectEvents[gPlayerAvatar.objectEventId];

    player[AXIS_X] = objectEvent->currentCoords.x;
    player[AXIS_Y] = objectEvent->currentCoords.y;
    bobber[AXIS_X] = objectEvent->currentCoords.x;
    bobber[AXIS_Y] = objectEvent->currentCoords.y;

    facingDirection = GetPlayerFacingDirection();
    MoveCoords(facingDirection, &bobber[AXIS_X], &bobber[AXIS_Y]);

    GetCoordinatesAroundBobber_field_player_avatar(bobber, surroundingTile, facingDirection);
    numQualifyingTile = CountQualifyingTiles_field_player_avatar(surroundingTile, player, facingDirection, objectEvent, isTileLand);

    numQualifyingTile += CountLandTiles_field_player_avatar(isTileLand);

    return (numQualifyingTile == 3) ? odds : (numQualifyingTile * FISHING_PROXIMITY_BOOST_field_player_avatar);
}

static void GetCoordinatesAroundBobber_field_player_avatar(s16 bobber[], s16 surroundingTile[][AXIS_COUNT], u32 facingDirection)
{
    u32 direction;

    for (direction = DIR_SOUTH; direction < CARDINAL_DIRECTION_COUNT; direction++)
    {
        surroundingTile[direction][AXIS_X] = bobber[AXIS_X];
        surroundingTile[direction][AXIS_Y] = bobber[AXIS_Y];
        MoveCoords(direction, &surroundingTile[direction][AXIS_X], &surroundingTile[direction][AXIS_Y]);
    }
}

static u32 CountQualifyingTiles_field_player_avatar(s16 surroundingTile[][AXIS_COUNT], s16 player[], u8 facingDirection, struct ObjectEvent *objectEvent, bool32 isTileLand[])
{
    u32 numQualifyingTile = 0;
    s16 tile[AXIS_COUNT];
    u8 direction = DIR_SOUTH;

    for (direction = DIR_SOUTH; direction < CARDINAL_DIRECTION_COUNT; direction++)
    {
        tile[AXIS_X] = surroundingTile[direction][AXIS_X];
        tile[AXIS_Y] = surroundingTile[direction][AXIS_Y];

        if (!CheckTileQualification_field_player_avatar(tile, player, facingDirection, objectEvent, isTileLand, direction))
            continue;

        numQualifyingTile++;
    }
    return numQualifyingTile;
}

static bool32 CheckTileQualification_field_player_avatar(s16 tile[], s16 player[], u32 facingDirection, struct ObjectEvent* objectEvent, bool32 isTileLand[], u32 direction)
{
    u32 collison = GetCollisionAtCoords(objectEvent, tile[AXIS_X], tile[AXIS_Y], facingDirection);

    if (IsPlayerHere_field_player_avatar(tile[AXIS_X], tile[AXIS_Y], player[AXIS_X], player[AXIS_Y]))
        return FALSE;
    else if (IsMetatileBlocking_field_player_avatar(tile[AXIS_X], tile[AXIS_Y], collison))
        return TRUE;
    else if (MetatileBehavior_IsSurfableFishableWater(MapGridGetMetatileBehaviorAt(tile[AXIS_X], tile[AXIS_Y])))
        return FALSE;
    else if (IsMetatileLand_field_player_avatar(tile[AXIS_X], tile[AXIS_Y], collison))
        isTileLand[direction] = TRUE;

    return FALSE;
}

static u32 CountLandTiles_field_player_avatar(bool32 isTileLand[])
{
    u32 direction, numQualifyingTile = 0;

    for (direction = DIR_SOUTH; direction < CARDINAL_DIRECTION_COUNT; direction++)
        if (isTileLand[direction])
            numQualifyingTile++;

    return (numQualifyingTile < 2) ? 0 : numQualifyingTile;
}

static bool32 IsPlayerHere_field_player_avatar(s16 x, s16 y, s16 playerX, s16 playerY)
{
    return ((x == playerX) && (y == playerY));
}

static bool32 IsMetatileBlocking_field_player_avatar(s16 x, s16 y, u32 collison)
{
    switch(collison)
    {
        case COLLISION_NONE:
        case COLLISION_STOP_SURFING:
        case COLLISION_ELEVATION_MISMATCH:
            return FALSE;
        default:
            return TRUE;
        case COLLISION_OBJECT_EVENT:
            return (gObjectEvents[GetObjectEventIdByXY(x,y)].inanimate);
    }
    return TRUE;
}

static bool32 IsMetatileLand_field_player_avatar(s16 x, s16 y, u32 collison)
{
    switch(collison)
    {
        case COLLISION_NONE:
        case COLLISION_STOP_SURFING:
        case COLLISION_ELEVATION_MISMATCH:
            return TRUE;
        default:
            return FALSE;
    }
}

#undef tStep_field_player_avatar
#undef tFrameCounter_field_player_avatar
#undef tFishingRod_field_player_avatar

static void AlignFishingAnimationFrames_field_player_avatar(void)
{
    struct Sprite *playerSprite = &gSprites[gPlayerAvatar.spriteId];
    u8 animCmdIndex;
    u8 animType;

    AnimateSprite(playerSprite);
    playerSprite->x2 = 0;
    playerSprite->y2 = 0;
    animCmdIndex = playerSprite->animCmdIndex;
    if (playerSprite->anims[playerSprite->animNum][animCmdIndex].type == -1)
    {
        animCmdIndex--;
    }
    else
    {
        playerSprite->animDelayCounter++;
        if (playerSprite->anims[playerSprite->animNum][animCmdIndex].type == -1)
            animCmdIndex--;
    }
    animType = playerSprite->anims[playerSprite->animNum][animCmdIndex].type;
    if (animType == 1 || animType == 2 || animType == 3)
    {
        playerSprite->x2 = 8;
        if (GetPlayerFacingDirection() == 3)
            playerSprite->x2 = -8;
    }
    if (animType == 5)
        playerSprite->y2 = -8;
    if (animType == 10 || animType == 11)
        playerSprite->y2 = 8;
    if (gPlayerAvatar.flags & PLAYER_AVATAR_FLAG_SURFING)
        SetSurfBlob_PlayerOffset(gObjectEvents[gPlayerAvatar.objectEventId].fieldEffectSpriteId, TRUE, playerSprite->y2);
}

void SetSpinStartFacingDir(u8 direction)
{
    sSpinStartFacingDir_field_player_avatar = direction;
}

static u8 GetSpinStartFacingDir_field_player_avatar(void)
{
    if (sSpinStartFacingDir_field_player_avatar == DIR_NONE)
        return DIR_SOUTH;

    return sSpinStartFacingDir_field_player_avatar;
}

// Task data for Task_DoPlayerSpinEntrance_field_player_avatar and Task_DoPlayerSpinExit_field_player_avatar
#define tState_field_player_avatar          data[0]
#define tSpinDelayTimer_field_player_avatar data[1]
#define tSpeed_field_player_avatar          data[2]
#define tCurY_field_player_avatar           data[3]
#define tDestY_field_player_avatar          data[4]
#define tStartDir_field_player_avatar       data[5]
#define tPriority_field_player_avatar       data[6]
#define tSubpriority_field_player_avatar    data[7]
#define tGroundTimer_field_player_avatar    data[8]

static void Task_DoPlayerSpinExit_field_player_avatar(u8 taskId)
{
    struct ObjectEvent *object = &gObjectEvents[gPlayerAvatar.objectEventId];
    struct Sprite *sprite = &gSprites[object->spriteId];
    s16 *data = gTasks[taskId].data;

    switch (tState_field_player_avatar)
    {
        case 0: // Init
            if (!ObjectEventClearHeldMovementIfFinished(object))
                return;

            SetSpinStartFacingDir(object->facingDirection);
            tSpinDelayTimer_field_player_avatar = 0;
            tSpeed_field_player_avatar = 1;
            tCurY_field_player_avatar = (u16)(sprite->y + sprite->y2) << 4;
            sprite->y2 = 0;
            CameraObjectFreeze();
            object->fixedPriority = TRUE;
            sprite->oam.priority = 0;
            sprite->subpriority = 0;
            sprite->subspriteMode = SUBSPRITES_OFF;
            tState_field_player_avatar++;
        case 1: // Spin while rising
            TrySpinPlayerForWarp_field_player_avatar(object, &tSpinDelayTimer_field_player_avatar);

            // Rise and accelerate
            tCurY_field_player_avatar -= tSpeed_field_player_avatar;
            tSpeed_field_player_avatar += 3;
            sprite->y = tCurY_field_player_avatar >> 4;

            // Check if offscreen
            if (sprite->y + (s16)gTotalCameraPixelOffsetY < -32)
                tState_field_player_avatar++;
            break;
        case 2:
            DestroyTask(taskId);
            break;
    }
}

static void Task_DoPlayerSpinEntrance_field_player_avatar(u8 taskId);

void DoPlayerSpinEntrance(void)
{
    Task_DoPlayerSpinEntrance_field_player_avatar(CreateTask(Task_DoPlayerSpinEntrance_field_player_avatar, 0));
}

bool32 IsPlayerSpinEntranceActive(void)
{
    return FuncIsActiveTask(Task_DoPlayerSpinEntrance_field_player_avatar);
}

void DoPlayerSpinExit(void)
{
    Task_DoPlayerSpinExit_field_player_avatar(CreateTask(Task_DoPlayerSpinExit_field_player_avatar, 0));
}

bool32 IsPlayerSpinExitActive(void)
{
    return FuncIsActiveTask(Task_DoPlayerSpinExit_field_player_avatar);
}

static const u8  sSpinDirections_field_player_avatar[] = {DIR_SOUTH, DIR_WEST, DIR_EAST, DIR_NORTH, DIR_SOUTH};

static void Task_DoPlayerSpinEntrance_field_player_avatar(u8 taskId)
{
    struct ObjectEvent *object = &gObjectEvents[gPlayerAvatar.objectEventId];
    struct Sprite *sprite = &gSprites[object->spriteId];
    s16 *data = gTasks[taskId].data;

    switch (tState_field_player_avatar)
    {
        case 0:
            // Because the spin start facing direction is never set for this
            // warp type, the player will always exit the warp facing South.
            // This may have been intentional, unclear
            tStartDir_field_player_avatar = GetSpinStartFacingDir_field_player_avatar();
            ObjectEventForceSetHeldMovement(object, GetFaceDirectionMovementAction(sSpinDirections_field_player_avatar[tStartDir_field_player_avatar]));
            tSpinDelayTimer_field_player_avatar = 0;
            tSpeed_field_player_avatar = 116;
            tDestY_field_player_avatar = sprite->y;
            tPriority_field_player_avatar = sprite->oam.priority;
            tSubpriority_field_player_avatar = sprite->subpriority;
            tCurY_field_player_avatar = -((u16)sprite->y2 + 32) * 16;
            sprite->y2 = 0;
            CameraObjectFreeze();
            object->fixedPriority = TRUE;
            sprite->oam.priority = 1;
            sprite->subpriority = 0;
            sprite->subspriteMode = SUBSPRITES_OFF;
            tState_field_player_avatar++;
        case 1: // Spin while descending
            TrySpinPlayerForWarp_field_player_avatar(object, &tSpinDelayTimer_field_player_avatar);

            // Fall and decelerate
            tCurY_field_player_avatar += tSpeed_field_player_avatar;
            tSpeed_field_player_avatar -= 3;
            if (tSpeed_field_player_avatar < 4)
                tSpeed_field_player_avatar = 4;
            sprite->y = tCurY_field_player_avatar >> 4;

            // Check if reached dest
            if (sprite->y >= tDestY_field_player_avatar)
            {
                sprite->y = tDestY_field_player_avatar;
                tGroundTimer_field_player_avatar = 0;
                tState_field_player_avatar++;
            }
            break;
        case 2: // Spin on ground
            TrySpinPlayerForWarp_field_player_avatar(object, &tSpinDelayTimer_field_player_avatar);
            if (++tGroundTimer_field_player_avatar > 8)
                tState_field_player_avatar++;
            break;
        case 3: // Spin until facing original direction
            if (tStartDir_field_player_avatar == TrySpinPlayerForWarp_field_player_avatar(object, &tSpinDelayTimer_field_player_avatar))
            {
                object->fixedPriority = 0;
                sprite->oam.priority = tPriority_field_player_avatar;
                sprite->subpriority = tSubpriority_field_player_avatar;
                CameraObjectReset();
                DestroyTask(taskId);
            }
            break;
    }
}

static u8 TrySpinPlayerForWarp_field_player_avatar(struct ObjectEvent *object, s16 *delayTimer)
{
    if (*delayTimer < 8 && ++(*delayTimer) < 8)
        return object->facingDirection;

    if (!ObjectEventCheckHeldMovementStatus(object))
        return object->facingDirection;

    ObjectEventForceSetHeldMovement(object, GetFaceDirectionMovementAction(sSpinDirections_field_player_avatar[object->facingDirection]));
    *delayTimer = 0;
    return sSpinDirections_field_player_avatar[object->facingDirection];
}

//sideways stairs
u8 GetRightSideStairsDirection(u8 direction)
{
    switch (direction)
    {
    case DIR_WEST:
        return DIR_NORTHWEST;
    case DIR_EAST:
        return DIR_SOUTHEAST;
    default:
        if (direction > DIR_EAST)
            direction -= DIR_EAST;
        return direction;
    }
}

u8 GetLeftSideStairsDirection(u8 direction)
{
    switch (direction)
    {
    case DIR_WEST:
        return DIR_SOUTHWEST;
    case DIR_EAST:
        return DIR_NORTHEAST;
    default:
        if (direction > DIR_EAST)
            direction -= DIR_EAST;
        return direction;
    }
}

bool8 ObjectMovingOnRockStairs(struct ObjectEvent *objectEvent, u8 direction)
{
    #if SLOW_MOVEMENT_ON_STAIRS == TRUE
        s16 x = objectEvent->currentCoords.x;
        s16 y = objectEvent->currentCoords.y;

        // TODO followers on sideways stairs
        if (IsFollowerVisible() && GetFollowerObject() != NULL && (objectEvent->isPlayer || objectEvent->localId == OBJ_EVENT_ID_FOLLOWER))
            return FALSE;

        switch (direction)
        {
        case DIR_NORTH:
            return MetatileBehavior_IsRockStairs(MapGridGetMetatileBehaviorAt(x,y));
        case DIR_SOUTH:
            MoveCoords(DIR_SOUTH, &x, &y);
            return MetatileBehavior_IsRockStairs(MapGridGetMetatileBehaviorAt(x,y));
        case DIR_WEST:
        case DIR_EAST:
        case DIR_NORTHEAST:
        case DIR_NORTHWEST:
        case DIR_SOUTHWEST:
        case DIR_SOUTHEAST:
            // directionOverwrite is only used for sideways stairs motion
            if (objectEvent->directionOverwrite)
                return TRUE;
        default:
            return FALSE;
        }
    #else
        return FALSE;
    #endif
}

