void FieldInitRegionMap(MainCallback callback)
{
    SetVBlankCallback(NULL);
    sFieldRegionMapHandler = Alloc(sizeof(*sFieldRegionMapHandler));
    sFieldRegionMapHandler->state = 0;
    sFieldRegionMapHandler->callback = callback;
    SetMainCallback2(MCB2_InitRegionMapRegisters_field_region_map);
}

static void MCB2_InitRegionMapRegisters_field_region_map(void)
{
    SetGpuReg(REG_OFFSET_DISPCNT, 0);
    SetGpuReg(REG_OFFSET_BG0HOFS, 0);
    SetGpuReg(REG_OFFSET_BG0VOFS, 0);
    SetGpuReg(REG_OFFSET_BG1HOFS, 0);
    SetGpuReg(REG_OFFSET_BG1VOFS, 0);
    SetGpuReg(REG_OFFSET_BG2HOFS, 0);
    SetGpuReg(REG_OFFSET_BG2VOFS, 0);
    SetGpuReg(REG_OFFSET_BG3HOFS, 0);
    SetGpuReg(REG_OFFSET_BG3VOFS, 0);
    ResetSpriteData();
    FreeAllSpritePalettes();
    ResetBgsAndClearDma3BusyFlags(0);
    InitBgsFromTemplates(1, sFieldRegionMapBgTemplates_field_region_map, ARRAY_COUNT(sFieldRegionMapBgTemplates_field_region_map));
    InitWindows(sFieldRegionMapWindowTemplates_field_region_map);
    DeactivateAllTextPrinters();
    LoadUserWindowBorderGfx(0, 0x27, BG_PLTT_ID(13));
    ClearScheduledBgCopiesToVram();
    SetMainCallback2(MCB2_FieldUpdateRegionMap_field_region_map);
    SetVBlankCallback(VBCB_FieldUpdateRegionMap_field_region_map);
}

static void VBCB_FieldUpdateRegionMap_field_region_map(void)
{
    LoadOam();
    ProcessSpriteCopyRequests();
    TransferPlttBuffer();
}

static void MCB2_FieldUpdateRegionMap_field_region_map(void)
{
    FieldUpdateRegionMap_field_region_map();
    AnimateSprites();
    BuildOamBuffer();
    UpdatePaletteFade();
    DoScheduledBgTilemapCopiesToVram();
}

static void FieldUpdateRegionMap_field_region_map(void)
{
    switch (sFieldRegionMapHandler->state)
    {
        case 0:
            InitRegionMap(&sFieldRegionMapHandler->regionMap, FALSE);
            CreateRegionMapPlayerIcon(TAG_PLAYER_ICON_field_region_map, TAG_PLAYER_ICON_field_region_map);
            CreateRegionMapCursor(TAG_CURSOR_field_region_map, TAG_CURSOR_field_region_map);
            sFieldRegionMapHandler->state++;
            break;
        case 1:
            DrawStdFrameWithCustomTileAndPalette(WIN_TITLE_field_region_map, FALSE, 0x27, 0xd);
            FillWindowPixelBuffer(WIN_TITLE_field_region_map, PIXEL_FILL(1));
            PrintTitleWindowText_field_region_map();
            ScheduleBgCopyTilemapToVram(0);
            DrawStdFrameWithCustomTileAndPalette(WIN_MAPSEC_NAME_field_region_map, FALSE, 0x27, 0xd);
            PrintRegionMapSecName_field_region_map();
            BeginNormalPaletteFade(PALETTES_ALL, 0, 16, 0, RGB_BLACK);
            sFieldRegionMapHandler->state++;
            break;
        case 2:
            SetGpuRegBits(REG_OFFSET_DISPCNT, DISPCNT_OBJ_1D_MAP | DISPCNT_OBJ_ON);
            ShowBg(0);
            ShowBg(2);
            sFieldRegionMapHandler->state++;
            break;
        case 3:
            if (!gPaletteFade.active)
            {
                sFieldRegionMapHandler->state++;
            }
            break;
        case 4:
            switch (DoRegionMapInputCallback())
            {
                case MAP_INPUT_MOVE_END:
                    PrintRegionMapSecName_field_region_map();
                    PrintTitleWindowText_field_region_map();
                    break;
                case MAP_INPUT_A_BUTTON:
                case MAP_INPUT_B_BUTTON:
                    sFieldRegionMapHandler->state++;
                    break;
                case MAP_INPUT_R_BUTTON:
                    if (sFieldRegionMapHandler->regionMap.mapSecType == MAPSECTYPE_CITY_CANFLY 
                        && FlagGet(OW_FLAG_POKE_RIDER) && Overworld_MapTypeAllowsTeleportAndFly(gMapHeader.mapType) == TRUE)
                    {
                        PlaySE(SE_SELECT);
                        SetFlyDestination(&sFieldRegionMapHandler->regionMap);
                        gSkipShowMonAnim = TRUE;
                        ReturnToFieldFromFlyMapSelect();
                    }
            }
            break;
        case 5:
            BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
            sFieldRegionMapHandler->state++;
            break;
        case 6:
            if (!gPaletteFade.active)
            {
                FreeRegionMapIconResources();
                SetMainCallback2(sFieldRegionMapHandler->callback);
                TRY_FREE_AND_SET_NULL(sFieldRegionMapHandler);
                FreeAllWindowBuffers();
            }
            break;
    }
}

static void PrintRegionMapSecName_field_region_map(void)
{
    if (sFieldRegionMapHandler->regionMap.mapSecType != MAPSECTYPE_NONE)
    {
        FillWindowPixelBuffer(WIN_MAPSEC_NAME_field_region_map, PIXEL_FILL(1));
        AddTextPrinterParameterized(WIN_MAPSEC_NAME_field_region_map, FONT_NORMAL, sFieldRegionMapHandler->regionMap.mapSecName, 0, 1, 0, NULL);
        ScheduleBgCopyTilemapToVram(WIN_MAPSEC_NAME_field_region_map);
    }
    else
    {
        FillWindowPixelBuffer(WIN_MAPSEC_NAME_field_region_map, PIXEL_FILL(1));
        CopyWindowToVram(WIN_MAPSEC_NAME_field_region_map, COPYWIN_FULL);
    }
}

static void PrintTitleWindowText_field_region_map(void)
{
static const u8  FlyPromptText_field_region_map[] = _("{R_BUTTON} FLY");
    u32 hoennOffset = GetStringCenterAlignXOffset(FONT_NORMAL, gText_Hoenn, 0x38);
    u32 flyOffset = GetStringCenterAlignXOffset(FONT_NORMAL, FlyPromptText_field_region_map, 0x38);

    FillWindowPixelBuffer(WIN_TITLE_field_region_map, PIXEL_FILL(1));

    if (sFieldRegionMapHandler->regionMap.mapSecType == MAPSECTYPE_CITY_CANFLY
        && FlagGet(OW_FLAG_POKE_RIDER) && Overworld_MapTypeAllowsTeleportAndFly(gMapHeader.mapType) == TRUE)
    {
        AddTextPrinterParameterized(WIN_TITLE_field_region_map, FONT_NORMAL, FlyPromptText_field_region_map, flyOffset, 1, 0, NULL);
        ScheduleBgCopyTilemapToVram(WIN_TITLE_field_region_map);
    }
    else
    {
        AddTextPrinterParameterized(WIN_TITLE_field_region_map, FONT_NORMAL, gText_Hoenn, hoennOffset, 1, 0, NULL);
        CopyWindowToVram(WIN_TITLE_field_region_map, COPYWIN_FULL);
    }
}
