static void SetUpWarpExitTask_field_screen_effect(void)
{
    s16 x, y;
    u8 behavior;
    TaskFunc func;

    PlayerGetDestCoords(&x, &y);
    behavior = MapGridGetMetatileBehaviorAt(x, y);
    if (MetatileBehavior_IsDoor(behavior) == TRUE)
        func = Task_ExitDoor_field_screen_effect;
    else if (MetatileBehavior_IsDirectionalStairWarp(behavior) == TRUE && !gExitStairsMovementDisabled)
        func = Task_ExitStairs_field_screen_effect;
    else if (MetatileBehavior_IsNonAnimDoor(behavior) == TRUE)
        func = Task_ExitNonAnimDoor_field_screen_effect;
    else
        func = Task_ExitNonDoor_field_screen_effect;

    gExitStairsMovementDisabled = FALSE;
    CreateTask(func, 10);
}

