static void SetFlashScanlineEffectWindowBoundary_field_screen_effect(u16 *dest, u32 y, s32 left, s32 right)
{
    if (y <= 160)
    {
        if (left < 0)
            left = 0;
        if (left > 255)
            left = 255;
        if (right < 0)
            right = 0;
        if (right > 255)
            right = 255;
        dest[y] = (left << 8) | right;
    }
}

static void SetFlashScanlineEffectWindowBoundaries_field_screen_effect(u16 *dest, s32 centerX, s32 centerY, s32 radius)
{
    s32 r = radius;
    s32 v2 = radius;
    s32 v3 = 0;
    while (r >= v3)
    {
        SetFlashScanlineEffectWindowBoundary_field_screen_effect(dest, centerY - v3, centerX - r, centerX + r);
        SetFlashScanlineEffectWindowBoundary_field_screen_effect(dest, centerY + v3, centerX - r, centerX + r);
        SetFlashScanlineEffectWindowBoundary_field_screen_effect(dest, centerY - r, centerX - v3, centerX + v3);
        SetFlashScanlineEffectWindowBoundary_field_screen_effect(dest, centerY + r, centerX - v3, centerX + v3);
        v2 -= (v3 * 2) - 1;
        v3++;
        if (v2 < 0)
        {
            v2 += 2 * (r - 1);
            r--;
        }
    }
}

static void SetOrbFlashScanlineEffectWindowBoundary_field_screen_effect(u16 *dest, u32 y, s32 left, s32 right)
{
    if (y <= 160)
    {
        if (left < 0)
            left = 0;
        if (left > 240)
            left = 240;
        if (right < 0)
            right = 0;
        if (right > 240)
            right = 240;
        dest[y] = (left << 8) | right;
    }
}

static void SetOrbFlashScanlineEffectWindowBoundaries_field_screen_effect(u16 *dest, s32 centerX, s32 centerY, s32 radius)
{
    s32 r = radius;
    s32 v2 = radius;
    s32 v3 = 0;
    while (r >= v3)
    {
        SetOrbFlashScanlineEffectWindowBoundary_field_screen_effect(dest, centerY - v3, centerX - r, centerX + r);
        SetOrbFlashScanlineEffectWindowBoundary_field_screen_effect(dest, centerY + v3, centerX - r, centerX + r);
        SetOrbFlashScanlineEffectWindowBoundary_field_screen_effect(dest, centerY - r, centerX - v3, centerX + v3);
        SetOrbFlashScanlineEffectWindowBoundary_field_screen_effect(dest, centerY + r, centerX - v3, centerX + v3);
        v2 -= (v3 * 2) - 1;
        v3++;
        if (v2 < 0)
        {
            v2 += 2 * (r - 1);
            r--;
        }
    }
}

#define tFlashCenterX_field_screen_effect        data[1]
#define tFlashCenterY_field_screen_effect        data[2]
#define tCurFlashRadius_field_screen_effect      data[3]
#define tDestFlashRadius_field_screen_effect     data[4]
#define tFlashRadiusDelta_field_screen_effect    data[5]
#define tClearScanlineEffect_field_screen_effect data[6]

static void UpdateFlashLevelEffect_field_screen_effect(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    switch (tState_field_screen_effect)
    {
    case 0:
        SetFlashScanlineEffectWindowBoundaries_field_screen_effect(gScanlineEffectRegBuffers[gScanlineEffect.srcBuffer], tFlashCenterX_field_screen_effect, tFlashCenterY_field_screen_effect, tCurFlashRadius_field_screen_effect);
        tState_field_screen_effect = 1;
        break;
    case 1:
        SetFlashScanlineEffectWindowBoundaries_field_screen_effect(gScanlineEffectRegBuffers[gScanlineEffect.srcBuffer], tFlashCenterX_field_screen_effect, tFlashCenterY_field_screen_effect, tCurFlashRadius_field_screen_effect);
        tState_field_screen_effect = 0;
        tCurFlashRadius_field_screen_effect += tFlashRadiusDelta_field_screen_effect;
        if (tCurFlashRadius_field_screen_effect > tDestFlashRadius_field_screen_effect)
        {
            if (tClearScanlineEffect_field_screen_effect == 1)
            {
                ScanlineEffect_Stop();
                tState_field_screen_effect = 2;
            }
            else
            {
                DestroyTask(taskId);
            }
        }
        break;
    case 2:
        ScanlineEffect_Clear();
        DestroyTask(taskId);
        break;
    }
}

static void UpdateOrbFlashEffect_field_screen_effect(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    switch (tState_field_screen_effect)
    {
    case 0:
        SetOrbFlashScanlineEffectWindowBoundaries_field_screen_effect(gScanlineEffectRegBuffers[gScanlineEffect.srcBuffer], tFlashCenterX_field_screen_effect, tFlashCenterY_field_screen_effect, tCurFlashRadius_field_screen_effect);
        tState_field_screen_effect = 1;
        break;
    case 1:
        SetOrbFlashScanlineEffectWindowBoundaries_field_screen_effect(gScanlineEffectRegBuffers[gScanlineEffect.srcBuffer], tFlashCenterX_field_screen_effect, tFlashCenterY_field_screen_effect, tCurFlashRadius_field_screen_effect);
        tState_field_screen_effect = 0;
        tCurFlashRadius_field_screen_effect += tFlashRadiusDelta_field_screen_effect;
        if (tCurFlashRadius_field_screen_effect > tDestFlashRadius_field_screen_effect)
        {
            if (tClearScanlineEffect_field_screen_effect == 1)
            {
                ScanlineEffect_Stop();
                tState_field_screen_effect = 2;
            }
            else
            {
                DestroyTask(taskId);
            }
        }
        break;
    case 2:
        ScanlineEffect_Clear();
        DestroyTask(taskId);
        break;
    }
}

static void Task_WaitForFlashUpdate_field_screen_effect(u8 taskId)
{
    if (!FuncIsActiveTask(UpdateFlashLevelEffect_field_screen_effect))
    {
        ScriptContext_Enable();
        DestroyTask(taskId);
    }
}

static void StartWaitForFlashUpdate_field_screen_effect(void)
{
    if (!FuncIsActiveTask(Task_WaitForFlashUpdate_field_screen_effect))
        CreateTask(Task_WaitForFlashUpdate_field_screen_effect, 80);
}

static u8 StartUpdateFlashLevelEffect_field_screen_effect(s32 centerX, s32 centerY, s32 initialFlashRadius, s32 destFlashRadius, s32 clearScanlineEffect, u8 delta)
{
    u8 taskId = CreateTask(UpdateFlashLevelEffect_field_screen_effect, 80);
    s16 *data = gTasks[taskId].data;

    tCurFlashRadius_field_screen_effect = initialFlashRadius;
    tDestFlashRadius_field_screen_effect = destFlashRadius;
    tFlashCenterX_field_screen_effect = centerX;
    tFlashCenterY_field_screen_effect = centerY;
    tClearScanlineEffect_field_screen_effect = clearScanlineEffect;

    if (initialFlashRadius < destFlashRadius)
        tFlashRadiusDelta_field_screen_effect = delta;
    else
        tFlashRadiusDelta_field_screen_effect = -delta;

    return taskId;
}

static u8 StartUpdateOrbFlashEffect_field_screen_effect(s32 centerX, s32 centerY, s32 initialFlashRadius, s32 destFlashRadius, s32 clearScanlineEffect, u8 delta)
{
    u8 taskId = CreateTask(UpdateOrbFlashEffect_field_screen_effect, 80);
    s16 *data = gTasks[taskId].data;

    tCurFlashRadius_field_screen_effect = initialFlashRadius;
    tDestFlashRadius_field_screen_effect = destFlashRadius;
    tFlashCenterX_field_screen_effect = centerX;
    tFlashCenterY_field_screen_effect = centerY;
    tClearScanlineEffect_field_screen_effect = clearScanlineEffect;

    if (initialFlashRadius < destFlashRadius)
        tFlashRadiusDelta_field_screen_effect = delta;
    else
        tFlashRadiusDelta_field_screen_effect = -delta;

    return taskId;
}

#undef tCurFlashRadius_field_screen_effect
#undef tDestFlashRadius_field_screen_effect
#undef tFlashRadiusDelta_field_screen_effect
#undef tClearScanlineEffect_field_screen_effect

// A higher flash level is a smaller flash radius (more darkness). 0 is full brightness
void AnimateFlash(u8 newFlashLevel)
{
    u8 curFlashLevel = GetFlashLevel();
    bool8 fullBrightness = FALSE;
    if (newFlashLevel == 0)
        fullBrightness = TRUE;
    StartUpdateFlashLevelEffect_field_screen_effect(DISPLAY_WIDTH / 2, DISPLAY_HEIGHT / 2, sFlashLevelToRadius_field_screen_effect[curFlashLevel], sFlashLevelToRadius_field_screen_effect[newFlashLevel], fullBrightness, 1);
    StartWaitForFlashUpdate_field_screen_effect();
    LockPlayerFieldControls();
}

void WriteFlashScanlineEffectBuffer(u8 flashLevel)
{
    if (flashLevel)
    {
        SetFlashScanlineEffectWindowBoundaries_field_screen_effect(&gScanlineEffectRegBuffers[0][0], DISPLAY_WIDTH / 2, DISPLAY_HEIGHT / 2, sFlashLevelToRadius_field_screen_effect[flashLevel]);
        CpuFastSet(&gScanlineEffectRegBuffers[0], &gScanlineEffectRegBuffers[1], 480);
    }
}

void WriteBattlePyramidViewScanlineEffectBuffer(void)
{
    SetFlashScanlineEffectWindowBoundaries_field_screen_effect(&gScanlineEffectRegBuffers[0][0], DISPLAY_WIDTH / 2, DISPLAY_HEIGHT / 2, gSaveBlock2Ptr->frontier.pyramidLightRadius);
    CpuFastSet(&gScanlineEffectRegBuffers[0], &gScanlineEffectRegBuffers[1], 480);
}

static void Task_SpinEnterWarp_field_screen_effect(u8 taskId)
{
    switch (gTasks[taskId].tState_field_screen_effect)
    {
    case 0:
        FreezeObjectEvents();
        LockPlayerFieldControls();
        DoPlayerSpinEntrance();
        gTasks[taskId].tState_field_screen_effect++;
        break;
    case 1:
        if (WaitForWeatherFadeIn_field_screen_effect() && IsPlayerSpinEntranceActive() != TRUE)
        {
            UnfreezeObjectEvents();
            UnlockPlayerFieldControls();
            DestroyTask(taskId);
        }
        break;
    }
}

static void Task_SpinExitWarp_field_screen_effect(u8 taskId)
{
    struct Task *task = &gTasks[taskId];

    switch (task->tState_field_screen_effect)
    {
    case 0:
        FreezeObjectEvents();
        LockPlayerFieldControls();
        PlaySE(SE_WARP_IN);
        DoPlayerSpinExit();
        task->tState_field_screen_effect++;
        break;
    case 1:
        if (!IsPlayerSpinExitActive())
        {
            WarpFadeOutScreen();
            task->tState_field_screen_effect++;
        }
        break;
    case 2:
        if (!PaletteFadeActive_field_screen_effect() && BGMusicStopped())
            task->tState_field_screen_effect++;
        break;
    case 3:
        WarpIntoMap();
        SetMainCallback2(CB2_LoadMap);
        DestroyTask(taskId);
        break;
    }
}

// Only called by an unused function
// DoTeleportTileWarp is used instead
void DoSpinEnterWarp(void)
{
    LockPlayerFieldControls();
    CreateTask(Task_WarpAndLoadMap_field_screen_effect, 10);
    gFieldCallback = FieldCB_SpinEnterWarp_field_screen_effect;
}

// Opposite of DoSpinEnterWarp / DoTeleportTileWarp
// Player exits current map by spinning up offscreen, enters new map with a fade in
void DoSpinExitWarp(void)
{
    LockPlayerFieldControls();
    gFieldCallback = FieldCB_DefaultWarpExit;
    CreateTask(Task_SpinExitWarp_field_screen_effect, 10);
}

static void LoadOrbEffectPalette_field_screen_effect(bool8 blueOrb)
{
    int i;
    u16 color[1];

    if (!blueOrb)
        color[0] = RGB_RED;
    else
        color[0] = RGB_BLUE;

    for (i = 0; i < 16; i++)
        LoadPalette(color, BG_PLTT_ID(15) + i, PLTT_SIZEOF(1));
}

static bool8 UpdateOrbEffectBlend_field_screen_effect(u16 shakeDir)
{
    u8 lo = REG_BLDALPHA & 0xFF;
    u8 hi = REG_BLDALPHA >> 8;

    if (shakeDir != 0)
    {
        if (lo)
            lo--;
    }
    else
    {
        if (hi < 16)
            hi++;
    }

    SetGpuReg(REG_OFFSET_BLDALPHA, BLDALPHA_BLEND(lo, hi));

    if (lo == 0 && hi == 16)
        return TRUE;
    else
        return FALSE;
}

#define tBlueOrb_field_screen_effect     data[1]
#define tCenterX_field_screen_effect     data[2]
#define tCenterY_field_screen_effect     data[3]
#define tShakeDelay_field_screen_effect  data[4]
#define tShakeDir_field_screen_effect    data[5]
#define tDispCnt_field_screen_effect     data[6]
#define tBldCnt_field_screen_effect      data[7]
#define tBldAlpha_field_screen_effect    data[8]
#define tWinIn_field_screen_effect       data[9]
#define tWinOut_field_screen_effect      data[10]

static void Task_OrbEffect_field_screen_effect(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    switch (tState_field_screen_effect)
    {
    case 0:
        tDispCnt_field_screen_effect = REG_DISPCNT;
        tBldCnt_field_screen_effect = REG_BLDCNT;
        tBldAlpha_field_screen_effect = REG_BLDALPHA;
        tWinIn_field_screen_effect = REG_WININ;
        tWinOut_field_screen_effect = REG_WINOUT;
        ClearGpuRegBits(REG_OFFSET_DISPCNT, DISPCNT_WIN1_ON);
        SetGpuRegBits(REG_OFFSET_BLDCNT, gOrbEffectBackgroundLayerFlags[0]);
        SetGpuReg(REG_OFFSET_BLDALPHA, BLDALPHA_BLEND(12, 7));
        SetGpuReg(REG_OFFSET_WININ, WININ_WIN0_BG_ALL | WININ_WIN0_OBJ | WININ_WIN0_CLR);
        SetGpuReg(REG_OFFSET_WINOUT, WINOUT_WIN01_BG1 | WINOUT_WIN01_BG2 | WINOUT_WIN01_BG3 | WINOUT_WIN01_OBJ);
        SetBgTilemapPalette(0, 0, 0, DISPLAY_TILE_WIDTH, DISPLAY_TILE_HEIGHT, 0xF);
        ScheduleBgCopyTilemapToVram(0);
        SetOrbFlashScanlineEffectWindowBoundaries_field_screen_effect(&gScanlineEffectRegBuffers[0][0], tCenterX_field_screen_effect, tCenterY_field_screen_effect, 1);
        CpuFastSet(&gScanlineEffectRegBuffers[0], &gScanlineEffectRegBuffers[1], 480);
        ScanlineEffect_SetParams(sFlashEffectParams_field_screen_effect);
        tState_field_screen_effect = 1;
        break;
    case 1:
        BgDmaFill(0, PIXEL_FILL(1), 0, 1);
        LoadOrbEffectPalette_field_screen_effect(tBlueOrb_field_screen_effect);
        StartUpdateOrbFlashEffect_field_screen_effect(tCenterX_field_screen_effect, tCenterY_field_screen_effect, 1, 160, 1, 2);
        tState_field_screen_effect = 2;
        break;
    case 2:
        if (!FuncIsActiveTask(UpdateOrbFlashEffect_field_screen_effect))
        {
            ScriptContext_Enable();
            tState_field_screen_effect = 3;
        }
        break;
    case 3:
        InstallCameraPanAheadCallback();
        SetCameraPanningCallback(NULL);
        tShakeDir_field_screen_effect = 0;
        tShakeDelay_field_screen_effect = 4;
        tState_field_screen_effect = 4;
        break;
    case 4:
        // If the caller script is delayed after starting the orb effect, a `waitstate` might be reached *after*
        // we enable the ScriptContext in case 2; enabling it here as well avoids softlocks in this scenario
        ScriptContext_Enable();
        if (--tShakeDelay_field_screen_effect == 0)
        {
            s32 panning;
            tShakeDelay_field_screen_effect = 4;
            tShakeDir_field_screen_effect ^= 1;
            if (tShakeDir_field_screen_effect)
                panning = 4;
            else
                panning = -4;
            SetCameraPanning(0, panning);
        }
        break;
    case 6:
        InstallCameraPanAheadCallback();
        tShakeDelay_field_screen_effect = 8;
        tState_field_screen_effect = 7;
        break;
    case 7:
        if (--tShakeDelay_field_screen_effect == 0)
        {
            tShakeDelay_field_screen_effect = 8;
            tShakeDir_field_screen_effect ^= 1;
            if (UpdateOrbEffectBlend_field_screen_effect(tShakeDir_field_screen_effect) == TRUE)
            {
                tState_field_screen_effect = 5;
                BgDmaFill(0, PIXEL_FILL(0), 0, 1);
            }
        }
        break;
    case 5:
        SetGpuReg(REG_OFFSET_WIN0H, 255);
        SetGpuReg(REG_OFFSET_DISPCNT, tDispCnt_field_screen_effect);
        SetGpuReg(REG_OFFSET_BLDCNT, tBldCnt_field_screen_effect);
        SetGpuReg(REG_OFFSET_BLDALPHA, tBldAlpha_field_screen_effect);
        SetGpuReg(REG_OFFSET_WININ, tWinIn_field_screen_effect);
        SetGpuReg(REG_OFFSET_WINOUT, tWinOut_field_screen_effect);
        ScriptContext_Enable();
        DestroyTask(taskId);
        break;
    }
}

void DoOrbEffect(void)
{
    u8 taskId = CreateTask(Task_OrbEffect_field_screen_effect, 80);
    s16 *data = gTasks[taskId].data;

    if (gSpecialVar_Result == 0)
    {
        tBlueOrb_field_screen_effect = FALSE;
        tCenterX_field_screen_effect = 104;
    }
    else if (gSpecialVar_Result == 1)
    {
        tBlueOrb_field_screen_effect = TRUE;
        tCenterX_field_screen_effect = 136;
    }
    else if (gSpecialVar_Result == 2)
    {
        tBlueOrb_field_screen_effect = FALSE;
        tCenterX_field_screen_effect = 120;
    }
    else
    {
        tBlueOrb_field_screen_effect = TRUE;
        tCenterX_field_screen_effect = 120;
    }

    tCenterY_field_screen_effect = 80;
}

void FadeOutOrbEffect(void)
{
    u8 taskId = FindTaskIdByFunc(Task_OrbEffect_field_screen_effect);
    gTasks[taskId].tState_field_screen_effect = 6;
}

#undef tBlueOrb_field_screen_effect
