static bool32 IsBuildingPCTile_field_specials(u32 tileId)
{
    return gMapHeader.mapLayout->primaryTileset == &gTileset_Building && (tileId == METATILE_Building_PC_On || tileId == METATILE_Building_PC_Off);
}

static bool32 IsPlayerHousePCTile_field_specials(u32 tileId)
{
    return gMapHeader.mapLayout->secondaryTileset == &gTileset_BrendansMaysHouse
        && (tileId == METATILE_BrendansMaysHouse_BrendanPC_On
            || tileId == METATILE_BrendansMaysHouse_BrendanPC_Off
            || tileId == METATILE_BrendansMaysHouse_MayPC_On
            || tileId == METATILE_BrendansMaysHouse_MayPC_Off);
}

static bool8 IsPlayerInFrontOfPC_field_specials(void)
{
    s16 x, y;
    u32 tileInFront;

    GetXYCoordsOneStepInFrontOfPlayer(&x, &y);
    tileInFront = MapGridGetMetatileIdAt(x, y);

    return IsBuildingPCTile_field_specials(tileInFront) || IsPlayerHousePCTile_field_specials(tileInFront);
}

// Task data for Task_PCTurnOnEffect_field_specials and Task_LotteryCornerComputerEffect_field_specials
#define tPaused_field_specials       data[0] // Never set
#define tTaskId_field_specials       data[1]
#define tFlickerCount_field_specials data[2]
#define tTimer_field_specials        data[3]
#define tIsScreenOn_field_specials   data[4]

// For this special, gSpecialVar_0x8004 is expected to be some PC_LOCATION_* value.
void DoPCTurnOnEffect(void)
{
    if (FuncIsActiveTask(Task_PCTurnOnEffect_field_specials) != TRUE && IsPlayerInFrontOfPC_field_specials() == TRUE)
    {
        u8 taskId = CreateTask(Task_PCTurnOnEffect_field_specials, 8);
        gTasks[taskId].tPaused_field_specials = FALSE;
        gTasks[taskId].tTaskId_field_specials = taskId;
        gTasks[taskId].tFlickerCount_field_specials = 0;
        gTasks[taskId].tTimer_field_specials = 0;
        gTasks[taskId].tIsScreenOn_field_specials = FALSE;
    }
}

static void Task_PCTurnOnEffect_field_specials(u8 taskId)
{
    struct Task *task = &gTasks[taskId];
    if (!task->tPaused_field_specials)
        PCTurnOnEffect_field_specials(task);
}

static void PCTurnOnEffect_field_specials(struct Task *task)
{
    u8 playerDirection;
    s8 dx = 0;
    s8 dy = 0;
    if (task->tTimer_field_specials == 6)
    {
        task->tTimer_field_specials = 0;

        // Get where the PC should be, depending on where the player is looking.
        playerDirection = GetPlayerFacingDirection();
        switch (playerDirection)
        {
        case DIR_NORTH:
            dx = 0;
            dy = -1;
            break;
        case DIR_WEST:
            dx = -1;
            dy = -1;
            break;
        case DIR_EAST:
            dx = 1;
            dy = -1;
            break;
        }

        // Update map
        PCTurnOnEffect_SetMetatile_field_specials(task->tIsScreenOn_field_specials, dx, dy);
        DrawWholeMapView();

        // Screen flickers 5 times. Odd number and starting with the
        // screen off means the animation ends with the screen on.
        task->tIsScreenOn_field_specials ^= 1;
        if (++task->tFlickerCount_field_specials == 5)
            DestroyTask(task->tTaskId_field_specials);
    }
    task->tTimer_field_specials++;
}

static void PCTurnOnEffect_SetMetatile_field_specials(s16 isScreenOn, s8 dx, s8 dy)
{
    u16 metatileId = 0;
    if (isScreenOn)
    {
        // Screen is on, set it off
        if (gSpecialVar_0x8004 == PC_LOCATION_OTHER)
            metatileId = METATILE_Building_PC_Off;
        else if (gSpecialVar_0x8004 == PC_LOCATION_BRENDANS_HOUSE)
            metatileId = METATILE_BrendansMaysHouse_BrendanPC_Off;
        else if (gSpecialVar_0x8004 == PC_LOCATION_MAYS_HOUSE)
            metatileId = METATILE_BrendansMaysHouse_MayPC_Off;
    }
    else
    {
        // Screen is off, set it on
        if (gSpecialVar_0x8004 == PC_LOCATION_OTHER)
            metatileId = METATILE_Building_PC_On;
        else if (gSpecialVar_0x8004 == PC_LOCATION_BRENDANS_HOUSE)
            metatileId = METATILE_BrendansMaysHouse_BrendanPC_On;
        else if (gSpecialVar_0x8004 == PC_LOCATION_MAYS_HOUSE)
            metatileId = METATILE_BrendansMaysHouse_MayPC_On;
    }
    MapGridSetMetatileIdAt(gSaveBlock1Ptr->pos.x + dx + MAP_OFFSET, gSaveBlock1Ptr->pos.y + dy + MAP_OFFSET, metatileId | MAPGRID_COLLISION_MASK);
}

// For this special, gSpecialVar_0x8004 is expected to be some PC_LOCATION_* value.
void DoPCTurnOffEffect(void)
{
    PCTurnOffEffect_field_specials();
}

static void PCTurnOffEffect_field_specials(void)
{
    s8 dx = 0;
    s8 dy = 0;
    u16 metatileId = 0;

    // Get where the PC should be, depending on where the player is looking.
    u8 playerDirection = GetPlayerFacingDirection();

    if (IsPlayerInFrontOfPC_field_specials() == FALSE)
        return;
    switch (playerDirection)
    {
    case DIR_NORTH:
        dx = 0;
        dy = -1;
        break;
    case DIR_WEST:
        dx = -1;
        dy = -1;
        break;
    case DIR_EAST:
        dx = 1;
        dy = -1;
        break;
    }

    if (gSpecialVar_0x8004 == PC_LOCATION_OTHER)
        metatileId = METATILE_Building_PC_Off;
    else if (gSpecialVar_0x8004 == PC_LOCATION_BRENDANS_HOUSE)
        metatileId = METATILE_BrendansMaysHouse_BrendanPC_Off;
    else if (gSpecialVar_0x8004 == PC_LOCATION_MAYS_HOUSE)
        metatileId = METATILE_BrendansMaysHouse_MayPC_Off;

    MapGridSetMetatileIdAt(gSaveBlock1Ptr->pos.x + dx + MAP_OFFSET, gSaveBlock1Ptr->pos.y + dy + MAP_OFFSET, metatileId | MAPGRID_COLLISION_MASK);
    DrawWholeMapView();
}

void DoLotteryCornerComputerEffect(void)
{
    if (FuncIsActiveTask(Task_LotteryCornerComputerEffect_field_specials) != TRUE)
    {
        u8 taskId = CreateTask(Task_LotteryCornerComputerEffect_field_specials, 8);
        gTasks[taskId].tPaused_field_specials = FALSE;
        gTasks[taskId].tTaskId_field_specials = taskId;
        gTasks[taskId].tFlickerCount_field_specials = 0;
        gTasks[taskId].tTimer_field_specials = 0;
        gTasks[taskId].tIsScreenOn_field_specials = FALSE;
    }
}

static void Task_LotteryCornerComputerEffect_field_specials(u8 taskId)
{
    struct Task *task = &gTasks[taskId];
    if (!task->tPaused_field_specials)
        LotteryCornerComputerEffect_field_specials(task);
}

static void LotteryCornerComputerEffect_field_specials(struct Task *task)
{
    if (task->tTimer_field_specials == 6)
    {
        task->tTimer_field_specials = 0;
        if (task->tIsScreenOn_field_specials)
        {
            // Screen is on, set it off
            MapGridSetMetatileIdAt(11 + MAP_OFFSET, 1 + MAP_OFFSET, METATILE_Shop_Laptop1_Normal | MAPGRID_COLLISION_MASK);
            MapGridSetMetatileIdAt(11 + MAP_OFFSET, 2 + MAP_OFFSET, METATILE_Shop_Laptop2_Normal | MAPGRID_COLLISION_MASK);
        }
        else
        {
            // Screen is off, set it on
            MapGridSetMetatileIdAt(11 + MAP_OFFSET, 1 + MAP_OFFSET, METATILE_Shop_Laptop1_Flash | MAPGRID_COLLISION_MASK);
            MapGridSetMetatileIdAt(11 + MAP_OFFSET, 2 + MAP_OFFSET, METATILE_Shop_Laptop2_Flash | MAPGRID_COLLISION_MASK);
        }
        DrawWholeMapView();

        // Screen flickers 5 times. Odd number and starting with the
        // screen off means the animation ends with the screen on.
        task->tIsScreenOn_field_specials ^= 1;
        if (++task->tFlickerCount_field_specials == 5)
            DestroyTask(task->tTaskId_field_specials);
    }
    task->tTimer_field_specials++;
}

void EndLotteryCornerComputerEffect(void)
{
    MapGridSetMetatileIdAt(11 + MAP_OFFSET, 1 + MAP_OFFSET, METATILE_Shop_Laptop1_Normal | MAPGRID_COLLISION_MASK);
    MapGridSetMetatileIdAt(11 + MAP_OFFSET, 2 + MAP_OFFSET, METATILE_Shop_Laptop2_Normal | MAPGRID_COLLISION_MASK);
    DrawWholeMapView();
}

#undef tPaused_field_specials
#undef tTaskId_field_specials
#undef tFlickerCount_field_specials
#undef tTimer_field_specials
#undef tIsScreenOn_field_specials

