u16 GetSlotMachineId(void)
{
static const u8  sSlotMachineRandomSeeds_field_specials[SLOT_MACHINE_COUNT] = {12, 2, 4, 5, 1, 8, 7, 11, 3, 10, 9, 6};
static const u8  sSlotMachineIds_field_specials[SLOT_MACHINE_COUNT] = {
        SLOT_MACHINE_UNLUCKIEST,
        SLOT_MACHINE_UNLUCKIER,
        SLOT_MACHINE_UNLUCKIER,
        SLOT_MACHINE_UNLUCKY,
        SLOT_MACHINE_UNLUCKY,
        SLOT_MACHINE_UNLUCKY,
        SLOT_MACHINE_LUCKY,
        SLOT_MACHINE_LUCKY,
        SLOT_MACHINE_LUCKY,
        SLOT_MACHINE_LUCKIER,
        SLOT_MACHINE_LUCKIER,
        SLOT_MACHINE_LUCKIEST
    };
static const u8  sSlotMachineServiceDayIds_field_specials[SLOT_MACHINE_COUNT] = {
        SLOT_MACHINE_LUCKY,
        SLOT_MACHINE_LUCKY,
        SLOT_MACHINE_LUCKY,
        SLOT_MACHINE_LUCKY,
        SLOT_MACHINE_LUCKY,
        SLOT_MACHINE_LUCKY,
        SLOT_MACHINE_LUCKIER,
        SLOT_MACHINE_LUCKIER,
        SLOT_MACHINE_LUCKIER,
        SLOT_MACHINE_LUCKIER,
        SLOT_MACHINE_LUCKIEST,
        SLOT_MACHINE_LUCKIEST
    };

    u32 rnd = gSaveBlock1Ptr->dewfordTrends[0].trendiness + gSaveBlock1Ptr->dewfordTrends[0].rand + sSlotMachineRandomSeeds_field_specials[gSpecialVar_0x8004];
    if (IsPokeNewsActive(POKENEWS_GAME_CORNER))
        return sSlotMachineServiceDayIds_field_specials[rnd % SLOT_MACHINE_COUNT];

    return sSlotMachineIds_field_specials[rnd % SLOT_MACHINE_COUNT];
}

