// Task data for Task_ShakeCamera_field_specials
#define tHorizontalPan_field_specials  data[0]
#define tDelayCounter_field_specials   data[1]
#define tNumShakes_field_specials      data[2]
#define tDelay_field_specials          data[3]
#define tVerticalPan_field_specials    data[4]

void ShakeCamera(void)
{
    u8 taskId = CreateTask(Task_ShakeCamera_field_specials, 9);
    gTasks[taskId].tHorizontalPan_field_specials = gSpecialVar_0x8005;
    gTasks[taskId].tDelayCounter_field_specials = 0;
    gTasks[taskId].tNumShakes_field_specials = gSpecialVar_0x8006;
    gTasks[taskId].tDelay_field_specials = gSpecialVar_0x8007;
    gTasks[taskId].tVerticalPan_field_specials = gSpecialVar_0x8004;
    SetCameraPanningCallback(NULL);
    PlaySE(SE_M_STRENGTH);
}

static void Task_ShakeCamera_field_specials(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    tDelayCounter_field_specials++;
    if (tDelayCounter_field_specials % tDelay_field_specials == 0)
    {
        tDelayCounter_field_specials = 0;
        tNumShakes_field_specials--;
        tHorizontalPan_field_specials = -tHorizontalPan_field_specials;
        tVerticalPan_field_specials = -tVerticalPan_field_specials;
        SetCameraPanning(tHorizontalPan_field_specials, tVerticalPan_field_specials);
        if (tNumShakes_field_specials == 0)
        {
            StopCameraShake_field_specials(taskId);
            InstallCameraPanAheadCallback();
        }
    }
}

static void StopCameraShake_field_specials(u8 taskId)
{
    DestroyTask(taskId);
    ScriptContext_Enable();
}

#undef tHorizontalPan_field_specials
#undef tDelayCounter_field_specials
#undef tNumShakes_field_specials
#undef tDelay_field_specials
#undef tVerticalPan_field_specials

