// Task data for Task_MoveElevator_field_specials
#define tTimer_field_specials       data[1]
#define tMoveCounter_field_specials data[2]
#define tVerticalPan_field_specials data[4]
#define tTotalMoves_field_specials  data[5]
#define tDescending_field_specials  data[6]

// The maximum considered difference between floors.
// Elevator trips with a larger difference are treated the same
// (i.e. traveling 9 floors and 200 floors would take the same amount of time).
#define MAX_ELEVATOR_TRIP_field_specials 9

// gSpecialVar_0x8005 here is expected to be the current floor number, and
// gSpecialVar_0x8006 is expected to be the destination floor number.
void MoveElevator(void)
{
static const u8  sElevatorTripLength_field_specials[MAX_ELEVATOR_TRIP_field_specials] = { 8, 16, 24, 32, 38, 46, 52, 56, 57 };

    s16 *data = gTasks[CreateTask(Task_MoveElevator_field_specials, 9)].data;
    u16 floorDelta;

    tTimer_field_specials = 0;
    tMoveCounter_field_specials = 0;
    tVerticalPan_field_specials = 1;

    if (gSpecialVar_0x8005 > gSpecialVar_0x8006)
    {
        floorDelta = gSpecialVar_0x8005 - gSpecialVar_0x8006;
        tDescending_field_specials = TRUE;
    }
    else
    {
        floorDelta = gSpecialVar_0x8006 - gSpecialVar_0x8005;
        tDescending_field_specials = FALSE;
    }

    if (floorDelta > MAX_ELEVATOR_TRIP_field_specials - 1)
        floorDelta = MAX_ELEVATOR_TRIP_field_specials - 1;

    tTotalMoves_field_specials = sElevatorTripLength_field_specials[floorDelta];

    SetCameraPanningCallback(NULL);
    MoveElevatorWindowLights_field_specials(floorDelta, tDescending_field_specials);
    PlaySE(SE_ELEVATOR);
}

static void Task_MoveElevator_field_specials(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    tTimer_field_specials++;
    if (tTimer_field_specials % 3 == 0)
    {
        tTimer_field_specials = 0;
        tMoveCounter_field_specials++;
        tVerticalPan_field_specials = -tVerticalPan_field_specials;
        SetCameraPanning(0, tVerticalPan_field_specials);

        if (tMoveCounter_field_specials == tTotalMoves_field_specials)
        {
            // Arrived at floor
            PlaySE(SE_DING_DONG);
            DestroyTask(taskId);
            ScriptContext_Enable();
            InstallCameraPanAheadCallback();
        }
    }
}

#undef tTimer_field_specials
