static void Task_ShowScrollableMultichoice_field_specials(u8 taskId)
{
    u32 width;
    u8 i, windowId;
    struct WindowTemplate template;
    struct Task *task = &gTasks[taskId];

    LockPlayerFieldControls();
    gScrollableMultichoice_ScrollOffset = 0;
    sScrollableMultichoice_ItemSpriteId_field_specials = MAX_SPRITES;
    FillFrontierExchangeCornerWindowAndItemIcon_field_specials(task->tScrollMultiId_field_specials, 0);
    ShowBattleFrontierTutorWindow_field_specials(task->tScrollMultiId_field_specials, 0);
    sScrollableMultichoice_ListMenuItem_field_specials = AllocZeroed(task->tNumItems_field_specials * 8);
    sFrontierExchangeCorner_NeverRead_field_specials = 0;
    InitScrollableMultichoice_field_specials();

    for (width = 0, i = 0; i < task->tNumItems_field_specials; i++)
    {
        const u8 *text = sScrollableMultichoiceOptions[gSpecialVar_0x8004][i];
        sScrollableMultichoice_ListMenuItem_field_specials[i].name = text;
        sScrollableMultichoice_ListMenuItem_field_specials[i].id = i;
        width = DisplayTextAndGetWidth(text, width);
    }

    task->tWidth_field_specials = ConvertPixelWidthToTileWidth(width);

    if (task->tLeft_field_specials + task->tWidth_field_specials > MAX_MULTICHOICE_WIDTH + 1)
    {
        int adjustedLeft = MAX_MULTICHOICE_WIDTH + 1 - task->tWidth_field_specials;
        if (adjustedLeft < 0)
            task->tLeft_field_specials = 0;
        else
            task->tLeft_field_specials = adjustedLeft;
    }

    template = CreateWindowTemplate(0, task->tLeft_field_specials, task->tTop_field_specials, task->tWidth_field_specials, task->tHeight_field_specials, 0xF, 0x64);
    windowId = AddWindow(&template);
    task->tWindowId_field_specials = windowId;
    SetStandardWindowBorderStyle(windowId, FALSE);

    gScrollableMultichoice_ListMenuTemplate.totalItems = task->tNumItems_field_specials;
    gScrollableMultichoice_ListMenuTemplate.maxShowed = task->tMaxItemsOnScreen_field_specials;
    gScrollableMultichoice_ListMenuTemplate.windowId = task->tWindowId_field_specials;

    ScrollableMultichoice_UpdateScrollArrows_field_specials(taskId);
    task->tListTaskId_field_specials = ListMenuInit(&gScrollableMultichoice_ListMenuTemplate, task->tScrollOffset_field_specials, task->tSelectedRow_field_specials);
    ScheduleBgCopyTilemapToVram(0);
    gTasks[taskId].func = ScrollableMultichoice_ProcessInput_field_specials;
}

static void InitScrollableMultichoice_field_specials(void)
{
    gScrollableMultichoice_ListMenuTemplate.items = sScrollableMultichoice_ListMenuItem_field_specials;
    gScrollableMultichoice_ListMenuTemplate.moveCursorFunc = ScrollableMultichoice_MoveCursor_field_specials;
    gScrollableMultichoice_ListMenuTemplate.itemPrintFunc = NULL;
    gScrollableMultichoice_ListMenuTemplate.totalItems = 1;
    gScrollableMultichoice_ListMenuTemplate.maxShowed = 1;
    gScrollableMultichoice_ListMenuTemplate.windowId = 0;
    gScrollableMultichoice_ListMenuTemplate.header_X = 0;
    gScrollableMultichoice_ListMenuTemplate.item_X = 8;
    gScrollableMultichoice_ListMenuTemplate.cursor_X = 0;
    gScrollableMultichoice_ListMenuTemplate.upText_Y = 1;
    gScrollableMultichoice_ListMenuTemplate.cursorPal = 2;
    gScrollableMultichoice_ListMenuTemplate.fillValue = 1;
    gScrollableMultichoice_ListMenuTemplate.cursorShadowPal = 3;
    gScrollableMultichoice_ListMenuTemplate.lettersSpacing = 0;
    gScrollableMultichoice_ListMenuTemplate.itemVerticalPadding = 0;
    gScrollableMultichoice_ListMenuTemplate.scrollMultiple = LIST_NO_MULTIPLE_SCROLL;
    gScrollableMultichoice_ListMenuTemplate.fontId = FONT_NORMAL;
    gScrollableMultichoice_ListMenuTemplate.cursorKind = CURSOR_BLACK_ARROW;
}

static void ScrollableMultichoice_MoveCursor_field_specials(s32 itemIndex, bool8 onInit, struct ListMenu *list)
{
    u8 taskId;
    PlaySE(SE_SELECT);
    taskId = FindTaskIdByFunc(ScrollableMultichoice_ProcessInput_field_specials);
    if (taskId != TASK_NONE)
    {
        u16 selection;
        struct Task *task = &gTasks[taskId];
        ListMenuGetScrollAndRow(task->tListTaskId_field_specials, &selection, NULL);
        gScrollableMultichoice_ScrollOffset = selection;
        ListMenuGetCurrentItemArrayId(task->tListTaskId_field_specials, &selection);
        HideFrontierExchangeCornerItemIcon_field_specials(task->tScrollMultiId_field_specials, sFrontierExchangeCorner_NeverRead_field_specials);
        FillFrontierExchangeCornerWindowAndItemIcon_field_specials(task->tScrollMultiId_field_specials, selection);
        ShowBattleFrontierTutorMoveDescription_field_specials(task->tScrollMultiId_field_specials, selection);
        sFrontierExchangeCorner_NeverRead_field_specials = selection;
    }
}

static void ScrollableMultichoice_ProcessInput_field_specials(u8 taskId)
{
    struct Task *task = &gTasks[taskId];
    s32 input = ListMenu_ProcessInput(task->tListTaskId_field_specials);

    switch (input)
    {
    case LIST_NOTHING_CHOSEN:
        break;
    case LIST_CANCEL:
        gSpecialVar_Result = MULTI_B_PRESSED;
        PlaySE(SE_SELECT);
        CloseScrollableMultichoice_field_specials(taskId);
        break;
    default:
        gSpecialVar_Result = input;
        PlaySE(SE_SELECT);
        if (!task->tKeepOpenAfterSelect_field_specials)
        {
            CloseScrollableMultichoice_field_specials(taskId);
        }
        else if (input == task->tNumItems_field_specials - 1)
        {
            // Selected option was the last one (Exit)
            CloseScrollableMultichoice_field_specials(taskId);
        }
        else
        {
            // Handle selection while keeping the menu open
            ScrollableMultichoice_RemoveScrollArrows_field_specials(taskId);
            task->func = Task_ScrollableMultichoice_WaitReturnToList_field_specials;
            ScriptContext_Enable();
        }
        break;
    }
}

static void CloseScrollableMultichoice_field_specials(u8 taskId)
{
    u16 selection;
    struct Task *task = &gTasks[taskId];
    ListMenuGetCurrentItemArrayId(task->tListTaskId_field_specials, &selection);
    HideFrontierExchangeCornerItemIcon_field_specials(task->tScrollMultiId_field_specials, selection);
    ScrollableMultichoice_RemoveScrollArrows_field_specials(taskId);
    DestroyListMenuTask(task->tListTaskId_field_specials, NULL, NULL);
    Free(sScrollableMultichoice_ListMenuItem_field_specials);
    ClearStdWindowAndFrameToTransparent(task->tWindowId_field_specials, TRUE);
    FillWindowPixelBuffer(task->tWindowId_field_specials, PIXEL_FILL(0));
    CopyWindowToVram(task->tWindowId_field_specials, COPYWIN_GFX);
    RemoveWindow(task->tWindowId_field_specials);
    DestroyTask(taskId);
    ScriptContext_Enable();
}

// Never run, tKeepOpenAfterSelect_field_specials is FALSE for all scrollable multichoices.
static void Task_ScrollableMultichoice_WaitReturnToList_field_specials(u8 taskId)
{
    switch (gTasks[taskId].tKeepOpenAfterSelect_field_specials)
    {
    case 1:
    default:
        break;
    case 2:
        gTasks[taskId].tKeepOpenAfterSelect_field_specials = 1;
        gTasks[taskId].func = Task_ScrollableMultichoice_ReturnToList_field_specials;
        break;
    }
}

// Never called
void ScrollableMultichoice_TryReturnToList(void)
{
    u8 taskId = FindTaskIdByFunc(Task_ScrollableMultichoice_WaitReturnToList_field_specials);
    if (taskId == TASK_NONE)
        ScriptContext_Enable();
    else
        gTasks[taskId].tKeepOpenAfterSelect_field_specials++; // Return to list
}

static void Task_ScrollableMultichoice_ReturnToList_field_specials(u8 taskId)
{
    LockPlayerFieldControls();
    ScrollableMultichoice_UpdateScrollArrows_field_specials(taskId);
    gTasks[taskId].func = ScrollableMultichoice_ProcessInput_field_specials;
}

static void ScrollableMultichoice_UpdateScrollArrows_field_specials(u8 taskId)
{
static const struct ScrollArrowsTemplate  sScrollableMultichoice_ScrollArrowsTemplate_field_specials = {
        .firstArrowType = SCROLL_ARROW_UP,
        .firstX = 0,
        .firstY = 0,
        .secondArrowType = SCROLL_ARROW_DOWN,
        .secondX = 0,
        .secondY = 0,
        .fullyUpThreshold = 0,
        .fullyDownThreshold = 0,
        .tileTag = GFXTAG_MULTICHOICE_SCROLL_ARROWS_field_specials,
        .palTag = PALTAG_MULTICHOICE_SCROLL_ARROWS_field_specials,
        .palNum = 0
    };

    struct Task *task = &gTasks[taskId];
    struct ScrollArrowsTemplate template = sScrollableMultichoice_ScrollArrowsTemplate_field_specials;
    if (task->tMaxItemsOnScreen_field_specials != task->tNumItems_field_specials)
    {
        u32 y0 = (8 * (task->tTop_field_specials - 1));

        template.firstX = (task->tWidth_field_specials / 2) * 8 + 12 + (task->tLeft_field_specials - 1) * 8;
        template.firstY = 8 + y0;
        template.secondX = (task->tWidth_field_specials / 2) * 8 + 12 + (task->tLeft_field_specials - 1) * 8;
        template.secondY = task->tHeight_field_specials * 8 + 10 + y0;
        template.fullyUpThreshold = 0;
        template.fullyDownThreshold = task->tNumItems_field_specials - task->tMaxItemsOnScreen_field_specials;
        task->tScrollArrowId_field_specials = AddScrollIndicatorArrowPair(&template, &gScrollableMultichoice_ScrollOffset);
    }
}

static void ScrollableMultichoice_RemoveScrollArrows_field_specials(u8 taskId)
{
    struct Task *task = &gTasks[taskId];
    if (task->tMaxItemsOnScreen_field_specials != task->tNumItems_field_specials)
        RemoveScrollIndicatorArrowPair(task->tScrollArrowId_field_specials);
}

