                sScrollableMultichoice_ItemSpriteId_field_specials = AddDecorationIconObject(sFrontierExchangeCorner_Decor2[selection], 33, 88, 0, TAG_ITEM_ICON_field_specials, TAG_ITEM_ICON_field_specials);
