// Never called
void ScrollableMultichoice_RedrawPersistentMenu(void)
{
    u16 scrollOffset, selectedRow;
    u8 i;
    u8 taskId = FindTaskIdByFunc(Task_ScrollableMultichoice_WaitReturnToList_field_specials);
    if (taskId != TASK_NONE)
    {
        struct Task *task = &gTasks[taskId];
        ListMenuGetScrollAndRow(task->tListTaskId_field_specials, &scrollOffset, &selectedRow);
        SetStandardWindowBorderStyle(task->tWindowId_field_specials, FALSE);

        for (i = 0; i < MAX_SCROLL_MULTI_ON_SCREEN; i++)
            AddTextPrinterParameterized5(task->tWindowId_field_specials, FONT_NORMAL, sScrollableMultichoiceOptions[gSpecialVar_0x8004][scrollOffset + i], 10, i * 16, TEXT_SKIP_DRAW, NULL, 0, 0);

        AddTextPrinterParameterized(task->tWindowId_field_specials, FONT_NORMAL, gText_SelectorArrow, 0, selectedRow * 16, TEXT_SKIP_DRAW, NULL);
        PutWindowTilemap(task->tWindowId_field_specials);
        CopyWindowToVram(task->tWindowId_field_specials, COPYWIN_FULL);
    }
}

// Never called
// Close a scrollable multichoice that stays open after selection
void ScrollableMultichoice_ClosePersistentMenu(void)
{
    u8 taskId = FindTaskIdByFunc(Task_ScrollableMultichoice_WaitReturnToList_field_specials);
    if (taskId != TASK_NONE)
    {
        struct Task *task = &gTasks[taskId];
        DestroyListMenuTask(task->tListTaskId_field_specials, NULL, NULL);
        Free(sScrollableMultichoice_ListMenuItem_field_specials);
        ClearStdWindowAndFrameToTransparent(task->tWindowId_field_specials, TRUE);
        FillWindowPixelBuffer(task->tWindowId_field_specials, PIXEL_FILL(0));
        ClearWindowTilemap(task->tWindowId_field_specials);
        CopyWindowToVram(task->tWindowId_field_specials, COPYWIN_GFX);
        RemoveWindow(task->tWindowId_field_specials);
        DestroyTask(taskId);
    }
}

