void CloseBattlePikeCurtain(void)
{
    u8 taskId = CreateTask(Task_CloseBattlePikeCurtain_field_specials, 8);
    gTasks[taskId].tFrameTimer_field_specials[0] = 4;
    gTasks[taskId].tFrameTimer_field_specials[1] = 4;
    gTasks[taskId].tFrameTimer_field_specials[2] = 4;
    gTasks[taskId].tCurrentFrame_field_specials = 0;
}

static void Task_CloseBattlePikeCurtain_field_specials(u8 taskId)
{
    u8 x, y;
    s16 *data = gTasks[taskId].data;

    tFrameTimer_field_specials[tCurrentFrame_field_specials]--;
    if (tFrameTimer_field_specials[tCurrentFrame_field_specials] == 0)
    {
        for (y = 0; y < CURTAIN_HEIGHT_field_specials; y++)
        {
            for (x = 0; x < CURTAIN_WIDTH_field_specials; x++)
            {
                MapGridSetMetatileIdAt(gSaveBlock1Ptr->pos.x + x + MAP_OFFSET - 1,
                                       gSaveBlock1Ptr->pos.y + y + MAP_OFFSET - 3,
                                       (x + METATILE_BattlePike_CurtainFrames_Start) + (y * METATILE_ROW_WIDTH) + (tCurrentFrame_field_specials * CURTAIN_HEIGHT_field_specials * METATILE_ROW_WIDTH));
            }
        }
        DrawWholeMapView();
        tCurrentFrame_field_specials++;
        if (tCurrentFrame_field_specials == 3)
        {
            DestroyTask(taskId);
            ScriptContext_Enable();
        }
    }
}

