// Most of the boxes in the moving truck are map tiles, with the
// exception of three boxes that are map events that jostle around
// while the truck is driving. In addition, their sprite's placement
// is slightly offset to make them look less perfectly stacked.
// Box 1 (LOCALID_TRUCK_BOX_TOP)
#define BOX1_X_OFFSET_field_special_scene  3
#define BOX1_Y_OFFSET_field_special_scene  3
// Box 2 (LOCALID_TRUCK_BOX_BOTTOM_L)
#define BOX2_X_OFFSET_field_special_scene  0
#define BOX2_Y_OFFSET_field_special_scene -3
// Box 3 (LOCALID_TRUCK_BOX_BOTTOM_R)
#define BOX3_X_OFFSET_field_special_scene -3
#define BOX3_Y_OFFSET_field_special_scene  0

// porthole states
enum
{
    INIT_PORTHOLE_field_special_scene,
    IDLE_CHECK_field_special_scene,
    EXECUTE_MOVEMENT_field_special_scene,
    EXIT_PORTHOLE_field_special_scene,
};

static const s8  sTruckCamera_HorizontalTable_field_special_scene[] = {0, 0, 0, 0, 0, 0, 0, 0, 1, 2, 2, 2, 2, 2, 2, -1, -1, -1, 0};

static const u8  sSSTidalSailEastMovementScript_field_special_scene[] =
{
    MOVEMENT_ACTION_WALK_FAST_RIGHT,
    MOVEMENT_ACTION_STEP_END
};

static const u8  sSSTidalSailWestMovementScript_field_special_scene[] =
{
    MOVEMENT_ACTION_WALK_FAST_LEFT,
    MOVEMENT_ACTION_STEP_END
};

static void Task_Truck3_field_special_scene(u8);

static s16 GetTruckCameraBobbingY_field_special_scene(int time)
{
    if (!(time % 120))
        return -1;
    else if ((time % 10) <= 4)
        return 1;

    return 0;
}

// Determines the frequency that the truck boxes bounce at.
// The return value of this function is multiplied and added
// to the boxes resting y offset, the result of which is that
// when it returns 0 they remain vertically still and when it
// returns -1 they jump upward.
// Box 1 has 30 added to the time so it jumps earlier, and
// box 2 has the return value multiplied by less, so it doesn't
// jump as high.
static s16 GetTruckBoxYMovement_field_special_scene(int time)
{
    if (!((time + 120) % 180))
        return -1;

    return 0;
}

#define tTimer_field_special_scene data[0]

static void Task_Truck1_field_special_scene(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    s16 cameraXpan = 0, cameraYpan = 0;
    s16 yBox1, yBox2, yBox3;

    yBox1 = GetTruckBoxYMovement_field_special_scene(tTimer_field_special_scene + 30) * 4;
    SetObjectEventSpritePosByLocalIdAndMap(LOCALID_TRUCK_BOX_TOP,      gSaveBlock1Ptr->location.mapNum, gSaveBlock1Ptr->location.mapGroup, BOX1_X_OFFSET_field_special_scene - cameraXpan, BOX1_Y_OFFSET_field_special_scene + yBox1);
    yBox2 = GetTruckBoxYMovement_field_special_scene(tTimer_field_special_scene) * 2;
    SetObjectEventSpritePosByLocalIdAndMap(LOCALID_TRUCK_BOX_BOTTOM_L, gSaveBlock1Ptr->location.mapNum, gSaveBlock1Ptr->location.mapGroup, BOX2_X_OFFSET_field_special_scene - cameraXpan, BOX2_Y_OFFSET_field_special_scene + yBox2);
    yBox3 = GetTruckBoxYMovement_field_special_scene(tTimer_field_special_scene) * 4;
    SetObjectEventSpritePosByLocalIdAndMap(LOCALID_TRUCK_BOX_BOTTOM_R, gSaveBlock1Ptr->location.mapNum, gSaveBlock1Ptr->location.mapGroup, BOX3_X_OFFSET_field_special_scene - cameraXpan, BOX3_Y_OFFSET_field_special_scene + yBox3);

    // Arbitrary timer limit that won't be reached
    if (++tTimer_field_special_scene == 30000)
        tTimer_field_special_scene = 0;

    cameraYpan = GetTruckCameraBobbingY_field_special_scene(tTimer_field_special_scene);
    SetCameraPanning(cameraXpan, cameraYpan);
}

#undef tTimer_field_special_scene

#define tTimerHorizontal_field_special_scene data[0]
#define tMoveStep_field_special_scene        data[1]
#define tTimerVertical_field_special_scene   data[2]

static void Task_Truck2_field_special_scene(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    s16 cameraYpan, cameraXpan;
    s16 yBox1, yBox2, yBox3;

    tTimerHorizontal_field_special_scene++;
    tTimerVertical_field_special_scene++;

    if (tTimerHorizontal_field_special_scene > 5)
    {
        tTimerHorizontal_field_special_scene = 0;
        tMoveStep_field_special_scene++;
    }
    if ((u16)tMoveStep_field_special_scene == ARRAY_COUNT(sTruckCamera_HorizontalTable_field_special_scene))
    {
        // Never reached, the task function is changed below before finishing the table
        DestroyTask(taskId);
    }
    else
    {
        if (sTruckCamera_HorizontalTable_field_special_scene[tMoveStep_field_special_scene] == 2)
            gTasks[taskId].func = Task_Truck3_field_special_scene;

        cameraXpan = sTruckCamera_HorizontalTable_field_special_scene[tMoveStep_field_special_scene];
        cameraYpan = GetTruckCameraBobbingY_field_special_scene(tTimerVertical_field_special_scene);
        SetCameraPanning(cameraXpan, cameraYpan);
        yBox1 = GetTruckBoxYMovement_field_special_scene(tTimerVertical_field_special_scene + 30) * 4;
        SetObjectEventSpritePosByLocalIdAndMap(LOCALID_TRUCK_BOX_TOP,      gSaveBlock1Ptr->location.mapNum, gSaveBlock1Ptr->location.mapGroup, BOX1_X_OFFSET_field_special_scene - cameraXpan, BOX1_Y_OFFSET_field_special_scene + yBox1);
        yBox2 = GetTruckBoxYMovement_field_special_scene(tTimerVertical_field_special_scene) * 2;
        SetObjectEventSpritePosByLocalIdAndMap(LOCALID_TRUCK_BOX_BOTTOM_L, gSaveBlock1Ptr->location.mapNum, gSaveBlock1Ptr->location.mapGroup, BOX2_X_OFFSET_field_special_scene - cameraXpan, BOX2_Y_OFFSET_field_special_scene + yBox2);
        yBox3 = GetTruckBoxYMovement_field_special_scene(tTimerVertical_field_special_scene) * 4;
        SetObjectEventSpritePosByLocalIdAndMap(LOCALID_TRUCK_BOX_BOTTOM_R, gSaveBlock1Ptr->location.mapNum, gSaveBlock1Ptr->location.mapGroup, BOX3_X_OFFSET_field_special_scene - cameraXpan, BOX3_Y_OFFSET_field_special_scene + yBox3);
    }
}

static void Task_Truck3_field_special_scene(u8 taskId)
{
   s16 *data = gTasks[taskId].data;
   s16 cameraXpan, cameraYpan;

   tTimerHorizontal_field_special_scene++;

   if (tTimerHorizontal_field_special_scene > 5)
   {
       tTimerHorizontal_field_special_scene = 0;
       tMoveStep_field_special_scene++;
   }

   if ((u16)tMoveStep_field_special_scene == ARRAY_COUNT(sTruckCamera_HorizontalTable_field_special_scene))
   {
       DestroyTask(taskId);
   }
   else
   {
       cameraXpan = sTruckCamera_HorizontalTable_field_special_scene[tMoveStep_field_special_scene];
       cameraYpan = 0;
       SetCameraPanning(cameraXpan, cameraYpan);
       SetObjectEventSpritePosByLocalIdAndMap(LOCALID_TRUCK_BOX_TOP,      gSaveBlock1Ptr->location.mapNum, gSaveBlock1Ptr->location.mapGroup, BOX1_X_OFFSET_field_special_scene - cameraXpan, BOX1_Y_OFFSET_field_special_scene + cameraYpan);
       SetObjectEventSpritePosByLocalIdAndMap(LOCALID_TRUCK_BOX_BOTTOM_L, gSaveBlock1Ptr->location.mapNum, gSaveBlock1Ptr->location.mapGroup, BOX2_X_OFFSET_field_special_scene - cameraXpan, BOX2_Y_OFFSET_field_special_scene + cameraYpan);
       SetObjectEventSpritePosByLocalIdAndMap(LOCALID_TRUCK_BOX_BOTTOM_R, gSaveBlock1Ptr->location.mapNum, gSaveBlock1Ptr->location.mapGroup, BOX3_X_OFFSET_field_special_scene - cameraXpan, BOX3_Y_OFFSET_field_special_scene + cameraYpan);
   }
}

#undef tTimerHorizontal_field_special_scene
#undef tMoveStep_field_special_scene
#undef tTimerVertical_field_special_scene

#define tState_field_special_scene   data[0]
#define tTimer_field_special_scene   data[1]
#define tTaskId1_field_special_scene data[2]
#define tTaskId2_field_special_scene data[3]

static void Task_HandleTruckSequence_field_special_scene(u8 taskId)
{
   s16 *data = gTasks[taskId].data;

    switch (tState_field_special_scene)
    {
    case 0:
        tTimer_field_special_scene++;
        if (tTimer_field_special_scene == 90)
        {
            SetCameraPanningCallback(NULL);
            tTimer_field_special_scene = 0;
            tTaskId1_field_special_scene = CreateTask(Task_Truck1_field_special_scene, 0xA);
            tState_field_special_scene = 1;
            PlaySE(SE_TRUCK_MOVE);
        }
        break;
    case 1:
        tTimer_field_special_scene++;
        if (tTimer_field_special_scene == 150)
        {
            FadeInFromBlack();
            tTimer_field_special_scene = 0;
            tState_field_special_scene = 2;
        }
        break;
    case 2:
        tTimer_field_special_scene++;
        if (!gPaletteFade.active && tTimer_field_special_scene > 300)
        {
            tTimer_field_special_scene = 0;
            DestroyTask(tTaskId1_field_special_scene);
            tTaskId2_field_special_scene = CreateTask(Task_Truck2_field_special_scene, 0xA);
            tState_field_special_scene = 3;
            PlaySE(SE_TRUCK_STOP);
        }
        break;
    case 3:
        if (!gTasks[tTaskId2_field_special_scene].isActive)
        {
            // Task_Truck2_field_special_scene / Task_Truck3_field_special_scene has finished
            InstallCameraPanAheadCallback();
            tTimer_field_special_scene = 0;
            tState_field_special_scene = 4;
        }
        break;
    case 4:
        tTimer_field_special_scene++;
        if (tTimer_field_special_scene == 90)
        {
            PlaySE(SE_TRUCK_UNLOAD);
            tTimer_field_special_scene = 0;
            tState_field_special_scene = 5;
        }
        break;
    case 5:
        tTimer_field_special_scene++;
        if (tTimer_field_special_scene == 120)
        {
            MapGridSetMetatileIdAt(4 + MAP_OFFSET, 1 + MAP_OFFSET, METATILE_InsideOfTruck_ExitLight_Top);
            MapGridSetMetatileIdAt(4 + MAP_OFFSET, 2 + MAP_OFFSET, METATILE_InsideOfTruck_ExitLight_Mid);
            MapGridSetMetatileIdAt(4 + MAP_OFFSET, 3 + MAP_OFFSET, METATILE_InsideOfTruck_ExitLight_Bottom);
            DrawWholeMapView();
            PlaySE(SE_TRUCK_DOOR);
            DestroyTask(taskId);
            UnlockPlayerFieldControls();
        }
        break;
    }
}

void ExecuteTruckSequence(void)
{
    MapGridSetMetatileIdAt(4 + MAP_OFFSET, 1 + MAP_OFFSET, METATILE_InsideOfTruck_DoorClosedFloor_Top);
    MapGridSetMetatileIdAt(4 + MAP_OFFSET, 2 + MAP_OFFSET, METATILE_InsideOfTruck_DoorClosedFloor_Mid);
    MapGridSetMetatileIdAt(4 + MAP_OFFSET, 3 + MAP_OFFSET, METATILE_InsideOfTruck_DoorClosedFloor_Bottom);
    DrawWholeMapView();
    LockPlayerFieldControls();
    CpuFastFill(0, gPlttBufferFaded, PLTT_SIZE);
    CreateTask(Task_HandleTruckSequence_field_special_scene, 0xA);
}

void EndTruckSequence(u8 taskId)
{
    if (!FuncIsActiveTask(Task_HandleTruckSequence_field_special_scene))
    {
        SetObjectEventSpritePosByLocalIdAndMap(LOCALID_TRUCK_BOX_TOP,      gSaveBlock1Ptr->location.mapNum, gSaveBlock1Ptr->location.mapGroup, BOX1_X_OFFSET_field_special_scene, BOX1_Y_OFFSET_field_special_scene);
        SetObjectEventSpritePosByLocalIdAndMap(LOCALID_TRUCK_BOX_BOTTOM_L, gSaveBlock1Ptr->location.mapNum, gSaveBlock1Ptr->location.mapGroup, BOX2_X_OFFSET_field_special_scene, BOX2_Y_OFFSET_field_special_scene);
        SetObjectEventSpritePosByLocalIdAndMap(LOCALID_TRUCK_BOX_BOTTOM_R, gSaveBlock1Ptr->location.mapNum, gSaveBlock1Ptr->location.mapGroup, BOX3_X_OFFSET_field_special_scene, BOX3_Y_OFFSET_field_special_scene);
    }
}

bool8 TrySetPortholeWarpDestination(void)
{
    s8 mapGroup, mapNum;
    s16 x, y;

    if (GetSSTidalLocation(&mapGroup, &mapNum, &x, &y) != SS_TIDAL_LOCATION_CURRENTS)
    {
        return FALSE;
    }
    else
    {
        SetWarpDestination(mapGroup, mapNum, WARP_ID_NONE, x, y);
        return TRUE;
    }
}

void Task_HandlePorthole(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    u16 *cruiseState = GetVarPointer(VAR_SS_TIDAL_STATE);
    struct WarpData *location = &gSaveBlock1Ptr->location;

    switch (data[0])
    {
    case INIT_PORTHOLE_field_special_scene: // finish fading before making porthole finish.
        if (!gPaletteFade.active)
        {
            data[1] = 0;
            data[0] = EXECUTE_MOVEMENT_field_special_scene; // execute movement before checking if should be exited. strange?
        }
        break;
    case IDLE_CHECK_field_special_scene:
        if (JOY_NEW(A_BUTTON))
            data[1] = 1;
        if (!ScriptMovement_IsObjectMovementFinished(OBJ_EVENT_ID_PLAYER, location->mapNum, location->mapGroup))
            return;
        if (CountSSTidalStep(1) == TRUE)
        {
            if (*cruiseState == SS_TIDAL_DEPART_SLATEPORT)
                *cruiseState = SS_TIDAL_EXIT_CURRENTS_RIGHT;
            else
                *cruiseState = SS_TIDAL_EXIT_CURRENTS_LEFT;
            data[0] = EXIT_PORTHOLE_field_special_scene;
            return;
        }
        data[0] = EXECUTE_MOVEMENT_field_special_scene;
        //fallthrough
    case EXECUTE_MOVEMENT_field_special_scene:
        if (data[1])
        {
            data[0] = EXIT_PORTHOLE_field_special_scene;
            return;
        }

        if (*cruiseState == SS_TIDAL_DEPART_SLATEPORT)
        {
            ScriptMovement_StartObjectMovementScript(OBJ_EVENT_ID_PLAYER, location->mapNum, location->mapGroup, sSSTidalSailEastMovementScript_field_special_scene);
            data[0] = IDLE_CHECK_field_special_scene;
        }
        else
        {
            ScriptMovement_StartObjectMovementScript(OBJ_EVENT_ID_PLAYER, location->mapNum, location->mapGroup, sSSTidalSailWestMovementScript_field_special_scene);
            data[0] = IDLE_CHECK_field_special_scene;
        }
        break;
    case EXIT_PORTHOLE_field_special_scene:
        FlagClear(FLAG_DONT_TRANSITION_MUSIC);
        FlagClear(FLAG_HIDE_MAP_NAME_POPUP);
        SetWarpDestinationToDynamicWarp(0);
        DoDiveWarp();
        DestroyTask(taskId);
        break;
    }
}

static void ShowSSTidalWhileSailing_field_special_scene(void)
{
    u8 spriteId = CreateObjectGraphicsSprite(OBJ_EVENT_GFX_SS_TIDAL, SpriteCallbackDummy, 112, 80, 0);

    gSprites[spriteId].coordOffsetEnabled = FALSE;

    if (VarGet(VAR_SS_TIDAL_STATE) == SS_TIDAL_DEPART_SLATEPORT)
        StartSpriteAnim(&gSprites[spriteId], GetFaceDirectionAnimNum(DIR_EAST));
    else
        StartSpriteAnim(&gSprites[spriteId], GetFaceDirectionAnimNum(DIR_WEST));
}

void FieldCB_ShowPortholeView(void)
{
    ShowSSTidalWhileSailing_field_special_scene();
    gObjectEvents[gPlayerAvatar.objectEventId].invisible = TRUE;
    FadeInFromBlack();
    CreateTask(Task_HandlePorthole, 80);
    LockPlayerFieldControls();
}

void LookThroughPorthole(void)
{
    FlagSet(FLAG_SYS_CRUISE_MODE);
    FlagSet(FLAG_DONT_TRANSITION_MUSIC);
    FlagSet(FLAG_HIDE_MAP_NAME_POPUP);
    SetDynamicWarp(0, gSaveBlock1Ptr->location.mapGroup, gSaveBlock1Ptr->location.mapNum, WARP_ID_NONE);
    TrySetPortholeWarpDestination();
    DoPortholeWarp();
}
