void Drought_InitVars(void)
{
    gWeatherPtr->initStep = 0;
    gWeatherPtr->weatherGfxLoaded = FALSE;
    gWeatherPtr->targetColorMapIndex = 0;
    gWeatherPtr->colorMapStepDelay = 0;
}

void Drought_InitAll(void)
{
    Drought_InitVars();
    while (gWeatherPtr->weatherGfxLoaded == FALSE)
        Drought_Main();
}

void Drought_Main(void)
{
    switch (gWeatherPtr->initStep)
    {
    case 0:
        if (gWeatherPtr->palProcessingState != WEATHER_PAL_STATE_CHANGING_WEATHER)
            gWeatherPtr->initStep++;
        break;
    case 1:
        ResetDroughtWeatherPaletteLoading();
        gWeatherPtr->initStep++;
        break;
    case 2:
        if (LoadDroughtWeatherPalettes() == FALSE)
            gWeatherPtr->initStep++;
        break;
    case 3:
        DroughtStateInit();
        gWeatherPtr->initStep++;
        break;
    case 4:
        DroughtStateRun();
        if (gWeatherPtr->droughtBrightnessStage == 6)
        {
            gWeatherPtr->weatherGfxLoaded = TRUE;
            gWeatherPtr->initStep++;
        }
        break;
    default:
        DroughtStateRun();
        break;
    }
}

bool8 Drought_Finish(void)
{
    return FALSE;
}

void StartDroughtWeatherBlend(void)
{
    CreateTask(UpdateDroughtBlend_field_weather_effect, 80);
}

#define tState_field_weather_effect      data[0]
#define tBlendY_field_weather_effect     data[1]
#define tBlendDelay_field_weather_effect data[2]
#define tWinRange_field_weather_effect   data[3]

static void UpdateDroughtBlend_field_weather_effect(u8 taskId)
{
    struct Task *task = &gTasks[taskId];

    switch (task->tState_field_weather_effect)
    {
    case 0:
        task->tBlendY_field_weather_effect = 0;
        task->tBlendDelay_field_weather_effect = 0;
        task->tWinRange_field_weather_effect = REG_WININ;
        SetGpuReg(REG_OFFSET_WININ, WININ_WIN0_ALL | WININ_WIN1_ALL);
        SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_TGT1_BG1 | BLDCNT_TGT1_BG2 | BLDCNT_TGT1_BG3 | BLDCNT_TGT1_OBJ | BLDCNT_EFFECT_LIGHTEN);
        SetGpuReg(REG_OFFSET_BLDY, 0);
        task->tState_field_weather_effect++;
        // fall through
    case 1:
        task->tBlendY_field_weather_effect += 3;
        if (task->tBlendY_field_weather_effect > 16)
            task->tBlendY_field_weather_effect = 16;
        SetGpuReg(REG_OFFSET_BLDY, task->tBlendY_field_weather_effect);
        if (task->tBlendY_field_weather_effect >= 16)
            task->tState_field_weather_effect++;
        break;
    case 2:
        task->tBlendDelay_field_weather_effect++;
        if (task->tBlendDelay_field_weather_effect > 9)
        {
            task->tBlendDelay_field_weather_effect = 0;
            task->tBlendY_field_weather_effect--;
            if (task->tBlendY_field_weather_effect <= 0)
            {
                task->tBlendY_field_weather_effect = 0;
                task->tState_field_weather_effect++;
            }
            SetGpuReg(REG_OFFSET_BLDY, task->tBlendY_field_weather_effect);
        }
        break;
    case 3:
        SetGpuReg(REG_OFFSET_BLDCNT, 0);
        SetGpuReg(REG_OFFSET_BLDY, 0);
        SetGpuReg(REG_OFFSET_WININ, task->tWinRange_field_weather_effect);
        task->tState_field_weather_effect++;
        break;
    case 4:
        ScriptContext_Enable();
        DestroyTask(taskId);
        break;
    }
}

#undef tState_field_weather_effect
#undef tBlendY_field_weather_effect
#undef tBlendDelay_field_weather_effect
#undef tWinRange_field_weather_effect

