static void CreateAshSprites_field_weather_effect(void)
{
    u8 i;
    u8 spriteId;
    struct Sprite *sprite;

    if (!gWeatherPtr->ashSpritesCreated)
    {
        for (i = 0; i < NUM_ASH_SPRITES; i++)
        {
            spriteId = CreateSpriteAtEnd(&sAshSpriteTemplate_field_weather_effect, 0, 0, 0x4E);
            if (spriteId != MAX_SPRITES)
            {
                sprite = &gSprites[spriteId];
                sprite->tCounterY_field_weather_effect = 0;
                sprite->tSpriteColumn_field_weather_effect = (u8)(i % 5);
                sprite->tSpriteRow_field_weather_effect = (u8)(i / 5);
                sprite->tOffsetY_field_weather_effect = sprite->tSpriteRow_field_weather_effect * 64 + 32;
                gWeatherPtr->sprites.s2.ashSprites[i] = sprite;
            }
            else
            {
                gWeatherPtr->sprites.s2.ashSprites[i] = NULL;
            }
        }

        gWeatherPtr->ashSpritesCreated = TRUE;
    }
}

static void DestroyAshSprites_field_weather_effect(void)
{
    u16 i;

    if (gWeatherPtr->ashSpritesCreated)
    {
        for (i = 0; i < NUM_ASH_SPRITES; i++)
        {
            if (gWeatherPtr->sprites.s2.ashSprites[i] != NULL)
                DestroySprite(gWeatherPtr->sprites.s2.ashSprites[i]);
        }

        FreeSpriteTilesByTag(GFXTAG_ASH);
        gWeatherPtr->ashSpritesCreated = FALSE;
    }
}

static void UpdateAshSprite_field_weather_effect(struct Sprite *sprite)
{
    if (++sprite->tCounterY_field_weather_effect > 5)
    {
        sprite->tCounterY_field_weather_effect = 0;
        sprite->tOffsetY_field_weather_effect++;
    }

    sprite->y = gSpriteCoordOffsetY + sprite->tOffsetY_field_weather_effect;
    sprite->x = gWeatherPtr->ashBaseSpritesX + 32 + sprite->tSpriteColumn_field_weather_effect * 64;
    if (sprite->x >= DISPLAY_WIDTH + 32)
    {
        sprite->x = gWeatherPtr->ashBaseSpritesX + (DISPLAY_WIDTH * 2) - (4 - sprite->tSpriteColumn_field_weather_effect) * 64;
        sprite->x &= 0x1FF;
    }
}

