#define tSpriteColumn_field_weather_effect  data[0]
#define tSpriteRow_field_weather_effect     data[1]

// Swirly sandstorm sprites
#define tRadius_field_weather_effect        data[0]
#define tWaveIndex_field_weather_effect     data[1]
#define tRadiusCounter_field_weather_effect data[2]
