static void CreateBubbleSprite_field_weather_effect(u16 coordsIndex)
{
    s16 x = sBubbleStartCoords_field_weather_effect[coordsIndex][0];
    s16 y = sBubbleStartCoords_field_weather_effect[coordsIndex][1] - gSpriteCoordOffsetY;
    u8 spriteId = CreateSpriteAtEnd(&sBubbleSpriteTemplate_field_weather_effect, x, y, 0);
    if (spriteId != MAX_SPRITES)
    {
        gSprites[spriteId].oam.priority = 1;
        gSprites[spriteId].coordOffsetEnabled = TRUE;
        gSprites[spriteId].tScrollXCounter_field_weather_effect = 0;
        gSprites[spriteId].tScrollXDir_field_weather_effect = 0;
        gSprites[spriteId].tCounter_field_weather_effect = 0;
        gWeatherPtr->bubblesSpriteCount++;
    }
}

static void DestroyBubbleSprites_field_weather_effect(void)
{
    u16 i;

    if (gWeatherPtr->bubblesSpriteCount)
    {
        for (i = 0; i < MAX_SPRITES; i++)
        {
            if (gSprites[i].template == &sBubbleSpriteTemplate_field_weather_effect)
                DestroySprite(&gSprites[i]);
        }

        FreeSpriteTilesByTag(GFXTAG_BUBBLE);
        gWeatherPtr->bubblesSpriteCount = 0;
    }
}

static void UpdateBubbleSprite_field_weather_effect(struct Sprite *sprite)
{
    ++sprite->tScrollXCounter_field_weather_effect;
    if (++sprite->tScrollXCounter_field_weather_effect > 8) // double increment
    {
        sprite->tScrollXCounter_field_weather_effect = 0;
        if (sprite->tScrollXDir_field_weather_effect == 0)
        {
            if (++sprite->x2 > 4)
                sprite->tScrollXDir_field_weather_effect = 1;
        }
        else
        {
            if (--sprite->x2 <= 0)
                sprite->tScrollXDir_field_weather_effect = 0;
        }
    }

    sprite->y -= 3;
    if (++sprite->tCounter_field_weather_effect >= 120)
        DestroySprite(sprite);
}

#undef tScrollXCounter_field_weather_effect
#undef tScrollXDir_field_weather_effect
#undef tCounter_field_weather_effect

