// For accessing Pokémon storage PC or the Hall of Fame PC
void ComputerScreenOpenEffect(u16 increment, u16 unused, u8 priority)
{
    CreateComputerScreenEffectTask_fldeff_misc(Task_ComputerScreenOpenEffect_fldeff_misc, increment, unused, priority);
}

void ComputerScreenCloseEffect(u16 increment, u16 unused, u8 priority)
{
    CreateComputerScreenEffectTask_fldeff_misc(Task_ComputerScreenCloseEffect_fldeff_misc, increment, unused, priority);
}

bool8 IsComputerScreenOpenEffectActive(void)
{
    return FuncIsActiveTask(Task_ComputerScreenOpenEffect_fldeff_misc);
}

bool8 IsComputerScreenCloseEffectActive(void)
{
    return FuncIsActiveTask(Task_ComputerScreenCloseEffect_fldeff_misc);
}

#define tState_fldeff_misc         data[0]
#define tHorzIncrement_fldeff_misc data[1]
#define tVertIncrement_fldeff_misc data[2]
#define tWinLeft_fldeff_misc       data[3]
#define tWinRight_fldeff_misc      data[4]
#define tWinTop_fldeff_misc        data[5]
#define tWinBottom_fldeff_misc     data[6]
#define tBlendCnt_fldeff_misc      data[7]
#define tBlendY_fldeff_misc        data[8]

static void CreateComputerScreenEffectTask_fldeff_misc(void (*taskfunc) (u8), u16 increment, u16 unused, u8 priority)
{
    u8 taskId = CreateTask(taskfunc, priority);

    gTasks[taskId].tState_fldeff_misc = 0;
    gTasks[taskId].tHorzIncrement_fldeff_misc = increment == 0 ? 16 : increment;
    gTasks[taskId].tVertIncrement_fldeff_misc = increment == 0 ? 20 : increment;
    gTasks[taskId].func(taskId);
}

static void Task_ComputerScreenOpenEffect_fldeff_misc(u8 taskId)
{
    struct Task *task = &gTasks[taskId];

    switch (task->tState_fldeff_misc)
    {
    case 0:
        task->tWinLeft_fldeff_misc = DISPLAY_WIDTH / 2;
        task->tWinRight_fldeff_misc = DISPLAY_WIDTH / 2;
        task->tWinTop_fldeff_misc = DISPLAY_HEIGHT / 2;
        task->tWinBottom_fldeff_misc = DISPLAY_HEIGHT / 2 + 1;

        SetGpuRegBits(REG_OFFSET_DISPCNT, DISPCNT_WIN0_ON);
        SetGpuReg(REG_OFFSET_WIN0H, WIN_RANGE(task->tWinLeft_fldeff_misc, task->tWinRight_fldeff_misc));
        SetGpuReg(REG_OFFSET_WIN0V, WIN_RANGE(task->tWinTop_fldeff_misc, task->tWinBottom_fldeff_misc));
        SetGpuReg(REG_OFFSET_WININ, WININ_WIN0_BG_ALL | WININ_WIN0_OBJ | WININ_WIN0_CLR);
        SetGpuReg(REG_OFFSET_WINOUT, 0);

        break;
    case 1:
        task->tBlendCnt_fldeff_misc = GetGpuReg(REG_OFFSET_BLDCNT);
        task->tBlendY_fldeff_misc = GetGpuReg(REG_OFFSET_BLDY);

        SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_TGT1_ALL | BLDCNT_EFFECT_LIGHTEN);
        SetGpuReg(REG_OFFSET_BLDY, 16);

        break;
    case 2:
        task->tWinLeft_fldeff_misc -= task->tHorzIncrement_fldeff_misc;
        task->tWinRight_fldeff_misc += task->tHorzIncrement_fldeff_misc;

        if (task->tWinLeft_fldeff_misc < 1 || task->tWinRight_fldeff_misc > DISPLAY_WIDTH - 1)
        {
            task->tWinLeft_fldeff_misc = 0;
            task->tWinRight_fldeff_misc = DISPLAY_WIDTH;
            SetGpuReg(REG_OFFSET_BLDY, 0);
            SetGpuReg(REG_OFFSET_BLDCNT, task->tBlendCnt_fldeff_misc);
            BlendPalettes(PALETTES_ALL, 0, 0);
            gPlttBufferFaded[0] = 0;
        }
        SetGpuReg(REG_OFFSET_WIN0H, WIN_RANGE(task->tWinLeft_fldeff_misc, task->tWinRight_fldeff_misc));

        if (task->tWinLeft_fldeff_misc != 0)
            return;
        break;
    case 3:
        task->tWinTop_fldeff_misc -= task->tVertIncrement_fldeff_misc;
        task->tWinBottom_fldeff_misc += task->tVertIncrement_fldeff_misc;

        if (task->tWinTop_fldeff_misc < 1 || task->tWinBottom_fldeff_misc > DISPLAY_HEIGHT - 1)
        {
            task->tWinTop_fldeff_misc = 0;
            task->tWinBottom_fldeff_misc = DISPLAY_HEIGHT;
            ClearGpuRegBits(REG_OFFSET_DISPCNT, DISPCNT_WIN0_ON);
        }
        SetGpuReg(REG_OFFSET_WIN0V, WIN_RANGE(task->tWinTop_fldeff_misc, task->tWinBottom_fldeff_misc));

        if (task->tWinTop_fldeff_misc != 0)
            return;
        break;
    default:
        SetGpuReg(REG_OFFSET_BLDCNT, task->tBlendCnt_fldeff_misc);
        DestroyTask(taskId);
        return;
    }
    task->tState_fldeff_misc++;
}

static void Task_ComputerScreenCloseEffect_fldeff_misc(u8 taskId)
{
    struct Task *task = &gTasks[taskId];

    switch (task->tState_fldeff_misc)
    {
    case 0:
        gPlttBufferFaded[0] = 0;
        break;
    case 1:
        task->tWinLeft_fldeff_misc = 0;
        task->tWinRight_fldeff_misc = DISPLAY_WIDTH;
        task->tWinTop_fldeff_misc = 0;
        task->tWinBottom_fldeff_misc = DISPLAY_HEIGHT;

        SetGpuRegBits(REG_OFFSET_DISPCNT, DISPCNT_WIN0_ON);
        SetGpuReg(REG_OFFSET_WIN0H, WIN_RANGE(task->tWinLeft_fldeff_misc, task->tWinRight_fldeff_misc));
        SetGpuReg(REG_OFFSET_WIN0V, WIN_RANGE(task->tWinTop_fldeff_misc, task->tWinBottom_fldeff_misc));
        SetGpuReg(REG_OFFSET_WININ, WININ_WIN0_BG_ALL | WININ_WIN0_OBJ | WININ_WIN0_CLR);
        SetGpuReg(REG_OFFSET_WINOUT, 0);
        break;
    case 2:
        task->tWinTop_fldeff_misc += task->tVertIncrement_fldeff_misc;
        task->tWinBottom_fldeff_misc -= task->tVertIncrement_fldeff_misc;

        if (task->tWinTop_fldeff_misc >= DISPLAY_HEIGHT / 2 || task->tWinBottom_fldeff_misc <= DISPLAY_HEIGHT / 2 + 1)
        {
            task->tWinTop_fldeff_misc = DISPLAY_HEIGHT / 2;
            task->tWinBottom_fldeff_misc = DISPLAY_HEIGHT / 2 + 1;
            SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_TGT1_ALL | BLDCNT_EFFECT_LIGHTEN);
            SetGpuReg(REG_OFFSET_BLDY, 16);
        }
        SetGpuReg(REG_OFFSET_WIN0V, WIN_RANGE(task->tWinTop_fldeff_misc, task->tWinBottom_fldeff_misc));

        if (task->tWinTop_fldeff_misc != DISPLAY_HEIGHT / 2)
            return;
        break;
    case 3:
        task->tWinLeft_fldeff_misc += task->tHorzIncrement_fldeff_misc;
        task->tWinRight_fldeff_misc -= task->tHorzIncrement_fldeff_misc;

        if (task->tWinLeft_fldeff_misc >= DISPLAY_WIDTH / 2 || task->tWinRight_fldeff_misc <= DISPLAY_WIDTH / 2)
        {
            task->tWinLeft_fldeff_misc = DISPLAY_WIDTH / 2;
            task->tWinRight_fldeff_misc = DISPLAY_WIDTH / 2;
            BlendPalettes(PALETTES_ALL, 16, 0);
            gPlttBufferFaded[0] = 0;
        }
        SetGpuReg(REG_OFFSET_WIN0H, WIN_RANGE(task->tWinLeft_fldeff_misc, task->tWinRight_fldeff_misc));

        if (task->tWinLeft_fldeff_misc != DISPLAY_WIDTH / 2)
            return;
        break;
    default:
        ClearGpuRegBits(REG_OFFSET_DISPCNT, DISPCNT_WIN0_ON);
        SetGpuReg(REG_OFFSET_BLDY, 0);
        SetGpuReg(REG_OFFSET_BLDCNT, 0);
        DestroyTask(taskId);
        return;
    }
    task->tState_fldeff_misc++;
}

#undef tState_fldeff_misc
#undef tHorzIncrement_fldeff_misc
#undef tVertIncrement_fldeff_misc
#undef tWinLeft_fldeff_misc
#undef tWinRight_fldeff_misc
#undef tWinTop_fldeff_misc
#undef tWinBottom_fldeff_misc
