bool8 FldEff_SecretBasePCTurnOn(void)
{
    s16 x, y;
    u8 taskId;

    GetXYCoordsOneStepInFrontOfPlayer(&x, &y);

    taskId = CreateTask(Task_SecretBasePCTurnOn_fldeff_misc, 0);
    gTasks[taskId].tX_fldeff_misc = x;
    gTasks[taskId].tY_fldeff_misc = y;
    gTasks[taskId].tState_fldeff_misc = 0;

    return FALSE;
}

static void Task_SecretBasePCTurnOn_fldeff_misc(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    switch (tState_fldeff_misc)
    {
    case 4:
    case 12:
        MapGridSetMetatileIdAt(tX_fldeff_misc, tY_fldeff_misc, METATILE_SecretBase_PC_On);
        CurrentMapDrawMetatileAt(tX_fldeff_misc, tY_fldeff_misc);
        break;
    case 8:
    case 16:
        MapGridSetMetatileIdAt(tX_fldeff_misc, tY_fldeff_misc, METATILE_SecretBase_PC);
        CurrentMapDrawMetatileAt(tX_fldeff_misc, tY_fldeff_misc);
        break;
    case 20:
        MapGridSetMetatileIdAt(tX_fldeff_misc, tY_fldeff_misc, METATILE_SecretBase_PC_On);
        CurrentMapDrawMetatileAt(tX_fldeff_misc, tY_fldeff_misc);
        FieldEffectActiveListRemove(FLDEFF_PCTURN_ON);
        ScriptContext_Enable();
        DestroyTask(taskId);
        return;
    }

    tState_fldeff_misc++;
}

#undef tX_fldeff_misc
#undef tY_fldeff_misc
#undef tState_fldeff_misc

void DoSecretBasePCTurnOffEffect(void)
{
    s16 x, y;

    GetXYCoordsOneStepInFrontOfPlayer(&x, &y);
    PlaySE(SE_PC_OFF);

    if (!VarGet(VAR_CURRENT_SECRET_BASE))
        MapGridSetMetatileIdAt(x, y, METATILE_SecretBase_PC | MAPGRID_COLLISION_MASK);
    else
        MapGridSetMetatileIdAt(x, y, METATILE_SecretBase_RegisterPC | MAPGRID_COLLISION_MASK);

    CurrentMapDrawMetatileAt(x, y);
}

void PopSecretBaseBalloon(s16 metatileId, s16 x, s16 y)
{
    u8 taskId = CreateTask(Task_PopSecretBaseBalloon_fldeff_misc, 0);

    gTasks[taskId].data[0] = metatileId;
    gTasks[taskId].data[1] = x;
    gTasks[taskId].data[2] = y;
    gTasks[taskId].data[3] = 0;
    gTasks[taskId].data[4] = 1;
}

static void Task_PopSecretBaseBalloon_fldeff_misc(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    if (data[3] == 6)
        data[3] = 0;
    else
        data[3]++;

    if (data[3] == 0)
    {
        if (data[4] == 2)
            DoBalloonSoundEffect_fldeff_misc(data[0]);

        MapGridSetMetatileIdAt(data[1], data[2], data[0] + data[4]);
        CurrentMapDrawMetatileAt(data[1], data[2]);

        if (data[4] == 3)
            DestroyTask(taskId);
        else
            data[4]++;
    }
}

static void DoBalloonSoundEffect_fldeff_misc(s16 metatileId)
{
    switch (metatileId)
    {
    case METATILE_SecretBase_RedBalloon:
        PlaySE(SE_BALLOON_RED);
        break;
    case METATILE_SecretBase_BlueBalloon:
        PlaySE(SE_BALLOON_BLUE);
        break;
    case METATILE_SecretBase_YellowBalloon:
        PlaySE(SE_BALLOON_YELLOW);
        break;
    case METATILE_SecretBase_MudBall:
        PlaySE(SE_MUD_BALL);
        break;
    }
}

