static void ResetGpuRegsAndBgs_frontier_pass(void)
{
    SetGpuReg(REG_OFFSET_DISPCNT, 0);
    SetGpuReg(REG_OFFSET_BG3CNT, 0);
    SetGpuReg(REG_OFFSET_BG2CNT, 0);
    SetGpuReg(REG_OFFSET_BG1CNT, 0);
    SetGpuReg(REG_OFFSET_BG0CNT, 0);
    ChangeBgX(0, 0, BG_COORD_SET);
    ChangeBgY(0, 0, BG_COORD_SET);
    ChangeBgX(1, 0, BG_COORD_SET);
    ChangeBgY(1, 0, BG_COORD_SET);
    ChangeBgX(2, 0, BG_COORD_SET);
    ChangeBgY(2, 0, BG_COORD_SET);
    ChangeBgX(3, 0, BG_COORD_SET);
    ChangeBgY(3, 0, BG_COORD_SET);
    SetGpuReg(REG_OFFSET_BLDCNT, 0);
    SetGpuReg(REG_OFFSET_BLDY, 0);
    SetGpuReg(REG_OFFSET_BLDALPHA, 0);
    SetGpuReg(REG_OFFSET_WIN0H, 0);
    SetGpuReg(REG_OFFSET_WIN0V, 0);
    SetGpuReg(REG_OFFSET_WIN1H, 0);
    SetGpuReg(REG_OFFSET_WIN1V, 0);
    SetGpuReg(REG_OFFSET_WININ, 0);
    SetGpuReg(REG_OFFSET_WINOUT, 0);
    CpuFill16(0, (void *)VRAM, VRAM_SIZE);
    CpuFill32(0, (void *)OAM, OAM_SIZE);
}

void ShowFrontierPass(void (*callback)(void))
{
    AllocateFrontierPassData_frontier_pass(callback);
    SetMainCallback2(CB2_InitFrontierPass_frontier_pass);
}

static void LeaveFrontierPass_frontier_pass(void)
{
    SetMainCallback2(sPassData_frontier_pass->callback);
    FreeFrontierPassData_frontier_pass();
}

static u32 AllocateFrontierPassData_frontier_pass(void (*callback)(void))
{
    u8 i;

    if (sPassData_frontier_pass != NULL)
        return ERR_ALREADY_DONE_frontier_pass;

    sPassData_frontier_pass = AllocZeroed(sizeof(*sPassData_frontier_pass));
    if (sPassData_frontier_pass == NULL)
        return ERR_ALLOC_FAILED_frontier_pass;

    sPassData_frontier_pass->callback = callback;
    i = GetCurrentRegionMapSectionId();
    if (i != MAPSEC_BATTLE_FRONTIER && i != MAPSEC_ARTISAN_CAVE)
    {
        // Player is not in the frontier, set
        // cursor position to the Trainer Card
        sPassData_frontier_pass->cursorX = 176;
        sPassData_frontier_pass->cursorY = 104;
    }
    else
    {
        // Player is in the frontier, set
        // cursor position to the frontier map
        sPassData_frontier_pass->cursorX = 176;
        sPassData_frontier_pass->cursorY = 48;
    }

    sPassData_frontier_pass->battlePoints = gSaveBlock2Ptr->frontier.battlePoints;
    sPassData_frontier_pass->hasBattleRecord = CanCopyRecordedBattleSaveData();
    sPassData_frontier_pass->areaToShow = CURSOR_AREA_NOTHING_frontier_pass;
    sPassData_frontier_pass->trainerStars = CountPlayerTrainerStars();
    for (i = 0; i < NUM_FRONTIER_FACILITIES; i++)
    {
        if (FlagGet(FLAG_SYS_TOWER_SILVER + i * 2))
            sPassData_frontier_pass->facilitySymbols[i]++;
        if (FlagGet(FLAG_SYS_TOWER_GOLD + i * 2))
            sPassData_frontier_pass->facilitySymbols[i]++;
    }

    return SUCCESS_frontier_pass;
}

static u32 FreeFrontierPassData_frontier_pass(void)
{
    if (sPassData_frontier_pass == NULL)
        return ERR_ALREADY_DONE_frontier_pass;

    memset(sPassData_frontier_pass, 0, sizeof(*sPassData_frontier_pass)); // Why clear data, if it's going to be freed anyway?
    FREE_AND_SET_NULL(sPassData_frontier_pass);
    return SUCCESS_frontier_pass;
}

static u32 AllocateFrontierPassGfx_frontier_pass(void)
{
    if (sPassGfx_frontier_pass != NULL)
        return ERR_ALREADY_DONE_frontier_pass;

    sPassGfx_frontier_pass = AllocZeroed(sizeof(*sPassGfx_frontier_pass));
    if (sPassGfx_frontier_pass == NULL)
        return ERR_ALLOC_FAILED_frontier_pass;

    return SUCCESS_frontier_pass;
}

static u32 FreeFrontierPassGfx_frontier_pass(void)
{
    FreeAllWindowBuffers();
    if (sPassGfx_frontier_pass == NULL)
        return ERR_ALREADY_DONE_frontier_pass;

    TRY_FREE_AND_SET_NULL(sPassGfx_frontier_pass->battleRecordTilemap);
    TRY_FREE_AND_SET_NULL(sPassGfx_frontier_pass->mapAndCardTilemap);
    TRY_FREE_AND_SET_NULL(sPassGfx_frontier_pass->mapAndCardZoomTilemap);

    memset(sPassGfx_frontier_pass, 0, sizeof(*sPassGfx_frontier_pass)); // Why clear data, if it's going to be freed anyway?
    FREE_AND_SET_NULL(sPassGfx_frontier_pass);
    return SUCCESS_frontier_pass;
}

static void VBlankCB_FrontierPass_frontier_pass(void)
{
    if (sPassGfx_frontier_pass->zooming)
    {
        SetBgAffine(2,
                    sBgAffineCoords_frontier_pass[sPassData_frontier_pass->areaToShow - 1][0] << 8,
                    sBgAffineCoords_frontier_pass[sPassData_frontier_pass->areaToShow - 1][1] << 8,
                    sBgAffineCoords_frontier_pass[sPassData_frontier_pass->areaToShow - 1][0],
                    sBgAffineCoords_frontier_pass[sPassData_frontier_pass->areaToShow - 1][1],
                    sPassGfx_frontier_pass->scaleX,
                    sPassGfx_frontier_pass->scaleY,
                    0);
    }
    LoadOam();
    ProcessSpriteCopyRequests();
    TransferPlttBuffer();
}

static void CB2_FrontierPass_frontier_pass(void)
{
    RunTasks();
    AnimateSprites();
    BuildOamBuffer();
}

static void CB2_InitFrontierPass_frontier_pass(void)
{
    if (InitFrontierPass_frontier_pass())
    {
        CreateTask(Task_HandleFrontierPassInput_frontier_pass, 0);
        SetMainCallback2(CB2_FrontierPass_frontier_pass);
    }
}

static void CB2_HideFrontierPass_frontier_pass(void)
{
    if (HideFrontierPass_frontier_pass())
        LeaveFrontierPass_frontier_pass();
}

static bool32 InitFrontierPass_frontier_pass(void)
{
    u32 sizeOut = 0;

    switch (sPassData_frontier_pass->state)
    {
    case 0:
        SetVBlankCallback(NULL);
        ScanlineEffect_Stop();
        SetVBlankHBlankCallbacksToNull();
        DisableInterrupts(INTR_FLAG_HBLANK);
        break;
    case 1:
        ResetGpuRegsAndBgs_frontier_pass();
        break;
    case 2:
        ResetTasks();
        ResetSpriteData();
        FreeAllSpritePalettes();
        ResetPaletteFade();
        ResetTempTileDataBuffers();
        break;
    case 3:
        AllocateFrontierPassGfx_frontier_pass();
        break;
    case 4:
        ResetBgsAndClearDma3BusyFlags(0);
        InitBgsFromTemplates(1, sPassBgTemplates_frontier_pass, ARRAY_COUNT(sPassBgTemplates_frontier_pass));
        SetBgTilemapBuffer(1, sPassGfx_frontier_pass->tilemapBuff1);
        SetBgTilemapBuffer(2, sPassGfx_frontier_pass->tilemapBuff2);
        SetBgTilemapBuffer(3, sPassGfx_frontier_pass->tilemapBuff3);
        SetBgAttribute(2, BG_ATTR_WRAPAROUND, 1);
        break;
    case 5:
        InitWindows(sPassWindowTemplates_frontier_pass);
        DeactivateAllTextPrinters();
        break;
    case 6:
        sPassGfx_frontier_pass->mapAndCardZoomTilemap = malloc_and_decompress(sMapAndCard_Zooming_Tilemap_frontier_pass, &sizeOut);
        sPassGfx_frontier_pass->mapAndCardTilemap = malloc_and_decompress(sMapAndCard_ZoomedOut_Tilemap_frontier_pass, &sizeOut);
        sPassGfx_frontier_pass->battleRecordTilemap = malloc_and_decompress(sBattleRecord_Tilemap_frontier_pass, &sizeOut);
        DecompressAndCopyTileDataToVram(1, gFrontierPassBg_Gfx, 0, 0, 0);
        DecompressAndCopyTileDataToVram(2, gFrontierPassMapAndCard_Gfx, 0, 0, 0);
        break;
    case 7:
        if (FreeTempTileDataBuffersIfPossible())
            return FALSE;
        FillBgTilemapBufferRect_Palette0(0, 0, 0, 0, DISPLAY_TILE_WIDTH, DISPLAY_TILE_HEIGHT);
        FillBgTilemapBufferRect_Palette0(1, 0, 0, 0, DISPLAY_TILE_WIDTH, DISPLAY_TILE_HEIGHT);
        FillBgTilemapBufferRect_Palette0(2, 0, 0, 0, DISPLAY_TILE_WIDTH, DISPLAY_TILE_HEIGHT);
        CopyBgTilemapBufferToVram(0);
        CopyBgTilemapBufferToVram(1);
        CopyBgTilemapBufferToVram(2);
        break;
    case 8:
        LoadPalette(gFrontierPassBg_Pal, 0, NUM_BG_PAL_SLOTS_frontier_pass * PLTT_SIZE_4BPP);
        LoadPalette(gFrontierPassBg_Pal[1 + sPassData_frontier_pass->trainerStars], BG_PLTT_ID(1), PLTT_SIZE_4BPP);
        LoadPalette(GetTextWindowPalette(0), BG_PLTT_ID(15), PLTT_SIZE_4BPP);
        DrawFrontierPassBg_frontier_pass();
        UpdateAreaHighlight_frontier_pass(sPassData_frontier_pass->cursorArea, sPassData_frontier_pass->previousCursorArea);
        if (sPassData_frontier_pass->areaToShow == CURSOR_AREA_MAP_frontier_pass || sPassData_frontier_pass->areaToShow == CURSOR_AREA_CARD_frontier_pass)
        {
            sPassData_frontier_pass->state = 0;
            return TRUE;
        }
        break;
    case 9:
        SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_OBJ_ON | DISPCNT_OBJ_1D_MAP);
        ShowBg(0);
        ShowBg(1);
        ShowBg(2);
        LoadCursorAndSymbolSprites_frontier_pass();
        SetVBlankCallback(VBlankCB_FrontierPass_frontier_pass);
        BlendPalettes(PALETTES_ALL, 16, RGB_BLACK);
        BeginNormalPaletteFade(PALETTES_ALL, 0, 16, 0, RGB_BLACK);
        break;
    case 10:
        AnimateSprites();
        BuildOamBuffer();
        if (UpdatePaletteFade())
            return FALSE;

        sPassData_frontier_pass->state = 0;
        return TRUE;
    }

    sPassData_frontier_pass->state++;
    return FALSE;
}

static bool32 HideFrontierPass_frontier_pass(void)
{
    switch (sPassData_frontier_pass->state)
    {
    case 0:
        if (sPassData_frontier_pass->areaToShow != CURSOR_AREA_MAP_frontier_pass && sPassData_frontier_pass->areaToShow != CURSOR_AREA_CARD_frontier_pass)
        {
            BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
        }
        else
        {
            sPassData_frontier_pass->state = 2;
            return FALSE;
        }
        break;
    case 1:
        if (UpdatePaletteFade())
            return FALSE;
        break;
    case 2:
        SetGpuReg(REG_OFFSET_DISPCNT, 0);
        HideBg(0);
        HideBg(1);
        HideBg(2);
        SetVBlankCallback(NULL);
        ScanlineEffect_Stop();
        SetVBlankHBlankCallbacksToNull();
        break;
    case 3:
        FreeCursorAndSymbolSprites_frontier_pass();
        break;
    case 4:
        ResetGpuRegsAndBgs_frontier_pass();
        ResetTasks();
        ResetSpriteData();
        FreeAllSpritePalettes();
        break;
    case 5:
        UnsetBgTilemapBuffer(0);
        UnsetBgTilemapBuffer(1);
        UnsetBgTilemapBuffer(2);
        FreeFrontierPassGfx_frontier_pass();
        sPassData_frontier_pass->state = 0;
        return TRUE;
    }

    sPassData_frontier_pass->state++;
    return FALSE;
}

static u8 GetCursorAreaFromCoords_frontier_pass(s16 x, s16 y)
{
    u8 i;

    // Minus/Plus 1, because the table doesn't take CURSOR_AREA_NOTHING_frontier_pass into account.
    for (i = 0; i < CURSOR_AREA_COUNT_frontier_pass - 1; i++)
    {
        if (sPassAreasLayout_frontier_pass[i].yStart <= y && sPassAreasLayout_frontier_pass[i].yEnd >= y
         && sPassAreasLayout_frontier_pass[i].xStart <= x && sPassAreasLayout_frontier_pass[i].xEnd >= x)
        {
            if (i >= CURSOR_AREA_SYMBOL_frontier_pass - 1 && sPassData_frontier_pass->facilitySymbols[i - CURSOR_AREA_SYMBOL_frontier_pass + 1] == 0)
                break;

            return i + 1;
        }
    }

    return CURSOR_AREA_NOTHING_frontier_pass;
}

// For Task_PassAreaZoom_frontier_pass
#define tZoomOut_frontier_pass data[0]

void CB2_ReshowFrontierPass(void)
{
    u8 taskId;

    if (!InitFrontierPass_frontier_pass())
        return;

    switch (sPassData_frontier_pass->areaToShow)
    {
    case CURSOR_AREA_MAP_frontier_pass:
    case CURSOR_AREA_CARD_frontier_pass:
        taskId = CreateTask(Task_PassAreaZoom_frontier_pass, 0);
        gTasks[taskId].tZoomOut_frontier_pass = TRUE;
        break;
    case CURSOR_AREA_RECORD_frontier_pass:
    default:
        sPassData_frontier_pass->areaToShow = CURSOR_AREA_NOTHING_frontier_pass;
        taskId = CreateTask(Task_HandleFrontierPassInput_frontier_pass, 0);
        break;
    }

    SetMainCallback2(CB2_FrontierPass_frontier_pass);
}

static void CB2_ReturnFromRecord_frontier_pass(void)
{
    AllocateFrontierPassData_frontier_pass(sSavedPassData_frontier_pass.callback);
    sPassData_frontier_pass->cursorX = sSavedPassData_frontier_pass.cursorX;
    sPassData_frontier_pass->cursorY = sSavedPassData_frontier_pass.cursorY;
    memset(&sSavedPassData_frontier_pass, 0, sizeof(sSavedPassData_frontier_pass));
    switch (InBattlePyramid())
    {
    case 1:
        PlayBGM(MUS_B_PYRAMID);
        break;
    case 2:
        PlayBGM(MUS_B_PYRAMID_TOP);
        break;
    default:
        Overworld_PlaySpecialMapMusic();
        break;
    }

    SetMainCallback2(CB2_ReshowFrontierPass);
}

static void CB2_ShowFrontierPassFeature_frontier_pass(void)
{
    if (!HideFrontierPass_frontier_pass())
        return;

    switch (sPassData_frontier_pass->areaToShow)
    {
    case CURSOR_AREA_MAP_frontier_pass:
        ShowFrontierMap_frontier_pass(CB2_ReshowFrontierPass);
        break;
    case CURSOR_AREA_RECORD_frontier_pass:
        sSavedPassData_frontier_pass.callback = sPassData_frontier_pass->callback;
        sSavedPassData_frontier_pass.cursorX = sPassData_frontier_pass->cursorX;
        sSavedPassData_frontier_pass.cursorY = sPassData_frontier_pass->cursorY;
        FreeFrontierPassData_frontier_pass();
        PlayRecordedBattle(CB2_ReturnFromRecord_frontier_pass);
        break;
    case CURSOR_AREA_CARD_frontier_pass:
        ShowPlayerTrainerCard(CB2_ReshowFrontierPass);
        break;
    }
}

static bool32 TryCallPassAreaFunction_frontier_pass(u8 taskId, u8 cursorArea)
{
    switch (cursorArea)
    {
    case CURSOR_AREA_RECORD_frontier_pass:
        if (!sPassData_frontier_pass->hasBattleRecord)
            return FALSE;
        sPassData_frontier_pass->areaToShow = CURSOR_AREA_RECORD_frontier_pass;
        DestroyTask(taskId);
        SetMainCallback2(CB2_ShowFrontierPassFeature_frontier_pass);
        break;
    case CURSOR_AREA_MAP_frontier_pass:
    case CURSOR_AREA_CARD_frontier_pass:
        sPassData_frontier_pass->areaToShow = cursorArea;
        gTasks[taskId].func = Task_PassAreaZoom_frontier_pass;
        gTasks[taskId].tZoomOut_frontier_pass = FALSE;
        break;
    default:
        return FALSE;
    }

    sPassData_frontier_pass->cursorX = sPassGfx_frontier_pass->cursorSprite->x;
    sPassData_frontier_pass->cursorY = sPassGfx_frontier_pass->cursorSprite->y;
    return TRUE;
}

static void Task_HandleFrontierPassInput_frontier_pass(u8 taskId)
{
    u8 var = FALSE; // Reused, first informs whether the cursor moves, then used as the new cursor area.

    if (JOY_HELD(DPAD_UP) && sPassGfx_frontier_pass->cursorSprite->y >= 9)
    {
        sPassGfx_frontier_pass->cursorSprite->y -= 2;
        if (sPassGfx_frontier_pass->cursorSprite->y <= 7)
            sPassGfx_frontier_pass->cursorSprite->y = 2;
        var = TRUE;
    }
    if (JOY_HELD(DPAD_DOWN) && sPassGfx_frontier_pass->cursorSprite->y <= 135)
    {
        sPassGfx_frontier_pass->cursorSprite->y += 2;
        if (sPassGfx_frontier_pass->cursorSprite->y >= 137)
            sPassGfx_frontier_pass->cursorSprite->y = 136;
        var = TRUE;
    }

    if (JOY_HELD(DPAD_LEFT) && sPassGfx_frontier_pass->cursorSprite->x >= 6)
    {
        sPassGfx_frontier_pass->cursorSprite->x -= 2;
        if (sPassGfx_frontier_pass->cursorSprite->x <= 4)
            sPassGfx_frontier_pass->cursorSprite->x = 5;
        var = TRUE;
    }
    if (JOY_HELD(DPAD_RIGHT) && sPassGfx_frontier_pass->cursorSprite->x <= 231)
    {
        sPassGfx_frontier_pass->cursorSprite->x += 2;
        if (sPassGfx_frontier_pass->cursorSprite->x >= 233)
            sPassGfx_frontier_pass->cursorSprite->x = 232;
        var = TRUE;
    }

    if (!var) // Cursor did not change.
    {
        if (sPassData_frontier_pass->cursorArea != CURSOR_AREA_NOTHING_frontier_pass && JOY_NEW(A_BUTTON))
        {
            if (sPassData_frontier_pass->cursorArea <= CURSOR_AREA_RECORD_frontier_pass) // Map, Card, Record
            {
                PlaySE(SE_SELECT);
                if (TryCallPassAreaFunction_frontier_pass(taskId, sPassData_frontier_pass->cursorArea))
                    return;
            }
            else if (sPassData_frontier_pass->cursorArea == CURSOR_AREA_CANCEL_frontier_pass)
            {
                PlaySE(SE_PC_OFF);
                SetMainCallback2(CB2_HideFrontierPass_frontier_pass);
                DestroyTask(taskId);
                // BUG. The function should return here. Otherwise, it can play the same sound twice and destroy the same task twice.
                #ifdef BUGFIX
                return;
                #endif
            }
        }

        if (JOY_NEW(B_BUTTON))
        {
            PlaySE(SE_PC_OFF);
            SetMainCallback2(CB2_HideFrontierPass_frontier_pass);
            DestroyTask(taskId);
        }
    }
    else
    {
        var = GetCursorAreaFromCoords_frontier_pass(sPassGfx_frontier_pass->cursorSprite->x - 5, sPassGfx_frontier_pass->cursorSprite->y + 5);
        if (sPassData_frontier_pass->cursorArea != var)
        {
            PrintAreaDescription_frontier_pass(var);
            sPassData_frontier_pass->previousCursorArea = sPassData_frontier_pass->cursorArea;
            sPassData_frontier_pass->cursorArea = var;
            UpdateAreaHighlight_frontier_pass(sPassData_frontier_pass->cursorArea, sPassData_frontier_pass->previousCursorArea);
        }
    }
}

#define tScaleX_frontier_pass      data[1]
#define tScaleY_frontier_pass      data[2]
#define tScaleSpeedX_frontier_pass data[3]
#define tScaleSpeedY_frontier_pass data[4]

// Zoom in/out for the Frontier map or the trainer card
static void Task_PassAreaZoom_frontier_pass(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    switch (sPassData_frontier_pass->state)
    {
    case 0:
        // Initialize the zoom, start fading in/out
        if (!tZoomOut_frontier_pass)
        {
            // Zooming in to map/card screen
            ShowHideZoomingArea_frontier_pass(TRUE, FALSE);
            tScaleX_frontier_pass = Q_8_8(1);
            tScaleY_frontier_pass = Q_8_8(1);
            tScaleSpeedX_frontier_pass = 0x15;
            tScaleSpeedY_frontier_pass = 0x15;
            BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_WHITE);
        }
        else
        {
            // Zooming out of map/card screen back to frontier pass
            tScaleX_frontier_pass = Q_8_8(1.984375); // 1 and 63/64
            tScaleY_frontier_pass = Q_8_8(1.984375);
            tScaleSpeedX_frontier_pass = -0x15;
            tScaleSpeedY_frontier_pass = -0x15;
            SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_OBJ_ON | DISPCNT_OBJ_1D_MAP);
            ShowBg(0);
            ShowBg(1);
            ShowBg(2);
            LoadCursorAndSymbolSprites_frontier_pass();
            SetVBlankCallback(VBlankCB_FrontierPass_frontier_pass);
            BlendPalettes(PALETTES_ALL, 16, RGB_WHITE);
            BeginNormalPaletteFade(PALETTES_ALL, 0, 16, 0, RGB_WHITE);
        }
        sPassGfx_frontier_pass->zooming = TRUE;
        sPassGfx_frontier_pass->scaleX = MathUtil_Inv16(tScaleX_frontier_pass);
        sPassGfx_frontier_pass->scaleY = MathUtil_Inv16(tScaleY_frontier_pass);
        break;
    case 1:
        // Update the fade and zoom
        UpdatePaletteFade();
        tScaleX_frontier_pass += tScaleSpeedX_frontier_pass;
        tScaleY_frontier_pass += tScaleSpeedY_frontier_pass;
        sPassGfx_frontier_pass->scaleX = MathUtil_Inv16(tScaleX_frontier_pass);
        sPassGfx_frontier_pass->scaleY = MathUtil_Inv16(tScaleY_frontier_pass);

        // Check if zoom hasn't reached target
        if (!tZoomOut_frontier_pass)
        {
            if (tScaleX_frontier_pass <= Q_8_8(1.984375))
                return;
        }
        else
        {
            if (tScaleX_frontier_pass != Q_8_8(1))
                return;
        }
        break;
    case 2:
        if (sPassGfx_frontier_pass->zooming)
            sPassGfx_frontier_pass->zooming = FALSE;
        if (UpdatePaletteFade())
            return;

        if (!tZoomOut_frontier_pass)
        {
            // Zoomed in and faded out, switch to map or trainer card
            DestroyTask(taskId);
            SetMainCallback2(CB2_ShowFrontierPassFeature_frontier_pass);
        }
        else
        {
            // Zoomed out and faded in, return to frontier pass
            ShowHideZoomingArea_frontier_pass(FALSE, FALSE);
            sPassData_frontier_pass->areaToShow = CURSOR_AREA_NOTHING_frontier_pass;
            gTasks[taskId].func = Task_HandleFrontierPassInput_frontier_pass;
        }
        SetBgAttribute(2, BG_ATTR_WRAPAROUND, 0);
        sPassData_frontier_pass->state = 0;
        return;
    }

    sPassData_frontier_pass->state++;
}

static void ShowAndPrintWindows_frontier_pass(void)
{
    s32 x;
    u8 i;

    for (i = 0; i < WINDOW_COUNT_frontier_pass; i++)
    {
        PutWindowTilemap(i);
        FillWindowPixelBuffer(i, PIXEL_FILL(0));
    }

    x = GetStringCenterAlignXOffset(FONT_NORMAL, gText_SymbolsEarned, 96);
    AddTextPrinterParameterized3(WINDOW_EARNED_SYMBOLS_frontier_pass, FONT_NORMAL, x, 5, sTextColors_frontier_pass[0], 0, gText_SymbolsEarned);

    x = GetStringCenterAlignXOffset(FONT_NORMAL, gText_BattleRecord, 96);
    AddTextPrinterParameterized3(WINDOW_BATTLE_RECORD_frontier_pass, FONT_NORMAL, x, 5, sTextColors_frontier_pass[0], 0, gText_BattleRecord);

    AddTextPrinterParameterized3(WINDOW_BATTLE_POINTS_frontier_pass, FONT_SMALL_NARROW, 5, 4, sTextColors_frontier_pass[0], 0, gText_BattlePoints);
    ConvertIntToDecimalStringN(gStringVar4, sPassData_frontier_pass->battlePoints, STR_CONV_MODE_LEFT_ALIGN, 5);
    x = GetStringRightAlignXOffset(FONT_SMALL_NARROW, gStringVar4, 91);
    AddTextPrinterParameterized3(WINDOW_BATTLE_POINTS_frontier_pass, FONT_SMALL_NARROW, x, 16, sTextColors_frontier_pass[0], 0, gStringVar4);

    sPassData_frontier_pass->cursorArea = GetCursorAreaFromCoords_frontier_pass(sPassData_frontier_pass->cursorX - 5, sPassData_frontier_pass->cursorY + 5);
    sPassData_frontier_pass->previousCursorArea = CURSOR_AREA_NOTHING_frontier_pass;
    PrintAreaDescription_frontier_pass(sPassData_frontier_pass->cursorArea);

    for (i = 0; i < WINDOW_COUNT_frontier_pass; i++)
        CopyWindowToVram(i, COPYWIN_FULL);

    CopyBgTilemapBufferToVram(0);
}

static void PrintAreaDescription_frontier_pass(u8 cursorArea)
{
    FillWindowPixelBuffer(WINDOW_DESCRIPTION_frontier_pass, PIXEL_FILL(0));

    if (cursorArea == CURSOR_AREA_RECORD_frontier_pass && !sPassData_frontier_pass->hasBattleRecord)
        AddTextPrinterParameterized3(WINDOW_DESCRIPTION_frontier_pass, FONT_NORMAL, 2, 0, sTextColors_frontier_pass[1], 0, sPassAreaDescriptions[CURSOR_AREA_NOTHING_frontier_pass]);
    else if (cursorArea != CURSOR_AREA_NOTHING_frontier_pass)
        AddTextPrinterParameterized3(WINDOW_DESCRIPTION_frontier_pass, FONT_NORMAL, 2, 0, sTextColors_frontier_pass[1], 0, sPassAreaDescriptions[cursorArea]);

    CopyWindowToVram(WINDOW_DESCRIPTION_frontier_pass, COPYWIN_FULL);
    CopyBgTilemapBufferToVram(0);
}

static void ShowHideZoomingArea_frontier_pass(bool8 show, bool8 zoomedIn)
{
    switch (sPassData_frontier_pass->areaToShow)
    {
    case CURSOR_AREA_MAP_frontier_pass:
        if (show)
            CopyToBgTilemapBufferRect_ChangePalette(2, sPassGfx_frontier_pass->mapAndCardZoomTilemap, 16, 3, 12, 7, 16);
        else
            FillBgTilemapBufferRect(2, 0, 16, 3, 12, 7, 16);
        break;
    case CURSOR_AREA_CARD_frontier_pass:
        if (show)
            CopyToBgTilemapBufferRect_ChangePalette(2, sPassGfx_frontier_pass->mapAndCardZoomTilemap + 84, 16, 10, 12, 7, 16);
        else
            FillBgTilemapBufferRect(2, 0, 16, 10, 12, 7, 16);
        break;
    default:
        return;
    }

    CopyBgTilemapBufferToVram(2);
    if (zoomedIn)
    {
        SetBgAffine(2,
                    sBgAffineCoords_frontier_pass[sPassData_frontier_pass->areaToShow - 1][0] << 8,
                    sBgAffineCoords_frontier_pass[sPassData_frontier_pass->areaToShow - 1][1] << 8,
                    sBgAffineCoords_frontier_pass[sPassData_frontier_pass->areaToShow - 1][0],
                    sBgAffineCoords_frontier_pass[sPassData_frontier_pass->areaToShow - 1][1],
                    MathUtil_Inv16(Q_8_8(1.984375)), // 1 and 63/64
                    MathUtil_Inv16(Q_8_8(1.984375)),
                    0);
    }
    else
    {
        SetBgAffine(2,
                    sBgAffineCoords_frontier_pass[sPassData_frontier_pass->areaToShow - 1][0] << 8,
                    sBgAffineCoords_frontier_pass[sPassData_frontier_pass->areaToShow - 1][1] << 8,
                    sBgAffineCoords_frontier_pass[sPassData_frontier_pass->areaToShow - 1][0],
                    sBgAffineCoords_frontier_pass[sPassData_frontier_pass->areaToShow - 1][1],
                    MathUtil_Inv16(Q_8_8(1)),
                    MathUtil_Inv16(Q_8_8(1)),
                    0);
    }
}

static void UpdateAreaHighlight_frontier_pass(u8 cursorArea, u8 previousCursorArea)
{
    #define NON_HIGHLIGHT_AREA_frontier_pass(area) ((area) == CURSOR_AREA_NOTHING_frontier_pass || (area) > CURSOR_AREA_CANCEL_frontier_pass)

    // If moving off highlightable area, unhighlight it
    switch (previousCursorArea)
    {
    case CURSOR_AREA_MAP_frontier_pass:
        CopyToBgTilemapBufferRect_ChangePalette(1, sPassGfx_frontier_pass->mapAndCardTilemap, 16, 3, 12, 7, 17);
        break;
    case CURSOR_AREA_CARD_frontier_pass:
        CopyToBgTilemapBufferRect_ChangePalette(1, sPassGfx_frontier_pass->mapAndCardTilemap + 336, 16, 10, 12, 7, 17);
        break;
    case CURSOR_AREA_RECORD_frontier_pass:
        if (sPassData_frontier_pass->hasBattleRecord)
            CopyToBgTilemapBufferRect_ChangePalette(1, sPassGfx_frontier_pass->battleRecordTilemap, 2, 10, 12, 3, 17);
        else if (NON_HIGHLIGHT_AREA_frontier_pass(cursorArea))
            return;
        break;
    case CURSOR_AREA_CANCEL_frontier_pass:
        CopyToBgTilemapBufferRect_ChangePalette(1, gFrontierPassCancelButton_Tilemap, 21, 0, 9, 2, 17);
        break;
    default:
        if (NON_HIGHLIGHT_AREA_frontier_pass(cursorArea))
            return;
        break;
    }

    // If moving on to highlightable area, highlight it
    switch (cursorArea)
    {
    case CURSOR_AREA_MAP_frontier_pass:
        CopyToBgTilemapBufferRect_ChangePalette(1, sPassGfx_frontier_pass->mapAndCardTilemap + 168, 16, 3, 12, 7, 17);
        break;
    case CURSOR_AREA_CARD_frontier_pass:
        CopyToBgTilemapBufferRect_ChangePalette(1, sPassGfx_frontier_pass->mapAndCardTilemap + 504, 16, 10, 12, 7, 17);
        break;
    case CURSOR_AREA_RECORD_frontier_pass:
        if (sPassData_frontier_pass->hasBattleRecord)
            CopyToBgTilemapBufferRect_ChangePalette(1, sPassGfx_frontier_pass->battleRecordTilemap + 72, 2, 10, 12, 3, 17);
        else
            return;
        break;
    case CURSOR_AREA_CANCEL_frontier_pass:
        CopyToBgTilemapBufferRect_ChangePalette(1, gFrontierPassCancelButtonHighlighted_Tilemap, 21, 0, 9, 2, 17);
        break;
    default:
        if (NON_HIGHLIGHT_AREA_frontier_pass(previousCursorArea))
            return;
    }

    CopyBgTilemapBufferToVram(1);
}

static void DrawFrontierPassBg_frontier_pass(void)
{
    CopyToBgTilemapBuffer(1, gFrontierPassBg_Tilemap, 0, 0);
    UpdateAreaHighlight_frontier_pass(sPassData_frontier_pass->cursorArea, sPassData_frontier_pass->previousCursorArea);
    ShowHideZoomingArea_frontier_pass(TRUE, sPassData_frontier_pass->areaToShow); // If returning to frontier pass from map/card (areaToShow will be != 0)
    ShowAndPrintWindows_frontier_pass();
    CopyBgTilemapBufferToVram(1);
}

static void LoadCursorAndSymbolSprites_frontier_pass(void)
{
    u8 spriteId;
    u8 i = 0;

    FreeAllSpritePalettes();
    ResetAffineAnimData();
    LoadSpritePalettes(sSpritePalettes_frontier_pass);
    LoadCompressedSpriteSheet(&sCursorSpriteSheets_frontier_pass[0]);
    LoadCompressedSpriteSheet(&sCursorSpriteSheets_frontier_pass[2]);
    spriteId = CreateSprite(&sSpriteTemplates_Cursors_frontier_pass[0], sPassData_frontier_pass->cursorX, sPassData_frontier_pass->cursorY, 0);
    sPassGfx_frontier_pass->cursorSprite = &gSprites[spriteId];
    sPassGfx_frontier_pass->cursorSprite->oam.priority = 0;

    for (i = 0; i < NUM_FRONTIER_FACILITIES; i++)
    {
        if (sPassData_frontier_pass->facilitySymbols[i] != 0)
        {
            struct SpriteTemplate sprite = sSpriteTemplate_Medal_frontier_pass;

            sprite.paletteTag += sPassData_frontier_pass->facilitySymbols[i] - 1; // Adds 1 if gold for TAG_MEDAL_GOLD_frontier_pass
            spriteId = CreateSprite(&sprite, sPassAreasLayout_frontier_pass[i + CURSOR_AREA_SYMBOL_frontier_pass - 1].xStart + 8, sPassAreasLayout_frontier_pass[i + CURSOR_AREA_SYMBOL_frontier_pass - 1].yStart + 6, i + 1);
            sPassGfx_frontier_pass->symbolSprites[i] = &gSprites[spriteId];
            sPassGfx_frontier_pass->symbolSprites[i]->oam.priority = 2;
            StartSpriteAnim(sPassGfx_frontier_pass->symbolSprites[i], i);
        }
    }
}

static void FreeCursorAndSymbolSprites_frontier_pass(void)
{
    u8 i = 0;

    DestroySprite(sPassGfx_frontier_pass->cursorSprite);
    sPassGfx_frontier_pass->cursorSprite = NULL;
    for (i = 0; i < NUM_FRONTIER_FACILITIES; i++)
    {
        if (sPassGfx_frontier_pass->symbolSprites[i] != NULL)
        {
            DestroySprite(sPassGfx_frontier_pass->symbolSprites[i]);
            sPassGfx_frontier_pass->symbolSprites[i] = NULL;
        }
    }
    FreeAllSpritePalettes();
    FreeSpriteTilesByTag(TAG_MEDAL_SILVER_frontier_pass);
    FreeSpriteTilesByTag(TAG_CURSOR_frontier_pass);
}

