static void ShowFrontierMap_frontier_pass(void (*callback)(void))
{
    if (sMapData_frontier_pass != NULL)
        SetMainCallback2(callback); // This line doesn't make sense at all, since it gets overwritten later anyway.

    sMapData_frontier_pass = AllocZeroed(sizeof(*sMapData_frontier_pass));
    sMapData_frontier_pass->callback = callback;
    ResetTasks();
    CreateTask(Task_HandleFrontierMap_frontier_pass, 0);
    SetMainCallback2(CB2_FrontierPass_frontier_pass);
}

static void FreeFrontierMap_frontier_pass(void)
{
    ResetTasks();
    SetMainCallback2(sMapData_frontier_pass->callback);
    memset(sMapData_frontier_pass, 0, sizeof(*sMapData_frontier_pass)); // Pointless memory clear.
    FREE_AND_SET_NULL(sMapData_frontier_pass);
}

static bool32 InitFrontierMap_frontier_pass(void)
{
    switch (sPassData_frontier_pass->state)
    {
    case 0:
        SetVBlankCallback(NULL);
        ScanlineEffect_Stop();
        SetVBlankHBlankCallbacksToNull();
        break;
    case 1:
        ResetGpuRegsAndBgs_frontier_pass();
        break;
    case 2:
        ResetSpriteData();
        FreeAllSpritePalettes();
        ResetPaletteFade();
        ResetTempTileDataBuffers();
        break;
    case 3:
        ResetBgsAndClearDma3BusyFlags(0);
        InitBgsFromTemplates(0, sMapBgTemplates_frontier_pass, ARRAY_COUNT(sMapBgTemplates_frontier_pass));
        SetBgTilemapBuffer(0, sMapData_frontier_pass->tilemapBuff0);
        SetBgTilemapBuffer(1, sMapData_frontier_pass->tilemapBuff1);
        SetBgTilemapBuffer(2, sMapData_frontier_pass->tilemapBuff2);
        FillBgTilemapBufferRect_Palette0(0, 0, 0, 0, DISPLAY_TILE_WIDTH, DISPLAY_TILE_HEIGHT);
        FillBgTilemapBufferRect_Palette0(1, 0, 0, 0, DISPLAY_TILE_WIDTH, DISPLAY_TILE_HEIGHT);
        FillBgTilemapBufferRect_Palette0(2, 0, 0, 0, DISPLAY_TILE_WIDTH, DISPLAY_TILE_HEIGHT);
        CopyBgTilemapBufferToVram(0);
        CopyBgTilemapBufferToVram(1);
        CopyBgTilemapBufferToVram(2);
        break;
    case 4:
        InitWindows(sMapWindowTemplates_frontier_pass);
        DeactivateAllTextPrinters();
        PrintOnFrontierMap_frontier_pass();
        DecompressAndCopyTileDataToVram(1, sMapScreen_Gfx_frontier_pass, 0, 0, 0);
        break;
    case 5:
        if (FreeTempTileDataBuffersIfPossible())
            return FALSE;
        LoadPalette(gFrontierPassBg_Pal, BG_PLTT_ID(0), NUM_BG_PAL_SLOTS_frontier_pass * PLTT_SIZE_4BPP);
        LoadPalette(GetTextWindowPalette(0), BG_PLTT_ID(15), PLTT_SIZE_4BPP);
        CopyToBgTilemapBuffer(2, sMapScreen_Tilemap_frontier_pass, 0, 0);
        CopyBgTilemapBufferToVram(2);
        break;
    case 6:
        SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_OBJ_ON | DISPCNT_OBJ_1D_MAP);
        ShowBg(0);
        ShowBg(1);
        ShowBg(2);
        InitFrontierMapSprites_frontier_pass();
        SetVBlankCallback(VBlankCB_FrontierPass_frontier_pass);
        BlendPalettes(PALETTES_ALL, 16, RGB_WHITE);
        BeginNormalPaletteFade(PALETTES_ALL, 0, 16, 0, RGB_WHITE);
        break;
    case 7:
        if (UpdatePaletteFade())
            return FALSE;
        sPassData_frontier_pass->state = 0;
        return TRUE;
    }

    sPassData_frontier_pass->state++;
    return FALSE;
}

static bool32 ExitFrontierMap_frontier_pass(void)
{
    switch (sPassData_frontier_pass->state)
    {
    case 0:
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_WHITE);
        break;
    case 1:
        if (UpdatePaletteFade())
            return FALSE;
        SetGpuReg(REG_OFFSET_DISPCNT, 0);
        HideBg(0);
        HideBg(1);
        HideBg(2);
        break;
    case 2:
        SetVBlankCallback(NULL);
        ScanlineEffect_Stop();
        SetVBlankHBlankCallbacksToNull();
        break;
    case 3:
        if (sMapData_frontier_pass->cursorSprite != NULL)
        {
            DestroySprite(sMapData_frontier_pass->cursorSprite);
            FreeSpriteTilesByTag(TAG_CURSOR_frontier_pass);
        }
        if (sMapData_frontier_pass->mapIndicatorSprite != NULL)
        {
            DestroySprite(sMapData_frontier_pass->mapIndicatorSprite);
            FreeSpriteTilesByTag(TAG_MAP_INDICATOR_frontier_pass);
        }
        if (sMapData_frontier_pass->playerHeadSprite != NULL)
        {
            DestroySprite(sMapData_frontier_pass->playerHeadSprite);
            FreeSpriteTilesByTag(TAG_HEAD_MALE_frontier_pass);
        }
        FreeAllWindowBuffers();
        break;
    case 4:
        ResetGpuRegsAndBgs_frontier_pass();
        ResetSpriteData();
        FreeAllSpritePalettes();
        break;
    case 5:
        UnsetBgTilemapBuffer(0);
        UnsetBgTilemapBuffer(1);
        UnsetBgTilemapBuffer(2);
        sPassData_frontier_pass->state = 0;
        return TRUE;
    }

    sPassData_frontier_pass->state++;
    return FALSE;
}

#define tState_frontier_pass     data[0]
#define tMoveSteps_frontier_pass data[1]

static void Task_HandleFrontierMap_frontier_pass(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    switch (tState_frontier_pass)
    {
    case 0:
        if (InitFrontierMap_frontier_pass())
            break;
        return;
    case 1:
        if (JOY_NEW(B_BUTTON))
        {
            PlaySE(SE_PC_OFF);
            tState_frontier_pass = 4;
        }
        else if (JOY_NEW(DPAD_DOWN))
        {
            if (sMapData_frontier_pass->cursorPos >= NUM_FRONTIER_FACILITIES - 1)
                HandleFrontierMapCursorMove_frontier_pass(0);
            else
                tState_frontier_pass = 2;
        }
        else if (JOY_NEW(DPAD_UP))
        {
            if (sMapData_frontier_pass->cursorPos == 0)
                HandleFrontierMapCursorMove_frontier_pass(1);
            else
                tState_frontier_pass = 3;
        }
        return;
    case 2:
        if (tMoveSteps_frontier_pass > 3)
        {
            HandleFrontierMapCursorMove_frontier_pass(0);
            tMoveSteps_frontier_pass = 0;
            tState_frontier_pass = 1;
        }
        else
        {
            sMapData_frontier_pass->cursorSprite->y += 4;
            tMoveSteps_frontier_pass++;
        }
        return;
    case 3:
        if (tMoveSteps_frontier_pass > 3)
        {
            HandleFrontierMapCursorMove_frontier_pass(1);
            tMoveSteps_frontier_pass = 0;
            tState_frontier_pass = 1;
        }
        else
        {
            sMapData_frontier_pass->cursorSprite->y -= 4;
            tMoveSteps_frontier_pass++;
        }
        return;
    case 4:
        if (ExitFrontierMap_frontier_pass())
            break;
        return;
    case 5:
        DestroyTask(taskId);
        FreeFrontierMap_frontier_pass();
        return;
    }

    tState_frontier_pass++;
}

static u8 MapNumToFrontierFacilityId(u16 mapNum) // id + 1, zero means not a frontier map number
{
    // In Battle Tower
    if ((mapNum >= MAP_NUM(BATTLE_FRONTIER_BATTLE_TOWER_LOBBY) && mapNum <= MAP_NUM(BATTLE_FRONTIER_BATTLE_TOWER_BATTLE_ROOM))
     || (mapNum >= MAP_NUM(BATTLE_FRONTIER_BATTLE_TOWER_MULTI_PARTNER_ROOM) && mapNum <= MAP_NUM(BATTLE_FRONTIER_BATTLE_TOWER_MULTI_BATTLE_ROOM)))
        return FRONTIER_FACILITY_TOWER + 1;

    // In Battle Dome
    else if (mapNum == MAP_NUM(BATTLE_FRONTIER_BATTLE_DOME_LOBBY)
             || mapNum == MAP_NUM(BATTLE_FRONTIER_BATTLE_DOME_CORRIDOR)
             || mapNum == MAP_NUM(BATTLE_FRONTIER_BATTLE_DOME_PRE_BATTLE_ROOM)
             || mapNum == MAP_NUM(BATTLE_FRONTIER_BATTLE_DOME_BATTLE_ROOM))
        return FRONTIER_FACILITY_DOME + 1;

    // In Battle Palace
    else if (mapNum == MAP_NUM(BATTLE_FRONTIER_BATTLE_PALACE_LOBBY)
        || mapNum == MAP_NUM(BATTLE_FRONTIER_BATTLE_PALACE_CORRIDOR)
        || mapNum == MAP_NUM(BATTLE_FRONTIER_BATTLE_PALACE_BATTLE_ROOM))
        return FRONTIER_FACILITY_PALACE + 1;

    // In Battle Arena
    else if (mapNum == MAP_NUM(BATTLE_FRONTIER_BATTLE_ARENA_LOBBY)
        || mapNum == MAP_NUM(BATTLE_FRONTIER_BATTLE_ARENA_CORRIDOR)
        || mapNum == MAP_NUM(BATTLE_FRONTIER_BATTLE_ARENA_BATTLE_ROOM))
        return FRONTIER_FACILITY_ARENA + 1;

    // In Battle Factory
    else if (mapNum == MAP_NUM(BATTLE_FRONTIER_BATTLE_FACTORY_LOBBY)
        || mapNum == MAP_NUM(BATTLE_FRONTIER_BATTLE_FACTORY_PRE_BATTLE_ROOM)
        || mapNum == MAP_NUM(BATTLE_FRONTIER_BATTLE_FACTORY_BATTLE_ROOM))
        return FRONTIER_FACILITY_FACTORY + 1;

    // In Battle Pike
    else if (mapNum == MAP_NUM(BATTLE_FRONTIER_BATTLE_PIKE_LOBBY)
             || mapNum == MAP_NUM(BATTLE_FRONTIER_BATTLE_PIKE_CORRIDOR)
             || mapNum == MAP_NUM(BATTLE_FRONTIER_BATTLE_PIKE_THREE_PATH_ROOM)
             || mapNum == MAP_NUM(BATTLE_FRONTIER_BATTLE_PIKE_ROOM_NORMAL)
             || mapNum == MAP_NUM(BATTLE_FRONTIER_BATTLE_PIKE_ROOM_FINAL)
             || mapNum == MAP_NUM(BATTLE_FRONTIER_BATTLE_PIKE_ROOM_WILD_MONS))
        return FRONTIER_FACILITY_PIKE + 1;

    // In Battle Pyramid
    else if (mapNum == MAP_NUM(BATTLE_FRONTIER_BATTLE_PYRAMID_LOBBY)
        || mapNum == MAP_NUM(BATTLE_FRONTIER_BATTLE_PYRAMID_FLOOR)
        || mapNum == MAP_NUM(BATTLE_FRONTIER_BATTLE_PYRAMID_TOP))
        return FRONTIER_FACILITY_PYRAMID + 1;

    else
        return 0;
}

static void InitFrontierMapSprites_frontier_pass(void)
{
    struct SpriteTemplate sprite;
    u8 spriteId;
    u8 id;
    s16 x = 0, y;

    FreeAllSpritePalettes();
    LoadSpritePalettes(sSpritePalettes_frontier_pass);

    LoadCompressedSpriteSheet(&sCursorSpriteSheets_frontier_pass[0]);
    spriteId = CreateSprite(&sSpriteTemplates_Cursors_frontier_pass[0], 155, (sMapData_frontier_pass->cursorPos * 16) + 8, 2);
    sMapData_frontier_pass->cursorSprite = &gSprites[spriteId];
    sMapData_frontier_pass->cursorSprite->oam.priority = 0;
    sMapData_frontier_pass->cursorSprite->hFlip = TRUE;
    StartSpriteAnim(sMapData_frontier_pass->cursorSprite, 1);

    LoadCompressedSpriteSheet(&sCursorSpriteSheets_frontier_pass[1]);
    spriteId = CreateSprite(&sSpriteTemplates_Cursors_frontier_pass[1], sMapLandmarks[sMapData_frontier_pass->cursorPos].x, sMapLandmarks[sMapData_frontier_pass->cursorPos].y, 1);
    sMapData_frontier_pass->mapIndicatorSprite = &gSprites[spriteId];
    sMapData_frontier_pass->mapIndicatorSprite->oam.priority = 0;
    StartSpriteAnim(sMapData_frontier_pass->mapIndicatorSprite, sMapLandmarks[sMapData_frontier_pass->cursorPos].animNum);

    // Create player indicator head sprite only if it's in vicinity of battle frontier.
    id = GetCurrentRegionMapSectionId();
    if (id == MAPSEC_BATTLE_FRONTIER || id == MAPSEC_ARTISAN_CAVE)
    {
        s8 mapNum = gSaveBlock1Ptr->location.mapNum;

        if (mapNum == MAP_NUM(BATTLE_FRONTIER_OUTSIDE_WEST)
            || (mapNum == MAP_NUM(BATTLE_FRONTIER_OUTSIDE_EAST) && (x = 55)))
        {
            x += gSaveBlock1Ptr->pos.x;
            y = gSaveBlock1Ptr->pos.y;

            x /= 8;
            y /= 8;

            id = 0;
        }
        else
        {
            id = MapNumToFrontierFacilityId(mapNum);
            if (id != 0)
            {
                x = sMapLandmarks[id - 1].x;
                y = sMapLandmarks[id - 1].y;
            }
            else
            {
                // Handle Artisan Cave.
                if (gSaveBlock1Ptr->escapeWarp.mapNum == MAP_NUM(BATTLE_FRONTIER_OUTSIDE_EAST))
                    x = gSaveBlock1Ptr->escapeWarp.x + 55;
                else
                    x = gSaveBlock1Ptr->escapeWarp.x;

                y = gSaveBlock1Ptr->escapeWarp.y;

                x /= 8;
                y /= 8;
            }
        }

        LoadCompressedSpriteSheet(sHeadsSpriteSheet_frontier_pass);
        sprite = sSpriteTemplate_PlayerHead_frontier_pass;
        sprite.paletteTag = gSaveBlock2Ptr->playerGender + TAG_HEAD_MALE_frontier_pass; // TAG_HEAD_FEMALE_frontier_pass if gender is FEMALE
        if (id != 0)
        {
            spriteId = CreateSprite(&sprite, x, y, 0);
        }
        else
        {
            x *= 8;
            y *= 8;
            spriteId = CreateSprite(&sprite, x + 20, y + 36, 0);
        }

        sMapData_frontier_pass->playerHeadSprite = &gSprites[spriteId];
        sMapData_frontier_pass->playerHeadSprite->oam.priority = 0;
        if (gSaveBlock2Ptr->playerGender != MALE)
            StartSpriteAnim(sMapData_frontier_pass->playerHeadSprite, 1);
    }
}

static void PrintOnFrontierMap_frontier_pass(void)
{
    u8 i;

    for (i = 0; i < MAP_WINDOW_COUNT_frontier_pass; i++)
    {
        PutWindowTilemap(i);
        FillWindowPixelBuffer(i, PIXEL_FILL(0));
    }

    for (i = 0; i < NUM_FRONTIER_FACILITIES; i++)
    {
        if (i == sMapData_frontier_pass->cursorPos)
            AddTextPrinterParameterized3(MAP_WINDOW_NAME_frontier_pass, FONT_NARROW, 4, (i * 16) + 1, sTextColors_frontier_pass[2], 0, sMapLandmarks[i].name);
        else
            AddTextPrinterParameterized3(MAP_WINDOW_NAME_frontier_pass, FONT_NARROW, 4, (i * 16) + 1, sTextColors_frontier_pass[1], 0, sMapLandmarks[i].name);
    }

    AddTextPrinterParameterized3(MAP_WINDOW_DESCRIPTION_frontier_pass, FONT_NORMAL, 4, 0, sTextColors_frontier_pass[0], 0, sMapLandmarks[sMapData_frontier_pass->cursorPos].description);

    for (i = 0; i < MAP_WINDOW_COUNT_frontier_pass; i++)
        CopyWindowToVram(i, COPYWIN_FULL);

    CopyBgTilemapBufferToVram(0);
}

static void HandleFrontierMapCursorMove_frontier_pass(u8 direction)
{
    u8 oldCursorPos, i;

    if (direction)
    {
        oldCursorPos = sMapData_frontier_pass->cursorPos;
        sMapData_frontier_pass->cursorPos = (oldCursorPos + 6) % NUM_FRONTIER_FACILITIES;
    }
    else
    {
        oldCursorPos = sMapData_frontier_pass->cursorPos;
        sMapData_frontier_pass->cursorPos = (oldCursorPos + 1) % NUM_FRONTIER_FACILITIES;
    }

    AddTextPrinterParameterized3(MAP_WINDOW_NAME_frontier_pass, FONT_NARROW, 4, (oldCursorPos * 16) + 1, sTextColors_frontier_pass[1], 0, sMapLandmarks[oldCursorPos].name);
    AddTextPrinterParameterized3(MAP_WINDOW_NAME_frontier_pass, FONT_NARROW, 4, (sMapData_frontier_pass->cursorPos * 16) + 1, sTextColors_frontier_pass[2], 0, sMapLandmarks[sMapData_frontier_pass->cursorPos].name);

    sMapData_frontier_pass->cursorSprite->y = (sMapData_frontier_pass->cursorPos * 16) + 8;

    StartSpriteAnim(sMapData_frontier_pass->mapIndicatorSprite, sMapLandmarks[sMapData_frontier_pass->cursorPos].animNum);
    sMapData_frontier_pass->mapIndicatorSprite->x = sMapLandmarks[sMapData_frontier_pass->cursorPos].x;
    sMapData_frontier_pass->mapIndicatorSprite->y = sMapLandmarks[sMapData_frontier_pass->cursorPos].y;
    FillWindowPixelBuffer(MAP_WINDOW_DESCRIPTION_frontier_pass, PIXEL_FILL(0));
    AddTextPrinterParameterized3(MAP_WINDOW_DESCRIPTION_frontier_pass, FONT_NORMAL, 4, 0, sTextColors_frontier_pass[0], 0, sMapLandmarks[sMapData_frontier_pass->cursorPos].description);

    for (i = 0; i < MAP_WINDOW_COUNT_frontier_pass; i++)
        CopyWindowToVram(i, COPYWIN_FULL);

    CopyBgTilemapBufferToVram(0);
    PlaySE(SE_DEX_SCROLL);
}
