// Contents of gpu_regs.c
#include "global.h"
#include "gpu_regs.h"

#define GPU_REG_BUF_SIZE_gpu_regs 0x60

#define GPU_REG_BUF_gpu_regs(offset) (*(u16 *)(&sGpuRegBuffer_gpu_regs[offset]))
#define GPU_REG_gpu_regs(offset) (*(vu16 *)(REG_BASE + offset))

#define EMPTY_SLOT_gpu_regs 0xFF

static u8  sGpuRegBuffer_gpu_regs[GPU_REG_BUF_SIZE_gpu_regs];
static u8  sGpuRegWaitingList_gpu_regs[GPU_REG_BUF_SIZE_gpu_regs];
static volatile bool8  sGpuRegBufferLocked_gpu_regs;
static volatile bool8  sShouldSyncRegIE_gpu_regs;
static vu16  sRegIE_gpu_regs;

static void CopyBufferedValueToGpuReg_gpu_regs(u8 regOffset);
static void SyncRegIE_gpu_regs(void);
static void UpdateRegDispstatIntrBits_gpu_regs(u16 regIE);

void InitGpuRegManager(void)
{
    s32 i;

    for (i = 0; i < GPU_REG_BUF_SIZE_gpu_regs; i++)
    {
        sGpuRegBuffer_gpu_regs[i] = 0;
        sGpuRegWaitingList_gpu_regs[i] = EMPTY_SLOT_gpu_regs;
    }

    sGpuRegBufferLocked_gpu_regs = FALSE;
    sShouldSyncRegIE_gpu_regs = FALSE;
    sRegIE_gpu_regs = 0;
}

static void CopyBufferedValueToGpuReg_gpu_regs(u8 regOffset)
{
    if (regOffset == REG_OFFSET_DISPSTAT)
    {
        REG_DISPSTAT &= ~(DISPSTAT_HBLANK_INTR | DISPSTAT_VBLANK_INTR);
        REG_DISPSTAT |= GPU_REG_BUF_gpu_regs(REG_OFFSET_DISPSTAT);
    }
    else
    {
        GPU_REG_gpu_regs(regOffset) = GPU_REG_BUF_gpu_regs(regOffset);
    }
}

void CopyBufferedValuesToGpuRegs(void)
{
    if (!sGpuRegBufferLocked_gpu_regs)
    {
        s32 i;

        for (i = 0; i < GPU_REG_BUF_SIZE_gpu_regs; i++)
        {
            u8 regOffset = sGpuRegWaitingList_gpu_regs[i];
            if (regOffset == EMPTY_SLOT_gpu_regs)
                return;
            CopyBufferedValueToGpuReg_gpu_regs(regOffset);
            sGpuRegWaitingList_gpu_regs[i] = EMPTY_SLOT_gpu_regs;
        }
    }
}

void SetGpuReg(u8 regOffset, u16 value)
{
    if (regOffset < GPU_REG_BUF_SIZE_gpu_regs)
    {
        u16 vcount;

        GPU_REG_BUF_gpu_regs(regOffset) = value;
        vcount = REG_VCOUNT & 0xFF;

        if ((vcount >= 161 && vcount <= 225) || (REG_DISPCNT & DISPCNT_FORCED_BLANK))
        {
            CopyBufferedValueToGpuReg_gpu_regs(regOffset);
        }
        else
        {
            s32 i;

            sGpuRegBufferLocked_gpu_regs = TRUE;

            for (i = 0; i < GPU_REG_BUF_SIZE_gpu_regs && sGpuRegWaitingList_gpu_regs[i] != EMPTY_SLOT_gpu_regs; i++)
            {
                if (sGpuRegWaitingList_gpu_regs[i] == regOffset)
                {
                    sGpuRegBufferLocked_gpu_regs = FALSE;
                    return;
                }
            }

            sGpuRegWaitingList_gpu_regs[i] = regOffset;
            sGpuRegBufferLocked_gpu_regs = FALSE;
        }
    }
}

void SetGpuReg_ForcedBlank(u8 regOffset, u16 value)
{
    if (regOffset < GPU_REG_BUF_SIZE_gpu_regs)
    {
        GPU_REG_BUF_gpu_regs(regOffset) = value;

        if (REG_DISPCNT & DISPCNT_FORCED_BLANK)
        {
            CopyBufferedValueToGpuReg_gpu_regs(regOffset);
        }
        else
        {
            s32 i;

            sGpuRegBufferLocked_gpu_regs = TRUE;

            for (i = 0; i < GPU_REG_BUF_SIZE_gpu_regs && sGpuRegWaitingList_gpu_regs[i] != EMPTY_SLOT_gpu_regs; i++)
            {
                if (sGpuRegWaitingList_gpu_regs[i] == regOffset)
                {
                    sGpuRegBufferLocked_gpu_regs = FALSE;
                    return;
                }
            }

            sGpuRegWaitingList_gpu_regs[i] = regOffset;
            sGpuRegBufferLocked_gpu_regs = FALSE;
        }
    }
}

u16 GetGpuReg(u8 regOffset)
{
    if (regOffset == REG_OFFSET_DISPSTAT)
        return REG_DISPSTAT;

    if (regOffset == REG_OFFSET_VCOUNT)
        return REG_VCOUNT;

    return GPU_REG_BUF_gpu_regs(regOffset);
}

void SetGpuRegBits(u8 regOffset, u16 mask)
{
    u16 regValue = GPU_REG_BUF_gpu_regs(regOffset);
    SetGpuReg(regOffset, regValue | mask);
}

void ClearGpuRegBits(u8 regOffset, u16 mask)
{
    u16 regValue = GPU_REG_BUF_gpu_regs(regOffset);
    SetGpuReg(regOffset, regValue & ~mask);
}

static void SyncRegIE_gpu_regs(void)
{
    if (sShouldSyncRegIE_gpu_regs)
    {
        u16 temp = REG_IME;
        REG_IME = 0;
        REG_IE = sRegIE_gpu_regs;
        REG_IME = temp;
        sShouldSyncRegIE_gpu_regs = FALSE;
    }
}

void EnableInterrupts(u16 mask)
{
    sRegIE_gpu_regs |= mask;
    sShouldSyncRegIE_gpu_regs = TRUE;
    SyncRegIE_gpu_regs();
    UpdateRegDispstatIntrBits_gpu_regs(sRegIE_gpu_regs);
}

void DisableInterrupts(u16 mask)
{
    sRegIE_gpu_regs &= ~mask;
    sShouldSyncRegIE_gpu_regs = TRUE;
    SyncRegIE_gpu_regs();
    UpdateRegDispstatIntrBits_gpu_regs(sRegIE_gpu_regs);
}

static void UpdateRegDispstatIntrBits_gpu_regs(u16 regIE)
{
    u16 oldValue = GetGpuReg(REG_OFFSET_DISPSTAT) & (DISPSTAT_HBLANK_INTR | DISPSTAT_VBLANK_INTR);
    u16 newValue = 0;

    if (regIE & INTR_FLAG_VBLANK)
        newValue |= DISPSTAT_VBLANK_INTR;

    if (regIE & INTR_FLAG_HBLANK)
        newValue |= DISPSTAT_HBLANK_INTR;

    if (oldValue != newValue)
        SetGpuReg(REG_OFFSET_DISPSTAT, newValue);
}
