void CB2_DoHallOfFameScreen(void)
{
    if (!InitHallOfFameScreen_hall_of_fame())
    {
        u8 taskId = CreateTask(Task_Hof_InitMonData_hall_of_fame, 0);
        gTasks[taskId].tDontSaveData_hall_of_fame = FALSE;
        sHofMonPtr_hall_of_fame = AllocZeroed(sizeof(*sHofMonPtr_hall_of_fame));
    }
}

void CB2_DoHallOfFameScreenDontSaveData(void)
{
    if (!InitHallOfFameScreen_hall_of_fame())
    {
        u8 taskId = CreateTask(Task_Hof_InitMonData_hall_of_fame, 0);
        gTasks[taskId].tDontSaveData_hall_of_fame = TRUE;
        sHofMonPtr_hall_of_fame = AllocZeroed(sizeof(*sHofMonPtr_hall_of_fame));
    }
}

static void Task_Hof_InitMonData_hall_of_fame(u8 taskId)
{
    u16 i, j;

    gTasks[taskId].tMonNumber_hall_of_fame = 0; // valid pokes

    for (i = 0; i < PARTY_SIZE; i++)
    {
        u8 nickname[POKEMON_NAME_LENGTH + 1];
        if (GetMonData(&gPlayerParty[i], MON_DATA_SPECIES))
        {
            sHofMonPtr_hall_of_fame->mon[i].species = GetMonData(&gPlayerParty[i], MON_DATA_SPECIES_OR_EGG);
            sHofMonPtr_hall_of_fame->mon[i].tid = GetMonData(&gPlayerParty[i], MON_DATA_OT_ID);
            sHofMonPtr_hall_of_fame->mon[i].isShiny = GetMonData(&gPlayerParty[i], MON_DATA_IS_SHINY);
            sHofMonPtr_hall_of_fame->mon[i].personality = GetMonData(&gPlayerParty[i], MON_DATA_PERSONALITY);
            sHofMonPtr_hall_of_fame->mon[i].lvl = GetMonData(&gPlayerParty[i], MON_DATA_LEVEL);
            GetMonData(&gPlayerParty[i], MON_DATA_NICKNAME, nickname);
            for (j = 0; j < POKEMON_NAME_LENGTH; j++)
                sHofMonPtr_hall_of_fame->mon[i].nickname[j] = nickname[j];
            gTasks[taskId].tMonNumber_hall_of_fame++;
        }
        else
        {
            sHofMonPtr_hall_of_fame->mon[i].species = SPECIES_NONE;
            sHofMonPtr_hall_of_fame->mon[i].tid = 0;
            sHofMonPtr_hall_of_fame->mon[i].isShiny = FALSE;
            sHofMonPtr_hall_of_fame->mon[i].personality = 0;
            sHofMonPtr_hall_of_fame->mon[i].lvl = 0;
            sHofMonPtr_hall_of_fame->mon[i].nickname[0] = EOS;
        }
    }

    sHofFadePalettes_hall_of_fame = 0;
    gTasks[taskId].tDisplayedMonId_hall_of_fame = 0;
    gTasks[taskId].tPlayerSpriteID_hall_of_fame = SPRITE_NONE;

    for (i = 0; i < PARTY_SIZE; i++)
    {
        gTasks[taskId].tMonSpriteId_hall_of_fame(i) = SPRITE_NONE;
    }

    if (gTasks[taskId].tDontSaveData_hall_of_fame)
        gTasks[taskId].func = Task_Hof_SetMonDisplayTask_hall_of_fame;
    else
        gTasks[taskId].func = Task_Hof_InitTeamSaveData_hall_of_fame;
}

static void Task_Hof_InitTeamSaveData_hall_of_fame(u8 taskId)
{
    u16 i;
    struct HallofFameTeam *lastSavedTeam = (struct HallofFameTeam *)(gDecompressionBuffer);

    if (!gHasHallOfFameRecords)
    {
        memset(gDecompressionBuffer, 0, SECTOR_SIZE * NUM_HOF_SECTORS);
    }
    else
    {
        if (LoadGameSave(SAVE_HALL_OF_FAME) != SAVE_STATUS_OK)
            memset(gDecompressionBuffer, 0, SECTOR_SIZE * NUM_HOF_SECTORS);
    }

    for (i = 0; i < HALL_OF_FAME_MAX_TEAMS_hall_of_fame; i++, lastSavedTeam++)
    {
        if (lastSavedTeam->mon[0].species == SPECIES_NONE)
            break;
    }
    if (i >= HALL_OF_FAME_MAX_TEAMS_hall_of_fame)
    {
        struct HallofFameTeam *afterTeam = (struct HallofFameTeam *)(gDecompressionBuffer);
        struct HallofFameTeam *beforeTeam = (struct HallofFameTeam *)(gDecompressionBuffer);
        afterTeam++;
        for (i = 0; i < HALL_OF_FAME_MAX_TEAMS_hall_of_fame - 1; i++, beforeTeam++, afterTeam++)
        {
            *beforeTeam = *afterTeam;
        }
        lastSavedTeam--;
    }
    *lastSavedTeam = *sHofMonPtr_hall_of_fame;

    DrawDialogueFrame(0, FALSE);
    AddTextPrinterParameterized2(0, FONT_NORMAL, gText_SavingDontTurnOffPower, 0, NULL, TEXT_COLOR_DARK_GRAY, TEXT_COLOR_WHITE, TEXT_COLOR_LIGHT_GRAY);
    CopyWindowToVram(0, COPYWIN_FULL);
    gTasks[taskId].func = Task_Hof_TrySaveData_hall_of_fame;
}

static void Task_Hof_TrySaveData_hall_of_fame(u8 taskId)
{
    gGameContinueCallback = CB2_DoHallOfFameScreenDontSaveData;
    if (TrySavingData(SAVE_HALL_OF_FAME) == SAVE_STATUS_ERROR && gDamagedSaveSectors != 0)
    {
        UnsetBgTilemapBuffer(1);
        UnsetBgTilemapBuffer(3);
        FreeAllWindowBuffers();

        TRY_FREE_AND_SET_NULL(sHofGfxPtr_hall_of_fame);
        TRY_FREE_AND_SET_NULL(sHofMonPtr_hall_of_fame);

        DestroyTask(taskId);
    }
    else
    {
        PlaySE(SE_SAVE);
        gTasks[taskId].func = Task_Hof_WaitToDisplayMon_hall_of_fame;
        gTasks[taskId].tFrameCount_hall_of_fame = 32;
    }
}

static void Task_Hof_WaitToDisplayMon_hall_of_fame(u8 taskId)
{
    if (gTasks[taskId].tFrameCount_hall_of_fame)
        gTasks[taskId].tFrameCount_hall_of_fame--;
    else
        gTasks[taskId].func = Task_Hof_SetMonDisplayTask_hall_of_fame;
}

static void Task_Hof_SetMonDisplayTask_hall_of_fame(u8 taskId)
{
    gTasks[taskId].func = Task_Hof_DisplayMon_hall_of_fame;
}

#define tDestinationX_hall_of_fame  data[1]
#define tDestinationY_hall_of_fame  data[2]
#define tSpecies_hall_of_fame       data[7]

static void Task_Hof_DisplayMon_hall_of_fame(u8 taskId)
{
    u8 spriteId;
    s16 startX, startY, destX, destY;

    u16 currMonId = gTasks[taskId].tDisplayedMonId_hall_of_fame;
    struct HallofFameMon* currMon = &sHofMonPtr_hall_of_fame->mon[currMonId];

    if (gTasks[taskId].tMonNumber_hall_of_fame > PARTY_SIZE / 2)
    {
        startX = sHallOfFame_MonFullTeamPositions_hall_of_fame[currMonId][0];
        startY = sHallOfFame_MonFullTeamPositions_hall_of_fame[currMonId][1];
        destX = sHallOfFame_MonFullTeamPositions_hall_of_fame[currMonId][2];
        destY = sHallOfFame_MonFullTeamPositions_hall_of_fame[currMonId][3];
    }
    else
    {
        startX = sHallOfFame_MonHalfTeamPositions_hall_of_fame[currMonId][0];
        startY = sHallOfFame_MonHalfTeamPositions_hall_of_fame[currMonId][1];
        destX = sHallOfFame_MonHalfTeamPositions_hall_of_fame[currMonId][2];
        destY = sHallOfFame_MonHalfTeamPositions_hall_of_fame[currMonId][3];
    }

    if (currMon->species == SPECIES_EGG)
        destY += 10;

    spriteId = CreateMonPicSprite_Affine(currMon->species, currMon->isShiny, currMon->personality, MON_PIC_AFFINE_FRONT, startX, startY, currMonId, TAG_NONE);
    gSprites[spriteId].tDestinationX_hall_of_fame = destX;
    gSprites[spriteId].tDestinationY_hall_of_fame = destY;
    gSprites[spriteId].data[0] = 0;
    gSprites[spriteId].tSpecies_hall_of_fame = currMon->species;
    gSprites[spriteId].callback = SpriteCB_GetOnScreenAndAnimate_hall_of_fame;
    gTasks[taskId].tMonSpriteId_hall_of_fame(currMonId) = spriteId;
    ClearDialogWindowAndFrame(0, TRUE);
    gTasks[taskId].func = Task_Hof_PrintMonInfoAfterAnimating_hall_of_fame;
}

static void Task_Hof_PrintMonInfoAfterAnimating_hall_of_fame(u8 taskId)
{
    u16 currMonId = gTasks[taskId].tDisplayedMonId_hall_of_fame;
    struct HallofFameMon* currMon = &sHofMonPtr_hall_of_fame->mon[currMonId];
    struct Sprite *monSprite = &gSprites[gTasks[taskId].tMonSpriteId_hall_of_fame(currMonId)];

    if (monSprite->callback == SpriteCallbackDummy)
    {
        monSprite->oam.affineMode = ST_OAM_AFFINE_OFF;
        HallOfFame_PrintMonInfo_hall_of_fame(currMon, 0, 14);
        gTasks[taskId].tFrameCount_hall_of_fame = 120;
        gTasks[taskId].func = Task_Hof_TryDisplayAnotherMon_hall_of_fame;
    }
}

static void Task_Hof_TryDisplayAnotherMon_hall_of_fame(u8 taskId)
{
    u16 currPokeID = gTasks[taskId].tDisplayedMonId_hall_of_fame;
    struct HallofFameMon* currMon = &sHofMonPtr_hall_of_fame->mon[currPokeID];

    if (gTasks[taskId].tFrameCount_hall_of_fame != 0)
    {
        gTasks[taskId].tFrameCount_hall_of_fame--;
    }
    else
    {
        sHofFadePalettes_hall_of_fame |= (0x10000 << gSprites[gTasks[taskId].tMonSpriteId_hall_of_fame(currPokeID)].oam.paletteNum);
        if (gTasks[taskId].tDisplayedMonId_hall_of_fame < PARTY_SIZE - 1 && currMon[1].species != SPECIES_NONE) // there is another Pokémon to display
        {
            gTasks[taskId].tDisplayedMonId_hall_of_fame++;
            BeginNormalPaletteFade(sHofFadePalettes_hall_of_fame, 0, 12, 12, RGB(16, 29, 24));
            gSprites[gTasks[taskId].tMonSpriteId_hall_of_fame(currPokeID)].oam.priority = 1;
            gTasks[taskId].func = Task_Hof_DisplayMon_hall_of_fame;
        }
        else
        {
            gTasks[taskId].func = Task_Hof_PaletteFadeAndPrintWelcomeText_hall_of_fame;
        }
    }
}

static void Task_Hof_PaletteFadeAndPrintWelcomeText_hall_of_fame(u8 taskId)
{
    u16 i;

    BeginNormalPaletteFade(PALETTES_OBJECTS, 0, 0, 0, RGB_BLACK);
    for (i = 0; i < PARTY_SIZE; i++)
    {
        if (gTasks[taskId].tMonSpriteId_hall_of_fame(i) != SPRITE_NONE)
            gSprites[gTasks[taskId].tMonSpriteId_hall_of_fame(i)].oam.priority = 0;
    }

    HallOfFame_PrintWelcomeText_hall_of_fame(0, 15);
    PlaySE(SE_APPLAUSE);
    gTasks[taskId].tFrameCount_hall_of_fame = 400;
    gTasks[taskId].func = Task_Hof_DoConfetti_hall_of_fame;
}

static void Task_Hof_DoConfetti_hall_of_fame(u8 taskId)
{
    if (gTasks[taskId].tFrameCount_hall_of_fame != 0)
    {
        gTasks[taskId].tFrameCount_hall_of_fame--;

        // Create new confetti every 4th frame for the first 290 frames
        // For the last 110 frames wait for the existing confetti to fall offscreen
        if ((gTasks[taskId].tFrameCount_hall_of_fame & 3) == 0 && gTasks[taskId].tFrameCount_hall_of_fame > 110)
            CreateHofConfettiSprite_hall_of_fame();
    }
    else
    {
        u16 i;
        for (i = 0; i < PARTY_SIZE; i++)
        {
            if (gTasks[taskId].tMonSpriteId_hall_of_fame(i) != SPRITE_NONE)
                gSprites[gTasks[taskId].tMonSpriteId_hall_of_fame(i)].oam.priority = 1;
        }
        BeginNormalPaletteFade(sHofFadePalettes_hall_of_fame, 0, 12, 12, RGB(16, 29, 24));
        FillWindowPixelBuffer(0, PIXEL_FILL(0));
        CopyWindowToVram(0, COPYWIN_FULL);
        gTasks[taskId].tFrameCount_hall_of_fame = 7;
        gTasks[taskId].func = Task_Hof_WaitToDisplayPlayer_hall_of_fame;
    }
}

static void Task_Hof_WaitToDisplayPlayer_hall_of_fame(u8 taskId)
{
    if (gTasks[taskId].tFrameCount_hall_of_fame >= 16)
    {
        gTasks[taskId].func = Task_Hof_DisplayPlayer_hall_of_fame;
    }
    else
    {
        gTasks[taskId].tFrameCount_hall_of_fame++;
        SetGpuReg(REG_OFFSET_BLDALPHA, gTasks[taskId].tFrameCount_hall_of_fame * 256);
    }
}

static void Task_Hof_DisplayPlayer_hall_of_fame(u8 taskId)
{
    SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_OBJ_ON | DISPCNT_OBJ_1D_MAP);
    ShowBg(0);
    ShowBg(1);
    ShowBg(3);
    gTasks[taskId].tPlayerSpriteID_hall_of_fame = CreateTrainerPicSprite(PlayerGenderToFrontTrainerPicId_Debug(gSaveBlock2Ptr->playerGender, TRUE), TRUE, 120, 72, 6, TAG_NONE);
    AddWindow(&sHof_WindowTemplate_hall_of_fame);
    LoadWindowGfx(1, gSaveBlock2Ptr->optionsWindowFrameType, 0x21D, BG_PLTT_ID(13));
    LoadPalette(GetTextWindowPalette(1), BG_PLTT_ID(14), PLTT_SIZE_4BPP);
    gTasks[taskId].tFrameCount_hall_of_fame = 120;
    gTasks[taskId].func = Task_Hof_WaitAndPrintPlayerInfo_hall_of_fame;
}

static void Task_Hof_WaitAndPrintPlayerInfo_hall_of_fame(u8 taskId)
{
    if (gTasks[taskId].tFrameCount_hall_of_fame != 0)
    {
        gTasks[taskId].tFrameCount_hall_of_fame--;
    }
    else if (gSprites[gTasks[taskId].tPlayerSpriteID_hall_of_fame].x != 192)
    {
        gSprites[gTasks[taskId].tPlayerSpriteID_hall_of_fame].x++;
    }
    else
    {
        FillBgTilemapBufferRect_Palette0(0, 0, 0, 0, 0x20, 0x20);
        HallOfFame_PrintPlayerInfo_hall_of_fame(1, 2);
        DrawDialogueFrame(0, FALSE);
        AddTextPrinterParameterized2(0, FONT_NORMAL, gText_LeagueChamp, 0, NULL, TEXT_COLOR_DARK_GRAY, TEXT_COLOR_WHITE, TEXT_COLOR_LIGHT_GRAY);
        CopyWindowToVram(0, COPYWIN_FULL);
        gTasks[taskId].func = Task_Hof_ExitOnKeyPressed_hall_of_fame;
    }
}

static void Task_Hof_ExitOnKeyPressed_hall_of_fame(u8 taskId)
{
    if (JOY_NEW(A_BUTTON))
    {
        FadeOutBGM(4);
        gTasks[taskId].func = Task_Hof_HandlePaletteOnExit_hall_of_fame;
    }
}

static void Task_Hof_HandlePaletteOnExit_hall_of_fame(u8 taskId)
{
    CpuCopy16(gPlttBufferFaded, gPlttBufferUnfaded, PLTT_SIZE);
    BeginNormalPaletteFade(PALETTES_ALL, 8, 0, 0x10, RGB_BLACK);
    gTasks[taskId].func = Task_Hof_HandleExit_hall_of_fame;
}

static void Task_Hof_HandleExit_hall_of_fame(u8 taskId)
{
    if (!gPaletteFade.active)
    {
        s32 i;

        for (i = 0; i < PARTY_SIZE; i++)
        {
            u8 spriteId = gTasks[taskId].tMonSpriteId_hall_of_fame(i);
            if (spriteId != SPRITE_NONE)
            {
                FreeOamMatrix(gSprites[spriteId].oam.matrixNum);
                FreeAndDestroyMonPicSprite(spriteId);
            }
        }

        FreeAndDestroyTrainerPicSprite(gTasks[taskId].tPlayerSpriteID_hall_of_fame);
        HideBg(0);
        HideBg(1);
        HideBg(3);
        FreeAllWindowBuffers();
        UnsetBgTilemapBuffer(1);
        UnsetBgTilemapBuffer(3);
        ResetBgsAndClearDma3BusyFlags(0);
        DestroyTask(taskId);

        TRY_FREE_AND_SET_NULL(sHofGfxPtr_hall_of_fame);
        TRY_FREE_AND_SET_NULL(sHofMonPtr_hall_of_fame);

        StartCredits_hall_of_fame();
    }
}

static void StartCredits_hall_of_fame(void)
{
    SetMainCallback2(CB2_StartCreditsSequence);
}

#undef tDontSaveData_hall_of_fame
#undef tDisplayedPoke
#undef tMonNumber_hall_of_fame
#undef tFrameCount_hall_of_fame
#undef tPlayerSpriteID_hall_of_fame
#undef tMonSpriteId_hall_of_fame

#define tCurrTeamNo_hall_of_fame     data[0]
#define tCurrPageNo_hall_of_fame     data[1]
#define tCurrMonId_hall_of_fame      data[2]
#define tMonNo_hall_of_fame          data[4]
#define tMonSpriteId_hall_of_fame(i) data[i + 5]

void CB2_DoHallOfFamePC(void)
{
    switch (gMain.state)
    {
    case 0:
    default:
        SetVBlankCallback(NULL);
        ClearVramOamPltt_LoadHofPal_hall_of_fame();
        sHofGfxPtr_hall_of_fame = AllocZeroed(sizeof(*sHofGfxPtr_hall_of_fame));
        gMain.state = 1;
        break;
    case 1:
        LoadHofGfx_hall_of_fame();
        gMain.state++;
        break;
    case 2:
        SetGpuReg(REG_OFFSET_BLDCNT, 0);
        SetGpuReg(REG_OFFSET_BLDALPHA, 0);
        SetGpuReg(REG_OFFSET_BLDY, 0);
        InitHofBgs_hall_of_fame();
        gMain.state++;
        break;
    case 3:
        if (!LoadHofBgs_hall_of_fame())
        {
            struct HallofFameTeam *fameTeam = (struct HallofFameTeam *)(gDecompressionBuffer);
            fameTeam->mon[0] = sDummyFameMon_hall_of_fame;
            ComputerScreenOpenEffect(0, 0, 0);
            SetVBlankCallback(VBlankCB_HallOfFame_hall_of_fame);
            gMain.state++;
        }
        break;
    case 4:
        RunTasks();
        AnimateSprites();
        BuildOamBuffer();
        UpdatePaletteFade();
        if (!IsComputerScreenOpenEffectActive())
            gMain.state++;
        break;
    case 5:
        {
            u8 taskId, i;

            SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_TGT1_BG1 | BLDCNT_EFFECT_BLEND | BLDCNT_TGT2_ALL);
            SetGpuReg(REG_OFFSET_BLDALPHA, BLDALPHA_BLEND(16, 7));
            SetGpuReg(REG_OFFSET_BLDY, 0);
            taskId = CreateTask(Task_HofPC_CopySaveData_hall_of_fame, 0);

            for (i = 0; i < PARTY_SIZE; i++)
            {
                gTasks[taskId].tMonSpriteId_hall_of_fame(i) = SPRITE_NONE;
            }

            sHofMonPtr_hall_of_fame = AllocZeroed(SECTOR_SIZE * NUM_HOF_SECTORS);
            SetMainCallback2(CB2_HallOfFame_hall_of_fame);
        }
        break;
    }
}

static void Task_HofPC_CopySaveData_hall_of_fame(u8 taskId)
{
    HofPCTopBar_AddWindow(0, 30, 0, 12, 0x226);
    if (LoadGameSave(SAVE_HALL_OF_FAME) != SAVE_STATUS_OK)
    {
        gTasks[taskId].func = Task_HofPC_PrintDataIsCorrupted_hall_of_fame;
    }
    else
    {
        u16 i;
        struct HallofFameTeam *savedTeams;

        CpuCopy16(gDecompressionBuffer, sHofMonPtr_hall_of_fame, SECTOR_SIZE * NUM_HOF_SECTORS);
        savedTeams = sHofMonPtr_hall_of_fame;
        for (i = 0; i < HALL_OF_FAME_MAX_TEAMS_hall_of_fame; i++, savedTeams++)
        {
            if (savedTeams->mon[0].species == SPECIES_NONE)
                break;
        }

        if (i < HALL_OF_FAME_MAX_TEAMS_hall_of_fame)
            gTasks[taskId].tCurrTeamNo_hall_of_fame = i - 1;
        else
            gTasks[taskId].tCurrTeamNo_hall_of_fame = HALL_OF_FAME_MAX_TEAMS_hall_of_fame - 1;

        gTasks[taskId].tCurrPageNo_hall_of_fame = GetGameStat(GAME_STAT_ENTERED_HOF);

        gTasks[taskId].func = Task_HofPC_DrawSpritesPrintText_hall_of_fame;
    }
}

static void Task_HofPC_DrawSpritesPrintText_hall_of_fame(u8 taskId)
{
    struct HallofFameTeam *savedTeams = sHofMonPtr_hall_of_fame;
    struct HallofFameMon* currMon;
    u16 i;

    for (i = 0; i < gTasks[taskId].tCurrTeamNo_hall_of_fame; i++)
        savedTeams++;

    currMon = &savedTeams->mon[0];
    sHofFadePalettes_hall_of_fame = 0;
    gTasks[taskId].tCurrMonId_hall_of_fame = 0;
    gTasks[taskId].tMonNo_hall_of_fame = 0;

    for (i = 0; i < PARTY_SIZE; i++, currMon++)
    {
        if (currMon->species != 0)
            gTasks[taskId].tMonNo_hall_of_fame++;
    }

    currMon = &savedTeams->mon[0];

    for (i = 0; i < PARTY_SIZE; i++, currMon++)
    {
        if (currMon->species != 0)
        {
            u16 spriteId;
            s16 posX, posY;

            if (gTasks[taskId].tMonNo_hall_of_fame > PARTY_SIZE / 2)
            {
                posX = sHallOfFame_MonFullTeamPositions_hall_of_fame[i][2];
                posY = sHallOfFame_MonFullTeamPositions_hall_of_fame[i][3];
            }
            else
            {
                posX = sHallOfFame_MonHalfTeamPositions_hall_of_fame[i][2];
                posY = sHallOfFame_MonHalfTeamPositions_hall_of_fame[i][3];
            }

            if (currMon->species == SPECIES_EGG)
                posY += 10;

            spriteId = CreateMonPicSprite(currMon->species, currMon->isShiny, currMon->personality, TRUE, posX, posY, i, TAG_NONE);
            gSprites[spriteId].oam.priority = 1;
            gTasks[taskId].tMonSpriteId_hall_of_fame(i) = spriteId;
        }
        else
        {
            gTasks[taskId].tMonSpriteId_hall_of_fame(i) = SPRITE_NONE;
        }
    }

    BlendPalettes(PALETTES_OBJECTS, 0xC, RGB(16, 29, 24));

    ConvertIntToDecimalStringN(gStringVar1, gTasks[taskId].tCurrPageNo_hall_of_fame, STR_CONV_MODE_RIGHT_ALIGN, 3);
    StringExpandPlaceholders(gStringVar4, gText_HOFNumber);

    if (gTasks[taskId].tCurrTeamNo_hall_of_fame <= 0)
        HofPCTopBar_PrintPair(gStringVar4, gText_PickCancel, FALSE, 0, TRUE);
    else
        HofPCTopBar_PrintPair(gStringVar4, gText_PickNextCancel, FALSE, 0, TRUE);

    gTasks[taskId].func = Task_HofPC_PrintMonInfo_hall_of_fame;
}

static void Task_HofPC_PrintMonInfo_hall_of_fame(u8 taskId)
{
    struct HallofFameTeam *savedTeams = sHofMonPtr_hall_of_fame;
    struct HallofFameMon* currMon;
    u16 i;
    u16 currMonID;

    for (i = 0; i < gTasks[taskId].tCurrTeamNo_hall_of_fame; i++)
        savedTeams++;

    for (i = 0; i < PARTY_SIZE; i++)
    {
        u16 spriteId = gTasks[taskId].tMonSpriteId_hall_of_fame(i);
        if (spriteId != SPRITE_NONE)
            gSprites[spriteId].oam.priority = 1;
    }

    currMonID = gTasks[taskId].tMonSpriteId_hall_of_fame(gTasks[taskId].tCurrMonId_hall_of_fame);
    gSprites[currMonID].oam.priority = 0;
    sHofFadePalettes_hall_of_fame = (0x10000 << gSprites[currMonID].oam.paletteNum) ^ PALETTES_OBJECTS;
    BlendPalettesUnfaded(sHofFadePalettes_hall_of_fame, 0xC, RGB(16, 29, 24));

    currMon = &savedTeams->mon[gTasks[taskId].tCurrMonId_hall_of_fame];
    if (currMon->species != SPECIES_EGG)
    {
        StopCryAndClearCrySongs();
        PlayCry_Normal(currMon->species, 0);
    }
    HallOfFame_PrintMonInfo_hall_of_fame(currMon, 0, 14);

    gTasks[taskId].func = Task_HofPC_HandleInput_hall_of_fame;
}

static void Task_HofPC_HandleInput_hall_of_fame(u8 taskId)
{
    u16 i;

    if (JOY_NEW(A_BUTTON))
    {
        if (gTasks[taskId].tCurrTeamNo_hall_of_fame != 0) // prepare another team to view
        {
            gTasks[taskId].tCurrTeamNo_hall_of_fame--;
            for (i = 0; i < PARTY_SIZE; i++)
            {
                u8 spriteId = gTasks[taskId].tMonSpriteId_hall_of_fame(i);
                if (spriteId != SPRITE_NONE)
                {
                    FreeAndDestroyMonPicSprite(spriteId);
                    gTasks[taskId].tMonSpriteId_hall_of_fame(i) = SPRITE_NONE;
                }
            }
            if (gTasks[taskId].tCurrPageNo_hall_of_fame != 0)
                gTasks[taskId].tCurrPageNo_hall_of_fame--;
            gTasks[taskId].func = Task_HofPC_DrawSpritesPrintText_hall_of_fame;
        }
        else // no more teams to view, turn off hall of fame PC
        {
            if (IsCryPlayingOrClearCrySongs())
            {
                StopCryAndClearCrySongs();
                m4aMPlayVolumeControl(&gMPlayInfo_BGM, TRACKS_ALL, 0x100);
            }
            gTasks[taskId].func = Task_HofPC_HandlePaletteOnExit_hall_of_fame;
        }
    }
    else if (JOY_NEW(B_BUTTON)) // turn off hall of fame PC
    {
        if (IsCryPlayingOrClearCrySongs())
        {
            StopCryAndClearCrySongs();
            m4aMPlayVolumeControl(&gMPlayInfo_BGM, TRACKS_ALL, 0x100);
        }
        gTasks[taskId].func = Task_HofPC_HandlePaletteOnExit_hall_of_fame;
    }
    else if (JOY_NEW(DPAD_UP) && gTasks[taskId].tCurrMonId_hall_of_fame != 0) // change mon -1
    {
        gTasks[taskId].tCurrMonId_hall_of_fame--;
        gTasks[taskId].func = Task_HofPC_PrintMonInfo_hall_of_fame;
    }
    else if (JOY_NEW(DPAD_DOWN) && gTasks[taskId].tCurrMonId_hall_of_fame < gTasks[taskId].tMonNo_hall_of_fame - 1) // change mon +1
    {
        gTasks[taskId].tCurrMonId_hall_of_fame++;
        gTasks[taskId].func = Task_HofPC_PrintMonInfo_hall_of_fame;
    }
}

static void Task_HofPC_HandlePaletteOnExit_hall_of_fame(u8 taskId)
{
    struct HallofFameTeam *fameTeam;

    CpuCopy16(gPlttBufferFaded, gPlttBufferUnfaded, PLTT_SIZE);
    fameTeam = (struct HallofFameTeam *)(gDecompressionBuffer);
    fameTeam->mon[0] = sDummyFameMon_hall_of_fame;
    ComputerScreenCloseEffect(0, 0, 0);
    gTasks[taskId].func = Task_HofPC_HandleExit_hall_of_fame;
}

static void Task_HofPC_HandleExit_hall_of_fame(u8 taskId)
{
    if (!IsComputerScreenCloseEffectActive())
    {
        u8 i;

        for (i = 0; i < PARTY_SIZE; i++)
        {
            u16 spriteId = gTasks[taskId].tMonSpriteId_hall_of_fame(i);
            if (spriteId != SPRITE_NONE)
            {
                FreeAndDestroyMonPicSprite(spriteId);
                gTasks[taskId].tMonSpriteId_hall_of_fame(i) = SPRITE_NONE;
            }
        }

        HideBg(0);
        HideBg(1);
        HideBg(3);
        HofPCTopBar_RemoveWindow();
        FreeAllWindowBuffers();
        UnsetBgTilemapBuffer(1);
        UnsetBgTilemapBuffer(3);
        ResetBgsAndClearDma3BusyFlags(0);
        DestroyTask(taskId);

        TRY_FREE_AND_SET_NULL(sHofGfxPtr_hall_of_fame);
        TRY_FREE_AND_SET_NULL(sHofMonPtr_hall_of_fame);

        ReturnFromHallOfFamePC();
    }
}

