{
    HofPCTopBar_Print(gText_AButtonExit, 8, TRUE);
    DrawDialogueFrame(0, FALSE);
    AddTextPrinterParameterized2(0, FONT_NORMAL, gText_HOFCorrupted, 0, NULL, TEXT_COLOR_DARK_GRAY, TEXT_COLOR_WHITE, TEXT_COLOR_LIGHT_GRAY);
    CopyWindowToVram(0, COPYWIN_FULL);
    gTasks[taskId].func = Task_HofPC_ExitOnButtonPress_hall_of_fame;
}

static void Task_HofPC_ExitOnButtonPress_hall_of_fame(u8 taskId)
{
    if (JOY_NEW(A_BUTTON))
        gTasks[taskId].func = Task_HofPC_HandlePaletteOnExit_hall_of_fame;
}

