static bool8 LoadHofBgs_hall_of_fame(void)
{
    switch (sHofGfxPtr_hall_of_fame->state)
    {
    case 0:
        DecompressAndCopyTileDataToVram(1, sHallOfFame_Gfx_hall_of_fame, 0, 0, 0);
        break;
    case 1:
        if (FreeTempTileDataBuffersIfPossible())
            return TRUE;
        break;
    case 2:
        FillBgTilemapBufferRect_Palette0(1, 1, 0, 0, 0x20, 2);
        FillBgTilemapBufferRect_Palette0(1, 0, 0, 3, 0x20, 0xB);
        FillBgTilemapBufferRect_Palette0(1, 1, 0, 0xE, 0x20, 6);
        FillBgTilemapBufferRect_Palette0(3, 2, 0, 0, 0x20, 0x20);

        CopyBgTilemapBufferToVram(1);
        CopyBgTilemapBufferToVram(3);
        break;
    case 3:
        InitStandardTextBoxWindows();
        InitTextBoxGfxAndPrinters();
        break;
    case 4:
        SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_OBJ_1D_MAP | DISPCNT_OBJ_ON);
        ShowBg(0);
        ShowBg(1);
        ShowBg(3);
        sHofGfxPtr_hall_of_fame->state = 0;
        return FALSE;
    }

    sHofGfxPtr_hall_of_fame->state++;
    return TRUE;
}

static void SpriteCB_GetOnScreenAndAnimate_hall_of_fame(struct Sprite *sprite)
{
    if (sprite->x != sprite->tDestinationX_hall_of_fame
        || sprite->y != sprite->tDestinationY_hall_of_fame)
    {
        if (sprite->x < sprite->tDestinationX_hall_of_fame)
            sprite->x += 15;
        if (sprite->x > sprite->tDestinationX_hall_of_fame)
            sprite->x -= 15;

        if (sprite->y < sprite->tDestinationY_hall_of_fame)
            sprite->y += 10;
        if (sprite->y > sprite->tDestinationY_hall_of_fame)
            sprite->y -= 10;
    }
    else
    {
        s16 species = sprite->tSpecies_hall_of_fame;

        if (species == SPECIES_EGG)
            DoMonFrontSpriteAnimation(sprite, species, TRUE, 3);
        else
            DoMonFrontSpriteAnimation(sprite, species, FALSE, 3);
    }
}

#undef tDestinationX_hall_of_fame
#undef tDestinationY_hall_of_fame
#undef tSpecies_hall_of_fame

#define sSineIdx_hall_of_fame data[0]
#define sExtraY_hall_of_fame  data[1]

static void SpriteCB_HofConfetti_hall_of_fame(struct Sprite *sprite)
{
    if (sprite->y2 > 120)
    {
        DestroySprite(sprite);
    }
    else
    {
        u16 rand;
        u8 sineIdx;

        sprite->y2++;
        sprite->y2 += sprite->sExtraY_hall_of_fame;

        sineIdx = sprite->sSineIdx_hall_of_fame;
        rand = (Random() % 4) + 8;
        sprite->x2 = rand * gSineTable[sineIdx] / 256;

        sprite->sSineIdx_hall_of_fame += 4;
    }
}

static bool8 CreateHofConfettiSprite_hall_of_fame(void)
{
    u8 spriteID;
    struct Sprite *sprite;

    s16 posX = Random() % DISPLAY_WIDTH;
    s16 posY = -(Random() % 8);

    spriteID = CreateSprite(&sSpriteTemplate_HofConfetti_hall_of_fame, posX, posY, 0);
    sprite = &gSprites[spriteID];

    StartSpriteAnim(sprite, Random() % ARRAY_COUNT(sAnims_Confetti_hall_of_fame));

    // 1/4 confetti sprites move an extra Y coord each frame
    if (Random() & 3)
        sprite->sExtraY_hall_of_fame = 0;
    else
        sprite->sExtraY_hall_of_fame = 1;

    return FALSE;
}

// The below confetti functions are used when a Battle Dome tourney is won
// For the Hall of Fame confetti see Task_Hof_DoConfetti_hall_of_fame
// The end result is essentially the same, just a very different way of handling it
#define tState_hall_of_fame         data[0]
#define tTimer_hall_of_fame         data[1]
#define tConfettiCount_hall_of_fame data[15]

// Indexes into the data array of the struct ConfettiUtil
#define CONFETTI_SINE_IDX_hall_of_fame 0
#define CONFETTI_EXTRA_Y_hall_of_fame  1
#define CONFETTI_TASK_ID_hall_of_fame  7

void DoDomeConfetti(void)
{
    u8 taskId;

    gSpecialVar_0x8004 = 180;
    taskId = CreateTask(Task_DoDomeConfetti_hall_of_fame, 0);
    if (taskId != TASK_NONE)
    {
        gTasks[taskId].tTimer_hall_of_fame = gSpecialVar_0x8004;
        gSpecialVar_0x8005 = taskId;
    }
}

static void StopDomeConfetti_hall_of_fame(void)
{
    u8 taskId;

    if ((taskId = FindTaskIdByFunc(Task_DoDomeConfetti_hall_of_fame)) != TASK_NONE)
        DestroyTask(taskId);

    ConfettiUtil_Free();
    FreeSpriteTilesByTag(TAG_CONFETTI_hall_of_fame);
    FreeSpritePaletteByTag(TAG_CONFETTI_hall_of_fame);
}

static void UpdateDomeConfetti_hall_of_fame(struct ConfettiUtil *util)
{
    if (util->yDelta > 110)
    {
        // Destroy confetti after it falls far enough
        gTasks[util->data[CONFETTI_TASK_ID_hall_of_fame]].tConfettiCount_hall_of_fame--;
        ConfettiUtil_Remove(util->id);
    }
    else
    {
        // Move confetti down
        u8 sineIdx;
        s32 rand;

        util->yDelta++;
        util->yDelta += util->data[CONFETTI_EXTRA_Y_hall_of_fame];

        sineIdx = util->data[CONFETTI_SINE_IDX_hall_of_fame];
        rand = Random();
        rand &= 3;
        rand += 8;
        util->xDelta = (rand) * ((gSineTable[sineIdx])) / 256;

        util->data[CONFETTI_SINE_IDX_hall_of_fame] += 4;
    }
}

static void Task_DoDomeConfetti_hall_of_fame(u8 taskId)
{
    u32 id = 0;
    s16 *data = gTasks[taskId].data;

    switch (tState_hall_of_fame)
    {
    case 0:
        if (!ConfettiUtil_Init(64))
        {
            // Init failed
            DestroyTask(taskId);
            gSpecialVar_0x8004 = 0;
            gSpecialVar_0x8005 = 0xFFFF;
        }
        LoadCompressedSpriteSheet(sSpriteSheet_Confetti_hall_of_fame);
        LoadCompressedSpritePalette(sSpritePalette_Confetti_hall_of_fame);
        tState_hall_of_fame++;
        break;
    case 1:
        if (tTimer_hall_of_fame != 0 && tTimer_hall_of_fame % 3 == 0)
        {
            // Create new confetti every 3 frames
            id = ConfettiUtil_AddNew(&sOamData_Confetti_hall_of_fame,
                              TAG_CONFETTI_hall_of_fame,
                              TAG_CONFETTI_hall_of_fame,
                              Random() % DISPLAY_WIDTH,
                              -(Random() % 8),
                              Random() % ARRAY_COUNT(sAnims_Confetti_hall_of_fame),
                              id);
            if (id != 0xFF)
            {
                ConfettiUtil_SetCallback(id, UpdateDomeConfetti_hall_of_fame);

                // 1/4 of the confetti move an extra y coord every frame
                if ((Random() % 4) == 0)
                    ConfettiUtil_SetData(id, CONFETTI_EXTRA_Y_hall_of_fame, 1);

                ConfettiUtil_SetData(id, CONFETTI_TASK_ID_hall_of_fame, taskId);
                tConfettiCount_hall_of_fame++;
            }
        }

        ConfettiUtil_Update();
        if (tTimer_hall_of_fame != 0)
            tTimer_hall_of_fame--;
        else if (tConfettiCount_hall_of_fame == 0)
            tState_hall_of_fame = 0xFF;
        break;
    case 0xFF:
        StopDomeConfetti_hall_of_fame();
        gSpecialVar_0x8004 = 0;
        gSpecialVar_0x8005 = 0xFFFF;
        break;
    }
}
// Contents of heal_location.c
#include "global.h"
#include "event_data.h"
#include "heal_location.h"
#include "constants/heal_locations.h"
#include "constants/maps.h"

#include "data/heal_locations.h"
#include "data/heal_locations_pkm_center.h"

u32 GetHealLocationIndexByMap(u16 mapGroup, u16 mapNum)
{
    u32 i;

    for (i = 0; i < ARRAY_COUNT(sHealLocations); i++)
    {
        if (sHealLocations[i].group == mapGroup && sHealLocations[i].map == mapNum)
            return i + 1;
    }
    return HEAL_LOCATION_NONE;
}

const struct HealLocation *GetHealLocationByMap(u16 mapGroup, u16 mapNum)
{
    u32 index = GetHealLocationIndexByMap(mapGroup, mapNum);

    if (index == HEAL_LOCATION_NONE)
        return NULL;
    else
        return &sHealLocations[index - 1];
}

u32 GetHealLocationIndexByWarpData(struct WarpData *warp)
{
    u32 i;
    for (i = 0; i < ARRAY_COUNT(sHealLocations); i++)
    {
        if (sHealLocations[i].group == warp->mapGroup
        && sHealLocations[i].map == warp->mapNum
        && sHealLocations[i].x == warp->x
        && sHealLocations[i].y == warp->y)
            return i + 1;
    }
    return HEAL_LOCATION_NONE;
}

const struct HealLocation *GetHealLocation(u32 index)
{
    if (index == HEAL_LOCATION_NONE)
        return NULL;
    else if (index > ARRAY_COUNT(sHealLocations))
        return NULL;
    else
        return &sHealLocations[index - 1];
}

static bool32 IsLastHealLocation_heal_location(u32 healLocation)
{
    const struct HealLocation *loc = GetHealLocation(healLocation);
    const struct WarpData *warpData = &gSaveBlock1Ptr->lastHealLocation;

    return warpData->mapGroup == loc->group
        && warpData->mapNum == loc->map
        && warpData->warpId == WARP_ID_NONE
        && warpData->x == loc->x
        && warpData->y == loc->y;
}

bool32 IsLastHealLocationPlayerHouse()
{
    if (IsLastHealLocation_heal_location(HEAL_LOCATION_LITTLEROOT_TOWN_MAYS_HOUSE)
        || IsLastHealLocation_heal_location(HEAL_LOCATION_LITTLEROOT_TOWN_MAYS_HOUSE_2F)
        || IsLastHealLocation_heal_location(HEAL_LOCATION_LITTLEROOT_TOWN_BRENDANS_HOUSE)
        || IsLastHealLocation_heal_location(HEAL_LOCATION_LITTLEROOT_TOWN_BRENDANS_HOUSE_2F))
        return TRUE;

    return FALSE;
}

u32 GetHealNpcLocalId(u32 healLocationId)
{
    if (healLocationId == HEAL_LOCATION_NONE || healLocationId >= HEAL_LOCATION_COUNT)
        return 0;

    return sHealNpcLocalId[healLocationId - 1];
}

void SetWhiteoutRespawnWarpAndHealerNPC(struct WarpData *warp)
{
    u32 healLocationId = GetHealLocationIndexByWarpData(&gSaveBlock1Ptr->lastHealLocation);
    u32 healNpcLocalId = GetHealNpcLocalId(healLocationId);
    struct HealLocation pkmCenterHealLocation;

    if (!healNpcLocalId)
    {
        *(warp) = gSaveBlock1Ptr->lastHealLocation;
        return;
    }

    pkmCenterHealLocation = sHealLocationsPokemonCenter[healLocationId - 1];
    warp->mapGroup = pkmCenterHealLocation.group;
    warp->mapNum = pkmCenterHealLocation.map;
    warp->warpId = WARP_ID_NONE;
    warp->x = pkmCenterHealLocation.x;
    warp->y = pkmCenterHealLocation.y;
    gSpecialVar_LastTalked = healNpcLocalId;
}
