static void VBlankCB_Intro_intro(void)
{
    LoadOam();
    ProcessSpriteCopyRequests();
    TransferPlttBuffer();
    ScanlineEffect_InitHBlankDmaTransfer();
}

void MainCB2_Intro(void)
{
    RunTasks();
    AnimateSprites();
    BuildOamBuffer();
    UpdatePaletteFade();
    if (gMain.newKeys != 0 && !gPaletteFade.active)
        SetMainCallback2(MainCB2_EndIntro_intro);
    else if (gIntroFrameCounter != -1)
        gIntroFrameCounter++;
}

static void MainCB2_EndIntro_intro(void)
{
    if (!UpdatePaletteFade())
        SetMainCallback2(CB2_InitTitleScreen);
}

static void LoadCopyrightGraphics_intro(u16 tilesetAddress, u16 tilemapAddress, u16 paletteOffset)
{
    LZ77UnCompVram(gIntroCopyright_Gfx, (void *)(VRAM + tilesetAddress));
    LZ77UnCompVram(gIntroCopyright_Tilemap, (void *)(VRAM + tilemapAddress));
    LoadPalette(gIntroCopyright_Pal, paletteOffset, PLTT_SIZE_4BPP);
}

static void SerialCB_CopyrightScreen_intro(void)
{
    GameCubeMultiBoot_HandleSerialInterrupt(&gMultibootProgramStruct);
}

static u8 SetUpCopyrightScreen_intro(void)
{
    switch (gMain.state)
    {
    case COPYRIGHT_INITIALIZE_intro:
        SetVBlankCallback(NULL);
        SetGpuReg(REG_OFFSET_BLDCNT, 0);
        SetGpuReg(REG_OFFSET_BLDALPHA, 0);
        SetGpuReg(REG_OFFSET_BLDY, 0);
        *(u16 *)PLTT = RGB_WHITE;
        SetGpuReg(REG_OFFSET_DISPCNT, 0);
        SetGpuReg(REG_OFFSET_BG0HOFS, 0);
        SetGpuReg(REG_OFFSET_BG0VOFS, 0);
        CpuFill32(0, (void *)VRAM, VRAM_SIZE);
        CpuFill32(0, (void *)OAM, OAM_SIZE);
        CpuFill16(0, (void *)(PLTT + 2), PLTT_SIZE - 2);
        ResetPaletteFade();
        LoadCopyrightGraphics_intro(0, 0x3800, BG_PLTT_ID(0));
        ScanlineEffect_Stop();
        ResetTasks();
        ResetSpriteData();
        FreeAllSpritePalettes();
        BeginNormalPaletteFade(PALETTES_ALL, 0, 16, 0, RGB_WHITEALPHA);
        SetGpuReg(REG_OFFSET_BG0CNT, BGCNT_PRIORITY(0)
                                   | BGCNT_CHARBASE(0)
                                   | BGCNT_SCREENBASE(7)
                                   | BGCNT_16COLOR
                                   | BGCNT_TXT256x256);
        EnableInterrupts(INTR_FLAG_VBLANK);
        SetVBlankCallback(VBlankCB_Intro_intro);
        REG_DISPCNT = DISPCNT_MODE_0 | DISPCNT_OBJ_1D_MAP | DISPCNT_BG0_ON;
        SetSerialCallback(SerialCB_CopyrightScreen_intro);
        GameCubeMultiBoot_Init(&gMultibootProgramStruct);
    // REG_DISPCNT needs to be overwritten the second time, because otherwise the intro won't show up on VBA 1.7.2 and John GBA Lite emulators.
    // The REG_DISPCNT overwrite is NOT needed in m-GBA, No$GBA, VBA 1.8.0, My Boy and Pizza Boy GBA emulators.
    case COPYRIGHT_EMULATOR_BLEND_intro:
        REG_DISPCNT = DISPCNT_MODE_0 | DISPCNT_OBJ_1D_MAP | DISPCNT_BG0_ON;
    default:
        UpdatePaletteFade();
        gMain.state++;
        GameCubeMultiBoot_Main(&gMultibootProgramStruct);
        break;
    case COPYRIGHT_START_FADE_intro:
        GameCubeMultiBoot_Main(&gMultibootProgramStruct);
        if (gMultibootProgramStruct.gcmb_field_2 != 1)
        {
            BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
            gMain.state++;
        }
        break;
    case COPYRIGHT_START_INTRO_intro:
        if (UpdatePaletteFade())
            break;
#if EXPANSION_INTRO == TRUE
        SetMainCallback2(CB2_ExpansionIntro);
        CreateTask(Task_HandleExpansionIntro, 0);
#else
        CreateTask(Task_Scene1_Load, 0);
        SetMainCallback2(MainCB2_Intro);
#endif
        if (gMultibootProgramStruct.gcmb_field_2 != 0)
        {
            if (gMultibootProgramStruct.gcmb_field_2 == 2)
            {
                // check the multiboot ROM header game code to see if we already did this
                if (*(u32 *)(EWRAM_START + 0xAC) == COLOSSEUM_GAME_CODE_intro)
                {
                    CpuCopy16(&gMultiBootProgram_PokemonColosseum_Start, (void *)EWRAM_START, sizeof(gMultiBootProgram_PokemonColosseum_Start));
                    *(u32 *)(EWRAM_START + 0xAC) = COLOSSEUM_GAME_CODE_intro;
                }
                GameCubeMultiBoot_ExecuteProgram(&gMultibootProgramStruct);
            }
        }
        else
        {
            GameCubeMultiBoot_Quit();
            SetSerialCallback(SerialCB);
        }
        return 0;
    }

    return 1;
}

void CB2_InitCopyrightScreenAfterBootup(void)
{
    if (!SetUpCopyrightScreen_intro())
    {
        SetSaveBlocksPointers(GetSaveBlocksPointersBaseOffset());
        ResetMenuAndMonGlobals();
        Save_ResetSaveCounters();
        LoadGameSave(SAVE_NORMAL);
        if (gSaveFileStatus == SAVE_STATUS_EMPTY || gSaveFileStatus == SAVE_STATUS_CORRUPT)
            Sav2_ClearSetDefault();
        SetPokemonCryStereo(gSaveBlock2Ptr->optionsSound);
        InitHeap(gHeap, HEAP_SIZE);
    }
}

void CB2_InitCopyrightScreenAfterTitleScreen(void)
{
    SetUpCopyrightScreen_intro();
}

#define sBigDropSpriteId_intro data[0]

void Task_Scene1_Load(u8 taskId)
{
    SetVBlankCallback(NULL);
    sIntroCharacterGender_intro = MOD(Random(), GENDER_COUNT);
    IntroResetGpuRegs_intro();
    SetGpuReg(REG_OFFSET_BG3VOFS, 0);
    SetGpuReg(REG_OFFSET_BG2VOFS, 80);
    SetGpuReg(REG_OFFSET_BG1VOFS, 24);
    SetGpuReg(REG_OFFSET_BG0VOFS, 40);
    LZ77UnCompVram(sIntro1Bg_Gfx_intro, (void *)VRAM);
    LZ77UnCompVram(sIntro1Bg0_Tilemap_intro, (void *)(BG_CHAR_ADDR(2)));
    DmaClear16(3, BG_SCREEN_ADDR(17), BG_SCREEN_SIZE);
    LZ77UnCompVram(sIntro1Bg1_Tilemap_intro, (void *)(BG_SCREEN_ADDR(18)));
    DmaClear16(3, BG_SCREEN_ADDR(19), BG_SCREEN_SIZE);
    LZ77UnCompVram(sIntro1Bg2_Tilemap_intro, (void *)(BG_SCREEN_ADDR(20)));
    DmaClear16(3, BG_SCREEN_ADDR(21), BG_SCREEN_SIZE);
    LZ77UnCompVram(sIntro1Bg3_Tilemap_intro, (void *)(BG_SCREEN_ADDR(22)));
    DmaClear16(3, BG_SCREEN_ADDR(23), BG_SCREEN_SIZE);
    LoadPalette(sIntro1Bg_Pal_intro, BG_PLTT_ID(0), sizeof(sIntro1Bg_Pal_intro));
    SetGpuReg(REG_OFFSET_BG3CNT, BGCNT_PRIORITY(3) | BGCNT_CHARBASE(0) | BGCNT_SCREENBASE(22) | BGCNT_16COLOR | BGCNT_TXT256x512);
    SetGpuReg(REG_OFFSET_BG2CNT, BGCNT_PRIORITY(2) | BGCNT_CHARBASE(0) | BGCNT_SCREENBASE(20) | BGCNT_16COLOR | BGCNT_TXT256x512);
    SetGpuReg(REG_OFFSET_BG1CNT, BGCNT_PRIORITY(1) | BGCNT_CHARBASE(0) | BGCNT_SCREENBASE(18) | BGCNT_16COLOR | BGCNT_TXT256x512);
    SetGpuReg(REG_OFFSET_BG0CNT, BGCNT_PRIORITY(0) | BGCNT_CHARBASE(0) | BGCNT_SCREENBASE(16) | BGCNT_16COLOR | BGCNT_TXT256x512);
    LoadCompressedSpriteSheet(sSpriteSheet_WaterDropsAndLogo_intro);
    LoadCompressedSpriteSheet(sSpriteSheet_FlygonSilhouette_intro);
    LoadSpritePalettes(sSpritePalettes_Intro1_intro);
    LoadCompressedSpriteSheet(sSpriteSheet_Sparkle_intro);
    LoadSpritePalettes(sSpritePalette_Sparkle_intro);
    CpuCopy16(&gPlttBufferUnfaded[OBJ_PLTT_ID(0)], &gPlttBufferUnfaded[OBJ_PLTT_ID(15) + 0], PLTT_SIZEOF(16 - 0));
    CpuCopy16(&gPlttBufferUnfaded[OBJ_PLTT_ID(0)], &gPlttBufferUnfaded[OBJ_PLTT_ID(14) + 1], PLTT_SIZEOF(16 - 1) + 1); // Copying an extra half color?
    CpuCopy16(&gPlttBufferUnfaded[OBJ_PLTT_ID(0)], &gPlttBufferUnfaded[OBJ_PLTT_ID(13) + 2], PLTT_SIZEOF(16 - 2));
    CpuCopy16(&gPlttBufferUnfaded[OBJ_PLTT_ID(0)], &gPlttBufferUnfaded[OBJ_PLTT_ID(12) + 3], PLTT_SIZEOF(16 - 3));
    CpuCopy16(&gPlttBufferUnfaded[OBJ_PLTT_ID(0)], &gPlttBufferUnfaded[OBJ_PLTT_ID(11) + 4], PLTT_SIZEOF(16 - 4));
    CpuCopy16(&gPlttBufferUnfaded[OBJ_PLTT_ID(0)], &gPlttBufferUnfaded[OBJ_PLTT_ID(10) + 5], PLTT_SIZEOF(16 - 5));
    CpuCopy16(&gPlttBufferUnfaded[OBJ_PLTT_ID(0)], &gPlttBufferUnfaded[OBJ_PLTT_ID( 9) + 6], PLTT_SIZEOF(16 - 6));
    CreateGameFreakLogoSprites_intro(DISPLAY_WIDTH / 2, DISPLAY_HEIGHT / 2, 0);
    gTasks[taskId].sBigDropSpriteId_intro = CreateWaterDrop_intro(236, -14, 0x200, 1, 0x78, FALSE);
    gTasks[taskId].func = Task_Scene1_FadeIn_intro;
}

static void Task_Scene1_FadeIn_intro(u8 taskId)
{
    BeginNormalPaletteFade(PALETTES_ALL, 0, 16, 0, RGB_BLACK);
    SetVBlankCallback(VBlankCB_Intro_intro);
    SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_MODE_0 | DISPCNT_OBJ_1D_MAP | DISPCNT_BG_ALL_ON | DISPCNT_OBJ_ON);
    gTasks[taskId].func = Task_Scene1_WaterDrops_intro;
    gIntroFrameCounter = 0;
    m4aSongNumStart(MUS_INTRO);
    ResetSerial();
}

// Task data for Task_Scene1_PanUp_intro
#define tBg2PosHi_intro data[1]
#define tBg2PosLo_intro data[2]
#define tBg1PosHi_intro data[3]
#define tBg1PosLo_intro data[4]
#define tBg3PosHi_intro data[5]
#define tBg3PosLo_intro data[6]

static void Task_Scene1_WaterDrops_intro(u8 taskId)
{
    if (gIntroFrameCounter == TIMER_BIG_DROP_START_intro)
        gSprites[gTasks[taskId].sBigDropSpriteId_intro].sState_intro = 1;

    if (gIntroFrameCounter == TIMER_LOGO_APPEAR_intro)
        CreateTask(Task_BlendLogoIn_intro, 0);

    if (gIntroFrameCounter == TIMER_BIG_DROP_FALLS_intro)
        gSprites[gTasks[taskId].sBigDropSpriteId_intro].sState_intro = 2;

    if (gIntroFrameCounter == TIMER_LOGO_BLEND_OUT_intro)
        CreateTask(Task_BlendLogoOut_intro, 0);

    if (gIntroFrameCounter == TIMER_SMALL_DROP_1_intro)
        CreateWaterDrop_intro(48, 0, 0x400, 5, 0x70, TRUE);

    if (gIntroFrameCounter == TIMER_SMALL_DROP_2_intro)
        CreateWaterDrop_intro(200, 60, 0x400, 9, 0x80, TRUE);

    if (gIntroFrameCounter == TIMER_SPARKLES_intro)
        CreateTask(Task_CreateSparkles_intro, 0);

    if (gIntroFrameCounter > TIMER_SPARKLES_intro)
    {
        gTasks[taskId].tBg2PosHi_intro = 80;
        gTasks[taskId].tBg2PosLo_intro = 0;
        gTasks[taskId].tBg1PosHi_intro = 24;
        gTasks[taskId].tBg1PosLo_intro = 0;
        gTasks[taskId].tBg3PosHi_intro = 40;
        gTasks[taskId].tBg3PosLo_intro = 0;
        gTasks[taskId].func = Task_Scene1_PanUp_intro;
    }
}

#define tDelay_intro       data[1]
#define tTimer_intro       data[2]
#define tTimerSteps_intro  data[3]
#define tNumSparkles_intro data[4]

static void Task_CreateSparkles_intro(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    if (++tTimer_intro & 1)
        tTimerSteps_intro++;

    switch (tState_intro)
    {
    case 0:
        CreateSprite(&sSpriteTemplate_Sparkle_intro, sSparkleCoords_intro[tNumSparkles_intro][0], sSparkleCoords_intro[tNumSparkles_intro][1] + tTimerSteps_intro, 0);
        tState_intro++;
        tDelay_intro = 12;
        tNumSparkles_intro++;
        break;
    case 1:
        if (--tDelay_intro == 0)
            tState_intro = 0;
        break;
    }

    if (tTimerSteps_intro > 60)
        DestroyTask(taskId);
}

#undef tDelay_intro
#undef tTimer_intro
#undef tTimerSteps_intro
#undef tNumSparkles_intro

#define sTimer_intro data[0]
static void SpriteCB_Sparkle_intro(struct Sprite *sprite)
{
    if (++sprite->sTimer_intro == 12)
        DestroySprite(sprite);
}
#undef sTimer_intro

static void Task_Scene1_PanUp_intro(u8 taskId)
{
    if (gIntroFrameCounter < TIMER_END_PAN_UP_intro)
    {
        s32 offset;

        // Slide bg 2 downward
        offset = (gTasks[taskId].tBg2PosHi_intro << 16) + (u16)gTasks[taskId].tBg2PosLo_intro;
        offset -= 0x6000;
        gTasks[taskId].tBg2PosHi_intro = offset >> 16;
        gTasks[taskId].tBg2PosLo_intro = offset;
        SetGpuReg(REG_OFFSET_BG2VOFS, gTasks[taskId].tBg2PosHi_intro);

        // Slide bg 1 downward
        offset = (gTasks[taskId].tBg1PosHi_intro << 16) + (u16)gTasks[taskId].tBg1PosLo_intro;
        offset -= 0x8000;
        gTasks[taskId].tBg1PosHi_intro = offset >> 16;
        gTasks[taskId].tBg1PosLo_intro = offset;
        SetGpuReg(REG_OFFSET_BG1VOFS, gTasks[taskId].tBg1PosHi_intro);

        // Slide bg 3 downward
        offset = (gTasks[taskId].tBg3PosHi_intro << 16) + (u16)gTasks[taskId].tBg3PosLo_intro;
        offset -= 0xC000;
        gTasks[taskId].tBg3PosHi_intro = offset >> 16;
        gTasks[taskId].tBg3PosLo_intro = offset;
        SetGpuReg(REG_OFFSET_BG0VOFS, gTasks[taskId].tBg3PosHi_intro);

        if (gIntroFrameCounter == TIMER_FLYGON_SILHOUETTE_APPEAR_intro)
        {
            // Show Flygon silhouette
            u8 spriteId = CreateSprite(&sSpriteTemplate_FlygonSilhouette_intro, 120, DISPLAY_HEIGHT, 10);
            gSprites[spriteId].invisible = TRUE;
        }
    }
    else
    {
        if (gIntroFrameCounter > TIMER_END_SCENE_1_intro)
        {
            // Fade to white
            BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_WHITEALPHA);
            gTasks[taskId].func = Task_Scene1_End_intro;
        }
    }
}

static void Task_Scene1_End_intro(u8 taskId)
{
    if (gIntroFrameCounter > TIMER_START_SCENE_2_intro)
        gTasks[taskId].func = Task_Scene2_Load_intro;
}

static void Task_Scene2_Load_intro(u8 taskId)
{
    IntroResetGpuRegs_intro();
    SetVBlankCallback(NULL);
    ResetSpriteData();
    FreeAllSpritePalettes();
    gIntroCredits_MovingSceneryVBase = 0;
    gIntroCredits_MovingSceneryVOffset = 0;
    sFlygonYOffset_intro = 0;
    LoadIntroPart2Graphics(1);
    gTasks[taskId].func = Task_Scene2_CreateSprites_intro;
}

#define tBgAnimTaskId_intro   data[0]
#define tPlayerSpriteId_intro data[1]
#define tFlygonSpriteId_intro data[2]
#define tFlygonTimer_intro    data[3]

static void Task_Scene2_CreateSprites_intro(u8 taskId)
{
    u8 spriteId;

    // Load sprite sheets
    if (sIntroCharacterGender_intro == MALE)
        LoadCompressedSpriteSheet(gSpriteSheet_IntroBrendan);
    else
        LoadCompressedSpriteSheet(gSpriteSheet_IntroMay);

    LoadCompressedSpriteSheet(gSpriteSheet_IntroBicycle);
    LoadCompressedSpriteSheet(gSpriteSheet_IntroFlygon);

    // Load sprite palettes
    for (spriteId = 0; spriteId < ARRAY_COUNT(sSpriteSheet_RunningPokemon_intro) - 1; spriteId++)
        LoadCompressedSpriteSheet(&sSpriteSheet_RunningPokemon_intro[spriteId]);

    LoadSpritePalettes(gSpritePalettes_IntroPlayerFlygon);
    LoadSpritePalettes(sSpritePalettes_RunningPokemon_intro);

    // Create Pokémon and player sprites
    CreateSprite(&sSpriteTemplate_Manectric_intro, DISPLAY_WIDTH + 32, 128, 0);
    CreateSprite(&sSpriteTemplate_Torchic_intro, DISPLAY_WIDTH + 48, 110, 1);

    if (sIntroCharacterGender_intro == MALE)
        spriteId = CreateIntroBrendanSprite(DISPLAY_WIDTH + 32, 100);
    else
        spriteId = CreateIntroMaySprite(DISPLAY_WIDTH + 32, 100);

    gSprites[spriteId].callback = SpriteCB_PlayerOnBicycle_intro;
    gSprites[spriteId].anims = sAnims_PlayerBicycle_intro;
    gTasks[taskId].tPlayerSpriteId_intro = spriteId;
    CreateSprite(&sSpriteTemplate_Volbeat_intro, DISPLAY_WIDTH + 32, 80, 4);
    spriteId = CreateIntroFlygonSprite(-64, 60);
    gSprites[spriteId].callback = SpriteCB_Flygon_intro;
    gTasks[taskId].tFlygonSpriteId_intro = spriteId;

    // Fade in and start bike ride
    BeginNormalPaletteFade(PALETTES_ALL, 0, 16, 0, RGB_WHITEALPHA);
    SetVBlankCallback(VBlankCB_Intro_intro);
    gTasks[taskId].tBgAnimTaskId_intro = CreateBicycleBgAnimationTask(1, 0x4000, 0x400, 0x10);
    SetIntroPart2BgCnt(1);
    gTasks[taskId].func = Task_Scene2_BikeRide_intro;
}

static void Task_Scene2_BikeRide_intro(u8 taskId)
{
    u16 offset;

    if (gIntroFrameCounter == TIMER_TORCHIC_EXIT_intro)
    {
        // Stop the moving scenery/backgrounds, for when the camera fixes on Torchic
        gIntroCredits_MovingSceneryState = INTROCRED_SCENERY_FROZEN;
        DestroyTask(gTasks[taskId].tBgAnimTaskId_intro);
    }

    if (gIntroFrameCounter > TIMER_END_SCENE_2_intro)
    {
        // Fade out to next scene
        BeginNormalPaletteFade(PALETTES_ALL, 8, 0, 16, RGB_WHITEALPHA);
        gTasks[taskId].func = Task_Scene2_End_intro;
    }

    // Check for updates to player/flygon sprites
    // These states are for SpriteCB_PlayerOnBicycle_intro and SpriteCB_Flygon_intro respectively
    if (gIntroFrameCounter == TIMER_PLAYER_DRIFT_BACK_intro)
        gSprites[gTasks[taskId].tPlayerSpriteId_intro].sState_intro = 1;
    if (gIntroFrameCounter == TIMER_PLAYER_MOVE_FORWARD_intro)
        gSprites[gTasks[taskId].tPlayerSpriteId_intro].sState_intro = 0;
    if (gIntroFrameCounter == TIMER_FLYGON_ENTER_intro)
        gSprites[gTasks[taskId].tFlygonSpriteId_intro].sState_intro = 1;
    if (gIntroFrameCounter == TIMER_PLAYER_MOVE_BACKWARD_intro)
        gSprites[gTasks[taskId].tPlayerSpriteId_intro].sState_intro = 2;
    if (gIntroFrameCounter == TIMER_PLAYER_HOLD_POSITION_intro)
        gSprites[gTasks[taskId].tPlayerSpriteId_intro].sState_intro = 3;
    if (gIntroFrameCounter == TIMER_PLAYER_EXIT_intro)
        gSprites[gTasks[taskId].tPlayerSpriteId_intro].sState_intro = 4;

    // Handle flygon's y movement
    offset = Sin(gTasks[taskId].tFlygonTimer_intro >> 2 & 0x7F, 48);
    sFlygonYOffset_intro = offset;
    if (gTasks[taskId].tFlygonTimer_intro < 512)
        gTasks[taskId].tFlygonTimer_intro++;

    // Alternate colors of the trees
    CycleSceneryPalette(0);
}

static void Task_Scene2_End_intro(u8 taskId)
{
    if (gIntroFrameCounter > TIMER_START_SCENE_3_intro)
        gTasks[taskId].func = Task_Scene3_Load_intro;
}

#define sStateDelay_intro data[1]
#define sNextState_intro  data[2]
#define sCosYIdx_intro    data[3]
#define sSinXIdx_intro    data[4]
#define sSinYIdx_intro    data[5]
#define sFig8Loops_intro  data[6]

enum {
    VOLBEAT_WAIT_ENTER_intro,
    VOLBEAT_ENTER_intro,
    VOLBEAT_ZIP_BACKWARD_intro,
    VOLBEAT_ZIP_DOWN_intro,
    VOLBEAT_ZIP_FORWARD_intro,
    VOLBEAT_INIT_FIGURE_8_intro,
    VOLBEAT_FIGURE_8_intro,
    VOLBEAT_EXIT_intro,
    VOLBEAT_WAIT_STATE_intro
};

static void SpriteCB_Volbeat_intro(struct Sprite *sprite)
{
    sprite->sCosYIdx_intro += 4;
    switch (sprite->sState_intro)
    {
    case VOLBEAT_WAIT_ENTER_intro:
        if (++sprite->sStateDelay_intro < 180)
            break;
        sprite->sState_intro++;
        // fallthrough
    case VOLBEAT_ENTER_intro:
        sprite->x -= 4;
        if (sprite->x == 60)
        {
            sprite->sState_intro = VOLBEAT_WAIT_STATE_intro;
            sprite->sStateDelay_intro = 20;
            sprite->sNextState_intro = VOLBEAT_ZIP_BACKWARD_intro;
        }
        break;
    case VOLBEAT_ZIP_BACKWARD_intro:
        sprite->x += 8;
        sprite->y -= 2;
        if (sprite->x == 124)
        {
            sprite->sState_intro = VOLBEAT_WAIT_STATE_intro;
            sprite->sStateDelay_intro = 20;
            sprite->sNextState_intro = VOLBEAT_ZIP_DOWN_intro;
        }
        break;
    case VOLBEAT_ZIP_DOWN_intro:
        sprite->y += 4;
        if (sprite->y == 80)
        {
            sprite->sState_intro = VOLBEAT_WAIT_STATE_intro;
            sprite->sStateDelay_intro = 10;
            sprite->sNextState_intro = VOLBEAT_ZIP_FORWARD_intro;
        }
        break;
    case VOLBEAT_ZIP_FORWARD_intro:
        sprite->x -= 8;
        sprite->y -= 2;
        if (sprite->x == 60)
        {
            sprite->sState_intro = VOLBEAT_WAIT_STATE_intro;
            sprite->sStateDelay_intro = 10;
            sprite->sNextState_intro = VOLBEAT_INIT_FIGURE_8_intro;
        }
        break;
    case VOLBEAT_INIT_FIGURE_8_intro:
        sprite->x += 60;
        sprite->sSinXIdx_intro = 0xC0;
        sprite->sSinYIdx_intro = 0x80;
        sprite->sFig8Loops_intro = 3;
        sprite->sState_intro++;
        // fallthrough
    case VOLBEAT_FIGURE_8_intro:
        sprite->x2 = Sin((u8)sprite->sSinXIdx_intro, 0x3C);
        sprite->y2 = Sin((u8)sprite->sSinYIdx_intro, 0x14);
        sprite->sSinXIdx_intro += 2;
        sprite->sSinYIdx_intro += 4;
        if ((sprite->sSinXIdx_intro & 0xFF) == 64)
        {
            sprite->hFlip = FALSE;
            if (--sprite->sFig8Loops_intro == 0)
            {
                sprite->x += sprite->x2;
                sprite->x2 = 0;
                sprite->sState_intro++;
            }
        }
        break;
    case VOLBEAT_EXIT_intro:
        sprite->x -= 2;
        sprite->y2 = Sin((u8)sprite->sSinYIdx_intro, 0x14);
        sprite->sSinYIdx_intro += 4;
        if (sprite->x < -16)
            DestroySprite(sprite);
        break;
    case VOLBEAT_WAIT_STATE_intro:
        // Wait for state progression, fly idly until then
        sprite->y2 = Cos((u8)sprite->sCosYIdx_intro, 2);
        if (!--sprite->sStateDelay_intro)
            sprite->sState_intro = sprite->sNextState_intro;
        break;
    }
}

#undef sStateDelay_intro
#undef sNextState_intro
#undef sCosYIdx_intro
#undef sSinXIdx_intro
#undef sSinYIdx_intro
#undef sFig8Loops_intro

#define sMoveTimer_intro data[1]
#define sDelay_intro     data[2]

static void SpriteCB_Torchic_intro(struct Sprite *sprite)
{
    switch (sprite->sState_intro)
    {
    case 0:
        if (gIntroFrameCounter == TIMER_TORCHIC_ENTER_intro)
        {
            StartSpriteAnim(sprite, TORCHIC_ANIM_RUN_intro);
            sprite->sState_intro++;
        }
        break;
    case 1:
        if (gIntroFrameCounter == TIMER_PLAYER_HOLD_POSITION_intro)
        {
            StartSpriteAnim(sprite, TORCHIC_ANIM_WALK_intro);
            sprite->sState_intro++;
        }
        else
        {
            sprite->sMoveTimer_intro += 64;
            if (sprite->sMoveTimer_intro & 0xFF00)
            {
                sprite->x--;
                sprite->sMoveTimer_intro &= 0xFF;
            }
        }
        break;
    case 2:
        if (gIntroFrameCounter != TIMER_TORCHIC_SPEED_UP_intro)
        {
            sprite->sMoveTimer_intro += 32;
            if (sprite->sMoveTimer_intro & 0xFF00)
            {
                sprite->x++;
                sprite->sMoveTimer_intro &= 0xFF;
            }
        }
        else
        {
            StartSpriteAnim(sprite, TORCHIC_ANIM_RUN_intro);
            sprite->sState_intro++;
            sprite->sDelay_intro = 80;
        }
        break;
    case 3:
        if (--sprite->sDelay_intro)
        {
            sprite->sMoveTimer_intro += 64;
            if (sprite->sMoveTimer_intro & 0xFF00)
            {
                sprite->x--;
                sprite->sMoveTimer_intro &= 0xFF;
            }
        }
        else
        {
            StartSpriteAnim(sprite, TORCHIC_ANIM_TRIP_intro);
            sprite->sState_intro++;
        }
        break;
    case 4:
        if (sprite->animEnded)
            sprite->x += 4;

        if (sprite->x > 336)
        {
            StartSpriteAnim(sprite, TORCHIC_ANIM_RUN_intro);
            sprite->sState_intro++;
        }
        break;
    case 5:
        if (gIntroFrameCounter >= TIMER_TORCHIC_EXIT_intro)
            sprite->x -= 2;
        break;
    }
}

#undef sMoveTimer_intro
#undef sDelay_intro

#define sSinIdx_intro data[1]
#define sCosIdx_intro data[2]

static void SpriteCB_Manectric_intro(struct Sprite *sprite)
{
    switch (sprite->sState_intro)
    {
    case 0:
        if (gIntroFrameCounter == TIMER_MANECTRIC_ENTER_intro)
            sprite->sState_intro++;
        break;
    case 1:
        sprite->x -= 2;
        if (gIntroFrameCounter != TIMER_MANECTRIC_RUN_CIRCULAR_intro)
            break;

        // Initialize circular pattern running
        sprite->y -= 12;
        sprite->sSinIdx_intro = 0x80;
        sprite->sCosIdx_intro = 0;
        sprite->sState_intro++;
        // fallthrough
    case 2:
        if (sprite->x + sprite->x2 <= -32)
        {
            // Manectric is offscreen now, destroy it
            DestroySprite(sprite);
        }
        else
        {
            // Run in circular pattern
            if ((sprite->sSinIdx_intro & 0xFF) < 64)
            {
                sprite->x2 = Sin((u8)sprite->sSinIdx_intro, 16);
            }
            else
            {
                if ((sprite->sSinIdx_intro & 0xFF) == 64)
                    sprite->x -= 48;
                sprite->x2 = Sin((u8)sprite->sSinIdx_intro, 64);
            }
            sprite->sSinIdx_intro++;
            sprite->y2 = Cos((u8)sprite->sCosIdx_intro, 12);
            sprite->sCosIdx_intro++;
        }
        break;
    }
}

#undef sSinIdx_intro
#undef sCosIdx_intro

#define tAlpha_intro        data[0]
#define tZoomDiv_intro      data[1]
#define tZoomDivSpeed_intro data[2]

static void Task_Scene3_Load_intro(u8 taskId)
{
    IntroResetGpuRegs_intro();
    LZ77UnCompVram(sIntroPokeball_Gfx_intro, (void *)VRAM);
    LZ77UnCompVram(sIntroPokeball_Tilemap_intro, (void *)(BG_CHAR_ADDR(1)));
    LoadPalette(sIntroPokeball_Pal_intro, BG_PLTT_ID(0), sizeof(sIntroPokeball_Pal_intro));
    gTasks[taskId].tAlpha_intro = 0;
    gTasks[taskId].tZoomDiv_intro = 0;
    gTasks[taskId].tZoomDivSpeed_intro = 0;
    gTasks[taskId].data[3] = 0;
    PanFadeAndZoomScreen(DISPLAY_WIDTH / 2, DISPLAY_HEIGHT / 2, 0, 0);
    ResetSpriteData();
    FreeAllSpritePalettes();
    BeginNormalPaletteFade(PALETTES_ALL, 0, 16, 0, RGB_WHITEALPHA);
    SetGpuReg(REG_OFFSET_BG2CNT, BGCNT_PRIORITY(3) | BGCNT_CHARBASE(0) | BGCNT_SCREENBASE(8) | BGCNT_256COLOR | BGCNT_AFF256x256);
    SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_MODE_1 | DISPCNT_OBJ_1D_MAP | DISPCNT_BG2_ON | DISPCNT_OBJ_ON);
    gTasks[taskId].func = Task_Scene3_SpinPokeball_intro;
    gIntroFrameCounter = 0;
    m4aSongNumStart(MUS_INTRO_BATTLE);
}
static void Task_Scene3_SpinPokeball_intro(u8 taskId)
{
    gTasks[taskId].tAlpha_intro += 0x400;

    if (gTasks[taskId].tZoomDiv_intro <= 0x6BF)
    {
        gTasks[taskId].tZoomDiv_intro += gTasks[taskId].tZoomDivSpeed_intro;
        gTasks[taskId].tZoomDivSpeed_intro += 2;
    }
    else
    {
        gTasks[taskId].func = Task_Scene3_WaitGroudon_intro;
    }

    PanFadeAndZoomScreen(DISPLAY_WIDTH / 2, DISPLAY_HEIGHT / 2, SAFE_DIV(0x10000, gTasks[taskId].tZoomDiv_intro), gTasks[taskId].tAlpha_intro);

    if (gIntroFrameCounter == TIMER_POKEBALL_FADE_intro)
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_WHITEALPHA);
}

#undef tAlpha_intro
#undef tZoomDiv_intro
#undef tZoomDivSpeed_intro

static void Task_Scene3_WaitGroudon_intro(u8 taskId)
{
    if (gIntroFrameCounter > TIMER_START_LEGENDARIES_intro)
        gTasks[taskId].func = Task_Scene3_LoadGroudon_intro;
}

static void Task_Scene3_LoadGroudon_intro(u8 taskId)
{
    if (!gPaletteFade.active)
    {
        IntroResetGpuRegs_intro();
        ResetSpriteData();
        FreeAllSpritePalettes();
        gReservedSpritePaletteCount = 8;
        LZDecompressVram(gIntroGroudon_Gfx, (void *)VRAM);
        LZDecompressVram(gIntroGroudon_Tilemap, (void *)(BG_CHAR_ADDR(3)));
        LZDecompressVram(gIntroLegendBg_Gfx, (void *)(BG_CHAR_ADDR(1)));
        LZDecompressVram(gIntroGroudonBg_Tilemap, (void *)(BG_SCREEN_ADDR(28)));
        LoadCompressedSpriteSheetUsingHeap(&gBattleAnimPicTable[GET_TRUE_SPRITE_INDEX(ANIM_TAG_ROCKS)]);
        LoadCompressedSpritePaletteUsingHeap(&gBattleAnimPaletteTable[GET_TRUE_SPRITE_INDEX(ANIM_TAG_ROCKS)]);
        CpuCopy16(gIntro3Bg_Pal, gPlttBufferUnfaded, sizeof(gIntro3Bg_Pal));
        gTasks[taskId].func = Task_Scene3_InitGroudonBg_intro;
    }
}

