void LoadIntroPart2Graphics(u8 scenery)
{
    LZ77UnCompVram(sGrass_Gfx_intro_credits_graphics, (void *)(BG_CHAR_ADDR(1)));
    LZ77UnCompVram(sGrass_Tilemap_intro_credits_graphics, (void *)(BG_SCREEN_ADDR(15)));
    LoadPalette(&sGrass_Pal_intro_credits_graphics, BG_PLTT_ID(15), sizeof(sGrass_Pal_intro_credits_graphics));
    switch (scenery)
    {
    case 0:
    default:
        // Never reached, only called with an argument of 1
        // Clouds are never used in this part of the intro
        LZ77UnCompVram(sCloudsBg_Gfx_intro_credits_graphics, (void *)(VRAM));
        LZ77UnCompVram(sCloudsBg_Tilemap_intro_credits_graphics, (void *)(BG_SCREEN_ADDR(6)));
        LoadPalette(&sCloudsBg_Pal_intro_credits_graphics, BG_PLTT_ID(0), sizeof(sCloudsBg_Pal_intro_credits_graphics));
        LoadCompressedSpriteSheet(sSpriteSheet_Clouds_intro_credits_graphics);
        LoadPalette(&sClouds_Pal_intro_credits_graphics, OBJ_PLTT_ID(0), sizeof(sClouds_Pal_intro_credits_graphics));
        CreateCloudSprites_intro_credits_graphics();
        break;
    case 1:
        LZ77UnCompVram(sTrees_Gfx_intro_credits_graphics, (void *)(VRAM));
        LZ77UnCompVram(sTrees_Tilemap_intro_credits_graphics, (void *)(BG_SCREEN_ADDR(6)));
        LoadPalette(&sTrees_Pal_intro_credits_graphics, BG_PLTT_ID(0), sizeof(sTrees_Pal_intro_credits_graphics));
        LoadCompressedSpriteSheet(sSpriteSheet_TreesSmall_intro_credits_graphics);
        LoadPalette(&sTreesSmall_Pal_intro_credits_graphics, OBJ_PLTT_ID(0), sizeof(sTreesSmall_Pal_intro_credits_graphics));
        CreateTreeSprites_intro_credits_graphics();
        break;
    }
    gIntroCredits_MovingSceneryState = INTROCRED_SCENERY_NORMAL;
    gReservedSpritePaletteCount = 8;
}

// Note: This is only called with scenery=1.
void SetIntroPart2BgCnt(u8 scenery)
{
    switch (scenery)
    {
    default:
    case 0:
        SetGpuReg(REG_OFFSET_BG3CNT, BGCNT_PRIORITY(3)
                                   | BGCNT_CHARBASE(0)
                                   | BGCNT_16COLOR
                                   | BGCNT_SCREENBASE(6)
                                   | BGCNT_TXT256x256);
        SetGpuReg(REG_OFFSET_BG2CNT, BGCNT_PRIORITY(2)
                                   | BGCNT_CHARBASE(0)
                                   | BGCNT_16COLOR
                                   | BGCNT_SCREENBASE(7)
                                   | BGCNT_TXT256x256);
        SetGpuReg(REG_OFFSET_BG1CNT, BGCNT_PRIORITY(1)
                                   | BGCNT_CHARBASE(1)
                                   | BGCNT_16COLOR
                                   | BGCNT_SCREENBASE(15)
                                   | BGCNT_TXT256x256);
        SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_MODE_0
                                    | DISPCNT_OBJ_1D_MAP
                                    | DISPCNT_BG1_ON
                                    | DISPCNT_BG2_ON
                                    | DISPCNT_BG3_ON
                                    | DISPCNT_OBJ_ON);
        break;
    case 1:
        SetGpuReg(REG_OFFSET_BG3CNT, BGCNT_PRIORITY(3)
                                   | BGCNT_CHARBASE(0)
                                   | BGCNT_16COLOR
                                   | BGCNT_SCREENBASE(6)
                                   | BGCNT_TXT256x256);
        SetGpuReg(REG_OFFSET_BG2CNT, BGCNT_PRIORITY(2)
                                   | BGCNT_CHARBASE(0)
                                   | BGCNT_16COLOR
                                   | BGCNT_SCREENBASE(7)
                                   | BGCNT_TXT256x256);
        SetGpuReg(REG_OFFSET_BG1CNT, BGCNT_PRIORITY(1)
                                   | BGCNT_CHARBASE(1)
                                   | BGCNT_16COLOR
                                   | BGCNT_SCREENBASE(15)
                                   | BGCNT_TXT256x256);
        SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_MODE_0
                                    | DISPCNT_OBJ_1D_MAP
                                    | DISPCNT_BG1_ON
                                    | DISPCNT_BG2_ON
                                    | DISPCNT_BG3_ON
                                    | DISPCNT_OBJ_ON);
        break;
    case 2:
        SetGpuReg(REG_OFFSET_BG3CNT, BGCNT_PRIORITY(3)
                                   | BGCNT_CHARBASE(0)
                                   | BGCNT_16COLOR
                                   | BGCNT_SCREENBASE(6)
                                   | BGCNT_TXT256x256);
        SetGpuReg(REG_OFFSET_BG2CNT, BGCNT_PRIORITY(2)
                                   | BGCNT_CHARBASE(0)
                                   | BGCNT_16COLOR
                                   | BGCNT_SCREENBASE(7)
                                   | BGCNT_TXT256x256);
        SetGpuReg(REG_OFFSET_BG1CNT, BGCNT_PRIORITY(1)
                                   | BGCNT_CHARBASE(1)
                                   | BGCNT_16COLOR
                                   | BGCNT_SCREENBASE(15)
                                   | BGCNT_TXT256x256);
        SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_MODE_0
                                    | DISPCNT_OBJ_1D_MAP
                                    | DISPCNT_BG1_ON
                                    | DISPCNT_BG2_ON
                                    | DISPCNT_BG3_ON
                                    | DISPCNT_OBJ_ON);
        break;
    }
}

void LoadCreditsSceneGraphics(u8 scene)
{
    LZ77UnCompVram(sGrass_Gfx_intro_credits_graphics, (void *)(BG_CHAR_ADDR(1)));
    LZ77UnCompVram(sGrass_Tilemap_intro_credits_graphics, (void *)(BG_SCREEN_ADDR(15)));
    switch (scene)
    {
    case SCENE_OCEAN_MORNING:
    default:
        LoadPalette(&sGrass_Pal_intro_credits_graphics, BG_PLTT_ID(15), sizeof(sGrass_Pal_intro_credits_graphics));
        LZ77UnCompVram(sCloudsBg_Gfx_intro_credits_graphics, (void *)(VRAM));
        LZ77UnCompVram(sCloudsBg_Tilemap_intro_credits_graphics, (void *)(BG_SCREEN_ADDR(6)));
        LoadPalette(&sCloudsBg_Pal_intro_credits_graphics, BG_PLTT_ID(0), sizeof(sCloudsBg_Pal_intro_credits_graphics));
        LoadCompressedSpriteSheet(sSpriteSheet_Clouds_intro_credits_graphics);
        LZ77UnCompVram(sClouds_Gfx_intro_credits_graphics, (void *)(OBJ_VRAM0));
        LoadPalette(&sClouds_Pal_intro_credits_graphics, OBJ_PLTT_ID(0), sizeof(sClouds_Pal_intro_credits_graphics));
        CreateCloudSprites_intro_credits_graphics();
        break;
    case SCENE_OCEAN_SUNSET:
        LoadPalette(&sGrassSunset_Pal_intro_credits_graphics, BG_PLTT_ID(15), sizeof(sGrassSunset_Pal_intro_credits_graphics));
        LZ77UnCompVram(sCloudsBg_Gfx_intro_credits_graphics, (void *)(VRAM));
        LZ77UnCompVram(sCloudsBg_Tilemap_intro_credits_graphics, (void *)(BG_SCREEN_ADDR(6)));
        LoadPalette(&sCloudsBgSunset_Pal_intro_credits_graphics, BG_PLTT_ID(0), sizeof(sCloudsBgSunset_Pal_intro_credits_graphics));
        LoadCompressedSpriteSheet(sSpriteSheet_Clouds_intro_credits_graphics);
        LZ77UnCompVram(sClouds_Gfx_intro_credits_graphics, (void *)(OBJ_VRAM0));
        LoadPalette(&sCloudsSunset_Pal_intro_credits_graphics, OBJ_PLTT_ID(0), sizeof(sCloudsSunset_Pal_intro_credits_graphics));
        CreateCloudSprites_intro_credits_graphics();
        break;
    case SCENE_FOREST_RIVAL_ARRIVE:
    case SCENE_FOREST_CATCH_RIVAL:
        LoadPalette(&sGrassSunset_Pal_intro_credits_graphics, BG_PLTT_ID(15), sizeof(sGrassSunset_Pal_intro_credits_graphics));
        LZ77UnCompVram(sTrees_Gfx_intro_credits_graphics, (void *)(VRAM));
        LZ77UnCompVram(sTrees_Tilemap_intro_credits_graphics, (void *)(BG_SCREEN_ADDR(6)));
        LoadPalette(&sTreesSunset_Pal_intro_credits_graphics, BG_PLTT_ID(0), sizeof(sTreesSunset_Pal_intro_credits_graphics));
        LoadCompressedSpriteSheet(sSpriteSheet_TreesSmall_intro_credits_graphics);
        LoadPalette(&sTreesSunset_Pal_intro_credits_graphics, OBJ_PLTT_ID(0), sizeof(sTreesSunset_Pal_intro_credits_graphics));
        CreateTreeSprites_intro_credits_graphics();
        break;
    case SCENE_CITY_NIGHT:
        LoadPalette(&sGrassNight_Pal_intro_credits_graphics, BG_PLTT_ID(15), sizeof(sGrassNight_Pal_intro_credits_graphics));
        LZ77UnCompVram(sHouses_Gfx_intro_credits_graphics, (void *)(VRAM));
        LZ77UnCompVram(sHouses_Tilemap_intro_credits_graphics, (void *)(BG_SCREEN_ADDR(6)));
        LoadPalette(&sHouses_Pal_intro_credits_graphics, BG_PLTT_ID(0), sizeof(sHouses_Pal_intro_credits_graphics));
        LoadCompressedSpriteSheet(sSpriteSheet_HouseSilhouette_intro_credits_graphics);
        LoadPalette(&sHouseSilhouette_Pal_intro_credits_graphics, OBJ_PLTT_ID(0), sizeof(sHouseSilhouette_Pal_intro_credits_graphics));
        CreateHouseSprites_intro_credits_graphics();
        break;
    }
    gReservedSpritePaletteCount = 8;
    gIntroCredits_MovingSceneryState = INTROCRED_SCENERY_NORMAL;
}

