static void TryDepositItem_item_menu(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    FillWindowPixelBuffer(WIN_DESCRIPTION_item_menu, PIXEL_FILL(0));
    if (ItemId_GetImportance(gSpecialVar_ItemId))
    {
        // Can't deposit important items
        BagMenu_Print_item_menu(WIN_DESCRIPTION_item_menu, FONT_NORMAL, sText_CantStoreImportantItems_item_menu, 3, 1, 0, 0, 0, COLORID_NORMAL_item_menu);
        gTasks[taskId].func = WaitDepositErrorMessage_item_menu;
    }
    else if (AddPCItem(gSpecialVar_ItemId, tItemCount_item_menu) == TRUE)
    {
        // Successfully deposited
        u8 *end = CopyItemNameHandlePlural(gSpecialVar_ItemId, gStringVar1, tItemCount_item_menu);
        WrapFontIdToFit(gStringVar1, end, FONT_NORMAL, WindowWidthPx(WIN_DESCRIPTION_item_menu) - 10 - 6);
        ConvertIntToDecimalStringN(gStringVar2, tItemCount_item_menu, STR_CONV_MODE_LEFT_ALIGN, MAX_ITEM_DIGITS);
        StringExpandPlaceholders(gStringVar4, sText_DepositedVar2Var1s_item_menu);
        BagMenu_Print_item_menu(WIN_DESCRIPTION_item_menu, FONT_NORMAL, gStringVar4, 3, 1, 0, 0, 0, COLORID_NORMAL_item_menu);
        gTasks[taskId].func = Task_RemoveItemFromBag_item_menu;
    }
    else
    {
        // No room to deposit
        BagMenu_Print_item_menu(WIN_DESCRIPTION_item_menu, FONT_NORMAL, sText_NoRoomForItems_item_menu, 3, 1, 0, 0, 0, COLORID_NORMAL_item_menu);
        gTasks[taskId].func = WaitDepositErrorMessage_item_menu;
    }
}

