static bool8 IsWallysBag_item_menu(void)
{
    if (gBagPosition.location == ITEMMENULOCATION_WALLY)
        return TRUE;
    return FALSE;
}

static void PrepareBagForWallyTutorial_item_menu(void)
{
    u32 i;

    sTempWallyBag_item_menu = AllocZeroed(sizeof(*sTempWallyBag_item_menu));
    memcpy(sTempWallyBag_item_menu->bagPocket_Items, gSaveBlock1Ptr->bagPocket_Items, sizeof(gSaveBlock1Ptr->bagPocket_Items));
    memcpy(sTempWallyBag_item_menu->bagPocket_PokeBalls, gSaveBlock1Ptr->bagPocket_PokeBalls, sizeof(gSaveBlock1Ptr->bagPocket_PokeBalls));
    sTempWallyBag_item_menu->pocket = gBagPosition.pocket;
    for (i = 0; i < POCKETS_COUNT; i++)
    {
        sTempWallyBag_item_menu->cursorPosition[i] = gBagPosition.cursorPosition[i];
        sTempWallyBag_item_menu->scrollPosition[i] = gBagPosition.scrollPosition[i];
    }
    ClearItemSlots(gSaveBlock1Ptr->bagPocket_Items, BAG_ITEMS_COUNT);
    ClearItemSlots(gSaveBlock1Ptr->bagPocket_PokeBalls, BAG_POKEBALLS_COUNT);
    ResetBagScrollPositions();
}

static void RestoreBagAfterWallyTutorial_item_menu(void)
{
    u32 i;

    memcpy(gSaveBlock1Ptr->bagPocket_Items, sTempWallyBag_item_menu->bagPocket_Items, sizeof(sTempWallyBag_item_menu->bagPocket_Items));
    memcpy(gSaveBlock1Ptr->bagPocket_PokeBalls, sTempWallyBag_item_menu->bagPocket_PokeBalls, sizeof(sTempWallyBag_item_menu->bagPocket_PokeBalls));
    gBagPosition.pocket = sTempWallyBag_item_menu->pocket;
    for (i = 0; i < POCKETS_COUNT; i++)
    {
        gBagPosition.cursorPosition[i] = sTempWallyBag_item_menu->cursorPosition[i];
        gBagPosition.scrollPosition[i] = sTempWallyBag_item_menu->scrollPosition[i];
    }
    Free(sTempWallyBag_item_menu);
}

void DoWallyTutorialBagMenu(void)
{
    PrepareBagForWallyTutorial_item_menu();
    AddBagItem(ITEM_POTION, 1);
    AddBagItem(ITEM_POKE_BALL, 1);
    GoToBagMenu(ITEMMENULOCATION_WALLY, ITEMS_POCKET, CB2_SetUpReshowBattleScreenAfterMenu2);
}

#define tTimer_item_menu data[8]
#define WALLY_BAG_DELAY_item_menu 102 // The number of frames between each action Wally takes in the bag

static void Task_WallyTutorialBagMenu_item_menu(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    if (!gPaletteFade.active)
    {
        switch (tTimer_item_menu)
        {
        case WALLY_BAG_DELAY_item_menu * 1:
            PlaySE(SE_SELECT);
            SwitchBagPocket_item_menu(taskId, MENU_CURSOR_DELTA_RIGHT, FALSE);
            tTimer_item_menu++;
            break;
        case WALLY_BAG_DELAY_item_menu * 2:
            PlaySE(SE_SELECT);
            BagMenu_PrintCursor_item_menu(tListTaskId_item_menu, COLORID_GRAY_CURSOR_item_menu);
            gSpecialVar_ItemId = ITEM_POKE_BALL;
            OpenContextMenu_item_menu(taskId);
            tTimer_item_menu++;
            break;
        case WALLY_BAG_DELAY_item_menu * 3:
            PlaySE(SE_SELECT);
            RemoveContextWindow_item_menu();
            DestroyListMenuTask(tListTaskId_item_menu, 0, 0);
            RestoreBagAfterWallyTutorial_item_menu();
            Task_FadeAndCloseBagMenu(taskId);
            break;
        default:
            tTimer_item_menu++;
            break;
        }
    }
}

#undef tTimer_item_menu

