static void ItemUseOnFieldCB_Itemfinder_item_use(u8 taskId)
{
    if (ItemfinderCheckForHiddenItems_item_use(gMapHeader.events, taskId) == TRUE)
        gTasks[taskId].func = Task_UseItemfinder_item_use;
    else
        DisplayItemMessageOnField(taskId, sText_ItemFinderNothing_item_use, Task_CloseItemfinderMessage_item_use);
}

// Define itemfinder task data
#define tItemDistanceX_item_use    data[0]
#define tItemDistanceY_item_use    data[1]
#define tItemFound_item_use        data[2]
#define tCounter_item_use          data[3] // Used to count delay between beeps and rotations during player spin
#define tItemfinderBeeps_item_use  data[4]
#define tFacingDir_item_use        data[5]

static void Task_UseItemfinder_item_use(u8 taskId)
{
    u8 playerDir;
    u8 playerDirToItem;
    u8 i;
    s16 *data = gTasks[taskId].data;
    if (tCounter_item_use == 0)
    {
        if (tItemfinderBeeps_item_use == 4)
        {
            playerDirToItem = GetDirectionToHiddenItem_item_use(tItemDistanceX_item_use, tItemDistanceY_item_use);
            if (playerDirToItem != DIR_NONE)
            {
                PlayerFaceHiddenItem_item_use(sClockwiseDirections_item_use[playerDirToItem - 1]);
                gTasks[taskId].func = Task_HiddenItemNearby_item_use;
            }
            else
            {
                // Player is standing on hidden item
                playerDir = GetPlayerFacingDirection();
                for (i = 0; i < ARRAY_COUNT(sClockwiseDirections_item_use); i++)
                {
                    if (playerDir == sClockwiseDirections_item_use[i])
                        tFacingDir_item_use = (i + 1) & 3;
                }
                gTasks[taskId].func = Task_StandingOnHiddenItem_item_use;
                tCounter_item_use = 0;
                tItemFound_item_use = 0;
            }
            return;
        }
        PlaySE(SE_ITEMFINDER);
        tItemfinderBeeps_item_use++;
    }
    tCounter_item_use = (tCounter_item_use + 1) & 0x1F;
}

static void Task_CloseItemfinderMessage_item_use(u8 taskId)
{
    ClearDialogWindowAndFrame(0, TRUE);
    ScriptUnfreezeObjectEvents();
    UnlockPlayerFieldControls();
    DestroyTask(taskId);
}

static bool8 ItemfinderCheckForHiddenItems_item_use(const struct MapEvents *events, u8 taskId)
{
    int itemX, itemY;
    s16 playerX, playerY, i, distanceX, distanceY;
    PlayerGetDestCoords(&playerX, &playerY);
    gTasks[taskId].tItemFound_item_use = FALSE;

    for (i = 0; i < events->bgEventCount; i++)
    {
        // Check if there are any hidden items on the current map that haven't been picked up
        if (events->bgEvents[i].kind == BG_EVENT_HIDDEN_ITEM && !FlagGet(events->bgEvents[i].bgUnion.hiddenItem.hiddenItemId + FLAG_HIDDEN_ITEMS_START))
        {
            itemX = (u16)events->bgEvents[i].x + MAP_OFFSET;
            distanceX = itemX - playerX;
            itemY = (u16)events->bgEvents[i].y + MAP_OFFSET;
            distanceY = itemY - playerY;

            // Player can see 7 metatiles on either side horizontally
            // and 5 metatiles on either side vertically
            if (distanceX >= -7 && distanceX <= 7 && distanceY >= -5 && distanceY <= 5)
                SetDistanceOfClosestHiddenItem_item_use(taskId, distanceX, distanceY);
        }
    }

    CheckForHiddenItemsInMapConnection_item_use(taskId);
    if (gTasks[taskId].tItemFound_item_use == TRUE)
        return TRUE;
    else
        return FALSE;
}

static bool8 IsHiddenItemPresentAtCoords_item_use(const struct MapEvents *events, s16 x, s16 y)
{
    u8 bgEventCount = events->bgEventCount;
    const struct BgEvent *bgEvent = events->bgEvents;
    int i;

    for (i = 0; i < bgEventCount; i++)
    {
        if (bgEvent[i].kind == BG_EVENT_HIDDEN_ITEM && x == (u16)bgEvent[i].x && y == (u16)bgEvent[i].y) // hidden item and coordinates matches x and y passed?
        {
            if (!FlagGet(bgEvent[i].bgUnion.hiddenItem.hiddenItemId + FLAG_HIDDEN_ITEMS_START))
                return TRUE;
            else
                return FALSE;
        }
    }
    return FALSE;
}

static bool8 IsHiddenItemPresentInConnection_item_use(const struct MapConnection *connection, int x, int y)
{
    s16 connectionX, connectionY;
    struct MapHeader const *const connectionHeader = GetMapHeaderFromConnection(connection);

// To convert our x/y into coordinates that are relative to the connected map, we must:
//  - Subtract the virtual offset used for the border buffer (MAP_OFFSET).
//  - Subtract the horizontal offset between North/South connections, or the vertical offset for East/West
//  - Account for map size. (0,0) is in the NW corner of our map, so when looking North/West we have to add the height/width of the connected map,
//     and when looking South/East we have to subtract the height/width of our current map.
#define localX_item_use (x - MAP_OFFSET)
#define localY_item_use (y - MAP_OFFSET)
    switch (connection->direction)
    {
    case CONNECTION_NORTH:
        connectionX = localX_item_use - connection->offset;
        connectionY = connectionHeader->mapLayout->height + localY_item_use;
        break;
    case CONNECTION_SOUTH:
        connectionX = localX_item_use - connection->offset;
        connectionY = localY_item_use - gMapHeader.mapLayout->height;
        break;
    case CONNECTION_WEST:
        connectionX = connectionHeader->mapLayout->width + localX_item_use;
        connectionY = localY_item_use - connection->offset;
        break;
    case CONNECTION_EAST:
        connectionX = localX_item_use - gMapHeader.mapLayout->width;
        connectionY = localY_item_use - connection->offset;
        break;
    default:
        return FALSE;
    }
    return IsHiddenItemPresentAtCoords_item_use(connectionHeader->events, connectionX, connectionY);
}

#undef localX_item_use
#undef localY_item_use

static void CheckForHiddenItemsInMapConnection_item_use(u8 taskId)
{
    s16 playerX, playerY;
    s16 x, y;
    s16 width = gMapHeader.mapLayout->width + MAP_OFFSET;
    s16 height = gMapHeader.mapLayout->height + MAP_OFFSET;

    s16 var1 = MAP_OFFSET;
    s16 var2 = MAP_OFFSET;

    PlayerGetDestCoords(&playerX, &playerY);

    // Player can see 7 metatiles on either side horizontally
    // and 5 metatiles on either side vertically
    for (x = playerX - 7; x <= playerX + 7; x++)
    {
        for (y = playerY - 5; y <= playerY + 5; y++)
        {
            if (var1 > x
             || x >= width
             || var2 > y
             || y >= height)
            {
                const struct MapConnection *conn = GetMapConnectionAtPos(x, y);
                if (conn && IsHiddenItemPresentInConnection_item_use(conn, x, y) == TRUE)
                    SetDistanceOfClosestHiddenItem_item_use(taskId, x - playerX, y - playerY);
            }
        }
    }
}

static void SetDistanceOfClosestHiddenItem_item_use(u8 taskId, s16 itemDistanceX, s16 itemDistanceY)
{
    s16 *data = gTasks[taskId].data;
    s16 oldItemAbsX, oldItemAbsY, newItemAbsX, newItemAbsY;

    if (tItemFound_item_use == FALSE)
    {
        // No other items found yet, set this one
        tItemDistanceX_item_use = itemDistanceX;
        tItemDistanceY_item_use = itemDistanceY;
        tItemFound_item_use = TRUE;
    }
    else
    {
        // Other items have been found, check if this one is closer

        // Get absolute x distance of the already-found item
        if (tItemDistanceX_item_use < 0)
            oldItemAbsX = tItemDistanceX_item_use * -1; // WEST
        else
            oldItemAbsX = tItemDistanceX_item_use;      // EAST

        // Get absolute y distance of the already-found item
        if (tItemDistanceY_item_use < 0)
            oldItemAbsY = tItemDistanceY_item_use * -1; // NORTH
        else
            oldItemAbsY = tItemDistanceY_item_use;      // SOUTH

        // Get absolute x distance of the newly-found item
        if (itemDistanceX < 0)
            newItemAbsX = itemDistanceX * -1;
        else
            newItemAbsX = itemDistanceX;

        // Get absolute y distance of the newly-found item
        if (itemDistanceY < 0)
            newItemAbsY = itemDistanceY * -1;
        else
            newItemAbsY = itemDistanceY;


        if (oldItemAbsX + oldItemAbsY > newItemAbsX + newItemAbsY)
        {
            // New item is closer
            tItemDistanceX_item_use = itemDistanceX;
            tItemDistanceY_item_use = itemDistanceY;
        }
        else
        {
            if (oldItemAbsX + oldItemAbsY == newItemAbsX + newItemAbsY
            && (oldItemAbsY > newItemAbsY || (oldItemAbsY == newItemAbsY && tItemDistanceY_item_use < itemDistanceY)))
            {
                // If items are equal distance, use whichever is closer on the Y axis or further south
                tItemDistanceX_item_use = itemDistanceX;
                tItemDistanceY_item_use = itemDistanceY;
            }
        }
    }
}

static u8 GetDirectionToHiddenItem_item_use(s16 itemDistanceX, s16 itemDistanceY)
{
    s16 absX, absY;

    if (itemDistanceX == 0 && itemDistanceY == 0)
        return DIR_NONE; // player is standing on the item.

    // Get absolute X distance.
    if (itemDistanceX < 0)
        absX = itemDistanceX * -1;
    else
        absX = itemDistanceX;

    // Get absolute Y distance.
    if (itemDistanceY < 0)
        absY = itemDistanceY * -1;
    else
        absY = itemDistanceY;

    if (absX > absY)
    {
        if (itemDistanceX < 0)
            return DIR_EAST;
        else
            return DIR_NORTH;
    }
    else
    {
        if (absX < absY)
        {
            if (itemDistanceY < 0)
                return DIR_SOUTH;
            else
                return DIR_WEST;
        }
        if (absX == absY)
        {
            if (itemDistanceY < 0)
                return DIR_SOUTH;
            else
                return DIR_WEST;
        }
        return DIR_NONE; // Unreachable
    }
}

static void PlayerFaceHiddenItem_item_use(u8 direction)
{
    ObjectEventClearHeldMovementIfFinished(&gObjectEvents[GetObjectEventIdByLocalIdAndMap(OBJ_EVENT_ID_PLAYER, 0, 0)]);
    ObjectEventClearHeldMovement(&gObjectEvents[GetObjectEventIdByLocalIdAndMap(OBJ_EVENT_ID_PLAYER, 0, 0)]);
    UnfreezeObjectEvent(&gObjectEvents[GetObjectEventIdByLocalIdAndMap(OBJ_EVENT_ID_PLAYER, 0, 0)]);
    PlayerTurnInPlace(direction);
}

static void Task_HiddenItemNearby_item_use(u8 taskId)
{
    if (ObjectEventCheckHeldMovementStatus(&gObjectEvents[GetObjectEventIdByLocalIdAndMap(OBJ_EVENT_ID_PLAYER, 0, 0)]) == TRUE)
        DisplayItemMessageOnField(taskId, sText_ItemFinderNearby_item_use, Task_CloseItemfinderMessage_item_use);
}

static void Task_StandingOnHiddenItem_item_use(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    if (ObjectEventCheckHeldMovementStatus(&gObjectEvents[GetObjectEventIdByLocalIdAndMap(OBJ_EVENT_ID_PLAYER, 0, 0)]) == TRUE
    || tItemFound_item_use == FALSE)
    {
        // Spin player around on item
        PlayerFaceHiddenItem_item_use(sClockwiseDirections_item_use[tFacingDir_item_use]);
        tItemFound_item_use = TRUE;
        tFacingDir_item_use = (tFacingDir_item_use + 1) & 3;
        tCounter_item_use++;

        if (tCounter_item_use == 4)
            DisplayItemMessageOnField(taskId, sText_ItemFinderOnTop_item_use, Task_CloseItemfinderMessage_item_use);
    }
}

// Undefine itemfinder task data
#undef tItemDistanceX_item_use
#undef tItemDistanceY_item_use
#undef tItemFound_item_use
#undef tCounter_item_use
#undef tItemfinderBeeps_item_use
#undef tFacingDir_item_use

