static u32 GetBallThrowableState_item_use(void)
{
    if (IsBattlerAlive(GetBattlerAtPosition(B_POSITION_OPPONENT_LEFT))
     && IsBattlerAlive(GetBattlerAtPosition(B_POSITION_OPPONENT_RIGHT)))
        return BALL_THROW_UNABLE_TWO_MONS;
    else if (IsPlayerPartyAndPokemonStorageFull() == TRUE)
        return BALL_THROW_UNABLE_NO_ROOM;
    else if (B_SEMI_INVULNERABLE_CATCH >= GEN_4 && (gStatuses3[GetCatchingBattler()] & STATUS3_SEMI_INVULNERABLE))
        return BALL_THROW_UNABLE_SEMI_INVULNERABLE;
    else if (FlagGet(B_FLAG_NO_CATCHING))
        return BALL_THROW_UNABLE_DISABLED_FLAG;

    return BALL_THROW_ABLE;
}

bool32 CanThrowBall(void)
{
    return (GetBallThrowableState_item_use() == BALL_THROW_ABLE);
}

static const u8  sText_CantThrowPokeBall_TwoMons_item_use[] = _("Cannot throw a ball!\nThere are two Pokémon out there!\p");
static const u8  sText_CantThrowPokeBall_SemiInvulnerable_item_use[] = _("Cannot throw a ball!\nThere's no Pokémon in sight!\p");
static const u8  sText_CantThrowPokeBall_Disabled_item_use[] = _("POKé BALLS cannot be used\nright now!\p");
void ItemUseInBattle_PokeBall(u8 taskId)
{
    switch (GetBallThrowableState_item_use())
    {
    case BALL_THROW_ABLE:
    default:
        RemoveBagItem(gSpecialVar_ItemId, 1);
        if (!InBattlePyramid())
            Task_FadeAndCloseBagMenu(taskId);
        else
            CloseBattlePyramidBag(taskId);
        break;
    case BALL_THROW_UNABLE_TWO_MONS:
        if (!InBattlePyramid())
            DisplayItemMessage(taskId, FONT_NORMAL, sText_CantThrowPokeBall_TwoMons_item_use, CloseItemMessage);
        else
            DisplayItemMessageInBattlePyramid(taskId, sText_CantThrowPokeBall_TwoMons_item_use, Task_CloseBattlePyramidBagMessage);
        break;
    case BALL_THROW_UNABLE_NO_ROOM:
        if (!InBattlePyramid())
            DisplayItemMessage(taskId, FONT_NORMAL, gText_BoxFull, CloseItemMessage);
        else
            DisplayItemMessageInBattlePyramid(taskId, gText_BoxFull, Task_CloseBattlePyramidBagMessage);
        break;
    case BALL_THROW_UNABLE_SEMI_INVULNERABLE:
        if (!InBattlePyramid())
            DisplayItemMessage(taskId, FONT_NORMAL, sText_CantThrowPokeBall_SemiInvulnerable_item_use, CloseItemMessage);
        else
            DisplayItemMessageInBattlePyramid(taskId, sText_CantThrowPokeBall_SemiInvulnerable_item_use, Task_CloseBattlePyramidBagMessage);
        break;
    case BALL_THROW_UNABLE_DISABLED_FLAG:
        if (!InBattlePyramid())
            DisplayItemMessage(taskId, FONT_NORMAL, sText_CantThrowPokeBall_Disabled_item_use, CloseItemMessage);
        else
            DisplayItemMessageInBattlePyramid(taskId, sText_CantThrowPokeBall_Disabled_item_use, Task_CloseBattlePyramidBagMessage);
        break;
    }
}

