{
    if (WaitFanfare(FALSE))
    {
        if (gTasks[taskId].data[3] == 0)
            DisplayItemMessage(taskId, FONT_NORMAL, sText_PokeFluteAwakenedMon_item_use, CloseItemMessage);
        else
            DisplayItemMessageOnField(taskId, sText_PokeFluteAwakenedMon_item_use, Task_CloseCantUseKeyItemMessage_item_use);
    }
}

static void Task_PlayPokeFlute_item_use(u8 taskId)
{
    PlayFanfareByFanfareNum(FANFARE_RG_POKE_FLUTE);
    gTasks[taskId].func = Task_DisplayPokeFluteMessage_item_use;
}

void ItemUseOutOfBattle_PokeFlute(u8 taskId)
{
    bool32 wokeSomeoneUp = FALSE;
    u32 i;

    for (i = 0; i < CalculatePlayerPartyCount(); i++)
    {
        if (!ExecuteTableBasedItemEffect(&gPlayerParty[i], ITEM_AWAKENING, i, 0))
            wokeSomeoneUp = TRUE;
    }

    if (wokeSomeoneUp)
    {
        if (gTasks[taskId].data[3] == 0)
            DisplayItemMessage(taskId, FONT_NORMAL, sText_PlayedPokeFlute_item_use, Task_PlayPokeFlute_item_use);
        else
            DisplayItemMessageOnField(taskId, sText_PlayedPokeFlute_item_use, Task_PlayPokeFlute_item_use);
    }
    else
    {
        if (gTasks[taskId].data[3] == 0)
            DisplayItemMessage(taskId, FONT_NORMAL, sText_PlayedPokeFluteCatchy_item_use, CloseItemMessage);
        else
            DisplayItemMessageOnField(taskId, sText_PlayedPokeFluteCatchy_item_use, Task_CloseCantUseKeyItemMessage_item_use);
    }
}

static void ItemUseOnFieldCB_TownMap_item_use(u8 taskId)
{
    LockPlayerFieldControls();
    ScriptContext_SetupScript(EventScript_RegionMap);
    DestroyTask(taskId);
}

void ItemUseOutOfBattle_TownMap(u8 taskId)
{
    if (!gTasks[taskId].tUsingRegisteredKeyItem_item_use)
    {
        sItemUseOnFieldCB = ItemUseOnFieldCB_TownMap_item_use;
        gFieldCallback = FieldCB_UseItemOnField_item_use;
        gBagMenu->newScreenCallback = CB2_ReturnToField;
        Task_FadeAndCloseBagMenu(taskId);
    }
    else
    {
        // TODO: handle key items with callbacks to menus allow to be used by registering them.
        DisplayDadsAdviceCannotUseItemMessage(taskId, gTasks[taskId].tUsingRegisteredKeyItem_item_use);
    }
}

#undef tUsingRegisteredKeyItem_item_use
