static const struct Landmark *const *GetLandmarks(u8 mapSection, u8 id);

const u8 *GetLandmarkName(u8 mapSection, u8 id, u8 count)
{
    const struct Landmark *const *landmarks = GetLandmarks(mapSection, id);

    if (!landmarks)
        return NULL;

    while (1)
    {
        const struct Landmark *landmark = *landmarks;

        if (landmark->flag == 0xFFFF || FlagGet(landmark->flag) == TRUE)
        {
            if (count == 0)
                break;
            else
                count--;
        }

        landmarks++;
        if (!*landmarks)
            return NULL;
    }

    return (*landmarks)->name;
}

static const struct Landmark *const *GetLandmarks(u8 mapSection, u8 id)
{
    u16 i = 0;

    for (; sLandmarkLists_landmark[i].mapSection != MAPSEC_NONE; i++)
    {
        if (sLandmarkLists_landmark[i].mapSection > mapSection)
            return NULL;
        if (sLandmarkLists_landmark[i].mapSection == mapSection)
            break;
    }

    if (sLandmarkLists_landmark[i].mapSection == MAPSEC_NONE)
        return NULL;

    for (; sLandmarkLists_landmark[i].mapSection == mapSection; i++)
    {
        if (sLandmarkLists_landmark[i].id == id)
            return sLandmarkLists_landmark[i].landmarks;
    }

    return NULL;
}
