#include "librfu.h"

static void STWI_intr_timer_librfu_stwi(void);
static u16 STWI_init_librfu_stwi(u8 request);
static s32 STWI_start_Command_librfu_stwi(void);
static void STWI_set_timer_librfu_stwi(u8 unk);
static void STWI_stop_timer_librfu_stwi(void);
