{
    FavorLadyOpenBagMenu();
}

static bool8 DoesFavorLadyLikeItem_lilycove_lady(u16 itemId)
{
    u8 numItems;
    u8 i;
    bool8 likedItem;

    sFavorLadyPtr_lilycove_lady = &gSaveBlock1Ptr->lilycoveLady.favor;
    numItems = GetNumAcceptedItems_lilycove_lady(sFavorLadyAcceptedItemLists[sFavorLadyPtr_lilycove_lady->favorId]);
    sFavorLadyPtr_lilycove_lady->state = LILYCOVE_LADY_STATE_COMPLETED;
    BufferItemName_lilycove_lady(gStringVar2, itemId);
    sFavorLadyPtr_lilycove_lady->itemId = itemId;
    SetFavorLadyPlayerName_lilycove_lady(gSaveBlock2Ptr->playerName, sFavorLadyPtr_lilycove_lady->playerName);
    sFavorLadyPtr_lilycove_lady->language = gGameLanguage;
    likedItem = FALSE;
    for (i = 0; i < numItems; i ++)
    {
        if (sFavorLadyAcceptedItemLists[sFavorLadyPtr_lilycove_lady->favorId][i] == itemId)
        {
            likedItem = TRUE;
            sFavorLadyPtr_lilycove_lady->numItemsGiven++;
            sFavorLadyPtr_lilycove_lady->likedItem = TRUE;
            if (sFavorLadyPtr_lilycove_lady->bestItem == itemId)
                sFavorLadyPtr_lilycove_lady->numItemsGiven = LILYCOVE_LADY_GIFT_THRESHOLD;
            break;
        }
        sFavorLadyPtr_lilycove_lady->likedItem = FALSE;
    }
    return likedItem;
}

bool8 Script_DoesFavorLadyLikeItem(void)
{
    return DoesFavorLadyLikeItem_lilycove_lady(gSpecialVar_ItemId);
}

bool8 IsFavorLadyThresholdMet(void)
{
    u8 numItemsGiven;

    sFavorLadyPtr_lilycove_lady = &gSaveBlock1Ptr->lilycoveLady.favor;
    numItemsGiven = sFavorLadyPtr_lilycove_lady->numItemsGiven;
    return numItemsGiven < LILYCOVE_LADY_GIFT_THRESHOLD ? FALSE : TRUE;
}

