static void QuizLadyPickQuestion_lilycove_lady(void)
{
    u8 questionId;
    u8 i;

    questionId = Random() % ARRAY_COUNT(sQuizLadyQuizQuestions);
    for (i = 0; i < QUIZ_QUESTION_LEN; i ++)
        sQuizLadyPtr_lilycove_lady->question[i] = sQuizLadyQuizQuestions[questionId][i];
    sQuizLadyPtr_lilycove_lady->correctAnswer = sQuizLadyQuizAnswers[questionId];
    sQuizLadyPtr_lilycove_lady->prize = sQuizLadyPrizes[questionId];
    sQuizLadyPtr_lilycove_lady->questionId = questionId;
    sQuizLadyPtr_lilycove_lady->playerName[0] = EOS;
}

static void InitLilycoveQuizLady_lilycove_lady(void)
{
    u8 i;

    sQuizLadyPtr_lilycove_lady = &gSaveBlock1Ptr->lilycoveLady.quiz;
    sQuizLadyPtr_lilycove_lady->id = LILYCOVE_LADY_QUIZ;
    sQuizLadyPtr_lilycove_lady->state = LILYCOVE_LADY_STATE_READY;

    for (i = 0; i < QUIZ_QUESTION_LEN; i ++)
        sQuizLadyPtr_lilycove_lady->question[i] = EC_EMPTY_WORD;

    sQuizLadyPtr_lilycove_lady->correctAnswer = EC_EMPTY_WORD;
    sQuizLadyPtr_lilycove_lady->playerAnswer = EC_EMPTY_WORD;

    for (i = 0; i < TRAINER_ID_LENGTH; i ++)
        sQuizLadyPtr_lilycove_lady->playerTrainerId[i] = 0;

    sQuizLadyPtr_lilycove_lady->prize = ITEM_NONE;
    sQuizLadyPtr_lilycove_lady->waitingForChallenger = FALSE;
    sQuizLadyPtr_lilycove_lady->prevQuestionId = ARRAY_COUNT(sQuizLadyQuizQuestions);
    sQuizLadyPtr_lilycove_lady->language = gGameLanguage;
    QuizLadyPickQuestion_lilycove_lady();
}

static void ResetQuizLadyForRecordMix_lilycove_lady(void)
{
    sQuizLadyPtr_lilycove_lady = &gSaveBlock1Ptr->lilycoveLady.quiz;
    sQuizLadyPtr_lilycove_lady->id = LILYCOVE_LADY_QUIZ;
    sQuizLadyPtr_lilycove_lady->state = LILYCOVE_LADY_STATE_READY;
    sQuizLadyPtr_lilycove_lady->waitingForChallenger = FALSE;
    sQuizLadyPtr_lilycove_lady->playerAnswer = EC_EMPTY_WORD;
}

u8 GetQuizLadyState(void)
{
    sQuizLadyPtr_lilycove_lady = &gSaveBlock1Ptr->lilycoveLady.quiz;
    if (sQuizLadyPtr_lilycove_lady->state == LILYCOVE_LADY_STATE_PRIZE)
        return LILYCOVE_LADY_STATE_PRIZE;
    else if (sQuizLadyPtr_lilycove_lady->state == LILYCOVE_LADY_STATE_COMPLETED)
        return LILYCOVE_LADY_STATE_COMPLETED;
    else
        return LILYCOVE_LADY_STATE_READY;
}

u8 GetQuizAuthor(void)
{
    s32 i, j;
    u8 authorNameId;
    struct LilycoveLadyQuiz *quiz = &gSaveBlock1Ptr->lilycoveLady.quiz;

    if (IsEasyChatAnswerUnlocked(quiz->correctAnswer) == FALSE)
    {
        i = quiz->questionId;
        do
        {
            if (++i >= (int)ARRAY_COUNT(sQuizLadyQuizQuestions))
                i = 0;
        } while (IsEasyChatAnswerUnlocked(sQuizLadyQuizAnswers[i]) == FALSE);

        for (j = 0; j < QUIZ_QUESTION_LEN; j++)
            quiz->question[j] = sQuizLadyQuizQuestions[i][j];
        quiz->correctAnswer = sQuizLadyQuizAnswers[i];
        quiz->prize = sQuizLadyPrizes[i];
        quiz->questionId = i;
        quiz->playerName[0] = EOS;
    }
    authorNameId = BufferQuizAuthorName_lilycove_lady();
    if (authorNameId == QUIZ_AUTHOR_NAME_LADY)
        return QUIZ_AUTHOR_LADY;
    else if (authorNameId == QUIZ_AUTHOR_NAME_OTHER_PLAYER || IsQuizTrainerIdNotPlayer_lilycove_lady())
        return QUIZ_AUTHOR_OTHER_PLAYER;
    else
        return QUIZ_AUTHOR_PLAYER;
}

static u8 BufferQuizAuthorName_lilycove_lady(void)
{
    u8 authorNameId;
    u8 nameLen;
    u8 i;

    authorNameId = QUIZ_AUTHOR_NAME_PLAYER;
    sQuizLadyPtr_lilycove_lady = &gSaveBlock1Ptr->lilycoveLady.quiz;
    if (sQuizLadyPtr_lilycove_lady->playerName[0] == EOS)
    {
        StringCopy_PlayerName(gStringVar1, COMPOUND_STRING("Lady"));
        authorNameId = QUIZ_AUTHOR_NAME_LADY;
    }
    else
    {
        StringCopy_PlayerName(gStringVar1, sQuizLadyPtr_lilycove_lady->playerName);
        ConvertInternationalString(gStringVar1, sQuizLadyPtr_lilycove_lady->language);
        nameLen = GetPlayerNameLength_lilycove_lady(sQuizLadyPtr_lilycove_lady->playerName);
        if (nameLen == GetPlayerNameLength_lilycove_lady(gSaveBlock2Ptr->playerName))
        {
            u8 *name = sQuizLadyPtr_lilycove_lady->playerName;
            for (i = 0; i < nameLen; i++)
            {
                name = sQuizLadyPtr_lilycove_lady->playerName;
                if (name[i] != gSaveBlock2Ptr->playerName[i])
                {
                    authorNameId = QUIZ_AUTHOR_NAME_OTHER_PLAYER;
                    break;
                }
            }
        }

    }
    return authorNameId;
}

static bool8 IsQuizTrainerIdNotPlayer_lilycove_lady(void)
{
    bool8 notPlayer;
    u8 i;

    sQuizLadyPtr_lilycove_lady = &gSaveBlock1Ptr->lilycoveLady.quiz;
    notPlayer = FALSE;
    for (i = 0; i < TRAINER_ID_LENGTH; i++)
    {
        if (sQuizLadyPtr_lilycove_lady->playerTrainerId[i] != gSaveBlock2Ptr->playerTrainerId[i])
        {
            notPlayer = TRUE;
            break;
        }
    }
    return notPlayer;
}

