static void ResetBlockSend_link(void)
{
    sBlockSend_link.active = FALSE;
    sBlockSend_link.pos = 0;
    sBlockSend_link.size = 0;
    sBlockSend_link.src = NULL;
}

static bool32 InitBlockSend_link(const void *src, size_t size)
{
    if (sBlockSend_link.active)
    {
        return FALSE;
    }
    sBlockSend_link.multiplayerId = GetMultiplayerId();
    sBlockSend_link.active = TRUE;
    sBlockSend_link.size = size;
    sBlockSend_link.pos = 0;
    if (size > BLOCK_BUFFER_SIZE)
    {
        sBlockSend_link.src = src;
    }
    else
    {
        if (src != gBlockSendBuffer)
            memcpy(gBlockSendBuffer, src, size);

        sBlockSend_link.src = gBlockSendBuffer;
    }
    BuildSendCmd_link(LINKCMD_INIT_BLOCK);
    gLinkCallback = LinkCB_BlockSendBegin_link;
    sBlockSendDelayCounter_link = 0;
    return TRUE;
}

static void LinkCB_BlockSendBegin_link(void)
{
    if (++sBlockSendDelayCounter_link > 2)
        gLinkCallback = LinkCB_BlockSend_link;
}

static void LinkCB_BlockSend_link(void)
{
    int i;
    const u8 *src;

    src = sBlockSend_link.src;
    gSendCmd[0] = LINKCMD_CONT_BLOCK;
    for (i = 0; i < CMD_LENGTH - 1; i++)
    {
        gSendCmd[i + 1] = (src[sBlockSend_link.pos + i * 2 + 1] << 8) | src[sBlockSend_link.pos + i * 2];
    }
    sBlockSend_link.pos += 14;
    if (sBlockSend_link.size <= sBlockSend_link.pos)
    {
        sBlockSend_link.active = FALSE;
        gLinkCallback = LinkCB_BlockSendEnd_link;
    }
}

static void LinkCB_BlockSendEnd_link(void)
{
    gLinkCallback = NULL;
}

