void ResetLinkRfuGFLayer(void)
{
    s32 i;
    u8 errorState = gRfu.errorState;
    CpuFill16(0, &gRfu, sizeof(gRfu));
    gRfu.errorState = errorState;
    gRfu.parentChild = 0xFF;
    if (gRfu.errorState != RFU_ERROR_STATE_IGNORE)
        gRfu.errorState = RFU_ERROR_STATE_NONE;
    for (i = 0; i < MAX_RFU_PLAYERS; i++)
        ResetSendDataManager_link_rfu_2(&gRfu.recvBlock[i]);
    ResetSendDataManager_link_rfu_2(&gRfu.sendBlock);
    RfuRecvQueue_Reset(&gRfu.recvQueue);
    RfuSendQueue_Reset(&gRfu.sendQueue);
    CpuFill16(0, gSendCmd, sizeof gSendCmd);
    CpuFill16(0, gRecvCmds, sizeof gRecvCmds);
    CpuFill16(0, gLinkPlayers, sizeof gLinkPlayers);
}

void InitRFU(void)
{
    IntrFunc serialIntr = gIntrTable[1];
    IntrFunc timerIntr = gIntrTable[2];
    InitRFUAPI();
    rfu_REQ_stopMode();
    rfu_waitREQComplete();
    REG_IME = 0;
    gIntrTable[1] = serialIntr;
    gIntrTable[2] = timerIntr;
    REG_IME = INTR_FLAG_VBLANK;
}

void InitRFUAPI(void)
{
    if (!rfu_initializeAPI((void *)gRfuAPIBuffer, sizeof(gRfuAPIBuffer), &gIntrTable[1], TRUE))
    {
        gLinkType = 0;
        ClearSavedLinkPlayers();
        RfuSetIgnoreError(FALSE);
        ResetLinkRfuGFLayer();
        rfu_setTimerInterrupt(3, &gIntrTable[2]);
    }
}

static void Task_ParentSearchForChildren_link_rfu_2(u8 taskId)
{
    UpdateChildStatuses_link_rfu_2();
    switch (gRfu.state)
    {
    case RFUSTATE_INIT_link_rfu_2:
        rfu_LMAN_initializeRFU(&sRfuReqConfig_link_rfu_2);
        gRfu.state = RFUSTATE_INIT_END_link_rfu_2;
        gTasks[taskId].data[1] = 1;
        break;
    case RFUSTATE_INIT_END_link_rfu_2:
        break;
    case RFUSTATE_PARENT_CONNECT_link_rfu_2:
        rfu_LMAN_establishConnection(gRfu.parentChild, 0, 240, (u16 *)sAcceptedSerialNos_link_rfu_2);
        gRfu.state = RFUSTATE_PARENT_CONNECT_END_link_rfu_2;
        gTasks[taskId].data[1] = 6;
        break;
    case RFUSTATE_PARENT_CONNECT_END_link_rfu_2:
        break;
    case RFUSTATE_STOP_MANAGER_link_rfu_2:
        rfu_LMAN_stopManager(FALSE);
        gRfu.state = RFUSTATE_STOP_MANAGER_END_link_rfu_2;
        break;
    case RFUSTATE_STOP_MANAGER_END_link_rfu_2:
        break;
    case RFUSTATE_PARENT_FINALIZE_link_rfu_2:
        gRfu.parentFinished = FALSE;
        rfu_LMAN_setMSCCallback(MSCCallback_Parent_link_rfu_2);
        InitChildRecvBuffers_link_rfu_2();
        InitParentSendData_link_rfu_2();
        gRfu.state = RFUSTATE_FINALIZED_link_rfu_2;
        gTasks[taskId].data[1] = 8;
        CreateTask(Task_PlayerExchange_link_rfu_2, 5);
        DestroyTask(taskId);
        break;
    }
}

s32 Rfu_GetIndexOfNewestChild(u8 bits)
{
    return sPlayerBitsToNewChildIdx_link_rfu_2[bits];
}

static void SetLinkPlayerIdsFromSlots_link_rfu_2(s32 baseSlots, s32 addSlots)
{
    u8 i;
    u8 baseId = 1;
    s32 baseSlotsCopy = baseSlots;
    s32 newId = 0;
    if (addSlots == -1)
    {
        // Initialize
        for (i = 0; i < RFU_CHILD_MAX; baseSlots >>= 1, i++)
        {
            if (baseSlots & 1)
            {
                gRfu.linkPlayerIdx[i] = baseId;
                baseId++;
            }
        }
    }
    else
    {
        // Clear id for any empty slot
        for (i = 0; i < RFU_CHILD_MAX; baseSlotsCopy >>= 1, i++)
        {
            if (!(baseSlotsCopy & 1))
                gRfu.linkPlayerIdx[i] = 0;
        }

        // Get starting id by checking existing slots
        for (baseId = RFU_CHILD_MAX; baseId != 0; baseId--)
        {
            for (i = 0; i < RFU_CHILD_MAX && gRfu.linkPlayerIdx[i] != baseId; i++)
                ;
            if (i == RFU_CHILD_MAX)
                newId = baseId;
        }

        // Set id for new slots
        for (addSlots &= ~baseSlots, i = 0; i < RFU_CHILD_MAX; addSlots >>= 1, i++)
        {
            if (addSlots & 1)
                gRfu.linkPlayerIdx[i] = newId++;
        }
    }
}

static void Task_ChildSearchForParent_link_rfu_2(u8 taskId)
{
    switch (gRfu.state)
    {
    case RFUSTATE_INIT_link_rfu_2:
        rfu_LMAN_initializeRFU((INIT_PARAM *)&sRfuReqConfigTemplate_link_rfu_2);
        gRfu.state = RFUSTATE_INIT_END_link_rfu_2;
        gTasks[taskId].data[1] = 1;
        break;
    case RFUSTATE_INIT_END_link_rfu_2:
        break;
    case RFUSTATE_CHILD_CONNECT_link_rfu_2:
        rfu_LMAN_establishConnection(gRfu.parentChild, 0, 240, (u16 *)sAcceptedSerialNos_link_rfu_2);
        gRfu.state = RFUSTATE_CHILD_CONNECT_END_link_rfu_2;
        gTasks[taskId].data[1] = 7;
        break;
    case RFUSTATE_CHILD_CONNECT_END_link_rfu_2:
        break;
    case RFUSTATE_RECONNECTED_link_rfu_2:
        gTasks[taskId].data[1] = 10;
        break;
    case RFUSTATE_CHILD_TRY_JOIN_link_rfu_2:
        switch (GetJoinGroupStatus_link_rfu_2())
        {
        case RFU_STATUS_JOIN_GROUP_OK:
            gRfu.state = RFUSTATE_CHILD_JOINED_link_rfu_2;
            break;
        case RFU_STATUS_JOIN_GROUP_NO:
        case RFU_STATUS_LEAVE_GROUP:
            rfu_LMAN_requestChangeAgbClockMaster();
            gRfu.disconnectMode = RFU_DISCONNECT_NORMAL;
            DestroyTask(taskId);
            break;
        }
        break;
    case RFUSTATE_CHILD_JOINED_link_rfu_2:
    {
        u8 bmChildSlot = 1 << gRfu.childSlot;
        rfu_clearSlot(TYPE_NI_SEND | TYPE_NI_RECV, gRfu.childSlot);
        rfu_setRecvBuffer(TYPE_UNI, gRfu.childSlot, gRfu.childRecvQueue, sizeof(gRfu.childRecvQueue));
        rfu_UNI_setSendData(bmChildSlot, gRfu.childSendBuffer,  sizeof(gRfu.childSendBuffer));
        gTasks[taskId].data[1] = 8;
        DestroyTask(taskId);
        if (sRfuDebug_link_rfu_2.childJoinCount == 0)
        {
            Debug_PrintEmpty_link_rfu_2();
            sRfuDebug_link_rfu_2.childJoinCount++;
        }
        CreateTask(Task_PlayerExchange_link_rfu_2, 5);
        break;
    }
    }
}

static void InitChildRecvBuffers_link_rfu_2(void)
{
    u8 i;
    u8 acceptSlot = lman.acceptSlot_flag;
    for (i = 0; i < RFU_CHILD_MAX; i++)
    {
        if (acceptSlot & 1)
        {
            rfu_setRecvBuffer(TYPE_UNI, i, gRfu.childRecvBuffer[i], sizeof(gRfu.childRecvBuffer[0]));
            rfu_clearSlot(TYPE_UNI_SEND | TYPE_UNI_RECV, i);
        }
        acceptSlot >>= 1;
    }
}

static void InitParentSendData_link_rfu_2(void)
{
    u8 acceptSlot = lman.acceptSlot_flag;
    rfu_UNI_setSendData(acceptSlot, gRfu.recvCmds, sizeof(gRfu.recvCmds));
    gRfu.parentSendSlot = Rfu_GetIndexOfNewestChild(acceptSlot);
    gRfu.parentSlots = acceptSlot;
    SetLinkPlayerIdsFromSlots_link_rfu_2(acceptSlot, -1);
    gRfu.parentChild = MODE_PARENT;
}

#define tConnectingForChat_link_rfu_2 data[7]

static void Task_UnionRoomListen_link_rfu_2(u8 taskId)
{
    if (GetHostRfuGameData()->activity == (ACTIVITY_PLYRTALK | IN_UNION_ROOM) && RfuGetStatus() == RFU_STATUS_NEW_CHILD_DETECTED)
    {
        rfu_REQ_disconnect(lman.acceptSlot_flag);
        rfu_waitREQComplete();
        RfuSetStatus(RFU_STATUS_OK, 0);
    }
    switch (gRfu.state)
    {
    case RFUSTATE_INIT_link_rfu_2:
        rfu_LMAN_initializeRFU(&sRfuReqConfig_link_rfu_2);
        gRfu.state = RFUSTATE_INIT_END_link_rfu_2;
        gTasks[taskId].data[1] = 1;
        break;
    case RFUSTATE_INIT_END_link_rfu_2:
        break;
    case RFUSTATE_UR_CONNECT_link_rfu_2:
        rfu_LMAN_establishConnection(MODE_P_C_SWITCH, 0, 240, (u16 *)sAcceptedSerialNos_link_rfu_2);
        rfu_LMAN_setMSCCallback(MSCCallback_Child_link_rfu_2);
        gRfu.state = RFUSTATE_UR_CONNECT_END_link_rfu_2;
        break;
    case RFUSTATE_UR_CONNECT_END_link_rfu_2:
        break;
    case RFUSTATE_UR_PLAYER_EXCHANGE_link_rfu_2:
        if (rfu_UNI_setSendData(1 << gRfu.childSlot, gRfu.childSendBuffer, sizeof(gRfu.childSendBuffer)) == 0)
        {
            gRfu.parentChild = MODE_CHILD;
            DestroyTask(taskId);
            if (gTasks[taskId].tConnectingForChat_link_rfu_2)
                CreateTask(Task_PlayerExchangeChat_link_rfu_2, 1);
            else
                CreateTask(Task_PlayerExchange_link_rfu_2, 5);
        }
        break;
    case RFUSTATE_UR_STOP_MANAGER_link_rfu_2:
        rfu_LMAN_stopManager(FALSE);
        gRfu.state = RFUSTATE_UR_STOP_MANAGER_END_link_rfu_2;
        break;
    case RFUSTATE_UR_STOP_MANAGER_END_link_rfu_2:
        break;
    case RFUSTATE_UR_FINALIZE_link_rfu_2:
        gRfu.parentFinished = FALSE;
        rfu_LMAN_setMSCCallback(MSCCallback_Parent_link_rfu_2);
        UpdateGameData_GroupLockedIn(TRUE);
        InitChildRecvBuffers_link_rfu_2();
        InitParentSendData_link_rfu_2();
        gRfu.state = RFUSTATE_FINALIZED_link_rfu_2;
        gTasks[taskId].data[1] = 8;
        gRfu.parentChild = MODE_PARENT;
        CreateTask(Task_PlayerExchange_link_rfu_2, 5);
        gRfu.playerExchangeActive = TRUE;
        DestroyTask(taskId);
        break;
    }
}

