// Argument is provided by the RFU and is unused.
static void MSCCallback_Child_link_rfu_2(u16 REQ_commandID)
{
    s32 i;

    for (i = 0; i < COMM_SLOT_LENGTH; i++)
        gRfu.childSendBuffer[i] = 0;

    rfu_REQ_recvData();
    rfu_waitREQComplete();
    if (gRfuSlotStatusUNI[gRfu.childSlot]->recv.newDataFlag)
    {
        gRfu.childSendCount++;
        RfuRecvQueue_Enqueue(&gRfu.recvQueue, gRfu.childRecvQueue);
        sRfuDebug_link_rfu_2.recvCount++;
        UpdateBackupQueue_link_rfu_2();
        rfu_UNI_readySendData(gRfu.childSlot);
        rfu_UNI_clearRecvNewDataFlag(gRfu.childSlot);
    }
    rfu_LMAN_REQ_sendData(TRUE);
}

// Argument is provided by the RFU and is unused.
static void MSCCallback_Parent_link_rfu_2(u16 REQ_commandID)
{
    gRfu.parentFinished = TRUE;
}

void LinkRfu_Shutdown(void)
{
    u8 i;

    rfu_LMAN_powerDownRFU();
    if (gRfu.parentChild == MODE_PARENT)
    {
        // Stop parent searching for children
        if (FuncIsActiveTask(Task_ParentSearchForChildren_link_rfu_2) == TRUE)
        {
            DestroyTask(gRfu.searchTaskId);
            ResetLinkRfuGFLayer();
        }
    }
    else if (gRfu.parentChild == MODE_CHILD)
    {
        // Stop child searching for parent
        if (FuncIsActiveTask(Task_ChildSearchForParent_link_rfu_2) == TRUE)
        {
            DestroyTask(gRfu.searchTaskId);
            ResetLinkRfuGFLayer();
        }
    }
    else if (gRfu.parentChild == MODE_P_C_SWITCH)
    {
        // Stop parent-child switching mode (union room)
        if (FuncIsActiveTask(Task_UnionRoomListen_link_rfu_2) == TRUE)
        {
            DestroyTask(gRfu.searchTaskId);
            ResetLinkRfuGFLayer();
        }
    }

    // Destroy additional tasks
    for (i = 0; i < ARRAY_COUNT(sShutdownTasks_link_rfu_2); i++)
    {
        if (FuncIsActiveTask(sShutdownTasks_link_rfu_2[i]) == TRUE)
            DestroyTask(FindTaskIdByFunc(sShutdownTasks_link_rfu_2[i]));
    }
}

static void CreateTask_ParentSearchForChildren_link_rfu_2(void)
{
    gRfu.searchTaskId = CreateTask(Task_ParentSearchForChildren_link_rfu_2, 1);
}

// If no parent ID (or if child connection not ready) can't reconnect with parent yet
static bool8 CanTryReconnectParent_link_rfu_2(void)
{
    if (gRfu.state == RFUSTATE_CHILD_CONNECT_END_link_rfu_2 && gRfu.parentId)
        return TRUE;
    return FALSE;
}

static bool32 TryReconnectParent_link_rfu_2(void)
{
    if (gRfu.state == RFUSTATE_CHILD_CONNECT_END_link_rfu_2 && !rfu_LMAN_CHILD_connectParent(gRfuLinkStatus->partner[gRfu.reconnectParentId].id, 240))
    {
        gRfu.state = RFUSTATE_RECONNECTED_link_rfu_2;
        return TRUE;
    }
    return FALSE;
}

static void CreateTask_ChildSearchForParent_link_rfu_2(void)
{
    gRfu.searchTaskId = CreateTask(Task_ChildSearchForParent_link_rfu_2, 1);
}

