// RFU equivalent of LinkCB_WaitCloseLink
static void WaitAllReadyToCloseLink_link_rfu_2(void)
{
    s32 i;
    u8 playerCount = gRfu.playerCount;
    s32 count = 0;

    // Wait for all players to be ready
    for (i = 0; i < MAX_RFU_PLAYERS; i++)
    {
        if (gRfu.readyCloseLink[i])
            count++;
    }
    if (count == playerCount)
    {
        // All ready, close link
        gBattleTypeFlags &= ~BATTLE_TYPE_LINK_IN_BATTLE;
        if (gRfu.parentChild == MODE_CHILD)
        {
            gRfu.errorState = RFU_ERROR_STATE_DISCONNECTING;
            TryDisconnectRfu_link_rfu_2();
        }
        else
        {
            gRfu.callback = TryDisconnectRfu_link_rfu_2;
        }
    }
}

static void SendReadyCloseLink_link_rfu_2(void)
{
    if (gSendCmd[0] == 0 && !gRfu.playerExchangeActive)
    {
        RfuPrepareSendBuffer_link_rfu_2(RFUCMD_READY_CLOSE_LINK);
        gRfu.callback = WaitAllReadyToCloseLink_link_rfu_2;
    }
}

static void Task_TryReadyCloseLink_link_rfu_2(u8 taskId)
{
    if (gRfu.callback == NULL)
    {
        gRfu.stopNewConnections = TRUE;
        gRfu.callback = SendReadyCloseLink_link_rfu_2;
        DestroyTask(taskId);
    }
}

void Rfu_SetCloseLinkCallback(void)
{
    if (!FuncIsActiveTask(Task_TryReadyCloseLink_link_rfu_2))
        CreateTask(Task_TryReadyCloseLink_link_rfu_2, 5);
}

static void SendReadyExitStandbyUntilAllReady_link_rfu_2(void)
{
    u8 playerCount;
    u8 i;

    if (GetMultiplayerId() != 0)
    {
        if (gRfu.recvQueue.count == 0 && gRfu.resendExitStandbyTimer > 60)
        {
            RfuPrepareSendBuffer_link_rfu_2(RFUCMD_READY_EXIT_STANDBY);
            gRfu.resendExitStandbyTimer = 0;
        }
    }
    playerCount = GetLinkPlayerCount();
    for (i = 0; i < playerCount; i++)
    {
        if (!gRfu.readyExitStandby[i])
            break;
    }
    if (i == playerCount)
    {
        for (i = 0; i < MAX_RFU_PLAYERS; i++)
            gRfu.readyExitStandby[i] = FALSE;
        gRfu.allReadyNum++;
        gRfu.callback = NULL;
    }
    gRfu.resendExitStandbyTimer++;
}

static void LinkLeaderReadyToExitStandby_link_rfu_2(void)
{
    if (gRfu.recvQueue.count == 0 && gSendCmd[0] == 0)
    {
        RfuPrepareSendBuffer_link_rfu_2(RFUCMD_READY_EXIT_STANDBY);
        gRfu.callback = SendReadyExitStandbyUntilAllReady_link_rfu_2;
    }
}

// RFU equivalent of LinkCB_Standby and LinkCB_StandbyForAll
static void Rfu_LinkStandby_link_rfu_2(void)
{
    u8 i;
    u8 playerCount;

    if (GetMultiplayerId() != 0)
    {
        // Not link leader, send exit standby when ready
        if (gRfu.recvQueue.count == 0 && gSendCmd[0] == 0)
        {
            RfuPrepareSendBuffer_link_rfu_2(RFUCMD_READY_EXIT_STANDBY);
            gRfu.callback = SendReadyExitStandbyUntilAllReady_link_rfu_2;
        }
    }
    else
    {
        // Link leader, wait for all members to send exit ready
        playerCount = GetLinkPlayerCount();
        for (i = 1; i < playerCount; i++)
        {
            if (!gRfu.readyExitStandby[i])
                break;
        }
        if (i == playerCount)
        {
            if (gRfu.recvQueue.count == 0 && gSendCmd[0] == 0)
            {
                RfuPrepareSendBuffer_link_rfu_2(RFUCMD_READY_EXIT_STANDBY);
                gRfu.callback = LinkLeaderReadyToExitStandby_link_rfu_2;
            }
        }
    }
}

void Rfu_SetLinkStandbyCallback(void)
{
    if (gRfu.callback == NULL)
    {
        gRfu.callback = Rfu_LinkStandby_link_rfu_2;
        gRfu.resendExitStandbyTimer = 0;
    }
}

