#define STATUS_INDICATOR_ACTIVE_link_rfu_3 0x1234 // Used to validate active indicator

void CreateWirelessStatusIndicatorSprite(u8 x, u8 y)
{
    u8 sprId;

    if (x == 0 && y == 0)
    {
        x = 231;
        y = 8;
    }
    if (gRfuLinkStatus->parentChild == MODE_PARENT)
    {
        sprId = CreateSprite(&sWirelessStatusIndicatorSpriteTemplate_link_rfu_3, x, y, 0);
        gSprites[sprId].sValidator_link_rfu_3 = STATUS_INDICATOR_ACTIVE_link_rfu_3;
        gSprites[sprId].sTileStart_link_rfu_3 = GetSpriteTileStartByTag(sWirelessStatusIndicatorSpriteSheet_link_rfu_3.tag);
        gSprites[sprId].invisible = TRUE;
        gWirelessStatusIndicatorSpriteId = sprId;
    }
    else
    {
        gWirelessStatusIndicatorSpriteId = CreateSprite(&sWirelessStatusIndicatorSpriteTemplate_link_rfu_3, x, y, 0);
        gSprites[gWirelessStatusIndicatorSpriteId].sValidator_link_rfu_3 = STATUS_INDICATOR_ACTIVE_link_rfu_3;
        gSprites[gWirelessStatusIndicatorSpriteId].sTileStart_link_rfu_3 = GetSpriteTileStartByTag(sWirelessStatusIndicatorSpriteSheet_link_rfu_3.tag);
        gSprites[gWirelessStatusIndicatorSpriteId].invisible = TRUE;
    }
}

void DestroyWirelessStatusIndicatorSprite(void)
{
    if (gSprites[gWirelessStatusIndicatorSpriteId].sValidator_link_rfu_3 == STATUS_INDICATOR_ACTIVE_link_rfu_3)
    {
        gSprites[gWirelessStatusIndicatorSpriteId].sValidator_link_rfu_3 = 0;
        DestroySprite(&gSprites[gWirelessStatusIndicatorSpriteId]);
        gMain.oamBuffer[125] = gDummyOamData;
        CpuCopy16(&gDummyOamData, (struct OamData *)OAM + 125, sizeof(struct OamData));
    }
}

void LoadWirelessStatusIndicatorSpriteGfx(void)
{
    if (GetSpriteTileStartByTag(sWirelessStatusIndicatorSpriteSheet_link_rfu_3.tag) == 0xFFFF)
        LoadCompressedSpriteSheet(&sWirelessStatusIndicatorSpriteSheet_link_rfu_3);
    LoadSpritePalette(&sWirelessStatusIndicatorSpritePalette_link_rfu_3);
    gWirelessStatusIndicatorSpriteId = SPRITE_NONE;
}

static u8 GetParentSignalStrength_link_rfu_3(void)
{
    u8 i;
    u8 flags = gRfuLinkStatus->connSlotFlag;
    for (i = 0; i < RFU_CHILD_MAX; i++)
    {
        if (flags & 1)
            return gRfuLinkStatus->strength[i];
        flags >>= 1;
    }
    return 0;
}

static void SetWirelessStatusIndicatorAnim_link_rfu_3(struct Sprite *sprite, s32 animNum)
{
    if (sprite->sCurrAnimNum_link_rfu_3 != animNum)
    {
        sprite->sCurrAnimNum_link_rfu_3 = animNum;
        sprite->sFrameDelay_link_rfu_3 = 0;
        sprite->sFrameIdx_link_rfu_3 = 0;
    }
}

void UpdateWirelessStatusIndicatorSprite(void)
{
    if (gWirelessStatusIndicatorSpriteId != SPRITE_NONE && gSprites[gWirelessStatusIndicatorSpriteId].sValidator_link_rfu_3 == STATUS_INDICATOR_ACTIVE_link_rfu_3)
    {
        struct Sprite *sprite = &gSprites[gWirelessStatusIndicatorSpriteId];
        u8 signalStrength = RFU_LINK_ICON_LEVEL4_MAX;
        u8 i = 0;

        // Get weakest signal strength
        if (gRfuLinkStatus->parentChild == MODE_PARENT)
        {
            for (i = 0; i < GetLinkPlayerCount() - 1; i++)
            {
                if (signalStrength >= GetConnectedChildStrength_link_rfu_3(i + 1))
                    signalStrength = GetConnectedChildStrength_link_rfu_3(i + 1);
            }
        }
        else
        {
            signalStrength = GetParentSignalStrength_link_rfu_3();
        }

        // Set signal strength sprite anim number
        if (IsRfuRecoveringFromLinkLoss() == TRUE)
            sprite->sNextAnimNum_link_rfu_3 = WIRELESS_STATUS_ANIM_ERROR_link_rfu_3;
        else if (signalStrength <= RFU_LINK_ICON_LEVEL1_MAX)
            sprite->sNextAnimNum_link_rfu_3 = WIRELESS_STATUS_ANIM_SEARCHING_link_rfu_3;
        else if (signalStrength >= RFU_LINK_ICON_LEVEL2_MIN && signalStrength <= RFU_LINK_ICON_LEVEL2_MAX)
            sprite->sNextAnimNum_link_rfu_3 = WIRELESS_STATUS_ANIM_1_BAR_link_rfu_3;
        else if (signalStrength >= RFU_LINK_ICON_LEVEL3_MIN && signalStrength <= RFU_LINK_ICON_LEVEL3_MAX)
            sprite->sNextAnimNum_link_rfu_3 = WIRELESS_STATUS_ANIM_2_BARS_link_rfu_3;
        else if (signalStrength >= RFU_LINK_ICON_LEVEL4_MIN)
            sprite->sNextAnimNum_link_rfu_3 = WIRELESS_STATUS_ANIM_3_BARS_link_rfu_3;

        if (sprite->sNextAnimNum_link_rfu_3 != sprite->sSavedAnimNum_link_rfu_3)
        {
            SetWirelessStatusIndicatorAnim_link_rfu_3(sprite, sprite->sNextAnimNum_link_rfu_3);
            sprite->sSavedAnimNum_link_rfu_3 = sprite->sNextAnimNum_link_rfu_3;
        }
        if (sprite->anims[sprite->sCurrAnimNum_link_rfu_3][sprite->sFrameIdx_link_rfu_3].frame.duration < sprite->sFrameDelay_link_rfu_3)
        {
            sprite->sFrameIdx_link_rfu_3++;
            sprite->sFrameDelay_link_rfu_3 = 0;
            if (sprite->anims[sprite->sCurrAnimNum_link_rfu_3][sprite->sFrameIdx_link_rfu_3].type == -2)
                sprite->sFrameIdx_link_rfu_3 = 0;
        }
        else
        {
            sprite->sFrameDelay_link_rfu_3++;
        }
        gMain.oamBuffer[125] = sWirelessStatusIndicatorOamData_link_rfu_3;
        gMain.oamBuffer[125].x = sprite->x + sprite->centerToCornerVecX;
        gMain.oamBuffer[125].y = sprite->y + sprite->centerToCornerVecY;
        gMain.oamBuffer[125].paletteNum = sprite->oam.paletteNum;
        gMain.oamBuffer[125].tileNum = sprite->sTileStart_link_rfu_3 + sprite->anims[sprite->sCurrAnimNum_link_rfu_3][sprite->sFrameIdx_link_rfu_3].frame.imageValue;
        CpuCopy16(&gMain.oamBuffer[125], (struct OamData *)OAM + 125, sizeof(struct OamData));
        if (RfuGetStatus() == RFU_STATUS_FATAL_ERROR)
            DestroyWirelessStatusIndicatorSprite();
    }
}

