#define FINE_m4a_tables   0xb1
#define GOTO_m4a_tables   0xb2
#define PATT_m4a_tables   0xb3
#define PEND_m4a_tables   0xb4
#define REPT_m4a_tables   0xb5
#define MEMACC_m4a_tables 0xb9
#define PRIO_m4a_tables   0xba
#define TEMPO_m4a_tables  0xbb
#define KEYSH_m4a_tables  0xbc
#define VOICE_m4a_tables  0xbd
#define VOL_m4a_tables    0xbe
#define PAN_m4a_tables    0xbf
#define BEND_m4a_tables   0xc0
#define BENDR_m4a_tables  0xc1
#define LFOS_m4a_tables   0xc2
#define LFODL_m4a_tables  0xc3
#define MOD_m4a_tables    0xc4
#define MODT_m4a_tables   0xc5
#define TUNE_m4a_tables   0xc8

#define XCMD_m4a_tables   0xcd
#define xRELE_m4a_tables  0x07
#define xIECV_m4a_tables  0x08
#define xIECL_m4a_tables  0x09

#define EOT_m4a_tables    0xce
#define TIE_m4a_tables    0xcf

