void ReadMail(struct Mail *mail, void (*exitCallback)(void), bool8 hasText)
{
    u16 buffer[2];
    u16 species;

    sMailRead_mail = AllocZeroed(sizeof(*sMailRead_mail));
    sMailRead_mail->language = GAME_LANGUAGE;
    sMailRead_mail->international = TRUE;
    sMailRead_mail->parserSingle = CopyEasyChatWord;
    sMailRead_mail->parserMultiple = ConvertEasyChatWordsToString;
    if (IS_ITEM_MAIL(mail->itemId))
    {
        sMailRead_mail->mailType = ITEM_TO_MAIL(mail->itemId);
    }
    else
    {
        sMailRead_mail->mailType = ITEM_TO_MAIL(FIRST_MAIL_INDEX);
        hasText = FALSE;
    }
    switch (sMailRead_mail->international)
    {
    case FALSE:
    default:
        // Never reached. JP only?
        sMailRead_mail->layout = &sMailLayouts_Wide_mail[sMailRead_mail->mailType];
        break;
    case TRUE:
        sMailRead_mail->layout = &sMailLayouts_Tall_mail[sMailRead_mail->mailType];
        break;
    }
    species = MailSpeciesToSpecies(mail->species, buffer);
    if (species > SPECIES_NONE && species < NUM_SPECIES)
    {
        switch (sMailRead_mail->mailType)
        {
        default:
            sMailRead_mail->iconType = ICON_TYPE_NONE_mail;
            break;
        case ITEM_TO_MAIL(ITEM_BEAD_MAIL):
            sMailRead_mail->iconType = ICON_TYPE_BEAD_mail;
            break;
        case ITEM_TO_MAIL(ITEM_DREAM_MAIL):
            sMailRead_mail->iconType = ICON_TYPE_DREAM_mail;
            break;
        }
    }
    else
    {
        sMailRead_mail->iconType = ICON_TYPE_NONE_mail;
    }
    sMailRead_mail->mail = mail;
    sMailRead_mail->exitCallback = exitCallback;
    sMailRead_mail->hasText = hasText;
    SetMainCallback2(CB2_InitMailRead_mail);
}

static bool8 MailReadBuildGraphics_mail(void)
{
    u16 icon;

    switch (gMain.state)
    {
        case 0:
            SetVBlankCallback(NULL);
            ScanlineEffect_Stop();
            SetGpuReg(REG_OFFSET_DISPCNT, 0);
            break;
        case 1:
            CpuFill16(0, (void *)OAM, OAM_SIZE);
            break;
        case 2:
            ResetPaletteFade();
            break;
        case 3:
            ResetTasks();
            break;
        case 4:
            ResetSpriteData();
            break;
        case 5:
            FreeAllSpritePalettes();
            ResetTempTileDataBuffers();
            SetGpuReg(REG_OFFSET_BG0HOFS, 0);
            SetGpuReg(REG_OFFSET_BG0VOFS, 0);
            SetGpuReg(REG_OFFSET_BG1HOFS, 0);
            SetGpuReg(REG_OFFSET_BG1VOFS, 0);
            SetGpuReg(REG_OFFSET_BG2VOFS, 0);
            SetGpuReg(REG_OFFSET_BG2HOFS, 0);
            SetGpuReg(REG_OFFSET_BG3HOFS, 0);
            SetGpuReg(REG_OFFSET_BG3VOFS, 0);
            SetGpuReg(REG_OFFSET_BLDCNT,  0);
            SetGpuReg(REG_OFFSET_BLDALPHA, 0);
            break;
        case 6:
            ResetBgsAndClearDma3BusyFlags(0);
            InitBgsFromTemplates(0, sBgTemplates_mail, ARRAY_COUNT(sBgTemplates_mail));
            SetBgTilemapBuffer(1, sMailRead_mail->bg1TilemapBuffer);
            SetBgTilemapBuffer(2, sMailRead_mail->bg2TilemapBuffer);
            break;
        case 7:
            InitWindows(sWindowTemplates_mail);
            DeactivateAllTextPrinters();
            break;
        case 8:
            DecompressAndCopyTileDataToVram(1, sMailGraphics_mail[sMailRead_mail->mailType].tiles, 0, 0, 0);
            break;
        case 9:
            if (FreeTempTileDataBuffersIfPossible())
                return FALSE;
            break;
        case 10:
            FillBgTilemapBufferRect_Palette0(0, 0, 0, 0, DISPLAY_TILE_WIDTH, DISPLAY_TILE_HEIGHT);
            FillBgTilemapBufferRect_Palette0(2, 1, 0, 0, DISPLAY_TILE_WIDTH, DISPLAY_TILE_HEIGHT);
            CopyToBgTilemapBuffer(1, sMailGraphics_mail[sMailRead_mail->mailType].tileMap, 0, 0);
            break;
        case 11:
            CopyBgTilemapBufferToVram(0);
            CopyBgTilemapBufferToVram(1);
            CopyBgTilemapBufferToVram(2);
            break;
        case 12:
            LoadPalette(GetOverworldTextboxPalettePtr(), BG_PLTT_ID(15), PLTT_SIZE_4BPP);
            gPlttBufferUnfaded[BG_PLTT_ID(15) + 10] = sMailGraphics_mail[sMailRead_mail->mailType].textColor;
            gPlttBufferFaded[BG_PLTT_ID(15) + 10] = sMailGraphics_mail[sMailRead_mail->mailType].textColor;
            gPlttBufferUnfaded[BG_PLTT_ID(15) + 11] = sMailGraphics_mail[sMailRead_mail->mailType].textShadow;
            gPlttBufferFaded[BG_PLTT_ID(15) + 11] = sMailGraphics_mail[sMailRead_mail->mailType].textShadow;

            LoadPalette(sMailGraphics_mail[sMailRead_mail->mailType].palette, BG_PLTT_ID(0), PLTT_SIZE_4BPP);
            gPlttBufferUnfaded[BG_PLTT_ID(0) + 10] = sBgColors_mail[gSaveBlock2Ptr->playerGender][0];
            gPlttBufferFaded[BG_PLTT_ID(0) + 10] = sBgColors_mail[gSaveBlock2Ptr->playerGender][0];
            gPlttBufferUnfaded[BG_PLTT_ID(0) + 11] = sBgColors_mail[gSaveBlock2Ptr->playerGender][1];
            gPlttBufferFaded[BG_PLTT_ID(0) + 11] = sBgColors_mail[gSaveBlock2Ptr->playerGender][1];
            break;
        case 13:
            if (sMailRead_mail->hasText)
                BufferMailText_mail();
            break;
        case 14:
            if (sMailRead_mail->hasText)
            {
                PrintMailText_mail();
                RunTextPrinters();
            }
            break;
        case 15:
            if (Overworld_IsRecvQueueAtMax() == TRUE)
                return FALSE;
            break;
        case 16:
            SetVBlankCallback(VBlankCB_MailRead_mail);
            gPaletteFade.bufferTransferDisabled = TRUE;
            break;
        case 17:
            icon = GetIconSpeciesNoPersonality(sMailRead_mail->mail->species);
            switch (sMailRead_mail->iconType)
            {
            case ICON_TYPE_BEAD_mail:
                LoadMonIconPalette(icon);
                sMailRead_mail->monIconSpriteId = CreateMonIconNoPersonality(icon, SpriteCallbackDummy, 96, 128, 0);
                break;
            case ICON_TYPE_DREAM_mail:
                LoadMonIconPalette(icon);
                sMailRead_mail->monIconSpriteId = CreateMonIconNoPersonality(icon, SpriteCallbackDummy, 40, 128, 0);
                break;
            }
            break;
        case 18:
            SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_OBJ_ON | DISPCNT_OBJ_1D_MAP);
            ShowBg(0);
            ShowBg(1);
            ShowBg(2);
            BeginNormalPaletteFade(PALETTES_ALL, 0, 16, 0, RGB_BLACK);
            gPaletteFade.bufferTransferDisabled = FALSE;
            sMailRead_mail->callback = CB2_WaitForPaletteExitOnKeyPress_mail;
            return TRUE;
        default:
            return FALSE;
    }
    gMain.state++;
    return FALSE;
}

static void CB2_InitMailRead_mail(void)
{
    do
    {
        if (MailReadBuildGraphics_mail() == TRUE)
        {
            SetMainCallback2(CB2_MailRead_mail);
            break;
        }
    } while (MenuHelpers_IsLinkActive() != TRUE);
}

static void BufferMailText_mail(void)
{
    u16 i;
    u8 numWords;
    u8 *ptr;

    // Convert the easy chat words to strings line by line and buffer them to message
    numWords = 0;
    for (i = 0; i < sMailRead_mail->layout->numLines; i ++)
    {
        ConvertEasyChatWordsToString(sMailRead_mail->message[i], &sMailRead_mail->mail->words[numWords], sMailRead_mail->layout->lines[i].numEasyChatWords, 1);
        numWords += sMailRead_mail->layout->lines[i].numEasyChatWords;
    }

    // Buffer the signature
    ptr = StringCopy(sMailRead_mail->playerName, sMailRead_mail->mail->playerName);
    if (!sMailRead_mail->international)
    {
        // Never reached
        StringCopy(ptr, gText_FromSpace); // Odd, "From" text is already printed in PrintMailText_mail
        sMailRead_mail->signatureWidth = sMailRead_mail->layout->signatureWidth - (StringLength(sMailRead_mail->playerName) * 8 - 96);
    }
    else
    {
        ConvertInternationalPlayerName(sMailRead_mail->playerName);
        sMailRead_mail->signatureWidth = sMailRead_mail->layout->signatureWidth;
    }
}

static void PrintMailText_mail(void)
{
    u16 i;
    u8 signature[32];
    u8 y;
    u8 *bufptr;
    s32 box_x;
    s32 box_y;

    y = 0;
    PutWindowTilemap(0);
    PutWindowTilemap(1);
    FillWindowPixelBuffer(0, PIXEL_FILL(0));
    FillWindowPixelBuffer(1, PIXEL_FILL(0));
    for (i = 0; i < sMailRead_mail->layout->numLines; i ++)
    {
        if (sMailRead_mail->message[i][0] == EOS || sMailRead_mail->message[i][0] == CHAR_SPACE)
            continue;

        AddTextPrinterParameterized3(0, FONT_NORMAL, sMailRead_mail->layout->lines[i].xOffset + sMailRead_mail->layout->wordsXPos, y + sMailRead_mail->layout->wordsYPos, sTextColors_mail, 0, sMailRead_mail->message[i]);
        y += sMailRead_mail->layout->lines[i].height;
    }
    bufptr = StringCopy(signature, gText_FromSpace);
    StringCopy(bufptr, sMailRead_mail->playerName);
    box_x = GetStringCenterAlignXOffset(FONT_NORMAL, signature, sMailRead_mail->signatureWidth) + 104;
    box_y = sMailRead_mail->layout->signatureYPos + 88;
    AddTextPrinterParameterized3(0, FONT_NORMAL, box_x, box_y, sTextColors_mail, 0, signature);
    CopyWindowToVram(0, COPYWIN_FULL);
    CopyWindowToVram(1, COPYWIN_FULL);
}

static void VBlankCB_MailRead_mail(void)
{
    LoadOam();
    ProcessSpriteCopyRequests();
    TransferPlttBuffer();
}

static void CB2_MailRead_mail(void)
{
    if (sMailRead_mail->iconType != ICON_TYPE_NONE_mail)
    {
        AnimateSprites();
        BuildOamBuffer();
    }
    sMailRead_mail->callback();
}

static void CB2_WaitForPaletteExitOnKeyPress_mail(void)
{
    if (!UpdatePaletteFade())
    {
        sMailRead_mail->callback = CB2_ExitOnKeyPress_mail;
    }
}

static void CB2_ExitOnKeyPress_mail(void)
{
    if (JOY_NEW(A_BUTTON | B_BUTTON))
    {
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
        sMailRead_mail->callback = CB2_ExitMailReadFreeVars_mail;
    }
}

static void CB2_ExitMailReadFreeVars_mail(void)
{
    if (!UpdatePaletteFade())
    {
        SetMainCallback2(sMailRead_mail->exitCallback);
        switch (sMailRead_mail->iconType)
        {
        case ICON_TYPE_BEAD_mail:
        case ICON_TYPE_DREAM_mail:
            FreeMonIconPalette(GetIconSpeciesNoPersonality(sMailRead_mail->mail->species));
            FreeAndDestroyMonIconSprite(&gSprites[sMailRead_mail->monIconSpriteId]);
        }
        memset(sMailRead_mail, 0, sizeof(*sMailRead_mail));
        ResetPaletteFade();
        UnsetBgTilemapBuffer(0);
        UnsetBgTilemapBuffer(1);
        ResetBgsAndClearDma3BusyFlags(0);
        FreeAllWindowBuffers();
        FREE_AND_SET_NULL(sMailRead_mail);
    }
}
