#define MAIN_MENU_BORDER_TILE_main_menu   0x1D5

static void CB2_MainMenu_main_menu(void)
{
    RunTasks();
    AnimateSprites();
    BuildOamBuffer();
    UpdatePaletteFade();
}

static void VBlankCB_MainMenu_main_menu(void)
{
    LoadOam();
    ProcessSpriteCopyRequests();
    TransferPlttBuffer();
}

void CB2_InitMainMenu(void)
{
    InitMainMenu_main_menu(FALSE);
}

void CB2_ReinitMainMenu(void)
{
    InitMainMenu_main_menu(TRUE);
}

static u32 InitMainMenu_main_menu(bool8 returningFromOptionsMenu)
{
    SetVBlankCallback(NULL);

    SetGpuReg(REG_OFFSET_DISPCNT, 0);
    SetGpuReg(REG_OFFSET_BG2CNT, 0);
    SetGpuReg(REG_OFFSET_BG1CNT, 0);
    SetGpuReg(REG_OFFSET_BG0CNT, 0);
    SetGpuReg(REG_OFFSET_BG2HOFS, 0);
    SetGpuReg(REG_OFFSET_BG2VOFS, 0);
    SetGpuReg(REG_OFFSET_BG1HOFS, 0);
    SetGpuReg(REG_OFFSET_BG1VOFS, 0);
    SetGpuReg(REG_OFFSET_BG0HOFS, 0);
    SetGpuReg(REG_OFFSET_BG0VOFS, 0);

    DmaFill16(3, 0, (void *)VRAM, VRAM_SIZE);
    DmaFill32(3, 0, (void *)OAM, OAM_SIZE);
    DmaFill16(3, 0, (void *)(PLTT + 2), PLTT_SIZE - 2);

    ResetPaletteFade();
    LoadPalette(sMainMenuBgPal_main_menu, BG_PLTT_ID(0), PLTT_SIZE_4BPP);
    LoadPalette(sMainMenuTextPal_main_menu, BG_PLTT_ID(15), PLTT_SIZE_4BPP);
    ScanlineEffect_Stop();
    ResetTasks();
    ResetSpriteData();
    FreeAllSpritePalettes();
    if (returningFromOptionsMenu)
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0x10, 0, RGB_BLACK); // fade to black
    else
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0x10, 0, RGB_WHITEALPHA); // fade to white
    ResetBgsAndClearDma3BusyFlags(0);
    InitBgsFromTemplates(0, sMainMenuBgTemplates_main_menu, ARRAY_COUNT(sMainMenuBgTemplates_main_menu));
    ChangeBgX(0, 0, BG_COORD_SET);
    ChangeBgY(0, 0, BG_COORD_SET);
    ChangeBgX(1, 0, BG_COORD_SET);
    ChangeBgY(1, 0, BG_COORD_SET);
    InitWindows(sWindowTemplates_MainMenu_main_menu);
    DeactivateAllTextPrinters();
    LoadMainMenuWindowFrameTiles_main_menu(0, MAIN_MENU_BORDER_TILE_main_menu);

    SetGpuReg(REG_OFFSET_WIN0H, 0);
    SetGpuReg(REG_OFFSET_WIN0V, 0);
    SetGpuReg(REG_OFFSET_WININ, 0);
    SetGpuReg(REG_OFFSET_WINOUT, 0);
    SetGpuReg(REG_OFFSET_BLDCNT, 0);
    SetGpuReg(REG_OFFSET_BLDALPHA, 0);
    SetGpuReg(REG_OFFSET_BLDY, 0);

    EnableInterrupts(1);
    SetVBlankCallback(VBlankCB_MainMenu_main_menu);
    SetMainCallback2(CB2_MainMenu_main_menu);
    SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_WIN0_ON | DISPCNT_OBJ_ON | DISPCNT_OBJ_1D_MAP);
    ShowBg(0);
    HideBg(1);
    CreateTask(Task_MainMenuCheckSaveFile_main_menu, 0);

    return 0;
}

#define tMenuType_main_menu data[0]
#define tCurrItem_main_menu data[1]
#define tItemCount_main_menu data[12]
#define tScrollArrowTaskId_main_menu data[13]
#define tIsScrolled_main_menu data[14]
#define tWirelessAdapterConnected_main_menu data[15]

#define tArrowTaskIsScrolled_main_menu data[15]   // For scroll indicator arrow task

static void Task_MainMenuCheckSaveFile_main_menu(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    if (!gPaletteFade.active)
    {
        SetGpuReg(REG_OFFSET_WIN0H, 0);
        SetGpuReg(REG_OFFSET_WIN0V, 0);
        SetGpuReg(REG_OFFSET_WININ, WININ_WIN0_BG0 | WININ_WIN0_OBJ);
        SetGpuReg(REG_OFFSET_WINOUT, WINOUT_WIN01_BG0 | WINOUT_WIN01_OBJ | WINOUT_WIN01_CLR);
        SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_EFFECT_DARKEN | BLDCNT_TGT1_BG0);
        SetGpuReg(REG_OFFSET_BLDALPHA, 0);
        SetGpuReg(REG_OFFSET_BLDY, 7);

        if (IsWirelessAdapterConnected())
            tWirelessAdapterConnected_main_menu = TRUE;
        switch (gSaveFileStatus)
        {
            case SAVE_STATUS_OK:
                tMenuType_main_menu = HAS_SAVED_GAME;
                if (IsMysteryGiftEnabled())
                    tMenuType_main_menu++;
                gTasks[taskId].func = Task_MainMenuCheckBattery_main_menu;
                break;
            case SAVE_STATUS_CORRUPT:
                CreateMainMenuErrorWindow_main_menu(gText_SaveFileErased_main_menu);
                tMenuType_main_menu = HAS_NO_SAVED_GAME;
                gTasks[taskId].func = Task_WaitForSaveFileErrorWindow_main_menu;
                break;
            case SAVE_STATUS_ERROR:
                CreateMainMenuErrorWindow_main_menu(gText_SaveFileCorrupted_main_menu);
                gTasks[taskId].func = Task_WaitForSaveFileErrorWindow_main_menu;
                tMenuType_main_menu = HAS_SAVED_GAME;
                if (IsMysteryGiftEnabled() == TRUE)
                    tMenuType_main_menu++;
                break;
            case SAVE_STATUS_EMPTY:
            default:
                tMenuType_main_menu = HAS_NO_SAVED_GAME;
                gTasks[taskId].func = Task_MainMenuCheckBattery_main_menu;
                break;
            case SAVE_STATUS_NO_FLASH:
                CreateMainMenuErrorWindow_main_menu(gJPText_No1MSubCircuit_main_menu);
                gTasks[taskId].tMenuType_main_menu = HAS_NO_SAVED_GAME;
                gTasks[taskId].func = Task_WaitForSaveFileErrorWindow_main_menu;
                break;
        }
        if (sCurrItemAndOptionMenuCheck_main_menu & OPTION_MENU_FLAG_main_menu)   // are we returning from the options menu?
        {
            switch (tMenuType_main_menu)  // if so, highlight the OPTIONS item
            {
                case HAS_NO_SAVED_GAME:
                case HAS_SAVED_GAME:
                    sCurrItemAndOptionMenuCheck_main_menu = tMenuType_main_menu + 1;
                    break;
                case HAS_MYSTERY_GIFT:
                    sCurrItemAndOptionMenuCheck_main_menu = 3;
                    break;
                case HAS_MYSTERY_EVENTS:
                    sCurrItemAndOptionMenuCheck_main_menu = 4;
                    break;
            }
        }
        sCurrItemAndOptionMenuCheck_main_menu &= ~OPTION_MENU_FLAG_main_menu;  // turn off the "returning from options menu" flag
        tCurrItem_main_menu = sCurrItemAndOptionMenuCheck_main_menu;
        tItemCount_main_menu = tMenuType_main_menu + 2;
    }
}

static void Task_WaitForSaveFileErrorWindow_main_menu(u8 taskId)
{
    RunTextPrinters();
    if (!IsTextPrinterActive(7) && (JOY_NEW(A_BUTTON)))
    {
        ClearWindowTilemap(7);
        ClearMainMenuWindowTilemap_main_menu(&sWindowTemplates_MainMenu_main_menu[7]);
        gTasks[taskId].func = Task_MainMenuCheckBattery_main_menu;
    }
}

static void Task_MainMenuCheckBattery_main_menu(u8 taskId)
{
    if (!gPaletteFade.active)
    {
        SetGpuReg(REG_OFFSET_WIN0H, 0);
        SetGpuReg(REG_OFFSET_WIN0V, 0);
        SetGpuReg(REG_OFFSET_WININ, WININ_WIN0_BG0 | WININ_WIN0_OBJ);
        SetGpuReg(REG_OFFSET_WINOUT, WINOUT_WIN01_BG0 | WINOUT_WIN01_OBJ | WINOUT_WIN01_CLR);
        SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_EFFECT_DARKEN | BLDCNT_TGT1_BG0);
        SetGpuReg(REG_OFFSET_BLDALPHA, 0);
        SetGpuReg(REG_OFFSET_BLDY, 7);

        if (!(RtcGetErrorStatus() & RTC_ERR_FLAG_MASK))
        {
            gTasks[taskId].func = Task_DisplayMainMenu_main_menu;
        }
        else
        {
            CreateMainMenuErrorWindow_main_menu(gText_BatteryRunDry_main_menu);
            gTasks[taskId].func = Task_WaitForBatteryDryErrorWindow_main_menu;
        }
    }
}

static void Task_WaitForBatteryDryErrorWindow_main_menu(u8 taskId)
{
    RunTextPrinters();
    if (!IsTextPrinterActive(7) && (JOY_NEW(A_BUTTON)))
    {
        ClearWindowTilemap(7);
        ClearMainMenuWindowTilemap_main_menu(&sWindowTemplates_MainMenu_main_menu[7]);
        gTasks[taskId].func = Task_DisplayMainMenu_main_menu;
    }
}

static void Task_DisplayMainMenu_main_menu(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    u16 palette;

    if (!gPaletteFade.active)
    {
        SetGpuReg(REG_OFFSET_WIN0H, 0);
        SetGpuReg(REG_OFFSET_WIN0V, 0);
        SetGpuReg(REG_OFFSET_WININ, WININ_WIN0_BG0 | WININ_WIN0_OBJ);
        SetGpuReg(REG_OFFSET_WINOUT, WINOUT_WIN01_BG0 | WINOUT_WIN01_OBJ | WINOUT_WIN01_CLR);
        SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_EFFECT_DARKEN | BLDCNT_TGT1_BG0);
        SetGpuReg(REG_OFFSET_BLDALPHA, 0);
        SetGpuReg(REG_OFFSET_BLDY, 7);

        palette = RGB_BLACK;
        LoadPalette(&palette, BG_PLTT_ID(15) + 14, PLTT_SIZEOF(1));

        palette = RGB_WHITE;
        LoadPalette(&palette, BG_PLTT_ID(15) + 10, PLTT_SIZEOF(1));

        palette = RGB(12, 12, 12);
        LoadPalette(&palette, BG_PLTT_ID(15) + 11, PLTT_SIZEOF(1));

        palette = RGB(26, 26, 25);
        LoadPalette(&palette, BG_PLTT_ID(15) + 12, PLTT_SIZEOF(1));

        // Note: If there is no save file, the save block is zeroed out,
        // so the default gender is MALE.
        if (gSaveBlock2Ptr->playerGender == MALE)
        {
            palette = RGB(4, 16, 31);
            LoadPalette(&palette, BG_PLTT_ID(15) + 1, PLTT_SIZEOF(1));
        }
        else
        {
            palette = RGB(31, 3, 21);
            LoadPalette(&palette, BG_PLTT_ID(15) + 1, PLTT_SIZEOF(1));
        }

        switch (gTasks[taskId].tMenuType_main_menu)
        {
            case HAS_NO_SAVED_GAME:
            default:
                FillWindowPixelBuffer(0, PIXEL_FILL(0xA));
                FillWindowPixelBuffer(1, PIXEL_FILL(0xA));
                AddTextPrinterParameterized3(0, FONT_NORMAL, 0, 1, sTextColor_Headers_main_menu, TEXT_SKIP_DRAW, gText_MainMenuNewGame_main_menu);
                AddTextPrinterParameterized3(1, FONT_NORMAL, 0, 1, sTextColor_Headers_main_menu, TEXT_SKIP_DRAW, gText_MainMenuOption_main_menu);
                PutWindowTilemap(0);
                PutWindowTilemap(1);
                CopyWindowToVram(0, COPYWIN_GFX);
                CopyWindowToVram(1, COPYWIN_GFX);
                DrawMainMenuWindowBorder_main_menu(&sWindowTemplates_MainMenu_main_menu[0], MAIN_MENU_BORDER_TILE_main_menu);
                DrawMainMenuWindowBorder_main_menu(&sWindowTemplates_MainMenu_main_menu[1], MAIN_MENU_BORDER_TILE_main_menu);
                break;
            case HAS_SAVED_GAME:
                FillWindowPixelBuffer(2, PIXEL_FILL(0xA));
                FillWindowPixelBuffer(3, PIXEL_FILL(0xA));
                FillWindowPixelBuffer(4, PIXEL_FILL(0xA));
                AddTextPrinterParameterized3(2, FONT_NORMAL, 0, 1, sTextColor_Headers_main_menu, TEXT_SKIP_DRAW, gText_MainMenuContinue_main_menu);
                AddTextPrinterParameterized3(3, FONT_NORMAL, 0, 1, sTextColor_Headers_main_menu, TEXT_SKIP_DRAW, gText_MainMenuNewGame_main_menu);
                AddTextPrinterParameterized3(4, FONT_NORMAL, 0, 1, sTextColor_Headers_main_menu, TEXT_SKIP_DRAW, gText_MainMenuOption_main_menu);
                MainMenu_FormatSavegameText_main_menu();
                PutWindowTilemap(2);
                PutWindowTilemap(3);
                PutWindowTilemap(4);
                CopyWindowToVram(2, COPYWIN_GFX);
                CopyWindowToVram(3, COPYWIN_GFX);
                CopyWindowToVram(4, COPYWIN_GFX);
                DrawMainMenuWindowBorder_main_menu(&sWindowTemplates_MainMenu_main_menu[2], MAIN_MENU_BORDER_TILE_main_menu);
                DrawMainMenuWindowBorder_main_menu(&sWindowTemplates_MainMenu_main_menu[3], MAIN_MENU_BORDER_TILE_main_menu);
                DrawMainMenuWindowBorder_main_menu(&sWindowTemplates_MainMenu_main_menu[4], MAIN_MENU_BORDER_TILE_main_menu);
                break;
            case HAS_MYSTERY_GIFT:
                FillWindowPixelBuffer(2, PIXEL_FILL(0xA));
                FillWindowPixelBuffer(3, PIXEL_FILL(0xA));
                FillWindowPixelBuffer(4, PIXEL_FILL(0xA));
                FillWindowPixelBuffer(5, PIXEL_FILL(0xA));
                AddTextPrinterParameterized3(2, FONT_NORMAL, 0, 1, sTextColor_Headers_main_menu, TEXT_SKIP_DRAW, gText_MainMenuContinue_main_menu);
                AddTextPrinterParameterized3(3, FONT_NORMAL, 0, 1, sTextColor_Headers_main_menu, TEXT_SKIP_DRAW, gText_MainMenuNewGame_main_menu);
                AddTextPrinterParameterized3(4, FONT_NORMAL, 0, 1, sTextColor_Headers_main_menu, TEXT_SKIP_DRAW, gText_MainMenuMysteryGift_main_menu);
                AddTextPrinterParameterized3(5, FONT_NORMAL, 0, 1, sTextColor_Headers_main_menu, TEXT_SKIP_DRAW, gText_MainMenuOption_main_menu);
                MainMenu_FormatSavegameText_main_menu();
                PutWindowTilemap(2);
                PutWindowTilemap(3);
                PutWindowTilemap(4);
                PutWindowTilemap(5);
                CopyWindowToVram(2, COPYWIN_GFX);
                CopyWindowToVram(3, COPYWIN_GFX);
                CopyWindowToVram(4, COPYWIN_GFX);
                CopyWindowToVram(5, COPYWIN_GFX);
                DrawMainMenuWindowBorder_main_menu(&sWindowTemplates_MainMenu_main_menu[2], MAIN_MENU_BORDER_TILE_main_menu);
                DrawMainMenuWindowBorder_main_menu(&sWindowTemplates_MainMenu_main_menu[3], MAIN_MENU_BORDER_TILE_main_menu);
                DrawMainMenuWindowBorder_main_menu(&sWindowTemplates_MainMenu_main_menu[4], MAIN_MENU_BORDER_TILE_main_menu);
                DrawMainMenuWindowBorder_main_menu(&sWindowTemplates_MainMenu_main_menu[5], MAIN_MENU_BORDER_TILE_main_menu);
                break;
            case HAS_MYSTERY_EVENTS:
                FillWindowPixelBuffer(2, PIXEL_FILL(0xA));
                FillWindowPixelBuffer(3, PIXEL_FILL(0xA));
                FillWindowPixelBuffer(4, PIXEL_FILL(0xA));
                FillWindowPixelBuffer(5, PIXEL_FILL(0xA));
                FillWindowPixelBuffer(6, PIXEL_FILL(0xA));
                AddTextPrinterParameterized3(2, FONT_NORMAL, 0, 1, sTextColor_Headers_main_menu, TEXT_SKIP_DRAW, gText_MainMenuContinue_main_menu);
                AddTextPrinterParameterized3(3, FONT_NORMAL, 0, 1, sTextColor_Headers_main_menu, TEXT_SKIP_DRAW, gText_MainMenuNewGame_main_menu);
                AddTextPrinterParameterized3(4, FONT_NORMAL, 0, 1, sTextColor_Headers_main_menu, TEXT_SKIP_DRAW, gText_MainMenuMysteryGift2_main_menu);
                AddTextPrinterParameterized3(5, FONT_NORMAL, 0, 1, sTextColor_Headers_main_menu, TEXT_SKIP_DRAW, gText_MainMenuMysteryEvents_main_menu);
                AddTextPrinterParameterized3(6, FONT_NORMAL, 0, 1, sTextColor_Headers_main_menu, TEXT_SKIP_DRAW, gText_MainMenuOption_main_menu);
                MainMenu_FormatSavegameText_main_menu();
                PutWindowTilemap(2);
                PutWindowTilemap(3);
                PutWindowTilemap(4);
                PutWindowTilemap(5);
                PutWindowTilemap(6);
                CopyWindowToVram(2, COPYWIN_GFX);
                CopyWindowToVram(3, COPYWIN_GFX);
                CopyWindowToVram(4, COPYWIN_GFX);
                CopyWindowToVram(5, COPYWIN_GFX);
                CopyWindowToVram(6, COPYWIN_GFX);
                DrawMainMenuWindowBorder_main_menu(&sWindowTemplates_MainMenu_main_menu[2], MAIN_MENU_BORDER_TILE_main_menu);
                DrawMainMenuWindowBorder_main_menu(&sWindowTemplates_MainMenu_main_menu[3], MAIN_MENU_BORDER_TILE_main_menu);
                DrawMainMenuWindowBorder_main_menu(&sWindowTemplates_MainMenu_main_menu[4], MAIN_MENU_BORDER_TILE_main_menu);
                DrawMainMenuWindowBorder_main_menu(&sWindowTemplates_MainMenu_main_menu[5], MAIN_MENU_BORDER_TILE_main_menu);
                DrawMainMenuWindowBorder_main_menu(&sWindowTemplates_MainMenu_main_menu[6], MAIN_MENU_BORDER_TILE_main_menu);
                tScrollArrowTaskId_main_menu = AddScrollIndicatorArrowPair(&sScrollArrowsTemplate_MainMenu_main_menu, &sCurrItemAndOptionMenuCheck_main_menu);
                gTasks[tScrollArrowTaskId_main_menu].func = Task_ScrollIndicatorArrowPairOnMainMenu;
                if (sCurrItemAndOptionMenuCheck_main_menu == 4)
                {
                    ChangeBgY(0, 0x2000, BG_COORD_ADD);
                    ChangeBgY(1, 0x2000, BG_COORD_ADD);
                    tIsScrolled_main_menu = TRUE;
                    gTasks[tScrollArrowTaskId_main_menu].tArrowTaskIsScrolled_main_menu = TRUE;
                }
                break;
        }
        gTasks[taskId].func = Task_HighlightSelectedMainMenuItem_main_menu;
    }
}

static void Task_HighlightSelectedMainMenuItem_main_menu(u8 taskId)
{
    HighlightSelectedMainMenuItem_main_menu(gTasks[taskId].tMenuType_main_menu, gTasks[taskId].tCurrItem_main_menu, gTasks[taskId].tIsScrolled_main_menu);
    gTasks[taskId].func = Task_HandleMainMenuInput_main_menu;
}

static bool8 HandleMainMenuInput_main_menu(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    if (JOY_NEW(A_BUTTON))
    {
        PlaySE(SE_SELECT);
        IsWirelessAdapterConnected();   // why bother calling this here? debug? Task_HandleMainMenuAPressed_main_menu will check too
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 0x10, RGB_BLACK);
        gTasks[taskId].func = Task_HandleMainMenuAPressed_main_menu;
    }
    else if (JOY_NEW(B_BUTTON))
    {
        PlaySE(SE_SELECT);
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 0x10, RGB_WHITEALPHA);
        SetGpuReg(REG_OFFSET_WIN0H, WIN_RANGE(0, DISPLAY_WIDTH));
        SetGpuReg(REG_OFFSET_WIN0V, WIN_RANGE(0, DISPLAY_HEIGHT));
        gTasks[taskId].func = Task_HandleMainMenuBPressed_main_menu;
    }
    else if ((JOY_NEW(DPAD_UP)) && tCurrItem_main_menu > 0)
    {
        if (tMenuType_main_menu == HAS_MYSTERY_EVENTS && tIsScrolled_main_menu == TRUE && tCurrItem_main_menu == 1)
        {
            ChangeBgY(0, 0x2000, BG_COORD_SUB);
            ChangeBgY(1, 0x2000, BG_COORD_SUB);
            gTasks[tScrollArrowTaskId_main_menu].tArrowTaskIsScrolled_main_menu = tIsScrolled_main_menu = FALSE;
        }
        tCurrItem_main_menu--;
        sCurrItemAndOptionMenuCheck_main_menu = tCurrItem_main_menu;
        return TRUE;
    }
    else if ((JOY_NEW(DPAD_DOWN)) && tCurrItem_main_menu < tItemCount_main_menu - 1)
    {
        if (tMenuType_main_menu == HAS_MYSTERY_EVENTS && tCurrItem_main_menu == 3 && tIsScrolled_main_menu == FALSE)
        {
            ChangeBgY(0, 0x2000, BG_COORD_ADD);
            ChangeBgY(1, 0x2000, BG_COORD_ADD);
            gTasks[tScrollArrowTaskId_main_menu].tArrowTaskIsScrolled_main_menu = tIsScrolled_main_menu = TRUE;
        }
        tCurrItem_main_menu++;
        sCurrItemAndOptionMenuCheck_main_menu = tCurrItem_main_menu;
        return TRUE;
    }
    return FALSE;
}

static void Task_HandleMainMenuInput_main_menu(u8 taskId)
{
    if (HandleMainMenuInput_main_menu(taskId))
        gTasks[taskId].func = Task_HighlightSelectedMainMenuItem_main_menu;
}

static void Task_HandleMainMenuAPressed_main_menu(u8 taskId)
{
    bool8 wirelessAdapterConnected;
    u8 action;

    if (!gPaletteFade.active)
    {
        if (gTasks[taskId].tMenuType_main_menu == HAS_MYSTERY_EVENTS)
            RemoveScrollIndicatorArrowPair(gTasks[taskId].tScrollArrowTaskId_main_menu);
        ClearStdWindowAndFrame(0, TRUE);
        ClearStdWindowAndFrame(1, TRUE);
        ClearStdWindowAndFrame(2, TRUE);
        ClearStdWindowAndFrame(3, TRUE);
        ClearStdWindowAndFrame(4, TRUE);
        ClearStdWindowAndFrame(5, TRUE);
        ClearStdWindowAndFrame(6, TRUE);
        ClearStdWindowAndFrame(7, TRUE);
        wirelessAdapterConnected = IsWirelessAdapterConnected();
        switch (gTasks[taskId].tMenuType_main_menu)
        {
            case HAS_NO_SAVED_GAME:
            default:
                switch (gTasks[taskId].tCurrItem_main_menu)
                {
                    case 0:
                    default:
                        action = ACTION_NEW_GAME_main_menu;
                        break;
                    case 1:
                        action = ACTION_OPTION_main_menu;
                        break;
                }
                break;
            case HAS_SAVED_GAME:
                switch (gTasks[taskId].tCurrItem_main_menu)
                {
                    case 0:
                    default:
                        action = ACTION_CONTINUE_main_menu;
                        break;
                    case 1:
                        action = ACTION_NEW_GAME_main_menu;
                        break;
                    case 2:
                        action = ACTION_OPTION_main_menu;
                        break;
                }
                break;
            case HAS_MYSTERY_GIFT:
                switch (gTasks[taskId].tCurrItem_main_menu)
                {
                    case 0:
                    default:
                        action = ACTION_CONTINUE_main_menu;
                        break;
                    case 1:
                        action = ACTION_NEW_GAME_main_menu;
                        break;
                    case 2:
                        action = ACTION_MYSTERY_GIFT_main_menu;
                        if (!wirelessAdapterConnected)
                        {
                            action = ACTION_INVALID_main_menu;
                            gTasks[taskId].tMenuType_main_menu = HAS_NO_SAVED_GAME;
                        }
                        break;
                    case 3:
                        action = ACTION_OPTION_main_menu;
                        break;
                }
                break;
            case HAS_MYSTERY_EVENTS:
                switch (gTasks[taskId].tCurrItem_main_menu)
                {
                    case 0:
                    default:
                        action = ACTION_CONTINUE_main_menu;
                        break;
                    case 1:
                        action = ACTION_NEW_GAME_main_menu;
                        break;
                    case 2:
                        if (gTasks[taskId].tWirelessAdapterConnected_main_menu)
                        {
                            action = ACTION_MYSTERY_GIFT_main_menu;
                            if (!wirelessAdapterConnected)
                            {
                                action = ACTION_INVALID_main_menu;
                                gTasks[taskId].tMenuType_main_menu = HAS_NO_SAVED_GAME;
                            }
                        }
                        else if (wirelessAdapterConnected)
                        {
                            action = ACTION_INVALID_main_menu;
                            gTasks[taskId].tMenuType_main_menu = HAS_SAVED_GAME;
                        }
                        else
                        {
                            action = ACTION_EREADER_main_menu;
                        }
                        break;
                    case 3:
                        if (wirelessAdapterConnected)
                        {
                            action = ACTION_INVALID_main_menu;
                            gTasks[taskId].tMenuType_main_menu = HAS_MYSTERY_GIFT;
                        }
                        else
                        {
                            action = ACTION_MYSTERY_EVENTS_main_menu;
                        }
                        break;
                    case 4:
                        action = ACTION_OPTION_main_menu;
                        break;
                }
                break;
        }
        ChangeBgY(0, 0, BG_COORD_SET);
        ChangeBgY(1, 0, BG_COORD_SET);
        switch (action)
        {
            case ACTION_NEW_GAME_main_menu:
            default:
                gPlttBufferUnfaded[0] = RGB_BLACK;
                gPlttBufferFaded[0] = RGB_BLACK;
                gTasks[taskId].func = Task_NewGameBirchSpeech_Init_main_menu;
                break;
            case ACTION_CONTINUE_main_menu:
                gPlttBufferUnfaded[0] = RGB_BLACK;
                gPlttBufferFaded[0] = RGB_BLACK;
                SetMainCallback2(CB2_ContinueSavedGame);
                DestroyTask(taskId);
                break;
            case ACTION_OPTION_main_menu:
                gMain.savedCallback = CB2_ReinitMainMenu;
                SetMainCallback2(CB2_InitOptionMenu);
                DestroyTask(taskId);
                break;
            case ACTION_MYSTERY_GIFT_main_menu:
                SetMainCallback2(CB2_InitMysteryGift);
                DestroyTask(taskId);
                break;
            case ACTION_MYSTERY_EVENTS_main_menu:
                SetMainCallback2(CB2_InitMysteryEventMenu);
                DestroyTask(taskId);
                break;
            case ACTION_EREADER_main_menu:
                SetMainCallback2(CB2_InitEReader);
                DestroyTask(taskId);
                break;
            case ACTION_INVALID_main_menu:
                gTasks[taskId].tCurrItem_main_menu = 0;
                gTasks[taskId].func = Task_DisplayMainMenuInvalidActionError_main_menu;
                gPlttBufferUnfaded[BG_PLTT_ID(15) + 1] = RGB_WHITE;
                gPlttBufferFaded[BG_PLTT_ID(15) + 1] = RGB_WHITE;
                SetGpuReg(REG_OFFSET_BG2HOFS, 0);
                SetGpuReg(REG_OFFSET_BG2VOFS, 0);
                SetGpuReg(REG_OFFSET_BG1HOFS, 0);
                SetGpuReg(REG_OFFSET_BG1VOFS, 0);
                SetGpuReg(REG_OFFSET_BG0HOFS, 0);
                SetGpuReg(REG_OFFSET_BG0VOFS, 0);
                BeginNormalPaletteFade(PALETTES_ALL, 0, 16, 0, RGB_BLACK);
                return;
        }
        FreeAllWindowBuffers();
        if (action != ACTION_OPTION_main_menu)
            sCurrItemAndOptionMenuCheck_main_menu = 0;
        else
            sCurrItemAndOptionMenuCheck_main_menu |= OPTION_MENU_FLAG_main_menu;  // entering the options menu
    }
}

static void Task_HandleMainMenuBPressed_main_menu(u8 taskId)
{
    if (!gPaletteFade.active)
    {
        if (gTasks[taskId].tMenuType_main_menu == HAS_MYSTERY_EVENTS)
            RemoveScrollIndicatorArrowPair(gTasks[taskId].tScrollArrowTaskId_main_menu);
        sCurrItemAndOptionMenuCheck_main_menu = 0;
        FreeAllWindowBuffers();
        SetMainCallback2(CB2_InitTitleScreen);
        DestroyTask(taskId);
    }
}

static void Task_DisplayMainMenuInvalidActionError_main_menu(u8 taskId)
{
    switch (gTasks[taskId].tCurrItem_main_menu)
    {
        case 0:
            FillBgTilemapBufferRect_Palette0(0, 0, 0, 0, DISPLAY_TILE_WIDTH, DISPLAY_TILE_HEIGHT);
            switch (gTasks[taskId].tMenuType_main_menu)
            {
                case 0:
                    CreateMainMenuErrorWindow_main_menu(gText_WirelessNotConnected_main_menu);
                    break;
                case 1:
                    CreateMainMenuErrorWindow_main_menu(gText_MysteryGiftCantUse_main_menu);
                    break;
                case 2:
                    CreateMainMenuErrorWindow_main_menu(gText_MysteryEventsCantUse_main_menu);
                    break;
            }
            gTasks[taskId].tCurrItem_main_menu++;
            break;
        case 1:
            if (!gPaletteFade.active)
                gTasks[taskId].tCurrItem_main_menu++;
            break;
        case 2:
            RunTextPrinters();
            if (!IsTextPrinterActive(7))
                gTasks[taskId].tCurrItem_main_menu++;
            break;
        case 3:
            if (JOY_NEW(A_BUTTON | B_BUTTON))
            {
                PlaySE(SE_SELECT);
                BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
                gTasks[taskId].func = Task_HandleMainMenuBPressed_main_menu;
            }
    }
}

