static void Task_NewGameBirchSpeechSub_InitPokeBall_main_menu(u8 taskId)
{
    u8 spriteId = gTasks[sBirchSpeechMainTaskId_main_menu].tLotadSpriteId_main_menu;

    gSprites[spriteId].x = 100;
    gSprites[spriteId].y = 75;
    gSprites[spriteId].invisible = FALSE;
    gSprites[spriteId].data[0] = 0;

    CreatePokeballSpriteToReleaseMon(spriteId, gSprites[spriteId].oam.paletteNum, 112, 58, 0, 0, 32, PALETTES_BG, SPECIES_LOTAD);
    gTasks[taskId].func = Task_NewGameBirchSpeechSub_WaitForLotad_main_menu;
    gTasks[sBirchSpeechMainTaskId_main_menu].tTimer_main_menu = 0;
}

static void Task_NewGameBirchSpeechSub_WaitForLotad_main_menu(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    struct Sprite *sprite = &gSprites[gTasks[sBirchSpeechMainTaskId_main_menu].tLotadSpriteId_main_menu];

    switch (tState_main_menu)
    {
        case 0:
            if (sprite->callback != SpriteCallbackDummy)
                return;
            sprite->oam.affineMode = ST_OAM_AFFINE_OFF;
            break;
        case 1:
            if (gTasks[sBirchSpeechMainTaskId_main_menu].tTimer_main_menu >= 96)
            {
                DestroyTask(taskId);
                if (gTasks[sBirchSpeechMainTaskId_main_menu].tTimer_main_menu < 0x4000)
                    gTasks[sBirchSpeechMainTaskId_main_menu].tTimer_main_menu++;
            }
            return;
    }
    tState_main_menu++;
    if (gTasks[sBirchSpeechMainTaskId_main_menu].tTimer_main_menu < 0x4000)
        gTasks[sBirchSpeechMainTaskId_main_menu].tTimer_main_menu++;
}

