static void NewGameBirchSpeech_WaitForThisIsPokemonText_main_menu(struct TextPrinterTemplate *printer, u16 renderCmd)
{
    // Wait for Birch's "This is a Pokémon" text to reach the pause
    // Then start the PokéBall release (if it hasn't been started already)
    if (*(printer->currentChar - 2) == EXT_CTRL_CODE_PAUSE && !sStartedPokeBallTask_main_menu)
    {
        sStartedPokeBallTask_main_menu = TRUE;
        CreateTask(Task_NewGameBirchSpeechSub_InitPokeBall_main_menu, 0);
    }
}

