void InitMatchCallCounters(void)
{
    RtcCalcLocalTime();
    sMatchCallState_match_call.minutes = GetCurrentTotalMinutes_match_call(&gLocalTime) + 10;
    sMatchCallState_match_call.stepCounter = 0;
}

static u32 GetCurrentTotalMinutes_match_call(struct Time *time)
{
    return time->days * 24 * 60 + time->hours * 60 + time->minutes;
}

static bool32 UpdateMatchCallMinutesCounter_match_call(void)
{
    int curMinutes;
    RtcCalcLocalTime();
    curMinutes = GetCurrentTotalMinutes_match_call(&gLocalTime);
    if (sMatchCallState_match_call.minutes > curMinutes || curMinutes - sMatchCallState_match_call.minutes > 9)
    {
        sMatchCallState_match_call.minutes = curMinutes;
        return TRUE;
    }

    return FALSE;
}

static bool32 CheckMatchCallChance_match_call(void)
{
    int callChance = 1;
    if (!GetMonData(&gPlayerParty[0], MON_DATA_SANITY_IS_EGG) && GetMonAbility(&gPlayerParty[0]) == ABILITY_LIGHTNING_ROD)
        callChance = 2;

    if (Random() % 10 < callChance * 3)
        return TRUE;
    else
        return FALSE;
}

static bool32 MapAllowsMatchCall_match_call(void)
{
    if (!Overworld_MapTypeAllowsTeleportAndFly(gMapHeader.mapType) || gMapHeader.regionMapSectionId == MAPSEC_SAFARI_ZONE)
        return FALSE;

    if (gMapHeader.regionMapSectionId == MAPSEC_SOOTOPOLIS_CITY
     && FlagGet(FLAG_HIDE_SOOTOPOLIS_CITY_RAYQUAZA) == TRUE
     && FlagGet(FLAG_NEVER_SET_0x0DC) == FALSE)
        return FALSE;

    if (gMapHeader.regionMapSectionId == MAPSEC_MT_CHIMNEY
     && FlagGet(FLAG_MET_ARCHIE_METEOR_FALLS) == TRUE
     && FlagGet(FLAG_DEFEATED_EVIL_TEAM_MT_CHIMNEY) == FALSE)
        return FALSE;

    return TRUE;
}

static bool32 UpdateMatchCallStepCounter_match_call(void)
{
    if (++sMatchCallState_match_call.stepCounter >= 10)
    {
        sMatchCallState_match_call.stepCounter = 0;
        return TRUE;
    }
    else
    {
        return FALSE;
    }
}

static bool32 SelectMatchCallTrainer_match_call(void)
{
    u32 matchCallId;
    u32 numRegistered = GetNumRegisteredTrainers_match_call();
    if (numRegistered == 0)
        return FALSE;

    sMatchCallState_match_call.trainerId = GetActiveMatchCallTrainerId_match_call(Random() % numRegistered);
    sMatchCallState_match_call.triggeredFromScript = FALSE;
    if (sMatchCallState_match_call.trainerId == REMATCH_TABLE_ENTRIES)
        return FALSE;

    matchCallId = GetTrainerMatchCallId_match_call(sMatchCallState_match_call.trainerId);
    if (GetRematchTrainerLocation_match_call(matchCallId) == gMapHeader.regionMapSectionId && !TrainerIsEligibleForRematch_match_call(matchCallId))
        return FALSE;

    return TRUE;
}

// Ignores registrable non-trainer NPCs, and special trainers like Wally and the gym leaders.
static u32 GetNumRegisteredTrainers_match_call(void)
{
    u32 i, count;
    for (i = 0, count = 0; i < REMATCH_SPECIAL_TRAINER_START; i++)
    {
        if (FlagGet(TRAINER_REGISTERED_FLAGS_START + i))
            count++;
    }

    return count;
}

static u32 GetActiveMatchCallTrainerId_match_call(u32 activeMatchCallId)
{
    u32 i;
    for (i = 0; i < REMATCH_SPECIAL_TRAINER_START; i++)
    {
        if (FlagGet(TRAINER_REGISTERED_FLAGS_START + i))
        {
            if (!activeMatchCallId)
                return gRematchTable[i].trainerIds[0];

            activeMatchCallId--;
        }
    }

    return REMATCH_TABLE_ENTRIES;
}

/*
    From the function calls below, a call can only be triggered...
    - If the player has match call
    - Every 10th step
    - Every 10 minutes
    - 1/3 of the time (or 2/3 of the time, if the lead party Pokémon has Lightning Rod)
    - If in a valid outdoor map (not Safari Zone, not underwater, not Mt Chimney with Team Magma, not Sootopolis with legendaries)
    - If an eligible trainer to call the player is selected
*/
bool32 TryStartMatchCall(void)
{
    if (FlagGet(FLAG_HAS_MATCH_CALL)
        && UpdateMatchCallStepCounter_match_call()
        && UpdateMatchCallMinutesCounter_match_call()
        && CheckMatchCallChance_match_call()
        && MapAllowsMatchCall_match_call()
        && SelectMatchCallTrainer_match_call())
    {
        StartMatchCall_match_call();
        return TRUE;
    }

    return FALSE;
}

void StartMatchCallFromScript(const u8 *message)
{
    sMatchCallState_match_call.triggeredFromScript = TRUE;
    StartMatchCall_match_call();
}

bool32 IsMatchCallTaskActive(void)
{
    return FuncIsActiveTask(ExecuteMatchCall_match_call);
}

static void StartMatchCall_match_call(void)
{
    if (!sMatchCallState_match_call.triggeredFromScript)
    {
        LockPlayerFieldControls();
        FreezeObjectEvents();
        PlayerFreeze();
        StopPlayerAvatar();
    }

    PlaySE(SE_POKENAV_CALL);
    CreateTask(ExecuteMatchCall_match_call, 1);
}

static const u16  sMatchCallWindow_Pal_match_call[] = INCBIN_U16("graphics/pokenav/match_call/window.gbapal");
static const u8  sMatchCallWindow_Gfx_match_call[] = INCBIN_U8("graphics/pokenav/match_call/window.4bpp");
static const u16  sPokenavIcon_Pal_match_call[] = INCBIN_U16("graphics/pokenav/match_call/nav_icon.gbapal");
static const u32  sPokenavIcon_Gfx_match_call[] = INCBIN_U32("graphics/pokenav/match_call/nav_icon.4bpp.lz");

static const u8  sText_PokenavCallEllipsis_match_call[] = _("………………\p");

#define tState_match_call      data[0]
#define tWindowId_match_call   data[2]
#define tIconTaskId_match_call data[5]

static bool32 (*const sMatchCallTaskFuncs[])(u8) =
{
    MatchCall_LoadGfx_match_call,
    MatchCall_DrawWindow_match_call,
    MatchCall_ReadyIntro_match_call,
    MatchCall_SlideWindowIn_match_call,
    MatchCall_PrintIntro_match_call,
    MatchCall_PrintMessage_match_call,
    MatchCall_SlideWindowOut_match_call,
    MatchCall_EndCall_match_call,
};

static void ExecuteMatchCall_match_call(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    if (sMatchCallTaskFuncs[tState_match_call](taskId))
    {
        tState_match_call++;
        data[1] = 0; // Never read
        if ((u16)tState_match_call > 7)
            DestroyTask(taskId);
    }
}

static const struct WindowTemplate  sMatchCallTextWindow_match_call =
{
    .bg = 0,
    .tilemapLeft = 1,
    .tilemapTop = 15,
    .width = 28,
    .height = 4,
    .paletteNum = 15,
    .baseBlock = 0x200
};

#define TILE_MC_WINDOW_match_call    0x270
#define TILE_POKENAV_ICON_match_call 0x279

static bool32 MatchCall_LoadGfx_match_call(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    tWindowId_match_call = AddWindow(&sMatchCallTextWindow_match_call);
    if (tWindowId_match_call == WINDOW_NONE)
    {
        DestroyTask(taskId);
        return FALSE;
    }

    if (LoadBgTiles(0, sMatchCallWindow_Gfx_match_call, sizeof(sMatchCallWindow_Gfx_match_call), TILE_MC_WINDOW_match_call) == 0xFFFF)
    {
        RemoveWindow(tWindowId_match_call);
        DestroyTask(taskId);
        return FALSE;
    }

    if (!DecompressAndCopyTileDataToVram(0, sPokenavIcon_Gfx_match_call, 0, TILE_POKENAV_ICON_match_call, 0))
    {
        RemoveWindow(tWindowId_match_call);
        DestroyTask(taskId);
        return FALSE;
    }

    FillWindowPixelBuffer(tWindowId_match_call, PIXEL_FILL(8));
    LoadPalette(sMatchCallWindow_Pal_match_call, BG_PLTT_ID(14), sizeof(sMatchCallWindow_Pal_match_call));
    LoadPalette(sPokenavIcon_Pal_match_call, BG_PLTT_ID(15), sizeof(sPokenavIcon_Pal_match_call));
    ChangeBgY(0, -0x2000, BG_COORD_SET);
    return TRUE;
}

static bool32 MatchCall_DrawWindow_match_call(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    if (FreeTempTileDataBuffersIfPossible())
        return FALSE;

    PutWindowTilemap(tWindowId_match_call);
    DrawMatchCallTextBoxBorder_Internal_match_call(tWindowId_match_call, TILE_MC_WINDOW_match_call, 14);
    WriteSequenceToBgTilemapBuffer(0, (0xF << 12) | TILE_POKENAV_ICON_match_call, 1, 15, 4, 4, 17, 1);
    tIconTaskId_match_call = CreateTask(Task_SpinPokenavIcon_match_call, 10);
    CopyWindowToVram(tWindowId_match_call, COPYWIN_GFX);
    CopyBgTilemapBufferToVram(0);
    return TRUE;
}

static bool32 MatchCall_ReadyIntro_match_call(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    if (!IsDma3ManagerBusyWithBgCopy())
    {
        // Note that "..." is not printed yet, just readied
        InitMatchCallTextPrinter_match_call(tWindowId_match_call, sText_PokenavCallEllipsis_match_call);
        return TRUE;
    }

    return FALSE;
}

static bool32 MatchCall_SlideWindowIn_match_call(u8 taskId)
{
    if (ChangeBgY(0, 0x600, BG_COORD_ADD) >= 0)
    {
        ChangeBgY(0, 0, BG_COORD_SET);
        return TRUE;
    }

    return FALSE;
}

static bool32 MatchCall_PrintIntro_match_call(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    if (!RunMatchCallTextPrinter_match_call(tWindowId_match_call))
    {
        FillWindowPixelBuffer(tWindowId_match_call, PIXEL_FILL(8));

        // Ready the message
        if (!sMatchCallState_match_call.triggeredFromScript)
            SelectMatchCallMessage(sMatchCallState_match_call.trainerId, gStringVar4);
        InitMatchCallTextPrinter_match_call(tWindowId_match_call, gStringVar4);
        return TRUE;
    }

    return FALSE;
}

static bool32 MatchCall_PrintMessage_match_call(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    if (!RunMatchCallTextPrinter_match_call(tWindowId_match_call) && !IsSEPlaying() && JOY_NEW(A_BUTTON | B_BUTTON))
    {
        FillWindowPixelBuffer(tWindowId_match_call, PIXEL_FILL(8));
        CopyWindowToVram(tWindowId_match_call, COPYWIN_GFX);
        PlaySE(SE_POKENAV_HANG_UP);
        return TRUE;
    }

    return FALSE;
}

static bool32 MatchCall_SlideWindowOut_match_call(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    if (ChangeBgY(0, 0x600, BG_COORD_SUB) <= -0x2000)
    {
        FillBgTilemapBufferRect_Palette0(0, 0, 0, 14, 30, 6);
        DestroyTask(tIconTaskId_match_call);
        RemoveWindow(tWindowId_match_call);
        CopyBgTilemapBufferToVram(0);
        return TRUE;
    }

    return FALSE;
}

static bool32 MatchCall_EndCall_match_call(u8 taskId)
{
    u8 playerObjectId;
    if (!IsDma3ManagerBusyWithBgCopy() && !IsSEPlaying())
    {
        ChangeBgY(0, 0, BG_COORD_SET);
        if (!sMatchCallState_match_call.triggeredFromScript)
        {
            LoadMessageBoxAndBorderGfx();
            playerObjectId = GetObjectEventIdByLocalIdAndMap(OBJ_EVENT_ID_PLAYER, 0, 0);
            ObjectEventClearHeldMovementIfFinished(&gObjectEvents[playerObjectId]);
            ScriptMovement_UnfreezeObjectEvents();
            UnfreezeObjectEvents();
            UnlockPlayerFieldControls();
        }

        return TRUE;
    }

    return FALSE;
}

static void DrawMatchCallTextBoxBorder_Internal_match_call(u32 windowId, u32 tileOffset, u32 paletteId)
{
    int bg, x, y, width, height;
    int tileNum;

    bg = GetWindowAttribute(windowId, WINDOW_BG);
    x = GetWindowAttribute(windowId, WINDOW_TILEMAP_LEFT);
    y = GetWindowAttribute(windowId, WINDOW_TILEMAP_TOP);
    width = GetWindowAttribute(windowId, WINDOW_WIDTH);
    height = GetWindowAttribute(windowId, WINDOW_HEIGHT);
    tileNum = tileOffset + GetBgAttribute(bg, BG_ATTR_BASETILE);

    FillBgTilemapBufferRect_Palette0(bg, ((paletteId << 12) & 0xF000) | (tileNum + 0), x - 1, y - 1, 1, 1);
    FillBgTilemapBufferRect_Palette0(bg, ((paletteId << 12) & 0xF000) | (tileNum + 1), x, y - 1, width, 1);
    FillBgTilemapBufferRect_Palette0(bg, ((paletteId << 12) & 0xF000) | (tileNum + 2), x + width, y - 1, 1, 1);
    FillBgTilemapBufferRect_Palette0(bg, ((paletteId << 12) & 0xF000) | (tileNum + 3), x - 1, y, 1, height);
    FillBgTilemapBufferRect_Palette0(bg, ((paletteId << 12) & 0xF000) | (tileNum + 4), x + width, y, 1, height);
    FillBgTilemapBufferRect_Palette0(bg, ((paletteId << 12) & 0xF000) | (tileNum + 5), x - 1, y + height, 1, 1);
    FillBgTilemapBufferRect_Palette0(bg, ((paletteId << 12) & 0xF000) | (tileNum + 6), x, y + height, width, 1);
    FillBgTilemapBufferRect_Palette0(bg, ((paletteId << 12) & 0xF000) | (tileNum + 7), x + width, y + height, 1, 1);
}

static void InitMatchCallTextPrinter_match_call(int windowId, const u8 *str)
{
    struct TextPrinterTemplate printerTemplate;
    printerTemplate.currentChar = str;
    printerTemplate.windowId = windowId;
    printerTemplate.fontId = FONT_NORMAL;
    printerTemplate.x = 32;
    printerTemplate.y = 1;
    printerTemplate.currentX = 32;
    printerTemplate.currentY = 1;
    printerTemplate.letterSpacing = 0;
    printerTemplate.lineSpacing = 0;
    printerTemplate.unk = 0;
    printerTemplate.fgColor = TEXT_DYNAMIC_COLOR_1;
    printerTemplate.bgColor = TEXT_COLOR_BLUE;
    printerTemplate.shadowColor = TEXT_DYNAMIC_COLOR_5;
    gTextFlags.useAlternateDownArrow = FALSE;

    AddTextPrinter(&printerTemplate, GetPlayerTextSpeedDelay(), NULL);
}

static bool32 RunMatchCallTextPrinter_match_call(int windowId)
{
    if (JOY_HELD(A_BUTTON))
        gTextFlags.canABSpeedUpPrint = TRUE;
    else
        gTextFlags.canABSpeedUpPrint = FALSE;

    RunTextPrinters();
    return IsTextPrinterActive(windowId);
}

#define tTimer_match_call     data[0]
#define tSpinStage_match_call data[1]
#define tTileNum_match_call   data[2]

static void Task_SpinPokenavIcon_match_call(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    if (++tTimer_match_call > 8)
    {
        tTimer_match_call = 0;
        if (++tSpinStage_match_call > 7)
            tSpinStage_match_call = 0;

        tTileNum_match_call = (tSpinStage_match_call * 16) + TILE_POKENAV_ICON_match_call;
        WriteSequenceToBgTilemapBuffer(0, tTileNum_match_call | ~0xFFF, 1, 15, 4, 4, 17, 1);
        CopyBgTilemapBufferToVram(0);
    }
}

#undef tTimer_match_call
#undef tSpinStage_match_call
#undef tTileNum_match_call

static bool32 TrainerIsEligibleForRematch_match_call(int matchCallId)
{
#if FREE_MATCH_CALL == FALSE
    return gSaveBlock1Ptr->trainerRematches[matchCallId] > 0;
#else
    return FALSE;
#endif //FREE_MATCH_CALL
}

static u16 GetRematchTrainerLocation_match_call(int matchCallId)
{
    const struct MapHeader *mapHeader = Overworld_GetMapHeaderByGroupAndId(gRematchTable[matchCallId].mapGroup, gRematchTable[matchCallId].mapNum);
    return mapHeader->regionMapSectionId;
}

static u32 GetNumRematchTrainersFought_match_call(void)
{
    u32 i, count;
    for (i = 0, count = 0; i < REMATCH_SPECIAL_TRAINER_START; i++)
    {
        if (HasTrainerBeenFought(gRematchTable[i].trainerIds[0]))
            count++;
    }

    return count;
}

// Look through the rematch table for trainers that have been defeated once before.
// Return the index into the rematch table of the nth defeated trainer,
// or REMATCH_TABLE_ENTRIES if fewer than n rematch trainers have been defeated.
static u32 GetNthRematchTrainerFought_match_call(int n)
{
    u32 i, count;

    for (i = 0, count = 0; i < REMATCH_TABLE_ENTRIES; i++)
    {
        if (HasTrainerBeenFought(gRematchTable[i].trainerIds[0]))
        {
            if (count == n)
                return i;

            count++;
        }
    }

    return REMATCH_TABLE_ENTRIES;
}

bool32 SelectMatchCallMessage(int trainerId, u8 *str)
{
    u32 matchCallId;
    const struct MatchCallText *matchCallText;
    bool32 newRematchRequest = FALSE;

    matchCallId = GetTrainerMatchCallId_match_call(trainerId);
    sBattleFrontierStreakInfo_match_call.facilityId = 0;

    // If the player is on the same route as the trainer
    // and they can be rematched, they will always request a battle
    if (TrainerIsEligibleForRematch_match_call(matchCallId)
     && GetRematchTrainerLocation_match_call(matchCallId) == gMapHeader.regionMapSectionId)
    {
        matchCallText = GetSameRouteMatchCallText(matchCallId, str);
    }
    // If the player is not on the same route as the trainer
    // and they can be rematched, there is a random chance for
    // the trainer to request a battle
    else if (ShouldTrainerRequestBattle_match_call(matchCallId))
    {
        matchCallText = GetDifferentRouteMatchCallText(matchCallId, str);
        newRematchRequest = TRUE;
        UpdateRematchIfDefeated(matchCallId);
    }
    else if (Random() % 3)
    {
        // Message talking about a battle the NPC had
        matchCallText = GetBattleMatchCallText(matchCallId, str);
    }
    else
    {
        // Message talking about something else
        matchCallText = GetGeneralMatchCallText(matchCallId, str);
    }

    BuildMatchCallString_match_call(matchCallId, matchCallText, str);
    return newRematchRequest;
}

static int GetTrainerMatchCallId_match_call(int trainerId)
{
    int i = 0;
    while (1)
    {
        if (sMatchCallTrainers_match_call[i].trainerId == trainerId)
            return i;
        else
            i++;
    }
}

static const struct MatchCallText *GetSameRouteMatchCallText(int matchCallId, u8 *str)
{
    u16 textId = sMatchCallTrainers_match_call[matchCallId].sameRouteMatchCallTextId;
    int mask = 0xFF;
    u32 topic = (textId >> 8) - 1;
    u32 id = (textId & mask) - 1;
    return &sMatchCallBattleRequestTopics_match_call[topic][id];
}

static const struct MatchCallText *GetDifferentRouteMatchCallText(int matchCallId, u8 *str)
{
    u16 textId = sMatchCallTrainers_match_call[matchCallId].differentRouteMatchCallTextId;
    int mask = 0xFF;
    u32 topic = (textId >> 8) - 1;
    u32 id = (textId & mask) - 1;
    return &sMatchCallBattleRequestTopics_match_call[topic][id];
}

static const struct MatchCallText *GetBattleMatchCallText(int matchCallId, u8 *str)
{
    int mask;
    u32 textId, topic, id;

    topic = Random() % 3;
    textId = sMatchCallTrainers_match_call[matchCallId].battleTopicTextIds[topic];
    if (!textId)
        SpriteCallbackDummy(NULL); // leftover debugging ???

    mask = 0xFF;
    topic = (textId >> 8) - 1;
    id = (textId & mask) - 1;
    return &sMatchCallBattleTopics_match_call[topic][id];
}

static const struct MatchCallText *GetGeneralMatchCallText(int matchCallId, u8 *str)
{
    int i;
    int count;
    u32 topic, id;
    u16 rand;

    rand = Random();
    if (!(rand & 1))
    {
        // Count the number of facilities with a win streak
        for (count = 0, i = 0; i < NUM_FRONTIER_FACILITIES; i++)
        {
            if (GetFrontierStreakInfo_match_call(i, &topic) > 1)
                count++;
        }

        if (count)
        {
            // At least one facility with a win streak
            // Randomly choose one to have a call about
            count = Random() % count;
            for (i = 0; i < NUM_FRONTIER_FACILITIES; i++)
            {
                sBattleFrontierStreakInfo_match_call.streak = GetFrontierStreakInfo_match_call(i, &topic);
                if (sBattleFrontierStreakInfo_match_call.streak < 2)
                    continue;

                if (!count)
                    break;

                count--;
            }

            sBattleFrontierStreakInfo_match_call.facilityId = i;
            id = sMatchCallTrainers_match_call[matchCallId].battleFrontierRecordStreakTextIndex - 1;
            return &sMatchCallGeneralTopics_match_call[topic][id];
        }
    }

    topic = (sMatchCallTrainers_match_call[matchCallId].generalTextId >> 8) - 1;
    id = (sMatchCallTrainers_match_call[matchCallId].generalTextId & 0xFF) - 1;
    return &sMatchCallGeneralTopics_match_call[topic][id];
}

static void BuildMatchCallString_match_call(int matchCallId, const struct MatchCallText *matchCallText, u8 *str)
{
    PopulateMatchCallStringVars_match_call(matchCallId, matchCallText->stringVarFuncIds);
    StringExpandPlaceholders(str, matchCallText->text);
}

