void SetMauvilleOldMan(void)
{
    u16 trainerId = (gSaveBlock2Ptr->playerTrainerId[1] << 8) | gSaveBlock2Ptr->playerTrainerId[0];


    // Determine man based on the last digit of the player's trainer ID.
    switch ((trainerId % 10) / 2)
    {
    case MAUVILLE_MAN_BARD:
        SetupBard_mauville_old_man();
        break;
    case MAUVILLE_MAN_HIPSTER:
        SetupHipster_mauville_old_man();
        break;
    case MAUVILLE_MAN_TRADER:
        SetupTrader_mauville_old_man();
        break;
    case MAUVILLE_MAN_STORYTELLER:
        SetupStoryteller_mauville_old_man();
        break;
    case MAUVILLE_MAN_GIDDY:
        SetupGiddy_mauville_old_man();
        break;
    }
    SetMauvilleOldManObjEventGfx();
}

