static const s32  sNumStories_mauville_old_man = ARRAY_COUNT(sStorytellerStories_mauville_old_man);
static const u32  sUnused_mauville_old_man = 8;

static void StorytellerSetup_mauville_old_man(void)
{
    s32 i;
    sStorytellerPtr_mauville_old_man = &gSaveBlock1Ptr->oldMan.storyteller;

    sStorytellerPtr_mauville_old_man->id = MAUVILLE_MAN_STORYTELLER;
    sStorytellerPtr_mauville_old_man->alreadyRecorded = FALSE;
    for (i = 0; i < NUM_STORYTELLER_TALES; i++)
    {
        sStorytellerPtr_mauville_old_man->gameStatIDs[i] = 0;
        sStorytellerPtr_mauville_old_man->trainerNames[0][i] = EOS;  // Maybe they meant storyteller->trainerNames[i][0] instead?
    }
}

static void Storyteller_ResetFlag_mauville_old_man(void)
{
    sStorytellerPtr_mauville_old_man = &gSaveBlock1Ptr->oldMan.storyteller;

    sStorytellerPtr_mauville_old_man->id = MAUVILLE_MAN_STORYTELLER;
    sStorytellerPtr_mauville_old_man->alreadyRecorded = FALSE;
}

static u32 StorytellerGetGameStat_mauville_old_man(u8 stat)
{
    if (stat == 50)
        stat = GAME_STAT_SAVED_GAME;
    return GetGameStat(stat);
}

static const struct Story *GetStoryByStat(u32 stat)
{
    s32 i;

    for (i = 0; i < sNumStories_mauville_old_man; i++)
    {
        if (sStorytellerStories_mauville_old_man[i].stat == stat)
            return &sStorytellerStories_mauville_old_man[i];
    }
    return &sStorytellerStories_mauville_old_man[sNumStories_mauville_old_man - 1];
}

static const u8 *GetStoryTitleByStat(u32 stat)
{
    return GetStoryByStat(stat)->title;
}

static const u8 *GetStoryTextByStat(u32 stat)
{
    return GetStoryByStat(stat)->fullText;
}

static const u8 *GetStoryActionByStat(u32 stat)
{
    return GetStoryByStat(stat)->action;
}

static u8 GetFreeStorySlot_mauville_old_man(void)
{
    u8 i;

    for (i = 0; i < NUM_STORYTELLER_TALES; i++)
    {
        if (sStorytellerPtr_mauville_old_man->gameStatIDs[i] == 0)
            break;
    }
    return i;
}

static u32 StorytellerGetRecordedTrainerStat_mauville_old_man(u32 trainer)
{
    u8 *ptr = sStorytellerPtr_mauville_old_man->statValues[trainer];

    return ptr[0] | (ptr[1] << 8) | (ptr[2] << 16) | (ptr[3] << 24);
}

static void StorytellerSetRecordedTrainerStat_mauville_old_man(u32 trainer, u32 val)
{
    u8 *ptr = sStorytellerPtr_mauville_old_man->statValues[trainer];

    ptr[0] = val;
    ptr[1] = val >> 8;
    ptr[2] = val >> 16;
    ptr[3] = val >> 24;
}

static bool32 HasTrainerStatIncreased_mauville_old_man(u32 trainer)
{
    if (StorytellerGetGameStat_mauville_old_man(sStorytellerPtr_mauville_old_man->gameStatIDs[trainer]) > StorytellerGetRecordedTrainerStat_mauville_old_man(trainer))
        return TRUE;
    else
        return FALSE;
}

static void GetStoryByStattellerPlayerName_mauville_old_man(u32 player, void *dst)
{
    u8 *name = sStorytellerPtr_mauville_old_man->trainerNames[player];

    memset(dst, EOS, PLAYER_NAME_LENGTH + 1);
    memcpy(dst, name, PLAYER_NAME_LENGTH);
}

static void StorytellerSetPlayerName_mauville_old_man(u32 player, const u8 *src)
{
    u8 *name = sStorytellerPtr_mauville_old_man->trainerNames[player];
    memset(name, EOS, PLAYER_NAME_LENGTH);
    memcpy(name, src, PLAYER_NAME_LENGTH);
}


static void StorytellerRecordNewStat_mauville_old_man(u32 player, u32 stat)
{
    sStorytellerPtr_mauville_old_man->gameStatIDs[player] = stat;
    StorytellerSetPlayerName_mauville_old_man(player, gSaveBlock2Ptr->playerName);
    StorytellerSetRecordedTrainerStat_mauville_old_man(player, StorytellerGetGameStat_mauville_old_man(stat));
    ConvertIntToDecimalStringN(gStringVar1, StorytellerGetGameStat_mauville_old_man(stat), STR_CONV_MODE_LEFT_ALIGN, 10);
    StringCopy(gStringVar2, GetStoryActionByStat(stat));
    sStorytellerPtr_mauville_old_man->language[player] = gGameLanguage;
}

static bool8 StorytellerInitializeRandomStat_mauville_old_man(void)
{
    u8 storyIds[sNumStories_mauville_old_man];
    s32 i, j;

    Shuffle(storyIds, sNumStories_mauville_old_man, sizeof(storyIds[0]));
    for (i = 0; i < sNumStories_mauville_old_man; i++)
    {
        u8 stat = sStorytellerStories_mauville_old_man[storyIds[i]].stat;
        u8 minVal = sStorytellerStories_mauville_old_man[storyIds[i]].minVal;

        for (j = 0; j < NUM_STORYTELLER_TALES; j++)
        {
            if (sStorytellerPtr_mauville_old_man->gameStatIDs[j] == stat)
                break;
        }
        if (j == NUM_STORYTELLER_TALES && StorytellerGetGameStat_mauville_old_man(stat) >= minVal)
        {
            sStorytellerPtr_mauville_old_man->alreadyRecorded = TRUE;
            if (GetFreeStorySlot_mauville_old_man() == NUM_STORYTELLER_TALES)
                StorytellerRecordNewStat_mauville_old_man(sSelectedStory_mauville_old_man, stat);
            else
                StorytellerRecordNewStat_mauville_old_man(GetFreeStorySlot_mauville_old_man(), stat);
            return TRUE;
        }
    }
    return FALSE;
}

static void StorytellerDisplayStory_mauville_old_man(u32 player)
{
    u8 stat = sStorytellerPtr_mauville_old_man->gameStatIDs[player];

    ConvertIntToDecimalStringN(gStringVar1, StorytellerGetRecordedTrainerStat_mauville_old_man(player), STR_CONV_MODE_LEFT_ALIGN, 10);
    StringCopy(gStringVar2, GetStoryActionByStat(stat));
    GetStoryByStattellerPlayerName_mauville_old_man(player, gStringVar3);
    ConvertInternationalString(gStringVar3, sStorytellerPtr_mauville_old_man->language[player]);
    ShowFieldMessage(GetStoryTextByStat(stat));
}

static void PrintStoryList_mauville_old_man(void)
{
    s32 i;
    s32 width = GetStringWidth(FONT_NORMAL, gText_Exit, 0);
    for (i = 0; i < NUM_STORYTELLER_TALES; i++)
    {
        s32 curWidth;
        u16 gameStatID = sStorytellerPtr_mauville_old_man->gameStatIDs[i];

        if (gameStatID == 0)
            break;
        curWidth = GetStringWidth(FONT_NORMAL, GetStoryTitleByStat(gameStatID), 0);
        if (curWidth > width)
            width = curWidth;
    }
    sStorytellerWindowId_mauville_old_man = CreateWindowFromRect(0, 0, ConvertPixelWidthToTileWidth(width), GetFreeStorySlot_mauville_old_man() * 2 + 2);
    SetStandardWindowBorderStyle(sStorytellerWindowId_mauville_old_man, FALSE);
    for (i = 0; i < NUM_STORYTELLER_TALES; i++)
    {
        u16 gameStatID = sStorytellerPtr_mauville_old_man->gameStatIDs[i];
        if (gameStatID == 0)
            break;
        AddTextPrinterParameterized(sStorytellerWindowId_mauville_old_man, FONT_NORMAL, GetStoryTitleByStat(gameStatID), 8, 16 * i + 1, TEXT_SKIP_DRAW, NULL);
    }
    AddTextPrinterParameterized(sStorytellerWindowId_mauville_old_man, FONT_NORMAL, gText_Exit, 8, 16 * i + 1, TEXT_SKIP_DRAW, NULL);
    InitMenuInUpperLeftCornerNormal(sStorytellerWindowId_mauville_old_man, GetFreeStorySlot_mauville_old_man() + 1, 0);
    CopyWindowToVram(sStorytellerWindowId_mauville_old_man, COPYWIN_FULL);
}

static void Task_StoryListMenu_mauville_old_man(u8 taskId)
{
    struct Task *task = &gTasks[taskId];
    s32 selection;

    switch (task->data[0])
    {
    case 0:
        PrintStoryList_mauville_old_man();
        task->data[0]++;
        break;
    case 1:
        selection = Menu_ProcessInput();
        if (selection == MENU_NOTHING_CHOSEN)
            break;
        if (selection == MENU_B_PRESSED || selection == GetFreeStorySlot_mauville_old_man())
        {
            gSpecialVar_Result = 0;
        }
        else
        {
            gSpecialVar_Result = 1;
            sSelectedStory_mauville_old_man = selection;
        }
        ClearToTransparentAndRemoveWindow(sStorytellerWindowId_mauville_old_man);
        DestroyTask(taskId);
        ScriptContext_Enable();
        break;
    }
}

// Sets gSpecialVar_Result to TRUE if player selected a story
void StorytellerStoryListMenu(void)
{
    CreateTask(Task_StoryListMenu_mauville_old_man, 80);
}

void Script_StorytellerDisplayStory(void)
{
    StorytellerDisplayStory_mauville_old_man(sSelectedStory_mauville_old_man);
}

u8 StorytellerGetFreeStorySlot(void)
{
    sStorytellerPtr_mauville_old_man = &gSaveBlock1Ptr->oldMan.storyteller;
    return GetFreeStorySlot_mauville_old_man();
}

// Returns TRUE if stat has increased
bool8 StorytellerUpdateStat(void)
{
    u8 stat;
    sStorytellerPtr_mauville_old_man = &gSaveBlock1Ptr->oldMan.storyteller;
    stat = sStorytellerPtr_mauville_old_man->gameStatIDs[sSelectedStory_mauville_old_man];

    if (HasTrainerStatIncreased_mauville_old_man(sSelectedStory_mauville_old_man) == TRUE)
    {
        StorytellerRecordNewStat_mauville_old_man(sSelectedStory_mauville_old_man, stat);
        return TRUE;
    }
    return FALSE;
}

bool8 HasStorytellerAlreadyRecorded(void)
{
    sStorytellerPtr_mauville_old_man = &gSaveBlock1Ptr->oldMan.storyteller;

    if (sStorytellerPtr_mauville_old_man->alreadyRecorded == FALSE)
        return FALSE;
    else
        return TRUE;
}

bool8 Script_StorytellerInitializeRandomStat(void)
{
    sStorytellerPtr_mauville_old_man = &gSaveBlock1Ptr->oldMan.storyteller;
    return StorytellerInitializeRandomStat_mauville_old_man();
}
