// Returns TRUE if the quantity was changed, FALSE if it remained the same
bool8 AdjustQuantityAccordingToDPadInput(s16 *quantity, u16 max)
{
    s16 valBefore = *quantity;

    if (JOY_REPEAT(DPAD_ANY) == DPAD_UP)
    {
        (*quantity)++;
        if (*quantity > max)
            *quantity = 1;

        if (*quantity == valBefore)
        {
            return FALSE;
        }
        else
        {
            PlaySE(SE_SELECT);
            return TRUE;
        }
    }
    else if (JOY_REPEAT(DPAD_ANY) == DPAD_DOWN)
    {
        (*quantity)--;
        if (*quantity <= 0)
            *quantity = max;

        if (*quantity == valBefore)
        {
            return FALSE;
        }
        else
        {
            PlaySE(SE_SELECT);
            return TRUE;
        }
    }
    else if (JOY_REPEAT(DPAD_ANY) == DPAD_RIGHT)
    {
        *quantity += 10;
        if (*quantity > max)
            *quantity = max;

        if (*quantity == valBefore)
        {
            return FALSE;
        }
        else
        {
            PlaySE(SE_SELECT);
            return TRUE;
        }
    }
    else if (JOY_REPEAT(DPAD_ANY) == DPAD_LEFT)
    {
        *quantity -= 10;
        if (*quantity <= 0)
            *quantity = 1;

        if (*quantity == valBefore)
        {
            return FALSE;
        }
        else
        {
            PlaySE(SE_SELECT);
            return TRUE;
        }
    }

    return FALSE;
}

