bool8 MetatileBehavior_IsATile(u8 metatileBehavior)
{
    return TRUE;
}

bool8 MetatileBehavior_IsEncounterTile(u8 metatileBehavior)
{
    if ((sTileBitAttributes_metatile_behavior[metatileBehavior] & TILE_FLAG_HAS_ENCOUNTERS_metatile_behavior))
        return TRUE;
    else
        return FALSE;
}

