/*
    This file contains two types of '3-2-1 Start' countdowns intended for use by the wireless minigames.

    One is static, where the numbers simply appear and disappear without moving. This version is unused.
    The other (used) version has the numbers squish and bounce up as they appear.
*/

#define TAG_STATIC_COUNTDOWN_minigame_countdown 0x2000

enum {
    STATE_IDLE_minigame_countdown = 1,
    STATE_START_minigame_countdown,
    STATE_RUN_minigame_countdown,
    STATE_END_minigame_countdown,
};

enum {
    FUNC_INIT_minigame_countdown,
    FUNC_FREE_minigame_countdown,
    FUNC_START_minigame_countdown,
    FUNC_RUN_minigame_countdown,
};

enum {
    ANIM_THREE_minigame_countdown,
    ANIM_TWO_minigame_countdown,
    ANIM_ONE_minigame_countdown,
    ANIM_START_LEFT_minigame_countdown,
    ANIM_START_MID_minigame_countdown,
    ANIM_START_RIGHT_minigame_countdown,
};

extern const struct OamData gOamData_AffineOff_ObjNormal_32x32;

static void Task_StaticCountdown_minigame_countdown(u8 taskId);
static void Task_StaticCountdown_Init_minigame_countdown(u8 taskId);
static void Task_StaticCountdown_Free_minigame_countdown(u8 taskId);
static void Task_StaticCountdown_Start_minigame_countdown(u8 taskId);
static void Task_StaticCountdown_Run_minigame_countdown(u8 taskId);

static const u16  s321Start_Static_Pal_minigame_countdown[] = INCBIN_U16("graphics/link/321start_static.gbapal");
static const u32  s321Start_Static_Gfx_minigame_countdown[] = INCBIN_U32("graphics/link/321start_static.4bpp.lz");

static const struct CompressedSpriteSheet  sSpriteSheet_321Start_Static_minigame_countdown[] =
{
    {s321Start_Static_Gfx_minigame_countdown, 0xC00, TAG_STATIC_COUNTDOWN_minigame_countdown},
    {},
};

