void StartMinigameCountdown(u16 tilesTag, u16 palTag, s16 x, s16 y, u8 subpriority)
{
    u8 taskId = CreateTask(Task_MinigameCountdown_minigame_countdown, 80);
    gTasks[taskId].tTilesTag_minigame_countdown = tilesTag;
    gTasks[taskId].tPalTag_minigame_countdown = palTag;
    gTasks[taskId].tX_minigame_countdown = x;
    gTasks[taskId].tY_minigame_countdown = y;
    gTasks[taskId].tSubpriority_minigame_countdown = subpriority;
}

bool32 IsMinigameCountdownRunning(void)
{
    return FuncIsActiveTask(Task_MinigameCountdown_minigame_countdown);
}

static void Task_MinigameCountdown_minigame_countdown(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    switch (tState_minigame_countdown)
    {
    case 0:
        Load321StartGfx_minigame_countdown(tTilesTag_minigame_countdown, tPalTag_minigame_countdown);
        tSpriteId1_minigame_countdown = CreateNumberSprite_minigame_countdown(tTilesTag_minigame_countdown, tPalTag_minigame_countdown, tX_minigame_countdown, tY_minigame_countdown, tSubpriority_minigame_countdown);
        CreateStartSprite_minigame_countdown(tTilesTag_minigame_countdown, tPalTag_minigame_countdown, tX_minigame_countdown, tY_minigame_countdown, tSubpriority_minigame_countdown, &tSpriteId2_minigame_countdown, &tSpriteId3_minigame_countdown);
        tState_minigame_countdown++;
        break;
    case 1:
        if (!RunMinigameCountdownDigitsAnim_minigame_countdown(tSpriteId1_minigame_countdown))
        {
            InitStartGraphic_minigame_countdown(tSpriteId1_minigame_countdown, tSpriteId2_minigame_countdown, tSpriteId3_minigame_countdown);
            FreeSpriteOamMatrix(&gSprites[tSpriteId1_minigame_countdown]);
            DestroySprite(&gSprites[tSpriteId1_minigame_countdown]);
            tState_minigame_countdown++;
        }
        break;
    case 2:
        if (!IsStartGraphicAnimRunning_minigame_countdown(tSpriteId2_minigame_countdown))
        {
            DestroySprite(&gSprites[tSpriteId2_minigame_countdown]);
            DestroySprite(&gSprites[tSpriteId3_minigame_countdown]);
            FreeSpriteTilesByTag(tTilesTag_minigame_countdown);
            FreeSpritePaletteByTag(tPalTag_minigame_countdown);
            DestroyTask(taskId);
        }
        break;
    }
}

#define sState_minigame_countdown   data[0]
#define sTimer_minigame_countdown   data[2]
#define sAnimNum_minigame_countdown data[4]

static bool32 RunMinigameCountdownDigitsAnim_minigame_countdown(u8 spriteId)
{
    struct Sprite *sprite = &gSprites[spriteId];

    switch (sprite->sState_minigame_countdown)
    {
    case 0:
        SetSpriteMatrixAnchor(sprite, NO_ANCHOR, 26);
        sprite->sState_minigame_countdown++;
        // fallthrough
    case 1:
        if (sprite->sTimer_minigame_countdown == 0)
            PlaySE(SE_BALL_BOUNCE_2);

        if (++sprite->sTimer_minigame_countdown >= 20)
        {
            // Ready for jump
            sprite->sTimer_minigame_countdown = 0;
            StartSpriteAffineAnim(sprite, 1);
            sprite->sState_minigame_countdown++;
        }
        break;
    case 2:
        if (sprite->affineAnimEnded)
            sprite->sState_minigame_countdown++;
        break;
    case 3:
        if (++sprite->sTimer_minigame_countdown >= 4)
        {
            // Start jump
            sprite->sTimer_minigame_countdown = 0;
            sprite->sState_minigame_countdown++;
            StartSpriteAffineAnim(sprite, 2);
        }
        break;
    case 4:
        // Moving up from jump
        sprite->y -= 4;
        if (++sprite->sTimer_minigame_countdown >= 8)
        {
            if (sprite->sAnimNum_minigame_countdown < 2)
            {
                // Swap to the next number
                StartSpriteAnim(sprite, sprite->sAnimNum_minigame_countdown + 1);
                sprite->sTimer_minigame_countdown = 0;
                sprite->sState_minigame_countdown++;
            }
            else
            {
                // End
                sprite->sState_minigame_countdown = 7;
                return FALSE;
            }
        }
        break;
    case 5:
        // Falling after jump
        sprite->y += 4;
        if (++sprite->sTimer_minigame_countdown >= 8)
        {
            // Land from jump
            sprite->sTimer_minigame_countdown = 0;
            StartSpriteAffineAnim(sprite, 3);
            sprite->sState_minigame_countdown++;
        }
        break;
    case 6:
        if (sprite->affineAnimEnded)
        {
            // Restart for next number
            sprite->sAnimNum_minigame_countdown++;
            sprite->sState_minigame_countdown = 1;
        }
        break;
    case 7:
        return FALSE;
    }

    return TRUE;
}

#undef sState_minigame_countdown
#undef sTimer_minigame_countdown
#undef sAnimNum_minigame_countdown

// First argument is unused.
static void InitStartGraphic_minigame_countdown(u8 spriteId1, u8 spriteId2, u8 spriteId3)
{
    gSprites[spriteId2].y2 = -40;
    gSprites[spriteId3].y2 = -40;
    gSprites[spriteId2].invisible = FALSE;
    gSprites[spriteId3].invisible = FALSE;
    gSprites[spriteId2].callback = SpriteCB_Start_minigame_countdown;
    gSprites[spriteId3].callback = SpriteCB_Start_minigame_countdown;
}

static bool32 IsStartGraphicAnimRunning_minigame_countdown(u8 spriteId)
{
    return gSprites[spriteId].callback == SpriteCB_Start_minigame_countdown;
}

#define sState_minigame_countdown  data[0]
#define sTimer_minigame_countdown  data[1]
#define sYSpeed_minigame_countdown data[4]
#define sY_minigame_countdown      data[5]

static void SpriteCB_Start_minigame_countdown(struct Sprite *sprite)
{
    int y;
    s16 *data = sprite->data;

    switch (sState_minigame_countdown)
    {
    case 0:
        sYSpeed_minigame_countdown = 64;
        sY_minigame_countdown = sprite->y2 << 4;
        sState_minigame_countdown++;
    case 1:
        sY_minigame_countdown += sYSpeed_minigame_countdown;
        sYSpeed_minigame_countdown++;
        sprite->y2 = sY_minigame_countdown >> 4;
        if (sprite->y2 >= 0)
        {
            PlaySE(SE_BALL_BOUNCE_2);
            sprite->y2 = 0;
            sState_minigame_countdown++;
        }
        break;
    case 2:
        sTimer_minigame_countdown += 12;
        if (sTimer_minigame_countdown >= 128)
        {
            PlaySE(SE_BALL_BOUNCE_2);
            sTimer_minigame_countdown = 0;
            sState_minigame_countdown++;
        }
        y = gSineTable[sTimer_minigame_countdown];
        sprite->y2 = -(y >> 4);
        break;
    case 3:
        sTimer_minigame_countdown += 16;
        if (sTimer_minigame_countdown >= 128)
        {
            PlaySE(SE_BALL_BOUNCE_2);
            sTimer_minigame_countdown = 0;
            sState_minigame_countdown++;
        }
        sprite->y2 = -(gSineTable[sTimer_minigame_countdown] >> 5);
        break;
    case 4:
        if (++sTimer_minigame_countdown > 40)
            sprite->callback = SpriteCallbackDummy;
        break;
    }
}

