static void SetBgShakeOffsets_mirage_tower(void)
{
    SetGpuReg(REG_OFFSET_BG0HOFS, sBgShakeOffsets_mirage_tower->bgHOFS);
    SetGpuReg(REG_OFFSET_BG0VOFS, sBgShakeOffsets_mirage_tower->bgVOFS);
}

static void UpdateBgShake_mirage_tower(u8 taskId)
{
    if (!gTasks[taskId].data[0])
    {
        sBgShakeOffsets_mirage_tower->bgHOFS = -sBgShakeOffsets_mirage_tower->bgHOFS;
        gTasks[taskId].data[0] = 2;
        SetBgShakeOffsets_mirage_tower();
    }
    else
    {
        gTasks[taskId].data[0]--;
    }
}

#define tState_mirage_tower data[0]

static void InitMirageTowerShake_mirage_tower(u8 taskId)
{
    u8 zero;

    switch (gTasks[taskId].tState_mirage_tower)
    {
    case 0:
        FreeAllWindowBuffers();
        SetBgAttribute(0, BG_ATTR_PRIORITY, 2);
        gTasks[taskId].tState_mirage_tower++;
        break;
    case 1:
        sMirageTowerGfxBuffer_mirage_tower = (u8 *)AllocZeroed(MIRAGE_TOWER_GFX_LENGTH_mirage_tower);
        sMirageTowerTilemapBuffer_mirage_tower = (u8 *)AllocZeroed(BG_SCREEN_SIZE);
        ChangeBgX(0, 0, BG_COORD_SET);
        ChangeBgY(0, 0, BG_COORD_SET);
        gTasks[taskId].tState_mirage_tower++;
        break;
    case 2:
        CpuSet(sBlankTile_Gfx, sMirageTowerGfxBuffer_mirage_tower, MIRAGE_TOWER_GFX_LENGTH_mirage_tower / 2);
        LoadBgTiles(0, sMirageTowerGfxBuffer_mirage_tower, MIRAGE_TOWER_GFX_LENGTH_mirage_tower, 0);
        gTasks[taskId].tState_mirage_tower++;
        break;
    case 3:
        SetBgTilemapBuffer(0, sMirageTowerTilemapBuffer_mirage_tower);
        CopyToBgTilemapBufferRect_ChangePalette(0, &sMirageTowerTilemap_mirage_tower, 12, 29, 6, 12, 17);
        CopyBgTilemapBufferToVram(0);
        gTasks[taskId].tState_mirage_tower++;
        break;
    case 4:
        ShowBg(0);
        gTasks[taskId].tState_mirage_tower++;
        break;
    case 5:
        SetInvisibleMirageTowerMetatiles_mirage_tower();
        gTasks[taskId].tState_mirage_tower++;
        break;
    case 6:
        sBgShakeOffsets_mirage_tower = Alloc(sizeof(*sBgShakeOffsets_mirage_tower));
        zero = 0;
        sBgShakeOffsets_mirage_tower->bgHOFS = 2;
        sBgShakeOffsets_mirage_tower->bgVOFS = zero;
        CreateTask(UpdateBgShake_mirage_tower, 10);
        DestroyTask(taskId);
        ScriptContext_Enable();
        break;
    }
}

#define OUTER_BUFFER_LENGTH_mirage_tower 0x60
#define INNER_BUFFER_LENGTH_mirage_tower 0x30
static void DoMirageTowerDisintegration_mirage_tower(u8 taskId)
{
    u8 bgShakeTaskId, j;
    u16 i;
    u8 index;

    switch (gTasks[taskId].tState_mirage_tower)
    {
    case 1:
        sFallingTower_mirage_tower = AllocZeroed(OUTER_BUFFER_LENGTH_mirage_tower * sizeof(struct FallAnim_Tower));
        break;
    case 3:
        if (gTasks[taskId].data[3] <= (OUTER_BUFFER_LENGTH_mirage_tower - 1))
        {
            if (gTasks[taskId].data[1] > 1)
            {
                // Initialize disintegration pattern
                index = gTasks[taskId].data[3];
                sFallingTower_mirage_tower[index].disintegrateRand = Alloc(INNER_BUFFER_LENGTH_mirage_tower);
                for (i = 0; i <= (INNER_BUFFER_LENGTH_mirage_tower - 1); i++)
                    sFallingTower_mirage_tower[index].disintegrateRand[i] = i;

                // Randomize disintegration pattern
                Shuffle(sFallingTower_mirage_tower[index].disintegrateRand, INNER_BUFFER_LENGTH_mirage_tower,
                    sizeof(sFallingTower_mirage_tower[index].disintegrateRand[0]));

                if (gTasks[taskId].data[3] <= (OUTER_BUFFER_LENGTH_mirage_tower - 1))
                    gTasks[taskId].data[3]++;
                gTasks[taskId].data[1] = 0;
            }
            gTasks[taskId].data[1]++;
        }
        index = gTasks[taskId].data[3];
        for (i = (u8)(gTasks[taskId].data[2]); i < index; i++)
        {
            for (j = 0; j < 1; j++)
            {
                UpdateDisintegrationEffect_mirage_tower(sMirageTowerGfxBuffer_mirage_tower,
                            (OUTER_BUFFER_LENGTH_mirage_tower - 1 - i) * INNER_BUFFER_LENGTH_mirage_tower + sFallingTower_mirage_tower[i].disintegrateRand[sFallingTower_mirage_tower[i].disintegrateIdx++],
                            0, INNER_BUFFER_LENGTH_mirage_tower, 1);
            }
            if (sFallingTower_mirage_tower[i].disintegrateIdx > (INNER_BUFFER_LENGTH_mirage_tower - 1))
            {
                FREE_AND_SET_NULL(sFallingTower_mirage_tower[i].disintegrateRand);
                gTasks[taskId].data[2]++;
                if ((i % 2) == 1)
                    sBgShakeOffsets_mirage_tower->bgVOFS--;
            }
        }
        LoadBgTiles(0, sMirageTowerGfxBuffer_mirage_tower, MIRAGE_TOWER_GFX_LENGTH_mirage_tower, 0);
        if (sFallingTower_mirage_tower[OUTER_BUFFER_LENGTH_mirage_tower - 1].disintegrateIdx > INNER_BUFFER_LENGTH_mirage_tower - 1)
            break;
        return;
    case 4:
        UnsetBgTilemapBuffer(0);
        bgShakeTaskId = FindTaskIdByFunc(UpdateBgShake_mirage_tower);
        if (bgShakeTaskId != TASK_NONE)
            DestroyTask(bgShakeTaskId);
        sBgShakeOffsets_mirage_tower->bgVOFS = sBgShakeOffsets_mirage_tower->bgHOFS = 0;
        SetBgShakeOffsets_mirage_tower();
        break;
    case 5:
        FREE_AND_SET_NULL(sBgShakeOffsets_mirage_tower);
        FREE_AND_SET_NULL(sFallingTower_mirage_tower);
        FREE_AND_SET_NULL(sMirageTowerGfxBuffer_mirage_tower);
        FREE_AND_SET_NULL(sMirageTowerTilemapBuffer_mirage_tower);
        break;
    case 6:
        SetGpuRegBits(REG_OFFSET_BG2CNT, BGCNT_PRIORITY(2));
        SetGpuRegBits(REG_OFFSET_BG0CNT, BGCNT_PRIORITY(0));
        SetBgAttribute(0, BG_ATTR_PRIORITY, 0);
        InitStandardTextBoxWindows();
        break;
    case 7:
        ShowBg(0);
        break;
    case 8:
        DestroyTask(taskId);
        ScriptContext_Enable();
        break;
    }
    gTasks[taskId].tState_mirage_tower++;
}

static void Task_FossilFallAndSink_mirage_tower(u8 taskId)
{
    u16 i;
    u8 *buffer;

    switch (gTasks[taskId].tState_mirage_tower)
    {
    case 1:
        sFallingFossil_mirage_tower = AllocZeroed(sizeof(*sFallingFossil_mirage_tower));
        sFallingFossil_mirage_tower->frameImageTiles = AllocZeroed(sizeof(sFossil_Gfx_mirage_tower));
        sFallingFossil_mirage_tower->frameImage = AllocZeroed(sizeof(*sFallingFossil_mirage_tower->frameImage));
        sFallingFossil_mirage_tower->disintegrateRand = AllocZeroed(FOSSIL_DISINTEGRATE_LENGTH_mirage_tower * sizeof(u16));
        sFallingFossil_mirage_tower->disintegrateIdx = 0;
        break;
    case 2:
        buffer = sFallingFossil_mirage_tower->frameImageTiles;
        for (i = 0; i < sizeof(sFossil_Gfx_mirage_tower); i++, buffer++)
            *buffer = sFossil_Gfx_mirage_tower[i];
        break;
    case 3:
        sFallingFossil_mirage_tower->frameImage->data = sFallingFossil_mirage_tower->frameImageTiles;
        sFallingFossil_mirage_tower->frameImage->size = sizeof(sFossil_Gfx_mirage_tower);
        break;
    case 4:
        {
            struct SpriteTemplate fossilTemplate = sSpriteTemplate_FallingFossil_mirage_tower;
            fossilTemplate.images = sFallingFossil_mirage_tower->frameImage;
            LoadObjectEventPalette(sSpriteTemplate_FallingFossil_mirage_tower.paletteTag);
            sFallingFossil_mirage_tower->spriteId = CreateSprite(&fossilTemplate, 128, -16, 1);
            gSprites[sFallingFossil_mirage_tower->spriteId].centerToCornerVecX = 0;
            gSprites[sFallingFossil_mirage_tower->spriteId].data[0] = gSprites[sFallingFossil_mirage_tower->spriteId].x;
            gSprites[sFallingFossil_mirage_tower->spriteId].data[1] = 1;
        }
    case 5:
        // Initialize disintegration pattern
        for (i = 0; i < FOSSIL_DISINTEGRATE_LENGTH_mirage_tower; i++)
            sFallingFossil_mirage_tower->disintegrateRand[i] = i;
        break;
    case 6:
        // Randomize disintegration pattern
        Shuffle(sFallingFossil_mirage_tower->disintegrateRand, FOSSIL_DISINTEGRATE_LENGTH_mirage_tower,
            sizeof(sFallingFossil_mirage_tower->disintegrateRand[0]));
        gSprites[sFallingFossil_mirage_tower->spriteId].callback = SpriteCB_FallingFossil_mirage_tower;
        break;
    case 7:
        // Wait for fossil to finish falling / disintegrating
        if (gSprites[sFallingFossil_mirage_tower->spriteId].callback != SpriteCallbackDummy)
            return;
        gSprites[sFallingFossil_mirage_tower->spriteId].inUse = FALSE;
        FieldEffectFreePaletteIfUnused(gSprites[sFallingFossil_mirage_tower->spriteId].oam.paletteNum);
        gSprites[sFallingFossil_mirage_tower->spriteId].inUse = TRUE;
        DestroySprite(&gSprites[sFallingFossil_mirage_tower->spriteId]);
        FREE_AND_SET_NULL(sFallingFossil_mirage_tower->disintegrateRand);;
        FREE_AND_SET_NULL(sFallingFossil_mirage_tower->frameImage);
        FREE_AND_SET_NULL(sFallingFossil_mirage_tower->frameImageTiles);
        FREE_AND_SET_NULL(sFallingFossil_mirage_tower);
        break;
    case 8:
        ScriptContext_Enable();
        break;
    }
    gTasks[taskId].tState_mirage_tower++;
}

static void SpriteCB_FallingFossil_mirage_tower(struct Sprite *sprite)
{
    if (sFallingFossil_mirage_tower->disintegrateIdx >= FOSSIL_DISINTEGRATE_LENGTH_mirage_tower)
    {
        // End animation
        sprite->callback = SpriteCallbackDummy;
    }
    else if (sprite->y >= 96)
    {
        // Fossil has reached the ground, update disintegration animation
        u8 i;
        for (i = 0; i < 2; i++)
            UpdateDisintegrationEffect_mirage_tower(sFallingFossil_mirage_tower->frameImageTiles, sFallingFossil_mirage_tower->disintegrateRand[sFallingFossil_mirage_tower->disintegrateIdx++], 0, 16, 0);

        StartSpriteAnim(sprite, 0);
    }
    else
    {
        // Fossil is still falling
        sprite->y++;
    }
}

static void UpdateDisintegrationEffect_mirage_tower(u8 *tiles, u16 randId, u8 c, u8 size, u8 offset)
{
    u8 heightTiles, height, widthTiles, width;
    u16 var, baseOffset;
    u8 col, row;
    u8 flag, tileMask;

    height = randId / size;
    sDebug_DisintegrationData_mirage_tower[0] = height;

    width = randId % size;
    sDebug_DisintegrationData_mirage_tower[1] = width;

    row = height & 7;
    col = width & 7;
    sDebug_DisintegrationData_mirage_tower[2] = height & 7;
    sDebug_DisintegrationData_mirage_tower[3] = width & 7;

    widthTiles = width / 8;
    heightTiles = height / 8;
    sDebug_DisintegrationData_mirage_tower[4] = width / 8;
    sDebug_DisintegrationData_mirage_tower[5] = height / 8;

    var = (size / 8) * (heightTiles * 64) + (widthTiles * 64);
    sDebug_DisintegrationData_mirage_tower[6] = var;

    baseOffset = var + ((row * 8) + col);
    baseOffset /= 2;
    sDebug_DisintegrationData_mirage_tower[7] = var + ((row * 8) + col);

    flag = ((randId % 2) ^ 1);
    tileMask = (c << (flag << 2)) | 15 << (((flag ^ 1) << 2));
    tiles[baseOffset + (offset * 32)] &= tileMask;
}
