static void VBlankCB_mystery_event_menu(void)
{
    LoadOam();
    ProcessSpriteCopyRequests();
    TransferPlttBuffer();
}

static bool8 CheckLanguageMatch_mystery_event_menu(void)
{
    return (gLinkPlayers[0].language == gLinkPlayers[1].language);
}

void CB2_InitMysteryEventMenu(void)
{
    ResetSpriteData();
    FreeAllSpritePalettes();
    ResetTasks();
    SetVBlankCallback(VBlankCB_mystery_event_menu);
    ResetBgsAndClearDma3BusyFlags(0);
    InitBgsFromTemplates(0, sBgTemplates_mystery_event_menu, ARRAY_COUNT(sBgTemplates_mystery_event_menu));
    if (InitWindows(sWindowTemplates_mystery_event_menu))
    {
        s32 i;

        DeactivateAllTextPrinters();
        for (i = 0; i < (int)ARRAY_COUNT(sWindowTemplates_mystery_event_menu) - 1; i++)
            FillWindowPixelBuffer(i, PIXEL_FILL(0));

        FillBgTilemapBufferRect_Palette0(0, 0, 0, 0, DISPLAY_TILE_WIDTH, DISPLAY_TILE_HEIGHT);
        LoadUserWindowBorderGfx(0, 1, BG_PLTT_ID(13));
        Menu_LoadStdPalAt(BG_PLTT_ID(14));
        SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_MODE_0 | DISPCNT_OBJ_1D_MAP | DISPCNT_BG0_ON);
        SetGpuReg(REG_OFFSET_BLDCNT, 0);
        CreateTask(Task_DestroySelf, 0);
        StopMapMusic();
        RunTasks();
        AnimateSprites();
        BuildOamBuffer();
        RunTextPrinters();
        UpdatePaletteFade();
        SetBackdropFromColor(RGB_BLACK);
        SetMainCallback2(CB2_MysteryEventMenu_mystery_event_menu);
    }
}

static bool8 GetEventLoadMessage_mystery_event_menu(u8 *dest, u32 status)
{
    bool8 retVal = TRUE;

    if (status == MEVENT_STATUS_LOAD_OK)
    {
        StringCopy(dest, gText_EventSafelyLoaded);
        retVal = FALSE;
    }

    if (status == MEVENT_STATUS_SUCCESS)
        retVal = FALSE;

    if (status == MEVENT_STATUS_LOAD_ERROR)
        StringCopy(dest, gText_LoadErrorEndingSession);

    return retVal;
}

static void CB2_MysteryEventMenu_mystery_event_menu(void)
{
    switch (gMain.state)
    {
    case 0:
        DrawStdFrameWithCustomTileAndPalette(WIN_MSG_mystery_event_menu, TRUE, 1, 0xD);
        PutWindowTilemap(WIN_MSG_mystery_event_menu);
        CopyWindowToVram(WIN_MSG_mystery_event_menu, COPYWIN_FULL);
        ShowBg(0);
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0x10, 0, RGB_BLACK);
        gMain.state++;
        break;
    case 1:
        if (!gPaletteFade.active)
        {
            PrintMysteryMenuText_mystery_event_menu(WIN_MSG_mystery_event_menu, gText_LinkStandby2, 1, 2, 1);
            gMain.state++;
        }
        break;
    case 2:
        if (!IsTextPrinterActive(WIN_MSG_mystery_event_menu))
        {
            gMain.state++;
            gLinkType = LINKTYPE_MYSTERY_EVENT;
            OpenLink();
        }
        break;
    case 3:
        if ((gLinkStatus & LINK_STAT_MASTER) && (gLinkStatus & LINK_STAT_PLAYER_COUNT) > 4)
        {
            PlaySE(SE_PIN);
            PrintMysteryMenuText_mystery_event_menu(WIN_MSG_mystery_event_menu, gText_PressAToLoadEvent, 1, 2, 1);
            gMain.state++;
        }
        if (JOY_NEW(B_BUTTON))
        {
            PlaySE(SE_SELECT);
            CloseLink();
            gMain.state = 15;
        }
        break;
    case 4:
        if (!IsTextPrinterActive(WIN_MSG_mystery_event_menu))
            gMain.state++;
        break;
    case 5:
        if (GetLinkPlayerCount_2() == 2)
        {
            if (JOY_NEW(A_BUTTON))
            {
                PlaySE(SE_SELECT);
                CheckShouldAdvanceLinkState();
                DrawStdFrameWithCustomTileAndPalette(WIN_LOADING_mystery_event_menu, TRUE, 1, 0xD);
                PrintMysteryMenuText_mystery_event_menu(WIN_LOADING_mystery_event_menu, gText_LoadingEvent, 1, 2, 0);
                PutWindowTilemap(WIN_LOADING_mystery_event_menu);
                CopyWindowToVram(WIN_LOADING_mystery_event_menu, COPYWIN_FULL);
                gMain.state++;
            }
            else if (JOY_NEW(B_BUTTON))
            {
                PlaySE(SE_SELECT);
                CloseLink();
                gMain.state = 15;
            }
        }
        else
        {
            GetEventLoadMessage_mystery_event_menu(gStringVar4, MEVENT_STATUS_LOAD_ERROR);
            PrintMysteryMenuText_mystery_event_menu(WIN_MSG_mystery_event_menu, gStringVar4, 1, 2, 1);
            gMain.state = 13;
        }
        break;
    case 6:
        if (IsLinkConnectionEstablished())
        {
            if (gReceivedRemoteLinkPlayers)
            {
                if (GetLinkPlayerDataExchangeStatusTimed(2, 2) == EXCHANGE_DIFF_SELECTIONS)
                {
                    SetCloseLinkCallback();
                    GetEventLoadMessage_mystery_event_menu(gStringVar4, MEVENT_STATUS_LOAD_ERROR);
                    PrintMysteryMenuText_mystery_event_menu(WIN_MSG_mystery_event_menu, gStringVar4, 1, 2, 1);
                    gMain.state = 13;
                }
                else if (CheckLanguageMatch_mystery_event_menu())
                {
                    PrintMysteryMenuText_mystery_event_menu(WIN_MSG_mystery_event_menu, gText_DontRemoveCableTurnOff, 1, 2, 1);
                    gMain.state++;
                }
                else
                {
                    CloseLink();
                    GetEventLoadMessage_mystery_event_menu(gStringVar4, MEVENT_STATUS_LOAD_ERROR);
                    PrintMysteryMenuText_mystery_event_menu(WIN_MSG_mystery_event_menu, gStringVar4, 1, 2, 1);
                    gMain.state = 13;
                }
            }
        }
        else if (JOY_NEW(B_BUTTON))
        {
            PlaySE(SE_SELECT);
            CloseLink();
            gMain.state = 15;
        }
        break;
    case 7:
        if (!IsTextPrinterActive(WIN_MSG_mystery_event_menu))
            gMain.state++;
        break;
    case 8:
        if (GetBlockReceivedStatus())
        {
            ResetBlockReceivedFlags();
            gMain.state++;
        }
        break;
    case 9:
        gMain.state++;
        break;
    case 10:
        SetCloseLinkCallback();
        gMain.state++;
        break;
    case 11:
        if (gReceivedRemoteLinkPlayers == 0)
        {
            u16 status = RunMysteryEventScript(gDecompressionBuffer);
            CpuFill32(0, gDecompressionBuffer, 0x7D4);
            if (!GetEventLoadMessage_mystery_event_menu(gStringVar4, status))
                TrySavingData(SAVE_NORMAL);
            gMain.state++;
        }
        break;
    case 12:
        PrintMysteryMenuText_mystery_event_menu(WIN_MSG_mystery_event_menu, gStringVar4, 1, 2, 1);
        gMain.state++;
        break;
    case 13:
        if (!IsTextPrinterActive(WIN_MSG_mystery_event_menu))
        {
            gMain.state++;
            sUnused_mystery_event_menu = 0;
        }
        break;
    case 14:
        if (JOY_NEW(A_BUTTON))
        {
            PlaySE(SE_SELECT);
            gMain.state++;
        }
        break;
    case 15:
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 0x10, RGB_BLACK);
        gMain.state++;
        break;
    case 16:
        if (!gPaletteFade.active)
            DoSoftReset();
        break;
    }

    if (gLinkStatus & LINK_STAT_CONN_ESTABLISHED && !IsLinkMaster())
    {
        CloseLink();
        GetEventLoadMessage_mystery_event_menu(gStringVar4, MEVENT_STATUS_LOAD_ERROR);
        PrintMysteryMenuText_mystery_event_menu(WIN_MSG_mystery_event_menu, gStringVar4, 1, 2, 1);
        gMain.state = 13;
    }

    RunTasks();
    AnimateSprites();
    BuildOamBuffer();
    RunTextPrinters();
    UpdatePaletteFade();
}

static void PrintMysteryMenuText_mystery_event_menu(u8 windowId, const u8 *text, u8 x, u8 y, s32 speed)
{
    u8 textColor[3];
    u8 letterSpacing = 0;
    u8 lineSpacing = 1;
    textColor[0] = 1;
    textColor[1] = 2;
    textColor[2] = 3;

    FillWindowPixelBuffer(windowId, PIXEL_FILL(textColor[0]));
    AddTextPrinterParameterized4(windowId, FONT_NORMAL, x, y, letterSpacing, lineSpacing, textColor, speed, text);
}
