bool32 WonderCard_Init(struct WonderCard * card, struct WonderCardMetadata * metadata)
{
    if (card == NULL || metadata == NULL)
        return FALSE;
    sWonderCardData_mystery_gift_view = AllocZeroed(sizeof(*sWonderCardData_mystery_gift_view));
    if (sWonderCardData_mystery_gift_view == NULL)
        return FALSE;
    sWonderCardData_mystery_gift_view->card = *card;
    sWonderCardData_mystery_gift_view->cardMetadata = *metadata;
    if (sWonderCardData_mystery_gift_view->card.bgType >= NUM_WONDER_BGS)
        sWonderCardData_mystery_gift_view->card.bgType = 0;
    if (sWonderCardData_mystery_gift_view->card.type >= CARD_TYPE_COUNT)
        sWonderCardData_mystery_gift_view->card.type = 0;
    if (sWonderCardData_mystery_gift_view->card.maxStamps > MAX_STAMP_CARD_STAMPS)
        sWonderCardData_mystery_gift_view->card.maxStamps = 0;
    sWonderCardData_mystery_gift_view->gfx = &sCardGraphics_mystery_gift_view[sWonderCardData_mystery_gift_view->card.bgType];
    return TRUE;
}

void WonderCard_Destroy(void)
{
    if (sWonderCardData_mystery_gift_view != NULL)
    {
        *sWonderCardData_mystery_gift_view = (struct WonderCardData){};
        FREE_AND_SET_NULL(sWonderCardData_mystery_gift_view);
    }
}

s32 WonderCard_Enter(void)
{
    if (sWonderCardData_mystery_gift_view == NULL)
        return -1;
    switch(sWonderCardData_mystery_gift_view->enterExitState)
    {
    case 0:
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
        break;
    case 1:
        if (UpdatePaletteFade())
            return 0;
        break;
    case 2:
        FillBgTilemapBufferRect_Palette0(0, 0x000, 0, 0, DISPLAY_TILE_WIDTH, DISPLAY_TILE_HEIGHT);
        FillBgTilemapBufferRect_Palette0(1, 0x000, 0, 0, DISPLAY_TILE_WIDTH, DISPLAY_TILE_HEIGHT);
        FillBgTilemapBufferRect_Palette0(2, 0x000, 0, 0, DISPLAY_TILE_WIDTH, DISPLAY_TILE_HEIGHT);
        CopyBgTilemapBufferToVram(0);
        CopyBgTilemapBufferToVram(1);
        CopyBgTilemapBufferToVram(2);
        DecompressAndCopyTileDataToVram(2, sWonderCardData_mystery_gift_view->gfx->tiles, 0, 0x008, 0);
        sWonderCardData_mystery_gift_view->windowIds[CARD_WIN_HEADER_mystery_gift_view] = AddWindow(&sCard_WindowTemplates_mystery_gift_view[CARD_WIN_HEADER_mystery_gift_view]);
        sWonderCardData_mystery_gift_view->windowIds[CARD_WIN_BODY_mystery_gift_view] = AddWindow(&sCard_WindowTemplates_mystery_gift_view[CARD_WIN_BODY_mystery_gift_view]);
        sWonderCardData_mystery_gift_view->windowIds[CARD_WIN_FOOTER_mystery_gift_view] = AddWindow(&sCard_WindowTemplates_mystery_gift_view[CARD_WIN_FOOTER_mystery_gift_view]);
        break;
    case 3:
        if (FreeTempTileDataBuffersIfPossible())
            return 0;
        LoadPalette(GetTextWindowPalette(1), BG_PLTT_ID(2), PLTT_SIZE_4BPP);
        gPaletteFade.bufferTransferDisabled = TRUE;
        LoadPalette(sWonderCardData_mystery_gift_view->gfx->pal, BG_PLTT_ID(1), PLTT_SIZE_4BPP);
        LZ77UnCompWram(sWonderCardData_mystery_gift_view->gfx->map, sWonderCardData_mystery_gift_view->bgTilemapBuffer);
        CopyRectToBgTilemapBufferRect(2, sWonderCardData_mystery_gift_view->bgTilemapBuffer, 0, 0, DISPLAY_TILE_WIDTH, DISPLAY_TILE_HEIGHT, 0, 0, DISPLAY_TILE_WIDTH, DISPLAY_TILE_HEIGHT, 1, 0x008, 0);
        CopyBgTilemapBufferToVram(2);
        break;
    case 4:
        BufferCardText_mystery_gift_view();
        break;
    case 5:
        DrawCardWindow_mystery_gift_view(CARD_WIN_HEADER_mystery_gift_view);
        DrawCardWindow_mystery_gift_view(CARD_WIN_BODY_mystery_gift_view);
        DrawCardWindow_mystery_gift_view(CARD_WIN_FOOTER_mystery_gift_view);
        CopyBgTilemapBufferToVram(1);
        break;
    case 6:
        LoadMonIconPalettes();
        break;
    case 7:
        ShowBg(1);
        ShowBg(2);
        gPaletteFade.bufferTransferDisabled = FALSE;
        CreateCardSprites_mystery_gift_view();
        BeginNormalPaletteFade(PALETTES_ALL, 0, 16, 0, RGB_BLACK);
        UpdatePaletteFade();
        break;
    default:
        if (UpdatePaletteFade())
            return 0;
        sWonderCardData_mystery_gift_view->enterExitState = 0;
        return 1;
    }
    sWonderCardData_mystery_gift_view->enterExitState++;
    return 0;
}

s32 WonderCard_Exit(bool32 useCancel)
{
    if (sWonderCardData_mystery_gift_view == NULL)
        return -1;
    switch (sWonderCardData_mystery_gift_view->enterExitState)
    {
    case 0:
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
        break;
    case 1:
        if (UpdatePaletteFade())
            return 0;
        break;
    case 2:
        FillBgTilemapBufferRect_Palette0(0, 0x000, 0, 0, DISPLAY_TILE_WIDTH, DISPLAY_TILE_HEIGHT);
        FillBgTilemapBufferRect_Palette0(1, 0x000, 0, 0, DISPLAY_TILE_WIDTH, DISPLAY_TILE_HEIGHT);
        FillBgTilemapBufferRect_Palette0(2, 0x000, 0, 0, DISPLAY_TILE_WIDTH, DISPLAY_TILE_HEIGHT);
        CopyBgTilemapBufferToVram(0);
        CopyBgTilemapBufferToVram(1);
        CopyBgTilemapBufferToVram(2);
        break;
    case 3:
        HideBg(1);
        HideBg(2);
        RemoveWindow(sWonderCardData_mystery_gift_view->windowIds[CARD_WIN_FOOTER_mystery_gift_view]);
        RemoveWindow(sWonderCardData_mystery_gift_view->windowIds[CARD_WIN_BODY_mystery_gift_view]);
        RemoveWindow(sWonderCardData_mystery_gift_view->windowIds[CARD_WIN_HEADER_mystery_gift_view]);
        break;
    case 4:
        DestroyCardSprites_mystery_gift_view();
        FreeMonIconPalettes();
        break;
    case 5:
        PrintMysteryGiftOrEReaderHeader(gGiftIsFromEReader, useCancel);
        CopyBgTilemapBufferToVram(0);
        BeginNormalPaletteFade(PALETTES_ALL, 0, 16, 0, RGB_BLACK);
        break;
    default:
        if (UpdatePaletteFade())
            return 0;
        sWonderCardData_mystery_gift_view->enterExitState = 0;
        return 1;
    }
    sWonderCardData_mystery_gift_view->enterExitState++;
    return 0;
}

static void BufferCardText_mystery_gift_view(void)
{
    u16 i = 0;
    u16 charsUntilStat;
    u16 stats[3] = {0, 0, 0};

    // Copy title/subtitle text
    memcpy(sWonderCardData_mystery_gift_view->titleText, sWonderCardData_mystery_gift_view->card.titleText, WONDER_CARD_TEXT_LENGTH);
    sWonderCardData_mystery_gift_view->titleText[WONDER_CARD_TEXT_LENGTH] = EOS;
    memcpy(sWonderCardData_mystery_gift_view->subtitleText, sWonderCardData_mystery_gift_view->card.subtitleText, WONDER_CARD_TEXT_LENGTH);
    sWonderCardData_mystery_gift_view->subtitleText[WONDER_CARD_TEXT_LENGTH] = EOS;

    // Copy card id number
    if (sWonderCardData_mystery_gift_view->card.idNumber > 999999)
        sWonderCardData_mystery_gift_view->card.idNumber = 999999;
    ConvertIntToDecimalStringN(sWonderCardData_mystery_gift_view->idNumberText, sWonderCardData_mystery_gift_view->card.idNumber, STR_CONV_MODE_LEFT_ALIGN, 6);

    // Copy body text
    for (i = 0; i < WONDER_CARD_BODY_TEXT_LINES; i++)
    {
        memcpy(sWonderCardData_mystery_gift_view->bodyText[i], sWonderCardData_mystery_gift_view->card.bodyText[i], WONDER_CARD_TEXT_LENGTH);
        sWonderCardData_mystery_gift_view->bodyText[i][WONDER_CARD_TEXT_LENGTH] = EOS;
    }

    // Copy footer line 1
    memcpy(sWonderCardData_mystery_gift_view->footerLine1Text, sWonderCardData_mystery_gift_view->card.footerLine1Text, WONDER_CARD_TEXT_LENGTH);
    sWonderCardData_mystery_gift_view->footerLine1Text[WONDER_CARD_TEXT_LENGTH] = EOS;

    // Copy footer line 2
    switch (sWonderCardData_mystery_gift_view->card.type)
    {
    case CARD_TYPE_GIFT:
        memcpy(sWonderCardData_mystery_gift_view->giftText, sWonderCardData_mystery_gift_view->card.footerLine2Text, WONDER_CARD_TEXT_LENGTH);
        sWonderCardData_mystery_gift_view->giftText[WONDER_CARD_TEXT_LENGTH] = EOS;
        break;
    case CARD_TYPE_STAMP:
        sWonderCardData_mystery_gift_view->giftText[0] = EOS;
        break;
    case CARD_TYPE_LINK_STAT:
        sWonderCardData_mystery_gift_view->giftText[0] = EOS;

        // Load stats
        stats[0] = sWonderCardData_mystery_gift_view->cardMetadata.battlesWon < MAX_WONDER_CARD_STAT ? sWonderCardData_mystery_gift_view->cardMetadata.battlesWon : MAX_WONDER_CARD_STAT;
        stats[1] = sWonderCardData_mystery_gift_view->cardMetadata.battlesLost < MAX_WONDER_CARD_STAT ? sWonderCardData_mystery_gift_view->cardMetadata.battlesLost : MAX_WONDER_CARD_STAT;
        stats[2] = sWonderCardData_mystery_gift_view->cardMetadata.numTrades < MAX_WONDER_CARD_STAT ? sWonderCardData_mystery_gift_view->cardMetadata.numTrades : MAX_WONDER_CARD_STAT;

        // Init stat text arrays
        for (i = 0; i < ARRAY_COUNT(sWonderCardData_mystery_gift_view->statTextData); i++)
        {
            memset(sWonderCardData_mystery_gift_view->statTextData[i].statNumberText, EOS, sizeof(sWonderCardData_mystery_gift_view->statTextData[i].statNumberText));
            memset(sWonderCardData_mystery_gift_view->statTextData[i].statText,       EOS, sizeof(sWonderCardData_mystery_gift_view->statTextData[i].statText));
        }

        // Copy stat texts
        for (i = 0, charsUntilStat = 0; i < WONDER_CARD_TEXT_LENGTH; i++)
        {
            if (sWonderCardData_mystery_gift_view->card.footerLine2Text[i] != CHAR_DYNAMIC)
            {
                // Regular text, just copy as is
                sWonderCardData_mystery_gift_view->statTextData[sWonderCardData_mystery_gift_view->statFooterWidth].statText[charsUntilStat] = sWonderCardData_mystery_gift_view->card.footerLine2Text[i];
                charsUntilStat++;
            }
            else
            {
                // Dynamic char encountered
                // These are used to give the id of which stat to print
                u8 id = sWonderCardData_mystery_gift_view->card.footerLine2Text[i + 1];
                if (id >= ARRAY_COUNT(stats))
                {
                    // Invalid stat id, skip ahead
                    i += 2;
                }
                else
                {
                    // Copy stat number
                    ConvertIntToDecimalStringN(sWonderCardData_mystery_gift_view->statTextData[sWonderCardData_mystery_gift_view->statFooterWidth].statNumberText, stats[id], STR_CONV_MODE_LEADING_ZEROS, 3);
                    sWonderCardData_mystery_gift_view->statTextData[sWonderCardData_mystery_gift_view->statFooterWidth].width = sWonderCardData_mystery_gift_view->card.footerLine2Text[i + 2];
                    sWonderCardData_mystery_gift_view->statFooterWidth++;
                    if (sWonderCardData_mystery_gift_view->statFooterWidth >= ARRAY_COUNT(sWonderCardData_mystery_gift_view->statTextData))
                        break;
                    charsUntilStat = 0;
                    i += 2;
                }
            }
        }
    }
}

static void DrawCardWindow_mystery_gift_view(u8 whichWindow)
{
    s8 i = 0;
    s32 windowId = sWonderCardData_mystery_gift_view->windowIds[whichWindow];
    PutWindowTilemap(windowId);
    FillWindowPixelBuffer(windowId, 0);
    switch (whichWindow)
    {
    case CARD_WIN_HEADER_mystery_gift_view:
    {
        // Print card title/subtitle
        s32 x;
        AddTextPrinterParameterized3(windowId, FONT_SHORT_COPY_1, 0, 1, sCard_TextColorTable_mystery_gift_view[sWonderCardData_mystery_gift_view->gfx->titleTextPal], 0, sWonderCardData_mystery_gift_view->titleText);
        x = 160 - GetStringWidth(FONT_SHORT_COPY_1, sWonderCardData_mystery_gift_view->subtitleText, GetFontAttribute(FONT_SHORT_COPY_1, FONTATTR_LETTER_SPACING));
        if (x < 0)
            x = 0;
        AddTextPrinterParameterized3(windowId, FONT_SHORT_COPY_1, x, 17, sCard_TextColorTable_mystery_gift_view[sWonderCardData_mystery_gift_view->gfx->titleTextPal], 0, sWonderCardData_mystery_gift_view->subtitleText);

        // Print id number
        if (sWonderCardData_mystery_gift_view->card.idNumber != 0)
            AddTextPrinterParameterized3(windowId, FONT_NORMAL, 166, 17, sCard_TextColorTable_mystery_gift_view[sWonderCardData_mystery_gift_view->gfx->titleTextPal], 0, sWonderCardData_mystery_gift_view->idNumberText);
        break;
    }
    case CARD_WIN_BODY_mystery_gift_view:
        // Print body text
        for (; i < WONDER_CARD_BODY_TEXT_LINES; i++)
            AddTextPrinterParameterized3(windowId, FONT_SHORT_COPY_1, 0, 16 * i + 2, sCard_TextColorTable_mystery_gift_view[sWonderCardData_mystery_gift_view->gfx->bodyTextPal], 0, sWonderCardData_mystery_gift_view->bodyText[i]);
        break;
    case CARD_WIN_FOOTER_mystery_gift_view:
        // Print footer line 1
        AddTextPrinterParameterized3(windowId, FONT_SHORT_COPY_1, 0,
                                     sCard_FooterTextOffsets[sWonderCardData_mystery_gift_view->card.type],
                                     sCard_TextColorTable_mystery_gift_view[sWonderCardData_mystery_gift_view->gfx->footerTextPal],
                                     0, sWonderCardData_mystery_gift_view->footerLine1Text);

        // Print footer line 2
        if (sWonderCardData_mystery_gift_view->card.type != CARD_TYPE_LINK_STAT)
        {
            // Print gift text
            // Odd that CARD_TYPE_STAMP is not ignored, it has empty text for this
            AddTextPrinterParameterized3(windowId, FONT_SHORT_COPY_1, 0,
                                         16 + sCard_FooterTextOffsets[sWonderCardData_mystery_gift_view->card.type],
                                         sCard_TextColorTable_mystery_gift_view[sWonderCardData_mystery_gift_view->gfx->footerTextPal],
                                         0, sWonderCardData_mystery_gift_view->giftText);
        }
        else
        {
            s32 x = 0;
            s32 y = sCard_FooterTextOffsets[sWonderCardData_mystery_gift_view->card.type] + 16;
            s32 spacing = GetFontAttribute(FONT_SHORT_COPY_1, FONTATTR_LETTER_SPACING);
            for (; i < sWonderCardData_mystery_gift_view->statFooterWidth; i++)
            {
                // Print stat text
                AddTextPrinterParameterized3(windowId, FONT_SHORT_COPY_1, x, y, sCard_TextColorTable_mystery_gift_view[sWonderCardData_mystery_gift_view->gfx->footerTextPal], 0, sWonderCardData_mystery_gift_view->statTextData[i].statText);
                if (sWonderCardData_mystery_gift_view->statTextData[i].statNumberText[0] != EOS)
                {
                    // Print stat number
                    x += GetStringWidth(FONT_SHORT_COPY_1, sWonderCardData_mystery_gift_view->statTextData[i].statText, spacing);
                    AddTextPrinterParameterized3(windowId, FONT_SHORT_COPY_1, x, y,
                                                 sCard_TextColorTable_mystery_gift_view[sWonderCardData_mystery_gift_view->gfx->footerTextPal],
                                                 0, sWonderCardData_mystery_gift_view->statTextData[i].statNumberText);
                    x += GetStringWidth(FONT_SHORT_COPY_1, sWonderCardData_mystery_gift_view->statTextData[i].statNumberText, spacing) + sWonderCardData_mystery_gift_view->statTextData[i].width;
                }
            }
        }
        break;
    }
    CopyWindowToVram(windowId, COPYWIN_FULL);
}

static void CreateCardSprites_mystery_gift_view(void)
{
    u8 i = 0;
    sWonderCardData_mystery_gift_view->monIconSpriteId = SPRITE_NONE;

    // Create icon sprite
    if (sWonderCardData_mystery_gift_view->cardMetadata.iconSpecies != SPECIES_NONE)
    {
        sWonderCardData_mystery_gift_view->monIconSpriteId = CreateMonIconNoPersonality(GetIconSpeciesNoPersonality(sWonderCardData_mystery_gift_view->cardMetadata.iconSpecies), SpriteCallbackDummy, 220, 20, 0);
        gSprites[sWonderCardData_mystery_gift_view->monIconSpriteId].oam.priority = 2;
    }

    // Create stamp sprites
    if (sWonderCardData_mystery_gift_view->card.maxStamps != 0 && sWonderCardData_mystery_gift_view->card.type == CARD_TYPE_STAMP)
    {
        LoadCompressedSpriteSheetUsingHeap(&sSpriteSheet_StampShadow_mystery_gift_view);
        LoadSpritePalette(&sSpritePalettes_StampShadow_mystery_gift_view[sWonderCardData_mystery_gift_view->gfx->stampShadowPal]);
        for (; i < sWonderCardData_mystery_gift_view->card.maxStamps; i++)
        {
            sWonderCardData_mystery_gift_view->stampSpriteIds[i][0] = SPRITE_NONE;
            sWonderCardData_mystery_gift_view->stampSpriteIds[i][1] = SPRITE_NONE;
            sWonderCardData_mystery_gift_view->stampSpriteIds[i][0] = CreateSprite(&sSpriteTemplate_StampShadow_mystery_gift_view, 216 - 32 * i, 144, 8);
            if (sWonderCardData_mystery_gift_view->cardMetadata.stampData[STAMP_SPECIES][i] != SPECIES_NONE)
                sWonderCardData_mystery_gift_view->stampSpriteIds[i][1] = CreateMonIconNoPersonality(GetIconSpeciesNoPersonality(sWonderCardData_mystery_gift_view->cardMetadata.stampData[STAMP_SPECIES][i]),
                                                                               SpriteCallbackDummy,
                                                                               216 - 32 * i,
                                                                               136, 0);
        }
    }
}

static void DestroyCardSprites_mystery_gift_view(void)
{
    u8 i = 0;

    // Destroy icon sprite
    if (sWonderCardData_mystery_gift_view->monIconSpriteId != SPRITE_NONE)
        FreeAndDestroyMonIconSprite(&gSprites[sWonderCardData_mystery_gift_view->monIconSpriteId]);

    // Destroy stamp sprites
    if (sWonderCardData_mystery_gift_view->card.maxStamps != 0 && sWonderCardData_mystery_gift_view->card.type == CARD_TYPE_STAMP)
    {
        for (; i < sWonderCardData_mystery_gift_view->card.maxStamps; i++)
        {
            if (sWonderCardData_mystery_gift_view->stampSpriteIds[i][0] != SPRITE_NONE)
                DestroySprite(&gSprites[sWonderCardData_mystery_gift_view->stampSpriteIds[i][0]]);
            if (sWonderCardData_mystery_gift_view->stampSpriteIds[i][1] != SPRITE_NONE)
                FreeAndDestroyMonIconSprite(&gSprites[sWonderCardData_mystery_gift_view->stampSpriteIds[i][1]]);
        }
        FreeSpriteTilesByTag(TAG_STAMP_SHADOW_mystery_gift_view);
        FreeSpritePaletteByTag(TAG_STAMP_SHADOW_mystery_gift_view);
    }
}

