bool32 WonderNews_Init(const struct WonderNews * news)
{
    if (news == NULL)
        return FALSE;
    sWonderNewsData_mystery_gift_view = AllocZeroed(sizeof(*sWonderNewsData_mystery_gift_view));
    if (sWonderNewsData_mystery_gift_view == NULL)
        return FALSE;
    sWonderNewsData_mystery_gift_view->news = *news;
    if (sWonderNewsData_mystery_gift_view->news.bgType >= NUM_WONDER_BGS)
        sWonderNewsData_mystery_gift_view->news.bgType = 0;
    sWonderNewsData_mystery_gift_view->gfx = &sNewsGraphics_mystery_gift_view[sWonderNewsData_mystery_gift_view->news.bgType];
    sWonderNewsData_mystery_gift_view->arrowTaskId = TASK_NONE;
    return TRUE;
}

void WonderNews_Destroy(void)
{
    if (sWonderNewsData_mystery_gift_view != NULL)
    {
        *sWonderNewsData_mystery_gift_view = (struct WonderNewsData){};
        FREE_AND_SET_NULL(sWonderNewsData_mystery_gift_view);
    }
}

s32 WonderNews_Enter(void)
{
    if (sWonderNewsData_mystery_gift_view == NULL)
        return -1;

    switch (sWonderNewsData_mystery_gift_view->enterExitState)
    {
    case 0:
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
        break;
    case 1:
        if (UpdatePaletteFade())
            return 0;
        ChangeBgY(0, 0, BG_COORD_SET);
        ChangeBgY(1, 0, BG_COORD_SET);
        ChangeBgY(2, 0, BG_COORD_SET);
        ChangeBgY(3, 0, BG_COORD_SET);
        SetGpuReg(REG_OFFSET_WIN0H, WIN_RANGE(0, DISPLAY_WIDTH));
        SetGpuReg(REG_OFFSET_WIN0V, WIN_RANGE(26, 152));
        SetGpuReg(REG_OFFSET_WININ, WININ_WIN0_BG_ALL | WININ_WIN0_OBJ);
        SetGpuReg(REG_OFFSET_WINOUT, WINOUT_WIN01_BG0 | WINOUT_WIN01_BG1 | WINOUT_WIN01_BG3 | WINOUT_WIN01_OBJ);
        SetGpuRegBits(REG_OFFSET_DISPCNT, DISPCNT_WIN0_ON);
        break;
    case 2:
        FillBgTilemapBufferRect_Palette0(0, 0x000, 0, 0, DISPLAY_TILE_WIDTH, DISPLAY_TILE_HEIGHT);
        FillBgTilemapBufferRect_Palette0(1, 0x000, 0, 0, DISPLAY_TILE_WIDTH, DISPLAY_TILE_HEIGHT);
        FillBgTilemapBufferRect_Palette0(2, 0x000, 0, 0, DISPLAY_TILE_WIDTH, DISPLAY_TILE_HEIGHT);
        FillBgTilemapBufferRect_Palette0(3, 0x000, 0, 0, DISPLAY_TILE_WIDTH, DISPLAY_TILE_HEIGHT);
        CopyBgTilemapBufferToVram(0);
        CopyBgTilemapBufferToVram(1);
        CopyBgTilemapBufferToVram(2);
        CopyBgTilemapBufferToVram(3);
        DecompressAndCopyTileDataToVram(3, sWonderNewsData_mystery_gift_view->gfx->tiles, 0, 8, 0);
        sWonderNewsData_mystery_gift_view->windowIds[NEWS_WIN_TITLE_mystery_gift_view] = AddWindow(&sNews_WindowTemplates_mystery_gift_view[NEWS_WIN_TITLE_mystery_gift_view]);
        sWonderNewsData_mystery_gift_view->windowIds[NEWS_WIN_BODY_mystery_gift_view] = AddWindow(&sNews_WindowTemplates_mystery_gift_view[NEWS_WIN_BODY_mystery_gift_view]);
        break;
    case 3:
        if (FreeTempTileDataBuffersIfPossible())
            return 0;
        LoadPalette(GetTextWindowPalette(1), BG_PLTT_ID(2), PLTT_SIZE_4BPP);
        gPaletteFade.bufferTransferDisabled = TRUE;
        LoadPalette(sWonderNewsData_mystery_gift_view->gfx->pal, BG_PLTT_ID(1), PLTT_SIZE_4BPP);
        LZ77UnCompWram(sWonderNewsData_mystery_gift_view->gfx->map, sWonderNewsData_mystery_gift_view->bgTilemapBuffer);
        CopyRectToBgTilemapBufferRect(1, sWonderNewsData_mystery_gift_view->bgTilemapBuffer, 0, 0, DISPLAY_TILE_WIDTH, 3, 0, 0, DISPLAY_TILE_WIDTH, 3, 1, 8, 0);
        CopyRectToBgTilemapBufferRect(3, sWonderNewsData_mystery_gift_view->bgTilemapBuffer, 0, 3, DISPLAY_TILE_WIDTH, 3 + DISPLAY_TILE_HEIGHT, 0, 3, DISPLAY_TILE_WIDTH, 3 + DISPLAY_TILE_HEIGHT, 1, 8, 0);
        CopyBgTilemapBufferToVram(1);
        CopyBgTilemapBufferToVram(3);
        break;
    case 4:
        BufferNewsText_mystery_gift_view();
        break;
    case 5:
        DrawNewsWindows_mystery_gift_view();
        CopyBgTilemapBufferToVram(0);
        CopyBgTilemapBufferToVram(2);
        break;
    case 6:
        ShowBg(1);
        ShowBg(2);
        ShowBg(3);
        gPaletteFade.bufferTransferDisabled = FALSE;
        sWonderNewsData_mystery_gift_view->arrowTaskId = AddScrollIndicatorArrowPair(&sWonderNewsData_mystery_gift_view->arrowsTemplate, &sWonderNewsData_mystery_gift_view->scrollOffset);
        BeginNormalPaletteFade(PALETTES_ALL, 0, 16, 0, RGB_BLACK);
        UpdatePaletteFade();
        break;
    default:
        if (UpdatePaletteFade())
            return 0;
        sWonderNewsData_mystery_gift_view->enterExitState = 0;
        return 1;
    }

    sWonderNewsData_mystery_gift_view->enterExitState++;
    return 0;
}

s32 WonderNews_Exit(bool32 useCancel)
{
    if (sWonderNewsData_mystery_gift_view == NULL)
        return -1;
    switch (sWonderNewsData_mystery_gift_view->enterExitState)
    {
    case 0:
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
        break;
    case 1:
        if (UpdatePaletteFade())
            return 0;
        ChangeBgY(2, 0, BG_COORD_SET);
        SetGpuReg(REG_OFFSET_WIN0H, 0);
        SetGpuReg(REG_OFFSET_WIN0V, 0);
        SetGpuReg(REG_OFFSET_WININ, 0);
        SetGpuReg(REG_OFFSET_WINOUT, 0);
        ClearGpuRegBits(REG_OFFSET_DISPCNT, DISPCNT_WIN0_ON);
        break;
    case 2:
        FillBgTilemapBufferRect_Palette0(0, 0x000, 0, 0, DISPLAY_TILE_WIDTH, DISPLAY_TILE_HEIGHT);
        FillBgTilemapBufferRect_Palette0(1, 0x000, 0, 0, DISPLAY_TILE_WIDTH, DISPLAY_TILE_HEIGHT);
        FillBgTilemapBufferRect_Palette0(2, 0x000, 0, 0, DISPLAY_TILE_WIDTH, DISPLAY_TILE_HEIGHT + 4);
        FillBgTilemapBufferRect_Palette0(3, 0x000, 0, 0, DISPLAY_TILE_WIDTH, DISPLAY_TILE_HEIGHT + 4);
        CopyBgTilemapBufferToVram(0);
        CopyBgTilemapBufferToVram(1);
        CopyBgTilemapBufferToVram(2);
        CopyBgTilemapBufferToVram(3);
        break;
    case 3:
        HideBg(1);
        HideBg(2);
        RemoveWindow(sWonderNewsData_mystery_gift_view->windowIds[NEWS_WIN_BODY_mystery_gift_view]);
        RemoveWindow(sWonderNewsData_mystery_gift_view->windowIds[NEWS_WIN_TITLE_mystery_gift_view]);
        break;
    case 4:
        ChangeBgY(2, 0, BG_COORD_SET);
        ChangeBgY(3, 0, BG_COORD_SET);
        if (sWonderNewsData_mystery_gift_view->arrowTaskId != TASK_NONE)
        {
            RemoveScrollIndicatorArrowPair(sWonderNewsData_mystery_gift_view->arrowTaskId);
            sWonderNewsData_mystery_gift_view->arrowTaskId = TASK_NONE;
        }
        break;
    case 5:
        PrintMysteryGiftOrEReaderHeader(gGiftIsFromEReader, useCancel);
        MG_DrawCheckerboardPattern(3);
        CopyBgTilemapBufferToVram(0);
        CopyBgTilemapBufferToVram(3);
        BeginNormalPaletteFade(PALETTES_ALL, 0, 16, 0, RGB_BLACK);
        break;
    default:
        if (UpdatePaletteFade())
            return 0;
        sWonderNewsData_mystery_gift_view->enterExitState = 0;
        return 1;
    }
    sWonderNewsData_mystery_gift_view->enterExitState++;
    return 0;
}

void WonderNews_RemoveScrollIndicatorArrowPair(void)
{
    if (!sWonderNewsData_mystery_gift_view->arrowsRemoved && sWonderNewsData_mystery_gift_view->arrowTaskId != TASK_NONE)
    {
        RemoveScrollIndicatorArrowPair(sWonderNewsData_mystery_gift_view->arrowTaskId);
        sWonderNewsData_mystery_gift_view->arrowTaskId = TASK_NONE;
        sWonderNewsData_mystery_gift_view->arrowsRemoved = TRUE;
    }
}


void WonderNews_AddScrollIndicatorArrowPair(void)
{
    if (sWonderNewsData_mystery_gift_view->arrowsRemoved)
    {
        sWonderNewsData_mystery_gift_view->arrowTaskId = AddScrollIndicatorArrowPair(&sWonderNewsData_mystery_gift_view->arrowsTemplate, &sWonderNewsData_mystery_gift_view->scrollOffset);
        sWonderNewsData_mystery_gift_view->arrowsRemoved = FALSE;
    }
}

u32 WonderNews_GetInput(u16 input)
{
    if (sWonderNewsData_mystery_gift_view->scrolling)
    {
        UpdateNewsScroll_mystery_gift_view();
        return NEWS_INPUT_NONE;
    }
    switch (input)
    {
    case A_BUTTON:
        return NEWS_INPUT_A;
    case B_BUTTON:
        return NEWS_INPUT_B;
    case DPAD_UP:
        if (sWonderNewsData_mystery_gift_view->scrollOffset == 0)
            return NEWS_INPUT_NONE;
        if (sWonderNewsData_mystery_gift_view->arrowsRemoved)
            return NEWS_INPUT_NONE;
        sWonderNewsData_mystery_gift_view->scrollingDown = FALSE;
        break;
    case DPAD_DOWN:
        if (sWonderNewsData_mystery_gift_view->scrollOffset == sWonderNewsData_mystery_gift_view->scrollEnd)
            return NEWS_INPUT_NONE;
        if (sWonderNewsData_mystery_gift_view->arrowsRemoved)
            return NEWS_INPUT_NONE;
        sWonderNewsData_mystery_gift_view->scrollingDown = TRUE;
        break;
    default:
        return NEWS_INPUT_NONE;
    }

    // Init scroll
    sWonderNewsData_mystery_gift_view->scrolling = TRUE;
    sWonderNewsData_mystery_gift_view->scrollIncrement = 2;
    sWonderNewsData_mystery_gift_view->scrollTotal = 0;
    if (!sWonderNewsData_mystery_gift_view->scrollingDown)
        return NEWS_INPUT_SCROLL_UP;
    else
        return NEWS_INPUT_SCROLL_DOWN;
}

static void BufferNewsText_mystery_gift_view(void)
{
    u8 i = 0;

    // Copy title text
    memcpy(sWonderNewsData_mystery_gift_view->titleText, sWonderNewsData_mystery_gift_view->news.titleText, WONDER_NEWS_TEXT_LENGTH);
    sWonderNewsData_mystery_gift_view->titleText[WONDER_NEWS_TEXT_LENGTH] = EOS;

    // Copy body text
    for (; i < WONDER_NEWS_BODY_TEXT_LINES; i++)
    {
        memcpy(sWonderNewsData_mystery_gift_view->bodyText[i], sWonderNewsData_mystery_gift_view->news.bodyText[i], WONDER_NEWS_TEXT_LENGTH);
        sWonderNewsData_mystery_gift_view->bodyText[i][WONDER_NEWS_TEXT_LENGTH] = EOS;
        if (i > 7 && sWonderNewsData_mystery_gift_view->bodyText[i][0] != EOS)
            sWonderNewsData_mystery_gift_view->scrollEnd++;
    }
    sWonderNewsData_mystery_gift_view->arrowsTemplate = sNews_ArrowsTemplate_mystery_gift_view;
    sWonderNewsData_mystery_gift_view->arrowsTemplate.fullyDownThreshold = sWonderNewsData_mystery_gift_view->scrollEnd;
}

static void DrawNewsWindows_mystery_gift_view(void)
{
    u8 i = 0;
    s32 x;
    PutWindowTilemap(sWonderNewsData_mystery_gift_view->windowIds[NEWS_WIN_TITLE_mystery_gift_view]);
    PutWindowTilemap(sWonderNewsData_mystery_gift_view->windowIds[NEWS_WIN_BODY_mystery_gift_view]);
    FillWindowPixelBuffer(sWonderNewsData_mystery_gift_view->windowIds[NEWS_WIN_TITLE_mystery_gift_view], 0);
    FillWindowPixelBuffer(sWonderNewsData_mystery_gift_view->windowIds[NEWS_WIN_BODY_mystery_gift_view], 0);

    // Print title text
    x = (224 - GetStringWidth(FONT_SHORT_COPY_1, sWonderNewsData_mystery_gift_view->titleText, GetFontAttribute(FONT_SHORT_COPY_1, FONTATTR_LETTER_SPACING))) / 2;
    if (x < 0)
        x = 0;
    AddTextPrinterParameterized3(sWonderNewsData_mystery_gift_view->windowIds[NEWS_WIN_TITLE_mystery_gift_view], FONT_SHORT_COPY_1, x, 6, sNews_TextColorTable_mystery_gift_view[sWonderNewsData_mystery_gift_view->gfx->titleTextPal], 0, sWonderNewsData_mystery_gift_view->titleText);

    // Print body text
    for (; i < WONDER_NEWS_BODY_TEXT_LINES; i++)
        AddTextPrinterParameterized3(sWonderNewsData_mystery_gift_view->windowIds[NEWS_WIN_BODY_mystery_gift_view], FONT_SHORT_COPY_1, 0,
                                     16 * i + 2,
                                     sNews_TextColorTable_mystery_gift_view[sWonderNewsData_mystery_gift_view->gfx->bodyTextPal],
                                     0, sWonderNewsData_mystery_gift_view->bodyText[i]);

    CopyWindowToVram(sWonderNewsData_mystery_gift_view->windowIds[NEWS_WIN_TITLE_mystery_gift_view], COPYWIN_FULL);
    CopyWindowToVram(sWonderNewsData_mystery_gift_view->windowIds[NEWS_WIN_BODY_mystery_gift_view], COPYWIN_FULL);
}

static void UpdateNewsScroll_mystery_gift_view(void)
{
    u16 bgMove = sWonderNewsData_mystery_gift_view->scrollIncrement;
    bgMove *= 256;
    if (sWonderNewsData_mystery_gift_view->scrollingDown)
    {
        ChangeBgY(2, bgMove, BG_COORD_ADD);
        ChangeBgY(3, bgMove, BG_COORD_ADD);
    }
    else
    {
        ChangeBgY(2, bgMove, BG_COORD_SUB);
        ChangeBgY(3, bgMove, BG_COORD_SUB);
    }
    sWonderNewsData_mystery_gift_view->scrollTotal += sWonderNewsData_mystery_gift_view->scrollIncrement;
    if (sWonderNewsData_mystery_gift_view->scrollTotal > 15)
    {
        if (sWonderNewsData_mystery_gift_view->scrollingDown)
            sWonderNewsData_mystery_gift_view->scrollOffset++;
        else
            sWonderNewsData_mystery_gift_view->scrollOffset--;
        sWonderNewsData_mystery_gift_view->scrolling = FALSE;
        sWonderNewsData_mystery_gift_view->scrollTotal = 0;
    }
}
