void DoNamingScreen(u8 templateNum, u8 *destBuffer, u16 monSpecies, u16 monGender, u32 monPersonality, MainCallback returnCallback)
{
    sNamingScreen_naming_screen = Alloc(sizeof(struct NamingScreenData));
    if (!sNamingScreen_naming_screen)
    {
        SetMainCallback2(returnCallback);
    }
    else
    {
        sNamingScreen_naming_screen->templateNum = templateNum;
        sNamingScreen_naming_screen->monSpecies = monSpecies;
        sNamingScreen_naming_screen->monGender = monGender;
        sNamingScreen_naming_screen->monPersonality = monPersonality;
        sNamingScreen_naming_screen->destBuffer = destBuffer;
        sNamingScreen_naming_screen->returnCallback = returnCallback;

        if (templateNum == NAMING_SCREEN_PLAYER)
            StartTimer1();

        SetMainCallback2(CB2_LoadNamingScreen_naming_screen);
    }
}

static void CB2_LoadNamingScreen_naming_screen(void)
{
    switch (gMain.state)
    {
    case 0:
        ResetVHBlank_naming_screen();
        NamingScreen_Init_naming_screen();
        gMain.state++;
        break;
    case 1:
        NamingScreen_InitBGs_naming_screen();
        gMain.state++;
        break;
    case 2:
        ResetPaletteFade();
        gMain.state++;
        break;
    case 3:
        ResetSpriteData();
        FreeAllSpritePalettes();
        gMain.state++;
        break;
    case 4:
        ResetTasks();
        gMain.state++;
        break;
    case 5:
        LoadPalettes_naming_screen();
        gMain.state++;
        break;
    case 6:
        LoadGfx_naming_screen();
        gMain.state++;
        break;
    case 7:
        CreateSprites_naming_screen();
        UpdatePaletteFade();
        NamingScreen_ShowBgs_naming_screen();
        gMain.state++;
        break;
    default:
        CreateHelperTasks_naming_screen();
        CreateNamingScreenTask_naming_screen();
        break;
    }
}

static void NamingScreen_Init_naming_screen(void)
{
    sNamingScreen_naming_screen->state = STATE_FADE_IN_naming_screen;
    sNamingScreen_naming_screen->bg1vOffset = 0;
    sNamingScreen_naming_screen->bg2vOffset = 0;
    sNamingScreen_naming_screen->bg1Priority = BGCNT_PRIORITY(1);
    sNamingScreen_naming_screen->bg2Priority = BGCNT_PRIORITY(2);
    sNamingScreen_naming_screen->bgToReveal = 0;
    sNamingScreen_naming_screen->bgToHide = 1;
    sNamingScreen_naming_screen->template = sNamingScreenTemplates_naming_screen[sNamingScreen_naming_screen->templateNum];
    sNamingScreen_naming_screen->currentPage = sNamingScreen_naming_screen->template->initialPage;
    sNamingScreen_naming_screen->inputCharBaseXPos = (DISPLAY_WIDTH - sNamingScreen_naming_screen->template->maxChars * 8) / 2 + 6;
    if (sNamingScreen_naming_screen->templateNum == NAMING_SCREEN_WALDA)
        sNamingScreen_naming_screen->inputCharBaseXPos += 11;
    sNamingScreen_naming_screen->keyRepeatStartDelayCopy = gKeyRepeatStartDelay;
    memset(sNamingScreen_naming_screen->textBuffer, EOS, sizeof(sNamingScreen_naming_screen->textBuffer));
    if (sNamingScreen_naming_screen->template->copyExistingString)
        StringCopy(sNamingScreen_naming_screen->textBuffer, sNamingScreen_naming_screen->destBuffer);
    gKeyRepeatStartDelay = 16;
}

static void SetSpritesVisible_naming_screen(void)
{
    u8 i;
    for (i = 0; i < MAX_SPRITES; i++)
    {
        if (gSprites[i].inUse)
            gSprites[i].invisible = FALSE;
    }
    SetCursorInvisibility_naming_screen(FALSE);
}

static void NamingScreen_InitBGs_naming_screen(void)
{
    u8 i;

    DmaClearLarge16(3, (void *)VRAM, VRAM_SIZE, 0x1000);
    DmaClear32(3, (void *)OAM, OAM_SIZE);
    DmaClear16(3, (void *)PLTT, PLTT_SIZE);

    SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_MODE_0);
    ResetBgsAndClearDma3BusyFlags(0);
    InitBgsFromTemplates(0, sBgTemplates_naming_screen, ARRAY_COUNT(sBgTemplates_naming_screen));

    ChangeBgX(0, 0, BG_COORD_SET);
    ChangeBgY(0, 0, BG_COORD_SET);
    ChangeBgX(1, 0, BG_COORD_SET);
    ChangeBgY(1, 0, BG_COORD_SET);
    ChangeBgX(2, 0, BG_COORD_SET);
    ChangeBgY(2, 0, BG_COORD_SET);
    ChangeBgX(3, 0, BG_COORD_SET);
    ChangeBgY(3, 0, BG_COORD_SET);

    InitStandardTextBoxWindows();
    InitTextBoxGfxAndPrinters();

    for (i = 0; i < WIN_COUNT_naming_screen; i++)
        sNamingScreen_naming_screen->windows[i] = AddWindow(&sWindowTemplates_naming_screen[i]);

    SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_OBJ_1D_MAP | DISPCNT_OBJ_ON);
    SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_EFFECT_BLEND | BLDCNT_TGT2_BG1 | BLDCNT_TGT2_BG2);
    SetGpuReg(REG_OFFSET_BLDALPHA, BLDALPHA_BLEND(12, 8));

    SetBgTilemapBuffer(1, sNamingScreen_naming_screen->tilemapBuffer1);
    SetBgTilemapBuffer(2, sNamingScreen_naming_screen->tilemapBuffer2);
    SetBgTilemapBuffer(3, sNamingScreen_naming_screen->tilemapBuffer3);

    FillBgTilemapBufferRect_Palette0(1, 0, 0, 0, 0x20, 0x20);
    FillBgTilemapBufferRect_Palette0(2, 0, 0, 0, 0x20, 0x20);
    FillBgTilemapBufferRect_Palette0(3, 0, 0, 0, 0x20, 0x20);
}

static void CreateNamingScreenTask_naming_screen(void)
{
    CreateTask(Task_NamingScreen_naming_screen, 2);
    SetMainCallback2(CB2_NamingScreen_naming_screen);
}

static void Task_NamingScreen_naming_screen(u8 taskId)
{
    switch (sNamingScreen_naming_screen->state)
    {
    case STATE_FADE_IN_naming_screen:
        MainState_FadeIn_naming_screen();
        SetSpritesVisible_naming_screen();
        SetVBlank_naming_screen();
        break;
    case STATE_WAIT_FADE_IN_naming_screen:
        MainState_WaitFadeIn_naming_screen();
        break;
    case STATE_HANDLE_INPUT_naming_screen:
        MainState_HandleInput_naming_screen();
        break;
    case STATE_MOVE_TO_OK_BUTTON_naming_screen:
        MainState_MoveToOKButton_naming_screen();
        MainState_HandleInput_naming_screen();
        break;
    case STATE_START_PAGE_SWAP_naming_screen:
        MainState_StartPageSwap_naming_screen();
        break;
    case STATE_WAIT_PAGE_SWAP_naming_screen:
        MainState_WaitPageSwap_naming_screen();
        break;
    case STATE_PRESSED_OK_naming_screen:
        MainState_PressedOKButton_naming_screen();
        break;
    case STATE_WAIT_SENT_TO_PC_MESSAGE_naming_screen:
        MainState_WaitSentToPCMessage_naming_screen();
        break;
    case STATE_FADE_OUT_naming_screen:
        MainState_FadeOut_naming_screen();
        break;
    case STATE_EXIT_naming_screen:
        MainState_Exit_naming_screen();
        break;
    }
}

