// Page Swap
//--------------------------------------------------

#define tState_naming_screen data[0]
#define tFrameCount_naming_screen data[1]

static bool8 PageSwapAnimState_Init_naming_screen(struct Task *);
static bool8 PageSwapAnimState_1_naming_screen(struct Task *);
static bool8 PageSwapAnimState_2_naming_screen(struct Task *);
static bool8 PageSwapAnimState_Done_naming_screen(struct Task *);

static bool8 (*const sPageSwapAnimStateFuncs[])(struct Task *) =
{
    PageSwapAnimState_Init_naming_screen,
    PageSwapAnimState_1_naming_screen,
    PageSwapAnimState_2_naming_screen,
    PageSwapAnimState_Done_naming_screen,
};

static void StartPageSwapAnim_naming_screen(void)
{
    u8 taskId;

    taskId = CreateTask(Task_HandlePageSwapAnim_naming_screen, 0);
    Task_HandlePageSwapAnim_naming_screen(taskId);
}

static void Task_HandlePageSwapAnim_naming_screen(u8 taskId)
{
    while (sPageSwapAnimStateFuncs[gTasks[taskId].tState_naming_screen](&gTasks[taskId]) != 0);
}

static bool8 IsPageSwapAnimNotInProgress_naming_screen(void)
{
    if (FindTaskIdByFunc(Task_HandlePageSwapAnim_naming_screen) == TASK_NONE)
        return TRUE;
    else
        return FALSE;
}

static bool8 PageSwapAnimState_Init_naming_screen(struct Task *task)
{
    sNamingScreen_naming_screen->bg1vOffset = 0;
    sNamingScreen_naming_screen->bg2vOffset = 0;
    task->tState_naming_screen++;
    return 0;
}

static bool8 PageSwapAnimState_1_naming_screen(struct Task *task)
{
    u16 *const vOffsets[] =
    {
        &sNamingScreen_naming_screen->bg2vOffset,
        &sNamingScreen_naming_screen->bg1vOffset
    };

    task->tFrameCount_naming_screen += 4;
    *vOffsets[sNamingScreen_naming_screen->bgToReveal] = Sin(task->tFrameCount_naming_screen, 40);
    *vOffsets[sNamingScreen_naming_screen->bgToHide] = Sin((task->tFrameCount_naming_screen + 128) & 0xFF, 40);
    if (task->tFrameCount_naming_screen >= 64)
    {
        u8 temp = sNamingScreen_naming_screen->bg1Priority;  //Why u8 and not u16?

        sNamingScreen_naming_screen->bg1Priority = sNamingScreen_naming_screen->bg2Priority;
        sNamingScreen_naming_screen->bg2Priority = temp;
        task->tState_naming_screen++;
    }
    return 0;
}

static bool8 PageSwapAnimState_2_naming_screen(struct Task *task)
{
    u16 *const vOffsets[] =
    {
        &sNamingScreen_naming_screen->bg2vOffset,
        &sNamingScreen_naming_screen->bg1vOffset
    };

    task->tFrameCount_naming_screen += 4;
    *vOffsets[sNamingScreen_naming_screen->bgToReveal] = Sin(task->tFrameCount_naming_screen, 40);
    *vOffsets[sNamingScreen_naming_screen->bgToHide] = Sin((task->tFrameCount_naming_screen + 128) & 0xFF, 40);
    if (task->tFrameCount_naming_screen >= 128)
    {
        u8 temp = sNamingScreen_naming_screen->bgToReveal;

        sNamingScreen_naming_screen->bgToReveal = sNamingScreen_naming_screen->bgToHide;
        sNamingScreen_naming_screen->bgToHide = temp;
        task->tState_naming_screen++;
    }
    return 0;
}

static bool8 PageSwapAnimState_Done_naming_screen(struct Task *task)
{
    DestroyTask(FindTaskIdByFunc(Task_HandlePageSwapAnim_naming_screen));
    return 0;
}

#undef tState_naming_screen
#undef tFrameCount_naming_screen

