#define tButtonId_naming_screen     data[0]
#define tKeepFlashing_naming_screen data[1]
#define tAllowFlash_naming_screen   data[2]
#define tColor_naming_screen        data[3]
#define tColorIncr_naming_screen    data[4]
#define tColorDelay_naming_screen   data[5]
#define tColorDelta_naming_screen   data[6]

static void CreateButtonFlashTask_naming_screen(void)
{
    u8 taskId;

    taskId = CreateTask(Task_UpdateButtonFlash_naming_screen, 3);
    gTasks[taskId].tButtonId_naming_screen = BUTTON_COUNT_naming_screen;
}

static void TryStartButtonFlash_naming_screen(u8 button, bool8 keepFlashing, bool8 interruptCurFlash)
{
    struct Task *task = &gTasks[FindTaskIdByFunc(Task_UpdateButtonFlash_naming_screen)];

    if (button == task->tButtonId_naming_screen && !interruptCurFlash)
    {
        task->tKeepFlashing_naming_screen = keepFlashing;
        task->tAllowFlash_naming_screen = TRUE;
        return;
    }
    if (button == BUTTON_COUNT_naming_screen && !task->tKeepFlashing_naming_screen && !interruptCurFlash)
        return;

    if (task->tButtonId_naming_screen != BUTTON_COUNT_naming_screen)
        RestoreButtonColor_naming_screen(task->tButtonId_naming_screen);

    StartButtonFlash_naming_screen(task, button, keepFlashing);
}

static void Task_UpdateButtonFlash_naming_screen(u8 taskId)
{
    struct Task *task = &gTasks[taskId];

    if (task->tButtonId_naming_screen == BUTTON_COUNT_naming_screen || !task->tAllowFlash_naming_screen)
        return;

    MultiplyInvertedPaletteRGBComponents(GetButtonPalOffset_naming_screen(task->tButtonId_naming_screen), task->tColor_naming_screen, task->tColor_naming_screen, task->tColor_naming_screen);

    if (task->tColorDelay_naming_screen && --task->tColorDelay_naming_screen)
        return;

    task->tColorDelay_naming_screen = 2;
    if (task->tColorIncr_naming_screen >= 0)
    {
        if (task->tColor_naming_screen < 14)
        {
            task->tColor_naming_screen += task->tColorIncr_naming_screen;
            task->tColorDelta_naming_screen += task->tColorIncr_naming_screen;
        }
        else
        {
            task->tColor_naming_screen = 16;
            task->tColorDelta_naming_screen++;
        }
    }
    else
    {
        task->tColor_naming_screen += task->tColorIncr_naming_screen;
        task->tColorDelta_naming_screen += task->tColorIncr_naming_screen;
    }

    if (task->tColor_naming_screen == 16 && task->tColorDelta_naming_screen == 22)
    {
        task->tColorIncr_naming_screen = -4;
    }
    else if (task->tColor_naming_screen == 0)
    {
        task->tAllowFlash_naming_screen = task->tKeepFlashing_naming_screen;
        task->tColorIncr_naming_screen = 2;
        task->tColorDelta_naming_screen = 0;
    }
}

static u16 GetButtonPalOffset_naming_screen(u8 button)
{
    const u16 palOffsets[BUTTON_COUNT_naming_screen + 1] =
    {
        [BUTTON_PAGE_naming_screen]  = OBJ_PLTT_ID(IndexOfSpritePaletteTag(PALTAG_PAGE_SWAP_naming_screen)) + 14,
        [BUTTON_BACK_naming_screen]  = OBJ_PLTT_ID(IndexOfSpritePaletteTag(PALTAG_BACK_BUTTON_naming_screen)) + 14,
        [BUTTON_OK_naming_screen]    = OBJ_PLTT_ID(IndexOfSpritePaletteTag(PALTAG_OK_BUTTON_naming_screen)) + 14,
        [BUTTON_COUNT_naming_screen] = OBJ_PLTT_ID(IndexOfSpritePaletteTag(PALTAG_OK_BUTTON_naming_screen)) + 1,
    };

    return palOffsets[button];
}

static void RestoreButtonColor_naming_screen(u8 button)
{
    u16 index = GetButtonPalOffset_naming_screen(button);
    gPlttBufferFaded[index] = gPlttBufferUnfaded[index];
}

static void StartButtonFlash_naming_screen(struct Task *task, u8 button, bool8 keepFlashing)
{
    task->tButtonId_naming_screen = button;
    task->tKeepFlashing_naming_screen = keepFlashing;
    task->tAllowFlash_naming_screen = TRUE;
    task->tColor_naming_screen = 4;
    task->tColorIncr_naming_screen = 2;
    task->tColorDelay_naming_screen = 0;
    task->tColorDelta_naming_screen = 4;
}

#undef tButtonId_naming_screen
#undef tColor_naming_screen

// Sprite data for the the cursor
#define sX_naming_screen          data[0]
#define sY_naming_screen          data[1]
#define sPrevX_naming_screen      data[2]
#define sPrevY_naming_screen      data[3]
#define sInvisible_naming_screen  data[4] & 0x00FF
#define sFlashing_naming_screen   data[4] & 0xFF00
#define sColor_naming_screen      data[5]
#define sColorIncr_naming_screen  data[6]
#define sColorDelay_naming_screen data[7]

static void SpriteCB_Cursor_naming_screen(struct Sprite *sprite)
{
    if (sprite->animEnded)
        StartSpriteAnim(sprite, 0);

    // Hide cursor when on button column
    sprite->invisible = sprite->sInvisible_naming_screen;
    if (sprite->sX_naming_screen == GetCurrentPageColumnCount_naming_screen())
        sprite->invisible = TRUE;

    if (sprite->invisible
       || !(sprite->sFlashing_naming_screen)
       || sprite->sX_naming_screen != sprite->sPrevX_naming_screen
       || sprite->sY_naming_screen != sprite->sPrevY_naming_screen)
    {
        sprite->sColor_naming_screen = 0;
        sprite->sColorIncr_naming_screen = 2;
        sprite->sColorDelay_naming_screen = 2;
    }

    sprite->sColorDelay_naming_screen--;
    if (sprite->sColorDelay_naming_screen == 0)
    {
        sprite->sColor_naming_screen += sprite->sColorIncr_naming_screen;
        if (sprite->sColor_naming_screen == 16 || sprite->sColor_naming_screen == 0)
            sprite->sColorIncr_naming_screen = -sprite->sColorIncr_naming_screen;
        sprite->sColorDelay_naming_screen = 2;
    }

    if (sprite->sFlashing_naming_screen)
    {
        s8 gb = sprite->sColor_naming_screen;
        s8 r = sprite->sColor_naming_screen >> 1;
        u16 index = OBJ_PLTT_ID(IndexOfSpritePaletteTag(PALTAG_CURSOR_naming_screen)) + 1;

        MultiplyInvertedPaletteRGBComponents(index, r, gb, gb);
    }
}

#define sDelay_naming_screen  data[0]
#define sXPosId_naming_screen data[1]

static void SpriteCB_InputArrow_naming_screen(struct Sprite *sprite)
{
    const s16 x[] = {0, -4, -2, -1};

    if (sprite->sDelay_naming_screen == 0 || --sprite->sDelay_naming_screen == 0)
    {
        sprite->sDelay_naming_screen = 8;
        sprite->sXPosId_naming_screen = MOD(sprite->sXPosId_naming_screen + 1, ARRAY_COUNT(x));
    }
    sprite->x2 = x[sprite->sXPosId_naming_screen];
}

#undef sDelay_naming_screen
#undef sXPosId_naming_screen

#define sId_naming_screen     data[0] // set in CreateTextEntrySprites_naming_screen
#define sYPosId_naming_screen data[1]
#define sDelay_naming_screen  data[2]

static void SpriteCB_Underscore_naming_screen(struct Sprite *sprite)
{
    const s16 y[] = {2, 3, 2, 1};
    u8 pos;

    pos = GetTextEntryPosition_naming_screen();
    if (pos != (u8)sprite->sId_naming_screen)
    {
        sprite->y2 = 0;
        sprite->sYPosId_naming_screen = 0;
        sprite->sDelay_naming_screen = 0;
    }
    else
    {
        sprite->y2 = y[sprite->sYPosId_naming_screen];
        sprite->sDelay_naming_screen++;
        if (sprite->sDelay_naming_screen > 8)
        {
            sprite->sYPosId_naming_screen = MOD(sprite->sYPosId_naming_screen + 1, ARRAY_COUNT(y));
            sprite->sDelay_naming_screen = 0;
        }
    }
}

#undef sId_naming_screen
#undef sYPosId_naming_screen
#undef sDelay_naming_screen

static void CreateSprites_naming_screen(void)
{
    CreateCursorSprite_naming_screen();
    CreatePageSwapButtonSprites_naming_screen();
    CreateBackOkSprites_naming_screen();
    CreateTextEntrySprites_naming_screen();
    CreateInputTargetIcon_naming_screen();
}

static void CreateCursorSprite_naming_screen(void)
{
    sNamingScreen_naming_screen->cursorSpriteId = CreateSprite(&sSpriteTemplate_Cursor_naming_screen, 38, 88, 1);
    SetCursorInvisibility_naming_screen(TRUE);
    gSprites[sNamingScreen_naming_screen->cursorSpriteId].oam.priority = 1;
    gSprites[sNamingScreen_naming_screen->cursorSpriteId].oam.objMode = ST_OAM_OBJ_BLEND;
    gSprites[sNamingScreen_naming_screen->cursorSpriteId].sColorIncr_naming_screen = 1; // ? immediately overwritten
    gSprites[sNamingScreen_naming_screen->cursorSpriteId].sColorIncr_naming_screen = 2;
    SetCursorPos_naming_screen(0, 0);
}

static void SetCursorPos_naming_screen(s16 x, s16 y)
{
    struct Sprite *cursorSprite = &gSprites[sNamingScreen_naming_screen->cursorSpriteId];

    if (x < sPageColumnCounts_naming_screen[CurrentPageToKeyboardId_naming_screen()])
        cursorSprite->x = sPageColumnXPos_naming_screen[CurrentPageToKeyboardId_naming_screen()][x] + 38;
    else
        cursorSprite->x = 0;

    cursorSprite->y = y * 16 + 88;
    cursorSprite->sPrevX_naming_screen = cursorSprite->sX_naming_screen;
    cursorSprite->sPrevY_naming_screen = cursorSprite->sY_naming_screen;
    cursorSprite->sX_naming_screen = x;
    cursorSprite->sY_naming_screen = y;
}

static void GetCursorPos_naming_screen(s16 *x, s16 *y)
{
    struct Sprite *cursorSprite = &gSprites[sNamingScreen_naming_screen->cursorSpriteId];

    *x = cursorSprite->sX_naming_screen;
    *y = cursorSprite->sY_naming_screen;
}

static void MoveCursorToOKButton_naming_screen(void)
{
    SetCursorPos_naming_screen(GetCurrentPageColumnCount_naming_screen(), 2);
}

static void SetCursorInvisibility_naming_screen(bool8 invisible)
{
    gSprites[sNamingScreen_naming_screen->cursorSpriteId].data[4] &= 0xFF00;
    gSprites[sNamingScreen_naming_screen->cursorSpriteId].data[4] |= invisible; // sInvisible_naming_screen
    StartSpriteAnim(&gSprites[sNamingScreen_naming_screen->cursorSpriteId], 0);
}

static void SetCursorFlashing_naming_screen(bool8 flashing)
{
    gSprites[sNamingScreen_naming_screen->cursorSpriteId].data[4] &= 0xFF;
    gSprites[sNamingScreen_naming_screen->cursorSpriteId].data[4] |= flashing << 8; // sFlashing_naming_screen
}

static void SquishCursor_naming_screen(void)
{
    StartSpriteAnim(&gSprites[sNamingScreen_naming_screen->cursorSpriteId], 1);
}

static bool8 IsCursorAnimFinished_naming_screen(void)
{
    return gSprites[sNamingScreen_naming_screen->cursorSpriteId].animEnded;
}

static const u8  sButtonKeyRoles_naming_screen[] = {KEY_ROLE_PAGE_naming_screen, KEY_ROLE_BACKSPACE_naming_screen, KEY_ROLE_OK_naming_screen};

static u8 GetKeyRoleAtCursorPos_naming_screen(void)
{
    s16 cursorX;
    s16 cursorY;

    GetCursorPos_naming_screen(&cursorX, &cursorY);
    if (cursorX < GetCurrentPageColumnCount_naming_screen())
        return KEY_ROLE_CHAR_naming_screen;
    else
        return sButtonKeyRoles_naming_screen[cursorY];
}

// If the cursor's x is equal to the column count, cursor is in the button column
static u8 GetCurrentPageColumnCount_naming_screen(void)
{
    return sPageColumnCounts_naming_screen[CurrentPageToKeyboardId_naming_screen()];
}

