static void CreatePageSwapButtonSprites_naming_screen(void)
{
    u8 frameSpriteId;
    u8 textSpriteId;
    u8 buttonSpriteId;

    frameSpriteId = CreateSprite(&sSpriteTemplate_PageSwapFrame_naming_screen, 204, 88, 0);
    sNamingScreen_naming_screen->swapBtnFrameSpriteId = frameSpriteId;
    SetSubspriteTables(&gSprites[frameSpriteId], sSubspriteTable_PageSwapFrame_naming_screen);
    gSprites[frameSpriteId].invisible = TRUE;

    textSpriteId = CreateSprite(&sSpriteTemplate_PageSwapText_naming_screen, 204, 84, 1);
    gSprites[frameSpriteId].sTextSpriteId_naming_screen = textSpriteId;
    SetSubspriteTables(&gSprites[textSpriteId], sSubspriteTable_PageSwapText_naming_screen);
    gSprites[textSpriteId].invisible = TRUE;

    buttonSpriteId = CreateSprite(&sSpriteTemplate_PageSwapButton_naming_screen, 204, 83, 2);
    gSprites[buttonSpriteId].oam.priority = 1;
    gSprites[frameSpriteId].sButtonSpriteId_naming_screen = buttonSpriteId;
    gSprites[buttonSpriteId].invisible = TRUE;
}

static void StartPageSwapButtonAnim_naming_screen(void)
{
    struct Sprite *sprite = &gSprites[sNamingScreen_naming_screen->swapBtnFrameSpriteId];

    sprite->sState_naming_screen = 2; // go to PageSwapSprite_SlideOff_naming_screen
    sprite->sPage_naming_screen = sNamingScreen_naming_screen->currentPage;
}

static u8 (*const sPageSwapSpriteFuncs[])(struct Sprite *) =
{
    PageSwapSprite_Init_naming_screen,
    PageSwapSprite_Idle_naming_screen,
    PageSwapSprite_SlideOff_naming_screen,
    PageSwapSprite_SlideOn_naming_screen,
};

static void SpriteCB_PageSwap_naming_screen(struct Sprite *sprite)
{
    while (sPageSwapSpriteFuncs[sprite->sState_naming_screen](sprite));
}

static bool8 PageSwapSprite_Init_naming_screen(struct Sprite *sprite)
{
    struct Sprite *text = &gSprites[sprite->sTextSpriteId_naming_screen];
    struct Sprite *button = &gSprites[sprite->sButtonSpriteId_naming_screen];

    SetPageSwapButtonGfx_naming_screen(PageToNextGfxId_naming_screen(sNamingScreen_naming_screen->currentPage), text, button);
    sprite->sState_naming_screen++;
    return FALSE;
}

static bool8 PageSwapSprite_Idle_naming_screen(struct Sprite *sprite)
{
    return FALSE;
}

static bool8 PageSwapSprite_SlideOff_naming_screen(struct Sprite *sprite)
{
    struct Sprite *text = &gSprites[sprite->sTextSpriteId_naming_screen];
    struct Sprite *button = &gSprites[sprite->sButtonSpriteId_naming_screen];

    text->y2++;
    if (text->y2 > 7)
    {
        sprite->sState_naming_screen++;
        text->y2 = -4;
        text->invisible = TRUE;
        SetPageSwapButtonGfx_naming_screen(PageToNextGfxId_naming_screen(((u8)sprite->sPage_naming_screen + 1) % KBPAGE_COUNT_naming_screen), text, button);
    }
    return FALSE;
}

static bool8 PageSwapSprite_SlideOn_naming_screen(struct Sprite *sprite)
{
    struct Sprite *text = &gSprites[sprite->sTextSpriteId_naming_screen];

    text->invisible = FALSE;
    text->y2++;
    if (text->y2 >= 0)
    {
        text->y2 = 0;
        sprite->sState_naming_screen = 1; // go to PageSwapSprite_Idle_naming_screen
    }
    return FALSE;
}

static const u16  sPageSwapPalTags_naming_screen[] = {
    [PAGE_SWAP_UPPER_naming_screen]  = PALTAG_PAGE_SWAP_UPPER_naming_screen,
    [PAGE_SWAP_OTHERS_naming_screen] = PALTAG_PAGE_SWAP_OTHERS,
    [PAGE_SWAP_LOWER_naming_screen]  = PALTAG_PAGE_SWAP_LOWER_naming_screen
};

static const u16  sPageSwapGfxTags_naming_screen[] = {
    [PAGE_SWAP_UPPER_naming_screen]  = GFXTAG_PAGE_SWAP_UPPER_naming_screen,
    [PAGE_SWAP_OTHERS_naming_screen] = GFXTAG_PAGE_SWAP_OTHERS_naming_screen,
    [PAGE_SWAP_LOWER_naming_screen]  = GFXTAG_PAGE_SWAP_LOWER_naming_screen
};

static void SetPageSwapButtonGfx_naming_screen(u8 page, struct Sprite *text, struct Sprite *button)
{
    button->oam.paletteNum = IndexOfSpritePaletteTag(sPageSwapPalTags_naming_screen[page]);
    text->sheetTileStart = GetSpriteTileStartByTag(sPageSwapGfxTags_naming_screen[page]);
    text->subspriteTableNum = page;
}

