static void CreateTextEntrySprites_naming_screen(void)
{
    u8 spriteId;
    s16 xPos;
    u8 i;

    xPos = sNamingScreen_naming_screen->inputCharBaseXPos - 5;
    spriteId = CreateSprite(&sSpriteTemplate_InputArrow_naming_screen, xPos, 56, 0);
    gSprites[spriteId].oam.priority = 3;
    gSprites[spriteId].invisible = TRUE;
    xPos = sNamingScreen_naming_screen->inputCharBaseXPos;
    for (i = 0; i < sNamingScreen_naming_screen->template->maxChars; i++, xPos += 8)
    {
        spriteId = CreateSprite(&sSpriteTemplate_Underscore_naming_screen, xPos + 3, 60, 0);
        gSprites[spriteId].oam.priority = 3;
        gSprites[spriteId].data[0] = i;
        gSprites[spriteId].invisible = TRUE;
    }
}

