//--------------------------------------------------
// Keyboard handling
//--------------------------------------------------

static bool8 KeyboardKeyHandler_Character_naming_screen(u8);
static void SwapKeyboardToLowerAfterFirstCapitalLetter_naming_screen(void);
static bool8 KeyboardKeyHandler_Page_naming_screen(u8);
static bool8 KeyboardKeyHandler_Backspace_naming_screen(u8);
static bool8 KeyboardKeyHandler_OK_naming_screen(u8);

static bool8 (*const sKeyboardKeyHandlers[])(u8) =
{
    [KEY_ROLE_CHAR_naming_screen]      = KeyboardKeyHandler_Character_naming_screen,
    [KEY_ROLE_PAGE_naming_screen]      = KeyboardKeyHandler_Page_naming_screen,
    [KEY_ROLE_BACKSPACE_naming_screen] = KeyboardKeyHandler_Backspace_naming_screen,
    [KEY_ROLE_OK_naming_screen]        = KeyboardKeyHandler_OK_naming_screen,
};

static bool8 HandleKeyboardEvent_naming_screen(void)
{
    u8 input = GetInputEvent_naming_screen();
    u8 keyRole = GetKeyRoleAtCursorPos_naming_screen();

    if (input == INPUT_SELECT_naming_screen)
    {
        return SwapKeyboardPage_naming_screen();
    }
    else if (input == INPUT_B_BUTTON_naming_screen)
    {
        DeleteTextCharacter_naming_screen();
        return FALSE;
    }
    else if (input == INPUT_START_naming_screen)
    {
        MoveCursorToOKButton_naming_screen();
        return FALSE;
    }
    else
    {
        return sKeyboardKeyHandlers[keyRole](input);
    }
}

static bool8 KeyboardKeyHandler_Character_naming_screen(u8 input)
{
    TryStartButtonFlash_naming_screen(BUTTON_COUNT_naming_screen, FALSE, FALSE);
    if (input == INPUT_A_BUTTON_naming_screen)
    {
        bool8 textFull = AddTextCharacter_naming_screen();

        SwapKeyboardToLowerAfterFirstCapitalLetter_naming_screen();

        SquishCursor_naming_screen();
        if (textFull)
        {
            SetInputState_naming_screen(INPUT_STATE_OVERRIDE_naming_screen);
            sNamingScreen_naming_screen->state = STATE_MOVE_TO_OK_BUTTON_naming_screen;
        }
    }
    return FALSE;
}

static void SwapKeyboardToLowerAfterFirstCapitalLetter_naming_screen(void)
{
    if (AUTO_LOWERCASE_KEYBOARD < GEN_6)
        return;

    if (sNamingScreen_naming_screen->currentPage != KBPAGE_LETTERS_UPPER_naming_screen)
        return;

    if (GetTextEntryPosition_naming_screen() != 1)
        return;

    MainState_StartPageSwap_naming_screen();
}

static bool8 KeyboardKeyHandler_Page_naming_screen(u8 input)
{
    TryStartButtonFlash_naming_screen(BUTTON_PAGE_naming_screen, TRUE, FALSE);
    if (input == INPUT_A_BUTTON_naming_screen)
        return SwapKeyboardPage_naming_screen();
    else
        return FALSE;
}

static bool8 KeyboardKeyHandler_Backspace_naming_screen(u8 input)
{
    TryStartButtonFlash_naming_screen(BUTTON_BACK_naming_screen, TRUE, FALSE);
    if (input == INPUT_A_BUTTON_naming_screen)
        DeleteTextCharacter_naming_screen();
    return FALSE;
}

static bool8 KeyboardKeyHandler_OK_naming_screen(u8 input)
{
    TryStartButtonFlash_naming_screen(BUTTON_OK_naming_screen, TRUE, FALSE);
    if (input == INPUT_A_BUTTON_naming_screen)
    {
        PlaySE(SE_SELECT);
        sNamingScreen_naming_screen->state = STATE_PRESSED_OK_naming_screen;
        return TRUE;
    }
    else
        return FALSE;
}

static bool8 SwapKeyboardPage_naming_screen(void)
{
    sNamingScreen_naming_screen->state = STATE_START_PAGE_SWAP_naming_screen;
    return TRUE;
}

