static void SetInputState_naming_screen(u8 state)
{
    u8 taskId = FindTaskIdByFunc(Task_HandleInput_naming_screen);

    gTasks[taskId].tState_naming_screen = state;
}

static void Task_HandleInput_naming_screen(u8 taskId)
{
    sInputFuncs[gTasks[taskId].tState_naming_screen](&gTasks[taskId]);
}

static void Input_Disabled_naming_screen(struct Task *task)
{
    task->tKeyboardEvent_naming_screen = INPUT_NONE_naming_screen;
}

static void Input_Enabled_naming_screen(struct Task *task)
{
    task->tKeyboardEvent_naming_screen = INPUT_NONE_naming_screen;

    if (JOY_NEW(A_BUTTON))
        task->tKeyboardEvent_naming_screen = INPUT_A_BUTTON_naming_screen;
    else if (JOY_NEW(B_BUTTON))
        task->tKeyboardEvent_naming_screen = INPUT_B_BUTTON_naming_screen;
    else if (JOY_NEW(SELECT_BUTTON))
        task->tKeyboardEvent_naming_screen = INPUT_SELECT_naming_screen;
    else if (JOY_NEW(START_BUTTON))
        task->tKeyboardEvent_naming_screen = INPUT_START_naming_screen;
    else
        HandleDpadMovement_naming_screen(task);
}

static void Input_Override_naming_screen(struct Task *task)
{
    task->tKeyboardEvent_naming_screen = INPUT_NONE_naming_screen;
}

static void HandleDpadMovement_naming_screen(struct Task *task)
{
    const s16 sDpadDeltaX[] =
    {
        [INPUT_NONE_naming_screen]       = 0,
        [INPUT_DPAD_UP_naming_screen]    = 0,
        [INPUT_DPAD_DOWN_naming_screen]  = 0,
        [INPUT_DPAD_LEFT_naming_screen]  = -1,
        [INPUT_DPAD_RIGHT_naming_screen] = 1
    };

    const s16 sDpadDeltaY[] =
    {
        [INPUT_NONE_naming_screen]       = 0,
        [INPUT_DPAD_UP_naming_screen]    = -1,
        [INPUT_DPAD_DOWN_naming_screen]  = 1,
        [INPUT_DPAD_LEFT_naming_screen]  = 0,
        [INPUT_DPAD_RIGHT_naming_screen] = 0
    };

    const s16 sKeyRowToButtonRow[KBROW_COUNT_naming_screen] = {0, 1, 1, 2};
    const s16 sButtonRowToKeyRow[BUTTON_COUNT_naming_screen] = {0, 0, 3};

    s16 cursorX;
    s16 cursorY;
    u16 input;
    s16 prevCursorX;

    GetCursorPos_naming_screen(&cursorX, &cursorY);
    input = INPUT_NONE_naming_screen;
    if (JOY_REPEAT(DPAD_UP))
        input = INPUT_DPAD_UP_naming_screen;
    if (JOY_REPEAT(DPAD_DOWN))
        input = INPUT_DPAD_DOWN_naming_screen;
    if (JOY_REPEAT(DPAD_LEFT))
        input = INPUT_DPAD_LEFT_naming_screen;
    if (JOY_REPEAT(DPAD_RIGHT))
        input = INPUT_DPAD_RIGHT_naming_screen;

    // Get new cursor position
    prevCursorX = cursorX;
    cursorX += sDpadDeltaX[input];
    cursorY += sDpadDeltaY[input];

    // Wrap cursor position in the X direction
    if (cursorX < 0)
        cursorX = GetCurrentPageColumnCount_naming_screen();
    if (cursorX > GetCurrentPageColumnCount_naming_screen())
        cursorX = 0;


    // Handle moving on/off the button column
    if (sDpadDeltaX[input] != 0)
    {
        if (cursorX == GetCurrentPageColumnCount_naming_screen())
        {
            // Moved onto button column
            // Save cursor pos in tButtonId_naming_screen for moving back onto keys
            task->tButtonId_naming_screen = cursorY;
            cursorY = sKeyRowToButtonRow[cursorY];
        }
        else if (prevCursorX == GetCurrentPageColumnCount_naming_screen())
        {
            // Moved off button column
            // If you're on the middle button, go to the row that
            // the cursor was on previously (saved in tButtonId_naming_screen above)
            if (cursorY == BUTTON_COUNT_naming_screen / 2)
                cursorY = task->tButtonId_naming_screen;
            else
                cursorY = sButtonRowToKeyRow[cursorY];
        }
    }

    // Wrap cursor position in the y direction
    if (cursorX == GetCurrentPageColumnCount_naming_screen())
    {
        // There are only 3 keys in the button column
        // so wrap Y accordingly
        if (cursorY < 0)
            cursorY = BUTTON_COUNT_naming_screen - 1;
        if (cursorY >= BUTTON_COUNT_naming_screen)
            cursorY = 0;

        if (cursorY == 0)
            task->tButtonId_naming_screen = BUTTON_BACK_naming_screen;
        else if (cursorY == BUTTON_COUNT_naming_screen - 1)
            task->tButtonId_naming_screen = BUTTON_OK_naming_screen;
    }
    else
    {
        if (cursorY < 0)
            cursorY = KBROW_COUNT_naming_screen - 1;
        if (cursorY > KBROW_COUNT_naming_screen - 1)
            cursorY = 0;
    }
    SetCursorPos_naming_screen(cursorX, cursorY);
}

