static u8 GetCharAtKeyboardPos_naming_screen(s16 x, s16 y)
{
    return sKeyboardChars_naming_screen[CurrentPageToKeyboardId_naming_screen()][y][x];
}


static u8 GetTextEntryPosition_naming_screen(void)
{
    u8 i;

    for (i = 0; i < sNamingScreen_naming_screen->template->maxChars; i++)
    {
        if (sNamingScreen_naming_screen->textBuffer[i] == EOS)
            return i;
    }
    return sNamingScreen_naming_screen->template->maxChars - 1;
}

static u8 GetPreviousTextCaretPosition_naming_screen(void)
{
    s8 i;

    for (i = sNamingScreen_naming_screen->template->maxChars - 1; i > 0; i--)
    {
        if (sNamingScreen_naming_screen->textBuffer[i] != EOS)
            return i;
    }
    return 0;
}

static void DeleteTextCharacter_naming_screen(void)
{
    u8 index;
    u8 keyRole;

    index = GetPreviousTextCaretPosition_naming_screen();
    sNamingScreen_naming_screen->textBuffer[index] = 0;
    DrawTextEntry_naming_screen();
    CopyBgTilemapBufferToVram(3);
    sNamingScreen_naming_screen->textBuffer[index] = EOS;
    keyRole = GetKeyRoleAtCursorPos_naming_screen();

    // The below flashes the Back key once on delete
    // It incorrectly leaves the Back key 1 shade lighter than its default
    if (keyRole == KEY_ROLE_CHAR_naming_screen || keyRole == KEY_ROLE_BACKSPACE_naming_screen)
        TryStartButtonFlash_naming_screen(BUTTON_BACK_naming_screen, FALSE, TRUE);
    PlaySE(SE_BALL);
}

// Returns TRUE if the text entry is now full
static bool8 AddTextCharacter_naming_screen(void)
{
    s16 x;
    s16 y;

    GetCursorPos_naming_screen(&x, &y);
    BufferCharacter_naming_screen(GetCharAtKeyboardPos_naming_screen(x, y));
    DrawTextEntry_naming_screen();
    CopyBgTilemapBufferToVram(3);
    PlaySE(SE_SELECT);

    if (GetPreviousTextCaretPosition_naming_screen() != sNamingScreen_naming_screen->template->maxChars - 1)
        return FALSE;
    else
        return TRUE;
}

static void BufferCharacter_naming_screen(u8 ch)
{
    u8 index = GetTextEntryPosition_naming_screen();
    sNamingScreen_naming_screen->textBuffer[index] = ch;
}

static void SaveInputText_naming_screen(void)
{
    u8 i;

    for (i = 0; i < sNamingScreen_naming_screen->template->maxChars; i++)
    {
        if (sNamingScreen_naming_screen->textBuffer[i] != CHAR_SPACE && sNamingScreen_naming_screen->textBuffer[i] != EOS)
        {
            StringCopyN(sNamingScreen_naming_screen->destBuffer, sNamingScreen_naming_screen->textBuffer, sNamingScreen_naming_screen->template->maxChars + 1);
            break;
        }
    }
}

