static void DrawTextEntry_naming_screen(void)
{
    u8 i;
    u8 temp[2];
    u16 extraWidth;
    u8 maxChars = sNamingScreen_naming_screen->template->maxChars;
    u16 x = sNamingScreen_naming_screen->inputCharBaseXPos - 0x40;

    FillWindowPixelBuffer(sNamingScreen_naming_screen->windows[WIN_TEXT_ENTRY_naming_screen], PIXEL_FILL(1));

    for (i = 0; i < maxChars; i++)
    {
        temp[0] = sNamingScreen_naming_screen->textBuffer[i];
        temp[1] = gText_ExpandedPlaceholder_Empty[0];
        extraWidth = (IsWideLetter_naming_screen(temp[0]) == TRUE) ? 2 : 0;

        AddTextPrinterParameterized(sNamingScreen_naming_screen->windows[WIN_TEXT_ENTRY_naming_screen], FONT_NORMAL, temp, i * 8 + x + extraWidth, 1, TEXT_SKIP_DRAW, NULL);
    }

    TryDrawGenderIcon_naming_screen();
    CopyWindowToVram(sNamingScreen_naming_screen->windows[WIN_TEXT_ENTRY_naming_screen], COPYWIN_GFX);
    PutWindowTilemap(sNamingScreen_naming_screen->windows[WIN_TEXT_ENTRY_naming_screen]);
}

