// Always false (presumably for non-latin languages)
static bool8 IsWideLetter_naming_screen(u8 character)
{
    u8 i;

    for (i = 0; sText_AlphabetUpperLower_naming_screen[i] != EOS; i++)
    {
        if (character == sText_AlphabetUpperLower_naming_screen[i])
            return FALSE;
    }
    return FALSE;
}

