static void MainCB2_option_menu(void)
{
    RunTasks();
    AnimateSprites();
    BuildOamBuffer();
    UpdatePaletteFade();
}

static void VBlankCB_option_menu(void)
{
    LoadOam();
    ProcessSpriteCopyRequests();
    TransferPlttBuffer();
}

void CB2_InitOptionMenu(void)
{
    switch (gMain.state)
    {
    default:
    case 0:
        SetVBlankCallback(NULL);
        gMain.state++;
        break;
    case 1:
        DmaClearLarge16(3, (void *)(VRAM), VRAM_SIZE, 0x1000);
        DmaClear32(3, OAM, OAM_SIZE);
        DmaClear16(3, PLTT, PLTT_SIZE);
        SetGpuReg(REG_OFFSET_DISPCNT, 0);
        ResetBgsAndClearDma3BusyFlags(0);
        InitBgsFromTemplates(0, sOptionMenuBgTemplates_option_menu, ARRAY_COUNT(sOptionMenuBgTemplates_option_menu));
        ChangeBgX(0, 0, BG_COORD_SET);
        ChangeBgY(0, 0, BG_COORD_SET);
        ChangeBgX(1, 0, BG_COORD_SET);
        ChangeBgY(1, 0, BG_COORD_SET);
        ChangeBgX(2, 0, BG_COORD_SET);
        ChangeBgY(2, 0, BG_COORD_SET);
        ChangeBgX(3, 0, BG_COORD_SET);
        ChangeBgY(3, 0, BG_COORD_SET);
        InitWindows(sOptionMenuWinTemplates_option_menu);
        DeactivateAllTextPrinters();
        SetGpuReg(REG_OFFSET_WIN0H, 0);
        SetGpuReg(REG_OFFSET_WIN0V, 0);
        SetGpuReg(REG_OFFSET_WININ, WININ_WIN0_BG0);
        SetGpuReg(REG_OFFSET_WINOUT, WINOUT_WIN01_BG0 | WINOUT_WIN01_BG1 | WINOUT_WIN01_CLR);
        SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_TGT1_BG0 | BLDCNT_EFFECT_DARKEN);
        SetGpuReg(REG_OFFSET_BLDALPHA, 0);
        SetGpuReg(REG_OFFSET_BLDY, 4);
        SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_WIN0_ON | DISPCNT_OBJ_ON | DISPCNT_OBJ_1D_MAP);
        ShowBg(0);
        ShowBg(1);
        gMain.state++;
        break;
    case 2:
        ResetPaletteFade();
        ScanlineEffect_Stop();
        ResetTasks();
        ResetSpriteData();
        gMain.state++;
        break;
    case 3:
        LoadBgTiles(1, GetWindowFrameTilesPal(gSaveBlock2Ptr->optionsWindowFrameType)->tiles, 0x120, 0x1A2);
        gMain.state++;
        break;
    case 4:
        LoadPalette(sOptionMenuBg_Pal_option_menu, BG_PLTT_ID(0), sizeof(sOptionMenuBg_Pal_option_menu));
        LoadPalette(GetWindowFrameTilesPal(gSaveBlock2Ptr->optionsWindowFrameType)->pal, BG_PLTT_ID(7), PLTT_SIZE_4BPP);
        gMain.state++;
        break;
    case 5:
        LoadPalette(sOptionMenuText_Pal_option_menu, BG_PLTT_ID(1), sizeof(sOptionMenuText_Pal_option_menu));
        gMain.state++;
        break;
    case 6:
        PutWindowTilemap(WIN_HEADER_option_menu);
        DrawHeaderText_option_menu();
        gMain.state++;
        break;
    case 7:
        gMain.state++;
        break;
    case 8:
        PutWindowTilemap(WIN_OPTIONS_option_menu);
        DrawOptionMenuTexts_option_menu();
        gMain.state++;
    case 9:
        DrawBgWindowFrames_option_menu();
        gMain.state++;
        break;
    case 10:
    {
        u8 taskId = CreateTask(Task_OptionMenuFadeIn_option_menu, 0);

        gTasks[taskId].tMenuSelection_option_menu = 0;
        gTasks[taskId].tTextSpeed_option_menu = gSaveBlock2Ptr->optionsTextSpeed;
        gTasks[taskId].tBattleSceneOff_option_menu = gSaveBlock2Ptr->optionsBattleSceneOff;
        gTasks[taskId].tBattleStyle_option_menu = gSaveBlock2Ptr->optionsBattleStyle;
        gTasks[taskId].tSound_option_menu = gSaveBlock2Ptr->optionsSound;
        gTasks[taskId].tButtonMode_option_menu = gSaveBlock2Ptr->optionsButtonMode;
        gTasks[taskId].tWindowFrameType_option_menu = gSaveBlock2Ptr->optionsWindowFrameType;

        TextSpeed_DrawChoices_option_menu(gTasks[taskId].tTextSpeed_option_menu);
        BattleScene_DrawChoices_option_menu(gTasks[taskId].tBattleSceneOff_option_menu);
        BattleStyle_DrawChoices_option_menu(gTasks[taskId].tBattleStyle_option_menu);
        Sound_DrawChoices_option_menu(gTasks[taskId].tSound_option_menu);
        ButtonMode_DrawChoices_option_menu(gTasks[taskId].tButtonMode_option_menu);
        FrameType_DrawChoices_option_menu(gTasks[taskId].tWindowFrameType_option_menu);
        HighlightOptionMenuItem_option_menu(gTasks[taskId].tMenuSelection_option_menu);

        CopyWindowToVram(WIN_OPTIONS_option_menu, COPYWIN_FULL);
        gMain.state++;
        break;
    }
    case 11:
        BeginNormalPaletteFade(PALETTES_ALL, 0, 16, 0, RGB_BLACK);
        SetVBlankCallback(VBlankCB_option_menu);
        SetMainCallback2(MainCB2_option_menu);
        return;
    }
}

static void Task_OptionMenuFadeIn_option_menu(u8 taskId)
{
    if (!gPaletteFade.active)
        gTasks[taskId].func = Task_OptionMenuProcessInput_option_menu;
}

static void Task_OptionMenuProcessInput_option_menu(u8 taskId)
{
    if (JOY_NEW(A_BUTTON))
    {
        if (gTasks[taskId].tMenuSelection_option_menu == MENUITEM_CANCEL_option_menu)
            gTasks[taskId].func = Task_OptionMenuSave_option_menu;
    }
    else if (JOY_NEW(B_BUTTON))
    {
        gTasks[taskId].func = Task_OptionMenuSave_option_menu;
    }
    else if (JOY_NEW(DPAD_UP))
    {
        if (gTasks[taskId].tMenuSelection_option_menu > 0)
            gTasks[taskId].tMenuSelection_option_menu--;
        else
            gTasks[taskId].tMenuSelection_option_menu = MENUITEM_CANCEL_option_menu;
        HighlightOptionMenuItem_option_menu(gTasks[taskId].tMenuSelection_option_menu);
    }
    else if (JOY_NEW(DPAD_DOWN))
    {
        if (gTasks[taskId].tMenuSelection_option_menu < MENUITEM_CANCEL_option_menu)
            gTasks[taskId].tMenuSelection_option_menu++;
        else
            gTasks[taskId].tMenuSelection_option_menu = 0;
        HighlightOptionMenuItem_option_menu(gTasks[taskId].tMenuSelection_option_menu);
    }
    else
    {
        u8 previousOption;

        switch (gTasks[taskId].tMenuSelection_option_menu)
        {
        case MENUITEM_TEXTSPEED_option_menu:
            previousOption = gTasks[taskId].tTextSpeed_option_menu;
            gTasks[taskId].tTextSpeed_option_menu = TextSpeed_ProcessInput_option_menu(gTasks[taskId].tTextSpeed_option_menu);

            if (previousOption != gTasks[taskId].tTextSpeed_option_menu)
                TextSpeed_DrawChoices_option_menu(gTasks[taskId].tTextSpeed_option_menu);
            break;
        case MENUITEM_BATTLESCENE_option_menu:
            previousOption = gTasks[taskId].tBattleSceneOff_option_menu;
            gTasks[taskId].tBattleSceneOff_option_menu = BattleScene_ProcessInput_option_menu(gTasks[taskId].tBattleSceneOff_option_menu);

            if (previousOption != gTasks[taskId].tBattleSceneOff_option_menu)
                BattleScene_DrawChoices_option_menu(gTasks[taskId].tBattleSceneOff_option_menu);
            break;
        case MENUITEM_BATTLESTYLE_option_menu:
            previousOption = gTasks[taskId].tBattleStyle_option_menu;
            gTasks[taskId].tBattleStyle_option_menu = BattleStyle_ProcessInput_option_menu(gTasks[taskId].tBattleStyle_option_menu);

            if (previousOption != gTasks[taskId].tBattleStyle_option_menu)
                BattleStyle_DrawChoices_option_menu(gTasks[taskId].tBattleStyle_option_menu);
            break;
        case MENUITEM_SOUND_option_menu:
            previousOption = gTasks[taskId].tSound_option_menu;
            gTasks[taskId].tSound_option_menu = Sound_ProcessInput_option_menu(gTasks[taskId].tSound_option_menu);

            if (previousOption != gTasks[taskId].tSound_option_menu)
                Sound_DrawChoices_option_menu(gTasks[taskId].tSound_option_menu);
            break;
        case MENUITEM_BUTTONMODE_option_menu:
            previousOption = gTasks[taskId].tButtonMode_option_menu;
            gTasks[taskId].tButtonMode_option_menu = ButtonMode_ProcessInput_option_menu(gTasks[taskId].tButtonMode_option_menu);

            if (previousOption != gTasks[taskId].tButtonMode_option_menu)
                ButtonMode_DrawChoices_option_menu(gTasks[taskId].tButtonMode_option_menu);
            break;
        case MENUITEM_FRAMETYPE_option_menu:
            previousOption = gTasks[taskId].tWindowFrameType_option_menu;
            gTasks[taskId].tWindowFrameType_option_menu = FrameType_ProcessInput_option_menu(gTasks[taskId].tWindowFrameType_option_menu);

            if (previousOption != gTasks[taskId].tWindowFrameType_option_menu)
                FrameType_DrawChoices_option_menu(gTasks[taskId].tWindowFrameType_option_menu);
            break;
        default:
            return;
        }

        if (sArrowPressed_option_menu)
        {
            sArrowPressed_option_menu = FALSE;
            CopyWindowToVram(WIN_OPTIONS_option_menu, COPYWIN_GFX);
        }
    }
}

static void Task_OptionMenuSave_option_menu(u8 taskId)
{
    gSaveBlock2Ptr->optionsTextSpeed = gTasks[taskId].tTextSpeed_option_menu;
    gSaveBlock2Ptr->optionsBattleSceneOff = gTasks[taskId].tBattleSceneOff_option_menu;
    gSaveBlock2Ptr->optionsBattleStyle = gTasks[taskId].tBattleStyle_option_menu;
    gSaveBlock2Ptr->optionsSound = gTasks[taskId].tSound_option_menu;
    gSaveBlock2Ptr->optionsButtonMode = gTasks[taskId].tButtonMode_option_menu;
    gSaveBlock2Ptr->optionsWindowFrameType = gTasks[taskId].tWindowFrameType_option_menu;

    BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
    gTasks[taskId].func = Task_OptionMenuFadeOut_option_menu;
}

static void Task_OptionMenuFadeOut_option_menu(u8 taskId)
{
    if (!gPaletteFade.active)
    {
        DestroyTask(taskId);
        FreeAllWindowBuffers();
        SetMainCallback2(gMain.savedCallback);
    }
}

static void HighlightOptionMenuItem_option_menu(u8 index)
{
    SetGpuReg(REG_OFFSET_WIN0H, WIN_RANGE(16, DISPLAY_WIDTH - 16));
    SetGpuReg(REG_OFFSET_WIN0V, WIN_RANGE(index * 16 + 40, index * 16 + 56));
}

static void DrawOptionMenuChoice_option_menu(const u8 *text, u8 x, u8 y, u8 style)
{
    u8 dst[16];
    u16 i;

    for (i = 0; *text != EOS && i < ARRAY_COUNT(dst) - 1; i++)
        dst[i] = *(text++);

    if (style != 0)
    {
        dst[2] = TEXT_COLOR_RED;
        dst[5] = TEXT_COLOR_LIGHT_RED;
    }

    dst[i] = EOS;
    AddTextPrinterParameterized(WIN_OPTIONS_option_menu, FONT_NORMAL, dst, x, y + 1, TEXT_SKIP_DRAW, NULL);
}

static u8 TextSpeed_ProcessInput_option_menu(u8 selection)
{
    if (JOY_NEW(DPAD_RIGHT))
    {
        if (selection <= 1)
            selection++;
        else
            selection = 0;

        sArrowPressed_option_menu = TRUE;
    }
    if (JOY_NEW(DPAD_LEFT))
    {
        if (selection != 0)
            selection--;
        else
            selection = 2;

        sArrowPressed_option_menu = TRUE;
    }
    return selection;
}

static void TextSpeed_DrawChoices_option_menu(u8 selection)
{
    u8 styles[3];
    s32 widthSlow, widthMid, widthFast, xMid;

    styles[0] = 0;
    styles[1] = 0;
    styles[2] = 0;
    styles[selection] = 1;

    DrawOptionMenuChoice_option_menu(gText_TextSpeedSlow, 104, YPOS_TEXTSPEED_option_menu, styles[0]);

    widthSlow = GetStringWidth(FONT_NORMAL, gText_TextSpeedSlow, 0);
    widthMid = GetStringWidth(FONT_NORMAL, gText_TextSpeedMid, 0);
    widthFast = GetStringWidth(FONT_NORMAL, gText_TextSpeedFast, 0);

    widthMid -= 94;
    xMid = (widthSlow - widthMid - widthFast) / 2 + 104;
    DrawOptionMenuChoice_option_menu(gText_TextSpeedMid, xMid, YPOS_TEXTSPEED_option_menu, styles[1]);

    DrawOptionMenuChoice_option_menu(gText_TextSpeedFast, GetStringRightAlignXOffset(FONT_NORMAL, gText_TextSpeedFast, 198), YPOS_TEXTSPEED_option_menu, styles[2]);
}

static u8 BattleScene_ProcessInput_option_menu(u8 selection)
{
    if (JOY_NEW(DPAD_LEFT | DPAD_RIGHT))
    {
        selection ^= 1;
        sArrowPressed_option_menu = TRUE;
    }

    return selection;
}

static void BattleScene_DrawChoices_option_menu(u8 selection)
{
    u8 styles[2];

    styles[0] = 0;
    styles[1] = 0;
    styles[selection] = 1;

    DrawOptionMenuChoice_option_menu(gText_BattleSceneOn, 104, YPOS_BATTLESCENE_option_menu, styles[0]);
    DrawOptionMenuChoice_option_menu(gText_BattleSceneOff, GetStringRightAlignXOffset(FONT_NORMAL, gText_BattleSceneOff, 198), YPOS_BATTLESCENE_option_menu, styles[1]);
}

static u8 BattleStyle_ProcessInput_option_menu(u8 selection)
{
    if (JOY_NEW(DPAD_LEFT | DPAD_RIGHT))
    {
        selection ^= 1;
        sArrowPressed_option_menu = TRUE;
    }

    return selection;
}

static void BattleStyle_DrawChoices_option_menu(u8 selection)
{
    u8 styles[2];

    styles[0] = 0;
    styles[1] = 0;
    styles[selection] = 1;

    DrawOptionMenuChoice_option_menu(gText_BattleStyleShift, 104, YPOS_BATTLESTYLE_option_menu, styles[0]);
    DrawOptionMenuChoice_option_menu(gText_BattleStyleSet, GetStringRightAlignXOffset(FONT_NORMAL, gText_BattleStyleSet, 198), YPOS_BATTLESTYLE_option_menu, styles[1]);
}

static u8 Sound_ProcessInput_option_menu(u8 selection)
{
    if (JOY_NEW(DPAD_LEFT | DPAD_RIGHT))
    {
        selection ^= 1;
        SetPokemonCryStereo(selection);
        sArrowPressed_option_menu = TRUE;
    }

    return selection;
}

static void Sound_DrawChoices_option_menu(u8 selection)
{
    u8 styles[2];

    styles[0] = 0;
    styles[1] = 0;
    styles[selection] = 1;

    DrawOptionMenuChoice_option_menu(gText_SoundMono, 104, YPOS_SOUND_option_menu, styles[0]);
    DrawOptionMenuChoice_option_menu(gText_SoundStereo, GetStringRightAlignXOffset(FONT_NORMAL, gText_SoundStereo, 198), YPOS_SOUND_option_menu, styles[1]);
}

static u8 FrameType_ProcessInput_option_menu(u8 selection)
{
    if (JOY_NEW(DPAD_RIGHT))
    {
        if (selection < WINDOW_FRAMES_COUNT - 1)
            selection++;
        else
            selection = 0;

        LoadBgTiles(1, GetWindowFrameTilesPal(selection)->tiles, 0x120, 0x1A2);
        LoadPalette(GetWindowFrameTilesPal(selection)->pal, BG_PLTT_ID(7), PLTT_SIZE_4BPP);
        sArrowPressed_option_menu = TRUE;
    }
    if (JOY_NEW(DPAD_LEFT))
    {
        if (selection != 0)
            selection--;
        else
            selection = WINDOW_FRAMES_COUNT - 1;

        LoadBgTiles(1, GetWindowFrameTilesPal(selection)->tiles, 0x120, 0x1A2);
        LoadPalette(GetWindowFrameTilesPal(selection)->pal, BG_PLTT_ID(7), PLTT_SIZE_4BPP);
        sArrowPressed_option_menu = TRUE;
    }
    return selection;
}

static void FrameType_DrawChoices_option_menu(u8 selection)
{
    u8 text[16] = {EOS};
    u8 n = selection + 1;
    u16 i;

    for (i = 0; gText_FrameTypeNumber[i] != EOS && i <= 5; i++)
        text[i] = gText_FrameTypeNumber[i];

    // Convert a number to decimal string
    if (n / 10 != 0)
    {
        text[i] = n / 10 + CHAR_0;
        i++;
        text[i] = n % 10 + CHAR_0;
        i++;
    }
    else
    {
        text[i] = n % 10 + CHAR_0;
        i++;
        text[i] = CHAR_SPACER;
        i++;
    }

    text[i] = EOS;

    DrawOptionMenuChoice_option_menu(gText_FrameType, 104, YPOS_FRAMETYPE_option_menu, 0);
    DrawOptionMenuChoice_option_menu(text, 128, YPOS_FRAMETYPE_option_menu, 1);
}

static u8 ButtonMode_ProcessInput_option_menu(u8 selection)
{
    if (JOY_NEW(DPAD_RIGHT))
    {
        if (selection <= 1)
            selection++;
        else
            selection = 0;

        sArrowPressed_option_menu = TRUE;
    }
    if (JOY_NEW(DPAD_LEFT))
    {
        if (selection != 0)
            selection--;
        else
            selection = 2;

        sArrowPressed_option_menu = TRUE;
    }
    return selection;
}

static void ButtonMode_DrawChoices_option_menu(u8 selection)
{
    s32 widthNormal, widthLR, widthLA, xLR;
    u8 styles[3];

    styles[0] = 0;
    styles[1] = 0;
    styles[2] = 0;
    styles[selection] = 1;

    DrawOptionMenuChoice_option_menu(gText_ButtonTypeNormal, 104, YPOS_BUTTONMODE_option_menu, styles[0]);

    widthNormal = GetStringWidth(FONT_NORMAL, gText_ButtonTypeNormal, 0);
    widthLR = GetStringWidth(FONT_NORMAL, gText_ButtonTypeLR, 0);
    widthLA = GetStringWidth(FONT_NORMAL, gText_ButtonTypeLEqualsA, 0);

    widthLR -= 94;
    xLR = (widthNormal - widthLR - widthLA) / 2 + 104;
    DrawOptionMenuChoice_option_menu(gText_ButtonTypeLR, xLR, YPOS_BUTTONMODE_option_menu, styles[1]);

    DrawOptionMenuChoice_option_menu(gText_ButtonTypeLEqualsA, GetStringRightAlignXOffset(FONT_NORMAL, gText_ButtonTypeLEqualsA, 198), YPOS_BUTTONMODE_option_menu, styles[2]);
}

static void DrawHeaderText_option_menu(void)
{
    FillWindowPixelBuffer(WIN_HEADER_option_menu, PIXEL_FILL(1));
    AddTextPrinterParameterized(WIN_HEADER_option_menu, FONT_NORMAL, gText_Option, 8, 1, TEXT_SKIP_DRAW, NULL);
    CopyWindowToVram(WIN_HEADER_option_menu, COPYWIN_FULL);
}

static void DrawOptionMenuTexts_option_menu(void)
{
    u8 i;

    FillWindowPixelBuffer(WIN_OPTIONS_option_menu, PIXEL_FILL(1));
    for (i = 0; i < MENUITEM_COUNT_option_menu; i++)
        AddTextPrinterParameterized(WIN_OPTIONS_option_menu, FONT_NORMAL, sOptionMenuItemsNames[i], 8, (i * 16) + 1, TEXT_SKIP_DRAW, NULL);
    CopyWindowToVram(WIN_OPTIONS_option_menu, COPYWIN_FULL);
}

#define TILE_TOP_CORNER_L_option_menu 0x1A2
#define TILE_TOP_EDGE_option_menu     0x1A3
#define TILE_TOP_CORNER_R_option_menu 0x1A4
#define TILE_LEFT_EDGE_option_menu    0x1A5
#define TILE_RIGHT_EDGE_option_menu   0x1A7
#define TILE_BOT_CORNER_L_option_menu 0x1A8
#define TILE_BOT_EDGE_option_menu     0x1A9
#define TILE_BOT_CORNER_R_option_menu 0x1AA

static void DrawBgWindowFrames_option_menu(void)
{
    //                     bg, tile,              x, y, width, height, palNum
    // Draw title window frame
    FillBgTilemapBufferRect(1, TILE_TOP_CORNER_L_option_menu,  1,  0,  1,  1,  7);
    FillBgTilemapBufferRect(1, TILE_TOP_EDGE_option_menu,      2,  0, 27,  1,  7);
    FillBgTilemapBufferRect(1, TILE_TOP_CORNER_R_option_menu, 28,  0,  1,  1,  7);
    FillBgTilemapBufferRect(1, TILE_LEFT_EDGE_option_menu,     1,  1,  1,  2,  7);
    FillBgTilemapBufferRect(1, TILE_RIGHT_EDGE_option_menu,   28,  1,  1,  2,  7);
    FillBgTilemapBufferRect(1, TILE_BOT_CORNER_L_option_menu,  1,  3,  1,  1,  7);
    FillBgTilemapBufferRect(1, TILE_BOT_EDGE_option_menu,      2,  3, 27,  1,  7);
    FillBgTilemapBufferRect(1, TILE_BOT_CORNER_R_option_menu, 28,  3,  1,  1,  7);

    // Draw options list window frame
    FillBgTilemapBufferRect(1, TILE_TOP_CORNER_L_option_menu,  1,  4,  1,  1,  7);
    FillBgTilemapBufferRect(1, TILE_TOP_EDGE_option_menu,      2,  4, 26,  1,  7);
    FillBgTilemapBufferRect(1, TILE_TOP_CORNER_R_option_menu, 28,  4,  1,  1,  7);
    FillBgTilemapBufferRect(1, TILE_LEFT_EDGE_option_menu,     1,  5,  1, 18,  7);
    FillBgTilemapBufferRect(1, TILE_RIGHT_EDGE_option_menu,   28,  5,  1, 18,  7);
    FillBgTilemapBufferRect(1, TILE_BOT_CORNER_L_option_menu,  1, 19,  1,  1,  7);
    FillBgTilemapBufferRect(1, TILE_BOT_EDGE_option_menu,      2, 19, 26,  1,  7);
    FillBgTilemapBufferRect(1, TILE_BOT_CORNER_R_option_menu, 28, 19,  1,  1,  7);

    CopyBgTilemapBufferToVram(1);
}
