// code
static void InitPartyMenu_party_menu(u8 menuType, u8 layout, u8 partyAction, bool8 keepCursorPos, u8 messageId, TaskFunc task, MainCallback callback)
{
    u16 i;

    ResetPartyMenu_party_menu();
    sPartyMenuInternal_party_menu = Alloc(sizeof(struct PartyMenuInternal));
    if (sPartyMenuInternal_party_menu == NULL)
    {
        SetMainCallback2(callback);
    }
    else
    {
        gPartyMenu.menuType = menuType;
        gPartyMenu.exitCallback = callback;
        gPartyMenu.action = partyAction;
        sPartyMenuInternal_party_menu->messageId = messageId;
        sPartyMenuInternal_party_menu->task = task;
        sPartyMenuInternal_party_menu->exitCallback = NULL;
        sPartyMenuInternal_party_menu->lastSelectedSlot = 0;
        sPartyMenuInternal_party_menu->spriteIdConfirmPokeball = 0x7F;
        sPartyMenuInternal_party_menu->spriteIdCancelPokeball = 0x7F;

        if (menuType == PARTY_MENU_TYPE_CHOOSE_HALF)
            sPartyMenuInternal_party_menu->chooseHalf = TRUE;
        else
            sPartyMenuInternal_party_menu->chooseHalf = FALSE;

        if (layout != KEEP_PARTY_LAYOUT)
            gPartyMenu.layout = layout;

        for (i = 0; i < ARRAY_COUNT(sPartyMenuInternal_party_menu->data); i++)
            sPartyMenuInternal_party_menu->data[i] = 0;
        for (i = 0; i < ARRAY_COUNT(sPartyMenuInternal_party_menu->windowId); i++)
            sPartyMenuInternal_party_menu->windowId[i] = WINDOW_NONE;

        if (!keepCursorPos)
            gPartyMenu.slotId = 0;
        else if (gPartyMenu.slotId > PARTY_SIZE - 1 || GetMonData(&gPlayerParty[gPartyMenu.slotId], MON_DATA_SPECIES) == SPECIES_NONE)
            gPartyMenu.slotId = 0;

        gTextFlags.autoScroll = 0;
        CalculatePlayerPartyCount();
        SetMainCallback2(CB2_InitPartyMenu_party_menu);
    }
}

static void RefreshPartyMenu(void) //Refreshes the party menu without restarting tasks
{
    u16 i;
    for (i = 0; i < ARRAY_COUNT(sPartyMenuInternal_party_menu->data); i++)
        sPartyMenuInternal_party_menu->data[i] = 0;
    for (i = 0; i < ARRAY_COUNT(sPartyMenuInternal_party_menu->windowId); i++)
        sPartyMenuInternal_party_menu->windowId[i] = WINDOW_NONE;
    gTextFlags.autoScroll = 0;
    CalculatePlayerPartyCount();
    SetMainCallback2(CB2_ReloadPartyMenu_party_menu);
}

static void CB2_UpdatePartyMenu_party_menu(void)
{
    RunTasks();
    AnimateSprites();
    BuildOamBuffer();
    DoScheduledBgTilemapCopiesToVram();
    UpdatePaletteFade();
}

static void VBlankCB_PartyMenu_party_menu(void)
{
    LoadOam();
    ProcessSpriteCopyRequests();
    TransferPlttBuffer();
}

static void CB2_InitPartyMenu_party_menu(void)
{
    while (TRUE)
    {
        if (MenuHelpers_ShouldWaitForLinkRecv() == TRUE || ShowPartyMenu_party_menu() == TRUE || MenuHelpers_IsLinkActive() == TRUE)
            break;
    }
}

static void CB2_ReloadPartyMenu_party_menu(void)
{
    while (TRUE)
    {
        if (MenuHelpers_ShouldWaitForLinkRecv() == TRUE || ReloadPartyMenu_party_menu() == TRUE || MenuHelpers_IsLinkActive() == TRUE)
            break;
    }
}

static bool8 ShowPartyMenu_party_menu(void)
{
    switch (gMain.state)
    {
    case 0:
        SetVBlankHBlankCallbacksToNull();
        ResetVramOamAndBgCntRegs();
        ClearScheduledBgCopiesToVram();
        gMain.state++;
        break;
    case 1:
        ScanlineEffect_Stop();
        gMain.state++;
        break;
    case 2:
        ResetPaletteFade();
        gPaletteFade.bufferTransferDisabled = TRUE;
        gMain.state++;
        break;
    case 3:
        ResetSpriteData();
        gMain.state++;
        break;
    case 4:
        FreeAllSpritePalettes();
        gMain.state++;
        break;
    case 5:
        if (!MenuHelpers_IsLinkActive())
            ResetTasks();
        gMain.state++;
        break;
    case 6:
        SetPartyMonsAllowedInMinigame_party_menu();
        gMain.state++;
        break;
    case 7:
        if (!AllocPartyMenuBg_party_menu())
        {
            ExitPartyMenu_party_menu();
            return TRUE;
        }
        else
        {
            sPartyMenuInternal_party_menu->data[0] = 0;
            gMain.state++;
        }
        break;
    case 8:
        if (AllocPartyMenuBgGfx_party_menu())
            gMain.state++;
        break;
    case 9:
        InitPartyMenuWindows_party_menu(gPartyMenu.layout);
        gMain.state++;
        break;
    case 10:
        InitPartyMenuBoxes_party_menu(gPartyMenu.layout);
        sPartyMenuInternal_party_menu->data[0] = 0;
        gMain.state++;
        break;
    case 11:
        LoadHeldItemIcons();
        gMain.state++;
        break;
    case 12:
        LoadPartyMenuPokeballGfx_party_menu();
        gMain.state++;
        break;
    case 13:
        LoadPartyMenuAilmentGfx();
        gMain.state++;
        break;
    case 14:
        LoadMonIconPalettes();
        gMain.state++;
        break;
    case 15:
        if (CreatePartyMonSpritesLoop_party_menu())
        {
            sPartyMenuInternal_party_menu->data[0] = 0;
            gMain.state++;
        }
        break;
    case 16:
        if (RenderPartyMenuBoxes_party_menu())
        {
            sPartyMenuInternal_party_menu->data[0] = 0;
            gMain.state++;
        }
        break;
    case 17:
        CreateCancelConfirmPokeballSprites_party_menu();
        gMain.state++;
        break;
    case 18:
        CreateCancelConfirmWindows_party_menu(sPartyMenuInternal_party_menu->chooseHalf);
        gMain.state++;
        break;
    case 19:
        gMain.state++;
        break;
    case 20:
        CreateTask(sPartyMenuInternal_party_menu->task, 0);
        DisplayPartyMenuStdMessage(sPartyMenuInternal_party_menu->messageId);
        gMain.state++;
        break;
    case 21:
        BlendPalettes(PALETTES_ALL, 16, 0);
        gPaletteFade.bufferTransferDisabled = FALSE;
        gMain.state++;
        break;
    case 22:
        BeginNormalPaletteFade(PALETTES_ALL, 0, 16, 0, RGB_BLACK);
        gMain.state++;
        break;
    default:
        SetVBlankCallback(VBlankCB_PartyMenu_party_menu);
        SetMainCallback2(CB2_UpdatePartyMenu_party_menu);
        return TRUE;
    }
    return FALSE;
}

static bool8 ReloadPartyMenu_party_menu(void)
{
    switch (gMain.state)
    {
    case 0:
        SetVBlankHBlankCallbacksToNull();
        ClearScheduledBgCopiesToVram();
        gMain.state++;
        break;
    case 1:
        ScanlineEffect_Stop();
        gMain.state++;
        break;
    case 2:
        ResetPaletteFade();
        gPaletteFade.bufferTransferDisabled = TRUE;
        gMain.state++;
        break;
    case 3:
        ResetSpriteData();
        gMain.state++;
        break;
    case 4:
        FreeAllSpritePalettes();
        gMain.state++;
        break;
    case 5:
        SetPartyMonsAllowedInMinigame_party_menu();
        gMain.state++;
        break;
    case 6:
        sPartyMenuInternal_party_menu->data[0] = 0;
        gMain.state++;
        break;
    case 7:
        LoadPartyMenuWindows_party_menu();
        gMain.state++;
        break;
    case 8:
        LoadPartyMenuBoxes_party_menu(gPartyMenu.layout);
        sPartyMenuInternal_party_menu->data[0] = 0;
        gMain.state++;
        break;
    case 9:
        LoadHeldItemIcons();
        gMain.state++;
        break;
    case 10:
        LoadPartyMenuPokeballGfx_party_menu();
        gMain.state++;
        break;
    case 11:
        LoadPartyMenuAilmentGfx();
        gMain.state++;
        break;
    case 12:
        LoadMonIconPalettes();
        gMain.state++;
        break;
    case 13:
        if (CreatePartyMonSpritesLoop_party_menu())
        {
            sPartyMenuInternal_party_menu->data[0] = 0;
            gMain.state++;
        }
        break;
    case 14:
        if (RenderPartyMenuBoxes_party_menu())
        {
            sPartyMenuInternal_party_menu->data[0] = 0;
            gMain.state++;
        }
        break;
    case 15:
        CreateCancelConfirmPokeballSprites_party_menu();
        gMain.state++;
        break;
    case 16:
        CreateCancelConfirmWindows_party_menu(sPartyMenuInternal_party_menu->chooseHalf);
        gMain.state++;
        break;
    case 17:
        BlendPalettes(PALETTES_ALL, 16, RGB_WHITEALPHA);
        gPaletteFade.bufferTransferDisabled = FALSE;
        gMain.state++;
        break;
    case 18:
        BeginNormalPaletteFade(PALETTES_ALL, 0, 16, 0, RGB_WHITEALPHA);
        gMain.state++;
        break;
    default:
        SetVBlankCallback(VBlankCB_PartyMenu_party_menu);
        SetMainCallback2(CB2_UpdatePartyMenu_party_menu);
        return TRUE;
    }
    return FALSE;
}

static void ExitPartyMenu_party_menu(void)
{
    BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
    CreateTask(Task_ExitPartyMenu_party_menu, 0);
    SetVBlankCallback(VBlankCB_PartyMenu_party_menu);
    SetMainCallback2(CB2_UpdatePartyMenu_party_menu);
}

static void Task_ExitPartyMenu_party_menu(u8 taskId)
{
    if (!gPaletteFade.active)
    {
        SetMainCallback2(gPartyMenu.exitCallback);
        FreePartyPointers_party_menu();
        DestroyTask(taskId);
    }
}

static void ResetPartyMenu_party_menu(void)
{
    sPartyMenuInternal_party_menu = NULL;
    sPartyBgTilemapBuffer_party_menu = NULL;
    sPartyMenuBoxes_party_menu = NULL;
    sPartyBgGfxTilemap_party_menu = NULL;
}

static bool8 AllocPartyMenuBg_party_menu(void)
{
    sPartyBgTilemapBuffer_party_menu = Alloc(0x800);
    if (sPartyBgTilemapBuffer_party_menu == NULL)
        return FALSE;

    memset(sPartyBgTilemapBuffer_party_menu, 0, 0x800);
    ResetBgsAndClearDma3BusyFlags(0);
    InitBgsFromTemplates(0, sPartyMenuBgTemplates, ARRAY_COUNT(sPartyMenuBgTemplates));
    SetBgTilemapBuffer(1, sPartyBgTilemapBuffer_party_menu);
    ResetAllBgsCoordinates();
    ScheduleBgCopyTilemapToVram(1);
    SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_OBJ_ON | DISPCNT_OBJ_1D_MAP);
    SetGpuReg(REG_OFFSET_BLDCNT, 0);
    ShowBg(0);
    ShowBg(1);
    ShowBg(2);
    return TRUE;
}

static bool8 AllocPartyMenuBgGfx_party_menu(void)
{
    u32 sizeout;

    switch (sPartyMenuInternal_party_menu->data[0])
    {
    case 0:
        sPartyBgGfxTilemap_party_menu = malloc_and_decompress(gPartyMenuBg_Gfx, &sizeout);
        LoadBgTiles(1, sPartyBgGfxTilemap_party_menu, sizeout, 0);
        sPartyMenuInternal_party_menu->data[0]++;
        break;
    case 1:
        if (!IsDma3ManagerBusyWithBgCopy())
        {
            LZDecompressWram(gPartyMenuBg_Tilemap, sPartyBgTilemapBuffer_party_menu);
            sPartyMenuInternal_party_menu->data[0]++;
        }
        break;
    case 2:
        LoadCompressedPalette(gPartyMenuBg_Pal, BG_PLTT_ID(0), 11 * PLTT_SIZE_4BPP);
        CpuCopy16(gPlttBufferUnfaded, sPartyMenuInternal_party_menu->palBuffer, 11 * PLTT_SIZE_4BPP);
        sPartyMenuInternal_party_menu->data[0]++;
        break;
    case 3:
        PartyPaletteBufferCopy_party_menu(4);
        sPartyMenuInternal_party_menu->data[0]++;
        break;
    case 4:
        PartyPaletteBufferCopy_party_menu(5);
        sPartyMenuInternal_party_menu->data[0]++;
        break;
    case 5:
        PartyPaletteBufferCopy_party_menu(6);
        sPartyMenuInternal_party_menu->data[0]++;
        break;
    case 6:
        PartyPaletteBufferCopy_party_menu(7);
        sPartyMenuInternal_party_menu->data[0]++;
        break;
    case 7:
        PartyPaletteBufferCopy_party_menu(8);
        sPartyMenuInternal_party_menu->data[0]++;
        break;
    default:
        return TRUE;
    }
    return FALSE;
}

static void PartyPaletteBufferCopy_party_menu(u8 palNum)
{
    u8 offset = PLTT_ID(palNum);
    CpuCopy16(&gPlttBufferUnfaded[BG_PLTT_ID(3)], &gPlttBufferUnfaded[offset], PLTT_SIZE_4BPP);
    CpuCopy16(&gPlttBufferUnfaded[BG_PLTT_ID(3)], &gPlttBufferFaded[offset], PLTT_SIZE_4BPP);
}

static void FreePartyPointers_party_menu(void)
{
    if (sPartyMenuInternal_party_menu)
        Free(sPartyMenuInternal_party_menu);
    if (sPartyBgTilemapBuffer_party_menu)
        Free(sPartyBgTilemapBuffer_party_menu);
    if (sPartyBgGfxTilemap_party_menu)
        Free(sPartyBgGfxTilemap_party_menu);
    if (sPartyMenuBoxes_party_menu)
        Free(sPartyMenuBoxes_party_menu);
    FreeAllWindowBuffers();
}

static void InitPartyMenuBoxes_party_menu(u8 layout)
{
    sPartyMenuBoxes_party_menu = Alloc(sizeof(struct PartyMenuBox[PARTY_SIZE]));
    LoadPartyMenuBoxes_party_menu(layout);
}

static void LoadPartyMenuBoxes_party_menu(u8 layout)
{
    u32 i;

    for (i = 0; i < PARTY_SIZE; i++)
    {
        sPartyMenuBoxes_party_menu[i].infoRects = &sPartyBoxInfoRects[PARTY_BOX_RIGHT_COLUMN_party_menu];
        sPartyMenuBoxes_party_menu[i].spriteCoords = sPartyMenuSpriteCoords[layout][i];
        sPartyMenuBoxes_party_menu[i].windowId = i;
        sPartyMenuBoxes_party_menu[i].monSpriteId = SPRITE_NONE;
        sPartyMenuBoxes_party_menu[i].itemSpriteId = SPRITE_NONE;
        sPartyMenuBoxes_party_menu[i].pokeballSpriteId = SPRITE_NONE;
        sPartyMenuBoxes_party_menu[i].statusSpriteId = SPRITE_NONE;
    }
    // The first party mon goes in the left column
    sPartyMenuBoxes_party_menu[0].infoRects = &sPartyBoxInfoRects[PARTY_BOX_LEFT_COLUMN_party_menu];

    if (layout == PARTY_LAYOUT_MULTI_SHOWCASE)
        sPartyMenuBoxes_party_menu[3].infoRects = &sPartyBoxInfoRects[PARTY_BOX_LEFT_COLUMN_party_menu];
    else if (layout != PARTY_LAYOUT_SINGLE)
        sPartyMenuBoxes_party_menu[1].infoRects = &sPartyBoxInfoRects[PARTY_BOX_LEFT_COLUMN_party_menu];
}

static void RenderPartyMenuBox_party_menu(u8 slot)
{
    if (gPartyMenu.menuType == PARTY_MENU_TYPE_MULTI_SHOWCASE && slot >= MULTI_PARTY_SIZE)
    {
        DisplayPartyPokemonDataForMultiBattle_party_menu(slot);
        if (gMultiPartnerParty[slot - MULTI_PARTY_SIZE].species == SPECIES_NONE)
            LoadPartyBoxPalette_party_menu(&sPartyMenuBoxes_party_menu[slot], PARTY_PAL_NO_MON_party_menu);
        else
            LoadPartyBoxPalette_party_menu(&sPartyMenuBoxes_party_menu[slot], PARTY_PAL_MULTI_ALT_party_menu);
        CopyWindowToVram(sPartyMenuBoxes_party_menu[slot].windowId, COPYWIN_GFX);
        PutWindowTilemap(sPartyMenuBoxes_party_menu[slot].windowId);
        ScheduleBgCopyTilemapToVram(2);
    }
    else
    {
        if (GetMonData(&gPlayerParty[slot], MON_DATA_SPECIES) == SPECIES_NONE)
        {
            DrawEmptySlot_party_menu(sPartyMenuBoxes_party_menu[slot].windowId);
            LoadPartyBoxPalette_party_menu(&sPartyMenuBoxes_party_menu[slot], PARTY_PAL_NO_MON_party_menu);
            CopyWindowToVram(sPartyMenuBoxes_party_menu[slot].windowId, COPYWIN_GFX);
        }
        else
        {
            if (gPartyMenu.menuType == PARTY_MENU_TYPE_MOVE_RELEARNER)
                DisplayPartyPokemonDataForRelearner_party_menu(slot);
            else if (gPartyMenu.menuType == PARTY_MENU_TYPE_CONTEST)
                DisplayPartyPokemonDataForContest_party_menu(slot);
            else if (gPartyMenu.menuType == PARTY_MENU_TYPE_CHOOSE_HALF)
                DisplayPartyPokemonDataForChooseHalf_party_menu(slot);
            else if (gPartyMenu.menuType == PARTY_MENU_TYPE_MINIGAME)
                DisplayPartyPokemonDataForWirelessMinigame_party_menu(slot);
            else if (gPartyMenu.menuType == PARTY_MENU_TYPE_STORE_PYRAMID_HELD_ITEMS)
                DisplayPartyPokemonDataForBattlePyramidHeldItem_party_menu(slot);
            else if (!DisplayPartyPokemonDataForMoveTutorOrEvolutionItem_party_menu(slot))
                DisplayPartyPokemonData_party_menu(slot);

            if (gPartyMenu.menuType == PARTY_MENU_TYPE_MULTI_SHOWCASE)
                AnimatePartySlot(slot, 0);
            else if (gPartyMenu.slotId == slot)
                AnimatePartySlot(slot, 1);
            else
                AnimatePartySlot(slot, 0);
        }
        PutWindowTilemap(sPartyMenuBoxes_party_menu[slot].windowId);
        ScheduleBgCopyTilemapToVram(0);
    }
}

static void DisplayPartyPokemonData_party_menu(u8 slot)
{
    if (GetMonData(&gPlayerParty[slot], MON_DATA_IS_EGG))
    {
        sPartyMenuBoxes_party_menu[slot].infoRects->blitFunc(sPartyMenuBoxes_party_menu[slot].windowId, 0, 0, 0, 0, TRUE);
        DisplayPartyPokemonNickname_party_menu(&gPlayerParty[slot], &sPartyMenuBoxes_party_menu[slot], 0);
    }
    else
    {
        sPartyMenuBoxes_party_menu[slot].infoRects->blitFunc(sPartyMenuBoxes_party_menu[slot].windowId, 0, 0, 0, 0, FALSE);
        DisplayPartyPokemonNickname_party_menu(&gPlayerParty[slot], &sPartyMenuBoxes_party_menu[slot], 0);
        DisplayPartyPokemonLevelCheck_party_menu(&gPlayerParty[slot], &sPartyMenuBoxes_party_menu[slot], 0);
        DisplayPartyPokemonGenderNidoranCheck_party_menu(&gPlayerParty[slot], &sPartyMenuBoxes_party_menu[slot], 0);
        DisplayPartyPokemonHPCheck_party_menu(&gPlayerParty[slot], &sPartyMenuBoxes_party_menu[slot], 0);
        DisplayPartyPokemonMaxHPCheck_party_menu(&gPlayerParty[slot], &sPartyMenuBoxes_party_menu[slot], 0);
        DisplayPartyPokemonHPBarCheck_party_menu(&gPlayerParty[slot], &sPartyMenuBoxes_party_menu[slot]);
    }
}

static void DisplayPartyPokemonDescriptionData_party_menu(u8 slot, u8 stringID)
{
    struct Pokemon *mon = &gPlayerParty[slot];

    sPartyMenuBoxes_party_menu[slot].infoRects->blitFunc(sPartyMenuBoxes_party_menu[slot].windowId, 0, 0, 0, 0, TRUE);
    DisplayPartyPokemonNickname_party_menu(mon, &sPartyMenuBoxes_party_menu[slot], 0);
    if (!GetMonData(mon, MON_DATA_IS_EGG))
    {
        DisplayPartyPokemonLevelCheck_party_menu(mon, &sPartyMenuBoxes_party_menu[slot], 0);
        DisplayPartyPokemonGenderNidoranCheck_party_menu(mon, &sPartyMenuBoxes_party_menu[slot], 0);
    }
    DisplayPartyPokemonDescriptionText_party_menu(stringID, &sPartyMenuBoxes_party_menu[slot], 0);
}

static void DisplayPartyPokemonDataForChooseHalf_party_menu(u8 slot)
{
    u8 i;
    struct Pokemon *mon = &gPlayerParty[slot];
    u8 *order = gSelectedOrderFromParty;

    if (!GetBattleEntryEligibility_party_menu(mon))
    {
        DisplayPartyPokemonDescriptionData_party_menu(slot, PARTYBOX_DESC_NOT_ABLE);
        return;
    }
    else
    {
        for (i = 0; i < GetMaxBattleEntries_party_menu(); i++)
        {
            if (order[i] != 0 && (order[i] - 1) == slot)
            {
                DisplayPartyPokemonDescriptionData_party_menu(slot, i + PARTYBOX_DESC_FIRST);
                return;
            }
        }
        DisplayPartyPokemonDescriptionData_party_menu(slot, PARTYBOX_DESC_ABLE_3);
    }
}

static void DisplayPartyPokemonDataForContest_party_menu(u8 slot)
{
    switch (GetContestEntryEligibility(&gPlayerParty[slot]))
    {
    case CANT_ENTER_CONTEST:
    case CANT_ENTER_CONTEST_EGG:
    case CANT_ENTER_CONTEST_FAINTED:
        DisplayPartyPokemonDescriptionData_party_menu(slot, PARTYBOX_DESC_NOT_ABLE);
        break;
    case CAN_ENTER_CONTEST_EQUAL_RANK:
    case CAN_ENTER_CONTEST_HIGH_RANK:
        DisplayPartyPokemonDescriptionData_party_menu(slot, PARTYBOX_DESC_ABLE);
        break;
    }
}

static void DisplayPartyPokemonDataForRelearner_party_menu(u8 slot)
{
    if (GetNumberOfRelearnableMoves(&gPlayerParty[slot]) == 0)
        DisplayPartyPokemonDescriptionData_party_menu(slot, PARTYBOX_DESC_NOT_ABLE_2);
    else
        DisplayPartyPokemonDescriptionData_party_menu(slot, PARTYBOX_DESC_ABLE_2);
}

static void DisplayPartyPokemonDataForWirelessMinigame_party_menu(u8 slot)
{
    if (IsMonAllowedInMinigame_party_menu(slot) == TRUE)
        DisplayPartyPokemonDescriptionData_party_menu(slot, PARTYBOX_DESC_ABLE);
    else
        DisplayPartyPokemonDescriptionData_party_menu(slot, PARTYBOX_DESC_NOT_ABLE);
}

static void DisplayPartyPokemonDataForBattlePyramidHeldItem_party_menu(u8 slot)
{
    if (GetMonData(&gPlayerParty[slot], MON_DATA_HELD_ITEM))
        DisplayPartyPokemonDescriptionData_party_menu(slot, PARTYBOX_DESC_HAVE);
    else
        DisplayPartyPokemonDescriptionData_party_menu(slot, PARTYBOX_DESC_DONT_HAVE);
}

// Returns TRUE if teaching move or cant evolve with item (i.e. description data is shown), FALSE otherwise
static bool8 DisplayPartyPokemonDataForMoveTutorOrEvolutionItem_party_menu(u8 slot)
{
    struct Pokemon *currentPokemon = &gPlayerParty[slot];
    u16 item = gSpecialVar_ItemId;

    if (gPartyMenu.action == PARTY_ACTION_MOVE_TUTOR)
    {
        gSpecialVar_Result = FALSE;
        DisplayPartyPokemonDataToTeachMove_party_menu(slot, gSpecialVar_0x8005);
    }
    else
    {
        if (gPartyMenu.action != PARTY_ACTION_USE_ITEM)
            return FALSE;

        switch (CheckIfItemIsTMHMOrEvolutionStone(item))
        {
        default:
            return FALSE;
        case 1: // TM/HM
            DisplayPartyPokemonDataToTeachMove_party_menu(slot, ItemIdToBattleMoveId(item));
            break;
        case 2: // Evolution stone
            if (!GetMonData(currentPokemon, MON_DATA_IS_EGG) && GetEvolutionTargetSpecies(currentPokemon, EVO_MODE_ITEM_CHECK, item, NULL) != SPECIES_NONE)
                return FALSE;
            DisplayPartyPokemonDescriptionData_party_menu(slot, PARTYBOX_DESC_NO_USE);
            break;
        }
    }
    return TRUE;
}

static void DisplayPartyPokemonDataToTeachMove_party_menu(u8 slot, u16 move)
{
    switch (CanTeachMove_party_menu(&gPlayerParty[slot], move))
    {
    case CANNOT_LEARN_MOVE_party_menu:
    case CANNOT_LEARN_MOVE_IS_EGG_party_menu:
        DisplayPartyPokemonDescriptionData_party_menu(slot, PARTYBOX_DESC_NOT_ABLE_2);
        break;
    case ALREADY_KNOWS_MOVE_party_menu:
        DisplayPartyPokemonDescriptionData_party_menu(slot, PARTYBOX_DESC_LEARNED);
        break;
    default:
        DisplayPartyPokemonDescriptionData_party_menu(slot, PARTYBOX_DESC_ABLE_2);
        break;
    }
}

static void DisplayPartyPokemonDataForMultiBattle_party_menu(u8 slot)
{
    struct PartyMenuBox *menuBox = &sPartyMenuBoxes_party_menu[slot];
    u8 actualSlot = slot - MULTI_PARTY_SIZE;

    if (gMultiPartnerParty[actualSlot].species == SPECIES_NONE)
    {
        DrawEmptySlot_party_menu(menuBox->windowId);
    }
    else
    {
        menuBox->infoRects->blitFunc(menuBox->windowId, 0, 0, 0, 0, FALSE);
        StringCopy(gStringVar1, gMultiPartnerParty[actualSlot].nickname);
        StringGet_Nickname(gStringVar1);
        ConvertInternationalPlayerName(gStringVar1);
        DisplayPartyPokemonBarDetail_party_menu(menuBox->windowId, gStringVar1, 0, menuBox->infoRects->dimensions);
        DisplayPartyPokemonLevel_party_menu(gMultiPartnerParty[actualSlot].level, menuBox);
        DisplayPartyPokemonGender_party_menu(gMultiPartnerParty[actualSlot].gender, gMultiPartnerParty[actualSlot].species, gMultiPartnerParty[actualSlot].nickname, menuBox);
        DisplayPartyPokemonHP_party_menu(gMultiPartnerParty[actualSlot].hp, gMultiPartnerParty[actualSlot].maxhp, menuBox);
        DisplayPartyPokemonMaxHP_party_menu(gMultiPartnerParty[actualSlot].maxhp, menuBox);
        DisplayPartyPokemonHPBar_party_menu(gMultiPartnerParty[actualSlot].hp, gMultiPartnerParty[actualSlot].maxhp, menuBox);
    }
}

static bool8 RenderPartyMenuBoxes_party_menu(void)
{
    RenderPartyMenuBox_party_menu(sPartyMenuInternal_party_menu->data[0]);
    if (++sPartyMenuInternal_party_menu->data[0] == PARTY_SIZE)
        return TRUE;
    else
        return FALSE;
}

static u8 *GetPartyMenuBgTile(u16 tileId)
{
    return &sPartyBgGfxTilemap_party_menu[tileId << 5];
}

static void CreatePartyMonSprites_party_menu(u8 slot)
{
    u8 actualSlot;

    if (gPartyMenu.menuType == PARTY_MENU_TYPE_MULTI_SHOWCASE && slot >= MULTI_PARTY_SIZE)
    {
        u8 status;
        actualSlot = slot - MULTI_PARTY_SIZE;

        if (gMultiPartnerParty[actualSlot].species != SPECIES_NONE)
        {
            CreatePartyMonIconSpriteParameterized_party_menu(gMultiPartnerParty[actualSlot].species, gMultiPartnerParty[actualSlot].personality, &sPartyMenuBoxes_party_menu[slot], 0);
            CreatePartyMonHeldItemSpriteParameterized_party_menu(gMultiPartnerParty[actualSlot].species, gMultiPartnerParty[actualSlot].heldItem, &sPartyMenuBoxes_party_menu[slot]);
            CreatePartyMonPokeballSpriteParameterized_party_menu(gMultiPartnerParty[actualSlot].species, &sPartyMenuBoxes_party_menu[slot]);
            if (gMultiPartnerParty[actualSlot].hp == 0)
                status = AILMENT_FNT;
            else
                status = GetAilmentFromStatus(gMultiPartnerParty[actualSlot].status);
            CreatePartyMonStatusSpriteParameterized_party_menu(gMultiPartnerParty[actualSlot].species, status, &sPartyMenuBoxes_party_menu[slot]);
        }
    }
    else if (GetMonData(&gPlayerParty[slot], MON_DATA_SPECIES) != SPECIES_NONE)
    {
        CreatePartyMonIconSprite_party_menu(&gPlayerParty[slot], &sPartyMenuBoxes_party_menu[slot], slot);
        CreatePartyMonHeldItemSprite_party_menu(&gPlayerParty[slot], &sPartyMenuBoxes_party_menu[slot]);
        CreatePartyMonPokeballSprite_party_menu(&gPlayerParty[slot], &sPartyMenuBoxes_party_menu[slot]);
        CreatePartyMonStatusSprite_party_menu(&gPlayerParty[slot], &sPartyMenuBoxes_party_menu[slot]);
    }
}

static bool8 CreatePartyMonSpritesLoop_party_menu(void)
{
    CreatePartyMonSprites_party_menu(sPartyMenuInternal_party_menu->data[0]);
    if (++sPartyMenuInternal_party_menu->data[0] == PARTY_SIZE)
        return TRUE;
    else
        return FALSE;
}

static void CreateCancelConfirmPokeballSprites_party_menu(void)
{
    if (gPartyMenu.menuType == PARTY_MENU_TYPE_MULTI_SHOWCASE)
    {
        // The showcase has no Cancel/Confirm buttons
        FillBgTilemapBufferRect(1, 14, 23, 17, 7, 2, 1);
    }
    else
    {
        if (sPartyMenuInternal_party_menu->chooseHalf)
        {
            sPartyMenuInternal_party_menu->spriteIdConfirmPokeball = CreateSmallPokeballButtonSprite_party_menu(0xBF, 0x88);
            DrawCancelConfirmButtons_party_menu();
            sPartyMenuInternal_party_menu->spriteIdCancelPokeball = CreateSmallPokeballButtonSprite_party_menu(0xBF, 0x98);
        }
        else
        {
            sPartyMenuInternal_party_menu->spriteIdCancelPokeball = CreatePokeballButtonSprite_party_menu(198, 148);
        }
        AnimatePartySlot(gPartyMenu.slotId, 1);
    }
}

void AnimatePartySlot(u8 slot, u8 animNum)
{
    u8 spriteId;

    switch (slot)
    {
    default:
        if (GetMonData(&gPlayerParty[slot], MON_DATA_SPECIES) != SPECIES_NONE)
        {
            LoadPartyBoxPalette_party_menu(&sPartyMenuBoxes_party_menu[slot], GetPartyBoxPaletteFlags_party_menu(slot, animNum));
            AnimateSelectedPartyIcon_party_menu(sPartyMenuBoxes_party_menu[slot].monSpriteId, animNum);
            PartyMenuStartSpriteAnim_party_menu(sPartyMenuBoxes_party_menu[slot].pokeballSpriteId, animNum);
        }
        return;
    case PARTY_SIZE: // Confirm
        if (animNum == 0)
            SetBgTilemapPalette(1, 23, 16, 7, 2, 1);
        else
            SetBgTilemapPalette(1, 23, 16, 7, 2, 2);
        spriteId = sPartyMenuInternal_party_menu->spriteIdConfirmPokeball;
        break;
    case PARTY_SIZE + 1: // Cancel
        // The position of the Cancel button changes if Confirm is present
        if (!sPartyMenuInternal_party_menu->chooseHalf)
        {
            if (animNum == 0)
                SetBgTilemapPalette(1, 23, 17, 7, 2, 1);
            else
                SetBgTilemapPalette(1, 23, 17, 7, 2, 2);
        }
        else if (animNum == 0)
        {
            SetBgTilemapPalette(1, 23, 18, 7, 2, 1);
        }
        else
        {
            SetBgTilemapPalette(1, 23, 18, 7, 2, 2);
        }
        spriteId = sPartyMenuInternal_party_menu->spriteIdCancelPokeball;
        break;
    }
    PartyMenuStartSpriteAnim_party_menu(spriteId, animNum);
    ScheduleBgCopyTilemapToVram(1);
}

static u8 GetPartyBoxPaletteFlags_party_menu(u8 slot, u8 animNum)
{
    u8 palFlags = 0;

    if (animNum == 1)
        palFlags |= PARTY_PAL_SELECTED_party_menu;
    if (GetMonData(&gPlayerParty[slot], MON_DATA_HP) == 0)
        palFlags |= PARTY_PAL_FAINTED_party_menu;
    if (PartyBoxPal_ParnterOrDisqualifiedInArena_party_menu(slot) == TRUE)
        palFlags |= PARTY_PAL_MULTI_ALT_party_menu;
    if (gPartyMenu.action == PARTY_ACTION_SWITCHING)
        palFlags |= PARTY_PAL_SWITCHING_party_menu;
    if (gPartyMenu.action == PARTY_ACTION_SWITCH)
    {
        if (slot == gPartyMenu.slotId || slot == gPartyMenu.slotId2)
            palFlags |= PARTY_PAL_TO_SWITCH_party_menu;
    }
    if (gPartyMenu.action == PARTY_ACTION_SOFTBOILED && slot == gPartyMenu.slotId )
        palFlags |= PARTY_PAL_TO_SOFTBOIL_party_menu;

    return palFlags;
}

static bool8 PartyBoxPal_ParnterOrDisqualifiedInArena_party_menu(u8 slot)
{
    if (gPartyMenu.layout == PARTY_LAYOUT_MULTI && (slot == 1 || slot == 4 || slot == 5))
        return TRUE;

    if (slot < MULTI_PARTY_SIZE && (gBattleTypeFlags & BATTLE_TYPE_ARENA) && gMain.inBattle && (gBattleStruct->arenaLostPlayerMons >> GetPartyIdFromBattleSlot_party_menu(slot) & 1))
        return TRUE;

    return FALSE;
}

static void DrawCancelConfirmButtons_party_menu(void)
{
    CopyToBgTilemapBufferRect_ChangePalette(1, sConfirmButton_Tilemap, 23, 16, 7, 2, 17);
    CopyToBgTilemapBufferRect_ChangePalette(1, sCancelButton_Tilemap, 23, 18, 7, 2, 17);
    ScheduleBgCopyTilemapToVram(1);
}

bool8 IsMultiBattle(void)
{
    if (gBattleTypeFlags & BATTLE_TYPE_MULTI && IsDoubleBattle() && gMain.inBattle)
        return TRUE;
    else
        return FALSE;
}

static void SwapPartyPokemon_party_menu(struct Pokemon *mon1, struct Pokemon *mon2)
{
    struct Pokemon *temp = Alloc(sizeof(struct Pokemon));

    *temp = *mon1;
    *mon1 = *mon2;
    *mon2 = *temp;

    Free(temp);
}

static void Task_ClosePartyMenu_party_menu(u8 taskId)
{
    BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
    gTasks[taskId].func = Task_ClosePartyMenuAndSetCB2_party_menu;
}

static void Task_ClosePartyMenuAndSetCB2_party_menu(u8 taskId)
{
    if (!gPaletteFade.active)
    {
        if (gPartyMenu.menuType == PARTY_MENU_TYPE_IN_BATTLE)
            UpdatePartyToFieldOrder_party_menu();

        if (sPartyMenuInternal_party_menu->exitCallback != NULL)
            SetMainCallback2(sPartyMenuInternal_party_menu->exitCallback);
        else
            SetMainCallback2(gPartyMenu.exitCallback);

        ResetSpriteData();
        FreePartyPointers_party_menu();
        DestroyTask(taskId);
    }
}

u8 GetCursorSelectionMonId(void)
{
    return gPartyMenu.slotId;
}

u8 GetPartyMenuType(void)
{
    return gPartyMenu.menuType;
}

void Task_HandleChooseMonInput(u8 taskId)
{
    if (!gPaletteFade.active && MenuHelpers_ShouldWaitForLinkRecv() != TRUE)
    {
        s8 *slotPtr = GetCurrentPartySlotPtr();

        switch (PartyMenuButtonHandler_party_menu(slotPtr))
        {
        case A_BUTTON: // Selected mon
            HandleChooseMonSelection_party_menu(taskId, slotPtr);
            break;
        case B_BUTTON: // Selected Cancel / pressed B
            HandleChooseMonCancel_party_menu(taskId, slotPtr);
            break;
        case START_BUTTON:
            if (sPartyMenuInternal_party_menu->chooseHalf)
            {
                PlaySE(SE_SELECT);
                MoveCursorToConfirm_party_menu();
            }
            break;
        }
    }
}

static s8 *GetCurrentPartySlotPtr(void)
{
    if (gPartyMenu.action == PARTY_ACTION_SWITCH || gPartyMenu.action == PARTY_ACTION_SOFTBOILED)
        return &gPartyMenu.slotId2;
    else
        return &gPartyMenu.slotId;
}

static void HandleChooseMonSelection_party_menu(u8 taskId, s8 *slotPtr)
{
    if (*slotPtr == PARTY_SIZE)
    {
        gPartyMenu.task(taskId);
    }
    else
    {
        switch (gPartyMenu.action)
        {
        case PARTY_ACTION_SOFTBOILED:
            if (IsSelectedMonNotEgg_party_menu((u8 *)slotPtr))
            {
                PartyMenuRemoveWindow_party_menu(&sPartyMenuInternal_party_menu->windowId[1]);
                Task_TryUseSoftboiledOnPartyMon(taskId);
            }
            break;
        case PARTY_ACTION_USE_ITEM:
            if (IsSelectedMonNotEgg_party_menu((u8 *)slotPtr))
            {
                if (gPartyMenu.menuType == PARTY_MENU_TYPE_IN_BATTLE)
                    sPartyMenuInternal_party_menu->exitCallback = CB2_SetUpExitToBattleScreen_party_menu;

                PartyMenuRemoveWindow_party_menu(&sPartyMenuInternal_party_menu->windowId[1]);
                gItemUseCB(taskId, Task_ClosePartyMenuAfterText_party_menu);
            }
            break;
        case PARTY_ACTION_MOVE_TUTOR:
            if (IsSelectedMonNotEgg_party_menu((u8 *)slotPtr))
            {
                PlaySE(SE_SELECT);
                PartyMenuRemoveWindow_party_menu(&sPartyMenuInternal_party_menu->windowId[1]);
                TryTutorSelectedMon_party_menu(taskId);
            }
            break;
        case PARTY_ACTION_GIVE_MAILBOX_MAIL:
            if (IsSelectedMonNotEgg_party_menu((u8 *)slotPtr))
            {
                PlaySE(SE_SELECT);
                PartyMenuRemoveWindow_party_menu(&sPartyMenuInternal_party_menu->windowId[1]);
                TryGiveMailToSelectedMon_party_menu(taskId);
            }
            break;
        case PARTY_ACTION_GIVE_ITEM:
        case PARTY_ACTION_GIVE_PC_ITEM:
            if (IsSelectedMonNotEgg_party_menu((u8 *)slotPtr))
            {
                PlaySE(SE_SELECT);
                PartyMenuRemoveWindow_party_menu(&sPartyMenuInternal_party_menu->windowId[1]);
                TryGiveItemOrMailToSelectedMon_party_menu(taskId);
            }
            break;
        case PARTY_ACTION_SWITCH:
            PlaySE(SE_SELECT);
            SwitchSelectedMons_party_menu(taskId);
            break;
        case PARTY_ACTION_CHOOSE_AND_CLOSE:
            PlaySE(SE_SELECT);
            Task_ClosePartyMenu_party_menu(taskId);
            break;
        case PARTY_ACTION_MINIGAME:
            if (IsSelectedMonNotEgg_party_menu((u8 *)slotPtr))
            {
                TryEnterMonForMinigame_party_menu(taskId, (u8)*slotPtr);
            }
            break;
        case PARTY_ACTION_CHOOSE_FAINTED_MON:
        {
            u8 partyId = GetPartyIdFromBattleSlot_party_menu((u8)*slotPtr);
            if (GetMonData(&gPlayerParty[*slotPtr], MON_DATA_HP) > 0
                || GetMonData(&gPlayerParty[*slotPtr], MON_DATA_SPECIES_OR_EGG) == SPECIES_EGG
                || ((gBattleTypeFlags & BATTLE_TYPE_MULTI) && partyId >= (PARTY_SIZE / 2)))
            {
                // Can't select if egg, alive, or doesn't belong to you
                PlaySE(SE_FAILURE);
            }
            else
            {
                PlaySE(SE_SELECT);
                gSelectedMonPartyId = partyId;
                Task_ClosePartyMenu_party_menu(taskId);
            }
            break;
        }
        default:
        case PARTY_ACTION_ABILITY_PREVENTS:
        case PARTY_ACTION_SWITCHING:
            PlaySE(SE_SELECT);
            Task_TryCreateSelectionWindow_party_menu(taskId);
            break;
        }
    }
}

static bool8 IsSelectedMonNotEgg_party_menu(u8 *slotPtr)
{
    if (GetMonData(&gPlayerParty[*slotPtr], MON_DATA_IS_EGG) == TRUE)
    {
        PlaySE(SE_FAILURE);
        return FALSE;
    }
    return TRUE;
}

static void HandleChooseMonCancel_party_menu(u8 taskId, s8 *slotPtr)
{
    switch (gPartyMenu.action)
    {
    case PARTY_ACTION_SEND_OUT:
    case PARTY_ACTION_CHOOSE_FAINTED_MON:
        PlaySE(SE_FAILURE);
        break;
    case PARTY_ACTION_SWITCH:
    case PARTY_ACTION_SOFTBOILED:
        PlaySE(SE_SELECT);
        FinishTwoMonAction_party_menu(taskId);
        break;
    case PARTY_ACTION_MINIGAME:
        PlaySE(SE_SELECT);
        CancelParticipationPrompt_party_menu(taskId);
        break;
    default:
        PlaySE(SE_SELECT);
        if (DisplayCancelChooseMonYesNo_party_menu(taskId) != TRUE)
        {
            if (!MenuHelpers_IsLinkActive())
                gSpecialVar_0x8004 = PARTY_SIZE + 1;
            gPartyMenuUseExitCallback = FALSE;
            *slotPtr = PARTY_SIZE + 1;
            Task_ClosePartyMenu_party_menu(taskId);
        }
        break;
    }
}

static bool8 DisplayCancelChooseMonYesNo_party_menu(u8 taskId)
{
    const u8 *stringPtr = NULL;

    if (gPartyMenu.menuType == PARTY_MENU_TYPE_CONTEST)
        stringPtr = gText_CancelParticipation;
    else if (gPartyMenu.menuType == PARTY_MENU_TYPE_CHOOSE_HALF)
        stringPtr = GetFacilityCancelString();

    if (stringPtr == NULL)
        return FALSE;

    PartyMenuRemoveWindow_party_menu(&sPartyMenuInternal_party_menu->windowId[1]);
    StringExpandPlaceholders(gStringVar4, stringPtr);
    DisplayPartyMenuMessage(gStringVar4, TRUE);
    gTasks[taskId].func = Task_CancelChooseMonYesNo_party_menu;
    return TRUE;
}

