#define tHP_party_menu           data[0]
#define tMaxHP_party_menu        data[1]
#define tHPIncrement_party_menu  data[2]
#define tHPToAdd_party_menu      data[3]
#define tPartyId_party_menu      data[4]
#define tStartHP_party_menu      data[5]

static void Task_PartyMenuModifyHP_party_menu(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    tHP_party_menu += tHPIncrement_party_menu;
    tHPToAdd_party_menu--;
    SetMonData(&gPlayerParty[tPartyId_party_menu], MON_DATA_HP, &tHP_party_menu);
    DisplayPartyPokemonHPCheck_party_menu(&gPlayerParty[tPartyId_party_menu], &sPartyMenuBoxes_party_menu[tPartyId_party_menu], 1);
    DisplayPartyPokemonHPBarCheck_party_menu(&gPlayerParty[tPartyId_party_menu], &sPartyMenuBoxes_party_menu[tPartyId_party_menu]);
    if (tHPToAdd_party_menu == 0 || tHP_party_menu == 0 || tHP_party_menu == tMaxHP_party_menu)
    {
        // If HP was recovered, buffer the amount recovered
        if (tHP_party_menu > tStartHP_party_menu)
            ConvertIntToDecimalStringN(gStringVar2, tHP_party_menu - tStartHP_party_menu, STR_CONV_MODE_LEFT_ALIGN, 3);

        SwitchTaskToFollowupFunc(taskId);
    }
}

void PartyMenuModifyHP(u8 taskId, u8 slot, s8 hpIncrement, s16 hpDifference, TaskFunc task)
{
    struct Pokemon *mon = &gPlayerParty[slot];
    s16 *data = gTasks[taskId].data;

    tHP_party_menu = GetMonData(mon, MON_DATA_HP);
    tMaxHP_party_menu = GetMonData(mon, MON_DATA_MAX_HP);
    tHPIncrement_party_menu = hpIncrement;
    tHPToAdd_party_menu = hpDifference;
    tPartyId_party_menu = slot;
    tStartHP_party_menu = tHP_party_menu;
    SetTaskFuncWithFollowupFunc(taskId, Task_PartyMenuModifyHP_party_menu, task);
}

// The usage of hp in this function is mostly nonsense
// Because caseId is always passed 0, none of the other cases ever occur
static void ResetHPTaskData_party_menu(u8 taskId, u8 caseId, u32 hp)
{
    s16 *data = gTasks[taskId].data;

    switch (caseId) // always zero
    {
        case 0:
            tHP_party_menu = hp;
            tStartHP_party_menu = hp;
            break;
        case 1:
            tMaxHP_party_menu = hp;
            break;
        case 2:
            tHPIncrement_party_menu = hp;
            break;
        case 3:
            tHPToAdd_party_menu = hp;
            break;
        case 4:
            tPartyId_party_menu = hp;
            break;
        case 5:
            SetTaskFuncWithFollowupFunc(taskId, Task_PartyMenuModifyHP_party_menu, (TaskFunc)hp); // >casting hp as a taskfunc
            break;
    }
}

#undef tHP_party_menu
#undef tMaxHP_party_menu
#undef tHPIncrement_party_menu
#undef tHPToAdd_party_menu
