static void SetPartyMonSelectionActions_party_menu(struct Pokemon *mons, u8 slotId, u8 action)
{
    u8 i;

    if (action == ACTIONS_NONE_party_menu)
    {
        SetPartyMonFieldSelectionActions_party_menu(mons, slotId);
    }
    else
    {
        sPartyMenuInternal_party_menu->numActions = sPartyMenuActionCounts[action];
        for (i = 0; i < sPartyMenuInternal_party_menu->numActions; i++)
            sPartyMenuInternal_party_menu->actions[i] = sPartyMenuActions[action][i];
    }
}

static void SetPartyMonFieldSelectionActions_party_menu(struct Pokemon *mons, u8 slotId)
{
    u8 i, j;

    sPartyMenuInternal_party_menu->numActions = 0;
    AppendToList(sPartyMenuInternal_party_menu->actions, &sPartyMenuInternal_party_menu->numActions, MENU_SUMMARY_party_menu);

    // Add field moves to action list
    for (i = 0; i < MAX_MON_MOVES; i++)
    {
        for (j = 0; j != FIELD_MOVES_COUNT_party_menu; j++)
        {
            if (GetMonData(&mons[slotId], i + MON_DATA_MOVE1) == sFieldMoves[j])
            {
                AppendToList(sPartyMenuInternal_party_menu->actions, &sPartyMenuInternal_party_menu->numActions, j + MENU_FIELD_MOVES_party_menu);
                break;
            }
        }
    }

    if (!InBattlePike())
    {
        if (GetMonData(&mons[1], MON_DATA_SPECIES) != SPECIES_NONE)
            AppendToList(sPartyMenuInternal_party_menu->actions, &sPartyMenuInternal_party_menu->numActions, MENU_SWITCH_party_menu);
        if (ItemIsMail(GetMonData(&mons[slotId], MON_DATA_HELD_ITEM)))
            AppendToList(sPartyMenuInternal_party_menu->actions, &sPartyMenuInternal_party_menu->numActions, MENU_MAIL_party_menu);
        else
            AppendToList(sPartyMenuInternal_party_menu->actions, &sPartyMenuInternal_party_menu->numActions, MENU_ITEM_party_menu);
    }
    AppendToList(sPartyMenuInternal_party_menu->actions, &sPartyMenuInternal_party_menu->numActions, MENU_CANCEL1_party_menu);
}

static u8 GetPartyMenuActionsType_party_menu(struct Pokemon *mon)
{
    u32 actionType;

    switch (gPartyMenu.menuType)
    {
    case PARTY_MENU_TYPE_FIELD:
        if (InMultiPartnerRoom() == TRUE || GetMonData(mon, MON_DATA_IS_EGG))
            actionType = ACTIONS_SWITCH_party_menu;
        else
            actionType = ACTIONS_NONE_party_menu; // actions populated by SetPartyMonFieldSelectionActions_party_menu
        break;
    case PARTY_MENU_TYPE_IN_BATTLE:
        actionType = GetPartyMenuActionsTypeInBattle_party_menu(mon);
        break;
    case PARTY_MENU_TYPE_CHOOSE_HALF:
        switch (GetPartySlotEntryStatus_party_menu(gPartyMenu.slotId))
        {
        default: // Not eligible
            actionType = ACTIONS_SUMMARY_ONLY_party_menu;
            break;
        case 0: // Eligible
            actionType = ACTIONS_ENTER_party_menu;
            break;
        case 1: // Already selected
            actionType = ACTIONS_NO_ENTRY_party_menu;
            break;
        }
        break;
    case PARTY_MENU_TYPE_DAYCARE:
        actionType = (GetMonData(mon, MON_DATA_IS_EGG)) ? ACTIONS_SUMMARY_ONLY_party_menu : ACTIONS_STORE_party_menu;
        break;
    case PARTY_MENU_TYPE_UNION_ROOM_REGISTER:
        actionType = ACTIONS_REGISTER_party_menu;
        break;
    case PARTY_MENU_TYPE_UNION_ROOM_TRADE:
        actionType = ACTIONS_TRADE_party_menu;
        break;
    case PARTY_MENU_TYPE_SPIN_TRADE:
        actionType = ACTIONS_SPIN_TRADE_party_menu;
        break;
    case PARTY_MENU_TYPE_STORE_PYRAMID_HELD_ITEMS:
        actionType = ACTIONS_TAKEITEM_TOSS_party_menu;
        break;
    // The following have no selection actions (i.e. they exit immediately upon selection)
    // PARTY_MENU_TYPE_CONTEST
    // PARTY_MENU_TYPE_CHOOSE_MON
    // PARTY_MENU_TYPE_MULTI_SHOWCASE
    // PARTY_MENU_TYPE_MOVE_RELEARNER
    // PARTY_MENU_TYPE_MINIGAME
    default:
        actionType = ACTIONS_NONE_party_menu;
        break;
    }
    return actionType;
}

static bool8 CreateSelectionWindow_party_menu(u8 taskId)
{
    struct Pokemon *mon = &gPlayerParty[gPartyMenu.slotId];
    u16 item;

    GetMonNickname(mon, gStringVar1);
    PartyMenuRemoveWindow_party_menu(&sPartyMenuInternal_party_menu->windowId[1]);
    if (gPartyMenu.menuType != PARTY_MENU_TYPE_STORE_PYRAMID_HELD_ITEMS)
    {
        SetPartyMonSelectionActions_party_menu(gPlayerParty, gPartyMenu.slotId, GetPartyMenuActionsType_party_menu(mon));
        DisplaySelectionWindow_party_menu(SELECTWINDOW_ACTIONS);
        DisplayPartyMenuStdMessage(PARTY_MSG_DO_WHAT_WITH_MON);
    }
    else
    {
        item = GetMonData(mon, MON_DATA_HELD_ITEM);
        if (item != ITEM_NONE)
        {
            SetPartyMonSelectionActions_party_menu(gPlayerParty, gPartyMenu.slotId, GetPartyMenuActionsType_party_menu(mon));
            DisplaySelectionWindow_party_menu(SELECTWINDOW_ITEM);
            CopyItemName(item, gStringVar2);
            DisplayPartyMenuStdMessage(PARTY_MSG_ALREADY_HOLDING_ONE);
        }
        else
        {
            StringExpandPlaceholders(gStringVar4, gText_PkmnNotHolding);
            DisplayPartyMenuMessage(gStringVar4, TRUE);
            ScheduleBgCopyTilemapToVram(2);
            gTasks[taskId].func = Task_UpdateHeldItemSprite_party_menu;
            return FALSE;
        }
    }
    return TRUE;
}

static void Task_TryCreateSelectionWindow_party_menu(u8 taskId)
{
    if (CreateSelectionWindow_party_menu(taskId))
    {
        gTasks[taskId].data[0] = 0xFF;
        gTasks[taskId].func = Task_HandleSelectionMenuInput_party_menu;
    }
}

static void Task_HandleSelectionMenuInput_party_menu(u8 taskId)
{
    if (!gPaletteFade.active && MenuHelpers_ShouldWaitForLinkRecv() != TRUE)
    {
        s8 input;
        s16 *data = gTasks[taskId].data;

        if (sPartyMenuInternal_party_menu->numActions <= 3)
            input = Menu_ProcessInputNoWrapAround_other();
        else
            input = ProcessMenuInput_other();

        data[0] = Menu_GetCursorPos();
        switch (input)
        {
        case MENU_NOTHING_CHOSEN:
            break;
        case MENU_B_PRESSED:
            PlaySE(SE_SELECT);
            PartyMenuRemoveWindow_party_menu(&sPartyMenuInternal_party_menu->windowId[2]);
            if (sPartyMenuInternal_party_menu->actions[sPartyMenuInternal_party_menu->numActions - 1] >= MENU_FIELD_MOVES_party_menu)
                CursorCb_FieldMove_party_menu(taskId);
            else
                sCursorOptions[sPartyMenuInternal_party_menu->actions[sPartyMenuInternal_party_menu->numActions - 1]].func(taskId);
            break;
        default:
            PartyMenuRemoveWindow_party_menu(&sPartyMenuInternal_party_menu->windowId[2]);
            if (sPartyMenuInternal_party_menu->actions[input] >= MENU_FIELD_MOVES_party_menu)
                CursorCb_FieldMove_party_menu(taskId);
            else
                sCursorOptions[sPartyMenuInternal_party_menu->actions[input]].func(taskId);
            break;
        }
    }
}

static void CursorCb_Summary_party_menu(u8 taskId)
{
    PlaySE(SE_SELECT);
    sPartyMenuInternal_party_menu->exitCallback = CB2_ShowPokemonSummaryScreen_party_menu;
    Task_ClosePartyMenu_party_menu(taskId);
}

static void CB2_ShowPokemonSummaryScreen_party_menu(void)
{
    if (gPartyMenu.menuType == PARTY_MENU_TYPE_IN_BATTLE)
    {
        UpdatePartyToBattleOrder_party_menu();
        ShowPokemonSummaryScreen(SUMMARY_MODE_LOCK_MOVES, gPlayerParty, gPartyMenu.slotId, gPlayerPartyCount - 1, CB2_ReturnToPartyMenuFromSummaryScreen_party_menu);
    }
    else
    {
        ShowPokemonSummaryScreen(SUMMARY_MODE_NORMAL, gPlayerParty, gPartyMenu.slotId, gPlayerPartyCount - 1, CB2_ReturnToPartyMenuFromSummaryScreen_party_menu);
    }
}

static void CB2_ReturnToPartyMenuFromSummaryScreen_party_menu(void)
{
    gPaletteFade.bufferTransferDisabled = TRUE;
    gPartyMenu.slotId = gLastViewedMonIndex;
    InitPartyMenu_party_menu(gPartyMenu.menuType, KEEP_PARTY_LAYOUT, gPartyMenu.action, TRUE, PARTY_MSG_DO_WHAT_WITH_MON, Task_TryCreateSelectionWindow_party_menu, gPartyMenu.exitCallback);
}

static void CursorCb_Switch_party_menu(u8 taskId)
{
    // Reset follower steps when the party leader is changed
    if (gPartyMenu.slotId == 0 || gPartyMenu.slotId2 == 0)
        gFollowerSteps = 0;
    PlaySE(SE_SELECT);
    gPartyMenu.action = PARTY_ACTION_SWITCH;
    PartyMenuRemoveWindow_party_menu(&sPartyMenuInternal_party_menu->windowId[1]);
    PartyMenuRemoveWindow_party_menu(&sPartyMenuInternal_party_menu->windowId[0]);
    DisplayPartyMenuStdMessage(PARTY_MSG_MOVE_TO_WHERE);
    AnimatePartySlot(gPartyMenu.slotId, 1);
    gPartyMenu.slotId2 = gPartyMenu.slotId;
    gTasks[taskId].func = Task_HandleChooseMonInput;
}

#define tSlot1Left_party_menu     data[0]
#define tSlot1Top_party_menu      data[1]
#define tSlot1Width_party_menu    data[2]
#define tSlot1Height_party_menu   data[3]
#define tSlot2Left_party_menu     data[4]
#define tSlot2Top_party_menu      data[5]
#define tSlot2Width_party_menu    data[6]
#define tSlot2Height_party_menu   data[7]
#define tSlot1Offset_party_menu   data[8]
#define tSlot2Offset_party_menu   data[9]
#define tSlot1SlideDir_party_menu data[10]
#define tSlot2SlideDir_party_menu data[11]

static void SwitchSelectedMons_party_menu(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    u8 windowIds[2];

    if (gPartyMenu.slotId2 == gPartyMenu.slotId)
    {
        FinishTwoMonAction_party_menu(taskId);
    }
    else
    {
        // Initialize switching party mons slide animation
        windowIds[0] = sPartyMenuBoxes_party_menu[gPartyMenu.slotId].windowId;
        tSlot1Left_party_menu = GetWindowAttribute(windowIds[0], WINDOW_TILEMAP_LEFT);
        tSlot1Top_party_menu = GetWindowAttribute(windowIds[0], WINDOW_TILEMAP_TOP);
        tSlot1Width_party_menu = GetWindowAttribute(windowIds[0], WINDOW_WIDTH);
        tSlot1Height_party_menu = GetWindowAttribute(windowIds[0], WINDOW_HEIGHT);
        tSlot1Offset_party_menu = 0;
        if (tSlot1Width_party_menu == 10)
            tSlot1SlideDir_party_menu = -1;
        else
            tSlot1SlideDir_party_menu = 1;
        windowIds[1] = sPartyMenuBoxes_party_menu[gPartyMenu.slotId2].windowId;
        tSlot2Left_party_menu = GetWindowAttribute(windowIds[1], WINDOW_TILEMAP_LEFT);
        tSlot2Top_party_menu = GetWindowAttribute(windowIds[1], WINDOW_TILEMAP_TOP);
        tSlot2Width_party_menu = GetWindowAttribute(windowIds[1], WINDOW_WIDTH);
        tSlot2Height_party_menu = GetWindowAttribute(windowIds[1], WINDOW_HEIGHT);
        tSlot2Offset_party_menu = 0;
        if (tSlot2Width_party_menu == 10)
            tSlot2SlideDir_party_menu = -1;
        else
            tSlot2SlideDir_party_menu = 1;
        sSlot1TilemapBuffer_party_menu = Alloc(tSlot1Width_party_menu * (tSlot1Height_party_menu << 1));
        sSlot2TilemapBuffer_party_menu = Alloc(tSlot2Width_party_menu * (tSlot2Height_party_menu << 1));
        CopyToBufferFromBgTilemap(0, sSlot1TilemapBuffer_party_menu, tSlot1Left_party_menu, tSlot1Top_party_menu, tSlot1Width_party_menu, tSlot1Height_party_menu);
        CopyToBufferFromBgTilemap(0, sSlot2TilemapBuffer_party_menu, tSlot2Left_party_menu, tSlot2Top_party_menu, tSlot2Width_party_menu, tSlot2Height_party_menu);
        ClearWindowTilemap(windowIds[0]);
        ClearWindowTilemap(windowIds[1]);
        gPartyMenu.action = PARTY_ACTION_SWITCHING;
        AnimatePartySlot(gPartyMenu.slotId, 1);
        AnimatePartySlot(gPartyMenu.slotId2, 1);
        SlidePartyMenuBoxOneStep_party_menu(taskId);
        gTasks[taskId].func = Task_SlideSelectedSlotsOffscreen_party_menu;
    }
}

// returns FALSE if the slot has slid fully offscreen / back onscreen
static bool8 TryMovePartySlot_party_menu(s16 x, s16 width, u8 *leftMove, u8 *newX, u8 *newWidth)
{
    if (x + width < 0)
        return FALSE;
    if (x >= 32)
        return FALSE;

    if (x < 0)
    {
        *leftMove = x * -1;
        *newX = 0;
        *newWidth = width + x;
    }
    else
    {
        *leftMove = 0;
        *newX = x;
        if (x + width >= 32)
            *newWidth = 32 - x;
        else
            *newWidth = width;

    }
    return TRUE;
}

static void MoveAndBufferPartySlot_party_menu(const void *rectSrc, s16 x, s16 y, s16 width, s16 height, s16 dir)
{
    u8 srcX, newX, newWidth;

    if (TryMovePartySlot_party_menu(x, width, &srcX, &newX, &newWidth))
    {
        FillBgTilemapBufferRect_Palette0(0, 0, newX, y, newWidth, height);
        if (TryMovePartySlot_party_menu(x + dir, width, &srcX, &newX, &newWidth))
            CopyRectToBgTilemapBufferRect(0, rectSrc, srcX, 0, width, height, newX, y, newWidth, height, 17, 0, 0);
    }
}

static void MovePartyMenuBoxSprites_party_menu(struct PartyMenuBox *menuBox, s16 offset)
{
    gSprites[menuBox->pokeballSpriteId].x2 += offset * 8;
    gSprites[menuBox->itemSpriteId].x2 += offset * 8;
    gSprites[menuBox->monSpriteId].x2 += offset * 8;
    gSprites[menuBox->statusSpriteId].x2 += offset * 8;
}

static void SlidePartyMenuBoxSpritesOneStep_party_menu(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    if (tSlot1SlideDir_party_menu != 0)
        MovePartyMenuBoxSprites_party_menu(&sPartyMenuBoxes_party_menu[gPartyMenu.slotId], tSlot1SlideDir_party_menu);
    if (tSlot2SlideDir_party_menu != 0)
        MovePartyMenuBoxSprites_party_menu(&sPartyMenuBoxes_party_menu[gPartyMenu.slotId2], tSlot2SlideDir_party_menu);
}

static void SlidePartyMenuBoxOneStep_party_menu(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    if (tSlot1SlideDir_party_menu != 0)
        MoveAndBufferPartySlot_party_menu(sSlot1TilemapBuffer_party_menu, tSlot1Left_party_menu + tSlot1Offset_party_menu, tSlot1Top_party_menu, tSlot1Width_party_menu, tSlot1Height_party_menu, tSlot1SlideDir_party_menu);
    if (tSlot2SlideDir_party_menu != 0)
        MoveAndBufferPartySlot_party_menu(sSlot2TilemapBuffer_party_menu, tSlot2Left_party_menu + tSlot2Offset_party_menu, tSlot2Top_party_menu, tSlot2Width_party_menu, tSlot2Height_party_menu, tSlot2SlideDir_party_menu);
    ScheduleBgCopyTilemapToVram(0);
}

static void Task_SlideSelectedSlotsOffscreen_party_menu(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    u16 slidingSlotPositions[2];

    SlidePartyMenuBoxOneStep_party_menu(taskId);
    SlidePartyMenuBoxSpritesOneStep_party_menu(taskId);
    tSlot1Offset_party_menu += tSlot1SlideDir_party_menu;
    tSlot2Offset_party_menu += tSlot2SlideDir_party_menu;
    slidingSlotPositions[0] = tSlot1Left_party_menu + tSlot1Offset_party_menu;
    slidingSlotPositions[1] = tSlot2Left_party_menu + tSlot2Offset_party_menu;

    // Both slots have slid offscreen
    if (slidingSlotPositions[0] > 33 && slidingSlotPositions[1] > 33)
    {
        tSlot1SlideDir_party_menu *= -1;
        tSlot2SlideDir_party_menu *= -1;
        SwitchPartyMon_party_menu();
        DisplayPartyPokemonData_party_menu(gPartyMenu.slotId);
        DisplayPartyPokemonData_party_menu(gPartyMenu.slotId2);
        PutWindowTilemap(sPartyMenuBoxes_party_menu[gPartyMenu.slotId].windowId);
        PutWindowTilemap(sPartyMenuBoxes_party_menu[gPartyMenu.slotId2].windowId);
        CopyToBufferFromBgTilemap(0, sSlot1TilemapBuffer_party_menu, tSlot1Left_party_menu, tSlot1Top_party_menu, tSlot1Width_party_menu, tSlot1Height_party_menu);
        CopyToBufferFromBgTilemap(0, sSlot2TilemapBuffer_party_menu, tSlot2Left_party_menu, tSlot2Top_party_menu, tSlot2Width_party_menu, tSlot2Height_party_menu);
        ClearWindowTilemap(sPartyMenuBoxes_party_menu[gPartyMenu.slotId].windowId);
        ClearWindowTilemap(sPartyMenuBoxes_party_menu[gPartyMenu.slotId2].windowId);
        gTasks[taskId].func = Task_SlideSelectedSlotsOnscreen_party_menu;
    }
}

static void Task_SlideSelectedSlotsOnscreen_party_menu(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    SlidePartyMenuBoxOneStep_party_menu(taskId);
    SlidePartyMenuBoxSpritesOneStep_party_menu(taskId);

    // Both slots have slid back onscreen
    if (tSlot1SlideDir_party_menu == 0 && tSlot2SlideDir_party_menu == 0)
    {
        PutWindowTilemap(sPartyMenuBoxes_party_menu[gPartyMenu.slotId].windowId);
        PutWindowTilemap(sPartyMenuBoxes_party_menu[gPartyMenu.slotId2].windowId);
        ScheduleBgCopyTilemapToVram(0);
        Free(sSlot1TilemapBuffer_party_menu);
        Free(sSlot2TilemapBuffer_party_menu);
        FinishTwoMonAction_party_menu(taskId);
    }
    // Continue sliding
    else
    {
        tSlot1Offset_party_menu += tSlot1SlideDir_party_menu;
        tSlot2Offset_party_menu += tSlot2SlideDir_party_menu;
        if (tSlot1Offset_party_menu == 0)
            tSlot1SlideDir_party_menu = 0;
        if (tSlot2Offset_party_menu == 0)
            tSlot2SlideDir_party_menu = 0;
    }
}

static void SwitchMenuBoxSprites_party_menu(u8 *spriteIdPtr1, u8 *spriteIdPtr2)
{
    u8 spriteIdBuffer = *spriteIdPtr1;
    u16 xBuffer1, yBuffer1, xBuffer2, yBuffer2;

    *spriteIdPtr1 = *spriteIdPtr2;
    *spriteIdPtr2 = spriteIdBuffer;
    xBuffer1 = gSprites[*spriteIdPtr1].x;
    yBuffer1 = gSprites[*spriteIdPtr1].y;
    xBuffer2 = gSprites[*spriteIdPtr1].x2;
    yBuffer2 = gSprites[*spriteIdPtr1].y2;
    gSprites[*spriteIdPtr1].x = gSprites[*spriteIdPtr2].x;
    gSprites[*spriteIdPtr1].y = gSprites[*spriteIdPtr2].y;
    gSprites[*spriteIdPtr1].x2 = gSprites[*spriteIdPtr2].x2;
    gSprites[*spriteIdPtr1].y2 = gSprites[*spriteIdPtr2].y2;
    gSprites[*spriteIdPtr2].x = xBuffer1;
    gSprites[*spriteIdPtr2].y = yBuffer1;
    gSprites[*spriteIdPtr2].x2 = xBuffer2;
    gSprites[*spriteIdPtr2].y2 = yBuffer2;
}

static void SwitchPartyMon_party_menu(void)
{
    struct PartyMenuBox *menuBoxes[2];
    struct Pokemon *mon1, *mon2;
    struct Pokemon *monBuffer;

    menuBoxes[0] = &sPartyMenuBoxes_party_menu[gPartyMenu.slotId];
    menuBoxes[1] = &sPartyMenuBoxes_party_menu[gPartyMenu.slotId2];
    mon1 = &gPlayerParty[gPartyMenu.slotId];
    mon2 = &gPlayerParty[gPartyMenu.slotId2];
    monBuffer = Alloc(sizeof(struct Pokemon));
    *monBuffer = *mon1;
    *mon1 = *mon2;
    *mon2 = *monBuffer;
    Free(monBuffer);
    SwitchMenuBoxSprites_party_menu(&menuBoxes[0]->pokeballSpriteId, &menuBoxes[1]->pokeballSpriteId);
    SwitchMenuBoxSprites_party_menu(&menuBoxes[0]->itemSpriteId, &menuBoxes[1]->itemSpriteId);
    SwitchMenuBoxSprites_party_menu(&menuBoxes[0]->monSpriteId, &menuBoxes[1]->monSpriteId);
    SwitchMenuBoxSprites_party_menu(&menuBoxes[0]->statusSpriteId, &menuBoxes[1]->statusSpriteId);
}

// Finish switching mons or using Softboiled
static void FinishTwoMonAction_party_menu(u8 taskId)
{
    PartyMenuRemoveWindow_party_menu(&sPartyMenuInternal_party_menu->windowId[1]);
    gPartyMenu.action = PARTY_ACTION_CHOOSE_MON;
    AnimatePartySlot(gPartyMenu.slotId, 0);
    gPartyMenu.slotId = gPartyMenu.slotId2;
    AnimatePartySlot(gPartyMenu.slotId2, 1);
    DisplayPartyMenuStdMessage(PARTY_MSG_CHOOSE_MON);
    gTasks[taskId].func = Task_HandleChooseMonInput;
}

