#define tSpecies_party_menu    data[1]
#define tAbilityNum_party_menu data[2]
#define tMonId_party_menu      data[3]
#define tOldFunc_party_menu    4

void Task_AbilityCapsule(u8 taskId)
{
static const u8  askText_party_menu[] = _("Would you like to change {STR_VAR_1}'s\nability to {STR_VAR_2}?");
static const u8  doneText_party_menu[] = _("{STR_VAR_1}'s ability became\n{STR_VAR_2}!{PAUSE_UNTIL_PRESS}");
    s16 *data = gTasks[taskId].data;

    switch (tState_party_menu)
    {
    case 0:
        // Can't use.
        if (gSpeciesInfo[tSpecies_party_menu].abilities[0] == gSpeciesInfo[tSpecies_party_menu].abilities[1]
            || gSpeciesInfo[tSpecies_party_menu].abilities[1] == 0
            || tAbilityNum_party_menu > 1
            || !tSpecies_party_menu)
        {
            gPartyMenuUseExitCallback = FALSE;
            PlaySE(SE_SELECT);
            DisplayPartyMenuMessage(gText_WontHaveEffect, 1);
            ScheduleBgCopyTilemapToVram(2);
            gTasks[taskId].func = Task_ClosePartyMenuAfterText_party_menu;
            return;
        }
        gPartyMenuUseExitCallback = TRUE;
        GetMonNickname(&gPlayerParty[tMonId_party_menu], gStringVar1);
        StringCopy(gStringVar2, gAbilitiesInfo[GetAbilityBySpecies(tSpecies_party_menu, tAbilityNum_party_menu)].name);
        StringExpandPlaceholders(gStringVar4, askText_party_menu);
        PlaySE(SE_SELECT);
        DisplayPartyMenuMessage(gStringVar4, 1);
        ScheduleBgCopyTilemapToVram(2);
        tState_party_menu++;
        break;
    case 1:
        if (!IsPartyMenuTextPrinterActive())
        {
            PartyMenuDisplayYesNoMenu_party_menu();
            tState_party_menu++;
        }
        break;
    case 2:
        switch (Menu_ProcessInputNoWrapClearOnChoose())
        {
        case 0:
            tState_party_menu++;
            break;
        case 1:
        case MENU_B_PRESSED:
            gPartyMenuUseExitCallback = FALSE;
            PlaySE(SE_SELECT);
            ScheduleBgCopyTilemapToVram(2);
            // Don't exit party selections screen, return to choosing a mon.
            ClearStdWindowAndFrameToTransparent(6, 0);
            ClearWindowTilemap(6);
            DisplayPartyMenuStdMessage(5);
            gTasks[taskId].func = (void *)GetWordTaskArg(taskId, tOldFunc_party_menu);
            return;
        }
        break;
    case 3:
        PlaySE(SE_USE_ITEM);
        StringExpandPlaceholders(gStringVar4, doneText_party_menu);
        DisplayPartyMenuMessage(gStringVar4, 1);
        ScheduleBgCopyTilemapToVram(2);
        tState_party_menu++;
        break;
    case 4:
        if (!IsPartyMenuTextPrinterActive())
            tState_party_menu++;
        break;
    case 5:
        SetMonData(&gPlayerParty[tMonId_party_menu], MON_DATA_ABILITY_NUM, &tAbilityNum_party_menu);
        RemoveBagItem(gSpecialVar_ItemId, 1);
        gTasks[taskId].func = Task_ClosePartyMenu_party_menu;
        break;
    }
}

void ItemUseCB_AbilityCapsule(u8 taskId, TaskFunc task)
{
    s16 *data = gTasks[taskId].data;

    tState_party_menu = 0;
    tMonId_party_menu = gPartyMenu.slotId;
    tSpecies_party_menu = GetMonData(&gPlayerParty[tMonId_party_menu], MON_DATA_SPECIES, NULL);
    tAbilityNum_party_menu = GetMonData(&gPlayerParty[tMonId_party_menu], MON_DATA_ABILITY_NUM, NULL) ^ 1;
    SetWordTaskArg(taskId, tOldFunc_party_menu, (uintptr_t)(gTasks[taskId].func));
    gTasks[taskId].func = Task_AbilityCapsule;
}

