void Task_Mint(u8 taskId)
{
    static const u8 askText_party_menu[] = _("It might affect {STR_VAR_1}'s stats.\nAre you sure you want to use it?");
    static const u8 doneText_party_menu[] = _("{STR_VAR_1}'s stats may have changed due\nto the effects of the {STR_VAR_2}!{PAUSE_UNTIL_PRESS}");
    s16 *data = gTasks[taskId].data;

    switch (tState_party_menu)
    {
    case 0:
        // Can't use.
        if (tOldNature_party_menu == tNewNature_party_menu)
        {
            gPartyMenuUseExitCallback = FALSE;
            PlaySE(SE_SELECT);
            DisplayPartyMenuMessage(gText_WontHaveEffect, 1);
            ScheduleBgCopyTilemapToVram(2);
            gTasks[taskId].func = Task_ClosePartyMenuAfterText_party_menu;
            return;
        }
        gPartyMenuUseExitCallback = TRUE;
        GetMonNickname(&gPlayerParty[tMonId_party_menu], gStringVar1);
        CopyItemName(gSpecialVar_ItemId, gStringVar2);
        StringExpandPlaceholders(gStringVar4, askText_party_menu);
        PlaySE(SE_SELECT);
        DisplayPartyMenuMessage(gStringVar4, 1);
        ScheduleBgCopyTilemapToVram(2);
        tState_party_menu++;
        break;
    case 1:
        if (!IsPartyMenuTextPrinterActive())
        {
            PartyMenuDisplayYesNoMenu_party_menu();
            tState_party_menu++;
        }
        break;
    case 2:
        switch (Menu_ProcessInputNoWrapClearOnChoose())
        {
        case 0:
            tState_party_menu++;
            break;
        case 1:
        case MENU_B_PRESSED:
            gPartyMenuUseExitCallback = FALSE;
            PlaySE(SE_SELECT);
            ScheduleBgCopyTilemapToVram(2);
            // Don't exit party selections screen, return to choosing a mon.
            ClearStdWindowAndFrameToTransparent(6, 0);
            ClearWindowTilemap(6);
            DisplayPartyMenuStdMessage(5);
            gTasks[taskId].func = (void *)GetWordTaskArg(taskId, tOldFunc_party_menu);
            return;
        }
        break;
    case 3:
        PlaySE(SE_USE_ITEM);
        StringExpandPlaceholders(gStringVar4, doneText_party_menu);
        DisplayPartyMenuMessage(gStringVar4, 1);
        ScheduleBgCopyTilemapToVram(2);
        tState_party_menu++;
        break;
    case 4:
        if (!IsPartyMenuTextPrinterActive())
            tState_party_menu++;
        break;
    case 5:
        SetMonData(&gPlayerParty[tMonId_party_menu], MON_DATA_HIDDEN_NATURE, &tNewNature_party_menu);
        CalculateMonStats(&gPlayerParty[tMonId_party_menu]);
        RemoveBagItem(gSpecialVar_ItemId, 1);
        gTasks[taskId].func = Task_ClosePartyMenu_party_menu;
        break;
    }
}

void ItemUseCB_Mint(u8 taskId, TaskFunc task)
{
    s16 *data = gTasks[taskId].data;

    tState_party_menu = 0;
    tMonId_party_menu = gPartyMenu.slotId;
    tOldNature_party_menu = GetMonData(&gPlayerParty[tMonId_party_menu], MON_DATA_HIDDEN_NATURE);
    tNewNature_party_menu = ItemId_GetSecondaryId(gSpecialVar_ItemId);
    SetWordTaskArg(taskId, tOldFunc_party_menu, (uintptr_t)(gTasks[taskId].func));
    gTasks[taskId].func = Task_Mint;
}

