void ItemUseCB_RareCandy(u8 taskId, TaskFunc task)
{
    struct Pokemon *mon = &gPlayerParty[gPartyMenu.slotId];
    struct PartyMenuInternal *ptr = sPartyMenuInternal_party_menu;
    s16 *arrayPtr = ptr->data;
    u16 *itemPtr = &gSpecialVar_ItemId;
    bool8 cannotUseEffect;
    u8 holdEffectParam = ItemId_GetHoldEffectParam(*itemPtr);

    sInitialLevel_party_menu = GetMonData(mon, MON_DATA_LEVEL);
    if (!(B_RARE_CANDY_CAP && sInitialLevel_party_menu >= GetCurrentLevelCap()))
    {
        BufferMonStatsToTaskData_party_menu(mon, arrayPtr);
        cannotUseEffect = ExecuteTableBasedItemEffect(mon, *itemPtr, gPartyMenu.slotId, 0);
        BufferMonStatsToTaskData_party_menu(mon, &ptr->data[NUM_STATS]);
    }
    else
    {
        cannotUseEffect = TRUE;
    }
    PlaySE(SE_SELECT);
    if (cannotUseEffect)
    {
        u16 targetSpecies = SPECIES_NONE;
        bool32 evoModeNormal = TRUE;

        // Resets values to 0 so other means of teaching moves doesn't overwrite levels
        sInitialLevel_party_menu = 0;
        sFinalLevel_party_menu = 0;

        if (holdEffectParam == 0)
        {
            targetSpecies = GetEvolutionTargetSpecies(mon, EVO_MODE_NORMAL, ITEM_NONE, NULL);
            if (targetSpecies == SPECIES_NONE)
            {
                targetSpecies = GetEvolutionTargetSpecies(mon, EVO_MODE_CANT_STOP, ITEM_NONE, NULL);
                evoModeNormal = FALSE;
            }
        }

        if (targetSpecies != SPECIES_NONE)
        {
            RemoveBagItem(gSpecialVar_ItemId, 1);
            FreePartyPointers_party_menu();
            gCB2_AfterEvolution = gPartyMenu.exitCallback;
            BeginEvolutionScene(mon, targetSpecies, evoModeNormal, gPartyMenu.slotId);
            DestroyTask(taskId);
        }
        else
        {
            gPartyMenuUseExitCallback = FALSE;
            DisplayPartyMenuMessage(gText_WontHaveEffect, TRUE);
            ScheduleBgCopyTilemapToVram(2);
            gTasks[taskId].func = task;
        }
    }
    else
    {
        sFinalLevel_party_menu = GetMonData(mon, MON_DATA_LEVEL, NULL);
        gPartyMenuUseExitCallback = TRUE;
        UpdateMonDisplayInfoAfterRareCandy_party_menu(gPartyMenu.slotId, mon);
        RemoveBagItem(gSpecialVar_ItemId, 1);
        GetMonNickname(mon, gStringVar1);
        if (sFinalLevel_party_menu > sInitialLevel_party_menu)
        {
            PlayFanfareByFanfareNum(FANFARE_LEVEL_UP);
            if (holdEffectParam == 0) // Rare Candy
            {
                ConvertIntToDecimalStringN(gStringVar2, sFinalLevel_party_menu, STR_CONV_MODE_LEFT_ALIGN, 3);
                StringExpandPlaceholders(gStringVar4, gText_PkmnElevatedToLvVar2);
            }
            else // Exp Candies
            {
                ConvertIntToDecimalStringN(gStringVar2, sExpCandyExperienceTable[holdEffectParam - 1], STR_CONV_MODE_LEFT_ALIGN, 6);
                ConvertIntToDecimalStringN(gStringVar3, sFinalLevel_party_menu, STR_CONV_MODE_LEFT_ALIGN, 3);
                StringExpandPlaceholders(gStringVar4, gText_PkmnGainedExpAndElevatedToLvVar3);
            }

            DisplayPartyMenuMessage(gStringVar4, TRUE);
            ScheduleBgCopyTilemapToVram(2);
            gTasks[taskId].func = Task_DisplayLevelUpStatsPg1_party_menu;
        }
        else
        {
            PlaySE(SE_USE_ITEM);
            gPartyMenuUseExitCallback = FALSE;
            ConvertIntToDecimalStringN(gStringVar2, sExpCandyExperienceTable[holdEffectParam - 1], STR_CONV_MODE_LEFT_ALIGN, 6);
            StringExpandPlaceholders(gStringVar4, gText_PkmnGainedExp);
            DisplayPartyMenuMessage(gStringVar4, FALSE);
            ScheduleBgCopyTilemapToVram(2);
            gTasks[taskId].func = task;
        }
    }
}

static void UpdateMonDisplayInfoAfterRareCandy_party_menu(u8 slot, struct Pokemon *mon)
{
    SetPartyMonAilmentGfx_party_menu(mon, &sPartyMenuBoxes_party_menu[slot]);
    if (gSprites[sPartyMenuBoxes_party_menu[slot].statusSpriteId].invisible)
        DisplayPartyPokemonLevelCheck_party_menu(mon, &sPartyMenuBoxes_party_menu[slot], 1);
    DisplayPartyPokemonHPCheck_party_menu(mon, &sPartyMenuBoxes_party_menu[slot], 1);
    DisplayPartyPokemonMaxHPCheck_party_menu(mon, &sPartyMenuBoxes_party_menu[slot], 1);
    DisplayPartyPokemonHPBarCheck_party_menu(mon, &sPartyMenuBoxes_party_menu[slot]);
    UpdatePartyMonHPBar_party_menu(sPartyMenuBoxes_party_menu[slot].monSpriteId, mon);
    AnimatePartySlot(slot, 1);
    ScheduleBgCopyTilemapToVram(0);
}

static void Task_DisplayLevelUpStatsPg1_party_menu(u8 taskId)
{
    if (WaitFanfare(FALSE) && IsPartyMenuTextPrinterActive() != TRUE && ((JOY_NEW(A_BUTTON)) || (JOY_NEW(B_BUTTON))))
    {
        PlaySE(SE_SELECT);
        DisplayLevelUpStatsPg1_party_menu(taskId);
        gTasks[taskId].func = Task_DisplayLevelUpStatsPg2_party_menu;
    }
}

static void Task_DisplayLevelUpStatsPg2_party_menu(u8 taskId)
{
    if ((JOY_NEW(A_BUTTON)) || (JOY_NEW(B_BUTTON)))
    {
        PlaySE(SE_SELECT);
        DisplayLevelUpStatsPg2_party_menu(taskId);
        sInitialLevel_party_menu += 1; // so the Pokemon doesn't learn a move meant for its previous level
        gTasks[taskId].func = Task_TryLearnNewMoves_party_menu;
    }
}

static void DisplayLevelUpStatsPg1_party_menu(u8 taskId)
{
    u16 *arrayPtr = (u16*) sPartyMenuInternal_party_menu->data;

    arrayPtr[12] = CreateLevelUpStatsWindow_party_menu();
    DrawLevelUpWindowPg1(arrayPtr[12], arrayPtr, &arrayPtr[6], TEXT_COLOR_WHITE, TEXT_COLOR_DARK_GRAY, TEXT_COLOR_LIGHT_GRAY);
    CopyWindowToVram(arrayPtr[12], COPYWIN_GFX);
    ScheduleBgCopyTilemapToVram(2);
}

static void DisplayLevelUpStatsPg2_party_menu(u8 taskId)
{
    u16 *arrayPtr = (u16*) sPartyMenuInternal_party_menu->data;

    DrawLevelUpWindowPg2(arrayPtr[12], &arrayPtr[6], TEXT_COLOR_WHITE, TEXT_COLOR_DARK_GRAY, TEXT_COLOR_LIGHT_GRAY);
    CopyWindowToVram(arrayPtr[12], COPYWIN_GFX);
    ScheduleBgCopyTilemapToVram(2);
}

static void Task_TryLearnNewMoves_party_menu(u8 taskId)
{
    u16 learnMove;

    if (WaitFanfare(FALSE) && ((JOY_NEW(A_BUTTON)) || (JOY_NEW(B_BUTTON))))
    {
        RemoveLevelUpStatsWindow_party_menu();
        for (; sInitialLevel_party_menu <= sFinalLevel_party_menu; sInitialLevel_party_menu++)
        {
            SetMonData(&gPlayerParty[gPartyMenu.slotId], MON_DATA_LEVEL, &sInitialLevel_party_menu);
            learnMove = MonTryLearningNewMove(&gPlayerParty[gPartyMenu.slotId], TRUE);
            gPartyMenu.learnMoveState = 1;
            switch (learnMove)
            {
            case 0: // No moves to learn
                if (sInitialLevel_party_menu >= sFinalLevel_party_menu)
                    PartyMenuTryEvolution_party_menu(taskId);
                break;
            case MON_HAS_MAX_MOVES:
                DisplayMonNeedsToReplaceMove_party_menu(taskId);
                break;
            case MON_ALREADY_KNOWS_MOVE:
                gTasks[taskId].func = Task_TryLearningNextMove_party_menu;
                break;
            default:
                DisplayMonLearnedMove_party_menu(taskId, learnMove);
                break;
            }
            if (learnMove)
                break;
        }
    }
}

static void Task_TryLearningNextMove_party_menu(u8 taskId)
{
    u16 result;
    for (; sInitialLevel_party_menu <= sFinalLevel_party_menu; sInitialLevel_party_menu++)
    {
        SetMonData(&gPlayerParty[gPartyMenu.slotId], MON_DATA_LEVEL, &sInitialLevel_party_menu);
        result = MonTryLearningNewMove(&gPlayerParty[gPartyMenu.slotId], FALSE);
        switch (result)
        {
        case 0: // No moves to learn
            if (sInitialLevel_party_menu >= sFinalLevel_party_menu)
                PartyMenuTryEvolution_party_menu(taskId);
            break;
        case MON_HAS_MAX_MOVES:
            DisplayMonNeedsToReplaceMove_party_menu(taskId);
            break;
        case MON_ALREADY_KNOWS_MOVE:
            gTasks[taskId].func = Task_TryLearningNextMove_party_menu;
            return;
        default:
            DisplayMonLearnedMove_party_menu(taskId, result);
            break;
        }
        if (result)
            break;
    }
}

