static void BufferMonStatsToTaskData_party_menu(struct Pokemon *mon, s16 *data)
{
    data[0] = GetMonData(mon, MON_DATA_MAX_HP);
    data[1] = GetMonData(mon, MON_DATA_ATK);
    data[2] = GetMonData(mon, MON_DATA_DEF);
    data[4] = GetMonData(mon, MON_DATA_SPATK);
    data[5] = GetMonData(mon, MON_DATA_SPDEF);
    data[3] = GetMonData(mon, MON_DATA_SPEED);
}

#define tState_party_menu        data[0]
#define tMonId_party_menu        data[1]
#define tDynamaxLevel_party_menu data[2]
#define tOldFunc_party_menu      4

void Task_DynamaxCandy(u8 taskId)
{
    static const u8 doneText_party_menu[] = _("{STR_VAR_1}'s Dynamax Level\nincreased by 1!{PAUSE_UNTIL_PRESS}");
    s16 *data = gTasks[taskId].data;

    switch (tState_party_menu)
    {
    case 0:
        // Can't use.
        if (tDynamaxLevel_party_menu == MAX_DYNAMAX_LEVEL)
        {
            gPartyMenuUseExitCallback = FALSE;
            PlaySE(SE_SELECT);
            DisplayPartyMenuMessage(gText_WontHaveEffect, 1);
            ScheduleBgCopyTilemapToVram(2);
            gTasks[taskId].func = Task_ClosePartyMenuAfterText_party_menu;
            return;
        }
        gPartyMenuUseExitCallback = TRUE;
        GetMonNickname(&gPlayerParty[tMonId_party_menu], gStringVar1);
        CopyItemName(gSpecialVar_ItemId, gStringVar2);
        tState_party_menu++;
        break;
    case 1:
        PlaySE(SE_USE_ITEM);
        StringExpandPlaceholders(gStringVar4, doneText_party_menu);
        DisplayPartyMenuMessage(gStringVar4, 1);
        ScheduleBgCopyTilemapToVram(2);
        tState_party_menu++;
        break;
    case 2:
        if (!IsPartyMenuTextPrinterActive())
            tState_party_menu++;
        break;
    case 3:
        tDynamaxLevel_party_menu++;
        SetMonData(&gPlayerParty[tMonId_party_menu], MON_DATA_DYNAMAX_LEVEL, &tDynamaxLevel_party_menu);
        RemoveBagItem(gSpecialVar_ItemId, 1);
        gTasks[taskId].func = Task_ClosePartyMenu_party_menu;
        break;
    }
}

void ItemUseCB_DynamaxCandy(u8 taskId, TaskFunc task)
{
    s16 *data = gTasks[taskId].data;

    tState_party_menu = 0;
    tMonId_party_menu = gPartyMenu.slotId;
    tDynamaxLevel_party_menu = GetMonData(&gPlayerParty[tMonId_party_menu], MON_DATA_DYNAMAX_LEVEL);
    SetWordTaskArg(taskId, tOldFunc_party_menu, (uintptr_t)(gTasks[taskId].func));
    gTasks[taskId].func = Task_DynamaxCandy;
}

