void ItemUseCB_SacredAsh(u8 taskId, TaskFunc task)
{
    sPartyMenuInternal_party_menu->tUsedOnSlot_party_menu = FALSE;
    sPartyMenuInternal_party_menu->tHadEffect_party_menu = FALSE;
    sPartyMenuInternal_party_menu->tLastSlotUsed_party_menu = gPartyMenu.slotId;
    UseSacredAsh_party_menu(taskId);
}

static void UseSacredAsh_party_menu(u8 taskId)
{
    struct Pokemon *mon = &gPlayerParty[gPartyMenu.slotId];
    u16 hp;

    if (GetMonData(mon, MON_DATA_SPECIES) == SPECIES_NONE)
    {
        gTasks[taskId].func = Task_SacredAshLoop_party_menu;
        return;
    }

    hp = GetMonData(mon, MON_DATA_HP);
    if (ExecuteTableBasedItemEffect(mon, gSpecialVar_ItemId, gPartyMenu.slotId, 0))
    {
        gTasks[taskId].func = Task_SacredAshLoop_party_menu;
        return;
    }

    PlaySE(SE_USE_ITEM);
    SetPartyMonAilmentGfx_party_menu(mon, &sPartyMenuBoxes_party_menu[gPartyMenu.slotId]);
    if (gSprites[sPartyMenuBoxes_party_menu[gPartyMenu.slotId].statusSpriteId].invisible)
        DisplayPartyPokemonLevelCheck_party_menu(mon, &sPartyMenuBoxes_party_menu[gPartyMenu.slotId], 1);
    AnimatePartySlot(sPartyMenuInternal_party_menu->tLastSlotUsed_party_menu, 0);
    AnimatePartySlot(gPartyMenu.slotId, 1);
    PartyMenuModifyHP(taskId, gPartyMenu.slotId, 1, GetMonData(mon, MON_DATA_HP) - hp, Task_SacredAshDisplayHPRestored_party_menu);
    ResetHPTaskData_party_menu(taskId, 0, hp);
    sPartyMenuInternal_party_menu->tUsedOnSlot_party_menu = TRUE;
    sPartyMenuInternal_party_menu->tHadEffect_party_menu = TRUE;
}

static void Task_SacredAshLoop_party_menu(u8 taskId)
{
    if (IsPartyMenuTextPrinterActive() != TRUE)
    {
        if (sPartyMenuInternal_party_menu->tUsedOnSlot_party_menu == TRUE)
        {
            sPartyMenuInternal_party_menu->tUsedOnSlot_party_menu = FALSE;
            sPartyMenuInternal_party_menu->tLastSlotUsed_party_menu = gPartyMenu.slotId;
        }
        if (++(gPartyMenu.slotId) == PARTY_SIZE)
        {
            if (sPartyMenuInternal_party_menu->tHadEffect_party_menu == FALSE)
            {
                gPartyMenuUseExitCallback = FALSE;
                DisplayPartyMenuMessage(gText_WontHaveEffect, TRUE);
                ScheduleBgCopyTilemapToVram(2);
            }
            else
            {
                gPartyMenuUseExitCallback = TRUE;
                RemoveBagItem(gSpecialVar_ItemId, 1);
            }
            gTasks[taskId].func = Task_ClosePartyMenuAfterText_party_menu;
            gPartyMenu.slotId = 0;
        }
        else
        {
            UseSacredAsh_party_menu(taskId);
        }
    }
}

static void Task_SacredAshDisplayHPRestored_party_menu(u8 taskId)
{
    GetMonNickname(&gPlayerParty[gPartyMenu.slotId], gStringVar1);
    StringExpandPlaceholders(gStringVar4, gText_PkmnHPRestoredByVar2);
    DisplayPartyMenuMessage(gStringVar4, FALSE);
    ScheduleBgCopyTilemapToVram(2);
    gTasks[taskId].func = Task_SacredAshLoop_party_menu;
}

