#define secondFusionSlot_party_menu     data[11]
#define unfuseSecondMon_party_menu      data[12]
#define moveToLearn_party_menu          data[13]
#define forgetMove_party_menu           data[14]
#define storageIndex_party_menu         data[15]

static void Task_TryItemUseFusionChange_party_menu(u8 taskId);
static void SpriteCB_FormChangeIconMosaic_party_menu(struct Sprite *sprite);

u8 IsFusionMon(u16 species)
{
    u16 i;
    const struct Fusion *itemFusion = gFusionTablePointers[species];
    if (itemFusion == NULL)
        return FALSE;
    for (i = 0; itemFusion[i].fusionStorageIndex != FUSION_TERMINATOR; i++)
    {
        if (itemFusion[i].fusingIntoMon == species)
            return UNFUSE_MON_party_menu;
        else if (itemFusion[i].targetSpecies1 == species)
            return FUSE_MON_party_menu;
        else if (itemFusion[i].targetSpecies2 == species)
            return SECOND_FUSE_MON_party_menu;
    }
    return FALSE;
}

void FormChangeTeachMove(u8 taskId, u32 move, u32 slot)
{
    struct Pokemon *mon;

    gPartyMenu.data1 = move;
    gPartyMenu.learnMoveState = 0;

    PlaySE(SE_SELECT);
    mon = &gPlayerParty[slot];
    GetMonNickname(mon, gStringVar1);
    StringCopy(gStringVar2, GetMoveName(move));

    if (GiveMoveToMon(mon, move) != MON_HAS_MAX_MOVES)
    {
        gTasks[taskId].func = Task_LearnedMove_party_menu;
    }
    else
    {
        DisplayLearnMoveMessage_party_menu(gText_PkmnNeedsToReplaceMove);
        gTasks[taskId].func = Task_ReplaceMoveYesNo_party_menu;
    }
}

void DeleteMove(struct Pokemon *mon, u32 move)
{
    struct BoxPokemon *boxMon = &mon->box;
    u32 i, j;

    if (move != MOVE_NONE)
    {
        for (i = 0; i < MAX_MON_MOVES; i++)
        {
            u32 existingMove = GetBoxMonData(boxMon, MON_DATA_MOVE1 + i, NULL);
            if (existingMove == move)
            {
                SetMonMoveSlot(mon, MOVE_NONE, i);
                RemoveMonPPBonus(mon, i);
                for (j = i; j < MAX_MON_MOVES - 1; j++)
                    ShiftMoveSlot_party_menu(mon, j, j + 1);
                break;
            }
        }
    }
}

bool32 DoesMonHaveAnyMoves(struct Pokemon *mon)
{
    struct BoxPokemon *boxMon = &mon->box;
    u32 i;

    for (i = 0; i < MAX_MON_MOVES; i++)
    {
        u32 existingMove = GetBoxMonData(boxMon, MON_DATA_MOVE1 + i, NULL);
        if (existingMove != MOVE_NONE)
            return TRUE;
    }
    return FALSE;
}

bool32 TryItemUseFusionChange(u8 taskId, TaskFunc task)
{
    u16 targetSpecies = gTasks[taskId].fusionResult_party_menu;
    s8 *slotPtr = GetCurrentPartySlotPtr();
    *slotPtr = gTasks[taskId].firstFusionSlot_party_menu;
    if (gTasks[taskId].fusionType_party_menu == FUSE_MON_party_menu)
        AnimatePartySlot(gTasks[taskId].secondFusionSlot_party_menu, 0);
    AnimatePartySlot(*slotPtr, 1);

    if (targetSpecies != SPECIES_NONE)
    {
        gPartyMenuUseExitCallback = TRUE;
        SetWordTaskArg(taskId, tNextFunc_party_menu, (u32)task);
        gTasks[taskId].func = Task_TryItemUseFusionChange_party_menu;
        gTasks[taskId].tState_party_menu = 0;
        gTasks[taskId].tTargetSpecies_party_menu = targetSpecies;
        gTasks[taskId].tAnimWait_party_menu = 0;
        return TRUE;
    }
    else
    {
        gPartyMenuUseExitCallback = FALSE;
        PlaySE(SE_SELECT);
        DisplayPartyMenuMessage(gText_WontHaveEffect, TRUE);
        ScheduleBgCopyTilemapToVram(2);
        gTasks[taskId].func = task;
        return FALSE;
    }
}

static void Task_TryItemUseFusionChange_party_menu(u8 taskId)
{
    struct Pokemon *mon = &gPlayerParty[gTasks[taskId].firstFusionSlot_party_menu];
    struct Sprite *icon = &gSprites[sPartyMenuBoxes_party_menu[gTasks[taskId].firstFusionSlot_party_menu].monSpriteId];
    struct Pokemon *mon2;
    struct Sprite *icon2 = &gSprites[sPartyMenuBoxes_party_menu[gTasks[taskId].secondFusionSlot_party_menu].monSpriteId];
    u16 targetSpecies;

    switch (gTasks[taskId].tState_party_menu)
    {
    case 0:
        if (gTasks[taskId].fusionType_party_menu == FUSE_MON_party_menu)
        {
            mon2 = &gPlayerParty[gTasks[taskId].secondFusionSlot_party_menu];
            CopyMon(&gPokemonStoragePtr->fusions[gTasks[taskId].storageIndex_party_menu], mon2, sizeof(*mon2));
            ZeroMonData(&gPlayerParty[gTasks[taskId].secondFusionSlot_party_menu]);
        }
        else
        {
            mon2 = &gPokemonStoragePtr->fusions[gTasks[taskId].storageIndex_party_menu];
            GiveMonToPlayer(mon2);
            ZeroMonData(&gPokemonStoragePtr->fusions[gTasks[taskId].storageIndex_party_menu]);
        }
        targetSpecies = gTasks[taskId].tTargetSpecies_party_menu;
        SetMonData(mon, MON_DATA_SPECIES, &targetSpecies);
        CalculateMonStats(mon);
        CompactPartySlots();
        CalculatePlayerPartyCount();
        gTasks[taskId].tState_party_menu++;
        PlaySE(SE_M_TELEPORT);
        break;
    case 1:
        targetSpecies = gTasks[taskId].tTargetSpecies_party_menu;
        if (gTasks[taskId].tAnimWait_party_menu == 0)
        {
            icon->oam.mosaic = TRUE;
            icon->data[0] = 10;
            icon->data[1] = 1;
            icon->data[2] = taskId;
            icon->callback = SpriteCB_FormChangeIconMosaic_party_menu;
            SetGpuReg(REG_OFFSET_MOSAIC, (icon->data[0] << 12) | (icon->data[1] << 8));
            if (gTasks[taskId].fusionType_party_menu == FUSE_MON_party_menu)
            {
                icon2->oam.mosaic = TRUE;
                icon2->data[0] = 10;
                icon2->data[1] = 1;
                icon2->data[2] = taskId;
                icon2->callback = SpriteCB_FormChangeIconMosaic_party_menu;
                SetGpuReg(REG_OFFSET_MOSAIC, (icon2->data[0] << 12) | (icon2->data[1] << 8));
            }
        }

        if (++gTasks[taskId].tAnimWait_party_menu == 60)
        {
            BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_WHITEALPHA);
            gTasks[taskId].tState_party_menu++;
        }
        break;
    case 2:
        if (gPaletteFade.active)
            break;
        if (gTasks[taskId].fusionType_party_menu == FUSE_MON_party_menu && gTasks[taskId].firstFusionSlot_party_menu > gTasks[taskId].secondFusionSlot_party_menu)
        {
            gTasks[taskId].firstFusionSlot_party_menu--;
            gPartyMenu.slotId--;
        }
        RefreshPartyMenu();
        gTasks[taskId].tState_party_menu++;
        break;
    case 3:
        BeginNormalPaletteFade(PALETTES_ALL, 16, 0, 0, RGB_WHITEALPHA);
        gTasks[taskId].tState_party_menu++;
        break;
    case 4:
        targetSpecies = gTasks[taskId].tTargetSpecies_party_menu;
        PlayCry_Normal(targetSpecies, 0);
        gTasks[taskId].tState_party_menu++;
        break;
    case 5:
        if (IsCryFinished())
        {
            GetMonNickname(mon, gStringVar1);
            StringExpandPlaceholders(gStringVar4, gText_PkmnTransformed);
            DisplayPartyMenuMessage(gStringVar4, FALSE);
            ScheduleBgCopyTilemapToVram(2);
            gTasks[taskId].tState_party_menu++;
        }
        break;
    case 6:
        if (!IsPartyMenuTextPrinterActive())
        {
            if (gTasks[taskId].moveToLearn_party_menu != 0)
            {
                if (gTasks[taskId].fusionType_party_menu == FUSE_MON_party_menu)
                    FormChangeTeachMove(taskId, gTasks[taskId].moveToLearn_party_menu, gTasks[taskId].firstFusionSlot_party_menu);
                else
                {
                    DeleteMove(mon, gTasks[taskId].forgetMove_party_menu);
                    if (!DoesMonHaveAnyMoves(mon))
                        FormChangeTeachMove(taskId, gTasks[taskId].moveToLearn_party_menu, gTasks[taskId].firstFusionSlot_party_menu);
                }
            }
            gTasks[taskId].tState_party_menu++;
        }
        break;
    case 7:
        gTasks[taskId].func = (void *)GetWordTaskArg(taskId, tNextFunc_party_menu);
        break;
    }
}

void ItemUseCB_Fusion(u8 taskId, TaskFunc taskFunc)
{
    u16 i;
    struct Task *task = &gTasks[taskId];
    u16 species = GetMonData(&gPlayerParty[gPartyMenu.slotId], MON_DATA_SPECIES);
    const struct Fusion *itemFusion = gFusionTablePointers[species];

    PlaySE(SE_SELECT);
    switch (IsFusionMon(species))
    {
        case FALSE: // Cancel if Not a Fuse Mon
            break;
        case UNFUSE_MON_party_menu:
            if (task->fusionType_party_menu == FUSE_MON_party_menu) // Cancel if An already Fused Mon Is Chosen For The Second Fusion Mon
                break;
            if (gPlayerPartyCount == PARTY_SIZE)
            {
                gPartyMenuUseExitCallback = FALSE;
                DisplayPartyMenuMessage(gText_YourPartysFull, TRUE);
                ScheduleBgCopyTilemapToVram(2);
                task->func = taskFunc;
                return;
            }
            for (i = 0; itemFusion[i].fusionStorageIndex != FUSION_TERMINATOR; i++) // Loops through fusion table and checks if the mon can be unfused
            {
                if (gPokemonStoragePtr->fusions[itemFusion[i].fusionStorageIndex].level == 0)
                    continue;
                if (itemFusion[i].itemId == gSpecialVar_ItemId && GetMonData(&gPokemonStoragePtr->fusions[itemFusion[i].fusionStorageIndex], MON_DATA_SPECIES) == itemFusion[i].targetSpecies2)
                {
                    task->fusionType_party_menu = UNFUSE_MON_party_menu;
                    task->firstFusion_party_menu = species;
                    task->firstFusionSlot_party_menu = gPartyMenu.slotId;
                    task->storageIndex_party_menu = itemFusion[i].fusionStorageIndex;
                    task->fusionResult_party_menu = itemFusion[i].targetSpecies1;
                    task->unfuseSecondMon_party_menu = itemFusion[i].targetSpecies2;
                    task->moveToLearn_party_menu = itemFusion[i].unfuseForgetMove;
                    task->forgetMove_party_menu = itemFusion[i].fusionMove;
                    TryItemUseFusionChange(taskId, taskFunc);
                    return;
                }
            }
            break;
        case FUSE_MON_party_menu:
            if (task->fusionType_party_menu == FUSE_MON_party_menu) // Cancel If Second Mon is Another First Fusion Mon
                break;
            for (i = 0; itemFusion[i].fusionStorageIndex != FUSION_TERMINATOR; i++) // Run through the Fusion table for each species and check if the item matches one of the entries
            {
                if (itemFusion[i].itemId == gSpecialVar_ItemId)
                {
                    task->fusionType_party_menu = FUSE_MON_party_menu;
                    task->firstFusion_party_menu = species;
                    task->firstFusionSlot_party_menu = gPartyMenu.slotId;
                    task->storageIndex_party_menu = itemFusion[i].fusionStorageIndex;
                    task->func = Task_HandleChooseMonInput;
                    gPartyMenuUseExitCallback = FALSE;
                    sPartyMenuInternal_party_menu->exitCallback = NULL;
                    PartyMenuRemoveWindow_party_menu(&sPartyMenuInternal_party_menu->windowId[0]);
                    DisplayPartyMenuStdMessage(PARTY_MSG_CHOOSE_SECOND_FUSION);
                    return;
                }
            }
            break;
        case SECOND_FUSE_MON_party_menu:
            if (task->fusionType_party_menu != FUSE_MON_party_menu) // Cancel if Secondary Fusion Mon Chosen First
                break;
            for (i = 0; itemFusion[i].fusionStorageIndex != FUSION_TERMINATOR; i++) // run through fusion table and check if the fusion works
            {
                if (gPokemonStoragePtr->fusions[itemFusion[i].fusionStorageIndex].level != 0)
                    continue;
                if (itemFusion[i].itemId == gSpecialVar_ItemId && itemFusion[i].targetSpecies1 == task->firstFusion_party_menu && itemFusion[i].targetSpecies2 == species)
                {
                    task->storageIndex_party_menu = itemFusion[i].fusionStorageIndex;
                    task->fusionResult_party_menu = itemFusion[i].fusingIntoMon;
                    task->secondFusionSlot_party_menu = gPartyMenu.slotId;
                    task->moveToLearn_party_menu = itemFusion[i].fusionMove;
                    // Start Fusion
                    TryItemUseFusionChange(taskId, taskFunc);
                    return;
                }
            }
            break;
    }
    // No Effect Exit
    gPartyMenuUseExitCallback = FALSE;
    DisplayPartyMenuMessage(gText_WontHaveEffect, TRUE);
    ScheduleBgCopyTilemapToVram(2);
    task->func = taskFunc;
    return;
}

#undef FUSE_MON_party_menu
#undef UNFUSE_MON_party_menu
#undef SECOND_FUSE_MON_party_menu

#undef fusionType_party_menu
#undef firstFusion_party_menu
#undef firstFusionSlot_party_menu
#undef fusionResult_party_menu
#undef secondFusionSlot_party_menu
#undef unfuseSecondMon_party_menu
#undef moveToLearn_party_menu
#undef forgetMove_party_menu
#undef storageIndex_party_menu

static void SpriteCB_FormChangeIconMosaic_party_menu(struct Sprite *sprite)
{
    u8 taskId = sprite->data[2];

    sprite->data[0] -= sprite->data[1];

    if (sprite->data[0] <= 0)
    {
        if (gTasks[taskId].tAnimWait_party_menu == 60)
            sprite->data[0] = 0;
        else
            sprite->data[0] = 10;
    }

    SetGpuReg(REG_OFFSET_MOSAIC, (sprite->data[0] << 12) | (sprite->data[1] << 8));

    if (sprite->data[0] == 0)
    {
        sprite->oam.mosaic = FALSE;
        sprite->callback = SpriteCallbackDummy;
    }
}

static void Task_TryItemUseFormChange_party_menu(u8 taskId)
{
    struct Pokemon *mon = &gPlayerParty[gPartyMenu.slotId];
    u16 targetSpecies;
    struct Sprite *icon = &gSprites[sPartyMenuBoxes_party_menu[gPartyMenu.slotId].monSpriteId];

    switch (gTasks[taskId].tState_party_menu)
    {
    case 0:
        targetSpecies = gTasks[taskId].tTargetSpecies_party_menu;
        SetMonData(mon, MON_DATA_SPECIES, &targetSpecies);
        TrySetDayLimitToFormChange(mon);
        CalculateMonStats(mon);
        gTasks[taskId].tState_party_menu++;
        break;
    case 1:
        gTasks[taskId].tState_party_menu++;
        break;
    case 2:
        PlaySE(SE_M_TELEPORT);
        gTasks[taskId].tState_party_menu++;
        break;
    case 3:
        targetSpecies = gTasks[taskId].tTargetSpecies_party_menu;

        if (gTasks[taskId].tAnimWait_party_menu == 0)
        {
            FreeAndDestroyMonIconSprite(icon);
            CreatePartyMonIconSpriteParameterized_party_menu(targetSpecies, GetMonData(mon, MON_DATA_PERSONALITY, NULL), &sPartyMenuBoxes_party_menu[gPartyMenu.slotId], 1);
            icon->oam.mosaic = TRUE;
            icon->data[0] = 10;
            icon->data[1] = 1;
            icon->data[2] = taskId;
            icon->callback = SpriteCB_FormChangeIconMosaic_party_menu;
            SetGpuReg(REG_OFFSET_MOSAIC, (icon->data[0] << 12) | (icon->data[1] << 8));
        }

        if (++gTasks[taskId].tAnimWait_party_menu == 60)
            gTasks[taskId].tState_party_menu++;

        break;
    case 4:
        targetSpecies = gTasks[taskId].tTargetSpecies_party_menu;
        PlayCry_Normal(targetSpecies, 0);
        gTasks[taskId].tState_party_menu++;
        break;
    case 5:
        if (IsCryFinished())
        {
            GetMonNickname(mon, gStringVar1);
            StringExpandPlaceholders(gStringVar4, gText_PkmnTransformed);
            DisplayPartyMenuMessage(gStringVar4, FALSE);
            ScheduleBgCopyTilemapToVram(2);
            gTasks[taskId].tState_party_menu++;
        }

        break;
    case 6:
        if (!IsPartyMenuTextPrinterActive())
        {
            if (gSpecialVar_ItemId == ITEM_ROTOM_CATALOG) //only for Rotom currently
            {
                u32 i;
                for (i = 0; i < ARRAY_COUNT(sRotomFormChangeMoves); i++)
                    DeleteMove(mon, sRotomFormChangeMoves[i]);

                if (I_ROTOM_CATALOG_THUNDER_SHOCK < GEN_9 && gSpecialVar_0x8000 == ROTOM_BASE_MOVE)
                {
                    if (!DoesMonHaveAnyMoves(mon))
                        FormChangeTeachMove(taskId, gSpecialVar_0x8000, gPartyMenu.slotId);
                }
                else
                    FormChangeTeachMove(taskId, gSpecialVar_0x8000, gPartyMenu.slotId);
            }

            gTasks[taskId].tState_party_menu++;
        }
        break;
    case 7:
        gTasks[taskId].func = (void *)GetWordTaskArg(taskId, tNextFunc_party_menu);
        break;
    }
}

