static void Task_InitMultiPartnerPartySlideIn_party_menu(u8 taskId)
{
    // The first slide step also sets the sprites offscreen
    gTasks[taskId].tXPos_party_menu = 256;
    SlideMultiPartyMenuBoxSpritesOneStep_party_menu(taskId);
    ChangeBgX(2, 0x10000, BG_COORD_SET);
    gTasks[taskId].func = Task_MultiPartnerPartySlideIn_party_menu;
}

static void Task_MultiPartnerPartySlideIn_party_menu(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    u8 i;

    if (!gPaletteFade.active)
    {
        tXPos_party_menu -= 8;
        SlideMultiPartyMenuBoxSpritesOneStep_party_menu(taskId);
        if (tXPos_party_menu == 0)
        {
            for (i = MULTI_PARTY_SIZE; i < PARTY_SIZE; i++)
            {
                if (gMultiPartnerParty[i - MULTI_PARTY_SIZE].species != SPECIES_NONE)
                    AnimateSelectedPartyIcon_party_menu(sPartyMenuBoxes_party_menu[i].monSpriteId, 0);
            }
            PlaySE(SE_M_HARDEN); // The Harden SE plays once the partners party mons have slid on screen
            gTasks[taskId].func = Task_WaitAfterMultiPartnerPartySlideIn_party_menu;
        }
    }
}

static void Task_WaitAfterMultiPartnerPartySlideIn_party_menu(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    // data[0] used as a timer afterwards rather than the x pos
    if (++data[0] == 256)
        Task_ClosePartyMenu_party_menu(taskId);
}

static void MoveMultiPartyMenuBoxSprite_party_menu(u8 spriteId, s16 x)
{
    if (x >= 0)
        gSprites[spriteId].x2 = x;
}

static void SlideMultiPartyMenuBoxSpritesOneStep_party_menu(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    u8 i;

    for (i = MULTI_PARTY_SIZE; i < PARTY_SIZE; i++)
    {
        if (gMultiPartnerParty[i - MULTI_PARTY_SIZE].species != SPECIES_NONE)
        {
            MoveMultiPartyMenuBoxSprite_party_menu(sPartyMenuBoxes_party_menu[i].monSpriteId, tXPos_party_menu - 8);
            MoveMultiPartyMenuBoxSprite_party_menu(sPartyMenuBoxes_party_menu[i].itemSpriteId, tXPos_party_menu - 8);
            MoveMultiPartyMenuBoxSprite_party_menu(sPartyMenuBoxes_party_menu[i].pokeballSpriteId, tXPos_party_menu - 8);
            MoveMultiPartyMenuBoxSprite_party_menu(sPartyMenuBoxes_party_menu[i].statusSpriteId, tXPos_party_menu - 8);
        }
    }
    ChangeBgX(2, 0x800, BG_COORD_ADD);
}

