void NewGameInitPCItems(void)
{
    u8 i = 0;
    ClearItemSlots(gSaveBlock1Ptr->pcItems, PC_ITEMS_COUNT);

    while (TRUE)
    {
        if (sNewGamePCItems_player_pc[i][0] == ITEM_NONE || sNewGamePCItems_player_pc[i][1] == 0)
            break;
        if (AddPCItem(sNewGamePCItems_player_pc[i][0], sNewGamePCItems_player_pc[i][1]) != TRUE)
            break;
        i++;
    }
}

void BedroomPC(void)
{
    sTopMenuOptionOrder_player_pc = sBedroomPC_OptionOrder_player_pc;
    sTopMenuNumOptions_player_pc = NUM_BEDROOM_PC_OPTIONS_player_pc;
    DisplayItemMessageOnField(CreateTask(TaskDummy, 0), gText_WhatWouldYouLike, InitPlayerPCMenu_player_pc);
}

void PlayerPC(void)
{
    sTopMenuOptionOrder_player_pc = sPlayerPC_OptionOrder_player_pc;
    sTopMenuNumOptions_player_pc = NUM_PLAYER_PC_OPTIONS_player_pc;
    DisplayItemMessageOnField(CreateTask(TaskDummy, 0), gText_WhatWouldYouLike, InitPlayerPCMenu_player_pc);
}

