static void InitPlayerPCMenu_player_pc(u8 taskId)
{
    s16 *data;
    struct WindowTemplate windowTemplate;
    data = gTasks[taskId].data;

    if (sTopMenuNumOptions_player_pc == NUM_PLAYER_PC_OPTIONS_player_pc)
        windowTemplate = sWindowTemplates_MainMenus_player_pc[WIN_MAIN_MENU_player_pc];
    else // Bedroom PC
        windowTemplate = sWindowTemplates_MainMenus_player_pc[WIN_MAIN_MENU_BEDROOM_player_pc];

    windowTemplate.width = GetMaxWidthInSubsetOfMenuTable(sPlayerPCMenuActions_player_pc, sTopMenuOptionOrder_player_pc, sTopMenuNumOptions_player_pc);
    tWindowId_player_pc = AddWindow(&windowTemplate);
    SetStandardWindowBorderStyle(tWindowId_player_pc, FALSE);
    PrintMenuActionTextsInUpperLeftCorner(tWindowId_player_pc, sTopMenuNumOptions_player_pc, sPlayerPCMenuActions_player_pc, sTopMenuOptionOrder_player_pc);
    InitMenuInUpperLeftCornerNormal(tWindowId_player_pc, sTopMenuNumOptions_player_pc, 0);
    ScheduleBgCopyTilemapToVram(0);
    gTasks[taskId].func = PlayerPCProcessMenuInput_player_pc;
}

static void PlayerPCProcessMenuInput_player_pc(u8 taskId)
{
    s16 *data;
    s8 inputOptionId;

    data = gTasks[taskId].data;
    if (sTopMenuNumOptions_player_pc > 3)
        inputOptionId = Menu_ProcessInput();
    else
        inputOptionId = Menu_ProcessInputNoWrap();

    switch (inputOptionId)
    {
    case MENU_NOTHING_CHOSEN:
        break;
    case MENU_B_PRESSED:
        PlaySE(SE_SELECT);
        ClearStdWindowAndFrameToTransparent(tWindowId_player_pc, FALSE);
        ClearWindowTilemap(tWindowId_player_pc);
        RemoveWindow(tWindowId_player_pc);
        ScheduleBgCopyTilemapToVram(0);
        gTasks[taskId].func = PlayerPC_TurnOff_player_pc;
        break;
    default:
        ClearStdWindowAndFrameToTransparent(tWindowId_player_pc, FALSE);
        ClearWindowTilemap(tWindowId_player_pc);
        RemoveWindow(tWindowId_player_pc);
        ScheduleBgCopyTilemapToVram(0);
        gTasks[taskId].func = sPlayerPCMenuActions_player_pc[sTopMenuOptionOrder_player_pc[inputOptionId]].func.void_u8;
        break;
    }
}

void ReshowPlayerPC(u8 var)
{
    DisplayItemMessageOnField(var, gText_WhatWouldYouLike, InitPlayerPCMenu_player_pc);
}

static void PlayerPC_ItemStorage_player_pc(u8 taskId)
{
    InitItemStorageMenu_player_pc(taskId, MENU_WITHDRAW_player_pc);
    gTasks[taskId].func = ItemStorageMenuProcessInput_player_pc;
}

static void PlayerPC_Mailbox_player_pc(u8 taskId)
{
    gPlayerPCItemPageInfo.count = GetMailboxMailCount_player_pc();

    if (gPlayerPCItemPageInfo.count == 0)
    {
        // Mailbox cannot be opened if no mail is in PC
        DisplayItemMessageOnField(taskId, gText_NoMailHere, ReshowPlayerPC);
    }
    else
    {
        gPlayerPCItemPageInfo.cursorPos = 0;
        gPlayerPCItemPageInfo.itemsAbove = 0;
        gPlayerPCItemPageInfo.scrollIndicatorTaskId = TASK_NONE;
        Mailbox_CompactMailList_player_pc();
        SetPlayerPCListCount_player_pc(taskId);
        if (MailboxMenu_Alloc(gPlayerPCItemPageInfo.count) == TRUE)
        {
            ClearDialogWindowAndFrame(0, FALSE);
            Mailbox_DrawMailboxMenu_player_pc(taskId);
            gTasks[taskId].func = Mailbox_ProcessInput_player_pc;
        }
        else
        {
            // Alloc failed, exit Mailbox
            DisplayItemMessageOnField(taskId, gText_NoMailHere, ReshowPlayerPC);
        }
    }
}

static void PlayerPC_Decoration_player_pc(u8 taskId)
{
    DoPlayerRoomDecorationMenu(taskId);
}

static void PlayerPC_TurnOff_player_pc(u8 taskId)
{
    if (sTopMenuNumOptions_player_pc == NUM_BEDROOM_PC_OPTIONS_player_pc) // Flimsy way to determine if Bedroom PC is in use
    {
        if (gSaveBlock2Ptr->playerGender == MALE)
            ScriptContext_SetupScript(LittlerootTown_BrendansHouse_2F_EventScript_TurnOffPlayerPC);
        else
            ScriptContext_SetupScript(LittlerootTown_MaysHouse_2F_EventScript_TurnOffPlayerPC);
    }
    else
    {
        ScriptContext_Enable();
    }
    DestroyTask(taskId);
}

static void InitItemStorageMenu_player_pc(u8 taskId, u8 var)
{
    s16 *data;
    struct WindowTemplate windowTemplate;

    data = gTasks[taskId].data;
    windowTemplate = sWindowTemplates_MainMenus_player_pc[WIN_ITEM_STORAGE_MENU_player_pc];
    windowTemplate.width = GetMaxWidthInMenuTable(sItemStorage_MenuActions_player_pc, ARRAY_COUNT(sItemStorage_MenuActions_player_pc));
    tWindowId_player_pc = AddWindow(&windowTemplate);
    SetStandardWindowBorderStyle(tWindowId_player_pc, FALSE);
    PrintMenuTable(tWindowId_player_pc, ARRAY_COUNT(sItemStorage_MenuActions_player_pc), sItemStorage_MenuActions_player_pc);
    InitMenuInUpperLeftCornerNormal(tWindowId_player_pc, ARRAY_COUNT(sItemStorage_MenuActions_player_pc), var);
    ScheduleBgCopyTilemapToVram(0);
    ItemStorageMenuPrint_player_pc(sItemStorage_OptionDescriptions_player_pc[var]);
}

static void ItemStorageMenuPrint_player_pc(const u8 *textPtr)
{
    DrawDialogueFrame(0, FALSE);
    AddTextPrinterParameterized(0, FONT_NORMAL, textPtr, 0, 1, 0, 0);
}

static void ItemStorageMenuProcessInput_player_pc(u8 taskId)
{
    s8 oldPos, newPos;
    s8 inputOptionId;

    oldPos = Menu_GetCursorPos();
    inputOptionId = Menu_ProcessInput();
    newPos = Menu_GetCursorPos();
    switch (inputOptionId)
    {
    case MENU_NOTHING_CHOSEN:
        if (oldPos != newPos)
            ItemStorageMenuPrint_player_pc(sItemStorage_OptionDescriptions_player_pc[newPos]);
        break;
    case MENU_B_PRESSED:
        PlaySE(SE_SELECT);
        ItemStorage_Exit_player_pc(taskId);
        break;
    default:
        PlaySE(SE_SELECT);
        sItemStorage_MenuActions_player_pc[inputOptionId].func.void_u8(taskId);
        break;
    }
}

static void ItemStorage_Deposit_player_pc(u8 taskId)
{
    gTasks[taskId].func = Task_ItemStorage_Deposit_player_pc;
    FadeScreen(FADE_TO_BLACK, 0);
}

static void Task_ItemStorage_Deposit_player_pc(u8 taskId)
{
    if (!gPaletteFade.active)
    {
        CleanupOverworldWindowsAndTilemaps();
        CB2_GoToItemDepositMenu();
        DestroyTask(taskId);
    }
}

void CB2_PlayerPCExitBagMenu(void)
{
    gFieldCallback = ItemStorage_ReshowAfterBagMenu_player_pc;
    SetMainCallback2(CB2_ReturnToField);
}

static void ItemStorage_ReshowAfterBagMenu_player_pc(void)
{
    LoadMessageBoxAndBorderGfx();
    DrawDialogueFrame(0, TRUE);
    InitItemStorageMenu_player_pc(CreateTask(ItemStorage_HandleReturnToProcessInput_player_pc, 0), 1);
    FadeInFromBlack();
}

static void ItemStorage_HandleReturnToProcessInput_player_pc(u8 taskId)
{
    if (IsWeatherNotFadingIn() == TRUE)
        gTasks[taskId].func = ItemStorageMenuProcessInput_player_pc;
}

static void ItemStorage_Withdraw_player_pc(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    tUsedSlots_player_pc = CountUsedPCItemSlots();
    if (tUsedSlots_player_pc != 0)
    {
        ItemStorage_Enter_player_pc(taskId, FALSE);
    }
    else
    {
        // Can't withdraw, no items in PC
        ItemStorage_EraseMainMenu_player_pc(taskId);
        DisplayItemMessageOnField(taskId, gText_NoItems, PlayerPC_ItemStorage_player_pc);
    }

}

static void ItemStorage_Toss_player_pc(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    tUsedSlots_player_pc = CountUsedPCItemSlots();
    if (tUsedSlots_player_pc != 0)
    {
        ItemStorage_Enter_player_pc(taskId, TRUE);
    }
    else
    {
        // Can't toss, no items in PC
        ItemStorage_EraseMainMenu_player_pc(taskId);
        DisplayItemMessageOnField(taskId, gText_NoItems, PlayerPC_ItemStorage_player_pc);
    }
}

static void ItemStorage_Enter_player_pc(u8 taskId, bool8 toss)
{
    s16 *data = gTasks[taskId].data;

    tInTossMenu_player_pc = toss;
    ItemStorage_EraseMainMenu_player_pc(taskId);
    gPlayerPCItemPageInfo.cursorPos = 0;
    gPlayerPCItemPageInfo.itemsAbove = 0;
    gPlayerPCItemPageInfo.scrollIndicatorTaskId = TASK_NONE;
    SetPlayerPCListCount_player_pc(taskId);
    ItemStorage_Init_player_pc();
    FreeAndReserveObjectSpritePalettes();
    LoadListMenuSwapLineGfx();
    CreateSwapLineSprites(sItemStorageMenu_player_pc->swapLineSpriteIds, SWAP_LINE_LENGTH_player_pc);
    ClearDialogWindowAndFrame(0, FALSE);
    gTasks[taskId].func = ItemStorage_CreateListMenu_player_pc;
}

static void ItemStorage_Exit_player_pc(u8 taskId)
{
    ItemStorage_EraseMainMenu_player_pc(taskId);
    ReshowPlayerPC(taskId);
}

// Used by Item Storage and the Mailbox
static void SetPlayerPCListCount_player_pc(u8 taskId)
{
    if (gPlayerPCItemPageInfo.count > 7)
        gPlayerPCItemPageInfo.pageItems = 8;
    else
        gPlayerPCItemPageInfo.pageItems = gPlayerPCItemPageInfo.count + 1;
}

static void ItemStorage_EraseMainMenu_player_pc(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    ClearStdWindowAndFrameToTransparent(tWindowId_player_pc, FALSE);
    ClearWindowTilemap(tWindowId_player_pc);
    RemoveWindow(tWindowId_player_pc);
    ScheduleBgCopyTilemapToVram(0);
}

static u8 GetMailboxMailCount_player_pc(void)
{
    u8 mailInPC, i;

    // Count mail in PC (by first skipping over mail in party)
    for (mailInPC = 0, i = PARTY_SIZE; i < MAIL_COUNT; i++)
        if (gSaveBlock1Ptr->mail[i].itemId != ITEM_NONE)
            mailInPC++;

    return mailInPC;
}

static void Mailbox_CompactMailList_player_pc(void)
{
    struct Mail temp;
    u8 i, j;

    for (i = PARTY_SIZE; i < MAIL_COUNT - 1; i++)
    {
        for (j = i + 1; j < MAIL_COUNT; j++)
        {
            if (gSaveBlock1Ptr->mail[i].itemId == ITEM_NONE)
                SWAP(gSaveBlock1Ptr->mail[i], gSaveBlock1Ptr->mail[j], temp);
        }
    }
}

static void Mailbox_DrawMailboxMenu_player_pc(u8 taskId)
{
    u8 windowId = MailboxMenu_AddWindow(MAILBOXWIN_TITLE);
    MailboxMenu_AddWindow(MAILBOXWIN_LIST);
    AddTextPrinterParameterized(windowId, FONT_NORMAL, sText_Mailbox_player_pc, GetStringCenterAlignXOffset(FONT_NORMAL, sText_Mailbox_player_pc, 0x40), 1, 0, NULL);
    ScheduleBgCopyTilemapToVram(0);
    gTasks[taskId].tListTaskId_player_pc = MailboxMenu_CreateList(&gPlayerPCItemPageInfo);
    MailboxMenu_AddScrollArrows(&gPlayerPCItemPageInfo);
}

static void Mailbox_ProcessInput_player_pc(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    if (!gPaletteFade.active)
    {
        s32 inputOptionId = ListMenu_ProcessInput(tListTaskId_player_pc);
        ListMenuGetScrollAndRow(tListTaskId_player_pc, &gPlayerPCItemPageInfo.itemsAbove, &gPlayerPCItemPageInfo.cursorPos);

        switch (inputOptionId)
        {
        case LIST_NOTHING_CHOSEN:
            break;
        case LIST_CANCEL:
            PlaySE(SE_SELECT);
            RemoveScrollIndicatorArrowPair(gPlayerPCItemPageInfo.scrollIndicatorTaskId);
            Mailbox_ReturnToPlayerPC_player_pc(taskId);
            break;
        default:
            // Selected mail, ask what to do with it
            PlaySE(SE_SELECT);
            MailboxMenu_RemoveWindow(MAILBOXWIN_TITLE);
            MailboxMenu_RemoveWindow(MAILBOXWIN_LIST);
            DestroyListMenuTask(tListTaskId_player_pc, &gPlayerPCItemPageInfo.itemsAbove, &gPlayerPCItemPageInfo.cursorPos);
            ScheduleBgCopyTilemapToVram(0);
            RemoveScrollIndicatorArrowPair(gPlayerPCItemPageInfo.scrollIndicatorTaskId);
            gTasks[taskId].func = Mailbox_PrintWhatToDoWithPlayerMailText_player_pc;
            break;
        }
    }
}

static void Mailbox_PrintWhatToDoWithPlayerMailText_player_pc(u8 taskId)
{
    StringCopy(gStringVar1, gSaveBlock1Ptr->mail[gPlayerPCItemPageInfo.itemsAbove + PARTY_SIZE + gPlayerPCItemPageInfo.cursorPos].playerName);
    ConvertInternationalPlayerNameStripChar(gStringVar1, CHAR_SPACE);
    StringExpandPlaceholders(gStringVar4, gText_WhatToDoWithVar1sMail);
    DisplayItemMessageOnField(taskId, gStringVar4, Mailbox_PrintMailOptions_player_pc);
}

static void Mailbox_ReturnToPlayerPC_player_pc(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    MailboxMenu_RemoveWindow(MAILBOXWIN_TITLE);
    MailboxMenu_RemoveWindow(MAILBOXWIN_LIST);
    DestroyListMenuTask(tListTaskId_player_pc, NULL, NULL);
    ScheduleBgCopyTilemapToVram(0);
    MailboxMenu_Free();
    ReshowPlayerPC(taskId);
}

static void Mailbox_PrintMailOptions_player_pc(u8 taskId)
{
    u8 windowId = MailboxMenu_AddWindow(MAILBOXWIN_OPTIONS);
    PrintMenuTable(windowId, ARRAY_COUNT(gMailboxMailOptions), gMailboxMailOptions);
    InitMenuInUpperLeftCornerNormal(windowId, ARRAY_COUNT(gMailboxMailOptions), 0);
    ScheduleBgCopyTilemapToVram(0);
    gTasks[taskId].func = Mailbox_MailOptionsProcessInput_player_pc;
}

static void Mailbox_MailOptionsProcessInput_player_pc(u8 taskId)
{
    s8 inputOptionId = ProcessMenuInput_other();

    switch (inputOptionId)
    {
    case MENU_NOTHING_CHOSEN:
        break;
    case MENU_B_PRESSED:
        PlaySE(SE_SELECT);
        Mailbox_Cancel_player_pc(taskId);
        break;
    default:
        PlaySE(SE_SELECT);
        gMailboxMailOptions[inputOptionId].func.void_u8(taskId);
        break;
    }
}

static void Mailbox_DoMailRead_player_pc(u8 taskId)
{
    FadeScreen(FADE_TO_BLACK, 0);
    gTasks[taskId].func = Mailbox_FadeAndReadMail_player_pc;
}

static void Mailbox_FadeAndReadMail_player_pc(u8 taskId)
{
    if (!gPaletteFade.active)
    {
        MailboxMenu_Free();
        CleanupOverworldWindowsAndTilemaps();
        ReadMail(&gSaveBlock1Ptr->mail[gPlayerPCItemPageInfo.itemsAbove + PARTY_SIZE + gPlayerPCItemPageInfo.cursorPos], Mailbox_ReturnToFieldFromReadMail_player_pc, TRUE);
        DestroyTask(taskId);
    }
}

static void Mailbox_ReturnToFieldFromReadMail_player_pc(void)
{
    gFieldCallback = Mailbox_ReshowAfterMail_player_pc;
    SetMainCallback2(CB2_ReturnToField);
}

static void Mailbox_ReshowAfterMail_player_pc(void)
{
    u8 taskId;

    LoadMessageBoxAndBorderGfx();
    taskId = CreateTask(Mailbox_HandleReturnToProcessInput_player_pc, 0);
    if (MailboxMenu_Alloc(gPlayerPCItemPageInfo.count) == TRUE)
        Mailbox_DrawMailboxMenu_player_pc(taskId);
    else
        DestroyTask(taskId);
    FadeInFromBlack();
}

static void Mailbox_HandleReturnToProcessInput_player_pc(u8 taskId)
{
    if (IsWeatherNotFadingIn() == TRUE)
        gTasks[taskId].func = Mailbox_ProcessInput_player_pc;
}

static void Mailbox_MoveToBag_player_pc(u8 taskId)
{
    DisplayItemMessageOnField(taskId, gText_MessageWillBeLost, Mailbox_AskConfirmMoveToBag_player_pc);
}

static void Mailbox_AskConfirmMoveToBag_player_pc(u8 taskId)
{
    DisplayYesNoMenuDefaultYes();
    gTasks[taskId].func = Mailbox_HandleConfirmMoveToBag_player_pc;
}

static void Mailbox_HandleConfirmMoveToBag_player_pc(u8 taskId)
{
    switch (Menu_ProcessInputNoWrapClearOnChoose())
    {
    case 0: // Yes
        Mailbox_DoMailMoveToBag_player_pc(taskId);
        break;
    case MENU_B_PRESSED:
        PlaySE(SE_SELECT);
    case 1: // No
        Mailbox_CancelMoveToBag_player_pc(taskId);
        break;
    case MENU_NOTHING_CHOSEN:
    default:
        break;
    }
}

static void Mailbox_DoMailMoveToBag_player_pc(u8 taskId)
{
    struct Mail *mail = &gSaveBlock1Ptr->mail[gPlayerPCItemPageInfo.itemsAbove + PARTY_SIZE + gPlayerPCItemPageInfo.cursorPos];
    if (!AddBagItem(mail->itemId, 1))
    {
        DisplayItemMessageOnField(taskId, gText_BagIsFull, Mailbox_Cancel_player_pc);
    }
    else
    {
        DisplayItemMessageOnField(taskId, gText_MailToBagMessageErased, Mailbox_Cancel_player_pc);
        ClearMail(mail);
        Mailbox_CompactMailList_player_pc();
        gPlayerPCItemPageInfo.count--;
        if (gPlayerPCItemPageInfo.count < (gPlayerPCItemPageInfo.pageItems + gPlayerPCItemPageInfo.itemsAbove) && gPlayerPCItemPageInfo.itemsAbove != 0)
            gPlayerPCItemPageInfo.itemsAbove--;
        SetPlayerPCListCount_player_pc(taskId);
    }
}

static void Mailbox_CancelMoveToBag_player_pc(u8 taskId)
{
    Mailbox_Cancel_player_pc(taskId);
}

static void Mailbox_Give_player_pc(u8 taskId)
{
    if (CalculatePlayerPartyCount() == 0)
    {
        Mailbox_NoPokemonForMail_player_pc(taskId);
    }
    else
    {
        FadeScreen(FADE_TO_BLACK, 0);
        gTasks[taskId].func = Mailbox_DoGiveMailPokeMenu_player_pc;
    }
}

static void Mailbox_DoGiveMailPokeMenu_player_pc(u8 taskId)
{
    if (!gPaletteFade.active)
    {
        MailboxMenu_Free();
        CleanupOverworldWindowsAndTilemaps();
        ChooseMonToGiveMailFromMailbox();
        DestroyTask(taskId);
    }
}

void Mailbox_ReturnToMailListAfterDeposit(void)
{
    gFieldCallback = Mailbox_UpdateMailListAfterDeposit_player_pc;
    SetMainCallback2(CB2_ReturnToField);
}

static void Mailbox_UpdateMailListAfterDeposit_player_pc(void)
{
    u8 taskId;
    u8 prevCount;
    taskId = CreateTask(Mailbox_HandleReturnToProcessInput_player_pc, 0);
    prevCount = gPlayerPCItemPageInfo.count;
    gPlayerPCItemPageInfo.count = GetMailboxMailCount_player_pc();
    Mailbox_CompactMailList_player_pc();
    if (prevCount != gPlayerPCItemPageInfo.count && (gPlayerPCItemPageInfo.count < (gPlayerPCItemPageInfo.pageItems + gPlayerPCItemPageInfo.itemsAbove))
       && gPlayerPCItemPageInfo.itemsAbove != 0)
        gPlayerPCItemPageInfo.itemsAbove--;
    SetPlayerPCListCount_player_pc(taskId);
    LoadMessageBoxAndBorderGfx();
    if (MailboxMenu_Alloc(gPlayerPCItemPageInfo.count) == TRUE)
        Mailbox_DrawMailboxMenu_player_pc(taskId);
    else
        DestroyTask(taskId);
    FadeInFromBlack();
}

static void Mailbox_NoPokemonForMail_player_pc(u8 taskId)
{
    DisplayItemMessageOnField(taskId, gText_NoPokemon, Mailbox_Cancel_player_pc);
}

static void Mailbox_Cancel_player_pc(u8 taskId)
{
    MailboxMenu_RemoveWindow(MAILBOXWIN_OPTIONS);
    ClearDialogWindowAndFrame(0, FALSE);
    Mailbox_DrawMailboxMenu_player_pc(taskId);
    ScheduleBgCopyTilemapToVram(0);
    gTasks[taskId].func = Mailbox_ProcessInput_player_pc;
}

static void ItemStorage_Init_player_pc(void)
{
    sItemStorageMenu_player_pc = AllocZeroed(sizeof(*sItemStorageMenu_player_pc));
    memset(sItemStorageMenu_player_pc->windowIds, WINDOW_NONE, ITEMPC_WIN_COUNT_player_pc);
    sItemStorageMenu_player_pc->toSwapPos = NOT_SWAPPING_player_pc;
    sItemStorageMenu_player_pc->spriteId = SPRITE_NONE;
}

static void ItemStorage_Free_player_pc(void)
{
    u32 i;
    for (i = 0; i < ITEMPC_WIN_COUNT_player_pc; i++)
        ItemStorage_RemoveWindow_player_pc(i);
    Free(sItemStorageMenu_player_pc);
}

static u8 ItemStorage_AddWindow_player_pc(u8 i)
{
    u8 *windowIdLoc = &sItemStorageMenu_player_pc->windowIds[i];
    if (*windowIdLoc == WINDOW_NONE)
    {
        *windowIdLoc = AddWindow(&sWindowTemplates_ItemStorage_player_pc[i]);
        DrawStdFrameWithCustomTileAndPalette(*windowIdLoc, FALSE, 0x214, 0xE);
        ScheduleBgCopyTilemapToVram(0);
    }
    return *windowIdLoc;
}

static void ItemStorage_RemoveWindow_player_pc(u8 i)
{
    u8 *windowIdLoc = &sItemStorageMenu_player_pc->windowIds[i];
    if (*windowIdLoc != WINDOW_NONE)
    {
        ClearStdWindowAndFrameToTransparent(*windowIdLoc, FALSE);
        ClearWindowTilemap(*windowIdLoc);
        ScheduleBgCopyTilemapToVram(0);
        RemoveWindow(*windowIdLoc);
        *windowIdLoc = WINDOW_NONE;
    }
}

void ItemStorage_RefreshListMenu(void)
{
    u16 i;

    // Copy item names for all entries but the last (which is Cancel)
    for(i = 0; i < gPlayerPCItemPageInfo.count - 1; i++)
    {
        CopyItemName_PlayerPC(&sItemStorageMenu_player_pc->itemNames[i][0], gSaveBlock1Ptr->pcItems[i].itemId);
        sItemStorageMenu_player_pc->listItems[i].name = &sItemStorageMenu_player_pc->itemNames[i][0];
        sItemStorageMenu_player_pc->listItems[i].id = i;
    }

    // Set up Cancel entry
    StringCopy(&sItemStorageMenu_player_pc->itemNames[i][0], gText_Cancel2);
    sItemStorageMenu_player_pc->listItems[i].name = &sItemStorageMenu_player_pc->itemNames[i][0];
    sItemStorageMenu_player_pc->listItems[i].id = LIST_CANCEL;

    // Set list menu data
    gMultiuseListMenuTemplate = sListMenuTemplate_ItemStorage_player_pc;
    gMultiuseListMenuTemplate.windowId = ItemStorage_AddWindow_player_pc(ITEMPC_WIN_LIST_player_pc);
    gMultiuseListMenuTemplate.totalItems = gPlayerPCItemPageInfo.count;
    gMultiuseListMenuTemplate.items = sItemStorageMenu_player_pc->listItems;
    gMultiuseListMenuTemplate.maxShowed = gPlayerPCItemPageInfo.pageItems;
}

void CopyItemName_PlayerPC(u8 *string, u16 itemId)
{
    CopyItemName(itemId, string);
}

static void ItemStorage_MoveCursor_player_pc(s32 id, bool8 onInit, struct ListMenu *list)
{
    if (onInit != TRUE)
        PlaySE(SE_SELECT);
    if (sItemStorageMenu_player_pc->toSwapPos == NOT_SWAPPING_player_pc)
    {
        ItemStorage_EraseItemIcon_player_pc();
        if (id != LIST_CANCEL)
            ItemStorage_DrawItemIcon_player_pc(gSaveBlock1Ptr->pcItems[id].itemId);
        else
            ItemStorage_DrawItemIcon_player_pc(ITEM_LIST_END);
        ItemStorage_PrintDescription_player_pc(id);
    }
}

static void ItemStorage_PrintMenuItem_player_pc(u8 windowId, u32 id, u8 yOffset)
{
    if (id != LIST_CANCEL)
    {
        if (sItemStorageMenu_player_pc->toSwapPos != NOT_SWAPPING_player_pc)
        {
            if (sItemStorageMenu_player_pc->toSwapPos == (u8)id)
                ItemStorage_DrawSwapArrow_player_pc(yOffset, 0, TEXT_SKIP_DRAW);
            else
                ItemStorage_DrawSwapArrow_player_pc(yOffset, 0xFF, TEXT_SKIP_DRAW);
        }
        ConvertIntToDecimalStringN(gStringVar1, gSaveBlock1Ptr->pcItems[id].quantity, STR_CONV_MODE_RIGHT_ALIGN, 3);
        StringExpandPlaceholders(gStringVar4, gText_xVar1);
        AddTextPrinterParameterized(windowId, FONT_NARROW, gStringVar4, GetStringRightAlignXOffset(FONT_NARROW, gStringVar4, 104), yOffset, TEXT_SKIP_DRAW, NULL);
    }
}

static void ItemStorage_PrintDescription_player_pc(s32 id)
{
    const u8 *description;
    u8 windowId = sItemStorageMenu_player_pc->windowIds[ITEMPC_WIN_MESSAGE_player_pc];

    // Get item description (or Cancel text)
    if (id != LIST_CANCEL)
        description = (u8 *)ItemId_GetDescription(gSaveBlock1Ptr->pcItems[id].itemId);
    else
        description = ItemStorage_GetMessage(MSG_GO_BACK_TO_PREV_player_pc);

    FillWindowPixelBuffer(windowId, PIXEL_FILL(1));
    AddTextPrinterParameterized(windowId, FONT_NORMAL, description, 0, 1, 0, NULL);
}

static void ItemStorage_AddScrollIndicator_player_pc(void)
{
    if (gPlayerPCItemPageInfo.scrollIndicatorTaskId == TASK_NONE)
        gPlayerPCItemPageInfo.scrollIndicatorTaskId = AddScrollIndicatorArrowPairParameterized(SCROLL_ARROW_UP, 176, 12, 148,
                                                                                                gPlayerPCItemPageInfo.count - gPlayerPCItemPageInfo.pageItems,
                                                                                                TAG_SCROLL_ARROW_player_pc,
                                                                                                TAG_SCROLL_ARROW_player_pc,
                                                                                                &gPlayerPCItemPageInfo.itemsAbove);
}

static void ItemStorage_RemoveScrollIndicator_player_pc(void)
{
    if (gPlayerPCItemPageInfo.scrollIndicatorTaskId != TASK_NONE)
    {
        RemoveScrollIndicatorArrowPair(gPlayerPCItemPageInfo.scrollIndicatorTaskId);
        gPlayerPCItemPageInfo.scrollIndicatorTaskId = TASK_NONE;
    }
}

static void ItemStorage_SetSwapArrow_player_pc(u8 listTaskId, u8 b, u8 speed)
{
    ItemStorage_DrawSwapArrow_player_pc(ListMenuGetYCoordForPrintingArrowCursor(listTaskId), b, speed);
}

static void ItemStorage_DrawSwapArrow_player_pc(u8 y, u8 b, u8 speed)
{
    u8 windowId = sItemStorageMenu_player_pc->windowIds[ITEMPC_WIN_LIST_player_pc];
    if (b == 0xFF)
        FillWindowPixelRect(windowId, PIXEL_FILL(1), 0, y, GetMenuCursorDimensionByFont(FONT_NORMAL, 0), GetMenuCursorDimensionByFont(FONT_NORMAL, 1));
    else
        AddTextPrinterParameterized4(windowId, FONT_NORMAL, 0, y, 0, 0, sSwapArrowTextColors_player_pc, speed, gText_SelectorArrow2);
}

static void ItemStorage_DrawItemIcon_player_pc(u16 itemId)
{
    u8 spriteId;
    u8 *spriteIdLoc = &sItemStorageMenu_player_pc->spriteId;

    if (*spriteIdLoc == SPRITE_NONE)
    {
        FreeSpriteTilesByTag(TAG_ITEM_ICON_player_pc);
        FreeSpritePaletteByTag(TAG_ITEM_ICON_player_pc);
        spriteId = AddItemIconSprite(TAG_ITEM_ICON_player_pc, TAG_ITEM_ICON_player_pc, itemId);
        if (spriteId != MAX_SPRITES)
        {
            *spriteIdLoc = spriteId;
            gSprites[spriteId].oam.priority = 0;
            gSprites[spriteId].x2 = 24;
            gSprites[spriteId].y2 = 80;
        }
    }
}

static void ItemStorage_EraseItemIcon_player_pc(void)
{
    u8 *spriteIdLoc = &sItemStorageMenu_player_pc->spriteId;
    if (*spriteIdLoc != SPRITE_NONE)
    {
        FreeSpriteTilesByTag(TAG_ITEM_ICON_player_pc);
        FreeSpritePaletteByTag(TAG_ITEM_ICON_player_pc);
        DestroySprite(&gSprites[*spriteIdLoc]);
        *spriteIdLoc = SPRITE_NONE;
    }
}

static void ItemStorage_CompactList_player_pc(void)
{
    CompactPCItems();
    SetItemListPerPageCount(gSaveBlock1Ptr->pcItems, PC_ITEMS_COUNT, &gPlayerPCItemPageInfo.pageItems, &gPlayerPCItemPageInfo.count, 8);
}

static void ItemStorage_CompactCursor_player_pc(void)
{
    SetCursorWithinListBounds(&gPlayerPCItemPageInfo.itemsAbove, &gPlayerPCItemPageInfo.cursorPos, gPlayerPCItemPageInfo.pageItems, gPlayerPCItemPageInfo.count);
}

static void ItemStorage_CreateListMenu_player_pc(u8 taskId)
{
    s16 *data;
    bool32 toss;
    u32 i, x;
    const u8 *text;

    data = gTasks[taskId].data;
    for (i = 0; i <= ITEMPC_WIN_LIST_END_player_pc; i++)
        ItemStorage_AddWindow_player_pc(i);
    toss = tInTossMenu_player_pc;
    text = sText_TossItem_player_pc;
    if (!toss)
        text = sText_WithdrawItem_player_pc;
    x = GetStringCenterAlignXOffset(FONT_NORMAL, text, 104);
    AddTextPrinterParameterized(sItemStorageMenu_player_pc->windowIds[ITEMPC_WIN_TITLE_player_pc], FONT_NORMAL, text, x, 1, 0, NULL);
    CopyWindowToVram(sItemStorageMenu_player_pc->windowIds[ITEMPC_WIN_ICON_player_pc], COPYWIN_GFX);
    ItemStorage_CompactList_player_pc();
    ItemStorage_CompactCursor_player_pc();
    ItemStorage_RefreshListMenu();
    tListTaskId_player_pc = ListMenuInit(&gMultiuseListMenuTemplate, gPlayerPCItemPageInfo.itemsAbove, gPlayerPCItemPageInfo.cursorPos);
    ItemStorage_AddScrollIndicator_player_pc();
    ScheduleBgCopyTilemapToVram(0);
    gTasks[taskId].func = ItemStorage_ProcessInput_player_pc;
}

static const u8 *ItemStorage_GetMessage(u16 itemId)
{
    const u8 *string;

    switch(itemId)
    {
    case MSG_GO_BACK_TO_PREV_player_pc:
        string = gText_GoBackPrevMenu;
        break;
    case MSG_HOW_MANY_TO_WITHDRAW_player_pc:
        string = sText_WithdrawHowManyItems_player_pc;
        break;
    case MSG_WITHDREW_ITEM_player_pc:
        string = sText_WithdrawXItems_player_pc;
        break;
    case MSG_HOW_MANY_TO_TOSS_player_pc:
        string = gText_TossHowManyVar1s;
        break;
    case MSG_THREW_AWAY_ITEM_player_pc:
        string = gText_ThrewAwayVar2Var1s;
        break;
    case MSG_NO_MORE_ROOM_player_pc:
        string = sText_NoRoomInBag_player_pc;
        break;
    case MSG_TOO_IMPORTANT_player_pc:
        string = sText_TooImportantToToss_player_pc;
        break;
    case MSG_OKAY_TO_THROW_AWAY_player_pc:
        string = gText_ConfirmTossItems;
        break;
    case MSG_SWITCH_WHICH_ITEM_player_pc:
        string = gText_MoveVar1Where;
        break;
    default:
        string = ItemId_GetDescription(itemId);
        break;
    }
    return string;
}

static void ItemStorage_PrintMessage_player_pc(const u8 *string)
{
    u8 windowId = sItemStorageMenu_player_pc->windowIds[ITEMPC_WIN_MESSAGE_player_pc];
    FillWindowPixelBuffer(windowId, PIXEL_FILL(1));
    StringExpandPlaceholders(gStringVar4, string);
    AddTextPrinterParameterized(windowId, FONT_NORMAL, gStringVar4, 0, 1, 0, NULL);
}

// Process input while on the item storage's item list
static void ItemStorage_ProcessInput_player_pc(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    if (JOY_NEW(SELECT_BUTTON))
    {
        // 'Select' starts input for swapping items if not on Cancel
        ListMenuGetScrollAndRow(tListTaskId_player_pc, &gPlayerPCItemPageInfo.itemsAbove, &gPlayerPCItemPageInfo.cursorPos);
        if (gPlayerPCItemPageInfo.itemsAbove + gPlayerPCItemPageInfo.cursorPos != gPlayerPCItemPageInfo.count - 1)
        {
            PlaySE(SE_SELECT);
            ItemStorage_StartItemSwap_player_pc(taskId);
        }
    }
    else
    {
        s32 id = ListMenu_ProcessInput(tListTaskId_player_pc);
        ListMenuGetScrollAndRow(tListTaskId_player_pc, &gPlayerPCItemPageInfo.itemsAbove, &gPlayerPCItemPageInfo.cursorPos);
        switch (id)
        {
        case LIST_NOTHING_CHOSEN:
            break;
        case LIST_CANCEL:
            PlaySE(SE_SELECT);
            ItemStorage_ExitItemList_player_pc(taskId);
            break;
        default:
            PlaySE(SE_SELECT);
            ItemStorage_DoItemAction_player_pc(taskId);
            break;
        }
    }
}

static void ItemStorage_ReturnToMenuSelect_player_pc(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    if (!IsDma3ManagerBusyWithBgCopy())
    {
        DrawDialogueFrame(0, FALSE);

        // Select Withdraw/Toss by default depending on which was just exited
        if (!tInTossMenu_player_pc)
            InitItemStorageMenu_player_pc(taskId, MENU_WITHDRAW_player_pc);
        else
            InitItemStorageMenu_player_pc(taskId, MENU_TOSS_player_pc);
        gTasks[taskId].func = ItemStorageMenuProcessInput_player_pc;
    }
}

static void ItemStorage_ExitItemList_player_pc(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    ItemStorage_EraseItemIcon_player_pc();
    ItemStorage_RemoveScrollIndicator_player_pc();
    DestroyListMenuTask(tListTaskId_player_pc, NULL, NULL);
    DestroySwapLineSprites(sItemStorageMenu_player_pc->swapLineSpriteIds, SWAP_LINE_LENGTH_player_pc);
    ItemStorage_Free_player_pc();
    gTasks[taskId].func = ItemStorage_ReturnToMenuSelect_player_pc;
}

static void ItemStorage_StartItemSwap_player_pc(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    ListMenuSetUnkIndicatorsStructField(tListTaskId_player_pc, 16, 1);
    sItemStorageMenu_player_pc->toSwapPos = gPlayerPCItemPageInfo.itemsAbove + gPlayerPCItemPageInfo.cursorPos;
    ItemStorage_SetSwapArrow_player_pc(tListTaskId_player_pc, 0, 0);
    ItemStorage_UpdateSwapLinePos_player_pc(sItemStorageMenu_player_pc->toSwapPos);
    CopyItemName(gSaveBlock1Ptr->pcItems[sItemStorageMenu_player_pc->toSwapPos].itemId, gStringVar1);
    ItemStorage_PrintMessage_player_pc(ItemStorage_GetMessage(MSG_SWITCH_WHICH_ITEM_player_pc));
    gTasks[taskId].func = ItemStorage_ProcessItemSwapInput_player_pc;
}

static void ItemStorage_ProcessItemSwapInput_player_pc(u8 taskId)
{
    s16 *data;
    s32 id;

    data = gTasks[taskId].data;
    if (JOY_NEW(SELECT_BUTTON))
    {
        ListMenuGetScrollAndRow(tListTaskId_player_pc, &gPlayerPCItemPageInfo.itemsAbove, &gPlayerPCItemPageInfo.cursorPos);
        ItemStorage_FinishItemSwap_player_pc(taskId, FALSE);
        return;
    }
    id = ListMenu_ProcessInput(tListTaskId_player_pc);
    ListMenuGetScrollAndRow(tListTaskId_player_pc, &gPlayerPCItemPageInfo.itemsAbove, &gPlayerPCItemPageInfo.cursorPos);
    SetSwapLineSpritesInvisibility(sItemStorageMenu_player_pc->swapLineSpriteIds, SWAP_LINE_LENGTH_player_pc, FALSE);
    ItemStorage_UpdateSwapLinePos_player_pc(gPlayerPCItemPageInfo.cursorPos);
    switch (id)
    {
    case LIST_NOTHING_CHOSEN:
        break;
    case LIST_CANCEL:
        if (JOY_NEW(A_BUTTON))
            ItemStorage_FinishItemSwap_player_pc(taskId, FALSE);
        else
            ItemStorage_FinishItemSwap_player_pc(taskId, TRUE);
        break;
    default:
        ItemStorage_FinishItemSwap_player_pc(taskId, FALSE);
        break;
    }
}

static void ItemStorage_FinishItemSwap_player_pc(u8 taskId, bool8 canceled)
{
    s16 *data = gTasks[taskId].data;
    u16 newPos = gPlayerPCItemPageInfo.itemsAbove + gPlayerPCItemPageInfo.cursorPos;
    PlaySE(SE_SELECT);
    DestroyListMenuTask(tListTaskId_player_pc, &gPlayerPCItemPageInfo.itemsAbove, &gPlayerPCItemPageInfo.cursorPos);

    if (!canceled && sItemStorageMenu_player_pc->toSwapPos != newPos && sItemStorageMenu_player_pc->toSwapPos != newPos - 1)
    {
        MoveItemSlotInList(gSaveBlock1Ptr->pcItems, sItemStorageMenu_player_pc->toSwapPos, newPos);
        ItemStorage_RefreshListMenu();
    }
    if (sItemStorageMenu_player_pc->toSwapPos < newPos)
        gPlayerPCItemPageInfo.cursorPos--;

    SetSwapLineSpritesInvisibility(sItemStorageMenu_player_pc->swapLineSpriteIds, SWAP_LINE_LENGTH_player_pc, TRUE);
    sItemStorageMenu_player_pc->toSwapPos = NOT_SWAPPING_player_pc;
    tListTaskId_player_pc = ListMenuInit(&gMultiuseListMenuTemplate, gPlayerPCItemPageInfo.itemsAbove, gPlayerPCItemPageInfo.cursorPos);
    ScheduleBgCopyTilemapToVram(0);
    gTasks[taskId].func = ItemStorage_ProcessInput_player_pc;
}

static void ItemStorage_UpdateSwapLinePos_player_pc(u8 y)
{
    UpdateSwapLineSpritesPos(sItemStorageMenu_player_pc->swapLineSpriteIds, SWAP_LINE_LENGTH_player_pc, 128, (y+1) * 16);
}

static void ItemStorage_PrintItemQuantity_player_pc(u8 windowId, u16 value, u32 mode, u8 x, u8 y, u8 n)
{
    ConvertIntToDecimalStringN(gStringVar1, value, mode, n);
    StringExpandPlaceholders(gStringVar4, gText_xVar1);
    AddTextPrinterParameterized(windowId, FONT_NORMAL, gStringVar4, GetStringCenterAlignXOffset(FONT_NORMAL, gStringVar4, 48), y, 0, NULL);
}

// Start an item Withdraw/Toss
static void ItemStorage_DoItemAction_player_pc(u8 taskId)
{
    u8 *end;
    s16 *data = gTasks[taskId].data;
    u16 pos = gPlayerPCItemPageInfo.cursorPos + gPlayerPCItemPageInfo.itemsAbove;
    ItemStorage_RemoveScrollIndicator_player_pc();
    tQuantity_player_pc = 1;

    if (!tInTossMenu_player_pc)
    {
        if (gSaveBlock1Ptr->pcItems[pos].quantity == 1)
        {
            // Withdrawing 1 item, do it automatically
            ItemStorage_DoItemWithdraw_player_pc(taskId);
            return;
        }

        // Withdrawing multiple items, show "how many" message
        end = CopyItemNameHandlePlural(gSaveBlock1Ptr->pcItems[pos].itemId, gStringVar1, 2);
        WrapFontIdToFit(gStringVar1, end, FONT_NORMAL, WindowWidthPx(ITEMPC_WIN_MESSAGE_player_pc) - 6);
        ItemStorage_PrintMessage_player_pc(ItemStorage_GetMessage(MSG_HOW_MANY_TO_WITHDRAW_player_pc));
    }
    else
    {
        if (gSaveBlock1Ptr->pcItems[pos].quantity == 1)
        {
            // Tossing 1 item, do it automatically
            ItemStorage_DoItemToss_player_pc(taskId);
            return;
        }

        // Tossing multiple items, show "how many" message
        end = CopyItemNameHandlePlural(gSaveBlock1Ptr->pcItems[pos].itemId, gStringVar1, 2);
        WrapFontIdToFit(gStringVar1, end, FONT_NORMAL, WindowWidthPx(ITEMPC_WIN_MESSAGE_player_pc) - 6);
        ItemStorage_PrintMessage_player_pc(ItemStorage_GetMessage(MSG_HOW_MANY_TO_TOSS_player_pc));
    }

    // Set up "how many" prompt
    ItemStorage_PrintItemQuantity_player_pc(ItemStorage_AddWindow_player_pc(ITEMPC_WIN_QUANTITY_player_pc), tQuantity_player_pc, STR_CONV_MODE_LEADING_ZEROS, 8, 1, 3);
    gTasks[taskId].func = ItemStorage_HandleQuantityRolling_player_pc;
}

static void ItemStorage_HandleQuantityRolling_player_pc(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    u16 pos = gPlayerPCItemPageInfo.cursorPos + gPlayerPCItemPageInfo.itemsAbove;

    if (AdjustQuantityAccordingToDPadInput(&tQuantity_player_pc, gSaveBlock1Ptr->pcItems[pos].quantity) == TRUE)
    {
        ItemStorage_PrintItemQuantity_player_pc(ItemStorage_AddWindow_player_pc(ITEMPC_WIN_QUANTITY_player_pc), tQuantity_player_pc, STR_CONV_MODE_LEADING_ZEROS, 8, 1, 3);
    }
    else
    {
        if (JOY_NEW(A_BUTTON))
        {
            // Quantity confirmed, perform action
            PlaySE(SE_SELECT);
            ItemStorage_RemoveWindow_player_pc(ITEMPC_WIN_QUANTITY_player_pc);
            if (!tInTossMenu_player_pc)
                ItemStorage_DoItemWithdraw_player_pc(taskId);
            else
                ItemStorage_DoItemToss_player_pc(taskId);
        }
        else if (JOY_NEW(B_BUTTON))
        {
            // Canceled action
            PlaySE(SE_SELECT);
            ItemStorage_RemoveWindow_player_pc(ITEMPC_WIN_QUANTITY_player_pc);
            ItemStorage_PrintMessage_player_pc(ItemStorage_GetMessage(gSaveBlock1Ptr->pcItems[pos].itemId));
            ItemStorage_ReturnToListInput_player_pc(taskId);
        }
    }
}

static void ItemStorage_DoItemWithdraw_player_pc(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    u16 pos = gPlayerPCItemPageInfo.cursorPos + gPlayerPCItemPageInfo.itemsAbove;

    if (AddBagItem(gSaveBlock1Ptr->pcItems[pos].itemId, tQuantity_player_pc) == TRUE)
    {
        // Item withdrawn
        u8 *end = CopyItemNameHandlePlural(gSaveBlock1Ptr->pcItems[pos].itemId, gStringVar1, tQuantity_player_pc);
        WrapFontIdToFit(gStringVar1, end, FONT_NORMAL, WindowWidthPx(ITEMPC_WIN_MESSAGE_player_pc) - 6);
        ConvertIntToDecimalStringN(gStringVar2, tQuantity_player_pc, STR_CONV_MODE_LEFT_ALIGN, 3);
        ItemStorage_PrintMessage_player_pc(ItemStorage_GetMessage(MSG_WITHDREW_ITEM_player_pc));
        gTasks[taskId].func = ItemStorage_HandleRemoveItem_player_pc;
    }
    else
    {
        // No room to withdraw items
        tQuantity_player_pc = 0;
        ItemStorage_PrintMessage_player_pc(ItemStorage_GetMessage(MSG_NO_MORE_ROOM_player_pc));
        gTasks[taskId].func = ItemStorage_HandleErrorMessageInput_player_pc;
    }
}

static void ItemStorage_DoItemToss_player_pc(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    u16 pos = gPlayerPCItemPageInfo.cursorPos + gPlayerPCItemPageInfo.itemsAbove;

    if (!ItemId_GetImportance(gSaveBlock1Ptr->pcItems[pos].itemId))
    {
        // Show toss confirmation prompt
        u8 *end = CopyItemNameHandlePlural(gSaveBlock1Ptr->pcItems[pos].itemId, gStringVar1, tQuantity_player_pc);
        WrapFontIdToFit(gStringVar1, end, FONT_NORMAL, WindowWidthPx(ITEMPC_WIN_MESSAGE_player_pc) - 6);
        ConvertIntToDecimalStringN(gStringVar2, tQuantity_player_pc, STR_CONV_MODE_LEFT_ALIGN, 3);
        ItemStorage_PrintMessage_player_pc(ItemStorage_GetMessage(MSG_OKAY_TO_THROW_AWAY_player_pc));
        CreateYesNoMenuWithCallbacks(taskId, &sWindowTemplates_ItemStorage_player_pc[ITEMPC_WIN_YESNO_player_pc], 1, 0, 1, 0x214, 0xE, &ItemTossYesNoFuncs_player_pc);
    }
    else
    {
        // Can't toss important items
        tQuantity_player_pc = 0;
        ItemStorage_PrintMessage_player_pc(ItemStorage_GetMessage(MSG_TOO_IMPORTANT_player_pc));
        gTasks[taskId].func = ItemStorage_HandleErrorMessageInput_player_pc;
    }
}

static void ItemStorage_TossItemYes_player_pc(u8 taskId)
{
    ItemStorage_PrintMessage_player_pc(ItemStorage_GetMessage(MSG_THREW_AWAY_ITEM_player_pc));
    gTasks[taskId].func = ItemStorage_HandleRemoveItem_player_pc;
}

static void ItemStorage_TossItemNo_player_pc(u8 taskId)
{
    ItemStorage_PrintMessage_player_pc(ItemStorage_GetMessage(gSaveBlock1Ptr->pcItems[gPlayerPCItemPageInfo.itemsAbove + gPlayerPCItemPageInfo.cursorPos].itemId));
    ItemStorage_ReturnToListInput_player_pc(taskId);
}

// Remove item from PC (was either Tossed or Withdrawn)
static void ItemStorage_HandleRemoveItem_player_pc(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    if (JOY_NEW(A_BUTTON | B_BUTTON))
    {
        RemovePCItem(gPlayerPCItemPageInfo.cursorPos + gPlayerPCItemPageInfo.itemsAbove, tQuantity_player_pc);
        DestroyListMenuTask(tListTaskId_player_pc, &gPlayerPCItemPageInfo.itemsAbove, &gPlayerPCItemPageInfo.cursorPos);
        ItemStorage_CompactList_player_pc();
        ItemStorage_CompactCursor_player_pc();
        ItemStorage_RefreshListMenu();
        tListTaskId_player_pc = ListMenuInit(&gMultiuseListMenuTemplate, gPlayerPCItemPageInfo.itemsAbove, gPlayerPCItemPageInfo.cursorPos);
        ItemStorage_ReturnToListInput_player_pc(taskId);
    }
}

static void ItemStorage_HandleErrorMessageInput_player_pc(u8 taskId)
{
    if (JOY_NEW(A_BUTTON | B_BUTTON))
    {
        ItemStorage_PrintMessage_player_pc(ItemStorage_GetMessage(gSaveBlock1Ptr->pcItems[gPlayerPCItemPageInfo.itemsAbove + gPlayerPCItemPageInfo.cursorPos].itemId));
        ItemStorage_ReturnToListInput_player_pc(taskId);
    }
}

static void ItemStorage_ReturnToListInput_player_pc(u8 taskId)
{
    ItemStorage_AddScrollIndicator_player_pc();
    gTasks[taskId].func = ItemStorage_ProcessInput_player_pc;
}
// Contents of play_time.c
#include "global.h"
#include "play_time.h"
#include "fake_rtc.h"

enum
{
    STOPPED_play_time,
    RUNNING_play_time,
    MAXED_OUT_play_time
};

static u8  sPlayTimeCounterState_play_time;

void PlayTimeCounter_Reset(void)
{
    sPlayTimeCounterState_play_time = STOPPED_play_time;

    gSaveBlock2Ptr->playTimeHours = 0;
    gSaveBlock2Ptr->playTimeMinutes = 0;
    gSaveBlock2Ptr->playTimeSeconds = 0;
    gSaveBlock2Ptr->playTimeVBlanks = 0;
}

void PlayTimeCounter_Start(void)
{
    sPlayTimeCounterState_play_time = RUNNING_play_time;

    if (gSaveBlock2Ptr->playTimeHours > 999)
        PlayTimeCounter_SetToMax();
}

void PlayTimeCounter_Stop(void)
{
    sPlayTimeCounterState_play_time = STOPPED_play_time;
}

void PlayTimeCounter_Update(void)
{
    if (sPlayTimeCounterState_play_time != RUNNING_play_time)
        return;

    gSaveBlock2Ptr->playTimeVBlanks++;

    if (gSaveBlock2Ptr->playTimeVBlanks < 60)
        return;

    gSaveBlock2Ptr->playTimeVBlanks = 0;
    gSaveBlock2Ptr->playTimeSeconds++;
    FakeRtc_TickTimeForward();

    if (gSaveBlock2Ptr->playTimeSeconds < 60)
        return;

    gSaveBlock2Ptr->playTimeSeconds = 0;
    gSaveBlock2Ptr->playTimeMinutes++;

    if (gSaveBlock2Ptr->playTimeMinutes < 60)
        return;

    gSaveBlock2Ptr->playTimeMinutes = 0;
    gSaveBlock2Ptr->playTimeHours++;

    if (gSaveBlock2Ptr->playTimeHours > 999)
        PlayTimeCounter_SetToMax();
}

void PlayTimeCounter_SetToMax(void)
{
    sPlayTimeCounterState_play_time = MAXED_OUT_play_time;

    gSaveBlock2Ptr->playTimeHours = 999;
    gSaveBlock2Ptr->playTimeMinutes = 59;
    gSaveBlock2Ptr->playTimeSeconds = 59;
    gSaveBlock2Ptr->playTimeVBlanks = 59;
}
