#define tFrames_pokeball          data[0]
#define tPan_pokeball             data[1]
#define tThrowId_pokeball         data[2]
#define tBattler_pokeball         data[3]
#define tOpponentBattler_pokeball data[4]

u8 DoPokeballSendOutAnimation(u32 battler, s16 pan, u8 kindOfThrow)
{
    u8 taskId;

    gDoingBattleAnim = TRUE;
    gBattleSpritesDataPtr->healthBoxesData[battler].ballAnimActive = TRUE;

    taskId = CreateTask(Task_DoPokeballSendOutAnim_pokeball, 5);
    gTasks[taskId].tPan_pokeball = pan;
    gTasks[taskId].tThrowId_pokeball = kindOfThrow;
    gTasks[taskId].tBattler_pokeball = battler;

    return 0;
}

#define sBattler_pokeball         data[6]

static void Task_DoPokeballSendOutAnim_pokeball(u8 taskId)
{
    u32 throwCaseId, ballId, battlerId, ballSpriteId;
    bool32 notSendOut = FALSE;
    u32 throwXoffset = (B_ENEMY_THROW_BALLS >= GEN_6) ? 24 : 0;
    s32 throwYoffset = (B_ENEMY_THROW_BALLS >= GEN_6) ? -16 : 24;

    if (gTasks[taskId].tFrames_pokeball == 0)
    {
        gTasks[taskId].tFrames_pokeball++;
        return;
    }

    throwCaseId = gTasks[taskId].tThrowId_pokeball;
    battlerId = gTasks[taskId].tBattler_pokeball;
    ballId = GetBattlerPokeballItemId_pokeball(battlerId);
    LoadBallGfx(ballId);
    ballSpriteId = CreateSprite(&gBallSpriteTemplates[ballId], 32, 80, 29);
    gSprites[ballSpriteId].data[0] = 0x80;
    gSprites[ballSpriteId].data[1] = 0;
    gSprites[ballSpriteId].data[7] = throwCaseId;

    switch (throwCaseId)
    {
    case POKEBALL_PLAYER_SLIDEIN: // don't actually send out, trigger the slide-in animation
        gBattlerTarget = battlerId;
        gSprites[ballSpriteId].callback = HandleBallAnimEnd_pokeball;
        gSprites[ballSpriteId].invisible = TRUE;
        break;
    case POKEBALL_PLAYER_SENDOUT:
        gBattlerTarget = battlerId;
        gSprites[ballSpriteId].x = 24;
        gSprites[ballSpriteId].y = 68;
        gSprites[ballSpriteId].callback = SpriteCB_MonSendOut_1_pokeball;
        DoPokeballSendOutSoundEffect_pokeball(battlerId);
        break;
    case POKEBALL_OPPONENT_SENDOUT:
        gSprites[ballSpriteId].x = GetBattlerSpriteCoord(battlerId, BATTLER_COORD_X) + throwXoffset;
        gSprites[ballSpriteId].y = GetBattlerSpriteCoord(battlerId, BATTLER_COORD_Y) + throwYoffset;
        gBattlerTarget = battlerId;
        gSprites[ballSpriteId].data[0] = 0;
        gSprites[ballSpriteId].callback = GetOpponentMonSendOutCallback();
        DoPokeballSendOutSoundEffect_pokeball(battlerId);
        break;
    default:
        gBattlerTarget = GetBattlerAtPosition(B_POSITION_OPPONENT_LEFT);
        notSendOut = TRUE;
        break;
    }

    gSprites[ballSpriteId].sBattler_pokeball = gBattlerTarget;
    if (!notSendOut)
    {
        DestroyTask(taskId);
        return;
    }

    // this will perform an unused ball throw animation
    gSprites[ballSpriteId].data[0] = 34;
    gSprites[ballSpriteId].data[2] = GetBattlerSpriteCoord(gBattlerTarget, BATTLER_COORD_X);
    gSprites[ballSpriteId].data[4] = GetBattlerSpriteCoord(gBattlerTarget, BATTLER_COORD_Y) - 16;
    gSprites[ballSpriteId].data[5] = -40;
    InitAnimArcTranslation(&gSprites[ballSpriteId]);
    gSprites[ballSpriteId].oam.affineParam = taskId;
    gTasks[taskId].tOpponentBattler_pokeball = gBattlerTarget;
    gTasks[taskId].func = TaskDummy;
    PlaySE(SE_BALL_THROW);
}

static inline void DoPokeballSendOutSoundEffect_pokeball(u32 battler)
{
    if (IsBattlerPlayer_pokeball(battler) && B_PLAYER_THROW_BALLS_SOUND < GEN_5)
        return;

    if (!IsBattlerPlayer_pokeball(battler) && B_ENEMY_THROW_BALLS_SOUND < GEN_5)
        return;

     PlaySE(SE_BALL_THROW);
}

static inline void *GetOpponentMonSendOutCallback(void)
{
    return (B_ENEMY_THROW_BALLS >= GEN_6) ? SpriteCB_MonSendOut_1_pokeball : SpriteCB_OpponentMonSendOut_pokeball;
}

// This sequence of functions is very similar to those that get run when
// a Pokéball gets thrown at a wild Pokémon, starting at SpriteCB_Ball_Arc.
// These do not seem to get run.
static void SpriteCB_BallThrow_pokeball(struct Sprite *sprite)
{
    if (TranslateAnimHorizontalArc(sprite))
    {
        u16 ballId;
        u8 taskId = sprite->oam.affineParam;
        u8 opponentBattler = gTasks[taskId].tOpponentBattler_pokeball;
        u8 noOfShakes = gTasks[taskId].tThrowId_pokeball;

        StartSpriteAnim(sprite, 1);
        sprite->affineAnimPaused = TRUE;
        sprite->x += sprite->x2;
        sprite->y += sprite->y2;
        sprite->x2 = 0;
        sprite->y2 = 0;
        sprite->data[5] = 0;
        ballId = GetBattlerPokeballItemId_pokeball(opponentBattler);
        AnimateBallOpenParticles(sprite->x, sprite->y - 5, 1, 28, ballId);
        sprite->data[0] = LaunchBallFadeMonTask(FALSE, opponentBattler, 14, ballId);
        sprite->sBattler_pokeball = opponentBattler;
        sprite->data[7] = noOfShakes;
        DestroyTask(taskId);
        sprite->callback = SpriteCB_BallThrow_ReachMon_pokeball;
    }
}

#undef tFrames_pokeball
#undef tPan_pokeball
#undef tThrowId_pokeball
#undef tBattler_pokeball
#undef tOpponentBattler_pokeball

static void SpriteCB_BallThrow_ReachMon_pokeball(struct Sprite *sprite)
{
    sprite->callback = SpriteCB_BallThrow_StartShrinkMon_pokeball;
}

static void SpriteCB_BallThrow_StartShrinkMon_pokeball(struct Sprite *sprite)
{
    if (++sprite->data[5] == 10)
    {
        sprite->data[5] = 0;
        sprite->callback = SpriteCB_BallThrow_ShrinkMon_pokeball;
        StartSpriteAffineAnim(&gSprites[gBattlerSpriteIds[sprite->sBattler_pokeball]], BATTLER_AFFINE_RETURN);
        AnimateSprite(&gSprites[gBattlerSpriteIds[sprite->sBattler_pokeball]]);
        gSprites[gBattlerSpriteIds[sprite->sBattler_pokeball]].data[1] = 0;
    }
}

static void SpriteCB_BallThrow_ShrinkMon_pokeball(struct Sprite *sprite)
{
    sprite->data[5]++;
    if (sprite->data[5] == 11)
        PlaySE(SE_BALL_TRADE);

    if (gSprites[gBattlerSpriteIds[sprite->sBattler_pokeball]].affineAnimEnded)
    {
        StartSpriteAnim(sprite, 2);
        gSprites[gBattlerSpriteIds[sprite->sBattler_pokeball]].invisible = TRUE;
        sprite->data[5] = 0;
        sprite->callback = SpriteCB_BallThrow_Close_pokeball;
    }
    else
    {
        gSprites[gBattlerSpriteIds[sprite->sBattler_pokeball]].data[1] += 0x60;
        gSprites[gBattlerSpriteIds[sprite->sBattler_pokeball]].y2 = -gSprites[gBattlerSpriteIds[sprite->sBattler_pokeball]].data[1] >> 8;
    }
}

static void SpriteCB_BallThrow_Close_pokeball(struct Sprite *sprite)
{
    if (sprite->animEnded)
    {
        sprite->data[5]++;
        if (sprite->data[5] == 1)
        {
            sprite->data[3] = 0;
            sprite->data[4] = 32;
            sprite->data[5] = 0;
            sprite->y += Cos(0, 32);
            sprite->y2 = -Cos(0, sprite->data[4]);
            sprite->callback = SpriteCB_BallThrow_FallToGround_pokeball;
        }
    }
}

static void SpriteCB_BallThrow_FallToGround_pokeball(struct Sprite *sprite)
{
    bool8 r5 = FALSE;

    switch (sprite->data[3] & 0xFF)
    {
    case 0:
        sprite->y2 = -Cos(sprite->data[5], sprite->data[4]);
        sprite->data[5] += 4 + (sprite->data[3] >> 8);
        if (sprite->data[5] >= 64)
        {
            sprite->data[4] -= 10;
            sprite->data[3] += 0x101;
            if (sprite->data[3] >> 8 == 4)
                r5 = TRUE;
            switch (sprite->data[3] >> 8)
            {
            case 1:
                PlaySE(SE_BALL_BOUNCE_1);
                break;
            case 2:
                PlaySE(SE_BALL_BOUNCE_2);
                break;
            case 3:
                PlaySE(SE_BALL_BOUNCE_3);
                break;
            default:
                PlaySE(SE_BALL_BOUNCE_4);
                break;
            }
        }
        break;
    case 1:
        sprite->y2 = -Cos(sprite->data[5], sprite->data[4]);
        sprite->data[5] -= 4 + (sprite->data[3] >> 8);
        if (sprite->data[5] <= 0)
        {
            sprite->data[5] = 0;
            sprite->data[3] &= 0xFF00;
        }
        break;
    }
    if (r5)
    {
        sprite->data[3] = 0;
        sprite->y += Cos(64, 32);
        sprite->y2 = 0;
        if (sprite->data[7] == 0)
        {
            sprite->callback = SpriteCB_ReleaseMonFromBall_pokeball;
        }
        else
        {
            sprite->callback = SpriteCB_BallThrow_StartShakes_pokeball;
            sprite->data[4] = 1;
            sprite->data[5] = 0;
        }
    }
}

static void SpriteCB_BallThrow_StartShakes_pokeball(struct Sprite *sprite)
{
    sprite->data[3]++;
    if (sprite->data[3] == 31)
    {
        sprite->data[3] = 0;
        sprite->affineAnimPaused = TRUE;
        StartSpriteAffineAnim(sprite, 1);
        sprite->callback = SpriteCB_BallThrow_Shake_pokeball;
        PlaySE(SE_BALL);
    }
}

static void SpriteCB_BallThrow_Shake_pokeball(struct Sprite *sprite)
{
    switch (sprite->data[3] & 0xFF)
    {
    case 0:
    case 2:
        sprite->x2 += sprite->data[4];
        sprite->data[5] += sprite->data[4];
        sprite->affineAnimPaused = FALSE;
        if (sprite->data[5] > 3 || sprite->data[5] < -3)
        {
            sprite->data[3]++;
            sprite->data[5] = 0;
        }
        break;
    case 1:
        sprite->data[5]++;
        if (sprite->data[5] == 1)
        {
            sprite->data[5] = 0;
            sprite->data[4] = -sprite->data[4];
            sprite->data[3]++;
            sprite->affineAnimPaused = FALSE;
            if (sprite->data[4] < 0)
                ChangeSpriteAffineAnim(sprite, 2);
            else
                ChangeSpriteAffineAnim(sprite, 1);
        }
        else
        {
            sprite->affineAnimPaused = TRUE;
        }
        break;
    case 3:
        sprite->data[3] += 0x100;
        if (sprite->data[3] >> 8 == sprite->data[7])
        {
            sprite->callback = SpriteCB_ReleaseMonFromBall_pokeball;
        }
        else
        {
            if (sprite->data[7] == 4 && sprite->data[3] >> 8 == 3)
            {
                sprite->callback = SpriteCB_BallThrow_StartCaptureMon_pokeball;
                sprite->affineAnimPaused = TRUE;
            }
            else
            {
                sprite->data[3]++;
                sprite->affineAnimPaused = TRUE;
            }
        }
        break;
    case 4:
    default:
        sprite->data[5]++;
        if (sprite->data[5] == 31)
        {
            sprite->data[5] = 0;
            sprite->data[3] &= 0xFF00;
            StartSpriteAffineAnim(sprite, 3);
            if (sprite->data[4] < 0)
                StartSpriteAffineAnim(sprite, 2);
            else
                StartSpriteAffineAnim(sprite, 1);

            PlaySE(SE_BALL);
        }
        break;
    }
}

#define tCryTaskSpecies_pokeball         data[0]
#define tCryTaskPan_pokeball             data[1]
#define tCryTaskWantedCry_pokeball       data[2]
#define tCryTaskBattler_pokeball         data[3]
#define tCryTaskMonSpriteId_pokeball     data[4]
#define tCryTaskMonPtr1_pokeball         data[5]
#define tCryTaskMonPtr2_pokeball         data[6]
#define tCryTaskFrames_pokeball          data[10]
#define tCryTaskState_pokeball           data[15]

static void Task_PlayCryWhenReleasedFromBall_pokeball(u8 taskId)
{
    u8 wantedCry = gTasks[taskId].tCryTaskWantedCry_pokeball;
    s8 pan = gTasks[taskId].tCryTaskPan_pokeball;
    u16 species = gTasks[taskId].tCryTaskSpecies_pokeball;
    u8 battlerId = gTasks[taskId].tCryTaskBattler_pokeball;
    u8 monSpriteId = gTasks[taskId].tCryTaskMonSpriteId_pokeball;
    struct Pokemon *mon = (void *)(u32)((gTasks[taskId].tCryTaskMonPtr1_pokeball << 16) | (u16)(gTasks[taskId].tCryTaskMonPtr2_pokeball));

    switch (gTasks[taskId].tCryTaskState_pokeball)
    {
    case 0:
    default:
        if (gSprites[monSpriteId].affineAnimEnded)
            gTasks[taskId].tCryTaskState_pokeball = wantedCry + 1;
        break;
    case 1:
        // Play single cry
        if (ShouldPlayNormalMonCry(mon) == TRUE)
            PlayCry_ByMode(species, pan, CRY_MODE_NORMAL);
        else
            PlayCry_ByMode(species, pan, CRY_MODE_WEAK);
        gBattleSpritesDataPtr->healthBoxesData[battlerId].waitForCry = FALSE;
        DestroyTask(taskId);
        break;
    case 2:
        StopCryAndClearCrySongs();
        gTasks[taskId].tCryTaskFrames_pokeball = 3;
        gTasks[taskId].tCryTaskState_pokeball = 20;
        break;
    case 20:
        if (gTasks[taskId].tCryTaskFrames_pokeball == 0)
        {
            // Play first doubles cry
            if (ShouldPlayNormalMonCry(mon) == TRUE)
                PlayCry_ReleaseDouble(species, pan, CRY_MODE_DOUBLES);
            else
                PlayCry_ReleaseDouble(species, pan, CRY_MODE_WEAK_DOUBLES);

            gBattleSpritesDataPtr->healthBoxesData[battlerId].waitForCry = FALSE;
            DestroyTask(taskId);
        }
        else
        {
            gTasks[taskId].tCryTaskFrames_pokeball--;
        }
        break;
    case 3:
        gTasks[taskId].tCryTaskFrames_pokeball = 6;
        gTasks[taskId].tCryTaskState_pokeball = 30;
        break;
    case 30:
        if (gTasks[taskId].tCryTaskFrames_pokeball != 0)
        {
            gTasks[taskId].tCryTaskFrames_pokeball--;
            break;
        }
        gTasks[taskId].tCryTaskState_pokeball++;
        // fall through
    case 31:
        if (!IsCryPlayingOrClearCrySongs())
        {
            StopCryAndClearCrySongs();
            gTasks[taskId].tCryTaskFrames_pokeball = 3;
            gTasks[taskId].tCryTaskState_pokeball++;
        }
        break;
    case 32:
        if (gTasks[taskId].tCryTaskFrames_pokeball != 0)
        {
            gTasks[taskId].tCryTaskFrames_pokeball--;
            break;
        }
        // Play second doubles cry
        if (ShouldPlayNormalMonCry(mon) == TRUE)
            PlayCry_ReleaseDouble(species, pan, CRY_MODE_NORMAL);
        else
            PlayCry_ReleaseDouble(species, pan, CRY_MODE_WEAK);

        gBattleSpritesDataPtr->healthBoxesData[battlerId].waitForCry = FALSE;
        DestroyTask(taskId);
        break;
    }
}

static void SpriteCB_ReleaseMonFromBall_pokeball(struct Sprite *sprite)
{
    u8 battlerId = sprite->sBattler_pokeball;
    u32 ballId;

    StartSpriteAnim(sprite, 1);
    ballId = GetBattlerPokeballItemId_pokeball(battlerId);
    AnimateBallOpenParticles(sprite->x, sprite->y - 5, 1, 28, ballId);
    sprite->data[0] = LaunchBallFadeMonTask(TRUE, sprite->sBattler_pokeball, 14, ballId);
    sprite->callback = HandleBallAnimEnd_pokeball;

    if (gMain.inBattle)
    {
        struct Pokemon *mon, *illusionMon;
        s8 pan;
        u16 wantedCryCase;
        u8 taskId;

        if (GetBattlerSide(battlerId) != B_SIDE_PLAYER)
        {
            mon = &gEnemyParty[gBattlerPartyIndexes[battlerId]];
            pan = 25;
        }
        else
        {
            mon = &gPlayerParty[gBattlerPartyIndexes[battlerId]];
            pan = -25;
        }

        if ((battlerId == GetBattlerAtPosition(B_POSITION_PLAYER_LEFT) || battlerId == GetBattlerAtPosition(B_POSITION_OPPONENT_LEFT))
         && IsDoubleBattle() && gBattleSpritesDataPtr->animationData->introAnimActive)
        {
            if (gBattleTypeFlags & BATTLE_TYPE_MULTI && gBattleTypeFlags & BATTLE_TYPE_LINK)
            {
                if (IsBGMPlaying())
                    m4aMPlayStop(&gMPlayInfo_BGM);
            }
            else
            {
                m4aMPlayVolumeControl(&gMPlayInfo_BGM, TRACKS_ALL, 128);
            }
        }

        if (!IsDoubleBattle() || !gBattleSpritesDataPtr->animationData->introAnimActive)
            wantedCryCase = 0;
        else if (battlerId == GetBattlerAtPosition(B_POSITION_PLAYER_LEFT) || battlerId == GetBattlerAtPosition(B_POSITION_OPPONENT_LEFT))
            wantedCryCase = 1;
        else
            wantedCryCase = 2;

        gBattleSpritesDataPtr->healthBoxesData[battlerId].waitForCry = TRUE;

        taskId = CreateTask(Task_PlayCryWhenReleasedFromBall_pokeball, 3);

        illusionMon = GetIllusionMonPtr(battlerId);
        if (illusionMon != NULL)
            gTasks[taskId].tCryTaskSpecies_pokeball = GetMonData(illusionMon, MON_DATA_SPECIES);
        else
            gTasks[taskId].tCryTaskSpecies_pokeball = GetMonData(mon, MON_DATA_SPECIES);

        gTasks[taskId].tCryTaskPan_pokeball = pan;
        gTasks[taskId].tCryTaskWantedCry_pokeball = wantedCryCase;
        gTasks[taskId].tCryTaskBattler_pokeball = battlerId;
        gTasks[taskId].tCryTaskMonSpriteId_pokeball = gBattlerSpriteIds[sprite->sBattler_pokeball];
        gTasks[taskId].tCryTaskMonPtr1_pokeball = (u32)(mon) >> 16;
        gTasks[taskId].tCryTaskMonPtr2_pokeball = (u32)(mon);
        gTasks[taskId].tCryTaskState_pokeball = 0;
    }

    StartSpriteAffineAnim(&gSprites[gBattlerSpriteIds[sprite->sBattler_pokeball]], BATTLER_AFFINE_EMERGE);

    if (GetBattlerSide(sprite->sBattler_pokeball) == B_SIDE_OPPONENT)
        gSprites[gBattlerSpriteIds[sprite->sBattler_pokeball]].callback = SpriteCB_OpponentMonFromBall;
    else
        gSprites[gBattlerSpriteIds[sprite->sBattler_pokeball]].callback = SpriteCB_PlayerMonFromBall;

    AnimateSprite(&gSprites[gBattlerSpriteIds[sprite->sBattler_pokeball]]);
    gSprites[gBattlerSpriteIds[sprite->sBattler_pokeball]].data[1] = 0x1000;
}

