#undef tCryTaskWantedCry_pokeball
#undef tCryTaskBattler_pokeball
#undef tCryTaskMonSpriteId_pokeball
#undef tCryTaskMonPtr1_pokeball
#undef tCryTaskMonPtr2_pokeball
#undef tCryTaskFrames_pokeball
#undef tCryTaskState_pokeball

static void SpriteCB_BallThrow_StartCaptureMon_pokeball(struct Sprite *sprite)
{
    sprite->animPaused = TRUE;
    sprite->callback = SpriteCB_BallThrow_CaptureMon_pokeball;
    sprite->data[3] = 0;
    sprite->data[4] = 0;
    sprite->data[5] = 0;
}

static void HandleBallAnimEnd_pokeball(struct Sprite *sprite)
{
    bool8 affineAnimEnded = FALSE;
    u8 battlerId = sprite->sBattler_pokeball;

    if (sprite->data[7] == POKEBALL_PLAYER_SLIDEIN)
    {
        gSprites[gBattlerSpriteIds[sprite->sBattler_pokeball]].callback = SpriteCB_PlayerMonSlideIn;
        AnimateSprite(&gSprites[gBattlerSpriteIds[sprite->sBattler_pokeball]]);
        gSprites[gBattlerSpriteIds[sprite->sBattler_pokeball]].data[1] = 0x1000;
    }

    gSprites[gBattlerSpriteIds[battlerId]].invisible = FALSE;
    if (sprite->animEnded)
        sprite->invisible = TRUE;
    if (gSprites[gBattlerSpriteIds[battlerId]].affineAnimEnded)
    {
        StartSpriteAffineAnim(&gSprites[gBattlerSpriteIds[battlerId]], BATTLER_AFFINE_NORMAL);
        affineAnimEnded = TRUE;
    }
    else
    {
        gSprites[gBattlerSpriteIds[battlerId]].data[1] -= 288;
        gSprites[gBattlerSpriteIds[battlerId]].y2 = gSprites[gBattlerSpriteIds[battlerId]].data[1] >> 8;
    }
    if (sprite->animEnded && affineAnimEnded)
    {
        s32 i, doneBattlers;

        gSprites[gBattlerSpriteIds[battlerId]].y2 = 0;
        gDoingBattleAnim = FALSE;
        gBattleSpritesDataPtr->healthBoxesData[battlerId].ballAnimActive = FALSE;
        FreeSpriteOamMatrix(sprite);
        DestroySprite(sprite);

        for (doneBattlers = 0, i = 0; i < MAX_BATTLERS_COUNT; i++)
        {
            if (gBattleSpritesDataPtr->healthBoxesData[i].ballAnimActive == FALSE)
                doneBattlers++;
        }
        if (doneBattlers == MAX_BATTLERS_COUNT)
        {
            for (i = 0; i < POKEBALL_COUNT; i++)
                FreeBallGfx(i);
        }
    }
}

static void SpriteCB_BallThrow_CaptureMon_pokeball(struct Sprite *sprite)
{
    u8 battlerId = sprite->sBattler_pokeball;

    sprite->data[4]++;
    if (sprite->data[4] == 40)
    {
        return;
    }
    else if (sprite->data[4] == 95)
    {
        gDoingBattleAnim = FALSE;
        m4aMPlayAllStop();
        PlaySE(MUS_EVOLVED);
    }
    else if (sprite->data[4] == 315)
    {
        FreeOamMatrix(gSprites[gBattlerSpriteIds[sprite->sBattler_pokeball]].oam.matrixNum);
        DestroySprite(&gSprites[gBattlerSpriteIds[sprite->sBattler_pokeball]]);
        DestroySpriteAndFreeResources(sprite);
        if (gMain.inBattle)
            gBattleSpritesDataPtr->healthBoxesData[battlerId].ballAnimActive = FALSE;
    }
}

static inline bool32 IsBattlerPlayer_pokeball(u32 battler)
{
    return (battler % B_POSITION_PLAYER_RIGHT) ? FALSE : TRUE;
}

static void SpriteCB_MonSendOut_1_pokeball(struct Sprite *sprite)
{
    bool32 isPlayer = IsBattlerPlayer_pokeball(sprite->sBattler_pokeball);
    u32 coordX = (isPlayer) ? BATTLER_COORD_X_2 : BATTLER_COORD_X;
    u32 coordY = (isPlayer) ? BATTLER_COORD_Y_PIC_OFFSET : BATTLER_COORD_Y;

    sprite->data[0] = 25;
    sprite->data[2] = GetBattlerSpriteCoord(sprite->sBattler_pokeball, coordX);
    sprite->data[4] = GetBattlerSpriteCoord(sprite->sBattler_pokeball, coordY) + 24;
    sprite->data[5] = -30;
    sprite->oam.affineParam = sprite->sBattler_pokeball;
    InitAnimArcTranslation(sprite);
    sprite->callback = SpriteCB_MonSendOut_2_pokeball;
}

#define HIBYTE_pokeball(x) (((x) >> 8) & 0xFF)

static void SpriteCB_MonSendOut_2_pokeball(struct Sprite *sprite)
{
    u32 r6;
    u32 r7;
    bool32 rightPosition = (IsBattlerPlayer_pokeball(sprite->sBattler_pokeball)) ? B_POSITION_PLAYER_RIGHT : B_POSITION_OPPONENT_RIGHT;

    if (HIBYTE_pokeball(sprite->data[7]) >= 35 && HIBYTE_pokeball(sprite->data[7]) < 80)
    {
        s16 r4;

        if ((sprite->oam.affineParam & 0xFF00) == 0)
        {
            r6 = sprite->data[1] & 1;
            r7 = sprite->data[2] & 1;
            sprite->data[1] = ((sprite->data[1] / 3) & ~1) | r6;
            sprite->data[2] = ((sprite->data[2] / 3) & ~1) | r7;
            StartSpriteAffineAnim(sprite, 4);
        }
        r4 = sprite->data[0];
        AnimTranslateLinear(sprite);
        sprite->data[7] += sprite->sBattler_pokeball / 3;
        sprite->y2 += Sin(HIBYTE_pokeball(sprite->data[7]), sprite->data[5]);
        sprite->oam.affineParam += 0x100;
        if ((sprite->oam.affineParam >> 8) % 3 != 0)
            sprite->data[0] = r4;
        else
            sprite->data[0] = r4 - 1;
        if (HIBYTE_pokeball(sprite->data[7]) >= 80)
        {
            r6 = sprite->data[1] & 1;
            r7 = sprite->data[2] & 1;
            sprite->data[1] = ((sprite->data[1] * 3) & ~1) | r6;
            sprite->data[2] = ((sprite->data[2] * 3) & ~1) | r7;
        }
    }
    else
    {
        if (TranslateAnimHorizontalArc(sprite))
        {
            sprite->x += sprite->x2;
            sprite->y += sprite->y2;
            sprite->y2 = 0;
            sprite->x2 = 0;
            sprite->sBattler_pokeball = sprite->oam.affineParam & 0xFF;
            sprite->data[0] = 0;

            if (IsDoubleBattle() && gBattleSpritesDataPtr->animationData->introAnimActive
             && sprite->sBattler_pokeball == GetBattlerAtPosition(rightPosition))
                sprite->callback = SpriteCB_ReleaseMon2FromBall_pokeball;
            else
                sprite->callback = SpriteCB_ReleaseMonFromBall_pokeball;

            StartSpriteAffineAnim(sprite, 0);
        }
    }
}

#undef HIBYTE_pokeball

static void SpriteCB_ReleaseMon2FromBall_pokeball(struct Sprite *sprite)
{
    if (sprite->data[0]++ > 24)
    {
        sprite->data[0] = 0;
        sprite->callback = SpriteCB_ReleaseMonFromBall_pokeball;
    }
}

static void SpriteCB_OpponentMonSendOut_pokeball(struct Sprite *sprite)
{
    sprite->data[0]++;
    if (sprite->data[0] > 15)
    {
        sprite->data[0] = 0;
        if (IsDoubleBattle() && gBattleSpritesDataPtr->animationData->introAnimActive
         && sprite->sBattler_pokeball == GetBattlerAtPosition(B_POSITION_OPPONENT_RIGHT))
            sprite->callback = SpriteCB_ReleaseMon2FromBall_pokeball;
        else
            sprite->callback = SpriteCB_ReleaseMonFromBall_pokeball;
    }
}

