// Sprite data for the Pokémon
#define sSpecies_pokeball data[7]

// Sprite data for the Poké Ball
#define sMonSpriteId_pokeball data[0]
#define sDelay_pokeball       data[1]
#define sMonPalNum_pokeball   data[2]
#define sFadePalsLo_pokeball  data[3]
#define sFadePalsHi_pokeball  data[4]
#define sFinalMonX_pokeball   data[5]
#define sFinalMonY_pokeball   data[6]
#define sTrigIdx_pokeball     data[7]

// Poké Ball in Birch intro, and when receiving via trade
void CreatePokeballSpriteToReleaseMon(u8 monSpriteId, u8 monPalNum, u8 x, u8 y, u8 oamPriority, u8 subpriority, u8 delay, u32 fadePalettes, u16 species)
{
    u8 spriteId;

    LoadCompressedSpriteSheetUsingHeap(&gBallSpriteSheets[BALL_POKE]);
    LoadCompressedSpritePaletteUsingHeap(&gBallSpritePalettes[BALL_POKE]);
    spriteId = CreateSprite(&gBallSpriteTemplates[BALL_POKE], x, y, subpriority);

    gSprites[spriteId].sMonSpriteId_pokeball = monSpriteId;
    gSprites[spriteId].sFinalMonX_pokeball = gSprites[monSpriteId].x;
    gSprites[spriteId].sFinalMonY_pokeball = gSprites[monSpriteId].y;

    gSprites[monSpriteId].x = x;
    gSprites[monSpriteId].y = y;
    gSprites[monSpriteId].sSpecies_pokeball = species;

    gSprites[spriteId].sDelay_pokeball = delay;
    gSprites[spriteId].sMonPalNum_pokeball = monPalNum;
    gSprites[spriteId].sFadePalsLo_pokeball = fadePalettes;
    gSprites[spriteId].sFadePalsHi_pokeball = fadePalettes >> 16;
    gSprites[spriteId].oam.priority = oamPriority;
    gSprites[spriteId].callback = SpriteCB_PokeballReleaseMon_pokeball;

    gSprites[monSpriteId].invisible = TRUE;
}

static void SpriteCB_PokeballReleaseMon_pokeball(struct Sprite *sprite)
{
    if (sprite->sDelay_pokeball == 0)
    {
        u8 subpriority;
        u8 spriteId = sprite->sMonSpriteId_pokeball;
        u8 monPalNum = sprite->sMonPalNum_pokeball;
        u32 selectedPalettes = (u16)sprite->sFadePalsLo_pokeball | ((u16)sprite->sFadePalsHi_pokeball << 16);

        if (sprite->subpriority != 0)
            subpriority = sprite->subpriority - 1;
        else
            subpriority = 0;

        StartSpriteAnim(sprite, 1);
        AnimateBallOpenParticlesForPokeball_pokeball(sprite->x, sprite->y - 5, sprite->oam.priority, subpriority);
        // sDelay_pokeball re-used to store task id but never read
        sprite->sDelay_pokeball = LaunchBallFadeMonTaskForPokeball_pokeball(TRUE, monPalNum, selectedPalettes);
        sprite->callback = SpriteCB_ReleasedMonFlyOut_pokeball;
        gSprites[spriteId].invisible = FALSE;
        StartSpriteAffineAnim(&gSprites[spriteId], BATTLER_AFFINE_EMERGE);
        AnimateSprite(&gSprites[spriteId]);
        gSprites[spriteId].data[1] = 0x1000;
        sprite->sTrigIdx_pokeball = 0;
    }
    else
    {
        sprite->sDelay_pokeball--;
    }
}

static void SpriteCB_ReleasedMonFlyOut_pokeball(struct Sprite *sprite)
{
    bool8 emergeAnimFinished = FALSE;
    bool8 atFinalPosition = FALSE;
    u8 monSpriteId = sprite->sMonSpriteId_pokeball;
    u16 x, y;

    if (sprite->animEnded)
        sprite->invisible = TRUE;

    if (gSprites[monSpriteId].affineAnimEnded)
    {
        StartSpriteAffineAnim(&gSprites[monSpriteId], BATTLER_AFFINE_NORMAL);
        emergeAnimFinished = TRUE;
    }

    x = (sprite->sFinalMonX_pokeball - sprite->x) * sprite->sTrigIdx_pokeball / 128 + sprite->x;
    y = (sprite->sFinalMonY_pokeball - sprite->y) * sprite->sTrigIdx_pokeball / 128 + sprite->y;
    gSprites[monSpriteId].x = x;
    gSprites[monSpriteId].y = y;

    if (sprite->sTrigIdx_pokeball < 128)
    {
        s16 sine = -(gSineTable[(u8)sprite->sTrigIdx_pokeball] / 8);

        sprite->sTrigIdx_pokeball += 4;
        gSprites[monSpriteId].x2 = sine;
        gSprites[monSpriteId].y2 = sine;
    }
    else
    {
        gSprites[monSpriteId].x = sprite->sFinalMonX_pokeball;
        gSprites[monSpriteId].y = sprite->sFinalMonY_pokeball;
        gSprites[monSpriteId].x2 = 0;
        gSprites[monSpriteId].y2 = 0;
        atFinalPosition = TRUE;
    }
    if (sprite->animEnded && emergeAnimFinished && atFinalPosition)
    {
        if (gSprites[monSpriteId].sSpecies_pokeball == SPECIES_EGG)
            DoMonFrontSpriteAnimation(&gSprites[monSpriteId], gSprites[monSpriteId].sSpecies_pokeball, TRUE, 0);
        else
            DoMonFrontSpriteAnimation(&gSprites[monSpriteId], gSprites[monSpriteId].sSpecies_pokeball, FALSE, 0);

        DestroySpriteAndFreeResources(sprite);
    }
}

#undef sSpecies_pokeball
#undef sFinalMonX_pokeball
#undef sFinalMonY_pokeball
#undef sTrigIdx_pokeball

#define sTimer_pokeball       data[5]

u8 CreateTradePokeballSprite(u8 monSpriteId, u8 monPalNum, u8 x, u8 y, u8 oamPriority, u8 subPriority, u8 delay, u32 fadePalettes)
{
    u8 spriteId;

    LoadCompressedSpriteSheetUsingHeap(&gBallSpriteSheets[BALL_POKE]);
    LoadCompressedSpritePaletteUsingHeap(&gBallSpritePalettes[BALL_POKE]);
    spriteId = CreateSprite(&gBallSpriteTemplates[BALL_POKE], x, y, subPriority);
    gSprites[spriteId].sMonSpriteId_pokeball = monSpriteId;
    gSprites[spriteId].sDelay_pokeball = delay;
    gSprites[spriteId].sMonPalNum_pokeball = monPalNum;
    gSprites[spriteId].sFadePalsLo_pokeball = fadePalettes;
    gSprites[spriteId].sFadePalsHi_pokeball = fadePalettes >> 16;
    gSprites[spriteId].oam.priority = oamPriority;
    gSprites[spriteId].callback = SpriteCB_TradePokeball_pokeball;
    return spriteId;
}

static void SpriteCB_TradePokeball_pokeball(struct Sprite *sprite)
{
    if (sprite->sDelay_pokeball == 0)
    {
        u8 subpriority;
        u8 monSpriteId = sprite->sMonSpriteId_pokeball;
        u8 monPalNum = sprite->sMonPalNum_pokeball;
        u32 selectedPalettes = (u16)sprite->sFadePalsLo_pokeball | ((u16)sprite->sFadePalsHi_pokeball << 16);

        if (sprite->subpriority != 0)
            subpriority = sprite->subpriority - 1;
        else
            subpriority = 0;

        StartSpriteAnim(sprite, 1);
        AnimateBallOpenParticlesForPokeball_pokeball(sprite->x, sprite->y - 5, sprite->oam.priority, subpriority);
        // sDelay_pokeball re-used to store task id but never read
        sprite->sDelay_pokeball = LaunchBallFadeMonTaskForPokeball_pokeball(TRUE, monPalNum, selectedPalettes);
        sprite->callback = SpriteCB_TradePokeballSendOff_pokeball;
#ifdef BUGFIX
        // FIX: If this is used on a sprite that has previously had an affine animation, it will not
        // play the shrink anim properly due to being paused. Works together with the fix to ResetSpriteAfterAnim.
        gSprites[monSpriteId].affineAnimPaused = FALSE;
#endif // BUGFIX
        StartSpriteAffineAnim(&gSprites[monSpriteId], BATTLER_AFFINE_RETURN);
        AnimateSprite(&gSprites[monSpriteId]);
        gSprites[monSpriteId].data[1] = 0;
    }
    else
    {
        sprite->sDelay_pokeball--;
    }
}

static void SpriteCB_TradePokeballSendOff_pokeball(struct Sprite *sprite)
{
    u8 monSpriteId;

    sprite->sTimer_pokeball++;
    if (sprite->sTimer_pokeball == 11)
        PlaySE(SE_BALL_TRADE);

    monSpriteId = sprite->sMonSpriteId_pokeball;
    if (gSprites[monSpriteId].affineAnimEnded)
    {
        StartSpriteAnim(sprite, 2);
        gSprites[monSpriteId].invisible = TRUE;
        sprite->sTimer_pokeball = 0;
        sprite->callback = SpriteCB_TradePokeballEnd_pokeball;
    }
    else
    {
        gSprites[monSpriteId].data[1] += 96;
        gSprites[monSpriteId].y2 = -gSprites[monSpriteId].data[1] >> 8;
    }
}

static void SpriteCB_TradePokeballEnd_pokeball(struct Sprite *sprite)
{
    if (sprite->animEnded)
        sprite->callback = SpriteCallbackDummy;
}

