// First character in range followed by number of characters in range for upper and lowercase
static const u8  sLetterSearchRanges_pokedex[][4] =
{
    {}, // Name not specified, shouldn't be reached
    [NAME_ABC_pokedex] = {CHAR_A, 3, CHAR_a, 3},
    [NAME_DEF_pokedex] = {CHAR_D, 3, CHAR_d, 3},
    [NAME_GHI_pokedex] = {CHAR_G, 3, CHAR_g, 3},
    [NAME_JKL_pokedex] = {CHAR_J, 3, CHAR_j, 3},
    [NAME_MNO_pokedex] = {CHAR_M, 3, CHAR_m, 3},
    [NAME_PQR_pokedex] = {CHAR_P, 3, CHAR_p, 3},
    [NAME_STU_pokedex] = {CHAR_S, 3, CHAR_s, 3},
    [NAME_VWX_pokedex] = {CHAR_V, 3, CHAR_v, 3},
    [NAME_YZ_pokedex]  = {CHAR_Y, 2, CHAR_y, 2},
};

#define LETTER_IN_RANGE_UPPER_pokedex(letter, range) \
    ((letter) >= sLetterSearchRanges_pokedex[range][0]                                  \
  && (letter) < sLetterSearchRanges_pokedex[range][0] + sLetterSearchRanges_pokedex[range][1])  \

#define LETTER_IN_RANGE_LOWER_pokedex(letter, range) \
    ((letter) >= sLetterSearchRanges_pokedex[range][2]                                  \
  && (letter) < sLetterSearchRanges_pokedex[range][2] + sLetterSearchRanges_pokedex[range][3])  \

