static void LoadScreenSelectBarMain_pokedex(u16 unused)
{
    CopyToBgTilemapBuffer(1, gPokedexScreenSelectBarMain_Tilemap, 0, 0);
}

static void LoadScreenSelectBarSubmenu_pokedex(u16 unused)
{
    CopyToBgTilemapBuffer(1, gPokedexScreenSelectBarSubmenu_Tilemap, 0, 0);
}

static void HighlightScreenSelectBarItem_pokedex(u8 selectedScreen, u16 unused)
{
    u8 i;
    u8 j;
    u16 *ptr = GetBgTilemapBuffer(1);

    for (i = 0; i < SCREEN_COUNT_pokedex; i++)
    {
        u8 row = (i * 7) + 1;
        u16 newPalette;

        do
        {
            newPalette = 0x4000;
            if (i == selectedScreen)
                newPalette = 0x2000;
        } while (0);

        for (j = 0; j < 7; j++)
        {
            ptr[row + j] = (ptr[row + j] % 0x1000) | newPalette;
            ptr[row + j + 0x20] = (ptr[row + j + 0x20] % 0x1000) | newPalette;
        }
    }
    CopyBgTilemapBufferToVram(1);
}

static void HighlightSubmenuScreenSelectBarItem_pokedex(u8 a, u16 b)
{
    u8 i;
    u8 j;
    u16 *ptr = GetBgTilemapBuffer(1);

    for (i = 0; i < 4; i++)
    {
        u8 row = i * 7 + 1;
        u32 newPalette;

        do
        {
            if (i == a || i == 3)
                newPalette = 0x2000;
            else
                newPalette = 0x4000;
        } while (0);

        for (j = 0; j < 7; j++)
        {
            ptr[row + j] = (ptr[row + j] % 0x1000) | newPalette;
            ptr[row + j + 0x20] = (ptr[row + j + 0x20] % 0x1000) | newPalette;
        }
    }
    CopyBgTilemapBufferToVram(1);
}

#define tState_pokedex         data[0]
#define tSpecies_pokedex        data[1]
#define tPalTimer_pokedex      data[2]
#define tMonSpriteId_pokedex   data[3]
#define tIsShiny_pokedex       data[13]
#define tPersonalityLo_pokedex data[14]
#define tPersonalityHi_pokedex data[15]

u8 DisplayCaughtMonDexPage(u16 species, bool32 isShiny, u32 personality)
{
    u8 taskId = 0;
    if (POKEDEX_PLUS_HGSS)
        taskId = CreateTask(Task_DisplayCaughtMonDexPageHGSS, 0);
    else
        taskId = CreateTask(Task_DisplayCaughtMonDexPage_pokedex, 0);

    gTasks[taskId].tState_pokedex = 0;
    gTasks[taskId].tSpecies_pokedex = species;
    gTasks[taskId].tIsShiny_pokedex = isShiny;
    gTasks[taskId].tPersonalityLo_pokedex = personality;
    gTasks[taskId].tPersonalityHi_pokedex = personality >> 16;
    return taskId;
}

static void Task_DisplayCaughtMonDexPage_pokedex(u8 taskId)
{
    u8 spriteId;
    u16 species = gTasks[taskId].tSpecies_pokedex;
    u16 dexNum = SpeciesToNationalPokedexNum(species);

    switch (gTasks[taskId].tState_pokedex)
    {
    case 0:
    default:
        if (!gPaletteFade.active)
        {
            gPokedexVBlankCB = gMain.vblankCallback;
            SetVBlankCallback(NULL);
            ResetOtherVideoRegisters_pokedex(DISPCNT_BG0_ON);
            ResetBgsAndClearDma3BusyFlags(0);
            InitBgsFromTemplates(0, sNewEntryInfoScreen_BgTemplate_pokedex, ARRAY_COUNT(sNewEntryInfoScreen_BgTemplate_pokedex));
            SetBgTilemapBuffer(3, AllocZeroed(BG_SCREEN_SIZE));
            SetBgTilemapBuffer(2, AllocZeroed(BG_SCREEN_SIZE));
            InitWindows(sNewEntryInfoScreen_WindowTemplates_pokedex);
            DeactivateAllTextPrinters();
            gTasks[taskId].tState_pokedex = 1;
        }
        break;
    case 1:
        DecompressAndLoadBgGfxUsingHeap(3, gPokedexMenu_Gfx, 0x2000, 0, 0);
        CopyToBgTilemapBuffer(3, gPokedexInfoScreen_Tilemap, 0, 0);
        FillWindowPixelBuffer(WIN_INFO_pokedex, PIXEL_FILL(0));
        PutWindowTilemap(WIN_INFO_pokedex);
        PutWindowTilemap(WIN_FOOTPRINT_pokedex);
        DrawFootprint(WIN_FOOTPRINT_pokedex, species);
        CopyWindowToVram(WIN_FOOTPRINT_pokedex, COPYWIN_GFX);
        ResetPaletteFade();
        LoadPokedexBgPalette_pokedex(FALSE);
        gTasks[taskId].tState_pokedex++;
        break;
    case 2:
        gTasks[taskId].tState_pokedex++;
        break;
    case 3:
        PrintMonInfo_pokedex(dexNum, IsNationalPokedexEnabled(), 1, 1);
        CopyWindowToVram(WIN_INFO_pokedex, COPYWIN_FULL);
        CopyBgTilemapBufferToVram(2);
        CopyBgTilemapBufferToVram(3);
        gTasks[taskId].tState_pokedex++;
        break;
    case 4:
        spriteId = CreateMonPicSprite(species, FALSE, ((u16)gTasks[taskId].tPersonalityHi_pokedex << 16) | (u16)gTasks[taskId].tPersonalityLo_pokedex, TRUE, MON_PAGE_X_pokedex, MON_PAGE_Y_pokedex, 0, TAG_NONE);
        gSprites[spriteId].oam.priority = 0;
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0x10, 0, RGB_BLACK);
        SetVBlankCallback(gPokedexVBlankCB);
        gTasks[taskId].tMonSpriteId_pokedex = spriteId;
        gTasks[taskId].tState_pokedex++;
        break;
    case 5:
        SetGpuReg(REG_OFFSET_BLDCNT, 0);
        SetGpuReg(REG_OFFSET_BLDALPHA, 0);
        SetGpuReg(REG_OFFSET_BLDY, 0);
        SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_OBJ_1D_MAP | DISPCNT_OBJ_ON);
        ShowBg(2);
        ShowBg(3);
        gTasks[taskId].tState_pokedex++;
        break;
    case 6:
        if (!gPaletteFade.active)
        {
            PlayCry_Normal(species, 0);
            gTasks[taskId].tPalTimer_pokedex = 0;
            gTasks[taskId].func = Task_HandleCaughtMonPageInput_pokedex;
        }
        break;
    }
}

static void Task_HandleCaughtMonPageInput_pokedex(u8 taskId)
{
    if (JOY_NEW(A_BUTTON | B_BUTTON))
    {
        BeginNormalPaletteFade(PALETTES_BG, 0, 0, 16, RGB_BLACK);
        gSprites[gTasks[taskId].tMonSpriteId_pokedex].callback = SpriteCB_SlideCaughtMonToCenter_pokedex;
        gTasks[taskId].func = Task_ExitCaughtMonPage_pokedex;
    }
    // Flicker caught screen color_pokedex
    else if (++gTasks[taskId].tPalTimer_pokedex & 16)
    {
        LoadPalette(gPokedexBgHoenn_Pal + 1, BG_PLTT_ID(3) + 1, PLTT_SIZEOF(7));
    }
    else
    {
        LoadPalette(gPokedexBgHoenn_Pal + 49, BG_PLTT_ID(3) + 1, PLTT_SIZEOF(7));
    }
}

static void Task_ExitCaughtMonPage_pokedex(u8 taskId)
{
    if (!gPaletteFade.active)
    {
        bool32 isShiny;
        u32 personality;
        u8 paletteNum;
        const u32 *lzPaletteData;
        void *buffer;

        SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_OBJ_1D_MAP | DISPCNT_OBJ_ON);
        FreeAllWindowBuffers();
        buffer = GetBgTilemapBuffer(2);
        if (buffer)
            Free(buffer);
        buffer = GetBgTilemapBuffer(3);
        if (buffer)
            Free(buffer);

        isShiny = (bool8)gTasks[taskId].tIsShiny_pokedex;
        personality = ((u16)gTasks[taskId].tPersonalityHi_pokedex << 16) | (u16)gTasks[taskId].tPersonalityLo_pokedex;
        paletteNum = gSprites[gTasks[taskId].tMonSpriteId_pokedex].oam.paletteNum;
        lzPaletteData = GetMonSpritePalFromSpeciesAndPersonality(gTasks[taskId].tSpecies_pokedex, isShiny, personality);
        LoadCompressedPalette(lzPaletteData, OBJ_PLTT_ID(paletteNum), PLTT_SIZE_4BPP);
        DestroyTask(taskId);
    }
}

static void SpriteCB_SlideCaughtMonToCenter_pokedex(struct Sprite *sprite)
{
    if (sprite->x < DISPLAY_WIDTH / 2)
        sprite->x += 2;
    if (sprite->x > DISPLAY_WIDTH / 2)
        sprite->x -= 2;

    if (sprite->y < DISPLAY_HEIGHT / 2)
        sprite->y += 1;
    if (sprite->y > DISPLAY_HEIGHT / 2)
        sprite->y -= 1;
}

