static int DoPokedexSearch_pokedex(u8 dexMode, u8 order, u8 abcGroup, u8 bodyColor, u8 type1, u8 type2)
{
    u16 species;
    u16 i;
    u16 resultsCount;
    u8 types[2];

    CreatePokedexList_pokedex(dexMode, order);

    for (i = 0, resultsCount = 0; i < NATIONAL_DEX_COUNT; i++)
    {
        if (sPokedexView_pokedex->pokedexList[i].seen)
        {
            sPokedexView_pokedex->pokedexList[resultsCount] = sPokedexView_pokedex->pokedexList[i];
            resultsCount++;
        }
    }
    sPokedexView_pokedex->pokemonListCount = resultsCount;

    // Search by name
    if (abcGroup != 0xFF)
    {
        for (i = 0, resultsCount = 0; i < sPokedexView_pokedex->pokemonListCount; i++)
        {
            u8 firstLetter;

            species = NationalPokedexNumToSpecies(sPokedexView_pokedex->pokedexList[i].dexNum);
            firstLetter = GetSpeciesName(species)[0];
            if (LETTER_IN_RANGE_UPPER_pokedex(firstLetter, abcGroup) || LETTER_IN_RANGE_LOWER_pokedex(firstLetter, abcGroup))
            {
                sPokedexView_pokedex->pokedexList[resultsCount] = sPokedexView_pokedex->pokedexList[i];
                resultsCount++;
            }
        }
        sPokedexView_pokedex->pokemonListCount = resultsCount;
    }

    // Search by body color_pokedex
    if (bodyColor != 0xFF)
    {
        for (i = 0, resultsCount = 0; i < sPokedexView_pokedex->pokemonListCount; i++)
        {
            species = NationalPokedexNumToSpecies(sPokedexView_pokedex->pokedexList[i].dexNum);

            if (bodyColor == gSpeciesInfo[species].bodyColor)
            {
                sPokedexView_pokedex->pokedexList[resultsCount] = sPokedexView_pokedex->pokedexList[i];
                resultsCount++;
            }
        }
        sPokedexView_pokedex->pokemonListCount = resultsCount;
    }

    // Search by type
    if (type1 != TYPE_NONE || type2 != TYPE_NONE)
    {
        if (type1 == TYPE_NONE)
        {
            type1 = type2;
            type2 = TYPE_NONE;
        }

        if (type2 == TYPE_NONE)
        {
            for (i = 0, resultsCount = 0; i < sPokedexView_pokedex->pokemonListCount; i++)
            {
                if (sPokedexView_pokedex->pokedexList[i].owned)
                {
                    species = NationalPokedexNumToSpecies(sPokedexView_pokedex->pokedexList[i].dexNum);

                    types[0] = gSpeciesInfo[species].types[0];
                    types[1] = gSpeciesInfo[species].types[1];
                    if (types[0] == type1 || types[1] == type1)
                    {
                        sPokedexView_pokedex->pokedexList[resultsCount] = sPokedexView_pokedex->pokedexList[i];
                        resultsCount++;
                    }
                }
            }
        }
        else
        {
            for (i = 0, resultsCount = 0; i < sPokedexView_pokedex->pokemonListCount; i++)
            {
                if (sPokedexView_pokedex->pokedexList[i].owned)
                {
                    species = NationalPokedexNumToSpecies(sPokedexView_pokedex->pokedexList[i].dexNum);

                    types[0] = gSpeciesInfo[species].types[0];
                    types[1] = gSpeciesInfo[species].types[1];
                    if ((types[0] == type1 && types[1] == type2) || (types[0] == type2 && types[1] == type1))
                    {
                        sPokedexView_pokedex->pokedexList[resultsCount] = sPokedexView_pokedex->pokedexList[i];
                        resultsCount++;
                    }
                }
            }
        }
        sPokedexView_pokedex->pokemonListCount = resultsCount;
    }

    if (sPokedexView_pokedex->pokemonListCount != 0)
    {
        for (i = sPokedexView_pokedex->pokemonListCount; i < NATIONAL_DEX_COUNT; i++)
        {
            sPokedexView_pokedex->pokedexList[i].dexNum = 0xFFFF;
            sPokedexView_pokedex->pokedexList[i].seen = FALSE;
            sPokedexView_pokedex->pokedexList[i].owned = FALSE;
        }
    }

    return resultsCount;
}

