static void Task_LoadSearchMenu_pokedex(u8 taskId)
{
    u16 i;

    switch (gMain.state)
    {
    default:
    case 0:
        if (!gPaletteFade.active)
        {
            sPokedexView_pokedex->currentPage = PAGE_SEARCH_pokedex;
            ResetOtherVideoRegisters_pokedex(0);
            ResetBgsAndClearDma3BusyFlags(0);
            InitBgsFromTemplates(0, sSearchMenu_BgTemplate_pokedex, ARRAY_COUNT(sSearchMenu_BgTemplate_pokedex));
            SetBgTilemapBuffer(3, AllocZeroed(BG_SCREEN_SIZE));
            SetBgTilemapBuffer(2, AllocZeroed(BG_SCREEN_SIZE));
            SetBgTilemapBuffer(1, AllocZeroed(BG_SCREEN_SIZE));
            SetBgTilemapBuffer(0, AllocZeroed(BG_SCREEN_SIZE));
            InitWindows(sSearchMenu_WindowTemplate_pokedex);
            DeactivateAllTextPrinters();
            PutWindowTilemap(0);
            DecompressAndLoadBgGfxUsingHeap(3, gPokedexSearchMenu_Gfx, 0x2000, 0, 0);

            if (!IsNationalPokedexEnabled())
                CopyToBgTilemapBuffer(3, gPokedexSearchMenuHoenn_Tilemap, 0, 0);
            else
                CopyToBgTilemapBuffer(3, gPokedexSearchMenuNational_Tilemap, 0, 0);
            LoadPalette(gPokedexSearchMenu_Pal + 1, BG_PLTT_ID(0) + 1, PLTT_SIZEOF(4 * 16 - 1));
            gMain.state = 1;
        }
        break;
    case 1:
        LoadCompressedSpriteSheet(sInterfaceSpriteSheet_pokedex);
        LoadSpritePalettes(sInterfaceSpritePalette_pokedex);
        CreateSearchParameterScrollArrows_pokedex(taskId);
        for (i = 0; i < NUM_TASK_DATA; i++)
            gTasks[taskId].data[i] = 0;
        SetDefaultSearchModeAndOrder_pokedex(taskId);
        HighlightSelectedSearchTopBarItem_pokedex(SEARCH_TOPBAR_SEARCH_pokedex);
        PrintSelectedSearchParameters_pokedex(taskId);
        CopyWindowToVram(0, COPYWIN_FULL);
        CopyBgTilemapBufferToVram(1);
        CopyBgTilemapBufferToVram(2);
        CopyBgTilemapBufferToVram(3);
        gMain.state++;
        break;
    case 2:
        BeginNormalPaletteFade(PALETTES_ALL, 0, 16, 0, RGB_BLACK);
        gMain.state++;
        break;
    case 3:
        SetGpuReg(REG_OFFSET_BLDCNT, 0);
        SetGpuReg(REG_OFFSET_BLDALPHA, 0);
        SetGpuReg(REG_OFFSET_BLDY, 0);
        SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_OBJ_1D_MAP | DISPCNT_OBJ_ON);
        HideBg(0);
        ShowBg(1);
        ShowBg(2);
        ShowBg(3);
        gMain.state++;
        break;
    case 4:
        if (!gPaletteFade.active)
        {
            gTasks[taskId].func = Task_SwitchToSearchMenuTopBar_pokedex;
            gMain.state = 0;
        }
        break;
    }
}

static void FreeSearchWindowAndBgBuffers_pokedex(void)
{
    void *tilemapBuffer;

    FreeAllWindowBuffers();
    tilemapBuffer = GetBgTilemapBuffer(0);
    if (tilemapBuffer)
        Free(tilemapBuffer);
    tilemapBuffer = GetBgTilemapBuffer(1);
    if (tilemapBuffer)
        Free(tilemapBuffer);
    tilemapBuffer = GetBgTilemapBuffer(2);
    if (tilemapBuffer)
        Free(tilemapBuffer);
    tilemapBuffer = GetBgTilemapBuffer(3);
    if (tilemapBuffer)
        Free(tilemapBuffer);
}

static void Task_SwitchToSearchMenuTopBar_pokedex(u8 taskId)
{
    HighlightSelectedSearchTopBarItem_pokedex(gTasks[taskId].tTopBarItem_pokedex);
    PrintSelectedSearchParameters_pokedex(taskId);
    CopyWindowToVram(0, COPYWIN_GFX);
    CopyBgTilemapBufferToVram(3);
    gTasks[taskId].func = Task_HandleSearchTopBarInput_pokedex;
}

static void Task_HandleSearchTopBarInput_pokedex(u8 taskId)
{
    if (JOY_NEW(B_BUTTON))
    {
        PlaySE(SE_PC_OFF);
        gTasks[taskId].func = Task_ExitSearch_pokedex;
        return;
    }
    if (JOY_NEW(A_BUTTON))
    {
        switch (gTasks[taskId].tTopBarItem_pokedex)
        {
        case SEARCH_TOPBAR_SEARCH_pokedex:
            PlaySE(SE_PIN);
            gTasks[taskId].tMenuItem_pokedex = SEARCH_NAME_pokedex;
            gTasks[taskId].func = Task_SwitchToSearchMenu_pokedex;
            break;
        case SEARCH_TOPBAR_SHIFT_pokedex:
            PlaySE(SE_PIN);
            gTasks[taskId].tMenuItem_pokedex = SEARCH_ORDER_pokedex;
            gTasks[taskId].func = Task_SwitchToSearchMenu_pokedex;
            break;
        case SEARCH_TOPBAR_CANCEL_pokedex:
            PlaySE(SE_PC_OFF);
            gTasks[taskId].func = Task_ExitSearch_pokedex;
            break;
        }
        return;
    }
    if (JOY_NEW(DPAD_LEFT) && gTasks[taskId].tTopBarItem_pokedex > SEARCH_TOPBAR_SEARCH_pokedex)
    {
        PlaySE(SE_DEX_PAGE);
        gTasks[taskId].tTopBarItem_pokedex--;
        HighlightSelectedSearchTopBarItem_pokedex(gTasks[taskId].tTopBarItem_pokedex);
        CopyWindowToVram(0, COPYWIN_GFX);
        CopyBgTilemapBufferToVram(3);
    }
    if (JOY_NEW(DPAD_RIGHT) && gTasks[taskId].tTopBarItem_pokedex < SEARCH_TOPBAR_CANCEL_pokedex)
    {
        PlaySE(SE_DEX_PAGE);
        gTasks[taskId].tTopBarItem_pokedex++;
        HighlightSelectedSearchTopBarItem_pokedex(gTasks[taskId].tTopBarItem_pokedex);
        CopyWindowToVram(0, COPYWIN_GFX);
        CopyBgTilemapBufferToVram(3);
    }
}

static void Task_SwitchToSearchMenu_pokedex(u8 taskId)
{
    HighlightSelectedSearchMenuItem_pokedex(gTasks[taskId].tTopBarItem_pokedex, gTasks[taskId].tMenuItem_pokedex);
    PrintSelectedSearchParameters_pokedex(taskId);
    CopyWindowToVram(0, COPYWIN_GFX);
    CopyBgTilemapBufferToVram(3);
    gTasks[taskId].func = Task_HandleSearchMenuInput_pokedex;
}

// Input for main search menu
static void Task_HandleSearchMenuInput_pokedex(u8 taskId)
{
    const u8 (*movementMap)[4];

    if (gTasks[taskId].tTopBarItem_pokedex != SEARCH_TOPBAR_SEARCH_pokedex)
    {
        if (!IsNationalPokedexEnabled())
            movementMap = sSearchMovementMap_ShiftHoennDex_pokedex;
        else
            movementMap = sSearchMovementMap_ShiftNatDex_pokedex;
    }
    else
    {
        if (!IsNationalPokedexEnabled())
            movementMap = sSearchMovementMap_SearchHoennDex_pokedex;
        else
            movementMap = sSearchMovementMap_SearchNatDex_pokedex;
    }

    if (JOY_NEW(B_BUTTON))
    {
        PlaySE(SE_BALL);
        SetDefaultSearchModeAndOrder_pokedex(taskId);
        gTasks[taskId].func = Task_SwitchToSearchMenuTopBar_pokedex;
        return;
    }
    if (JOY_NEW(A_BUTTON))
    {
        if (gTasks[taskId].tMenuItem_pokedex == SEARCH_OK_pokedex)
        {
            if (gTasks[taskId].tTopBarItem_pokedex != SEARCH_TOPBAR_SEARCH_pokedex)
            {
                sPokeBallRotation_pokedex = POKEBALL_ROTATION_TOP_pokedex;
                sPokedexView_pokedex->pokeBallRotationBackup = POKEBALL_ROTATION_TOP_pokedex;
                sLastSelectedPokemon_pokedex = 0;
                sPokedexView_pokedex->selectedPokemonBackup = 0;
                gSaveBlock2Ptr->pokedex.mode = GetSearchModeSelection_pokedex(taskId, SEARCH_MODE_pokedex);
                if (!IsNationalPokedexEnabled())
                    gSaveBlock2Ptr->pokedex.mode = DEX_MODE_HOENN;
                sPokedexView_pokedex->dexModeBackup = gSaveBlock2Ptr->pokedex.mode;
                gSaveBlock2Ptr->pokedex.order = GetSearchModeSelection_pokedex(taskId, SEARCH_ORDER_pokedex);
                sPokedexView_pokedex->dexOrderBackup = gSaveBlock2Ptr->pokedex.order;
                PlaySE(SE_PC_OFF);
                gTasks[taskId].func = Task_ExitSearch_pokedex;
            }
            else
            {
                EraseAndPrintSearchTextBox_pokedex(gText_SearchingPleaseWait);
                gTasks[taskId].func = Task_StartPokedexSearch_pokedex;
                PlaySE(SE_DEX_SEARCH);
                CopyWindowToVram(0, COPYWIN_GFX);
            }
        }
        else
        {
            PlaySE(SE_PIN);
            gTasks[taskId].func = Task_SelectSearchMenuItem_pokedex;
        }
        return;
    }

    if (JOY_NEW(DPAD_LEFT) && movementMap[gTasks[taskId].tMenuItem_pokedex][0] != 0xFF)
    {
        PlaySE(SE_SELECT);
        gTasks[taskId].tMenuItem_pokedex = movementMap[gTasks[taskId].tMenuItem_pokedex][0];
        HighlightSelectedSearchMenuItem_pokedex(gTasks[taskId].tTopBarItem_pokedex, gTasks[taskId].tMenuItem_pokedex);
        CopyWindowToVram(0, COPYWIN_GFX);
        CopyBgTilemapBufferToVram(3);
    }
    if (JOY_NEW(DPAD_RIGHT) && movementMap[gTasks[taskId].tMenuItem_pokedex][1] != 0xFF)
    {
        PlaySE(SE_SELECT);
        gTasks[taskId].tMenuItem_pokedex = movementMap[gTasks[taskId].tMenuItem_pokedex][1];
        HighlightSelectedSearchMenuItem_pokedex(gTasks[taskId].tTopBarItem_pokedex, gTasks[taskId].tMenuItem_pokedex);
        CopyWindowToVram(0, COPYWIN_GFX);
        CopyBgTilemapBufferToVram(3);
    }
    if (JOY_NEW(DPAD_UP) && movementMap[gTasks[taskId].tMenuItem_pokedex][2] != 0xFF)
    {
        PlaySE(SE_SELECT);
        gTasks[taskId].tMenuItem_pokedex = movementMap[gTasks[taskId].tMenuItem_pokedex][2];
        HighlightSelectedSearchMenuItem_pokedex(gTasks[taskId].tTopBarItem_pokedex, gTasks[taskId].tMenuItem_pokedex);
        CopyWindowToVram(0, COPYWIN_GFX);
        CopyBgTilemapBufferToVram(3);
    }
    if (JOY_NEW(DPAD_DOWN) && movementMap[gTasks[taskId].tMenuItem_pokedex][3] != 0xFF)
    {
        PlaySE(SE_SELECT);
        gTasks[taskId].tMenuItem_pokedex = movementMap[gTasks[taskId].tMenuItem_pokedex][3];
        HighlightSelectedSearchMenuItem_pokedex(gTasks[taskId].tTopBarItem_pokedex, gTasks[taskId].tMenuItem_pokedex);
        CopyWindowToVram(0, COPYWIN_GFX);
        CopyBgTilemapBufferToVram(3);
    }
}

static void Task_StartPokedexSearch_pokedex(u8 taskId)
{
    u8 dexMode = GetSearchModeSelection_pokedex(taskId, SEARCH_MODE_pokedex);
    u8 order = GetSearchModeSelection_pokedex(taskId, SEARCH_ORDER_pokedex);
    u8 abcGroup = GetSearchModeSelection_pokedex(taskId, SEARCH_NAME_pokedex);
    u8 bodyColor = GetSearchModeSelection_pokedex(taskId, SEARCH_COLOR_pokedex);
    u8 type1 = GetSearchModeSelection_pokedex(taskId, SEARCH_TYPE_LEFT_pokedex);
    u8 type2 = GetSearchModeSelection_pokedex(taskId, SEARCH_TYPE_RIGHT_pokedex);

    DoPokedexSearch_pokedex(dexMode, order, abcGroup, bodyColor, type1, type2);
    gTasks[taskId].func = Task_WaitAndCompleteSearch_pokedex;
}

static void Task_WaitAndCompleteSearch_pokedex(u8 taskId)
{
    if (!IsSEPlaying())
    {
        if (sPokedexView_pokedex->pokemonListCount != 0)
        {
            PlaySE(SE_SUCCESS);
            EraseAndPrintSearchTextBox_pokedex(gText_SearchCompleted);
        }
        else
        {
            PlaySE(SE_FAILURE);
            EraseAndPrintSearchTextBox_pokedex(gText_NoMatchingPkmnWereFound);
        }
        gTasks[taskId].func = Task_SearchCompleteWaitForInput_pokedex;
        CopyWindowToVram(0, COPYWIN_GFX);
    }
}

static void Task_SearchCompleteWaitForInput_pokedex(u8 taskId)
{
    if (JOY_NEW(A_BUTTON))
    {
        if (sPokedexView_pokedex->pokemonListCount != 0)
        {
            // Return to dex list and show search results
            sPokedexView_pokedex->screenSwitchState = 1;
            sPokedexView_pokedex->dexMode = GetSearchModeSelection_pokedex(taskId, SEARCH_MODE_pokedex);
            sPokedexView_pokedex->dexOrder = GetSearchModeSelection_pokedex(taskId, SEARCH_ORDER_pokedex);
            gTasks[taskId].func = Task_ExitSearch_pokedex;
            PlaySE(SE_PC_OFF);
        }
        else
        {
            gTasks[taskId].func = Task_SwitchToSearchMenu_pokedex;
            PlaySE(SE_BALL);
        }
    }
}

static void Task_SelectSearchMenuItem_pokedex(u8 taskId)
{
    u8 menuItem;
    s16 *cursorPos;
    s16 *scrollOffset;

    DrawOrEraseSearchParameterBox_pokedex(FALSE);
    menuItem = gTasks[taskId].tMenuItem_pokedex;
    cursorPos = &gTasks[taskId].data[sSearchOptions_pokedex[menuItem].taskDataCursorPos];
    scrollOffset = &gTasks[taskId].data[sSearchOptions_pokedex[menuItem].taskDataScrollOffset];
    gTasks[taskId].tCursorPos_pokedex = *cursorPos;
    gTasks[taskId].tScrollOffset_pokedex = *scrollOffset;
    PrintSearchParameterText_pokedex(taskId);
    PrintSelectorArrow_pokedex(*cursorPos);
    gTasks[taskId].func = Task_HandleSearchParameterInput_pokedex;
    CopyWindowToVram(0, COPYWIN_GFX);
    CopyBgTilemapBufferToVram(3);
}

// Input for scrolling parameter box in right column
static void Task_HandleSearchParameterInput_pokedex(u8 taskId)
{
    u8 menuItem;
    const struct SearchOptionText *texts;
    s16 *cursorPos;
    s16 *scrollOffset;
    u16 maxOption;
    bool8 moved;

    menuItem = gTasks[taskId].tMenuItem_pokedex;
    texts = sSearchOptions_pokedex[menuItem].texts;
    cursorPos = &gTasks[taskId].data[sSearchOptions_pokedex[menuItem].taskDataCursorPos];
    scrollOffset = &gTasks[taskId].data[sSearchOptions_pokedex[menuItem].taskDataScrollOffset];
    maxOption = sSearchOptions_pokedex[menuItem].numOptions - 1;
    if (JOY_NEW(A_BUTTON))
    {
        PlaySE(SE_PIN);
        ClearSearchParameterBoxText_pokedex();
        DrawOrEraseSearchParameterBox_pokedex(TRUE);
        gTasks[taskId].func = Task_SwitchToSearchMenu_pokedex;
        CopyWindowToVram(0, COPYWIN_GFX);
        CopyBgTilemapBufferToVram(3);
        return;
    }
    if (JOY_NEW(B_BUTTON))
    {
        PlaySE(SE_BALL);
        ClearSearchParameterBoxText_pokedex();
        DrawOrEraseSearchParameterBox_pokedex(TRUE);
        *cursorPos = gTasks[taskId].tCursorPos_pokedex;
        *scrollOffset = gTasks[taskId].tScrollOffset_pokedex;
        gTasks[taskId].func = Task_SwitchToSearchMenu_pokedex;
        CopyWindowToVram(0, COPYWIN_GFX);
        CopyBgTilemapBufferToVram(3);
        return;
    }
    moved = FALSE;
    if (JOY_REPEAT(DPAD_UP))
    {
        if (*cursorPos != 0)
        {
            // Move cursor up
            EraseSelectorArrow_pokedex(*cursorPos);
            (*cursorPos)--;
            PrintSelectorArrow_pokedex(*cursorPos);
            moved = TRUE;
        }
        else if (*scrollOffset != 0)
        {
            // Scroll up
            (*scrollOffset)--;
            PrintSearchParameterText_pokedex(taskId);
            PrintSelectorArrow_pokedex(*cursorPos);
            moved = TRUE;
        }
        if (moved)
        {
            PlaySE(SE_SELECT);
            EraseAndPrintSearchTextBox_pokedex(texts[*cursorPos + *scrollOffset].description);
            CopyWindowToVram(0, COPYWIN_GFX);
        }
        return;
    }
    if (JOY_REPEAT(DPAD_DOWN))
    {
        if (*cursorPos < MAX_SEARCH_PARAM_CURSOR_POS_pokedex && *cursorPos < maxOption)
        {
            // Move cursor down
            EraseSelectorArrow_pokedex(*cursorPos);
            (*cursorPos)++;
            PrintSelectorArrow_pokedex(*cursorPos);
            moved = TRUE;
        }
        else if (maxOption > MAX_SEARCH_PARAM_CURSOR_POS_pokedex && *scrollOffset < maxOption - MAX_SEARCH_PARAM_CURSOR_POS_pokedex)
        {
            // Scroll down
            (*scrollOffset)++;
            PrintSearchParameterText_pokedex(taskId);
            PrintSelectorArrow_pokedex(5);
            moved = TRUE;
        }
        if (moved)
        {
            PlaySE(SE_SELECT);
            EraseAndPrintSearchTextBox_pokedex(texts[*cursorPos + *scrollOffset].description);
            CopyWindowToVram(0, COPYWIN_GFX);
        }
        return;
    }
}

static void Task_ExitSearch_pokedex(u8 taskId)
{
    BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
    gTasks[taskId].func = Task_ExitSearchWaitForFade_pokedex;
}

static void Task_ExitSearchWaitForFade_pokedex(u8 taskId)
{
    if (!gPaletteFade.active)
    {
        FreeSearchWindowAndBgBuffers_pokedex();
        DestroyTask(taskId);
    }
}

void SetSearchRectHighlight(u8 flags, u8 x, u8 y, u8 width)
{
    u16 i;
    u16 temp; //should be a pointer, but does not match as one
    u32 ptr = (u32)GetBgTilemapBuffer(3); //same as above

    for (i = 0; i < width; i++)
    {
        temp = *(u16 *)(ptr + (y + 0) * 64 + (x + i) * 2);
        temp &= 0x0fff;
        temp |= (flags << 12);
        *(u16 *)(ptr + (y + 0) * 64 + (x + i) * 2) = temp;

        temp = *(u16 *)(ptr + (y + 1) * 64 + (x + i) * 2);
        temp &= 0x0fff;
        temp |= (flags << 12);
        *(u16 *)(ptr + (y + 1) * 64 + (x + i) * 2) = temp;
    }
}

#define SEARCH_BG_SEARCH_pokedex                SEARCH_TOPBAR_SEARCH_pokedex
#define SEARCH_BG_SHIFT_pokedex                 SEARCH_TOPBAR_SHIFT_pokedex
#define SEARCH_BG_CANCEL_pokedex                SEARCH_TOPBAR_CANCEL_pokedex
#define SEARCH_BG_NAME_pokedex                  (SEARCH_NAME_pokedex + SEARCH_TOPBAR_COUNT_pokedex)
#define SEARCH_BG_COLOR_pokedex                 (SEARCH_COLOR_pokedex + SEARCH_TOPBAR_COUNT_pokedex)
#define SEARCH_BG_TYPE_SELECTION_LEFT_pokedex   (SEARCH_TYPE_LEFT_pokedex + SEARCH_TOPBAR_COUNT_pokedex)
#define SEARCH_BG_TYPE_SELECTION_RIGHT_pokedex  (SEARCH_TYPE_RIGHT_pokedex + SEARCH_TOPBAR_COUNT_pokedex)
#define SEARCH_BG_ORDER_pokedex                 (SEARCH_ORDER_pokedex + SEARCH_TOPBAR_COUNT_pokedex)
#define SEARCH_BG_MODE_pokedex                  (SEARCH_MODE_pokedex + SEARCH_TOPBAR_COUNT_pokedex)
#define SEARCH_BG_OK_pokedex                    (SEARCH_OK_pokedex + SEARCH_TOPBAR_COUNT_pokedex)
#define SEARCH_BG_TYPE_TITLE_pokedex            (SEARCH_COUNT_pokedex + SEARCH_TOPBAR_COUNT_pokedex)

static void DrawSearchMenuItemBgHighlight_pokedex(u8 searchBg, bool8 unselected, bool8 disabled)
{
    u8 highlightFlags = (unselected & 1) | ((disabled & 1) << 1);

    switch (searchBg)
    {
    case SEARCH_BG_SEARCH_pokedex:
    case SEARCH_BG_SHIFT_pokedex:
    case SEARCH_BG_CANCEL_pokedex:
        SetSearchRectHighlight(highlightFlags, sSearchMenuTopBarItems_pokedex[searchBg].highlightX, sSearchMenuTopBarItems_pokedex[searchBg].highlightY, sSearchMenuTopBarItems_pokedex[searchBg].highlightWidth);
        break;
    case SEARCH_BG_NAME_pokedex:
    case SEARCH_BG_COLOR_pokedex:
    case SEARCH_BG_ORDER_pokedex:
    case SEARCH_BG_MODE_pokedex:
        SetSearchRectHighlight(highlightFlags, sSearchMenuItems_pokedex[searchBg - SEARCH_TOPBAR_COUNT_pokedex].titleBgX, sSearchMenuItems_pokedex[searchBg - SEARCH_TOPBAR_COUNT_pokedex].titleBgY, sSearchMenuItems_pokedex[searchBg - SEARCH_TOPBAR_COUNT_pokedex].titleBgWidth);
        // fall through, draw selectionBg for above
    case SEARCH_BG_TYPE_SELECTION_LEFT_pokedex:
    case SEARCH_BG_TYPE_SELECTION_RIGHT_pokedex:
        SetSearchRectHighlight(highlightFlags, sSearchMenuItems_pokedex[searchBg - SEARCH_TOPBAR_COUNT_pokedex].selectionBgX, sSearchMenuItems_pokedex[searchBg - SEARCH_TOPBAR_COUNT_pokedex].selectionBgY, sSearchMenuItems_pokedex[searchBg - SEARCH_TOPBAR_COUNT_pokedex].selectionBgWidth);
        break;
    case SEARCH_BG_TYPE_TITLE_pokedex:
        SetSearchRectHighlight(highlightFlags, sSearchMenuItems_pokedex[SEARCH_TYPE_LEFT_pokedex].titleBgX, sSearchMenuItems_pokedex[SEARCH_TYPE_LEFT_pokedex].titleBgY, sSearchMenuItems_pokedex[SEARCH_TYPE_LEFT_pokedex].titleBgWidth);
        break;
    case SEARCH_BG_OK_pokedex:
        if (!IsNationalPokedexEnabled())
            SetSearchRectHighlight(highlightFlags, sSearchMenuItems_pokedex[searchBg - SEARCH_TOPBAR_COUNT_pokedex].titleBgX, sSearchMenuItems_pokedex[searchBg - SEARCH_TOPBAR_COUNT_pokedex].titleBgY - 2, sSearchMenuItems_pokedex[searchBg - SEARCH_TOPBAR_COUNT_pokedex].titleBgWidth);
        else
            SetSearchRectHighlight(highlightFlags, sSearchMenuItems_pokedex[searchBg - SEARCH_TOPBAR_COUNT_pokedex].titleBgX, sSearchMenuItems_pokedex[searchBg - SEARCH_TOPBAR_COUNT_pokedex].titleBgY, sSearchMenuItems_pokedex[searchBg - SEARCH_TOPBAR_COUNT_pokedex].titleBgWidth);
        break;
    }
}

static void SetInitialSearchMenuBgHighlights_pokedex(u8 topBarItem)
{
    switch (topBarItem)
    {
    case SEARCH_TOPBAR_SEARCH_pokedex:
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_SEARCH_pokedex, FALSE, FALSE);
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_SHIFT_pokedex, TRUE, FALSE);
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_CANCEL_pokedex, TRUE, FALSE);
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_NAME_pokedex, TRUE, FALSE);
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_COLOR_pokedex, TRUE, FALSE);
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_TYPE_TITLE_pokedex, TRUE, FALSE);
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_TYPE_SELECTION_LEFT_pokedex, TRUE, FALSE);
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_TYPE_SELECTION_RIGHT_pokedex, TRUE, FALSE);
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_ORDER_pokedex, TRUE, FALSE);
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_MODE_pokedex, TRUE, FALSE);
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_OK_pokedex, TRUE, FALSE);
        break;
    case SEARCH_TOPBAR_SHIFT_pokedex:
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_SEARCH_pokedex, TRUE, FALSE);
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_SHIFT_pokedex, FALSE, FALSE);
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_CANCEL_pokedex, TRUE, FALSE);
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_NAME_pokedex, TRUE, TRUE);
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_COLOR_pokedex, TRUE, TRUE);
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_TYPE_TITLE_pokedex, TRUE, TRUE);
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_TYPE_SELECTION_LEFT_pokedex, TRUE, TRUE);
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_TYPE_SELECTION_RIGHT_pokedex, TRUE, TRUE);
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_ORDER_pokedex, TRUE, FALSE);
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_MODE_pokedex, TRUE, FALSE);
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_OK_pokedex, TRUE, FALSE);
        break;
    case SEARCH_TOPBAR_CANCEL_pokedex:
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_SEARCH_pokedex, TRUE, FALSE);
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_SHIFT_pokedex, TRUE, FALSE);
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_CANCEL_pokedex, FALSE, FALSE);
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_NAME_pokedex, TRUE, TRUE);
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_COLOR_pokedex, TRUE, TRUE);
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_TYPE_TITLE_pokedex, TRUE, TRUE);
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_TYPE_SELECTION_LEFT_pokedex, TRUE, TRUE);
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_TYPE_SELECTION_RIGHT_pokedex, TRUE, TRUE);
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_ORDER_pokedex, TRUE, TRUE);
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_MODE_pokedex, TRUE, TRUE);
        DrawSearchMenuItemBgHighlight_pokedex(SEARCH_BG_OK_pokedex, TRUE, TRUE);
        break;
    }
}

