// Prints the currently selected search parameters in the search menu selection boxes
static void PrintSelectedSearchParameters_pokedex(u8 taskId)
{
    u16 searchParamId;

    ClearSearchMenuRect_pokedex(40, 16, 96, 80);

    searchParamId = gTasks[taskId].tCursorPos_Name_pokedex + gTasks[taskId].tScrollOffset_Name_pokedex;
    PrintSearchText_pokedex(sDexSearchNameOptions_pokedex[searchParamId].title, 0x2D, 0x11);

    searchParamId = gTasks[taskId].tCursorPos_Color_pokedex + gTasks[taskId].tScrollOffset_Color_pokedex;
    PrintSearchText_pokedex(sDexSearchColorOptions_pokedex[searchParamId].title, 0x2D, 0x21);

    searchParamId = gTasks[taskId].tCursorPos_TypeLeft_pokedex + gTasks[taskId].tScrollOffset_TypeLeft_pokedex;
    PrintSearchTextToFit_pokedex(sDexSearchTypeOptions_pokedex[searchParamId].title, 0x2D, 0x31, 38);

    searchParamId = gTasks[taskId].tCursorPos_TypeRight_pokedex + gTasks[taskId].tScrollOffset_TypeRight_pokedex;
    PrintSearchTextToFit_pokedex(sDexSearchTypeOptions_pokedex[searchParamId].title, 0x5D, 0x31, 38);

    searchParamId = gTasks[taskId].tCursorPos_Order_pokedex + gTasks[taskId].tScrollOffset_Order_pokedex;
    PrintSearchText_pokedex(sDexOrderOptions_pokedex[searchParamId].title, 0x2D, 0x41);

    if (IsNationalPokedexEnabled())
    {
        searchParamId = gTasks[taskId].tCursorPos_Mode_pokedex + gTasks[taskId].tScrollOffset_Mode_pokedex;
        PrintSearchText_pokedex(sDexModeOptions_pokedex[searchParamId].title, 0x2D, 0x51);
    }
}

static void DrawOrEraseSearchParameterBox_pokedex(bool8 erase)
{
    u16 i;
    u16 j;
    u16 *ptr = GetBgTilemapBuffer(3);

    if (!erase)
    {
        *(ptr + 0x11) = 0xC0B;
        for (i = 0x12; i < 0x1F; i++)
            *(ptr + i) = 0x80D;
        for (j = 1; j < 13; j++)
        {
            *(ptr + 0x11 + j * 32) = 0x40A;
            for (i = 0x12; i < 0x1F; i++)
                *(ptr + j * 32 + i) = 2;
        }
        *(ptr + 0x1B1) = 0x40B;
        for (i = 0x12; i < 0x1F; i++)
            *(ptr + 0x1A0 + i) = 0xD;
    }
    else
    {
        for (j = 0; j < 14; j++)
        {
            for (i = 0x11; i < 0x1E; i++)
            {
                *(ptr + j * 32 + i) = 0x4F;
            }
        }
    }
}

// Prints the currently viewable search parameter titles in the right-hand text box
// and the currently selected search parameter description in the bottom text box
static void PrintSearchParameterText_pokedex(u8 taskId)
{
    const struct SearchOptionText *texts = sSearchOptions_pokedex[gTasks[taskId].tMenuItem_pokedex].texts;
    const s16 *cursorPos = &gTasks[taskId].data[sSearchOptions_pokedex[gTasks[taskId].tMenuItem_pokedex].taskDataCursorPos];
    const s16 *scrollOffset = &gTasks[taskId].data[sSearchOptions_pokedex[gTasks[taskId].tMenuItem_pokedex].taskDataScrollOffset];
    u16 i;
    u16 j;

    ClearSearchParameterBoxText_pokedex();

    for (i = 0, j = *scrollOffset; i < MAX_SEARCH_PARAM_ON_SCREEN_pokedex && texts[j].title != NULL; i++, j++)
        PrintSearchParameterTitle_pokedex(i, texts[j].title);

    EraseAndPrintSearchTextBox_pokedex(texts[*cursorPos + *scrollOffset].description);
}

static u8 GetSearchModeSelection_pokedex(u8 taskId, u8 option)
{
    const s16 *cursorPos = &gTasks[taskId].data[sSearchOptions_pokedex[option].taskDataCursorPos];
    const s16 *scrollOffset = &gTasks[taskId].data[sSearchOptions_pokedex[option].taskDataScrollOffset];
    u16 id = *cursorPos + *scrollOffset;

    switch (option)
    {
    default:
        return 0;
    case SEARCH_MODE_pokedex:
        return sPokedexModes_pokedex[id];
    case SEARCH_ORDER_pokedex:
        return sOrderOptions_pokedex[id];
    case SEARCH_NAME_pokedex:
        if (id == 0)
            return 0xFF;
        else
            return id;
    case SEARCH_COLOR_pokedex:
        if (id == 0)
            return 0xFF;
        else
            return id - 1;
    case SEARCH_TYPE_LEFT_pokedex:
    case SEARCH_TYPE_RIGHT_pokedex:
        return sDexSearchTypeIds_pokedex[id];
    }
}

static void SetDefaultSearchModeAndOrder_pokedex(u8 taskId)
{
    u16 selected;

    switch (sPokedexView_pokedex->dexModeBackup)
    {
    default:
    case DEX_MODE_HOENN:
        selected = DEX_MODE_HOENN;
        break;
    case DEX_MODE_NATIONAL:
        selected = DEX_MODE_NATIONAL;
        break;
    }
    gTasks[taskId].tCursorPos_Mode_pokedex = selected;

    switch (sPokedexView_pokedex->dexOrderBackup)
    {
    default:
    case ORDER_NUMERICAL_pokedex:
        selected = ORDER_NUMERICAL_pokedex;
        break;
    case ORDER_ALPHABETICAL_pokedex:
        selected = ORDER_ALPHABETICAL_pokedex;
        break;
    case ORDER_HEAVIEST_pokedex:
        selected = ORDER_HEAVIEST_pokedex;
        break;
    case ORDER_LIGHTEST_pokedex:
        selected = ORDER_LIGHTEST_pokedex;
        break;
    case ORDER_TALLEST_pokedex:
        selected = ORDER_TALLEST_pokedex;
        break;
    case ORDER_SMALLEST_pokedex:
        selected = ORDER_SMALLEST_pokedex;
        break;
    }
    gTasks[taskId].tCursorPos_Order_pokedex = selected;
}

static bool8 SearchParamCantScrollUp_pokedex(u8 taskId)
{
    u8 menuItem = gTasks[taskId].tMenuItem_pokedex;
    const s16 *scrollOffset = &gTasks[taskId].data[sSearchOptions_pokedex[menuItem].taskDataScrollOffset];
    u16 lastOption = sSearchOptions_pokedex[menuItem].numOptions - 1;

    if (lastOption > MAX_SEARCH_PARAM_CURSOR_POS_pokedex && *scrollOffset != 0)
        return FALSE;
    else
        return TRUE;
}

static bool8 SearchParamCantScrollDown_pokedex(u8 taskId)
{
    u8 menuItem = gTasks[taskId].tMenuItem_pokedex;
    const s16 *scrollOffset = &gTasks[taskId].data[sSearchOptions_pokedex[menuItem].taskDataScrollOffset];
    u16 lastOption = sSearchOptions_pokedex[menuItem].numOptions - 1;

    if (lastOption > MAX_SEARCH_PARAM_CURSOR_POS_pokedex && *scrollOffset < lastOption - MAX_SEARCH_PARAM_CURSOR_POS_pokedex)
        return FALSE;
    else
        return TRUE;
}

#define sTaskId_pokedex      data[0]

static void SpriteCB_SearchParameterScrollArrow_pokedex(struct Sprite *sprite)
{
    if (gTasks[sprite->sTaskId_pokedex].func == Task_HandleSearchParameterInput_pokedex)
    {
        u8 val;

        if (sprite->sIsDownArrow_pokedex)
        {
            if (SearchParamCantScrollDown_pokedex(sprite->sTaskId_pokedex))
                sprite->invisible = TRUE;
            else
                sprite->invisible = FALSE;
        }
        else
        {
            if (SearchParamCantScrollUp_pokedex(sprite->sTaskId_pokedex))
                sprite->invisible = TRUE;
            else
                sprite->invisible = FALSE;
        }
        val = sprite->data[2] + sprite->sIsDownArrow_pokedex * 128;
        sprite->y2 = gSineTable[val] / 128;
        sprite->data[2] += 8;
    }
    else
    {
        sprite->invisible = TRUE;
    }
}

static void CreateSearchParameterScrollArrows_pokedex(u8 taskId)
{
    u8 spriteId;

    spriteId = CreateSprite(&sScrollArrowSpriteTemplate_pokedex, 184, 4, 0);
    gSprites[spriteId].sTaskId_pokedex = taskId;
    gSprites[spriteId].sIsDownArrow_pokedex = FALSE;
    gSprites[spriteId].callback = SpriteCB_SearchParameterScrollArrow_pokedex;

    spriteId = CreateSprite(&sScrollArrowSpriteTemplate_pokedex, 184, 108, 0);
    gSprites[spriteId].sTaskId_pokedex = taskId;
    gSprites[spriteId].sIsDownArrow_pokedex = TRUE;
    gSprites[spriteId].vFlip = TRUE;
    gSprites[spriteId].callback = SpriteCB_SearchParameterScrollArrow_pokedex;
}

#undef sTaskId_pokedex
#undef sIsDownArrow_pokedex

static void EraseAndPrintSearchTextBox_pokedex(const u8 *str)
{
    ClearSearchMenuRect_pokedex(8, 120, 224, 32);
    PrintSearchText_pokedex(str, 8, 121);
}

static void EraseSelectorArrow_pokedex(u32 y)
{
    ClearSearchMenuRect_pokedex(144, y * 16 + 8, 8, 16);
}

static void PrintSelectorArrow_pokedex(u32 y)
{
    PrintSearchText_pokedex(gText_SelectorArrow, 144, y * 16 + 9);
}

static void PrintSearchParameterTitle_pokedex(u32 y, const u8 *str)
{
    PrintSearchText_pokedex(str, 152, y * 16 + 9);
}

static void ClearSearchParameterBoxText_pokedex(void)
{
    ClearSearchMenuRect_pokedex(144, 8, 96, 96);
}
