bool8 LoadCryWaveformWindow(struct CryScreenWindow *window, u8 windowId)
{
    u8 i;
    u8 finished = FALSE;

    switch (gDexCryScreenState)
    {
    case 0:
        if (!sDexCryScreen_pokedex_cry_screen)
        {
            sDexCryScreen_pokedex_cry_screen = AllocZeroed(sizeof(*sDexCryScreen_pokedex_cry_screen));
            sCryWaveformWindowTiledata_pokedex_cry_screen = (u8 *)GetWindowAttribute(windowId, WINDOW_TILE_DATA);
        }

        sDexCryScreen_pokedex_cry_screen->unk = window->unk0;
        sDexCryScreen_pokedex_cry_screen->playStartPos = window->yPos;
        sDexCryScreen_pokedex_cry_screen->cryOverrideCountdown = 0;
        sDexCryScreen_pokedex_cry_screen->cryRepeatDelay = 0;
        sDexCryScreen_pokedex_cry_screen->cryState = 0;
        sDexCryScreen_pokedex_cry_screen->waveformPreviousY = WAVEFORM_WINDOW_HEIGHT_pokedex_cry_screen / 2;
        sDexCryScreen_pokedex_cry_screen->playhead = 0;
        ShiftWaveformOver_pokedex_cry_screen(windowId, -8 * window->xPos, TRUE); // Does nothing
        for (i = 0; i < 224; i++)
            CopyToWindowPixelBuffer(windowId, sCryScreenBg_Gfx_pokedex_cry_screen, TILE_SIZE_4BPP, i);

        gDexCryScreenState++;
        break;
    case 1:
        for (i = 0; i < sDexCryScreen_pokedex_cry_screen->playStartPos * 8; i++)
            DrawWaveformSegment_pokedex_cry_screen(i, 0);

        gDexCryScreenState++;
        break;
    case 2:
        DrawWaveformWindow_pokedex_cry_screen(windowId);
        LoadPalette(sCryScreenBg_Pal_pokedex_cry_screen, BG_PLTT_ID(window->paletteNo), PLTT_SIZE_4BPP);
        finished = TRUE;
        break;
    }

    return finished;
}

void UpdateCryWaveformWindow(u8 windowId)
{
    u8 waveformIdx;

    DrawWaveformWindow_pokedex_cry_screen(windowId);
    AdvancePlayhead_pokedex_cry_screen(windowId);

    // Cry cant be replayed until this counter is done
    if (sDexCryScreen_pokedex_cry_screen->cryRepeatDelay)
        sDexCryScreen_pokedex_cry_screen->cryRepeatDelay--;

    // Once a cry replay has started, it waits for this countdown before playing
    if (sDexCryScreen_pokedex_cry_screen->cryOverrideCountdown)
    {
        sDexCryScreen_pokedex_cry_screen->cryOverrideCountdown--;
        if (!sDexCryScreen_pokedex_cry_screen->cryOverrideCountdown)
        {
            PlayCryScreenCry_pokedex_cry_screen(sDexCryScreen_pokedex_cry_screen->species);
            DrawWaveformFlatline_pokedex_cry_screen();
            return;
        }
    }

    // No cry playing
    if (sDexCryScreen_pokedex_cry_screen->cryState == 0)
    {
        DrawWaveformFlatline_pokedex_cry_screen();
        return;
    }

    // Cry playing, buffer waveform
    if (sDexCryScreen_pokedex_cry_screen->cryState == 1)
    {
        BufferCryWaveformSegment_pokedex_cry_screen();
    }
    else if (sDexCryScreen_pokedex_cry_screen->cryState > 8)
    {
        // Buffered waveform exhausted, end or buffer more
        if (!IsCryPlaying())
        {
            DrawWaveformFlatline_pokedex_cry_screen();
            sDexCryScreen_pokedex_cry_screen->cryState = 0;
            return;
        }

        BufferCryWaveformSegment_pokedex_cry_screen();
        sDexCryScreen_pokedex_cry_screen->cryState = 1;
    }

    // Draw cry
    waveformIdx = 2 * (sDexCryScreen_pokedex_cry_screen->cryState - 1);
    DrawWaveformSegment_pokedex_cry_screen(sDexCryScreen_pokedex_cry_screen->playStartPos * 8 + sDexCryScreen_pokedex_cry_screen->playhead - 2, sDexCryScreen_pokedex_cry_screen->cryWaveformBuffer[waveformIdx]);
    DrawWaveformSegment_pokedex_cry_screen(sDexCryScreen_pokedex_cry_screen->playStartPos * 8 + sDexCryScreen_pokedex_cry_screen->playhead - 1, sDexCryScreen_pokedex_cry_screen->cryWaveformBuffer[waveformIdx + 1]);
    sDexCryScreen_pokedex_cry_screen->cryState++;
}

void CryScreenPlayButton(u16 species)
{
    if (gMPlayInfo_BGM.status & MUSICPLAYER_STATUS_PAUSE && !sDexCryScreen_pokedex_cry_screen->cryOverrideCountdown)
    {
        if (!sDexCryScreen_pokedex_cry_screen->cryRepeatDelay)
        {
            sDexCryScreen_pokedex_cry_screen->cryRepeatDelay = 4;
            if (IsCryPlaying() == TRUE)
            {
                StopCry();
                sDexCryScreen_pokedex_cry_screen->species = species;
                sDexCryScreen_pokedex_cry_screen->cryOverrideCountdown = 2;
            }
            else
            {
                PlayCryScreenCry_pokedex_cry_screen(species);
            }
        }
    }
}

static void PlayCryScreenCry_pokedex_cry_screen(u16 species)
{
    PlayCry_NormalNoDucking(species, 0, CRY_VOLUME_RS, CRY_PRIORITY_NORMAL);
    sDexCryScreen_pokedex_cry_screen->cryState = 1;
}

static void BufferCryWaveformSegment_pokedex_cry_screen(void)
{
    u8 i;
    s8 *baseBuffer;
    s8 *buffer;

    if (gPcmDmaCounter < 2)
        baseBuffer = gSoundInfo.pcmBuffer;
    else
        baseBuffer = gSoundInfo.pcmBuffer + (gSoundInfo.pcmDmaPeriod + 1 - gPcmDmaCounter) * gSoundInfo.pcmSamplesPerVBlank;

    buffer = baseBuffer + PCM_DMA_BUF_SIZE;
    for (i = 0; i < ARRAY_COUNT(sDexCryScreen_pokedex_cry_screen->cryWaveformBuffer); i++)
        sDexCryScreen_pokedex_cry_screen->cryWaveformBuffer[i] = buffer[i * 2] * 2;
}

static void DrawWaveformFlatline_pokedex_cry_screen(void)
{
    DrawWaveformSegment_pokedex_cry_screen(sDexCryScreen_pokedex_cry_screen->playStartPos * 8 + sDexCryScreen_pokedex_cry_screen->playhead - 2, 0);
    DrawWaveformSegment_pokedex_cry_screen(sDexCryScreen_pokedex_cry_screen->playStartPos * 8 + sDexCryScreen_pokedex_cry_screen->playhead - 1, 0);
}

static void AdvancePlayhead_pokedex_cry_screen(u8 windowId)
{
    u8 i;
    u16 offset;

    ShiftWaveformOver_pokedex_cry_screen(windowId, sDexCryScreen_pokedex_cry_screen->playhead, FALSE);
    sDexCryScreen_pokedex_cry_screen->playhead += 2;
    offset = (sDexCryScreen_pokedex_cry_screen->playhead / 8 + sDexCryScreen_pokedex_cry_screen->playStartPos + 1) % 32;
    for (i = 0; i < 7; i++)
        CopyToWindowPixelBuffer(windowId, sCryScreenBg_Gfx_pokedex_cry_screen, TILE_SIZE_4BPP, offset + (i * TILE_SIZE_4BPP));
}

// Waveform segments are drawn in alternate vertical slices
// Note that the waveform isnt put on screen until DrawWaveformWindow_pokedex_cry_screen
static void DrawWaveformSegment_pokedex_cry_screen(u8 position, u8 amplitude)
{
    // Position is a bitfield containing the play start pos, the playhead pos, and which vertical slice half to draw
    #define PLAY_START_POS_pokedex_cry_screen (position >> 3)
    #define PLAYHEAD_POS_pokedex_cry_screen   (position & ((1 << 3) - 1))
    #define VERT_SLICE_pokedex_cry_screen     (position & 1)

    u8 currentPointY;
    u8 nybble;
    u16 offset;
    u16 temp;
    u8 y;

    temp = (amplitude + 127) * 256;
    y = temp / 1152.0;
    if (y > WAVEFORM_WINDOW_HEIGHT_pokedex_cry_screen - 1)
        y = WAVEFORM_WINDOW_HEIGHT_pokedex_cry_screen - 1;
    currentPointY = y;
    nybble = VERT_SLICE_pokedex_cry_screen;
    if (y > sDexCryScreen_pokedex_cry_screen->waveformPreviousY)
    {
        // Current point lower than previous point, draw point and draw line up to previous
        do
        {
            offset = sWaveformOffsets_pokedex_cry_screen[PLAYHEAD_POS_pokedex_cry_screen][y] + PLAY_START_POS_pokedex_cry_screen * TILE_SIZE_4BPP;
            sCryWaveformWindowTiledata_pokedex_cry_screen[offset] &= sWaveformTileDataNybbleMasks_pokedex_cry_screen[nybble];
            sCryWaveformWindowTiledata_pokedex_cry_screen[offset] |= sWaveformColor_pokedex_cry_screen[nybble][((y / 3) - 1) & 0x0F];
            y--;
        } while (y > sDexCryScreen_pokedex_cry_screen->waveformPreviousY);
    }
    else
    {
        // Current point higher than previous point, draw point and draw line down to previous
        do
        {
            offset = sWaveformOffsets_pokedex_cry_screen[PLAYHEAD_POS_pokedex_cry_screen][y] + PLAY_START_POS_pokedex_cry_screen * TILE_SIZE_4BPP;
            sCryWaveformWindowTiledata_pokedex_cry_screen[offset] &= sWaveformTileDataNybbleMasks_pokedex_cry_screen[nybble];
            sCryWaveformWindowTiledata_pokedex_cry_screen[offset] |= sWaveformColor_pokedex_cry_screen[nybble][((y / 3) - 1) & 0x0F];
            y++;
        } while (y < sDexCryScreen_pokedex_cry_screen->waveformPreviousY);
    }

    sDexCryScreen_pokedex_cry_screen->waveformPreviousY = currentPointY;
}

static void DrawWaveformWindow_pokedex_cry_screen(u8 windowId)
{
    CopyWindowToVram(windowId, COPYWIN_GFX);
}

// rsVertical is leftover from a very different version of this function in RS
// In RS, when TRUE it would use VOFS and when FALSE it would use HOFS (only FALSE was used)
// Here when TRUE it does nothing
static void ShiftWaveformOver_pokedex_cry_screen(u8 windowId, s16 offset, bool8 rsVertical)
{
    if (!rsVertical)
    {
        u8 bg = GetWindowAttribute(windowId, WINDOW_BG);
        ChangeBgX(bg, offset << 8, BG_COORD_SET);
    }
}

bool8 LoadCryMeter(struct CryScreenWindow *window, u8 windowId)
{
    bool8 finished = FALSE;

    switch (gDexCryScreenState)
    {
    case 0:
        if (!sCryMeterNeedle_pokedex_cry_screen)
            sCryMeterNeedle_pokedex_cry_screen = AllocZeroed(sizeof(*sCryMeterNeedle_pokedex_cry_screen));

        CopyToWindowPixelBuffer(windowId, sCryMeter_Gfx_pokedex_cry_screen, 0, 0);
        LoadPalette(sCryMeter_Pal_pokedex_cry_screen, BG_PLTT_ID(window->paletteNo), PLTT_SIZE_4BPP);
        gDexCryScreenState++;
        break;
    case 1:
        LoadSpriteSheets(sCryMeterNeedleSpriteSheets_pokedex_cry_screen);
        LoadSpritePalettes(sCryMeterNeedleSpritePalettes_pokedex_cry_screen);
        sCryMeterNeedle_pokedex_cry_screen->spriteId = CreateSprite(&sCryMeterNeedleSpriteTemplate_pokedex_cry_screen, 40 + window->xPos * 8, 56 + window->yPos * 8, 1);
        sCryMeterNeedle_pokedex_cry_screen->rotation = MIN_NEEDLE_POS_pokedex_cry_screen;
        sCryMeterNeedle_pokedex_cry_screen->targetRotation = MIN_NEEDLE_POS_pokedex_cry_screen;
        sCryMeterNeedle_pokedex_cry_screen->moveIncrement = 0;
        finished = TRUE;
        break;
    }

    return finished;
}

void FreeCryScreen(void)
{
    FreeSpritePaletteByTag(GetSpritePaletteTagByPaletteNum(gSprites[sCryMeterNeedle_pokedex_cry_screen->spriteId].oam.paletteNum));
    DestroySprite(gSprites + sCryMeterNeedle_pokedex_cry_screen->spriteId);
    FREE_AND_SET_NULL(sDexCryScreen_pokedex_cry_screen);
    FREE_AND_SET_NULL(sCryMeterNeedle_pokedex_cry_screen);
}

static void SpriteCB_CryMeterNeedle_pokedex_cry_screen(struct Sprite *sprite)
{
    u16 i;
    s8 peakAmplitude;
    s16 x;
    s16 y;
    struct ObjAffineSrcData affine;
    struct OamMatrix matrix;
    u8 amplitude;

    gSprites[sCryMeterNeedle_pokedex_cry_screen->spriteId].oam.affineMode = ST_OAM_AFFINE_NORMAL;
    gSprites[sCryMeterNeedle_pokedex_cry_screen->spriteId].oam.affineParam = 0;

    // While no cry is playing, cryState is 0
    // While cry is playing, cryState loops 1-8
    switch (sDexCryScreen_pokedex_cry_screen->cryState)
    {
    case 0:
        sCryMeterNeedle_pokedex_cry_screen->targetRotation = MIN_NEEDLE_POS_pokedex_cry_screen;
        if (sCryMeterNeedle_pokedex_cry_screen->rotation > 0)
        {
            if (sCryMeterNeedle_pokedex_cry_screen->moveIncrement != 1)
                sCryMeterNeedle_pokedex_cry_screen->moveIncrement--;
        }
        else
        {
            sCryMeterNeedle_pokedex_cry_screen->moveIncrement = NEEDLE_MOVE_INCREMENT_pokedex_cry_screen;
        }
        break;
    case 2:
        peakAmplitude = 0;
        for (i = 0; i < ARRAY_COUNT(sDexCryScreen_pokedex_cry_screen->cryWaveformBuffer); i++)
        {
            if (peakAmplitude < sDexCryScreen_pokedex_cry_screen->cryWaveformBuffer[i])
                peakAmplitude = sDexCryScreen_pokedex_cry_screen->cryWaveformBuffer[i];
        }
        SetCryMeterNeedleTarget_pokedex_cry_screen(peakAmplitude * 208 / 256);
        break;
    case 6:
        // To introduce some randomness, needle jumps to set pos in waveform rather than peak
        amplitude = sDexCryScreen_pokedex_cry_screen->cryWaveformBuffer[10];
        SetCryMeterNeedleTarget_pokedex_cry_screen(amplitude * 208 / 256);
        break;
    }

    if (sCryMeterNeedle_pokedex_cry_screen->rotation == sCryMeterNeedle_pokedex_cry_screen->targetRotation)
    {
        // Empty, needle has reached target
    }
    else if (sCryMeterNeedle_pokedex_cry_screen->rotation < sCryMeterNeedle_pokedex_cry_screen->targetRotation)
    {
        // Rotate needle left
        sCryMeterNeedle_pokedex_cry_screen->rotation += sCryMeterNeedle_pokedex_cry_screen->moveIncrement;
        if (sCryMeterNeedle_pokedex_cry_screen->rotation > sCryMeterNeedle_pokedex_cry_screen->targetRotation)
        {
            sCryMeterNeedle_pokedex_cry_screen->rotation = sCryMeterNeedle_pokedex_cry_screen->targetRotation;
            sCryMeterNeedle_pokedex_cry_screen->targetRotation = 0;
        }
    }
    else
    {
        // Rotate needle right
        sCryMeterNeedle_pokedex_cry_screen->rotation -= sCryMeterNeedle_pokedex_cry_screen->moveIncrement;
        if (sCryMeterNeedle_pokedex_cry_screen->rotation < sCryMeterNeedle_pokedex_cry_screen->targetRotation)
        {
            sCryMeterNeedle_pokedex_cry_screen->rotation = sCryMeterNeedle_pokedex_cry_screen->targetRotation;
            sCryMeterNeedle_pokedex_cry_screen->targetRotation = 0;
        }
    }

    affine.xScale = 256;
    affine.yScale = 256;
    affine.rotation = sCryMeterNeedle_pokedex_cry_screen->rotation * 256;
    ObjAffineSet(&affine, &matrix, 1, 2);
    SetOamMatrix(0, matrix.a, matrix.b, matrix.c, matrix.d);
    x = gSineTable[((sCryMeterNeedle_pokedex_cry_screen->rotation + 0x7F) & 0xFF)];
    y = gSineTable[((sCryMeterNeedle_pokedex_cry_screen->rotation + 0x7F) & 0xFF) + 64];
    sprite->x2 = x * 24 / 256;
    sprite->y2 = y * 24 / 256;
}

static void SetCryMeterNeedleTarget_pokedex_cry_screen(s8 offset)
{
    u16 rotation = (MIN_NEEDLE_POS_pokedex_cry_screen - offset) & 0xFF;

    // Min is positive, max is negative. Make sure needle hasnt moved out of bounds
    if (rotation > MIN_NEEDLE_POS_pokedex_cry_screen && rotation < (u8)MAX_NEEDLE_POS_pokedex_cry_screen)
        rotation = (u8)MAX_NEEDLE_POS_pokedex_cry_screen;

    sCryMeterNeedle_pokedex_cry_screen->targetRotation = rotation;
    sCryMeterNeedle_pokedex_cry_screen->moveIncrement = NEEDLE_MOVE_INCREMENT_pokedex_cry_screen;
}

