static void VerticalSquishBounce_pokemon_animation(struct Sprite *sprite)
{
    s16 posY = 0;

    if (sprite->data[2] == 0)
    {
        HandleStartAffineAnim_pokemon_animation(sprite);
        sprite->data[3] = 0;
    }

    TryFlipX_pokemon_animation(sprite);

    if (sprite->data[2] > sprite->data[0] * 3)
    {
        HandleSetAffineData_pokemon_animation(sprite, 256, 256, 0);
        sprite->y2 = 0;
        ResetSpriteAfterAnim_pokemon_animation(sprite);
        sprite->callback = WaitAnimEnd_pokemon_animation;
    }
    else
    {
        s16 yScale = Sin(sprite->data[4], 32) + 256;

        if (sprite->data[2] > sprite->data[0] && sprite->data[2] < sprite->data[0] * 2)
            sprite->data[3] += (128 / sprite->data[0]);
        if (yScale > 256)
            posY = (256 - yScale) / 8;

        sprite->y2 = -(Sin(sprite->data[3], 10)) - posY;
        HandleSetAffineData_pokemon_animation(sprite, 256 - Sin(sprite->data[4], 32), yScale, 0);
        sprite->data[2]++;
        sprite->data[4] = (sprite->data[4] + 128 / sprite->data[0]) & 0xFF;
    }

    TryFlipX_pokemon_animation(sprite);
}

