static void BounceRotateToSides_pokemon_animation(struct Sprite *sprite)
{
    s16 var;
    u8 structId;
    s8 r9;
    s16 r10;
    s16 r7;
    u32 arrId;

    TryFlipX_pokemon_animation(sprite);
    structId = sprite->data[0];
    var = sAnims_pokemon_animation[structId].rotation;
    r9 = sBounceRotateToSidesData_pokemon_animation[sAnims_pokemon_animation[structId].data][sprite->data[4]][0];
    r10 = sBounceRotateToSidesData_pokemon_animation[sAnims_pokemon_animation[structId].data][sprite->data[4]][1] - r9;
    arrId = sAnims_pokemon_animation[structId].data;
    r7 = sprite->data[3];

    if (sprite->data[2] == 0)
    {
        HandleStartAffineAnim_pokemon_animation(sprite);
        sprite->data[2]++;
    }

    if (sBounceRotateToSidesData_pokemon_animation[arrId][sprite->data[4]][2] == 0)
    {
        HandleSetAffineData_pokemon_animation(sprite, 256, 256, 0);
        sprite->x2 = 0;
        sprite->y2 = 0;
        ResetSpriteAfterAnim_pokemon_animation(sprite);
        sprite->callback = WaitAnimEnd_pokemon_animation;
    }
    else
    {
        u16 rotation;

        sprite->y2 = -(Sin(r7 * 128 / sBounceRotateToSidesData_pokemon_animation[arrId][sprite->data[4]][2], 10));
        sprite->x2 = (r10 * r7 / sBounceRotateToSidesData_pokemon_animation[arrId][sprite->data[4]][2]) + r9;

        rotation = -(var * sprite->x2) / 8;
        HandleSetAffineData_pokemon_animation(sprite, 256, 256, rotation);

        if (r7 == sBounceRotateToSidesData_pokemon_animation[arrId][sprite->data[4]][2])
        {
            sprite->data[4]++;
            sprite->data[3] = 0;
        }
        else
        {
            sprite->data[3]++;
        }
    }

    TryFlipX_pokemon_animation(sprite);
}

static void Anim_BounceRotateToSides_pokemon_animation(struct Sprite *sprite)
{
    u8 id = sprite->data[0] = AddNewAnim_pokemon_animation();
    sAnims_pokemon_animation[id].rotation = 4096;
    sAnims_pokemon_animation[id].data = sprite->data[6];
    BounceRotateToSides_pokemon_animation(sprite);
    sprite->callback = BounceRotateToSides_pokemon_animation;
}

