static void BackAndLunge_0_pokemon_animation(struct Sprite *sprite)
{
    TryFlipX_pokemon_animation(sprite);
    if (++sprite->x2 > 7)
    {
        sprite->x2 = 8;
        sprite->data[7] = 2;
        sprite->callback = BackAndLunge_1_pokemon_animation;
    }
    TryFlipX_pokemon_animation(sprite);
}

static void BackAndLunge_1_pokemon_animation(struct Sprite *sprite)
{
    TryFlipX_pokemon_animation(sprite);

    sprite->x2 -= sprite->data[7];
    sprite->data[7]++;
    if (sprite->x2 <= 0)
    {
        s16 subResult;
        u8 var = sprite->data[7];
        sprite->data[6] = 0;
        subResult = sprite->x2;

        do
        {
            subResult -= var;
            sprite->data[6]++;
            var++;
        }
        while (subResult > -8);

        sprite->data[5] = 1;
        sprite->callback = BackAndLunge_2_pokemon_animation;
    }

    TryFlipX_pokemon_animation(sprite);
}

static void BackAndLunge_2_pokemon_animation(struct Sprite *sprite)
{
    u8 rotation;

    TryFlipX_pokemon_animation(sprite);
    sprite->x2 -= sprite->data[7];
    sprite->data[7]++;
    rotation = (sprite->data[5] * 6) / sprite->data[6];

    if (++sprite->data[5] > sprite->data[6])
        sprite->data[5] = sprite->data[6];

    HandleSetAffineData_pokemon_animation(sprite, 256, 256, rotation * 256);

    if (sprite->x2 < -8)
    {
        sprite->x2 = -8;
        sprite->data[4] = 2;
        sprite->data[3] = 0;
        sprite->data[2] = rotation;
        sprite->callback = BackAndLunge_3_pokemon_animation;
    }

    TryFlipX_pokemon_animation(sprite);
}

static void BackAndLunge_3_pokemon_animation(struct Sprite *sprite)
{
    TryFlipX_pokemon_animation(sprite);

    if (sprite->data[3] > 11)
    {
        sprite->data[2] -= 2;
        if (sprite->data[2] < 0)
            sprite->data[2] = 0;

        HandleSetAffineData_pokemon_animation(sprite, 256, 256, sprite->data[2] << 8);
        if (sprite->data[2] == 0)
            sprite->callback = BackAndLunge_4_pokemon_animation;
    }
    else
    {
        sprite->x2 += sprite->data[4];
        sprite->data[4] *= -1;
        sprite->data[3]++;
    }

    TryFlipX_pokemon_animation(sprite);
}

static void BackAndLunge_4_pokemon_animation(struct Sprite *sprite)
{
    TryFlipX_pokemon_animation(sprite);

    sprite->x2 += 2;
    if (sprite->x2 > 0)
    {
        sprite->x2 = 0;
        ResetSpriteAfterAnim_pokemon_animation(sprite);
        sprite->callback = WaitAnimEnd_pokemon_animation;
    }

    TryFlipX_pokemon_animation(sprite);
}

