static void TumblingFrontFlip_pokemon_animation(struct Sprite *sprite)
{
    if (sAnims_pokemon_animation[sprite->data[0]].delay != 0)
    {
        sAnims_pokemon_animation[sprite->data[0]].delay--;
    }
    else
    {
        TryFlipX_pokemon_animation(sprite);
        if (sprite->data[2] == 0)
        {
            sprite->data[2]++;
            HandleStartAffineAnim_pokemon_animation(sprite);
            sprite->data[7] = sAnims_pokemon_animation[sprite->data[0]].speed;
            sprite->data[3] = -1;
            sprite->data[4] = -1;
            sprite->data[5] = 0;
            sprite->data[6] = 0;
        }

        sprite->x2 += (sprite->data[7] * 2 * sprite->data[3]);
        sprite->y2 += (sprite->data[7] * sprite->data[4]);
        sprite->data[6] += 8;
        if (sprite->x2 <= -16 || sprite->x2 >= 16)
        {
            sprite->x2 = sprite->data[3] * 16;
            sprite->data[3] *= -1;
            sprite->data[5]++;
        }
        else if (sprite->y2 <= -16 || sprite->y2 >= 16)
        {
            sprite->y2 = sprite->data[4] * 16;
            sprite->data[4] *= -1;
            sprite->data[5]++;
        }

        if (sprite->data[5] > 5 && sprite->x2 <= 0)
        {
            sprite->x2 = 0;
            sprite->y2 = 0;
            if (sAnims_pokemon_animation[sprite->data[0]].runs > 1)
            {
                sAnims_pokemon_animation[sprite->data[0]].runs--;
                sprite->data[5] = 0;
                sprite->data[6] = 0;
                sAnims_pokemon_animation[sprite->data[0]].delay = 10;
            }
            else
            {
                ResetSpriteAfterAnim_pokemon_animation(sprite);
                sprite->callback = WaitAnimEnd_pokemon_animation;
            }
        }

        HandleSetAffineData_pokemon_animation(sprite, 256, 256, sprite->data[6] << 8);
        TryFlipX_pokemon_animation(sprite);
    }
}

static void Figure8_pokemon_animation(struct Sprite *sprite);

static void Anim_Figure8_pokemon_animation(struct Sprite *sprite)
{
    HandleStartAffineAnim_pokemon_animation(sprite);
    sprite->data[6] = 0;
    sprite->data[7] = 0;
    sprite->callback = Figure8_pokemon_animation;
}

static void Figure8_pokemon_animation(struct Sprite *sprite)
{
    TryFlipX_pokemon_animation(sprite);
    sprite->data[6] += 4;
    sprite->x2 = -(Sin(sprite->data[6], 16));
    sprite->y2 = -(Sin((sprite->data[6] * 2) & 0xFF, 8));
    if (sprite->data[6] > 192 && sprite->data[7] == 1)
    {
        HandleSetAffineData_pokemon_animation(sprite, 256, 256, 0);
        sprite->data[7]++;
    }
    else if (sprite->data[6] > 64 && sprite->data[7] == 0)
    {
        HandleSetAffineData_pokemon_animation(sprite, -256, 256, 0);
        sprite->data[7]++;
    }

    if (sprite->data[6] > 255)
    {
        sprite->x2 = 0;
        sprite->y2 = 0;
        HandleSetAffineData_pokemon_animation(sprite, 256, 256, 0);
        ResetSpriteAfterAnim_pokemon_animation(sprite);
        sprite->callback = WaitAnimEnd_pokemon_animation;
    }
    TryFlipX_pokemon_animation(sprite);
}

static void Anim_FlashYellow_pokemon_animation(struct Sprite *sprite)
{
    if (++sprite->data[2] == 1)
    {
        sprite->data[7] = OBJ_PLTT_ID(sprite->oam.paletteNum);
        sprite->data[6] = 0;
        sprite->data[5] = 0;
        sprite->data[4] = 0;
    }

    if (sYellowFlashData_pokemon_animation[sprite->data[6]][1] == (u8)-1)
    {
        sprite->callback = WaitAnimEnd_pokemon_animation;
    }
    else
    {
        if (sprite->data[4] == 1)
        {
            if (sYellowFlashData_pokemon_animation[sprite->data[6]][0])
                BlendPalette(sprite->data[7], 16, 16, RGB_YELLOW);
            else
                BlendPalette(sprite->data[7], 16, 0, RGB_YELLOW);

            sprite->data[4] = 0;
        }

        if (sYellowFlashData_pokemon_animation[sprite->data[6]][1] == sprite->data[5])
        {
            sprite->data[4] = 1;
            sprite->data[5] = 0;
            sprite->data[6]++;
        }
        else
        {
            sprite->data[5]++;
        }
    }
}

static void SwingConcave_pokemon_animation(struct Sprite *sprite)
{
    if (sprite->data[2] == 0)
        HandleStartAffineAnim_pokemon_animation(sprite);

    TryFlipX_pokemon_animation(sprite);
    if (sprite->data[2] > sAnims_pokemon_animation[sprite->data[0]].data)
    {
        HandleSetAffineData_pokemon_animation(sprite, 256, 256, 0);
        sprite->x2 = 0;
        if (sAnims_pokemon_animation[sprite->data[0]].runs > 1)
        {
            sAnims_pokemon_animation[sprite->data[0]].runs--;
            sprite->data[2] = 0;
        }
        else
        {
            ResetSpriteAfterAnim_pokemon_animation(sprite);
            sprite->callback = WaitAnimEnd_pokemon_animation;
        }
    }
    else
    {
        s16 index = (sprite->data[2] * 256) / sAnims_pokemon_animation[sprite->data[0]].data;
        sprite->x2 = -(Sin(index, 10));
        HandleSetAffineData_pokemon_animation(sprite, 256, 256, Sin(index, 3276));
    }

    sprite->data[2]++;
    TryFlipX_pokemon_animation(sprite);
}

