static void RotateUpSlamDown_0_pokemon_animation(struct Sprite *sprite);
static void RotateUpSlamDown_1_pokemon_animation(struct Sprite *sprite);
static void RotateUpSlamDown_2_pokemon_animation(struct Sprite *sprite);

static void Anim_RotateUpSlamDown_pokemon_animation(struct Sprite *sprite)
{
    HandleStartAffineAnim_pokemon_animation(sprite);
    sprite->data[6] = -(14 * sprite->centerToCornerVecX / 10);
    sprite->data[7] = 128;
    sprite->callback = RotateUpSlamDown_0_pokemon_animation;
}

static void RotateUpSlamDown_0_pokemon_animation(struct Sprite *sprite)
{
    TryFlipX_pokemon_animation(sprite);
    sprite->data[7]--;
    sprite->x2 = sprite->data[6] + Cos(sprite->data[7], sprite->data[6]);

    sprite->y2 = -(Sin(sprite->data[7], sprite->data[6]));

    HandleSetAffineData_pokemon_animation(sprite, 256, 256, (sprite->data[7] - 128) << 8);
    if (sprite->data[7] <= 120)
    {
        sprite->data[7] = 120;
        sprite->data[3] = 0;
        sprite->callback = RotateUpSlamDown_1_pokemon_animation;
    }

    TryFlipX_pokemon_animation(sprite);
}

static void RotateUpSlamDown_1_pokemon_animation(struct Sprite *sprite)
{
    if (sprite->data[3] == 20)
    {
        sprite->callback = RotateUpSlamDown_2_pokemon_animation;
        sprite->data[3] = 0;
    }

    sprite->data[3]++;
}

static void RotateUpSlamDown_2_pokemon_animation(struct Sprite *sprite)
{
    TryFlipX_pokemon_animation(sprite);
    sprite->data[7] += 2;
    sprite->x2 = sprite->data[6] + Cos(sprite->data[7], sprite->data[6]);

    sprite->y2 = -(Sin(sprite->data[7], sprite->data[6]));

    HandleSetAffineData_pokemon_animation(sprite, 256, 256, (sprite->data[7] - 128) << 8);
    if (sprite->data[7] >= 128)
    {
        sprite->x2 = 0;
        sprite->y2 = 0;
        HandleSetAffineData_pokemon_animation(sprite, 256, 256, 0);
        sprite->data[2] = 0;
        ResetSpriteAfterAnim_pokemon_animation(sprite);
        sprite->callback = Anim_VerticalShake_pokemon_animation;
    }

    TryFlipX_pokemon_animation(sprite);
}

static void DeepVerticalSquishBounce_pokemon_animation(struct Sprite *sprite)
{
    if (sAnims_pokemon_animation[sprite->data[0]].delay != 0)
    {
        sAnims_pokemon_animation[sprite->data[0]].delay--;
    }
    else
    {
        if (sprite->data[2] == 0)
        {
            HandleStartAffineAnim_pokemon_animation(sprite);
            sprite->data[4] = 0;
            sprite->data[5] = 0;
            sprite->data[2] = 1;
        }

        if (sprite->data[5] == 0)
        {
            sprite->data[7] = Sin(sprite->data[4], 256);
            sprite->y2 = Sin(sprite->data[4], 16);
            sprite->data[6] = Sin(sprite->data[4], 32);
            HandleSetAffineData_pokemon_animation(sprite, 256 - sprite->data[6], 256 + sprite->data[7], 0);
            if (sprite->data[4] == 128)
            {
                sprite->data[4] = 0;
                sprite->data[5] = 1;
            }
        }
        else if (sprite->data[5] == 1)
        {
            sprite->data[7] = Sin(sprite->data[4], 32);
            sprite->y2 = -(Sin(sprite->data[4], 8));
            sprite->data[6] = Sin(sprite->data[4], 128);
            HandleSetAffineData_pokemon_animation(sprite, 256 + sprite->data[6], 256 - sprite->data[7], 0);
            if (sprite->data[4] == 128)
            {
                if (sAnims_pokemon_animation[sprite->data[0]].runs > 1)
                {
                    sAnims_pokemon_animation[sprite->data[0]].runs--;
                    sAnims_pokemon_animation[sprite->data[0]].delay = 10;
                    sprite->data[4] = 0;
                    sprite->data[5] = 0;
                }
                else
                {
                    HandleSetAffineData_pokemon_animation(sprite, 256, 256, 0);
                    ResetSpriteAfterAnim_pokemon_animation(sprite);
                    sprite->callback = WaitAnimEnd_pokemon_animation;
                }
            }
        }

        sprite->data[4] += sAnims_pokemon_animation[sprite->data[0]].rotation;
    }
}

static void Anim_DeepVerticalSquishBounce_pokemon_animation(struct Sprite *sprite)
{
    u8 id = sprite->data[0] = AddNewAnim_pokemon_animation();
    sAnims_pokemon_animation[id].rotation = 4;
    DeepVerticalSquishBounce_pokemon_animation(sprite);
    sprite->callback = DeepVerticalSquishBounce_pokemon_animation;
}

static void Anim_HorizontalJumps_pokemon_animation(struct Sprite *sprite)
{
    s32 counter = sprite->data[2];
    TryFlipX_pokemon_animation(sprite);
    if (counter > 512)
    {
        sprite->callback = WaitAnimEnd_pokemon_animation;
        sprite->x2 = 0;
        sprite->y2 = 0;
    }
    else
    {
        switch (sprite->data[2] / 128)
        {
        case 0:
            sprite->x2 = -(counter % 128 * 8) / 128;
            break;
        case 1:
            sprite->x2 = (counter % 128 / 16) - 8;
            break;
        case 2:
            sprite->x2 = (counter % 128 / 16);
            break;
        case 3:
            sprite->x2 = -(counter % 128 * 8) / 128 + 8;
            break;
        }

        sprite->y2 = -(Sin(counter % 128, 8));
    }

    sprite->data[2] += 12;
    TryFlipX_pokemon_animation(sprite);
}

static void HorizontalJumpsVerticalStretch_0_pokemon_animation(struct Sprite *sprite);
static void HorizontalJumpsVerticalStretch_1_pokemon_animation(struct Sprite *sprite);
static void HorizontalJumpsVerticalStretch_2_pokemon_animation(struct Sprite *sprite);

static void Anim_HorizontalJumpsVerticalStretch_pokemon_animation(struct Sprite *sprite)
{
    u8 id = sprite->data[0] = AddNewAnim_pokemon_animation();
    sAnims_pokemon_animation[id].data = -1;
    HandleStartAffineAnim_pokemon_animation(sprite);
    sprite->data[3] = 0;
    HorizontalJumpsVerticalStretch_0_pokemon_animation(sprite);
    sprite->callback = HorizontalJumpsVerticalStretch_0_pokemon_animation;
}

static void HorizontalJumpsVerticalStretch_0_pokemon_animation(struct Sprite *sprite)
{
    if (sAnims_pokemon_animation[sprite->data[0]].delay != 0)
    {
        sAnims_pokemon_animation[sprite->data[0]].delay--;
    }
    else
    {
        s32 counter;

        TryFlipX_pokemon_animation(sprite);
        counter = sprite->data[2];
        if (sprite->data[2] > 128)
        {
            sprite->data[2] = 0;
            sprite->callback = HorizontalJumpsVerticalStretch_1_pokemon_animation;
        }
        else
        {
            s32 var = 8 * sAnims_pokemon_animation[sprite->data[0]].data;
            sprite->x2 = var * (counter % 128) / 128;
            sprite->y2 = -(Sin(counter % 128, 8));
            sprite->data[2] += 12;
        }

        TryFlipX_pokemon_animation(sprite);
    }
}

static void HorizontalJumpsVerticalStretch_1_pokemon_animation(struct Sprite *sprite)
{
    TryFlipX_pokemon_animation(sprite);
    if (sprite->data[2] > 48)
    {
        HandleSetAffineData_pokemon_animation(sprite, 256, 256, 0);
        sprite->y2 = 0;
        sprite->data[2] = 0;
        sprite->callback = HorizontalJumpsVerticalStretch_2_pokemon_animation;
    }
    else
    {
        s16 yDelta;
        s16 yScale = Sin(sprite->data[4], 64) + 256;
        if (sprite->data[2] >= 16 && sprite->data[2] <= 31)
        {
            sprite->data[3] += 8;
            sprite->x2 -= sAnims_pokemon_animation[sprite->data[0]].data;
        }

        yDelta = 0;
        if (yScale > 256)
            yDelta = (256 - yScale) / 8;

        sprite->y2 = -(Sin(sprite->data[3], 20)) - yDelta;
        HandleSetAffineData_pokemon_animation(sprite, 256 - Sin(sprite->data[4], 32), yScale, 0);
        sprite->data[2]++;
        sprite->data[4] += 8;
        sprite->data[4] &= 0xFF;
    }

    TryFlipX_pokemon_animation(sprite);
}

static void HorizontalJumpsVerticalStretch_2_pokemon_animation(struct Sprite *sprite)
{
    s32 counter;

    TryFlipX_pokemon_animation(sprite);
    counter = sprite->data[2];
    if (counter > 128)
    {
        if (sAnims_pokemon_animation[sprite->data[0]].runs > 1)
        {
            sAnims_pokemon_animation[sprite->data[0]].runs--;
            sAnims_pokemon_animation[sprite->data[0]].delay = 10;
            sprite->data[3] = 0;
            sprite->data[2] = 0;
            sprite->data[4] = 0;
            sprite->callback = HorizontalJumpsVerticalStretch_0_pokemon_animation;
        }
        else
        {
            ResetSpriteAfterAnim_pokemon_animation(sprite);
            sprite->callback = WaitAnimEnd_pokemon_animation;
        }

        sprite->x2 = 0;
        sprite->y2 = 0;
    }
    else
    {
        s32 var = sAnims_pokemon_animation[sprite->data[0]].data;

        sprite->x2 = var * ((counter % 128) * 8) / 128 + 8 * -var;
        sprite->y2 = -(Sin(counter % 128, 8));
    }

    sprite->data[2] += 12;
    TryFlipX_pokemon_animation(sprite);
}

static void RotateToSides_pokemon_animation(struct Sprite *sprite)
{
    if (sprite->data[2] == 0)
    {
        HandleStartAffineAnim_pokemon_animation(sprite);
        sprite->data[2]++;
    }

    TryFlipX_pokemon_animation(sprite);
    if (sprite->data[7] > 254)
    {
        sprite->x2 = 0;
        sprite->y2 = 0;
        HandleSetAffineData_pokemon_animation(sprite, 256, 256, 0);
        if (sAnims_pokemon_animation[sprite->data[0]].runs > 1)
        {
            sAnims_pokemon_animation[sprite->data[0]].runs--;
            sprite->data[2] = 0;
            sprite->data[7] = 0;
        }
        else
        {
            ResetSpriteAfterAnim_pokemon_animation(sprite);
            sprite->callback = WaitAnimEnd_pokemon_animation;
        }

        TryFlipX_pokemon_animation(sprite);
    }
    else
    {
        u16 rotation;

        sprite->x2 = -(Sin(sprite->data[7], 16));
        rotation = Sin(sprite->data[7], 32);
        HandleSetAffineData_pokemon_animation(sprite, 256, 256, rotation << 8);
        sprite->data[7] += sAnims_pokemon_animation[sprite->data[0]].rotation;
        TryFlipX_pokemon_animation(sprite);
    }
}

static void Anim_RotateToSides_Fast_pokemon_animation(struct Sprite *sprite)
{
    u8 id = sprite->data[0] = AddNewAnim_pokemon_animation();
    sAnims_pokemon_animation[id].rotation = 4;
    RotateToSides_pokemon_animation(sprite);
    sprite->callback = RotateToSides_pokemon_animation;
}

static void Anim_RotateUpToSides_pokemon_animation(struct Sprite *sprite)
{
    if (sprite->data[2] == 0)
    {
        HandleStartAffineAnim_pokemon_animation(sprite);
        sprite->data[2]++;
    }

    TryFlipX_pokemon_animation(sprite);
    if (sprite->data[7] > 254)
    {
        sprite->x2 = 0;
        sprite->y2 = 0;
        HandleSetAffineData_pokemon_animation(sprite, 256, 256, 0);
        ResetSpriteAfterAnim_pokemon_animation(sprite);
        sprite->callback = WaitAnimEnd_pokemon_animation;
        TryFlipX_pokemon_animation(sprite);
    }
    else
    {
        u16 rotation;

        sprite->x2 = -(Sin(sprite->data[7], 16));
        sprite->y2 = -(Sin(sprite->data[7] % 128, 16));
        rotation = Sin(sprite->data[7], 32);
        HandleSetAffineData_pokemon_animation(sprite, 256, 256, rotation << 8);
        sprite->data[7] += 8;
        TryFlipX_pokemon_animation(sprite);
    }
}

static void Anim_FlickerIncreasing_pokemon_animation(struct Sprite *sprite)
{
    if (sprite->data[2] == 0)
        sprite->data[7] = 0;

    if (sprite->data[2] == sprite->data[7])
    {
        sprite->data[7] = 0;
        sprite->data[2]++;
        sprite->invisible = FALSE;
    }
    else
    {
        sprite->data[7]++;
        sprite->invisible = TRUE;
    }

    if (sprite->data[2] > 10)
    {
        sprite->invisible = FALSE;
        sprite->callback = WaitAnimEnd_pokemon_animation;
    }
}

static void TipHopForward_0_pokemon_animation(struct Sprite *sprite);
static void TipHopForward_1_pokemon_animation(struct Sprite *sprite);
static void TipHopForward_2_pokemon_animation(struct Sprite *sprite);

static void Anim_TipHopForward_pokemon_animation(struct Sprite *sprite)
{
    HandleStartAffineAnim_pokemon_animation(sprite);
    sprite->data[7] = 0;
    sprite->callback = TipHopForward_0_pokemon_animation;
}

static void TipHopForward_0_pokemon_animation(struct Sprite *sprite)
{
    if (sprite->data[7] > 31)
    {
        sprite->data[7] = 32;
        sprite->data[2] = 0;
        sprite->callback = TipHopForward_1_pokemon_animation;
    }
    else
    {
        sprite->data[7] += 4;
    }

    HandleSetAffineData_pokemon_animation(sprite, 256, 256, sprite->data[7] << 8);
}

static void TipHopForward_1_pokemon_animation(struct Sprite *sprite)
{
    TryFlipX_pokemon_animation(sprite);
    if (sprite->data[2] > 512)
    {
        sprite->callback = TipHopForward_2_pokemon_animation;
        sprite->data[6] = 0;
    }
    else
    {
        sprite->x2 = -(sprite->data[2] * 16) / 512;
        sprite->y2 = -(Sin(sprite->data[2] % 128, 4));
        sprite->data[2] += 12;
    }

    TryFlipX_pokemon_animation(sprite);
}

static void TipHopForward_2_pokemon_animation(struct Sprite *sprite)
{
    TryFlipX_pokemon_animation(sprite);
    sprite->data[7] -= 2;
    if (sprite->data[7] < 0)
    {
        sprite->data[7] = 0;
        sprite->x2 = 0;
        ResetSpriteAfterAnim_pokemon_animation(sprite);
        sprite->callback = WaitAnimEnd_pokemon_animation;
    }
    else
    {
        sprite->x2 = -(Sin(sprite->data[7] * 2, 16));
    }

    HandleSetAffineData_pokemon_animation(sprite, 256, 256, sprite->data[7] << 8);
    TryFlipX_pokemon_animation(sprite);
}

static void Anim_PivotShake_pokemon_animation(struct Sprite *sprite)
{
    u16 rotation;

    if (sprite->data[2] == 0)
    {
        HandleStartAffineAnim_pokemon_animation(sprite);
        sprite->data[2]++;
        sprite->data[7] = 0;
    }

    TryFlipX_pokemon_animation(sprite);
    if (sprite->data[7] > 255)
    {
        sprite->x2 = 0;
        sprite->y2 = 0;
        sprite->data[7] = 0;
        ResetSpriteAfterAnim_pokemon_animation(sprite);
        sprite->callback = WaitAnimEnd_pokemon_animation;
    }
    else
    {
        sprite->data[7] += 16;
        sprite->x2 = -(Sin(sprite->data[7] % 128, 8));
        sprite->y2 = -(Sin(sprite->data[7] % 128, 8));
    }

    rotation = Sin(sprite->data[7] % 128, 16);
    HandleSetAffineData_pokemon_animation(sprite, 256, 256, rotation << 8);
    TryFlipX_pokemon_animation(sprite);
}

static void TipAndShake_0_pokemon_animation(struct Sprite *sprite);
static void TipAndShake_1_pokemon_animation(struct Sprite *sprite);
static void TipAndShake_2_pokemon_animation(struct Sprite *sprite);
static void TipAndShake_3_pokemon_animation(struct Sprite *sprite);

static void Anim_TipAndShake_pokemon_animation(struct Sprite *sprite)
{
    HandleStartAffineAnim_pokemon_animation(sprite);
    sprite->data[7] = 0;
    sprite->data[4] = 0;
    sprite->callback = TipAndShake_0_pokemon_animation;
}

static void TipAndShake_0_pokemon_animation(struct Sprite *sprite)
{
    TryFlipX_pokemon_animation(sprite);
    if (sprite->data[7] > 24)
    {
        if (++sprite->data[4] > 4)
        {
            sprite->data[4] = 0;
            sprite->callback = TipAndShake_1_pokemon_animation;
        }
    }
    else
    {
        sprite->data[7] += 2;
        sprite->x2 = Sin(sprite->data[7], 8);
        sprite->y2 = -(Sin(sprite->data[7], 8));
    }

    HandleSetAffineData_pokemon_animation(sprite, 256, 256, -(sprite->data[7]) << 8);
    TryFlipX_pokemon_animation(sprite);
}

static void TipAndShake_1_pokemon_animation(struct Sprite *sprite)
{
    TryFlipX_pokemon_animation(sprite);
    if (sprite->data[7] > 32)
    {
        sprite->data[6] = 1;
        sprite->callback = TipAndShake_2_pokemon_animation;
    }
    else
    {
        sprite->data[7] += 2;
        sprite->x2 = Sin(sprite->data[7], 8);
        sprite->y2 = -(Sin(sprite->data[7], 8));
    }

    HandleSetAffineData_pokemon_animation(sprite, 256, 256, -(sprite->data[7]) << 8);
    TryFlipX_pokemon_animation(sprite);
}

static void TipAndShake_2_pokemon_animation(struct Sprite *sprite)
{
    TryFlipX_pokemon_animation(sprite);
    sprite->data[7] += (sprite->data[6] * 4);
    if (sprite->data[5] > 9)
    {
        sprite->data[7] = 32;
        sprite->callback = TipAndShake_3_pokemon_animation;
    }

    sprite->x2 = Sin(sprite->data[7], 8);
    sprite->y2 = -(Sin(sprite->data[7], 8));
    if (sprite->data[7] <= 28 || sprite->data[7] >= 36)
    {
        sprite->data[6] *= -1;
        sprite->data[5]++;
    }

    HandleSetAffineData_pokemon_animation(sprite, 256, 256, -(sprite->data[7]) << 8);
    TryFlipX_pokemon_animation(sprite);
}

static void TipAndShake_3_pokemon_animation(struct Sprite *sprite)
{
    TryFlipX_pokemon_animation(sprite);
    if (sprite->data[7] <= 0)
    {
        sprite->data[7] = 0;
        ResetSpriteAfterAnim_pokemon_animation(sprite);
        sprite->callback = WaitAnimEnd_pokemon_animation;
    }
    else
    {
        sprite->data[7] -= 2;
        sprite->x2 = Sin(sprite->data[7], 8);
        sprite->y2 = -(Sin(sprite->data[7], 8));
    }

    HandleSetAffineData_pokemon_animation(sprite, 256, 256, -(sprite->data[7]) << 8);
    TryFlipX_pokemon_animation(sprite);
}

static void Anim_VibrateToCorners_pokemon_animation(struct Sprite *sprite)
{
    TryFlipX_pokemon_animation(sprite);
    if (sprite->data[2] > 40)
    {
        sprite->callback = WaitAnimEnd_pokemon_animation;
        sprite->x2 = 0;
    }
    else
    {
        s8 sign;
        if (!(sprite->data[2] & 1))
            sign = 1;
        else
            sign = -1;

        if ((sprite->data[2] % 4) / 2 == 0)
        {
            sprite->x2 = Sin((sprite->data[2] * 128 / 40) % 256, 16) * sign;
            sprite->y2 = -(sprite->x2);
        }
        else
        {
            sprite->x2 = -(Sin((sprite->data[2] * 128 / 40) % 256, 16)) * sign;
            sprite->y2 = sprite->x2;
        }
    }

    sprite->data[2]++;
    TryFlipX_pokemon_animation(sprite);
}

static void Anim_GrowInStages_pokemon_animation(struct Sprite *sprite)
{
    TryFlipX_pokemon_animation(sprite);
    if (sprite->data[2] == 0)
    {
        HandleStartAffineAnim_pokemon_animation(sprite);
        sprite->data[5] = 0;
        sprite->data[6] = 0;
        sprite->data[7] = 0;
        sprite->data[2]++;
    }

    if (sprite->data[6] > 0)
    {
        sprite->data[6]--;
        if (sprite->data[5] != 3)
        {
            s16 scale = (8 * sprite->data[6]) / 20;
            scale = Sin(sprite->data[7] - scale, 64);
            HandleSetAffineData_pokemon_animation(sprite, 256 - scale, 256 - scale, 0);
        }
    }
    else
    {
        s16 var;

        if (sprite->data[5] == 3)
        {
            if (sprite->data[7] > 63)
            {
                sprite->data[7] = 64;
                HandleSetAffineData_pokemon_animation(sprite, 256, 256, 0);
                ResetSpriteAfterAnim_pokemon_animation(sprite);
                sprite->callback = WaitAnimEnd_pokemon_animation;
            }
            var = Cos(sprite->data[7], 64);
        }
        else
        {
            var = Sin(sprite->data[7], 64);
            if (sprite->data[7] > 63)
            {
                sprite->data[5] = 3;
                sprite->data[6] = 10;
                sprite->data[7] = 0;
            }
            else
            {
                if (var > 48 && sprite->data[5] == 1)
                {
                    sprite->data[5] = 2;
                    sprite->data[6] = 20;
                }
                else if (var > 16 && sprite->data[5] == 0)
                {
                    sprite->data[5] = 1;
                    sprite->data[6] = 20;
                }
            }
        }

        sprite->data[7] += 2;
        HandleSetAffineData_pokemon_animation(sprite, 256 - var, 256 - var, 0);
    }

    TryFlipX_pokemon_animation(sprite);
}

static void Anim_VerticalSpring_pokemon_animation(struct Sprite *sprite)
{
    if (sprite->data[2] == 0)
    {
        HandleStartAffineAnim_pokemon_animation(sprite);
        sprite->data[2]++;
        sprite->data[7] = 0;
    }

    if (sprite->data[7] > 512)
    {
        sprite->y2 = 0;
        HandleSetAffineData_pokemon_animation(sprite, 256, 256, 0);
        ResetSpriteAfterAnim_pokemon_animation(sprite);
        sprite->callback = WaitAnimEnd_pokemon_animation;
    }
    else
    {
        s16 yScale;

        sprite->y2 = Sin(sprite->data[7] % 256, 8);
        sprite->data[7] += 8;
        yScale = Sin(sprite->data[7] % 128, 96);
        HandleSetAffineData_pokemon_animation(sprite, 256, yScale + 256, 0);
    }
}

