static void TriangleDown_pokemon_animation(struct Sprite *sprite)
{
    TryFlipX_pokemon_animation(sprite);
    if (sprite->data[2] == 0)
        sprite->data[3] = 0;

    if (sTriangleDownData_pokemon_animation[sprite->data[3]][2] / sprite->data[5] == sprite->data[2])
    {
        sprite->data[3]++;
        sprite->data[2] = 0;
    }

    if (sTriangleDownData_pokemon_animation[sprite->data[3]][2] / sprite->data[5] == 0)
    {
        if (--sprite->data[6] == 0)
            sprite->callback = WaitAnimEnd_pokemon_animation;
        else
            sprite->data[2] = 0;
    }
    else
    {
        s32 amplitude = sprite->data[5];
        sprite->x2 += (sTriangleDownData_pokemon_animation[sprite->data[3]][0] * amplitude);
        sprite->y2 += (sTriangleDownData_pokemon_animation[sprite->data[3]][1] * sprite->data[5]); // Not using amplitude here. No reason for this.
        sprite->data[2]++;
        TryFlipX_pokemon_animation(sprite);
    }
}

