static void SetHorizontalDip_pokemon_animation(struct Sprite *sprite)
{
    u16 index = Sin((sprite->data[2] * 128) / sprite->data[7], sprite->data[5]);
    sprite->data[6] = -(index << 8);
    SetPosForRotation_pokemon_animation(sprite, index, sprite->data[4], 0);
    HandleSetAffineData_pokemon_animation(sprite, 256, 256, sprite->data[6]);
}

static void Anim_HorizontalDip_pokemon_animation(struct Sprite *sprite)
{
    if (sprite->data[2] == 0)
    {
        HandleStartAffineAnim_pokemon_animation(sprite);
        sprite->data[7] = 60;
        sprite->data[5] = 8;
        sprite->data[4] = -32;
        sprite->data[3] = 1;
        sprite->data[0] = 0;
    }

    if (sprite->data[2] > sprite->data[7])
    {
        HandleSetAffineData_pokemon_animation(sprite, 256, 256, 0);
        sprite->x2 = 0;
        sprite->y2 = 0;
        sprite->data[0]++;
        if (sprite->data[3] <= sprite->data[0])
        {
            ResetSpriteAfterAnim_pokemon_animation(sprite);
            sprite->callback = WaitAnimEnd_pokemon_animation;
            return;
        }
        else
        {
            sprite->data[2] = 0;
        }
    }
    else
    {
        SetHorizontalDip_pokemon_animation(sprite);
    }

    sprite->data[2]++;
}

