{
    if (sprite->data[2] == 0)
    {
        HandleStartAffineAnim_pokemon_animation(sprite);
        sprite->y2 += 2;
        sprite->data[6] = 40;
        sprite->data[7] = 80;
    }

    ShrinkGrowVibrate_pokemon_animation(sprite);
}

