enum {
    SHAKEGLOW_RED_pokemon_animation,
    SHAKEGLOW_GREEN_pokemon_animation,
    SHAKEGLOW_BLUE_pokemon_animation,
    SHAKEGLOW_BLACK_pokemon_animation,
    SHAKEGLOW_WHITE_pokemon_animation,
    SHAKEGLOW_PURPLE_pokemon_animation
};

static void ShakeGlow_Blend_pokemon_animation(struct Sprite *sprite)
{
static const u16  sColors_pokemon_animation[] =
    {
        [SHAKEGLOW_RED_pokemon_animation]   = RGB_RED,
        [SHAKEGLOW_GREEN_pokemon_animation] = RGB_GREEN,
        [SHAKEGLOW_BLUE_pokemon_animation]  = RGB_BLUE,
        [SHAKEGLOW_BLACK_pokemon_animation] = RGB_BLACK,
        [SHAKEGLOW_WHITE_pokemon_animation] = RGB_WHITE,
        [SHAKEGLOW_PURPLE_pokemon_animation] = RGB_PURPLE
    };

    if (sprite->data[2] > 127)
    {
        BlendPalette(sprite->data[7], 16, 0, RGB_RED);
        sprite->callback = WaitAnimEnd_pokemon_animation;
    }
    else
    {
        sprite->data[6] = Sin(sprite->data[2], 12);
        BlendPalette(sprite->data[7], 16, sprite->data[6], sColors_pokemon_animation[sprite->data[1]]);
    }
}

static void ShakeGlow_Move_pokemon_animation(struct Sprite *sprite)
{
    if (sprite->data[3] < sprite->data[4])
    {
        TryFlipX_pokemon_animation(sprite);
        if (sprite->data[5] > sprite->data[0])
        {
            if (++sprite->data[3] < sprite->data[4])
                sprite->data[5] = 0;

            sprite->x2 = 0;
        }
        else
        {
            s8 sign = 1 - (sprite->data[3] % 2 * 2);
            sprite->x2 = sign * Sin((sprite->data[5] * 384 / sprite->data[0]) % 256, 6);
            sprite->data[5]++;
        }

        TryFlipX_pokemon_animation(sprite);
    }
}

static void Anim_ShakeGlowRed_Fast_pokemon_animation(struct Sprite *sprite)
{
    if (sprite->data[2] == 0)
    {
        sprite->data[7] = OBJ_PLTT_ID(sprite->oam.paletteNum);
        sprite->data[0] = 10;
        sprite->data[5] = 0;
        sprite->data[4] = 2;
        sprite->data[3] = 0;
        sprite->data[1] = SHAKEGLOW_RED_pokemon_animation;
    }

    if (sprite->data[2] % 2 == 0)
        ShakeGlow_Blend_pokemon_animation(sprite);

    if (sprite->data[2] >= (128 - sprite->data[0] * sprite->data[4]) / 2)
        ShakeGlow_Move_pokemon_animation(sprite);

    sprite->data[2]++;
}

static void Anim_ShakeGlowRed_pokemon_animation(struct Sprite *sprite)
{
    if (sprite->data[2] == 0)
    {
        sprite->data[7] = OBJ_PLTT_ID(sprite->oam.paletteNum);
        sprite->data[0] = 20;
        sprite->data[5] = 0;
        sprite->data[4] = 1;
        sprite->data[3] = 0;
        sprite->data[1] = SHAKEGLOW_RED_pokemon_animation;
    }

    if (sprite->data[2] % 2 == 0)
        ShakeGlow_Blend_pokemon_animation(sprite);

    if (sprite->data[2] >= (128 - sprite->data[0] * sprite->data[4]) / 2)
        ShakeGlow_Move_pokemon_animation(sprite);

    sprite->data[2]++;
}

