// Used to compare limits for vineStateTimer
// The upper 8 bits of vineStateTimer are the vine state,
// the lower 8 bits are a timer to the next state.
// When the timer is incremented above 255, it increments
// the vine state and the timer is reset.
#define VINE_STATE_TIMER_pokemon_jump(vineState) (((vineState) << 8) | 0xFF)

enum {
    MONSTATE_NORMAL, // Pokémon is either on the ground or in the middle of a jump
    MONSTATE_JUMP,   // Pokémon has begun a jump
    MONSTATE_HIT,    // Pokémon got hit by the vine
};

enum {
    JUMPSTATE_NONE_pokemon_jump,
    JUMPSTATE_SUCCESS, // Cleared vine
    JUMPSTATE_FAILURE, // Hit vine
};

#define PLAY_AGAIN_NO_pokemon_jump  1
#define PLAY_AGAIN_YES_pokemon_jump 2

#define TAG_MON1_pokemon_jump 0
#define TAG_MON2_pokemon_jump 1 // MON2-5 used implicitly by adding multiplayer id to tag
#define TAG_MON3_pokemon_jump 2
#define TAG_MON4_pokemon_jump 3
#define TAG_MON5_pokemon_jump 4

#define GFXTAG_VINE1_pokemon_jump     5
#define GFXTAG_VINE2_pokemon_jump     6
#define GFXTAG_VINE3_pokemon_jump     7
#define GFXTAG_VINE4_pokemon_jump     8
