#define TAG_DIGITS_pokemon_jump 800

#define VINE_SPRITES_PER_SIDE_pokemon_jump 4 // Vine rope is divided into 8 sprites, 4 per side copied and flipped horizontally

// Used by SetLinkTimeInterval_pokemon_jump to get a bit mask for capping
// a timer that controls how frequently link data is sent.
#define LINK_INTERVAL_NONE_pokemon_jump   0
#define LINK_INTERVAL_SHORT_pokemon_jump  3 // 3 frame interval
#define LINK_INTERVAL_MEDIUM_pokemon_jump 4 // 7 frame interval
#define LINK_INTERVAL_LONG_pokemon_jump   5 // 15 frame interval

#define LINK_TIMER_STOPPED_pokemon_jump 0x1111

