void StartPokemonJump(u16 partyId, MainCallback exitCallback)
{
    u8 taskId;

    if (gReceivedRemoteLinkPlayers)
    {
        sPokemonJump_pokemon_jump = Alloc(sizeof(*sPokemonJump_pokemon_jump));
        if (sPokemonJump_pokemon_jump)
        {
            ResetTasks();
            taskId = CreateTask(Task_StartPokemonJump_pokemon_jump, 1);
            sPokemonJump_pokemon_jump->mainState = 0;
            sPokemonJump_pokemon_jump->exitCallback = exitCallback;
            sPokemonJump_pokemon_jump->taskId = taskId;
            sPokemonJump_pokemon_jump->multiplayerId = GetMultiplayerId();
            InitJumpMonInfo_pokemon_jump(&sPokemonJump_pokemon_jump->monInfo[sPokemonJump_pokemon_jump->multiplayerId], &gPlayerParty[partyId]);
            InitGame_pokemon_jump(sPokemonJump_pokemon_jump);
            SetWordTaskArg(taskId, 2, (u32)sPokemonJump_pokemon_jump);
            SetMainCallback2(CB2_PokemonJump_pokemon_jump);
            return;
        }
    }

    // Exit - Players not connected, or alloc failed
    SetMainCallback2(exitCallback);
}

static void FreePokemonJump_pokemon_jump(void)
{
    FreeWindowsAndDigitObj_pokemon_jump();
    Free(sPokemonJump_pokemon_jump);
}

static void InitGame_pokemon_jump(struct PokemonJump *jump)
{
    jump->numPlayers = GetLinkPlayerCount();
    jump->comm.funcId = FUNC_RESET_GAME_pokemon_jump;
    jump->comm.data = 0;
    InitPlayerAndJumpTypes_pokemon_jump();
    ResetForNewGame_pokemon_jump(jump);
    if (jump->numPlayers == MAX_RFU_PLAYERS)
        IncrementGamesWithMaxPlayers_pokemon_jump();
}

static void ResetForNewGame_pokemon_jump(struct PokemonJump *jump)
{
    int i;

    jump->vineState = VINE_UPSWING_LOWER_pokemon_jump;
    jump->prevVineState = VINE_UPSWING_LOWER_pokemon_jump;
    jump->vineTimer = 0;
    jump->vineSpeed = 0;
    jump->updateScore = FALSE;
    jump->isLeader = GetMultiplayerId() == 0;
    jump->mainState = 0;
    jump->helperState = 0;
    jump->excellentsInRow = 0;
    jump->excellentsInRowRecord = 0;
    jump->initScoreUpdate = FALSE;
    jump->unused2 = 0;
    jump->unused3 = 0;
    jump->numPlayersAtPeak = 0;
    jump->allowVineUpdates = FALSE;
    jump->allPlayersReady = FALSE;
    jump->funcActive = TRUE;
    jump->comm.jumpScore = 0;
    jump->comm.receivedBonusFlags = 0;
    jump->comm.jumpsInRow = 0;
    jump->unused4 = TRUE;
    jump->showBonus = FALSE;
    jump->skipJumpUpdate = FALSE;
    jump->giveBonus = FALSE;
    jump->linkTimer = 0;
    jump->linkTimerLimit = 0;
    ResetPlayersForNewGame_pokemon_jump();
    ResetPlayersJumpStates_pokemon_jump();

    for (i = 0; i < MAX_RFU_PLAYERS; i++)
    {
        jump->atJumpPeak[i] = FALSE;
        jump->jumpTimeStarts[i] = 0;
    }
}

static void InitPlayerAndJumpTypes_pokemon_jump(void)
{
    int i, index;

    for (i = 0; i < MAX_RFU_PLAYERS; i++)
    {
        index = GetPokemonJumpSpeciesIdx_pokemon_jump(sPokemonJump_pokemon_jump->monInfo[i].species);
        sPokemonJump_pokemon_jump->players[i].monJumpType = sPokeJumpMons_pokemon_jump[index].jumpType;
    }

    sPokemonJump_pokemon_jump->player = &sPokemonJump_pokemon_jump->players[sPokemonJump_pokemon_jump->multiplayerId];
}

static void ResetPlayersForNewGame_pokemon_jump(void)
{
    int i;

    for (i = 0; i < MAX_RFU_PLAYERS; i++)
    {
        sPokemonJump_pokemon_jump->players[i].jumpTimeStart = 0;
        sPokemonJump_pokemon_jump->players[i].monState = MONSTATE_NORMAL;
        sPokemonJump_pokemon_jump->players[i].prevMonState = MONSTATE_NORMAL;
        sPokemonJump_pokemon_jump->players[i].jumpOffset = 0;
        sPokemonJump_pokemon_jump->players[i].jumpOffsetIdx = INT_MAX;
        sPokemonJump_pokemon_jump->players[i].jumpState = JUMPSTATE_NONE_pokemon_jump;
        sPokemonJump_pokemon_jump->memberFuncIds[i] = FUNC_NONE_pokemon_jump;
    }
}

static s16 GetPokemonJumpSpeciesIdx_pokemon_jump(u16 species)
{
    u32 i;
    for (i = 0; i < ARRAY_COUNT(sPokeJumpMons_pokemon_jump); i++)
    {
        if (sPokeJumpMons_pokemon_jump[i].species == species)
            return i;
    }

    return -1; // species isnt allowed
}

static void InitJumpMonInfo_pokemon_jump(struct PokemonJump_MonInfo *monInfo, struct Pokemon *mon)
{
    monInfo->species = GetMonData(mon, MON_DATA_SPECIES);
    monInfo->otId = GetMonData(mon, MON_DATA_OT_ID);
    monInfo->isShiny = GetMonData(mon, MON_DATA_IS_SHINY);
    monInfo->personality = GetMonData(mon, MON_DATA_PERSONALITY);
}

static void VBlankCB_PokemonJump_pokemon_jump(void)
{
    TransferPlttBuffer();
    LoadOam();
    ProcessSpriteCopyRequests();
}

static void CB2_PokemonJump_pokemon_jump(void)
{
    RunTasks();
    AnimateSprites();
    BuildOamBuffer();
    UpdatePaletteFade();
}

static void SetPokeJumpTask_pokemon_jump(TaskFunc func)
{
    sPokemonJump_pokemon_jump->taskId = CreateTask(func, 1);
    sPokemonJump_pokemon_jump->mainState = 0;
}

static void Task_StartPokemonJump_pokemon_jump(u8 taskId)
{
    switch (sPokemonJump_pokemon_jump->mainState)
    {
    case 0:
        SetVBlankCallback(NULL);
        ResetSpriteData();
        FreeAllSpritePalettes();
        SetTaskWithPokeJumpStruct_pokemon_jump(Task_CommunicateMonInfo_pokemon_jump, 5);
        FadeOutMapMusic(4);
        sPokemonJump_pokemon_jump->mainState++;
        break;
    case 1:
        if (!FuncIsActiveTask(Task_CommunicateMonInfo_pokemon_jump))
        {
            StartPokeJumpGfx_pokemon_jump(&sPokemonJump_pokemon_jump->jumpGfx);
            LoadWirelessStatusIndicatorSpriteGfx();
            CreateWirelessStatusIndicatorSprite(0, 0);
            sPokemonJump_pokemon_jump->mainState++;
        }
        break;
    case 2:
        if (!IsPokeJumpGfxFuncFinished_pokemon_jump() && IsNotWaitingForBGMStop() == TRUE)
        {
            FadeOutAndPlayNewMapMusic(MUS_RG_POKE_JUMP, 8);
            sPokemonJump_pokemon_jump->mainState++;
        }
        break;
    case 3:
        if (IsLinkTaskFinished())
        {
            BlendPalettes(PALETTES_ALL, 16, RGB_BLACK);
            BeginNormalPaletteFade(PALETTES_ALL, -1, 16, 0, RGB_BLACK);
            SetVBlankCallback(VBlankCB_PokemonJump_pokemon_jump);
            sPokemonJump_pokemon_jump->mainState++;
        }
        break;
    case 4:
        UpdatePaletteFade();
        if (!gPaletteFade.active)
        {
            sPokemonJump_pokemon_jump->startDelayTimer = 0;
            sPokemonJump_pokemon_jump->mainState++;
        }
        break;
    case 5:
        sPokemonJump_pokemon_jump->startDelayTimer++;
        if (sPokemonJump_pokemon_jump->startDelayTimer >= 20)
        {
            if (sPokemonJump_pokemon_jump->isLeader)
                SetPokeJumpTask_pokemon_jump(Task_PokemonJump_Leader_pokemon_jump);
            else
                SetPokeJumpTask_pokemon_jump(Task_PokemonJump_Member_pokemon_jump);

            InitVineState_pokemon_jump();
            DestroyTask(taskId);
        }
        break;
    }
}

static void SetLinkTimeInterval_pokemon_jump(int intervalId)
{
    if (intervalId == LINK_INTERVAL_NONE_pokemon_jump)
    {
        // Link data is sent when timer reaches 0.
        // Set timer to 1 and set limit to special
        // 'stopped' value so timer won't change
        sPokemonJump_pokemon_jump->linkTimerLimit = LINK_TIMER_STOPPED_pokemon_jump;
        sPokemonJump_pokemon_jump->linkTimer = 1;
    }
    else
    {
        sPokemonJump_pokemon_jump->linkTimerLimit = (1 << (intervalId - 1)) - 1;
        sPokemonJump_pokemon_jump->linkTimer = 0;
    }
}

static void SetFunc_Leader_pokemon_jump(u8 funcId)
{
    int i;

    sPokemonJump_pokemon_jump->comm.funcId = funcId;
    sPokemonJump_pokemon_jump->mainState = 0;
    sPokemonJump_pokemon_jump->helperState = 0;
    sPokemonJump_pokemon_jump->funcActive = TRUE;
    sPokemonJump_pokemon_jump->allPlayersReady = FALSE;
    for (i = 1; i < sPokemonJump_pokemon_jump->numPlayers; i++)
        sPokemonJump_pokemon_jump->players[i].funcFinished = FALSE;
}

static void RecvLinkData_Leader_pokemon_jump(void)
{
    int i;
    int numReady;
    u16 monState;
    u8 funcId;
    u16 playAgainState;

    for (i = 1, numReady = 0; i < sPokemonJump_pokemon_jump->numPlayers; i++)
    {
        monState = sPokemonJump_pokemon_jump->players[i].monState;
        if (RecvPacket_MemberStateToLeader_pokemon_jump(&sPokemonJump_pokemon_jump->players[i], i, &funcId, &playAgainState))
        {
            sPokemonJump_pokemon_jump->playAgainStates[i] = playAgainState;
            sPokemonJump_pokemon_jump->memberFuncIds[i] = funcId;
            sPokemonJump_pokemon_jump->players[i].prevMonState = monState;
        }

        // Group member has finished currently assigned function
        if (sPokemonJump_pokemon_jump->players[i].funcFinished && sPokemonJump_pokemon_jump->memberFuncIds[i] == sPokemonJump_pokemon_jump->comm.funcId)
            numReady++;
    }

    if (numReady == sPokemonJump_pokemon_jump->numPlayers - 1)
        sPokemonJump_pokemon_jump->allPlayersReady = TRUE;
}

static bool32 (* const sPokeJumpLeaderFuncs[])(void) =
{
    [FUNC_GAME_INTRO_pokemon_jump]     = GameIntro_Leader_pokemon_jump,
    [FUNC_WAIT_ROUND_pokemon_jump]     = WaitRound_Leader_pokemon_jump,
    [FUNC_GAME_ROUND_pokemon_jump]     = GameRound_Leader_pokemon_jump,
    [FUNC_GAME_OVER_pokemon_jump]      = GameOver_Leader_pokemon_jump,
    [FUNC_ASK_PLAY_AGAIN_pokemon_jump] = AskPlayAgain_Leader_pokemon_jump,
    [FUNC_RESET_GAME_pokemon_jump]     = ResetGame_Leader_pokemon_jump,
    [FUNC_EXIT_pokemon_jump]           = ExitGame_pokemon_jump,
    [FUNC_GIVE_PRIZE_pokemon_jump]     = GivePrize_Leader_pokemon_jump,
    [FUNC_SAVE_pokemon_jump]           = SavePokeJump_pokemon_jump,
};

static void Task_PokemonJump_Leader_pokemon_jump(u8 taskId)
{
    RecvLinkData_Leader_pokemon_jump();
    TryUpdateScore_pokemon_jump();
    if (!sPokemonJump_pokemon_jump->funcActive && sPokemonJump_pokemon_jump->allPlayersReady)
    {
        SetFunc_Leader_pokemon_jump(sPokemonJump_pokemon_jump->nextFuncId);
        SetLinkTimeInterval_pokemon_jump(LINK_INTERVAL_SHORT_pokemon_jump);
    }

    if (sPokemonJump_pokemon_jump->funcActive == TRUE)
    {
        if (!sPokeJumpLeaderFuncs[sPokemonJump_pokemon_jump->comm.funcId]())
        {
            sPokemonJump_pokemon_jump->funcActive = FALSE;
            sPokemonJump_pokemon_jump->players[sPokemonJump_pokemon_jump->multiplayerId].funcFinished = TRUE;
        }
    }

    UpdateGame_pokemon_jump();
    SendLinkData_Leader_pokemon_jump();
}

static void SendLinkData_Leader_pokemon_jump(void)
{
    if (!sPokemonJump_pokemon_jump->linkTimer)
        SendPacket_LeaderState_pokemon_jump(sPokemonJump_pokemon_jump->players, &sPokemonJump_pokemon_jump->comm);

    if (sPokemonJump_pokemon_jump->linkTimerLimit != LINK_TIMER_STOPPED_pokemon_jump)
    {
        sPokemonJump_pokemon_jump->linkTimer++;
        sPokemonJump_pokemon_jump->linkTimer &= sPokemonJump_pokemon_jump->linkTimerLimit;
    }
}

static void SetFunc_Member_pokemon_jump(u8 funcId)
{
    sPokemonJump_pokemon_jump->comm.funcId = funcId;
    sPokemonJump_pokemon_jump->mainState = 0;
    sPokemonJump_pokemon_jump->helperState = 0;
    sPokemonJump_pokemon_jump->funcActive = TRUE;
    sPokemonJump_pokemon_jump->players[sPokemonJump_pokemon_jump->multiplayerId].funcFinished = FALSE;
}

static void RecvLinkData_Member_pokemon_jump(void)
{
    int i;
    u16 monState;
    struct PokemonJump_CommData leaderData;

    monState = sPokemonJump_pokemon_jump->players[0].monState;
    if (RecvPacket_LeaderState_pokemon_jump(sPokemonJump_pokemon_jump->players, &leaderData))
    {
        if (sPokemonJump_pokemon_jump->players[sPokemonJump_pokemon_jump->multiplayerId].funcFinished == TRUE
         && leaderData.funcId != sPokemonJump_pokemon_jump->comm.funcId)
        {
            SetFunc_Member_pokemon_jump(leaderData.funcId);
        }

        if (sPokemonJump_pokemon_jump->comm.jumpScore != leaderData.jumpScore)
        {
            sPokemonJump_pokemon_jump->comm.jumpScore = leaderData.jumpScore;
            sPokemonJump_pokemon_jump->updateScore = TRUE;
            sPokemonJump_pokemon_jump->comm.receivedBonusFlags = leaderData.receivedBonusFlags;
            if (sPokemonJump_pokemon_jump->comm.receivedBonusFlags)
                sPokemonJump_pokemon_jump->showBonus = TRUE;
            else
                sPokemonJump_pokemon_jump->showBonus = FALSE;
        }

        sPokemonJump_pokemon_jump->comm.data = leaderData.data;
        sPokemonJump_pokemon_jump->comm.jumpsInRow = leaderData.jumpsInRow;
        sPokemonJump_pokemon_jump->players[0].prevMonState = monState;
    }

    for (i = 1; i < sPokemonJump_pokemon_jump->numPlayers; i++)
    {
        if (i != sPokemonJump_pokemon_jump->multiplayerId)
        {
            monState = sPokemonJump_pokemon_jump->players[i].monState;
            if (RecvPacket_MemberStateToMember_pokemon_jump(&sPokemonJump_pokemon_jump->players[i], i))
                sPokemonJump_pokemon_jump->players[i].prevMonState = monState;
        }
    }
}

static bool32 (* const sPokeJumpMemberFuncs[])(void) =
{
    [FUNC_GAME_INTRO_pokemon_jump]     = GameIntro_Member_pokemon_jump,
    [FUNC_WAIT_ROUND_pokemon_jump]     = WaitRound_Member_pokemon_jump,
    [FUNC_GAME_ROUND_pokemon_jump]     = GameRound_Member_pokemon_jump,
    [FUNC_GAME_OVER_pokemon_jump]      = GameOver_Member_pokemon_jump,
    [FUNC_ASK_PLAY_AGAIN_pokemon_jump] = AskPlayAgain_Member_pokemon_jump,
    [FUNC_RESET_GAME_pokemon_jump]     = ResetGame_Member_pokemon_jump,
    [FUNC_EXIT_pokemon_jump]           = ExitGame_pokemon_jump,
    [FUNC_GIVE_PRIZE_pokemon_jump]     = GivePrize_Member_pokemon_jump,
    [FUNC_SAVE_pokemon_jump]           = SavePokeJump_pokemon_jump,
};

static void Task_PokemonJump_Member_pokemon_jump(u8 taskId)
{
    RecvLinkData_Member_pokemon_jump();
    if (sPokemonJump_pokemon_jump->funcActive)
    {
        if (!sPokeJumpMemberFuncs[sPokemonJump_pokemon_jump->comm.funcId]())
        {
            sPokemonJump_pokemon_jump->funcActive = FALSE;
            sPokemonJump_pokemon_jump->players[sPokemonJump_pokemon_jump->multiplayerId].funcFinished = TRUE;
            SetLinkTimeInterval_pokemon_jump(LINK_INTERVAL_SHORT_pokemon_jump);
        }
    }

    UpdateGame_pokemon_jump();
    SendLinkData_Member_pokemon_jump();
}

static void SendLinkData_Member_pokemon_jump(void)
{
    if (!sPokemonJump_pokemon_jump->linkTimer)
        SendPacket_MemberState_pokemon_jump(&sPokemonJump_pokemon_jump->players[sPokemonJump_pokemon_jump->multiplayerId], sPokemonJump_pokemon_jump->comm.funcId, sPokemonJump_pokemon_jump->playAgainComm);

    if (sPokemonJump_pokemon_jump->linkTimerLimit != LINK_TIMER_STOPPED_pokemon_jump)
    {
        sPokemonJump_pokemon_jump->linkTimer++;
        sPokemonJump_pokemon_jump->linkTimer &= sPokemonJump_pokemon_jump->linkTimerLimit;
    }
}

static bool32 GameIntro_Leader_pokemon_jump(void)
{
    switch (sPokemonJump_pokemon_jump->mainState)
    {
    case 0:
        SetLinkTimeInterval_pokemon_jump(LINK_INTERVAL_SHORT_pokemon_jump);
        sPokemonJump_pokemon_jump->mainState++;
        // fall through
    case 1:
        if (!DoGameIntro_pokemon_jump())
        {
            sPokemonJump_pokemon_jump->comm.data = sPokemonJump_pokemon_jump->vineTimer;
            sPokemonJump_pokemon_jump->nextFuncId = FUNC_WAIT_ROUND_pokemon_jump;
            return FALSE;
        }
        break;
    }

    return TRUE;
}

static bool32 GameIntro_Member_pokemon_jump(void)
{
    switch (sPokemonJump_pokemon_jump->mainState)
    {
    case 0:
        SetLinkTimeInterval_pokemon_jump(LINK_INTERVAL_NONE_pokemon_jump);
        sPokemonJump_pokemon_jump->rngSeed = sPokemonJump_pokemon_jump->comm.data;
        sPokemonJump_pokemon_jump->mainState++;
        // fall through
    case 1:
        return DoGameIntro_pokemon_jump();
    }

    return TRUE;
}

static bool32 WaitRound_Leader_pokemon_jump(void)
{
    switch (sPokemonJump_pokemon_jump->mainState)
    {
    case 0:
        ResetPlayersJumpStates_pokemon_jump();
        SetLinkTimeInterval_pokemon_jump(LINK_INTERVAL_LONG_pokemon_jump);
        sPokemonJump_pokemon_jump->mainState++;
        break;
    case 1:
        if (sPokemonJump_pokemon_jump->allPlayersReady)
        {
            sPokemonJump_pokemon_jump->nextFuncId = FUNC_GAME_ROUND_pokemon_jump;
            return FALSE;
        }
        break;
    }

    return TRUE;
}

static bool32 WaitRound_Member_pokemon_jump(void)
{
    switch (sPokemonJump_pokemon_jump->mainState)
    {
    case 0:
        ResetPlayersJumpStates_pokemon_jump();
        SetLinkTimeInterval_pokemon_jump(LINK_INTERVAL_NONE_pokemon_jump);
        sPokemonJump_pokemon_jump->vineTimer = sPokemonJump_pokemon_jump->comm.data;
        sPokemonJump_pokemon_jump->mainState++;
        // fall through
    case 1:
        if (AreLinkQueuesEmpty_pokemon_jump())
            return FALSE;
        break;
    }

    return TRUE;
}

static bool32 GameRound_Leader_pokemon_jump(void)
{
    if (!HandleSwingRound_pokemon_jump())
    {
        sPokemonJump_pokemon_jump->comm.data = sPokemonJump_pokemon_jump->vineTimer;
        sPokemonJump_pokemon_jump->nextFuncId = FUNC_WAIT_ROUND_pokemon_jump;
    }
    else if (UpdateVineHitStates_pokemon_jump())
    {
        return TRUE;
    }
    else
    {
        // Someone hit the vine
        ResetVineAfterHit_pokemon_jump();
        sPokemonJump_pokemon_jump->nextFuncId = FUNC_GAME_OVER_pokemon_jump;
    }

    return FALSE;
}

static bool32 GameRound_Member_pokemon_jump(void)
{
    if (!HandleSwingRound_pokemon_jump())
        ;
    else if (UpdateVineHitStates_pokemon_jump())
        return TRUE;
    else // Someone hit the vine
        ResetVineAfterHit_pokemon_jump();

    return FALSE;
}

static bool32 GameOver_Leader_pokemon_jump(void)
{
    switch (sPokemonJump_pokemon_jump->mainState)
    {
    case 0:
        UpdateVineHitStates_pokemon_jump();
        if (AllPlayersJumpedOrHit_pokemon_jump())
            sPokemonJump_pokemon_jump->mainState++;
        break;
    case 1:
        if (!DoVineHitEffect_pokemon_jump())
        {
            if (HasEnoughScoreForPrize_pokemon_jump())
            {
                sPokemonJump_pokemon_jump->comm.data = GetPrizeData_pokemon_jump();
                sPokemonJump_pokemon_jump->nextFuncId = FUNC_GIVE_PRIZE_pokemon_jump;
            }
            else if (sPokemonJump_pokemon_jump->comm.jumpsInRow >= 200)
            {
                sPokemonJump_pokemon_jump->comm.data = sPokemonJump_pokemon_jump->excellentsInRowRecord;
                sPokemonJump_pokemon_jump->nextFuncId = FUNC_SAVE_pokemon_jump;
            }
            else
            {
                sPokemonJump_pokemon_jump->comm.data = sPokemonJump_pokemon_jump->excellentsInRowRecord;
                sPokemonJump_pokemon_jump->nextFuncId = FUNC_ASK_PLAY_AGAIN_pokemon_jump;
            }

            sPokemonJump_pokemon_jump->mainState++;
            return FALSE;
        }
        break;
    case 2:
        return FALSE;
    }

    return TRUE;
}

static bool32 GameOver_Member_pokemon_jump(void)
{
    switch (sPokemonJump_pokemon_jump->mainState)
    {
    case 0:
        if (!UpdateVineHitStates_pokemon_jump())
            ResetVineAfterHit_pokemon_jump();
        if (AllPlayersJumpedOrHit_pokemon_jump())
            sPokemonJump_pokemon_jump->mainState++;
        break;
    case 1:
        if (!DoVineHitEffect_pokemon_jump())
        {
            sPokemonJump_pokemon_jump->mainState++;
            return FALSE;
        }
        break;
    case 2:
        return FALSE;
    }

    return TRUE;
}

static bool32 AskPlayAgain_Leader_pokemon_jump(void)
{
    switch (sPokemonJump_pokemon_jump->mainState)
    {
    case 0:
        SetLinkTimeInterval_pokemon_jump(LINK_INTERVAL_MEDIUM_pokemon_jump);
        sPokemonJump_pokemon_jump->mainState++;
        // fall through
    case 1:
        if (!DoPlayAgainPrompt_pokemon_jump())
        {
            TryUpdateRecords_pokemon_jump(sPokemonJump_pokemon_jump->comm.jumpScore, sPokemonJump_pokemon_jump->comm.jumpsInRow, sPokemonJump_pokemon_jump->comm.data);
            sPokemonJump_pokemon_jump->mainState++;
        }
        break;
    case 2:
        if (sPokemonJump_pokemon_jump->allPlayersReady)
        {
            if (ShouldPlayAgain_pokemon_jump())
                sPokemonJump_pokemon_jump->nextFuncId = FUNC_RESET_GAME_pokemon_jump;
            else
                sPokemonJump_pokemon_jump->nextFuncId = FUNC_EXIT_pokemon_jump;

            sPokemonJump_pokemon_jump->mainState++;
            return FALSE;
        }
        break;
    case 3:
        return FALSE;
    }

    return TRUE;
}

static bool32 AskPlayAgain_Member_pokemon_jump(void)
{
    switch (sPokemonJump_pokemon_jump->mainState)
    {
    case 0:
        SetLinkTimeInterval_pokemon_jump(LINK_INTERVAL_NONE_pokemon_jump);
        sPokemonJump_pokemon_jump->mainState++;
        // fall through
    case 1:
        if (!DoPlayAgainPrompt_pokemon_jump())
        {
            TryUpdateRecords_pokemon_jump(sPokemonJump_pokemon_jump->comm.jumpScore, sPokemonJump_pokemon_jump->comm.jumpsInRow, sPokemonJump_pokemon_jump->comm.data);
            sPokemonJump_pokemon_jump->playAgainComm = sPokemonJump_pokemon_jump->playAgainState;
            return FALSE;
        }
        break;
    }

    return TRUE;
}

static bool32 ResetGame_Leader_pokemon_jump(void)
{
    switch (sPokemonJump_pokemon_jump->mainState)
    {
    case 0:
        if (!CloseMessageAndResetScore_pokemon_jump())
            sPokemonJump_pokemon_jump->mainState++;
        break;
    case 1:
        if (sPokemonJump_pokemon_jump->allPlayersReady)
        {
            ResetForNewGame_pokemon_jump(sPokemonJump_pokemon_jump);
            sPokemonJump_pokemon_jump->rngSeed = Random();
            sPokemonJump_pokemon_jump->comm.data = sPokemonJump_pokemon_jump->rngSeed;
            sPokemonJump_pokemon_jump->nextFuncId = FUNC_GAME_INTRO_pokemon_jump;
            return FALSE;
        }
        break;
    }

    return TRUE;
}

static bool32 ResetGame_Member_pokemon_jump(void)
{
    switch (sPokemonJump_pokemon_jump->mainState)
    {
    case 0:
        if (!CloseMessageAndResetScore_pokemon_jump())
        {
            ResetForNewGame_pokemon_jump(sPokemonJump_pokemon_jump);
            sPokemonJump_pokemon_jump->mainState++;
            return FALSE;
        }
        break;
    case 1:
        return FALSE;
    }

    return TRUE;
}

static bool32 ExitGame_pokemon_jump(void)
{
    switch (sPokemonJump_pokemon_jump->mainState)
    {
    case 0:
        sPokemonJump_pokemon_jump->mainState = 1;
        break;
    case 1:
        SetLinkTimeInterval_pokemon_jump(LINK_INTERVAL_NONE_pokemon_jump);
        sPokemonJump_pokemon_jump->mainState++;
        break;
    case 2:
        if (!ClosePokeJumpLink_pokemon_jump())
        {
            SetMainCallback2(sPokemonJump_pokemon_jump->exitCallback);
            FreePokemonJump_pokemon_jump();
        }
        break;
    }

    return TRUE;
}

static bool32 GivePrize_Leader_pokemon_jump(void)
{
    switch (sPokemonJump_pokemon_jump->mainState)
    {
    case 0:
        SetLinkTimeInterval_pokemon_jump(LINK_INTERVAL_MEDIUM_pokemon_jump);
        sPokemonJump_pokemon_jump->mainState++;
        break;
    case 1:
        if (!TryGivePrize_pokemon_jump())
        {
            sPokemonJump_pokemon_jump->comm.data = sPokemonJump_pokemon_jump->excellentsInRowRecord;
            sPokemonJump_pokemon_jump->nextFuncId = FUNC_SAVE_pokemon_jump;
            return FALSE;
        }
        break;
    }

    return TRUE;
}

static bool32 GivePrize_Member_pokemon_jump(void)
{
    SetLinkTimeInterval_pokemon_jump(LINK_INTERVAL_NONE_pokemon_jump);
    if (!TryGivePrize_pokemon_jump())
        return FALSE;
    else
        return TRUE;
}

static bool32 SavePokeJump_pokemon_jump(void)
{
    switch (sPokemonJump_pokemon_jump->mainState)
    {
    case 0:
        TryUpdateRecords_pokemon_jump(sPokemonJump_pokemon_jump->comm.jumpScore, sPokemonJump_pokemon_jump->comm.jumpsInRow, sPokemonJump_pokemon_jump->comm.data);
        SetUpPokeJumpGfxFuncById_pokemon_jump(GFXFUNC_MSG_SAVING_pokemon_jump);
        sPokemonJump_pokemon_jump->mainState++;
        break;
    case 1:
        if (!IsPokeJumpGfxFuncFinished_pokemon_jump())
        {
            SetLinkTimeInterval_pokemon_jump(LINK_INTERVAL_NONE_pokemon_jump);
            sPokemonJump_pokemon_jump->mainState++;
        }
        break;
    case 2:
        if (AreLinkQueuesEmpty_pokemon_jump())
        {
            CreateTask(Task_LinkFullSave, 6);
            sPokemonJump_pokemon_jump->mainState++;
        }
        break;
    case 3:
        if (!FuncIsActiveTask(Task_LinkFullSave))
        {
            ClearMessageWindow_pokemon_jump();
            sPokemonJump_pokemon_jump->mainState++;
        }
        break;
    case 4:
        if (!RemoveMessageWindow_pokemon_jump())
        {
            sPokemonJump_pokemon_jump->nextFuncId = FUNC_ASK_PLAY_AGAIN_pokemon_jump;
            return FALSE;
        }
        break;
    }

    return TRUE;
}

static bool32 DoGameIntro_pokemon_jump(void)
{
    switch (sPokemonJump_pokemon_jump->helperState)
    {
    case 0:
        SetUpPokeJumpGfxFuncById_pokemon_jump(GFXFUNC_SHOW_NAMES_HIGHLIGHT_pokemon_jump);
        ResetMonSpriteSubpriorities_pokemon_jump();
        sPokemonJump_pokemon_jump->helperState++;
        break;
    case 1:
        if (!IsPokeJumpGfxFuncFinished_pokemon_jump())
        {
            StartMonIntroBounce_pokemon_jump(sPokemonJump_pokemon_jump->multiplayerId);
            sPokemonJump_pokemon_jump->timer = 0;
            sPokemonJump_pokemon_jump->helperState++;
        }
        break;
    case 2:
        if (++sPokemonJump_pokemon_jump->timer > 120)
        {
            SetUpPokeJumpGfxFuncById_pokemon_jump(GFXFUNC_ERASE_NAMES_pokemon_jump);
            sPokemonJump_pokemon_jump->helperState++;
        }
        break;
    case 3:
        if (IsPokeJumpGfxFuncFinished_pokemon_jump() != TRUE && IsMonIntroBounceActive_pokemon_jump() != TRUE)
            sPokemonJump_pokemon_jump->helperState++;
        break;
    case 4:
        SetUpPokeJumpGfxFuncById_pokemon_jump(GFXFUNC_COUNTDOWN_pokemon_jump);
        sPokemonJump_pokemon_jump->helperState++;
        break;
    case 5:
        if (!IsPokeJumpGfxFuncFinished_pokemon_jump())
        {
            DisallowVineUpdates_pokemon_jump();
            SetUpResetVineGfx_pokemon_jump();
            sPokemonJump_pokemon_jump->helperState++;
        }
        break;
    case 6:
        if (!ResetVineGfx_pokemon_jump())
        {
            AllowVineUpdates_pokemon_jump();
            ResetVineState_pokemon_jump();
            sPokemonJump_pokemon_jump->helperState++;
            return FALSE;
        }
        break;
    case 7:
        return FALSE;
    }

    return TRUE;
}

// Update the vine and wait for player to input a jump
// Returns false when vine reaches the 'hit' point, after
// which input is ignored
static bool32 HandleSwingRound_pokemon_jump(void)
{
    UpdateVineState_pokemon_jump();
    if (sPokemonJump_pokemon_jump->ignoreJumpInput)
    {
        sPokemonJump_pokemon_jump->ignoreJumpInput = FALSE;
        return FALSE;
    }

    switch (sPokemonJump_pokemon_jump->helperState)
    {
    case 0:
        if (IsPlayersMonState_pokemon_jump(MONSTATE_NORMAL))
            sPokemonJump_pokemon_jump->helperState++;
        else
            break;
        // fall through
    case 1:
        if (JOY_NEW(A_BUTTON))
        {
            SetMonStateJump_pokemon_jump();
            SetLinkTimeInterval_pokemon_jump(LINK_INTERVAL_SHORT_pokemon_jump);
            sPokemonJump_pokemon_jump->helperState++;
        }
        break;
    case 2:
        if (IsPlayersMonState_pokemon_jump(MONSTATE_JUMP) == TRUE)
            sPokemonJump_pokemon_jump->helperState++;
        break;
    case 3:
        if (IsPlayersMonState_pokemon_jump(MONSTATE_NORMAL) == TRUE)
            sPokemonJump_pokemon_jump->helperState = 0;
        break;
    }

    return TRUE;
}

static bool32 DoVineHitEffect_pokemon_jump(void)
{
    int i;

    switch (sPokemonJump_pokemon_jump->helperState)
    {
    case 0:
        for (i = 0; i < sPokemonJump_pokemon_jump->numPlayers; i++)
        {
            if (IsMonHitShakeActive_pokemon_jump(i) == TRUE)
                return TRUE;
        }

        sPokemonJump_pokemon_jump->helperState++;
        break;
    case 1:
        for (i = 0; i < sPokemonJump_pokemon_jump->numPlayers; i++)
        {
            if (sPokemonJump_pokemon_jump->players[i].monState == MONSTATE_HIT)
                StartMonHitFlash_pokemon_jump(i);
        }

        SetUpPokeJumpGfxFuncById_pokemon_jump(GFXFUNC_SHOW_NAMES_pokemon_jump);
        sPokemonJump_pokemon_jump->timer = 0;
        sPokemonJump_pokemon_jump->helperState++;
        break;
    case 2:
        if (++sPokemonJump_pokemon_jump->timer > 100)
        {
            SetUpPokeJumpGfxFuncById_pokemon_jump(GFXFUNC_ERASE_NAMES_pokemon_jump);
            sPokemonJump_pokemon_jump->timer = 0;
            sPokemonJump_pokemon_jump->helperState++;
        }
        break;
    case 3:
        if (!IsPokeJumpGfxFuncFinished_pokemon_jump())
        {
            StopMonHitFlash_pokemon_jump();
            sPokemonJump_pokemon_jump->comm.receivedBonusFlags = 0;
            ResetPlayersMonState_pokemon_jump();
            sPokemonJump_pokemon_jump->helperState++;
            return FALSE;
        }
        break;
    case 4:
        return FALSE;
    }

    return TRUE;
}

static bool32 TryGivePrize_pokemon_jump(void)
{
    switch (sPokemonJump_pokemon_jump->helperState)
    {
    case 0:
        UnpackPrizeData_pokemon_jump(sPokemonJump_pokemon_jump->comm.data, &sPokemonJump_pokemon_jump->prizeItemId, &sPokemonJump_pokemon_jump->prizeItemQuantity);
        PrintPrizeMessage_pokemon_jump(sPokemonJump_pokemon_jump->prizeItemId, sPokemonJump_pokemon_jump->prizeItemQuantity);
        sPokemonJump_pokemon_jump->helperState++;
        break;
    case 1:
    case 4:
        if (!DoPrizeMessageAndFanfare_pokemon_jump())
        {
            sPokemonJump_pokemon_jump->timer = 0;
            sPokemonJump_pokemon_jump->helperState++;
        }
        break;
    case 2:
    case 5:
        // Wait to continue after message
        sPokemonJump_pokemon_jump->timer++;
        if (JOY_NEW(A_BUTTON | B_BUTTON) || sPokemonJump_pokemon_jump->timer > 180)
        {
            ClearMessageWindow_pokemon_jump();
            sPokemonJump_pokemon_jump->helperState++;
        }
        break;
    case 3:
        if (!RemoveMessageWindow_pokemon_jump())
        {
            sPokemonJump_pokemon_jump->prizeItemQuantity = GetQuantityLimitedByBag_pokemon_jump(sPokemonJump_pokemon_jump->prizeItemId, sPokemonJump_pokemon_jump->prizeItemQuantity);
            if (sPokemonJump_pokemon_jump->prizeItemQuantity && AddBagItem(sPokemonJump_pokemon_jump->prizeItemId, sPokemonJump_pokemon_jump->prizeItemQuantity))
            {
                if (!CheckBagHasSpace(sPokemonJump_pokemon_jump->prizeItemId, 1))
                {
                    // An item was given successfully, but no room for any more.
                    // It's possible the full prize quantity had to be limited
                    PrintPrizeFilledBagMessage_pokemon_jump(sPokemonJump_pokemon_jump->prizeItemId);
                    sPokemonJump_pokemon_jump->helperState = 4; // Do message
                }
                else
                {
                    sPokemonJump_pokemon_jump->helperState = 6; // Exit
                    break;
                }
            }
            else
            {
                PrintNoRoomForPrizeMessage_pokemon_jump(sPokemonJump_pokemon_jump->prizeItemId);
                sPokemonJump_pokemon_jump->helperState = 4; // Do message
            }
        }
        break;
    case 6:
        if (!RemoveMessageWindow_pokemon_jump())
            return FALSE;
        break;
    }

    return TRUE;
}

static bool32 DoPlayAgainPrompt_pokemon_jump(void)
{
    s8 input;

    switch (sPokemonJump_pokemon_jump->helperState)
    {
    case 0:
        SetUpPokeJumpGfxFuncById_pokemon_jump(GFXFUNC_MSG_PLAY_AGAIN_pokemon_jump);
        sPokemonJump_pokemon_jump->helperState++;
        break;
    case 1:
        if (!IsPokeJumpGfxFuncFinished_pokemon_jump())
            sPokemonJump_pokemon_jump->helperState++;
        break;
    case 2:
        input = HandlePlayAgainInput_pokemon_jump();
        switch (input)
        {
        case MENU_B_PRESSED:
        case 1: // No
            sPokemonJump_pokemon_jump->playAgainState = PLAY_AGAIN_NO_pokemon_jump;
            SetUpPokeJumpGfxFuncById_pokemon_jump(GFXFUNC_ERASE_MSG_pokemon_jump);
            sPokemonJump_pokemon_jump->helperState++;
            break;
        case 0: // Yes
            sPokemonJump_pokemon_jump->playAgainState = PLAY_AGAIN_YES_pokemon_jump;
            SetUpPokeJumpGfxFuncById_pokemon_jump(GFXFUNC_ERASE_MSG_pokemon_jump);
            sPokemonJump_pokemon_jump->helperState++;
            break;
        }
        break;
    case 3:
        if (!IsPokeJumpGfxFuncFinished_pokemon_jump())
            sPokemonJump_pokemon_jump->helperState++;
        break;
    case 4:
        SetUpPokeJumpGfxFuncById_pokemon_jump(GFXFUNC_MSG_COMM_STANDBY_pokemon_jump);
        sPokemonJump_pokemon_jump->helperState++;
        break;
    case 5:
        if (!IsPokeJumpGfxFuncFinished_pokemon_jump())
        {
            sPokemonJump_pokemon_jump->helperState++;
            return FALSE;
        }
        break;
    case 6:
        return FALSE;
    }

    return TRUE;
}

static bool32 ClosePokeJumpLink_pokemon_jump(void)
{
    switch (sPokemonJump_pokemon_jump->helperState)
    {
    case 0:
        ClearMessageWindow_pokemon_jump();
        sPokemonJump_pokemon_jump->helperState++;
        break;
    case 1:
        if (!RemoveMessageWindow_pokemon_jump())
        {
            SetUpPokeJumpGfxFuncById_pokemon_jump(GFXFUNC_MSG_PLAYER_DROPPED_pokemon_jump);
            sPokemonJump_pokemon_jump->helperState++;
        }
        break;
    case 2:
        if (!IsPokeJumpGfxFuncFinished_pokemon_jump())
        {
            sPokemonJump_pokemon_jump->timer = 0;
            sPokemonJump_pokemon_jump->helperState++;
        }
        break;
    case 3:
        if (++sPokemonJump_pokemon_jump->timer > 120)
        {
            BeginNormalPaletteFade(PALETTES_ALL, -1, 0, 16, RGB_BLACK);
            sPokemonJump_pokemon_jump->helperState++;
        }
        break;
    case 4:
        if (!gPaletteFade.active)
        {
            SetCloseLinkCallback();
            sPokemonJump_pokemon_jump->helperState++;
        }
        break;
    case 5:
        if (!gReceivedRemoteLinkPlayers)
            return FALSE;
        break;
    }

    return TRUE;
}

static bool32 CloseMessageAndResetScore_pokemon_jump(void)
{
    switch (sPokemonJump_pokemon_jump->helperState)
    {
    case 0:
        ClearMessageWindow_pokemon_jump();
        PrintScore_pokemon_jump(0);
        sPokemonJump_pokemon_jump->helperState++;
        break;
    case 1:
        if (!RemoveMessageWindow_pokemon_jump())
        {
            sPokemonJump_pokemon_jump->helperState++;
            return FALSE;
        }
        break;
    case 2:
        return FALSE;
    }

    return TRUE;
}

#define tState_pokemon_jump data[0]
#define tNumReceived_pokemon_jump data[1]
#define tReceivedPacket_pokemon_jump(playerId) data[(playerId) + 2]
#define DATAIDX_GAME_STRUCT_pokemon_jump 14

static void Task_CommunicateMonInfo_pokemon_jump(u8 taskId)
{
    int i;
    s16 *data = gTasks[taskId].data;
    struct PokemonJump *jump = (struct PokemonJump *)GetWordTaskArg(taskId, DATAIDX_GAME_STRUCT_pokemon_jump);

    switch (tState_pokemon_jump)
    {
    case 0:
        for (i = 0; i < MAX_RFU_PLAYERS; i++)
            tReceivedPacket_pokemon_jump(i) = FALSE;

        tState_pokemon_jump++;
        // fall through
    case 1:
        SendPacket_MonInfo_pokemon_jump(&jump->monInfo[jump->multiplayerId]);
        for (i = 0; i < MAX_RFU_PLAYERS; i++)
        {
            if (!tReceivedPacket_pokemon_jump(i) && RecvPacket_MonInfo_pokemon_jump(i, &jump->monInfo[i]))
            {
                StringCopy(jump->players[i].name, gLinkPlayers[i].name);
                tReceivedPacket_pokemon_jump(i) = TRUE;
                tNumReceived_pokemon_jump++;
                if (tNumReceived_pokemon_jump == jump->numPlayers)
                {
                    InitPlayerAndJumpTypes_pokemon_jump();
                    DestroyTask(taskId);
                    break;
                }
            }
        }
        break;
    }
}

static void SetTaskWithPokeJumpStruct_pokemon_jump(TaskFunc func, u8 taskPriority)
{
    u8 taskId = CreateTask(func, taskPriority);
    SetWordTaskArg(taskId, DATAIDX_GAME_STRUCT_pokemon_jump, (u32)sPokemonJump_pokemon_jump);
}

#undef tState_pokemon_jump
#undef tNumReceived_pokemon_jump
#undef tReceivedPacket_pokemon_jump
#undef DATAIDX_GAME_STRUCT_pokemon_jump

static void InitVineState_pokemon_jump(void)
{
    sPokemonJump_pokemon_jump->vineTimer = 0;
    sPokemonJump_pokemon_jump->vineState = VINE_UPSWING_LOWER_pokemon_jump;
    sPokemonJump_pokemon_jump->vineStateTimer = 0;
    sPokemonJump_pokemon_jump->vineSpeed = 0;
    sPokemonJump_pokemon_jump->ignoreJumpInput = FALSE;
    sPokemonJump_pokemon_jump->gameOver = FALSE;
}

static void ResetVineState_pokemon_jump(void)
{
    sPokemonJump_pokemon_jump->vineTimer = 0;
    sPokemonJump_pokemon_jump->vineStateTimer = VINE_STATE_TIMER_pokemon_jump(VINE_UPSWING_LOWER_pokemon_jump);
    sPokemonJump_pokemon_jump->vineState = VINE_UPSWING_LOW_pokemon_jump;
    sPokemonJump_pokemon_jump->ignoreJumpInput = FALSE;
    sPokemonJump_pokemon_jump->gameOver = FALSE;
    sPokemonJump_pokemon_jump->vineSpeedStage = 0;
    sPokemonJump_pokemon_jump->vineBaseSpeedIdx = 0;
    sPokemonJump_pokemon_jump->vineSpeedAccel = 0;
    sPokemonJump_pokemon_jump->vineSpeedDelay = 0;
    sPokemonJump_pokemon_jump->atMaxSpeedStage = FALSE;
    UpdateVineSpeed_pokemon_jump();
}

static void UpdateVineState_pokemon_jump(void)
{
    if (sPokemonJump_pokemon_jump->allowVineUpdates)
    {
        sPokemonJump_pokemon_jump->vineTimer++;
        sPokemonJump_pokemon_jump->vineStateTimer += GetVineSpeed_pokemon_jump();
        if (sPokemonJump_pokemon_jump->vineStateTimer >= VINE_STATE_TIMER_pokemon_jump(NUM_VINESTATES_pokemon_jump - 1))
            sPokemonJump_pokemon_jump->vineStateTimer -= VINE_STATE_TIMER_pokemon_jump(NUM_VINESTATES_pokemon_jump - 1);

        sPokemonJump_pokemon_jump->prevVineState = sPokemonJump_pokemon_jump->vineState;
        sPokemonJump_pokemon_jump->vineState = sPokemonJump_pokemon_jump->vineStateTimer >> 8;

        // If beginning upswing
        if (sPokemonJump_pokemon_jump->vineState > VINE_UPSWING_LOWER_pokemon_jump && sPokemonJump_pokemon_jump->prevVineState < VINE_UPSWING_LOW_pokemon_jump)
        {
            sPokemonJump_pokemon_jump->ignoreJumpInput++;
            UpdateVineSpeed_pokemon_jump();
        }
    }
}

static int GetVineSpeed_pokemon_jump(void)
{
    int speed;

    if (sPokemonJump_pokemon_jump->gameOver)
        return 0;

    speed = sPokemonJump_pokemon_jump->vineSpeed;
    if (sPokemonJump_pokemon_jump->vineStateTimer <= VINE_STATE_TIMER_pokemon_jump(VINE_LOWEST_pokemon_jump))
    {
        // If at or below lowest, then vine is in downswing
        // Increase speed in downswing
        sPokemonJump_pokemon_jump->vineSpeedAccel += 80;
        speed += sPokemonJump_pokemon_jump->vineSpeedAccel / 256;
    }

    return speed;
}

static const u16  sVineBaseSpeeds_pokemon_jump[] = {26, 31, 36, 41, 46, 51, 56, 61};
static const u16  sVineSpeedDelays_pokemon_jump[] = {0, 1, 1, 2};

static void UpdateVineSpeed_pokemon_jump(void)
{
    int baseSpeed;

    sPokemonJump_pokemon_jump->vineSpeedAccel = 0;
    if (sPokemonJump_pokemon_jump->vineSpeedDelay)
    {
        sPokemonJump_pokemon_jump->vineSpeedDelay--;
        if (sPokemonJump_pokemon_jump->atMaxSpeedStage)
        {
            if (PokeJumpRandom_pokemon_jump() % 4)
            {
                sPokemonJump_pokemon_jump->vineSpeed = sPokemonJump_pokemon_jump->nextVineSpeed;
            }
            else
            {
                if (sPokemonJump_pokemon_jump->nextVineSpeed > 54)
                    sPokemonJump_pokemon_jump->vineSpeed = 30;
                else
                    sPokemonJump_pokemon_jump->vineSpeed = 82;
            }
        }
    }
    else
    {
        if (!(sPokemonJump_pokemon_jump->vineBaseSpeedIdx & ARRAY_COUNT(sVineBaseSpeeds_pokemon_jump)))
        {
            sPokemonJump_pokemon_jump->nextVineSpeed = sVineBaseSpeeds_pokemon_jump[sPokemonJump_pokemon_jump->vineBaseSpeedIdx] + (sPokemonJump_pokemon_jump->vineSpeedStage * 7);
            sPokemonJump_pokemon_jump->vineSpeedDelay = sVineSpeedDelays_pokemon_jump[PokeJumpRandom_pokemon_jump() % ARRAY_COUNT(sVineSpeedDelays_pokemon_jump)] + 2;
            sPokemonJump_pokemon_jump->vineBaseSpeedIdx++;
        }
        else
        {
            if (sPokemonJump_pokemon_jump->vineBaseSpeedIdx == ARRAY_COUNT(sVineBaseSpeeds_pokemon_jump))
            {
                if (sPokemonJump_pokemon_jump->vineSpeedStage < 3)
                    sPokemonJump_pokemon_jump->vineSpeedStage++;
                else
                    sPokemonJump_pokemon_jump->atMaxSpeedStage = TRUE;
            }

            baseSpeed = sVineBaseSpeeds_pokemon_jump[15 - sPokemonJump_pokemon_jump->vineBaseSpeedIdx];
            sPokemonJump_pokemon_jump->nextVineSpeed = baseSpeed + (sPokemonJump_pokemon_jump->vineSpeedStage * 7);
            if (++sPokemonJump_pokemon_jump->vineBaseSpeedIdx > 15)
            {
                if (PokeJumpRandom_pokemon_jump() % 4 == 0)
                    sPokemonJump_pokemon_jump->nextVineSpeed -= 5;

                sPokemonJump_pokemon_jump->vineBaseSpeedIdx = 0;
            }
        }

        sPokemonJump_pokemon_jump->vineSpeed = sPokemonJump_pokemon_jump->nextVineSpeed;
    }
}

static int PokeJumpRandom_pokemon_jump(void)
{
    sPokemonJump_pokemon_jump->rngSeed = ISO_RANDOMIZE1(sPokemonJump_pokemon_jump->rngSeed);
    return sPokemonJump_pokemon_jump->rngSeed >> 16;
}

