static void LoadSpriteSheetsAndPalettes_pokemon_jump(struct PokemonJumpGfx *jumpGfx)
{
    int i;

    for (i = 0; i < ARRAY_COUNT(sCompressedSpriteSheets_pokemon_jump); i++)
        LoadCompressedSpriteSheet(&sCompressedSpriteSheets_pokemon_jump[i]);

    for (i = 0; i < ARRAY_COUNT(sSpritePalettes_pokemon_jump); i++)
        LoadSpritePalette(&sSpritePalettes_pokemon_jump[i]);

    jumpGfx->vinePalNumDownswing = IndexOfSpritePaletteTag(PALTAG_1_pokemon_jump);
    jumpGfx->vinePalNumUpswing = IndexOfSpritePaletteTag(PALTAG_2_pokemon_jump);
}

static void ResetPokeJumpSpriteData_pokemon_jump(struct Sprite *sprite)
{
    int i;
    for (i = 0; i < (int)ARRAY_COUNT(sprite->data); i++)
        sprite->data[i] = 0;
}

static void CreateJumpMonSprite_pokemon_jump(struct PokemonJumpGfx *jumpGfx, struct PokemonJump_MonInfo *monInfo, s16 x, s16 y, u8 multiplayerId)
{
    struct SpriteTemplate spriteTemplate;
    struct SpriteSheet spriteSheet;
    struct CompressedSpritePalette spritePalette;
    u8 *buffer;
    u8 *unusedBuffer;
    u8 subpriority;
    u8 spriteId;

    spriteTemplate = sSpriteTemplate_JumpMon_pokemon_jump;
    buffer = Alloc(MON_PIC_SIZE * MAX_MON_PIC_FRAMES);
    unusedBuffer = Alloc(MON_PIC_SIZE);
    if (multiplayerId == GetPokeJumpMultiplayerId_pokemon_jump())
        subpriority = 3;
    else
        subpriority = multiplayerId + 4;

    if (buffer && unusedBuffer)
    {
        HandleLoadSpecialPokePic(TRUE,
                                buffer,
                                monInfo->species,
                                monInfo->personality);

        spriteSheet.data = buffer;
        spriteSheet.tag = multiplayerId;
        spriteSheet.size = MON_PIC_SIZE;
        LoadSpriteSheet(&spriteSheet);

        spritePalette.data = GetMonSpritePalFromSpeciesAndPersonality(monInfo->species, monInfo->isShiny, monInfo->personality);
        spritePalette.tag = multiplayerId;
        LoadCompressedSpritePalette(&spritePalette);

        Free(buffer);
        Free(unusedBuffer);

        spriteTemplate.tileTag += multiplayerId;
        spriteTemplate.paletteTag += multiplayerId;
        spriteId = CreateSprite(&spriteTemplate, x, y, subpriority);
        if (spriteId != MAX_SPRITES)
        {
            jumpGfx->monSprites[multiplayerId] = &gSprites[spriteId];
            jumpGfx->monSpriteSubpriorities[multiplayerId] = subpriority;
            return;
        }
    }

    jumpGfx->monSprites[multiplayerId] = NULL;
}

#define sState_pokemon_jump data[0]
#define sTimer_pokemon_jump data[1]
#define sOffset_pokemon_jump data[7] // Never read

static void DoStarAnim_pokemon_jump(struct PokemonJumpGfx *jumpGfx, int multiplayerId)
{
    ResetPokeJumpSpriteData_pokemon_jump(jumpGfx->starSprites[multiplayerId]);
    jumpGfx->starSprites[multiplayerId]->sOffset_pokemon_jump = jumpGfx->monSprites[multiplayerId] - gSprites;
    jumpGfx->starSprites[multiplayerId]->invisible = FALSE;
    jumpGfx->starSprites[multiplayerId]->y = 96;
    jumpGfx->starSprites[multiplayerId]->callback = SpriteCB_Star_pokemon_jump;
    StartSpriteAnim(jumpGfx->starSprites[multiplayerId], 1);
}

static void SpriteCB_Star_pokemon_jump(struct Sprite *sprite)
{
    switch (sprite->sState_pokemon_jump)
    {
    case 0:
        if (sprite->animEnded)
        {
            sprite->invisible = TRUE;
            sprite->callback = SpriteCallbackDummy;
        }
        break;
    case 1:
        sprite->y--;
        sprite->sTimer_pokemon_jump++;
        if (sprite->y <= 72)
        {
            sprite->y = 72;
            sprite->sState_pokemon_jump++;
        }
        break;
    case 2:
        if (++sprite->sTimer_pokemon_jump >= 48)
        {
            sprite->invisible = TRUE;
            sprite->callback = SpriteCallbackDummy;
        }
        break;
    }
}

#undef sState_pokemon_jump
#undef sTimer_pokemon_jump
#undef sOffset_pokemon_jump

static void Gfx_StartMonHitShake_pokemon_jump(struct PokemonJumpGfx *jumpGfx, int multiplayerId)
{
    jumpGfx->monSprites[multiplayerId]->callback = SpriteCB_MonHitShake_pokemon_jump;
    jumpGfx->monSprites[multiplayerId]->y2 = 0;
    ResetPokeJumpSpriteData_pokemon_jump(jumpGfx->monSprites[multiplayerId]);
}

static bool32 Gfx_IsMonHitShakeActive_pokemon_jump(struct PokemonJumpGfx *jumpGfx, int multiplayerId)
{
    return jumpGfx->monSprites[multiplayerId]->callback == SpriteCB_MonHitShake_pokemon_jump;
}

#define sTimer_pokemon_jump     data[1]
#define sNumShakes_pokemon_jump data[2]

static void SpriteCB_MonHitShake_pokemon_jump(struct Sprite *sprite)
{
    if (++sprite->sTimer_pokemon_jump > 1)
    {
        if (++sprite->sNumShakes_pokemon_jump & 1)
            sprite->y2 = 2;
        else
            sprite->y2 = -2;

        sprite->sTimer_pokemon_jump = 0;
    }

    if (sprite->sNumShakes_pokemon_jump > 12)
    {
        sprite->y2 = 0;
        sprite->callback = SpriteCallbackDummy;
    }
}

#undef sTimer_pokemon_jump
#undef sNumShakes_pokemon_jump

static void Gfx_StartMonHitFlash_pokemon_jump(struct PokemonJumpGfx *jumpGfx, int multiplayerId)
{
    ResetPokeJumpSpriteData_pokemon_jump(jumpGfx->monSprites[multiplayerId]);
    jumpGfx->monSprites[multiplayerId]->callback = SpriteCB_MonHitFlash_pokemon_jump;
}

static void Gfx_StopMonHitFlash_pokemon_jump(struct PokemonJumpGfx *jumpGfx)
{
    int i;
    u16 numPlayers = GetNumPokeJumpPlayers_pokemon_jump();
    for (i = 0; i < numPlayers; i++)
    {
        if (jumpGfx->monSprites[i]->callback == SpriteCB_MonHitFlash_pokemon_jump)
        {
            jumpGfx->monSprites[i]->invisible = FALSE;
            jumpGfx->monSprites[i]->callback = SpriteCallbackDummy;
            jumpGfx->monSprites[i]->subpriority = 10;
        }
    }
}

#define sTimer_pokemon_jump data[0]

static void SpriteCB_MonHitFlash_pokemon_jump(struct Sprite *sprite)
{
    if (++sprite->sTimer_pokemon_jump > 3)
    {
        sprite->sTimer_pokemon_jump = 0;
        sprite->invisible ^= 1;
    }
}

#undef sTimer_pokemon_jump

static void Gfx_ResetMonSpriteSubpriorities_pokemon_jump(struct PokemonJumpGfx *jumpGfx)
{
    int i;
    u16 numPlayers = GetNumPokeJumpPlayers_pokemon_jump();
    for (i = 0; i < numPlayers; i++)
        jumpGfx->monSprites[i]->subpriority = jumpGfx->monSpriteSubpriorities[i];
}

static void Gfx_StartMonIntroBounce_pokemon_jump(struct PokemonJumpGfx *jumpGfx, int multiplayerId)
{
    ResetPokeJumpSpriteData_pokemon_jump(jumpGfx->monSprites[multiplayerId]);
    jumpGfx->monSprites[multiplayerId]->callback = SpriteCB_MonIntroBounce_pokemon_jump;
}

static bool32 Gfx_IsMonIntroBounceActive_pokemon_jump(struct PokemonJumpGfx *jumpGfx)
{
    int i;
    u16 numPlayers = GetNumPokeJumpPlayers_pokemon_jump();
    for (i = 0; i < numPlayers; i++)
    {
        if (jumpGfx->monSprites[i]->callback == SpriteCB_MonIntroBounce_pokemon_jump)
            return TRUE;
    }

    return FALSE;
}

#define sState_pokemon_jump   data[0]
#define sHopPos_pokemon_jump  data[1]
#define sNumHops_pokemon_jump data[2]

static void SpriteCB_MonIntroBounce_pokemon_jump(struct Sprite *sprite)
{
    switch (sprite->sState_pokemon_jump)
    {
    case 0:
        PlaySE(SE_BIKE_HOP);
        sprite->sHopPos_pokemon_jump = 0;
        sprite->sState_pokemon_jump++;
        // fall through
    case 1:
        sprite->sHopPos_pokemon_jump += 4;
        if (sprite->sHopPos_pokemon_jump > 127)
            sprite->sHopPos_pokemon_jump = 0;

        sprite->y2 = -(gSineTable[sprite->sHopPos_pokemon_jump] >> 3);
        if (sprite->sHopPos_pokemon_jump == 0)
        {
            if (++sprite->sNumHops_pokemon_jump < 2)
                sprite->sState_pokemon_jump = 0;
            else
                sprite->callback = SpriteCallbackDummy;
        }
        break;
    }
}

#undef sState_pokemon_jump
#undef sHopPos_pokemon_jump
#undef sNumHops_pokemon_jump

static void CreateStarSprite_pokemon_jump(struct PokemonJumpGfx *jumpGfx, s16 x, s16 y, u8 multiplayerId)
{
    u8 spriteId = CreateSprite(&sSpriteTemplate_Star_pokemon_jump, x, y, 1);
    if (spriteId != MAX_SPRITES)
    {
        gSprites[spriteId].invisible = TRUE;
        jumpGfx->starSprites[multiplayerId] = &gSprites[spriteId];
    }
}

static void CreateVineSprites_pokemon_jump(struct PokemonJumpGfx *jumpGfx)
{
    int i;
    int count;
    u8 spriteId;

    count = 0;
    for (i = 0; i < VINE_SPRITES_PER_SIDE_pokemon_jump; i++)
    {
        spriteId = CreateSprite(sSpriteTemplates_Vine[i], sVineXCoords_pokemon_jump[count], sVineYCoords_pokemon_jump[i][0], 2);
        jumpGfx->vineSprites[count] = &gSprites[spriteId];
        count++;
    }

    for (i = VINE_SPRITES_PER_SIDE_pokemon_jump - 1; i >= 0; i--)
    {
        spriteId = CreateSprite(sSpriteTemplates_Vine[i], sVineXCoords_pokemon_jump[count], sVineYCoords_pokemon_jump[i][0], 2);
        jumpGfx->vineSprites[count] = &gSprites[spriteId];
        jumpGfx->vineSprites[count]->hFlip = TRUE;
        count++;
    }
}

static void UpdateVineAnim_pokemon_jump(struct PokemonJumpGfx *jumpGfx, int vineState)
{
    int i, count, palNum;
    int priority;

    if (vineState > VINE_LOWEST_pokemon_jump)
    {
        // animNums for vine on upswing are same as
        // on downswing but in reverse
        vineState = NUM_VINESTATES_pokemon_jump - vineState;
        priority = 3; // Set vine behind Pokémon
        palNum = jumpGfx->vinePalNumUpswing;
    }
    else
    {
        priority = 2; // Set vine in front of Pokémon
        palNum = jumpGfx->vinePalNumDownswing;
    }

    count = 0;
    for (i = 0; i < VINE_SPRITES_PER_SIDE_pokemon_jump; i++)
    {
        jumpGfx->vineSprites[count]->y = sVineYCoords_pokemon_jump[i][vineState];
        jumpGfx->vineSprites[count]->oam.priority = priority;
        jumpGfx->vineSprites[count]->oam.paletteNum = palNum;
        StartSpriteAnim(jumpGfx->vineSprites[count], vineState);
        count++;
    }

    for (i = VINE_SPRITES_PER_SIDE_pokemon_jump - 1; i >= 0; i--)
    {
        jumpGfx->vineSprites[count]->y = sVineYCoords_pokemon_jump[i][vineState];
        jumpGfx->vineSprites[count]->oam.priority = priority;
        jumpGfx->vineSprites[count]->oam.paletteNum = palNum;
        StartSpriteAnim(jumpGfx->vineSprites[count], vineState);
        count++;
    }
}

