static void SetUpPokeJumpGfxFuncById_pokemon_jump(int id)
{
    int i;

    for (i = 0; i < ARRAY_COUNT(sPokeJumpGfxFuncs); i++)
    {
        if (sPokeJumpGfxFuncs[i].id == id)
            SetUpPokeJumpGfxFunc_pokemon_jump(sPokeJumpGfxFuncs[i].func);
    }
}

static bool32 IsPokeJumpGfxFuncFinished_pokemon_jump(void)
{
    return (sPokemonJumpGfx_pokemon_jump->funcFinished != TRUE);
}

static void SetUpPokeJumpGfxFunc_pokemon_jump(void (*func)(void))
{
    SetWordTaskArg(sPokemonJumpGfx_pokemon_jump->taskId, 0, (u32) func);
    sPokemonJumpGfx_pokemon_jump->mainState = 0;
    sPokemonJumpGfx_pokemon_jump->funcFinished = FALSE;
}

static void Task_RunPokeJumpGfxFunc_pokemon_jump(u8 taskId)
{
    if (!sPokemonJumpGfx_pokemon_jump->funcFinished)
    {
        // Read the function set in the data by SetUpPokeJumpGfxFunc_pokemon_jump
        void (*func)(void) = (void *)(GetWordTaskArg(taskId, 0));

        func();
    }
}

static void LoadPokeJumpGfx_pokemon_jump(void)
{
    switch (sPokemonJumpGfx_pokemon_jump->mainState)
    {
    case 0:
        ResetBgsAndClearDma3BusyFlags(0);
        InitBgsFromTemplates(0, sBgTemplates_pokemon_jump, ARRAY_COUNT(sBgTemplates_pokemon_jump));
        InitWindows(sWindowTemplates_pokemon_jump);
        ResetTempTileDataBuffers();
        LoadSpriteSheetsAndPalettes_pokemon_jump(sPokemonJumpGfx_pokemon_jump);
        InitDigitPrinters_pokemon_jump();
        LoadPalette(sBg_Pal_pokemon_jump, BG_PLTT_ID(0), PLTT_SIZE_4BPP);
        DecompressAndCopyTileDataToVram(BG_SCENERY_pokemon_jump, sBg_Gfx_pokemon_jump, 0, 0, 0);
        DecompressAndCopyTileDataToVram(BG_SCENERY_pokemon_jump, sBg_Tilemap_pokemon_jump, 0, 0, 1);
        LoadPalette(sVenusaur_Pal_pokemon_jump, BG_PLTT_ID(3), PLTT_SIZE_4BPP);
        DecompressAndCopyTileDataToVram(BG_VENUSAUR_pokemon_jump, sVenusaur_Gfx_pokemon_jump, 0, 0, 0);
        DecompressAndCopyTileDataToVram(BG_VENUSAUR_pokemon_jump, sVenusaur_Tilemap_pokemon_jump, 0, 0, 1);
        LoadPalette(sBonuses_Pal_pokemon_jump, BG_PLTT_ID(1), PLTT_SIZE_4BPP);
        DecompressAndCopyTileDataToVram(BG_BONUSES_pokemon_jump, sBonuses_Gfx_pokemon_jump, 0, 0, 0);
        DecompressAndCopyTileDataToVram(BG_BONUSES_pokemon_jump, sBonuses_Tilemap_pokemon_jump, 0, 0, 1);
        LoadPalette(sInterface_Pal_pokemon_jump, BG_PLTT_ID(2), PLTT_SIZE_4BPP);
        SetBgTilemapBuffer(BG_INTERFACE_pokemon_jump, sPokemonJumpGfx_pokemon_jump->tilemapBuffer);
        FillBgTilemapBufferRect_Palette0(BG_INTERFACE_pokemon_jump, 0, 0, 0, 0x20, 0x20);
        PrintScoreSuffixes_pokemon_jump();
        PrintScore_pokemon_jump(0);
        LoadUserWindowBorderGfxOnBg(0, 1, BG_PLTT_ID(14));
        CopyBgTilemapBufferToVram(BG_INTERFACE_pokemon_jump);
        CopyBgTilemapBufferToVram(BG_VENUSAUR_pokemon_jump);
        CopyBgTilemapBufferToVram(BG_BONUSES_pokemon_jump);
        ResetBgPositions();
        sPokemonJumpGfx_pokemon_jump->mainState++;
        break;
    case 1:
        if (!FreeTempTileDataBuffersIfPossible())
        {
            CreateJumpMonSprites_pokemon_jump();
            CreateVineSprites_pokemon_jump(sPokemonJumpGfx_pokemon_jump);
            UpdateVineAnim_pokemon_jump(sPokemonJumpGfx_pokemon_jump, VINE_UPSWING_LOWER_pokemon_jump);
            ShowBg(BG_SCENERY_pokemon_jump);
            ShowBg(BG_INTERFACE_pokemon_jump);
            ShowBg(BG_VENUSAUR_pokemon_jump);
            HideBg(BG_BONUSES_pokemon_jump);
            sPokemonJumpGfx_pokemon_jump->mainState++;
        }
        break;
    case 2:
        sPokemonJumpGfx_pokemon_jump->funcFinished = TRUE;
        break;
    }
}

