static void ErasePlayerNames_pokemon_jump(void)
{
    int i, numPlayers;

    numPlayers = GetNumPokeJumpPlayers_pokemon_jump();
    switch (sPokemonJumpGfx_pokemon_jump->mainState)
    {
    case 0:
        for (i = 0; i < numPlayers; i++)
            ClearWindowTilemap(sPokemonJumpGfx_pokemon_jump->nameWindowIds[i]);

        CopyBgTilemapBufferToVram(BG_INTERFACE_pokemon_jump);
        sPokemonJumpGfx_pokemon_jump->mainState++;
        break;
    case 1:
        if (!IsDma3ManagerBusyWithBgCopy())
        {
            for (i = 0; i < numPlayers; i++)
                RemoveWindow(sPokemonJumpGfx_pokemon_jump->nameWindowIds[i]);

            sPokemonJumpGfx_pokemon_jump->funcFinished = TRUE;
        }
        break;
    }
}

