static void SetUpResetVineGfx_pokemon_jump(void)
{
    sPokemonJumpGfx_pokemon_jump->resetVineState = 0;
    sPokemonJumpGfx_pokemon_jump->resetVineTimer = 0;
    sPokemonJumpGfx_pokemon_jump->vineState = VINE_UPSWING_LOWER_pokemon_jump;
    UpdateVineSwing_pokemon_jump(sPokemonJumpGfx_pokemon_jump->vineState);
}

static bool32 ResetVineGfx_pokemon_jump(void)
{
    switch (sPokemonJumpGfx_pokemon_jump->resetVineState)
    {
    case 0:
        sPokemonJumpGfx_pokemon_jump->resetVineTimer++;
        if (sPokemonJumpGfx_pokemon_jump->resetVineTimer > 10)
        {
            sPokemonJumpGfx_pokemon_jump->resetVineTimer = 0;
            sPokemonJumpGfx_pokemon_jump->vineState++;
            if (sPokemonJumpGfx_pokemon_jump->vineState >= NUM_VINESTATES_pokemon_jump)
            {
                sPokemonJumpGfx_pokemon_jump->vineState = VINE_HIGHEST_pokemon_jump;
                sPokemonJumpGfx_pokemon_jump->resetVineState++;
            }
        }
        UpdateVineSwing_pokemon_jump(sPokemonJumpGfx_pokemon_jump->vineState);
        if (sPokemonJumpGfx_pokemon_jump->vineState != VINE_UPSWING_LOW_pokemon_jump)
            break;
    case 1:
        return FALSE;
    }

    return TRUE;
}

