static bool32 DoPrizeMessageAndFanfare_pokemon_jump(void)
{
    switch (sPokemonJumpGfx_pokemon_jump->msgWindowState)
    {
    case 0:
        if (!IsDma3ManagerBusyWithBgCopy())
        {
            PutWindowTilemap(sPokemonJumpGfx_pokemon_jump->msgWindowId);
            DrawTextBorderOuter(sPokemonJumpGfx_pokemon_jump->msgWindowId, 1, 14);
            CopyBgTilemapBufferToVram(BG_INTERFACE_pokemon_jump);
            sPokemonJumpGfx_pokemon_jump->msgWindowState++;
        }
        break;
    case 1:
        if (IsDma3ManagerBusyWithBgCopy())
            break;
        if (sPokemonJumpGfx_pokemon_jump->fanfare == MUS_DUMMY)
        {
            sPokemonJumpGfx_pokemon_jump->msgWindowState += 2;
            return FALSE;
        }
        PlayFanfare(sPokemonJumpGfx_pokemon_jump->fanfare);
        sPokemonJumpGfx_pokemon_jump->msgWindowState++;
    case 2:
        if (!IsFanfareTaskInactive())
            break;
        sPokemonJumpGfx_pokemon_jump->msgWindowState++;
    case 3:
        return FALSE;
    }

    return TRUE;
}

static void ClearMessageWindow_pokemon_jump(void)
{
    if (sPokemonJumpGfx_pokemon_jump->msgWindowId != WINDOW_NONE)
    {
        rbox_fill_rectangle(sPokemonJumpGfx_pokemon_jump->msgWindowId);
        CopyWindowToVram(sPokemonJumpGfx_pokemon_jump->msgWindowId, COPYWIN_MAP);
        sPokemonJumpGfx_pokemon_jump->msgWindowState = 0;
    }
}

static bool32 RemoveMessageWindow_pokemon_jump(void)
{
    if (sPokemonJumpGfx_pokemon_jump->msgWindowId == WINDOW_NONE)
        return FALSE;

    switch (sPokemonJumpGfx_pokemon_jump->msgWindowState)
    {
    case 0:
        if (!IsDma3ManagerBusyWithBgCopy())
        {
            RemoveWindow(sPokemonJumpGfx_pokemon_jump->msgWindowId);
            sPokemonJumpGfx_pokemon_jump->msgWindowId = WINDOW_NONE;
            sPokemonJumpGfx_pokemon_jump->msgWindowState++;
        }
        else
            break;
    case 1:
        return FALSE;
    }

    return TRUE;
}

