// The venusaurs in the background are actually an empty 256x512 bg with 3 pairs of venusaurs on it.
// The below array is used to get values for where to set the bg Y to show the corresponding
// venusaur pair in their state of swinging the vine rope
// NEUTRAL/DOWN/UP refers to which direction the Venusaur is facing as it swings the vine
enum {
    VENUSAUR_NEUTRAL_pokemon_jump,
    VENUSAUR_DOWN_pokemon_jump,
    VENUSAUR_UP_pokemon_jump,
};

static const u8  sVenusaurStates_pokemon_jump[] = {
    [VINE_HIGHEST_pokemon_jump]          = VENUSAUR_UP_pokemon_jump,
    [VINE_DOWNSWING_HIGHER_pokemon_jump] = VENUSAUR_UP_pokemon_jump,
    [VINE_DOWNSWING_HIGH_pokemon_jump]   = VENUSAUR_NEUTRAL_pokemon_jump,
    [VINE_DOWNSWING_LOW_pokemon_jump]    = VENUSAUR_NEUTRAL_pokemon_jump,
    [VINE_DOWNSWING_LOWER_pokemon_jump]  = VENUSAUR_DOWN_pokemon_jump,
    [VINE_LOWEST_pokemon_jump]           = VENUSAUR_DOWN_pokemon_jump,
    [VINE_UPSWING_LOWER_pokemon_jump]    = VENUSAUR_DOWN_pokemon_jump,
    [VINE_UPSWING_LOW_pokemon_jump]      = VENUSAUR_NEUTRAL_pokemon_jump,
    [VINE_UPSWING_HIGH_pokemon_jump]     = VENUSAUR_NEUTRAL_pokemon_jump,
    [VINE_UPSWING_HIGHER_pokemon_jump]   = VENUSAUR_UP_pokemon_jump,
};

