static void CreateJumpMonSprites_pokemon_jump(void)
{
    int i, y, playersCount = GetNumPokeJumpPlayers_pokemon_jump();
    const s16 *xCoords = sMonXCoords[playersCount - 2];

    for (i = 0; i < playersCount; i++)
    {
        struct PokemonJump_MonInfo *monInfo = GetMonInfoByMultiplayerId_pokemon_jump(i);

        y = gSpeciesInfo[monInfo->species].frontPicYOffset;
        CreateJumpMonSprite_pokemon_jump(sPokemonJumpGfx_pokemon_jump, monInfo, *xCoords, y + 112, i);
        CreateStarSprite_pokemon_jump(sPokemonJumpGfx_pokemon_jump, *xCoords, 112, i);
        xCoords++;
    }
}

