static void UpdateVineSwing_pokemon_jump(int vineState)
{
    UpdateVineAnim_pokemon_jump(sPokemonJumpGfx_pokemon_jump, vineState);
    ChangeBgY(BG_VENUSAUR_pokemon_jump, (sVenusaurStates_pokemon_jump[vineState] * 5) << 13, BG_COORD_SET);
}

static int DoSameJumpTimeBonus_pokemon_jump(u8 flags)
{
    int i, numPlayers;

    for (i = 0, numPlayers = 0; i < MAX_RFU_PLAYERS; i++)
    {
        if (flags & 1)
        {
            // Player was part of a synchronous jump
            // Give a bonus to them
            DoStarAnim_pokemon_jump(sPokemonJumpGfx_pokemon_jump, i);
            numPlayers++;
        }
        flags >>= 1;
    }

    ShowBonus_pokemon_jump(numPlayers - 2);
    return numPlayers;
}

