void ResetPokemonJumpRecords(void)
{
#if FREE_POKEMON_JUMP == FALSE
    struct PokemonJumpRecords *records = GetPokeJumpRecords_pokemon_jump();
    records->jumpsInRow = 0;
    records->bestJumpScore = 0;
    records->excellentsInRow = 0;
    records->gamesWithMaxPlayers = 0;
    records->unused2 = 0;
    records->unused1 = 0;
#endif //FREE_POKEMON_JUMP
}

static bool32 TryUpdateRecords_pokemon_jump(u32 jumpScore, u16 jumpsInRow, u16 excellentsInRow)
{
#if FREE_POKEMON_JUMP == FALSE
    struct PokemonJumpRecords *records = GetPokeJumpRecords_pokemon_jump();
    bool32 newRecord = FALSE;

    if (records->bestJumpScore < jumpScore && jumpScore <= MAX_JUMP_SCORE_pokemon_jump)
        records->bestJumpScore = jumpScore, newRecord = TRUE;
    if (records->jumpsInRow < jumpsInRow && jumpsInRow <= MAX_JUMPS_pokemon_jump)
        records->jumpsInRow = jumpsInRow, newRecord = TRUE;
    if (records->excellentsInRow < excellentsInRow && excellentsInRow <= MAX_JUMPS_pokemon_jump)
        records->excellentsInRow = excellentsInRow, newRecord = TRUE;

    return newRecord;
#else
    return FALSE;
#endif //FREE_POKEMON_JUMP
}

static void IncrementGamesWithMaxPlayers_pokemon_jump(void)
{
#if FREE_POKEMON_JUMP == FALSE
    struct PokemonJumpRecords *records = GetPokeJumpRecords_pokemon_jump();
    if (records->gamesWithMaxPlayers < 9999)
        records->gamesWithMaxPlayers++;
#endif //FREE_POKEMON_JUMP
}

