static const struct WindowTemplate  sWindowTemplate_Records_pokemon_jump =
{
    .bg = 0,
    .tilemapLeft = 1,
    .tilemapTop = 1,
    .width = 28,
    .height = 9,
    .paletteNum = 15,
    .baseBlock = 0x1,
};

static const u8 *const  sRecordsTexts_pokemon_jump[] = {gText_JumpsInARow, gText_BestScore2, gText_ExcellentsInARow};

#define tState_pokemon_jump data[0]
#define tWindowId_pokemon_jump data[1]

static void Task_ShowPokemonJumpRecords_pokemon_jump(u8 taskId)
{
    struct WindowTemplate window;
    int i, width, widthCurr;
    s16 *data = gTasks[taskId].data;

    switch (tState_pokemon_jump)
    {
    case 0:
        window = sWindowTemplate_Records_pokemon_jump;
        width = GetStringWidth(FONT_NORMAL, gText_PkmnJumpRecords, 0);
        for (i = 0; i < ARRAY_COUNT(sRecordsTexts_pokemon_jump); i++)
        {
            widthCurr = GetStringWidth(FONT_NORMAL, sRecordsTexts_pokemon_jump[i], 0) + 38;
            if (widthCurr > width)
                width = widthCurr;
        }
        width = (width + 7) / 8;
        if (width & 1)
            width++;
        window.tilemapLeft = (30 - width) / 2;
        window.width = width;
        tWindowId_pokemon_jump = AddWindow(&window);
        PrintRecordsText_pokemon_jump(tWindowId_pokemon_jump, width);
        CopyWindowToVram(tWindowId_pokemon_jump, COPYWIN_FULL);
        tState_pokemon_jump++;
        break;
    case 1:
        if (!IsDma3ManagerBusyWithBgCopy())
            tState_pokemon_jump++;
        break;
    case 2:
        if (JOY_NEW(A_BUTTON | B_BUTTON))
        {
            rbox_fill_rectangle(tWindowId_pokemon_jump);
            CopyWindowToVram(tWindowId_pokemon_jump, COPYWIN_MAP);
            tState_pokemon_jump++;
        }
        break;
    case 3:
        if (!IsDma3ManagerBusyWithBgCopy())
        {
            RemoveWindow(tWindowId_pokemon_jump);
            DestroyTask(taskId);
            ScriptContext_Enable();
        }
        break;
    }
}

#undef tState_pokemon_jump
#undef tWindowId_pokemon_jump

static void PrintRecordsText_pokemon_jump(u16 windowId, int width)
{
#if FREE_POKEMON_JUMP == FALSE
    int i, x;
    int recordNums[3];
    struct PokemonJumpRecords *records = GetPokeJumpRecords_pokemon_jump();
    recordNums[0] = records->jumpsInRow;
    recordNums[1] = records->bestJumpScore;
    recordNums[2] = records->excellentsInRow;

    LoadUserWindowBorderGfx_(windowId, 0x21D, BG_PLTT_ID(13));
    DrawTextBorderOuter(windowId, 0x21D, 13);
    FillWindowPixelBuffer(windowId, PIXEL_FILL(1));
    AddTextPrinterParameterized(windowId, FONT_NORMAL, gText_PkmnJumpRecords, GetStringCenterAlignXOffset(FONT_NORMAL, gText_PkmnJumpRecords, width * 8), 1, TEXT_SKIP_DRAW, NULL);
    for (i = 0; i < ARRAY_COUNT(sRecordsTexts_pokemon_jump); i++)
    {
        AddTextPrinterParameterized(windowId, FONT_NORMAL, sRecordsTexts_pokemon_jump[i], 0, 25 + (i * 16), TEXT_SKIP_DRAW, NULL);
        ConvertIntToDecimalStringN(gStringVar1, recordNums[i], STR_CONV_MODE_LEFT_ALIGN, 5);
        TruncateToFirstWordOnly_pokemon_jump(gStringVar1);
        x = (width * 8) - GetStringWidth(FONT_NORMAL, gStringVar1, 0);
        AddTextPrinterParameterized(windowId, FONT_NORMAL, gStringVar1, x, 25 + (i * 16), TEXT_SKIP_DRAW, NULL);
    }
    PutWindowTilemap(windowId);
#endif //FREE_POKEMON_JUMP
}

static inline void TruncateToFirstWordOnly_pokemon_jump(u8 *str)
{
    for (;*str != EOS; str++)
    {
        if (*str == CHAR_SPACE)
        {
            *str = EOS;
            break;
        }
    }
}
