// Handle options menu that shows when the box title bar is selected
static void Task_HandleBoxOptions_pokemon_storage_system(u8 taskId)
{
    switch (sStorage_pokemon_storage_system->state)
    {
    case 0:
        PrintMessage_pokemon_storage_system(MSG_WHAT_YOU_DO_pokemon_storage_system);
        AddMenu_pokemon_storage_system();
        sStorage_pokemon_storage_system->state++;
        break;
    case 1:
        if (IsMenuLoading_pokemon_storage_system())
            return;
        sStorage_pokemon_storage_system->state++;
    case 2:
        switch (HandleMenuInput_pokemon_storage_system())
        {
        case MENU_B_PRESSED:
        case MENU_CANCEL_pokemon_storage_system:
            AnimateBoxScrollArrows_pokemon_storage_system(TRUE);
            ClearBottomWindow_pokemon_storage_system();
            SetPokeStorageTask_pokemon_storage_system(Task_PokeStorageMain_pokemon_storage_system);
            break;
        case MENU_NAME_pokemon_storage_system:
            PlaySE(SE_SELECT);
            SetPokeStorageTask_pokemon_storage_system(Task_NameBox_pokemon_storage_system);
            break;
        case MENU_WALLPAPER_pokemon_storage_system:
            PlaySE(SE_SELECT);
            ClearBottomWindow_pokemon_storage_system();
            SetPokeStorageTask_pokemon_storage_system(Task_HandleWallpapers_pokemon_storage_system);
            break;
        case MENU_JUMP_pokemon_storage_system:
            PlaySE(SE_SELECT);
            ClearBottomWindow_pokemon_storage_system();
            SetPokeStorageTask_pokemon_storage_system(Task_JumpBox_pokemon_storage_system);
            break;
        }
        break;
    }
}

static void Task_HandleWallpapers_pokemon_storage_system(u8 taskId)
{
    switch (sStorage_pokemon_storage_system->state)
    {
    case 0:
        AddWallpaperSetsMenu_pokemon_storage_system();
        PrintMessage_pokemon_storage_system(MSG_PICK_A_THEME_pokemon_storage_system);
        sStorage_pokemon_storage_system->state++;
        break;
    case 1:
        if (!IsMenuLoading_pokemon_storage_system())
             sStorage_pokemon_storage_system->state++;
        break;
    case 2:
        sStorage_pokemon_storage_system->wallpaperSetId = HandleMenuInput_pokemon_storage_system();
        switch (sStorage_pokemon_storage_system->wallpaperSetId)
        {
        case MENU_B_PRESSED:
            AnimateBoxScrollArrows_pokemon_storage_system(TRUE);
            ClearBottomWindow_pokemon_storage_system();
            SetPokeStorageTask_pokemon_storage_system(Task_PokeStorageMain_pokemon_storage_system);
            break;
        case MENU_SCENERY_1_pokemon_storage_system:
        case MENU_SCENERY_2_pokemon_storage_system:
        case MENU_SCENERY_3_pokemon_storage_system:
        case MENU_ETCETERA_pokemon_storage_system:
            PlaySE(SE_SELECT);
            RemoveMenu_pokemon_storage_system();
            sStorage_pokemon_storage_system->wallpaperSetId -= MENU_WALLPAPER_SETS_START_pokemon_storage_system;
            sStorage_pokemon_storage_system->state++;
            break;
        case MENU_FRIENDS_pokemon_storage_system:
            // New wallpaper from Walda.
            PlaySE(SE_SELECT);
            sStorage_pokemon_storage_system->wallpaperId = WALLPAPER_FRIENDS;
            RemoveMenu_pokemon_storage_system();
            ClearBottomWindow_pokemon_storage_system();
            sStorage_pokemon_storage_system->state = 6;
            break;
        }
        break;
    case 3:
        if (!IsDma3ManagerBusyWithBgCopy())
        {
            AddWallpapersMenu_pokemon_storage_system(sStorage_pokemon_storage_system->wallpaperSetId);
            PrintMessage_pokemon_storage_system(MSG_PICK_A_WALLPAPER_pokemon_storage_system);
            sStorage_pokemon_storage_system->state++;
        }
        break;
    case 4:
        sStorage_pokemon_storage_system->wallpaperId = HandleMenuInput_pokemon_storage_system();
        switch (sStorage_pokemon_storage_system->wallpaperId)
        {
        case MENU_NOTHING_CHOSEN:
            break;
        case MENU_B_PRESSED:
            ClearBottomWindow_pokemon_storage_system();
            sStorage_pokemon_storage_system->state = 0;
            break;
        default:
            PlaySE(SE_SELECT);
            ClearBottomWindow_pokemon_storage_system();
            sStorage_pokemon_storage_system->wallpaperId -= MENU_WALLPAPERS_START_pokemon_storage_system;
            SetWallpaperForCurrentBox_pokemon_storage_system(sStorage_pokemon_storage_system->wallpaperId);
            sStorage_pokemon_storage_system->state++;
            break;
        }
        break;
    case 5:
        if (!DoWallpaperGfxChange_pokemon_storage_system())
        {
            AnimateBoxScrollArrows_pokemon_storage_system(TRUE);
            SetPokeStorageTask_pokemon_storage_system(Task_PokeStorageMain_pokemon_storage_system);
        }
        break;
    case 6:
        if (!IsDma3ManagerBusyWithBgCopy())
        {
            SetWallpaperForCurrentBox_pokemon_storage_system(sStorage_pokemon_storage_system->wallpaperId);
            sStorage_pokemon_storage_system->state = 5;
        }
        break;
    }
}

static void Task_JumpBox_pokemon_storage_system(u8 taskId)
{
    switch (sStorage_pokemon_storage_system->state)
    {
    case 0:
        PrintMessage_pokemon_storage_system(MSG_JUMP_TO_WHICH_BOX_pokemon_storage_system);
        LoadChooseBoxMenuGfx_pokemon_storage_system(&sStorage_pokemon_storage_system->chooseBoxMenu, GFXTAG_CHOOSE_BOX_MENU_pokemon_storage_system, PALTAG_MISC_1_pokemon_storage_system, 3, FALSE);
        CreateChooseBoxMenuSprites_pokemon_storage_system(StorageGetCurrentBox());
        sStorage_pokemon_storage_system->state++;
        break;
    case 1:
        sStorage_pokemon_storage_system->newCurrBoxId = HandleChooseBoxMenuInput_pokemon_storage_system();
        switch (sStorage_pokemon_storage_system->newCurrBoxId)
        {
        case BOXID_NONE_CHOSEN_pokemon_storage_system:
            break;
        default:
            ClearBottomWindow_pokemon_storage_system();
            DestroyChooseBoxMenuSprites_pokemon_storage_system();
            FreeChooseBoxMenu_pokemon_storage_system();
            if (sStorage_pokemon_storage_system->newCurrBoxId == BOXID_CANCELED_pokemon_storage_system || sStorage_pokemon_storage_system->newCurrBoxId == StorageGetCurrentBox())
            {
                AnimateBoxScrollArrows_pokemon_storage_system(TRUE);
                SetPokeStorageTask_pokemon_storage_system(Task_PokeStorageMain_pokemon_storage_system);
            }
            else
            {
                sStorage_pokemon_storage_system->state++;
            }
            break;
        }
        break;
    case 2:
        SetUpScrollToBox_pokemon_storage_system(sStorage_pokemon_storage_system->newCurrBoxId);
        sStorage_pokemon_storage_system->state++;
        break;
    case 3:
        if (!ScrollToBox_pokemon_storage_system())
        {
            SetCurrentBox_pokemon_storage_system(sStorage_pokemon_storage_system->newCurrBoxId);
            SetPokeStorageTask_pokemon_storage_system(Task_PokeStorageMain_pokemon_storage_system);
        }
        break;
    }
}

static void Task_NameBox_pokemon_storage_system(u8 taskId)
{
    switch (sStorage_pokemon_storage_system->state)
    {
    case 0:
        SaveMovingMon_pokemon_storage_system();
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
        sStorage_pokemon_storage_system->state++;
        break;
    case 1:
        if (!UpdatePaletteFade())
        {
            sWhichToReshow_pokemon_storage_system = SCREEN_CHANGE_NAME_BOX_pokemon_storage_system - 1;
            sStorage_pokemon_storage_system->screenChangeType = SCREEN_CHANGE_NAME_BOX_pokemon_storage_system;
            SetPokeStorageTask_pokemon_storage_system(Task_ChangeScreen_pokemon_storage_system);
        }
        break;
    }
}

static void Task_ShowMonSummary_pokemon_storage_system(u8 taskId)
{
    switch (sStorage_pokemon_storage_system->state)
    {
    case 0:
        InitSummaryScreenData_pokemon_storage_system();
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
        sStorage_pokemon_storage_system->state++;
        break;
    case 1:
        if (!UpdatePaletteFade())
        {
            sWhichToReshow_pokemon_storage_system = SCREEN_CHANGE_SUMMARY_SCREEN_pokemon_storage_system - 1;
            sStorage_pokemon_storage_system->screenChangeType = SCREEN_CHANGE_SUMMARY_SCREEN_pokemon_storage_system;
            SetPokeStorageTask_pokemon_storage_system(Task_ChangeScreen_pokemon_storage_system);
        }
        break;
    }
}

static void Task_GiveItemFromBag_pokemon_storage_system(u8 taskId)
{
    switch (sStorage_pokemon_storage_system->state)
    {
    case 0:
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
        sStorage_pokemon_storage_system->state++;
        break;
    case 1:
        if (!UpdatePaletteFade())
        {
            sWhichToReshow_pokemon_storage_system = SCREEN_CHANGE_ITEM_FROM_BAG_pokemon_storage_system - 1;
            sStorage_pokemon_storage_system->screenChangeType = SCREEN_CHANGE_ITEM_FROM_BAG_pokemon_storage_system;
            SetPokeStorageTask_pokemon_storage_system(Task_ChangeScreen_pokemon_storage_system);
            sJustOpenedBag_pokemon_storage_system = TRUE;
        }
        break;
    }
}

static void Task_OnCloseBoxPressed_pokemon_storage_system(u8 taskId)
{
    switch (sStorage_pokemon_storage_system->state)
    {
    case 0:
        if (IsMonBeingMoved_pokemon_storage_system())
        {
            PlaySE(SE_FAILURE);
            PrintMessage_pokemon_storage_system(MSG_HOLDING_POKE_pokemon_storage_system);
            sStorage_pokemon_storage_system->state = 1;
        }
        else if (IsMovingItem_pokemon_storage_system())
        {
            SetPokeStorageTask_pokemon_storage_system(Task_CloseBoxWhileHoldingItem_pokemon_storage_system);
        }
        else
        {
            PlaySE(SE_SELECT);
            PrintMessage_pokemon_storage_system(MSG_EXIT_BOX_pokemon_storage_system);
            ShowYesNoWindow_pokemon_storage_system(0);
            sStorage_pokemon_storage_system->state = 2;
        }
        break;
    case 1:
        if (JOY_NEW(A_BUTTON | B_BUTTON | DPAD_ANY))
        {
            ClearBottomWindow_pokemon_storage_system();
            SetPokeStorageTask_pokemon_storage_system(Task_PokeStorageMain_pokemon_storage_system);
        }
        break;
    case 2:
        switch (Menu_ProcessInputNoWrapClearOnChoose())
        {
        case MENU_B_PRESSED:
        case 1:
            ClearBottomWindow_pokemon_storage_system();
            SetPokeStorageTask_pokemon_storage_system(Task_PokeStorageMain_pokemon_storage_system);
            break;
        case 0:
            PlaySE(SE_PC_OFF);
            ClearBottomWindow_pokemon_storage_system();
            sStorage_pokemon_storage_system->state++;
            break;
        }
        break;
    case 3:
        ComputerScreenCloseEffect(20, 0, 1);
        sStorage_pokemon_storage_system->state++;
        break;
    case 4:
        if (!IsComputerScreenCloseEffectActive())
        {
            UpdateBoxToSendMons_pokemon_storage_system();
            gPlayerPartyCount = CalculatePlayerPartyCount();
            sStorage_pokemon_storage_system->screenChangeType = SCREEN_CHANGE_EXIT_BOX_pokemon_storage_system;
            SetPokeStorageTask_pokemon_storage_system(Task_ChangeScreen_pokemon_storage_system);
        }
        break;
    }
}

static void Task_OnBPressed_pokemon_storage_system(u8 taskId)
{
    switch (sStorage_pokemon_storage_system->state)
    {
    case 0:
        if (IsMonBeingMoved_pokemon_storage_system())
        {
            if (OW_PC_PRESS_B < GEN_4)
            {
                PlaySE(SE_FAILURE);
                PrintMessage_pokemon_storage_system(MSG_HOLDING_POKE_pokemon_storage_system);
                sStorage_pokemon_storage_system->state = 1;
            }
            else if (CanPlaceMon_pokemon_storage_system())
            {
                PlaySE(SE_SELECT);
                SetPokeStorageTask_pokemon_storage_system(Task_PlaceMon_pokemon_storage_system);
            }
            else
            {
                SetPokeStorageTask_pokemon_storage_system(Task_PokeStorageMain_pokemon_storage_system);
            }
        }
        else if (IsMovingItem_pokemon_storage_system())
        {
            SetPokeStorageTask_pokemon_storage_system(Task_CloseBoxWhileHoldingItem_pokemon_storage_system);
        }
        else
        {
            PlaySE(SE_SELECT);
            PrintMessage_pokemon_storage_system(MSG_CONTINUE_BOX_pokemon_storage_system);
            ShowYesNoWindow_pokemon_storage_system(0);
            sStorage_pokemon_storage_system->state = 2;
        }
        break;
    case 1:
        if (JOY_NEW(A_BUTTON | B_BUTTON | DPAD_ANY))
        {
            ClearBottomWindow_pokemon_storage_system();
            SetPokeStorageTask_pokemon_storage_system(Task_PokeStorageMain_pokemon_storage_system);
        }
        break;
    case 2:
        switch (Menu_ProcessInputNoWrapClearOnChoose())
        {
        case 0:
            ClearBottomWindow_pokemon_storage_system();
            SetPokeStorageTask_pokemon_storage_system(Task_PokeStorageMain_pokemon_storage_system);
            break;
        case 1:
        case MENU_B_PRESSED:
            PlaySE(SE_PC_OFF);
            ClearBottomWindow_pokemon_storage_system();
            sStorage_pokemon_storage_system->state++;
            break;
        }
        break;
    case 3:
        ComputerScreenCloseEffect(20, 0, 0);
        sStorage_pokemon_storage_system->state++;
        break;
    case 4:
        if (!IsComputerScreenCloseEffectActive())
        {
            UpdateBoxToSendMons_pokemon_storage_system();
            gPlayerPartyCount = CalculatePlayerPartyCount();
            sStorage_pokemon_storage_system->screenChangeType = SCREEN_CHANGE_EXIT_BOX_pokemon_storage_system;
            SetPokeStorageTask_pokemon_storage_system(Task_ChangeScreen_pokemon_storage_system);
        }
        break;
    }
}

static void Task_ChangeScreen_pokemon_storage_system(u8 taskId)
{
    struct BoxPokemon *boxMons;
    u8 mode, monIndex, maxMonIndex;
    u8 screenChangeType = sStorage_pokemon_storage_system->screenChangeType;

    if (sStorage_pokemon_storage_system->boxOption == OPTION_MOVE_ITEMS_pokemon_storage_system && IsMovingItem_pokemon_storage_system() == TRUE)
        sMovingItemId_pokemon_storage_system = GetMovingItemId_pokemon_storage_system();
    else
        sMovingItemId_pokemon_storage_system = ITEM_NONE;

    switch (screenChangeType)
    {
    case SCREEN_CHANGE_EXIT_BOX_pokemon_storage_system:
    default:
        FreePokeStorageData_pokemon_storage_system();
        SetMainCallback2(CB2_ExitPokeStorage_pokemon_storage_system);
        break;
    case SCREEN_CHANGE_SUMMARY_SCREEN_pokemon_storage_system:
        boxMons = sStorage_pokemon_storage_system->summaryMon.box;
        monIndex = sStorage_pokemon_storage_system->summaryStartPos;
        maxMonIndex = sStorage_pokemon_storage_system->summaryMaxPos;
        mode = sStorage_pokemon_storage_system->summaryScreenMode;
        FreePokeStorageData_pokemon_storage_system();
        if (mode == SUMMARY_MODE_NORMAL && boxMons == &sSavedMovingMon_pokemon_storage_system.box)
            ShowPokemonSummaryScreenHandleDeoxys(mode, boxMons, monIndex, maxMonIndex, CB2_ReturnToPokeStorage_pokemon_storage_system);
        else
            ShowPokemonSummaryScreen(mode, boxMons, monIndex, maxMonIndex, CB2_ReturnToPokeStorage_pokemon_storage_system);
        break;
    case SCREEN_CHANGE_NAME_BOX_pokemon_storage_system:
        FreePokeStorageData_pokemon_storage_system();
        DoNamingScreen(NAMING_SCREEN_BOX, GetBoxNamePtr(StorageGetCurrentBox()), 0, 0, 0, CB2_ReturnToPokeStorage_pokemon_storage_system);
        break;
    case SCREEN_CHANGE_ITEM_FROM_BAG_pokemon_storage_system:
        FreePokeStorageData_pokemon_storage_system();
        GoToBagMenu(ITEMMENULOCATION_PCBOX, 0, CB2_ReturnToPokeStorage_pokemon_storage_system);
        break;
    }

    DestroyTask(taskId);
}

static void GiveChosenBagItem_pokemon_storage_system(void)
{
    u16 itemId = gSpecialVar_ItemId;

    if (itemId != ITEM_NONE)
    {
        u8 pos = GetCursorPosition_pokemon_storage_system();
        if (sInPartyMenu_pokemon_storage_system)
        {
            struct Pokemon *mon = &gPlayerParty[pos];
            SetMonData(&gPlayerParty[pos], MON_DATA_HELD_ITEM, &itemId);
            SetMonFormPSS(&mon->box);
        }
        else
        {
            SetCurrentBoxMonData(pos, MON_DATA_HELD_ITEM, &itemId);
            SetMonFormPSS(&gPokemonStoragePtr->boxes[StorageGetCurrentBox()][pos]);
        }

        RemoveBagItem(itemId, 1);
    }
}

static void FreePokeStorageData_pokemon_storage_system(void)
{
    TilemapUtil_Free_pokemon_storage_system();
    MultiMove_Free_pokemon_storage_system();
    FREE_AND_SET_NULL(sStorage_pokemon_storage_system);
    FreeAllWindowBuffers();
}


