static void SetPartySlotTilemaps_pokemon_storage_system(void)
{
    u8 i;

    // Skips first party slot, it should always be drawn
    // as if it has a Pokémon in it
    for (i = 1; i < PARTY_SIZE; i++)
    {
        s32 species = GetMonData(&gPlayerParty[i], MON_DATA_SPECIES);
        SetPartySlotTilemap_pokemon_storage_system(i, species != SPECIES_NONE);
    }
}

static void SetPartySlotTilemap_pokemon_storage_system(u8 partyId, bool8 hasMon)
{
    u16 i, j, index;
    const u16 *data;

    if (hasMon)
        data = sPartySlotFilled_Tilemap_pokemon_storage_system;
    else
        data = sPartySlotEmpty_Tilemap_pokemon_storage_system;

    index = 3 * (3 * (partyId - 1) + 1);
    index *= 4;
    index += 7;
    for (i = 0; i < 3; i++)
    {
        for (j = 0; j < 4; j++)
            sStorage_pokemon_storage_system->partyMenuTilemapBuffer[index + j] = data[j];

        data += 4;
        index += 12;
    }
}

static void UpdatePartySlotColors_pokemon_storage_system(void)
{
    SetPartySlotTilemaps_pokemon_storage_system();
    TilemapUtil_SetRect_pokemon_storage_system(TILEMAPID_PARTY_MENU_pokemon_storage_system, 0, 0, 12, 22);
    TilemapUtil_Update_pokemon_storage_system(TILEMAPID_PARTY_MENU_pokemon_storage_system);
    ScheduleBgCopyTilemapToVram(1);
}

static void SetUpDoShowPartyMenu_pokemon_storage_system(void)
{
    sStorage_pokemon_storage_system->showPartyMenuState = 0;
    PlaySE(SE_WIN_OPEN);
    SetUpShowPartyMenu_pokemon_storage_system();
}

static bool8 DoShowPartyMenu_pokemon_storage_system(void)
{
    switch (sStorage_pokemon_storage_system->showPartyMenuState)
    {
    case 0:
        if (!ShowPartyMenu_pokemon_storage_system())
        {
            SetCursorInParty_pokemon_storage_system();
            sStorage_pokemon_storage_system->showPartyMenuState++;
        }
        break;
    case 1:
        if (!UpdateCursorPos_pokemon_storage_system())
        {
            if (sStorage_pokemon_storage_system->setMosaic)
                StartDisplayMonMosaicEffect_pokemon_storage_system();
            sStorage_pokemon_storage_system->showPartyMenuState++;
        }
        break;
    case 2:
        return FALSE;
    }
    return TRUE;
}

