static void PrintMessage_pokemon_storage_system(u8 id)
{
    u8 *txtPtr;

    DynamicPlaceholderTextUtil_Reset();
    switch (sMessages_pokemon_storage_system[id].format)
    {
    case MSG_VAR_NONE_pokemon_storage_system:
        break;
    case MSG_VAR_MON_NAME_1_pokemon_storage_system:
    case MSG_VAR_MON_NAME_2:
    case MSG_VAR_MON_NAME_3:
        DynamicPlaceholderTextUtil_SetPlaceholderPtr(0, sStorage_pokemon_storage_system->displayMonName);
        break;
    case MSG_VAR_RELEASE_MON_1_pokemon_storage_system:
    case MSG_VAR_RELEASE_MON_2:
    case MSG_VAR_RELEASE_MON_3_pokemon_storage_system:
        DynamicPlaceholderTextUtil_SetPlaceholderPtr(0, sStorage_pokemon_storage_system->releaseMonName);
        break;
    case MSG_VAR_ITEM_NAME_pokemon_storage_system:
        if (IsMovingItem_pokemon_storage_system())
            txtPtr = StringCopy(sStorage_pokemon_storage_system->itemName, GetMovingItemName());
        else
            txtPtr = StringCopy(sStorage_pokemon_storage_system->itemName, sStorage_pokemon_storage_system->displayMonItemName);

        while (*(txtPtr - 1) == CHAR_SPACE)
            txtPtr--;

        *txtPtr = EOS;
        DynamicPlaceholderTextUtil_SetPlaceholderPtr(0, sStorage_pokemon_storage_system->itemName);
        break;
    }

    DynamicPlaceholderTextUtil_ExpandPlaceholders(sStorage_pokemon_storage_system->messageText, sMessages_pokemon_storage_system[id].text);
    FillWindowPixelBuffer(WIN_MESSAGE_pokemon_storage_system, PIXEL_FILL(1));
    AddTextPrinterParameterized(WIN_MESSAGE_pokemon_storage_system, FONT_NORMAL, sStorage_pokemon_storage_system->messageText, 0, 1, TEXT_SKIP_DRAW, NULL);
    DrawTextBorderOuter(WIN_MESSAGE_pokemon_storage_system, 2, 14);
    PutWindowTilemap(WIN_MESSAGE_pokemon_storage_system);
    CopyWindowToVram(WIN_MESSAGE_pokemon_storage_system, COPYWIN_GFX);
    ScheduleBgCopyTilemapToVram(0);
}

