//------------------------------------------------------------------------------
//  SECTION: Pokémon sprites
//
//  The below functions generally handle the Pokémon icon sprites, including
//  moving them with a scrolling box, shifting the party sprites, and
//  animating released Pokémon.
//------------------------------------------------------------------------------


static void InitMonIconFields_pokemon_storage_system(void)
{
    u16 i;

    LoadMonIconPalettes();
    for (i = 0; i < MAX_MON_ICONS_pokemon_storage_system; i++)
        sStorage_pokemon_storage_system->numIconsPerSpecies[i] = 0;
    for (i = 0; i < MAX_MON_ICONS_pokemon_storage_system; i++)
        sStorage_pokemon_storage_system->iconSpeciesList[i] = SPECIES_NONE;
    for (i = 0; i < PARTY_SIZE; i++)
        sStorage_pokemon_storage_system->partySprites[i] = NULL;
    for (i = 0; i < IN_BOX_COUNT; i++)
        sStorage_pokemon_storage_system->boxMonsSprites[i] = NULL;

    sStorage_pokemon_storage_system->movingMonSprite = NULL;
    sStorage_pokemon_storage_system->unkUnused1 = 0;
}

static u8 GetMonIconPriorityByCursorPos_pokemon_storage_system(void)
{
    return (IsCursorInBox_pokemon_storage_system() ? 2 : 1);
}

static void CreateMovingMonIcon_pokemon_storage_system(void)
{
    u32 personality = GetMonData(&sStorage_pokemon_storage_system->movingMon, MON_DATA_PERSONALITY);
    u16 species = GetMonData(&sStorage_pokemon_storage_system->movingMon, MON_DATA_SPECIES_OR_EGG);
    u8 priority = GetMonIconPriorityByCursorPos_pokemon_storage_system();

    sStorage_pokemon_storage_system->movingMonSprite = CreateMonIconSprite_pokemon_storage_system(species, personality, 0, 0, priority, 7);
    sStorage_pokemon_storage_system->movingMonSprite->callback = SpriteCB_HeldMon_pokemon_storage_system;
}

static void InitBoxMonSprites_pokemon_storage_system(u8 boxId)
{
    u8 boxPosition;
    u16 i, j, count;
    u16 species;
    u32 personality;

    count = 0;
    boxPosition = 0;

    // For each box slot, create a Pokémon icon if a species is present
    for (i = 0; i < IN_BOX_ROWS; i++)
    {
        for (j = 0; j < IN_BOX_COLUMNS; j++)
        {
            species = GetBoxMonDataAt(boxId, boxPosition, MON_DATA_SPECIES_OR_EGG);
            if (species != SPECIES_NONE)
            {
                personality = GetBoxMonDataAt(boxId, boxPosition, MON_DATA_PERSONALITY);
                sStorage_pokemon_storage_system->boxMonsSprites[count] = CreateMonIconSprite_pokemon_storage_system(species, personality, 8 * (3 * j) + 100, 8 * (3 * i) + 44, 2, 19 - j);
            }
            else
            {
                sStorage_pokemon_storage_system->boxMonsSprites[count] = NULL;
            }
            boxPosition++;
            count++;
        }
    }

    // If in item mode, set all Pokémon icons with no item to be transparent
    if (sStorage_pokemon_storage_system->boxOption == OPTION_MOVE_ITEMS_pokemon_storage_system)
    {
        for (boxPosition = 0; boxPosition < IN_BOX_COUNT; boxPosition++)
        {
            if (GetBoxMonDataAt(boxId, boxPosition, MON_DATA_HELD_ITEM) == ITEM_NONE)
                sStorage_pokemon_storage_system->boxMonsSprites[boxPosition]->oam.objMode = ST_OAM_OBJ_BLEND;
        }
    }
}

static void CreateBoxMonIconAtPos_pokemon_storage_system(u8 boxPosition)
{
    u16 species = GetCurrentBoxMonData(boxPosition, MON_DATA_SPECIES_OR_EGG);

    if (species != SPECIES_NONE)
    {
        s16 x = 8 * (3 * (boxPosition % IN_BOX_COLUMNS)) + 100;
        s16 y = 8 * (3 * (boxPosition / IN_BOX_COLUMNS)) + 44;
        u32 personality = GetCurrentBoxMonData(boxPosition, MON_DATA_PERSONALITY);

        sStorage_pokemon_storage_system->boxMonsSprites[boxPosition] = CreateMonIconSprite_pokemon_storage_system(species, personality, x, y, 2, 19 - (boxPosition % IN_BOX_COLUMNS));
        if (sStorage_pokemon_storage_system->boxOption == OPTION_MOVE_ITEMS_pokemon_storage_system)
            sStorage_pokemon_storage_system->boxMonsSprites[boxPosition]->oam.objMode = ST_OAM_OBJ_BLEND;
    }
}

#define sDistance_pokemon_storage_system      data[1]
#define sSpeed_pokemon_storage_system         data[2]
#define sScrollInDestX_pokemon_storage_system data[3]
#define sDelay_pokemon_storage_system         data[4]
#define sScrollOutX_pokemon_storage_system    data[5]

static void StartBoxMonIconsScrollOut_pokemon_storage_system(s16 speed)
{
    u16 i;

    for (i = 0; i < IN_BOX_COUNT; i++)
    {
        if (sStorage_pokemon_storage_system->boxMonsSprites[i] != NULL)
        {
            sStorage_pokemon_storage_system->boxMonsSprites[i]->sSpeed_pokemon_storage_system = speed;
            sStorage_pokemon_storage_system->boxMonsSprites[i]->sDelay_pokemon_storage_system = 1;
            sStorage_pokemon_storage_system->boxMonsSprites[i]->callback = SpriteCB_BoxMonIconScrollOut_pokemon_storage_system;
        }
    }
}

static void SpriteCB_BoxMonIconScrollIn_pokemon_storage_system(struct Sprite *sprite)
{
    if (sprite->sDistance_pokemon_storage_system != 0)
    {
        // Icon moving
        sprite->sDistance_pokemon_storage_system--;
        sprite->x += sprite->sSpeed_pokemon_storage_system;
    }
    else
    {
        // Icon arrived
        sStorage_pokemon_storage_system->iconScrollNumIncoming--;
        sprite->x = sprite->sScrollInDestX_pokemon_storage_system;
        sprite->callback = SpriteCallbackDummy;
    }
}

static void SpriteCB_BoxMonIconScrollOut_pokemon_storage_system(struct Sprite *sprite)
{
    if (sprite->sDelay_pokemon_storage_system != 0)
    {
        sprite->sDelay_pokemon_storage_system--;
    }
    else
    {
        // Icon moving
        sprite->x += sprite->sSpeed_pokemon_storage_system;
        sprite->sScrollOutX_pokemon_storage_system = sprite->x + sprite->x2;

        // Check if icon offscreen
        if (sprite->sScrollOutX_pokemon_storage_system <= 68 || sprite->sScrollOutX_pokemon_storage_system >= 252)
            sprite->callback = SpriteCallbackDummy;
    }
}

// Sprites for Pokémon icons are destroyed during
// the box scroll once they've gone offscreen
static void DestroyBoxMonIconsInColumn_pokemon_storage_system(u8 column)
{
    u16 row;
    u8 boxPosition = column;

    for (row = 0; row < IN_BOX_ROWS; row++)
    {
        if (sStorage_pokemon_storage_system->boxMonsSprites[boxPosition] != NULL)
        {
            DestroyBoxMonIcon_pokemon_storage_system(sStorage_pokemon_storage_system->boxMonsSprites[boxPosition]);
            sStorage_pokemon_storage_system->boxMonsSprites[boxPosition] = NULL;
        }
        boxPosition += IN_BOX_COLUMNS;
    }
}

// Create the appearing icons for the incoming scrolling box
static u8 CreateBoxMonIconsInColumn_pokemon_storage_system(u8 column, u16 distance, s16 speed)
{
    s32 i;
    u16 y = 44;
    s16 xDest = 8 * (3 * column) + 100;
    u16 x = xDest - ((distance + 1) * speed);
    u8 subpriority = 19 - column;
    u8 iconsCreated = 0;
    u8 boxPosition = column;

    if (sStorage_pokemon_storage_system->boxOption != OPTION_MOVE_ITEMS_pokemon_storage_system)
    {
        for (i = 0; i < IN_BOX_ROWS; i++)
        {
            if (sStorage_pokemon_storage_system->boxSpecies[boxPosition] != SPECIES_NONE)
            {
                sStorage_pokemon_storage_system->boxMonsSprites[boxPosition] = CreateMonIconSprite_pokemon_storage_system(sStorage_pokemon_storage_system->boxSpecies[boxPosition],
                                                                                        sStorage_pokemon_storage_system->boxPersonalities[boxPosition],
                                                                                        x, y, 2, subpriority);
                if (sStorage_pokemon_storage_system->boxMonsSprites[boxPosition] != NULL)
                {
                    sStorage_pokemon_storage_system->boxMonsSprites[boxPosition]->sDistance_pokemon_storage_system = distance;
                    sStorage_pokemon_storage_system->boxMonsSprites[boxPosition]->sSpeed_pokemon_storage_system = speed;
                    sStorage_pokemon_storage_system->boxMonsSprites[boxPosition]->sScrollInDestX_pokemon_storage_system = xDest;
                    sStorage_pokemon_storage_system->boxMonsSprites[boxPosition]->callback = SpriteCB_BoxMonIconScrollIn_pokemon_storage_system;
                    iconsCreated++;
                }
            }
            boxPosition += IN_BOX_COLUMNS;
            y += 24;
        }
    }
    else
    {
        // Separate case for Move Items mode is used
        // to create the icons with the proper blend
        for (i = 0; i < IN_BOX_ROWS; i++)
        {
            if (sStorage_pokemon_storage_system->boxSpecies[boxPosition] != SPECIES_NONE)
            {
                sStorage_pokemon_storage_system->boxMonsSprites[boxPosition] = CreateMonIconSprite_pokemon_storage_system(sStorage_pokemon_storage_system->boxSpecies[boxPosition],
                                                                                        sStorage_pokemon_storage_system->boxPersonalities[boxPosition],
                                                                                        x, y, 2, subpriority);
                if (sStorage_pokemon_storage_system->boxMonsSprites[boxPosition] != NULL)
                {
                    sStorage_pokemon_storage_system->boxMonsSprites[boxPosition]->sDistance_pokemon_storage_system = distance;
                    sStorage_pokemon_storage_system->boxMonsSprites[boxPosition]->sSpeed_pokemon_storage_system = speed;
                    sStorage_pokemon_storage_system->boxMonsSprites[boxPosition]->sScrollInDestX_pokemon_storage_system = xDest;
                    sStorage_pokemon_storage_system->boxMonsSprites[boxPosition]->callback = SpriteCB_BoxMonIconScrollIn_pokemon_storage_system;
                    if (GetBoxMonDataAt(sStorage_pokemon_storage_system->incomingBoxId, boxPosition, MON_DATA_HELD_ITEM) == ITEM_NONE)
                        sStorage_pokemon_storage_system->boxMonsSprites[boxPosition]->oam.objMode = ST_OAM_OBJ_BLEND;
                    iconsCreated++;
                }
            }
            boxPosition += IN_BOX_COLUMNS;
            y += 24;
        }
    }

    return iconsCreated;
}

#undef sDistance_pokemon_storage_system
#undef sSpeed_pokemon_storage_system
#undef sScrollInDestX_pokemon_storage_system
#undef sDelay_pokemon_storage_system
#undef sScrollOutX_pokemon_storage_system

static void InitBoxMonIconScroll_pokemon_storage_system(u8 boxId, s8 direction)
{
    sStorage_pokemon_storage_system->iconScrollState = 0;
    sStorage_pokemon_storage_system->iconScrollToBoxId = boxId;
    sStorage_pokemon_storage_system->iconScrollDirection = direction;
    sStorage_pokemon_storage_system->iconScrollDistance = 32;
    sStorage_pokemon_storage_system->iconScrollSpeed = -(6 * direction);
    sStorage_pokemon_storage_system->iconScrollNumIncoming = 0;
    GetIncomingBoxMonData_pokemon_storage_system(boxId);
    if (direction > 0)
        sStorage_pokemon_storage_system->iconScrollCurColumn = 0;
    else
        sStorage_pokemon_storage_system->iconScrollCurColumn = IN_BOX_COLUMNS - 1;

    sStorage_pokemon_storage_system->iconScrollPos = (24 * sStorage_pokemon_storage_system->iconScrollCurColumn) + 100;
    StartBoxMonIconsScrollOut_pokemon_storage_system(sStorage_pokemon_storage_system->iconScrollSpeed);
}

static bool8 UpdateBoxMonIconScroll_pokemon_storage_system(void)
{
    if (sStorage_pokemon_storage_system->iconScrollDistance != 0)
        sStorage_pokemon_storage_system->iconScrollDistance--;

    switch (sStorage_pokemon_storage_system->iconScrollState)
    {
    case 0:
        sStorage_pokemon_storage_system->iconScrollPos += sStorage_pokemon_storage_system->iconScrollSpeed;
        if (sStorage_pokemon_storage_system->iconScrollPos <= 64 || sStorage_pokemon_storage_system->iconScrollPos >= 252)
        {
            // A column of icons has gone offscreen, destroy them
            DestroyBoxMonIconsInColumn_pokemon_storage_system(sStorage_pokemon_storage_system->iconScrollCurColumn);
            sStorage_pokemon_storage_system->iconScrollPos += sStorage_pokemon_storage_system->iconScrollDirection * 24;
            sStorage_pokemon_storage_system->iconScrollState++;
        }
        break;
    case 1:
        // Create the new incoming column of icons
        sStorage_pokemon_storage_system->iconScrollPos += sStorage_pokemon_storage_system->iconScrollSpeed;
        sStorage_pokemon_storage_system->iconScrollNumIncoming += CreateBoxMonIconsInColumn_pokemon_storage_system(sStorage_pokemon_storage_system->iconScrollCurColumn, sStorage_pokemon_storage_system->iconScrollDistance, sStorage_pokemon_storage_system->iconScrollSpeed);

        if ((sStorage_pokemon_storage_system->iconScrollDirection > 0 && sStorage_pokemon_storage_system->iconScrollCurColumn == IN_BOX_COLUMNS - 1)
         || (sStorage_pokemon_storage_system->iconScrollDirection < 0 && sStorage_pokemon_storage_system->iconScrollCurColumn == 0))
        {
            // Scroll has reached final column
            sStorage_pokemon_storage_system->iconScrollState++;
        }
        else
        {
            // Continue scrolling
            sStorage_pokemon_storage_system->iconScrollCurColumn += sStorage_pokemon_storage_system->iconScrollDirection;
            sStorage_pokemon_storage_system->iconScrollState = 0;
        }
        break;
    case 2:
        // Wait to make sure all icons have arrived
        if (sStorage_pokemon_storage_system->iconScrollNumIncoming == 0)
        {
            sStorage_pokemon_storage_system->iconScrollDistance++;
            return FALSE;
        }
        break;
    default:
        return FALSE;
    }

    return TRUE;
}

static void GetIncomingBoxMonData_pokemon_storage_system(u8 boxId)
{
    s32 i, j, boxPosition;

    boxPosition = 0;
    for (i = 0; i < IN_BOX_ROWS; i++)
    {
        for (j = 0; j < IN_BOX_COLUMNS; j++)
        {
            sStorage_pokemon_storage_system->boxSpecies[boxPosition] = GetBoxMonDataAt(boxId, boxPosition, MON_DATA_SPECIES_OR_EGG);
            if (sStorage_pokemon_storage_system->boxSpecies[boxPosition] != SPECIES_NONE)
                sStorage_pokemon_storage_system->boxPersonalities[boxPosition] = GetBoxMonDataAt(boxId, boxPosition, MON_DATA_PERSONALITY);
            boxPosition++;
        }
    }

    sStorage_pokemon_storage_system->incomingBoxId = boxId;
}

static void DestroyBoxMonIconAtPosition_pokemon_storage_system(u8 boxPosition)
{
    if (sStorage_pokemon_storage_system->boxMonsSprites[boxPosition] != NULL)
    {
        DestroyBoxMonIcon_pokemon_storage_system(sStorage_pokemon_storage_system->boxMonsSprites[boxPosition]);
        sStorage_pokemon_storage_system->boxMonsSprites[boxPosition] = NULL;
    }
}

static void SetBoxMonIconObjMode_pokemon_storage_system(u8 boxPosition, u8 objMode)
{
    if (sStorage_pokemon_storage_system->boxMonsSprites[boxPosition] != NULL)
        sStorage_pokemon_storage_system->boxMonsSprites[boxPosition]->oam.objMode = objMode;
}

static void CreatePartyMonsSprites_pokemon_storage_system(bool8 visible)
{
    u16 i, count;
    u16 species = GetMonData(&gPlayerParty[0], MON_DATA_SPECIES_OR_EGG);
    u32 personality = GetMonData(&gPlayerParty[0], MON_DATA_PERSONALITY);

    sStorage_pokemon_storage_system->partySprites[0] = CreateMonIconSprite_pokemon_storage_system(species, personality, 104, 64, 1, 12);
    count = 1;
    for (i = 1; i < PARTY_SIZE; i++)
    {
        species = GetMonData(&gPlayerParty[i], MON_DATA_SPECIES_OR_EGG);
        if (species != SPECIES_NONE)
        {
            personality = GetMonData(&gPlayerParty[i], MON_DATA_PERSONALITY);
            sStorage_pokemon_storage_system->partySprites[i] = CreateMonIconSprite_pokemon_storage_system(species, personality, 152,  8 * (3 * (i - 1)) + 16, 1, 12);
            count++;
        }
        else
        {
            sStorage_pokemon_storage_system->partySprites[i] = NULL;
        }
    }

    if (!visible)
    {
        for (i = 0; i < count; i++)
        {
            sStorage_pokemon_storage_system->partySprites[i]->y -= DISPLAY_HEIGHT;
            sStorage_pokemon_storage_system->partySprites[i]->invisible = TRUE;
        }
    }

    if (sStorage_pokemon_storage_system->boxOption == OPTION_MOVE_ITEMS_pokemon_storage_system)
    {
        for (i = 0; i < PARTY_SIZE; i++)
        {
            if (sStorage_pokemon_storage_system->partySprites[i] != NULL && GetMonData(&gPlayerParty[i], MON_DATA_HELD_ITEM) == ITEM_NONE)
                sStorage_pokemon_storage_system->partySprites[i]->oam.objMode = ST_OAM_OBJ_BLEND;
        }
    }
}

static void CompactPartySprites_pokemon_storage_system(void)
{
    u16 i, targetSlot;

    sStorage_pokemon_storage_system->numPartyToCompact = 0;
    for (i = 0, targetSlot = 0; i < PARTY_SIZE; i++)
    {
        if (sStorage_pokemon_storage_system->partySprites[i] != NULL)
        {
            if (i != targetSlot)
            {
                MovePartySpriteToNextSlot_pokemon_storage_system(sStorage_pokemon_storage_system->partySprites[i], targetSlot);
                sStorage_pokemon_storage_system->partySprites[i] = NULL;
                sStorage_pokemon_storage_system->numPartyToCompact++;
            }
            targetSlot++;
        }
    }
}

static u8 GetNumPartySpritesCompacting_pokemon_storage_system(void)
{
    return sStorage_pokemon_storage_system->numPartyToCompact;
}

#define sPartyId_pokemon_storage_system   data[1]
#define sMonX_pokemon_storage_system      data[2]
#define sMonY_pokemon_storage_system      data[3]
#define sSpeedX_pokemon_storage_system    data[4]
#define sSpeedY_pokemon_storage_system    data[5]
#define sMoveSteps_pokemon_storage_system data[6]

static void MovePartySpriteToNextSlot_pokemon_storage_system(struct Sprite *sprite, u16 partyId)
{
    s16 x, y;

    sprite->sPartyId_pokemon_storage_system = partyId;
    if (partyId == 0)
        x = 104, y = 64;
    else
        x = 152, y = 8 * (3 * (partyId - 1)) + 16;

    sprite->sMonX_pokemon_storage_system = (u16)(sprite->x) * 8;
    sprite->sMonY_pokemon_storage_system = (u16)(sprite->y) * 8;
    sprite->sSpeedX_pokemon_storage_system = ((x * 8) - sprite->sMonX_pokemon_storage_system) / 8;
    sprite->sSpeedY_pokemon_storage_system = ((y * 8) - sprite->sMonY_pokemon_storage_system) / 8;
    sprite->sMoveSteps_pokemon_storage_system = 8;
    sprite->callback = SpriteCB_MovePartyMonToNextSlot_pokemon_storage_system;
}

static void SpriteCB_MovePartyMonToNextSlot_pokemon_storage_system(struct Sprite *sprite)
{
    if (sprite->sMoveSteps_pokemon_storage_system != 0)
    {
        s16 x = sprite->sMonX_pokemon_storage_system += sprite->sSpeedX_pokemon_storage_system;
        s16 y = sprite->sMonY_pokemon_storage_system += sprite->sSpeedY_pokemon_storage_system;
        sprite->x = x / 8u;
        sprite->y = y / 8u;
        sprite->sMoveSteps_pokemon_storage_system--;
    }
    else
    {
        if (sprite->sPartyId_pokemon_storage_system == 0)
        {
            sprite->x = 104;
            sprite->y = 64;
        }
        else
        {
            sprite->x = 152;
            sprite->y = 8 * (3 * (sprite->sPartyId_pokemon_storage_system - 1)) + 16;
        }
        sprite->callback = SpriteCallbackDummy;
        sStorage_pokemon_storage_system->partySprites[sprite->sPartyId_pokemon_storage_system] = sprite;
        sStorage_pokemon_storage_system->numPartyToCompact--;
    }
}

#undef sPartyId_pokemon_storage_system
#undef sMonX_pokemon_storage_system
#undef sMonY_pokemon_storage_system
#undef sSpeedX_pokemon_storage_system
#undef sSpeedY_pokemon_storage_system
#undef sMoveSteps_pokemon_storage_system

