static void MovePartySprites_pokemon_storage_system(s16 yDelta)
{
    u16 i, posY;

    for (i = 0; i < PARTY_SIZE; i++)
    {
        if (sStorage_pokemon_storage_system->partySprites[i] != NULL)
        {
            sStorage_pokemon_storage_system->partySprites[i]->y += yDelta;
            posY = sStorage_pokemon_storage_system->partySprites[i]->y + sStorage_pokemon_storage_system->partySprites[i]->y2 + sStorage_pokemon_storage_system->partySprites[i]->centerToCornerVecY;
            posY += 16;
            if (posY > 192)
                sStorage_pokemon_storage_system->partySprites[i]->invisible = TRUE;
            else
                sStorage_pokemon_storage_system->partySprites[i]->invisible = FALSE;
        }
    }
}

