static void SetMenuText_pokemon_storage_system(u8 textId)
{
    if (sStorage_pokemon_storage_system->menuItemsCount < ARRAY_COUNT(sStorage_pokemon_storage_system->menuItems))
    {
        u8 len;
        struct StorageMenu *menu = &sStorage_pokemon_storage_system->menuItems[sStorage_pokemon_storage_system->menuItemsCount];

        menu->text = sMenuTexts_pokemon_storage_system[textId];
        menu->textId = textId;
        len = StringLength(menu->text);
        if (len > sStorage_pokemon_storage_system->menuWidth)
            sStorage_pokemon_storage_system->menuWidth = len;

        sStorage_pokemon_storage_system->menuItemsCount++;
    }
}

static s8 GetMenuItemTextId_pokemon_storage_system(u8 menuIdx)
{
    if (menuIdx >= sStorage_pokemon_storage_system->menuItemsCount)
        return -1;
    else
        return sStorage_pokemon_storage_system->menuItems[menuIdx].textId;
}

static void AddMenu_pokemon_storage_system(void)
{
    sStorage_pokemon_storage_system->menuWindow.width = sStorage_pokemon_storage_system->menuWidth + 2;
    sStorage_pokemon_storage_system->menuWindow.height = 2 * sStorage_pokemon_storage_system->menuItemsCount;
    sStorage_pokemon_storage_system->menuWindow.tilemapLeft = 29 - sStorage_pokemon_storage_system->menuWindow.width;
    sStorage_pokemon_storage_system->menuWindow.tilemapTop = 15 - sStorage_pokemon_storage_system->menuWindow.height;
    sStorage_pokemon_storage_system->menuWindowId = AddWindow(&sStorage_pokemon_storage_system->menuWindow);
    ClearWindowTilemap(sStorage_pokemon_storage_system->menuWindowId);
    DrawStdFrameWithCustomTileAndPalette(sStorage_pokemon_storage_system->menuWindowId, FALSE, 11, 14);
    PrintMenuTable(sStorage_pokemon_storage_system->menuWindowId, sStorage_pokemon_storage_system->menuItemsCount, (void *)sStorage_pokemon_storage_system->menuItems);
    InitMenuInUpperLeftCornerNormal(sStorage_pokemon_storage_system->menuWindowId, sStorage_pokemon_storage_system->menuItemsCount, 0);
    ScheduleBgCopyTilemapToVram(0);
    sStorage_pokemon_storage_system->menuUnusedField = 0;
}

// Called after AddMenu_pokemon_storage_system to determine whether or not the handler callback should
// wait to move on to the next state. Evidently there was no need to wait, and
// now it always returns FALSE
static bool8 IsMenuLoading_pokemon_storage_system(void)
{
    return FALSE;
}

static s16 HandleMenuInput_pokemon_storage_system(void)
{
    s32 input = MENU_NOTHING_CHOSEN;

    do
    {
        if (JOY_NEW(A_BUTTON))
        {
            input = Menu_GetCursorPos();
            break;
        }
        else if (JOY_NEW(B_BUTTON))
        {
            PlaySE(SE_SELECT);
            input = MENU_B_PRESSED;
        }

        if (JOY_NEW(DPAD_UP))
        {
            PlaySE(SE_SELECT);
            Menu_MoveCursor(-1);
        }
        else if (JOY_NEW(DPAD_DOWN))
        {
            PlaySE(SE_SELECT);
            Menu_MoveCursor(1);
        }
    } while (0);

    if (input != MENU_NOTHING_CHOSEN)
        RemoveMenu_pokemon_storage_system();

    if (input >= 0)
        input = sStorage_pokemon_storage_system->menuItems[input].textId;

    return input;
}

static void RemoveMenu_pokemon_storage_system(void)
{
    ClearStdWindowAndFrameToTransparent(sStorage_pokemon_storage_system->menuWindowId, TRUE);
    RemoveWindow(sStorage_pokemon_storage_system->menuWindowId);
}


