static void CreateItemIconSprites_pokemon_storage_system(void)
{
    s32 i;
    u8 spriteId;
    struct CompressedSpriteSheet spriteSheet;
    struct SpriteTemplate spriteTemplate;

    if (sStorage_pokemon_storage_system->boxOption == OPTION_MOVE_ITEMS_pokemon_storage_system)
    {
        spriteSheet.data = sItemIconGfxBuffer_pokemon_storage_system;
        spriteSheet.size = 0x200;
        spriteTemplate = sSpriteTemplate_ItemIcon_pokemon_storage_system;

        for (i = 0; i < MAX_ITEM_ICONS_pokemon_storage_system; i++)
        {
            spriteSheet.tag = GFXTAG_ITEM_ICON_0_pokemon_storage_system + i;
            LoadCompressedSpriteSheet(&spriteSheet);
            sStorage_pokemon_storage_system->itemIcons[i].tiles = GetSpriteTileStartByTag(spriteSheet.tag) * TILE_SIZE_4BPP + (void *)(OBJ_VRAM0);
            sStorage_pokemon_storage_system->itemIcons[i].palIndex = AllocSpritePalette(PALTAG_ITEM_ICON_0_pokemon_storage_system + i);
            sStorage_pokemon_storage_system->itemIcons[i].palIndex = OBJ_PLTT_ID(sStorage_pokemon_storage_system->itemIcons[i].palIndex);
            spriteTemplate.tileTag = GFXTAG_ITEM_ICON_0_pokemon_storage_system + i;
            spriteTemplate.paletteTag = PALTAG_ITEM_ICON_0_pokemon_storage_system + i;
            spriteId = CreateSprite(&spriteTemplate, 0, 0, 11);
            sStorage_pokemon_storage_system->itemIcons[i].sprite = &gSprites[spriteId];
            sStorage_pokemon_storage_system->itemIcons[i].sprite->invisible = TRUE;
            sStorage_pokemon_storage_system->itemIcons[i].active = FALSE;
        }
    }
    sStorage_pokemon_storage_system->movingItemId = ITEM_NONE;
}

static void TryLoadItemIconAtPos_pokemon_storage_system(u8 cursorArea, u8 cursorPos)
{
    u16 heldItem;

    if (sStorage_pokemon_storage_system->boxOption != OPTION_MOVE_ITEMS_pokemon_storage_system)
        return;

    // If we've already loaded the item here, stop
    if (IsItemIconAtPosition_pokemon_storage_system(cursorArea, cursorPos))
        return;

    switch (cursorArea)
    {
    case CURSOR_AREA_IN_BOX_pokemon_storage_system:
        if (!GetCurrentBoxMonData(cursorPos, MON_DATA_SANITY_HAS_SPECIES))
            return;
        heldItem = GetCurrentBoxMonData(cursorPos, MON_DATA_HELD_ITEM);
        break;
    case CURSOR_AREA_IN_PARTY_pokemon_storage_system:
        if (cursorPos >= PARTY_SIZE || !GetMonData(&gPlayerParty[cursorPos], MON_DATA_SANITY_HAS_SPECIES))
            return;
        heldItem = GetMonData(&gPlayerParty[cursorPos], MON_DATA_HELD_ITEM);
        break;
    default:
        return;
    }

    if (heldItem != ITEM_NONE)
    {
        const u32 *tiles = GetItemIconPic(heldItem);
        const u32 *pal = GetItemIconPalette(heldItem);
        u8 id = GetNewItemIconIdx_pokemon_storage_system();

        SetItemIconPosition_pokemon_storage_system(id, cursorArea, cursorPos);
        LoadItemIconGfx_pokemon_storage_system(id, tiles, pal);
        SetItemIconAffineAnim_pokemon_storage_system(id, ITEM_ANIM_APPEAR_pokemon_storage_system);
        SetItemIconActive_pokemon_storage_system(id, TRUE);
    }
}

static void TryHideItemIconAtPos_pokemon_storage_system(u8 cursorArea, u8 cursorPos)
{
    u8 id;

    if (sStorage_pokemon_storage_system->boxOption != OPTION_MOVE_ITEMS_pokemon_storage_system)
        return;

    id = GetItemIconIdxByPosition_pokemon_storage_system(cursorArea, cursorPos);
    SetItemIconAffineAnim_pokemon_storage_system(id, ITEM_ANIM_DISAPPEAR_pokemon_storage_system);
    SetItemIconCallback_pokemon_storage_system(id, ITEM_CB_WAIT_ANIM_pokemon_storage_system, cursorArea, cursorPos);
}

static void TakeItemFromMon_pokemon_storage_system(u8 cursorArea, u8 cursorPos)
{
    u8 id;
    u16 itemId;

    if (sStorage_pokemon_storage_system->boxOption != OPTION_MOVE_ITEMS_pokemon_storage_system)
        return;

    id = GetItemIconIdxByPosition_pokemon_storage_system(cursorArea, cursorPos);
    itemId = ITEM_NONE;
    SetItemIconAffineAnim_pokemon_storage_system(id, ITEM_ANIM_PICK_UP_pokemon_storage_system);
    SetItemIconCallback_pokemon_storage_system(id, ITEM_CB_TO_HAND_pokemon_storage_system, cursorArea, cursorPos);
    SetItemIconPosition_pokemon_storage_system(id, CURSOR_AREA_IN_HAND_pokemon_storage_system, 0);
    if (cursorArea == CURSOR_AREA_IN_BOX_pokemon_storage_system)
    {
        SetCurrentBoxMonData(cursorPos, MON_DATA_HELD_ITEM, &itemId);
        SetBoxMonIconObjMode_pokemon_storage_system(cursorPos, ST_OAM_OBJ_BLEND);
        SetMonFormPSS(&gPokemonStoragePtr->boxes[StorageGetCurrentBox()][cursorPos]);
    }
    else
    {
        struct Pokemon *mon = &gPlayerParty[cursorPos];
        SetMonData(&gPlayerParty[cursorPos], MON_DATA_HELD_ITEM, &itemId);
        SetPartyMonIconObjMode_pokemon_storage_system(cursorPos, ST_OAM_OBJ_BLEND);
        SetMonFormPSS(&mon->box);
    }

    sStorage_pokemon_storage_system->movingItemId = sStorage_pokemon_storage_system->displayMonItemId;
}

static void InitItemIconInCursor_pokemon_storage_system(u16 itemId)
{
    const u32 *tiles = GetItemIconPic(itemId);
    const u32 *pal = GetItemIconPalette(itemId);
    u8 id = GetNewItemIconIdx_pokemon_storage_system();
    LoadItemIconGfx_pokemon_storage_system(id, tiles, pal);
    SetItemIconAffineAnim_pokemon_storage_system(id, ITEM_ANIM_LARGE_pokemon_storage_system);
    SetItemIconCallback_pokemon_storage_system(id, ITEM_CB_TO_HAND_pokemon_storage_system, CURSOR_AREA_IN_BOX_pokemon_storage_system, 0);
    SetItemIconPosition_pokemon_storage_system(id, CURSOR_AREA_IN_HAND_pokemon_storage_system, 0);
    SetItemIconActive_pokemon_storage_system(id, TRUE);
    sStorage_pokemon_storage_system->movingItemId = itemId;
}

static void SwapItemsWithMon_pokemon_storage_system(u8 cursorArea, u8 cursorPos)
{
    u8 id;
    u16 itemId;

    if (sStorage_pokemon_storage_system->boxOption != OPTION_MOVE_ITEMS_pokemon_storage_system)
        return;

    id = GetItemIconIdxByPosition_pokemon_storage_system(cursorArea, cursorPos);
    SetItemIconAffineAnim_pokemon_storage_system(id, ITEM_ANIM_PICK_UP_pokemon_storage_system);
    SetItemIconCallback_pokemon_storage_system(id, ITEM_CB_SWAP_TO_HAND_pokemon_storage_system, CURSOR_AREA_IN_HAND_pokemon_storage_system, 0);
    if (cursorArea == CURSOR_AREA_IN_BOX_pokemon_storage_system)
    {
        itemId = GetCurrentBoxMonData(cursorPos, MON_DATA_HELD_ITEM);
        SetCurrentBoxMonData(cursorPos, MON_DATA_HELD_ITEM, &sStorage_pokemon_storage_system->movingItemId);
        sStorage_pokemon_storage_system->movingItemId = itemId;
        SetMonFormPSS(&gPokemonStoragePtr->boxes[StorageGetCurrentBox()][cursorPos]);
    }
    else
    {
        struct Pokemon *mon = &gPlayerParty[cursorPos];
        itemId = GetMonData(&gPlayerParty[cursorPos], MON_DATA_HELD_ITEM);
        SetMonData(&gPlayerParty[cursorPos], MON_DATA_HELD_ITEM, &sStorage_pokemon_storage_system->movingItemId);
        sStorage_pokemon_storage_system->movingItemId = itemId;
        SetMonFormPSS(&mon->box);
    }

    id = GetItemIconIdxByPosition_pokemon_storage_system(CURSOR_AREA_IN_HAND_pokemon_storage_system, 0);
    SetItemIconAffineAnim_pokemon_storage_system(id, ITEM_ANIM_PUT_DOWN_pokemon_storage_system);
    SetItemIconCallback_pokemon_storage_system(id, ITEM_CB_SWAP_TO_MON_pokemon_storage_system, cursorArea, cursorPos);
}

