// The party menu is being closed, if the cursor is on
// a Pokémon that has a held item make sure it slides
// up along with the closing menu.
static void MoveHeldItemWithPartyMenu_pokemon_storage_system(void)
{
    s32 i;

    if (sStorage_pokemon_storage_system->boxOption != OPTION_MOVE_ITEMS_pokemon_storage_system)
        return;

    for (i = 0; i < MAX_ITEM_ICONS_pokemon_storage_system; i++)
    {
        if (sStorage_pokemon_storage_system->itemIcons[i].active
         && sStorage_pokemon_storage_system->itemIcons[i].area == CURSOR_AREA_IN_PARTY_pokemon_storage_system)
            SetItemIconCallback_pokemon_storage_system(i, ITEM_CB_HIDE_PARTY_pokemon_storage_system, CURSOR_AREA_IN_HAND_pokemon_storage_system, 0);
    }
}

static bool8 IsItemIconAnimActive_pokemon_storage_system(void)
{
    s32 i;

    for (i = 0; i < MAX_ITEM_ICONS_pokemon_storage_system; i++)
    {
        if (sStorage_pokemon_storage_system->itemIcons[i].active)
        {
            if (!sStorage_pokemon_storage_system->itemIcons[i].sprite->affineAnimEnded
              && sStorage_pokemon_storage_system->itemIcons[i].sprite->affineAnimBeginning)
                return TRUE;
            if (sStorage_pokemon_storage_system->itemIcons[i].sprite->callback != SpriteCallbackDummy
             && sStorage_pokemon_storage_system->itemIcons[i].sprite->callback != SpriteCB_ItemIcon_SetPosToCursor_pokemon_storage_system)
                return TRUE;
        }
    }
    return FALSE;
}

static bool8 IsMovingItem_pokemon_storage_system(void)
{
    s32 i;

    if (sStorage_pokemon_storage_system->boxOption == OPTION_MOVE_ITEMS_pokemon_storage_system)
    {
        for (i = 0; i < MAX_ITEM_ICONS_pokemon_storage_system; i++)
        {
            if (sStorage_pokemon_storage_system->itemIcons[i].active
             && sStorage_pokemon_storage_system->itemIcons[i].area == CURSOR_AREA_IN_HAND_pokemon_storage_system)
                return TRUE;
        }
    }
    return FALSE;
}

static const u8 *GetMovingItemName(void)
{
    return ItemId_GetName(sStorage_pokemon_storage_system->movingItemId);
}

static u16 GetMovingItemId_pokemon_storage_system(void)
{
    return sStorage_pokemon_storage_system->movingItemId;
}

static u8 GetNewItemIconIdx_pokemon_storage_system(void)
{
    u8 i;

    for (i = 0; i < MAX_ITEM_ICONS_pokemon_storage_system; i++)
    {
        if (!sStorage_pokemon_storage_system->itemIcons[i].active)
        {
            sStorage_pokemon_storage_system->itemIcons[i].active = TRUE;
            return i;
        }
    }
    return MAX_ITEM_ICONS_pokemon_storage_system;
}

static bool32 IsItemIconAtPosition_pokemon_storage_system(u8 cursorArea, u8 cursorPos)
{
    s32 i;

    for (i = 0; i < MAX_ITEM_ICONS_pokemon_storage_system; i++)
    {
        if (sStorage_pokemon_storage_system->itemIcons[i].active
         && sStorage_pokemon_storage_system->itemIcons[i].area == cursorArea
         && sStorage_pokemon_storage_system->itemIcons[i].pos == cursorPos)
            return TRUE;
    }
    return FALSE;
}

static u8 GetItemIconIdxByPosition_pokemon_storage_system(u8 cursorArea, u8 cursorPos)
{
    u8 i;

    for (i = 0; i < MAX_ITEM_ICONS_pokemon_storage_system; i++)
    {
        if (sStorage_pokemon_storage_system->itemIcons[i].active
         && sStorage_pokemon_storage_system->itemIcons[i].area == cursorArea
         && sStorage_pokemon_storage_system->itemIcons[i].pos == cursorPos)
            return i;
    }
    return MAX_ITEM_ICONS_pokemon_storage_system;
}

static u8 GetItemIconIdxBySprite_pokemon_storage_system(struct Sprite *sprite)
{
    u8 i;

    for (i = 0; i < MAX_ITEM_ICONS_pokemon_storage_system; i++)
    {
        if (sStorage_pokemon_storage_system->itemIcons[i].active
         && sStorage_pokemon_storage_system->itemIcons[i].sprite == sprite)
            return i;
    }
    return MAX_ITEM_ICONS_pokemon_storage_system;
}

static void SetItemIconPosition_pokemon_storage_system(u8 id, u8 cursorArea, u8 cursorPos)
{
    u8 x, y;

    if (id >= MAX_ITEM_ICONS_pokemon_storage_system)
        return;

    switch (cursorArea)
    {
    case CURSOR_AREA_IN_BOX_pokemon_storage_system:
        x = cursorPos % IN_BOX_COLUMNS;
        y = cursorPos / IN_BOX_COLUMNS;
        sStorage_pokemon_storage_system->itemIcons[id].sprite->x = (24 * x) + 112;
        sStorage_pokemon_storage_system->itemIcons[id].sprite->y = (24 * y) + 56;
        sStorage_pokemon_storage_system->itemIcons[id].sprite->oam.priority = 2;
        break;
    case CURSOR_AREA_IN_PARTY_pokemon_storage_system:
        if (cursorPos == 0)
        {
            sStorage_pokemon_storage_system->itemIcons[id].sprite->x = 116;
            sStorage_pokemon_storage_system->itemIcons[id].sprite->y = 76;
        }
        else
        {
            sStorage_pokemon_storage_system->itemIcons[id].sprite->x = 164;
            sStorage_pokemon_storage_system->itemIcons[id].sprite->y = 24 * (cursorPos - 1) + 28;
        }
        sStorage_pokemon_storage_system->itemIcons[id].sprite->oam.priority = 1;
        break;
    }

    sStorage_pokemon_storage_system->itemIcons[id].area = cursorArea;
    sStorage_pokemon_storage_system->itemIcons[id].pos = cursorPos;
}

static void LoadItemIconGfx_pokemon_storage_system(u8 id, const u32 *itemTiles, const u32 *itemPal)
{
    s32 i;

    if (id >= MAX_ITEM_ICONS_pokemon_storage_system)
        return;

    CpuFastFill(0, sStorage_pokemon_storage_system->itemIconBuffer, 0x200);
    LZ77UnCompWram(itemTiles, sStorage_pokemon_storage_system->tileBuffer);
    for (i = 0; i < 3; i++)
        CpuFastCopy(&sStorage_pokemon_storage_system->tileBuffer[i * 0x60], &sStorage_pokemon_storage_system->itemIconBuffer[i * 0x80], 0x60);

    CpuFastCopy(sStorage_pokemon_storage_system->itemIconBuffer, sStorage_pokemon_storage_system->itemIcons[id].tiles, 0x200);
    LZ77UnCompWram(itemPal, sStorage_pokemon_storage_system->itemIconBuffer);
    LoadPalette(sStorage_pokemon_storage_system->itemIconBuffer, sStorage_pokemon_storage_system->itemIcons[id].palIndex, PLTT_SIZE_4BPP);
}

static void SetItemIconAffineAnim_pokemon_storage_system(u8 id, u8 animNum)
{
    if (id >= MAX_ITEM_ICONS_pokemon_storage_system)
        return;

    StartSpriteAffineAnim(sStorage_pokemon_storage_system->itemIcons[id].sprite, animNum);
}

#define sItemIconId_pokemon_storage_system data[0]
#define sState_pokemon_storage_system      data[0]
#define sCursorArea_pokemon_storage_system data[6]
#define sCursorPos_pokemon_storage_system  data[7]

static void SetItemIconCallback_pokemon_storage_system(u8 id, u8 callbackId, u8 cursorArea, u8 cursorPos)
{
    if (id >= MAX_ITEM_ICONS_pokemon_storage_system)
        return;

    switch (callbackId)
    {
    case ITEM_CB_WAIT_ANIM_pokemon_storage_system:
        sStorage_pokemon_storage_system->itemIcons[id].sprite->sItemIconId_pokemon_storage_system = id;
        sStorage_pokemon_storage_system->itemIcons[id].sprite->callback = SpriteCB_ItemIcon_WaitAnim_pokemon_storage_system;
        break;
    case ITEM_CB_TO_HAND_pokemon_storage_system:
        sStorage_pokemon_storage_system->itemIcons[id].sprite->sState_pokemon_storage_system = 0;
        sStorage_pokemon_storage_system->itemIcons[id].sprite->callback = SpriteCB_ItemIcon_ToHand_pokemon_storage_system;
        break;
    case ITEM_CB_TO_MON_pokemon_storage_system:
        sStorage_pokemon_storage_system->itemIcons[id].sprite->sState_pokemon_storage_system = 0;
        sStorage_pokemon_storage_system->itemIcons[id].sprite->sCursorArea_pokemon_storage_system = cursorArea;
        sStorage_pokemon_storage_system->itemIcons[id].sprite->sCursorPos_pokemon_storage_system = cursorPos;
        sStorage_pokemon_storage_system->itemIcons[id].sprite->callback = SpriteCB_ItemIcon_ToMon_pokemon_storage_system;
        break;
    case ITEM_CB_SWAP_TO_HAND_pokemon_storage_system:
        sStorage_pokemon_storage_system->itemIcons[id].sprite->sState_pokemon_storage_system = 0;
        sStorage_pokemon_storage_system->itemIcons[id].sprite->callback = SpriteCB_ItemIcon_SwapToHand_pokemon_storage_system;
        sStorage_pokemon_storage_system->itemIcons[id].sprite->sCursorArea_pokemon_storage_system = cursorArea;
        sStorage_pokemon_storage_system->itemIcons[id].sprite->sCursorPos_pokemon_storage_system = cursorPos;
        break;
    case ITEM_CB_SWAP_TO_MON_pokemon_storage_system:
        sStorage_pokemon_storage_system->itemIcons[id].sprite->sState_pokemon_storage_system = 0;
        sStorage_pokemon_storage_system->itemIcons[id].sprite->sCursorArea_pokemon_storage_system = cursorArea;
        sStorage_pokemon_storage_system->itemIcons[id].sprite->sCursorPos_pokemon_storage_system = cursorPos;
        sStorage_pokemon_storage_system->itemIcons[id].sprite->callback = SpriteCB_ItemIcon_SwapToMon_pokemon_storage_system;
        break;
    case ITEM_CB_HIDE_PARTY_pokemon_storage_system:
        // If cursor is on a Pokémon with a held item and
        // the player closes the party menu, have the held
        // item follow the Pokémon as the menu slides out
        sStorage_pokemon_storage_system->itemIcons[id].sprite->callback = SpriteCB_ItemIcon_HideParty_pokemon_storage_system;
        break;
    }
}

static void SetItemIconActive_pokemon_storage_system(u8 id, bool8 active)
{
    if (id >= MAX_ITEM_ICONS_pokemon_storage_system)
        return;

    sStorage_pokemon_storage_system->itemIcons[id].active = active;
    sStorage_pokemon_storage_system->itemIcons[id].sprite->invisible = (active == FALSE);
}

static void PrintItemDescription_pokemon_storage_system(void)
{
    const u8 *description;

    if (IsMovingItem_pokemon_storage_system())
        description = ItemId_GetDescription(sStorage_pokemon_storage_system->movingItemId);
    else
        description = ItemId_GetDescription(sStorage_pokemon_storage_system->displayMonItemId);

    FillWindowPixelBuffer(WIN_ITEM_DESC_pokemon_storage_system, PIXEL_FILL(1));
    AddTextPrinterParameterized5(WIN_ITEM_DESC_pokemon_storage_system, FONT_NORMAL, description, 4, 0, 0, NULL, 0, 1);
}

static void InitItemInfoWindow_pokemon_storage_system(void)
{
    sStorage_pokemon_storage_system->itemInfoWindowOffset = 21;
    LoadBgTiles(0, sItemInfoFrame_Gfx_pokemon_storage_system, 0x80, 0x13A);
    DrawItemInfoWindow_pokemon_storage_system(0);
}

static bool8 UpdateItemInfoWindowSlideIn_pokemon_storage_system(void)
{
    s32 i, pos;

    if (sStorage_pokemon_storage_system->itemInfoWindowOffset == 0)
        return FALSE;

    sStorage_pokemon_storage_system->itemInfoWindowOffset--;
    pos = 21 - sStorage_pokemon_storage_system->itemInfoWindowOffset;
    for (i = 0; i < pos; i++)
        WriteSequenceToBgTilemapBuffer(0, GetBgAttribute(0, BG_ATTR_BASETILE) + 0x14 + sStorage_pokemon_storage_system->itemInfoWindowOffset + i, i, 13, 1, 7, 15, 21);

    DrawItemInfoWindow_pokemon_storage_system(pos);
    return (sStorage_pokemon_storage_system->itemInfoWindowOffset != 0);
}

static bool8 UpdateItemInfoWindowSlideOut_pokemon_storage_system(void)
{
    s32 i, pos;

    if (sStorage_pokemon_storage_system->itemInfoWindowOffset == 22)
        return FALSE;

    if (sStorage_pokemon_storage_system->itemInfoWindowOffset == 0)
        FillBgTilemapBufferRect(0, 0, 21, 12, 1, 9, 17);

    sStorage_pokemon_storage_system->itemInfoWindowOffset++;
    pos = 21 - sStorage_pokemon_storage_system->itemInfoWindowOffset;
    for (i = 0; i < pos; i++)
    {
        WriteSequenceToBgTilemapBuffer(0, GetBgAttribute(0, BG_ATTR_BASETILE) + 0x14 + sStorage_pokemon_storage_system->itemInfoWindowOffset + i, i, 13, 1, 7, 15, 21);
    }

    if (pos >= 0)
        DrawItemInfoWindow_pokemon_storage_system(pos);

    FillBgTilemapBufferRect(0, 0, pos + 1, 12, 1, 9, 17);
    ScheduleBgCopyTilemapToVram(0);
    return TRUE;
}

static void DrawItemInfoWindow_pokemon_storage_system(u32 x)
{
    if (x != 0)
    {
        FillBgTilemapBufferRect(0, 0x13A, 0, 0xC, x, 1, 15);
        FillBgTilemapBufferRect(0, 0x93A, 0, 0x14, x, 1, 15);
    }
    FillBgTilemapBufferRect(0, 0x13B, x, 0xD, 1, 7, 15);
    FillBgTilemapBufferRect(0, 0x13C, x, 0xC, 1, 1, 15);
    FillBgTilemapBufferRect(0, 0x13D, x, 0x14, 1, 1, 15);
    ScheduleBgCopyTilemapToVram(0);
}

static void SpriteCB_ItemIcon_WaitAnim_pokemon_storage_system(struct Sprite *sprite)
{
    if (sprite->affineAnimEnded)
    {
        SetItemIconActive_pokemon_storage_system(sprite->sItemIconId_pokemon_storage_system, FALSE);
        sprite->callback = SpriteCallbackDummy;
    }
}

static void SpriteCB_ItemIcon_ToHand_pokemon_storage_system(struct Sprite *sprite)
{
    switch (sprite->sState_pokemon_storage_system)
    {
    case 0:
        sprite->data[1] = sprite->x << 4;
        sprite->data[2] = sprite->y << 4;
        sprite->data[3] = 10;
        sprite->data[4] = 21;
        sprite->data[5] = 0;
        sprite->sState_pokemon_storage_system++;
    case 1:
        sprite->data[1] -= sprite->data[3];
        sprite->data[2] -= sprite->data[4];
        sprite->x = sprite->data[1] >> 4;
        sprite->y = sprite->data[2] >> 4;
        if (++sprite->data[5] > 11)
            sprite->callback = SpriteCB_ItemIcon_SetPosToCursor_pokemon_storage_system;
        break;
    }
}

static void SpriteCB_ItemIcon_SetPosToCursor_pokemon_storage_system(struct Sprite *sprite)
{
    sprite->x = sStorage_pokemon_storage_system->cursorSprite->x + 4;
    sprite->y = sStorage_pokemon_storage_system->cursorSprite->y + sStorage_pokemon_storage_system->cursorSprite->y2 + 8;
    sprite->oam.priority = sStorage_pokemon_storage_system->cursorSprite->oam.priority;
}

static void SpriteCB_ItemIcon_ToMon_pokemon_storage_system(struct Sprite *sprite)
{
    switch (sprite->sState_pokemon_storage_system)
    {
    case 0:
        sprite->data[1] = sprite->x << 4;
        sprite->data[2] = sprite->y << 4;
        sprite->data[3] = 10;
        sprite->data[4] = 21;
        sprite->data[5] = 0;
        sprite->sState_pokemon_storage_system++;
    case 1:
        sprite->data[1] += sprite->data[3];
        sprite->data[2] += sprite->data[4];
        sprite->x = sprite->data[1] >> 4;
        sprite->y = sprite->data[2] >> 4;
        if (++sprite->data[5] > 11)
        {
            SetItemIconPosition_pokemon_storage_system(GetItemIconIdxBySprite_pokemon_storage_system(sprite), sprite->sCursorArea_pokemon_storage_system, sprite->sCursorPos_pokemon_storage_system);
            sprite->callback = SpriteCallbackDummy;
        }
        break;
    }
}

static void SpriteCB_ItemIcon_SwapToHand_pokemon_storage_system(struct Sprite *sprite)
{
    switch (sprite->sState_pokemon_storage_system)
    {
    case 0:
        sprite->data[1] = sprite->x << 4;
        sprite->data[2] = sprite->y << 4;
        sprite->data[3] = 10;
        sprite->data[4] = 21;
        sprite->data[5] = 0;
        sprite->sState_pokemon_storage_system++;
    case 1:
        sprite->data[1] -= sprite->data[3];
        sprite->data[2] -= sprite->data[4];
        sprite->x = sprite->data[1] >> 4;
        sprite->y = sprite->data[2] >> 4;
        sprite->x2 = gSineTable[sprite->data[5] * 8] >> 4;
        if (++sprite->data[5] > 11)
        {
            SetItemIconPosition_pokemon_storage_system(GetItemIconIdxBySprite_pokemon_storage_system(sprite), sprite->sCursorArea_pokemon_storage_system, sprite->sCursorPos_pokemon_storage_system);
            sprite->x2 = 0;
            sprite->callback = SpriteCB_ItemIcon_SetPosToCursor_pokemon_storage_system;
        }
        break;
    }
}

static void SpriteCB_ItemIcon_SwapToMon_pokemon_storage_system(struct Sprite *sprite)
{
    switch (sprite->sState_pokemon_storage_system)
    {
    case 0:
        sprite->data[1] = sprite->x << 4;
        sprite->data[2] = sprite->y << 4;
        sprite->data[3] = 10;
        sprite->data[4] = 21;
        sprite->data[5] = 0;
        sprite->sState_pokemon_storage_system++;
    case 1:
        sprite->data[1] += sprite->data[3];
        sprite->data[2] += sprite->data[4];
        sprite->x = sprite->data[1] >> 4;
        sprite->y = sprite->data[2] >> 4;
        sprite->x2 = -(gSineTable[sprite->data[5] * 8] >> 4);
        if (++sprite->data[5] > 11)
        {
            SetItemIconPosition_pokemon_storage_system(GetItemIconIdxBySprite_pokemon_storage_system(sprite), sprite->sCursorArea_pokemon_storage_system, sprite->sCursorPos_pokemon_storage_system);
            sprite->callback = SpriteCallbackDummy;
            sprite->x2 = 0;
        }
        break;
    }
}

static void SpriteCB_ItemIcon_HideParty_pokemon_storage_system(struct Sprite *sprite)
{
    sprite->y -= 8;
    if (sprite->y + sprite->y2 < -16)
    {
        sprite->callback = SpriteCallbackDummy;
        SetItemIconActive_pokemon_storage_system(GetItemIconIdxBySprite_pokemon_storage_system(sprite), FALSE);
    }
}

#undef sState_pokemon_storage_system
#undef sItemIconId_pokemon_storage_system
#undef sCursorArea_pokemon_storage_system
#undef sCursorPos_pokemon_storage_system


