static void PrintNotEggInfo_pokemon_summary_screen(void)
{
    struct Pokemon *mon = &sMonSummaryScreen->currentMon;
    struct PokeSummary *summary = &sMonSummaryScreen->summary;
    u16 dexNum = SpeciesToPokedexNum(summary->species);

    if (dexNum != 0xFFFF)
    {
        u8 digitCount = (NATIONAL_DEX_COUNT > 999 && IsNationalPokedexEnabled()) ? 4 : 3;
        StringCopy(gStringVar1, &gText_NumberClear01[0]);
        ConvertIntToDecimalStringN(gStringVar2, dexNum, STR_CONV_MODE_LEADING_ZEROS, digitCount);
        StringAppend(gStringVar1, gStringVar2);
        if (!IsMonShiny(mon))
        {
            PrintTextOnWindow_pokemon_summary_screen(PSS_LABEL_WINDOW_PORTRAIT_DEX_NUMBER_pokemon_summary_screen, gStringVar1, 0, 1, 0, 1);
            SetMonPicBackgroundPalette_pokemon_summary_screen(FALSE);
        }
        else
        {
            PrintTextOnWindow_pokemon_summary_screen(PSS_LABEL_WINDOW_PORTRAIT_DEX_NUMBER_pokemon_summary_screen, gStringVar1, 0, 1, 0, 7);
            SetMonPicBackgroundPalette_pokemon_summary_screen(TRUE);
        }
        PutWindowTilemap(PSS_LABEL_WINDOW_PORTRAIT_DEX_NUMBER_pokemon_summary_screen);
    }
    else
    {
        ClearWindowTilemap(PSS_LABEL_WINDOW_PORTRAIT_DEX_NUMBER_pokemon_summary_screen);
        if (!IsMonShiny(mon))
            SetMonPicBackgroundPalette_pokemon_summary_screen(FALSE);
        else
            SetMonPicBackgroundPalette_pokemon_summary_screen(TRUE);
    }
    StringCopy(gStringVar1, gText_LevelSymbol);
    ConvertIntToDecimalStringN(gStringVar2, summary->level, STR_CONV_MODE_LEFT_ALIGN, 3);
    StringAppend(gStringVar1, gStringVar2);
    PrintTextOnWindow_pokemon_summary_screen(PSS_LABEL_WINDOW_PORTRAIT_SPECIES_pokemon_summary_screen, gStringVar1, 24, 17, 0, 1);
    GetMonNickname(mon, gStringVar1);
    PrintTextOnWindowToFitPx_pokemon_summary_screen(PSS_LABEL_WINDOW_PORTRAIT_NICKNAME_pokemon_summary_screen, gStringVar1, 0, 1, 0, 1, WindowWidthPx(PSS_LABEL_WINDOW_PORTRAIT_NICKNAME_pokemon_summary_screen) - 9);
    PrintTextOnWindow_pokemon_summary_screen(PSS_LABEL_WINDOW_PORTRAIT_SPECIES_pokemon_summary_screen, gText_Slash, 0, 1, 0, 1);
    PrintTextOnWindowToFitPx_pokemon_summary_screen(PSS_LABEL_WINDOW_PORTRAIT_SPECIES_pokemon_summary_screen, GetSpeciesName(summary->species2), 6, 1, 0, 1, WindowWidthPx(PSS_LABEL_WINDOW_PORTRAIT_SPECIES_pokemon_summary_screen) - 9);
    PrintGenderSymbol_pokemon_summary_screen(mon, summary->species2);
    PutWindowTilemap(PSS_LABEL_WINDOW_PORTRAIT_NICKNAME_pokemon_summary_screen);
    PutWindowTilemap(PSS_LABEL_WINDOW_PORTRAIT_SPECIES_pokemon_summary_screen);
}

static void PrintEggInfo_pokemon_summary_screen(void)
{
    GetMonNickname(&sMonSummaryScreen->currentMon, gStringVar1);
    PrintTextOnWindow_pokemon_summary_screen(PSS_LABEL_WINDOW_PORTRAIT_NICKNAME_pokemon_summary_screen, gStringVar1, 0, 1, 0, 1);
    PutWindowTilemap(PSS_LABEL_WINDOW_PORTRAIT_NICKNAME_pokemon_summary_screen);
    ClearWindowTilemap(PSS_LABEL_WINDOW_PORTRAIT_DEX_NUMBER_pokemon_summary_screen);
    ClearWindowTilemap(PSS_LABEL_WINDOW_PORTRAIT_SPECIES_pokemon_summary_screen);
}

static void PrintGenderSymbol_pokemon_summary_screen(struct Pokemon *mon, u16 species)
{
    if (species != SPECIES_NIDORAN_M && species != SPECIES_NIDORAN_F)
    {
        switch (GetMonGender(mon))
        {
        case MON_MALE:
            PrintTextOnWindow_pokemon_summary_screen(PSS_LABEL_WINDOW_PORTRAIT_SPECIES_pokemon_summary_screen, gText_MaleSymbol, 57, 17, 0, 3);
            break;
        case MON_FEMALE:
            PrintTextOnWindow_pokemon_summary_screen(PSS_LABEL_WINDOW_PORTRAIT_SPECIES_pokemon_summary_screen, gText_FemaleSymbol, 57, 17, 0, 4);
            break;
        }
    }
}

