    statsXPos = 2 + GetStringCenterAlignXOffset(FONT_NORMAL, gText_SpAtk4, 36);
    PrintTextOnWindow_pokemon_summary_screen(PSS_LABEL_WINDOW_POKEMON_SKILLS_STATS_RIGHT_pokemon_summary_screen, gText_SpAtk4, statsXPos, 1, 0, 1);
    statsXPos = 2 + GetStringCenterAlignXOffset(FONT_NORMAL, gText_SpDef4, 36);
    PrintTextOnWindow_pokemon_summary_screen(PSS_LABEL_WINDOW_POKEMON_SKILLS_STATS_RIGHT_pokemon_summary_screen, gText_SpDef4, statsXPos, 17, 0, 1);
    statsXPos = 2 + GetStringCenterAlignXOffset(FONT_NORMAL, gText_Speed2, 36);
    PrintTextOnWindow_pokemon_summary_screen(PSS_LABEL_WINDOW_POKEMON_SKILLS_STATS_RIGHT_pokemon_summary_screen, gText_Speed2, statsXPos, 33, 0, 1);
    PrintTextOnWindow_pokemon_summary_screen(PSS_LABEL_WINDOW_POKEMON_SKILLS_EXP_pokemon_summary_screen, gText_ExpPoints, 6, 1, 0, 1);
    PrintTextOnWindow_pokemon_summary_screen(PSS_LABEL_WINDOW_POKEMON_SKILLS_EXP_pokemon_summary_screen, gText_NextLv, 6, 17, 0, 1);
    PrintTextOnWindow_pokemon_summary_screen(PSS_LABEL_WINDOW_POKEMON_SKILLS_STATUS_pokemon_summary_screen, gText_Status, 2, 1, 0, 1);
    PrintTextOnWindow_pokemon_summary_screen(PSS_LABEL_WINDOW_MOVES_POWER_ACC_pokemon_summary_screen, gText_Power, 0, 1, 0, 1);
