static void PutPageWindowTilemaps_pokemon_summary_screen(u8 page)
{
    u8 i;

    ClearWindowTilemap(PSS_LABEL_WINDOW_POKEMON_INFO_TITLE_pokemon_summary_screen);
    ClearWindowTilemap(PSS_LABEL_WINDOW_POKEMON_SKILLS_TITLE_pokemon_summary_screen);
    ClearWindowTilemap(PSS_LABEL_WINDOW_BATTLE_MOVES_TITLE_pokemon_summary_screen);
    ClearWindowTilemap(PSS_LABEL_WINDOW_CONTEST_MOVES_TITLE_pokemon_summary_screen);

    switch (page)
    {
    case PSS_PAGE_INFO:
        PutWindowTilemap(PSS_LABEL_WINDOW_POKEMON_INFO_TITLE_pokemon_summary_screen);
        PutWindowTilemap(PSS_LABEL_WINDOW_PROMPT_CANCEL_pokemon_summary_screen);
        if (InBattleFactory() == TRUE || InSlateportBattleTent() == TRUE)
            PutWindowTilemap(PSS_LABEL_WINDOW_POKEMON_INFO_RENTAL_pokemon_summary_screen);
        PutWindowTilemap(PSS_LABEL_WINDOW_POKEMON_INFO_TYPE_pokemon_summary_screen);
        break;
    case PSS_PAGE_SKILLS:
        PutWindowTilemap(PSS_LABEL_WINDOW_POKEMON_SKILLS_TITLE_pokemon_summary_screen);
        PutWindowTilemap(PSS_LABEL_WINDOW_POKEMON_SKILLS_STATS_LEFT_pokemon_summary_screen);
        PutWindowTilemap(PSS_LABEL_WINDOW_POKEMON_SKILLS_STATS_RIGHT_pokemon_summary_screen);
        PutWindowTilemap(PSS_LABEL_WINDOW_POKEMON_SKILLS_EXP_pokemon_summary_screen);
        break;
    case PSS_PAGE_BATTLE_MOVES:
        PutWindowTilemap(PSS_LABEL_WINDOW_BATTLE_MOVES_TITLE_pokemon_summary_screen);
        if (sMonSummaryScreen->mode == SUMMARY_MODE_SELECT_MOVE)
        {
            if (sMonSummaryScreen->newMove != MOVE_NONE || sMonSummaryScreen->firstMoveIndex != MAX_MON_MOVES)
                PutWindowTilemap(PSS_LABEL_WINDOW_MOVES_POWER_ACC_pokemon_summary_screen);
        }
        else
        {
            PutWindowTilemap(PSS_LABEL_WINDOW_PROMPT_INFO_pokemon_summary_screen);
            if (ShouldShowMoveRelearner_pokemon_summary_screen())
                PutWindowTilemap(PSS_LABEL_WINDOW_PROMPT_RELEARN_pokemon_summary_screen);
        }
        break;
    case PSS_PAGE_CONTEST_MOVES:
        PutWindowTilemap(PSS_LABEL_WINDOW_CONTEST_MOVES_TITLE_pokemon_summary_screen);
        if (sMonSummaryScreen->mode == SUMMARY_MODE_SELECT_MOVE)
        {
            if (sMonSummaryScreen->newMove != MOVE_NONE || sMonSummaryScreen->firstMoveIndex != MAX_MON_MOVES)
                PutWindowTilemap(PSS_LABEL_WINDOW_MOVES_APPEAL_JAM_pokemon_summary_screen);
        }
        else
        {
            PutWindowTilemap(PSS_LABEL_WINDOW_PROMPT_INFO_pokemon_summary_screen);
            if (ShouldShowMoveRelearner_pokemon_summary_screen())
                PutWindowTilemap(PSS_LABEL_WINDOW_PROMPT_RELEARN_pokemon_summary_screen);
        }
        break;
    }

    for (i = 0; i < ARRAY_COUNT(sMonSummaryScreen->windowIds); i++)
        PutWindowTilemap(sMonSummaryScreen->windowIds[i]);

    ScheduleBgCopyTilemapToVram(0);
}

static void ClearPageWindowTilemaps_pokemon_summary_screen(u8 page)
{
    u8 i;

    switch (page)
    {
    case PSS_PAGE_INFO:
        ClearWindowTilemap(PSS_LABEL_WINDOW_PROMPT_CANCEL_pokemon_summary_screen);
        if (InBattleFactory() == TRUE || InSlateportBattleTent() == TRUE)
            ClearWindowTilemap(PSS_LABEL_WINDOW_POKEMON_INFO_RENTAL_pokemon_summary_screen);
        ClearWindowTilemap(PSS_LABEL_WINDOW_POKEMON_INFO_TYPE_pokemon_summary_screen);
        break;
    case PSS_PAGE_SKILLS:
        ClearWindowTilemap(PSS_LABEL_WINDOW_POKEMON_SKILLS_STATS_LEFT_pokemon_summary_screen);
        ClearWindowTilemap(PSS_LABEL_WINDOW_POKEMON_SKILLS_STATS_RIGHT_pokemon_summary_screen);
        ClearWindowTilemap(PSS_LABEL_WINDOW_POKEMON_SKILLS_EXP_pokemon_summary_screen);
        break;
    case PSS_PAGE_BATTLE_MOVES:
        if (sMonSummaryScreen->mode == SUMMARY_MODE_SELECT_MOVE)
        {
            if (sMonSummaryScreen->newMove != MOVE_NONE || sMonSummaryScreen->firstMoveIndex != MAX_MON_MOVES)
            {
                ClearWindowTilemap(PSS_LABEL_WINDOW_MOVES_POWER_ACC_pokemon_summary_screen);
                gSprites[sMonSummaryScreen->categoryIconSpriteId].invisible = TRUE;
            }
        }
        else
        {
            ClearWindowTilemap(PSS_LABEL_WINDOW_PROMPT_INFO_pokemon_summary_screen);
            if (ShouldShowMoveRelearner_pokemon_summary_screen())
                ClearWindowTilemap(PSS_LABEL_WINDOW_PROMPT_RELEARN_pokemon_summary_screen);
        }
        break;
    case PSS_PAGE_CONTEST_MOVES:
        if (sMonSummaryScreen->mode == SUMMARY_MODE_SELECT_MOVE)
        {
            if (sMonSummaryScreen->newMove != MOVE_NONE || sMonSummaryScreen->firstMoveIndex != MAX_MON_MOVES)
                ClearWindowTilemap(PSS_LABEL_WINDOW_MOVES_APPEAL_JAM_pokemon_summary_screen);
        }
        else
        {
            ClearWindowTilemap(PSS_LABEL_WINDOW_PROMPT_INFO_pokemon_summary_screen);
            if (ShouldShowMoveRelearner_pokemon_summary_screen())
                ClearWindowTilemap(PSS_LABEL_WINDOW_PROMPT_RELEARN_pokemon_summary_screen);
        }
        break;
    }

    for (i = 0; i < ARRAY_COUNT(sMonSummaryScreen->windowIds); i++)
        RemoveWindowByIndex_pokemon_summary_screen(i);

    ScheduleBgCopyTilemapToVram(0);
}

static u8 AddWindowFromTemplateList_pokemon_summary_screen(const struct WindowTemplate *template, u8 templateId)
{
    u8 *windowIdPtr = &sMonSummaryScreen->windowIds[templateId];
    if (*windowIdPtr == WINDOW_NONE)
    {
        *windowIdPtr = AddWindow(&template[templateId]);
        FillWindowPixelBuffer(*windowIdPtr, PIXEL_FILL(0));
    }
    return *windowIdPtr;
}

static void RemoveWindowByIndex_pokemon_summary_screen(u8 windowIndex)
{
    u8 *windowIdPtr = &sMonSummaryScreen->windowIds[windowIndex];
    if (*windowIdPtr != WINDOW_NONE)
    {
        ClearWindowTilemap(*windowIdPtr);
        RemoveWindow(*windowIdPtr);
        *windowIdPtr = WINDOW_NONE;
    }
}

static void PrintPageSpecificText_pokemon_summary_screen(u8 pageIndex)
{
    u16 i;
    for (i = 0; i < ARRAY_COUNT(sMonSummaryScreen->windowIds); i++)
    {
        if (sMonSummaryScreen->windowIds[i] != WINDOW_NONE)
            FillWindowPixelBuffer(sMonSummaryScreen->windowIds[i], PIXEL_FILL(0));
    }
    sTextPrinterFunctions[pageIndex]();
}

static void CreateTextPrinterTask_pokemon_summary_screen(u8 pageIndex)
{
    CreateTask(sTextPrinterTasks[pageIndex], 16);
}

static void PrintInfoPageText_pokemon_summary_screen(void)
{
    if (sMonSummaryScreen->summary.isEgg)
    {
        PrintEggOTName_pokemon_summary_screen();
        PrintEggOTID_pokemon_summary_screen();
        PrintEggState_pokemon_summary_screen();
        PrintEggMemo_pokemon_summary_screen();
    }
    else
    {
        PrintMonOTName_pokemon_summary_screen();
        PrintMonOTID_pokemon_summary_screen();
        PrintMonAbilityName_pokemon_summary_screen();
        PrintMonAbilityDescription_pokemon_summary_screen();
        BufferMonTrainerMemo_pokemon_summary_screen();
        PrintMonTrainerMemo_pokemon_summary_screen();
    }
}

static void Task_PrintInfoPage_pokemon_summary_screen(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    switch (data[0])
    {
    case 1:
        PrintMonOTName_pokemon_summary_screen();
        break;
    case 2:
        PrintMonOTID_pokemon_summary_screen();
        break;
    case 3:
        PrintMonAbilityName_pokemon_summary_screen();
        break;
    case 4:
        PrintMonAbilityDescription_pokemon_summary_screen();
        break;
    case 5:
        BufferMonTrainerMemo_pokemon_summary_screen();
        break;
    case 6:
        PrintMonTrainerMemo_pokemon_summary_screen();
        break;
    case 7:
        DestroyTask(taskId);
        return;
    }
    data[0]++;
}

