static void PrintEggState_pokemon_summary_screen(void)
{
    const u8 *text;
    struct PokeSummary *sum = &sMonSummaryScreen->summary;

    if (sMonSummaryScreen->summary.sanity == TRUE)
        text = gText_EggWillTakeALongTime;
    else if (sum->friendship <= 5)
        text = gText_EggAboutToHatch;
    else if (sum->friendship <= 10)
        text = gText_EggWillHatchSoon;
    else if (sum->friendship <= 40)
        text = gText_EggWillTakeSomeTime;
    else
        text = gText_EggWillTakeALongTime;

    PrintTextOnWindow_pokemon_summary_screen(AddWindowFromTemplateList_pokemon_summary_screen(sPageInfoTemplate_pokemon_summary_screen, PSS_DATA_WINDOW_INFO_ABILITY_pokemon_summary_screen), text, 0, 1, 0, 0);
}

static void PrintEggMemo_pokemon_summary_screen(void)
{
    const u8 *text;
    struct PokeSummary *sum = &sMonSummaryScreen->summary;

    if (sMonSummaryScreen->summary.sanity != 1)
    {
        if (sum->metLocation == METLOC_FATEFUL_ENCOUNTER)
            text = gText_PeculiarEggNicePlace;
        else if (DidMonComeFromGBAGames_pokemon_summary_screen() == FALSE || DoesMonOTMatchOwner_pokemon_summary_screen() == FALSE)
            text = gText_PeculiarEggTrade;
        else if (sum->metLocation == METLOC_SPECIAL_EGG)
            text = (DidMonComeFromRSE() == TRUE) ? gText_EggFromHotSprings : gText_EggFromTraveler;
        else
            text = gText_OddEggFoundByCouple;
    }
    else
    {
        text = gText_OddEggFoundByCouple;
    }

    PrintTextOnWindow_pokemon_summary_screen(AddWindowFromTemplateList_pokemon_summary_screen(sPageInfoTemplate_pokemon_summary_screen, PSS_DATA_WINDOW_INFO_MEMO_pokemon_summary_screen), text, 0, 1, 0, 0);
}

