static void BufferStat_pokemon_summary_screen(u8 *dst, u8 statIndex, u32 stat, u32 strId, u32 n)
{
static const u8  sTextNatureDown_pokemon_summary_screen[] = _("{COLOR}{08}");
static const u8  sTextNatureUp_pokemon_summary_screen[] = _("{COLOR}{05}");
static const u8  sTextNatureNeutral_pokemon_summary_screen[] = _("{COLOR}{01}");
    u8 *txtPtr;

    if (statIndex == 0 || !SUMMARY_SCREEN_NATURE_COLORS || gNaturesInfo[sMonSummaryScreen->summary.mintNature].statUp == gNaturesInfo[sMonSummaryScreen->summary.mintNature].statDown)
        txtPtr = StringCopy(dst, sTextNatureNeutral_pokemon_summary_screen);
    else if (statIndex == gNaturesInfo[sMonSummaryScreen->summary.mintNature].statUp)
        txtPtr = StringCopy(dst, sTextNatureUp_pokemon_summary_screen);
    else if (statIndex == gNaturesInfo[sMonSummaryScreen->summary.mintNature].statDown)
        txtPtr = StringCopy(dst, sTextNatureDown_pokemon_summary_screen);
    else
        txtPtr = StringCopy(dst, sTextNatureNeutral_pokemon_summary_screen);

    ConvertIntToDecimalStringN(txtPtr, stat, STR_CONV_MODE_RIGHT_ALIGN, n);
    DynamicPlaceholderTextUtil_SetPlaceholderPtr(strId, dst);
}

