bool32 PokenavCallback_Init_ConditionSearch(void)
{
    struct Pokenav_SearchResults *menu = AllocSubstruct(POKENAV_SUBSTRUCT_CONDITION_SEARCH_RESULTS, sizeof(struct Pokenav_SearchResults));
    if (menu == NULL)
        return FALSE;

    menu->monList = AllocSubstruct(POKENAV_SUBSTRUCT_MON_LIST, sizeof(struct PokenavMonList));
    if (menu->monList == NULL)
        return FALSE;

    menu->callback = HandleConditionSearchInput_WaitSetup_pokenav_conditions_search_results;
    menu->loopedTaskId = CreateLoopedTask(GetConditionSearchLoopedTask_pokenav_conditions_search_results, 1);
    menu->returnFromGraph = FALSE;
    menu->conditionDataId = sSearchMonDataIds_pokenav_conditions_search_results[GetSelectedConditionSearch()];
    return TRUE;
}

