static bool32 HandleConditionSearchInput_WaitSetup_pokenav_conditions_search_results(struct Pokenav_SearchResults *menu)
{
    if (!IsLoopedTaskActive(menu->loopedTaskId))
        menu->callback = HandleConditionSearchInput_pokenav_conditions_search_results;
    return FALSE;
}

static u32 HandleConditionSearchInput_pokenav_conditions_search_results(struct Pokenav_SearchResults *menu)
{
    if (JOY_REPEAT(DPAD_UP))
    {
        return CONDITION_SEARCH_FUNC_MOVE_UP_pokenav_conditions_search_results;
    }
    else if (JOY_REPEAT(DPAD_DOWN))
    {
        return CONDITION_SEARCH_FUNC_MOVE_DOWN_pokenav_conditions_search_results;
    }
    else if (JOY_NEW(DPAD_LEFT))
    {
        return CONDITION_SEARCH_FUNC_PAGE_UP_pokenav_conditions_search_results;
    }
    else if (JOY_NEW(DPAD_RIGHT))
    {
        return CONDITION_SEARCH_FUNC_PAGE_DOWN_pokenav_conditions_search_results;
    }
    else if (JOY_NEW(B_BUTTON))
    {
        // Exiting back to main search menu
        menu->saveResultsList = FALSE;
        menu->callback = ReturnToConditionSearchList_pokenav_conditions_search_results;
        return CONDITION_SEARCH_FUNC_EXIT_pokenav_conditions_search_results;
    }
    else if (JOY_NEW(A_BUTTON))
    {
        // Entering graph menu
        menu->monList->currIndex = PokenavList_GetSelectedIndex();
        menu->saveResultsList = TRUE;
        menu->callback = OpenConditionGraphFromSearchList_pokenav_conditions_search_results;
        return CONDITION_SEARCH_FUNC_SELECT_MON_pokenav_conditions_search_results;
    }
    else
    {
        return CONDITION_SEARCH_FUNC_NONE_pokenav_conditions_search_results;
    }
}

