static void PrintSearchResultListMenuItems_pokenav_conditions_search_results(struct Pokenav_SearchResultsGfx *gfx)
{
    s32 rank = GetSearchResultsSelectedMonRank_pokenav_conditions_search_results();
    DynamicPlaceholderTextUtil_Reset();
    DynamicPlaceholderTextUtil_SetPlaceholderPtr(0, gStringVar1);
    *gStringVar1 = EOS;
    DynamicPlaceholderTextUtil_ExpandPlaceholders(gStringVar2, gText_NumberIndex_pokenav_conditions_search_results);
    AddTextPrinterParameterized(gfx->winid, FONT_NORMAL, gStringVar2, 4, 1, TEXT_SKIP_DRAW, NULL);
    ConvertIntToDecimalStringN(gStringVar1, rank, STR_CONV_MODE_RIGHT_ALIGN, 3);
    AddTextPrinterParameterized(gfx->winid, FONT_NORMAL, gStringVar1, 34, 1, TEXT_SKIP_DRAW, NULL);
    CopyWindowToVram(gfx->winid, COPYWIN_GFX);
}

static void CreateSearchResultsList_pokenav_conditions_search_results(void)
{
    struct PokenavListTemplate template;

    template.list = (struct PokenavListItem *)GetSearchResultsMonDataList();
    template.count = GetSearchResultsMonListCount_pokenav_conditions_search_results();
    template.itemSize = sizeof(struct PokenavListItem);
    template.startIndex = GetSearchResultsCurrentListIndex_pokenav_conditions_search_results();
    template.item_X = 13;
    template.windowWidth = 17;
    template.listTop = 1;
    template.maxShowed = 8;
    template.fillValue = 2;
    template.fontId = FONT_NORMAL;
    template.bufferItemFunc = (PokenavListBufferItemFunc)BufferSearchMonListItem_pokenav_conditions_search_results;
    template.iconDrawFunc = NULL;
    CreatePokenavList(&sConditionSearchResultBgTemplates_pokenav_conditions_search_results[1], &template, 0);
}

static void BufferSearchMonListItem_pokenav_conditions_search_results(struct PokenavMonListItem * item, u8 *dest)
{
    u8 gender;
    u8 level;
    u8 *s, *end;
    const u8 *genderStr;
    u32 fontId;

    // Mon is in party
    if (item->boxId == TOTAL_BOXES_COUNT)
    {
        struct Pokemon *mon = &gPlayerParty[item->monId];
        gender = GetMonGender(mon);
        level = GetLevelFromMonExp(mon);
        GetMonData(mon, MON_DATA_NICKNAME, gStringVar3);
    }
    // Mon is in PC
    else
    {
        struct BoxPokemon * mon = GetBoxedMonPtr(item->boxId, item->monId);
        gender = GetBoxMonGender(mon);
        level = GetLevelFromBoxMonExp(mon);
        GetBoxMonData(mon, MON_DATA_NICKNAME, gStringVar3);
    }

    switch (gender)
    {
    default:
        genderStr = sText_NoGenderSymbol_pokenav_conditions_search_results;
        break;
    case MON_MALE:
        genderStr = sText_MaleSymbol_pokenav_conditions_search_results;
        break;
    case MON_FEMALE:
        genderStr = sText_FemaleSymbol_pokenav_conditions_search_results;
        break;
    }
    end = StringGet_Nickname(gStringVar3);
    fontId = GetFontIdToFit(gStringVar3, FONT_NORMAL, 0, 60);
    WrapFontIdToFit(gStringVar3, end, FONT_NORMAL, 60);
    dest = GetStringClearToWidth(dest, fontId, gStringVar3, 60);

    s = StringCopy(gStringVar1, genderStr);
    *s++ = CHAR_SLASH;
    *s++ = CHAR_EXTRA_SYMBOL;
    *s++ = CHAR_LV_2;
    ConvertIntToDecimalStringN(s, level, STR_CONV_MODE_LEFT_ALIGN, 3);
    GetStringClearToWidth(dest, FONT_NORMAL, gStringVar1, 40);
}
// Contents of pokenav_list.c
#include "global.h"
#include "pokenav.h"
