static void LoadListArrowGfx_pokenav_list(void)
{
    u32 i;
    const struct CompressedSpriteSheet *ptr;

    for (i = 0, ptr = sListArrowSpriteSheets_pokenav_list; i < ARRAY_COUNT(sListArrowSpriteSheets_pokenav_list); ptr++, i++)
        LoadCompressedSpriteSheet(ptr);

    Pokenav_AllocAndLoadPalettes(sListArrowPalettes_pokenav_list);
}

static void CreateListArrowSprites_pokenav_list(struct PokenavListWindowState *windowState, struct PokenavListSub *list)
{
    u32 spriteId;
    s16 x;

    spriteId = CreateSprite(&sSpriteTemplate_RightArrow_pokenav_list, list->listWindow.x * 8 + 3, (list->listWindow.y + 1) * 8, 7);
    list->rightArrow = &gSprites[spriteId];

    x = list->listWindow.x * 8 + (list->listWindow.width - 1) * 4;
    spriteId = CreateSprite(&sSpriteTemplate_UpDownArrow_pokenav_list, x, list->listWindow.y * 8 + windowState->entriesOnscreen * 16, 7);
    list->downArrow = &gSprites[spriteId];
    list->downArrow->oam.tileNum += 2;
    list->downArrow->callback = SpriteCB_DownArrow_pokenav_list;

    spriteId = CreateSprite(&sSpriteTemplate_UpDownArrow_pokenav_list, x, list->listWindow.y * 8, 7);
    list->upArrow = &gSprites[spriteId];
    list->upArrow->oam.tileNum += 4;
    list->upArrow->callback = SpriteCB_UpArrow_pokenav_list;
}

static void DestroyListArrows_pokenav_list(struct PokenavListSub *list)
{
    DestroySprite(list->rightArrow);
    DestroySprite(list->upArrow);
    DestroySprite(list->downArrow);
    FreeSpriteTilesByTag(GFXTAG_ARROW_pokenav_list);
    FreeSpritePaletteByTag(PALTAG_ARROW_pokenav_list);
}

static void ToggleListArrows_pokenav_list(struct PokenavListSub *list, bool32 invisible)
{
    if (invisible)
    {
        list->rightArrow->callback = SpriteCallbackDummy;
        list->upArrow->callback = SpriteCallbackDummy;
        list->downArrow->callback = SpriteCallbackDummy;
    }
    else
    {
        list->rightArrow->callback = SpriteCB_RightArrow_pokenav_list;
        list->upArrow->callback = SpriteCB_UpArrow_pokenav_list;
        list->downArrow->callback = SpriteCB_DownArrow_pokenav_list;
    }
    list->rightArrow->invisible = invisible;
    list->upArrow->invisible = invisible;
    list->downArrow->invisible = invisible;
}

static void SpriteCB_RightArrow_pokenav_list(struct Sprite *sprite)
{
    struct PokenavList *list = GetSubstructPtr(POKENAV_SUBSTRUCT_LIST);
    sprite->y2 = list->windowState.selectedIndexOffset << 4;
}

#define sTimer_pokenav_list data[0]
#define sOffset_pokenav_list data[1]
#define sInvisible_pokenav_list data[7]

static void SpriteCB_DownArrow_pokenav_list(struct Sprite *sprite)
{
    if (!sprite->sInvisible_pokenav_list && ShouldShowDownArrow_pokenav_list())
        sprite->invisible = FALSE;
    else
        sprite->invisible = TRUE;

    if (++sprite->sTimer_pokenav_list > 3)
    {
        s16 offset;

        sprite->sTimer_pokenav_list = 0;
        offset = (sprite->sOffset_pokenav_list + 1) & 7;
        sprite->sOffset_pokenav_list = offset;
        sprite->y2 = offset;
    }
}

static void SpriteCB_UpArrow_pokenav_list(struct Sprite *sprite)
{
    if (!sprite->sInvisible_pokenav_list && ShouldShowUpArrow_pokenav_list())
        sprite->invisible = FALSE;
    else
        sprite->invisible = TRUE;

    if (++sprite->sTimer_pokenav_list > 3)
    {
        s16 offset;

        sprite->sTimer_pokenav_list = 0;
        offset = (sprite->sOffset_pokenav_list + 1) & 7;
        sprite->sOffset_pokenav_list = offset;
        sprite->y2 = -1 * offset;
    }
}

void PokenavList_ToggleVerticalArrows(bool32 invisible)
{
    struct PokenavList *list = GetSubstructPtr(POKENAV_SUBSTRUCT_LIST);
    list->sub.upArrow->sInvisible_pokenav_list = invisible;
    list->sub.downArrow->sInvisible_pokenav_list = invisible;
}

#undef sTimer_pokenav_list
#undef sOffset_pokenav_list
#undef sInvisible_pokenav_list

static void InitPokenavListWindowState_pokenav_list(struct PokenavListWindowState *dst, struct PokenavListTemplate *template)
{
    dst->listPtr = template->list;
    dst->windowTopIndex = template->startIndex;
    dst->listLength = template->count;
    dst->listItemSize = template->itemSize;
    dst->entriesOnscreen = template->maxShowed;
    if (dst->entriesOnscreen >= dst->listLength)
    {
        dst->windowTopIndex = 0;
        dst->entriesOffscreen = 0;
        dst->selectedIndexOffset = template->startIndex;
    }
    else
    {
        dst->entriesOffscreen = dst->listLength - dst->entriesOnscreen;
        if (dst->windowTopIndex + dst->entriesOnscreen > dst->listLength)
        {
            dst->selectedIndexOffset = dst->windowTopIndex + dst->entriesOnscreen - dst->listLength;
            dst->windowTopIndex = template->startIndex - dst->selectedIndexOffset;
        }
        else
        {
            dst->selectedIndexOffset = 0;
        }
    }
}

static bool32 CopyPokenavListMenuTemplate_pokenav_list(struct PokenavListSub *dest, const struct BgTemplate *bgTemplate, struct PokenavListTemplate *template, s32 tileOffset)
{
    struct WindowTemplate window;

    dest->listWindow.bg = bgTemplate->bg;
    dest->listWindow.tileOffset = tileOffset;
    dest->bufferItemFunc = template->bufferItemFunc;
    dest->iconDrawFunc = template->iconDrawFunc;
    dest->listWindow.fillValue = template->fillValue;
    dest->listWindow.x = template->item_X;
    dest->listWindow.y = template->listTop;
    dest->listWindow.width = template->windowWidth;
    dest->listWindow.fontId = template->fontId;

    window.bg = bgTemplate->bg;
    window.tilemapLeft = template->item_X;
    window.tilemapTop = 0;
    window.width = template->windowWidth;
    window.height = 32;
    window.paletteNum = template->fillValue;
    window.baseBlock = tileOffset + 2;

    dest->listWindow.windowId = AddWindow(&window);
    if (dest->listWindow.windowId == WINDOW_NONE)
        return FALSE;

    dest->listWindow.unkA = 0;
    dest->rightArrow = NULL;
    dest->upArrow = NULL;
    dest->downArrow = NULL;
    return 1;
}
