{
    struct Pokenav_MainMenu *menu = GetSubstructPtr(POKENAV_SUBSTRUCT_MAIN_MENU);

    DrawHelpBar_pokenav_main_menu(menu->helpBarWindowId);
    AddTextPrinterParameterized3(menu->helpBarWindowId, FONT_NORMAL, 0, 1, sHelpBarTextColors_pokenav_main_menu, 0, sHelpBarTexts[textId]);
}

bool32 WaitForHelpBar(void)
{
    return IsDma3ManagerBusyWithBgCopy();
}

static void DrawHelpBar_pokenav_main_menu(u32 windowId)
{
    FillWindowPixelBuffer(windowId, PIXEL_FILL(4));
    FillWindowPixelRect(windowId, PIXEL_FILL(5), 0, 0, 0x80, 1);
}

static void InitPokenavMainMenuResources_pokenav_main_menu(void)
{
    s32 i;
    u8 spriteId;
    struct Pokenav_MainMenu *menu = GetSubstructPtr(POKENAV_SUBSTRUCT_MAIN_MENU);

    for (i = 0; i < ARRAY_COUNT(sSpinningPokenavSpriteSheet_pokenav_main_menu); i++)
        LoadCompressedSpriteSheet(&sSpinningPokenavSpriteSheet_pokenav_main_menu[i]);

    Pokenav_AllocAndLoadPalettes(sSpinningNavgearPalettes_pokenav_main_menu);
    menu->palettes = ~1 & ~(0x10000 << IndexOfSpritePaletteTag(0));
    spriteId = CreateSprite(&sSpinningPokenavSpriteTemplate_pokenav_main_menu, 220, 12, 0);
    menu->spinningPokenav = &gSprites[spriteId];
}

static void CleanupPokenavMainMenuResources_pokenav_main_menu(void)
{
    struct Pokenav_MainMenu *menu = GetSubstructPtr(POKENAV_SUBSTRUCT_MAIN_MENU);

    DestroySprite(menu->spinningPokenav);
    FreeSpriteTilesByTag(0);
    FreeSpritePaletteByTag(0);
}

static void SpriteCB_SpinningPokenav_pokenav_main_menu(struct Sprite *sprite)
{
    // If the background starts scrolling, follow it.
    sprite->y2 = (GetBgY(0) / 256u) * -1;
}

struct Sprite *GetSpinningPokenavSprite(void)
{
    struct Pokenav_MainMenu *menu = GetSubstructPtr(POKENAV_SUBSTRUCT_MAIN_MENU);

    menu->spinningPokenav->callback = SpriteCallbackDummy;
    return menu->spinningPokenav;
}

void HideSpinningPokenavSprite(void)
{
    struct Pokenav_MainMenu *menu = GetSubstructPtr(POKENAV_SUBSTRUCT_MAIN_MENU);

    // Move sprite so it's no longer visible
    menu->spinningPokenav->x = 220;
    menu->spinningPokenav->y = 12;
    menu->spinningPokenav->callback = SpriteCB_SpinningPokenav_pokenav_main_menu;
    menu->spinningPokenav->invisible = FALSE;
    menu->spinningPokenav->oam.priority = 0;
    menu->spinningPokenav->subpriority = 0;
}

static void CreateLeftHeaderSprites_pokenav_main_menu(void)
{
    s32 i, spriteId;
    struct Pokenav_MainMenu *menu = GetSubstructPtr(POKENAV_SUBSTRUCT_MAIN_MENU);

    LoadCompressedSpriteSheet(&sMenuLeftHeaderSpriteSheet_pokenav_main_menu);
    AllocSpritePalette(1);
    AllocSpritePalette(2);
    for (i = 0; i < (s32)ARRAY_COUNT(menu->leftHeaderSprites); i++)
    {
        // Create main left header
        spriteId = CreateSprite(&sLeftHeaderSpriteTemplate_pokenav_main_menu, 0, 0, 1);
        menu->leftHeaderSprites[i] = &gSprites[spriteId];
        menu->leftHeaderSprites[i]->invisible = TRUE;
        menu->leftHeaderSprites[i]->x2 = i * 64;

        // Create submenu left header
        spriteId = CreateSprite(&sSubmenuLeftHeaderSpriteTemplate_pokenav_main_menu, 0, 0, 2);
        menu->submenuLeftHeaderSprites[i] = &gSprites[spriteId];
        menu->submenuLeftHeaderSprites[i]->invisible = TRUE;
        menu->submenuLeftHeaderSprites[i]->x2 = i * 32;
        menu->submenuLeftHeaderSprites[i]->y2 = 18;
        menu->submenuLeftHeaderSprites[i]->oam.tileNum += (i * 8) + 64;
    }
}

void LoadLeftHeaderGfxForIndex(u32 menuGfxId)
{
    if (menuGfxId < POKENAV_GFX_SUBMENUS_START)
        LoadLeftHeaderGfxForMenu_pokenav_main_menu(menuGfxId);
    else
        LoadLeftHeaderGfxForSubMenu_pokenav_main_menu(menuGfxId - POKENAV_GFX_SUBMENUS_START);
}

void UpdateRegionMapRightHeaderTiles(u32 menuGfxId)
{
    struct Pokenav_MainMenu *menu = GetSubstructPtr(POKENAV_SUBSTRUCT_MAIN_MENU);

    if (menuGfxId == POKENAV_GFX_MAP_MENU_ZOOMED_OUT)
        menu->leftHeaderSprites[1]->oam.tileNum = GetSpriteTileStartByTag(2) + 32;
    else
        menu->leftHeaderSprites[1]->oam.tileNum = GetSpriteTileStartByTag(2) + 64;
}

static void LoadLeftHeaderGfxForMenu_pokenav_main_menu(u32 menuGfxId)
{
    struct Pokenav_MainMenu *menu;
    u32 size, tag;

    if (menuGfxId >= POKENAV_GFX_SUBMENUS_START)
        return;

    menu = GetSubstructPtr(POKENAV_SUBSTRUCT_MAIN_MENU);
    tag = sMenuLeftHeaderSpriteSheets_pokenav_main_menu[menuGfxId].tag;
    size = GetDecompressedDataSize(sMenuLeftHeaderSpriteSheets_pokenav_main_menu[menuGfxId].data);
    LoadPalette(&gPokenavLeftHeader_Pal[tag * 16], OBJ_PLTT_ID(IndexOfSpritePaletteTag(1)), PLTT_SIZE_4BPP);
    LZ77UnCompWram(sMenuLeftHeaderSpriteSheets_pokenav_main_menu[menuGfxId].data, gDecompressionBuffer);
    RequestDma3Copy(gDecompressionBuffer, (void *)OBJ_VRAM0 + (GetSpriteTileStartByTag(2) * 32), size, 1);
    menu->leftHeaderSprites[1]->oam.tileNum = GetSpriteTileStartByTag(2) + sMenuLeftHeaderSpriteSheets_pokenav_main_menu[menuGfxId].size;

    if (menuGfxId == POKENAV_GFX_MAP_MENU_ZOOMED_OUT || menuGfxId == POKENAV_GFX_MAP_MENU_ZOOMED_IN)
        menu->leftHeaderSprites[1]->x2 = 56;
    else
        menu->leftHeaderSprites[1]->x2 = 64;
}

static void LoadLeftHeaderGfxForSubMenu_pokenav_main_menu(u32 menuGfxId)
{
    u32 size, tag;

    if (menuGfxId >= POKENAV_GFX_MENUS_END - POKENAV_GFX_SUBMENUS_START)
        return;

    tag = sPokenavSubMenuLeftHeaderSpriteSheets_pokenav_main_menu[menuGfxId].tag;
    size = GetDecompressedDataSize(sPokenavSubMenuLeftHeaderSpriteSheets_pokenav_main_menu[menuGfxId].data);
    LoadPalette(&gPokenavLeftHeader_Pal[tag * 16], OBJ_PLTT_ID(IndexOfSpritePaletteTag(2)), PLTT_SIZE_4BPP);
    LZ77UnCompWram(sPokenavSubMenuLeftHeaderSpriteSheets_pokenav_main_menu[menuGfxId].data, &gDecompressionBuffer[0x1000]);
    RequestDma3Copy(&gDecompressionBuffer[0x1000], (void *)OBJ_VRAM0 + 0x800 + (GetSpriteTileStartByTag(2) * 32), size, 1);
}

void ShowLeftHeaderGfx(u32 menuGfxId, bool32 isMain, bool32 isOnRightSide)
{
    u32 tileTop;

    if (!isMain)
        tileTop = 0x30;
    else
        tileTop = 0x10;

    if (menuGfxId < POKENAV_GFX_SUBMENUS_START)
        ShowLeftHeaderSprites_pokenav_main_menu(tileTop, isOnRightSide);
    else
        ShowLeftHeaderSubmenuSprites_pokenav_main_menu(tileTop, isOnRightSide);
}

void HideMainOrSubMenuLeftHeader(u32 id, bool32 onRightSide)
{
    if (id < POKENAV_GFX_PARTY_MENU)
        HideLeftHeaderSprites_pokenav_main_menu(onRightSide);
    else
        HideLeftHeaderSubmenuSprites_pokenav_main_menu(onRightSide);
}

void SetLeftHeaderSpritesInvisibility(void)
{
    s32 i;
    struct Pokenav_MainMenu *menu = GetSubstructPtr(POKENAV_SUBSTRUCT_MAIN_MENU);

    for (i = 0; i < (s32)ARRAY_COUNT(menu->leftHeaderSprites); i++)
    {
        menu->leftHeaderSprites[i]->invisible = TRUE;
        menu->submenuLeftHeaderSprites[i]->invisible = TRUE;
    }
}

bool32 AreLeftHeaderSpritesMoving(void)
{
    struct Pokenav_MainMenu *menu = GetSubstructPtr(POKENAV_SUBSTRUCT_MAIN_MENU);

    if (menu->leftHeaderSprites[0]->callback == SpriteCallbackDummy && menu->submenuLeftHeaderSprites[0]->callback == SpriteCallbackDummy)
        return FALSE;
    else
        return TRUE;
}

static void ShowLeftHeaderSprites_pokenav_main_menu(u32 startY, bool32 isOnRightSide)
{
    s32 start, end, i;
    struct Pokenav_MainMenu *menu = GetSubstructPtr(POKENAV_SUBSTRUCT_MAIN_MENU);

    if (!isOnRightSide)
        start = -96, end = 32;
    else
        start = 256, end = 160;

    for (i = 0; i < (s32)ARRAY_COUNT(menu->leftHeaderSprites); i++)
    {
        menu->leftHeaderSprites[i]->y = startY;
        MoveLeftHeader_pokenav_main_menu(menu->leftHeaderSprites[i], start, end, 12);
    }
}

static void ShowLeftHeaderSubmenuSprites_pokenav_main_menu(u32 startY, bool32 isOnRightSide)
{
    s32 start, end, i;
    struct Pokenav_MainMenu *menu = GetSubstructPtr(POKENAV_SUBSTRUCT_MAIN_MENU);

    if (!isOnRightSide)
        start = -96, end = 16;
    else
        start = 256, end = 192;

    for (i = 0; i < (s32)ARRAY_COUNT(menu->submenuLeftHeaderSprites); i++)
    {
        menu->submenuLeftHeaderSprites[i]->y = startY;
        MoveLeftHeader_pokenav_main_menu(menu->submenuLeftHeaderSprites[i], start, end, 12);
    }
}

static void HideLeftHeaderSprites_pokenav_main_menu(bool32 isOnRightSide)
{
    s32 start, end, i;
    struct Pokenav_MainMenu *menu = GetSubstructPtr(POKENAV_SUBSTRUCT_MAIN_MENU);

    if (!isOnRightSide)
        start = 32, end = -96;
    else
        start = 192, end = 256;

    for (i = 0; i < (s32)ARRAY_COUNT(menu->leftHeaderSprites); i++)
    {
        MoveLeftHeader_pokenav_main_menu(menu->leftHeaderSprites[i], start, end, 12);
    }
}

static void HideLeftHeaderSubmenuSprites_pokenav_main_menu(bool32 isOnRightSide)
{
    s32 start, end, i;
    struct Pokenav_MainMenu *menu = GetSubstructPtr(POKENAV_SUBSTRUCT_MAIN_MENU);

    if (!isOnRightSide)
        start = 16, end = -96;
    else
        start = 192, end = 256;

    for (i = 0; i < (s32)ARRAY_COUNT(menu->submenuLeftHeaderSprites); i++)
    {
        MoveLeftHeader_pokenav_main_menu(menu->submenuLeftHeaderSprites[i], start, end, 12);
    }
}

static void MoveLeftHeader_pokenav_main_menu(struct Sprite *sprite, s32 startX, s32 endX, s32 duration)
{
    sprite->x = startX;
    sprite->data[0] = startX * 16;
    sprite->data[1] = (endX - startX) * 16 / duration;
    sprite->data[2] = duration;
    sprite->data[7] = endX;
    sprite->callback = SpriteCB_MoveLeftHeader_pokenav_main_menu;
}

static void SpriteCB_MoveLeftHeader_pokenav_main_menu(struct Sprite *sprite)
{
    if (sprite->data[2] != 0)
    {
        sprite->data[2]--;
        sprite->data[0] += sprite->data[1];
        sprite->x = sprite->data[0] >> 4;
        if (sprite->x < -16 || sprite->x > 256)
            sprite->invisible = TRUE;
        else
            sprite->invisible = FALSE;
    }
    else
    {
        sprite->x = sprite->data[7];
        sprite->callback = SpriteCallbackDummy;
    }
}
