bool32 OpenMatchCall(void)
{
    struct Pokenav_MatchCallGfx *gfx = AllocSubstruct(POKENAV_SUBSTRUCT_MATCH_CALL_OPEN, sizeof(struct Pokenav_MatchCallGfx));
    if (!gfx)
        return FALSE;

    gfx->unused19 = 0;
    gfx->loopTaskId = CreateLoopedTask(LoopedTask_OpenMatchCall_pokenav_match_call_gfx, 1);
    gfx->isTaskActiveCB = GetCurrentLoopedTaskActive_pokenav_match_call_gfx;
    return TRUE;
}

void CreateMatchCallLoopedTask(s32 index)
{
    struct Pokenav_MatchCallGfx *gfx = GetSubstructPtr(POKENAV_SUBSTRUCT_MATCH_CALL_OPEN);
    gfx->loopTaskId = CreateLoopedTask(sMatchCallLoopTaskFuncs_pokenav_match_call_gfx[index], 1);
    gfx->isTaskActiveCB = GetCurrentLoopedTaskActive_pokenav_match_call_gfx;
}

bool32 IsMatchCallLoopedTaskActive(void)
{
    struct Pokenav_MatchCallGfx *gfx = GetSubstructPtr(POKENAV_SUBSTRUCT_MATCH_CALL_OPEN);
    return gfx->isTaskActiveCB();
}

void FreeMatchCallSubstruct2(void)
{
    struct Pokenav_MatchCallGfx *gfx = GetSubstructPtr(POKENAV_SUBSTRUCT_MATCH_CALL_OPEN);
    FreeMatchCallSprites_pokenav_match_call_gfx();
    DestroyMatchCallList_pokenav_match_call_gfx();
    RemoveWindow(gfx->infoBoxWindowId);
    RemoveWindow(gfx->locWindowId);
    RemoveWindow(gfx->msgBoxWindowId);
    FreePokenavSubstruct(POKENAV_SUBSTRUCT_MATCH_CALL_OPEN);
}

static bool32 GetCurrentLoopedTaskActive_pokenav_match_call_gfx(void)
{
    struct Pokenav_MatchCallGfx *gfx = GetSubstructPtr(POKENAV_SUBSTRUCT_MATCH_CALL_OPEN);
    return IsLoopedTaskActive(gfx->loopTaskId);
}

static u32 LoopedTask_OpenMatchCall_pokenav_match_call_gfx(s32 state)
{
    struct Pokenav_MatchCallGfx *gfx = GetSubstructPtr(POKENAV_SUBSTRUCT_MATCH_CALL_OPEN);
    switch (state)
    {
    case 0:
        InitBgTemplates(sMatchCallBgTemplates_pokenav_match_call_gfx, ARRAY_COUNT(sMatchCallBgTemplates_pokenav_match_call_gfx));
        ChangeBgX(2, 0, BG_COORD_SET);
        ChangeBgY(2, 0, BG_COORD_SET);
        DecompressAndCopyTileDataToVram(2, sMatchCallUI_Gfx_pokenav_match_call_gfx, 0, 0, 0);
        SetBgTilemapBuffer(2, gfx->bgTilemapBuffer2);
        CopyToBgTilemapBuffer(2, sMatchCallUI_Tilemap_pokenav_match_call_gfx, 0, 0);
        CopyBgTilemapBufferToVram(2);
        CopyPaletteIntoBufferUnfaded(sMatchCallUI_Pal_pokenav_match_call_gfx, BG_PLTT_ID(2), sizeof(sMatchCallUI_Pal_pokenav_match_call_gfx));
        CopyBgTilemapBufferToVram(2);
        return LT_INC_AND_PAUSE;
    case 1:
        if (FreeTempTileDataBuffersIfPossible())
            return LT_PAUSE;

        BgDmaFill(1, 0, 0, 1);
        SetBgTilemapBuffer(1, gfx->bgTilemapBuffer1);
        FillBgTilemapBufferRect_Palette0(1, 0x1000, 0, 0, 32, 20);
        CopyPaletteIntoBufferUnfaded(sCallWindow_Pal_pokenav_match_call_gfx, BG_PLTT_ID(1), sizeof(sCallWindow_Pal_pokenav_match_call_gfx));
        CopyBgTilemapBufferToVram(1);
        return LT_INC_AND_PAUSE;
    case 2:
        if (FreeTempTileDataBuffersIfPossible())
            return LT_PAUSE;

        LoadCallWindowAndFade_pokenav_match_call_gfx(gfx);
        DecompressAndCopyTileDataToVram(3, sPokeball_Gfx_pokenav_match_call_gfx, 0, 0, 0);
        CopyPaletteIntoBufferUnfaded(sListWindow_Pal_pokenav_match_call_gfx, BG_PLTT_ID(3), sizeof(sListWindow_Pal_pokenav_match_call_gfx));
        CopyPaletteIntoBufferUnfaded(sPokeball_Pal_pokenav_match_call_gfx, BG_PLTT_ID(5), PLTT_SIZE_4BPP);
        return LT_INC_AND_PAUSE;
    case 3:
        if (FreeTempTileDataBuffersIfPossible() || !IsMatchCallListInitFinished())
            return LT_PAUSE;

        CreateMatchCallList_pokenav_match_call_gfx();
        return LT_INC_AND_PAUSE;
    case 4:
        if (IsCreatePokenavListTaskActive())
            return LT_PAUSE;

        DrawMatchCallLeftColumnWindows_pokenav_match_call_gfx(gfx);
        return LT_INC_AND_PAUSE;
    case 5:
        UpdateMatchCallInfoBox_pokenav_match_call_gfx(gfx);
        PrintMatchCallLocation_pokenav_match_call_gfx(gfx, 0);
        return LT_INC_AND_PAUSE;
    case 6:
        ChangeBgX(1, 0, BG_COORD_SET);
        ChangeBgY(1, 0, BG_COORD_SET);
        ShowBg(2);
        ShowBg(3);
        ShowBg(1);
        AllocMatchCallSprites_pokenav_match_call_gfx();
        LoadLeftHeaderGfxForIndex(3);
        ShowLeftHeaderGfx(POKENAV_GFX_MATCH_CALL_MENU, TRUE, FALSE);
        PokenavFadeScreen(POKENAV_FADE_FROM_BLACK);
        return LT_INC_AND_PAUSE;
    case 7:
        if (IsPaletteFadeActive() || AreLeftHeaderSpritesMoving())
            return LT_PAUSE;

        SetPokeballIconsFlashing_pokenav_match_call_gfx(TRUE);
        return LT_FINISH;
    default:
        return LT_FINISH;
    }
}

static u32 MatchCallListCursorDown_pokenav_match_call_gfx(s32 state)
{
    struct Pokenav_MatchCallGfx *gfx = GetSubstructPtr(POKENAV_SUBSTRUCT_MATCH_CALL_OPEN);
    switch (state)
    {
    case 0:
        switch (PokenavList_MoveCursorDown())
        {
        case 0:
            break;
        case 1:
            PlaySE(SE_SELECT);
            return LT_SET_STATE(2);
        case 2:
            PlaySE(SE_SELECT);
            // fall through
        default:
            return LT_INC_AND_PAUSE;
        }
        break;
    case 1:
        if (PokenavList_IsMoveWindowTaskActive())
            return LT_PAUSE;

        PrintMatchCallLocation_pokenav_match_call_gfx(gfx, 0);
        return LT_INC_AND_PAUSE;
    case 2:
        PrintMatchCallLocation_pokenav_match_call_gfx(gfx, 0);
        return LT_INC_AND_PAUSE;
    case 3:
        if (IsDma3ManagerBusyWithBgCopy())
            return LT_PAUSE;
        break;
    }
    return LT_FINISH;
}

