static u32 DoMatchCallMessage_pokenav_match_call_gfx(s32 state)
{
    struct Pokenav_MatchCallGfx *gfx = GetSubstructPtr(POKENAV_SUBSTRUCT_MATCH_CALL_OPEN);
    switch (state)
    {
    case 0:
        PokenavList_ToggleVerticalArrows(TRUE);
        DrawMsgBoxForMatchCallMsg_pokenav_match_call_gfx(gfx);
        return LT_INC_AND_PAUSE;
    case 1:
        if (IsDma3ManagerBusyWithBgCopy2_pokenav_match_call_gfx(gfx))
            return LT_PAUSE;

        PrintCallingDots_pokenav_match_call_gfx(gfx);
        PlaySE(SE_POKENAV_CALL);
        gfx->skipHangUpSE = FALSE;
        return LT_INC_AND_PAUSE;
    case 2:
        if (WaitForCallingDotsText_pokenav_match_call_gfx(gfx))
            return LT_PAUSE;

        PrintMatchCallMessage_pokenav_match_call_gfx(gfx);
        return LT_INC_AND_PAUSE;
    case 3:
        if (WaitForMatchCallMessageText_pokenav_match_call_gfx(gfx))
            return LT_PAUSE;
        break;
    }

    return LT_FINISH;
}

