        PlaySE(SE_SELECT);
        DrawMsgBoxForCloseByMsg_pokenav_match_call_gfx(gfx);
        PokenavList_ToggleVerticalArrows(TRUE);
        gfx->skipHangUpSE = TRUE;
        return LT_INC_AND_PAUSE;
    case 1:
        if (IsDma3ManagerBusyWithBgCopy2_pokenav_match_call_gfx(gfx))
            return LT_PAUSE;

        PrintTrainerIsCloseBy_pokenav_match_call_gfx(gfx);
        return LT_INC_AND_PAUSE;
