{
    int topId;
    int delta;
    struct Pokenav_MatchCallGfx *gfx = GetSubstructPtr(POKENAV_SUBSTRUCT_MATCH_CALL_OPEN);
    switch (state)
    {
    case 0:
        topId = PokenavList_GetTopIndex();
        delta = GetIndexDeltaOfNextCheckPageDown(topId);
        if (delta)
        {
            PlaySE(SE_SELECT);
            gfx->pageDelta = delta;
            TrainerPicSlideOffscreen_pokenav_match_call_gfx(gfx);
            return LT_INC_AND_PAUSE;
        }
        break;
    case 1:
        if (WaitForTrainerPic_pokenav_match_call_gfx(gfx))
            return LT_PAUSE;

        PrintMatchCallLocation_pokenav_match_call_gfx(gfx, gfx->pageDelta);
        return LT_INC_AND_PAUSE;
    case 2:
        PrintCheckPageInfo(gfx->pageDelta);
        return LT_INC_AND_PAUSE;
    case 3:
        LoadCheckPageTrainerPic_pokenav_match_call_gfx(gfx);
        return LT_INC_AND_PAUSE;
    case 4:
        if (PokenavList_IsTaskActive() || WaitForTrainerPic_pokenav_match_call_gfx(gfx))
            return LT_PAUSE;
        break;
    }

    return LT_FINISH;
}

