    case 0:
        PlaySE(SE_SELECT);
        TrainerPicSlideOffscreen_pokenav_match_call_gfx(gfx);
        PokenavList_ReshowListFromCheckPage();
        return LT_INC_AND_PAUSE;
    case 1:
