static void CreateMatchCallList_pokenav_match_call_gfx(void)
{
    struct PokenavListTemplate template;
    template.list = (struct PokenavListItem *)GetMatchCallList();
    template.count = GetNumberRegistered();
    template.itemSize = sizeof(struct PokenavListItem);
    template.startIndex = 0;
    template.item_X = 13;
    template.windowWidth = 16;
    template.listTop = 1;
    template.maxShowed = 8;
    template.fillValue = 3;
    template.fontId = FONT_NARROW;
    template.bufferItemFunc = (PokenavListBufferItemFunc)BufferMatchCallNameAndDesc;
    template.iconDrawFunc = TryDrawRematchPokeballIcon_pokenav_match_call_gfx;
    CreatePokenavList(&sMatchCallBgTemplates_pokenav_match_call_gfx[2], &template, 2);
    CreateTask(Task_FlashPokeballIcons_pokenav_match_call_gfx, 7);
}

static void DestroyMatchCallList_pokenav_match_call_gfx(void)
{
    DestroyPokenavList();
    DestroyTask(FindTaskIdByFunc(Task_FlashPokeballIcons_pokenav_match_call_gfx));
}

#define tSinIdx_pokenav_match_call_gfx data[0]
#define tSinVal_pokenav_match_call_gfx data[1]
#define tActive_pokenav_match_call_gfx data[15]

static void SetPokeballIconsFlashing_pokenav_match_call_gfx(bool32 active)
{
    u8 taskId = FindTaskIdByFunc(Task_FlashPokeballIcons_pokenav_match_call_gfx);
    if (taskId != TASK_NONE)
        gTasks[taskId].tActive_pokenav_match_call_gfx = active;
}

static void Task_FlashPokeballIcons_pokenav_match_call_gfx(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    if (tActive_pokenav_match_call_gfx)
    {
        tSinIdx_pokenav_match_call_gfx += 4;
        tSinIdx_pokenav_match_call_gfx &= 0x7F;
        tSinVal_pokenav_match_call_gfx = gSineTable[tSinIdx_pokenav_match_call_gfx] >> 4;
        PokenavCopyPalette(sPokeball_Pal_pokenav_match_call_gfx, &sPokeball_Pal_pokenav_match_call_gfx[0x10], 0x10, 0x10, tSinVal_pokenav_match_call_gfx, &gPlttBufferUnfaded[BG_PLTT_ID(5)]);
        if (!gPaletteFade.active)
            CpuCopy32(&gPlttBufferUnfaded[BG_PLTT_ID(5)], &gPlttBufferFaded[BG_PLTT_ID(5)], PLTT_SIZE_4BPP);
    }
}

#undef tSinIdx_pokenav_match_call_gfx
#undef tSinVal_pokenav_match_call_gfx
#undef tActive_pokenav_match_call_gfx

enum {
    POKEBALL_ICON_TOP_pokenav_match_call_gfx = 0x5000,
    POKEBALL_ICON_BOTTOM_pokenav_match_call_gfx,
    POKEBALL_ICON_EMPTY_pokenav_match_call_gfx,
};

static void TryDrawRematchPokeballIcon_pokenav_match_call_gfx(u16 windowId, u32 rematchId, u32 tileOffset)
{
    u8 bg = GetWindowAttribute(windowId, WINDOW_BG);
    u16 *tilemap = GetBgTilemapBuffer(bg);
    tilemap += tileOffset * 64 + 0x1D;
    if (ShouldDrawRematchPokeballIcon(rematchId))
    {
        tilemap[0] = POKEBALL_ICON_TOP_pokenav_match_call_gfx;
        tilemap[0x20] = POKEBALL_ICON_BOTTOM_pokenav_match_call_gfx;
    }
    else
    {
        tilemap[0] = POKEBALL_ICON_EMPTY_pokenav_match_call_gfx;
        tilemap[0x20] = POKEBALL_ICON_EMPTY_pokenav_match_call_gfx;
    }
}

void ClearRematchPokeballIcon(u16 windowId, u32 tileOffset)
{
    u8 bg = GetWindowAttribute(windowId, WINDOW_BG);
    u16 *tilemap = GetBgTilemapBuffer(bg);
    tilemap += tileOffset * 64 + 0x1D;
    tilemap[0] = POKEBALL_ICON_EMPTY_pokenav_match_call_gfx;
    tilemap[0x20] = POKEBALL_ICON_EMPTY_pokenav_match_call_gfx;
}

