static void AllocMatchCallSprites_pokenav_match_call_gfx(void)
{
    int i;
    u8 paletteNum;
    struct SpriteSheet spriteSheet;
    struct Pokenav_MatchCallGfx *gfx = GetSubstructPtr(POKENAV_SUBSTRUCT_MATCH_CALL_OPEN);

    // Load options cursor gfx
    for (i = 0; i < ARRAY_COUNT(sOptionsCursorSpriteSheets_pokenav_match_call_gfx); i++)
        LoadCompressedSpriteSheet(&sOptionsCursorSpriteSheets_pokenav_match_call_gfx[i]);
    Pokenav_AllocAndLoadPalettes(sOptionsCursorSpritePalettes_pokenav_match_call_gfx);
    gfx->optionsCursorSprite = NULL;

    // Load trainer pic gfx
    spriteSheet.data = gfx->trainerPicGfx;
    spriteSheet.size = sizeof(gfx->trainerPicGfx);
    spriteSheet.tag = GFXTAG_TRAINER_PIC_pokenav_match_call_gfx;
    gfx->trainerPicGfxPtr = (u8 *)OBJ_VRAM0 + LoadSpriteSheet(&spriteSheet) * 0x20;
    paletteNum = AllocSpritePalette(PALTAG_TRAINER_PIC_pokenav_match_call_gfx);
    gfx->trainerPicPalOffset = OBJ_PLTT_ID(paletteNum);
    gfx->trainerPicSprite = CreateTrainerPicSprite_pokenav_match_call_gfx();
    gfx->trainerPicSprite->invisible = TRUE;
}

static void FreeMatchCallSprites_pokenav_match_call_gfx(void)
{
    struct Pokenav_MatchCallGfx *gfx = GetSubstructPtr(POKENAV_SUBSTRUCT_MATCH_CALL_OPEN);
    if (gfx->optionsCursorSprite)
        DestroySprite(gfx->optionsCursorSprite);
    if (gfx->trainerPicSprite)
        DestroySprite(gfx->trainerPicSprite);

    FreeSpriteTilesByTag(GFXTAG_TRAINER_PIC_pokenav_match_call_gfx);
    FreeSpriteTilesByTag(GFXTAG_CURSOR_pokenav_match_call_gfx);
    FreeSpritePaletteByTag(PALTAG_CURSOR_pokenav_match_call_gfx);
    FreeSpritePaletteByTag(PALTAG_TRAINER_PIC_pokenav_match_call_gfx);
}

static void CreateOptionsCursorSprite_pokenav_match_call_gfx(struct Pokenav_MatchCallGfx *gfx, int top)
{
    if (!gfx->optionsCursorSprite)
    {
        u8 spriteId = CreateSprite(&sOptionsCursorSpriteTemplate_pokenav_match_call_gfx, 4, 80, 5);
        gfx->optionsCursorSprite = &gSprites[spriteId];
        UpdateCursorGfxPos_pokenav_match_call_gfx(gfx, top);
    }
}

static void CloseMatchCallSelectOptionsWindow_pokenav_match_call_gfx(struct Pokenav_MatchCallGfx *gfx)
{
    DestroySprite(gfx->optionsCursorSprite);
    gfx->optionsCursorSprite = NULL;
}

static void UpdateCursorGfxPos_pokenav_match_call_gfx(struct Pokenav_MatchCallGfx *gfx, int top)
{
    gfx->optionsCursorSprite->y2 = top * 16;
}

static void SpriteCB_OptionsCursor_pokenav_match_call_gfx(struct Sprite *sprite)
{
    if (++sprite->data[0] > 3)
    {
        sprite->data[0] = 0;
        sprite->x2 = (sprite->x2 + 1) & 7;
    }
}

static struct Sprite *CreateTrainerPicSprite_pokenav_match_call_gfx(void)
{
    u8 spriteId = CreateSprite(&sTrainerPicSpriteTemplate_pokenav_match_call_gfx, 44, 104, 6);
    return &gSprites[spriteId];
}

static void LoadCheckPageTrainerPic_pokenav_match_call_gfx(struct Pokenav_MatchCallGfx *gfx)
{
    u16 cursor;
    int trainerPic = GetMatchCallTrainerPic(PokenavList_GetSelectedIndex());
    if (trainerPic >= 0)
    {
        DecompressPicFromTable(&gTrainerSprites[trainerPic].frontPic, gfx->trainerPicGfx);
        LZ77UnCompWram(gTrainerSprites[trainerPic].palette.data, gfx->trainerPicPal);
        cursor = RequestDma3Copy(gfx->trainerPicGfx, gfx->trainerPicGfxPtr, sizeof(gfx->trainerPicGfx), 1);
        LoadPalette(gfx->trainerPicPal, gfx->trainerPicPalOffset, sizeof(gfx->trainerPicPal));
        gfx->trainerPicSprite->data[0] = 0;
        gfx->trainerPicSprite->data[7] = cursor;
        gfx->trainerPicSprite->callback = SpriteCB_TrainerPicSlideOnscreen_pokenav_match_call_gfx;
    }
}

static void TrainerPicSlideOffscreen_pokenav_match_call_gfx(struct Pokenav_MatchCallGfx *gfx)
{
    gfx->trainerPicSprite->callback = SpriteCB_TrainerPicSlideOffscreen_pokenav_match_call_gfx;
}

static bool32 WaitForTrainerPic_pokenav_match_call_gfx(struct Pokenav_MatchCallGfx *gfx)
{
    return gfx->trainerPicSprite->callback != SpriteCallbackDummy;
}

static void SpriteCB_TrainerPicSlideOnscreen_pokenav_match_call_gfx(struct Sprite *sprite)
{
    switch (sprite->data[0])
    {
    case 0:
        if (CheckForSpaceForDma3Request(sprite->data[7]) != -1)
        {
            sprite->x2 = -80;
            sprite->invisible = FALSE;
            sprite->data[0]++;
        }
        break;
    case 1:
        sprite->x2 += 8;
        if (sprite->x2 >= 0)
        {
            sprite->x2 = 0;
            sprite->callback = SpriteCallbackDummy;
        }
        break;
    }
}

static void SpriteCB_TrainerPicSlideOffscreen_pokenav_match_call_gfx(struct Sprite *sprite)
{
    sprite->x2 -= 8;
    if (sprite->x2 <= -80)
    {
        sprite->invisible = TRUE;
        sprite->callback = SpriteCallbackDummy;
    }
}
