static bool32 AreAnyTrainerRematchesNearby_pokenav_menu_handler_gfx(void)
{
#if FREE_MATCH_CALL == FALSE
    s32 i;

    for (i = 0; i < REMATCH_TABLE_ENTRIES; i++)
    {
        if (GetMatchTableMapSectionId(i) == gMapHeader.regionMapSectionId
            && IsRematchEntryRegistered(i)
            && gSaveBlock1Ptr->trainerRematches[i])
            return TRUE;
    }
#endif //FREE_MATCH_CALL

    return FALSE;
}

bool32 OpenPokenavMenuInitial(void)
{
    struct Pokenav_MenuGfx * gfx = OpenPokenavMenu();

    if (gfx == NULL)
        return FALSE;

    gfx->pokenavAlreadyOpen = FALSE;
    return TRUE;
}

bool32 OpenPokenavMenuNotInitial(void)
{
    struct Pokenav_MenuGfx * gfx = OpenPokenavMenu();

    if (gfx == NULL)
        return FALSE;

    gfx->pokenavAlreadyOpen = TRUE;
    return TRUE;
}

static struct Pokenav_MenuGfx * OpenPokenavMenu(void)
{
    struct Pokenav_MenuGfx * gfx = AllocSubstruct(POKENAV_SUBSTRUCT_MENU_GFX, sizeof(struct Pokenav_MenuGfx));

    if (gfx != NULL)
    {
        gfx->numIconsBlending = 0;
        gfx->loopedTaskId = CreateLoopedTask(LoopedTask_OpenMenu_pokenav_menu_handler_gfx, 1);
        gfx->isTaskActiveCB = GetCurrentLoopedTaskActive_pokenav_menu_handler_gfx;
    }

    return gfx;
}

void CreateMenuHandlerLoopedTask(s32 ltIdx)
{
    struct Pokenav_MenuGfx * gfx = GetSubstructPtr(POKENAV_SUBSTRUCT_MENU_GFX);
    gfx->loopedTaskId = CreateLoopedTask(sMenuHandlerLoopTaskFuncs_pokenav_menu_handler_gfx[ltIdx], 1);
    gfx->isTaskActiveCB = GetCurrentLoopedTaskActive_pokenav_menu_handler_gfx;
}

bool32 IsMenuHandlerLoopedTaskActive(void)
{
    struct Pokenav_MenuGfx * gfx = GetSubstructPtr(POKENAV_SUBSTRUCT_MENU_GFX);
    return gfx->isTaskActiveCB();
}

void FreeMenuHandlerSubstruct2(void)
{
    struct Pokenav_MenuGfx * gfx = GetSubstructPtr(POKENAV_SUBSTRUCT_MENU_GFX);

    DestroyMovingDotsBgTask_pokenav_menu_handler_gfx();
    RemoveWindow(gfx->optionDescWindowId);
    FreeAndDestroyMainMenuSprites_pokenav_menu_handler_gfx();
    DestroyMenuOptionGlowTask_pokenav_menu_handler_gfx();
    FreePokenavSubstruct(POKENAV_SUBSTRUCT_MENU_GFX);
}

static bool32 GetCurrentLoopedTaskActive_pokenav_menu_handler_gfx(void)
{
    struct Pokenav_MenuGfx * gfx = GetSubstructPtr(POKENAV_SUBSTRUCT_MENU_GFX);

    return IsLoopedTaskActive(gfx->loopedTaskId);
}

static u32 LoopedTask_OpenMenu_pokenav_menu_handler_gfx(s32 state)
{
    struct Pokenav_MenuGfx * gfx = GetSubstructPtr(POKENAV_SUBSTRUCT_MENU_GFX);

    switch (state)
    {
    case 0:
        InitBgTemplates(sPokenavMainMenuBgTemplates_pokenav_menu_handler_gfx, ARRAY_COUNT(sPokenavMainMenuBgTemplates_pokenav_menu_handler_gfx));
        DecompressAndCopyTileDataToVram(1, gPokenavMessageBox_Gfx, 0, 0, 0);
        SetBgTilemapBuffer(1, gfx->bg1TilemapBuffer);
        CopyToBgTilemapBuffer(1, gPokenavMessageBox_Tilemap, 0, 0);
        CopyBgTilemapBufferToVram(1);
        CopyPaletteIntoBufferUnfaded(gPokenavMessageBox_Pal, BG_PLTT_ID(1), PLTT_SIZE_4BPP);
        ChangeBgX(1, 0, BG_COORD_SET);
        ChangeBgY(1, 0, BG_COORD_SET);
        ChangeBgX(2, 0, BG_COORD_SET);
        ChangeBgY(2, 0, BG_COORD_SET);
        ChangeBgX(3, 0, BG_COORD_SET);
        ChangeBgY(3, 0, BG_COORD_SET);
        return LT_INC_AND_PAUSE;
    case 1:
        if (FreeTempTileDataBuffersIfPossible())
            return LT_PAUSE;
        DecompressAndCopyTileDataToVram(2, sPokenavDeviceBgTiles_pokenav_menu_handler_gfx, 0, 0, 0);
        DecompressAndCopyTileDataToVram(2, sPokenavDeviceBgTilemap_pokenav_menu_handler_gfx, 0, 0, 1);
        CopyPaletteIntoBufferUnfaded(sPokenavDeviceBgPal_pokenav_menu_handler_gfx, BG_PLTT_ID(2), sizeof(sPokenavDeviceBgPal_pokenav_menu_handler_gfx));
        return LT_INC_AND_PAUSE;
    case 2:
        if (FreeTempTileDataBuffersIfPossible())
            return LT_PAUSE;
        DecompressAndCopyTileDataToVram(3, sPokenavBgDotsTiles_pokenav_menu_handler_gfx, 0, 0, 0);
        DecompressAndCopyTileDataToVram(3, sPokenavBgDotsTilemap_pokenav_menu_handler_gfx, 0, 0, 1);
        CopyPaletteIntoBufferUnfaded(sPokenavBgDotsPal_pokenav_menu_handler_gfx, BG_PLTT_ID(3), sizeof(sPokenavBgDotsPal_pokenav_menu_handler_gfx));
        if (GetPokenavMenuType() == POKENAV_MENU_TYPE_CONDITION || GetPokenavMenuType() == POKENAV_MENU_TYPE_CONDITION_SEARCH)
            ChangeBgDotsColorToPurple_pokenav_menu_handler_gfx();
        return LT_INC_AND_PAUSE;
    case 3:
        if (FreeTempTileDataBuffersIfPossible())
            return LT_PAUSE;
        AddOptionDescriptionWindow_pokenav_menu_handler_gfx();
        CreateMovingBgDotsTask_pokenav_menu_handler_gfx();
        return LT_INC_AND_CONTINUE;
    case 4:
        LoadPokenavOptionPalettes_pokenav_menu_handler_gfx();
        return LT_INC_AND_CONTINUE;
    case 5:
        PrintCurrentOptionDescription_pokenav_menu_handler_gfx();
        CreateMenuOptionSprites_pokenav_menu_handler_gfx();
        CreateMatchCallBlueLightSprite_pokenav_menu_handler_gfx();
        DrawCurrentMenuOptionLabels_pokenav_menu_handler_gfx();
        return LT_INC_AND_PAUSE;
    case 6:
        if (IsDma3ManagerBusyWithBgCopy__pokenav_menu_handler_gfx())
            return LT_PAUSE;
        return LT_INC_AND_CONTINUE;
    case 7:
        ShowBg(1);
        ShowBg(2);
        ShowBg(3);
        if (gfx->pokenavAlreadyOpen)
        {
            PokenavFadeScreen(POKENAV_FADE_FROM_BLACK);
        }
        else
        {
            PlaySE(SE_POKENAV_ON);
            PokenavFadeScreen(POKENAV_FADE_FROM_BLACK_ALL);
        }
        switch (GetPokenavMenuType())
        {
        case POKENAV_MENU_TYPE_CONDITION_SEARCH:
            LoadLeftHeaderGfxForIndex(7);
            // fallthrough
        case POKENAV_MENU_TYPE_CONDITION:
            LoadLeftHeaderGfxForIndex(1);
            break;
        default:
            LoadLeftHeaderGfxForIndex(0);
            break;
        }
        return LT_INC_AND_PAUSE;
    case 8:
        if (IsPaletteFadeActive())
            return LT_PAUSE;
        switch (GetPokenavMenuType())
        {
        case POKENAV_MENU_TYPE_CONDITION_SEARCH:
            ShowLeftHeaderGfx(7, FALSE, FALSE);
            // fallthrough
        case POKENAV_MENU_TYPE_CONDITION:
            ShowLeftHeaderGfx(1, FALSE, FALSE);
            break;
        default:
            ShowLeftHeaderGfx(0, FALSE, FALSE);
            break;
        }
        StartOptionAnimations_Enter_pokenav_menu_handler_gfx();
        SetupPokenavMenuScanlineEffects_pokenav_menu_handler_gfx();
        return LT_INC_AND_CONTINUE;
    case 9:
        if (AreMenuOptionSpritesMoving_pokenav_menu_handler_gfx())
            return LT_PAUSE;
        if (AreLeftHeaderSpritesMoving())
            return LT_PAUSE;
        break;
    }
    return LT_FINISH;
}

