static u32 LoopedTask_OpenConditionMenu_pokenav_menu_handler_gfx(s32 state)
{
    switch (state)
    {
    case 0:
        ResetBldCnt_pokenav_menu_handler_gfx();
        StartOptionAnimations_Exit_pokenav_menu_handler_gfx();
        HideMainOrSubMenuLeftHeader(POKENAV_GFX_MAIN_MENU, FALSE);
        PlaySE(SE_SELECT);
        return LT_INC_AND_PAUSE;
    case 1:
        if (AreMenuOptionSpritesMoving_pokenav_menu_handler_gfx())
            return LT_PAUSE;
        if (AreLeftHeaderSpritesMoving())
            return LT_PAUSE;
        DrawCurrentMenuOptionLabels_pokenav_menu_handler_gfx();
        LoadLeftHeaderGfxForIndex(1);
        return LT_INC_AND_PAUSE;
    case 2:
        StartOptionAnimations_Enter_pokenav_menu_handler_gfx();
        ShowLeftHeaderGfx(1, FALSE, FALSE);
        CreateBgDotPurplePalTask_pokenav_menu_handler_gfx();
        PrintCurrentOptionDescription_pokenav_menu_handler_gfx();
        return LT_INC_AND_PAUSE;
    case 3:
        if (AreMenuOptionSpritesMoving_pokenav_menu_handler_gfx())
            return LT_PAUSE;
        if (AreLeftHeaderSpritesMoving())
            return LT_PAUSE;
        if (IsTaskActive_UpdateBgDotsPalette_pokenav_menu_handler_gfx())
            return LT_PAUSE;
        if (IsDma3ManagerBusyWithBgCopy__pokenav_menu_handler_gfx())
            return LT_PAUSE;
        InitMenuOptionGlow_pokenav_menu_handler_gfx();
        break;
    }
    return LT_FINISH;
}

