{
    struct Pokenav_RegionMapGfx *state = AllocSubstruct(POKENAV_SUBSTRUCT_REGION_MAP_ZOOM, sizeof(struct Pokenav_RegionMapGfx));
    if (!state)
        return FALSE;

    state->loopTaskId = CreateLoopedTask(LoopedTask_OpenRegionMap_pokenav_region_map, 1);
    state->isTaskActiveCB = GetCurrentLoopedTaskActive_pokenav_region_map;
    return TRUE;
}

