static u32 HandleRibbonsMonListInput_WaitListInit_pokenav_ribbons_list(struct Pokenav_RibbonsMonList *list)
{
    if (!IsLoopedTaskActive(list->loopedTaskId))
        list->callback = HandleRibbonsMonListInput_pokenav_ribbons_list;
    return 0;
}

static u32 HandleRibbonsMonListInput_pokenav_ribbons_list(struct Pokenav_RibbonsMonList *list)
{
    if (JOY_REPEAT(DPAD_UP))
        return RIBBONS_MON_LIST_FUNC_MOVE_UP_pokenav_ribbons_list;
    if (JOY_REPEAT(DPAD_DOWN))
        return RIBBONS_MON_LIST_FUNC_MOVE_DOWN_pokenav_ribbons_list;
    if (JOY_NEW(DPAD_LEFT))
        return RIBBONS_MON_LIST_FUNC_PAGE_UP_pokenav_ribbons_list;
    if (JOY_NEW(DPAD_RIGHT))
        return RIBBONS_MON_LIST_FUNC_PAGE_DOWN_pokenav_ribbons_list;
    if (JOY_NEW(B_BUTTON))
    {
        list->saveMonList = 0;
        list->callback = RibbonsMonMenu_ReturnToMainMenu_pokenav_ribbons_list;
        return RIBBONS_MON_LIST_FUNC_EXIT_pokenav_ribbons_list;
    }
    if (JOY_NEW(A_BUTTON))
    {
        list->monList->currIndex = PokenavList_GetSelectedIndex();
        list->saveMonList = 1;
        list->callback = RibbonsMonMenu_ToSummaryScreen_pokenav_ribbons_list;
        return RIBBONS_MON_LIST_FUNC_OPEN_RIBBONS_SUMMARY_pokenav_ribbons_list;
    }
    return RIBBONS_MON_LIST_FUNC_NONE_pokenav_ribbons_list;
}

