static const u8  sMaleIconString_pokenav_ribbons_summary[] = _("{COLOR_HIGHLIGHT_SHADOW}{LIGHT_RED}{WHITE}{GREEN}♂{COLOR_HIGHLIGHT_SHADOW}{DARK_GRAY}{WHITE}{LIGHT_GRAY}");
static const u8  sFemaleIconString_pokenav_ribbons_summary[] = _("{COLOR_HIGHLIGHT_SHADOW}{LIGHT_GREEN}{WHITE}{BLUE}♀{COLOR_HIGHLIGHT_SHADOW}{DARK_GRAY}{WHITE}{LIGHT_GRAY}");
static const u8  sGenderlessIconString_pokenav_ribbons_summary[] = _("{UNK_SPACER}");

static void PrintRibbbonsSummaryMonInfo_pokenav_ribbons_summary(struct Pokenav_RibbonsSummaryMenu *menu)
{
    const u8 *genderTxt;
    u8 *txtPtr;
    u8 level, gender;
    u16 windowId = menu->nameWindowId;

    FillWindowPixelBuffer(windowId, PIXEL_FILL(1));
    GetMonNicknameLevelGender_pokenav_ribbons_summary(gStringVar3, &level, &gender);
    switch (gender)
    {
    case MON_MALE:
        genderTxt = sMaleIconString_pokenav_ribbons_summary;
        break;
    case MON_FEMALE:
        genderTxt = sFemaleIconString_pokenav_ribbons_summary;
        break;
    default:
        genderTxt = sGenderlessIconString_pokenav_ribbons_summary;
        break;
    }
    AddTextPrinterParameterized(windowId, GetFontIdToFit(gStringVar3, FONT_NORMAL, 0, 60), gStringVar3, 0, 1, TEXT_SKIP_DRAW, NULL);

    txtPtr = StringCopy(gStringVar1, genderTxt);
    *(txtPtr++) = CHAR_SLASH;
    *(txtPtr++) = CHAR_EXTRA_SYMBOL;
    *(txtPtr++) = CHAR_LV_2;
    ConvertIntToDecimalStringN(txtPtr, level, STR_CONV_MODE_LEFT_ALIGN, 3);
    AddTextPrinterParameterized(windowId, FONT_NORMAL, gStringVar1, 60, 1, TEXT_SKIP_DRAW, NULL);
    CopyWindowToVram(windowId, COPYWIN_GFX);
}

