static void AddRibbonListIndexWindow_pokenav_ribbons_summary(struct Pokenav_RibbonsSummaryMenu *menu)
{
    menu->listIdxWindowId = AddWindow(sRibbonMonListIndexWindowTemplate_pokenav_ribbons_summary);
    FillWindowPixelBuffer(menu->listIdxWindowId, PIXEL_FILL(1));
    PutWindowTilemap(menu->listIdxWindowId);
    PrintRibbonsMonListIndex_pokenav_ribbons_summary(menu);
}

static void PrintRibbonsMonListIndex_pokenav_ribbons_summary(struct Pokenav_RibbonsSummaryMenu *menu)
{
    s32 x;
    u8 *txtPtr;
    u32 id = GetRibbonsSummaryCurrentIndex_pokenav_ribbons_summary() + 1;
    u32 count = GetRibbonsSummaryMonListCount_pokenav_ribbons_summary();

    txtPtr = ConvertIntToDecimalStringN(gStringVar1, id, STR_CONV_MODE_RIGHT_ALIGN, 3);
    *(txtPtr++) = CHAR_SLASH;
    ConvertIntToDecimalStringN(txtPtr, count, STR_CONV_MODE_RIGHT_ALIGN, 3);
    x = GetStringCenterAlignXOffset(FONT_NORMAL, gStringVar1, 56);
    AddTextPrinterParameterized(menu->listIdxWindowId, FONT_NORMAL, gStringVar1, x, 1, TEXT_SKIP_DRAW, NULL);
    CopyWindowToVram(menu->listIdxWindowId, COPYWIN_GFX);
}

static void ResetSpritesAndDrawMonFrontPic_pokenav_ribbons_summary(struct Pokenav_RibbonsSummaryMenu *menu)
{
    u16 species;
    u32 personality;
    bool8 isShiny;

    GetMonSpeciesPersonalityShiny_pokenav_ribbons_summary(&species, &personality, &isShiny);
    ResetAllPicSprites();
    menu->monSpriteId = DrawRibbonsMonFrontPic_pokenav_ribbons_summary(MON_SPRITE_X_ON_pokenav_ribbons_summary, MON_SPRITE_Y_pokenav_ribbons_summary);
    PokenavFillPalette(15, 0);
}

static void DestroyRibbonsMonFrontPic_pokenav_ribbons_summary(struct Pokenav_RibbonsSummaryMenu *menu)
{
    FreeAndDestroyMonPicSprite(menu->monSpriteId);
}

// x and y arguments are ignored
// y is always given as MON_SPRITE_Y_pokenav_ribbons_summary
// x is given as either MON_SPRITE_X_ON_pokenav_ribbons_summary or MON_SPRITE_X_OFF_pokenav_ribbons_summary (but ignored and MON_SPRITE_X_ON_pokenav_ribbons_summary is used)
static u16 DrawRibbonsMonFrontPic_pokenav_ribbons_summary(s32 x, s32 y)
{
    u16 species, spriteId;
    u32 personality;
    bool8 isShiny;

    GetMonSpeciesPersonalityShiny_pokenav_ribbons_summary(&species, &personality, &isShiny);
    spriteId = CreateMonPicSprite(species, isShiny, personality, TRUE, MON_SPRITE_X_ON_pokenav_ribbons_summary, MON_SPRITE_Y_pokenav_ribbons_summary, 15, TAG_NONE);
    gSprites[spriteId].oam.priority = 0;
    return spriteId;
}

static void SlideMonSpriteOff_pokenav_ribbons_summary(struct Pokenav_RibbonsSummaryMenu *menu)
{
    StartMonSpriteSlide_pokenav_ribbons_summary(&gSprites[menu->monSpriteId], MON_SPRITE_X_ON_pokenav_ribbons_summary, MON_SPRITE_X_OFF_pokenav_ribbons_summary, 6);
}

static void SlideMonSpriteOn_pokenav_ribbons_summary(struct Pokenav_RibbonsSummaryMenu *menu)
{
    // Switch to new mon sprite
    FreeAndDestroyMonPicSprite(menu->monSpriteId);
    menu->monSpriteId = DrawRibbonsMonFrontPic_pokenav_ribbons_summary(MON_SPRITE_X_OFF_pokenav_ribbons_summary, MON_SPRITE_Y_pokenav_ribbons_summary);

    // Slide on
    StartMonSpriteSlide_pokenav_ribbons_summary(&gSprites[menu->monSpriteId], MON_SPRITE_X_OFF_pokenav_ribbons_summary, MON_SPRITE_X_ON_pokenav_ribbons_summary, 6);
}

// Is Pokémon summary sprite still sliding off/on
static bool32 IsMonSpriteAnimating_pokenav_ribbons_summary(struct Pokenav_RibbonsSummaryMenu *menu)
{
    return (gSprites[menu->monSpriteId].callback != SpriteCallbackDummy);
}

#define sCurrX_pokenav_ribbons_summary    data[0]
#define sMoveIncr_pokenav_ribbons_summary data[1]
#define sTime_pokenav_ribbons_summary     data[2]
#define sDestX_pokenav_ribbons_summary    data[3]

static void StartMonSpriteSlide_pokenav_ribbons_summary(struct Sprite *sprite, s32 startX, s32 destX, s32 time)
{
    u32 delta = destX - startX;

    sprite->x = startX;
    sprite->sCurrX_pokenav_ribbons_summary = startX << 4;
    sprite->sMoveIncr_pokenav_ribbons_summary = (delta << 4) / time;
    sprite->sTime_pokenav_ribbons_summary = time;
    sprite->sDestX_pokenav_ribbons_summary = destX;

    sprite->callback = SpriteCB_MonSpriteSlide_pokenav_ribbons_summary;
}

static void SpriteCB_MonSpriteSlide_pokenav_ribbons_summary(struct Sprite *sprite)
{
    if (sprite->sTime_pokenav_ribbons_summary != 0)
    {
        sprite->sTime_pokenav_ribbons_summary--;
        sprite->sCurrX_pokenav_ribbons_summary += sprite->sMoveIncr_pokenav_ribbons_summary;
        sprite->x = sprite->sCurrX_pokenav_ribbons_summary >> 4;
        if (sprite->x <= MON_SPRITE_X_OFF_pokenav_ribbons_summary)
            sprite->invisible = TRUE;
        else
            sprite->invisible = FALSE;
    }
    else
    {
        sprite->x = sprite->sDestX_pokenav_ribbons_summary;
        sprite->callback = SpriteCallbackDummy;
    }
}

#undef sCurrX_pokenav_ribbons_summary
#undef sMoveIncr_pokenav_ribbons_summary
#undef sTime_pokenav_ribbons_summary
#undef sDestX_pokenav_ribbons_summary

static void DrawAllRibbonsSmall_pokenav_ribbons_summary(struct Pokenav_RibbonsSummaryMenu *menu)
{
    u32 *ribbonIds;

    ClearRibbonsSummaryBg_pokenav_ribbons_summary();

    ribbonIds = GetNormalRibbonIds(&sRibbonDraw_Total_pokenav_ribbons_summary);
    for (sRibbonDraw_Current_pokenav_ribbons_summary = 0; sRibbonDraw_Current_pokenav_ribbons_summary < sRibbonDraw_Total_pokenav_ribbons_summary; sRibbonDraw_Current_pokenav_ribbons_summary++)
        DrawRibbonSmall_pokenav_ribbons_summary(sRibbonDraw_Current_pokenav_ribbons_summary, *(ribbonIds++));

    ribbonIds = GetGiftRibbonIds(&sRibbonDraw_Total_pokenav_ribbons_summary);
    for (sRibbonDraw_Current_pokenav_ribbons_summary = 0; sRibbonDraw_Current_pokenav_ribbons_summary < sRibbonDraw_Total_pokenav_ribbons_summary; sRibbonDraw_Current_pokenav_ribbons_summary++)
        DrawRibbonSmall_pokenav_ribbons_summary(sRibbonDraw_Current_pokenav_ribbons_summary + GIFT_RIBBON_START_POS_pokenav_ribbons_summary, *(ribbonIds++));

    CopyBgTilemapBufferToVram(1);
}

// Redundant, the same FillBg is called in LoopedTask_OpenRibbonsSummaryMenu_pokenav_ribbons_summary
static void ClearRibbonsSummaryBg_pokenav_ribbons_summary(void)
{
    FillBgTilemapBufferRect_Palette0(1, 0, 0, 0, 32, 20);
}

static void DrawRibbonSmall_pokenav_ribbons_summary(u32 i, u32 ribbonId)
{
    u16 bgData[4];
    u32 destX = (i % RIBBONS_PER_ROW_pokenav_ribbons_summary) * 2 + 11;
    u32 destY = (i / RIBBONS_PER_ROW_pokenav_ribbons_summary) * 2 + 4;

    BufferSmallRibbonGfxData_pokenav_ribbons_summary(bgData, ribbonId);
    CopyToBgTilemapBufferRect(1, bgData, destX, destY, 2, 2);
}

