// Create dummy sprite to be used for the zoomed in version of the selected ribbon
static void CreateBigRibbonSprite_pokenav_ribbons_summary(struct Pokenav_RibbonsSummaryMenu *menu)
{
    u8 spriteId;

    LoadCompressedSpriteSheet(&sSpriteSheet_RibbonIconsBig_pokenav_ribbons_summary);
    Pokenav_AllocAndLoadPalettes(sSpritePalettes_RibbonIcons_pokenav_ribbons_summary);

    spriteId = CreateSprite(&sSpriteTemplate_RibbonIconBig_pokenav_ribbons_summary, 0, 0, 0);
    menu->bigRibbonSprite = &gSprites[spriteId];
    menu->bigRibbonSprite->invisible = TRUE;
}

#define sInvisibleWhenDone_pokenav_ribbons_summary data[0]

static void UpdateAndZoomInSelectedRibbon_pokenav_ribbons_summary(struct Pokenav_RibbonsSummaryMenu *menu)
{
    u32 ribbonId;
    s32 position = GetSelectedPosition_pokenav_ribbons_summary();
    s32 x = (position % RIBBONS_PER_ROW_pokenav_ribbons_summary) * 16 + 96;
    s32 y = (position / RIBBONS_PER_ROW_pokenav_ribbons_summary) * 16 + 40;

    menu->bigRibbonSprite->x = x;
    menu->bigRibbonSprite->y = y;

    // Set new selected ribbon's gfx data
    ribbonId = GetRibbonId_pokenav_ribbons_summary();
    menu->bigRibbonSprite->oam.tileNum = (sRibbonGfxData[ribbonId].tileNumOffset * 16) + GetSpriteTileStartByTag(GFXTAG_RIBBON_ICONS_BIG_pokenav_ribbons_summary);
    menu->bigRibbonSprite->oam.paletteNum = IndexOfSpritePaletteTag(sRibbonGfxData[ribbonId].palNumOffset + PALTAG_RIBBON_ICONS_1_pokenav_ribbons_summary);

    // Start zoom in animation
    StartSpriteAffineAnim(menu->bigRibbonSprite, RIBBONANIM_ZOOM_IN_pokenav_ribbons_summary);
    menu->bigRibbonSprite->invisible = FALSE;
    menu->bigRibbonSprite->sInvisibleWhenDone_pokenav_ribbons_summary = FALSE;
    menu->bigRibbonSprite->callback = SpriteCB_WaitForRibbonAnimation_pokenav_ribbons_summary;
}

// Start animation to zoom out of selected ribbon
static void ZoomOutSelectedRibbon_pokenav_ribbons_summary(struct Pokenav_RibbonsSummaryMenu *menu)
{
    menu->bigRibbonSprite->sInvisibleWhenDone_pokenav_ribbons_summary = TRUE;
    StartSpriteAffineAnim(menu->bigRibbonSprite, RIBBONANIM_ZOOM_OUT_pokenav_ribbons_summary);
    menu->bigRibbonSprite->callback = SpriteCB_WaitForRibbonAnimation_pokenav_ribbons_summary;
}

static bool32 IsRibbonAnimating_pokenav_ribbons_summary(struct Pokenav_RibbonsSummaryMenu *menu)
{
    return (menu->bigRibbonSprite->callback != SpriteCallbackDummy);
}

static void SpriteCB_WaitForRibbonAnimation_pokenav_ribbons_summary(struct Sprite *sprite)
{
    if (sprite->affineAnimEnded)
    {
        sprite->invisible = sprite->sInvisibleWhenDone_pokenav_ribbons_summary;
        sprite->callback = SpriteCallbackDummy;
    }
}
