void DoRayquazaScene(u8 animId, bool8 endEarly, void (*exitCallback)(void))
{
    sRayScene_rayquaza_scene = AllocZeroed(sizeof(*sRayScene_rayquaza_scene));
    sRayScene_rayquaza_scene->animId = animId;
    sRayScene_rayquaza_scene->exitCallback = exitCallback;
    sRayScene_rayquaza_scene->endEarly = endEarly;
    SetMainCallback2(CB2_InitRayquazaScene_rayquaza_scene);
}

static void CB2_InitRayquazaScene_rayquaza_scene(void)
{
    u32 i;
    SetVBlankHBlankCallbacksToNull();
    ClearScheduledBgCopiesToVram();
    ScanlineEffect_Stop();
    for (i = 0; i < OBJECT_EVENTS_COUNT; i++)
    {
        if (gObjectEvents[i].graphicsId == OBJ_EVENT_GFX_RAYQUAZA)
            gObjectEvents[i].invisible = FALSE;
    }
    FreeAllSpritePalettes();
    ResetPaletteFade();
    ResetSpriteData();
    ResetTasks();
    FillPalette(RGB_BLACK, BG_PLTT_ID(15), PLTT_SIZE_4BPP);
    CreateTask(sTasksForAnimations_rayquaza_scene[sRayScene_rayquaza_scene->animId], 0);
    SetMainCallback2(CB2_RayquazaScene_rayquaza_scene);
}

static void CB2_RayquazaScene_rayquaza_scene(void)
{
    RunTasks();
    AnimateSprites();
    BuildOamBuffer();
    DoScheduledBgTilemapCopiesToVram();
    UpdatePaletteFade();
}

static void VBlankCB_RayquazaScene_rayquaza_scene(void)
{
    LoadOam();
    ProcessSpriteCopyRequests();
    TransferPlttBuffer();
}

static void Task_EndAfterFadeScreen_rayquaza_scene(u8 taskId)
{
    if (!gPaletteFade.active)
    {
        ResetSpriteData();
        FreeAllSpritePalettes();
        SetMainCallback2(sRayScene_rayquaza_scene->exitCallback);
        Free(sRayScene_rayquaza_scene);
        DestroyTask(taskId);
    }
}

static void Task_SetNextAnim_rayquaza_scene(u8 taskId)
{
    if (!gPaletteFade.active)
    {
        if (sRayScene_rayquaza_scene->endEarly == TRUE)
        {
            gTasks[taskId].func = Task_EndAfterFadeScreen_rayquaza_scene;
        }
        else
        {
            sRayScene_rayquaza_scene->animId++;
            sRayScene_rayquaza_scene->unk = 0;
            gTasks[taskId].func = sTasksForAnimations_rayquaza_scene[sRayScene_rayquaza_scene->animId];
        }
    }
}

// The cutscene window is cropped to a narrower view, with black borders on each vertical edge
// This function is used in scenes where sprites in these borders need to be hidden
static void SetWindowsHideVertBorders_rayquaza_scene(void)
{
    SetGpuReg(REG_OFFSET_WININ, WININ_WIN0_ALL);
    SetGpuReg(REG_OFFSET_WINOUT, 0);
    SetGpuReg(REG_OFFSET_WIN0H, WIN_RANGE(0, DISPLAY_WIDTH));
    SetGpuReg(REG_OFFSET_WIN0V, WIN_RANGE(24, DISPLAY_HEIGHT - 24));
    gPlttBufferUnfaded[0] = 0;
    gPlttBufferFaded[0] = 0;
}

static void ResetWindowDimensions_rayquaza_scene(void)
{
    SetGpuReg(REG_OFFSET_WININ, WININ_WIN0_ALL);
    SetGpuReg(REG_OFFSET_WINOUT, WINOUT_WIN01_ALL);
}


// RAY_ANIM_DUO_FIGHT_rayquaza_scene / RAY_ANIM_DUO_FIGHT_PRE_rayquaza_scene

#define tTimer_rayquaza_scene           data[0]
#define tHelperTaskId_rayquaza_scene    data[1]
#define tGroudonSpriteId_rayquaza_scene data[2]
#define tKyogreSpriteId_rayquaza_scene  data[3]

#define sGroudonBodySpriteId_rayquaza_scene     data[0]
#define sGroudonShoulderSpriteId_rayquaza_scene data[1]
#define sGroudonClawSpriteId_rayquaza_scene     data[2]

static void Task_HandleDuoFightPre_rayquaza_scene(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    DuoFight_AnimateRain_rayquaza_scene();
    if (!gPaletteFade.active)
    {
        s16 frame = tTimer_rayquaza_scene;
        if (frame == 64)
        {
            DuoFight_Lightning1_rayquaza_scene();
        }
        else if (frame == 144)
        {
            DuoFight_Lightning2_rayquaza_scene();
        }
        else
        {
            switch (frame)
            {
            case 328:
                DuoFightEnd_rayquaza_scene(taskId, 0);
                return;
            case 148:
                DuoFight_LightningLong_rayquaza_scene();
                break;
            }
        }

        tTimer_rayquaza_scene++;
    }
}

static u8 DuoFightPre_CreateGroudonSprites_rayquaza_scene(void)
{
    u8 spriteId;
    s16 *data;

    spriteId = CreateSprite(&sSpriteTemplate_DuoFightPre_Groudon_rayquaza_scene, 88, 72, 3);
    gSprites[spriteId].callback = SpriteCB_DuoFightPre_Groudon_rayquaza_scene;
    data = gSprites[spriteId].data;
    sGroudonBodySpriteId_rayquaza_scene = CreateSprite(&sSpriteTemplate_DuoFightPre_Groudon_rayquaza_scene, 56, 104, 3);
    sGroudonShoulderSpriteId_rayquaza_scene = CreateSprite(&sSpriteTemplate_DuoFightPre_GroudonShoulder_rayquaza_scene, 75, 101, 0);
    sGroudonClawSpriteId_rayquaza_scene = CreateSprite(&sSpriteTemplate_DuoFightPre_GroudonClaw_rayquaza_scene, 109, 114, 1);
    StartSpriteAnim(&gSprites[sGroudonBodySpriteId_rayquaza_scene], 1);
    return spriteId;
}

static void SpriteCB_DuoFightPre_Groudon_rayquaza_scene(struct Sprite *sprite)
{
    s16 *data = sprite->data;
    data[5]++;
    data[5] &= 0x1F;
    if (data[5] == 0 && sprite->x != 72)
    {
        sprite->x--;
        gSprites[sprite->sGroudonBodySpriteId_rayquaza_scene].x--;
        gSprites[sGroudonShoulderSpriteId_rayquaza_scene].x--;
        gSprites[sGroudonClawSpriteId_rayquaza_scene].x--;
    }

    switch (sprite->animCmdIndex)
    {
    case 0:
        gSprites[sGroudonShoulderSpriteId_rayquaza_scene].x2 = 0;
        gSprites[sGroudonShoulderSpriteId_rayquaza_scene].y2 = 0;
        gSprites[sGroudonClawSpriteId_rayquaza_scene].x2 = 0;
        gSprites[sGroudonClawSpriteId_rayquaza_scene].y2 = 0;
        break;
    case 1:
    case 3:
        gSprites[sGroudonShoulderSpriteId_rayquaza_scene].x2 = -1;
        gSprites[sGroudonShoulderSpriteId_rayquaza_scene].y2 = 0;
        gSprites[sGroudonClawSpriteId_rayquaza_scene].x2 = -1;
        gSprites[sGroudonClawSpriteId_rayquaza_scene].y2 = 0;
        break;
    case 2:
        gSprites[sGroudonShoulderSpriteId_rayquaza_scene].x2 = -1;
        gSprites[sGroudonShoulderSpriteId_rayquaza_scene].y2 = 1;
        gSprites[sGroudonClawSpriteId_rayquaza_scene].x2 = -2;
        gSprites[sGroudonClawSpriteId_rayquaza_scene].y2 = 1;
        break;
    }
}

static u8 DuoFightPre_CreateKyogreSprites_rayquaza_scene(void)
{
    u8 spriteId;
    s16 *data;

    spriteId = CreateSprite(&sSpriteTemplate_DuoFightPre_Kyogre_rayquaza_scene, 136, 96, 1);
    gSprites[spriteId].callback = SpriteCB_DuoFightPre_Kyogre_rayquaza_scene;
    data = gSprites[spriteId].data;

    data[0]  = CreateSprite(&sSpriteTemplate_DuoFightPre_Kyogre_rayquaza_scene, 168,  96, 1) << 8;
    data[0] |= CreateSprite(&sSpriteTemplate_DuoFightPre_Kyogre_rayquaza_scene, 136, 112, 1);
    data[1]  = CreateSprite(&sSpriteTemplate_DuoFightPre_Kyogre_rayquaza_scene, 168, 112, 1) << 8;
    data[1] |= CreateSprite(&sSpriteTemplate_DuoFightPre_Kyogre_rayquaza_scene, 136, 128, 1);
    data[2]  = CreateSprite(&sSpriteTemplate_DuoFightPre_Kyogre_rayquaza_scene, 168, 128, 1) << 8;
    data[2] |= CreateSprite(&sSpriteTemplate_DuoFightPre_Kyogre_rayquaza_scene, 104, 128, 2);
    data[3]  = CreateSprite(&sSpriteTemplate_DuoFightPre_Kyogre_rayquaza_scene, 136, 128, 2) << 8;
    data[3] |= CreateSprite(&sSpriteTemplate_DuoFightPre_Kyogre_rayquaza_scene, 184, 128, 0);
    data[4]  = CreateSprite(&sSpriteTemplate_DuoFightPre_KyogrePectoralFin_rayquaza_scene, 208, 132, 0) << 8;
    data[4] |= CreateSprite(&sSpriteTemplate_DuoFightPre_KyogreDorsalFin_rayquaza_scene, 200, 120, 1);

    StartSpriteAnim(&gSprites[data[0] >> 8], 1);
    StartSpriteAnim(&gSprites[data[0] & 0xFF], 2);
    StartSpriteAnim(&gSprites[data[1] >> 8], 3);
    StartSpriteAnim(&gSprites[data[1] & 0xFF], 4);
    StartSpriteAnim(&gSprites[data[2] >> 8], 5);
    StartSpriteAnim(&gSprites[data[2] & 0xFF], 6);
    StartSpriteAnim(&gSprites[data[3] >> 8], 7);
    StartSpriteAnim(&gSprites[data[3] & 0xFF], 8);

    return spriteId;
}

static void SpriteCB_DuoFightPre_Kyogre_rayquaza_scene(struct Sprite *sprite)
{
    s16 *data = sprite->data;
    data[5]++;
    data[5] &= 0x1F;
    if (data[5] == 0 && sprite->x != 152)
    {
        sprite->x++;
        gSprites[sprite->data[0] >> 8].x++;
        gSprites[sprite->data[0] & 0xFF].x++;
        gSprites[data[1] >> 8].x++;
        gSprites[data[1] & 0xFF].x++;
        gSprites[data[2] >> 8].x++;
        gSprites[data[2] & 0xFF].x++;
        gSprites[data[3] >> 8].x++;
        gSprites[data[3] & 0xFF].x++;
        gSprites[data[4] >> 8].x++;
        gSprites[data[4] & 0xFF].x++;
    }

    switch (gSprites[data[2] & 0xFF].animCmdIndex)
    {
    case 0:
        sprite->y2 = 0;
        gSprites[data[0] >> 8].y2 = 0;
        gSprites[data[0] & 0xFF].y2 = 0;
        gSprites[data[1] >> 8].y2 = 0;
        gSprites[data[1] & 0xFF].y2 = 0;
        gSprites[data[2] >> 8].y2 = 0;
        gSprites[data[2] & 0xFF].y2 = 0;
        gSprites[data[3] >> 8].y2 = 0;
        gSprites[data[3] & 0xFF].y2 = 0;
        gSprites[data[4] >> 8].y2 = 0;
        gSprites[data[4] & 0xFF].y2 = 0;
        break;
    case 1:
    case 3:
        sprite->y2 = 1;
        gSprites[data[0] >> 8].y2 = 1;
        gSprites[data[0] & 0xFF].y2 = 1;
        gSprites[data[1] >> 8].y2 = 1;
        gSprites[data[1] & 0xFF].y2 = 1;
        gSprites[data[2] >> 8].y2 = 1;
        gSprites[data[2] & 0xFF].y2 = 1;
        gSprites[data[3] >> 8].y2 = 1;
        gSprites[data[3] & 0xFF].y2 = 1;
        gSprites[data[4] >> 8].y2 = 1;
        gSprites[data[4] & 0xFF].y2 = 1;
        break;
    case 2:
        sprite->y2 = 2;
        gSprites[data[0] >> 8].y2 = 2;
        gSprites[data[0] & 0xFF].y2 = 2;
        gSprites[data[1] >> 8].y2 = 2;
        gSprites[data[1] & 0xFF].y2 = 2;
        gSprites[data[2] >> 8].y2 = 2;
        gSprites[data[4] & 0xFF].y2 = 2;
        break;
    }
}

static void VBlankCB_DuoFight_rayquaza_scene(void)
{
    VBlankCB_RayquazaScene_rayquaza_scene();
    ScanlineEffect_InitHBlankDmaTransfer();
}

static void InitDuoFightSceneBgs_rayquaza_scene(void)
{
    ResetVramOamAndBgCntRegs();
    ResetBgsAndClearDma3BusyFlags(0);
    InitBgsFromTemplates(0, sBgTemplates_DuoFight_rayquaza_scene, ARRAY_COUNT(sBgTemplates_DuoFight_rayquaza_scene));
    SetBgTilemapBuffer(0, sRayScene_rayquaza_scene->tilemapBuffers[0]);
    SetBgTilemapBuffer(1, sRayScene_rayquaza_scene->tilemapBuffers[1]);
    SetBgTilemapBuffer(2, sRayScene_rayquaza_scene->tilemapBuffers[2]);
    ResetAllBgsCoordinates();
    ScheduleBgCopyTilemapToVram(0);
    ScheduleBgCopyTilemapToVram(1);
    ScheduleBgCopyTilemapToVram(2);
    SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_OBJ_ON | DISPCNT_OBJ_1D_MAP);
    ShowBg(0);
    ShowBg(1);
    ShowBg(2);
    SetGpuReg(REG_OFFSET_BLDCNT, 0);
}

static void LoadDuoFightSceneGfx_rayquaza_scene(void)
{
    ResetTempTileDataBuffers();
    DecompressAndCopyTileDataToVram(0, gRaySceneDuoFight_Clouds_Gfx, 0, 0, 0);
    while (FreeTempTileDataBuffersIfPossible())
        ;
    LZDecompressWram(gRaySceneDuoFight_Clouds2_Tilemap, sRayScene_rayquaza_scene->tilemapBuffers[0]);
    LZDecompressWram(gRaySceneDuoFight_Clouds1_Tilemap, sRayScene_rayquaza_scene->tilemapBuffers[1]);
    LZDecompressWram(gRaySceneDuoFight_Clouds3_Tilemap, sRayScene_rayquaza_scene->tilemapBuffers[2]);
    LoadCompressedPalette(gRaySceneDuoFight_Clouds_Pal, BG_PLTT_ID(0), 2 * PLTT_SIZE_4BPP);
    LoadCompressedSpriteSheet(&sSpriteSheet_DuoFight_Groudon_rayquaza_scene);
    LoadCompressedSpriteSheet(&sSpriteSheet_DuoFight_GroudonShoulder_rayquaza_scene);
    LoadCompressedSpriteSheet(&sSpriteSheet_DuoFight_GroudonClaw_rayquaza_scene);
    LoadCompressedSpriteSheet(&sSpriteSheet_DuoFight_Kyogre_rayquaza_scene);
    LoadCompressedSpriteSheet(&sSpriteSheet_DuoFight_KyogrePectoralFin_rayquaza_scene);
    LoadCompressedSpriteSheet(&sSpriteSheet_DuoFight_KyogreDorsalFin_rayquaza_scene);
    LoadCompressedSpritePalette(&sSpritePal_DuoFight_Groudon_rayquaza_scene);
    LoadCompressedSpritePalette(&sSpritePal_DuoFight_Kyogre_rayquaza_scene);
}

static void Task_DuoFightAnim_rayquaza_scene(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    ScanlineEffect_Clear();
    InitDuoFightSceneBgs_rayquaza_scene();
    LoadDuoFightSceneGfx_rayquaza_scene();
    CpuFastFill16(0, gScanlineEffectRegBuffers, sizeof(gScanlineEffectRegBuffers));
    ScanlineEffect_SetParams(sScanlineParams_DuoFight_Clouds_rayquaza_scene);
    tTimer_rayquaza_scene = 0;
    tHelperTaskId_rayquaza_scene = CreateTask(Task_DuoFight_AnimateClouds_rayquaza_scene, 0);
    if (sRayScene_rayquaza_scene->animId == RAY_ANIM_DUO_FIGHT_PRE_rayquaza_scene)
    {
        tGroudonSpriteId_rayquaza_scene = DuoFightPre_CreateGroudonSprites_rayquaza_scene();
        tKyogreSpriteId_rayquaza_scene = DuoFightPre_CreateKyogreSprites_rayquaza_scene();
        gTasks[taskId].func = Task_HandleDuoFightPre_rayquaza_scene;
    }
    else
    {
        tGroudonSpriteId_rayquaza_scene = DuoFight_CreateGroudonSprites_rayquaza_scene();
        tKyogreSpriteId_rayquaza_scene = DuoFight_CreateKyogreSprites_rayquaza_scene();
        gTasks[taskId].func = Task_HandleDuoFight_rayquaza_scene;
        StopMapMusic();
    }

    BlendPalettes(PALETTES_ALL, 0x10, RGB_BLACK);
    BeginNormalPaletteFade(PALETTES_ALL, 0, 0x10, 0, RGB_BLACK);
    SetVBlankCallback(VBlankCB_DuoFight_rayquaza_scene);
    PlaySE(SE_DOWNPOUR);
}

static void Task_DuoFight_AnimateClouds_rayquaza_scene(u8 taskId)
{
    s16 i;
    u16 *data = (u16*)gTasks[taskId].data;

    for (i = 24; i < 92; i++)
    {
        if (i <= 47)
        {
            gScanlineEffectRegBuffers[0][i] = data[0] >> 8;
            gScanlineEffectRegBuffers[1][i] = data[0] >> 8;
        }
        else if (i <= 63)
        {
            gScanlineEffectRegBuffers[0][i] = data[1] >> 8;
            gScanlineEffectRegBuffers[1][i] = data[1] >> 8;
        }
        else if (i <= 75)
        {
            gScanlineEffectRegBuffers[0][i] = data[2] >> 8;
            gScanlineEffectRegBuffers[1][i] = data[2] >> 8;
        }
        else if (i <= 83)
        {
            gScanlineEffectRegBuffers[0][i] = data[3] >> 8;
            gScanlineEffectRegBuffers[1][i] = data[3] >> 8;
        }
        else if (i <= 87)
        {
            gScanlineEffectRegBuffers[0][i] = data[4] >> 8;
            gScanlineEffectRegBuffers[1][i] = data[4] >> 8;
        }
        else
        {
            gScanlineEffectRegBuffers[0][i] = data[5] >> 8;
            gScanlineEffectRegBuffers[1][i] = data[5] >> 8;
        }
    }

    if (sRayScene_rayquaza_scene->animId == RAY_ANIM_DUO_FIGHT_PRE_rayquaza_scene)
    {
        data[0] += 448;
        data[1] += 384;
        data[2] += 320;
        data[3] += 256;
        data[4] += 192;
        data[5] += 128;
    }
    else
    {
        data[0] += 768;
        data[1] += 640;
        data[2] += 512;
        data[3] += 384;
        data[4] += 256;
        data[5] += 128;
    }
}

static void Task_HandleDuoFight_rayquaza_scene(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    DuoFight_AnimateRain_rayquaza_scene();
    if (!gPaletteFade.active)
    {
        s16 frame = tTimer_rayquaza_scene;
        if (frame == 32 || frame == 112)
        {
            DuoFight_Lightning1_rayquaza_scene();
        }
        else if (frame == 216)
        {
            DuoFight_Lightning2_rayquaza_scene();
        }
        else if (frame == 220)
        {
            DuoFight_LightningLong_rayquaza_scene();
        }
        else
        {
            switch (frame)
            {
            case 412:
                DuoFightEnd_rayquaza_scene(taskId, 2);
                return;
            case 380:
                SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_TGT1_BG2 | BLDCNT_TGT2_BG1 | BLDCNT_EFFECT_BLEND);
                gTasks[tHelperTaskId_rayquaza_scene].func = DuoFight_PanOffScene_rayquaza_scene;
                gTasks[tHelperTaskId_rayquaza_scene].data[0] = 0;
                gTasks[tHelperTaskId_rayquaza_scene].data[2] = data[2];
                gTasks[tHelperTaskId_rayquaza_scene].data[3] = data[3];
                ScanlineEffect_Stop();
                break;
            }
        }

        tTimer_rayquaza_scene++;
    }
}

// In the below functions, BlendPalettesGradually flashes the bg white and the duo black
// and gradually fades them back to original color to simulate lightning
static void DuoFight_Lightning1_rayquaza_scene(void)
{
    PlaySE(SE_THUNDER);
    BlendPalettesGradually(PALETTES_BG & ~(0x8000), 0, 16, 0, RGB_WHITEALPHA, 0, 0);
    BlendPalettesGradually(PALETTES_OBJECTS, 0, 16, 0, RGB_BLACK,      0, 1);
}

static void DuoFight_Lightning2_rayquaza_scene(void)
{
    PlaySE(SE_THUNDER);
    BlendPalettesGradually(PALETTES_BG & ~(0x8000), 0, 16, 16, RGB_WHITEALPHA, 0, 0);
    BlendPalettesGradually(PALETTES_OBJECTS, 0, 16, 16, RGB_BLACK,      0, 1);
}

static void DuoFight_LightningLong_rayquaza_scene(void)
{
    BlendPalettesGradually(PALETTES_BG & ~(0x8000), 4, 16, 0, RGB_WHITEALPHA, 0, 0);
    BlendPalettesGradually(PALETTES_OBJECTS, 4, 16, 0, RGB_BLACK,      0, 1);
}

static void DuoFight_AnimateRain_rayquaza_scene(void)
{
    ChangeBgX(2, 0x400, BG_COORD_ADD);
    ChangeBgY(2, 0x800, BG_COORD_SUB);
}

// Only used by the full version, which pans up at the end (so scene objects move down)
// DuoFightPre just fades to black with no pan
static void DuoFight_PanOffScene_rayquaza_scene(u8 taskId)
{
    u16 bgY;
    s16 *data = gTasks[taskId].data;
    DuoFight_SlideGroudonDown_rayquaza_scene(&gSprites[tGroudonSpriteId_rayquaza_scene]);
    DuoFight_SlideKyogreDown_rayquaza_scene(&gSprites[tKyogreSpriteId_rayquaza_scene]);

    bgY = GetBgY(1);
    if (GetBgY(1) == 0 || bgY > 0x8000)
        ChangeBgY(1, 0x400, BG_COORD_SUB);

    if (tTimer_rayquaza_scene != 16)
    {
        tTimer_rayquaza_scene++;
        SetGpuReg(REG_OFFSET_BLDALPHA, BLDALPHA_BLEND(16 - tTimer_rayquaza_scene, tTimer_rayquaza_scene));
    }
}

static void DuoFightEnd_rayquaza_scene(u8 taskId, s8 palDelay)
{
    PlaySE(SE_DOWNPOUR_STOP);
    BeginNormalPaletteFade(PALETTES_ALL, palDelay, 0, 0x10, RGB_BLACK);
    gTasks[taskId].func = Task_DuoFightEnd_rayquaza_scene;
}

static void Task_DuoFightEnd_rayquaza_scene(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    DuoFight_AnimateRain_rayquaza_scene();
    if (!gPaletteFade.active)
    {
        DestroyTask(tHelperTaskId_rayquaza_scene);
        ChangeBgY(1, 0, BG_COORD_SET);
        SetVBlankCallback(NULL);
        ScanlineEffect_Stop();
        ResetSpriteData();
        FreeAllSpritePalettes();
        tTimer_rayquaza_scene = 0;
        gTasks[taskId].func = Task_SetNextAnim_rayquaza_scene;
    }
}

static u8 DuoFight_CreateGroudonSprites_rayquaza_scene(void)
{
    u8 spriteId;
    s16 *data;

    spriteId = CreateSprite(&sSpriteTemplate_DuoFight_Groudon_rayquaza_scene, 98, 72, 3);
    gSprites[spriteId].callback = SpriteCB_DuoFight_Groudon_rayquaza_scene;
    data = gSprites[spriteId].data;
    sGroudonBodySpriteId_rayquaza_scene = CreateSprite(&sSpriteTemplate_DuoFight_Groudon_rayquaza_scene, 66, 104, 3);
    sGroudonShoulderSpriteId_rayquaza_scene = CreateSprite(&sSpriteTemplate_DuoFight_GroudonShoulder_rayquaza_scene, 85, 101, 0);
    sGroudonClawSpriteId_rayquaza_scene = CreateSprite(&sSpriteTemplate_DuoFight_GroudonClaw_rayquaza_scene, 119, 114, 1);
    StartSpriteAnim(&gSprites[sGroudonBodySpriteId_rayquaza_scene], 1);
    return spriteId;
}

static void SpriteCB_DuoFight_Groudon_rayquaza_scene(struct Sprite *sprite)
{
    s16 *data = sprite->data;
    data[5]++;
    data[5] &= 0xF;
    if (!(data[5] & 7) && sprite->x != 72)
    {
        sprite->x--;
        gSprites[sprite->sGroudonBodySpriteId_rayquaza_scene].x--;
        gSprites[sGroudonShoulderSpriteId_rayquaza_scene].x--;
        gSprites[sGroudonClawSpriteId_rayquaza_scene].x--;
    }

    switch (sprite->animCmdIndex)
    {
    case 0:
        gSprites[sGroudonShoulderSpriteId_rayquaza_scene].x2 = 0;
        gSprites[sGroudonShoulderSpriteId_rayquaza_scene].y2 = 0;
        gSprites[sGroudonClawSpriteId_rayquaza_scene].x2 = 0;
        gSprites[sGroudonClawSpriteId_rayquaza_scene].y2 = 0;
        break;
    case 1:
    case 3:
        gSprites[sGroudonShoulderSpriteId_rayquaza_scene].x2 = -1;
        gSprites[sGroudonShoulderSpriteId_rayquaza_scene].y2 = 0;
        gSprites[sGroudonClawSpriteId_rayquaza_scene].x2 = -1;
        gSprites[sGroudonClawSpriteId_rayquaza_scene].y2 = 0;
        break;
    case 2:
        gSprites[sGroudonShoulderSpriteId_rayquaza_scene].x2 = -1;
        gSprites[sGroudonShoulderSpriteId_rayquaza_scene].y2 = 1;
        gSprites[sGroudonClawSpriteId_rayquaza_scene].x2 = -2;
        gSprites[sGroudonClawSpriteId_rayquaza_scene].y2 = 1;
        break;
    }
}

static void DuoFight_SlideGroudonDown_rayquaza_scene(struct Sprite *sprite)
{
    s16 *data = sprite->data;
    if (sprite->y <= DISPLAY_HEIGHT)
    {
        sprite->y += 8;
        gSprites[sprite->sGroudonBodySpriteId_rayquaza_scene].y += 8;
        gSprites[sGroudonShoulderSpriteId_rayquaza_scene].y += 8;
        gSprites[sGroudonClawSpriteId_rayquaza_scene].y += 8;
    }
}

static u8 DuoFight_CreateKyogreSprites_rayquaza_scene(void)
{
    u8 spriteId;
    s16 *data;

    spriteId = CreateSprite(&sSpriteTemplate_DuoFight_Kyogre_rayquaza_scene, 126, 96, 1);
    gSprites[spriteId].callback = SpriteCB_DuoFight_Kyogre_rayquaza_scene;
    data = gSprites[spriteId].data;

    data[0] = CreateSprite(&sSpriteTemplate_DuoFight_Kyogre_rayquaza_scene, 158, 96, 1) << 8;
    data[0] |= CreateSprite(&sSpriteTemplate_DuoFight_Kyogre_rayquaza_scene, 126, 112, 1);
    data[1] = CreateSprite(&sSpriteTemplate_DuoFight_Kyogre_rayquaza_scene, 158, 112, 1) << 8;
    data[1] |= CreateSprite(&sSpriteTemplate_DuoFight_Kyogre_rayquaza_scene, 126, 128, 1);
    data[2] = CreateSprite(&sSpriteTemplate_DuoFight_Kyogre_rayquaza_scene, 158, 128, 1) << 8;
    data[2] |= CreateSprite(&sSpriteTemplate_DuoFight_Kyogre_rayquaza_scene, 94, 128, 2);
    data[3] = CreateSprite(&sSpriteTemplate_DuoFight_Kyogre_rayquaza_scene, 126, 128, 2) << 8;
    data[3] |= CreateSprite(&sSpriteTemplate_DuoFight_Kyogre_rayquaza_scene, 174, 128, 0);
    data[4] = CreateSprite(&sSpriteTemplate_DuoFight_KyogrePectoralFin_rayquaza_scene, 198, 132, 0) << 8;
    data[4] |= CreateSprite(&sSpriteTemplate_DuoFight_KyogreDorsalFin_rayquaza_scene, 190, 120, 1);

    StartSpriteAnim(&gSprites[data[0] >> 8], 1);
    StartSpriteAnim(&gSprites[data[0] & 0xFF], 2);
    StartSpriteAnim(&gSprites[data[1] >> 8], 3);
    StartSpriteAnim(&gSprites[data[1] & 0xFF], 4);
    StartSpriteAnim(&gSprites[data[2] >> 8], 5);
    StartSpriteAnim(&gSprites[data[2] & 0xFF], 6);
    StartSpriteAnim(&gSprites[data[3] >> 8], 7);
    StartSpriteAnim(&gSprites[data[3] & 0xFF], 8);

    return spriteId;
}

static void SpriteCB_DuoFight_Kyogre_rayquaza_scene(struct Sprite *sprite)
{
    s16 *data = sprite->data;
    data[5]++;
    data[5] &= 0xF;
    if (!(data[5] & 7) && sprite->x != 152)
    {
        sprite->x++;
        gSprites[sprite->data[0] >> 8].x++;
        gSprites[sprite->data[0] & 0xFF].x++;
        gSprites[data[1] >> 8].x++;
        gSprites[data[1] & 0xFF].x++;
        gSprites[data[2] >> 8].x++;
        gSprites[data[2] & 0xFF].x++;
        gSprites[data[3] >> 8].x++;
        gSprites[data[3] & 0xFF].x++;
        gSprites[data[4] >> 8].x++;
        gSprites[data[4] & 0xFF].x++;
    }

    switch (gSprites[data[2] & 0xFF].animCmdIndex)
    {
    case 0:
        sprite->y2 = 0;
        gSprites[data[0] >> 8].y2 = 0;
        gSprites[data[0] & 0xFF].y2 = 0;
        gSprites[data[1] >> 8].y2 = 0;
        gSprites[data[1] & 0xFF].y2 = 0;
        gSprites[data[2] >> 8].y2 = 0;
        gSprites[data[2] & 0xFF].y2 = 0;
        gSprites[data[3] >> 8].y2 = 0;
        gSprites[data[3] & 0xFF].y2 = 0;
        gSprites[data[4] >> 8].y2 = 0;
        gSprites[data[4] & 0xFF].y2 = 0;
        break;
    case 1:
    case 3:
        sprite->y2 = 1;
        gSprites[data[0] >> 8].y2 = 1;
        gSprites[data[0] & 0xFF].y2 = 1;
        gSprites[data[1] >> 8].y2 = 1;
        gSprites[data[1] & 0xFF].y2 = 1;
        gSprites[data[2] >> 8].y2 = 1;
        gSprites[data[2] & 0xFF].y2 = 1;
        gSprites[data[3] >> 8].y2 = 1;
        gSprites[data[3] & 0xFF].y2 = 1;
        gSprites[data[4] >> 8].y2 = 1;
        gSprites[data[4] & 0xFF].y2 = 1;
        break;
    case 2:
        sprite->y2 = 2;
        gSprites[data[0] >> 8].y2 = 2;
        gSprites[data[0] & 0xFF].y2 = 2;
        gSprites[data[1] >> 8].y2 = 2;
        gSprites[data[1] & 0xFF].y2 = 2;
        gSprites[data[2] >> 8].y2 = 2;
        gSprites[data[4] & 0xFF].y2 = 2;
        break;
    }
}

static void DuoFight_SlideKyogreDown_rayquaza_scene(struct Sprite *sprite)
{
    s16 *data = sprite->data;
    if (sprite->y <= DISPLAY_HEIGHT)
    {
        sprite->y += 8;
        gSprites[sprite->data[0] >> 8].y += 8;
        gSprites[sprite->data[0] & 0xFF].y += 8;
        gSprites[data[1] >> 8].y += 8;
        gSprites[data[1] & 0xFF].y += 8;
        gSprites[data[2] >> 8].y += 8;
        gSprites[data[2] & 0xFF].y += 8;
        gSprites[data[3] >> 8].y += 8;
        gSprites[data[3] & 0xFF].y += 8;
        gSprites[data[4] >> 8].y += 8;
        gSprites[data[4] & 0xFF].y += 8;
    }
}

#undef tTimer_rayquaza_scene
#undef tHelperTaskId_rayquaza_scene
#undef tGroudonSpriteId_rayquaza_scene
#undef tKyogreSpriteId_rayquaza_scene

#undef sGroudonBodySpriteId_rayquaza_scene
#undef sGroudonShoulderSpriteId_rayquaza_scene
#undef sGroudonClawSpriteId_rayquaza_scene


// RAY_ANIM_TAKES_FLIGHT_rayquaza_scene

#define tState_rayquaza_scene      data[0]
#define tTimer_rayquaza_scene      data[1]
#define tScale_rayquaza_scene      data[2]
#define tScaleSpeed_rayquaza_scene data[3]
#define tYCoord_rayquaza_scene     data[4]
#define tYSpeed_rayquaza_scene     data[5]
#define tYOffset_rayquaza_scene    data[6]
#define tYOffsetDir_rayquaza_scene data[7]

static void InitTakesFlightSceneBgs_rayquaza_scene(void)
{
    ResetVramOamAndBgCntRegs();
    ResetBgsAndClearDma3BusyFlags(0);
    InitBgsFromTemplates(1, sBgTemplates_TakesFlight_rayquaza_scene, ARRAY_COUNT(sBgTemplates_TakesFlight_rayquaza_scene));
    SetBgTilemapBuffer(0, sRayScene_rayquaza_scene->tilemapBuffers[0]);
    SetBgTilemapBuffer(1, sRayScene_rayquaza_scene->tilemapBuffers[1]);
    SetBgTilemapBuffer(2, sRayScene_rayquaza_scene->tilemapBuffers[2]);
    ResetAllBgsCoordinates();
    ScheduleBgCopyTilemapToVram(0);
    ScheduleBgCopyTilemapToVram(1);
    ScheduleBgCopyTilemapToVram(2);
    SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_OBJ_ON | DISPCNT_OBJ_1D_MAP);
    ShowBg(0);
    ShowBg(1);
    ShowBg(2);
    SetGpuReg(REG_OFFSET_BLDCNT, 0);
}

static void LoadTakesFlightSceneGfx_rayquaza_scene(void)
{
    ResetTempTileDataBuffers();
    DecompressAndCopyTileDataToVram(0, gRaySceneDuoFight_Clouds_Gfx, 0, 0, 0); // Re-uses clouds from previous scene
    DecompressAndCopyTileDataToVram(1, gRaySceneTakesFlight_Bg_Gfx, 0, 0, 0);
    DecompressAndCopyTileDataToVram(2, gRaySceneTakesFlight_Rayquaza_Gfx, 0, 0, 0);
    while (FreeTempTileDataBuffersIfPossible())
        ;
    LZDecompressWram(gRaySceneDuoFight_Clouds2_Tilemap, sRayScene_rayquaza_scene->tilemapBuffers[0]);
    LZDecompressWram(gRaySceneTakesFlight_Bg_Tilemap, sRayScene_rayquaza_scene->tilemapBuffers[1]);
    LZDecompressWram(gRaySceneTakesFlight_Rayquaza_Tilemap, sRayScene_rayquaza_scene->tilemapBuffers[2]);
    LoadCompressedPalette(gRaySceneTakesFlight_Rayquaza_Pal, BG_PLTT_ID(0), 2 * PLTT_SIZE_4BPP);
    LoadCompressedSpriteSheet(&sSpriteSheet_TakesFlight_Smoke_rayquaza_scene);
    LoadCompressedSpritePalette(&sSpritePal_TakesFlight_Smoke_rayquaza_scene);
}

static void Task_RayTakesFlightAnim_rayquaza_scene(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    PlayNewMapMusic(MUS_RAYQUAZA_APPEARS);
    InitTakesFlightSceneBgs_rayquaza_scene();
    LoadTakesFlightSceneGfx_rayquaza_scene();
    SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_TGT1_OBJ | BLDCNT_TGT2_BG1 | BLDCNT_EFFECT_BLEND);
    SetGpuReg(REG_OFFSET_BLDALPHA, BLDALPHA_BLEND(8, 8));
    BlendPalettes(PALETTES_ALL, 16, 0);
    SetVBlankCallback(VBlankCB_RayquazaScene_rayquaza_scene);
    CreateTask(Task_TakesFlight_CreateSmoke_rayquaza_scene, 0);
    tState_rayquaza_scene = 0;
    tTimer_rayquaza_scene = 0;
    gTasks[taskId].func = Task_HandleRayTakesFlight_rayquaza_scene;
}

// Animate Rayquaza (flying up and down, and changing size as it gets further from the screen)
// In this scene Rayquaza is a bg tilemap on bg 2, not a sprite
static void Task_HandleRayTakesFlight_rayquaza_scene(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    switch (tState_rayquaza_scene)
    {
    case 0:
        // Delay, then fade in
        if (tTimer_rayquaza_scene == 8)
        {
            BeginNormalPaletteFade(PALETTES_ALL, 0, 0x10, 0, RGB_BLACK);
            tScale_rayquaza_scene = 0;
            tScaleSpeed_rayquaza_scene = 30;
            tYCoord_rayquaza_scene = 0;
            tYSpeed_rayquaza_scene = 7;
            tTimer_rayquaza_scene = 0;
            tState_rayquaza_scene++;
        }
        else
        {
            tTimer_rayquaza_scene++;
        }
        break;
    case 1:
        // Fly in
        tScale_rayquaza_scene += tScaleSpeed_rayquaza_scene;
        tYCoord_rayquaza_scene += tYSpeed_rayquaza_scene;

        if (tScaleSpeed_rayquaza_scene > 3)
            tScaleSpeed_rayquaza_scene -= 3;

        if (tYSpeed_rayquaza_scene != 0)
            tYSpeed_rayquaza_scene--;

        if (tScale_rayquaza_scene > 255)
        {
            tScale_rayquaza_scene = 256;
            tScaleSpeed_rayquaza_scene = 0;
            tYOffset_rayquaza_scene = 12;
            tYOffsetDir_rayquaza_scene = -1;
            tTimer_rayquaza_scene = 0;
            tState_rayquaza_scene++;
        }
        SetBgAffine(2, 0x7800, 0x1800, 120, tYCoord_rayquaza_scene + 32, tScale_rayquaza_scene, tScale_rayquaza_scene, 0);
        break;
    case 2:
        // Float up and down
        tTimer_rayquaza_scene++;
        SetBgAffine(2, 0x7800, 0x1800, 120, tYCoord_rayquaza_scene + 32 + (tYOffset_rayquaza_scene >> 2), tScale_rayquaza_scene, tScale_rayquaza_scene, 0);
        tYOffset_rayquaza_scene += tYOffsetDir_rayquaza_scene;
        if (tYOffset_rayquaza_scene == 12 || tYOffset_rayquaza_scene == -12)
        {
            tYOffsetDir_rayquaza_scene *= -1;
            if (tTimer_rayquaza_scene > 295)
            {
                tState_rayquaza_scene++;
                BeginNormalPaletteFade(PALETTES_ALL, 6, 0, 0x10, RGB_BLACK);
            }
        }
        break;
    case 3:
        // Fly away, fade out
        tScale_rayquaza_scene += 16;
        SetBgAffine(2, 0x7800, 0x1800, 120, tYCoord_rayquaza_scene + 32, tScale_rayquaza_scene, tScale_rayquaza_scene, 0);
        Task_RayTakesFlightEnd_rayquaza_scene(taskId);
        break;
    }
}

#undef tState_rayquaza_scene
#undef tTimer_rayquaza_scene
#undef tScale_rayquaza_scene
#undef tScaleSpeed_rayquaza_scene
#undef tYCoord_rayquaza_scene
#undef tYSpeed_rayquaza_scene
#undef tYOffset_rayquaza_scene
#undef tYOffsetDir_rayquaza_scene

