#define tState_rayquaza_scene          data[0]
#define tTimer_rayquaza_scene          data[1]
#define tRayquazaTaskId_rayquaza_scene data[2]
#define tSoundTimer_rayquaza_scene     data[3]

static void Task_RayChargesAnim_rayquaza_scene(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    InitChargesSceneBgs_rayquaza_scene();
    LoadChargesSceneGfx_rayquaza_scene();
    SetWindowsHideVertBorders_rayquaza_scene();
    BlendPalettes(PALETTES_ALL, 0x10, RGB_BLACK);
    SetVBlankCallback(VBlankCB_RayquazaScene_rayquaza_scene);
    tState_rayquaza_scene = 0;
    tTimer_rayquaza_scene = 0;
    tRayquazaTaskId_rayquaza_scene = CreateTask(Task_RayCharges_ShakeRayquaza_rayquaza_scene, 0);
    gTasks[taskId].func = Task_HandleRayCharges_rayquaza_scene;
}

static void Task_HandleRayCharges_rayquaza_scene(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    RayCharges_AnimateBg_rayquaza_scene();
    if ((tSoundTimer_rayquaza_scene & 7) == 0 && tState_rayquaza_scene <= 1 && tTimer_rayquaza_scene <= 89)
        PlaySE(SE_INTRO_BLAST);

    tSoundTimer_rayquaza_scene++;
    switch (tState_rayquaza_scene)
    {
    case 0:
        // Delay, then fade in
        if (tTimer_rayquaza_scene == 8)
        {
            BeginNormalPaletteFade(PALETTES_ALL, 0, 0x10, 0, RGB_BLACK);
            tTimer_rayquaza_scene = 0;
            tState_rayquaza_scene++;
        }
        else
        {
            tTimer_rayquaza_scene++;
        }
        break;
    case 1:
        // Delay while Rayquaza shakes, then start Rayquaza moving offscreen
        if (tTimer_rayquaza_scene == 127)
        {
            tTimer_rayquaza_scene = 0;
            tState_rayquaza_scene++;
            gTasks[tRayquazaTaskId_rayquaza_scene].func = Task_RayCharges_FlyOffscreen_rayquaza_scene;
        }
        else
        {
            tTimer_rayquaza_scene++;
        }
        break;
    case 2:
        // Delay for Rayquaza's flying animation
        if (tTimer_rayquaza_scene == 12)
        {
            tTimer_rayquaza_scene = 0;
            tState_rayquaza_scene++;
        }
        else
        {
            tTimer_rayquaza_scene++;
        }
        break;
    case 3:
        // Fade out
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 0x10, RGB_BLACK);
        gTasks[taskId].func = Task_RayChargesEnd_rayquaza_scene;
        break;
    }
}

#undef tState_rayquaza_scene
#undef tTimer_rayquaza_scene
#undef tSoundTimer_rayquaza_scene

#define tState_rayquaza_scene    data[0]
#define tOffset_rayquaza_scene   data[1]
#define tShakeDir_rayquaza_scene data[2]
#define tTimer_rayquaza_scene    data[15]

static void Task_RayCharges_ShakeRayquaza_rayquaza_scene(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    if ((tTimer_rayquaza_scene & 3) == 0)
    {
        ChangeBgX(1, (Random() % 8 - 4) << 8, BG_COORD_SET);
        ChangeBgY(1, (Random() % 8 - 4) << 8, BG_COORD_SET);
    }

    tTimer_rayquaza_scene++;
}

// Rayquaza backs up then launches forward
static void Task_RayCharges_FlyOffscreen_rayquaza_scene(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    if (tState_rayquaza_scene == 0)
    {
        ChangeBgX(1, 0, BG_COORD_SET);
        ChangeBgY(1, 0, BG_COORD_SET);
        tState_rayquaza_scene++;
        tOffset_rayquaza_scene = 10;
        tShakeDir_rayquaza_scene = -1;
    }
    else if (tState_rayquaza_scene == 1)
    {
        ChangeBgX(1, tOffset_rayquaza_scene << 8, BG_COORD_SUB);
        ChangeBgY(1, tOffset_rayquaza_scene << 8, BG_COORD_ADD);
        tOffset_rayquaza_scene += tShakeDir_rayquaza_scene;
        if (tOffset_rayquaza_scene == -10)
            tShakeDir_rayquaza_scene *= -1;
    }
}

#undef tState_rayquaza_scene
#undef tOffset_rayquaza_scene
#undef tShakeDir_rayquaza_scene
#undef tTimer_rayquaza_scene

static void RayCharges_AnimateBg_rayquaza_scene(void)
{
    // Update yellow orbs
    ChangeBgX(2, 0x400, BG_COORD_SUB);
    ChangeBgY(2, 0x400, BG_COORD_ADD);

    // Update blue streaks
    ChangeBgX(0, 0x800, BG_COORD_SUB);
    ChangeBgY(0, 0x800, BG_COORD_ADD);
}

static void Task_RayChargesEnd_rayquaza_scene(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    RayCharges_AnimateBg_rayquaza_scene();
    if (!gPaletteFade.active)
    {
        SetVBlankCallback(NULL);
        ResetWindowDimensions_rayquaza_scene();
        DestroyTask(tRayquazaTaskId_rayquaza_scene);
        gTasks[taskId].func = Task_SetNextAnim_rayquaza_scene;
    }
}

#undef tRayquazaTaskId_rayquaza_scene


