// these variables were const in R/S, but had to become changeable because of saveblocks changing RAM position
static void SetSrcLookupPointers_record_mixing(void)
{
    sSecretBasesSave = gSaveBlock1Ptr->secretBases;
    sTvShowsSave = gSaveBlock1Ptr->tvShows;
    sPokeNewsSave = gSaveBlock1Ptr->pokeNews;
    sOldManSave = &gSaveBlock1Ptr->oldMan;
    sDewfordTrendsSave = gSaveBlock1Ptr->dewfordTrends;
    sRecordMixMailSave = &sRecordMixMail_record_mixing;
    sBattleTowerSave = &gSaveBlock2Ptr->frontier.towerPlayer;
    sLilycoveLadySave = &gSaveBlock1Ptr->lilycoveLady;
    sApprenticesSave = gSaveBlock2Ptr->apprentices;
    sBattleTowerSave_Duplicate = &gSaveBlock2Ptr->frontier.towerPlayer;
}

static void PrepareUnknownExchangePacket_record_mixing(struct PlayerRecordRS *dest)
{
    memcpy(dest->secretBases, sSecretBasesSave, sizeof(dest->secretBases));
    memcpy(dest->tvShows, sTvShowsSave, sizeof(dest->tvShows));
    SanitizeTVShowLocationsForRuby(dest->tvShows);
    memcpy(dest->pokeNews, sPokeNewsSave, sizeof(dest->pokeNews));
    memcpy(&dest->oldMan, sOldManSave, sizeof(dest->oldMan));
    memcpy(dest->dewfordTrends, sDewfordTrendsSave, sizeof(dest->dewfordTrends));
    GetRecordMixingDaycareMail_record_mixing(&dest->daycareMail);
    EmeraldBattleTowerRecordToRuby(sBattleTowerSave, &dest->battleTowerRecord);

    if (GetMultiplayerId() == 0)
        dest->giftItem = GetRecordMixingGift();
}

static void PrepareExchangePacketForRubySapphire_record_mixing(struct PlayerRecordRS *dest)
{
    memcpy(dest->secretBases, sSecretBasesSave, sizeof(dest->secretBases));
    ClearJapaneseSecretBases(dest->secretBases);
    memcpy(dest->tvShows, sTvShowsSave, sizeof(dest->tvShows));
    SanitizeTVShowsForRuby(dest->tvShows);
    memcpy(dest->pokeNews, sPokeNewsSave, sizeof(dest->pokeNews));
    memcpy(&dest->oldMan, sOldManSave, sizeof(dest->oldMan));
    SanitizeMauvilleOldManForRuby(&dest->oldMan);
    memcpy(dest->dewfordTrends, sDewfordTrendsSave, sizeof(dest->dewfordTrends));
    GetRecordMixingDaycareMail_record_mixing(&dest->daycareMail);
    SanitizeDaycareMailForRuby_record_mixing(&dest->daycareMail);
    EmeraldBattleTowerRecordToRuby(sBattleTowerSave, &dest->battleTowerRecord);
    SanitizeRubyBattleTowerRecord_record_mixing(&dest->battleTowerRecord);

    if (GetMultiplayerId() == 0)
        dest->giftItem = GetRecordMixingGift();
}

static void PrepareExchangePacket_record_mixing(void)
{
    SetPlayerSecretBaseParty();
    DeactivateAllNormalTVShows();
    SetSrcLookupPointers_record_mixing();

    if (Link_AnyPartnersPlayingRubyOrSapphire())
    {
        if (LinkDummy_Return2() == 0)
            PrepareUnknownExchangePacket_record_mixing(&sSentRecord_record_mixing->ruby);
        else
            PrepareExchangePacketForRubySapphire_record_mixing(&sSentRecord_record_mixing->ruby);
    }
    else
    {
        memcpy(sSentRecord_record_mixing->emerald.secretBases, sSecretBasesSave, sizeof(sSentRecord_record_mixing->emerald.secretBases));
        memcpy(sSentRecord_record_mixing->emerald.tvShows, sTvShowsSave, sizeof(sSentRecord_record_mixing->emerald.tvShows));
        memcpy(sSentRecord_record_mixing->emerald.pokeNews, sPokeNewsSave, sizeof(sSentRecord_record_mixing->emerald.pokeNews));
        memcpy(&sSentRecord_record_mixing->emerald.oldMan, sOldManSave, sizeof(sSentRecord_record_mixing->emerald.oldMan));
        memcpy(&sSentRecord_record_mixing->emerald.lilycoveLady, sLilycoveLadySave, sizeof(sSentRecord_record_mixing->emerald.lilycoveLady));
        memcpy(sSentRecord_record_mixing->emerald.dewfordTrends, sDewfordTrendsSave, sizeof(sSentRecord_record_mixing->emerald.dewfordTrends));
        GetRecordMixingDaycareMail_record_mixing(&sSentRecord_record_mixing->emerald.daycareMail);
        memcpy(&sSentRecord_record_mixing->emerald.battleTowerRecord, sBattleTowerSave, sizeof(sSentRecord_record_mixing->emerald.battleTowerRecord));
        SanitizeEmeraldBattleTowerRecord_record_mixing(&sSentRecord_record_mixing->emerald.battleTowerRecord);

        if (GetMultiplayerId() == 0)
            sSentRecord_record_mixing->emerald.giftItem = GetRecordMixingGift();

        GetSavedApprentices_record_mixing(sSentRecord_record_mixing->emerald.apprentices, sApprenticesSave);
        GetPlayerHallRecords(&sSentRecord_record_mixing->emerald.hallRecords);
    }
}

static void ReceiveExchangePacket_record_mixing(u32 multiplayerId)
{
    if (Link_AnyPartnersPlayingRubyOrSapphire())
    {
        // Ruby/Sapphire
        CalculateDaycareMailRandSum_record_mixing((void *)sReceivedRecords_record_mixing->ruby.tvShows);
        ReceiveSecretBasesData(sReceivedRecords_record_mixing->ruby.secretBases, sizeof(sReceivedRecords_record_mixing->ruby), multiplayerId);
        ReceiveDaycareMailData_record_mixing(&sReceivedRecords_record_mixing->ruby.daycareMail, sizeof(sReceivedRecords_record_mixing->ruby), multiplayerId, sReceivedRecords_record_mixing->ruby.tvShows);
        ReceiveBattleTowerData_record_mixing(&sReceivedRecords_record_mixing->ruby.battleTowerRecord, sizeof(sReceivedRecords_record_mixing->ruby), multiplayerId);
        ReceiveTvShowsData(sReceivedRecords_record_mixing->ruby.tvShows, sizeof(sReceivedRecords_record_mixing->ruby), multiplayerId);
        ReceivePokeNewsData(sReceivedRecords_record_mixing->ruby.pokeNews, sizeof(sReceivedRecords_record_mixing->ruby), multiplayerId);
        ReceiveOldManData_record_mixing(&sReceivedRecords_record_mixing->ruby.oldMan, sizeof(sReceivedRecords_record_mixing->ruby), multiplayerId);
        ReceiveDewfordTrendData(sReceivedRecords_record_mixing->ruby.dewfordTrends, sizeof(sReceivedRecords_record_mixing->ruby), multiplayerId);
        ReceiveGiftItem_record_mixing(&sReceivedRecords_record_mixing->ruby.giftItem, multiplayerId);
    }
    else
    {
        // Emerald
        CalculateDaycareMailRandSum_record_mixing((void *)sReceivedRecords_record_mixing->emerald.tvShows);
        ReceiveSecretBasesData(sReceivedRecords_record_mixing->emerald.secretBases, sizeof(sReceivedRecords_record_mixing->emerald), multiplayerId);
        ReceiveTvShowsData(sReceivedRecords_record_mixing->emerald.tvShows, sizeof(sReceivedRecords_record_mixing->emerald), multiplayerId);
        ReceivePokeNewsData(sReceivedRecords_record_mixing->emerald.pokeNews, sizeof(sReceivedRecords_record_mixing->emerald), multiplayerId);
        ReceiveOldManData_record_mixing(&sReceivedRecords_record_mixing->emerald.oldMan, sizeof(sReceivedRecords_record_mixing->emerald), multiplayerId);
        ReceiveDewfordTrendData(sReceivedRecords_record_mixing->emerald.dewfordTrends, sizeof(sReceivedRecords_record_mixing->emerald), multiplayerId);
        ReceiveDaycareMailData_record_mixing(&sReceivedRecords_record_mixing->emerald.daycareMail, sizeof(sReceivedRecords_record_mixing->emerald), multiplayerId, sReceivedRecords_record_mixing->emerald.tvShows);
        ReceiveBattleTowerData_record_mixing(&sReceivedRecords_record_mixing->emerald.battleTowerRecord, sizeof(sReceivedRecords_record_mixing->emerald), multiplayerId);
        ReceiveGiftItem_record_mixing(&sReceivedRecords_record_mixing->emerald.giftItem, multiplayerId);
        ReceiveLilycoveLadyData_record_mixing(&sReceivedRecords_record_mixing->emerald.lilycoveLady, sizeof(sReceivedRecords_record_mixing->emerald), multiplayerId);
        ReceiveApprenticeData_record_mixing(sReceivedRecords_record_mixing->emerald.apprentices, sizeof(sReceivedRecords_record_mixing->emerald), (u8)multiplayerId);
        ReceiveRankingHallRecords_record_mixing(&sReceivedRecords_record_mixing->emerald.hallRecords, sizeof(sReceivedRecords_record_mixing->emerald), (u8)multiplayerId);
    }
}

