static u16 CorrectSpecialMapSecId_Internal_region_map(u16 mapSecId)
{
    u32 i;

    for (i = 0; i < ARRAY_COUNT(sMarineCaveMapSecIds_region_map); i++)
    {
        if (sMarineCaveMapSecIds_region_map[i] == mapSecId)
        {
            return GetTerraOrMarineCaveMapSecId_region_map();
        }
    }
    for (i = 0; sRegionMap_SpecialPlaceLocations_region_map[i][0] != MAPSEC_NONE; i++)
    {
        if (sRegionMap_SpecialPlaceLocations_region_map[i][0] == mapSecId)
        {
            return sRegionMap_SpecialPlaceLocations_region_map[i][1];
        }
    }
    return mapSecId;
}

static u16 GetTerraOrMarineCaveMapSecId_region_map(void)
{
    s16 idx;

    idx = VarGet(VAR_ABNORMAL_WEATHER_LOCATION) - 1;

    if (idx < 0 || idx > ABNORMAL_WEATHER_LOCATIONS - 1)
        idx = 0;

    return sTerraOrMarineCaveMapSecIds_region_map[idx];
}

static void GetMarineCaveCoords_region_map(u16 *x, u16 *y)
{
    u16 idx;

    idx = VarGet(VAR_ABNORMAL_WEATHER_LOCATION);
    if (idx < MARINE_CAVE_LOCATIONS_START || idx > ABNORMAL_WEATHER_LOCATIONS)
    {
        idx = MARINE_CAVE_LOCATIONS_START;
    }
    idx -= MARINE_CAVE_LOCATIONS_START;

    *x = sMarineCaveLocationCoords_region_map[idx].x + MAPCURSOR_X_MIN_region_map;
    *y = sMarineCaveLocationCoords_region_map[idx].y + MAPCURSOR_Y_MIN_region_map;
}

