void CreateRegionMapPlayerIcon(u16 tileTag, u16 paletteTag)
{
    u8 spriteId;
    struct SpriteSheet sheet = {sRegionMapPlayerIcon_BrendanGfx_region_map, 0x80, tileTag};
    struct SpritePalette palette = {sRegionMapPlayerIcon_BrendanPal_region_map, paletteTag};
    struct SpriteTemplate template = {tileTag, paletteTag, &sRegionMapPlayerIconOam_region_map, sRegionMapPlayerIconAnimTable_region_map, NULL, gDummySpriteAffineAnimTable, SpriteCallbackDummy};

    if (IsEventIslandMapSecId(gMapHeader.regionMapSectionId))
    {
        sRegionMap_region_map->playerIconSprite = NULL;
        return;
    }
    if (gSaveBlock2Ptr->playerGender == FEMALE)
    {
        sheet.data = sRegionMapPlayerIcon_MayGfx_region_map;
        palette.data = sRegionMapPlayerIcon_MayPal_region_map;
    }
    LoadSpriteSheet(&sheet);
    LoadSpritePalette(&palette);
    spriteId = CreateSprite(&template, 0, 0, 1);
    sRegionMap_region_map->playerIconSprite = &gSprites[spriteId];
    if (!sRegionMap_region_map->zoomed)
    {
        sRegionMap_region_map->playerIconSprite->x = sRegionMap_region_map->playerIconSpritePosX * 8 + 4;
        sRegionMap_region_map->playerIconSprite->y = sRegionMap_region_map->playerIconSpritePosY * 8 + 4;
        sRegionMap_region_map->playerIconSprite->callback = SpriteCB_PlayerIconMapFull_region_map;
    }
    else
    {
        sRegionMap_region_map->playerIconSprite->x = sRegionMap_region_map->playerIconSpritePosX * 16 - 0x30;
        sRegionMap_region_map->playerIconSprite->y = sRegionMap_region_map->playerIconSpritePosY * 16 - 0x42;
        sRegionMap_region_map->playerIconSprite->callback = SpriteCB_PlayerIconMapZoomed_region_map;
    }
}

static void HideRegionMapPlayerIcon_region_map(void)
{
    if (sRegionMap_region_map->playerIconSprite != NULL)
    {
        sRegionMap_region_map->playerIconSprite->invisible = TRUE;
        sRegionMap_region_map->playerIconSprite->callback = SpriteCallbackDummy;
    }
}

static void UnhideRegionMapPlayerIcon_region_map(void)
{
    if (sRegionMap_region_map->playerIconSprite != NULL)
    {
        if (sRegionMap_region_map->zoomed == TRUE)
        {
            sRegionMap_region_map->playerIconSprite->x = sRegionMap_region_map->playerIconSpritePosX * 16 - 0x30;
            sRegionMap_region_map->playerIconSprite->y = sRegionMap_region_map->playerIconSpritePosY * 16 - 0x42;
            sRegionMap_region_map->playerIconSprite->callback = SpriteCB_PlayerIconMapZoomed_region_map;
            sRegionMap_region_map->playerIconSprite->invisible = FALSE;
        }
        else
        {
            sRegionMap_region_map->playerIconSprite->x = sRegionMap_region_map->playerIconSpritePosX * 8 + 4;
            sRegionMap_region_map->playerIconSprite->y = sRegionMap_region_map->playerIconSpritePosY * 8 + 4;
            sRegionMap_region_map->playerIconSprite->x2 = 0;
            sRegionMap_region_map->playerIconSprite->y2 = 0;
            sRegionMap_region_map->playerIconSprite->callback = SpriteCB_PlayerIconMapFull_region_map;
            sRegionMap_region_map->playerIconSprite->invisible = FALSE;
        }
    }
}

#define sY_region_map       data[0]
#define sX_region_map       data[1]
#define sVisible_region_map data[2]
#define sTimer_region_map   data[7]

static void SpriteCB_PlayerIconMapZoomed_region_map(struct Sprite *sprite)
{
    sprite->x2 = -2 * sRegionMap_region_map->scrollX;
    sprite->y2 = -2 * sRegionMap_region_map->scrollY;
    sprite->sY_region_map = sprite->y + sprite->y2 + sprite->centerToCornerVecY;
    sprite->sX_region_map = sprite->x + sprite->x2 + sprite->centerToCornerVecX;
    if (sprite->sY_region_map < -8 || sprite->sY_region_map > DISPLAY_HEIGHT + 8 || sprite->sX_region_map < -8 || sprite->sX_region_map > DISPLAY_WIDTH + 8)
        sprite->sVisible_region_map = FALSE;
    else
        sprite->sVisible_region_map = TRUE;

    if (sprite->sVisible_region_map == TRUE)
        SpriteCB_PlayerIcon_region_map(sprite);
    else
        sprite->invisible = TRUE;
}

static void SpriteCB_PlayerIconMapFull_region_map(struct Sprite *sprite)
{
    SpriteCB_PlayerIcon_region_map(sprite);
}

static void SpriteCB_PlayerIcon_region_map(struct Sprite *sprite)
{
    if (sRegionMap_region_map->blinkPlayerIcon)
    {
        if (++sprite->sTimer_region_map > 16)
        {
            sprite->sTimer_region_map = 0;
            sprite->invisible = sprite->invisible ? FALSE : TRUE;
        }
    }
    else
    {
        sprite->invisible = FALSE;
    }
}

