static void SpriteCB_Cursor_UpOrRight_reset_rtc_screen(struct Sprite *sprite)
{
    int state = gTasks[sprite->sTaskId_reset_rtc_screen].tSelection_reset_rtc_screen;
    if (state != sprite->sState_reset_rtc_screen)
    {
        sprite->sState_reset_rtc_screen = state;
        switch (state)
        {
        case SELECTION_DAYS_reset_rtc_screen:
            sprite->invisible = FALSE;
            sprite->animNum = ARROW_UP_reset_rtc_screen;
            sprite->animDelayCounter = 0;
            sprite->x = 53;
            sprite->y = 68;
            break;
        case SELECTION_HOURS_reset_rtc_screen:
            sprite->invisible = FALSE;
            sprite->animNum = ARROW_UP_reset_rtc_screen;
            sprite->animDelayCounter = 0;
            sprite->x = 86;
            sprite->y = 68;
            break;
        case SELECTION_MINS_reset_rtc_screen:
            sprite->invisible = FALSE;
            sprite->animNum = ARROW_UP_reset_rtc_screen;
            sprite->animDelayCounter = 0;
            sprite->x = 101;
            sprite->y = 68;
            break;
        case SELECTION_SECS_reset_rtc_screen:
            sprite->invisible = FALSE;
            sprite->animNum = ARROW_UP_reset_rtc_screen;
            sprite->animDelayCounter = 0;
            sprite->x = 116;
            sprite->y = 68;
            break;
        case SELECTION_CONFIRM_reset_rtc_screen:
            sprite->invisible = FALSE;
            sprite->animNum = ARROW_RIGHT_reset_rtc_screen;
            sprite->animDelayCounter = 0;
            sprite->x = 153;
            sprite->y = 80;
            break;
        case SELECTION_NONE_reset_rtc_screen:
            DestroySprite(sprite);
            break;
        }
    }
}

