static void PrintTime_reset_rtc_screen(u8 windowId, u8 x, u8 y, u16 days, u8 hours, u8 minutes, u8 seconds)
{
    u8 *dest = gStringVar4;

    // Print days
    ConvertIntToDecimalStringN(gStringVar1, days, STR_CONV_MODE_RIGHT_ALIGN, 4);
    dest = StringCopy(dest, gStringVar1);
    dest = StringCopy(dest, gText_Day);

    // Print hours
    ConvertIntToDecimalStringN(gStringVar1, hours, STR_CONV_MODE_RIGHT_ALIGN, 3);
    dest = StringCopy(dest, gStringVar1);
    dest = StringCopy(dest, gText_Colon3);

    // Print minutes
    ConvertIntToDecimalStringN(gStringVar1, minutes, STR_CONV_MODE_LEADING_ZEROS, 2);
    dest = StringCopy(dest, gStringVar1);
    dest = StringCopy(dest, gText_Colon3);

    // Print seconds
    ConvertIntToDecimalStringN(gStringVar1, seconds, STR_CONV_MODE_LEADING_ZEROS, 2);
    dest = StringCopy(dest, gStringVar1);

    AddTextPrinterParameterized(windowId, FONT_NORMAL, gStringVar4, x, y, TEXT_SKIP_DRAW, NULL);
}

static void ShowChooseTimeWindow_reset_rtc_screen(u8 windowId, u16 days, u8 hours, u8 minutes, u8 seconds)
{
    DrawStdFrameWithCustomTileAndPalette(windowId, FALSE, 0x214, 0xE);
    PrintTime_reset_rtc_screen(windowId, 0, 1, days, hours, minutes, seconds);
    AddTextPrinterParameterized(windowId, FONT_NORMAL, gText_Confirm2, 126, 1, 0, NULL);
    ScheduleBgCopyTilemapToVram(0);
}

static bool32 MoveTimeUpDown_reset_rtc_screen(s16 *val, int minVal, int maxVal, u16 keys)
{
    if (keys & DPAD_DOWN)
    {
        *val -= 1;
        if (*val < minVal)
            *val = maxVal;
    }
    else if (keys & DPAD_UP)
    {
        *val += 1;
        if (*val > maxVal)
            *val = minVal;
    }
    else if (keys & DPAD_LEFT)
    {
        *val -= 10;
        if (*val < minVal)
            *val = maxVal;
    }
    else if (keys & DPAD_RIGHT)
    {
        *val += 10;
        if (*val > maxVal)
            *val = minVal;
    }
    else
    {
        return FALSE;
    }

    return TRUE;
}

static void Task_ResetRtc_SetFinished_reset_rtc_screen(u8 taskId)
{
    gTasks[taskId].tFinished_reset_rtc_screen = TRUE;
}

static void Task_ResetRtc_Exit_reset_rtc_screen(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    HideChooseTimeWindow_reset_rtc_screen(tWindowId_reset_rtc_screen);
    FreeCursorPalette_reset_rtc_screen();
    gTasks[taskId].func = Task_ResetRtc_SetFinished_reset_rtc_screen;
}

static void Task_ResetRtc_HandleInput_reset_rtc_screen(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    u8 selection = tSelection_reset_rtc_screen;
    const struct ResetRtcInputMap *selectionInfo = &sInputMap_reset_rtc_screen[selection - 1];

    if (JOY_NEW(B_BUTTON))
    {
        gTasks[taskId].func = Task_ResetRtc_Exit_reset_rtc_screen;
        tSetTime_reset_rtc_screen = FALSE;
        tSelection_reset_rtc_screen = SELECTION_NONE_reset_rtc_screen;
        PlaySE(SE_SELECT);
        return;
    }

    if (JOY_NEW(DPAD_RIGHT))
    {
        if (selectionInfo->right)
        {
            tSelection_reset_rtc_screen = selectionInfo->right;
            PlaySE(SE_SELECT);
            return;
        }
    }

    if (JOY_NEW(DPAD_LEFT))
    {
        if (selectionInfo->left)
        {
            tSelection_reset_rtc_screen = selectionInfo->left;
            PlaySE(SE_SELECT);
            return;
        }
    }

    if (selection == SELECTION_CONFIRM_reset_rtc_screen)
    {
        if (JOY_NEW(A_BUTTON))
        {
            gLocalTime.days = tDays_reset_rtc_screen;
            gLocalTime.hours = tHours_reset_rtc_screen;
            gLocalTime.minutes = tMinutes_reset_rtc_screen;
            gLocalTime.seconds = tSeconds_reset_rtc_screen;
            PlaySE(SE_SELECT);
            gTasks[taskId].func = Task_ResetRtc_Exit_reset_rtc_screen;
            tSetTime_reset_rtc_screen = TRUE;
            tSelection_reset_rtc_screen = SELECTION_NONE_reset_rtc_screen;
        }
    }
    else if (MoveTimeUpDown_reset_rtc_screen(&data[selectionInfo->dataIndex], selectionInfo->minVal, selectionInfo->maxVal, JOY_REPEAT(DPAD_UP | DPAD_DOWN)))
    {
        PlaySE(SE_SELECT);
        PrintTime_reset_rtc_screen(tWindowId_reset_rtc_screen, 0, 1, tDays_reset_rtc_screen, tHours_reset_rtc_screen, tMinutes_reset_rtc_screen, tSeconds_reset_rtc_screen);
        CopyWindowToVram(tWindowId_reset_rtc_screen, COPYWIN_GFX);
    }
}

static void Task_ResetRtc_Init_reset_rtc_screen(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    tFinished_reset_rtc_screen = FALSE;
    tDays_reset_rtc_screen = gLocalTime.days;
    tHours_reset_rtc_screen = gLocalTime.hours;
    tMinutes_reset_rtc_screen = gLocalTime.minutes;
    tSeconds_reset_rtc_screen = gLocalTime.seconds;
    tWindowId_reset_rtc_screen = AddWindow(&sInputTimeWindow_reset_rtc_screen);
    ShowChooseTimeWindow_reset_rtc_screen(tWindowId_reset_rtc_screen, tDays_reset_rtc_screen, tHours_reset_rtc_screen, tMinutes_reset_rtc_screen, tSeconds_reset_rtc_screen);
    CreateCursor_reset_rtc_screen(taskId);
    tSelection_reset_rtc_screen = SELECTION_HOURS_reset_rtc_screen;
    gTasks[taskId].func = Task_ResetRtc_HandleInput_reset_rtc_screen;
}

void CB2_InitResetRtcScreen(void)
{
    SetGpuReg(REG_OFFSET_DISPCNT, 0);
    SetVBlankCallback(NULL);
    DmaClear16(3, PLTT, PLTT_SIZE);
    DmaFillLarge16(3, 0, (u8 *)VRAM, VRAM_SIZE, 0x1000);
    ResetOamRange(0, 128);
    LoadOam();
    ScanlineEffect_Stop();
    ScanlineEffect_Clear();
    ResetSpriteData();
    ResetTasks();
    ResetPaletteFade();
    InitResetRtcScreenBgAndWindows_reset_rtc_screen();
    SetVBlankCallback(VBlankCB_reset_rtc_screen);
    SetMainCallback2(CB2_ResetRtcScreen_reset_rtc_screen);
    CreateTask(Task_ResetRtcScreen_reset_rtc_screen, 80);
}

static void InitResetRtcScreenBgAndWindows_reset_rtc_screen(void)
{
    ClearScheduledBgCopiesToVram();
    ResetBgsAndClearDma3BusyFlags(0);
    InitBgsFromTemplates(0, sBgTemplates_reset_rtc_screen, ARRAY_COUNT(sBgTemplates_reset_rtc_screen));
    ScheduleBgCopyTilemapToVram(0);
    SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_OBJ_ON | DISPCNT_OBJ_1D_MAP);
    ShowBg(0);
    InitWindows(sWindowTemplates_reset_rtc_screen);
    DeactivateAllTextPrinters();
    LoadMessageBoxAndBorderGfx();
}

static void CB2_ResetRtcScreen_reset_rtc_screen(void)
{
    RunTasks();
    AnimateSprites();
    BuildOamBuffer();
    DoScheduledBgTilemapCopiesToVram();
    UpdatePaletteFade();
}

static void VBlankCB_reset_rtc_screen(void)
{
    ProcessSpriteCopyRequests();
    LoadOam();
    TransferPlttBuffer();
}

static void ShowMessage_reset_rtc_screen(const u8 *str)
{
    DrawDialogFrameWithCustomTileAndPalette(WIN_MSG_reset_rtc_screen, FALSE, 0x200, 0xF);
    AddTextPrinterParameterized(WIN_MSG_reset_rtc_screen, FONT_NORMAL, str, 0, 1, 0, NULL);
    ScheduleBgCopyTilemapToVram(0);
}

#define tState_reset_rtc_screen data[0]

static void Task_ShowResetRtcPrompt_reset_rtc_screen(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    switch (tState_reset_rtc_screen)
    {
    case 0:
        DrawStdFrameWithCustomTileAndPalette(WIN_TIME_reset_rtc_screen, FALSE, 0x214, 0xE);

        AddTextPrinterParameterized(WIN_TIME_reset_rtc_screen, FONT_NORMAL, gText_PresentTime, 0, 1, TEXT_SKIP_DRAW, 0);
        PrintTime_reset_rtc_screen(
            WIN_TIME_reset_rtc_screen,
            0,
            17,
            gLocalTime.days,
            gLocalTime.hours,
            gLocalTime.minutes,
            gLocalTime.seconds);

        AddTextPrinterParameterized(WIN_TIME_reset_rtc_screen, FONT_NORMAL, gText_PreviousTime, 0, 33, TEXT_SKIP_DRAW, 0);
        PrintTime_reset_rtc_screen(
            WIN_TIME_reset_rtc_screen,
            0,
            49,
            gSaveBlock2Ptr->lastBerryTreeUpdate.days,
            gSaveBlock2Ptr->lastBerryTreeUpdate.hours,
            gSaveBlock2Ptr->lastBerryTreeUpdate.minutes,
            gSaveBlock2Ptr->lastBerryTreeUpdate.seconds);

        ShowMessage_reset_rtc_screen(gText_ResetRTCConfirmCancel);
        CopyWindowToVram(WIN_TIME_reset_rtc_screen, COPYWIN_GFX);
        ScheduleBgCopyTilemapToVram(0);
        tState_reset_rtc_screen++;
    case 1:
        if (JOY_NEW(B_BUTTON))
        {
            // Cancel, exit without resetting RTC
            DestroyTask(taskId);
            DoSoftReset();
        }
        else if (JOY_NEW(A_BUTTON))
        {
            // Confirm
            PlaySE(SE_SELECT);
            DestroyTask(taskId);
        }
        break;
    }
}

#undef tState_reset_rtc_screen

// Task states for Task_ResetRtcScreen_reset_rtc_screen
enum {
    MAINSTATE_FADE_IN_reset_rtc_screen,
    MAINSTATE_CHECK_SAVE_reset_rtc_screen,
    MAINSTATE_START_SET_TIME_reset_rtc_screen,
    MAINSTATE_WAIT_SET_TIME_reset_rtc_screen,
    MAINSTATE_SAVE_reset_rtc_screen,
    MAINSTATE_WAIT_EXIT_reset_rtc_screen,
    MAINSTATE_EXIT_reset_rtc_screen,
};

#define tState_reset_rtc_screen data[0]
#define tSubTaskId_reset_rtc_screen data[1]

static void Task_ResetRtcScreen_reset_rtc_screen(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    switch (tState_reset_rtc_screen)
    {
    case MAINSTATE_FADE_IN_reset_rtc_screen:
        BeginNormalPaletteFade(PALETTES_ALL, 1, 0x10, 0, RGB_WHITEALPHA);
        tState_reset_rtc_screen = MAINSTATE_CHECK_SAVE_reset_rtc_screen;
        break;
    case MAINSTATE_CHECK_SAVE_reset_rtc_screen:
        if (!gPaletteFade.active)
        {
            if (gSaveFileStatus == SAVE_STATUS_EMPTY
             || gSaveFileStatus == SAVE_STATUS_CORRUPT)
            {
                ShowMessage_reset_rtc_screen(gText_NoSaveFileCantSetTime);
                tState_reset_rtc_screen = MAINSTATE_WAIT_EXIT_reset_rtc_screen;
            }
            else
            {
                RtcCalcLocalTime();
                tSubTaskId_reset_rtc_screen = CreateTask(Task_ShowResetRtcPrompt_reset_rtc_screen, 80);
                tState_reset_rtc_screen = MAINSTATE_START_SET_TIME_reset_rtc_screen;
            }
        }
        break;
    case MAINSTATE_START_SET_TIME_reset_rtc_screen:
        // Wait for A or B press on prompt first
        if (gTasks[tSubTaskId_reset_rtc_screen].isActive != TRUE)
        {
            ClearStdWindowAndFrameToTransparent(WIN_TIME_reset_rtc_screen, FALSE);
            ShowMessage_reset_rtc_screen(gText_PleaseResetTime);
            gLocalTime = gSaveBlock2Ptr->lastBerryTreeUpdate;
            tSubTaskId_reset_rtc_screen = CreateTask(Task_ResetRtc_Init_reset_rtc_screen, 80);
            tState_reset_rtc_screen = MAINSTATE_WAIT_SET_TIME_reset_rtc_screen;
        }
        break;
    case MAINSTATE_WAIT_SET_TIME_reset_rtc_screen:
        if (gTasks[tSubTaskId_reset_rtc_screen].tFinished_reset_rtc_screen)
        {
            if (!gTasks[tSubTaskId_reset_rtc_screen].tSetTime_reset_rtc_screen)
            {
                // Exited without setting time, return to "Please reset time"
                DestroyTask(tSubTaskId_reset_rtc_screen);
                tState_reset_rtc_screen = MAINSTATE_START_SET_TIME_reset_rtc_screen;
            }
            else
            {
                // Time has been chosen, reset rtc and save
                DestroyTask(tSubTaskId_reset_rtc_screen);
                RtcReset();
                RtcCalcLocalTimeOffset(
                    gLocalTime.days,
                    gLocalTime.hours,
                    gLocalTime.minutes,
                    gLocalTime.seconds);
                gSaveBlock2Ptr->lastBerryTreeUpdate = gLocalTime;
                VarSet(VAR_DAYS, gLocalTime.days);
                DisableResetRTC();
                ShowMessage_reset_rtc_screen(gText_ClockHasBeenReset);
                tState_reset_rtc_screen = MAINSTATE_SAVE_reset_rtc_screen;
            }
        }
        break;
    case MAINSTATE_SAVE_reset_rtc_screen:
        if (TrySavingData(SAVE_NORMAL) == SAVE_STATUS_OK)
        {
            ShowMessage_reset_rtc_screen(gText_SaveCompleted);
            PlaySE(SE_DING_DONG);
        }
        else
        {
            ShowMessage_reset_rtc_screen(gText_SaveFailed);
            PlaySE(SE_BOO);
        }
        tState_reset_rtc_screen = MAINSTATE_WAIT_EXIT_reset_rtc_screen;
        // fallthrough
    case MAINSTATE_WAIT_EXIT_reset_rtc_screen:
        if (JOY_NEW(A_BUTTON))
        {
            BeginNormalPaletteFade(PALETTES_ALL, 1, 0, 0x10, RGB_WHITEALPHA);
            tState_reset_rtc_screen = MAINSTATE_EXIT_reset_rtc_screen;
            // fallthrough
        }
        else
        {
            break;
        }
    case MAINSTATE_EXIT_reset_rtc_screen:
        if (!gPaletteFade.active)
        {
            DestroyTask(taskId);
            FreeAllWindowBuffers();
            DoSoftReset();
        }
    }
}
