#undef ____roamer
#define NUM_LOCATION_SETS_roamer (ARRAY_COUNT(sRoamerLocations_roamer) - 1)
#define NUM_LOCATIONS_PER_SET_roamer (ARRAY_COUNT(sRoamerLocations_roamer[0]))

void DeactivateAllRoamers(void)
{
    u32 i;

    for (i = 0; i < ROAMER_COUNT; i++)
        SetRoamerInactive(i);
}

static void ClearRoamerLocationHistory_roamer(u32 roamerIndex)
{
    u32 i;

    for (i = 0; i < ARRAY_COUNT(sLocationHistory_roamer[roamerIndex]); i++)
    {
        sLocationHistory_roamer[roamerIndex][i][MAP_GRP] = 0;
        sLocationHistory_roamer[roamerIndex][i][MAP_NUM] = 0;
    }
}

void MoveAllRoamersToOtherLocationSets(void)
{
    u32 i;

    for (i = 0; i < ROAMER_COUNT; i++)
        RoamerMoveToOtherLocationSet(i);
}

void MoveAllRoamers(void)
{
    u32 i;

    for (i = 0; i < ROAMER_COUNT; i++)
        RoamerMove(i);
}

static void CreateInitialRoamerMon_roamer(u8 index, u16 species, u8 level)
{
    ClearRoamerLocationHistory_roamer(index);
    CreateMon(&gEnemyParty[0], species, level, USE_RANDOM_IVS, FALSE, 0, OT_ID_PLAYER_ID, 0);
    ROAMER_roamer(index)->ivs = GetMonData(&gEnemyParty[0], MON_DATA_IVS);
    ROAMER_roamer(index)->personality = GetMonData(&gEnemyParty[0], MON_DATA_PERSONALITY);
    ROAMER_roamer(index)->species = species;
    ROAMER_roamer(index)->level = level;
    ROAMER_roamer(index)->statusA = 0;
    ROAMER_roamer(index)->statusB = 0;
    ROAMER_roamer(index)->hp = GetMonData(&gEnemyParty[0], MON_DATA_MAX_HP);
    ROAMER_roamer(index)->cool = GetMonData(&gEnemyParty[0], MON_DATA_COOL);
    ROAMER_roamer(index)->beauty = GetMonData(&gEnemyParty[0], MON_DATA_BEAUTY);
    ROAMER_roamer(index)->cute = GetMonData(&gEnemyParty[0], MON_DATA_CUTE);
    ROAMER_roamer(index)->smart = GetMonData(&gEnemyParty[0], MON_DATA_SMART);
    ROAMER_roamer(index)->tough = GetMonData(&gEnemyParty[0], MON_DATA_TOUGH);
    ROAMER_roamer(index)->active = TRUE;
    sRoamerLocation_roamer[index][MAP_GRP] = ROAMER_MAP_GROUP_roamer;
    sRoamerLocation_roamer[index][MAP_NUM] = sRoamerLocations_roamer[Random() % NUM_LOCATION_SETS_roamer][0];
}

static u8 GetFirstInactiveRoamerIndex_roamer(void)
{
    u32 i;

    for (i = 0; i < ROAMER_COUNT; i++)
    {
        if (!ROAMER_roamer(i)->active)
            return i;
    }
    return ROAMER_COUNT;
}

bool8 TryAddRoamer(u16 species, u8 level)
{
    u8 index = GetFirstInactiveRoamerIndex_roamer();

    if (index < ROAMER_COUNT)
    {
        // Create the roamer and stop searching
        CreateInitialRoamerMon_roamer(index, species, level);
        return TRUE;
    }

    // Maximum active roamers found: do nothing and let the calling function know
    return FALSE;
}

// gSpecialVar_0x8004 here corresponds to the options in the multichoice MULTI_TV_LATI (0 for 'Red', 1 for 'Blue')
void InitRoamer(void)
{
    if (gSpecialVar_0x8004 == 0) // Red
        TryAddRoamer(SPECIES_LATIAS, 40);
    else
        TryAddRoamer(SPECIES_LATIOS, 40);
}

void UpdateLocationHistoryForRoamer(void)
{
    u32 i;

    for (i = 0; i < ROAMER_COUNT; i++)
    {
        sLocationHistory_roamer[i][2][MAP_GRP] = sLocationHistory_roamer[i][1][MAP_GRP];
        sLocationHistory_roamer[i][2][MAP_NUM] = sLocationHistory_roamer[i][1][MAP_NUM];

        sLocationHistory_roamer[i][1][MAP_GRP] = sLocationHistory_roamer[i][0][MAP_GRP];
        sLocationHistory_roamer[i][1][MAP_NUM] = sLocationHistory_roamer[i][0][MAP_NUM];

        sLocationHistory_roamer[i][0][MAP_GRP] = gSaveBlock1Ptr->location.mapGroup;
        sLocationHistory_roamer[i][0][MAP_NUM] = gSaveBlock1Ptr->location.mapNum;
    }
}

void RoamerMoveToOtherLocationSet(u32 roamerIndex)
{
    u8 mapNum = 0;

    if (!ROAMER_roamer(roamerIndex)->active)
        return;

    sRoamerLocation_roamer[roamerIndex][MAP_GRP] = ROAMER_MAP_GROUP_roamer;

    // Choose a location set that starts with a map
    // different from the roamer's current map
    do
    {
        mapNum = sRoamerLocations_roamer[Random() % NUM_LOCATION_SETS_roamer][0];
        if (sRoamerLocation_roamer[roamerIndex][MAP_NUM] != mapNum)
        {
            sRoamerLocation_roamer[roamerIndex][MAP_NUM] = mapNum;
            return;
        }
    } while (sRoamerLocation_roamer[roamerIndex][MAP_NUM] == mapNum);
    sRoamerLocation_roamer[roamerIndex][MAP_NUM] = mapNum;
}

void RoamerMove(u32 roamerIndex)
{
    u8 locSet = 0;

    if ((Random() % 16) == 0)
    {
        RoamerMoveToOtherLocationSet(roamerIndex);
    }
    else
    {
        if (!ROAMER_roamer(roamerIndex)->active)
            return;

        while (locSet < NUM_LOCATION_SETS_roamer)
        {
            // Find the location set that starts with the roamer's current map
            if (sRoamerLocation_roamer[roamerIndex][MAP_NUM] == sRoamerLocations_roamer[locSet][0])
            {
                u8 mapNum;
                // Choose a new map (excluding the first) within this set
                // Also exclude a map if the roamer was there 2 moves ago
                do
                {
                    mapNum = sRoamerLocations_roamer[locSet][(Random() % (NUM_LOCATIONS_PER_SET_roamer - 1)) + 1];
                } while ((sLocationHistory_roamer[roamerIndex][2][MAP_GRP] == ROAMER_MAP_GROUP_roamer
                        && sLocationHistory_roamer[roamerIndex][2][MAP_NUM] == mapNum)
                        || mapNum == MAP_NUM(UNDEFINED));
                sRoamerLocation_roamer[roamerIndex][MAP_NUM] = mapNum;
                return;
            }
            locSet++;
        }
    }
}

bool8 IsRoamerAt(u32 roamerIndex, u8 mapGroup, u8 mapNum)
{
    if (ROAMER_roamer(roamerIndex)->active && mapGroup == sRoamerLocation_roamer[roamerIndex][MAP_GRP] && mapNum == sRoamerLocation_roamer[roamerIndex][MAP_NUM])
        return TRUE;
    else
        return FALSE;
}

void CreateRoamerMonInstance(u32 roamerIndex)
{
    u32 status = ROAMER_roamer(roamerIndex)->statusA + (ROAMER_roamer(roamerIndex)->statusB << 8);
    struct Pokemon *mon = &gEnemyParty[0];
    ZeroEnemyPartyMons();
    CreateMonWithIVsPersonality(mon, ROAMER_roamer(roamerIndex)->species, ROAMER_roamer(roamerIndex)->level, ROAMER_roamer(roamerIndex)->ivs, ROAMER_roamer(roamerIndex)->personality);
    // The roamer's status field is u16, but SetMonData expects status to be u32, so will set the roamer's status
    // using the status field and the following 3 bytes (cool, beauty, and cute).
    SetMonData(mon, MON_DATA_STATUS, &status);
    SetMonData(mon, MON_DATA_HP, &ROAMER_roamer(roamerIndex)->hp);
    SetMonData(mon, MON_DATA_COOL, &ROAMER_roamer(roamerIndex)->cool);
    SetMonData(mon, MON_DATA_BEAUTY, &ROAMER_roamer(roamerIndex)->beauty);
    SetMonData(mon, MON_DATA_CUTE, &ROAMER_roamer(roamerIndex)->cute);
    SetMonData(mon, MON_DATA_SMART, &ROAMER_roamer(roamerIndex)->smart);
    SetMonData(mon, MON_DATA_TOUGH, &ROAMER_roamer(roamerIndex)->tough);
}

bool8 TryStartRoamerEncounter(void)
{
    u32 i;

    for (i = 0; i < ROAMER_COUNT; i++)
    {
        if (IsRoamerAt(i, gSaveBlock1Ptr->location.mapGroup, gSaveBlock1Ptr->location.mapNum) == TRUE && (Random() % 4) == 0)
        {
            CreateRoamerMonInstance(i);
            gEncounteredRoamerIndex = i;
            return TRUE;
        }
    }
    return FALSE;
}

void UpdateRoamerHPStatus(struct Pokemon *mon)
{
    u32 status = GetMonData(mon, MON_DATA_STATUS);

    ROAMER_roamer(gEncounteredRoamerIndex)->hp = GetMonData(mon, MON_DATA_HP);
    ROAMER_roamer(gEncounteredRoamerIndex)->statusA = status;
    ROAMER_roamer(gEncounteredRoamerIndex)->statusB = status >> 8;

    RoamerMoveToOtherLocationSet(gEncounteredRoamerIndex);
}

void SetRoamerInactive(u32 roamerIndex)
{
    ROAMER_roamer(roamerIndex)->active = FALSE;
}

void GetRoamerLocation(u32 roamerIndex, u8 *mapGroup, u8 *mapNum)
{
    *mapGroup = sRoamerLocation_roamer[roamerIndex][MAP_GRP];
    *mapNum = sRoamerLocation_roamer[roamerIndex][MAP_NUM];
}
