// Get the id of the col/row from the selection ID
// e.g. GET_ROW_roulette(SQU_PURPLE_SKITTY_roulette) is ROW_PURPLE_roulette
#define GET_COL_roulette(selectionId) ((selectionId) % (NUM_BOARD_POKES_roulette + 1))
#define GET_ROW_roulette(selectionId) ((selectionId) / (NUM_BOARD_POKES_roulette + 1) * (NUM_BOARD_POKES_roulette + 1))

// Get the col/row index from the selection ID
// e.g. GET_ROW_IDX_roulette(SQU_PURPLE_SKITTY_roulette) is 2 (purple being the 3rd row)
#define GET_COL_IDX_roulette(selectionId) (selectionId - 1)
#define GET_ROW_IDX_roulette(selectionId) (selectionId / 5 - 1)

