static void CB2_Roulette_roulette(void)
{
    RunTasks();
    AnimateSprites();
    BuildOamBuffer();
    if (sRoulette->flashUtil.enabled)
        RouletteFlash_Run(&sRoulette->flashUtil);
}

static void VBlankCB_Roulette_roulette(void)
{
    LoadOam();
    ProcessSpriteCopyRequests();
    TransferPlttBuffer();
    UpdateWheelPosition_roulette();
    SetGpuReg(REG_OFFSET_BG1HOFS, 0x200 - sRoulette->gridX);

    if (sRoulette->shroomishShadowTimer)
        SetGpuReg(REG_OFFSET_BLDALPHA, sRoulette->shroomishShadowAlpha);

    if (sRoulette->updateGridHighlight)
    {
        DmaCopy16(3, &sRoulette->tilemapBuffers[2][0xE0], (void *)BG_SCREEN_ADDR(4) + 0x1C0, 0x340);
        sRoulette->updateGridHighlight = FALSE;
    }
    switch (sRoulette->selectionRectDrawState)
    {
    case SELECT_STATE_DRAW_roulette:
        SetBgAttribute(0, BG_ATTR_CHARBASEINDEX, 0);
        ShowBg(0);
        DmaCopy16(3, &sRoulette->tilemapBuffers[0][0xE0], (void *)BG_SCREEN_ADDR(31) + 0x1C0, 0x340);
        sRoulette->selectionRectDrawState = SELECT_STATE_UPDATE_roulette;
        break;
    case SELECT_STATE_UPDATE_roulette:
        DmaCopy16(3, &sRoulette->tilemapBuffers[0][0xE0], (void *)BG_SCREEN_ADDR(31) + 0x1C0, 0x340);
        break;
    case SELECT_STATE_ERASE_roulette:
        SetBgAttribute(0, BG_ATTR_CHARBASEINDEX, 2);
        ShowBg(0);
        DmaFill16(3, 0, (void *)BG_SCREEN_ADDR(31) + 0x1C0, 0x340);
        sRoulette->selectionRectDrawState = SELECT_STATE_WAIT_roulette;
    case SELECT_STATE_WAIT_roulette:
        break;
    }
}

static void InitRouletteBgAndWindows_roulette(void)
{
    u32 size = 0;

    sRoulette = AllocZeroed(sizeof(*sRoulette));
    ResetBgsAndClearDma3BusyFlags(0);
    InitBgsFromTemplates(1, sBgTemplates_roulette, ARRAY_COUNT(sBgTemplates_roulette));
    SetBgTilemapBuffer(0, sRoulette->tilemapBuffers[0]);
    SetBgTilemapBuffer(1, sRoulette->tilemapBuffers[2]);
    SetBgTilemapBuffer(2, sRoulette->tilemapBuffers[6]);
    InitWindows(sWindowTemplates_roulette);
    InitTextBoxGfxAndPrinters();
    sTextWindowId_roulette = 0;
    sRoulette->gridTilemap = malloc_and_decompress(sGrid_Tilemap_roulette, &size);
}

static void FreeRoulette_roulette(void)
{
    FREE_AND_SET_NULL(sRoulette->gridTilemap);
    FreeAllWindowBuffers();
    UnsetBgTilemapBuffer(0);
    UnsetBgTilemapBuffer(1);
    UnsetBgTilemapBuffer(2);
    ResetBgsAndClearDma3BusyFlags(0);
    memset(sRoulette, 0, sizeof(*sRoulette));
    FREE_AND_SET_NULL(sRoulette);
}

static void InitRouletteTableData_roulette(void)
{
    u8 i;
    u16 bgColors[3] = {RGB(24, 4, 10), RGB(10, 19, 6), RGB(24, 4, 10)}; // 3rd is never used, same as 1st

    sRoulette->tableId = (gSpecialVar_0x8004 & 1);

    if (gSpecialVar_0x8004 & ROULETTE_SPECIAL_RATE)
        sRoulette->isSpecialRate = TRUE;

    sRoulette->wheelSpeed = sRouletteTables_roulette[sRoulette->tableId].wheelSpeed;
    sRoulette->wheelDelay = sRouletteTables_roulette[sRoulette->tableId].wheelDelay;
    sRoulette->minBet = sTableMinBets_roulette[sRoulette->tableId + sRoulette->isSpecialRate * 2];
    sRoulette->unk1 = 1;

    // Left table (with min bet of 1) has red background, other table has green
    if (sRoulette->minBet == 1)
        gPlttBufferUnfaded[BG_PLTT_ID(0)] = gPlttBufferUnfaded[BG_PLTT_ID(5) + 1] = gPlttBufferFaded[BG_PLTT_ID(0)] = gPlttBufferFaded[BG_PLTT_ID(5) + 1] = bgColors[0];
    else
        gPlttBufferUnfaded[BG_PLTT_ID(0)] = gPlttBufferUnfaded[BG_PLTT_ID(5) + 1] = gPlttBufferFaded[BG_PLTT_ID(0)] = gPlttBufferFaded[BG_PLTT_ID(5) + 1] = bgColors[1];

    RouletteFlash_Reset(&sRoulette->flashUtil);

    // Init flash util for flashing the selected colors on the wheel
    // + 1 for the additional entry to flash the outer edges on a win
    for (i = 0; i < NUM_ROULETTE_SLOTS_roulette + 1; i++)
    {
        RouletteFlash_Add(&sRoulette->flashUtil, i, &sFlashData_Colors_roulette[i]);
    }

    for (i = 0; i < PARTY_SIZE; i++)
    {
        switch (GetMonData(&gPlayerParty[i], MON_DATA_SPECIES_OR_EGG))
        {
        case SPECIES_SHROOMISH:
            sRoulette->partySpeciesFlags |= HAS_SHROOMISH_roulette;
            break;
        case SPECIES_TAILLOW:
            sRoulette->partySpeciesFlags |= HAS_TAILLOW_roulette;
            break;
        }
    }
    RtcCalcLocalTime();
}

// Task data for the roulette game tasks, starting with Task_StartPlaying_roulette
#define tMultiplier_roulette      data[2]
#define tSelectionId_roulette     data[4]
#define tWonBet_roulette          data[5]
#define tBallNum_roulette         data[6]
#define tTotalBallNum_roulette    data[8] // Same as tBallNum_roulette but isn't cleared every 6 balls
#define tConsecutiveWins_roulette data[11]
#define tWinningSquare_roulette   data[12]
#define tCoins_roulette           data[13]

static void CB2_LoadRoulette_roulette(void)
{
    u8 taskId;

    switch (gMain.state)
    {
    case 0:
        SetVBlankCallback(NULL);
        ScanlineEffect_Stop();
        SetVBlankHBlankCallbacksToNull();
        ResetVramOamAndBgCntRegs();
        ResetAllBgsCoordinates();
        break;
    case 1:
        InitRouletteBgAndWindows_roulette();
        DeactivateAllTextPrinters();
        SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_EFFECT_NONE |
                                     BLDCNT_TGT2_BG2 |
                                     BLDCNT_TGT2_BD);
        SetGpuReg(REG_OFFSET_BLDALPHA, BLDALPHA_BLEND(10, 6));
        break;
    case 2:
        ResetPaletteFade();
        ResetSpriteData();
        ResetTasks();
        ResetTempTileDataBuffers();
        break;
    case 3:
        LoadPalette(&sWheel_Pal_roulette, BG_PLTT_ID(0), 14 * PLTT_SIZE_4BPP);
        DecompressAndCopyTileDataToVram(1, gRouletteMenu_Gfx, 0, 0, 0);
        DecompressAndCopyTileDataToVram(2, gRouletteWheel_Gfx, 0, 0, 0);
        break;
    case 4:
        if (FreeTempTileDataBuffersIfPossible())
            return;

        InitRouletteTableData_roulette();
        CopyToBgTilemapBuffer(2, sWheel_Tilemap_roulette, 0, 0);
        break;
    case 5:
        LoadOrFreeMiscSpritePalettesAndSheets_roulette(FALSE);
        CreateWheelBallSprites_roulette();
        CreateWheelCenterSprite_roulette();
        CreateInterfaceSprites_roulette();
        CreateGridSprites_roulette();
        CreateGridBallSprites_roulette();
        CreateWheelIconSprites_roulette();
        break;
    case 6:
        AnimateSprites();
        BuildOamBuffer();
        SetCreditDigits_roulette(GetCoins());
        SetBallCounterNumLeft_roulette(BALLS_PER_ROUND_roulette);
        SetMultiplierSprite_roulette(SELECTION_NONE_roulette);
        DrawGridBackground_roulette(SELECTION_NONE_roulette);
        DrawStdWindowFrame(sTextWindowId_roulette, FALSE);
        AddTextPrinterParameterized(sTextWindowId_roulette, FONT_NORMAL, Roulette_Text_ControlsInstruction, 0, 1, TEXT_SKIP_DRAW, NULL);
        CopyWindowToVram(sTextWindowId_roulette, COPYWIN_FULL);
        gSpriteCoordOffsetX = -60;
        gSpriteCoordOffsetY = 0;
        break;
    case 7:
        SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_MODE_0 |
                                      DISPCNT_OBJ_1D_MAP |
                                      DISPCNT_OBJ_ON);
        CopyBgTilemapBufferToVram(1);
        CopyBgTilemapBufferToVram(2);
        ShowBg(0);
        ShowBg(1);
        ShowBg(2);
        break;
    case 8:
        EnableInterrupts(INTR_FLAG_VBLANK);
        SetVBlankCallback(VBlankCB_Roulette_roulette);
        BeginHardwarePaletteFade(0xFF, 0, 16, 0, 1);
        taskId = sRoulette->playTaskId = CreateTask(Task_StartPlaying_roulette, 0);
        gTasks[taskId].tBallNum_roulette = BALLS_PER_ROUND_roulette;
        gTasks[taskId].tCoins_roulette = GetCoins();
        AlertTVThatPlayerPlayedRoulette(GetCoins());
        sRoulette->spinTaskId = CreateTask(Task_SpinWheel_roulette, 1);
        SetMainCallback2(CB2_Roulette_roulette);
        return;
    }
    gMain.state++;
}

static void Task_SpinWheel_roulette(u8 taskId)
{
    s16 sin;
    s16 cos;

    if (sRoulette->wheelDelayTimer++ == sRoulette->wheelDelay)
    {
        sRoulette->wheelDelayTimer = 0;
        if ((sRoulette->wheelAngle -= sRoulette->wheelSpeed) < 0)
            sRoulette->wheelAngle = 360 - sRoulette->wheelSpeed;
    }
    sin = Sin2(sRoulette->wheelAngle);
    cos = Cos2(sRoulette->wheelAngle);
    sin = sin / 16;
    sRoulette->wheelRotation.a = sRoulette->wheelRotation.d = cos / 16;
    sRoulette->wheelRotation.b =  sin;
    sRoulette->wheelRotation.c = -sin;
}

static void Task_StartPlaying_roulette(u8 taskId)
{
    if (UpdatePaletteFade() == 0)
    {
        SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_EFFECT_NONE |
                                     BLDCNT_TGT2_BG2 |
                                     BLDCNT_TGT2_BD);
        SetGpuReg(REG_OFFSET_BLDALPHA, BLDALPHA_BLEND(8, 8));
        gTasks[taskId].tBallNum_roulette = 0;
        ResetBallDataForNewSpin_roulette(taskId);
        ResetHits_roulette();
        HideWheelBalls_roulette();
        DrawGridBackground_roulette(SELECTION_NONE_roulette);
        SetBallCounterNumLeft_roulette(BALLS_PER_ROUND_roulette);
        StartTaskAfterDelayOrInput_roulette(taskId, Task_ContinuePlaying_roulette, NO_DELAY_roulette, A_BUTTON | B_BUTTON);
    }
}

