static void SetCreditDigits_roulette(u16 num)
{
    u8 i;
    u16 d = 1000;
    bool8 printZero = FALSE;
    for (i = 0; i < MAX_COIN_DIGITS; i++)
    {
        u8 digit = num / d;
        gSprites[sRoulette->spriteIds[i + SPR_CREDIT_DIGITS_roulette]].invisible = TRUE;
        if (digit > 0 || printZero || i == MAX_COIN_DIGITS - 1)
        {
            gSprites[sRoulette->spriteIds[i + SPR_CREDIT_DIGITS_roulette]].invisible = FALSE;
            gSprites[sRoulette->spriteIds[i + SPR_CREDIT_DIGITS_roulette]].oam.tileNum =
                gSprites[sRoulette->spriteIds[i + SPR_CREDIT_DIGITS_roulette]].sheetTileStart
                + (*gSprites[sRoulette->spriteIds[i + SPR_CREDIT_DIGITS_roulette]].anims + digit)->type;
            printZero = TRUE;
        }
        num = num % d;
        d = d / 10;
    }
}

// Identical to GetMultiplier_roulette but with different data array
static u8 GetMultiplierAnimId_roulette(u8 selectionId)
{
    u8 animIds[5] = {0, 1, 2, 3, 4};

    if (selectionId > NUM_GRID_SELECTIONS_roulette)
        selectionId = 0;

    switch (sGridSelections_roulette[selectionId].baseMultiplier)
    {
    case NUM_BOARD_COLORS_roulette:
        selectionId = GET_ROW_IDX_roulette(selectionId);
        if (sRoulette->colorHits[selectionId] > 3)
            return 0;
        return animIds[sRoulette->colorHits[selectionId] + 1];
    case NUM_BOARD_POKES_roulette:
        selectionId = GET_COL_IDX_roulette(selectionId);
        if (sRoulette->pokeHits[selectionId] > 2)
            return 0;
        return animIds[sRoulette->pokeHits[selectionId] + 2];
    case NUM_ROULETTE_SLOTS_roulette:
        if (sRoulette->hitFlags & sGridSelections_roulette[selectionId].flag)
            return 0;
        return animIds[4];
    }
    return 0;
}

static void SetMultiplierSprite_roulette(u8 selectionId)
{
    struct Sprite *sprite = &gSprites[sRoulette->spriteIds[SPR_MULTIPLIER_roulette]];
    sprite->animCmdIndex = GetMultiplierAnimId_roulette(selectionId);
    sprite->oam.tileNum = sprite->sheetTileStart + (*sprite->anims + sprite->animCmdIndex)->type;
}

static void SetBallCounterNumLeft_roulette(u8 numBalls)
{
    u8 i;
    u8 t = 0;
    if (sRoulette->minBet == 1)
        t = 2;
    switch (numBalls)
    {
    case 6:
        for (i = 0; i < BALLS_PER_ROUND_roulette / 2; i++)
        {
            gSprites[sRoulette->spriteIds[i + SPR_BALL_COUNTER_roulette]].invisible = FALSE;
            gSprites[sRoulette->spriteIds[i + SPR_BALL_COUNTER_roulette]].oam.tileNum =
                gSprites[sRoulette->spriteIds[i + SPR_BALL_COUNTER_roulette]].sheetTileStart
                + (*gSprites[sRoulette->spriteIds[i + SPR_BALL_COUNTER_roulette]].anims)->type;
        }
        break;
    case 5:
        gSprites[sRoulette->spriteIds[SPR_BALL_COUNTER_3_roulette]].oam.tileNum =
            gSprites[sRoulette->spriteIds[SPR_BALL_COUNTER_3_roulette]].sheetTileStart
            + (*gSprites[sRoulette->spriteIds[SPR_BALL_COUNTER_3_roulette]].anims + t + 1)->type;
        break;
    case 4:
        gSprites[sRoulette->spriteIds[SPR_BALL_COUNTER_3_roulette]].oam.tileNum =
            gSprites[sRoulette->spriteIds[SPR_BALL_COUNTER_3_roulette]].sheetTileStart
            + (*gSprites[sRoulette->spriteIds[SPR_BALL_COUNTER_3_roulette]].anims + t + 2)->type;
        break;
    case 3:
        gSprites[sRoulette->spriteIds[SPR_BALL_COUNTER_2_roulette]].oam.tileNum =
            gSprites[sRoulette->spriteIds[SPR_BALL_COUNTER_2_roulette]].sheetTileStart
            + (*gSprites[sRoulette->spriteIds[SPR_BALL_COUNTER_2_roulette]].anims + t + 1)->type;
        break;
    case 2:
        gSprites[sRoulette->spriteIds[SPR_BALL_COUNTER_2_roulette]].oam.tileNum =
            gSprites[sRoulette->spriteIds[SPR_BALL_COUNTER_2_roulette]].sheetTileStart
            + (*gSprites[sRoulette->spriteIds[SPR_BALL_COUNTER_2_roulette]].anims + t + 2)->type;
        break;
    case 1:
        gSprites[sRoulette->spriteIds[SPR_BALL_COUNTER_1_roulette]].oam.tileNum =
            gSprites[sRoulette->spriteIds[SPR_BALL_COUNTER_1_roulette]].sheetTileStart
            + (*gSprites[sRoulette->spriteIds[SPR_BALL_COUNTER_1_roulette]].anims + t + 1)->type;
        break;
    case 0:
    default:
        for (i = 0; i < BALLS_PER_ROUND_roulette / 2; i++)
        {
            gSprites[sRoulette->spriteIds[i + SPR_BALL_COUNTER_roulette]].oam.tileNum =
                gSprites[sRoulette->spriteIds[i + SPR_BALL_COUNTER_roulette]].sheetTileStart
                + (*gSprites[sRoulette->spriteIds[i + SPR_BALL_COUNTER_roulette]].anims + t + 2)->type;
        }
    }
}

