static void CB2_WipeSave_save_failed_screen(void)
{
    u8 wipeTries = 0;

    sClockInfo_save_failed_screen[CLOCK_RUNNING_save_failed_screen] = TRUE;

    while (gDamagedSaveSectors != 0 && wipeTries < 3)
    {
        if (WipeSectors_save_failed_screen(gDamagedSaveSectors))
        {
            FillWindowPixelBuffer(sWindowIds_save_failed_screen[TEXT_WIN_ID_save_failed_screen], PIXEL_FILL(1));
            SaveFailedScreenTextPrint_save_failed_screen(gText_BackupMemoryDamaged, 1, 0);
            SetMainCallback2(CB2_GameplayCannotBeContinued_save_failed_screen);
            return;
        }

        FillWindowPixelBuffer(sWindowIds_save_failed_screen[TEXT_WIN_ID_save_failed_screen], PIXEL_FILL(1));
        SaveFailedScreenTextPrint_save_failed_screen(gText_CheckCompleted, 1, 0);
        HandleSavingData(sSaveFailedType_save_failed_screen);

        if (gDamagedSaveSectors != 0)
        {
            FillWindowPixelBuffer(sWindowIds_save_failed_screen[TEXT_WIN_ID_save_failed_screen], PIXEL_FILL(1));
            SaveFailedScreenTextPrint_save_failed_screen(gText_SaveFailedCheckingBackup, 1, 0);
        }

        wipeTries++;
    }

    if (wipeTries == 3)
    {
        FillWindowPixelBuffer(sWindowIds_save_failed_screen[TEXT_WIN_ID_save_failed_screen], PIXEL_FILL(1));
        SaveFailedScreenTextPrint_save_failed_screen(gText_BackupMemoryDamaged, 1, 0);
    }
    else
    {
        FillWindowPixelBuffer(sWindowIds_save_failed_screen[TEXT_WIN_ID_save_failed_screen], PIXEL_FILL(1));

        if (gGameContinueCallback == NULL)
            SaveFailedScreenTextPrint_save_failed_screen(gText_SaveCompleteGameCannotContinue, 1, 0);
        else
            SaveFailedScreenTextPrint_save_failed_screen(gText_SaveCompletePressA, 1, 0);
    }

    SetMainCallback2(CB2_FadeAndReturnToTitleScreen_save_failed_screen);
}

static void CB2_GameplayCannotBeContinued_save_failed_screen(void)
{
    sClockInfo_save_failed_screen[CLOCK_RUNNING_save_failed_screen] = FALSE;

    if (JOY_NEW(A_BUTTON))
    {
        FillWindowPixelBuffer(sWindowIds_save_failed_screen[TEXT_WIN_ID_save_failed_screen], PIXEL_FILL(1));
        SaveFailedScreenTextPrint_save_failed_screen(gText_GamePlayCannotBeContinued, 1, 0);
        SetVBlankCallback(VBlankCB_save_failed_screen);
        SetMainCallback2(CB2_FadeAndReturnToTitleScreen_save_failed_screen);
    }
}

static void CB2_FadeAndReturnToTitleScreen_save_failed_screen(void)
{
    sClockInfo_save_failed_screen[CLOCK_RUNNING_save_failed_screen] = FALSE;

    if (JOY_NEW(A_BUTTON))
    {
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
        SetVBlankCallback(VBlankCB_save_failed_screen);
        SetMainCallback2(CB2_ReturnToTitleScreen_save_failed_screen);
    }
}

static void CB2_ReturnToTitleScreen_save_failed_screen(void)
{
    if (!UpdatePaletteFade())
    {
        if (gGameContinueCallback == NULL) // no callback exists, so do a soft reset.
        {
            DoSoftReset();
        }
        else
        {
            SetMainCallback2((MainCallback)gGameContinueCallback);
            gGameContinueCallback = NULL;
        }
    }
}

static void VBlankCB_UpdateClockGraphics_save_failed_screen(void)
{
    u32 n = (gMain.vblankCounter2 >> 3) & 7;

    gMain.oamBuffer[0] = sClockOamData_save_failed_screen;
    gMain.oamBuffer[0].x = 112;
    gMain.oamBuffer[0].y = (CLOCK_WIN_TOP_save_failed_screen + 1) * 8;

    if (sClockInfo_save_failed_screen[CLOCK_RUNNING_save_failed_screen])
    {
        gMain.oamBuffer[0].tileNum = sClockFrames_save_failed_screen[n][0];
        gMain.oamBuffer[0].matrixNum = (sClockFrames_save_failed_screen[n][2] << 4) | (sClockFrames_save_failed_screen[n][1] << 3);
    }
    else
    {
        gMain.oamBuffer[0].tileNum = 1;
    }

    CpuFastCopy(gMain.oamBuffer, (void *)OAM, 4);

    if (sClockInfo_save_failed_screen[DEBUG_TIMER_save_failed_screen])
        sClockInfo_save_failed_screen[DEBUG_TIMER_save_failed_screen]--;
}

static bool8 VerifySectorWipe_save_failed_screen(u16 sector)
{
    u32 *ptr = (u32 *)&gSaveDataBuffer;
    u16 i;

    ReadFlash(sector, 0, (u8 *)ptr, SECTOR_SIZE);

    // 1/4 because ptr is u32
    for (i = 0; i < SECTOR_SIZE / 4; i++, ptr++)
        if (*ptr)
            return TRUE; // Sector has nonzero data, failed

    return FALSE;
}

static bool8 WipeSector_save_failed_screen(u16 sector)
{
    u16 i, j;
    bool8 failed = TRUE;

    // Attempt to wipe sector with an arbitrary attempt limit of 130
    for (i = 0; failed && i < 130; i++)
    {
        for (j = 0; j < SECTOR_SIZE; j++)
            ProgramFlashByte(sector, j, 0);

        failed = VerifySectorWipe_save_failed_screen(sector);
    }

    return failed;
}

static bool8 WipeSectors_save_failed_screen(u32 sectorBits)
{
    u16 i;

    for (i = 0; i < SECTORS_COUNT; i++)
        if ((sectorBits & (1 << i)) && !WipeSector_save_failed_screen(i))
            sectorBits &= ~(1 << i);

    if (sectorBits == 0)
        return FALSE;
    else
        return TRUE;
}

void CB2_FlashNotDetectedScreen(void)
{
static const struct WindowTemplate  textWin_save_failed_screen[] =
    {
        {
            .bg = 0,
            .tilemapLeft = 3,
            .tilemapTop = 2,
            .width = 24,
            .height = 16,
            .paletteNum = 15,
            .baseBlock = 1,
        }
    };

    if (gMain.state)
        return;

    SetGpuReg(REG_OFFSET_DISPCNT, 0);
    SetGpuReg(REG_OFFSET_BLDCNT, 0);
    SetGpuReg(REG_OFFSET_BG0CNT, 0);
    SetGpuReg(REG_OFFSET_BG0HOFS, 0);
    SetGpuReg(REG_OFFSET_BG0VOFS, 0);
    DmaFill16(3, 0, VRAM, VRAM_SIZE);
    DmaFill32(3, 0, OAM, OAM_SIZE);
    DmaFill16(3, 0, PLTT, PLTT_SIZE);
    ResetBgsAndClearDma3BusyFlags(0);
    InitBgsFromTemplates(0, sBgTemplates_save_failed_screen, ARRAY_COUNT(sBgTemplates_save_failed_screen));
    LoadBgTiles(0, gTextWindowFrame1_Gfx, 0x120, 0x214);
    DeactivateAllTextPrinters();
    ResetTasks();
    ResetPaletteFade();
    LoadPalette(gTextWindowFrame1_Pal, 0xE0, 0x20);
    LoadPalette(gStandardMenuPalette, 0xF0, 0x20);
    InitWindows(textWin_save_failed_screen);
    DrawStdFrameWithCustomTileAndPalette(0, TRUE, 0x214, 0xE);
static const u8  saveFailedMessage_save_failed_screen[] =_(
        "{COLOR RED}ERROR! {COLOR DARK_GRAY}Flash memory not detected!\n"
        "\n"
        "If playing on an emulator, set your\n"
        "save type setting to\n"
        "Flash 1Mb/128K and reload the ROM.\n"
        "\n"
        "If playing on hardware, your cart\n"
        "does not have a working flash chip.");
    SaveFailedScreenTextPrint_save_failed_screen(saveFailedMessage_save_failed_screen, 1, 0);
    TransferPlttBuffer();
    *(u16*)PLTT = RGB(17, 18, 31);
    ShowBg(0);
    gMain.state++;
}
