static void MultichoiceDynamicEventShowItem_OnInit_script_menu(struct DynamicListMenuEventArgs *eventArgs)
{
    struct WindowTemplate *template = &gWindows[eventArgs->windowId].window;
    u32 baseBlock = template->baseBlock + template->width * template->height;
    struct WindowTemplate auxTemplate = CreateWindowTemplate(0, template->tilemapLeft + template->width + 2, template->tilemapTop, 4, 4, 15, baseBlock);
    u32 auxWindowId = AddWindow(&auxTemplate);
    SetStandardWindowBorderStyle(auxWindowId, FALSE);
    FillWindowPixelBuffer(auxWindowId, 0x11);
    CopyWindowToVram(auxWindowId, COPYWIN_FULL);
    sAuxWindowId_script_menu = auxWindowId;
    sItemSpriteId_script_menu = MAX_SPRITES;
}

static void MultichoiceDynamicEventShowItem_OnSelectionChanged_script_menu(struct DynamicListMenuEventArgs *eventArgs)
{
    struct WindowTemplate *template = &gWindows[eventArgs->windowId].window;
    u32 x = template->tilemapLeft * 8 + template->width * 8 + 36;
    u32 y = template->tilemapTop * 8 + 20;

    if (sItemSpriteId_script_menu != MAX_SPRITES)
    {
        FreeSpriteTilesByTag(TAG_CB_ITEM_ICON_script_menu);
        FreeSpritePaletteByTag(TAG_CB_ITEM_ICON_script_menu);
        DestroySprite(&gSprites[sItemSpriteId_script_menu]);
    }

    sItemSpriteId_script_menu = AddItemIconSprite(TAG_CB_ITEM_ICON_script_menu, TAG_CB_ITEM_ICON_script_menu, eventArgs->selectedItem);
    gSprites[sItemSpriteId_script_menu].oam.priority = 0;
    gSprites[sItemSpriteId_script_menu].x = x;
    gSprites[sItemSpriteId_script_menu].y = y;
}

static void MultichoiceDynamicEventShowItem_OnDestroy_script_menu(struct DynamicListMenuEventArgs *eventArgs)
{
    ClearStdWindowAndFrame(sAuxWindowId_script_menu, TRUE);
    RemoveWindow(sAuxWindowId_script_menu);

    if (sItemSpriteId_script_menu != MAX_SPRITES)
    {
        FreeSpriteTilesByTag(TAG_CB_ITEM_ICON_script_menu);
        FreeSpritePaletteByTag(TAG_CB_ITEM_ICON_script_menu);
        DestroySprite(&gSprites[sItemSpriteId_script_menu]);
    }
}

