static void Task_ShowSecretBaseRegistryMenu_secret_base(u8 taskId)
{
    u16 *data = (u16*) gTasks[taskId].data;
    LockPlayerFieldControls();
    tNumBases_secret_base = GetNumRegisteredSecretBases_secret_base();
    if (tNumBases_secret_base != 0)
    {
        tSelectedRow_secret_base = 0;
        tScrollOffset_secret_base = 0;
        ClearDialogWindowAndFrame(0, FALSE);
        sRegistryMenu_secret_base = AllocZeroed(sizeof(*sRegistryMenu_secret_base));
        tMainWindowId_secret_base = AddWindow(&sRegistryWindowTemplates_secret_base[0]);
        BuildRegistryMenuItems_secret_base(taskId);
        FinalizeRegistryMenu_secret_base(taskId);
        gTasks[taskId].func = HandleRegistryMenuInput_secret_base;
    }
    else
    {
        DisplayItemMessageOnField(taskId, gText_NoRegistry, GoToSecretBasePCRegisterMenu_secret_base);
    }
}

static void BuildRegistryMenuItems_secret_base(u8 taskId)
{
    s16 *data;
    u8 i;
    u8 count;

    data = gTasks[taskId].data;
    count = 0;
    for (i = 1; i < SECRET_BASES_COUNT; i++)
    {
        if (IsSecretBaseRegistered_secret_base(i))
        {
            GetSecretBaseName(sRegistryMenu_secret_base->names[count], i);
            sRegistryMenu_secret_base->items[count].name = sRegistryMenu_secret_base->names[count];
            sRegistryMenu_secret_base->items[count].id = i;
            count++;
        }
    }

    sRegistryMenu_secret_base->items[count].name = gText_Cancel;
    sRegistryMenu_secret_base->items[count].id = LIST_CANCEL;
    tNumBases_secret_base = count + 1;
    if (tNumBases_secret_base < 8)
        tMaxShownItems_secret_base = tNumBases_secret_base;
    else
        tMaxShownItems_secret_base = 8;

    gMultiuseListMenuTemplate = sRegistryListMenuTemplate_secret_base;
    gMultiuseListMenuTemplate.windowId = tMainWindowId_secret_base;
    gMultiuseListMenuTemplate.totalItems = tNumBases_secret_base;
    gMultiuseListMenuTemplate.items = sRegistryMenu_secret_base->items;
    gMultiuseListMenuTemplate.maxShowed = tMaxShownItems_secret_base;
}

