    tArrowTaskId_secret_base = AddScrollIndicatorArrowPairParameterized(SCROLL_ARROW_UP, 188, 12, 148, tNumBases_secret_base - tMaxShownItems_secret_base, TAG_SCROLL_ARROW_secret_base, TAG_SCROLL_ARROW_secret_base, &tScrollOffset_secret_base);
