static void HandleRegistryMenuInput_secret_base(u8 taskId)
{
    u16 *data = (u16*) gTasks[taskId].data;
    s32 input = ListMenu_ProcessInput(tListTaskId_secret_base);
    ListMenuGetScrollAndRow(tListTaskId_secret_base, &tScrollOffset_secret_base, &tSelectedRow_secret_base);

    switch (input)
    {
    case LIST_NOTHING_CHOSEN:
        break;
    case LIST_CANCEL:
        PlaySE(SE_SELECT);
        DestroyListMenuTask(tListTaskId_secret_base, NULL, NULL);
        RemoveScrollIndicatorArrowPair(tArrowTaskId_secret_base);
        ClearStdWindowAndFrame(tMainWindowId_secret_base, FALSE);
        ClearWindowTilemap(tMainWindowId_secret_base);
        RemoveWindow(tMainWindowId_secret_base);
        ScheduleBgCopyTilemapToVram(0);
        Free(sRegistryMenu_secret_base);
        GoToSecretBasePCRegisterMenu_secret_base(taskId);
        break;
    default:
        PlaySE(SE_SELECT);
        tSelectedBaseId_secret_base = input;
        ShowRegistryMenuActions_secret_base(taskId);
        break;
    }
}

