{
    struct WindowTemplate template;
    u16 *data = (u16*) gTasks[taskId].data;
    RemoveScrollIndicatorArrowPair(tArrowTaskId_secret_base);
    template = sRegistryWindowTemplates_secret_base[1];
    template.width = GetMaxWidthInMenuTable(sRegistryMenuActions_secret_base, 2);
    tActionWindowId_secret_base = AddWindow(&template);
    SetStandardWindowBorderStyle(tActionWindowId_secret_base, FALSE);
    PrintMenuTable(tActionWindowId_secret_base, ARRAY_COUNT(sRegistryMenuActions_secret_base), sRegistryMenuActions_secret_base);
    InitMenuInUpperLeftCornerNormal(tActionWindowId_secret_base, ARRAY_COUNT(sRegistryMenuActions_secret_base), 0);
    ScheduleBgCopyTilemapToVram(0);
    gTasks[taskId].func = HandleRegistryMenuActionsInput_secret_base;
}

static void HandleRegistryMenuActionsInput_secret_base(u8 taskId)
{
    s8 input = Menu_ProcessInputNoWrap();
    switch (input)
    {
    case MENU_B_PRESSED:
        PlaySE(SE_SELECT);
        ReturnToMainRegistryMenu_secret_base(taskId);
        break;
    case MENU_NOTHING_CHOSEN:
        break;
    default:
        PlaySE(SE_SELECT);
        sRegistryMenuActions_secret_base[input].func.void_u8(taskId);
        break;
    }
}

