static u8 CreateShopMenu_shop(u8 martType)
{
    int numMenuItems;

    LockPlayerFieldControls();
    sMartInfo_shop.martType = martType;

    if (martType == MART_TYPE_NORMAL_shop)
    {
        struct WindowTemplate winTemplate = sShopMenuWindowTemplates_shop[WIN_BUY_SELL_QUIT_shop];
        winTemplate.width = GetMaxWidthInMenuTable(sShopMenuActions_BuySellQuit_shop, ARRAY_COUNT(sShopMenuActions_BuySellQuit_shop));
        sMartInfo_shop.windowId = AddWindow(&winTemplate);
        sMartInfo_shop.menuActions = sShopMenuActions_BuySellQuit_shop;
        numMenuItems = ARRAY_COUNT(sShopMenuActions_BuySellQuit_shop);
    }
    else
    {
        struct WindowTemplate winTemplate = sShopMenuWindowTemplates_shop[WIN_BUY_QUIT_shop];
        winTemplate.width = GetMaxWidthInMenuTable(sShopMenuActions_BuyQuit_shop, ARRAY_COUNT(sShopMenuActions_BuyQuit_shop));
        sMartInfo_shop.windowId = AddWindow(&winTemplate);
        sMartInfo_shop.menuActions = sShopMenuActions_BuyQuit_shop;
        numMenuItems = ARRAY_COUNT(sShopMenuActions_BuyQuit_shop);
    }

    SetStandardWindowBorderStyle(sMartInfo_shop.windowId, FALSE);
    PrintMenuTable(sMartInfo_shop.windowId, numMenuItems, sMartInfo_shop.menuActions);
    InitMenuInUpperLeftCornerNormal(sMartInfo_shop.windowId, numMenuItems, 0);
    PutWindowTilemap(sMartInfo_shop.windowId);
    CopyWindowToVram(sMartInfo_shop.windowId, COPYWIN_MAP);

    return CreateTask(Task_ShopMenu_shop, 8);
}

static void SetShopMenuCallback_shop(void (* callback)(void))
{
    sMartInfo_shop.callback = callback;
}

static void SetShopItemsForSale_shop(const u16 *items)
{
    u16 i = 0;

    sMartInfo_shop.itemList = items;
    sMartInfo_shop.itemCount = 0;

    // Read items until ITEM_NONE / DECOR_NONE is reached
    while (sMartInfo_shop.itemList[i])
    {
        sMartInfo_shop.itemCount++;
        i++;
    }
}

static void Task_ShopMenu_shop(u8 taskId)
{
    s8 inputCode = Menu_ProcessInputNoWrap();
    switch (inputCode)
    {
    case MENU_NOTHING_CHOSEN:
        break;
    case MENU_B_PRESSED:
        PlaySE(SE_SELECT);
        Task_HandleShopMenuQuit_shop(taskId);
        break;
    default:
        sMartInfo_shop.menuActions[inputCode].func.void_u8(taskId);
        break;
    }
}

#define tItemCount_shop  data[1]
#define tItemId_shop     data[5]
#define tListTaskId_shop data[7]
#define tCallbackHi_shop data[8]
#define tCallbackLo_shop data[9]

static void Task_HandleShopMenuBuy_shop(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    tCallbackHi_shop = (u32)CB2_InitBuyMenu_shop >> 16;
    tCallbackLo_shop = (u32)CB2_InitBuyMenu_shop;
    gTasks[taskId].func = Task_GoToBuyOrSellMenu_shop;
    FadeScreen(FADE_TO_BLACK, 0);
}

static void Task_HandleShopMenuSell_shop(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    tCallbackHi_shop = (u32)CB2_GoToSellMenu >> 16;
    tCallbackLo_shop = (u32)CB2_GoToSellMenu;
    gTasks[taskId].func = Task_GoToBuyOrSellMenu_shop;
    FadeScreen(FADE_TO_BLACK, 0);
}

void CB2_ExitSellMenu(void)
{
    gFieldCallback = MapPostLoadHook_ReturnToShopMenu_shop;
    SetMainCallback2(CB2_ReturnToField);
}

static void Task_HandleShopMenuQuit_shop(u8 taskId)
{
    ClearStdWindowAndFrameToTransparent(sMartInfo_shop.windowId, 2); // Incorrect use, making it not copy it to vram.
    RemoveWindow(sMartInfo_shop.windowId);
    TryPutSmartShopperOnAir();
    UnlockPlayerFieldControls();
    DestroyTask(taskId);

    if (sMartInfo_shop.callback)
        sMartInfo_shop.callback();
}

static void Task_GoToBuyOrSellMenu_shop(u8 taskId)
{
    s16 *data = gTasks[taskId].data;
    if (!gPaletteFade.active)
    {
        DestroyTask(taskId);
        SetMainCallback2((void *)((u16)tCallbackHi_shop << 16 | (u16)tCallbackLo_shop));
    }
}

static void MapPostLoadHook_ReturnToShopMenu_shop(void)
{
    FadeInFromBlack();
    CreateTask(Task_ReturnToShopMenu_shop, 8);
}

static void Task_ReturnToShopMenu_shop(u8 taskId)
{
    if (IsWeatherNotFadingIn() == TRUE)
    {
        if (sMartInfo_shop.martType == MART_TYPE_DECOR2_shop)
            DisplayItemMessageOnField(taskId, gText_CanIHelpWithAnythingElse, ShowShopMenuAfterExitingBuyOrSellMenu_shop);
        else
            DisplayItemMessageOnField(taskId, gText_AnythingElseICanHelp, ShowShopMenuAfterExitingBuyOrSellMenu_shop);
    }
}

static void ShowShopMenuAfterExitingBuyOrSellMenu_shop(u8 taskId)
{
    CreateShopMenu_shop(sMartInfo_shop.martType);
    DestroyTask(taskId);
}

static void CB2_BuyMenu_shop(void)
{
    RunTasks();
    AnimateSprites();
    BuildOamBuffer();
    DoScheduledBgTilemapCopiesToVram();
    UpdatePaletteFade();
}

static void VBlankCB_BuyMenu_shop(void)
{
    LoadOam();
    ProcessSpriteCopyRequests();
    TransferPlttBuffer();
}

static void CB2_InitBuyMenu_shop(void)
{
    u8 taskId;

    switch (gMain.state)
    {
    case 0:
        SetVBlankHBlankCallbacksToNull();
        CpuFastFill(0, (void *)OAM, OAM_SIZE);
        ScanlineEffect_Stop();
        ResetTempTileDataBuffers();
        FreeAllSpritePalettes();
        ResetPaletteFade();
        ResetSpriteData();
        ResetTasks();
        ClearScheduledBgCopiesToVram();
        sShopData_shop = AllocZeroed(sizeof(struct ShopData));
        sShopData_shop->scrollIndicatorsTaskId = TASK_NONE;
        sShopData_shop->itemSpriteIds[0] = SPRITE_NONE;
        sShopData_shop->itemSpriteIds[1] = SPRITE_NONE;
        BuyMenuBuildListMenuTemplate_shop();
        BuyMenuInitBgs_shop();
        FillBgTilemapBufferRect_Palette0(0, 0, 0, 0, 0x20, 0x20);
        FillBgTilemapBufferRect_Palette0(1, 0, 0, 0, 0x20, 0x20);
        FillBgTilemapBufferRect_Palette0(2, 0, 0, 0, 0x20, 0x20);
        FillBgTilemapBufferRect_Palette0(3, 0, 0, 0, 0x20, 0x20);
        BuyMenuInitWindows_shop();
        BuyMenuDecompressBgGraphics_shop();
        gMain.state++;
        break;
    case 1:
        if (!FreeTempTileDataBuffersIfPossible())
            gMain.state++;
        break;
    default:
        BuyMenuDrawGraphics_shop();
        BuyMenuAddScrollIndicatorArrows_shop();
        taskId = CreateTask(Task_BuyMenu_shop, 8);
        gTasks[taskId].tListTaskId_shop = ListMenuInit(&gMultiuseListMenuTemplate, 0, 0);
        BlendPalettes(PALETTES_ALL, 16, RGB_BLACK);
        BeginNormalPaletteFade(PALETTES_ALL, 0, 16, 0, RGB_BLACK);
        SetVBlankCallback(VBlankCB_BuyMenu_shop);
        SetMainCallback2(CB2_BuyMenu_shop);
        break;
    }
}

static void BuyMenuFreeMemory_shop(void)
{
    Free(sShopData_shop);
    Free(sListMenuItems_shop);
    Free(sItemNames);
    FreeAllWindowBuffers();
}

static void BuyMenuBuildListMenuTemplate_shop(void)
{
    u16 i;

    sListMenuItems_shop = Alloc((sMartInfo_shop.itemCount + 1) * sizeof(*sListMenuItems_shop));
    sItemNames = Alloc((sMartInfo_shop.itemCount + 1) * sizeof(*sItemNames));
    for (i = 0; i < sMartInfo_shop.itemCount; i++)
        BuyMenuSetListEntry_shop(&sListMenuItems_shop[i], sMartInfo_shop.itemList[i], sItemNames[i]);

    StringCopy(sItemNames[i], gText_Cancel2);
    sListMenuItems_shop[i].name = sItemNames[i];
    sListMenuItems_shop[i].id = LIST_CANCEL;

    gMultiuseListMenuTemplate = sShopBuyMenuListTemplate_shop;
    gMultiuseListMenuTemplate.items = sListMenuItems_shop;
    gMultiuseListMenuTemplate.totalItems = sMartInfo_shop.itemCount + 1;
    if (gMultiuseListMenuTemplate.totalItems > MAX_ITEMS_SHOWN_shop)
        gMultiuseListMenuTemplate.maxShowed = MAX_ITEMS_SHOWN_shop;
    else
        gMultiuseListMenuTemplate.maxShowed = gMultiuseListMenuTemplate.totalItems;

    sShopData_shop->itemsShowed = gMultiuseListMenuTemplate.maxShowed;
}

static void BuyMenuSetListEntry_shop(struct ListMenuItem *menuItem, u16 item, u8 *name)
{
    if (sMartInfo_shop.martType == MART_TYPE_NORMAL_shop)
        CopyItemName(item, name);
    else
        StringCopy(name, gDecorations[item].name);

    menuItem->name = name;
    menuItem->id = item;
}

static void BuyMenuPrintItemDescriptionAndShowItemIcon_shop(s32 item, bool8 onInit, struct ListMenu *list)
{
    const u8 *description;
    if (onInit != TRUE)
        PlaySE(SE_SELECT);

    if (item != LIST_CANCEL)
        BuyMenuAddItemIcon_shop(item, sShopData_shop->iconSlot);
    else
        BuyMenuAddItemIcon_shop(ITEM_LIST_END, sShopData_shop->iconSlot);

    BuyMenuRemoveItemIcon_shop(item, sShopData_shop->iconSlot ^ 1);
    sShopData_shop->iconSlot ^= 1;
    if (item != LIST_CANCEL)
    {
        if (sMartInfo_shop.martType == MART_TYPE_NORMAL_shop)
            description = ItemId_GetDescription(item);
        else
            description = gDecorations[item].description;
    }
    else
    {
        description = gText_QuitShopping;
    }

    FillWindowPixelBuffer(WIN_ITEM_DESCRIPTION_shop, PIXEL_FILL(0));
    BuyMenuPrint_shop(WIN_ITEM_DESCRIPTION_shop, description, 3, 1, 0, COLORID_NORMAL);
}

static void BuyMenuPrintPriceInList_shop(u8 windowId, u32 itemId, u8 y)
{
    u8 x;

    if (itemId != LIST_CANCEL)
    {
        if (sMartInfo_shop.martType == MART_TYPE_NORMAL_shop)
        {
            ConvertIntToDecimalStringN(
                gStringVar1,
                ItemId_GetPrice(itemId) >> IsPokeNewsActive(POKENEWS_SLATEPORT),
                STR_CONV_MODE_LEFT_ALIGN,
                6);
        }
        else
        {
            ConvertIntToDecimalStringN(
                gStringVar1,
                gDecorations[itemId].price,
                STR_CONV_MODE_LEFT_ALIGN,
                6);
        }

        if (ItemId_GetImportance(itemId) && (CheckBagHasItem(itemId, 1) || CheckPCHasItem(itemId, 1)))
            StringCopy(gStringVar4, gText_SoldOut);
        else
            StringExpandPlaceholders(gStringVar4, gText_PokedollarVar1);
        x = GetStringRightAlignXOffset(FONT_NARROW, gStringVar4, 120);
        AddTextPrinterParameterized4(windowId, FONT_NARROW, x, y, 0, 0, sShopBuyMenuTextColors_shop[COLORID_ITEM_LIST], TEXT_SKIP_DRAW, gStringVar4);
    }
}

static void BuyMenuAddScrollIndicatorArrows_shop(void)
{
    if (sShopData_shop->scrollIndicatorsTaskId == TASK_NONE && sMartInfo_shop.itemCount + 1 > MAX_ITEMS_SHOWN_shop)
    {
        sShopData_shop->scrollIndicatorsTaskId = AddScrollIndicatorArrowPairParameterized(
            SCROLL_ARROW_UP,
            172,
            12,
            148,
            sMartInfo_shop.itemCount - (MAX_ITEMS_SHOWN_shop - 1),
            TAG_SCROLL_ARROW_shop,
            TAG_SCROLL_ARROW_shop,
            &sShopData_shop->scrollOffset);
    }
}

static void BuyMenuRemoveScrollIndicatorArrows_shop(void)
{
    if (sShopData_shop->scrollIndicatorsTaskId != TASK_NONE)
    {
        RemoveScrollIndicatorArrowPair(sShopData_shop->scrollIndicatorsTaskId);
        sShopData_shop->scrollIndicatorsTaskId = TASK_NONE;
    }
}

static void BuyMenuPrintCursor_shop(u8 scrollIndicatorsTaskId, u8 colorSet)
{
    u8 y = ListMenuGetYCoordForPrintingArrowCursor(scrollIndicatorsTaskId);
    BuyMenuPrint_shop(WIN_ITEM_LIST_shop, gText_SelectorArrow2, 0, y, 0, colorSet);
}

static void BuyMenuAddItemIcon_shop(u16 item, u8 iconSlot)
{
    u8 spriteId;
    u8 *spriteIdPtr = &sShopData_shop->itemSpriteIds[iconSlot];
    if (*spriteIdPtr != SPRITE_NONE)
        return;

    if (sMartInfo_shop.martType == MART_TYPE_NORMAL_shop || item == ITEM_LIST_END)
    {
        spriteId = AddItemIconSprite(iconSlot + TAG_ITEM_ICON_BASE_shop, iconSlot + TAG_ITEM_ICON_BASE_shop, item);
        if (spriteId != MAX_SPRITES)
        {
            *spriteIdPtr = spriteId;
            gSprites[spriteId].x2 = 24;
            gSprites[spriteId].y2 = 88;
        }
    }
    else
    {
        spriteId = AddDecorationIconObject(item, 20, 84, 1, iconSlot + TAG_ITEM_ICON_BASE_shop, iconSlot + TAG_ITEM_ICON_BASE_shop);
        if (spriteId != MAX_SPRITES)
            *spriteIdPtr = spriteId;
    }
}

static void BuyMenuRemoveItemIcon_shop(u16 item, u8 iconSlot)
{
    u8 *spriteIdPtr = &sShopData_shop->itemSpriteIds[iconSlot];
    if (*spriteIdPtr == SPRITE_NONE)
        return;

    FreeSpriteTilesByTag(iconSlot + TAG_ITEM_ICON_BASE_shop);
    FreeSpritePaletteByTag(iconSlot + TAG_ITEM_ICON_BASE_shop);
    DestroySprite(&gSprites[*spriteIdPtr]);
    *spriteIdPtr = SPRITE_NONE;
}

static void BuyMenuInitBgs_shop(void)
{
    ResetBgsAndClearDma3BusyFlags(0);
    InitBgsFromTemplates(0, sShopBuyMenuBgTemplates_shop, ARRAY_COUNT(sShopBuyMenuBgTemplates_shop));
    SetBgTilemapBuffer(1, sShopData_shop->tilemapBuffers[1]);
    SetBgTilemapBuffer(2, sShopData_shop->tilemapBuffers[3]);
    SetBgTilemapBuffer(3, sShopData_shop->tilemapBuffers[2]);
    SetGpuReg(REG_OFFSET_BG0HOFS, 0);
    SetGpuReg(REG_OFFSET_BG0VOFS, 0);
    SetGpuReg(REG_OFFSET_BG1HOFS, 0);
    SetGpuReg(REG_OFFSET_BG1VOFS, 0);
    SetGpuReg(REG_OFFSET_BG2HOFS, 0);
    SetGpuReg(REG_OFFSET_BG2VOFS, 0);
    SetGpuReg(REG_OFFSET_BG3HOFS, 0);
    SetGpuReg(REG_OFFSET_BG3VOFS, 0);
    SetGpuReg(REG_OFFSET_BLDCNT, 0);
    SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_MODE_0 | DISPCNT_OBJ_ON | DISPCNT_OBJ_1D_MAP);
    ShowBg(0);
    ShowBg(1);
    ShowBg(2);
    ShowBg(3);
}

static void BuyMenuDecompressBgGraphics_shop(void)
{
    DecompressAndCopyTileDataToVram(1, gShopMenu_Gfx, 0x3A0, 0x3E3, 0);
    LZDecompressWram(gShopMenu_Tilemap, sShopData_shop->tilemapBuffers[0]);
    LoadCompressedPalette(gShopMenu_Pal, BG_PLTT_ID(12), PLTT_SIZE_4BPP);
}

static void BuyMenuInitWindows_shop(void)
{
    InitWindows(sShopBuyMenuWindowTemplates_shop);
    DeactivateAllTextPrinters();
    LoadUserWindowBorderGfx(WIN_MONEY_shop, 1, BG_PLTT_ID(13));
    LoadMessageBoxGfx(WIN_MONEY_shop, 0xA, BG_PLTT_ID(14));
    PutWindowTilemap(WIN_MONEY_shop);
    PutWindowTilemap(WIN_ITEM_LIST_shop);
    PutWindowTilemap(WIN_ITEM_DESCRIPTION_shop);
}

static void BuyMenuPrint_shop(u8 windowId, const u8 *text, u8 x, u8 y, s8 speed, u8 colorSet)
{
    AddTextPrinterParameterized4(windowId, FONT_NORMAL, x, y, 0, 0, sShopBuyMenuTextColors_shop[colorSet], speed, text);
}

static void BuyMenuDisplayMessage_shop(u8 taskId, const u8 *text, TaskFunc callback)
{
    DisplayMessageAndContinueTask(taskId, WIN_MESSAGE_shop, 10, 14, FONT_NORMAL, GetPlayerTextSpeedDelay(), text, callback);
    ScheduleBgCopyTilemapToVram(0);
}

static void BuyMenuDrawGraphics_shop(void)
{
    BuyMenuDrawMapGraphics_shop();
    BuyMenuCopyMenuBgToBg1TilemapBuffer_shop();
    AddMoneyLabelObject(19, 11);
    PrintMoneyAmountInMoneyBoxWithBorder(WIN_MONEY_shop, 1, 13, GetMoney(&gSaveBlock1Ptr->money));
    ScheduleBgCopyTilemapToVram(0);
    ScheduleBgCopyTilemapToVram(1);
    ScheduleBgCopyTilemapToVram(2);
    ScheduleBgCopyTilemapToVram(3);
}

static void BuyMenuDrawMapGraphics_shop(void)
{
    BuyMenuCollectObjectEventData_shop();
    BuyMenuDrawObjectEvents_shop();
    BuyMenuDrawMapBg_shop();
}

static void BuyMenuDrawMapBg_shop(void)
{
    s16 i, j;
    s16 x, y;
    const struct MapLayout *mapLayout;
    u16 metatile;
    u8 metatileLayerType;

    mapLayout = gMapHeader.mapLayout;
    GetXYCoordsOneStepInFrontOfPlayer(&x, &y);
    x -= 4;
    y -= 4;

    for (j = 0; j < 10; j++)
    {
        for (i = 0; i < 15; i++)
        {
            metatile = MapGridGetMetatileIdAt(x + i, y + j);
            if (BuyMenuCheckForOverlapWithMenuBg_shop(i, j) == TRUE)
                metatileLayerType = MapGridGetMetatileLayerTypeAt(x + i, y + j);
            else
                metatileLayerType = METATILE_LAYER_TYPE_COVERED;

            if (metatile < NUM_METATILES_IN_PRIMARY)
                BuyMenuDrawMapMetatile_shop(i, j, mapLayout->primaryTileset->metatiles + metatile * NUM_TILES_PER_METATILE, metatileLayerType);
            else
                BuyMenuDrawMapMetatile_shop(i, j, mapLayout->secondaryTileset->metatiles + ((metatile - NUM_METATILES_IN_PRIMARY) * NUM_TILES_PER_METATILE), metatileLayerType);
        }
    }
}

static void BuyMenuDrawMapMetatile_shop(s16 x, s16 y, const u16 *src, u8 metatileLayerType)
{
    u16 offset1 = x * 2;
    u16 offset2 = y * 64;

    switch (metatileLayerType)
    {
    case METATILE_LAYER_TYPE_NORMAL:
        BuyMenuDrawMapMetatileLayer_shop(sShopData_shop->tilemapBuffers[3], offset1, offset2, src);
        BuyMenuDrawMapMetatileLayer_shop(sShopData_shop->tilemapBuffers[1], offset1, offset2, src + 4);
        break;
    case METATILE_LAYER_TYPE_COVERED:
        BuyMenuDrawMapMetatileLayer_shop(sShopData_shop->tilemapBuffers[2], offset1, offset2, src);
        BuyMenuDrawMapMetatileLayer_shop(sShopData_shop->tilemapBuffers[3], offset1, offset2, src + 4);
        break;
    case METATILE_LAYER_TYPE_SPLIT:
        BuyMenuDrawMapMetatileLayer_shop(sShopData_shop->tilemapBuffers[2], offset1, offset2, src);
        BuyMenuDrawMapMetatileLayer_shop(sShopData_shop->tilemapBuffers[1], offset1, offset2, src + 4);
        break;
    }
}

static void BuyMenuDrawMapMetatileLayer_shop(u16 *dest, s16 offset1, s16 offset2, const u16 *src)
{
    // This function draws a whole 2x2 metatile.
    dest[offset1 + offset2] = src[0]; // top left
    dest[offset1 + offset2 + 1] = src[1]; // top right
    dest[offset1 + offset2 + 32] = src[2]; // bottom left
    dest[offset1 + offset2 + 33] = src[3]; // bottom right
}

static void BuyMenuCollectObjectEventData_shop(void)
{
    s16 facingX;
    s16 facingY;
    u8 y;
    u8 x;
    u8 numObjects = 0;

    GetXYCoordsOneStepInFrontOfPlayer(&facingX, &facingY);

    for (y = 0; y < OBJECT_EVENTS_COUNT; y++)
        sShopData_shop->viewportObjects[y][OBJ_EVENT_ID_shop] = OBJECT_EVENTS_COUNT;

    for (y = 0; y < 5; y++)
    {
        for (x = 0; x < 7; x++)
        {
            u8 objEventId = GetObjectEventIdByXY(facingX - 4 + x, facingY - 2 + y);

            // skip if invalid or an overworld pokemon that is not following the player
            if (objEventId != OBJECT_EVENTS_COUNT && !(gObjectEvents[objEventId].active && gObjectEvents[objEventId].graphicsId >= OBJ_EVENT_GFX_MON_BASE && gObjectEvents[objEventId].localId != OBJ_EVENT_ID_FOLLOWER))
            {
                sShopData_shop->viewportObjects[numObjects][OBJ_EVENT_ID_shop] = objEventId;
                sShopData_shop->viewportObjects[numObjects][X_COORD_shop] = x;
                sShopData_shop->viewportObjects[numObjects][Y_COORD_shop] = y;
                sShopData_shop->viewportObjects[numObjects][LAYER_TYPE_shop] = MapGridGetMetatileLayerTypeAt(facingX - 4 + x, facingY - 2 + y);

                switch (gObjectEvents[objEventId].facingDirection)
                {
                case DIR_SOUTH:
                    sShopData_shop->viewportObjects[numObjects][ANIM_NUM_shop] = ANIM_STD_FACE_SOUTH;
                    break;
                case DIR_NORTH:
                    sShopData_shop->viewportObjects[numObjects][ANIM_NUM_shop] = ANIM_STD_FACE_NORTH;
                    break;
                case DIR_WEST:
                    sShopData_shop->viewportObjects[numObjects][ANIM_NUM_shop] = ANIM_STD_FACE_WEST;
                    break;
                case DIR_EAST:
                default:
                    sShopData_shop->viewportObjects[numObjects][ANIM_NUM_shop] = ANIM_STD_FACE_EAST;
                    break;
                }
                numObjects++;
            }
        }
    }
}

static void BuyMenuDrawObjectEvents_shop(void)
{
    u8 i;
    u8 spriteId;
    const struct ObjectEventGraphicsInfo *graphicsInfo;
    u8 weatherTemp = gWeatherPtr->palProcessingState;

    // This function runs during fadeout, so the weather palette processing state must be temporarily changed,
    // so that time-blending will work properly
    if (weatherTemp == WEATHER_PAL_STATE_SCREEN_FADING_OUT)
        gWeatherPtr->palProcessingState = WEATHER_PAL_STATE_IDLE;
    for (i = 0; i < OBJECT_EVENTS_COUNT; i++)
    {
        if (sShopData_shop->viewportObjects[i][OBJ_EVENT_ID_shop] == OBJECT_EVENTS_COUNT)
            continue;

        graphicsInfo = GetObjectEventGraphicsInfo(gObjectEvents[sShopData_shop->viewportObjects[i][OBJ_EVENT_ID_shop]].graphicsId);

        spriteId = CreateObjectGraphicsSprite(
            gObjectEvents[sShopData_shop->viewportObjects[i][OBJ_EVENT_ID_shop]].graphicsId,
            SpriteCallbackDummy,
            (u16)sShopData_shop->viewportObjects[i][X_COORD_shop] * 16 + 8,
            (u16)sShopData_shop->viewportObjects[i][Y_COORD_shop] * 16 + 48 - graphicsInfo->height / 2,
            2);

        if (BuyMenuCheckIfObjectEventOverlapsMenuBg_shop(sShopData_shop->viewportObjects[i]) == TRUE)
        {
            gSprites[spriteId].subspriteTableNum = 4;
            gSprites[spriteId].subspriteMode = SUBSPRITES_ON;
        }

        StartSpriteAnim(&gSprites[spriteId], sShopData_shop->viewportObjects[i][ANIM_NUM_shop]);
    }

    gWeatherPtr->palProcessingState = weatherTemp; // restore weather state
    CpuFastCopy(gPlttBufferFaded + 16*16, gPlttBufferUnfaded + 16*16, PLTT_BUFFER_SIZE);
}

static bool8 BuyMenuCheckIfObjectEventOverlapsMenuBg_shop(s16 *object)
{
    if (!BuyMenuCheckForOverlapWithMenuBg_shop(object[X_COORD_shop], object[Y_COORD_shop] + 2) && object[LAYER_TYPE_shop] != METATILE_LAYER_TYPE_COVERED)
        return TRUE;
    else
        return FALSE;
}

static void BuyMenuCopyMenuBgToBg1TilemapBuffer_shop(void)
{
    s16 i;
    u16 *dest = sShopData_shop->tilemapBuffers[1];
    const u16 *src = sShopData_shop->tilemapBuffers[0];

    for (i = 0; i < 1024; i++)
    {
        if (src[i] != 0)
            dest[i] = src[i] + 0xC3E3;
    }
}

static bool8 BuyMenuCheckForOverlapWithMenuBg_shop(int x, int y)
{
    const u16 *metatile = sShopData_shop->tilemapBuffers[0];
    int offset1 = x * 2;
    int offset2 = y * 64;

    if (metatile[offset2 + offset1] == 0 &&
        metatile[offset2 + offset1 + 32] == 0 &&
        metatile[offset2 + offset1 + 1] == 0 &&
        metatile[offset2 + offset1 + 33] == 0)
        return TRUE;

    return FALSE;
}

static void Task_BuyMenu_shop(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    if (!gPaletteFade.active)
    {
        s32 itemId = ListMenu_ProcessInput(tListTaskId_shop);
        ListMenuGetScrollAndRow(tListTaskId_shop, &sShopData_shop->scrollOffset, &sShopData_shop->selectedRow);

        switch (itemId)
        {
        case LIST_NOTHING_CHOSEN:
            break;
        case LIST_CANCEL:
            PlaySE(SE_SELECT);
            ExitBuyMenu_shop(taskId);
            break;
        default:
            PlaySE(SE_SELECT);
            tItemId_shop = itemId;
            ClearWindowTilemap(WIN_ITEM_DESCRIPTION_shop);
            BuyMenuRemoveScrollIndicatorArrows_shop();
            BuyMenuPrintCursor_shop(tListTaskId_shop, COLORID_GRAY_CURSOR);

            if (sMartInfo_shop.martType == MART_TYPE_NORMAL_shop)
                sShopData_shop->totalCost = (ItemId_GetPrice(itemId) >> IsPokeNewsActive(POKENEWS_SLATEPORT));
            else
                sShopData_shop->totalCost = gDecorations[itemId].price;

            if (ItemId_GetImportance(itemId) && (CheckBagHasItem(itemId, 1) || CheckPCHasItem(itemId, 1)))
                BuyMenuDisplayMessage_shop(taskId, gText_ThatItemIsSoldOut, BuyMenuReturnToItemList_shop);
            else if (!IsEnoughMoney(&gSaveBlock1Ptr->money, sShopData_shop->totalCost))
            {
                BuyMenuDisplayMessage_shop(taskId, gText_YouDontHaveMoney, BuyMenuReturnToItemList_shop);
            }
            else
            {
                if (sMartInfo_shop.martType == MART_TYPE_NORMAL_shop)
                {
                    CopyItemName(itemId, gStringVar1);
                    if (ItemId_GetImportance(itemId))
                    {
                        ConvertIntToDecimalStringN(gStringVar2, sShopData_shop->totalCost, STR_CONV_MODE_LEFT_ALIGN, 6);
                        StringExpandPlaceholders(gStringVar4, gText_YouWantedVar1ThatllBeVar2);
                        tItemCount_shop = 1;
                        sShopData_shop->totalCost = (ItemId_GetPrice(tItemId_shop) >> IsPokeNewsActive(POKENEWS_SLATEPORT)) * tItemCount_shop;
                        BuyMenuDisplayMessage_shop(taskId, gStringVar4, BuyMenuConfirmPurchase_shop);
                    }
                    else if (ItemId_GetPocket(itemId) == POCKET_TM_HM)
                    {
                        StringCopy(gStringVar2, GetMoveName(ItemIdToBattleMoveId(itemId)));
                        BuyMenuDisplayMessage_shop(taskId, gText_Var1CertainlyHowMany2, Task_BuyHowManyDialogueInit_shop);
                    }
                    else
                    {
                        BuyMenuDisplayMessage_shop(taskId, gText_Var1CertainlyHowMany, Task_BuyHowManyDialogueInit_shop);
                    }
                }
                else
                {
                    StringCopy(gStringVar1, gDecorations[itemId].name);
                    ConvertIntToDecimalStringN(gStringVar2, sShopData_shop->totalCost, STR_CONV_MODE_LEFT_ALIGN, MAX_MONEY_DIGITS);

                    if (sMartInfo_shop.martType == MART_TYPE_DECOR_shop)
                        StringExpandPlaceholders(gStringVar4, gText_Var1IsItThatllBeVar2);
                    else // MART_TYPE_DECOR2_shop
                        StringExpandPlaceholders(gStringVar4, gText_YouWantedVar1ThatllBeVar2);

                    BuyMenuDisplayMessage_shop(taskId, gStringVar4, BuyMenuConfirmPurchase_shop);
                }
            }
            break;
        }
    }
}

static void Task_BuyHowManyDialogueInit_shop(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    u16 quantityInBag = CountTotalItemQuantityInBag(tItemId_shop);
    u16 maxQuantity;

    DrawStdFrameWithCustomTileAndPalette(WIN_QUANTITY_IN_BAG_shop, FALSE, 1, 13);
    ConvertIntToDecimalStringN(gStringVar1, quantityInBag, STR_CONV_MODE_RIGHT_ALIGN, MAX_ITEM_DIGITS + 1);
    StringExpandPlaceholders(gStringVar4, gText_InBagVar1);
    BuyMenuPrint_shop(WIN_QUANTITY_IN_BAG_shop, gStringVar4, 0, 1, 0, COLORID_NORMAL);
    tItemCount_shop = 1;
    DrawStdFrameWithCustomTileAndPalette(WIN_QUANTITY_PRICE_shop, FALSE, 1, 13);
    BuyMenuPrintItemQuantityAndPrice_shop(taskId);
    ScheduleBgCopyTilemapToVram(0);

    maxQuantity = GetMoney(&gSaveBlock1Ptr->money) / sShopData_shop->totalCost;

    if (maxQuantity > MAX_BAG_ITEM_CAPACITY)
        sShopData_shop->maxQuantity = MAX_BAG_ITEM_CAPACITY;
    else
        sShopData_shop->maxQuantity = maxQuantity;

    gTasks[taskId].func = Task_BuyHowManyDialogueHandleInput_shop;
}

static void Task_BuyHowManyDialogueHandleInput_shop(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    if (AdjustQuantityAccordingToDPadInput(&tItemCount_shop, sShopData_shop->maxQuantity) == TRUE)
    {
        sShopData_shop->totalCost = (ItemId_GetPrice(tItemId_shop) >> IsPokeNewsActive(POKENEWS_SLATEPORT)) * tItemCount_shop;
        BuyMenuPrintItemQuantityAndPrice_shop(taskId);
    }
    else
    {
        if (JOY_NEW(A_BUTTON))
        {
            PlaySE(SE_SELECT);
            ClearStdWindowAndFrameToTransparent(WIN_QUANTITY_PRICE_shop, FALSE);
            ClearStdWindowAndFrameToTransparent(WIN_QUANTITY_IN_BAG_shop, FALSE);
            ClearWindowTilemap(WIN_QUANTITY_PRICE_shop);
            ClearWindowTilemap(WIN_QUANTITY_IN_BAG_shop);
            PutWindowTilemap(WIN_ITEM_LIST_shop);
            CopyItemName(tItemId_shop, gStringVar1);
            ConvertIntToDecimalStringN(gStringVar2, tItemCount_shop, STR_CONV_MODE_LEFT_ALIGN, MAX_ITEM_DIGITS);
            ConvertIntToDecimalStringN(gStringVar3, sShopData_shop->totalCost, STR_CONV_MODE_LEFT_ALIGN, MAX_MONEY_DIGITS);
            BuyMenuDisplayMessage_shop(taskId, gText_Var1AndYouWantedVar2, BuyMenuConfirmPurchase_shop);
        }
        else if (JOY_NEW(B_BUTTON))
        {
            PlaySE(SE_SELECT);
            ClearStdWindowAndFrameToTransparent(WIN_QUANTITY_PRICE_shop, FALSE);
            ClearStdWindowAndFrameToTransparent(WIN_QUANTITY_IN_BAG_shop, FALSE);
            ClearWindowTilemap(WIN_QUANTITY_PRICE_shop);
            ClearWindowTilemap(WIN_QUANTITY_IN_BAG_shop);
            BuyMenuReturnToItemList_shop(taskId);
        }
    }
}

static void BuyMenuConfirmPurchase_shop(u8 taskId)
{
    CreateYesNoMenuWithCallbacks(taskId, &sShopBuyMenuYesNoWindowTemplates_shop, 1, 0, 0, 1, 13, &sShopPurchaseYesNoFuncs_shop);
}

static void BuyMenuTryMakePurchase_shop(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    PutWindowTilemap(WIN_ITEM_LIST_shop);

    if (sMartInfo_shop.martType == MART_TYPE_NORMAL_shop)
    {
        if (AddBagItem(tItemId_shop, tItemCount_shop) == TRUE)
        {
            GetSetItemObtained(tItemId_shop, FLAG_SET_ITEM_OBTAINED);
            RecordItemPurchase_shop(taskId);
            BuyMenuDisplayMessage_shop(taskId, gText_HereYouGoThankYou, BuyMenuSubtractMoney_shop);
        }
        else
        {
            BuyMenuDisplayMessage_shop(taskId, gText_NoMoreRoomForThis, BuyMenuReturnToItemList_shop);
        }
    }
    else
    {
        if (DecorationAdd(tItemId_shop))
        {
            if (sMartInfo_shop.martType == MART_TYPE_DECOR_shop)
                BuyMenuDisplayMessage_shop(taskId, gText_ThankYouIllSendItHome, BuyMenuSubtractMoney_shop);
            else // MART_TYPE_DECOR2_shop
                BuyMenuDisplayMessage_shop(taskId, gText_ThanksIllSendItHome, BuyMenuSubtractMoney_shop);
        }
        else
        {
            BuyMenuDisplayMessage_shop(taskId, gText_SpaceForVar1Full, BuyMenuReturnToItemList_shop);
        }
    }
}

static void BuyMenuSubtractMoney_shop(u8 taskId)
{
    IncrementGameStat(GAME_STAT_SHOPPED);
    RemoveMoney(&gSaveBlock1Ptr->money, sShopData_shop->totalCost);
    PlaySE(SE_SHOP);
    PrintMoneyAmountInMoneyBox(WIN_MONEY_shop, GetMoney(&gSaveBlock1Ptr->money), 0);

    if (sMartInfo_shop.martType == MART_TYPE_NORMAL_shop)
        gTasks[taskId].func = Task_ReturnToItemListAfterItemPurchase_shop;
    else
        gTasks[taskId].func = Task_ReturnToItemListAfterDecorationPurchase_shop;
}

static void Task_ReturnToItemListAfterItemPurchase_shop(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    if (JOY_NEW(A_BUTTON | B_BUTTON))
    {
        u16 premierBallsToAdd = tItemCount_shop / 10;
        if (premierBallsToAdd >= 1
         && ((I_PREMIER_BALL_BONUS <= GEN_7 && tItemId_shop == ITEM_POKE_BALL)
          || (I_PREMIER_BALL_BONUS >= GEN_8 && (ItemId_GetPocket(tItemId_shop) == POCKET_POKE_BALLS))))
        {
            u32 spaceAvailable = GetFreeSpaceForItemInBag(ITEM_PREMIER_BALL);
            if (spaceAvailable < premierBallsToAdd)
                premierBallsToAdd = spaceAvailable;
        }
        else
        {
            premierBallsToAdd = 0;
        }

        PlaySE(SE_SELECT);
        AddBagItem(ITEM_PREMIER_BALL, premierBallsToAdd);
        if (premierBallsToAdd > 0)
        {
            ConvertIntToDecimalStringN(gStringVar1, premierBallsToAdd, STR_CONV_MODE_LEFT_ALIGN, MAX_ITEM_DIGITS);
            BuyMenuDisplayMessage_shop(taskId, (premierBallsToAdd >= 2 ? gText_ThrowInPremierBalls : gText_ThrowInPremierBall), BuyMenuReturnToItemList_shop);
        }
        else
        {
            BuyMenuReturnToItemList_shop(taskId);
        }
    }
}

static void Task_ReturnToItemListAfterDecorationPurchase_shop(u8 taskId)
{
    if (JOY_NEW(A_BUTTON | B_BUTTON))
    {
        PlaySE(SE_SELECT);
        BuyMenuReturnToItemList_shop(taskId);
    }
}

static void BuyMenuReturnToItemList_shop(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    ClearDialogWindowAndFrameToTransparent(WIN_MESSAGE_shop, FALSE);
    RedrawListMenu(tListTaskId_shop);
    BuyMenuPrintCursor_shop(tListTaskId_shop, COLORID_ITEM_LIST);
    PutWindowTilemap(WIN_ITEM_LIST_shop);
    PutWindowTilemap(WIN_ITEM_DESCRIPTION_shop);
    ScheduleBgCopyTilemapToVram(0);
    BuyMenuAddScrollIndicatorArrows_shop();
    gTasks[taskId].func = Task_BuyMenu_shop;
}

static void BuyMenuPrintItemQuantityAndPrice_shop(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    FillWindowPixelBuffer(WIN_QUANTITY_PRICE_shop, PIXEL_FILL(1));
    PrintMoneyAmount(WIN_QUANTITY_PRICE_shop, CalculateMoneyTextHorizontalPosition(sShopData_shop->totalCost), 1, sShopData_shop->totalCost, TEXT_SKIP_DRAW);
    ConvertIntToDecimalStringN(gStringVar1, tItemCount_shop, STR_CONV_MODE_LEADING_ZEROS, MAX_ITEM_DIGITS);
    StringExpandPlaceholders(gStringVar4, gText_xVar1);
    BuyMenuPrint_shop(WIN_QUANTITY_PRICE_shop, gStringVar4, 0, 1, 0, COLORID_NORMAL);
}

static void ExitBuyMenu_shop(u8 taskId)
{
    gFieldCallback = MapPostLoadHook_ReturnToShopMenu_shop;
    BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
    gTasks[taskId].func = Task_ExitBuyMenu_shop;
}

static void Task_ExitBuyMenu_shop(u8 taskId)
{
    if (!gPaletteFade.active)
    {
        RemoveMoneyLabelObject();
        BuyMenuFreeMemory_shop();
        SetMainCallback2(CB2_ReturnToField);
        DestroyTask(taskId);
    }
}

static void ClearItemPurchases_shop(void)
{
    sPurchaseHistoryId_shop = 0;
    memset(gMartPurchaseHistory, 0, sizeof(gMartPurchaseHistory));
}

static void RecordItemPurchase_shop(u8 taskId)
{
    s16 *data = gTasks[taskId].data;

    u16 i;

    for (i = 0; i < ARRAY_COUNT(gMartPurchaseHistory); i++)
    {
        if (gMartPurchaseHistory[i].itemId == tItemId_shop && gMartPurchaseHistory[i].quantity != 0)
        {
            if (gMartPurchaseHistory[i].quantity + tItemCount_shop > 255)
                gMartPurchaseHistory[i].quantity = 255;
            else
                gMartPurchaseHistory[i].quantity += tItemCount_shop;
            return;
        }
    }

    if (sPurchaseHistoryId_shop < ARRAY_COUNT(gMartPurchaseHistory))
    {
        gMartPurchaseHistory[sPurchaseHistoryId_shop].itemId = tItemId_shop;
        gMartPurchaseHistory[sPurchaseHistoryId_shop].quantity = tItemCount_shop;
        sPurchaseHistoryId_shop++;
    }
}

#undef tItemCount_shop
#undef tItemId_shop
#undef tListTaskId_shop
#undef tCallbackHi_shop
#undef tCallbackLo_shop

void CreatePokemartMenu(const u16 *itemsForSale)
{
    CreateShopMenu_shop(MART_TYPE_NORMAL_shop);
    SetShopItemsForSale_shop(itemsForSale);
    ClearItemPurchases_shop();
    SetShopMenuCallback_shop(ScriptContext_Enable);
}

void CreateDecorationShop1Menu(const u16 *itemsForSale)
{
    CreateShopMenu_shop(MART_TYPE_DECOR_shop);
    SetShopItemsForSale_shop(itemsForSale);
    SetShopMenuCallback_shop(ScriptContext_Enable);
}

void CreateDecorationShop2Menu(const u16 *itemsForSale)
{
    CreateShopMenu_shop(MART_TYPE_DECOR2_shop);
    SetShopItemsForSale_shop(itemsForSale);
    SetShopMenuCallback_shop(ScriptContext_Enable);
}
