#define SLOTMACHINE_GFX_TILES_slot_machine 233
#define MAX_BET_slot_machine 3

#define SYMBOLS_PER_REEL_slot_machine   21
#define REEL_SYMBOL_HEIGHT_slot_machine 24
#define REEL_HEIGHT_slot_machine        (SYMBOLS_PER_REEL_slot_machine * REEL_SYMBOL_HEIGHT_slot_machine)

#define REELTIME_SYMBOLS_slot_machine       6
#define REELTIME_SYMBOL_HEIGHT_slot_machine 20
#define REELTIME_REEL_HEIGHT_slot_machine   (REELTIME_SYMBOLS_slot_machine * REELTIME_SYMBOL_HEIGHT_slot_machine)

// There are three categories of biases: 7's, ReelTime, Regular
//  - 7's: BIAS_STRAIGHT_7_slot_machine, BIAS_MIXED_7_slot_machine
//  - ReelTime: BIAS_REELTIME_slot_machine
//  - Regular: everything else
//
// The 7's and ReelTime biases can be grouped together as 'Special' biases.
//
// There can be at most two biases at a time. If there are two, one bias will be
// ReelTime and the other will be one of the Regular biases.
//
// A new bias is drawn every round, except during ReelTime. Bias towards 7's
// persists across rounds until you match 7's. All other biases are reset after
// the round.
#define BIAS_REPLAY_slot_machine     (1 << 0)
#define BIAS_CHERRY_slot_machine     (1 << 1)
#define BIAS_LOTAD_slot_machine      (1 << 2)
#define BIAS_AZURILL_slot_machine    (1 << 3)
#define BIAS_POWER_slot_machine      (1 << 4)
#define BIAS_REELTIME_slot_machine   (1 << 5)
#define BIAS_MIXED_7_slot_machine    (1 << 6)
#define BIAS_STRAIGHT_7_slot_machine (1 << 7)

#define BIAS_7_slot_machine       (BIAS_STRAIGHT_7_slot_machine | BIAS_MIXED_7_slot_machine)
#define BIAS_SPECIAL_slot_machine (BIAS_7_slot_machine | BIAS_REELTIME_slot_machine)
#define BIAS_REGULAR_slot_machine (BIAS_REPLAY_slot_machine | BIAS_CHERRY_slot_machine | BIAS_LOATAD | BIAS_AZURILL_slot_machine | BIAS_POWER_slot_machine)

// The slot machine will try to manipulate the outcome by adding up to 4 extra
// turns to the reel after you press stop.
//
// The only exception is when it is stopping the third reel and it has decided
// you will lose. In this case, it adds as many turns as necessary to prevent a
// match.
#define MAX_EXTRA_TURNS_slot_machine 4

