// Just idles, digital display is handled by CreateDigitalDisplayScene_slot_machine and sprite callbacks
static void (*const sDigitalDisplayTasks[])(struct Task *task) =
{
    DigitalDisplay_Idle_slot_machine,
};

#define tState_slot_machine data[0]

static void Task_FadeToSlotMachine_slot_machine(u8 taskId)
{
    switch (gTasks[taskId].tState_slot_machine)
    {
    case 0:
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 0x10, RGB_BLACK);
        gTasks[taskId].tState_slot_machine++;
        break;
    case 1:
        if (!gPaletteFade.active)
        {
            SetMainCallback2(CB2_SlotMachineSetup_slot_machine);
            DestroyTask(taskId);
        }
        break;
    }
}

void PlaySlotMachine(u8 machineId, MainCallback exitCallback)
{
    u8 taskId;

    sSlotMachine_slot_machine = AllocZeroed(sizeof(*sSlotMachine_slot_machine));
    PlaySlotMachine_Internal_slot_machine(machineId, exitCallback);
    taskId = CreateTask(Task_FadeToSlotMachine_slot_machine, 0);
    gTasks[taskId].tState_slot_machine = 0;
}

#undef tState_slot_machine

static void CB2_SlotMachineSetup_slot_machine(void)
{
    switch (gMain.state)
    {
        case 0:
            SlotMachineSetup_InitBgsWindows_slot_machine();
            InitSlotMachine_slot_machine();
            gMain.state++;
            break;
        case 1:
            SlotMachineSetup_InitVRAM_slot_machine();
            gMain.state++;
            break;
        case 2:
            SlotMachineSetup_InitOAM_slot_machine();
            SlotMachineSetup_InitGpuRegs_slot_machine();
            gMain.state++;
            break;
        case 3:
            SlotMachineSetup_InitPalsSpritesTasks_slot_machine();
            gMain.state++;
            break;
        case 4:
            SlotMachineSetup_InitTilemaps_slot_machine();
            gMain.state++;
            break;
        case 5:
            SlotMachineSetup_LoadGfxAndTilemaps_slot_machine();
            gMain.state++;
            break;
        case 6:
            SlotMachineSetup_InitVBlank_slot_machine();
            gMain.state++;
            break;
        case 7:
            BeginNormalPaletteFade(-1, 0, 0x10, 0, RGB_BLACK);
            ShowBg(0);
            ShowBg(1);
            ShowBg(2);
            ShowBg(3);
            gMain.state++;
            break;
        case 8:
            AllocDigitalDisplayGfx_slot_machine();
            gMain.state++;
            break;
        case 9:
            SetDigitalDisplayImagePtrs_slot_machine();
            gMain.state++;
            break;
        case 10:
            CreateSlotMachineSprites_slot_machine();
            CreateGameplayTasks_slot_machine();
            gMain.state++;
            break;
        case 11:
            SetMainCallback2(CB2_SlotMachine_slot_machine);
            break;
    }
}

static void CB2_SlotMachine_slot_machine(void)
{
    RunTasks();
    AnimateSprites();
    BuildOamBuffer();
    UpdatePaletteFade();
}

static void SlotMachine_VBlankCB_slot_machine(void)
{
    LoadOam();
    ProcessSpriteCopyRequests();
    TransferPlttBuffer();
    SetGpuReg(REG_OFFSET_WIN0H, sSlotMachine_slot_machine->win0h);
    SetGpuReg(REG_OFFSET_WIN0V, sSlotMachine_slot_machine->win0v);
    SetGpuReg(REG_OFFSET_WININ, sSlotMachine_slot_machine->winIn);
    SetGpuReg(REG_OFFSET_WINOUT, sSlotMachine_slot_machine->winOut);
}

#define tMachineId_slot_machine    data[0]
#define tExitCallback_slot_machine data[1]

static void PlaySlotMachine_Internal_slot_machine(u8 machineId, MainCallback exitCallback)
{
    struct Task *task = &gTasks[CreateTask(SlotMachineDummyTask_slot_machine, 0xFF)];
    task->tMachineId_slot_machine = machineId;
    StoreWordInTwoHalfwords((u16*) &task->tExitCallback_slot_machine, (intptr_t)exitCallback);
}

// Extracts and assigns machineId and exit callback from task.
static void SlotMachine_InitFromTask_slot_machine(void)
{
    struct Task *task = &gTasks[FindTaskIdByFunc(SlotMachineDummyTask_slot_machine)];
    sSlotMachine_slot_machine->machineId = task->tMachineId_slot_machine;
    LoadWordFromTwoHalfwords((u16 *)&task->tExitCallback_slot_machine, (u32 *)&sSlotMachine_slot_machine->prevMainCb);
}

static void SlotMachineDummyTask_slot_machine(u8 taskId)
{
}

#undef tMachineId_slot_machine
#undef tExitCallback_slot_machine

static void SlotMachineSetup_InitBgsWindows_slot_machine(void)
{
    SetVBlankCallback(NULL);
    SetHBlankCallback(NULL);
    CpuFill32(0, (void *)VRAM, VRAM_SIZE);
    ResetBgsAndClearDma3BusyFlags(0);
    InitBgsFromTemplates(0, sBgTemplates_slot_machine, ARRAY_COUNT(sBgTemplates_slot_machine));
    InitWindows(sWindowTemplates_slot_machine);
    DeactivateAllTextPrinters();
}

static void SlotMachineSetup_InitVBlank_slot_machine(void)
{
    SetVBlankCallback(SlotMachine_VBlankCB_slot_machine);
    EnableInterrupts(INTR_FLAG_VBLANK);
    SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_OBJ_1D_MAP | DISPCNT_OBJ_ON | DISPCNT_WIN0_ON);
}

static void SlotMachineSetup_InitVRAM_slot_machine(void)
{
    DmaClearLarge16(3, (u16 *)(BG_VRAM), BG_VRAM_SIZE, 0x1000);
}

static void SlotMachineSetup_InitOAM_slot_machine(void)
{
    DmaClear16(3, (u16 *)OAM, OAM_SIZE);
}

static void SlotMachineSetup_InitGpuRegs_slot_machine(void)
{
    SetGpuReg(REG_OFFSET_BG0CNT, 0);
    SetGpuReg(REG_OFFSET_BG1CNT, 0);
    SetGpuReg(REG_OFFSET_BG2CNT, 0);
    SetGpuReg(REG_OFFSET_BG3CNT, 0);
    SetGpuReg(REG_OFFSET_BG0HOFS, 0);
    SetGpuReg(REG_OFFSET_BG0VOFS, 0);
    SetGpuReg(REG_OFFSET_BG1HOFS, 0);
    SetGpuReg(REG_OFFSET_BG1VOFS, 0);
    SetGpuReg(REG_OFFSET_BG2HOFS, 0);
    SetGpuReg(REG_OFFSET_BG2VOFS, 0);
    SetGpuReg(REG_OFFSET_BG3HOFS, 0);
    SetGpuReg(REG_OFFSET_BG3VOFS, 0);
    SetGpuReg(REG_OFFSET_WININ, WININ_WIN0_BG_ALL | WININ_WIN0_OBJ | WININ_WIN0_CLR);
    SetGpuReg(REG_OFFSET_WINOUT, WINOUT_WIN01_BG_ALL | WINOUT_WIN01_OBJ | WINOUT_WIN01_CLR);
    SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_TGT1_BG3 | BLDCNT_EFFECT_BLEND | BLDCNT_TGT2_OBJ);
    SetGpuReg(REG_OFFSET_BLDALPHA, BLDALPHA_BLEND(9, 8));
}

// Set up initial state of slot machine
static void InitSlotMachine_slot_machine(void)
{
    u8 i;

    SlotMachine_InitFromTask_slot_machine();
    sSlotMachine_slot_machine->state = SLOTTASK_UNFADE_slot_machine;
    sSlotMachine_slot_machine->pikaPowerBolts = 0;
    sSlotMachine_slot_machine->luckyGame = Random() & 1;
    sSlotMachine_slot_machine->machineBias = 0;
    sSlotMachine_slot_machine->matches = 0;
    sSlotMachine_slot_machine->reelTimeSpinsLeft = 0;
    sSlotMachine_slot_machine->reelTimeSpinsUsed = 0;
    sSlotMachine_slot_machine->coins = GetCoins();
    sSlotMachine_slot_machine->payout = 0;
    sSlotMachine_slot_machine->netCoinLoss = 0;
    sSlotMachine_slot_machine->bet = 0;
    sSlotMachine_slot_machine->currentReel = LEFT_REEL_slot_machine;
    sSlotMachine_slot_machine->reelSpeed = REEL_NORMAL_SPEED_slot_machine;
    sSlotMachine_slot_machine->win0h = DISPLAY_WIDTH;
    sSlotMachine_slot_machine->win0v = DISPLAY_HEIGHT;
    sSlotMachine_slot_machine->winIn = WININ_WIN0_BG_ALL | WININ_WIN0_OBJ | WININ_WIN0_CLR;
    sSlotMachine_slot_machine->winOut = WINOUT_WIN01_BG_ALL | WINOUT_WIN01_OBJ | WINOUT_WIN01_CLR;
    sSlotMachine_slot_machine->backupMapMusic = GetCurrentMapMusic();

    for (i = 0; i < NUM_REELS_slot_machine; i++)
    {
        sSlotMachine_slot_machine->reelShockOffsets[i] = 0;
        sSlotMachine_slot_machine->reelPositions[i] = sInitialReelPositions_slot_machine[i][sSlotMachine_slot_machine->luckyGame] % SYMBOLS_PER_REEL_slot_machine;
        sSlotMachine_slot_machine->reelPixelOffsets[i] = REEL_HEIGHT_slot_machine - sSlotMachine_slot_machine->reelPositions[i] * REEL_SYMBOL_HEIGHT_slot_machine;
        sSlotMachine_slot_machine->reelPixelOffsets[i] %= REEL_HEIGHT_slot_machine;
    }
    AlertTVThatPlayerPlayedSlotMachine(GetCoins());
}

