// Determine the biases for this round. There can be at most two biases, one of
// which would need to be a ReelTime bias.
//
// HOW IT WORKS:
//   If the machine is already biased toward 7's, keep this bias.
//
//   Otherwise, there are up to three draws. You first draw to see if you'll get
//   to draw a Special bias. If so, then you draw for the Special bias (and can
//   still potentially miss).
//
//   If you didn't get to draw a Special bias, missed a Special bias, or drew a
//   ReelTime bias, then you can still try to draw a Regular bias.
static void DrawMachineBias_slot_machine(void)
{
    u8 whichBias;

    if (sSlotMachine_slot_machine->reelTimeSpinsLeft == 0)
    {
        if (!(sSlotMachine_slot_machine->machineBias & (BIAS_STRAIGHT_7_slot_machine | BIAS_MIXED_7_slot_machine)))
        {
            if (ShouldTrySpecialBias_slot_machine())
            {
                whichBias = TrySelectBias_Special_slot_machine();
                if (whichBias != ARRAY_COUNT(sBiasesSpecial_slot_machine)) // A bias was selected
                {
                    sSlotMachine_slot_machine->machineBias |= sBiasesSpecial_slot_machine[whichBias];

                    // ReelTime was not selected; don't add other biases
                    if (whichBias != 1) return;
                }
            }

            whichBias = TrySelectBias_Regular_slot_machine();
            if (whichBias != ARRAY_COUNT(sBiasesRegular_slot_machine)) // A bias was selected
                sSlotMachine_slot_machine->machineBias |= sBiasesRegular_slot_machine[whichBias];
        }
    }
}

// Reset `didNotFailBias` to match `machineBias`.
static void ResetBiasFailure_slot_machine(void)
{
    sSlotMachine_slot_machine->didNotFailBias = FALSE;
    if (sSlotMachine_slot_machine->machineBias)
        sSlotMachine_slot_machine->didNotFailBias = TRUE;
}

// See sBiasSymbols_slot_machine for each bias's corresponding symbol.
static u8 GetBiasSymbol_slot_machine(u8 machineBias)
{
    u8 i;

    for (i = 0; i < 8; i++)
    {
        if (machineBias & 1)
            return sBiasSymbols_slot_machine[i];
        machineBias >>= 1;
    }
    return 0;
}

// Decides whether you will be given the opportunity to draw for a Special bias.
// Depends on your bet and the machine you're using.
//
// The probability of getting to draw a Special is miniscule if you don't bet 3
// coins: barely 1% even on the luckiest machine.
//
// The odds increase to roughly ~5% if you bet 3 coins.
static bool8 ShouldTrySpecialBias_slot_machine(void)
{
    u8 rval = Random();
    if (sSpecialDrawOdds_slot_machine[sSlotMachine_slot_machine->machineId][sSlotMachine_slot_machine->bet - 1] > rval)
        return TRUE;
    return FALSE;
}

// Draws for a Special bias. Note that even when you're given the opportunity to
// draw a Special bias, you can still miss.
//
// On the luckiest machine, there's a 61% chance of drawing no Special bias. On
// the unluckiest, a 73% chance.
static u8 TrySelectBias_Special_slot_machine(void)
{
    s16 whichBias;

    for (whichBias = 0; whichBias < (int)ARRAY_COUNT(sBiasesSpecial_slot_machine); whichBias++)
    {
        s16 rval = Random() & 0xff;
        s16 value = sBiasProbabilities_Special_slot_machine[whichBias][sSlotMachine_slot_machine->machineId];
        if (value > rval)
            break;
    }
    return whichBias;
}

static u8 TrySelectBias_Regular_slot_machine(void)
{
    s16 whichBias;

    for (whichBias = 0; whichBias < (int)ARRAY_COUNT(sBiasesRegular_slot_machine); whichBias++)
    {
        s16 rval = Random() & 0xff;
        s16 value = sBiasProbabilities_Regular_slot_machine[whichBias][sSlotMachine_slot_machine->machineId];

        // Boost odds of BIAS_POWER_slot_machine if it's a lucky game.
        if (whichBias == 0 && sSlotMachine_slot_machine->luckyGame == TRUE)
        {
            value += 10;
            if (value > 0x100)
                value = 0x100;
        }
        // Reduce odds of BIAS_REPLAY_slot_machine if it's a lucky game
        else if (whichBias == 4 && sSlotMachine_slot_machine->luckyGame == TRUE)
        {
            value -= 10;
            if (value < 0)
                value = 0;
        }
        if (value > rval)
            break;
    }
    return whichBias;
}

// Return the probability of drawing the given number of ReelTime spins.
//
// This depends on whether it is a lucky game and the number of Power bolts you
// have collected.
static u8 GetReelTimeSpinProbability_slot_machine(u8 spins)
{
    if (sSlotMachine_slot_machine->luckyGame == FALSE)
        return sReelTimeProbabilities_NormalGame_slot_machine[spins][sSlotMachine_slot_machine->pikaPowerBolts];
    else
        return sReelTimeProbabilities_LuckyGame_slot_machine[spins][sSlotMachine_slot_machine->pikaPowerBolts];
}

// The way this is computed skews the odds much more toward drawing a 0 than
// intended. It initially checks whether you draw a 0 (using the intended
// probability). It then tries to draw positive values, but if these draws all
// miss, you'll still draw a 0.
//
// As a result, even when the power gauge is maxed out, you still have a ~30%
// chance of drawing 0 spins. See sReelTimeProbabilities for more details.
//
// Drawing a random number via a cumulative pdf would have prevented this.
static void GetReelTimeDraw_slot_machine(void)
{
    u8 rval;
    s16 spins;

    sSlotMachine_slot_machine->reelTimeDraw = 0;
    rval = Random();
    if (rval < GetReelTimeSpinProbability_slot_machine(0))
        return;
    for (spins = 5; spins > 0; spins--)
    {
        rval = Random();
        if (rval < GetReelTimeSpinProbability_slot_machine(spins))
            break;
    }
    sSlotMachine_slot_machine->reelTimeDraw = spins;
}

// Returns true if the ReelTime machine should explode. Each time we check,
// the odds of explosion increase.
static bool8 ShouldReelTimeMachineExplode_slot_machine(u16 check)
{
    u16 rval = Random() & 0xff;
    if (rval < sReelTimeExplodeProbability_slot_machine[check])
        return TRUE;
    else
        return FALSE;
}

static u16 ReelTimeSpeed_slot_machine(void)
{
    u8 i = 0;
    u8 rval;
    u8 value;
    if (sSlotMachine_slot_machine->netCoinLoss >= 300)
        i = 4;
    else if (sSlotMachine_slot_machine->netCoinLoss >= 250)
        i = 3;
    else if (sSlotMachine_slot_machine->netCoinLoss >= 200)
        i = 2;
    else if (sSlotMachine_slot_machine->netCoinLoss >= 150)
        i = 1;

    rval = Random() % 100;
    value = sReelTimeSpeed_Probabilities_slot_machine[i][0];
    if (rval < value)
        return REEL_HALF_SPEED_slot_machine;

    rval = Random() % 100;
    value = sReelTimeSpeed_Probabilities_slot_machine[i][1] + sQuarterSpeed_ProbabilityBoost_slot_machine[sSlotMachine_slot_machine->reelTimeSpinsUsed];
    if (rval < value)
        return REEL_QUARTER_SPEED_slot_machine;

    return REEL_NORMAL_SPEED_slot_machine;
}

static void CheckMatch_slot_machine(void)
{
    sSlotMachine_slot_machine->matches = 0;
    CheckMatch_CenterRow_slot_machine();
    if (sSlotMachine_slot_machine->bet > 1)
        CheckMatch_TopAndBottom_slot_machine();
    if (sSlotMachine_slot_machine->bet > 2)
        CheckMatch_Diagonals_slot_machine();
}

static void CheckMatch_CenterRow_slot_machine(void)
{
    u8 sym1, sym2, sym3, match;

    sym1 = GetSymbolAtRest_slot_machine(LEFT_REEL_slot_machine, 2);
    sym2 = GetSymbolAtRest_slot_machine(MIDDLE_REEL_slot_machine, 2);
    sym3 = GetSymbolAtRest_slot_machine(RIGHT_REEL_slot_machine, 2);
    match = GetMatchFromSymbols_slot_machine(sym1, sym2, sym3);
    if (match != MATCH_NONE_slot_machine)
    {
        sSlotMachine_slot_machine->payout += sSlotPayouts_slot_machine[match];
        sSlotMachine_slot_machine->matches |= sSlotMatchFlags_slot_machine[match];
        FlashMatchLine_slot_machine(MATCH_MIDDLE_ROW_slot_machine);
    }
}

static void CheckMatch_TopAndBottom_slot_machine(void)
{
    u8 sym1, sym2, sym3, match;

    sym1 = GetSymbolAtRest_slot_machine(LEFT_REEL_slot_machine, 1);
    sym2 = GetSymbolAtRest_slot_machine(MIDDLE_REEL_slot_machine, 1);
    sym3 = GetSymbolAtRest_slot_machine(RIGHT_REEL_slot_machine, 1);
    match = GetMatchFromSymbols_slot_machine(sym1, sym2, sym3);
    if (match != MATCH_NONE_slot_machine)
    {
        if (match == MATCH_CHERRY)
            match = MATCH_TOPBOT_CHERRY;
        sSlotMachine_slot_machine->payout += sSlotPayouts_slot_machine[match];
        sSlotMachine_slot_machine->matches |= sSlotMatchFlags_slot_machine[match];
        FlashMatchLine_slot_machine(MATCH_TOP_ROW_slot_machine);
    }
    sym1 = GetSymbolAtRest_slot_machine(LEFT_REEL_slot_machine, 3);
    sym2 = GetSymbolAtRest_slot_machine(MIDDLE_REEL_slot_machine, 3);
    sym3 = GetSymbolAtRest_slot_machine(RIGHT_REEL_slot_machine, 3);
    match = GetMatchFromSymbols_slot_machine(sym1, sym2, sym3);
    if (match != MATCH_NONE_slot_machine)
    {
        if (match == MATCH_CHERRY)
            match = MATCH_TOPBOT_CHERRY;
        sSlotMachine_slot_machine->payout += sSlotPayouts_slot_machine[match];
        sSlotMachine_slot_machine->matches |= sSlotMatchFlags_slot_machine[match];
        FlashMatchLine_slot_machine(MATCH_BOTTOM_ROW_slot_machine);
    }
}

static void CheckMatch_Diagonals_slot_machine(void)
{
    u8 sym1, sym2, sym3, match;

    sym1 = GetSymbolAtRest_slot_machine(LEFT_REEL_slot_machine, 1);
    sym2 = GetSymbolAtRest_slot_machine(MIDDLE_REEL_slot_machine, 2);
    sym3 = GetSymbolAtRest_slot_machine(RIGHT_REEL_slot_machine, 3);
    match = GetMatchFromSymbols_slot_machine(sym1, sym2, sym3);
    if (match != MATCH_NONE_slot_machine)
    {
        // Don't add payout for cherry, since it's already counted in
        // CheckMatch_TopAndBottom_slot_machine().
        if (match != MATCH_CHERRY)
        {
            sSlotMachine_slot_machine->payout += sSlotPayouts_slot_machine[match];
            sSlotMachine_slot_machine->matches |= sSlotMatchFlags_slot_machine[match];
        }
        FlashMatchLine_slot_machine(MATCH_NWSE_DIAG_slot_machine);
    }
    sym1 = GetSymbolAtRest_slot_machine(LEFT_REEL_slot_machine, 3);
    sym2 = GetSymbolAtRest_slot_machine(MIDDLE_REEL_slot_machine, 2);
    sym3 = GetSymbolAtRest_slot_machine(RIGHT_REEL_slot_machine, 1);
    match = GetMatchFromSymbols_slot_machine(sym1, sym2, sym3);
    if (match != MATCH_NONE_slot_machine)
    {
        // Don't add payout for cherry, since it's already counted in
        // CheckMatch_TopAndBottom_slot_machine().
        if (match != MATCH_CHERRY)
        {
            sSlotMachine_slot_machine->payout += sSlotPayouts_slot_machine[match];
            sSlotMachine_slot_machine->matches |= sSlotMatchFlags_slot_machine[match];
        }
        FlashMatchLine_slot_machine(MATCH_NESW_DIAG_slot_machine);
    }
}

static u8 GetMatchFromSymbols_slot_machine(u8 sym1, u8 sym2, u8 sym3)
{
    if (sym1 == sym2 && sym1 == sym3)
        return sSymbolToMatch_slot_machine[sym1];
    if (sym1 == SYMBOL_7_RED_slot_machine && sym2 == SYMBOL_7_RED_slot_machine && sym3 == SYMBOL_7_BLUE_slot_machine)
        return MATCH_MIXED_7;
    if (sym1 == SYMBOL_7_BLUE_slot_machine && sym2 == SYMBOL_7_BLUE_slot_machine && sym3 == SYMBOL_7_RED_slot_machine)
        return MATCH_MIXED_7;
    if (sym1 == SYMBOL_CHERRY_slot_machine)
        return MATCH_CHERRY;
    return MATCH_NONE_slot_machine;
}

