#define sFlashing_slot_machine        data[1]
#define sNumFullFlashes_slot_machine  data[2]
#define sDelayTimer_slot_machine      data[3]
#define sColor_slot_machine           data[4]
#define sColorIncr_slot_machine       data[5]
#define sAtOriginalColor_slot_machine data[7]

// Creates invisible sprites that flash the bet lines/numbers where a match occurs
// 5 are created, 1 for each possible match line (3 rows, 2 diagonals)
static void CreateInvisibleFlashMatchLineSprites_slot_machine(void)
{
    u8 i;
    for (i = 0; i < ARRAY_COUNT(sSlotMachine_slot_machine->flashMatchLineSpriteIds); i++)
    {
        u8 spriteId = CreateInvisibleSprite(SpriteCB_FlashMatchingLines_slot_machine);
        gSprites[spriteId].sMatchLineId_slot_machine = i;
        sSlotMachine_slot_machine->flashMatchLineSpriteIds[i] = spriteId;
    }
}

static void FlashMatchLine_slot_machine(u8 matchLineId)
{
    struct Sprite *sprite = &gSprites[sSlotMachine_slot_machine->flashMatchLineSpriteIds[matchLineId]];
    sprite->sFlashing_slot_machine = TRUE;
    sprite->sNumFullFlashes_slot_machine = 4;
    sprite->sDelayTimer_slot_machine = 0;
    sprite->sColor_slot_machine = 0;
    sprite->sColorIncr_slot_machine = 2;
    sprite->sAtOriginalColor_slot_machine = FALSE;
}

// Match line flashes 4 times before the payout begins
// After this it does half-brightness flashes until the payout finishes
static bool8 IsMatchLineDoneFlashingBeforePayout_slot_machine(void)
{
    u8 i;
    for (i = 0; i < ARRAY_COUNT(sSlotMachine_slot_machine->flashMatchLineSpriteIds); i++)
    {
        struct Sprite *sprite = &gSprites[sSlotMachine_slot_machine->flashMatchLineSpriteIds[i]];
        if (sprite->sFlashing_slot_machine && sprite->sNumFullFlashes_slot_machine)
            return FALSE;
    }
    return TRUE;
}

// When payout is finished, stop lines flashing (but not if they're in the middle of a flash)
static bool8 TryStopMatchLinesFlashing_slot_machine(void)
{
    u8 i;
    for (i = 0; i < ARRAY_COUNT(sSlotMachine_slot_machine->flashMatchLineSpriteIds); i++)
    {
        if (!TryStopMatchLineFlashing_slot_machine(sSlotMachine_slot_machine->flashMatchLineSpriteIds[i]))
            return FALSE;
    }
    return TRUE;
}

static bool8 TryStopMatchLineFlashing_slot_machine(u8 spriteId)
{
    struct Sprite *sprite = &gSprites[spriteId];
    if (!sprite->sFlashing_slot_machine)
        return TRUE;
    if (sprite->sAtOriginalColor_slot_machine)
        sprite->sFlashing_slot_machine = FALSE;

    return sprite->sAtOriginalColor_slot_machine;
}

static void SpriteCB_FlashMatchingLines_slot_machine(struct Sprite *sprite)
{
    s16 maxColorChange;
    if (sprite->sFlashing_slot_machine)
    {
        if (!sprite->sDelayTimer_slot_machine--)
        {
            sprite->sAtOriginalColor_slot_machine = FALSE;
            sprite->sDelayTimer_slot_machine = 1;
            sprite->sColor_slot_machine += sprite->sColorIncr_slot_machine;
            maxColorChange = 4;
            if (sprite->sNumFullFlashes_slot_machine)
                maxColorChange = 8;
            if (sprite->sColor_slot_machine <= 0)
            {
                // Returned to original color, reverse
                sprite->sAtOriginalColor_slot_machine = TRUE;
                sprite->sColorIncr_slot_machine = -sprite->sColorIncr_slot_machine;
                if (sprite->sNumFullFlashes_slot_machine)
                    sprite->sNumFullFlashes_slot_machine--;
            }
            else if (sprite->sColor_slot_machine >= maxColorChange)
            {
                // Reached peak darkness, reverse
                sprite->sColorIncr_slot_machine = -sprite->sColorIncr_slot_machine;
            }
            if (sprite->sNumFullFlashes_slot_machine)
                sprite->sDelayTimer_slot_machine <<= 1;
        }
        MultiplyPaletteRGBComponents(sMatchLinePalOffsets_slot_machine[sprite->sMatchLineId_slot_machine], sprite->sColor_slot_machine, sprite->sColor_slot_machine, sprite->sColor_slot_machine);
    }
}

