static void FlashSlotMachineLights_slot_machine(void)
{
    u8 taskId = CreateTask(Task_FlashSlotMachineLights_slot_machine, 6);
    gTasks[taskId].sFlashDir_slot_machine = 1;
    Task_FlashSlotMachineLights_slot_machine(taskId);
}

static bool8 TryStopSlotMachineLights_slot_machine(void)
{
    u8 taskId = FindTaskIdByFunc(Task_FlashSlotMachineLights_slot_machine);
    if (gTasks[taskId].sFlashState_slot_machine == 0)
    {
        DestroyTask(taskId);
        LoadPalette(sSlotMachineMenu_Pal, BG_PLTT_ID(1), PLTT_SIZE_4BPP);
        return TRUE;
    }
    return FALSE;
}

static void Task_FlashSlotMachineLights_slot_machine(u8 taskId)
{
    struct Task *task = &gTasks[taskId];
    if (!task->sDelayTimer_slot_machine--)
    {
        task->sDelayTimer_slot_machine = 4;
        task->sFlashState_slot_machine += task->sFlashDir_slot_machine;
        if (task->sFlashState_slot_machine == 0 || task->sFlashState_slot_machine == 2)
            task->sFlashDir_slot_machine = -task->sFlashDir_slot_machine;
    }
    LoadPalette(sFlashingLightsPalTable_slot_machine[task->sFlashState_slot_machine], BG_PLTT_ID(1), PLTT_SIZE_4BPP);
}

