// The bolt sprite spins around as it appears
// Once the anim is done, destroy the sprite and set the bolt in the tilemap instead
static void PikaPowerBolt_WaitAnim_slot_machine(struct Task *task)
{
    if (gSprites[task->tSpriteId_slot_machine].data[7])
    {
        s16 r5 = task->tNumBolts_slot_machine + 2;
        s16 r3 = 0;
        s16 r2 = 0;
        if (task->tNumBolts_slot_machine == 1)
            r3 = 1, r2 = 1;
        else if (task->tNumBolts_slot_machine == 16)
            r3 = 2, r2 = 2;
        sSelectedPikaPowerTile_slot_machine[r2] = sPikaPowerTileTable_slot_machine[r3][0];
        LoadBgTilemap(2, &sSelectedPikaPowerTile_slot_machine[r2], 2, r5 + 0x40);
        DestroyPikaPowerBoltSprite_slot_machine(task->tSpriteId_slot_machine);
        task->tState_slot_machine = PIKABOLT_TASK_IDLE_slot_machine;
        task->tAnimating_slot_machine = 0;
    }
}

static void PikaPowerBolt_ClearAll_slot_machine(struct Task *task)
{
    s16 r5 = task->tNumBolts_slot_machine + 2;
    s16 r3 = 0;
    s16 r2 = 3;
    if (task->tNumBolts_slot_machine == 1)
        r3 = 1, r2 = 1;
    else if (task->tNumBolts_slot_machine == 16)
        r3 = 2, r2 = 2;
    if (task->tTimer_slot_machine == 0)
    {
        sSelectedPikaPowerTile_slot_machine[r2] = sPikaPowerTileTable_slot_machine[r3][1];
        LoadBgTilemap(2, &sSelectedPikaPowerTile_slot_machine[r2], 2, r5 + 0x40);
        task->tNumBolts_slot_machine--;
    }
    if (++task->tTimer_slot_machine >= 20)
        task->tTimer_slot_machine = 0;
    if (task->tNumBolts_slot_machine == 0)
    {
        task->tState_slot_machine = PIKABOLT_TASK_IDLE_slot_machine;
        task->tAnimating_slot_machine = 0;
    }
}

static void ResetPikaPowerBoltTask_slot_machine(struct Task *task)
{
    u8 i;

    for (i = 2; i < NUM_TASK_DATA; i++)
        task->data[i] = 0;
}

static void LoadPikaPowerMeter_slot_machine(u8 bolts)
{
    s16 i;
    s16 r3 = 0, r1 = 0;
    s16 r4 = 3;
    for (i = 0; i < bolts; i++, r4++)
    {
        r3 = 0, r1 = 0;
        if (i == 0)
            r3 = 1, r1 = 1;
        else if (i == 15) // meter is full
            r3 = 2, r1 = 2;
        sSelectedPikaPowerTile_slot_machine[r1] = sPikaPowerTileTable_slot_machine[r3][0];
        LoadBgTilemap(2, &sSelectedPikaPowerTile_slot_machine[r1], 2, r4 + 0x40);
    }
    for (; i < 16; i++, r4++)
    {
        r3 = 0, r1 = 3;
        if (i == 0)
            r3 = 1, r1 = 1;
        else if (i == 15)
            r3 = 2, r1 = 2;
        sSelectedPikaPowerTile_slot_machine[r1] = sPikaPowerTileTable_slot_machine[r3][1];
        LoadBgTilemap(2, &sSelectedPikaPowerTile_slot_machine[r1], 2, r4 + 0x40);
    }
    gTasks[sSlotMachine_slot_machine->pikaPowerBoltTaskId].data[1] = bolts;
}

#undef tState_slot_machine
#undef tNumBolts_slot_machine
#undef tSpriteId_slot_machine
#undef tTimer_slot_machine
#undef tAnimating_slot_machine

#define tState_slot_machine         data[0]
#define tReelSpeed_slot_machine     data[1]
#define tTimer3_slot_machine        data[2]
#define tRtReelSpeed_slot_machine   data[4]
#define tTimer2_slot_machine        data[4]
#define tTimer1_slot_machine        data[5]
#define tExplodeChecks_slot_machine data[6]

static void BeginReelTime_slot_machine(void)
{
    u8 taskId = CreateTask(Task_ReelTime_slot_machine, 7);
    Task_ReelTime_slot_machine(taskId);
}

static bool8 IsReelTimeTaskDone_slot_machine(void)
{
    if (FindTaskIdByFunc(Task_ReelTime_slot_machine) == TAIL_SENTINEL)
        return TRUE;
    return FALSE;
}

static void Task_ReelTime_slot_machine(u8 taskId)
{
    sReelTimeTasks[gTasks[taskId].tState_slot_machine](&gTasks[taskId]);
}

static void ReelTime_Init_slot_machine(struct Task *task)
{
    sSlotMachine_slot_machine->reelTimeSpinsLeft = 0;
    sSlotMachine_slot_machine->reeltimePixelOffset = 0;
    sSlotMachine_slot_machine->reeltimePosition = 0;
    task->tState_slot_machine++; // RT_TASK_WINDOW_ENTER_slot_machine
    task->data[1] = 0;
    task->data[2] = 30;
    task->tRtReelSpeed_slot_machine = 1280;
    gSpriteCoordOffsetX = 0;
    gSpriteCoordOffsetY = 0;
    SetGpuReg(REG_OFFSET_BG1HOFS, 0);
    SetGpuReg(REG_OFFSET_BG1VOFS, 0);
    LoadReelTimeWindowTilemap_slot_machine(REG_OFFSET_BG3VOFS, 0);
    CreateReelTimeMachineSprites_slot_machine();
    CreateReelTimePikachuSprite_slot_machine();
    CreateReelTimeNumberSprites_slot_machine();
    CreateReelTimeShadowSprites_slot_machine();
    CreateReelTimeNumberGapSprite_slot_machine();
    GetReelTimeDraw_slot_machine();
    StopMapMusic();
    PlayNewMapMusic(MUS_ROULETTE);
}

static void ReelTime_WindowEnter_slot_machine(struct Task *task)
{
    s16 r3;
    gSpriteCoordOffsetX -= 8;
    task->data[1] += 8;
    r3 = ((task->data[1] + 240) & 0xff) >> 3;
    SetGpuReg(REG_OFFSET_BG1HOFS, task->data[1] & 0x1ff);
    if (r3 != task->data[2] && task->data[3] <= 18)
    {
        task->data[2] = r3;
        task->data[3] = task->data[1] >> 3;
        LoadReelTimeWindowTilemap_slot_machine(r3, task->data[3]);
    }
    if (task->data[1] >= 200)
    {
        task->tState_slot_machine++; // RT_TASK_WAIT_START_PIKA_slot_machine
        task->data[3] = 0;
    }
    AdvanceReeltimeReel_slot_machine(task->tRtReelSpeed_slot_machine >> 8);
}

static void ReelTime_WaitStartPikachu_slot_machine(struct Task *task)
{
    AdvanceReeltimeReel_slot_machine(task->tRtReelSpeed_slot_machine >> 8);
    if (++task->tTimer1_slot_machine >= 60)
    {
        task->tState_slot_machine++; // RT_TASK_PIKA_SPEEDUP1_slot_machine
        CreateReelTimeBoltSprites_slot_machine();
        CreateReelTimePikachuAuraSprites_slot_machine();
    }
}

static void ReelTime_PikachuSpeedUp1_slot_machine(struct Task *task)
{
    int i;
    u8 pikachuAnimIds[ARRAY_COUNT(sReelTimePikachuAnimIds_slot_machine)];
    s16 reelTimeBoltDelays[ARRAY_COUNT(sReelTimeBoltDelays_slot_machine)];
    s16 pikachuAuraFlashDelays[ARRAY_COUNT(sPikachuAuraFlashDelays_slot_machine)];

    memcpy(pikachuAnimIds, sReelTimePikachuAnimIds_slot_machine, sizeof(sReelTimePikachuAnimIds_slot_machine));
    memcpy(reelTimeBoltDelays, sReelTimeBoltDelays_slot_machine, sizeof(sReelTimeBoltDelays_slot_machine));
    memcpy(pikachuAuraFlashDelays, sPikachuAuraFlashDelays_slot_machine, sizeof(sPikachuAuraFlashDelays_slot_machine));

    AdvanceReeltimeReel_slot_machine(task->tRtReelSpeed_slot_machine >> 8);
    // gradually slow down the reel
    task->tRtReelSpeed_slot_machine -= 4;
    i = 4 - (task->tRtReelSpeed_slot_machine >> 8);
    SetReelTimeBoltDelay_slot_machine(reelTimeBoltDelays[i]);
    SetReelTimePikachuAuraFlashDelay_slot_machine(pikachuAuraFlashDelays[i]);
    StartSpriteAnimIfDifferent(&gSprites[sSlotMachine_slot_machine->reelTimePikachuSpriteId], pikachuAnimIds[i]);
    // once speed goes below 256, go to next ReelTime task and keep the speed level
    if (task->tRtReelSpeed_slot_machine <= 0x100)
    {
        task->tState_slot_machine++; // RT_TASK_PIKA_SPEEDUP2_slot_machine
        task->tRtReelSpeed_slot_machine = 0x100;
        task->tTimer1_slot_machine = 0;
    }
}

static void ReelTime_PikachuSpeedUp2_slot_machine(struct Task *task)
{
    AdvanceReeltimeReel_slot_machine(task->tRtReelSpeed_slot_machine >> 8);
    if (++task->tTimer1_slot_machine >= 80)
    {
        task->tState_slot_machine++; // RT_TASK_WAIT_REEL_slot_machine
        task->tTimer1_slot_machine = 0;
        SetReelTimePikachuAuraFlashDelay_slot_machine(2);
        StartSpriteAnimIfDifferent(&gSprites[sSlotMachine_slot_machine->reelTimePikachuSpriteId], 3);
    }
}

static void ReelTime_WaitReel_slot_machine(struct Task *task)
{
    AdvanceReeltimeReel_slot_machine(task->tRtReelSpeed_slot_machine >> 8);
    task->tRtReelSpeed_slot_machine = (u8)task->tRtReelSpeed_slot_machine + 0x80;
    if (++task->tTimer1_slot_machine >= 80)
    {
        task->tState_slot_machine++; // RT_TASK_CHECK_EXPLODE_slot_machine
        task->tTimer1_slot_machine = 0;
    }
}

// Check whether the ReelTime machine should explode.
//
// The ReelTime machine displays 0 when this task starts. If there is a positive
// ReelTime draw, the machine keeps spinning until it lands on that number.
//
// Otherwise, it checks every 40 frames whether it should explode. If so, it
// explodes immediately. After 4 checks, the machine won't explode but continues
// to spin until it lands on 0.
static void ReelTime_CheckExplode_slot_machine(struct Task *task)
{
    AdvanceReeltimeReel_slot_machine(task->tRtReelSpeed_slot_machine >> 8);
    task->tRtReelSpeed_slot_machine = (u8)task->tRtReelSpeed_slot_machine + 0x40;
    if (++task->tTimer1_slot_machine >= 40)
    {
        task->tTimer1_slot_machine = 0;
        if (sSlotMachine_slot_machine->reelTimeDraw)
        {
            if (sSlotMachine_slot_machine->reelTimeSpinsLeft <= task->tExplodeChecks_slot_machine)
                task->tState_slot_machine++; // RT_TASK_LAND_slot_machine
        }
        else if (task->tExplodeChecks_slot_machine > 3)
        {
            task->tState_slot_machine++; // RT_TASK_LAND_slot_machine
        }
        else if (ShouldReelTimeMachineExplode_slot_machine(task->tExplodeChecks_slot_machine))
        {
            task->tState_slot_machine = RT_TASK_EXPLODE_slot_machine;
        }
        task->tExplodeChecks_slot_machine++;
    }
}

// Reel spins until it lands on the selected outcome.
static void ReelTime_LandOnOutcome_slot_machine(struct Task *task)
{
    s16 reeltimePixelOffset = sSlotMachine_slot_machine->reeltimePixelOffset % 20;
    if (reeltimePixelOffset)
    {
        reeltimePixelOffset = AdvanceReeltimeReelToNextSymbol(task->tRtReelSpeed_slot_machine >> 8);
        task->tRtReelSpeed_slot_machine = (u8)task->tRtReelSpeed_slot_machine + 0x40;
    }
    else if (GetReelTimeSymbol_slot_machine(1) != sSlotMachine_slot_machine->reelTimeDraw)
    {
        AdvanceReeltimeReel_slot_machine(task->tRtReelSpeed_slot_machine >> 8);
        reeltimePixelOffset = sSlotMachine_slot_machine->reeltimePixelOffset % 20;
        task->tRtReelSpeed_slot_machine = (u8)task->tRtReelSpeed_slot_machine + 0x40;
    }
    if (reeltimePixelOffset == 0 && GetReelTimeSymbol_slot_machine(1) == sSlotMachine_slot_machine->reelTimeDraw)
    {
        task->tRtReelSpeed_slot_machine = 0; // Also initializes task->tTimer2_slot_machine
        task->tState_slot_machine++; // RT_TASK_PIKA_REACT_slot_machine
    }
}

// Animate Pikachu reaction. Clear any power bolts the player may have won if
// they got a positive ReelTime draw.
static void ReelTime_PikachuReact_slot_machine(struct Task *task)
{
    if (++task->tTimer2_slot_machine >= 60)
    {
        StopMapMusic();
        DestroyReelTimeBoltSprites_slot_machine();
        DestroyReelTimePikachuAuraSprites_slot_machine();
        task->tState_slot_machine++; // RT_TASK_WAIT_CLEAR_POWER_slot_machine
        if(sSlotMachine_slot_machine->reelTimeDraw == 0)
        {
            task->tTimer2_slot_machine = 0xa0;
            StartSpriteAnimIfDifferent(&gSprites[sSlotMachine_slot_machine->reelTimePikachuSpriteId], 5);
            PlayFanfare(MUS_TOO_BAD);
        }
        else
        {
            task->tTimer2_slot_machine = 0xc0;
            StartSpriteAnimIfDifferent(&gSprites[sSlotMachine_slot_machine->reelTimePikachuSpriteId], 4);
            gSprites[sSlotMachine_slot_machine->reelTimePikachuSpriteId].animCmdIndex = 0;
            if (sSlotMachine_slot_machine->pikaPowerBolts)
            {
                ResetPikaPowerBolts_slot_machine();
                sSlotMachine_slot_machine->pikaPowerBolts = 0;
            }
            PlayFanfare(MUS_SLOTS_WIN);
        }
    }
}

static void ReelTime_WaitClearPikaPower_slot_machine(struct Task *task)
{
    if ((task->tTimer2_slot_machine == 0 || --task->tTimer2_slot_machine == 0) && !IsPikaPowerBoltAnimating_slot_machine())
        task->tState_slot_machine++; // RT_TASK_CLOSE_WINDOW_SUCCESS_slot_machine
}

static void ReelTime_CloseWindow_slot_machine(struct Task *task)
{
    s16 r4;
    gSpriteCoordOffsetX -= 8;
    task->data[1] += 8;
    task->data[3] += 8;
    r4 = ((task->data[1] - 8) & 0xff) >> 3;
    SetGpuReg(REG_OFFSET_BG1HOFS, task->data[1] & 0x1ff);
    if (task->data[3] >> 3 <= 25)
        ClearReelTimeWindowTilemap_slot_machine(r4);
    else
        task->tState_slot_machine++; // RT_TASK_DESTROY_SPRITES_slot_machine
}

// Destroy sprites and wrap up the ReelTime task.
//
// If the player got a positive ReelTime draw, select the speed that the slot
// reels will initially move at.
static void ReelTime_DestroySprites_slot_machine(struct Task *task)
{
    sSlotMachine_slot_machine->reelTimeSpinsUsed = 0;
    sSlotMachine_slot_machine->reelTimeSpinsLeft = sSlotMachine_slot_machine->reelTimeDraw;
    gSpriteCoordOffsetX = 0;
    SetGpuReg(REG_OFFSET_BG1HOFS, 0);
    sSlotMachine_slot_machine->reelSpeed = REEL_NORMAL_SPEED_slot_machine;
    DestroyReelTimePikachuSprite_slot_machine();
    DestroyReelTimeMachineSprites_slot_machine();
    DestroyReelTimeShadowSprites_slot_machine();
    PlayNewMapMusic(sSlotMachine_slot_machine->backupMapMusic);
    if (sSlotMachine_slot_machine->reelTimeSpinsLeft == 0)
    {
        DestroyTask(FindTaskIdByFunc(Task_ReelTime_slot_machine));
    }
    else
    {
        CreateDigitalDisplayScene_slot_machine(DIG_DISPLAY_REEL_TIME_slot_machine);
        task->tReelSpeed_slot_machine = ReelTimeSpeed_slot_machine();
        task->tTimer3_slot_machine = 0;
        task->data[3] = 0;
        task->tState_slot_machine++; // RT_TASK_SET_REEL_SPEED_slot_machine
    }
}

// Slow the slot reels down until they match the selected speed.
static void ReelTime_SetReelSpeed_slot_machine(struct Task *task)
{
    if (sSlotMachine_slot_machine->reelSpeed == task->tReelSpeed_slot_machine)
        task->tState_slot_machine++; // RT_TASK_END_SUCCESS_slot_machine
    else if (sSlotMachine_slot_machine->reelPixelOffsets[0] % REEL_SYMBOL_HEIGHT_slot_machine == 0 && (++task->tTimer3_slot_machine & 0x07) == 0)
        sSlotMachine_slot_machine->reelSpeed >>= 1;
}

static void ReelTime_EndSuccess_slot_machine(struct Task *task)
{
    if (IsDigitalDisplayAnimFinished_slot_machine())
        DestroyTask(FindTaskIdByFunc(Task_ReelTime_slot_machine));
}

static void ReelTime_ExplodeMachine_slot_machine(struct Task *task)
{
    DestroyReelTimeMachineSprites_slot_machine();
    DestroyReelTimeBoltSprites_slot_machine();
    DestroyReelTimePikachuAuraSprites_slot_machine();
    CreateReelTimeExplosionSprite_slot_machine();
    gSprites[sSlotMachine_slot_machine->reelTimeShadowSpriteIds[0]].invisible = TRUE;
    StartSpriteAnimIfDifferent(&gSprites[sSlotMachine_slot_machine->reelTimePikachuSpriteId], 5);
    task->tState_slot_machine++; // RT_TASK_WAIT_EXPLODE_slot_machine
    task->data[4] = 4;
    task->tTimer1_slot_machine = 0;
    StopMapMusic();
    PlayFanfare(MUS_TOO_BAD);
    PlaySE(SE_M_EXPLOSION);
}

static void ReelTime_WaitExplode_slot_machine(struct Task *task)
{
    gSpriteCoordOffsetY = task->data[4];
    SetGpuReg(REG_OFFSET_BG1VOFS, task->data[4]);
    if (task->tTimer1_slot_machine & 0x01)
        task->data[4] = -task->data[4];
    if ((++task->tTimer1_slot_machine & 0x1f) == 0)
        task->data[4] >>= 1;
    if (task->data[4] == 0)
    {
        DestroyReelTimeExplosionSprite_slot_machine();
        CreateReelTimeDuckSprites_slot_machine();
        CreateBrokenReelTimeMachineSprite_slot_machine();
        CreateReelTimeSmokeSprite_slot_machine();
        gSprites[sSlotMachine_slot_machine->reelTimeShadowSpriteIds[0]].invisible = FALSE;
        task->tState_slot_machine++; // RT_TASK_WAIT_SMOKE_slot_machine
        task->tTimer1_slot_machine = 0;
    }
}

static void ReelTime_WaitSmoke_slot_machine(struct Task *task)
{
    gSpriteCoordOffsetY = 0;
    SetGpuReg(REG_OFFSET_BG1VOFS, 0);
    if (IsReelTimeSmokeAnimFinished_slot_machine())
    {
        task->tState_slot_machine++; // RT_TASK_CLOSE_WINDOW_FAILURE_slot_machine
        DestroyReelTimeSmokeSprite_slot_machine();
    }
}

static void ReelTime_EndFailure_slot_machine(struct Task *task)
{
    gSpriteCoordOffsetX = 0;
    SetGpuReg(REG_OFFSET_BG1HOFS, 0);
    PlayNewMapMusic(sSlotMachine_slot_machine->backupMapMusic);
    DestroyReelTimePikachuSprite_slot_machine();
    DestroyBrokenReelTimeMachineSprite_slot_machine();
    DestroyReelTimeShadowSprites_slot_machine();
    DestroyReelTimeDuckSprites_slot_machine();
    DestroyTask(FindTaskIdByFunc(Task_ReelTime_slot_machine));
}

static void LoadReelTimeWindowTilemap_slot_machine(s16 a0, s16 a1)
{
    s16 i;
    for (i = 4; i < 15; i++)
        LoadBgTilemap(1, &sReelTimeWindow_Tilemap_slot_machine[a1 + (i - 4) * 20], 2, 32 * i + a0);
}

static void ClearReelTimeWindowTilemap_slot_machine(s16 a0)
{
    u8 i;
    for (i = 4; i < 15; i++)
        LoadBgTilemap(1, sEmptyTilemap_slot_machine, 2, 32 * i + a0);
}

#undef tState_slot_machine
#undef tReelSpeed_slot_machine
#undef tRtReelSpeed_slot_machine
#undef tTimer2_slot_machine
#undef tTimer1_slot_machine
#undef tExplodeChecks_slot_machine

#define tState_slot_machine data[0]

// Info Box is the screen shown when Select is pressed
static void OpenInfoBox_slot_machine(u8 digDisplayId)
{
    u8 taskId = CreateTask(Task_InfoBox_slot_machine, 1);
    gTasks[taskId].data[1] = digDisplayId;
    Task_InfoBox_slot_machine(taskId);
}

static bool8 IsInfoBoxClosed_slot_machine(void)
{
    if (FindTaskIdByFunc(Task_InfoBox_slot_machine) == TASK_NONE)
        return TRUE;
    else
        return FALSE;
}

static void Task_InfoBox_slot_machine(u8 taskId)
{
    sInfoBoxTasks[gTasks[taskId].tState_slot_machine](&gTasks[taskId]);
}

static void InfoBox_FadeIn_slot_machine(struct Task *task)
{
    BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
    task->tState_slot_machine++;
}

static void InfoBox_WaitFade_slot_machine(struct Task *task)
{
    if (!gPaletteFade.active)
        task->tState_slot_machine++;
}

static void InfoBox_DrawWindow_slot_machine(struct Task *task)
{
    DestroyDigitalDisplayScene_slot_machine();
    LoadInfoBoxTilemap_slot_machine();
    AddWindow(&sWindowTemplate_InfoBox_slot_machine);
    PutWindowTilemap(1);
    FillWindowPixelBuffer(1, PIXEL_FILL(0));
    task->tState_slot_machine++;
}

static void InfoBox_AddText_slot_machine(struct Task *task)
{
    AddTextPrinterParameterized3(1, FONT_NORMAL, 2, 5, sColors_ReeltimeHelp_slot_machine, 0, gText_ReelTimeHelp);
    CopyWindowToVram(1, COPYWIN_FULL);
    BeginNormalPaletteFade(PALETTES_ALL, 0, 16, 0, RGB_BLACK);
    task->tState_slot_machine++;
}

static void InfoBox_WaitInput_slot_machine(struct Task *task)
{
    if (JOY_NEW(B_BUTTON | SELECT_BUTTON))
    {
        FillWindowPixelBuffer(1, PIXEL_FILL(0));
        ClearWindowTilemap(1);
        CopyWindowToVram(1, COPYWIN_MAP);
        RemoveWindow(1);
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
        task->tState_slot_machine++;
    }
}

static void InfoBox_LoadSlotMachineTilemap_slot_machine(struct Task *task)
{
    LoadSlotMachineMenuTilemap_slot_machine();
    ShowBg(3);
    task->tState_slot_machine++;
}

static void InfoBox_CreateDigitalDisplay_slot_machine(struct Task *task)
{
    CreateDigitalDisplayScene_slot_machine(task->data[1]);
    task->tState_slot_machine++;
}

static void InfoBox_LoadPikaPowerMeter_slot_machine(struct Task *task)
{
    LoadPikaPowerMeter_slot_machine(sSlotMachine_slot_machine->pikaPowerBolts);
    BeginNormalPaletteFade(PALETTES_ALL, 0, 16, 0, RGB_BLACK);
    task->tState_slot_machine++;
}

static void InfoBox_FreeTask_slot_machine(struct Task *task)
{
    DestroyTask(FindTaskIdByFunc(Task_InfoBox_slot_machine));
}

#undef tState_slot_machine

#define sWaitForAnim_slot_machine data[7]

static void CreateDigitalDisplayTask_slot_machine(void)
{
    u8 i;
    struct Task *task;
    i = CreateTask(Task_DigitalDisplay_slot_machine, 3);
    sSlotMachine_slot_machine->digDisplayTaskId = i;
    task = &gTasks[i];
    task->data[1] = -1;
    for (i = 4; i < NUM_TASK_DATA; i++)
        task->data[i] = MAX_SPRITES;
}

// For the panel on the right side of the slot screen
static void CreateDigitalDisplayScene_slot_machine(u8 id)
{
    u8 i;
    struct Task *task;

    DestroyDigitalDisplayScene_slot_machine();

    task = &gTasks[sSlotMachine_slot_machine->digDisplayTaskId];
    task->data[1] = id;

    for (i = 0; sDigitalDisplayScenes_slot_machine[id][i].spriteTemplateId != 255; i++)
    {
        u8 spriteId;
        spriteId = CreateStdDigitalDisplaySprite_slot_machine(
                sDigitalDisplayScenes_slot_machine[id][i].spriteTemplateId,
                sDigitalDisplayScenes_slot_machine[id][i].dispInfoId,
                sDigitalDisplayScenes_slot_machine[id][i].spriteId
        );
        task->data[4 + i] = spriteId;
    }
}

static void AddDigitalDisplaySprite_slot_machine(u8 templateIdx, SpriteCallback callback, s16 x, s16 y, s16 spriteId)
{
    u8 i;
    struct Task *task = &gTasks[sSlotMachine_slot_machine->digDisplayTaskId];
    for (i = 4; i < NUM_TASK_DATA; i++)
    {
        if (task->data[i] == MAX_SPRITES)
        {
            task->data[i] = CreateDigitalDisplaySprite_slot_machine(templateIdx, callback, x, y, spriteId);
            break;
        }
    }
}

static void DestroyDigitalDisplayScene_slot_machine(void)
{
    u8 i;
    struct Task *task = &gTasks[sSlotMachine_slot_machine->digDisplayTaskId];

    if ((u16)task->data[1] != 0xFFFF)
        sDigitalDisplaySceneExitCallbacks[task->data[1]]();

    for (i = 4; i < NUM_TASK_DATA; i++)
    {
        if (task->data[i] != MAX_SPRITES)
        {
            DestroySprite(&gSprites[task->data[i]]);
            task->data[i] = MAX_SPRITES;
        }
    }
}

static bool8 IsDigitalDisplayAnimFinished_slot_machine(void)
{
    u8 i;
    struct Task *task = &gTasks[sSlotMachine_slot_machine->digDisplayTaskId];
    for (i = 4; i < NUM_TASK_DATA; i++)
    {
        if (task->data[i] != MAX_SPRITES)
        {
            if (gSprites[task->data[i]].sWaitForAnim_slot_machine)
                return FALSE;
        }
    }
    return TRUE;
}

static void Task_DigitalDisplay_slot_machine(u8 taskId)
{
    sDigitalDisplayTasks[gTasks[taskId].data[0]](&gTasks[taskId]);
}

