{
}

static void CreateReelSymbolSprites_slot_machine(void)
{
    s16 i;
    s16 j;
    s16 x;
    for (i = 0, x = 0x30; i < 3; i++, x += 0x28)
    {
        for (j = 0; j < 120; j += 24)
        {
            struct Sprite *sprite = gSprites + CreateSprite(&sSpriteTemplate_ReelSymbol_slot_machine, x, 0, 14);
            sprite->oam.priority = 3;
            sprite->data[0] = i;
            sprite->data[1] = j;
            sprite->data[3] = -1;
        }
    }
}

static void SpriteCB_ReelSymbol_slot_machine(struct Sprite *sprite)
{
    sprite->data[2] = sSlotMachine_slot_machine->reelPixelOffsets[sprite->data[0]] + sprite->data[1];
    sprite->data[2] %= 120;
    sprite->y = sSlotMachine_slot_machine->reelShockOffsets[sprite->data[0]] + 28 + sprite->data[2];
    sprite->sheetTileStart = GetSpriteTileStartByTag(GetSymbolAtRest_slot_machine(sprite->data[0], sprite->data[2] / 24));
    SetSpriteSheetFrameTileNum(sprite);
}

static void CreateCreditPayoutNumberSprites_slot_machine(void)
{
    s16 i;
    s16 x;

    // Credit number sprite
    for (x = 203, i = 1; i <= MAX_COINS; i *= 10, x -= 7)
        CreateCoinNumberSprite_slot_machine(x, 23, FALSE, i);

    // Payout number sprite
    for (x = 235, i = 1; i <= MAX_COINS; i *= 10, x -= 7)
        CreateCoinNumberSprite_slot_machine(x, 23, TRUE, i);
}

#define sIsPayout_slot_machine data[0]
#define sDigitMin_slot_machine data[1]
#define sDigitMax_slot_machine data[2]
#define sCurNum_slot_machine   data[3] // Only used to determine whether the sprite has already been updated to show the correct digit

static void CreateCoinNumberSprite_slot_machine(s16 x, s16 y, bool8 isPayout, s16 digitMult)
{
    struct Sprite *sprite = &gSprites[CreateSprite(&sSpriteTemplate_CoinNumber_slot_machine, x, y, 13)];
    sprite->oam.priority = 2;
    sprite->sIsPayout_slot_machine = isPayout;
    sprite->sDigitMin_slot_machine = digitMult;
    sprite->sDigitMax_slot_machine = digitMult * 10;
    sprite->sCurNum_slot_machine = -1;
}

static void SpriteCB_CoinNumber_slot_machine(struct Sprite *sprite)
{
    u16 tag = sSlotMachine_slot_machine->coins;
    if (sprite->sIsPayout_slot_machine)
        tag = sSlotMachine_slot_machine->payout;
    if (sprite->sCurNum_slot_machine != tag)
    {
        // Convert total to current digit
        sprite->sCurNum_slot_machine = tag;
        tag %= (u16)sprite->sDigitMax_slot_machine;
        tag /= (u16)sprite->sDigitMin_slot_machine;

        tag += GFXTAG_NUM_0_slot_machine;
        sprite->sheetTileStart = GetSpriteTileStartByTag(tag);
        SetSpriteSheetFrameTileNum(sprite);
    }
}

