static void SpriteCB_ReelTimePikachuAura_slot_machine(struct Sprite *sprite)
{
    u8 colors[] = {16, 0};
    if (sprite->sFlashPal_slot_machine && --sprite->sDelayTimer_slot_machine <= 0)
    {
        MultiplyInvertedPaletteRGBComponents(OBJ_PLTT_ID(IndexOfSpritePaletteTag(PALTAG_PIKA_AURA_slot_machine)) + 3, colors[sprite->sColorIdx_slot_machine], colors[sprite->sColorIdx_slot_machine], colors[sprite->sColorIdx_slot_machine]);
        ++sprite->sColorIdx_slot_machine;
        sprite->sColorIdx_slot_machine &= 1;
        sprite->sDelayTimer_slot_machine = sprite->sDelay_slot_machine;
    }
}

