    for (i = 0; i < ARRAY_COUNT(sSlotMachine_slot_machine->reelTimePikachuAuraSpriteIds); i++)
        DestroySprite(&gSprites[sSlotMachine_slot_machine->reelTimePikachuAuraSpriteIds[i]]);
