{
    u8 i;
    for (i = 0; i < ARRAY_COUNT(sSlotMachine_slot_machine->reelTimeDuckSpriteIds); i++)
    {
        DestroySprite(&gSprites[sSlotMachine_slot_machine->reelTimeDuckSpriteIds[i]]);
    }
}

#define sState_slot_machine        data[0]
#define sMoveY_slot_machine        data[1]
#define sTimer_slot_machine        data[2]
#define sAnimFinished_slot_machine data[7]

static void CreateReelTimeSmokeSprite_slot_machine(void)
{
    u8 spriteId = CreateSprite(&sSpriteTemplate_ReelTimeSmoke_slot_machine, 168, 60, 8);
    struct Sprite *sprite = &gSprites[spriteId];
    sprite->oam.priority = 1;
    sprite->oam.affineMode = ST_OAM_AFFINE_DOUBLE;
    InitSpriteAffineAnim(sprite);
    sSlotMachine_slot_machine->reelTimeSmokeSpriteId = spriteId;
}

static void SpriteCB_ReelTimeSmoke_slot_machine(struct Sprite *sprite)
{
    if (sprite->sState_slot_machine == 0)
    {
        if (sprite->affineAnimEnded)
            sprite->sState_slot_machine++;
    }
    else if (sprite->sState_slot_machine == 1)
    {
        sprite->invisible ^= 1;
        if (++sprite->sTimer_slot_machine >= 24)
        {
            sprite->sState_slot_machine++;
            sprite->sTimer_slot_machine = 0;
        }
    }
    else
    {
        sprite->invisible = TRUE;
        if (++sprite->sTimer_slot_machine >= 16)
            sprite->sAnimFinished_slot_machine = TRUE;
    }
    sprite->sMoveY_slot_machine &= 0xff;
    sprite->sMoveY_slot_machine += 16;
    sprite->y2 -= (sprite->sMoveY_slot_machine >> 8);
}

static u8 IsReelTimeSmokeAnimFinished_slot_machine(void)
{
    return gSprites[sSlotMachine_slot_machine->reelTimeSmokeSpriteId].sAnimFinished_slot_machine;
}

