static u8 CreateDigitalDisplaySprite_slot_machine(u8 templateIdx, SpriteCallback callback, s16 x, s16 y, s16 internalSpriteId)
{
    struct SpriteTemplate spriteTemplate;
    u8 spriteId;
    struct Sprite *sprite;

    spriteTemplate = *sSpriteTemplates_DigitalDisplay[templateIdx];
    spriteTemplate.images = sImageTables_DigitalDisplay[templateIdx];
    spriteId = CreateSprite(&spriteTemplate, x, y, 16);
    sprite = &gSprites[spriteId];
    sprite->oam.priority = 3;
    sprite->callback = callback;
    sprite->sSpriteId_slot_machine = internalSpriteId;
    sprite->sWaitForAnim_slot_machine = TRUE;
    if (sSubspriteTables_DigitalDisplay[templateIdx])
        SetSubspriteTables(sprite, sSubspriteTables_DigitalDisplay[templateIdx]);
    return spriteId;
}

static void SpriteCB_DigitalDisplay_Static_slot_machine(struct Sprite *sprite)
{
    sprite->sWaitForAnim_slot_machine = FALSE;
}

static void SpriteCB_DigitalDisplay_Smoke_slot_machine(struct Sprite *sprite)
{
    s16 targetX[] = {4, -4, 4, -4};
    s16 targetY[] = {4, 4, -4, -4};

    if (sprite->sCounter_slot_machine++ >= 16)
    {
        sprite->subspriteTableNum ^= 1;
        sprite->sCounter_slot_machine = 0;
    }
    sprite->x2 = 0;
    sprite->y2 = 0;
    if (sprite->subspriteTableNum != 0)
    {
        sprite->x2 = targetX[sprite->sSpriteId_slot_machine];
        sprite->y2 = targetY[sprite->sSpriteId_slot_machine];
    }
}

static void SpriteCB_DigitalDisplay_SmokeNE_slot_machine(struct Sprite *sprite)
{
    sprite->hFlip = TRUE;
    SpriteCB_DigitalDisplay_Smoke_slot_machine(sprite);
}

static void SpriteCB_DigitalDisplay_SmokeSW_slot_machine(struct Sprite *sprite)
{
    sprite->vFlip = TRUE;
    SpriteCB_DigitalDisplay_Smoke_slot_machine(sprite);
}

static void SpriteCB_DigitalDisplay_SmokeSE_slot_machine(struct Sprite *sprite)
{
    sprite->hFlip = TRUE;
    sprite->vFlip = TRUE;
    SpriteCB_DigitalDisplay_Smoke_slot_machine(sprite);
}

// The word "Reel" in Reel Time
static void SpriteCB_DigitalDisplay_Reel_slot_machine(struct Sprite *sprite)
{
    switch (sprite->sState_slot_machine)
    {
    case 0:
        sprite->x += 4;
        if (sprite->x >= DISPLAY_WIDTH - 32)
        {
            sprite->x = DISPLAY_WIDTH - 32;
            sprite->sState_slot_machine++;
        }
        break;
    case 1:
        if (++sprite->sCounter_slot_machine > 90)
            sprite->sState_slot_machine++;
        break;
    case 2:
        sprite->x += 4;
        if (sprite->x >= DISPLAY_WIDTH + 32)
            sprite->sState_slot_machine++;
        break;
    case 3:
        sprite->sWaitForAnim_slot_machine = FALSE;
        break;
    }
}

// The word "Time" in Reel Time
static void SpriteCB_DigitalDisplay_Time_slot_machine(struct Sprite *sprite)
{
    switch (sprite->sState_slot_machine)
    {
    case 0:
        sprite->x -= 4;
        if (sprite->x <= DISPLAY_WIDTH - 32)
        {
            sprite->x = DISPLAY_WIDTH - 32;
            sprite->sState_slot_machine++;
        }
        break;
    case 1:
        if (++sprite->sCounter_slot_machine > 90)
            sprite->sState_slot_machine++;
        break;
    case 2:
        sprite->x -= 4;
        if (sprite->x <= 144)
            sprite->sState_slot_machine++;
        break;
    case 3:
        sprite->sWaitForAnim_slot_machine = FALSE;
        break;
    }
}

static void SpriteCB_DigitalDisplay_ReelTimeNumber_slot_machine(struct Sprite *sprite)
{
    switch (sprite->sState_slot_machine)
    {
    case 0:
        StartSpriteAnim(sprite, sSlotMachine_slot_machine->reelTimeSpinsLeft - 1);
        sprite->sState_slot_machine++;
        // fallthrough
    case 1:
        if (++sprite->sCounter_slot_machine >= 4)
        {
            sprite->sState_slot_machine++;
            sprite->sCounter_slot_machine = 0;
        }
        break;
    case 2:
        sprite->x += 4;
        if (sprite->x >= DISPLAY_WIDTH - 32)
        {
            sprite->x = DISPLAY_WIDTH - 32;
            sprite->sState_slot_machine++;
        }
        break;
    case 3:
        if (++sprite->sCounter_slot_machine > 90)
            sprite->sState_slot_machine++;
        break;
    case 4:
        sprite->x += 4;
        if (sprite->x >= DISPLAY_WIDTH + 8)
            sprite->sState_slot_machine++;
        break;
    case 5:
        sprite->sWaitForAnim_slot_machine = FALSE;
        break;
    }
}

static void SpriteCB_DigitalDisplay_PokeballRocking_slot_machine(struct Sprite *sprite)
{
    switch (sprite->sState_slot_machine)
    {
    case 0:
        sprite->animPaused = TRUE;
        sprite->sState_slot_machine++;
        // fallthrough
    case 1:
        sprite->y += 8;
        if (sprite->y >= 0x70)
        {
            sprite->y = 0x70;
            sprite->sCounter_slot_machine = 16;
            sprite->sState_slot_machine++;
        }
        break;
    case 2:
        if (sprite->data[2] == 0)
        {
            sprite->y -= sprite->sCounter_slot_machine;
            sprite->sCounter_slot_machine = -sprite->sCounter_slot_machine;
            if (++sprite->data[3] >= 2)
            {
                sprite->sCounter_slot_machine >>= 2;
                sprite->data[3] = 0;
                if (sprite->sCounter_slot_machine == 0)
                {
                    sprite->sState_slot_machine++;
                    sprite->sWaitForAnim_slot_machine = FALSE;
                    sprite->animPaused = FALSE;
                }
            }
        }
        sprite->data[2]++;
        sprite->data[2] &= 0x07;
        break;
    }
}

static void SpriteCB_DigitalDisplay_Stop_slot_machine(struct Sprite *sprite)
{
    switch (sprite->sState_slot_machine)
    {
    case 0:
        if (++sprite->sCounter_slot_machine > 8)
            sprite->sState_slot_machine++;
        break;
    case 1:
        sprite->y += 2;
        if (sprite->y >= 0x30)
        {
            sprite->y = 0x30;
            sprite->sState_slot_machine++;
            sprite->sWaitForAnim_slot_machine = FALSE;
        }
        break;
    }
}

static void SpriteCB_DigitalDisplay_AButtonStop_slot_machine(struct Sprite *sprite)
{
    switch (sprite->sState_slot_machine)
    {
    case 0:
        sprite->invisible = TRUE;
        if (++sprite->sCounter_slot_machine > 0x20)
        {
            sprite->sState_slot_machine++;
            sprite->sCounter_slot_machine = 5;
            sprite->oam.mosaic = TRUE;
            sprite->invisible = FALSE;
            StartSpriteAnim(sprite, 1);
            SetGpuReg(REG_OFFSET_MOSAIC, ((sprite->sCounter_slot_machine << 4) | sprite->sCounter_slot_machine) << 8);
        }
        break;
    case 1:
        sprite->sCounter_slot_machine -= (sprite->data[2] >> 8);
        if (sprite->sCounter_slot_machine < 0)
            sprite->sCounter_slot_machine = 0;
        SetGpuReg(REG_OFFSET_MOSAIC, ((sprite->sCounter_slot_machine << 4) | sprite->sCounter_slot_machine) << 8);
        sprite->data[2] &= 0xff;
        sprite->data[2] += 0x80;
        if (sprite->sCounter_slot_machine == 0)
        {
            sprite->sState_slot_machine++;
            sprite->sWaitForAnim_slot_machine = FALSE;
            sprite->oam.mosaic = FALSE;
            StartSpriteAnim(sprite, 0);
        }
        break;
    }
}

static void SpriteCB_DigitalDisplay_PokeballShining_slot_machine(struct Sprite *sprite)
{
    if (sprite->sCounter_slot_machine < 3)
    {
        LoadPalette(sPokeballShiningPalTable_slot_machine[sprite->sCounter_slot_machine], OBJ_PLTT_ID(IndexOfSpritePaletteTag(PALTAG_DIG_DISPLAY_slot_machine)), PLTT_SIZE_4BPP);
        if (++sprite->data[2] >= 4)
        {
            sprite->data[1]++;
            sprite->data[2] = 0;
        }
    }
    else
    {
        LoadPalette(sPokeballShiningPalTable_slot_machine[sprite->sCounter_slot_machine], OBJ_PLTT_ID(IndexOfSpritePaletteTag(PALTAG_DIG_DISPLAY_slot_machine)), PLTT_SIZE_4BPP);
        if (++sprite->data[2] >= 25)
        {
            sprite->sCounter_slot_machine = 0;
            sprite->data[2] = 0;
        }
    }
    StartSpriteAnimIfDifferent(sprite, 1);
    sprite->sWaitForAnim_slot_machine = FALSE;
}

static void SpriteCB_DigitalDisplay_RegBonus_slot_machine(struct Sprite *sprite)
{
    // Elements in array correspond to R E G B O N U S
    s16 letterXOffset[] = {  0, -40,   0,   0, 48,   0,  24,   0};
    s16 letterYOffset[] = {-32,   0, -32, -48,  0, -48,   0, -48};
    s16 letterDelay[]   = { 16,  12,  16,   0,  0,   4,   8,   8};

    switch (sprite->sState_slot_machine)
    {
    case 0:
        sprite->x2 = letterXOffset[sprite->sSpriteId_slot_machine];
        sprite->y2 = letterYOffset[sprite->sSpriteId_slot_machine];
        sprite->sCounter_slot_machine = letterDelay[sprite->sSpriteId_slot_machine];
        sprite->sState_slot_machine++;
        // fallthrough
    case 1:
        if (sprite->sCounter_slot_machine-- == 0)
            sprite->sState_slot_machine++;
        break;
    case 2:
        if (sprite->x2 > 0)
            sprite->x2 -= 4;
        else if (sprite->x2 < 0)
            sprite->x2 += 4;

        if (sprite->y2 > 0)
            sprite->y2 -= 4;
        else if (sprite->y2 < 0)
            sprite->y2 += 4;

        if (sprite->x2 == 0 && sprite->y2 == 0)
            sprite->sState_slot_machine++;
        break;
    }
}

static void SpriteCB_DigitalDisplay_BigBonus_slot_machine(struct Sprite *sprite)
{
    s16 sp0[] = {160, 192, 224, 104, 80, 64, 48, 24};

    if (sprite->sState_slot_machine == 0)
    {
        sprite->sState_slot_machine++;
        sprite->sCounter_slot_machine = 12;
    }
    sprite->x2 = Cos(sp0[sprite->sSpriteId_slot_machine], sprite->sCounter_slot_machine);
    sprite->y2 = Sin(sp0[sprite->sSpriteId_slot_machine], sprite->sCounter_slot_machine);
    if (sprite->sCounter_slot_machine != 0)
        sprite->sCounter_slot_machine--;
}

// For the A Button prompt when inserting bet
// Initially no sprite until after the first bet
static void SpriteCB_DigitalDisplay_AButtonStart_slot_machine(struct Sprite *sprite)
{
    switch (sprite->sState_slot_machine)
    {
        case 0:
            sSlotMachine_slot_machine->winIn = WININ_WIN0_BG_ALL | WININ_WIN0_CLR;
            sSlotMachine_slot_machine->winOut = WINOUT_WIN01_BG_ALL | WINOUT_WIN01_OBJ | WINOUT_WIN01_CLR;
            sSlotMachine_slot_machine->win0v = WIN_RANGE(32, 136);
            sprite->invisible = TRUE;
            sprite->sState_slot_machine++;
            // fallthrough
        case 1:
            sprite->sCounter_slot_machine += 2;
            sprite->data[2] = sprite->sCounter_slot_machine + 176;
            sprite->data[3] = DISPLAY_WIDTH - sprite->sCounter_slot_machine;
            if (sprite->data[2] > 208)
                sprite->data[2] = 208;
            if (sprite->data[3] < 208)
                sprite->data[3] = 208;
            sSlotMachine_slot_machine->win0h = (sprite->data[2] << 8) | sprite->data[3];
            if (sprite->sCounter_slot_machine > 51)
            {
                sprite->sState_slot_machine++;
                sSlotMachine_slot_machine->winIn = WININ_WIN0_BG_ALL | WININ_WIN0_OBJ | WININ_WIN0_CLR;
            }
            break;
        case 2:
            if (sSlotMachine_slot_machine->bet == 0)
                break;
            AddDigitalDisplaySprite_slot_machine(DIG_SPRITE_A_BUTTON_slot_machine, SpriteCallbackDummy, 208, 116, 0);
            sSlotMachine_slot_machine->win0h = WIN_RANGE(192, 224);
            sSlotMachine_slot_machine->win0v = WIN_RANGE(104, 128);
            sSlotMachine_slot_machine->winIn = WININ_WIN0_BG_ALL | WININ_WIN0_CLR;
            sprite->sState_slot_machine++;
            sprite->sCounter_slot_machine = 0;
            // fallthrough
        case 3:
            sprite->sCounter_slot_machine += 2;
            sprite->data[2] = sprite->sCounter_slot_machine + 192;
            sprite->data[3] = DISPLAY_WIDTH - 16 - sprite->sCounter_slot_machine;
            if (sprite->data[2] > 208)
                sprite->data[2] = 208;
            if (sprite->data[3] < 208)
                sprite->data[3] = 208;
            sSlotMachine_slot_machine->win0h = (sprite->data[2] << 8) | sprite->data[3];
            if (sprite->sCounter_slot_machine > 15)
            {
                sprite->sState_slot_machine++;
                sSlotMachine_slot_machine->winIn = WININ_WIN0_BG_ALL | WININ_WIN0_OBJ | WININ_WIN0_CLR;
            }
            break;
    }
}

