static void LoadSlotMachineGfx_slot_machine(void)
{
    u8 i;

    LoadReelBackground_slot_machine();
    sDigitalDisplayGfxPtr_slot_machine = Alloc(0x3200);
    LZDecompressWram(gSlotMachineDigitalDisplay_Gfx, sDigitalDisplayGfxPtr_slot_machine);
    sReelTimeGfxPtr_slot_machine = Alloc(0x3600);
    LZDecompressWram(sReelTimeGfx_slot_machine, sReelTimeGfxPtr_slot_machine);
    sSlotMachineSpritesheetsPtr_slot_machine = AllocZeroed(sizeof(struct SpriteSheet) * ARRAY_COUNT(sSlotMachineSpriteSheets_slot_machine));
    for (i = 0; i < ARRAY_COUNT(sSlotMachineSpriteSheets_slot_machine); i++)
    {
        sSlotMachineSpritesheetsPtr_slot_machine[i].data = sSlotMachineSpriteSheets_slot_machine[i].data;
        sSlotMachineSpritesheetsPtr_slot_machine[i].size = sSlotMachineSpriteSheets_slot_machine[i].size;
        sSlotMachineSpritesheetsPtr_slot_machine[i].tag = sSlotMachineSpriteSheets_slot_machine[i].tag;
    }
    sSlotMachineSpritesheetsPtr_slot_machine[GFXTAG_STOP_slot_machine - 1].data = sDigitalDisplayGfxPtr_slot_machine + 0xA00;
    sSlotMachineSpritesheetsPtr_slot_machine[GFXTAG_BONUS_slot_machine - 1].data = sDigitalDisplayGfxPtr_slot_machine + 0x1400;
    sSlotMachineSpritesheetsPtr_slot_machine[GFXTAG_BIG_slot_machine - 1].data = sDigitalDisplayGfxPtr_slot_machine + 0x1600;
    sSlotMachineSpritesheetsPtr_slot_machine[GFXTAG_REG_slot_machine - 1].data = sDigitalDisplayGfxPtr_slot_machine + 0x1900;
    LoadSpriteSheets(sSlotMachineSpritesheetsPtr_slot_machine);
    LoadSpritePalettes(sSlotMachineSpritePalettes_slot_machine);
}

static void LoadReelBackground_slot_machine(void)
{
    u8 *dest;
    u8 i, j;

    sReelBackgroundSpriteSheet_slot_machine = AllocZeroed(sizeof(struct SpriteSheet));
    sReelBackground_Gfx_slot_machine = AllocZeroed(0x2000); // Background is plain white
    dest = sReelBackground_Gfx_slot_machine;
    for (i = 0; i < 0x40; i++)
    {
        for (j = 0; j < 0x20; j++, dest++)
            *dest = sReelBackground_Tilemap[j];
    }
    sReelBackgroundSpriteSheet_slot_machine->data = sReelBackground_Gfx_slot_machine;
    sReelBackgroundSpriteSheet_slot_machine->size = 0x800;
    sReelBackgroundSpriteSheet_slot_machine->tag  = GFXTAG_REEL_BG_slot_machine;
    LoadSpriteSheet(sReelBackgroundSpriteSheet_slot_machine);
}

static void LoadMenuGfx_slot_machine(void)
{
    sMenuGfx_slot_machine = Alloc(0x2200);
    LZDecompressWram(gSlotMachineMenu_Gfx, sMenuGfx_slot_machine);
    LoadBgTiles(2, sMenuGfx_slot_machine, 0x2200, 0);
    LoadPalette(gSlotMachineMenu_Pal, BG_PLTT_ID(0), 5 * PLTT_SIZE_4BPP);
    LoadPalette(sUnkPalette_slot_machine, BG_PLTT_ID(13), PLTT_SIZE_4BPP);
}

static void LoadMenuAndReelOverlayTilemaps_slot_machine(void)
{
    LoadSlotMachineMenuTilemap_slot_machine();
    LoadSlotMachineReelOverlay_slot_machine();
}

static void LoadSlotMachineMenuTilemap_slot_machine(void)
{
    LoadBgTilemap(2, gSlotMachineMenu_Tilemap, 0x500, 0);
}

static void LoadSlotMachineReelOverlay_slot_machine(void)
{
    s16 x, y, dx;

    for (x = 4; x < 18; x += 5)
    {
        for (dx = 0; dx < 4; dx++)
        {
            LoadBgTilemap(3, sReelOverlay_Tilemap_slot_machine,     2, x + dx + 5  * 32);
            LoadBgTilemap(3, sReelOverlay_Tilemap_slot_machine + 1, 2, x + dx + 13 * 32);
            LoadBgTilemap(3, sReelOverlay_Tilemap_slot_machine + 2, 2, x + dx + 6  * 32);
            LoadBgTilemap(3, sReelOverlay_Tilemap_slot_machine + 3, 2, x + dx + 12 * 32);
        }

        LoadBgTilemap(3, sReelOverlay_Tilemap_slot_machine + 4, 2, x + 6 * 32);
        LoadBgTilemap(3, sReelOverlay_Tilemap_slot_machine + 5, 2, x + 12 * 32);

        for (y = 7; y <= 11; y++)
            LoadBgTilemap(3, sReelOverlay_Tilemap_slot_machine + 6, 2, x + y * 32);
    }
}

// For (un)shading the gray button at the bottom of a reel when A is pressed. The button is colored in quadrants
static void SetReelButtonTilemap_slot_machine(s16 offset, u16 topLeft, u16 topRight, u16 bottomLeft, u16 bottomRight)
{
    sReelButtonPress_Tilemap_slot_machine[0] = topLeft;
    sReelButtonPress_Tilemap_slot_machine[1] = topRight;
    sReelButtonPress_Tilemap_slot_machine[2] = bottomLeft;
    sReelButtonPress_Tilemap_slot_machine[3] = bottomRight;

    LoadBgTilemap(2, sReelButtonPress_Tilemap_slot_machine,     2, 15 * 32 + offset);     // Top left
    LoadBgTilemap(2, sReelButtonPress_Tilemap_slot_machine + 1, 2, 15 * 32 + 1 + offset); // Top right
    LoadBgTilemap(2, sReelButtonPress_Tilemap_slot_machine + 2, 2, 16 * 32 + offset);     // Bottom left
    LoadBgTilemap(2, sReelButtonPress_Tilemap_slot_machine + 3, 2, 16 * 32 + 1 + offset); // Bottom Right
}

