#define SPRAY_COUNT_sprays 0
#define SPRAY_GET_sprays 1

#define NUM_SPRAY_STRENGTH_sprays 3
#define SPRAY_MENU_Y_COORD_sprays 8

#define LOCAL_VAR_SPRAY_sprays gSpecialVar_0x8004
#define LOCAL_VAR_SPRAY_CONST_sprays VAR_0x8004

u32 CountOrGetSprays(u32);
u32 GetNumberSprayStrength(void);
u32 GetSprayId(void);
u32 GetLastUsedSprayType(void);
u32 SetSprayMenuCursorPosition(int, int);
#if I_REPEL_LURE_MENU == TRUE
void DrawSprayMenu(void);
#endif
void HandleSprayMenuChoice(void);

u32 CountOrGetSprays(u32 func)
{
    u32 i, currentSpray, sprayCount = 0;
    u32 spray = GetLastUsedSprayType();

    for (i = 0; i < NUM_SPRAY_STRENGTH_sprays; i++)
    {
        currentSpray = spray + i;

        if (!CheckBagHasItem(currentSpray,1))
            continue;

        if (func == SPRAY_COUNT_sprays)
            sprayCount++;
        else
            return (currentSpray);
    }
    return sprayCount;
}

u32 GetNumberSprayStrength(void)
{
    return CountOrGetSprays(SPRAY_COUNT_sprays);
}

u32 GetSprayId(void)
{
    return CountOrGetSprays(SPRAY_GET_sprays);
}

u32 GetLastUsedSprayType(void)
{
    if (IS_LAST_USED_LURE(VarGet(VAR_REPEL_STEP_COUNT)))
        return ITEM_LURE;
    else
        return ITEM_REPEL;
}

u32 SetSprayMenuCursorPosition(int currentSpray, int count)
{
    if (VarGet(VAR_LAST_REPEL_LURE_USED) == currentSpray)
        return count;

    return 0;
}

#if I_REPEL_LURE_MENU == TRUE
void DrawSprayMenu(void)
{
    struct MenuAction menuItems[NUM_SPRAY_STRENGTH_sprays+1] = {NULL};
    int sprayIndex, count = 0, menuPos = 0, currentSpray, yCoord = 0;
    u32 spray = GetLastUsedSprayType();

    for (sprayIndex = 0; sprayIndex < (NUM_SPRAY_STRENGTH_sprays); sprayIndex++)
    {
        currentSpray = spray + sprayIndex;

        if (!CheckBagHasItem(currentSpray, 1))
            continue;

        menuItems[count].text = ItemId_GetName(currentSpray);
        VarSet(LOCAL_VAR_SPRAY_CONST_sprays + count, currentSpray);

        if (VAR_LAST_REPEL_LURE_USED != 0)
            menuPos = SetSprayMenuCursorPosition(currentSpray, count);

        yCoord = SPRAY_MENU_Y_COORD_sprays - (2 * count);
        count++;
    }

    gSpecialVar_0x8003 = count;
    menuItems[count].text = gText_Cancel2;

    DrawMultichoiceMenuInternal(18, yCoord, 0, FALSE, menuPos, menuItems, count+1);
}
#endif

void HandleSprayMenuChoice(void)
{
    u32 lureMask = (GetLastUsedSprayType() == ITEM_LURE) ? REPEL_LURE_MASK : 0;

    LOCAL_VAR_SPRAY_sprays = VarGet(LOCAL_VAR_SPRAY_CONST_sprays + gSpecialVar_Result);

    VarSet(VAR_REPEL_STEP_COUNT, ItemId_GetHoldEffectParam(LOCAL_VAR_SPRAY_sprays) | lureMask);

    if (VAR_LAST_REPEL_LURE_USED != 0)
        VarSet(VAR_LAST_REPEL_LURE_USED, LOCAL_VAR_SPRAY_sprays);
}
