// .text
u16 GetStarterPokemon(u16 chosenStarterId)
{
    if (chosenStarterId > STARTER_MON_COUNT_starter_choose)
        chosenStarterId = 0;
    return sStarterMon_starter_choose[chosenStarterId];
}

static void VblankCB_StarterChoose_starter_choose(void)
{
    LoadOam();
    ProcessSpriteCopyRequests();
    TransferPlttBuffer();
}

// Data for Task_StarterChoose_starter_choose
#define tStarterSelection_starter_choose   data[0]
#define tPkmnSpriteId_starter_choose       data[1]
#define tCircleSpriteId_starter_choose     data[2]

// Data for sSpriteTemplate_Pokeball_starter_choose
#define sTaskId_starter_choose data[0]
#define sBallId_starter_choose data[1]

void CB2_ChooseStarter(void)
{
    u8 taskId;
    u8 spriteId;

    SetVBlankCallback(NULL);

    SetGpuReg(REG_OFFSET_DISPCNT, 0);
    SetGpuReg(REG_OFFSET_BG3CNT, 0);
    SetGpuReg(REG_OFFSET_BG2CNT, 0);
    SetGpuReg(REG_OFFSET_BG1CNT, 0);
    SetGpuReg(REG_OFFSET_BG0CNT, 0);

    ChangeBgX(0, 0, BG_COORD_SET);
    ChangeBgY(0, 0, BG_COORD_SET);
    ChangeBgX(1, 0, BG_COORD_SET);
    ChangeBgY(1, 0, BG_COORD_SET);
    ChangeBgX(2, 0, BG_COORD_SET);
    ChangeBgY(2, 0, BG_COORD_SET);
    ChangeBgX(3, 0, BG_COORD_SET);
    ChangeBgY(3, 0, BG_COORD_SET);

    DmaFill16(3, 0, VRAM, VRAM_SIZE);
    DmaFill32(3, 0, OAM, OAM_SIZE);
    DmaFill16(3, 0, PLTT, PLTT_SIZE);

    LZ77UnCompVram(gBirchBagGrass_Gfx, (void *)VRAM);
    LZ77UnCompVram(gBirchBagTilemap, (void *)(BG_SCREEN_ADDR(6)));
    LZ77UnCompVram(gBirchGrassTilemap, (void *)(BG_SCREEN_ADDR(7)));

    ResetBgsAndClearDma3BusyFlags(0);
    InitBgsFromTemplates(0, sBgTemplates_starter_choose, ARRAY_COUNT(sBgTemplates_starter_choose));
    InitWindows(sWindowTemplates_starter_choose);

    DeactivateAllTextPrinters();
    LoadUserWindowBorderGfx(0, 0x2A8, BG_PLTT_ID(13));
    ClearScheduledBgCopiesToVram();
    ScanlineEffect_Stop();
    ResetTasks();
    ResetSpriteData();
    ResetPaletteFade();
    FreeAllSpritePalettes();
    ResetAllPicSprites();

    LoadPalette(GetOverworldTextboxPalettePtr(), BG_PLTT_ID(14), PLTT_SIZE_4BPP);
    LoadPalette(gBirchBagGrass_Pal, BG_PLTT_ID(0), sizeof(gBirchBagGrass_Pal));
    LoadCompressedSpriteSheet(&sSpriteSheet_PokeballSelect_starter_choose[0]);
    LoadCompressedSpriteSheet(&sSpriteSheet_StarterCircle_starter_choose[0]);
    LoadSpritePalettes(sSpritePalettes_StarterChoose_starter_choose);
    BeginNormalPaletteFade(PALETTES_ALL, 0, 0x10, 0, RGB_BLACK);

    EnableInterrupts(DISPSTAT_VBLANK);
    SetVBlankCallback(VblankCB_StarterChoose_starter_choose);
    SetMainCallback2(CB2_StarterChoose_starter_choose);

    SetGpuReg(REG_OFFSET_WININ, WININ_WIN0_BG_ALL | WININ_WIN0_OBJ | WININ_WIN0_CLR);
    SetGpuReg(REG_OFFSET_WINOUT, WINOUT_WIN01_BG_ALL | WINOUT_WIN01_OBJ);
    SetGpuReg(REG_OFFSET_WIN0H, 0);
    SetGpuReg(REG_OFFSET_WIN0V, 0);
    SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_TGT1_BG1 | BLDCNT_TGT1_BG2 | BLDCNT_TGT1_BG3 | BLDCNT_TGT1_OBJ | BLDCNT_TGT1_BD | BLDCNT_EFFECT_DARKEN);
    SetGpuReg(REG_OFFSET_BLDALPHA, 0);
    SetGpuReg(REG_OFFSET_BLDY, 7);
    SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_WIN0_ON | DISPCNT_OBJ_ON | DISPCNT_OBJ_1D_MAP);

    ShowBg(0);
    ShowBg(2);
    ShowBg(3);

    taskId = CreateTask(Task_StarterChoose_starter_choose, 0);
    gTasks[taskId].tStarterSelection_starter_choose = 1;

    // Create hand sprite
    spriteId = CreateSprite(&sSpriteTemplate_Hand_starter_choose, 120, 56, 2);
    gSprites[spriteId].data[0] = taskId;

    // Create three Poké Ball sprites
    spriteId = CreateSprite(&sSpriteTemplate_Pokeball_starter_choose, sPokeballCoords_starter_choose[0][0], sPokeballCoords_starter_choose[0][1], 2);
    gSprites[spriteId].sTaskId_starter_choose = taskId;
    gSprites[spriteId].sBallId_starter_choose = 0;

    spriteId = CreateSprite(&sSpriteTemplate_Pokeball_starter_choose, sPokeballCoords_starter_choose[1][0], sPokeballCoords_starter_choose[1][1], 2);
    gSprites[spriteId].sTaskId_starter_choose = taskId;
    gSprites[spriteId].sBallId_starter_choose = 1;

    spriteId = CreateSprite(&sSpriteTemplate_Pokeball_starter_choose, sPokeballCoords_starter_choose[2][0], sPokeballCoords_starter_choose[2][1], 2);
    gSprites[spriteId].sTaskId_starter_choose = taskId;
    gSprites[spriteId].sBallId_starter_choose = 2;

    sStarterLabelWindowId_starter_choose = WINDOW_NONE;
}

static void CB2_StarterChoose_starter_choose(void)
{
    RunTasks();
    AnimateSprites();
    BuildOamBuffer();
    DoScheduledBgTilemapCopiesToVram();
    UpdatePaletteFade();
}

static void Task_StarterChoose_starter_choose(u8 taskId)
{
    CreateStarterPokemonLabel_starter_choose(gTasks[taskId].tStarterSelection_starter_choose);
    DrawStdFrameWithCustomTileAndPalette(0, FALSE, 0x2A8, 0xD);
    AddTextPrinterParameterized(0, FONT_NORMAL, gText_BirchInTrouble, 0, 1, 0, NULL);
    PutWindowTilemap(0);
    ScheduleBgCopyTilemapToVram(0);
    gTasks[taskId].func = Task_HandleStarterChooseInput_starter_choose;
}

static void Task_HandleStarterChooseInput_starter_choose(u8 taskId)
{
    u8 selection = gTasks[taskId].tStarterSelection_starter_choose;

    if (JOY_NEW(A_BUTTON))
    {
        u8 spriteId;

        ClearStarterLabel_starter_choose();

        // Create white circle background
        spriteId = CreateSprite(&sSpriteTemplate_StarterCircle_starter_choose, sPokeballCoords_starter_choose[selection][0], sPokeballCoords_starter_choose[selection][1], 1);
        gTasks[taskId].tCircleSpriteId_starter_choose = spriteId;

        // Create Pokémon sprite
        spriteId = CreatePokemonFrontSprite_starter_choose(GetStarterPokemon(gTasks[taskId].tStarterSelection_starter_choose), sPokeballCoords_starter_choose[selection][0], sPokeballCoords_starter_choose[selection][1]);
        gSprites[spriteId].affineAnims = &sAffineAnims_StarterPokemon;
        gSprites[spriteId].callback = SpriteCB_StarterPokemon_starter_choose;

        gTasks[taskId].tPkmnSpriteId_starter_choose = spriteId;
        gTasks[taskId].func = Task_WaitForStarterSprite_starter_choose;
    }
    else if (JOY_NEW(DPAD_LEFT) && selection > 0)
    {
        gTasks[taskId].tStarterSelection_starter_choose--;
        gTasks[taskId].func = Task_MoveStarterChooseCursor_starter_choose;
    }
    else if (JOY_NEW(DPAD_RIGHT) && selection < STARTER_MON_COUNT_starter_choose - 1)
    {
        gTasks[taskId].tStarterSelection_starter_choose++;
        gTasks[taskId].func = Task_MoveStarterChooseCursor_starter_choose;
    }
}

static void Task_WaitForStarterSprite_starter_choose(u8 taskId)
{
    if (gSprites[gTasks[taskId].tCircleSpriteId_starter_choose].affineAnimEnded &&
        gSprites[gTasks[taskId].tCircleSpriteId_starter_choose].x == STARTER_PKMN_POS_X_starter_choose &&
        gSprites[gTasks[taskId].tCircleSpriteId_starter_choose].y == STARTER_PKMN_POS_Y_starter_choose)
    {
        gTasks[taskId].func = Task_AskConfirmStarter_starter_choose;
    }
}

static void Task_AskConfirmStarter_starter_choose(u8 taskId)
{
    PlayCry_Normal(GetStarterPokemon(gTasks[taskId].tStarterSelection_starter_choose), 0);
    FillWindowPixelBuffer(0, PIXEL_FILL(1));
    AddTextPrinterParameterized(0, FONT_NORMAL, gText_ConfirmStarterChoice, 0, 1, 0, NULL);
    ScheduleBgCopyTilemapToVram(0);
    CreateYesNoMenu(&sWindowTemplate_ConfirmStarter_starter_choose, 0x2A8, 0xD, 0);
    gTasks[taskId].func = Task_HandleConfirmStarterInput_starter_choose;
}

static void Task_HandleConfirmStarterInput_starter_choose(u8 taskId)
{
    u8 spriteId;

    switch (Menu_ProcessInputNoWrapClearOnChoose())
    {
    case 0:  // YES
        // Return the starter choice and exit.
        gSpecialVar_Result = gTasks[taskId].tStarterSelection_starter_choose;
        ResetAllPicSprites();
        SetMainCallback2(gMain.savedCallback);
        break;
    case 1:  // NO
    case MENU_B_PRESSED:
        PlaySE(SE_SELECT);
        spriteId = gTasks[taskId].tPkmnSpriteId_starter_choose;
        FreeOamMatrix(gSprites[spriteId].oam.matrixNum);
        FreeAndDestroyMonPicSprite(spriteId);

        spriteId = gTasks[taskId].tCircleSpriteId_starter_choose;
        FreeOamMatrix(gSprites[spriteId].oam.matrixNum);
        DestroySprite(&gSprites[spriteId]);
        gTasks[taskId].func = Task_DeclineStarter_starter_choose;
        break;
    }
}

static void Task_DeclineStarter_starter_choose(u8 taskId)
{
    gTasks[taskId].func = Task_StarterChoose_starter_choose;
}

static void CreateStarterPokemonLabel_starter_choose(u8 selection)
{
    u8 categoryText[32];
    struct WindowTemplate winTemplate;
    const u8 *speciesName;
    s32 width;
    u8 labelLeft, labelRight, labelTop, labelBottom;

    u16 species = GetStarterPokemon(selection);
    CopyMonCategoryText(species, categoryText);
    speciesName = GetSpeciesName(species);

    winTemplate = sWindowTemplate_StarterLabel_starter_choose;
    winTemplate.tilemapLeft = sStarterLabelCoords_starter_choose[selection][0];
    winTemplate.tilemapTop = sStarterLabelCoords_starter_choose[selection][1];

    sStarterLabelWindowId_starter_choose = AddWindow(&winTemplate);
    FillWindowPixelBuffer(sStarterLabelWindowId_starter_choose, PIXEL_FILL(0));

    width = GetStringCenterAlignXOffset(FONT_NARROW, categoryText, 0x68);
    AddTextPrinterParameterized3(sStarterLabelWindowId_starter_choose, FONT_NARROW, width, 1, sTextColors_starter_choose, 0, categoryText);

    width = GetStringCenterAlignXOffset(FONT_NORMAL, speciesName, 0x68);
    AddTextPrinterParameterized3(sStarterLabelWindowId_starter_choose, FONT_NORMAL, width, 17, sTextColors_starter_choose, 0, speciesName);

    PutWindowTilemap(sStarterLabelWindowId_starter_choose);
    ScheduleBgCopyTilemapToVram(0);

    labelLeft = sStarterLabelCoords_starter_choose[selection][0] * 8 - 4;
    labelRight = (sStarterLabelCoords_starter_choose[selection][0] + 13) * 8 + 4;
    labelTop = sStarterLabelCoords_starter_choose[selection][1] * 8;
    labelBottom = (sStarterLabelCoords_starter_choose[selection][1] + 4) * 8;
    SetGpuReg(REG_OFFSET_WIN0H, WIN_RANGE(labelLeft, labelRight));
    SetGpuReg(REG_OFFSET_WIN0V, WIN_RANGE(labelTop, labelBottom));
}

static void ClearStarterLabel_starter_choose(void)
{
    FillWindowPixelBuffer(sStarterLabelWindowId_starter_choose, PIXEL_FILL(0));
    ClearWindowTilemap(sStarterLabelWindowId_starter_choose);
    RemoveWindow(sStarterLabelWindowId_starter_choose);
    sStarterLabelWindowId_starter_choose = WINDOW_NONE;
    SetGpuReg(REG_OFFSET_WIN0H, 0);
    SetGpuReg(REG_OFFSET_WIN0V, 0);
    ScheduleBgCopyTilemapToVram(0);
}

static void Task_MoveStarterChooseCursor_starter_choose(u8 taskId)
{
    ClearStarterLabel_starter_choose();
    gTasks[taskId].func = Task_CreateStarterLabel_starter_choose;
}

static void Task_CreateStarterLabel_starter_choose(u8 taskId)
{
    CreateStarterPokemonLabel_starter_choose(gTasks[taskId].tStarterSelection_starter_choose);
    gTasks[taskId].func = Task_HandleStarterChooseInput_starter_choose;
}

static u8 CreatePokemonFrontSprite_starter_choose(u16 species, u8 x, u8 y)
{
    u8 spriteId;

    spriteId = CreateMonPicSprite_Affine(species, FALSE, 0, MON_PIC_AFFINE_FRONT, x, y, 14, TAG_NONE);
    gSprites[spriteId].oam.priority = 0;
    return spriteId;
}

static void SpriteCB_SelectionHand_starter_choose(struct Sprite *sprite)
{
    // Float up and down above selected Poké Ball
    sprite->x = sCursorCoords_starter_choose[gTasks[sprite->data[0]].tStarterSelection_starter_choose][0];
    sprite->y = sCursorCoords_starter_choose[gTasks[sprite->data[0]].tStarterSelection_starter_choose][1];
    sprite->y2 = Sin(sprite->data[1], 8);
    sprite->data[1] = (u8)(sprite->data[1]) + 4;
}

static void SpriteCB_Pokeball_starter_choose(struct Sprite *sprite)
{
    // Animate Poké Ball if currently selected
    if (gTasks[sprite->sTaskId_starter_choose].tStarterSelection_starter_choose == sprite->sBallId_starter_choose)
        StartSpriteAnimIfDifferent(sprite, 1);
    else
        StartSpriteAnimIfDifferent(sprite, 0);
}

static void SpriteCB_StarterPokemon_starter_choose(struct Sprite *sprite)
{
    // Move sprite to upper center of screen
    if (sprite->x > STARTER_PKMN_POS_X_starter_choose)
        sprite->x -= 4;
    if (sprite->x < STARTER_PKMN_POS_X_starter_choose)
        sprite->x += 4;
    if (sprite->y > STARTER_PKMN_POS_Y_starter_choose)
        sprite->y -= 2;
    if (sprite->y < STARTER_PKMN_POS_Y_starter_choose)
        sprite->y += 2;
}
