{ 
    if (FlagGet(FLAG_SYS_POKEDEX_GET) == TRUE)
        AddStartMenuAction_start_menu(MENU_ACTION_POKEDEX_start_menu);
    
    if (FLAG_SYS_DEXNAV_GET != 0 && FlagGet(FLAG_SYS_DEXNAV_GET))
        AddStartMenuAction_start_menu(MENU_ACTION_DEXNAV_start_menu);
    
    if (FlagGet(FLAG_SYS_POKEMON_GET) == TRUE)
        AddStartMenuAction_start_menu(MENU_ACTION_POKEMON_start_menu);

    AddStartMenuAction_start_menu(MENU_ACTION_BAG_start_menu);

    if (FlagGet(FLAG_SYS_POKENAV_GET) == TRUE)
        AddStartMenuAction_start_menu(MENU_ACTION_POKENAV_start_menu);

    AddStartMenuAction_start_menu(MENU_ACTION_PLAYER_start_menu);
    AddStartMenuAction_start_menu(MENU_ACTION_SAVE_start_menu);
    AddStartMenuAction_start_menu(MENU_ACTION_OPTION_start_menu);
    AddStartMenuAction_start_menu(MENU_ACTION_EXIT_start_menu);
}

