static bool8 SaveStartCallback_start_menu(void)
{
    InitSave_start_menu();
    gMenuCallback = SaveCallback_start_menu;

    return FALSE;
}

static bool8 SaveCallback_start_menu(void)
{
    switch (RunSaveCallback_start_menu())
    {
    case SAVE_IN_PROGRESS_start_menu:
        return FALSE;
    case SAVE_CANCELED_start_menu: // Back to start menu
        ClearDialogWindowAndFrameToTransparent(0, FALSE);
        InitStartMenu_start_menu();
        gMenuCallback = HandleStartMenuInput_start_menu;
        return FALSE;
    case SAVE_SUCCESS_start_menu:
    case SAVE_ERROR_start_menu:    // Close start menu
        ClearDialogWindowAndFrameToTransparent(0, TRUE);
        ScriptUnfreezeObjectEvents();
        UnlockPlayerFieldControls();
        SoftResetInBattlePyramid();
        return TRUE;
    }

    return FALSE;
}

static bool8 BattlePyramidRetireStartCallback_start_menu(void)
{
    InitBattlePyramidRetire_start_menu();
    gMenuCallback = BattlePyramidRetireCallback_start_menu;

    return FALSE;
}

static bool8 BattlePyramidRetireReturnCallback_start_menu(void)
{
    InitStartMenu_start_menu();
    gMenuCallback = HandleStartMenuInput_start_menu;

    return FALSE;
}

static bool8 BattlePyramidRetireCallback_start_menu(void)
{
    switch (RunSaveCallback_start_menu())
    {
    case SAVE_SUCCESS_start_menu: // No (Stay in battle pyramid)
        RemoveExtraStartMenuWindows_start_menu();
        gMenuCallback = BattlePyramidRetireReturnCallback_start_menu;
        return FALSE;
    case SAVE_IN_PROGRESS_start_menu:
        return FALSE;
    case SAVE_CANCELED_start_menu: // Yes (Retire from battle pyramid)
        ClearDialogWindowAndFrameToTransparent(0, TRUE);
        ScriptUnfreezeObjectEvents();
        UnlockPlayerFieldControls();
        ScriptContext_SetupScript(BattlePyramid_Retire);
        return TRUE;
    }

    return FALSE;
}

static void InitSave_start_menu(void)
{
    SaveMapView();
    sSaveDialogCallback = SaveConfirmSaveCallback_start_menu;
    sSavingComplete_start_menu = FALSE;
}

static u8 RunSaveCallback_start_menu(void)
{
    // True if text is still printing
    if (RunTextPrintersAndIsPrinter0Active() == TRUE)
    {
        return SAVE_IN_PROGRESS_start_menu;
    }

    sSavingComplete_start_menu = FALSE;
    return sSaveDialogCallback();
}

void SaveGame(void)
{
    InitSave_start_menu();
    CreateTask(SaveGameTask_start_menu, 0x50);
}

static void ShowSaveMessage_start_menu(const u8 *message, u8 (*saveCallback)(void))
{
    StringExpandPlaceholders(gStringVar4, message);
    LoadMessageBoxAndFrameGfx(0, TRUE);
    AddTextPrinterForMessage_2(TRUE);
    sSavingComplete_start_menu = TRUE;
    sSaveDialogCallback = saveCallback;
}

static void SaveGameTask_start_menu(u8 taskId)
{
    u8 status = RunSaveCallback_start_menu();

    switch (status)
    {
    case SAVE_CANCELED_start_menu:
    case SAVE_ERROR_start_menu:
        gSpecialVar_Result = 0;
        break;
    case SAVE_SUCCESS_start_menu:
        gSpecialVar_Result = status;
        break;
    case SAVE_IN_PROGRESS_start_menu:
        return;
    }

    DestroyTask(taskId);
    ScriptContext_Enable();
}

