{
    ClearDialogWindowAndFrame(0, TRUE);
}

static void HideSaveInfoWindow_start_menu(void)
{
    RemoveSaveInfoWindow_start_menu();
}

static void SaveStartTimer_start_menu(void)
{
    sSaveDialogTimer_start_menu = 60;
}

static bool8 SaveSuccesTimer_start_menu(void)
{
    sSaveDialogTimer_start_menu--;

    if (JOY_HELD(A_BUTTON))
    {
        PlaySE(SE_SELECT);
        return TRUE;
    }
    if (sSaveDialogTimer_start_menu == 0)
    {
        return TRUE;
    }

    return FALSE;
}

static bool8 SaveErrorTimer_start_menu(void)
{
    if (sSaveDialogTimer_start_menu != 0)
    {
        sSaveDialogTimer_start_menu--;
    }
    else if (JOY_HELD(A_BUTTON))
    {
        return TRUE;
    }

    return FALSE;
}

static u8 SaveConfirmSaveCallback_start_menu(void)
{
    ClearStdWindowAndFrame(GetStartMenuWindowId(), FALSE);
    RemoveStartMenuWindow();
    ShowSaveInfoWindow_start_menu();

    if (InBattlePyramid())
    {
        ShowSaveMessage_start_menu(gText_BattlePyramidConfirmRest, SaveYesNoCallback_start_menu);
    }
    else
    {
        ShowSaveMessage_start_menu(gText_ConfirmSave, SaveYesNoCallback_start_menu);
    }

    return SAVE_IN_PROGRESS_start_menu;
}

static u8 SaveYesNoCallback_start_menu(void)
{
    DisplayYesNoMenuDefaultYes(); // Show Yes/No menu
    sSaveDialogCallback = SaveConfirmInputCallback_start_menu;
    return SAVE_IN_PROGRESS_start_menu;
}

static u8 SaveConfirmInputCallback_start_menu(void)
{
    switch (Menu_ProcessInputNoWrapClearOnChoose())
    {
    case 0: // Yes
        switch (gSaveFileStatus)
        {
        case SAVE_STATUS_EMPTY:
        case SAVE_STATUS_CORRUPT:
            if (gDifferentSaveFile == FALSE)
            {
                sSaveDialogCallback = SaveFileExistsCallback_start_menu;
                return SAVE_IN_PROGRESS_start_menu;
            }

            sSaveDialogCallback = SaveSavingMessageCallback_start_menu;
            return SAVE_IN_PROGRESS_start_menu;
        default:
            sSaveDialogCallback = SaveFileExistsCallback_start_menu;
            return SAVE_IN_PROGRESS_start_menu;
        }
    case MENU_B_PRESSED:
    case 1: // No
        HideSaveInfoWindow_start_menu();
        HideSaveMessageWindow_start_menu();
        return SAVE_CANCELED_start_menu;
    }

    return SAVE_IN_PROGRESS_start_menu;
}

// A different save file exists
static u8 SaveFileExistsCallback_start_menu(void)
{
    if (gDifferentSaveFile == TRUE)
    {
        ShowSaveMessage_start_menu(gText_DifferentSaveFile, SaveConfirmOverwriteDefaultNoCallback_start_menu);
    }
    else
    {
        ShowSaveMessage_start_menu(gText_AlreadySavedFile, SaveConfirmOverwriteCallback_start_menu);
    }

    return SAVE_IN_PROGRESS_start_menu;
}

static u8 SaveConfirmOverwriteDefaultNoCallback_start_menu(void)
{
    DisplayYesNoMenuWithDefault(1); // Show Yes/No menu (No selected as default)
    sSaveDialogCallback = SaveOverwriteInputCallback_start_menu;
    return SAVE_IN_PROGRESS_start_menu;
}

static u8 SaveConfirmOverwriteCallback_start_menu(void)
{
    DisplayYesNoMenuDefaultYes(); // Show Yes/No menu
    sSaveDialogCallback = SaveOverwriteInputCallback_start_menu;
    return SAVE_IN_PROGRESS_start_menu;
}

static u8 SaveOverwriteInputCallback_start_menu(void)
{
    switch (Menu_ProcessInputNoWrapClearOnChoose())
    {
    case 0: // Yes
        sSaveDialogCallback = SaveSavingMessageCallback_start_menu;
        return SAVE_IN_PROGRESS_start_menu;
    case MENU_B_PRESSED:
    case 1: // No
        HideSaveInfoWindow_start_menu();
        HideSaveMessageWindow_start_menu();
        return SAVE_CANCELED_start_menu;
    }

    return SAVE_IN_PROGRESS_start_menu;
}

static u8 SaveSavingMessageCallback_start_menu(void)
{
    ShowSaveMessage_start_menu(gText_SavingDontTurnOff, SaveDoSaveCallback_start_menu);
    return SAVE_IN_PROGRESS_start_menu;
}

static u8 SaveDoSaveCallback_start_menu(void)
{
    u8 saveStatus;

    IncrementGameStat(GAME_STAT_SAVED_GAME);
    PausePyramidChallenge();

    if (gDifferentSaveFile == TRUE)
    {
        saveStatus = TrySavingData(SAVE_OVERWRITE_DIFFERENT_FILE);
        gDifferentSaveFile = FALSE;
    }
    else
    {
        saveStatus = TrySavingData(SAVE_NORMAL);
    }

    if (saveStatus == SAVE_STATUS_OK)
        ShowSaveMessage_start_menu(gText_PlayerSavedGame, SaveSuccessCallback_start_menu);
    else
        ShowSaveMessage_start_menu(gText_SaveError, SaveErrorCallback_start_menu);

    SaveStartTimer_start_menu();
    return SAVE_IN_PROGRESS_start_menu;
}

static u8 SaveSuccessCallback_start_menu(void)
{
    if (!IsTextPrinterActive(0))
    {
        PlaySE(SE_SAVE);
        sSaveDialogCallback = SaveReturnSuccessCallback_start_menu;
    }

    return SAVE_IN_PROGRESS_start_menu;
}

static u8 SaveReturnSuccessCallback_start_menu(void)
{
    if (!IsSEPlaying() && SaveSuccesTimer_start_menu())
    {
        HideSaveInfoWindow_start_menu();
        return SAVE_SUCCESS_start_menu;
    }
    else
    {
        return SAVE_IN_PROGRESS_start_menu;
    }
}

static u8 SaveErrorCallback_start_menu(void)
{
    if (!IsTextPrinterActive(0))
    {
        PlaySE(SE_BOO);
        sSaveDialogCallback = SaveReturnErrorCallback_start_menu;
    }

    return SAVE_IN_PROGRESS_start_menu;
}

static u8 SaveReturnErrorCallback_start_menu(void)
{
    if (!SaveErrorTimer_start_menu())
    {
        return SAVE_IN_PROGRESS_start_menu;
    }
    else
    {
        HideSaveInfoWindow_start_menu();
        return SAVE_ERROR_start_menu;
    }
}

