static void ResetTilesetAnimBuffer_tileset_anims(void)
{
    sTilesetDMA3TransferBufferSize_tileset_anims = 0;
    CpuFill32(0, sTilesetDMA3TransferBuffer, sizeof sTilesetDMA3TransferBuffer);
}

static void AppendTilesetAnimToBuffer_tileset_anims(const u16 *src, u16 *dest, u16 size)
{
    if (sTilesetDMA3TransferBufferSize_tileset_anims < 20)
    {
        sTilesetDMA3TransferBuffer[sTilesetDMA3TransferBufferSize_tileset_anims].src = src;
        sTilesetDMA3TransferBuffer[sTilesetDMA3TransferBufferSize_tileset_anims].dest = dest;
        sTilesetDMA3TransferBuffer[sTilesetDMA3TransferBufferSize_tileset_anims].size = size;
        sTilesetDMA3TransferBufferSize_tileset_anims ++;
    }
}

void TransferTilesetAnimsBuffer(void)
{
    int i;

    for (i = 0; i < sTilesetDMA3TransferBufferSize_tileset_anims; i ++)
        DmaCopy16(3, sTilesetDMA3TransferBuffer[i].src, sTilesetDMA3TransferBuffer[i].dest, sTilesetDMA3TransferBuffer[i].size);

    sTilesetDMA3TransferBufferSize_tileset_anims = 0;
}

void InitTilesetAnimations(void)
{
    ResetTilesetAnimBuffer_tileset_anims();
    _InitPrimaryTilesetAnimation_tileset_anims();
    _InitSecondaryTilesetAnimation_tileset_anims();
}

void InitSecondaryTilesetAnimation(void)
{
    _InitSecondaryTilesetAnimation_tileset_anims();
}

void UpdateTilesetAnimations(void)
{
    ResetTilesetAnimBuffer_tileset_anims();
    if (++sPrimaryTilesetAnimCounter_tileset_anims >= sPrimaryTilesetAnimCounterMax_tileset_anims)
        sPrimaryTilesetAnimCounter_tileset_anims = 0;
    if (++sSecondaryTilesetAnimCounter_tileset_anims >= sSecondaryTilesetAnimCounterMax_tileset_anims)
        sSecondaryTilesetAnimCounter_tileset_anims = 0;

    if (sPrimaryTilesetAnimCallback)
        sPrimaryTilesetAnimCallback(sPrimaryTilesetAnimCounter_tileset_anims);
    if (sSecondaryTilesetAnimCallback)
        sSecondaryTilesetAnimCallback(sSecondaryTilesetAnimCounter_tileset_anims);
}

static void _InitPrimaryTilesetAnimation_tileset_anims(void)
{
    sPrimaryTilesetAnimCounter_tileset_anims = 0;
    sPrimaryTilesetAnimCounterMax_tileset_anims = 0;
    sPrimaryTilesetAnimCallback = NULL;
    if (gMapHeader.mapLayout->primaryTileset && gMapHeader.mapLayout->primaryTileset->callback)
        gMapHeader.mapLayout->primaryTileset->callback();
}

static void _InitSecondaryTilesetAnimation_tileset_anims(void)
{
    sSecondaryTilesetAnimCounter_tileset_anims = 0;
    sSecondaryTilesetAnimCounterMax_tileset_anims = 0;
    sSecondaryTilesetAnimCallback = NULL;
    if (gMapHeader.mapLayout->secondaryTileset && gMapHeader.mapLayout->secondaryTileset->callback)
        gMapHeader.mapLayout->secondaryTileset->callback();
}

