// Task data for the main title screen tasks (Task_TitleScreenPhase#)
#define tCounter_title_screen    data[0]
#define tSkipToNext_title_screen data[1]
#define tPointless_title_screen  data[2] // Incremented but never used to do anything.
#define tBg2Y_title_screen       data[3]
#define tBg1Y_title_screen       data[4]

// Sprite data for sVersionBannerLeftSpriteTemplate_title_screen / sVersionBannerRightSpriteTemplate_title_screen
#define sAlphaBlendIdx_title_screen data[0]
#define sParentTaskId_title_screen  data[1]

static void SpriteCB_VersionBannerLeft_title_screen(struct Sprite *sprite)
{
    if (gTasks[sprite->sParentTaskId_title_screen].tSkipToNext_title_screen)
    {
        sprite->oam.objMode = ST_OAM_OBJ_NORMAL;
        sprite->y = VERSION_BANNER_Y_GOAL_title_screen;
    }
    else
    {
        if (sprite->y != VERSION_BANNER_Y_GOAL_title_screen)
            sprite->y++;
        if (sprite->sAlphaBlendIdx_title_screen != 0)
            sprite->sAlphaBlendIdx_title_screen--;
        SetGpuReg(REG_OFFSET_BLDALPHA, gTitleScreenAlphaBlend[sprite->sAlphaBlendIdx_title_screen]);
    }
}

static void SpriteCB_VersionBannerRight_title_screen(struct Sprite *sprite)
{
    if (gTasks[sprite->sParentTaskId_title_screen].tSkipToNext_title_screen)
    {
        sprite->oam.objMode = ST_OAM_OBJ_NORMAL;
        sprite->y = VERSION_BANNER_Y_GOAL_title_screen;
    }
    else
    {
        if (sprite->y != VERSION_BANNER_Y_GOAL_title_screen)
            sprite->y++;
    }
}

// Sprite data for SpriteCB_PressStartCopyrightBanner_title_screen
#define sAnimate_title_screen data[0]
#define sTimer_title_screen   data[1]

static void SpriteCB_PressStartCopyrightBanner_title_screen(struct Sprite *sprite)
{
    if (sprite->sAnimate_title_screen == TRUE)
    {
        // Alternate between hidden and shown every 16th frame
        if (++sprite->sTimer_title_screen & 16)
            sprite->invisible = FALSE;
        else
            sprite->invisible = TRUE;
    }
    else
    {
        sprite->invisible = FALSE;
    }
}

static void CreatePressStartBanner_title_screen(s16 x, s16 y)
{
    u8 i;
    u8 spriteId;

    x -= 64;
    for (i = 0; i < NUM_PRESS_START_FRAMES_title_screen; i++, x += 32)
    {
        spriteId = CreateSprite(&sStartCopyrightBannerSpriteTemplate_title_screen, x, y, 0);
        StartSpriteAnim(&gSprites[spriteId], i);
        gSprites[spriteId].sAnimate_title_screen = TRUE;
    }
}

static void CreateCopyrightBanner_title_screen(s16 x, s16 y)
{
    u8 i;
    u8 spriteId;

    x -= 64;
    for (i = 0; i < NUM_COPYRIGHT_FRAMES_title_screen; i++, x += 32)
    {
        spriteId = CreateSprite(&sStartCopyrightBannerSpriteTemplate_title_screen, x, y, 0);
        StartSpriteAnim(&gSprites[spriteId], i + NUM_PRESS_START_FRAMES_title_screen);
    }
}

#undef sAnimate_title_screen
#undef sTimer_title_screen

// Defines for SpriteCB_PokemonLogoShine_title_screen
enum {
    SHINE_MODE_SINGLE_NO_BG_COLOR_title_screen,
    SHINE_MODE_DOUBLE_title_screen,
    SHINE_MODE_SINGLE_title_screen,
};

#define SHINE_SPEED_title_screen  4

#define sMode_title_screen     data[0]
#define sBgColor_title_screen  data[1]

static void SpriteCB_PokemonLogoShine_title_screen(struct Sprite *sprite)
{
    if (sprite->x < DISPLAY_WIDTH + 32)
    {
        // In any mode except SHINE_MODE_SINGLE_NO_BG_COLOR_title_screen the background
        // color will change, in addition to the shine sprite moving.
        if (sprite->sMode_title_screen != SHINE_MODE_SINGLE_NO_BG_COLOR_title_screen)
        {
            u16 backgroundColor;

            if (sprite->x < DISPLAY_WIDTH / 2)
            {
                // Brighten background color
                if (sprite->sBgColor_title_screen < 31)
                    sprite->sBgColor_title_screen++;
                if (sprite->sBgColor_title_screen < 31)
                    sprite->sBgColor_title_screen++;
            }
            else
            {
                // Darken background color
                if (sprite->sBgColor_title_screen != 0)
                    sprite->sBgColor_title_screen--;
                if (sprite->sBgColor_title_screen != 0)
                    sprite->sBgColor_title_screen--;
            }

            backgroundColor = _RGB(sprite->sBgColor_title_screen, sprite->sBgColor_title_screen, sprite->sBgColor_title_screen);

            // Flash the background green for 4 frames of movement.
            // Otherwise use the updating color.
            if (sprite->x == DISPLAY_WIDTH / 2 + (3 * SHINE_SPEED_title_screen)
             || sprite->x == DISPLAY_WIDTH / 2 + (4 * SHINE_SPEED_title_screen)
             || sprite->x == DISPLAY_WIDTH / 2 + (5 * SHINE_SPEED_title_screen)
             || sprite->x == DISPLAY_WIDTH / 2 + (6 * SHINE_SPEED_title_screen))
                gPlttBufferFaded[0] = RGB(24, 31, 12);
            else
                gPlttBufferFaded[0] = backgroundColor;
        }

        sprite->x += SHINE_SPEED_title_screen;
    }
    else
    {
        // Sprite has moved fully offscreen
        gPlttBufferFaded[0] = RGB_BLACK;
        DestroySprite(sprite);
    }
}

static void SpriteCB_PokemonLogoShine_Fast_title_screen(struct Sprite *sprite)
{
    if (sprite->x < DISPLAY_WIDTH + 32)
        sprite->x += SHINE_SPEED_title_screen * 2;
    else
        DestroySprite(sprite);
}

static void StartPokemonLogoShine_title_screen(u8 mode)
{
    u8 spriteId;

    switch (mode)
    {
    case SHINE_MODE_SINGLE_NO_BG_COLOR_title_screen:
    case SHINE_MODE_SINGLE_title_screen:
        // Create one regular shine sprite.
        // If mode is SHINE_MODE_SINGLE_title_screen it will also change the background color.
        spriteId = CreateSprite(&sPokemonLogoShineSpriteTemplate_title_screen, 0, 68, 0);
        gSprites[spriteId].oam.objMode = ST_OAM_OBJ_WINDOW;
        gSprites[spriteId].sMode_title_screen = mode;
        break;
    case SHINE_MODE_DOUBLE_title_screen:
        // Create an invisible sprite with mode set to update the background color
        spriteId = CreateSprite(&sPokemonLogoShineSpriteTemplate_title_screen, 0, 68, 0);
        gSprites[spriteId].oam.objMode = ST_OAM_OBJ_WINDOW;
        gSprites[spriteId].sMode_title_screen = mode;
        gSprites[spriteId].invisible = TRUE;

        // Create two faster shine sprites
        spriteId = CreateSprite(&sPokemonLogoShineSpriteTemplate_title_screen, 0, 68, 0);
        gSprites[spriteId].callback = SpriteCB_PokemonLogoShine_Fast_title_screen;
        gSprites[spriteId].oam.objMode = ST_OAM_OBJ_WINDOW;

        spriteId = CreateSprite(&sPokemonLogoShineSpriteTemplate_title_screen, -80, 68, 0);
        gSprites[spriteId].callback = SpriteCB_PokemonLogoShine_Fast_title_screen;
        gSprites[spriteId].oam.objMode = ST_OAM_OBJ_WINDOW;
        break;
    }
}

#undef sMode_title_screen
#undef sBgColor_title_screen

static void VBlankCB_title_screen(void)
{
    ScanlineEffect_InitHBlankDmaTransfer();
    LoadOam();
    ProcessSpriteCopyRequests();
    TransferPlttBuffer();
    SetGpuReg(REG_OFFSET_BG1VOFS, gBattle_BG1_Y);
}

void CB2_InitTitleScreen(void)
{
    switch (gMain.state)
    {
    default:
    case 0:
        SetVBlankCallback(NULL);
        SetGpuReg(REG_OFFSET_BLDCNT, 0);
        SetGpuReg(REG_OFFSET_BLDALPHA, 0);
        SetGpuReg(REG_OFFSET_BLDY, 0);
        *((u16 *)PLTT) = RGB_WHITE;
        SetGpuReg(REG_OFFSET_DISPCNT, 0);
        SetGpuReg(REG_OFFSET_BG2CNT, 0);
        SetGpuReg(REG_OFFSET_BG1CNT, 0);
        SetGpuReg(REG_OFFSET_BG0CNT, 0);
        SetGpuReg(REG_OFFSET_BG2HOFS, 0);
        SetGpuReg(REG_OFFSET_BG2VOFS, 0);
        SetGpuReg(REG_OFFSET_BG1HOFS, 0);
        SetGpuReg(REG_OFFSET_BG1VOFS, 0);
        SetGpuReg(REG_OFFSET_BG0HOFS, 0);
        SetGpuReg(REG_OFFSET_BG0VOFS, 0);
        DmaFill16(3, 0, (void *)VRAM, VRAM_SIZE);
        DmaFill32(3, 0, (void *)OAM, OAM_SIZE);
        DmaFill16(3, 0, (void *)(PLTT + 2), PLTT_SIZE - 2);
        ResetPaletteFade();
        gMain.state = 1;
        break;
    case 1:
        // bg2
        LZ77UnCompVram(gTitleScreenPokemonLogoGfx, (void *)(BG_CHAR_ADDR(0)));
        LZ77UnCompVram(gTitleScreenPokemonLogoTilemap, (void *)(BG_SCREEN_ADDR(9)));
        LoadPalette(gTitleScreenBgPalettes, BG_PLTT_ID(0), 15 * PLTT_SIZE_4BPP);
        // bg3
        LZ77UnCompVram(sTitleScreenRayquazaGfx_title_screen, (void *)(BG_CHAR_ADDR(2)));
        LZ77UnCompVram(sTitleScreenRayquazaTilemap_title_screen, (void *)(BG_SCREEN_ADDR(26)));
        // bg1
        LZ77UnCompVram(sTitleScreenCloudsGfx_title_screen, (void *)(BG_CHAR_ADDR(3)));
        LZ77UnCompVram(gTitleScreenCloudsTilemap, (void *)(BG_SCREEN_ADDR(27)));
        ScanlineEffect_Stop();
        ResetTasks();
        ResetSpriteData();
        FreeAllSpritePalettes();
        gReservedSpritePaletteCount = 9;
        LoadCompressedSpriteSheet(&sSpriteSheet_EmeraldVersion_title_screen[0]);
        LoadCompressedSpriteSheet(&sSpriteSheet_PressStart_title_screen[0]);
        LoadCompressedSpriteSheet(&sPokemonLogoShineSpriteSheet_title_screen[0]);
        LoadPalette(gTitleScreenEmeraldVersionPal, OBJ_PLTT_ID(0), PLTT_SIZE_4BPP);
        LoadSpritePalette(&sSpritePalette_PressStart_title_screen[0]);
        gMain.state = 2;
        break;
    case 2:
    {
        u8 taskId = CreateTask(Task_TitleScreenPhase1_title_screen, 0);

        gTasks[taskId].tCounter_title_screen = 256;
        gTasks[taskId].tSkipToNext_title_screen = FALSE;
        gTasks[taskId].tPointless_title_screen = -16;
        gTasks[taskId].tBg2Y_title_screen = -32;
        gMain.state = 3;
        break;
    }
    case 3:
        BeginNormalPaletteFade(PALETTES_ALL, 1, 16, 0, RGB_WHITEALPHA);
        SetVBlankCallback(VBlankCB_title_screen);
        gMain.state = 4;
        break;
    case 4:
        PanFadeAndZoomScreen(DISPLAY_WIDTH / 2, DISPLAY_HEIGHT / 2, 0x100, 0);
        SetGpuReg(REG_OFFSET_BG2X_L, -29 * 256);
        SetGpuReg(REG_OFFSET_BG2X_H, -1);
        SetGpuReg(REG_OFFSET_BG2Y_L, -32 * 256);
        SetGpuReg(REG_OFFSET_BG2Y_H, -1);
        SetGpuReg(REG_OFFSET_WIN0H, 0);
        SetGpuReg(REG_OFFSET_WIN0V, 0);
        SetGpuReg(REG_OFFSET_WIN1H, 0);
        SetGpuReg(REG_OFFSET_WIN1V, 0);
        SetGpuReg(REG_OFFSET_WININ, WININ_WIN0_BG_ALL | WININ_WIN0_OBJ | WININ_WIN1_BG_ALL | WININ_WIN1_OBJ);
        SetGpuReg(REG_OFFSET_WINOUT, WINOUT_WIN01_BG_ALL | WINOUT_WIN01_OBJ | WINOUT_WINOBJ_ALL);
        SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_TGT1_BG2 | BLDCNT_EFFECT_LIGHTEN);
        SetGpuReg(REG_OFFSET_BLDALPHA, 0);
        SetGpuReg(REG_OFFSET_BLDY, 12);
        SetGpuReg(REG_OFFSET_BG0CNT, BGCNT_PRIORITY(3) | BGCNT_CHARBASE(2) | BGCNT_SCREENBASE(26) | BGCNT_16COLOR | BGCNT_TXT256x256);
        SetGpuReg(REG_OFFSET_BG1CNT, BGCNT_PRIORITY(2) | BGCNT_CHARBASE(3) | BGCNT_SCREENBASE(27) | BGCNT_16COLOR | BGCNT_TXT256x256);
        SetGpuReg(REG_OFFSET_BG2CNT, BGCNT_PRIORITY(1) | BGCNT_CHARBASE(0) | BGCNT_SCREENBASE(9) | BGCNT_256COLOR | BGCNT_AFF256x256);
        EnableInterrupts(INTR_FLAG_VBLANK);
        SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_MODE_1
                                    | DISPCNT_OBJ_1D_MAP
                                    | DISPCNT_BG2_ON
                                    | DISPCNT_OBJ_ON
                                    | DISPCNT_WIN0_ON
                                    | DISPCNT_OBJWIN_ON);
        m4aSongNumStart(MUS_TITLE);
        gMain.state = 5;
        break;
    case 5:
        if (!UpdatePaletteFade())
        {
            StartPokemonLogoShine_title_screen(SHINE_MODE_SINGLE_NO_BG_COLOR_title_screen);
            ScanlineEffect_InitWave(0, DISPLAY_HEIGHT, 4, 4, 0, SCANLINE_EFFECT_REG_BG1HOFS, TRUE);
            SetMainCallback2(MainCB2_title_screen);
        }
        break;
    }
}

static void MainCB2_title_screen(void)
{
    RunTasks();
    AnimateSprites();
    BuildOamBuffer();
    UpdatePaletteFade();
}

// Shine the Pokémon logo two more times, and fade in the version banner
static void Task_TitleScreenPhase1_title_screen(u8 taskId)
{
    // Skip to next phase when A, B, Start, or Select is pressed
    if (JOY_NEW(A_B_START_SELECT_title_screen) || gTasks[taskId].tSkipToNext_title_screen)
    {
        gTasks[taskId].tSkipToNext_title_screen = TRUE;
        gTasks[taskId].tCounter_title_screen = 0;
    }

    if (gTasks[taskId].tCounter_title_screen != 0)
    {
        u16 frameNum = gTasks[taskId].tCounter_title_screen;
        if (frameNum == 176)
            StartPokemonLogoShine_title_screen(SHINE_MODE_DOUBLE_title_screen);
        else if (frameNum == 64)
            StartPokemonLogoShine_title_screen(SHINE_MODE_SINGLE_title_screen);

        gTasks[taskId].tCounter_title_screen--;
    }
    else
    {
        u8 spriteId;

        SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_MODE_1 | DISPCNT_OBJ_1D_MAP | DISPCNT_BG2_ON | DISPCNT_OBJ_ON);
        SetGpuReg(REG_OFFSET_WININ, 0);
        SetGpuReg(REG_OFFSET_WINOUT, 0);
        SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_TGT1_OBJ | BLDCNT_EFFECT_BLEND | BLDCNT_TGT2_ALL);
        SetGpuReg(REG_OFFSET_BLDALPHA, BLDALPHA_BLEND(16, 0));
        SetGpuReg(REG_OFFSET_BLDY, 0);

        // Create left side of version banner
        spriteId = CreateSprite(&sVersionBannerLeftSpriteTemplate_title_screen, VERSION_BANNER_LEFT_X_title_screen, VERSION_BANNER_Y_title_screen, 0);
        gSprites[spriteId].sAlphaBlendIdx_title_screen = ARRAY_COUNT(gTitleScreenAlphaBlend);
        gSprites[spriteId].sParentTaskId_title_screen = taskId;

        // Create right side of version banner
        spriteId = CreateSprite(&sVersionBannerRightSpriteTemplate_title_screen, VERSION_BANNER_RIGHT_X_title_screen, VERSION_BANNER_Y_title_screen, 0);
        gSprites[spriteId].sParentTaskId_title_screen = taskId;

        gTasks[taskId].tCounter_title_screen = 144;
        gTasks[taskId].func = Task_TitleScreenPhase2_title_screen;
    }
}

#undef sParentTaskId_title_screen
#undef sAlphaBlendIdx_title_screen

// Create "Press Start" and copyright banners, and slide Pokémon logo up
static void Task_TitleScreenPhase2_title_screen(u8 taskId)
{
    u32 yPos;

    // Skip to next phase when A, B, Start, or Select is pressed
    if (JOY_NEW(A_B_START_SELECT_title_screen) || gTasks[taskId].tSkipToNext_title_screen)
    {
        gTasks[taskId].tSkipToNext_title_screen = TRUE;
        gTasks[taskId].tCounter_title_screen = 0;
    }

    if (gTasks[taskId].tCounter_title_screen != 0)
    {
        gTasks[taskId].tCounter_title_screen--;
    }
    else
    {
        gTasks[taskId].tSkipToNext_title_screen = TRUE;
        SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_TGT1_BG1 | BLDCNT_EFFECT_BLEND | BLDCNT_TGT2_BG0 | BLDCNT_TGT2_BD);
        SetGpuReg(REG_OFFSET_BLDALPHA, BLDALPHA_BLEND(6, 15));
        SetGpuReg(REG_OFFSET_BLDY, 0);
        SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_MODE_1
                                    | DISPCNT_OBJ_1D_MAP
                                    | DISPCNT_BG0_ON
                                    | DISPCNT_BG1_ON
                                    | DISPCNT_BG2_ON
                                    | DISPCNT_OBJ_ON);
        CreatePressStartBanner_title_screen(START_BANNER_X_title_screen, 108);
        CreateCopyrightBanner_title_screen(START_BANNER_X_title_screen, 148);
        gTasks[taskId].tBg1Y_title_screen = 0;
        gTasks[taskId].func = Task_TitleScreenPhase3_title_screen;
    }

    if (!(gTasks[taskId].tCounter_title_screen & 3) && gTasks[taskId].tPointless_title_screen != 0)
        gTasks[taskId].tPointless_title_screen++;
    if (!(gTasks[taskId].tCounter_title_screen & 1) && gTasks[taskId].tBg2Y_title_screen != 0)
        gTasks[taskId].tBg2Y_title_screen++;

    // Slide Pokémon logo up
    yPos = gTasks[taskId].tBg2Y_title_screen * 256;
    SetGpuReg(REG_OFFSET_BG2Y_L, yPos);
    SetGpuReg(REG_OFFSET_BG2Y_H, yPos / 0x10000);

    gTasks[taskId].data[5] = 15; // Unused
    gTasks[taskId].data[6] = 6;  // Unused
}

// Show Rayquaza silhouette and process main title screen input
static void Task_TitleScreenPhase3_title_screen(u8 taskId)
{
    if (JOY_NEW(A_BUTTON) || JOY_NEW(START_BUTTON))
    {
        FadeOutBGM(4);
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_WHITEALPHA);
        SetMainCallback2(CB2_GoToMainMenu_title_screen);
    }
    else if (JOY_HELD(CLEAR_SAVE_BUTTON_COMBO_title_screen) == CLEAR_SAVE_BUTTON_COMBO_title_screen)
    {
        SetMainCallback2(CB2_GoToClearSaveDataScreen_title_screen);
    }
    else if (JOY_HELD(RESET_RTC_BUTTON_COMBO_title_screen) == RESET_RTC_BUTTON_COMBO_title_screen
      && CanResetRTC() == TRUE)
    {
        FadeOutBGM(4);
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
        SetMainCallback2(CB2_GoToResetRtcScreen_title_screen);
    }
    else if (JOY_HELD(BERRY_UPDATE_BUTTON_COMBO_title_screen) == BERRY_UPDATE_BUTTON_COMBO_title_screen)
    {
        FadeOutBGM(4);
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
        SetMainCallback2(CB2_GoToBerryFixScreen_title_screen);
    }
    else
    {
        SetGpuReg(REG_OFFSET_BG2Y_L, 0);
        SetGpuReg(REG_OFFSET_BG2Y_H, 0);
        if (++gTasks[taskId].tCounter_title_screen & 1)
        {
            gTasks[taskId].tBg1Y_title_screen++;
            gBattle_BG1_Y = gTasks[taskId].tBg1Y_title_screen / 2;
            gBattle_BG1_X = 0;
        }
        UpdateLegendaryMarkingColor_title_screen(gTasks[taskId].tCounter_title_screen);
        if ((gMPlayInfo_BGM.status & 0xFFFF) == 0)
        {
            BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_WHITEALPHA);
            SetMainCallback2(CB2_GoToCopyrightScreen_title_screen);
        }
    }
}

static void CB2_GoToMainMenu_title_screen(void)
{
    if (!UpdatePaletteFade())
        SetMainCallback2(CB2_InitMainMenu);
}

static void CB2_GoToCopyrightScreen_title_screen(void)
{
    if (!UpdatePaletteFade())
        SetMainCallback2(CB2_InitCopyrightScreenAfterTitleScreen);
}

static void CB2_GoToClearSaveDataScreen_title_screen(void)
{
    if (!UpdatePaletteFade())
        SetMainCallback2(CB2_InitClearSaveDataScreen);
}

static void CB2_GoToResetRtcScreen_title_screen(void)
{
    if (!UpdatePaletteFade())
        SetMainCallback2(CB2_InitResetRtcScreen);
}

static void CB2_GoToBerryFixScreen_title_screen(void)
{
    if (!UpdatePaletteFade())
    {
        m4aMPlayAllStop();
        SetMainCallback2(CB2_InitBerryFixProgram);
    }
}

static void UpdateLegendaryMarkingColor_title_screen(u8 frameNum)
{
    if ((frameNum % 4) == 0) // Change color every 4th frame
    {
        s32 intensity = Cos(frameNum, 128) + 128;
        s32 r = 31 - ((intensity * 32 - intensity) / 256);
        s32 g = 31 - (intensity * 22 / 256);
        s32 b = 12;

        u16 color = RGB(r, g, b);
        LoadPalette(&color, BG_PLTT_ID(14) + 15, sizeof(color));
   }
}
