static void QueueAction_trade(u16 delay, u8 actionId)
{
    int i;

    for (i = 0; i < (int)ARRAY_COUNT(sTradeMenu->queuedActions); i++)
    {
        // Find first available spot
        if (!sTradeMenu->queuedActions[i].active)
        {
            sTradeMenu->queuedActions[i].delay = delay;
            sTradeMenu->queuedActions[i].actionId = actionId;
            sTradeMenu->queuedActions[i].active = TRUE;
            break;
        }
    }
}

static u32 GetNumQueuedActions_trade(void)
{
    u32 numActions = 0;
    int i;

    for (i = 0; i < (int)ARRAY_COUNT(sTradeMenu->queuedActions); i++)
    {
        numActions += sTradeMenu->queuedActions[i].active;
    }

    return numActions;
}

static void DoQueuedActions_trade(void)
{
    int i;

    for (i = 0; i < (int)ARRAY_COUNT(sTradeMenu->queuedActions); i++)
    {
        if (sTradeMenu->queuedActions[i].active)
        {
            if (sTradeMenu->queuedActions[i].delay != 0)
            {
                sTradeMenu->queuedActions[i].delay--;
            }
            else
            {
                switch (sTradeMenu->queuedActions[i].actionId)
                {
                case QUEUE_SEND_DATA_trade:
                    SendLinkData_trade(sTradeMenu->linkData, 20);
                    break;
                case QUEUE_STANDBY_trade:
                    PrintTradeMessage_trade(MSG_STANDBY_trade);
                    break;
                case QUEUE_ONLY_MON1_trade:
                    PrintTradeMessage_trade(MSG_ONLY_MON1_trade);
                    break;
                case QUEUE_ONLY_MON2_trade:
                case QUEUE_UNUSED1:
                case QUEUE_UNUSED2:
                    PrintTradeMessage_trade(MSG_ONLY_MON2_trade);
                    break;
                case QUEUE_MON_CANT_BE_TRADED_trade:
                    PrintTradeMessage_trade(MSG_MON_CANT_BE_TRADED_trade);
                    break;
                case QUEUE_EGG_CANT_BE_TRADED_trade:
                    PrintTradeMessage_trade(MSG_EGG_CANT_BE_TRADED_trade);
                    break;
                case QUEUE_FRIENDS_MON_CANT_BE_TRADED_trade:
                    PrintTradeMessage_trade(MSG_FRIENDS_MON_CANT_BE_TRADED_trade);
                    break;
                }
                sTradeMenu->queuedActions[i].active = FALSE;
            }
        }
    }
}

