static void VblankCb_TrainerCard_trainer_card(void)
{
    LoadOam();
    ProcessSpriteCopyRequests();
    TransferPlttBuffer();
    BlinkTimeColon_trainer_card();
    if (sData_trainer_card->allowDMACopy)
        DmaCopy16(3, &gScanlineEffectRegBuffers[0], &gScanlineEffectRegBuffers[1], 0x140);
}

static void HblankCb_TrainerCard_trainer_card(void)
{
    u16 backup;
    u16 bgVOffset;

    backup = REG_IME;
    REG_IME = 0;
    bgVOffset = gScanlineEffectRegBuffers[1][REG_VCOUNT & 0xFF];
    REG_BG0VOFS = bgVOffset;
    REG_IME = backup;
}

static void CB2_TrainerCard_trainer_card(void)
{
    RunTasks();
    AnimateSprites();
    BuildOamBuffer();
    UpdatePaletteFade();
}

static void CloseTrainerCard_trainer_card(u8 taskId)
{
    SetMainCallback2(sData_trainer_card->callback2);
    FreeAllWindowBuffers();
    FREE_AND_SET_NULL(sData_trainer_card);
    DestroyTask(taskId);
}

// States for Task_TrainerCard_trainer_card. Skips the initial states, which are done once in order
#define STATE_HANDLE_INPUT_FRONT_trainer_card  10
#define STATE_HANDLE_INPUT_BACK_trainer_card   11
#define STATE_WAIT_FLIP_TO_BACK_trainer_card   12
#define STATE_WAIT_FLIP_TO_FRONT_trainer_card  13
#define STATE_CLOSE_CARD_trainer_card          14
#define STATE_WAIT_LINK_PARTNER_trainer_card   15
#define STATE_CLOSE_CARD_LINK_trainer_card     16

static void Task_TrainerCard_trainer_card(u8 taskId)
{
    switch (sData_trainer_card->mainState)
    {
    // Draw card initially
    case 0:
        if (!IsDma3ManagerBusyWithBgCopy())
        {
            FillWindowPixelBuffer(WIN_CARD_TEXT_trainer_card, PIXEL_FILL(0));
            sData_trainer_card->mainState++;
        }
        break;
    case 1:
        if (PrintAllOnCardFront_trainer_card())
            sData_trainer_card->mainState++;
        break;
    case 2:
        DrawTrainerCardWindow_trainer_card(WIN_CARD_TEXT_trainer_card);
        sData_trainer_card->mainState++;
        break;
    case 3:
        FillWindowPixelBuffer(WIN_TRAINER_PIC_trainer_card, PIXEL_FILL(0));
        CreateTrainerCardTrainerPic_trainer_card();
        DrawTrainerCardWindow_trainer_card(WIN_TRAINER_PIC_trainer_card);
        sData_trainer_card->mainState++;
        break;
    case 4:
        DrawCardScreenBackground_trainer_card(sData_trainer_card->bgTilemap);
        sData_trainer_card->mainState++;
        break;
    case 5:
        DrawCardFrontOrBack_trainer_card(sData_trainer_card->frontTilemap);
        sData_trainer_card->mainState++;
        break;
    case 6:
        DrawStarsAndBadgesOnCard_trainer_card();
        sData_trainer_card->mainState++;
        break;
    // Fade in
    case 7:
        if (gWirelessCommType == 1 && gReceivedRemoteLinkPlayers == TRUE)
        {
            LoadWirelessStatusIndicatorSpriteGfx();
            CreateWirelessStatusIndicatorSprite(DISPLAY_WIDTH - 10, DISPLAY_HEIGHT - 10);
        }
        BlendPalettes(PALETTES_ALL, 16, sData_trainer_card->blendColor);
        BeginNormalPaletteFade(PALETTES_ALL, 0, 16, 0, sData_trainer_card->blendColor);
        SetVBlankCallback(VblankCb_TrainerCard_trainer_card);
        sData_trainer_card->mainState++;
        break;
    case 8:
        if (!UpdatePaletteFade() && !IsDma3ManagerBusyWithBgCopy())
        {
            PlaySE(SE_RG_CARD_OPEN);
            sData_trainer_card->mainState = STATE_HANDLE_INPUT_FRONT_trainer_card;
        }
        break;
    case 9:
        if (!IsSEPlaying())
            sData_trainer_card->mainState++;
        break;
    case STATE_HANDLE_INPUT_FRONT_trainer_card:
        // Blink the : in play time
        if (!gReceivedRemoteLinkPlayers && sData_trainer_card->timeColonNeedDraw)
        {
            PrintTimeOnCard_trainer_card();
            DrawTrainerCardWindow_trainer_card(WIN_CARD_TEXT_trainer_card);
            sData_trainer_card->timeColonNeedDraw = FALSE;
        }
        if (JOY_NEW(A_BUTTON))
        {
            FlipTrainerCard_trainer_card();
            PlaySE(SE_RG_CARD_FLIP);
            sData_trainer_card->mainState = STATE_WAIT_FLIP_TO_BACK_trainer_card;
        }
        else if (JOY_NEW(B_BUTTON))
        {
            if (gReceivedRemoteLinkPlayers && sData_trainer_card->isLink && InUnionRoom() == TRUE)
            {
                sData_trainer_card->mainState = STATE_WAIT_LINK_PARTNER_trainer_card;
            }
            else
            {
                BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, sData_trainer_card->blendColor);
                sData_trainer_card->mainState = STATE_CLOSE_CARD_trainer_card;
            }
        }
        break;
    case STATE_WAIT_FLIP_TO_BACK_trainer_card:
        if (IsCardFlipTaskActive_trainer_card() && Overworld_IsRecvQueueAtMax() != TRUE)
        {
            PlaySE(SE_RG_CARD_OPEN);
            sData_trainer_card->mainState = STATE_HANDLE_INPUT_BACK_trainer_card;
        }
        break;
    case STATE_HANDLE_INPUT_BACK_trainer_card:
        if (JOY_NEW(B_BUTTON))
        {
            if (gReceivedRemoteLinkPlayers && sData_trainer_card->isLink && InUnionRoom() == TRUE)
            {
                sData_trainer_card->mainState = STATE_WAIT_LINK_PARTNER_trainer_card;
            }
            else if (gReceivedRemoteLinkPlayers)
            {
                BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, sData_trainer_card->blendColor);
                sData_trainer_card->mainState = STATE_CLOSE_CARD_trainer_card;
            }
            else
            {
                FlipTrainerCard_trainer_card();
                sData_trainer_card->mainState = STATE_WAIT_FLIP_TO_FRONT_trainer_card;
                PlaySE(SE_RG_CARD_FLIP);
            }
        }
        else if (JOY_NEW(A_BUTTON))
        {
           if (gReceivedRemoteLinkPlayers && sData_trainer_card->isLink && InUnionRoom() == TRUE)
           {
               sData_trainer_card->mainState = STATE_WAIT_LINK_PARTNER_trainer_card;
           }
           else
           {
               BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, sData_trainer_card->blendColor);
               sData_trainer_card->mainState = STATE_CLOSE_CARD_trainer_card;
           }
        }
        break;
    case STATE_WAIT_LINK_PARTNER_trainer_card:
        SetCloseLinkCallback();
        DrawDialogueFrame(WIN_MSG_trainer_card, TRUE);
        AddTextPrinterParameterized(WIN_MSG_trainer_card, FONT_NORMAL, gText_WaitingTrainerFinishReading, 0, 1, 255, 0);
        CopyWindowToVram(WIN_MSG_trainer_card, COPYWIN_FULL);
        sData_trainer_card->mainState = STATE_CLOSE_CARD_LINK_trainer_card;
        break;
    case STATE_CLOSE_CARD_LINK_trainer_card:
        if (!gReceivedRemoteLinkPlayers)
        {
            BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, sData_trainer_card->blendColor);
            sData_trainer_card->mainState = STATE_CLOSE_CARD_trainer_card;
        }
        break;
    case STATE_CLOSE_CARD_trainer_card:
        if (!UpdatePaletteFade())
            CloseTrainerCard_trainer_card(taskId);
        break;
    case STATE_WAIT_FLIP_TO_FRONT_trainer_card:
        if (IsCardFlipTaskActive_trainer_card() && Overworld_IsRecvQueueAtMax() != TRUE)
        {
            sData_trainer_card->mainState = STATE_HANDLE_INPUT_FRONT_trainer_card;
            PlaySE(SE_RG_CARD_OPEN);
        }
        break;
   }
}

static bool8 LoadCardGfx_trainer_card(void)
{
    switch (sData_trainer_card->gfxLoadState)
    {
    case 0:
        if (sData_trainer_card->cardType != CARD_TYPE_FRLG)
            LZ77UnCompWram(gHoennTrainerCardBg_Tilemap, sData_trainer_card->bgTilemap);
        else
            LZ77UnCompWram(gKantoTrainerCardBg_Tilemap, sData_trainer_card->bgTilemap);
        break;
    case 1:
        if (sData_trainer_card->cardType != CARD_TYPE_FRLG)
            LZ77UnCompWram(gHoennTrainerCardBack_Tilemap, sData_trainer_card->backTilemap);
        else
            LZ77UnCompWram(gKantoTrainerCardBack_Tilemap, sData_trainer_card->backTilemap);
        break;
    case 2:
        if (!sData_trainer_card->isLink)
        {
            if (sData_trainer_card->cardType != CARD_TYPE_FRLG)
                LZ77UnCompWram(gHoennTrainerCardFront_Tilemap, sData_trainer_card->frontTilemap);
            else
                LZ77UnCompWram(gKantoTrainerCardFront_Tilemap, sData_trainer_card->frontTilemap);
        }
        else
        {
            if (sData_trainer_card->cardType != CARD_TYPE_FRLG)
                LZ77UnCompWram(gHoennTrainerCardFrontLink_Tilemap, sData_trainer_card->frontTilemap);
            else
                LZ77UnCompWram(gKantoTrainerCardFrontLink_Tilemap, sData_trainer_card->frontTilemap);
        }
        break;
    case 3:
        if (sData_trainer_card->cardType != CARD_TYPE_FRLG)
            LZ77UnCompWram(sHoennTrainerCardBadges_Gfx_trainer_card, sData_trainer_card->badgeTiles);
        else
            LZ77UnCompWram(sKantoTrainerCardBadges_Gfx_trainer_card, sData_trainer_card->badgeTiles);
        break;
    case 4:
        if (sData_trainer_card->cardType != CARD_TYPE_FRLG)
            LZ77UnCompWram(gHoennTrainerCard_Gfx, sData_trainer_card->cardTiles);
        else
            LZ77UnCompWram(gKantoTrainerCard_Gfx, sData_trainer_card->cardTiles);
        break;
    case 5:
        if (sData_trainer_card->cardType == CARD_TYPE_FRLG)
            LZ77UnCompWram(sTrainerCardStickers_Gfx_trainer_card, sData_trainer_card->stickerTiles);
        break;
    default:
        sData_trainer_card->gfxLoadState = 0;
        return TRUE;
    }
    sData_trainer_card->gfxLoadState++;
    return FALSE;
}

static void CB2_InitTrainerCard_trainer_card(void)
{
    switch (gMain.state)
    {
    case 0:
        ResetGpuRegs_trainer_card();
        SetUpTrainerCardTask_trainer_card();
        gMain.state++;
        break;
    case 1:
        DmaClear32(3, (void *)OAM, OAM_SIZE);
        gMain.state++;
        break;
    case 2:
        if (!sData_trainer_card->blendColor)
            DmaClear16(3, (void *)PLTT, PLTT_SIZE);
        gMain.state++;
        break;
    case 3:
        ResetSpriteData();
        FreeAllSpritePalettes();
        ResetPaletteFade();
        gMain.state++;
    case 4:
        InitBgsAndWindows_trainer_card();
        gMain.state++;
        break;
    case 5:
        LoadMonIconGfx_trainer_card();
        gMain.state++;
        break;
    case 6:
        if (LoadCardGfx_trainer_card() == TRUE)
            gMain.state++;
        break;
    case 7:
        LoadStickerGfx_trainer_card();
        gMain.state++;
        break;
    case 8:
        InitGpuRegs_trainer_card();
        gMain.state++;
        break;
    case 9:
        BufferTextsVarsForCardPage2_trainer_card();
        gMain.state++;
        break;
    case 10:
        if (SetCardBgsAndPals_trainer_card() == TRUE)
            gMain.state++;
        break;
    default:
        SetTrainerCardCb2_trainer_card();
        break;
    }
}

static u32 GetCappedGameStat_trainer_card(u8 statId, u32 maxValue)
{
    u32 statValue = GetGameStat(statId);

    return min(maxValue, statValue);
}

static bool8 HasAllFrontierSymbols_trainer_card(void)
{
    u8 i;
    for (i = 0; i < NUM_FRONTIER_FACILITIES; i++)
    {
        if (!FlagGet(FLAG_SYS_TOWER_SILVER + 2 * i) || !FlagGet(FLAG_SYS_TOWER_GOLD + 2 * i))
            return FALSE;
    }
    return TRUE;
}

u32 CountPlayerTrainerStars(void)
{
    u8 stars = 0;

    if (GetGameStat(GAME_STAT_ENTERED_HOF))
        stars++;
    if (HasAllHoennMons())
        stars++;
    if (CountPlayerMuseumPaintings() >= CONTEST_CATEGORIES_COUNT)
        stars++;
    if (HasAllFrontierSymbols_trainer_card())
        stars++;

    return stars;
}

static u8 GetRubyTrainerStars_trainer_card(struct TrainerCard *trainerCard)
{
    u8 stars = 0;

    if (trainerCard->hofDebutHours || trainerCard->hofDebutMinutes || trainerCard->hofDebutSeconds)
        stars++;
    if (trainerCard->caughtAllHoenn)
        stars++;
    if (trainerCard->battleTowerStraightWins > 49)
        stars++;
    if (trainerCard->hasAllPaintings)
        stars++;

    return stars;
}

static void SetPlayerCardData_trainer_card(struct TrainerCard *trainerCard, u8 cardType)
{
    u32 playTime;
    u8 i;

    trainerCard->gender = gSaveBlock2Ptr->playerGender;
    trainerCard->playTimeHours = gSaveBlock2Ptr->playTimeHours;
    trainerCard->playTimeMinutes = gSaveBlock2Ptr->playTimeMinutes;

    playTime = GetGameStat(GAME_STAT_FIRST_HOF_PLAY_TIME);
    if (!GetGameStat(GAME_STAT_ENTERED_HOF))
        playTime = 0;

    trainerCard->hofDebutHours = playTime >> 16;
    trainerCard->hofDebutMinutes = (playTime >> 8) & 0xFF;
    trainerCard->hofDebutSeconds = playTime & 0xFF;
    if ((playTime >> 16) > 999)
    {
        trainerCard->hofDebutHours = 999;
        trainerCard->hofDebutMinutes = 59;
        trainerCard->hofDebutSeconds = 59;
    }

    trainerCard->hasPokedex = FlagGet(FLAG_SYS_POKEDEX_GET);
    trainerCard->caughtAllHoenn = HasAllHoennMons();
    trainerCard->caughtMonsCount = GetCaughtMonsCount_trainer_card();

    trainerCard->trainerId = (gSaveBlock2Ptr->playerTrainerId[1] << 8) | gSaveBlock2Ptr->playerTrainerId[0];

    trainerCard->linkBattleWins = GetCappedGameStat_trainer_card(GAME_STAT_LINK_BATTLE_WINS, 9999);
    trainerCard->linkBattleLosses = GetCappedGameStat_trainer_card(GAME_STAT_LINK_BATTLE_LOSSES, 9999);

    trainerCard->pokemonTrades = GetCappedGameStat_trainer_card(GAME_STAT_POKEMON_TRADES, 0xFFFF);

    trainerCard->money = GetMoney(&gSaveBlock1Ptr->money);

    for (i = 0; i < TRAINER_CARD_PROFILE_LENGTH; i++)
        trainerCard->easyChatProfile[i] = gSaveBlock1Ptr->easyChatProfile[i];

    StringCopy(trainerCard->playerName, gSaveBlock2Ptr->playerName);

    switch (cardType)
    {
    case CARD_TYPE_EMERALD:
        trainerCard->battleTowerWins = 0;
        trainerCard->battleTowerStraightWins = 0;
    // Seems like GF got CARD_TYPE_FRLG and CARD_TYPE_RS wrong.
    case CARD_TYPE_FRLG:
        trainerCard->contestsWithFriends = GetCappedGameStat_trainer_card(GAME_STAT_WON_LINK_CONTEST, 999);
        trainerCard->pokeblocksWithFriends = GetCappedGameStat_trainer_card(GAME_STAT_POKEBLOCKS_WITH_FRIENDS, 0xFFFF);
        if (CountPlayerMuseumPaintings() >= CONTEST_CATEGORIES_COUNT)
            trainerCard->hasAllPaintings = TRUE;
        trainerCard->stars = GetRubyTrainerStars_trainer_card(trainerCard);
        break;
    case CARD_TYPE_RS:
        trainerCard->battleTowerWins = 0;
        trainerCard->battleTowerStraightWins = 0;
        trainerCard->contestsWithFriends = 0;
        trainerCard->pokeblocksWithFriends = 0;
        trainerCard->hasAllPaintings = 0;
        trainerCard->stars = 0;
        break;
    }
}

static void TrainerCard_GenerateCardForPlayer_trainer_card(struct TrainerCard *trainerCard)
{
    memset(trainerCard, 0, sizeof(struct TrainerCard));
    trainerCard->version = GAME_VERSION;
    SetPlayerCardData_trainer_card(trainerCard, CARD_TYPE_EMERALD);
    trainerCard->hasAllFrontierSymbols = HasAllFrontierSymbols_trainer_card();
    trainerCard->frontierBP = gSaveBlock2Ptr->frontier.cardBattlePoints;
    if (trainerCard->hasAllFrontierSymbols)
        trainerCard->stars++;

    if (trainerCard->gender == FEMALE)
        trainerCard->unionRoomClass = gUnionRoomFacilityClasses[(trainerCard->trainerId % NUM_UNION_ROOM_CLASSES) + NUM_UNION_ROOM_CLASSES];
    else
        trainerCard->unionRoomClass = gUnionRoomFacilityClasses[trainerCard->trainerId % NUM_UNION_ROOM_CLASSES];
}

void TrainerCard_GenerateCardForLinkPlayer(struct TrainerCard *trainerCard)
{
    memset(trainerCard, 0, 0x60);
    trainerCard->version = GAME_VERSION;
    SetPlayerCardData_trainer_card(trainerCard, CARD_TYPE_EMERALD);
    trainerCard->linkHasAllFrontierSymbols = HasAllFrontierSymbols_trainer_card();
    *((u16 *)&trainerCard->linkPoints.frontier) = gSaveBlock2Ptr->frontier.cardBattlePoints;
    if (trainerCard->linkHasAllFrontierSymbols)
        trainerCard->stars++;

    if (trainerCard->gender == FEMALE)
        trainerCard->unionRoomClass = gUnionRoomFacilityClasses[(trainerCard->trainerId % NUM_UNION_ROOM_CLASSES) + NUM_UNION_ROOM_CLASSES];
    else
        trainerCard->unionRoomClass = gUnionRoomFacilityClasses[trainerCard->trainerId % NUM_UNION_ROOM_CLASSES];
}

void CopyTrainerCardData(struct TrainerCard *dst, struct TrainerCard *src, u8 gameVersion)
{
    memset(dst, 0, sizeof(struct TrainerCard));
    dst->version = gameVersion;

    switch (VersionToCardType_trainer_card(gameVersion))
    {
    case CARD_TYPE_FRLG:
        memcpy(dst, src, 0x60);
        break;
    case CARD_TYPE_RS:
        memcpy(dst, src, 0x38);
        break;
    case CARD_TYPE_EMERALD:
        memcpy(dst, src, 0x60);
        dst->linkPoints.frontier = 0;
        dst->hasAllFrontierSymbols = src->linkHasAllFrontierSymbols;
        dst->frontierBP = *((u16 *)&src->linkPoints.frontier);
        break;
    }
}

static void SetDataFromTrainerCard_trainer_card(void)
{
    u8 i;
    u32 badgeFlag;

    sData_trainer_card->hasPokedex = FALSE;
    sData_trainer_card->hasHofResult = FALSE;
    sData_trainer_card->hasLinkResults = FALSE;
    sData_trainer_card->hasBattleTowerWins = FALSE;
    sData_trainer_card->unused_E = FALSE;
    sData_trainer_card->unused_F = FALSE;
    sData_trainer_card->hasTrades = FALSE;
    memset(sData_trainer_card->badgeCount, 0, sizeof(sData_trainer_card->badgeCount));
    if (sData_trainer_card->trainerCard.hasPokedex)
        sData_trainer_card->hasPokedex++;

    if (sData_trainer_card->trainerCard.hofDebutHours
     || sData_trainer_card->trainerCard.hofDebutMinutes
     || sData_trainer_card->trainerCard.hofDebutSeconds)
        sData_trainer_card->hasHofResult++;

    if (sData_trainer_card->trainerCard.linkBattleWins || sData_trainer_card->trainerCard.linkBattleLosses)
        sData_trainer_card->hasLinkResults++;
    if (sData_trainer_card->trainerCard.pokemonTrades)
        sData_trainer_card->hasTrades++;
    if (sData_trainer_card->trainerCard.battleTowerWins || sData_trainer_card->trainerCard.battleTowerStraightWins)
        sData_trainer_card->hasBattleTowerWins++;

    for (i = 0, badgeFlag = FLAG_BADGE01_GET; badgeFlag < FLAG_BADGE01_GET + NUM_BADGES; badgeFlag++, i++)
    {
        if (FlagGet(badgeFlag))
            sData_trainer_card->badgeCount[i]++;
    }
}

static void InitGpuRegs_trainer_card(void)
{
    SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_WIN0_ON | DISPCNT_OBJ_ON | DISPCNT_OBJ_1D_MAP);
    ShowBg(0);
    ShowBg(1);
    ShowBg(2);
    ShowBg(3);
    SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_TGT1_BG0 | BLDCNT_EFFECT_DARKEN);
    SetGpuReg(REG_OFFSET_BLDY, 0);
    SetGpuReg(REG_OFFSET_WININ, WININ_WIN0_BG_ALL | WININ_WIN0_OBJ | WININ_WIN0_CLR);
    SetGpuReg(REG_OFFSET_WINOUT, WINOUT_WIN01_BG1 | WINOUT_WIN01_BG2 | WINOUT_WIN01_BG3 | WINOUT_WIN01_OBJ);
    SetGpuReg(REG_OFFSET_WIN0V, DISPLAY_HEIGHT);
    SetGpuReg(REG_OFFSET_WIN0H, DISPLAY_WIDTH);
    if (gReceivedRemoteLinkPlayers)
        EnableInterrupts(INTR_FLAG_VBLANK | INTR_FLAG_HBLANK | INTR_FLAG_VCOUNT | INTR_FLAG_TIMER3 | INTR_FLAG_SERIAL);
    else
        EnableInterrupts(INTR_FLAG_VBLANK | INTR_FLAG_HBLANK);
}

static void UpdateCardFlipRegs_trainer_card(u16 cardTop)
{
    s8 blendY = (cardTop + 40) / 10;

    if (blendY <= 4)
        blendY = 0;
    sData_trainer_card->flipBlendY = blendY;
    SetGpuReg(REG_OFFSET_BLDY, sData_trainer_card->flipBlendY);
    SetGpuReg(REG_OFFSET_WIN0V, WIN_RANGE(sData_trainer_card->cardTop, DISPLAY_HEIGHT - sData_trainer_card->cardTop));
}

static void ResetGpuRegs_trainer_card(void)
{
    SetVBlankCallback(NULL);
    SetHBlankCallback(NULL);
    SetGpuReg(REG_OFFSET_DISPCNT, 0);
    SetGpuReg(REG_OFFSET_BG0CNT, 0);
    SetGpuReg(REG_OFFSET_BG1CNT, 0);
    SetGpuReg(REG_OFFSET_BG2CNT, 0);
    SetGpuReg(REG_OFFSET_BG3CNT, 0);
}

static void InitBgsAndWindows_trainer_card(void)
{
    ResetBgsAndClearDma3BusyFlags(0);
    InitBgsFromTemplates(0, sTrainerCardBgTemplates_trainer_card, ARRAY_COUNT(sTrainerCardBgTemplates_trainer_card));
    ChangeBgX(0, 0, BG_COORD_SET);
    ChangeBgY(0, 0, BG_COORD_SET);
    ChangeBgX(1, 0, BG_COORD_SET);
    ChangeBgY(1, 0, BG_COORD_SET);
    ChangeBgX(2, 0, BG_COORD_SET);
    ChangeBgY(2, 0, BG_COORD_SET);
    ChangeBgX(3, 0, BG_COORD_SET);
    ChangeBgY(3, 0, BG_COORD_SET);
    InitWindows(sTrainerCardWindowTemplates_trainer_card);
    DeactivateAllTextPrinters();
    LoadMessageBoxAndBorderGfx();
}

static void SetTrainerCardCb2_trainer_card(void)
{
    SetMainCallback2(CB2_TrainerCard_trainer_card);
}

static void SetUpTrainerCardTask_trainer_card(void)
{
    ResetTasks();
    ScanlineEffect_Stop();
    CreateTask(Task_TrainerCard_trainer_card, 0);
    InitTrainerCardData_trainer_card();
    SetDataFromTrainerCard_trainer_card();
}

