static const u8 *const  sTimeColonTextColors_trainer_card[] = {sTrainerCardTextColors_trainer_card, sTimeColonInvisibleTextColors_trainer_card};

static void PrintTimeOnCard_trainer_card(void)
{
    u16 hours;
    u16 minutes;
    s32 width;
    u32 x, y, totalWidth;

    if (!sData_trainer_card->isHoenn)
        AddTextPrinterParameterized3(WIN_CARD_TEXT_trainer_card, FONT_NORMAL, 20, 88, sTrainerCardTextColors_trainer_card, TEXT_SKIP_DRAW, gText_TrainerCardTime);
    else
        AddTextPrinterParameterized3(WIN_CARD_TEXT_trainer_card, FONT_NORMAL, 16, 89, sTrainerCardTextColors_trainer_card, TEXT_SKIP_DRAW, gText_TrainerCardTime);

    if (sData_trainer_card->isLink)
    {
        hours = sData_trainer_card->trainerCard.playTimeHours;
        minutes = sData_trainer_card->trainerCard.playTimeMinutes;
    }
    else
    {
        hours = gSaveBlock2Ptr->playTimeHours;
        minutes = gSaveBlock2Ptr->playTimeMinutes;
    }

    if (hours > 999)
        hours = 999;
    if (minutes > 59)
        minutes = 59;
    width = GetStringWidth(FONT_NORMAL, gText_Colon2, 0);

    if (!sData_trainer_card->isHoenn)
    {
        x = 144;
        y = 88;
    }
    else
    {
        x = 128;
        y = 89;
    }
    totalWidth = width + 30;
    x -= totalWidth;

    FillWindowPixelRect(WIN_CARD_TEXT_trainer_card, PIXEL_FILL(0), x, y, totalWidth, 15);
    ConvertIntToDecimalStringN(gStringVar4, hours, STR_CONV_MODE_RIGHT_ALIGN, 3);
    AddTextPrinterParameterized3(WIN_CARD_TEXT_trainer_card, FONT_NORMAL, x, y, sTrainerCardTextColors_trainer_card, TEXT_SKIP_DRAW, gStringVar4);
    x += 18;
    AddTextPrinterParameterized3(WIN_CARD_TEXT_trainer_card, FONT_NORMAL, x, y, sTimeColonTextColors_trainer_card[sData_trainer_card->timeColonInvisible], TEXT_SKIP_DRAW, gText_Colon2);
    x += width;
    ConvertIntToDecimalStringN(gStringVar4, minutes, STR_CONV_MODE_LEADING_ZEROS, 2);
    AddTextPrinterParameterized3(WIN_CARD_TEXT_trainer_card, FONT_NORMAL, x, y, sTrainerCardTextColors_trainer_card, TEXT_SKIP_DRAW, gStringVar4);
}

