static void DrawTrainerCardWindow_trainer_card(u8 windowId)
{
    PutWindowTilemap(windowId);
    CopyWindowToVram(windowId, COPYWIN_FULL);
}

static u8 SetCardBgsAndPals_trainer_card(void)
{
    switch (sData_trainer_card->bgPalLoadState)
    {
    case 0:
        LoadBgTiles(3, sData_trainer_card->badgeTiles, ARRAY_COUNT(sData_trainer_card->badgeTiles), 0);
        break;
    case 1:
        LoadBgTiles(0, sData_trainer_card->cardTiles, 0x1800, 0);
        break;
    case 2:
        if (sData_trainer_card->cardType != CARD_TYPE_FRLG)
        {
            LoadPalette(sHoennTrainerCardPals_trainer_card[sData_trainer_card->trainerCard.stars], BG_PLTT_ID(0), 3 * PLTT_SIZE_4BPP);
            LoadPalette(sHoennTrainerCardBadges_Pal_trainer_card, BG_PLTT_ID(3), PLTT_SIZE_4BPP);
            if (sData_trainer_card->trainerCard.gender != MALE)
                LoadPalette(sHoennTrainerCardFemaleBg_Pal_trainer_card, BG_PLTT_ID(1), PLTT_SIZE_4BPP);
        }
        else
        {
            LoadPalette(sKantoTrainerCardPals_trainer_card[sData_trainer_card->trainerCard.stars], BG_PLTT_ID(0), 3 * PLTT_SIZE_4BPP);
            LoadPalette(sKantoTrainerCardBadges_Pal_trainer_card, BG_PLTT_ID(3), PLTT_SIZE_4BPP);
            if (sData_trainer_card->trainerCard.gender != MALE)
                LoadPalette(sKantoTrainerCardFemaleBg_Pal_trainer_card, BG_PLTT_ID(1), PLTT_SIZE_4BPP);
        }
        LoadPalette(sTrainerCardStar_Pal_trainer_card, BG_PLTT_ID(4), PLTT_SIZE_4BPP);
        break;
    case 3:
        SetBgTilemapBuffer(0, sData_trainer_card->cardTilemapBuffer);
        SetBgTilemapBuffer(2, sData_trainer_card->bgTilemapBuffer);
        break;
    case 4:
        FillBgTilemapBufferRect_Palette0(0, 0, 0, 0, 32, 32);
        FillBgTilemapBufferRect_Palette0(2, 0, 0, 0, 32, 32);
        FillBgTilemapBufferRect_Palette0(3, 0, 0, 0, 32, 32);
    default:
        return 1;
    }
    sData_trainer_card->bgPalLoadState++;
    return 0;
}

static void DrawCardScreenBackground_trainer_card(u16 *ptr)
{
    s16 i, j;
    u16 *dst = sData_trainer_card->bgTilemapBuffer;

    for (i = 0; i < 20; i++)
    {
        for (j = 0; j < 32; j++)
        {
            if (j < 30)
                dst[32 * i + j] = ptr[30 * i + j];
            else
                dst[32 * i + j] = ptr[0];
        }
    }
    CopyBgTilemapBufferToVram(2);
}

static void DrawCardFrontOrBack_trainer_card(u16 *ptr)
{
    s16 i, j;
    u16 *dst = sData_trainer_card->cardTilemapBuffer;

    for (i = 0; i < 20; i++)
    {
        for (j = 0; j < 32; j++)
        {
            if (j < 30)
                dst[32 * i + j] = ptr[30 * i + j];
            else
                dst[32 * i + j] = ptr[0];
        }
    }
    CopyBgTilemapBufferToVram(0);
}

static void DrawStarsAndBadgesOnCard_trainer_card(void)
{
static const u8  yOffsets_trainer_card[] = {7, 7};

    s16 i, x;
    u16 tileNum = 192;
    u8 palNum = 3;

    FillBgTilemapBufferRect(3, 143, 15, yOffsets_trainer_card[sData_trainer_card->isHoenn], sData_trainer_card->trainerCard.stars, 1, 4);
    if (!sData_trainer_card->isLink)
    {
        x = 4;
        for (i = 0; i < NUM_BADGES; i++, tileNum += 2, x += 3)
        {
            if (sData_trainer_card->badgeCount[i])
            {
                FillBgTilemapBufferRect(3, tileNum, x, 15, 1, 1, palNum);
                FillBgTilemapBufferRect(3, tileNum + 1, x + 1, 15, 1, 1, palNum);
                FillBgTilemapBufferRect(3, tileNum + 16, x, 16, 1, 1, palNum);
                FillBgTilemapBufferRect(3, tileNum + 17, x + 1, 16, 1, 1, palNum);
            }
        }
    }
    CopyBgTilemapBufferToVram(3);
}

static void DrawCardBackStats_trainer_card(void)
{
    if (sData_trainer_card->cardType == CARD_TYPE_FRLG)
    {
        if (sData_trainer_card->hasTrades)
        {
            FillBgTilemapBufferRect(3, 141, 27, 9, 1, 1, 1);
            FillBgTilemapBufferRect(3, 157, 27, 10, 1, 1, 1);
        }
        if (sData_trainer_card->trainerCard.linkPoints.berryCrush)
        {
            FillBgTilemapBufferRect(3, 141, 21, 13, 1, 1, 1);
            FillBgTilemapBufferRect(3, 157, 21, 14, 1, 1, 1);
        }
        if (sData_trainer_card->trainerCard.unionRoomNum)
        {
            FillBgTilemapBufferRect(3, 141, 27, 11, 1, 1, 1);
            FillBgTilemapBufferRect(3, 157, 27, 12, 1, 1, 1);
        }
    }
    else
    {
        if (sData_trainer_card->hasTrades)
        {
            FillBgTilemapBufferRect(3, 141, 27, 9, 1, 1, 0);
            FillBgTilemapBufferRect(3, 157, 27, 10, 1, 1, 0);
        }
        if (sData_trainer_card->trainerCard.contestsWithFriends)
        {
            FillBgTilemapBufferRect(3, 141, 27, 13, 1, 1, 0);
            FillBgTilemapBufferRect(3, 157, 27, 14, 1, 1, 0);
        }
        if (sData_trainer_card->hasBattleTowerWins)
        {
            FillBgTilemapBufferRect(3, 141, 17, 15, 1, 1, 0);
            FillBgTilemapBufferRect(3, 157, 17, 16, 1, 1, 0);
            FillBgTilemapBufferRect(3, 140, 27, 15, 1, 1, 0);
            FillBgTilemapBufferRect(3, 156, 27, 16, 1, 1, 0);
        }
    }
    CopyBgTilemapBufferToVram(3);
}

static void BlinkTimeColon_trainer_card(void)
{
    if (++sData_trainer_card->timeColonBlinkTimer > 60)
    {
        sData_trainer_card->timeColonBlinkTimer = 0;
        sData_trainer_card->timeColonInvisible ^= 1;
        sData_trainer_card->timeColonNeedDraw = TRUE;
    }
}

u8 GetTrainerCardStars(u8 cardId)
{
    struct TrainerCard *trainerCards = gTrainerCards;
    return trainerCards[cardId].stars;
}

#define tFlipState_trainer_card data[0]
#define tCardTop_trainer_card   data[1]

static void FlipTrainerCard_trainer_card(void)
{
    u8 taskId = CreateTask(Task_DoCardFlipTask_trainer_card, 0);
    Task_DoCardFlipTask_trainer_card(taskId);
    SetHBlankCallback(HblankCb_TrainerCard_trainer_card);
}

static bool8 IsCardFlipTaskActive_trainer_card(void)
{
    if (FindTaskIdByFunc(Task_DoCardFlipTask_trainer_card) == TASK_NONE)
        return TRUE;
    else
        return FALSE;
}

static void Task_DoCardFlipTask_trainer_card(u8 taskId)
{
    while(sTrainerCardFlipTasks[gTasks[taskId].tFlipState_trainer_card](&gTasks[taskId]))
        ;
}

static bool8 Task_BeginCardFlip_trainer_card(struct Task *task)
{
    u32 i;

    HideBg(1);
    HideBg(3);
    ScanlineEffect_Stop();
    ScanlineEffect_Clear();
    for (i = 0; i < DISPLAY_HEIGHT; i++)
        gScanlineEffectRegBuffers[1][i] = 0;
    task->tFlipState_trainer_card++;
    return FALSE;
}

// Note: Cannot be DISPLAY_HEIGHT / 2, or cardHeight will be 0
#define CARD_FLIP_Y_trainer_card ((DISPLAY_HEIGHT / 2) - 3)

static bool8 Task_AnimateCardFlipDown_trainer_card(struct Task *task)
{
    u32 cardHeight, r5, r10, cardTop, r6, var_24, cardBottom, var;
    s16 i;

    sData_trainer_card->allowDMACopy = FALSE;
    if (task->tCardTop_trainer_card >= CARD_FLIP_Y_trainer_card)
        task->tCardTop_trainer_card = CARD_FLIP_Y_trainer_card;
    else
        task->tCardTop_trainer_card += 7;

    sData_trainer_card->cardTop = task->tCardTop_trainer_card;
    UpdateCardFlipRegs_trainer_card(task->tCardTop_trainer_card);

    cardTop = task->tCardTop_trainer_card;
    cardBottom = DISPLAY_HEIGHT - cardTop;
    cardHeight = cardBottom - cardTop;
    r6 = -cardTop << 16;
    r5 = (DISPLAY_HEIGHT << 16) / cardHeight;
    r5 -= 1 << 16;
    var_24 = r6;
    var_24 += r5 * cardHeight;
    r10 = r5 / cardHeight;
    r5 *= 2;

    for (i = 0; i < cardTop; i++)
        gScanlineEffectRegBuffers[0][i] = -i;
    for (; i < (s16)cardBottom; i++)
    {
        var = r6 >> 16;
        r6 += r5;
        r5 -= r10;
        gScanlineEffectRegBuffers[0][i] = var;
    }
    var = var_24 >> 16;
    for (; i < DISPLAY_HEIGHT; i++)
        gScanlineEffectRegBuffers[0][i] = var;

    sData_trainer_card->allowDMACopy = TRUE;
    if (task->tCardTop_trainer_card >= CARD_FLIP_Y_trainer_card)
        task->tFlipState_trainer_card++;

    return FALSE;
}

static bool8 Task_DrawFlippedCardSide_trainer_card(struct Task *task)
{
    sData_trainer_card->allowDMACopy = FALSE;
    if (Overworld_IsRecvQueueAtMax() == TRUE)
        return FALSE;

    do
    {
        switch (sData_trainer_card->flipDrawState)
        {
        case 0:
            FillWindowPixelBuffer(WIN_CARD_TEXT_trainer_card, PIXEL_FILL(0));
            FillBgTilemapBufferRect_Palette0(3, 0, 0, 0, 0x20, 0x20);
            break;
        case 1:
            if (!sData_trainer_card->onBack)
            {
                if (!PrintAllOnCardBack_trainer_card())
                    return FALSE;
            }
            else
            {
                if (!PrintAllOnCardFront_trainer_card())
                    return FALSE;
            }
            break;
        case 2:
            if (!sData_trainer_card->onBack)
                DrawCardFrontOrBack_trainer_card(sData_trainer_card->backTilemap);
            else
                DrawTrainerCardWindow_trainer_card(WIN_CARD_TEXT_trainer_card);
            break;
        case 3:
            if (!sData_trainer_card->onBack)
                DrawCardBackStats_trainer_card();
            else
                FillWindowPixelBuffer(WIN_TRAINER_PIC_trainer_card, PIXEL_FILL(0));
            break;
        case 4:
            if (sData_trainer_card->onBack)
                CreateTrainerCardTrainerPic_trainer_card();
            break;
        default:
            task->tFlipState_trainer_card++;
            sData_trainer_card->allowDMACopy = TRUE;
            sData_trainer_card->flipDrawState = 0;
            return FALSE;
        }
        sData_trainer_card->flipDrawState++;
    } while (gReceivedRemoteLinkPlayers == 0);

    return FALSE;
}

static bool8 Task_SetCardFlipped_trainer_card(struct Task *task)
{
    sData_trainer_card->allowDMACopy = FALSE;

    // If on back of card, draw front of card because its being flipped
    if (sData_trainer_card->onBack)
    {
        DrawTrainerCardWindow_trainer_card(WIN_TRAINER_PIC_trainer_card);
        DrawCardScreenBackground_trainer_card(sData_trainer_card->bgTilemap);
        DrawCardFrontOrBack_trainer_card(sData_trainer_card->frontTilemap);
        DrawStarsAndBadgesOnCard_trainer_card();
    }
    DrawTrainerCardWindow_trainer_card(WIN_CARD_TEXT_trainer_card);
    sData_trainer_card->onBack ^= 1;
    task->tFlipState_trainer_card++;
    sData_trainer_card->allowDMACopy = TRUE;
    PlaySE(SE_RG_CARD_FLIPPING);
    return FALSE;
}

static bool8 Task_AnimateCardFlipUp_trainer_card(struct Task *task)
{
    u32 cardHeight, r5, r10, cardTop, r6, var_24, cardBottom, var;
    s16 i;

    sData_trainer_card->allowDMACopy = FALSE;
    if (task->tCardTop_trainer_card <= 5)
        task->tCardTop_trainer_card = 0;
    else
        task->tCardTop_trainer_card -= 5;

    sData_trainer_card->cardTop = task->tCardTop_trainer_card;
    UpdateCardFlipRegs_trainer_card(task->tCardTop_trainer_card);

    cardTop = task->tCardTop_trainer_card;
    cardBottom = DISPLAY_HEIGHT - cardTop;
    cardHeight = cardBottom - cardTop;
    r6 = -cardTop << 16;
    r5 = (DISPLAY_HEIGHT << 16) / cardHeight;
    r5 -= 1 << 16;
    var_24 = r6;
    var_24 += r5 * cardHeight;
    r10 = r5 / cardHeight;
    r5 /= 2;

    for (i = 0; i < cardTop; i++)
        gScanlineEffectRegBuffers[0][i] = -i;
    for (; i < (s16)cardBottom; i++)
    {
        var = r6 >> 16;
        r6 += r5;
        r5 += r10;
        gScanlineEffectRegBuffers[0][i] = var;
    }
    var = var_24 >> 16;
    for (; i < DISPLAY_HEIGHT; i++)
        gScanlineEffectRegBuffers[0][i] = var;

    sData_trainer_card->allowDMACopy = TRUE;
    if (task->tCardTop_trainer_card <= 0)
        task->tFlipState_trainer_card++;

    return FALSE;
}

static bool8 Task_EndCardFlip_trainer_card(struct Task *task)
{
    ShowBg(1);
    ShowBg(3);
    SetHBlankCallback(NULL);
    DestroyTask(FindTaskIdByFunc(Task_DoCardFlipTask_trainer_card));
    return FALSE;
}

void ShowPlayerTrainerCard(void (*callback)(void))
{
    sData_trainer_card = AllocZeroed(sizeof(*sData_trainer_card));
    sData_trainer_card->callback2 = callback;
    if (callback == CB2_ReshowFrontierPass)
        sData_trainer_card->blendColor = RGB_WHITE;
    else
        sData_trainer_card->blendColor = RGB_BLACK;

    if (InUnionRoom() == TRUE)
        sData_trainer_card->isLink = TRUE;
    else
        sData_trainer_card->isLink = FALSE;

    sData_trainer_card->language = GAME_LANGUAGE;
    TrainerCard_GenerateCardForPlayer_trainer_card(&sData_trainer_card->trainerCard);
    SetMainCallback2(CB2_InitTrainerCard_trainer_card);
}

void ShowTrainerCardInLink(u8 cardId, void (*callback)(void))
{
    sData_trainer_card = AllocZeroed(sizeof(*sData_trainer_card));
    sData_trainer_card->callback2 = callback;
    sData_trainer_card->isLink = TRUE;
    sData_trainer_card->trainerCard = gTrainerCards[cardId];
    sData_trainer_card->language = gLinkPlayers[cardId].language;
    SetMainCallback2(CB2_InitTrainerCard_trainer_card);
}

static void InitTrainerCardData_trainer_card(void)
{
    u8 i;

    sData_trainer_card->mainState = 0;
    sData_trainer_card->timeColonBlinkTimer = gSaveBlock2Ptr->playTimeVBlanks;
    sData_trainer_card->timeColonInvisible = FALSE;
    sData_trainer_card->onBack = FALSE;
    sData_trainer_card->flipBlendY = 0;
    sData_trainer_card->cardType = GetSetCardType_trainer_card();
    for (i = 0; i < TRAINER_CARD_PROFILE_LENGTH; i++)
        CopyEasyChatWord(sData_trainer_card->easyChatProfile[i], sData_trainer_card->trainerCard.easyChatProfile[i]);
}

static u8 GetSetCardType_trainer_card(void)
{
    if (sData_trainer_card == NULL)
    {
        if (gGameVersion == VERSION_FIRE_RED || gGameVersion == VERSION_LEAF_GREEN)
            return CARD_TYPE_FRLG;
        else if (gGameVersion == VERSION_EMERALD)
            return CARD_TYPE_EMERALD;
        else
            return CARD_TYPE_RS;
    }
    else
    {
        if (sData_trainer_card->trainerCard.version == VERSION_FIRE_RED || sData_trainer_card->trainerCard.version == VERSION_LEAF_GREEN)
        {
            sData_trainer_card->isHoenn = FALSE;
            return CARD_TYPE_FRLG;
        }
        else if (sData_trainer_card->trainerCard.version == VERSION_EMERALD)
        {
            sData_trainer_card->isHoenn = TRUE;
            return CARD_TYPE_EMERALD;
        }
        else
        {
            sData_trainer_card->isHoenn = TRUE;
            return CARD_TYPE_RS;
        }
    }
}

static u8 VersionToCardType_trainer_card(u8 version)
{
    if (version == VERSION_FIRE_RED || version == VERSION_LEAF_GREEN)
        return CARD_TYPE_FRLG;
    else if (version == VERSION_EMERALD)
        return CARD_TYPE_EMERALD;
    else
        return CARD_TYPE_RS;
}

static void CreateTrainerCardTrainerPic_trainer_card(void)
{
    if (InUnionRoom() == TRUE && gReceivedRemoteLinkPlayers == 1)
    {
        CreateTrainerCardTrainerPicSprite(FacilityClassToPicIndex(sData_trainer_card->trainerCard.unionRoomClass),
                    TRUE,
                    sTrainerPicOffset_trainer_card[sData_trainer_card->isHoenn][sData_trainer_card->trainerCard.gender][0],
                    sTrainerPicOffset_trainer_card[sData_trainer_card->isHoenn][sData_trainer_card->trainerCard.gender][1],
                    8,
                    WIN_TRAINER_PIC_trainer_card);
    }
    else
    {
        CreateTrainerCardTrainerPicSprite(FacilityClassToPicIndex(sTrainerPicFacilityClass_trainer_card[sData_trainer_card->cardType][sData_trainer_card->trainerCard.gender]),
                    TRUE,
                    sTrainerPicOffset_trainer_card[sData_trainer_card->isHoenn][sData_trainer_card->trainerCard.gender][0],
                    sTrainerPicOffset_trainer_card[sData_trainer_card->isHoenn][sData_trainer_card->trainerCard.gender][1],
                    8,
                    WIN_TRAINER_PIC_trainer_card);
    }
}
