static void CreateNPCTrainerHillParty_trainer_hill(u16 trainerId, u8 firstMonId)
{
    u8 trId, level;
    s32 i, floorId, partySlot;

    if (trainerId == 0 || trainerId > HILL_TRAINERS_PER_FLOOR)
        return;

    trId = trainerId - 1;
    SetUpDataStruct_trainer_hill();
    level = GetHighestLevelInPlayerParty();
    floorId = GetFloorId_trainer_hill();
    for (i = firstMonId, partySlot = 0; i < firstMonId + PARTY_SIZE / 2; i++, partySlot++)
    {
        u8 id = sTrainerPartySlots_trainer_hill[trId][partySlot];
        struct Pokemon *mon = &gEnemyParty[i];

        CreateBattleTowerMon(mon, &sHillData->floors[floorId].trainers[trId].mons[id]);
        SetTrainerHillMonLevel_trainer_hill(mon, level);
    }

    FreeDataStruct_trainer_hill();
}

void FillHillTrainerParty(void)
{
    ZeroEnemyPartyMons();
    CreateNPCTrainerHillParty_trainer_hill(gTrainerBattleOpponent_A, 0);
}

void FillHillTrainersParties(void)
{
    ZeroEnemyPartyMons();
    CreateNPCTrainerHillParty_trainer_hill(gTrainerBattleOpponent_A, 0);
    CreateNPCTrainerHillParty_trainer_hill(gTrainerBattleOpponent_B, PARTY_SIZE / 2);
}

