u8 FldEff_ExclamationMarkIcon(void)
{
    u8 spriteId = CreateSpriteAtEnd(&sSpriteTemplate_ExclamationQuestionMark_trainer_see, 0, 0, 0x53);

    if (spriteId != MAX_SPRITES)
    {
        SetIconSpriteData_trainer_see(&gSprites[spriteId], FLDEFF_EXCLAMATION_MARK_ICON, 0);
        UpdateSpritePaletteByTemplate(&sSpriteTemplate_ExclamationQuestionMark_trainer_see, &gSprites[spriteId]);
    }

    return 0;
}

u8 FldEff_QuestionMarkIcon(void)
{
    u8 spriteId;
    if (gFieldEffectArguments[7] >= 0)
    {
        // Use follower emotes
        u8 emotion = gFieldEffectArguments[7];
        spriteId = CreateSpriteAtEnd(&sSpriteTemplate_Emote_trainer_see, 0, 0, 0x52);
        if (spriteId == MAX_SPRITES)
            return 0;
        SetIconSpriteData_trainer_see(&gSprites[spriteId], FLDEFF_EMOTE, emotion); // Set animation based on emotion
        UpdateSpritePaletteByTemplate(&sSpriteTemplate_Emote_trainer_see, &gSprites[spriteId]);
        return 0;
    }
    spriteId = CreateSpriteAtEnd(&sSpriteTemplate_ExclamationQuestionMark_trainer_see, 0, 0, 0x52);

    if (spriteId != MAX_SPRITES)
    {
        SetIconSpriteData_trainer_see(&gSprites[spriteId], FLDEFF_QUESTION_MARK_ICON, 1);
        UpdateSpritePaletteByTemplate(&sSpriteTemplate_ExclamationQuestionMark_trainer_see, &gSprites[spriteId]);
    }

    return 0;
}

