static void SetIconSpriteData_trainer_see(struct Sprite *sprite, u16 fldEffId, u8 spriteAnimNum)
{
    sprite->oam.priority = 1;
    sprite->coordOffsetEnabled = 1;

    sprite->sLocalId_trainer_see = gFieldEffectArguments[0];
    sprite->sMapNum_trainer_see = gFieldEffectArguments[1];
    sprite->sMapGroup_trainer_see = gFieldEffectArguments[2];
    sprite->sYVelocity_trainer_see = -5;
    sprite->sFldEffId_trainer_see = fldEffId;

    StartSpriteAnim(sprite, spriteAnimNum);
}

static void SpriteCB_TrainerIcons_trainer_see(struct Sprite *sprite)
{
    u8 objEventId;

    if (TryGetObjectEventIdByLocalIdAndMap(sprite->sLocalId_trainer_see, sprite->sMapNum_trainer_see, sprite->sMapGroup_trainer_see, &objEventId)
     || sprite->animEnded)
    {
        FieldEffectStop(sprite, sprite->sFldEffId_trainer_see);
    }
    else
    {
        struct Sprite *objEventSprite = &gSprites[gObjectEvents[objEventId].spriteId];
        sprite->sYOffset_trainer_see += sprite->sYVelocity_trainer_see;
        sprite->x = objEventSprite->x;
        sprite->y = objEventSprite->y - 16;
        sprite->x2 = objEventSprite->x2;
        sprite->y2 = objEventSprite->y2 + sprite->sYOffset_trainer_see;
        if (sprite->sYOffset_trainer_see)
            sprite->sYVelocity_trainer_see++;
        else
            sprite->sYVelocity_trainer_see = 0;
    }
}

