static void TryStartRandomMassOutbreak_tv(void)
{
    u8 i;
    u16 outbreakIdx;
    TVShow *show;

    if (FlagGet(FLAG_SYS_GAME_CLEAR))
    {
        for (i = 0; i < LAST_TVSHOW_IDX_tv; i++)
        {
            if (gSaveBlock1Ptr->tvShows[i].common.kind == TVSHOW_MASS_OUTBREAK)
                return;
        }
        if (!rbernoulli_tv(1, 200))
        {
            sCurTVShowSlot = FindFirstEmptyNormalTVShowSlot_tv(gSaveBlock1Ptr->tvShows);
            if (sCurTVShowSlot != -1)
            {
                outbreakIdx = Random() % ARRAY_COUNT(sPokeOutbreakSpeciesList_tv);
                show = &gSaveBlock1Ptr->tvShows[sCurTVShowSlot];
                show->massOutbreak.kind = TVSHOW_MASS_OUTBREAK;
                show->massOutbreak.active = TRUE;
                show->massOutbreak.level = sPokeOutbreakSpeciesList_tv[outbreakIdx].level;
                show->massOutbreak.unused1 = 0;
                show->massOutbreak.unused3 = 0;
                show->massOutbreak.species = sPokeOutbreakSpeciesList_tv[outbreakIdx].species;
                show->massOutbreak.unused2 = 0;
                show->massOutbreak.moves[0] = sPokeOutbreakSpeciesList_tv[outbreakIdx].moves[0];
                show->massOutbreak.moves[1] = sPokeOutbreakSpeciesList_tv[outbreakIdx].moves[1];
                show->massOutbreak.moves[2] = sPokeOutbreakSpeciesList_tv[outbreakIdx].moves[2];
                show->massOutbreak.moves[3] = sPokeOutbreakSpeciesList_tv[outbreakIdx].moves[3];
                show->massOutbreak.locationMapNum = sPokeOutbreakSpeciesList_tv[outbreakIdx].location;
                show->massOutbreak.locationMapGroup = 0;
                show->massOutbreak.unused4 = 0;
                show->massOutbreak.probability = 50;
                show->massOutbreak.unused5 = 0;
                show->massOutbreak.daysLeft = 1;
                StorePlayerIdInNormalShow_tv(show);
                show->massOutbreak.language = gGameLanguage;
            }
        }
    }
}

