void TryPutFindThatGamerOnAir(u16 nCoinsPaidOut)
{
    TVShow *show;
    bool8 flag;
    u16 nCoinsWon;

    sCurTVShowSlot = FindFirstEmptyRecordMixTVShowSlot_tv(gSaveBlock1Ptr->tvShows);
    if (sCurTVShowSlot != -1 && IsRecordMixShowAlreadySpawned_tv(TVSHOW_FIND_THAT_GAMER, FALSE) != TRUE)
    {
        flag = FALSE;
        switch (sFindThatGamerWhichGame_tv)
        {
        case SLOT_MACHINE_tv:
            if (nCoinsPaidOut >= sFindThatGamerCoinsSpent_tv + 200)
            {
                flag = TRUE;
                nCoinsWon = nCoinsPaidOut - sFindThatGamerCoinsSpent_tv;
                break;
            }
            if (sFindThatGamerCoinsSpent_tv >= 100 && nCoinsPaidOut <= sFindThatGamerCoinsSpent_tv - 100)
            {
                nCoinsWon = sFindThatGamerCoinsSpent_tv - nCoinsPaidOut;
                break;
            }
            return;
        case ROULETTE_tv:
            if (nCoinsPaidOut >= sFindThatGamerCoinsSpent_tv + 50)
            {
                flag = TRUE;
                nCoinsWon = nCoinsPaidOut - sFindThatGamerCoinsSpent_tv;
                break;
            }
            if (sFindThatGamerCoinsSpent_tv >= 50 && nCoinsPaidOut <= sFindThatGamerCoinsSpent_tv - 50)
            {
                nCoinsWon = sFindThatGamerCoinsSpent_tv - nCoinsPaidOut;
                break;
            }
            return;
        default:
            return;
        }
        show = &gSaveBlock1Ptr->tvShows[sCurTVShowSlot];
        show->findThatGamer.kind = TVSHOW_FIND_THAT_GAMER;
        show->findThatGamer.active = FALSE; // NOTE: Show is not active until passed via Record Mix.
        show->findThatGamer.nCoins = nCoinsWon;
        show->findThatGamer.whichGame = sFindThatGamerWhichGame_tv;
        show->findThatGamer.won = flag;
        StringCopy(show->findThatGamer.playerName, gSaveBlock2Ptr->playerName);
        StorePlayerIdInRecordMixShow_tv(show);
        show->findThatGamer.language = gGameLanguage;
    }
}

