static void PrintNumPlayersWaitingForMsg_union_room(u8 windowId, u8 capacityCode, u8 stringId)
{
    FillWindowPixelBuffer(windowId, PIXEL_FILL(1));
    switch (capacityCode << 8)
    {
    case LINK_GROUP_CAPACITY(0, 2):
        PrintUnionRoomText_union_room(windowId, FONT_NORMAL, sPlayersNeededOrModeTexts[0][stringId - 1], 0, 1, UR_COLOR_DEFAULT_union_room);
        break;
    case LINK_GROUP_CAPACITY(0, 4):
        PrintUnionRoomText_union_room(windowId, FONT_NORMAL, sPlayersNeededOrModeTexts[1][stringId - 1], 0, 1, UR_COLOR_DEFAULT_union_room);
        break;
    case LINK_GROUP_CAPACITY(2, 5):
        PrintUnionRoomText_union_room(windowId, FONT_NORMAL, sPlayersNeededOrModeTexts[2][stringId - 1], 0, 1, UR_COLOR_DEFAULT_union_room);
        break;
    case LINK_GROUP_CAPACITY(3, 5):
        PrintUnionRoomText_union_room(windowId, FONT_NORMAL, sPlayersNeededOrModeTexts[3][stringId - 1], 0, 1, UR_COLOR_DEFAULT_union_room);
        break;
    case LINK_GROUP_CAPACITY(2, 4):
        PrintUnionRoomText_union_room(windowId, FONT_NORMAL, sPlayersNeededOrModeTexts[4][stringId - 1], 0, 1, UR_COLOR_DEFAULT_union_room);
        break;
    }

    CopyWindowToVram(windowId, COPYWIN_GFX);
}

static void PrintPlayerNameAndIdOnWindow_union_room(u8 windowId)
{
    u8 text[30];
    u8 *txtPtr;

    PrintUnionRoomText_union_room(windowId, FONT_NORMAL, gSaveBlock2Ptr->playerName, 0, 1, UR_COLOR_DEFAULT_union_room);
    txtPtr = StringCopy(text, sText_ID);
    ConvertIntToDecimalStringN(txtPtr, ReadAsU16_union_room(gSaveBlock2Ptr->playerTrainerId), STR_CONV_MODE_LEADING_ZEROS, 5);
    PrintUnionRoomText_union_room(windowId, FONT_NORMAL, text, 0, 17, UR_COLOR_DEFAULT_union_room);
}

static void GetAwaitingCommunicationText_union_room(u8 *dst, u8 activity)
{
    switch (activity)
    {
    case ACTIVITY_BATTLE_SINGLE:
    case ACTIVITY_BATTLE_DOUBLE:
    case ACTIVITY_BATTLE_MULTI:
    case ACTIVITY_TRADE:
    case ACTIVITY_POKEMON_JUMP:
    case ACTIVITY_BERRY_CRUSH:
    case ACTIVITY_BERRY_PICK:
    case ACTIVITY_BATTLE_TOWER:
    case ACTIVITY_BATTLE_TOWER_OPEN:
    case ACTIVITY_RECORD_CORNER:
    case ACTIVITY_BERRY_BLENDER:
    case ACTIVITY_WONDER_CARD:
    case ACTIVITY_WONDER_NEWS:
    case ACTIVITY_CONTEST_COOL:
    case ACTIVITY_CONTEST_BEAUTY:
    case ACTIVITY_CONTEST_CUTE:
    case ACTIVITY_CONTEST_SMART:
    case ACTIVITY_CONTEST_TOUGH:
        // BUG: argument *dst isn't used, instead it always prints to gStringVar4
        // not an issue in practice since Gamefreak never used any other arguments here besides gStringVar4
    #ifndef BUGFIX
        StringExpandPlaceholders(gStringVar4, sText_AwaitingCommunication);
    #else
        StringExpandPlaceholders(dst, sText_AwaitingCommunication);
    #endif
        break;
    }
}

static bool32 IsActivityWithVariableGroupSize_union_room(u32 activity)
{
    switch (activity)
    {
    case ACTIVITY_POKEMON_JUMP:
    case ACTIVITY_BERRY_CRUSH:
    case ACTIVITY_BERRY_PICK:
    case ACTIVITY_RECORD_CORNER:
    case ACTIVITY_BERRY_BLENDER:
    case ACTIVITY_CONTEST_COOL:
    case ACTIVITY_CONTEST_BEAUTY:
    case ACTIVITY_CONTEST_CUTE:
    case ACTIVITY_CONTEST_SMART:
    case ACTIVITY_CONTEST_TOUGH:
        return TRUE;
    default:
        return FALSE;
    }
}

void TryBecomeLinkLeader(void)
{
    u8 taskId;
    struct WirelessLink_Leader *data;

    taskId = CreateTask(Task_TryBecomeLinkLeader_union_room, 0);
    sWirelessLinkMain.leader = data = (void *)(gTasks[taskId].data);
    sLeader = data;

    data->state = LL_STATE_INIT_union_room;
    data->textState = 0;
    gSpecialVar_Result = LINKUP_ONGOING;
}

static void Task_TryBecomeLinkLeader_union_room(u8 taskId)
{
    u32 id, val;
    struct WirelessLink_Leader *data = sWirelessLinkMain.leader;

    switch (data->state)
    {
    case LL_STATE_INIT_union_room:
        if (gSpecialVar_0x8004 == LINK_GROUP_BATTLE_TOWER && gSaveBlock2Ptr->frontier.lvlMode == FRONTIER_LVL_OPEN)
            gSpecialVar_0x8004++;
        gPlayerCurrActivity = sLinkGroupToActivityAndCapacity[gSpecialVar_0x8004];
        sPlayerActivityGroupSize_union_room = sLinkGroupToActivityAndCapacity[gSpecialVar_0x8004] >> 8;
        SetHostRfuGameData(gPlayerCurrActivity, 0, FALSE);
        SetWirelessCommType1();
        OpenLink();
        InitializeRfuLinkManager_LinkLeader(GROUP_MAX(sPlayerActivityGroupSize_union_room));
        data->state = LL_STATE_INIT2_union_room;
        break;
    case LL_STATE_INIT2_union_room:
        data->incomingPlayerList = AllocZeroed(RFU_CHILD_MAX * sizeof(struct RfuIncomingPlayer));
        data->playerList = AllocZeroed(MAX_RFU_PLAYERS * sizeof(struct RfuPlayer));
        data->playerListBackup = AllocZeroed(MAX_RFU_PLAYERS * sizeof(struct RfuPlayer));
        ClearIncomingPlayerList_union_room(data->incomingPlayerList, RFU_CHILD_MAX);
        ClearRfuPlayerList_union_room(data->playerList->players, MAX_RFU_PLAYERS);
        CopyHostRfuGameDataAndUsername(&data->playerList->players[0].rfu.data, data->playerList->players[0].rfu.name);
        data->playerList->players[0].timeoutCounter = 0;
        data->playerList->players[0].groupScheduledAnim = UNION_ROOM_SPAWN_IN;
        data->playerList->players[0].useRedText = FALSE;
        data->playerList->players[0].newPlayerCountdown = 0;
        data->listenTaskId = CreateTask_ListenForCompatiblePartners_union_room(data->incomingPlayerList, 0xFF);
        data->bButtonCancelWindowId = AddWindow(&sWindowTemplate_BButtonCancel);
        switch (GROUP_MAX(sPlayerActivityGroupSize_union_room))
        {
        case 2:
        case 3:
        case 4:
            data->listWindowId = AddWindow(&sWindowTemplate_PlayerList);
            break;
        case 5:
            data->listWindowId = AddWindow(&sWindowTemplate_5PlayerList);
            break;
        }
        data->nPlayerModeWindowId = AddWindow(&sWindowTemplate_NumPlayerMode);

        FillWindowPixelBuffer(data->bButtonCancelWindowId, PIXEL_FILL(2));
        PrintUnionRoomText_union_room(data->bButtonCancelWindowId, FONT_SMALL, sText_BButtonCancel, 8, 1, UR_COLOR_CANCEL_union_room);
        PutWindowTilemap(data->bButtonCancelWindowId);
        CopyWindowToVram(data->bButtonCancelWindowId, COPYWIN_GFX);

        DrawStdWindowFrame(data->listWindowId, FALSE);
        gMultiuseListMenuTemplate = sListMenuTemplate_PossibleGroupMembers;
        gMultiuseListMenuTemplate.windowId = data->listWindowId;
        data->listTaskId = ListMenuInit(&gMultiuseListMenuTemplate, 0, 0);

        DrawStdWindowFrame(data->nPlayerModeWindowId, FALSE);
        PutWindowTilemap(data->nPlayerModeWindowId);
        CopyWindowToVram(data->nPlayerModeWindowId, COPYWIN_GFX);

        CopyBgTilemapBufferToVram(0);
        data->playerCount = 1;
        data->state = LL_STATE_GET_AWAITING_PLAYERS_TEXT_union_room;
        break;
    case LL_STATE_GET_AWAITING_PLAYERS_TEXT_union_room:
        StringCopy(gStringVar1, sLinkGroupActivityNameTexts[gPlayerCurrActivity]);
        if (GROUP_MIN(sPlayerActivityGroupSize_union_room) != 0)
        {
            if (data->playerCount > GROUP_MIN(sPlayerActivityGroupSize_union_room) - 1 && GROUP_MAX(sPlayerActivityGroupSize_union_room) != 0)
                StringExpandPlaceholders(gStringVar4, sText_AwaitingLinkPressStart);
            else
                StringExpandPlaceholders(gStringVar4, sText_AwaitingCommunication);
        }
        else
        {
            GetAwaitingCommunicationText_union_room(gStringVar4, gPlayerCurrActivity);
        }

        PrintNumPlayersWaitingForMsg_union_room(data->nPlayerModeWindowId, sPlayerActivityGroupSize_union_room, data->playerCount);
        data->state = LL_STATE_PRINT_AWAITING_PLAYERS_union_room;
        break;
    case LL_STATE_PRINT_AWAITING_PLAYERS_union_room:
        if (PrintOnTextbox_union_room(&data->textState, gStringVar4))
            data->state = LL_STATE_AWAIT_PLAYERS_union_room;
        break;
    case LL_STATE_AWAIT_PLAYERS_union_room:
        Leader_SetStateIfMemberListChanged_union_room(data, LL_STATE_ACCEPT_NEW_MEMBER_PROMPT_union_room, LL_STATE_MEMBER_LEFT_union_room);
        if (JOY_NEW(B_BUTTON))
        {
            if (data->playerCount == 1)
                data->state = LL_STATE_SHUTDOWN_AND_FAIL_union_room;
            else if (GROUP_MIN2(sPlayerActivityGroupSize_union_room) != 0)
                data->state = LL_STATE_CANCEL_WITH_MSG_union_room;
            else
                data->state = LL_STATE_CANCEL_PROMPT_union_room;
        }
        if (GROUP_MIN(sPlayerActivityGroupSize_union_room) != 0
            && data->playerCount > GROUP_MIN(sPlayerActivityGroupSize_union_room) - 1
            && GROUP_MAX(sPlayerActivityGroupSize_union_room) != 0
            && IsRfuCommunicatingWithAllChildren()
            && JOY_NEW(START_BUTTON))
        {
            data->state = LL_STATE_MEMBERS_OK_PROMPT_union_room;
            LinkRfu_StopManagerAndFinalizeSlots();
        }
        if (data->state == LL_STATE_AWAIT_PLAYERS_union_room && RfuTryDisconnectLeavingChildren())
        {
            // At least 1 group member has left or is trying to leave
            data->state = LL_STATE_WAIT_DISCONNECT_CHILD_union_room;
        }
        break;
    case LL_STATE_WAIT_DISCONNECT_CHILD_union_room:
        // Resume after ensuring all members trying to leave have left
        if (!RfuTryDisconnectLeavingChildren())
        {
            data->state = LL_STATE_AWAIT_PLAYERS_union_room;
            data->playerCount = LeaderPrunePlayerList_union_room(data->playerList);
        }
        break;
    case LL_STATE_MEMBER_LEFT_union_room:
        // BUG: sPlayerActivityGroupSize_union_room was meant below, not gPlayerCurrActivity
        //      This will be false for all but ACTIVITY_BATTLE_DOUBLE and ACTIVITY_DECLINE
        //      All this changes is which of two texts gets printed
    #ifdef BUGFIX
        id = (GROUP_MAX(sPlayerActivityGroupSize_union_room) == 2) ? 0 : 1;
    #else
        id = (GROUP_MAX(gPlayerCurrActivity) == 2) ? 1 : 0;
    #endif
        if (PrintOnTextbox_union_room(&data->textState, sPlayerUnavailableTexts[id]))
        {
            data->playerCount = LeaderPrunePlayerList_union_room(data->playerList);
            RedrawListMenu(data->listTaskId);
            data->state = LL_STATE_GET_AWAITING_PLAYERS_TEXT_union_room;
        }
        break;
    case LL_STATE_MEMBER_DISCONNECTED_union_room:
        id = (GROUP_MAX(sPlayerActivityGroupSize_union_room) == 2) ? 0 : 1;
        if (PrintOnTextbox_union_room(&data->textState, sPlayerUnavailableTexts[id]))
        {
            data->state = LL_STATE_SHUTDOWN_AND_RETRY_union_room;
        }
        break;
    case LL_STATE_ACCEPT_NEW_MEMBER_PROMPT_union_room:
        if (PrintOnTextbox_union_room(&data->textState, gStringVar4))
        {
            data->state = LL_STATE_ACCEPT_NEW_MEMBER_PROMPT_HANDLE_INPUT_union_room;
        }
        break;
    case LL_STATE_ACCEPT_NEW_MEMBER_PROMPT_HANDLE_INPUT_union_room:
        switch (UnionRoomHandleYesNo_union_room(&data->textState, HasTrainerLeftPartnersList(ReadAsU16_union_room(data->playerList->players[data->playerCount].rfu.data.compatibility.playerTrainerId), data->playerList->players[data->playerCount].rfu.name)))
        {
        case 0: // YES
            LoadWirelessStatusIndicatorSpriteGfx();
            CreateWirelessStatusIndicatorSprite(0, 0);
            data->joinRequestAnswer = RFU_STATUS_JOIN_GROUP_OK;
            SendRfuStatusToPartner(data->joinRequestAnswer, ReadAsU16_union_room(data->playerList->players[data->playerCount].rfu.data.compatibility.playerTrainerId), data->playerList->players[data->playerCount].rfu.name);
            data->state = LL_STATE_UPDATE_AFTER_JOIN_REQUEST_union_room;
            break;
        case 1: // NO
        case MENU_B_PRESSED:
            data->joinRequestAnswer = RFU_STATUS_JOIN_GROUP_NO;
            SendRfuStatusToPartner(data->joinRequestAnswer, ReadAsU16_union_room(data->playerList->players[data->playerCount].rfu.data.compatibility.playerTrainerId), data->playerList->players[data->playerCount].rfu.name);
            data->state = LL_STATE_UPDATE_AFTER_JOIN_REQUEST_union_room;
            break;
        case -3:
            data->state = LL_STATE_WAIT_DISCONNECT_CHILD_union_room;
            break;
        }
        break;
    case LL_STATE_UPDATE_AFTER_JOIN_REQUEST_union_room:
        val = WaitSendRfuStatusToPartner(ReadAsU16_union_room(data->playerList->players[data->playerCount].rfu.data.compatibility.playerTrainerId), data->playerList->players[data->playerCount].rfu.name);
        if (val == 1) // Send complete
        {
            if (data->joinRequestAnswer == RFU_STATUS_JOIN_GROUP_OK)
            {
                // Sent "OK"
                data->playerList->players[data->playerCount].newPlayerCountdown = 0;
                RedrawListMenu(data->listTaskId);
                data->playerCount++;
                if (data->playerCount == GROUP_MAX(sPlayerActivityGroupSize_union_room))
                {
                    if (GROUP_MIN2(sPlayerActivityGroupSize_union_room) != 0 || data->playerCount == RFU_CHILD_MAX)
                    {
                        data->state = LL_STATE_MEMBERS_OK_PROMPT_union_room;
                    }
                    else
                    {
                        CopyAndTranslatePlayerName_union_room(gStringVar1, &data->playerList->players[data->playerCount - 1]);
                        StringExpandPlaceholders(gStringVar4, sText_AnOKWasSentToPlayer);
                        data->state = LL_STATE_ACCEPTED_FINAL_MEMBER_union_room;
                    }

                    LinkRfu_StopManagerAndFinalizeSlots();
                    PrintNumPlayersWaitingForMsg_union_room(data->nPlayerModeWindowId, sPlayerActivityGroupSize_union_room, data->playerCount);
                }
                else
                {
                    data->state = LL_STATE_GET_AWAITING_PLAYERS_TEXT_union_room;
                }
            }
            else // Member disconnected
            {
                RequestDisconnectSlotByTrainerNameAndId(data->playerList->players[data->playerCount].rfu.name, ReadAsU16_union_room(data->playerList->players[data->playerCount].rfu.data.compatibility.playerTrainerId));
                data->playerList->players[data->playerCount].groupScheduledAnim = UNION_ROOM_SPAWN_NONE;
                LeaderPrunePlayerList_union_room(data->playerList);
                RedrawListMenu(data->listTaskId);
                data->state = LL_STATE_GET_AWAITING_PLAYERS_TEXT_union_room;
            }

            data->joinRequestAnswer = 0;
        }
        else if (val == 2)
        {
            // Disconnect
            RfuSetStatus(RFU_STATUS_OK, 0);
            data->state = LL_STATE_GET_AWAITING_PLAYERS_TEXT_union_room;
        }
        break;
    case LL_STATE_ACCEPTED_FINAL_MEMBER_union_room:
        if (PrintOnTextbox_union_room(&data->textState, gStringVar4))
            data->state = LL_STATE_WAIT_AND_CONFIRM_MEMBERS_union_room;
        break;
    case LL_STATE_WAIT_AND_CONFIRM_MEMBERS_union_room:
        if (++data->delayTimerAfterOk > 120)
            data->state = LL_STATE_CONFIRMED_MEMBERS_union_room;
        break;
    case LL_STATE_MEMBERS_OK_PROMPT_union_room:
        if (PrintOnTextbox_union_room(&data->textState, sText_AreTheseMembersOK))
            data->state = LL_STATE_MEMBERS_OK_PROMPT_HANDLE_INPUT_union_room;
        break;
    case LL_STATE_MEMBERS_OK_PROMPT_HANDLE_INPUT_union_room:
        switch (UnionRoomHandleYesNo_union_room(&data->textState, FALSE))
        {
        case 0: // YES
            data->state = LL_STATE_CONFIRMED_MEMBERS_union_room;
            break;
        case 1: // NO
        case MENU_B_PRESSED:
            if (GROUP_MIN2(sPlayerActivityGroupSize_union_room) != 0)
                data->state = LL_STATE_CANCEL_WITH_MSG_union_room;
            else
                data->state = LL_STATE_CANCEL_PROMPT_union_room;
            break;
        }
        break;
    case LL_STATE_CANCEL_PROMPT_union_room:
        if (PrintOnTextbox_union_room(&data->textState, sText_CancelModeWithTheseMembers))
            data->state = LL_STATE_CANCEL_PROMPT_HANDLE_INPUT_union_room;
        break;
    case LL_STATE_CANCEL_PROMPT_HANDLE_INPUT_union_room:
        switch (UnionRoomHandleYesNo_union_room(&data->textState, FALSE))
        {
        case 0: // YES
            data->state = LL_STATE_SHUTDOWN_AND_FAIL_union_room;
            break;
        case 1: // NO
        case MENU_B_PRESSED:
            if (GROUP_MIN2(sPlayerActivityGroupSize_union_room) != 0)
                data->state = LL_STATE_MEMBERS_OK_PROMPT_union_room;
            else if (data->playerCount == GROUP_MAX(sPlayerActivityGroupSize_union_room))
                data->state = LL_STATE_MEMBERS_OK_PROMPT_union_room;
            else
                data->state = LL_STATE_GET_AWAITING_PLAYERS_TEXT_union_room;
            break;
        }
        break;
    case LL_STATE_CONFIRMED_MEMBERS_union_room:
        if (!Leader_SetStateIfMemberListChanged_union_room(data, LL_STATE_ACCEPT_NEW_MEMBER_PROMPT_union_room, LL_STATE_MEMBER_DISCONNECTED_union_room))
            data->state = LL_STATE_FINAL_MEMBER_CHECK_union_room;
        break;
    case LL_STATE_FINAL_MEMBER_CHECK_union_room:
        if (LmanAcceptSlotFlagIsNotZero())
        {
            if (WaitRfuState(FALSE))
            {
                data->state = LL_STATE_TRY_START_ACTIVITY_union_room;
            }
            else
            {
                if (++data->memberConfirmTimeout > 300)
                {
                    data->state = LL_STATE_MEMBER_DISCONNECTED_union_room;
                    data->textState = 0;
                }
            }
        }
        else
        {
            data->state = LL_STATE_MEMBER_DISCONNECTED_union_room;
            data->textState = 0;
        }
        break;
    case LL_STATE_CANCEL_WITH_MSG_union_room:
        if (PrintOnTextbox_union_room(&data->textState, sText_ModeWithTheseMembersWillBeCanceled))
            data->state = LL_STATE_SHUTDOWN_AND_FAIL_union_room;
        break;
    case LL_STATE_SHUTDOWN_AND_RETRY_union_room:
    case LL_STATE_SHUTDOWN_AND_FAIL_union_room:
        DestroyWirelessStatusIndicatorSprite();
        LinkRfu_Shutdown();
        Leader_DestroyResources_union_room(data);
        data->state++; // LL_STATE_RETRY_union_room or LL_STATE_FAILED_union_room
        break;
    case LL_STATE_FAILED_union_room:
        ScriptContext_Enable();
        DestroyTask(taskId);
        gSpecialVar_Result = LINKUP_FAILED;
        break;
    case LL_STATE_RETRY_union_room:
        ScriptContext_Enable();
        DestroyTask(taskId);
        gSpecialVar_Result = LINKUP_RETRY_ROLE_ASSIGN;
        break;
    case LL_STATE_TRY_START_ACTIVITY_union_room:
        if (RfuHasErrored())
        {
            data->state = LL_STATE_MEMBER_DISCONNECTED_union_room;
        }
        else
        {
            if (gReceivedRemoteLinkPlayers)
            {
                if (IsActivityWithVariableGroupSize_union_room(gPlayerCurrActivity))
                    GetOtherPlayersInfoFlags();
                UpdateGameData_GroupLockedIn(TRUE);
                CreateTask_RunScriptAndFadeToActivity_union_room();
                Leader_DestroyResources_union_room(data);
                DestroyTask(taskId);
            }
        }
        break;
    }
}

static void Leader_DestroyResources_union_room(struct WirelessLink_Leader *data)
{
    ClearWindowTilemap(data->nPlayerModeWindowId);
    ClearStdWindowAndFrame(data->nPlayerModeWindowId, FALSE);
    DestroyListMenuTask(data->listTaskId, 0, 0);
    ClearWindowTilemap(data->bButtonCancelWindowId);
    ClearStdWindowAndFrame(data->listWindowId, FALSE);
    CopyBgTilemapBufferToVram(0);
    RemoveWindow(data->nPlayerModeWindowId);
    RemoveWindow(data->listWindowId);
    RemoveWindow(data->bButtonCancelWindowId);
    DestroyTask(data->listenTaskId);

    Free(data->playerListBackup);
    Free(data->playerList);
    Free(data->incomingPlayerList);
}

