static void Task_CardOrNewsOverWireless_union_room(u8 taskId)
{
    s32 id;
    struct WindowTemplate winTemplate;
    struct WirelessLink_Group *data = sWirelessLinkMain.group;

    switch (data->state)
    {
    case 0:
        SetHostRfuGameData(ACTIVITY_NONE, 0, FALSE);
        SetWirelessCommType1();
        OpenLink();
        InitializeRfuLinkManager_JoinGroup();
        data->incomingPlayerList = AllocZeroed(RFU_CHILD_MAX * sizeof(struct RfuIncomingPlayer));
        data->playerList = AllocZeroed(MAX_RFU_PLAYER_LIST_SIZE * sizeof(struct RfuPlayer));
        data->state = 1;
        break;
    case 1:
        MG_AddMessageTextPrinter(sText_SearchingForWirelessSystemWait);
        data->state = 2;
        break;
    case 2:
        ClearIncomingPlayerList_union_room(data->incomingPlayerList, RFU_CHILD_MAX);
        ClearRfuPlayerList_union_room(data->playerList->players, MAX_RFU_PLAYER_LIST_SIZE);
        data->listenTaskId = CreateTask_ListenForWonderDistributor_union_room(data->incomingPlayerList, data->isWonderNews + LINK_GROUP_WONDER_CARD);

        if (data->showListMenu)
        {
            winTemplate = sWindowTemplate_GroupList;
            winTemplate.baseBlock = GetMysteryGiftBaseBlock();
            data->listWindowId = AddWindow(&winTemplate);

            MG_DrawTextBorder(data->listWindowId);
            gMultiuseListMenuTemplate = sListMenuTemplate_UnionRoomGroups;
            gMultiuseListMenuTemplate.windowId = data->listWindowId;
            data->listTaskId = ListMenuInit(&gMultiuseListMenuTemplate, 0, 0);

            CopyBgTilemapBufferToVram(0);
        }

        data->leaderId = 0;
        data->state = 3;
        break;
    case 3:
        id = GetNewLeaderCandidate_union_room();
        switch (id)
        {
        case 1:
            PlaySE(SE_PC_LOGIN);
        default:
            if (data->showListMenu)
                RedrawListMenu(data->listTaskId);
            break;
        case 0:
            if (data->showListMenu)
                id = ListMenu_ProcessInput(data->listTaskId);
            if (data->refreshTimer > 120)
            {
                if (data->playerList->players[0].groupScheduledAnim == UNION_ROOM_SPAWN_IN && !data->playerList->players[0].rfu.data.startedActivity)
                {
                    if (HasWonderCardOrNewsByLinkGroup_union_room(&data->playerList->players[0].rfu.data, data->isWonderNews + LINK_GROUP_WONDER_CARD))
                    {
                        data->leaderId = 0;
                        data->refreshTimer = 0;
                        LoadWirelessStatusIndicatorSpriteGfx();
                        CreateWirelessStatusIndicatorSprite(0, 0);
                        CreateTask_RfuReconnectWithParent(data->playerList->players[0].rfu.name, ReadAsU16_union_room(data->playerList->players[0].rfu.data.compatibility.playerTrainerId));
                        PlaySE(SE_POKENAV_ON);
                        data->state = 4;
                    }
                    else
                    {
                        PlaySE(SE_BOO);
                        data->state = 10;
                    }
                }
            }
            else if (JOY_NEW(B_BUTTON))
            {
                data->state = 6;
                data->refreshTimer = 0;
            }
            data->refreshTimer++;
            break;
        }
        break;
    case 4:
        MG_AddMessageTextPrinter(sText_AwaitingResponseFromWirelessSystem);
        CopyAndTranslatePlayerName_union_room(gStringVar1, &data->playerList->players[data->leaderId]);
        data->state = 5;
        break;
    case 5:
        if (gReceivedRemoteLinkPlayers)
        {
            gPlayerCurrActivity = data->playerList->players[data->leaderId].rfu.data.activity;
            data->state = 12;
        }

        switch (RfuGetStatus())
        {
        case RFU_STATUS_FATAL_ERROR:
        case RFU_STATUS_CONNECTION_ERROR:
        case RFU_STATUS_JOIN_GROUP_NO:
            data->state = 8;
            break;
        case RFU_STATUS_JOIN_GROUP_OK:
            MG_AddMessageTextPrinter(sText_WirelessLinkEstablished);
            RfuSetStatus(RFU_STATUS_OK, 0);
            break;
        }
        break;
    case 6:
    case 8:
    case 10:
    case 12:
        if (data->showListMenu)
        {
            DestroyListMenuTask(data->listTaskId, 0, 0);
            CopyBgTilemapBufferToVram(0);
            RemoveWindow(data->listWindowId);
        }
        DestroyTask(data->listenTaskId);
        Free(data->playerList);
        Free(data->incomingPlayerList);
        data->state++;
        break;
    case 9:
        if (PrintMysteryGiftMenuMessage(&data->textState, sText_WirelessLinkDropped))
        {
            DestroyWirelessStatusIndicatorSprite();
            DestroyTask(taskId);
            LinkRfu_Shutdown();
            gSpecialVar_Result = LINKUP_FAILED;
        }
        break;
    case 7:
        if (PrintMysteryGiftMenuMessage(&data->textState, sText_WirelessSearchCanceled))
        {
            DestroyWirelessStatusIndicatorSprite();
            DestroyTask(taskId);
            LinkRfu_Shutdown();
            gSpecialVar_Result = LINKUP_FAILED;
        }
        break;
    case 11:
        if (PrintMysteryGiftMenuMessage(&data->textState, sNoWonderSharedTexts[data->isWonderNews]))
        {
            DestroyWirelessStatusIndicatorSprite();
            DestroyTask(taskId);
            LinkRfu_Shutdown();
            gSpecialVar_Result = LINKUP_FAILED;
        }
        break;
    case 13:
        data->state++;
        SetLinkStandbyCallback();
        break;
    case 14:
        if (IsLinkTaskFinished())
            DestroyTask(taskId);
        break;
    }
}

void RunUnionRoom(void)
{
    struct WirelessLink_URoom *uroom;

    ResetHostRfuGameData();
    CreateTask(Task_RunUnionRoom_union_room, 10);

    // dumb line needed to match
    sWirelessLinkMain.uRoom = sWirelessLinkMain.uRoom;

    uroom = AllocZeroed(sizeof(*sWirelessLinkMain.uRoom));
    sWirelessLinkMain.uRoom = uroom;
    sURoom = uroom;

    uroom->state = UR_STATE_INIT_union_room;
    uroom->textState = 0;
    uroom->unknown = 0;
    uroom->unreadPlayerId = 0;

    gSpecialVar_Result = 0;
    ListMenuLoadStdPalAt(BG_PLTT_ID(13), 1);
}

static u16 ReadAsU16_union_room(const u8 *ptr)
{
    return (ptr[1] << 8) | (ptr[0]);
}

static void ScheduleFieldMessageWithFollowupState_union_room(u32 nextState, const u8 *src)
{
    struct WirelessLink_URoom *uroom = sWirelessLinkMain.uRoom;

    uroom->state = UR_STATE_PRINT_MSG_union_room;
    uroom->stateAfterPrint = nextState;
    if (src != gStringVar4)
        StringExpandPlaceholders(gStringVar4, src);
}

static void ScheduleFieldMessageAndExit_union_room(const u8 *src)
{
    struct WirelessLink_URoom *uroom = sWirelessLinkMain.uRoom;

    uroom->state = UR_STATE_PRINT_AND_EXIT_union_room;
    if (src != gStringVar4)
        StringExpandPlaceholders(gStringVar4, src);
}

static void CopyPlayerListToBuffer_union_room(struct WirelessLink_URoom *uroom)
{
    memcpy(&gDecompressionBuffer[sizeof(gDecompressionBuffer) - (MAX_UNION_ROOM_LEADERS * sizeof(struct RfuPlayer))],
            uroom->playerList,
            MAX_UNION_ROOM_LEADERS * sizeof(struct RfuPlayer));
}

static void CopyPlayerListFromBuffer_union_room(struct WirelessLink_URoom *uroom)
{
    memcpy(uroom->playerList,
           &gDecompressionBuffer[sizeof(gDecompressionBuffer) - (MAX_UNION_ROOM_LEADERS * sizeof(struct RfuPlayer))],
           MAX_UNION_ROOM_LEADERS * sizeof(struct RfuPlayer));
}

static void Task_RunUnionRoom_union_room(u8 taskId)
{
    u32 id = 0;
    s32 input = 0;
    s32 playerGender = MALE;
    struct WirelessLink_URoom *uroom = sWirelessLinkMain.uRoom;
    s16 *taskData = gTasks[taskId].data;

    switch (uroom->state)
    {
    case UR_STATE_INIT_union_room:
        uroom->incomingChildList = AllocZeroed(RFU_CHILD_MAX * sizeof(struct RfuIncomingPlayer));
        uroom->incomingParentList = AllocZeroed(RFU_CHILD_MAX * sizeof(struct RfuIncomingPlayer));
        uroom->playerList = AllocZeroed(MAX_UNION_ROOM_LEADERS * sizeof(struct RfuPlayer));
        uroom->spawnPlayer = AllocZeroed(sizeof(struct RfuPlayer));
        ClearRfuPlayerList_union_room(uroom->playerList->players, MAX_UNION_ROOM_LEADERS);
        gPlayerCurrActivity = IN_UNION_ROOM;
        uroom->searchTaskId = CreateTask_SearchForChildOrParent_union_room(uroom->incomingParentList, uroom->incomingChildList, LINK_GROUP_UNION_ROOM_RESUME);
        InitUnionRoomPlayerObjects(uroom->objects);
        SetTilesAroundUnionRoomPlayersPassable();
        uroom->state = UR_STATE_INIT_OBJECTS_union_room;
        break;
    case UR_STATE_INIT_OBJECTS_union_room:
        CreateUnionRoomPlayerSprites(uroom->spriteIds, taskData[0]);
        if (++taskData[0] == MAX_UNION_ROOM_LEADERS)
            uroom->state = UR_STATE_INIT_LINK_union_room;
        break;
    case UR_STATE_INIT_LINK_union_room:
        SetHostRfuGameData(IN_UNION_ROOM, 0, FALSE);
        SetTradeBoardRegisteredMonInfo(sUnionRoomTrade_union_room.type, sUnionRoomTrade_union_room.playerSpecies, sUnionRoomTrade_union_room.playerLevel);
        SetWirelessCommType1();
        OpenLink();
        InitializeRfuLinkManager_EnterUnionRoom();
        ClearRfuPlayerList_union_room(&uroom->spawnPlayer->players[0], 1);
        ClearIncomingPlayerList_union_room(uroom->incomingChildList, RFU_CHILD_MAX);
        ClearIncomingPlayerList_union_room(uroom->incomingParentList, RFU_CHILD_MAX);
        gSpecialVar_Result = 0;
        uroom->state = UR_STATE_CHECK_SELECTING_MON_union_room;
        break;
    case UR_STATE_CHECK_SELECTING_MON_union_room:
        if ((GetPartyMenuType() == PARTY_MENU_TYPE_UNION_ROOM_REGISTER
          || GetPartyMenuType() == PARTY_MENU_TYPE_UNION_ROOM_TRADE)
           && sUnionRoomTrade_union_room.state != URTRADE_STATE_NONE_union_room)
        {
            id = GetCursorSelectionMonId();
            switch (sUnionRoomTrade_union_room.state)
            {
            case URTRADE_STATE_REGISTERING_union_room:
                UpdateGameData_SetActivity(ACTIVITY_PLYRTALK | IN_UNION_ROOM, 0, TRUE);
                if (id >= PARTY_SIZE)
                {
                    ResetUnionRoomTrade_union_room(&sUnionRoomTrade_union_room);
                    SetTradeBoardRegisteredMonInfo(TYPE_NORMAL, SPECIES_NONE, 0);
                    ScheduleFieldMessageAndExit_union_room(sText_RegistrationCanceled);
                }
                else if (!RegisterTradeMonAndGetIsEgg_union_room(GetCursorSelectionMonId(), &sUnionRoomTrade_union_room))
                {
                    ScheduleFieldMessageWithFollowupState_union_room(UR_STATE_REGISTER_REQUEST_TYPE_union_room, sText_ChooseRequestedMonType);
                }
                else
                {
                    uroom->state = UR_STATE_REGISTER_COMPLETE_union_room;
                }
                break;
            case URTRADE_STATE_OFFERING_union_room:
                CopyPlayerListFromBuffer_union_room(uroom);
                taskData[1] = sUnionRoomTrade_union_room.offerPlayerId;
                if (id >= PARTY_SIZE)
                {
                    ScheduleFieldMessageAndExit_union_room(sText_TradeCanceled);
                }
                else
                {
                    UpdateGameData_SetActivity(ACTIVITY_PLYRTALK | IN_UNION_ROOM, 0, TRUE);
                    gPlayerCurrActivity = ACTIVITY_TRADE | IN_UNION_ROOM;
                    RegisterTradeMon_union_room(GetCursorSelectionMonId(), &sUnionRoomTrade_union_room);
                    uroom->state = UR_STATE_TRADE_OFFER_MON_union_room;
                }
                break;
            }
            sUnionRoomTrade_union_room.state = URTRADE_STATE_NONE_union_room;
        }
        else
        {
            uroom->state = UR_STATE_MAIN_union_room;
        }
        break;
    case UR_STATE_MAIN_union_room:
        if (gSpecialVar_Result != 0)
        {
            if (gSpecialVar_Result == UR_INTERACT_ATTENDANT)
            {
                UpdateGameData_SetActivity(ACTIVITY_PLYRTALK | IN_UNION_ROOM, 0, TRUE);
                PlaySE(SE_PC_LOGIN);
                StringCopy(gStringVar1, gSaveBlock2Ptr->playerName);
                uroom->state = UR_STATE_INTERACT_WITH_ATTENDANT_union_room;
                gSpecialVar_Result = 0;
            }
            else if (gSpecialVar_Result == UR_INTERACT_START_MENU)
            {
                UpdateGameData_SetActivity(ACTIVITY_PLYRTALK | IN_UNION_ROOM, 0, TRUE);
                uroom->state = UR_STATE_WAIT_FOR_START_MENU_union_room;
                gSpecialVar_Result = 0;
            }
            else // UR_INTERACT_PLAYER_# (1-8)
            {
                taskData[0] = 0;
                taskData[1] = gSpecialVar_Result - 1;
                uroom->state = UR_STATE_INTERACT_WITH_PLAYER_union_room;
                gSpecialVar_Result = 0;
            }
        }
        else if (ArePlayerFieldControlsLocked() != TRUE)
        {
            if (JOY_NEW(A_BUTTON))
            {
                if (TryInteractWithUnionRoomMember(uroom->playerList, &taskData[0], &taskData[1], uroom->spriteIds))
                {
                    PlaySE(SE_SELECT);
                    StartScriptInteraction_union_room();
                    uroom->state = UR_STATE_INTERACT_WITH_PLAYER_union_room;
                    break;
                }
                else if (IsPlayerFacingTradingBoard_union_room())
                {
                    UpdateGameData_SetActivity(ACTIVITY_PLYRTALK | IN_UNION_ROOM, 0, TRUE);
                    PlaySE(SE_PC_LOGIN);
                    StartScriptInteraction_union_room();
                    StringCopy(gStringVar1, gSaveBlock2Ptr->playerName);
                    uroom->state = UR_STATE_CHECK_TRADING_BOARD_union_room;
                    break;
                }
            }

            switch (HandlePlayerListUpdate_union_room())
            {
            case PLIST_NEW_PLAYER_union_room:
                PlaySE(SE_PC_LOGIN);
            case PLIST_RECENT_UPDATE_union_room:
                ScheduleUnionRoomPlayerRefresh(uroom);
                break;
            case PLIST_CONTACTED_union_room:
                uroom->state = UR_STATE_PLAYER_CONTACTED_YOU_union_room;
                StartScriptInteraction_union_room();
                SetTradeBoardRegisteredMonInfo(TYPE_NORMAL, SPECIES_NONE, 0);
                UpdateGameData_SetActivity(ACTIVITY_NPCTALK | IN_UNION_ROOM, GetActivePartnersInfo_union_room(uroom), FALSE);
                break;
            }
            HandleUnionRoomPlayerRefresh(uroom);
        }
        break;
    case UR_STATE_WAIT_FOR_START_MENU_union_room:
        if (!FuncIsActiveTask(Task_ShowStartMenu))
        {
            UpdateGameData_SetActivity(ACTIVITY_NONE | IN_UNION_ROOM, 0, FALSE);
            uroom->state = UR_STATE_MAIN_union_room;
        }
        break;
    case UR_STATE_INTERACT_WITH_PLAYER_union_room:
        UR_RunTextPrinters_union_room();
        playerGender = GetUnionRoomPlayerGender_union_room(taskData[1], uroom->playerList);
        UpdateGameData_SetActivity(ACTIVITY_PLYRTALK | IN_UNION_ROOM, 0, TRUE);
        switch (UnionRoomGetPlayerInteractionResponse_union_room(uroom->playerList, taskData[0], taskData[1], playerGender))
        {
        case 0: // Player is or was just doing an activity
            uroom->state = UR_STATE_PRINT_AND_EXIT_union_room;
            break;
        case 1: // Link communicating
            TryConnectToUnionRoomParent(uroom->playerList->players[taskData[1]].rfu.name, &uroom->playerList->players[taskData[1]].rfu.data, gPlayerCurrActivity);
            uroom->unreadPlayerId = id; // Should be just 0, but won't match any other way.
            uroom->state = UR_STATE_TRY_COMMUNICATING_union_room;
            break;
        case 2: // Ask to join chat
            ScheduleFieldMessageWithFollowupState_union_room(UR_STATE_RECV_JOIN_CHAT_REQUEST_union_room, gStringVar4);
            break;
        }
        break;
    case UR_STATE_TRY_COMMUNICATING_union_room:
        UR_RunTextPrinters_union_room();
        switch (RfuGetStatus())
        {
        case RFU_STATUS_NEW_CHILD_DETECTED:
            HandleCancelActivity_union_room(TRUE);
            uroom->state = UR_STATE_MAIN_union_room;
            break;
        case RFU_STATUS_FATAL_ERROR:
        case RFU_STATUS_CONNECTION_ERROR:
            if (IsUnionRoomListenTaskActive() == TRUE)
                ScheduleFieldMessageAndExit_union_room(sText_TrainerAppearsBusy);
            else
                ScheduleFieldMessageWithFollowupState_union_room(UR_STATE_CANCEL_ACTIVITY_LINK_ERROR_union_room, sText_TrainerAppearsBusy);

            gPlayerCurrActivity = IN_UNION_ROOM;
            break;
        }

        if (gReceivedRemoteLinkPlayers)
        {
            CreateTrainerCardInBuffer_union_room(gBlockSendBuffer, TRUE);
            CreateTask(Task_ExchangeCards_union_room, 5);
            uroom->state = UR_STATE_COMMUNICATING_WAIT_FOR_DATA_union_room;
        }
        break;
    case UR_STATE_COMMUNICATING_WAIT_FOR_DATA_union_room:
        if (!FuncIsActiveTask(Task_ExchangeCards_union_room))
        {
            if (gPlayerCurrActivity == (ACTIVITY_TRADE | IN_UNION_ROOM))
                ScheduleFieldMessageWithFollowupState_union_room(UR_STATE_SEND_TRADE_REQUST_union_room, sText_AwaitingPlayersResponseAboutTrade);
            else
                uroom->state = UR_STATE_DO_SOMETHING_PROMPT_union_room;
        }
        break;
    case UR_STATE_CANCEL_ACTIVITY_LINK_ERROR_union_room:
        if (!gReceivedRemoteLinkPlayers)
        {
            HandleCancelActivity_union_room(FALSE);
            UpdateUnionRoomMemberFacing(taskData[0], taskData[1], uroom->playerList);
            uroom->state = UR_STATE_INIT_LINK_union_room;
        }
        break;
    case UR_STATE_DO_SOMETHING_PROMPT_union_room:
        id = ConvPartnerUnameAndGetWhetherMetAlready_union_room(&uroom->playerList->players[taskData[1]]);
        playerGender = GetUnionRoomPlayerGender_union_room(taskData[1], uroom->playerList);
        ScheduleFieldMessageWithFollowupState_union_room(UR_STATE_HANDLE_DO_SOMETHING_PROMPT_INPUT_union_room, sHiDoSomethingTexts[id][playerGender]);
        break;
    case UR_STATE_HANDLE_DO_SOMETHING_PROMPT_INPUT_union_room:
        input = ListMenuHandler_AllItemsAvailable_union_room(&uroom->textState,
                                                  &uroom->topListMenuWindowId,
                                                  &uroom->topListMenuId,
                                                  &sWindowTemplate_InviteToActivity,
                                                  &sListMenuTemplate_InviteToActivity);
        if (input != LIST_NOTHING_CHOSEN)
        {
            if (!gReceivedRemoteLinkPlayers)
            {
                uroom->state = UR_STATE_TRAINER_APPEARS_BUSY_union_room;
            }
            else
            {
                uroom->partnerYesNoResponse = 0;
                playerGender = GetUnionRoomPlayerGender_union_room(taskData[1], uroom->playerList);
                if (input == LIST_CANCEL || input == IN_UNION_ROOM)
                {
                    uroom->playerSendBuffer[0] = IN_UNION_ROOM;
                    Rfu_SendPacket(uroom->playerSendBuffer);
                    StringCopy(gStringVar4, sIfYouWantToDoSomethingTexts[gLinkPlayers[0].gender]);
                    uroom->state = UR_STATE_REQUEST_DECLINED_union_room;
                }
                else
                {
                    gPlayerCurrActivity = input;
                    sPlayerActivityGroupSize_union_room = (u32)input >> 8; // Extract capacity from sInviteToActivityMenuItems
                    if (gPlayerCurrActivity == (ACTIVITY_BATTLE_SINGLE | IN_UNION_ROOM) && !HasAtLeastTwoMonsOfLevel30OrLower_union_room())
                    {
                        ScheduleFieldMessageWithFollowupState_union_room(UR_STATE_DO_SOMETHING_PROMPT_union_room, sText_NeedTwoMonsOfLevel30OrLower1);
                    }
                    else
                    {
                        uroom->playerSendBuffer[0] = gPlayerCurrActivity | IN_UNION_ROOM;
                        Rfu_SendPacket(uroom->playerSendBuffer);
                        uroom->state = UR_STATE_SEND_ACTIVITY_REQUEST_union_room;
                    }
                }
            }
        }
        break;
    case UR_STATE_TRAINER_APPEARS_BUSY_union_room:
        StringCopy(gStringVar4, sText_TrainerBattleBusy);
        uroom->state = UR_STATE_CANCEL_REQUEST_PRINT_MSG_union_room;
        break;
    case UR_STATE_SEND_ACTIVITY_REQUEST_union_room:
        PollPartnerYesNoResponse_union_room(uroom);
        playerGender = GetUnionRoomPlayerGender_union_room(taskData[1], uroom->playerList);
        id = GetResponseIdx_InviteToURoomActivity_union_room(uroom->playerSendBuffer[0] & 0x3F);
        if (PrintOnTextbox_union_room(&uroom->textState, sText_WaitOrShowCardTexts[playerGender][id]))
        {
            taskData[3] = 0;
            uroom->state = UR_STATE_WAIT_FOR_RESPONSE_TO_REQUEST_union_room;
        }
        break;
    case UR_STATE_REQUEST_DECLINED_union_room:
        SetCloseLinkCallback();
        uroom->state = UR_STATE_CANCEL_REQUEST_PRINT_MSG_union_room;
        break;
    case UR_STATE_SEND_TRADE_REQUST_union_room:
        uroom->playerSendBuffer[0] = ACTIVITY_TRADE | IN_UNION_ROOM;
        uroom->playerSendBuffer[1] = sUnionRoomTrade_union_room.species;
        uroom->playerSendBuffer[2] = sUnionRoomTrade_union_room.level;
        Rfu_SendPacket(uroom->playerSendBuffer);
        uroom->state = UR_STATE_WAIT_FOR_RESPONSE_TO_REQUEST_union_room;
        break;
    case UR_STATE_WAIT_FOR_RESPONSE_TO_REQUEST_union_room:
        if (!gReceivedRemoteLinkPlayers)
        {
            StringCopy(gStringVar4, sText_TrainerBattleBusy); // Redundant, will be copied again in next state
            uroom->state = UR_STATE_TRAINER_APPEARS_BUSY_union_room;
        }
        else
        {
            PollPartnerYesNoResponse_union_room(uroom);
            if (uroom->partnerYesNoResponse == (ACTIVITY_ACCEPT | IN_UNION_ROOM))
            {
                if (gPlayerCurrActivity == ACTIVITY_CARD)
                {
                    ViewURoomPartnerTrainerCard_union_room(gStringVar4, uroom, FALSE);
                    uroom->state = UR_STATE_PRINT_CARD_INFO_union_room;
                }
                else
                {
                    uroom->state = UR_STATE_PRINT_START_ACTIVITY_MSG_union_room;
                }
            }
            else if (uroom->partnerYesNoResponse == (ACTIVITY_DECLINE | IN_UNION_ROOM))
            {
                uroom->state = UR_STATE_REQUEST_DECLINED_union_room;
                GetURoomActivityRejectMsg_union_room(gStringVar4, gPlayerCurrActivity | IN_UNION_ROOM, gLinkPlayers[0].gender);
                gPlayerCurrActivity = ACTIVITY_NONE;
            }
        }
        break;

    case UR_STATE_DO_SOMETHING_PROMPT_2_union_room: // Identical to UR_STATE_DO_SOMETHING_PROMPT_union_room
        id = ConvPartnerUnameAndGetWhetherMetAlready_union_room(&uroom->playerList->players[taskData[1]]);
        playerGender = GetUnionRoomPlayerGender_union_room(taskData[1], uroom->playerList);
        ScheduleFieldMessageWithFollowupState_union_room(UR_STATE_HANDLE_DO_SOMETHING_PROMPT_INPUT_union_room, sHiDoSomethingTexts[id][playerGender]);
        break;
    case UR_STATE_PRINT_CARD_INFO_union_room:
        if (PrintOnTextbox_union_room(&uroom->textState, gStringVar4))
        {
            uroom->state = UR_STATE_WAIT_FINISH_READING_CARD_union_room;
            SetLinkStandbyCallback();
            uroom->partnerYesNoResponse = 0;
            uroom->recvActivityRequest[0] = 0;
        }
        break;
    case UR_STATE_WAIT_FINISH_READING_CARD_union_room:
        if (IsLinkTaskFinished())
        {
            if (GetMultiplayerId() == 0)
            {
                StringCopy(gStringVar1, gLinkPlayers[GetMultiplayerId() ^ 1].name);
                id = PlayerHasMetTrainerBefore(gLinkPlayers[1].trainerId, gLinkPlayers[1].name);
                StringExpandPlaceholders(gStringVar4, sAwaitingResponseTexts[id]);
                uroom->state = UR_STATE_PRINT_CONTACT_MSG_union_room;
            }
            else
            {
                uroom->state = UR_STATE_DO_SOMETHING_PROMPT_2_union_room;
            }
        }
        break;
    case UR_STATE_RECV_JOIN_CHAT_REQUEST_union_room:
        switch (UnionRoomHandleYesNo_union_room(&uroom->textState, FALSE))
        {
        case 0: // YES
            CopyBgTilemapBufferToVram(0);
            gPlayerCurrActivity = ACTIVITY_CHAT | IN_UNION_ROOM;
            UpdateGameData_SetActivity(ACTIVITY_CHAT | IN_UNION_ROOM, 0, TRUE);
            TryConnectToUnionRoomParent(uroom->playerList->players[taskData[1]].rfu.name, &uroom->playerList->players[taskData[1]].rfu.data, gPlayerCurrActivity);
            uroom->unreadPlayerId = taskData[1];
            uroom->state = UR_STATE_TRY_ACCEPT_CHAT_REQUEST_DELAY_union_room;
            taskData[3] = 0;
            break;
        case 1: // NO
        case MENU_B_PRESSED:
            playerGender = GetUnionRoomPlayerGender_union_room(taskData[1], uroom->playerList);
            ScheduleFieldMessageAndExit_union_room(sDeclineChatTexts[playerGender]);
            break;
        }
        break;
    case UR_STATE_TRY_ACCEPT_CHAT_REQUEST_DELAY_union_room:
        if (++taskData[2] > 60)
        {
            uroom->state = UR_STATE_TRY_ACCEPT_CHAT_REQUEST_union_room;
            taskData[2] = 0;
        }
        break;
    case UR_STATE_TRY_ACCEPT_CHAT_REQUEST_union_room:
        switch (RfuGetStatus())
        {
        case RFU_STATUS_NEW_CHILD_DETECTED:
            HandleCancelActivity_union_room(TRUE);
            uroom->state = UR_STATE_MAIN_union_room;
            break;
        case RFU_STATUS_FATAL_ERROR:
        case RFU_STATUS_CONNECTION_ERROR:
            playerGender = GetUnionRoomPlayerGender_union_room(taskData[1], uroom->playerList);
            UpdateGameData_SetActivity(ACTIVITY_PLYRTALK | IN_UNION_ROOM, 0, TRUE);
            if (IsUnionRoomListenTaskActive() == TRUE)
                ScheduleFieldMessageAndExit_union_room(sChatDeclinedTexts[playerGender]);
            else
                ScheduleFieldMessageWithFollowupState_union_room(UR_STATE_CANCEL_ACTIVITY_LINK_ERROR_union_room, sChatDeclinedTexts[playerGender]);
            break;
        case RFU_STATUS_CHILD_SEND_COMPLETE:
            uroom->state = UR_STATE_ACCEPT_CHAT_REQUEST_union_room;
            break;
        }
        taskData[3]++;
        break;
    case UR_STATE_ACCEPT_CHAT_REQUEST_union_room:
        if (RfuHasErrored())
        {
            playerGender = GetUnionRoomPlayerGender_union_room(taskData[1], uroom->playerList);
            UpdateGameData_SetActivity(ACTIVITY_PLYRTALK | IN_UNION_ROOM, 0, TRUE);
            if (IsUnionRoomListenTaskActive() == TRUE)
                ScheduleFieldMessageAndExit_union_room(sChatDeclinedTexts[playerGender]);
            else
                ScheduleFieldMessageWithFollowupState_union_room(UR_STATE_CANCEL_ACTIVITY_LINK_ERROR_union_room, sChatDeclinedTexts[playerGender]);
        }
        if (gReceivedRemoteLinkPlayers)
            uroom->state = UR_STATE_START_ACTIVITY_FREE_UROOM_union_room;
        break;
    case UR_STATE_PLAYER_CONTACTED_YOU_union_room:
        PlaySE(SE_DING_DONG);
        StopUnionRoomLinkManager();
        uroom->state = UR_STATE_RECV_CONTACT_DATA_union_room;
        uroom->recvActivityRequest[0] = 0;
        break;
    case UR_STATE_RECV_CONTACT_DATA_union_room:
        if (RfuHasErrored())
        {
            HandleCancelActivity_union_room(FALSE);
            uroom->state = UR_STATE_INIT_LINK_union_room;
        }
        else if (gReceivedRemoteLinkPlayers)
        {
            CreateTrainerCardInBuffer_union_room(gBlockSendBuffer, TRUE);
            CreateTask(Task_ExchangeCards_union_room, 5);
            uroom->state = UR_STATE_WAIT_FOR_CONTACT_DATA_union_room;
        }
        break;
    case UR_STATE_WAIT_FOR_CONTACT_DATA_union_room:
        ReceiveUnionRoomActivityPacket_union_room(uroom);
        if (!FuncIsActiveTask(Task_ExchangeCards_union_room))
        {
            uroom->state = UR_STATE_PRINT_CONTACT_MSG_union_room;
            StringCopy(gStringVar1, gLinkPlayers[1].name);
            id = PlayerHasMetTrainerBefore(gLinkPlayers[1].trainerId, gLinkPlayers[1].name);
            StringExpandPlaceholders(gStringVar4, sPlayerContactedYouTexts[id]);
        }
        break;
    case UR_STATE_PRINT_CONTACT_MSG_union_room:
        ReceiveUnionRoomActivityPacket_union_room(uroom);
        if (PrintOnTextbox_union_room(&uroom->textState, gStringVar4))
            uroom->state = UR_STATE_HANDLE_CONTACT_DATA_union_room;
        break;
    case UR_STATE_HANDLE_CONTACT_DATA_union_room:
        ReceiveUnionRoomActivityPacket_union_room(uroom);
        if (HandleContactFromOtherPlayer_union_room(uroom) && JOY_NEW(B_BUTTON))
        {
            Rfu_DisconnectPlayerById(1);
            StringCopy(gStringVar4, sText_ChatEnded);
            uroom->state = UR_STATE_CANCEL_REQUEST_PRINT_MSG_union_room;
        }
        break;
    case UR_STATE_RECV_ACTIVITY_REQUEST_union_room:
        ScheduleFieldMessageWithFollowupState_union_room(UR_STATE_HANDLE_ACTIVITY_REQUEST_union_room, gStringVar4);
        break;
    case UR_STATE_HANDLE_ACTIVITY_REQUEST_union_room:
        switch (UnionRoomHandleYesNo_union_room(&uroom->textState, FALSE))
        {
        case 0: // ACCEPT
            uroom->playerSendBuffer[0] = ACTIVITY_ACCEPT | IN_UNION_ROOM;
            if (gPlayerCurrActivity == (ACTIVITY_CHAT | IN_UNION_ROOM))
                UpdateGameData_SetActivity(gPlayerCurrActivity | IN_UNION_ROOM, GetLinkPlayerInfoFlags(1), FALSE);
            else
                UpdateGameData_SetActivity(gPlayerCurrActivity | IN_UNION_ROOM, GetLinkPlayerInfoFlags(1), TRUE);

            uroom->spawnPlayer->players[0].newPlayerCountdown = 0;
            taskData[3] = 0;
            if (gPlayerCurrActivity == (ACTIVITY_BATTLE_SINGLE | IN_UNION_ROOM))
            {
                if (!HasAtLeastTwoMonsOfLevel30OrLower_union_room())
                {
                    uroom->playerSendBuffer[0] = ACTIVITY_DECLINE | IN_UNION_ROOM;
                    Rfu_SendPacket(uroom->playerSendBuffer);
                    uroom->state = UR_STATE_DECLINE_ACTIVITY_REQUEST_union_room;
                    StringCopy(gStringVar4, sText_NeedTwoMonsOfLevel30OrLower2);
                }
                else
                {
                    Rfu_SendPacket(uroom->playerSendBuffer);
                    uroom->state = UR_STATE_PRINT_START_ACTIVITY_MSG_union_room;
                }
            }
            else if (gPlayerCurrActivity == (ACTIVITY_CARD | IN_UNION_ROOM))
            {
                Rfu_SendPacket(uroom->playerSendBuffer);
                ViewURoomPartnerTrainerCard_union_room(gStringVar4, uroom, TRUE);
                uroom->state = UR_STATE_PRINT_CARD_INFO_union_room;
            }
            else
            {
                Rfu_SendPacket(uroom->playerSendBuffer);
                uroom->state = UR_STATE_PRINT_START_ACTIVITY_MSG_union_room;
            }
            break;
        case 1: // DECLINE
        case MENU_B_PRESSED:
            uroom->playerSendBuffer[0] = ACTIVITY_DECLINE | IN_UNION_ROOM;
            Rfu_SendPacket(uroom->playerSendBuffer);
            uroom->state = UR_STATE_DECLINE_ACTIVITY_REQUEST_union_room;
            GetYouDeclinedTheOfferMessage_union_room(gStringVar4, gPlayerCurrActivity);
            break;
        }
        break;
    case UR_STATE_DECLINE_ACTIVITY_REQUEST_union_room:
        SetCloseLinkCallback();
        uroom->state = UR_STATE_CANCEL_REQUEST_PRINT_MSG_union_room;
        break;
    case UR_STATE_CANCEL_REQUEST_PRINT_MSG_union_room:
        if (!gReceivedRemoteLinkPlayers)
        {
            gPlayerCurrActivity = IN_UNION_ROOM;
            ScheduleFieldMessageWithFollowupState_union_room(UR_STATE_CANCEL_REQUEST_RESTART_LINK_union_room, gStringVar4);
            memset(uroom->playerSendBuffer, 0, sizeof(uroom->playerSendBuffer));
            uroom->recvActivityRequest[0] = 0;
            uroom->partnerYesNoResponse = 0;
        }
        break;
    case UR_STATE_CANCEL_REQUEST_RESTART_LINK_union_room:
        uroom->state = UR_STATE_INIT_LINK_union_room;
        HandleCancelActivity_union_room(FALSE);
        break;
    case UR_STATE_PRINT_START_ACTIVITY_MSG_union_room:
        GetURoomActivityStartMsg_union_room(gStringVar4, gPlayerCurrActivity | IN_UNION_ROOM);
        ScheduleFieldMessageWithFollowupState_union_room(UR_STATE_START_ACTIVITY_LINK_union_room, gStringVar4);
        break;
    case UR_STATE_START_ACTIVITY_LINK_union_room:
        SetLinkStandbyCallback();
        uroom->state = UR_STATE_START_ACTIVITY_WAIT_FOR_LINK_union_room;
        break;
    case UR_STATE_START_ACTIVITY_WAIT_FOR_LINK_union_room:
        if (IsLinkTaskFinished())
            uroom->state = UR_STATE_START_ACTIVITY_FREE_UROOM_union_room;
        break;
    case UR_STATE_START_ACTIVITY_FREE_UROOM_union_room:
        Free(uroom->spawnPlayer);
        Free(uroom->playerList);
        Free(uroom->incomingParentList);
        Free(uroom->incomingChildList);
        DestroyTask(uroom->searchTaskId);
        DestroyUnionRoomPlayerSprites(uroom->spriteIds);
        uroom->state = UR_STATE_START_ACTIVITY_FADE_union_room;
        break;
    case UR_STATE_START_ACTIVITY_FADE_union_room:
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
        uroom->state = UR_STATE_START_ACTIVITY_union_room;
        break;
    case UR_STATE_START_ACTIVITY_union_room:
        if (!UpdatePaletteFade())
        {
            DestroyUnionRoomPlayerObjects();
            DestroyTask(taskId);
            Free(sWirelessLinkMain.uRoom);
            CreateTask_StartActivity_union_room();
        }
        break;
    case UR_STATE_INTERACT_WITH_ATTENDANT_union_room:
        if (GetHostRfuGameData()->tradeSpecies == SPECIES_NONE)
        {
            uroom->state = UR_STATE_REGISTER_PROMPT_union_room;
        }
        else
        {
            if (GetHostRfuGameData()->tradeSpecies == SPECIES_EGG)
            {
                StringCopy(gStringVar4, sText_CancelRegistrationOfEgg);
            }
            else
            {
                StringCopy(gStringVar1, GetSpeciesName(GetHostRfuGameData()->tradeSpecies));
                ConvertIntToDecimalStringN(gStringVar2, GetHostRfuGameData()->tradeLevel, STR_CONV_MODE_LEFT_ALIGN, 3);
                StringExpandPlaceholders(gStringVar4, sText_CancelRegistrationOfMon);
            }
            ScheduleFieldMessageWithFollowupState_union_room(UR_STATE_CANCEL_REGISTRATION_PROMPT_union_room, gStringVar4);
        }
        break;
    case UR_STATE_REGISTER_PROMPT_union_room:
        if (PrintOnTextbox_union_room(&uroom->textState, sText_RegisterMonAtTradingBoard))
            uroom->state = UR_STATE_REGISTER_PROMPT_HANDLE_INPUT_union_room;
        break;
    case UR_STATE_REGISTER_PROMPT_HANDLE_INPUT_union_room:
        input = ListMenuHandler_AllItemsAvailable_union_room(&uroom->textState,
                                                  &uroom->tradeBoardMainWindowId,
                                                  &uroom->tradeBoardHeaderWindowId,
                                                  &sWindowTemplate_RegisterForTrade,
                                                  &sListMenuTemplate_RegisterForTrade);
        if (input != LIST_NOTHING_CHOSEN)
        {
            if (input == LIST_CANCEL || input == 3) // Exit
            {
                uroom->state = UR_STATE_MAIN_union_room;
                HandleCancelActivity_union_room(TRUE);
            }
            else
            {
                switch (input)
                {
                case 1: // REGISTER
                    ScheduleFieldMessageWithFollowupState_union_room(UR_STATE_REGISTER_SELECT_MON_FADE_union_room, sText_WhichMonWillYouOffer);
                    break;
                case 2: // INFO
                    ScheduleFieldMessageWithFollowupState_union_room(UR_STATE_REGISTER_PROMPT_HANDLE_INPUT_union_room, sText_TradingBoardInfo);
                    break;
                }
            }
        }
        break;
    case UR_STATE_REGISTER_SELECT_MON_FADE_union_room:
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
        uroom->state = UR_STATE_REGISTER_SELECT_MON_union_room;
        break;
    case UR_STATE_REGISTER_SELECT_MON_union_room:
        if (!gPaletteFade.active)
        {
            sUnionRoomTrade_union_room.state = URTRADE_STATE_REGISTERING_union_room;
            gFieldCallback = FieldCB_ContinueScriptUnionRoom;
            ChooseMonForTradingBoard(PARTY_MENU_TYPE_UNION_ROOM_REGISTER, CB2_ReturnToField);
        }
        break;
    case UR_STATE_REGISTER_REQUEST_TYPE_union_room:
        input = ListMenuHandler_AllItemsAvailable_union_room(&uroom->textState,
                                                  &uroom->tradeBoardMainWindowId,
                                                  &uroom->tradeBoardHeaderWindowId,
                                                  &sWindowTemplate_TradingBoardRequestType,
                                                  &sMenuTemplate_TradingBoardRequestType);
        if (input != LIST_NOTHING_CHOSEN)
        {
            switch (input)
            {
            case LIST_CANCEL:
            case NUMBER_OF_MON_TYPES: // Exit
                ResetUnionRoomTrade_union_room(&sUnionRoomTrade_union_room);
                SetTradeBoardRegisteredMonInfo(TYPE_NORMAL, SPECIES_NONE, 0);
                ScheduleFieldMessageAndExit_union_room(sText_RegistrationCanceled);
                break;
            default:
                sUnionRoomTrade_union_room.type = input;
                uroom->state = UR_STATE_REGISTER_COMPLETE_union_room;
                break;
            }
        }
        break;
    case UR_STATE_REGISTER_COMPLETE_union_room:
        SetTradeBoardRegisteredMonInfo(sUnionRoomTrade_union_room.type, sUnionRoomTrade_union_room.playerSpecies, sUnionRoomTrade_union_room.playerLevel);
        ScheduleFieldMessageAndExit_union_room(sText_RegistraionCompleted);
        break;
    case UR_STATE_CANCEL_REGISTRATION_PROMPT_union_room:
        switch (UnionRoomHandleYesNo_union_room(&uroom->textState, FALSE))
        {
        case 0: // YES
            uroom->state = UR_STATE_CANCEL_REGISTRATION_union_room;
            break;
        case 1: // NO
        case MENU_B_PRESSED:
            HandleCancelActivity_union_room(TRUE);
            uroom->state = UR_STATE_MAIN_union_room;
            break;
        }
        break;
    case UR_STATE_CANCEL_REGISTRATION_union_room:
        if (PrintOnTextbox_union_room(&uroom->textState, sText_RegistrationCanceled2))
        {
            SetTradeBoardRegisteredMonInfo(TYPE_NORMAL, SPECIES_NONE, 0);
            ResetUnionRoomTrade_union_room(&sUnionRoomTrade_union_room);
            HandleCancelActivity_union_room(TRUE);
            uroom->state = UR_STATE_MAIN_union_room;
        }
        break;
    case UR_STATE_CHECK_TRADING_BOARD_union_room:
        if (PrintOnTextbox_union_room(&uroom->textState, sText_XCheckedTradingBoard))
            uroom->state = UR_STATE_TRADING_BOARD_LOAD_union_room;
        break;
    case UR_STATE_TRADING_BOARD_LOAD_union_room:
        UR_ClearBg0_union_room();
        uroom->state = UR_STATE_TRADING_BOARD_HANDLE_INPUT_union_room;
        break;
    case UR_STATE_TRADING_BOARD_HANDLE_INPUT_union_room:
        input = TradeBoardMenuHandler(&uroom->textState,
                                      &uroom->tradeBoardMainWindowId,
                                      &uroom->tradeBoardListMenuId,
                                      &uroom->tradeBoardHeaderWindowId,
                                      &sWindowTemplate_TradingBoardMain,
                                      &sTradeBoardListMenuTemplate,
                                      uroom->playerList);
        if (input != LIST_NOTHING_CHOSEN)
        {
            switch (input)
            {
            case LIST_CANCEL:
            case 8: // EXIT
                HandleCancelActivity_union_room(TRUE);
                uroom->state = UR_STATE_MAIN_union_room;
                break;
            default:
                UR_ClearBg0_union_room();
                switch (IsRequestedTradeInPlayerParty_union_room(uroom->playerList->players[input].rfu.data.tradeType, uroom->playerList->players[input].rfu.data.tradeSpecies))
                {
                case UR_TRADE_MATCH:
                    CopyAndTranslatePlayerName_union_room(gStringVar1, &uroom->playerList->players[input]);
                    ScheduleFieldMessageWithFollowupState_union_room(UR_STATE_TRADE_PROMPT_union_room, sText_AskTrainerToMakeTrade);
                    taskData[1] = input;
                    break;
                case UR_TRADE_NOTYPE:
                    CopyAndTranslatePlayerName_union_room(gStringVar1, &uroom->playerList->players[input]);
                    StringCopy(gStringVar2, gTypesInfo[uroom->playerList->players[input].rfu.data.tradeType].name);
                    ScheduleFieldMessageWithFollowupState_union_room(UR_STATE_TRADING_BOARD_LOAD_union_room, sText_DontHaveTypeTrainerWants);
                    break;
                case UR_TRADE_NOEGG:
                    CopyAndTranslatePlayerName_union_room(gStringVar1, &uroom->playerList->players[input]);
                    StringCopy(gStringVar2, gTypesInfo[uroom->playerList->players[input].rfu.data.tradeType].name);
                    ScheduleFieldMessageWithFollowupState_union_room(UR_STATE_TRADING_BOARD_LOAD_union_room, sText_DontHaveEggTrainerWants);
                    break;
                }
                break;
            }
        }
        break;
    case UR_STATE_TRADE_PROMPT_union_room:
        switch (UnionRoomHandleYesNo_union_room(&uroom->textState, FALSE))
        {
        case 0: // YES
            uroom->state = UR_STATE_TRADE_SELECT_MON_union_room;
            break;
        case MENU_B_PRESSED:
        case 1: // NO
            HandleCancelActivity_union_room(TRUE);
            uroom->state = UR_STATE_MAIN_union_room;
            break;
        }
        break;
    case UR_STATE_TRADE_SELECT_MON_union_room:
        if (PrintOnTextbox_union_room(&uroom->textState, sText_WhichMonWillYouOffer))
        {
            sUnionRoomTrade_union_room.state = URTRADE_STATE_OFFERING_union_room;
            memcpy(&gRfuPartnerCompatibilityData, &uroom->playerList->players[taskData[1]].rfu.data.compatibility, sizeof(gRfuPartnerCompatibilityData));
            gUnionRoomRequestedMonType = uroom->playerList->players[taskData[1]].rfu.data.tradeType;
            gUnionRoomOfferedSpecies = uroom->playerList->players[taskData[1]].rfu.data.tradeSpecies;
            gFieldCallback = FieldCB_ContinueScriptUnionRoom;
            ChooseMonForTradingBoard(PARTY_MENU_TYPE_UNION_ROOM_TRADE, CB2_ReturnToField);
            CopyPlayerListToBuffer_union_room(uroom);
            sUnionRoomTrade_union_room.offerPlayerId = taskData[1];
        }
        break;
    case UR_STATE_TRADE_OFFER_MON_union_room:
        gPlayerCurrActivity = ACTIVITY_TRADE | IN_UNION_ROOM;
        TryConnectToUnionRoomParent(uroom->playerList->players[taskData[1]].rfu.name, &uroom->playerList->players[taskData[1]].rfu.data, gPlayerCurrActivity);
        CopyAndTranslatePlayerName_union_room(gStringVar1, &uroom->playerList->players[taskData[1]]);
        UR_PrintFieldMessage_union_room(sCommunicatingWaitTexts[2]);
        uroom->state = UR_STATE_TRY_COMMUNICATING_union_room;
        break;
    case UR_STATE_PRINT_AND_EXIT_union_room:
        if (PrintOnTextbox_union_room(&uroom->textState, gStringVar4))
        {
            HandleCancelActivity_union_room(TRUE);
            UpdateUnionRoomMemberFacing(taskData[0], taskData[1], uroom->playerList);
            uroom->state = UR_STATE_MAIN_union_room;
        }
        break;
    case UR_STATE_PRINT_MSG_union_room:
        if (PrintOnTextbox_union_room(&uroom->textState, gStringVar4))
            uroom->state = uroom->stateAfterPrint;
        break;
    }
}

void SetUsingUnionRoomStartMenu(void)
{
    if (InUnionRoom() == TRUE)
        gSpecialVar_Result = UR_INTERACT_START_MENU;
}

static void ReceiveUnionRoomActivityPacket_union_room(struct WirelessLink_URoom *data)
{
    if (gRecvCmds[1][1] != 0 && (gRecvCmds[1][0] & RFUCMD_MASK) == RFUCMD_SEND_PACKET)
    {
        data->recvActivityRequest[0] = gRecvCmds[1][1];
        if (gRecvCmds[1][1] == (ACTIVITY_TRADE | IN_UNION_ROOM))
        {
            data->recvActivityRequest[1] = gRecvCmds[1][2];
            data->recvActivityRequest[2] = gRecvCmds[1][3];
        }
    }
}

static bool32 HandleContactFromOtherPlayer_union_room(struct WirelessLink_URoom *uroom)
{
    if (uroom->recvActivityRequest[0] != 0)
    {
        s32 id = GetChatLeaderActionRequestMessage_union_room(gStringVar4, gLinkPlayers[1].gender, &uroom->recvActivityRequest[0], uroom);
        if (id == 0) // Error
        {
            return TRUE;
        }
        else if (id == 1) // Recieve activity request
        {
            uroom->state = UR_STATE_RECV_ACTIVITY_REQUEST_union_room;
            gPlayerCurrActivity = uroom->recvActivityRequest[0];
            return FALSE;
        }
        else if (id == 2) // No activity
        {
            uroom->state = UR_STATE_CANCEL_REQUEST_PRINT_MSG_union_room;
            SetCloseLinkCallback();
            return FALSE;
        }
    }

    return TRUE;
}

void InitUnionRoom(void)
{
    struct WirelessLink_URoom *data;

    if (!ShouldCheckForUnionRoom())
        return;

    sUnionRoomPlayerName_union_room[0] = EOS;
    CreateTask(Task_InitUnionRoom_union_room, 0);
    sWirelessLinkMain.uRoom = sWirelessLinkMain.uRoom; // Needed to match.
    sWirelessLinkMain.uRoom = data = AllocZeroed(sizeof(struct WirelessLink_URoom));
    sURoom = sWirelessLinkMain.uRoom;
    data->state = 0;
    data->textState = 0;
    data->unknown = 0;
    data->unreadPlayerId = 0;
    sUnionRoomPlayerName_union_room[0] = EOS;
}

static void Task_InitUnionRoom_union_room(u8 taskId)
{
    s32 i;
    u8 text[32];
    struct WirelessLink_URoom *data = sWirelessLinkMain.uRoom;

    switch (data->state)
    {
    case 0:
        data->state = 1;
        break;
    case 1:
        SetHostRfuGameData(ACTIVITY_SEARCH, 0, FALSE);
        SetWirelessCommType1();
        OpenLink();
        InitializeRfuLinkManager_EnterUnionRoom();
        RfuSetIgnoreError(TRUE);
        data->state = 2;
        break;
    case 2:
        data->incomingChildList = AllocZeroed(RFU_CHILD_MAX * sizeof(struct RfuIncomingPlayer));
        ClearIncomingPlayerList_union_room(data->incomingChildList, RFU_CHILD_MAX);
        data->incomingParentList = AllocZeroed(RFU_CHILD_MAX * sizeof(struct RfuIncomingPlayer));
        ClearIncomingPlayerList_union_room(data->incomingParentList, RFU_CHILD_MAX);
        data->playerList = AllocZeroed(MAX_UNION_ROOM_LEADERS * sizeof(struct RfuPlayer));
        ClearRfuPlayerList_union_room(data->playerList->players, MAX_UNION_ROOM_LEADERS);
        data->spawnPlayer = AllocZeroed(sizeof(struct RfuPlayer));
        ClearRfuPlayerList_union_room(&data->spawnPlayer->players[0], 1);
        data->searchTaskId = CreateTask_SearchForChildOrParent_union_room(data->incomingParentList, data->incomingChildList, LINK_GROUP_UNION_ROOM_INIT);
        data->state = 3;
        break;
    case 3:
        switch (HandlePlayerListUpdate_union_room())
        {
        case PLIST_NEW_PLAYER_union_room:
        case PLIST_RECENT_UPDATE_union_room:
            if (sUnionRoomPlayerName_union_room[0] == EOS)
            {
                for (i = 0; i < MAX_UNION_ROOM_LEADERS; i++)
                {
                    if (data->playerList->players[i].groupScheduledAnim == UNION_ROOM_SPAWN_IN)
                    {
                        CopyAndTranslatePlayerName_union_room(text, &data->playerList->players[i]);
                        if (PlayerHasMetTrainerBefore(ReadAsU16_union_room(data->playerList->players[i].rfu.data.compatibility.playerTrainerId), text))
                        {
                            StringCopy(sUnionRoomPlayerName_union_room, text);
                            break;
                        }
                    }
                }
            }
            break;
        case PLIST_UNUSED_union_room:
            break;
        }
        break;
    case 4:
        Free(data->spawnPlayer);
        Free(data->playerList);
        Free(data->incomingParentList);
        Free(data->incomingChildList);
        DestroyTask(data->searchTaskId);
        Free(sWirelessLinkMain.uRoom);
        LinkRfu_Shutdown();
        DestroyTask(taskId);
        break;
    }
}

bool16 BufferUnionRoomPlayerName(void)
{
    if (!ShouldCheckForUnionRoom())
        return FALSE;

    if (sUnionRoomPlayerName_union_room[0] != EOS)
    {
        StringCopy(gStringVar1, sUnionRoomPlayerName_union_room);
        sUnionRoomPlayerName_union_room[0] = EOS;
        return TRUE;
    }
    else
    {
        return FALSE;
    }
}

static u8 HandlePlayerListUpdate_union_room(void)
{
    s32 i;
    u8 j;
    struct WirelessLink_URoom *data = sWirelessLinkMain.uRoom;
    s32 retVal = PLIST_NONE_union_room;

    for (i = 0; i < RFU_CHILD_MAX; i++)
    {
        if (ArePlayersDifferent_union_room(&data->incomingParentList->players[i].rfu, &sUnionRoomPlayer_DummyRfu) == TRUE)
        {
            data->spawnPlayer->players[0].rfu = data->incomingParentList->players[i].rfu;
            data->spawnPlayer->players[0].timeoutCounter = 0;
            data->spawnPlayer->players[0].groupScheduledAnim = UNION_ROOM_SPAWN_IN;
            data->spawnPlayer->players[0].newPlayerCountdown = 1;
            return PLIST_CONTACTED_union_room;
        }
    }
    for (j = 0; j < MAX_UNION_ROOM_LEADERS; j++)
    {
        if (data->playerList->players[j].groupScheduledAnim != UNION_ROOM_SPAWN_NONE)
        {
            i = GetNewIncomingPlayerId_union_room(&data->playerList->players[j], &data->incomingChildList->players[0]);
            if (i != 0xFF)
            {
                if (data->playerList->players[j].groupScheduledAnim == UNION_ROOM_SPAWN_IN)
                {
                    if (ArePlayerDataDifferent_union_room(&data->playerList->players[j].rfu, &data->incomingChildList->players[i].rfu))
                    {
                        data->playerList->players[j].rfu = data->incomingChildList->players[i].rfu;
                        data->playerList->players[j].newPlayerCountdown = 64;
                        retVal = PLIST_NEW_PLAYER_union_room;
                    }
                    else if (data->playerList->players[j].newPlayerCountdown != 0)
                    {
                        data->playerList->players[j].newPlayerCountdown--;
                        if (data->playerList->players[j].newPlayerCountdown == 0)
                            retVal = PLIST_RECENT_UPDATE_union_room;
                    }
                }
                else
                {
                    data->playerList->players[j].groupScheduledAnim = UNION_ROOM_SPAWN_IN;
                    data->playerList->players[j].newPlayerCountdown = 0;
                    retVal = PLIST_RECENT_UPDATE_union_room;
                }
                data->playerList->players[j].timeoutCounter = 0;
            }
            else if (data->playerList->players[j].groupScheduledAnim != UNION_ROOM_SPAWN_OUT)
            {
                data->playerList->players[j].timeoutCounter++;
                if (data->playerList->players[j].timeoutCounter >= 600)
                {
                    data->playerList->players[j].groupScheduledAnim = UNION_ROOM_SPAWN_OUT;
                    retVal = PLIST_RECENT_UPDATE_union_room;
                }
            }
            else if (data->playerList->players[j].groupScheduledAnim == UNION_ROOM_SPAWN_OUT)
            {
                data->playerList->players[j].timeoutCounter++;
                if (data->playerList->players[j].timeoutCounter >= 900)
                    ClearRfuPlayerList_union_room(&data->playerList->players[j], 1);
            }
        }
    }
    for (i = 0; i < RFU_CHILD_MAX; i++)
        if (TryAddIncomingPlayerToList_union_room(&data->playerList->players[0], &data->incomingChildList->players[i], MAX_UNION_ROOM_LEADERS) != 0xFF)
            retVal = PLIST_NEW_PLAYER_union_room;

    return retVal;
}

static void Task_SearchForChildOrParent_union_room(u8 taskId)
{
    s32 i, j;
    struct RfuPlayerData rfu;
    struct RfuIncomingPlayerList **list = (void *) gTasks[taskId].data;
    bool8 isParent;

    for (i = 0; i < RFU_CHILD_MAX; i++)
    {
        isParent = Rfu_GetCompatiblePlayerData(&rfu.data, rfu.name, i);

        if (!IsPartnerActivityAcceptable_union_room(rfu.data.activity, gTasks[taskId].data[4]))
            rfu = sUnionRoomPlayer_DummyRfu;
        if (rfu.data.compatibility.language == LANGUAGE_JAPANESE)
            rfu = sUnionRoomPlayer_DummyRfu;

        if (!isParent)
        {
            for (j = 0; j < i; j++)
            {
                if (!ArePlayersDifferent_union_room(&list[1]->players[j].rfu, &rfu))
                    rfu = sUnionRoomPlayer_DummyRfu;
            }
            list[1]->players[i].rfu = rfu;
            list[1]->players[i].active = ArePlayersDifferent_union_room(&list[1]->players[i].rfu, &sUnionRoomPlayer_DummyRfu);
        }
        else
        {
            list[0]->players[i].rfu = rfu;
            list[0]->players[i].active = ArePlayersDifferent_union_room(&list[0]->players[i].rfu, &sUnionRoomPlayer_DummyRfu);
        }
    }
}

static u8 CreateTask_SearchForChildOrParent_union_room(struct RfuIncomingPlayerList * parentList, struct RfuIncomingPlayerList * childList, u32 linkGroup)
{
    u8 taskId = CreateTask(Task_SearchForChildOrParent_union_room, 0);
    struct RfuIncomingPlayerList ** data = (void *)gTasks[taskId].data;
    data[0] = parentList;
    data[1] = childList;
    gTasks[taskId].data[4] = linkGroup;
    return taskId;
}

static void Task_ListenForCompatiblePartners_union_room(u8 taskId)
{
    s32 i, j;
    struct RfuIncomingPlayerList **list = (void *) gTasks[taskId].data;

    for (i = 0; i < RFU_CHILD_MAX; i++)
    {
        Rfu_GetCompatiblePlayerData(&list[0]->players[i].rfu.data, list[0]->players[i].rfu.name, i);
        if (!IsPartnerActivityAcceptable_union_room(list[0]->players[i].rfu.data.activity, gTasks[taskId].data[2]))
        {
            list[0]->players[i].rfu = sUnionRoomPlayer_DummyRfu;
        }
        for (j = 0; j < i; j++)
        {
            if (!ArePlayersDifferent_union_room(&list[0]->players[j].rfu, &list[0]->players[i].rfu))
                list[0]->players[i].rfu = sUnionRoomPlayer_DummyRfu;
        }
        list[0]->players[i].active = ArePlayersDifferent_union_room(&list[0]->players[i].rfu, &sUnionRoomPlayer_DummyRfu);
    }
}

static bool32 HasWonderCardOrNewsByLinkGroup_union_room(struct RfuGameData *data, s16 linkGroup)
{
    if (linkGroup == LINK_GROUP_WONDER_CARD)
    {
        if (!data->compatibility.hasCard)
            return FALSE;
        else
            return TRUE;
    }
    else if (linkGroup == LINK_GROUP_WONDER_NEWS)
    {
        if (!data->compatibility.hasNews)
            return FALSE;
        else
            return TRUE;
    }
    else
    {
        return FALSE;
    }
}

static void Task_ListenForWonderDistributor_union_room(u8 taskId)
{
    s32 i;
    struct RfuIncomingPlayerList **list = (void *) gTasks[taskId].data;

    for (i = 0; i < RFU_CHILD_MAX; i++)
    {
        if (Rfu_GetWonderDistributorPlayerData(&list[0]->players[i].rfu.data, list[0]->players[i].rfu.name, i))
            HasWonderCardOrNewsByLinkGroup_union_room(&list[0]->players[i].rfu.data, gTasks[taskId].data[2]);

        list[0]->players[i].active = ArePlayersDifferent_union_room(&list[0]->players[i].rfu, &sUnionRoomPlayer_DummyRfu);
    }
}

static u8 CreateTask_ListenForCompatiblePartners_union_room(struct RfuIncomingPlayerList * list, u32 linkGroup)
{
    u8 taskId = CreateTask(Task_ListenForCompatiblePartners_union_room, 0);
    struct RfuIncomingPlayerList **oldList = (void *) gTasks[taskId].data;
    oldList[0] = list;
    gTasks[taskId].data[2] = linkGroup;
    return taskId;
}

static u8 CreateTask_ListenForWonderDistributor_union_room(struct RfuIncomingPlayerList * list, u32 linkGroup)
{
    u8 taskId = CreateTask(Task_ListenForWonderDistributor_union_room, 0);
    struct RfuIncomingPlayerList **oldList = (void *) gTasks[taskId].data;
    oldList[0] = list;
    gTasks[taskId].data[2] = linkGroup;
    return taskId;
}

static bool32 UR_PrintFieldMessage_union_room(const u8 *src)
{
    LoadMessageBoxAndBorderGfx();
    DrawDialogueFrame(0, TRUE);
    StringExpandPlaceholders(gStringVar4, src);
    AddTextPrinterWithCustomSpeedForMessage(FALSE, 1);
    return FALSE;
}

static bool32 UR_RunTextPrinters_union_room(void)
{
    if (!RunTextPrintersAndIsPrinter0Active())
        return TRUE;
    else
        return FALSE;
}

static bool8 PrintOnTextbox_union_room(u8 *textState, const u8 *str)
{
    switch (*textState)
    {
    case 0:
        LoadMessageBoxAndBorderGfx();
        DrawDialogueFrame(0, TRUE);
        StringExpandPlaceholders(gStringVar4, str);
        AddTextPrinterForMessage_2(TRUE);
        (*textState)++;
        break;
    case 1:
        if (!RunTextPrintersAndIsPrinter0Active())
        {
            *textState = 0;
            return TRUE;
        }
        break;
    }
    return FALSE;
}

static s8 UnionRoomHandleYesNo_union_room(u8 *state, bool32 noDraw)
{
    s8 input;

    switch (*state)
    {
    case 0:
        if (noDraw)
            return -3;
        DisplayYesNoMenuDefaultYes();
        (*state)++;
        break;
    case 1:
        if (noDraw)
        {
            EraseYesNoWindow();
            *state = 0;
            return -3;
        }
        input = Menu_ProcessInputNoWrapClearOnChoose();
        if (input == MENU_B_PRESSED || input == 0 || input == 1)
        {
            *state = 0;
            return input;
        }
        break;
    }
    return MENU_NOTHING_CHOSEN;
}

static u8 CreateTradeBoardWindow_union_room(const struct WindowTemplate * template)
{
    u8 windowId = AddWindow(template);
    DrawStdWindowFrame(windowId, FALSE);
    FillWindowPixelBuffer(windowId, PIXEL_FILL(15));
    PrintUnionRoomText_union_room(windowId, FONT_NORMAL, sText_NameWantedOfferLv, 8, 1, UR_COLOR_TRADE_BOARD_OTHER_union_room);
    CopyWindowToVram(windowId, COPYWIN_GFX);
    PutWindowTilemap(windowId);
    return windowId;
}

static void DeleteTradeBoardWindow_union_room(u8 windowId)
{
    RemoveWindow(windowId);
}

static s32 ListMenuHandler_AllItemsAvailable_union_room(u8 *state, u8 *windowId, u8 *listMenuId, const struct WindowTemplate *winTemplate, const struct ListMenuTemplate *menuTemplate)
{
    s32 maxWidth, input;
    struct WindowTemplate winTemplateCopy;

    switch (*state)
    {
    case 0:
        winTemplateCopy = *winTemplate;
        maxWidth = Intl_GetListMenuWidth(menuTemplate);
        if (winTemplateCopy.width > maxWidth)
            winTemplateCopy.width = maxWidth;

        if (winTemplateCopy.tilemapLeft + winTemplateCopy.width >= DISPLAY_TILE_WIDTH)
            winTemplateCopy.tilemapLeft = max(DISPLAY_TILE_WIDTH - 1 - winTemplateCopy.width, 0);

        *windowId = AddWindow(&winTemplateCopy);
        DrawStdWindowFrame(*windowId, FALSE);
        gMultiuseListMenuTemplate = *menuTemplate;
        gMultiuseListMenuTemplate.windowId = *windowId;
        *listMenuId = ListMenuInit(&gMultiuseListMenuTemplate, 0, 0);
        CopyWindowToVram(*windowId, COPYWIN_MAP);
        (*state)++;
        break;
    case 1:
        input = ListMenu_ProcessInput(*listMenuId);
        if (JOY_NEW(A_BUTTON))
        {
            DestroyListMenuTask(*listMenuId, NULL, NULL);
            ClearStdWindowAndFrame(*windowId, TRUE);
            RemoveWindow(*windowId);
            *state = 0;
            return input;
        }
        else if (JOY_NEW(B_BUTTON))
        {
            DestroyListMenuTask(*listMenuId, NULL, NULL);
            ClearStdWindowAndFrame(*windowId, TRUE);
            RemoveWindow(*windowId);
            *state = 0;
            return LIST_CANCEL;
        }
        break;
    }

    return LIST_NOTHING_CHOSEN;
}

static s32 TradeBoardMenuHandler(u8 *state, u8 *mainWindowId, u8 *listMenuId, u8 *headerWindowId,
                                const struct WindowTemplate *winTemplate,
                                const struct ListMenuTemplate *menuTemplate,
                                struct RfuPlayerList *list)
{
    s32 input;
    s32 idx;

    switch (*state)
    {
    case 0:
        *headerWindowId = CreateTradeBoardWindow_union_room(&sWindowTemplate_TradingBoardHeader);
        *mainWindowId = AddWindow(winTemplate);
        DrawStdWindowFrame(*mainWindowId, FALSE);
        gMultiuseListMenuTemplate = *menuTemplate;
        gMultiuseListMenuTemplate.windowId = *mainWindowId;
        *listMenuId = ListMenuInit(&gMultiuseListMenuTemplate, 0, 1);
        (*state)++;
        break;
    case 1:
        CopyWindowToVram(*mainWindowId, COPYWIN_MAP);
        (*state)++;
        break;
    case 2:
        input = ListMenu_ProcessInput(*listMenuId);
        if (JOY_NEW(A_BUTTON | B_BUTTON))
        {
            // Exit or B button
            if (input == 8 || JOY_NEW(B_BUTTON))
            {
                DestroyListMenuTask(*listMenuId, NULL, NULL);
                RemoveWindow(*mainWindowId);
                DeleteTradeBoardWindow_union_room(*headerWindowId);
                *state = 0;
                return LIST_CANCEL;
            }
            else
            {
                idx = GetIndexOfNthTradeBoardOffer_union_room(list->players, input);
                if (idx >= 0)
                {
                    DestroyListMenuTask(*listMenuId, NULL, NULL);
                    RemoveWindow(*mainWindowId);
                    DeleteTradeBoardWindow_union_room(*headerWindowId);
                    *state = 0;
                    return idx;
                }
                else
                {
                    PlaySE(SE_WALL_HIT);
                }
            }
        }
        break;
    }

    return LIST_NOTHING_CHOSEN;
}

