// Checks player name and trainer id, returns TRUE if they are not the same
static bool8 ArePlayersDifferent_union_room(struct RfuPlayerData* player1, const struct RfuPlayerData* player2)
{
    s32 i;

    for (i = 0; i < 2; i++)
    {
        if (player1->data.compatibility.playerTrainerId[i] != player2->data.compatibility.playerTrainerId[i])
            return TRUE;
    }

    for (i = 0; i < PLAYER_NAME_LENGTH + 1; i++)
    {
        if (player1->name[i] != player2->name[i])
            return TRUE;
    }

    return FALSE;
}

static bool32 ArePlayerDataDifferent_union_room(struct RfuPlayerData *player1, struct RfuPlayerData *player2)
{
    s32 i;

    if (player1->data.activity != player2->data.activity)
        return TRUE;

    if (player1->data.startedActivity != player2->data.startedActivity)
        return TRUE;

    for (i = 0; i < RFU_CHILD_MAX; i++)
    {
        if (player1->data.partnerInfo[i] != player2->data.partnerInfo[i])
            return TRUE;
    }

    if (player1->data.tradeSpecies != player2->data.tradeSpecies)
        return TRUE;

    if (player1->data.tradeType != player2->data.tradeType)
        return TRUE;

    return FALSE;
}

static u32 GetNewIncomingPlayerId_union_room(struct RfuPlayer *player, struct RfuIncomingPlayer *incomingPlayer)
{
    u8 result = 0xFF; // None
    s32 i;

    for (i = 0; i < RFU_CHILD_MAX; i++)
    {
        if (incomingPlayer[i].active && !ArePlayersDifferent_union_room(&player->rfu, &incomingPlayer[i].rfu))
        {
            result = i;
            incomingPlayer[i].active = FALSE;
        }
    }

    return result;
}

static u8 TryAddIncomingPlayerToList_union_room(struct RfuPlayer *players, struct RfuIncomingPlayer *incomingPlayer, u8 max)
{
    s32 i;

    if (incomingPlayer->active)
    {
        for (i = 0; i < max; i++)
        {
            if (players[i].groupScheduledAnim == UNION_ROOM_SPAWN_NONE)
            {
                players[i].rfu = incomingPlayer->rfu;
                players[i].timeoutCounter = 0;
                players[i].groupScheduledAnim = UNION_ROOM_SPAWN_IN;
                players[i].newPlayerCountdown = 64;
                incomingPlayer->active = FALSE;
                return i;
            }
        }
    }

    return 0xFF;
}

