void EnterUnionRoomChat(void)
{
    sChat_union_room_chat = Alloc(sizeof(*sChat_union_room_chat));
    InitUnionRoomChat_union_room_chat(sChat_union_room_chat);
    gKeyRepeatStartDelay = 20;
    SetVBlankCallback(NULL);
    SetMainCallback2(CB2_LoadInterface_union_room_chat);
}

static void InitUnionRoomChat_union_room_chat(struct UnionRoomChat *chat)
{
#if FREE_UNION_ROOM_CHAT == FALSE
    int i;
#endif //FREE_UNION_ROOM_CHAT

    chat->funcId = CHAT_FUNC_JOIN_union_room_chat;
    chat->funcState = 0;
    chat->currentPage = 0;
    chat->currentCol = 0;
    chat->currentRow = 0;
    chat->lastBufferCursorPos = 0;
    chat->bufferCursorPos = 0;
    chat->receivedPlayerIndex = 0;
    chat->messageEntryBuffer[0] = EOS;
    chat->linkPlayerCount = GetLinkPlayerCount();
    chat->multiplayerId = GetMultiplayerId();
    chat->exitType = CHAT_EXIT_NONE_union_room_chat;
    chat->changedRegisteredTexts = FALSE;
    PrepareSendBuffer_Null_union_room_chat(chat->sendMessageBuffer);
#if FREE_UNION_ROOM_CHAT == FALSE
    for (i = 0; i < UNION_ROOM_KB_ROW_COUNT; i++)
        StringCopy(chat->registeredTexts[i], gSaveBlock1Ptr->registeredTexts[i]);
#endif //FREE_UNION_ROOM_CHAT
}

static void FreeUnionRoomChat_union_room_chat(void)
{
    DestroyTask(sChat_union_room_chat->handleInputTask);
    DestroyTask(sChat_union_room_chat->receiveMessagesTask);
    Free(sChat_union_room_chat);
}

static void CB2_LoadInterface_union_room_chat(void)
{
    switch (gMain.state)
    {
    case 0:
        ResetTasks();
        ResetSpriteData();
        FreeAllSpritePalettes();
        TryAllocDisplay_union_room_chat();
        gMain.state++;
        break;
    case 1:
        RunDisplaySubtasks_union_room_chat();
        if (!IsDisplaySubtask0Active_union_room_chat())
        {
            BlendPalettes(PALETTES_ALL, 16, RGB_BLACK);
            BeginNormalPaletteFade(PALETTES_ALL, -1, 16, 0, RGB_BLACK);
            SetVBlankCallback(VBlankCB_UnionRoomChatMain_union_room_chat);
            gMain.state++;
        }
        break;
    case 2:
        UpdatePaletteFade();
        if (!gPaletteFade.active)
        {
            SetMainCallback2(CB2_UnionRoomChatMain_union_room_chat);
            sChat_union_room_chat->handleInputTask = CreateTask(Task_HandlePlayerInput_union_room_chat, 8);
            sChat_union_room_chat->receiveMessagesTask = CreateTask(Task_ReceiveChatMessage_union_room_chat, 7);
            LoadWirelessStatusIndicatorSpriteGfx();
            CreateWirelessStatusIndicatorSprite(DISPLAY_WIDTH - 8, DISPLAY_HEIGHT - 10);
        }
        break;
    }
}

static void VBlankCB_UnionRoomChatMain_union_room_chat(void)
{
    TransferPlttBuffer();
    LoadOam();
    ProcessSpriteCopyRequests();
    ScanlineEffect_InitHBlankDmaTransfer();
}

static void CB2_UnionRoomChatMain_union_room_chat(void)
{
    RunTasks();
    RunDisplaySubtasks_union_room_chat();
    AnimateSprites();
    BuildOamBuffer();
    UpdatePaletteFade();
}

static void Task_HandlePlayerInput_union_room_chat(u8 taskId)
{
    // If exitType is not CHAT_EXIT_NONE_union_room_chat, begin exit function.
    // Otherwise just call main function below.
    switch (sChat_union_room_chat->exitType)
    {
    case CHAT_EXIT_ONLY_LEADER_union_room_chat:
        SetChatFunction_union_room_chat(CHAT_FUNC_EXIT_union_room_chat);
        sChat_union_room_chat->exitType = CHAT_EXIT_NONE_union_room_chat;
        break;
    case CHAT_EXIT_DROPPED_union_room_chat:
        SetChatFunction_union_room_chat(CHAT_FUNC_DROP_union_room_chat);
        sChat_union_room_chat->exitType = CHAT_EXIT_NONE_union_room_chat;
        break;
    case CHAT_EXIT_DISBANDED_union_room_chat:
        SetChatFunction_union_room_chat(CHAT_FUNC_DISBANDED_union_room_chat);
        sChat_union_room_chat->exitType = CHAT_EXIT_NONE_union_room_chat;
        break;
    }

    sChatMainFunctions[sChat_union_room_chat->funcId]();
}

static void Chat_Join_union_room_chat(void)
{
    switch (sChat_union_room_chat->funcState)
    {
    case 0:
        PrepareSendBuffer_Join_union_room_chat(sChat_union_room_chat->sendMessageBuffer);
        sChat_union_room_chat->funcState++;
        // fall through
    case 1:
        if (IsLinkTaskFinished() && !Rfu_IsPlayerExchangeActive())
        {
            if (SendBlock(0, sChat_union_room_chat->sendMessageBuffer, sizeof(sChat_union_room_chat->sendMessageBuffer)))
                sChat_union_room_chat->funcState++;
        }
        break;
    case 2:
        if (IsLinkTaskFinished())
            SetChatFunction_union_room_chat(CHAT_FUNC_HANDLE_INPUT_union_room_chat);
        break;
    }
}

static void Chat_HandleInput_union_room_chat(void)
{
    bool8 updateMsgActive, cursorBlinkActive;

    switch (sChat_union_room_chat->funcState)
    {
    case 0:
        if (JOY_NEW(START_BUTTON))
        {
            if (sChat_union_room_chat->bufferCursorPos)
                SetChatFunction_union_room_chat(CHAT_FUNC_SEND_union_room_chat);
        }
        else if (JOY_NEW(SELECT_BUTTON))
        {
            SetChatFunction_union_room_chat(CHAT_FUNC_SWITCH_union_room_chat);
        }
        else if (JOY_REPEAT(B_BUTTON))
        {
            if (sChat_union_room_chat->bufferCursorPos)
            {
                DeleteLastMessageCharacter_union_room_chat();
                StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_UPDATE_MSG_union_room_chat, 0);
                sChat_union_room_chat->funcState = 1;
            }
            else
            {
                SetChatFunction_union_room_chat(CHAT_FUNC_ASK_QUIT_union_room_chat);
            }
        }
        else if (JOY_NEW(A_BUTTON))
        {
            AppendTextToMessage_union_room_chat();
            StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_UPDATE_MSG_union_room_chat, 0);
            StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_CURSOR_BLINK_union_room_chat, 1);
            sChat_union_room_chat->funcState = 1;
        }
        else if (JOY_NEW(R_BUTTON))
        {
            if (sChat_union_room_chat->currentPage != UNION_ROOM_KB_PAGE_REGISTER_union_room_chat)
            {
                SwitchCaseOfLastMessageCharacter_union_room_chat();
                StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_UPDATE_MSG_union_room_chat, 0);
                sChat_union_room_chat->funcState = 1;
            }
            else
            {
                SetChatFunction_union_room_chat(CHAT_FUNC_REGISTER_union_room_chat);
            }
        }
        else if (HandleDPadInput_union_room_chat())
        {
            StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_MOVE_KB_CURSOR_union_room_chat, 0);
            sChat_union_room_chat->funcState = 1;
        }
        break;
    case 1:
        updateMsgActive = IsDisplaySubtaskActive_union_room_chat(0);
        cursorBlinkActive = IsDisplaySubtaskActive_union_room_chat(1);
        if (!updateMsgActive && !cursorBlinkActive)
            sChat_union_room_chat->funcState = 0;
        break;
    }
}

static void Chat_Switch_union_room_chat(void)
{
    s16 input;
    bool32 shouldSwitchPages;

    switch (sChat_union_room_chat->funcState)
    {
    case 0:
        StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_SHOW_KB_SWAP_MENU_union_room_chat, 0);
        sChat_union_room_chat->funcState++;
        break;
    case 1:
        if (!IsDisplaySubtaskActive_union_room_chat(0))
            sChat_union_room_chat->funcState++;
        break;
    case 2:
        input = Menu_ProcessInput();
        switch (input)
        {
        default:
            StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_HIDE_KB_SWAP_MENU_union_room_chat, 0);
            shouldSwitchPages = TRUE;
            if (sChat_union_room_chat->currentPage == input || input > UNION_ROOM_KB_PAGE_REGISTER_union_room_chat)
                shouldSwitchPages = FALSE;
            break;
        case MENU_NOTHING_CHOSEN:
            if (JOY_NEW(SELECT_BUTTON))
            {
                PlaySE(SE_SELECT);
                Menu_MoveCursor(1);
            }
            return;
        case MENU_B_PRESSED:
            StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_HIDE_KB_SWAP_MENU_union_room_chat, 0);
            sChat_union_room_chat->funcState = 3;
            return;
        }

        if (!shouldSwitchPages)
        {
            sChat_union_room_chat->funcState = 3;
            return;
        }

        sChat_union_room_chat->currentCol = 0;
        sChat_union_room_chat->currentRow = 0;
        StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_SWITCH_PAGES_union_room_chat, 1);
        sChat_union_room_chat->currentPage = input;
        sChat_union_room_chat->funcState = 4;
        break;
    case 3:
        if (!IsDisplaySubtaskActive_union_room_chat(0))
            SetChatFunction_union_room_chat(CHAT_FUNC_HANDLE_INPUT_union_room_chat);
        break;
    case 4:
        if (!IsDisplaySubtaskActive_union_room_chat(0) && !IsDisplaySubtaskActive_union_room_chat(1))
            SetChatFunction_union_room_chat(CHAT_FUNC_HANDLE_INPUT_union_room_chat);
        break;
    }
}

static void Chat_AskQuitChatting_union_room_chat(void)
{
    s8 input;

    switch (sChat_union_room_chat->funcState)
    {
    case 0:
        StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_ASK_QUIT_CHATTING_union_room_chat, 0);
        sChat_union_room_chat->funcState = 1;
        break;
    case 1:
        if (!IsDisplaySubtaskActive_union_room_chat(0))
            sChat_union_room_chat->funcState = 2;
        break;
    case 2:
        input = ProcessMenuInput_union_room_chat();
        switch (input)
        {
        case MENU_B_PRESSED:
        case 1:
            StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_DESTROY_YESNO_union_room_chat, 0);
            sChat_union_room_chat->funcState = 3;
            break;
        case 0:
            if (sChat_union_room_chat->multiplayerId == 0)
            {
                PrepareSendBuffer_Disband_union_room_chat(sChat_union_room_chat->sendMessageBuffer);
                StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_DESTROY_YESNO_union_room_chat, 0);
                sChat_union_room_chat->funcState = 9;
            }
            else
            {
                PrepareSendBuffer_Leave_union_room_chat(sChat_union_room_chat->sendMessageBuffer);
                sChat_union_room_chat->funcState = 4;
            }
            break;
        }
        break;
    case 3:
        if (!IsDisplaySubtaskActive_union_room_chat(0))
            SetChatFunction_union_room_chat(CHAT_FUNC_HANDLE_INPUT_union_room_chat);
        break;
    case 9:
        if (!IsDisplaySubtaskActive_union_room_chat(0))
        {
            StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_ASK_CONFIRM_LEADER_LEAVE_union_room_chat, 0);
            sChat_union_room_chat->funcState = 10;
        }
        break;
    case 10:
        if (!IsDisplaySubtaskActive_union_room_chat(0))
            sChat_union_room_chat->funcState = 8;
        break;
    case 8:
        input = ProcessMenuInput_union_room_chat();
        switch (input)
        {
        case MENU_B_PRESSED:
        case 1:
            StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_DESTROY_YESNO_union_room_chat, 0);
            sChat_union_room_chat->funcState = 3;
            break;
        case 0:
            Rfu_StopPartnerSearch();
            PrepareSendBuffer_Disband_union_room_chat(sChat_union_room_chat->sendMessageBuffer);
            sChat_union_room_chat->funcState = 4;
            sChat_union_room_chat->tryQuitAgainTimer = 0;
            break;
        }
        break;
    case 4:
        if (IsLinkTaskFinished() && !Rfu_IsPlayerExchangeActive() && SendBlock(0, sChat_union_room_chat->sendMessageBuffer, sizeof(sChat_union_room_chat->sendMessageBuffer)))
        {
            if (!sChat_union_room_chat->multiplayerId)
                sChat_union_room_chat->funcState = 6;
            else
                sChat_union_room_chat->funcState = 5;
        }

        if (!gReceivedRemoteLinkPlayers)
            SetChatFunction_union_room_chat(CHAT_FUNC_SAVE_AND_EXIT_union_room_chat);
        break;
    case 5:
        if (!gReceivedRemoteLinkPlayers)
        {
            SetChatFunction_union_room_chat(CHAT_FUNC_SAVE_AND_EXIT_union_room_chat);
        }
        else if (++sChat_union_room_chat->tryQuitAgainTimer > 300)
        {
            sChat_union_room_chat->tryQuitAgainTimer = 0;
            sChat_union_room_chat->funcState = 4;
        }
        break;
    }
}

static void Chat_Exit_union_room_chat(void)
{
    switch (sChat_union_room_chat->funcState)
    {
    case 0:
        if (!FuncIsActiveTask(Task_ReceiveChatMessage_union_room_chat))
        {
            StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_DESTROY_YESNO_union_room_chat, 0);
            sChat_union_room_chat->funcState++;
        }
        break;
    case 1:
        if (!IsDisplaySubtaskActive_union_room_chat(0))
        {
            StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_PRINT_EXITING_CHAT_union_room_chat, 0);
            sChat_union_room_chat->funcState++;
        }
        break;
    case 2:
        if (!IsDisplaySubtaskActive_union_room_chat(0))
        {
            PrepareSendBuffer_Drop_union_room_chat(sChat_union_room_chat->sendMessageBuffer);
            sChat_union_room_chat->funcState++;
        }
        break;
    case 3:
        if (IsLinkTaskFinished() && !Rfu_IsPlayerExchangeActive() && SendBlock(0, sChat_union_room_chat->sendMessageBuffer, sizeof(sChat_union_room_chat->sendMessageBuffer)))
            sChat_union_room_chat->funcState++;
        break;
    case 4:
        if ((GetBlockReceivedStatus() & 1) && !Rfu_IsPlayerExchangeActive())
            sChat_union_room_chat->funcState++;
        break;
    case 5:
        if (IsLinkTaskFinished() && !Rfu_IsPlayerExchangeActive())
        {
            SetCloseLinkCallback();
            sChat_union_room_chat->exitDelayTimer = 0;
            sChat_union_room_chat->funcState++;
        }
        break;
    case 6:
        if (sChat_union_room_chat->exitDelayTimer < 150)
            sChat_union_room_chat->exitDelayTimer++;

        if (!gReceivedRemoteLinkPlayers)
            sChat_union_room_chat->funcState++;
        break;
    case 7:
        if (sChat_union_room_chat->exitDelayTimer >= 150)
            SetChatFunction_union_room_chat(CHAT_FUNC_SAVE_AND_EXIT_union_room_chat);
        else
            sChat_union_room_chat->exitDelayTimer++;
        break;
    }
}

static void Chat_Drop_union_room_chat(void)
{
    switch (sChat_union_room_chat->funcState)
    {
    case 0:
        if (!FuncIsActiveTask(Task_ReceiveChatMessage_union_room_chat))
        {
            StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_DESTROY_YESNO_union_room_chat, 0);
            sChat_union_room_chat->funcState++;
        }
        break;
    case 1:
        if (!IsDisplaySubtaskActive_union_room_chat(0) && IsLinkTaskFinished() && !Rfu_IsPlayerExchangeActive())
        {
            SetCloseLinkCallback();
            sChat_union_room_chat->exitDelayTimer = 0;
            sChat_union_room_chat->funcState++;
        }
        break;
    case 2:
        if (sChat_union_room_chat->exitDelayTimer < 150)
            sChat_union_room_chat->exitDelayTimer++;

        if (!gReceivedRemoteLinkPlayers)
            sChat_union_room_chat->funcState++;
        break;
    case 3:
        if (sChat_union_room_chat->exitDelayTimer >= 150)
            SetChatFunction_union_room_chat(CHAT_FUNC_SAVE_AND_EXIT_union_room_chat);
        else
            sChat_union_room_chat->exitDelayTimer++;
        break;
    }
}

static void Chat_Disbanded_union_room_chat(void)
{
    switch (sChat_union_room_chat->funcState)
    {
    case 0:
        if (!FuncIsActiveTask(Task_ReceiveChatMessage_union_room_chat))
        {
            if (sChat_union_room_chat->multiplayerId)
                StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_DESTROY_YESNO_union_room_chat, 0);

            sChat_union_room_chat->funcState++;
        }
        break;
    case 1:
        if (!IsDisplaySubtaskActive_union_room_chat(0))
        {
            if (sChat_union_room_chat->multiplayerId)
                StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_PRINT_LEADER_LEFT_union_room_chat, 0);

            sChat_union_room_chat->funcState++;
        }
        break;
    case 2:
        if (IsDisplaySubtaskActive_union_room_chat(0) != TRUE && IsLinkTaskFinished() && !Rfu_IsPlayerExchangeActive())
        {
            SetCloseLinkCallback();
            sChat_union_room_chat->exitDelayTimer = 0;
            sChat_union_room_chat->funcState++;
        }
        break;
    case 3:
        if (sChat_union_room_chat->exitDelayTimer < 150)
            sChat_union_room_chat->exitDelayTimer++;

        if (!gReceivedRemoteLinkPlayers)
            sChat_union_room_chat->funcState++;
        break;
    case 4:
        if (sChat_union_room_chat->exitDelayTimer >= 150)
            SetChatFunction_union_room_chat(CHAT_FUNC_SAVE_AND_EXIT_union_room_chat);
        else
            sChat_union_room_chat->exitDelayTimer++;
        break;
    }
}

static void Chat_SendMessage_union_room_chat(void)
{
    switch (sChat_union_room_chat->funcState)
    {
    case 0:
        if (!gReceivedRemoteLinkPlayers)
        {
            SetChatFunction_union_room_chat(CHAT_FUNC_HANDLE_INPUT_union_room_chat);
            break;
        }

        PrepareSendBuffer_Chat_union_room_chat(sChat_union_room_chat->sendMessageBuffer);
        sChat_union_room_chat->funcState++;
        // fall through
    case 1:
        if (IsLinkTaskFinished() == TRUE && !Rfu_IsPlayerExchangeActive() && SendBlock(0, sChat_union_room_chat->sendMessageBuffer, sizeof(sChat_union_room_chat->sendMessageBuffer)))
            sChat_union_room_chat->funcState++;
        break;
    case 2:
        ResetMessageEntryBuffer_union_room_chat();
        StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_UPDATE_MSG_union_room_chat, 0);
        sChat_union_room_chat->funcState++;
        break;
    case 3:
        if (!IsDisplaySubtaskActive_union_room_chat(0))
            sChat_union_room_chat->funcState++;
        break;
    case 4:
        if (IsLinkTaskFinished())
            SetChatFunction_union_room_chat(CHAT_FUNC_HANDLE_INPUT_union_room_chat);
        break;
    }
}

static void Chat_Register_union_room_chat(void)
{
    switch (sChat_union_room_chat->funcState)
    {
    case 0:
        if (ChatMessageIsNotEmpty_union_room_chat())
        {
            StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_ASK_REGISTER_TEXT_union_room_chat, 0);
            sChat_union_room_chat->funcState = 2;
        }
        else
        {
            StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_PRINT_INPUT_TEXT_union_room_chat, 0);
            sChat_union_room_chat->funcState = 5;
        }
        break;
    case 1:
        if (JOY_NEW(A_BUTTON))
        {
            RegisterTextAtRow_union_room_chat();
            StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_RETURN_TO_KB_union_room_chat, 0);
            sChat_union_room_chat->funcState = 3;
        }
        else if (JOY_NEW(B_BUTTON))
        {
            StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_CANCEL_REGISTER_union_room_chat, 0);
            sChat_union_room_chat->funcState = 4;
        }
        else if (HandleDPadInput_union_room_chat())
        {
            StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_MOVE_KB_CURSOR_union_room_chat, 0);
            sChat_union_room_chat->funcState = 2;
        }
        break;
    case 2:
        if (!IsDisplaySubtaskActive_union_room_chat(0))
            sChat_union_room_chat->funcState = 1;
        break;
    case 3:
        if (!IsDisplaySubtaskActive_union_room_chat(0))
        {
            StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_CANCEL_REGISTER_union_room_chat, 0);
            sChat_union_room_chat->funcState = 4;
        }
        break;
    case 4:
        if (!IsDisplaySubtaskActive_union_room_chat(0))
            SetChatFunction_union_room_chat(CHAT_FUNC_HANDLE_INPUT_union_room_chat);
        break;
    case 5:
        if (!IsDisplaySubtaskActive_union_room_chat(0))
            sChat_union_room_chat->funcState = 6;
        break;
    case 6:
        if (JOY_NEW(A_BUTTON | B_BUTTON))
        {
            StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_DESTROY_YESNO_union_room_chat, 0);
            sChat_union_room_chat->funcState = 4;
        }
        break;
    }
}

static void Chat_SaveAndExit_union_room_chat(void)
{
    s8 input;

    switch (sChat_union_room_chat->funcState)
    {
    case 0:
        if (!sChat_union_room_chat->changedRegisteredTexts)
        {
            sChat_union_room_chat->funcState = 12;
        }
        else
        {
            StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_DESTROY_YESNO_union_room_chat, 0);
            sChat_union_room_chat->funcState = 1;
        }
        break;
    case 1:
        if (!IsDisplaySubtaskActive_union_room_chat(0))
        {
            StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_ASK_SAVE_union_room_chat, 0);
            sChat_union_room_chat->funcState = 2;
        }
        break;
    case 2:
        input = ProcessMenuInput_union_room_chat();
        switch (input)
        {
        case MENU_B_PRESSED:
        case 1:
            sChat_union_room_chat->funcState = 12;
            break;
        case 0:
            StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_DESTROY_YESNO_union_room_chat, 0);
            sChat_union_room_chat->funcState = 3;
            break;
        }
        break;
    case 3:
        if (!IsDisplaySubtaskActive_union_room_chat(0))
        {
            StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_ASK_OVERWRITE_SAVE_union_room_chat, 0);
            sChat_union_room_chat->funcState = 4;
        }
        break;
    case 4:
        if (!IsDisplaySubtaskActive_union_room_chat(0))
            sChat_union_room_chat->funcState = 5;
        break;
    case 5:
        input = ProcessMenuInput_union_room_chat();
        switch (input)
        {
        case MENU_B_PRESSED:
        case 1:
            sChat_union_room_chat->funcState = 12;
            break;
        case 0:
            StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_DESTROY_YESNO_union_room_chat, 0);
            sChat_union_room_chat->funcState = 6;
            break;
        }
        break;
    case 6:
        if (!IsDisplaySubtaskActive_union_room_chat(0))
        {
            StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_PRINT_SAVING_union_room_chat, 0);
            SaveRegisteredTexts_union_room_chat();
            sChat_union_room_chat->funcState = 7;
        }
        break;
    case 7:
        if (!IsDisplaySubtaskActive_union_room_chat(0))
        {
            SetContinueGameWarpStatusToDynamicWarp();
            TrySavingData(SAVE_NORMAL);
            sChat_union_room_chat->funcState = 8;
        }
        break;
    case 8:
        StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_PRINT_SAVED_GAME_union_room_chat, 0);
        sChat_union_room_chat->funcState = 9;
        break;
    case 9:
        if (!IsDisplaySubtaskActive_union_room_chat(0))
        {
            PlaySE(SE_SAVE);
            ClearContinueGameWarpStatus2();
            sChat_union_room_chat->funcState = 10;
        }
        break;
    case 10:
        sChat_union_room_chat->afterSaveTimer = 0;
        sChat_union_room_chat->funcState = 11;
        break;
    case 11:
        sChat_union_room_chat->afterSaveTimer++;
        if (sChat_union_room_chat->afterSaveTimer > 120)
            sChat_union_room_chat->funcState = 12;
        break;
    case 12:
        BeginNormalPaletteFade(PALETTES_ALL, -1, 0, 16, RGB_BLACK);
        sChat_union_room_chat->funcState = 13;
        break;
    case 13:
        if (!gPaletteFade.active)
        {
            FreeDisplay_union_room_chat();
            FreeUnionRoomChat_union_room_chat();
            SetMainCallback2(CB2_ReturnToField);
        }
        break;
    }
}

