static bool32 HandleDPadInput_union_room_chat(void)
{
    do
    {
        if (JOY_REPEAT(DPAD_UP))
        {
            if (sChat_union_room_chat->currentRow > 0)
                sChat_union_room_chat->currentRow--;
            else
                sChat_union_room_chat->currentRow = sKeyboardPageMaxRow_union_room_chat[sChat_union_room_chat->currentPage];
            break;
        }
        if (JOY_REPEAT(DPAD_DOWN))
        {
            if (sChat_union_room_chat->currentRow < sKeyboardPageMaxRow_union_room_chat[sChat_union_room_chat->currentPage])
                sChat_union_room_chat->currentRow++;
            else
                sChat_union_room_chat->currentRow = 0;
            break;
        }
        if (sChat_union_room_chat->currentPage != UNION_ROOM_KB_PAGE_REGISTER_union_room_chat)
        {
            if (JOY_REPEAT(DPAD_LEFT))
            {
                if (sChat_union_room_chat->currentCol > 0)
                    sChat_union_room_chat->currentCol--;
                else
                    sChat_union_room_chat->currentCol = 4;
                break;
            }
            else if (JOY_REPEAT(DPAD_RIGHT))
            {
                if (sChat_union_room_chat->currentCol < 4)
                    sChat_union_room_chat->currentCol++;
                else
                    sChat_union_room_chat->currentCol = 0;
                break;
            }
        }
        return FALSE;
    } while (0);

    return TRUE;
}

static void AppendTextToMessage_union_room_chat(void)
{
    int i;
    const u8 *charsStr;
    int strLength;
    u8 *str;
    u8 buffer[21];

    if (sChat_union_room_chat->currentPage != UNION_ROOM_KB_PAGE_REGISTER_union_room_chat)
    {
        // Going to append a single character
        charsStr = sUnionRoomKeyboardText[sChat_union_room_chat->currentPage][sChat_union_room_chat->currentRow];
        for (i = 0; i < sChat_union_room_chat->currentCol; i++)
        {
            if (*charsStr == CHAR_EXTRA_SYMBOL)
                charsStr++;
            charsStr++;
        }

        strLength = 1;
    }
    else
    {
        // Going to append registered text string
        u8 *tempStr = StringCopy(buffer, sChat_union_room_chat->registeredTexts[sChat_union_room_chat->currentRow]);
        tempStr[0] = CHAR_SPACE;
        tempStr[1] = EOS;
        charsStr = buffer;
        strLength = StringLength_Multibyte(buffer);
    }

    sChat_union_room_chat->lastBufferCursorPos = sChat_union_room_chat->bufferCursorPos;
    if (!charsStr)
        return;

    str = GetEndOfMessagePtr();
    while (--strLength != -1 && sChat_union_room_chat->bufferCursorPos < MAX_MESSAGE_LENGTH_union_room_chat)
    {
        if (*charsStr == CHAR_EXTRA_SYMBOL)
        {
            *str = *charsStr;
            charsStr++;
            str++;
        }

        *str = *charsStr;
        charsStr++;
        str++;

        sChat_union_room_chat->bufferCursorPos++;
    }

    *str = EOS;
}

static void DeleteLastMessageCharacter_union_room_chat(void)
{
    sChat_union_room_chat->lastBufferCursorPos = sChat_union_room_chat->bufferCursorPos;
    if (sChat_union_room_chat->bufferCursorPos)
    {
        u8 *str = GetLastCharOfMessagePtr();
        *str = EOS;
        sChat_union_room_chat->bufferCursorPos--;
    }
}

static void SwitchCaseOfLastMessageCharacter_union_room_chat(void)
{
    u8 *str;
    u8 character;

    sChat_union_room_chat->lastBufferCursorPos = sChat_union_room_chat->bufferCursorPos - 1;
    str = GetLastCharOfMessagePtr();
    if (*str != CHAR_EXTRA_SYMBOL)
    {
        character = gCaseToggleTable[*str];
        if (character)
            *str = character;
    }
}

