static u8 *GetEndOfMessagePtr(void)
{
    u8 *str = sChat_union_room_chat->messageEntryBuffer;
    while (*str != EOS)
        str++;

    return str;
}

static u8 *GetLastCharOfMessagePtr(void)
{
    u8 *currChar = sChat_union_room_chat->messageEntryBuffer;
    u8 *lastChar = currChar;
    while (*currChar != EOS)
    {
        lastChar = currChar;
        if (*currChar == CHAR_EXTRA_SYMBOL)
            currChar++;
        currChar++;
    }

    return lastChar;
}

static u16 GetNumOverflowCharsInMessage_union_room_chat(void)
{
    u8 *str;
    u32 i, numChars, strLength;

    strLength = StringLength_Multibyte(sChat_union_room_chat->messageEntryBuffer);
    str = sChat_union_room_chat->messageEntryBuffer;
    numChars = 0;
    if (strLength > 10)
    {
        strLength -= 10;
        for (i = 0; i < strLength; i++)
        {
            if (*str == CHAR_EXTRA_SYMBOL)
                str++;

            str++;
            numChars++;
        }
    }

    return numChars;
}

