#define tState_union_room_chat               data[0]
#define tI_union_room_chat                   data[1]
#define tCurrLinkPlayer_union_room_chat      data[2]
#define tBlockReceivedStatus_union_room_chat data[3]
#define tLinkPlayerCount_union_room_chat     data[4]
#define tNextState_union_room_chat           data[5]

static void Task_ReceiveChatMessage_union_room_chat(u8 taskId)
{
    u8 *buffer;
    s16 *data = gTasks[taskId].data;

    switch (tState_union_room_chat)
    {
    case 0:
        if (!gReceivedRemoteLinkPlayers)
        {
            DestroyTask(taskId);
            return;
        }

        tState_union_room_chat = 1;
        // fall through
    case 1:
        tLinkPlayerCount_union_room_chat = GetLinkPlayerCount();
        if (sChat_union_room_chat->linkPlayerCount != tLinkPlayerCount_union_room_chat)
        {
            tState_union_room_chat = 2;
            sChat_union_room_chat->linkPlayerCount = tLinkPlayerCount_union_room_chat;
            return;
        }

        tBlockReceivedStatus_union_room_chat = GetBlockReceivedStatus();
        if (!tBlockReceivedStatus_union_room_chat && Rfu_IsPlayerExchangeActive())
            return;

        tI_union_room_chat = 0;
        tState_union_room_chat = 3;
        // fall through
    case 3:
        for (; tI_union_room_chat < MAX_RFU_PLAYERS && ((tBlockReceivedStatus_union_room_chat >> tI_union_room_chat) & 1) == 0; tI_union_room_chat++)
            ;

        if (tI_union_room_chat == MAX_RFU_PLAYERS)
        {
            tState_union_room_chat = 1;
            return;
        }

        tCurrLinkPlayer_union_room_chat = tI_union_room_chat;
        ResetBlockReceivedFlag(tCurrLinkPlayer_union_room_chat);
        buffer = (u8 *)gBlockRecvBuffer[tI_union_room_chat];
        switch (buffer[0])
        {
            default:
            case CHAT_MESSAGE_CHAT_union_room_chat:    tNextState_union_room_chat = 3; break;
            case CHAT_MESSAGE_JOIN_union_room_chat:    tNextState_union_room_chat = 3; break;
            case CHAT_MESSAGE_LEAVE_union_room_chat:   tNextState_union_room_chat = 4; break;
            case CHAT_MESSAGE_DROP_union_room_chat:    tNextState_union_room_chat = 5; break;
            case CHAT_MESSAGE_DISBAND_union_room_chat: tNextState_union_room_chat = 6; break;
        }

        if (ProcessReceivedChatMessage_union_room_chat(sChat_union_room_chat->receivedMessage, (u8 *)gBlockRecvBuffer[tI_union_room_chat]))
        {
            sChat_union_room_chat->receivedPlayerIndex = tI_union_room_chat;
            StartDisplaySubtask_union_room_chat(CHATDISPLAY_FUNC_SCROLL_CHAT_union_room_chat, 2);
            tState_union_room_chat = 7;
        }
        else
        {
            tState_union_room_chat = tNextState_union_room_chat;
        }

        tI_union_room_chat++;
        break;
    case 7:
        if (!IsDisplaySubtaskActive_union_room_chat(2))
            tState_union_room_chat = tNextState_union_room_chat;
        break;
    case 4:
        if (!sChat_union_room_chat->multiplayerId && tCurrLinkPlayer_union_room_chat)
        {
            if (GetLinkPlayerCount() == 2)
            {
                Rfu_StopPartnerSearch();
                sChat_union_room_chat->exitType = CHAT_EXIT_ONLY_LEADER_union_room_chat;
                DestroyTask(taskId);
                return;
            }
            Rfu_DisconnectPlayerById(tCurrLinkPlayer_union_room_chat);
        }

        tState_union_room_chat = 3;
        break;
    case 5:
        if (sChat_union_room_chat->multiplayerId)
            sChat_union_room_chat->exitType = CHAT_EXIT_DROPPED_union_room_chat;

        DestroyTask(taskId);
        break;
    case 6:
        sChat_union_room_chat->exitType = CHAT_EXIT_DISBANDED_union_room_chat;
        DestroyTask(taskId);
        break;
    case 2:
        if (!Rfu_IsPlayerExchangeActive())
        {
            if (!sChat_union_room_chat->multiplayerId)
                SetUnionRoomChatPlayerData(sChat_union_room_chat->linkPlayerCount);

            tState_union_room_chat = 1;
        }
        break;
    }
}

#undef tNextState_union_room_chat
#undef tLinkPlayerCount_union_room_chat
#undef tBlockReceivedStatus_union_room_chat
#undef tCurrLinkPlayer_union_room_chat
#undef tI_union_room_chat
#undef tState_union_room_chat

