static void FreeDisplay_union_room_chat(void)
{
    FreeSprites_union_room_chat();
    TRY_FREE_AND_SET_NULL(sDisplay_union_room_chat);

    FreeAllWindowBuffers();
    gScanlineEffect.state = 3;
}

static void InitDisplay_union_room_chat(struct UnionRoomChatDisplay *display)
{
    display->yesNoMenuWindowId = WINDOW_NONE;
    display->messageWindowId = WINDOW_NONE;
    display->currLine = 0;
}

static void ResetDisplaySubtasks_union_room_chat(void)
{
    int i;

    if (!sDisplay_union_room_chat)
        return;

    for (i = 0; i < (int)ARRAY_COUNT(sDisplay_union_room_chat->subtasks); i++)
    {
        sDisplay_union_room_chat->subtasks[i].callback = Display_Dummy_union_room_chat;
        sDisplay_union_room_chat->subtasks[i].active = FALSE;
        sDisplay_union_room_chat->subtasks[i].state = 0;
    }
}

static void RunDisplaySubtasks_union_room_chat(void)
{
    int i;

    if (!sDisplay_union_room_chat)
        return;

    for (i = 0; i < (int)ARRAY_COUNT(sDisplay_union_room_chat->subtasks); i++)
    {
        sDisplay_union_room_chat->subtasks[i].active =
            sDisplay_union_room_chat->subtasks[i].callback(&sDisplay_union_room_chat->subtasks[i].state);
    }
}

static void StartDisplaySubtask_union_room_chat(u16 subtaskId, u8 assignId)
{
    u32 i;

    sDisplay_union_room_chat->subtasks[assignId].callback = Display_Dummy_union_room_chat;
    for (i = 0; i < ARRAY_COUNT(sDisplaySubtasks_union_room_chat); i++)
    {
        if (sDisplaySubtasks_union_room_chat[i].idx == subtaskId)
        {
            sDisplay_union_room_chat->subtasks[assignId].callback = sDisplaySubtasks_union_room_chat[i].callback;
            sDisplay_union_room_chat->subtasks[assignId].active = TRUE;
            sDisplay_union_room_chat->subtasks[assignId].state = 0;
            break;
        }
    }
}

static bool8 IsDisplaySubtaskActive_union_room_chat(u8 id)
{
    return sDisplay_union_room_chat->subtasks[id].active;
}

static bool32 Display_LoadGfx_union_room_chat(u8 *state)
{
    if (FreeTempTileDataBuffersIfPossible() == TRUE)
        return TRUE;

    switch (*state)
    {
    case 0:
        ResetGpuBgState_union_room_chat();
        SetBgTilemapBuffers_union_room_chat();
        break;
    case 1:
        ClearBg0_union_room_chat();
        break;
    case 2:
        LoadKeyboardWindowGfx_union_room_chat();
        break;
    case 3:
        LoadChatWindowGfx_union_room_chat();
        break;
    case 4:
        LoadChatUnkPalette_union_room_chat();
        break;
    case 5:
        LoadChatMessagesWindow_union_room_chat();
        DrawKeyboardWindow_union_room_chat();
        LoadKeyboardSwapWindow_union_room_chat();
        LoadTextEntryWindow_union_room_chat();
        break;
    case 6:
        if (!IsDma3ManagerBusyWithBgCopy())
        {
            CreateKeyboardCursorSprite_union_room_chat();
            CreateTextEntrySprites_union_room_chat();
            CreateRButtonSprites_union_room_chat();
        }
        break;
    default:
        return FALSE;
    }

    (*state)++;
    return TRUE;
}

