static bool32 Display_ScrollChat_union_room_chat(u8 *state)
{
    u16 row;
    u8 *str;
    u8 colorIdx;

    switch (*state)
    {
    case 0:
        row = sDisplay_union_room_chat->currLine;
        str = GetLastReceivedMessage();
        colorIdx = GetReceivedPlayerIndex_union_room_chat();
        PrintChatMessage_union_room_chat(row, str, colorIdx);
        CopyWindowToVram(WIN_CHAT_HISTORY_union_room_chat, COPYWIN_GFX);
        break;
    case 1:
        if (IsDma3ManagerBusyWithBgCopy())
            return TRUE;

        if (sDisplay_union_room_chat->currLine < 9)
        {
            sDisplay_union_room_chat->currLine++;
            *state = 4;
            return FALSE;
        }
        else
        {
            sDisplay_union_room_chat->scrollCount = 0;
            (*state)++;
        }
        // fall through
    case 2:
        ScrollWindow(WIN_CHAT_HISTORY_union_room_chat, 0, 5, PIXEL_FILL(1));
        CopyWindowToVram(WIN_CHAT_HISTORY_union_room_chat, COPYWIN_GFX);
        sDisplay_union_room_chat->scrollCount++;
        (*state)++;
        // fall through
    case 3:
        if (IsDma3ManagerBusyWithBgCopy())
            return TRUE;

        if (sDisplay_union_room_chat->scrollCount < 3)
        {
            (*state)--;
            return TRUE;
        }
        break;
    case 4:
        return FALSE;
    default:
        return TRUE;
    }

    (*state)++;
    return TRUE;
}

