static void AddYesNoMenuAt_union_room_chat(u8 left, u8 top, u8 initialCursorPos)
{
    struct WindowTemplate template;
    template.bg = 0;
    template.tilemapLeft = left;
    template.tilemapTop = top;
    template.width = 6;
    template.height = 4;
    template.paletteNum = 14;
    template.baseBlock = 0x52;
    sDisplay_union_room_chat->yesNoMenuWindowId = AddWindow(&template);
    if (sDisplay_union_room_chat->yesNoMenuWindowId != WINDOW_NONE)
    {
        FillWindowPixelBuffer(sDisplay_union_room_chat->yesNoMenuWindowId, PIXEL_FILL(1));
        PutWindowTilemap(sDisplay_union_room_chat->yesNoMenuWindowId);
        AddTextPrinterParameterized(sDisplay_union_room_chat->yesNoMenuWindowId, FONT_NORMAL, gText_Yes, 8, 1, TEXT_SKIP_DRAW, NULL);
        AddTextPrinterParameterized(sDisplay_union_room_chat->yesNoMenuWindowId, FONT_NORMAL, gText_No, 8, 17, TEXT_SKIP_DRAW, NULL);
        DrawTextBorderOuter(sDisplay_union_room_chat->yesNoMenuWindowId, 1, 13);
        InitMenuInUpperLeftCornerNormal(sDisplay_union_room_chat->yesNoMenuWindowId, 2, initialCursorPos);
    }
}

