static void FillTextEntryWindow_union_room_chat(u16 x, u16 width, u8 fillValue)
{
    FillWindowPixelRect(WIN_TEXT_ENTRY_union_room_chat, fillValue, x * 8, 1, width * 8, 14);
}

static void DrawTextEntryMessage_union_room_chat(u16 x, u8 *str, u8 bgColor, u8 fgColor, u8 shadowColor)
{
    u8 color[3];
    u8 strBuffer[35];
    if (bgColor != TEXT_COLOR_TRANSPARENT)
        FillTextEntryWindow_union_room_chat(x, GetTextEntryCursorPosition_union_room_chat() - x, bgColor);

    color[0] = bgColor;
    color[1] = fgColor;
    color[2] = shadowColor;
    strBuffer[0] = EXT_CTRL_CODE_BEGIN;
    strBuffer[1] = EXT_CTRL_CODE_MIN_LETTER_SPACING;
    strBuffer[2] = 8;
    StringCopy(&strBuffer[3], str);
    AddTextPrinterParameterized3(WIN_TEXT_ENTRY_union_room_chat, FONT_SHORT, x * 8, 1, color, TEXT_SKIP_DRAW, strBuffer);
}

static void PrintCurrentKeyboardPage_union_room_chat(void)
{
    u8 page;
    int i;
    u16 left;
    u16 top;
    u8 color[3];
    u8 str[45];
    u8 *str2;

    FillWindowPixelBuffer(WIN_KEYBOARD_union_room_chat, PIXEL_FILL(15));
    page = GetCurrentKeyboardPage_union_room_chat();
    color[0] = TEXT_COLOR_TRANSPARENT;
    color[1] = TEXT_DYNAMIC_COLOR_5;
    color[2] = TEXT_DYNAMIC_COLOR_4;
    if (page != UNION_ROOM_KB_PAGE_REGISTER_union_room_chat)
    {
        str[0] = EXT_CTRL_CODE_BEGIN;
        str[1] = EXT_CTRL_CODE_MIN_LETTER_SPACING;
        str[2] = 8;

        if (page == UNION_ROOM_KB_PAGE_EMOJI_union_room_chat)
            left = 6;
        else
            left = 8;

        for (i = 0, top = 0; i < UNION_ROOM_KB_ROW_COUNT; i++, top += 12)
        {
            if (!sUnionRoomKeyboardText[page][i])
                return;

            StringCopy(&str[3], sUnionRoomKeyboardText[page][i]);
            AddTextPrinterParameterized3(WIN_KEYBOARD_union_room_chat, FONT_SMALL, left, top, color, TEXT_SKIP_DRAW, str);
        }
    }
    else
    {
        left = 4;
        for (i = 0, top = 0; i < UNION_ROOM_KB_ROW_COUNT; i++, top += 12)
        {
            str2 = GetRegisteredTextByRow(i);
            if (GetStringWidth(FONT_SMALL, str2, 0) <= 40)
            {
                AddTextPrinterParameterized3(WIN_KEYBOARD_union_room_chat, FONT_SMALL, left, top, color, TEXT_SKIP_DRAW, str2);
            }
            else
            {
                int length = StringLength_Multibyte(str2);
                do
                {
                    length--;
                    StringCopyN_Multibyte(str, str2, length);
                } while (GetStringWidth(FONT_SMALL, str, 0) > 35);

                AddTextPrinterParameterized3(WIN_KEYBOARD_union_room_chat, FONT_SMALL, left, top, color, TEXT_SKIP_DRAW, str);
                AddTextPrinterParameterized3(WIN_KEYBOARD_union_room_chat, FONT_SMALL, left + 35, top, color, TEXT_SKIP_DRAW, sText_Ellipsis_union_room_chat);
            }
        }
    }
}

#define KEYBOARD_HOFS_END_union_room_chat 56

static bool32 SlideKeyboardPageOut_union_room_chat(void)
{
    if (sDisplay_union_room_chat->bg1hofs < KEYBOARD_HOFS_END_union_room_chat)
    {
        sDisplay_union_room_chat->bg1hofs += 12;
        if (sDisplay_union_room_chat->bg1hofs >= KEYBOARD_HOFS_END_union_room_chat)
            sDisplay_union_room_chat->bg1hofs = KEYBOARD_HOFS_END_union_room_chat;

        if (sDisplay_union_room_chat->bg1hofs < KEYBOARD_HOFS_END_union_room_chat)
        {
            // Still sliding
            UpdateSlidingKeyboard_union_room_chat(sDisplay_union_room_chat->bg1hofs);
            return TRUE;
        }
    }

    FinishSlidingKeyboard_union_room_chat(sDisplay_union_room_chat->bg1hofs);
    return FALSE;
}

static bool32 SlideKeyboardPageIn_union_room_chat(void)
{
    if (sDisplay_union_room_chat->bg1hofs > 0)
    {
        sDisplay_union_room_chat->bg1hofs -= 12;
        if (sDisplay_union_room_chat->bg1hofs <= 0)
            sDisplay_union_room_chat->bg1hofs = 0;

        if (sDisplay_union_room_chat->bg1hofs > 0)
        {
            // Still sliding
            UpdateSlidingKeyboard_union_room_chat(sDisplay_union_room_chat->bg1hofs);
            return TRUE;
        }
    }

    FinishSlidingKeyboard_union_room_chat(sDisplay_union_room_chat->bg1hofs);
    return FALSE;
}

static void ShowKeyboardSwapMenu_union_room_chat(void)
{
    FillWindowPixelBuffer(WIN_SWAP_MENU_union_room_chat, PIXEL_FILL(1));
    DrawTextBorderOuter(WIN_SWAP_MENU_union_room_chat, 1, 13);
    PrintMenuActionTextsAtPos(WIN_SWAP_MENU_union_room_chat, FONT_SHORT, 8, 1, 14, ARRAY_COUNT(sKeyboardPageTitleTexts_union_room_chat), sKeyboardPageTitleTexts_union_room_chat);
    InitMenuNormal(WIN_SWAP_MENU_union_room_chat, FONT_SHORT, 0, 1, 14, 5, GetCurrentKeyboardPage_union_room_chat());
    PutWindowTilemap(WIN_SWAP_MENU_union_room_chat);
}

static void HideKeyboardSwapMenu_union_room_chat(void)
{
    ClearStdWindowAndFrameToTransparent(WIN_SWAP_MENU_union_room_chat, FALSE);
    ClearWindowTilemap(WIN_SWAP_MENU_union_room_chat);
}

static void PrintChatMessage_union_room_chat(u16 row, u8 *str, u8 colorIdx)
{
    // colorIdx: 0 = gray, 1 = red, 2 = green, 3 = blue
    u8 color[3];
    color[0] = TEXT_COLOR_WHITE;
    color[1] = colorIdx * 2 + 2;
    color[2] = colorIdx * 2 + 3;
    FillWindowPixelRect(WIN_CHAT_HISTORY_union_room_chat, PIXEL_FILL(1), 0, row * 15, 168, 15);
    AddTextPrinterParameterized3(WIN_CHAT_HISTORY_union_room_chat, FONT_SHORT, 0, row * 15 + 1, color, TEXT_SKIP_DRAW, str);
}

static void ResetGpuBgState_union_room_chat(void)
{
    ChangeBgX(0, 0, BG_COORD_SET);
    ChangeBgY(0, 0, BG_COORD_SET);
    ChangeBgX(1, 0, BG_COORD_SET);
    ChangeBgY(1, 0, BG_COORD_SET);
    ChangeBgX(2, 0, BG_COORD_SET);
    ChangeBgY(2, 0, BG_COORD_SET);
    ChangeBgX(3, 0, BG_COORD_SET);
    ChangeBgY(3, 0, BG_COORD_SET);
    ShowBg(0);
    ShowBg(1);
    ShowBg(2);
    ShowBg(3);
    SetGpuRegBits(REG_OFFSET_DISPCNT, DISPCNT_OBJ_ON | DISPCNT_OBJ_1D_MAP);
    SetGpuReg(REG_OFFSET_BLDCNT, 0);
    ClearGpuRegBits(REG_OFFSET_DISPCNT, DISPCNT_WIN0_ON | DISPCNT_WIN1_ON | DISPCNT_OBJWIN_ON);
    SetGpuRegBits(REG_OFFSET_DISPCNT, DISPCNT_WIN0_ON);
    SetGpuReg(REG_OFFSET_WIN0H, WIN_RANGE(64, DISPLAY_WIDTH));
    SetGpuReg(REG_OFFSET_WIN0V, WIN_RANGE(0, DISPLAY_HEIGHT - 16));
    SetGpuReg(REG_OFFSET_WININ, WININ_WIN0_BG0 | WININ_WIN0_BG2 | WININ_WIN0_BG3
                              | WININ_WIN0_OBJ | WININ_WIN0_CLR);
    SetGpuReg(REG_OFFSET_WINOUT, WINOUT_WIN01_BG_ALL | WINOUT_WIN01_OBJ | WINOUT_WIN01_CLR);
}

static void SetBgTilemapBuffers_union_room_chat(void)
{
    SetBgTilemapBuffer(0, sDisplay_union_room_chat->bg0Buffer);
    SetBgTilemapBuffer(1, sDisplay_union_room_chat->bg1Buffer);
    SetBgTilemapBuffer(3, sDisplay_union_room_chat->bg3Buffer);
    SetBgTilemapBuffer(2, sDisplay_union_room_chat->bg2Buffer);
}

static void ClearBg0_union_room_chat(void)
{
    RequestDma3Fill(0, (void *)BG_CHAR_ADDR(0), 0x20, 1);
    FillBgTilemapBufferRect_Palette0(0, 0, 0, 0, 32, 32);
    CopyBgTilemapBufferToVram(0);
}

static void LoadKeyboardWindowGfx_union_room_chat(void)
{
    LoadPalette(gUnionRoomChat_Keyboard_Pal, BG_PLTT_ID(7), PLTT_SIZE_4BPP);
    LoadPalette(gUnionRoomChat_InputText_Pal, BG_PLTT_ID(12), PLTT_SIZE_4BPP);
    DecompressAndCopyTileDataToVram(1, gUnionRoomChat_Keyboard_Gfx, 0, 0, 0);
    CopyToBgTilemapBuffer(1, gUnionRoomChat_Keyboard_Tilemap, 0, 0);
    CopyBgTilemapBufferToVram(1);
}

static void LoadChatWindowGfx_union_room_chat(void)
{
    u8 *ptr;

    LoadPalette(gUnionRoomChat_Background_Pal, BG_PLTT_ID(0), PLTT_SIZE_4BPP);
    ptr = DecompressAndCopyTileDataToVram(2, gUnionRoomChat_Background_Gfx, 0, 0, 0);
    if (ptr)
    {
        // The below is nonsense. Tiles 0x11 and 0x21 of the background tileset are
        // the second half of "OK" and the "T" in "START" in the instructions header.
        // They're later blitted onto the text entry window, then immediately cleared.
        // The window has a different palette as well, so the tiles would appear mostly black anyway.
        CpuFastCopy(&ptr[0x11 * TILE_SIZE_4BPP], &sDisplay_union_room_chat->textEntryTiles[TILE_SIZE_4BPP * 0], TILE_SIZE_4BPP);
        CpuFastCopy(&ptr[0x21 * TILE_SIZE_4BPP], &sDisplay_union_room_chat->textEntryTiles[TILE_SIZE_4BPP * 1], TILE_SIZE_4BPP);
    }

    CopyToBgTilemapBuffer(2, gUnionRoomChat_Background_Tilemap, 0, 0);
    CopyBgTilemapBufferToVram(2);
}

static void LoadChatUnkPalette_union_room_chat(void)
{
    LoadPalette(sUnusedPalette_union_room_chat, BG_PLTT_ID(8), sizeof(sUnusedPalette_union_room_chat));
    RequestDma3Fill(0, (void *)BG_CHAR_ADDR(1) + TILE_SIZE_4BPP, TILE_SIZE_4BPP, 1);
}

static void LoadChatMessagesWindow_union_room_chat(void)
{
    LoadPalette(sChatMessagesWindow_Pal_union_room_chat, BG_PLTT_ID(15), sizeof(sChatMessagesWindow_Pal_union_room_chat));
    PutWindowTilemap(WIN_CHAT_HISTORY_union_room_chat);
    FillWindowPixelBuffer(WIN_CHAT_HISTORY_union_room_chat, PIXEL_FILL(1));
    CopyWindowToVram(WIN_CHAT_HISTORY_union_room_chat, COPYWIN_FULL);
}

static void DrawKeyboardWindow_union_room_chat(void)
{
    PutWindowTilemap(WIN_KEYBOARD_union_room_chat);
    PrintCurrentKeyboardPage_union_room_chat();
    CopyWindowToVram(WIN_KEYBOARD_union_room_chat, COPYWIN_FULL);
}

static void LoadTextEntryWindow_union_room_chat(void)
{
    int i;

    // Pointless, cleared below. The tiles are nonsense anyway, see LoadChatWindowGfx_union_room_chat.
    for (i = 0; i < MAX_MESSAGE_LENGTH_union_room_chat; i++)
        BlitBitmapToWindow(WIN_TEXT_ENTRY_union_room_chat, sDisplay_union_room_chat->textEntryTiles, i * 8, 0, 8, 16);

    FillWindowPixelBuffer(WIN_TEXT_ENTRY_union_room_chat, PIXEL_FILL(0));
    PutWindowTilemap(WIN_TEXT_ENTRY_union_room_chat);
    CopyWindowToVram(WIN_TEXT_ENTRY_union_room_chat, COPYWIN_FULL);
}

static void LoadKeyboardSwapWindow_union_room_chat(void)
{
    FillWindowPixelBuffer(WIN_SWAP_MENU_union_room_chat, PIXEL_FILL(1));
    LoadUserWindowBorderGfx(WIN_SWAP_MENU_union_room_chat, 1, BG_PLTT_ID(13));
    LoadUserWindowBorderGfx_(WIN_SWAP_MENU_union_room_chat, 0xA, BG_PLTT_ID(2));
    LoadPalette(gStandardMenuPalette, BG_PLTT_ID(14), PLTT_SIZE_4BPP);
}

static void InitScanlineEffect_union_room_chat(void)
{
    struct ScanlineEffectParams params;
    params.dmaControl = SCANLINE_EFFECT_DMACNT_16BIT;
    params.dmaDest = &REG_BG1HOFS;
    params.initState = 1;
    params.unused9 = 0;
    sDisplay_union_room_chat->bg1hofs = 0;
    CpuFastFill(0, gScanlineEffectRegBuffers, sizeof(gScanlineEffectRegBuffers));
    ScanlineEffect_SetParams(params);
}

static void UpdateSlidingKeyboard_union_room_chat(s16 bg1hofs)
{
    CpuFill16(bg1hofs, gScanlineEffectRegBuffers[gScanlineEffect.srcBuffer], 0x120);
    CpuFill16(0,       gScanlineEffectRegBuffers[gScanlineEffect.srcBuffer] + 0x90, 0x20);
}

static void FinishSlidingKeyboard_union_room_chat(s16 bg1hofs)
{
    CpuFill16(bg1hofs, gScanlineEffectRegBuffers[0],         0x120);
    CpuFill16(0,       gScanlineEffectRegBuffers[0] +  0x90, 0x20);
    CpuFill16(bg1hofs, gScanlineEffectRegBuffers[0] + 0x3C0, 0x120);
    CpuFill16(0,       gScanlineEffectRegBuffers[0] + 0x450, 0x20);
}

static bool32 TryAllocSprites_union_room_chat(void)
{
    u32 i;
    for (i = 0; i < ARRAY_COUNT(sSpriteSheets_union_room_chat); i++)
        LoadCompressedSpriteSheet(&sSpriteSheets_union_room_chat[i]);

    LoadSpritePalette(&sSpritePalette_union_room_chat);
    sSprites_union_room_chat = Alloc(sizeof(*sSprites_union_room_chat));
    if (!sSprites_union_room_chat)
        return FALSE;

    return TRUE;
}

static void FreeSprites_union_room_chat(void)
{
    if (sSprites_union_room_chat)
        Free(sSprites_union_room_chat);
}

static void CreateKeyboardCursorSprite_union_room_chat(void)
{
    u8 spriteId = CreateSprite(&sSpriteTemplate_KeyboardCursor_union_room_chat, 10, 24, 0);
    sSprites_union_room_chat->keyboardCursor = &gSprites[spriteId];
}

static void SetKeyboardCursorInvisibility_union_room_chat(bool32 invisible)
{
    sSprites_union_room_chat->keyboardCursor->invisible = invisible;
}

static void MoveKeyboardCursor_union_room_chat(void)
{
    u8 x, y;
    u8 page = GetCurrentKeyboardPage_union_room_chat();
    GetCurrentKeyboardColAndRow_union_room_chat(&x, &y);
    if (page != UNION_ROOM_KB_PAGE_REGISTER_union_room_chat)
    {
        StartSpriteAnim(sSprites_union_room_chat->keyboardCursor, 0);
        sSprites_union_room_chat->keyboardCursor->x = x * 8 + 10;
        sSprites_union_room_chat->keyboardCursor->y = y * 12 + 24;
    }
    else
    {
        StartSpriteAnim(sSprites_union_room_chat->keyboardCursor, 2);
        sSprites_union_room_chat->keyboardCursor->x = 24;
        sSprites_union_room_chat->keyboardCursor->y = y * 12 + 24;
    }
}

static void SetRegisteredTextPalette_union_room_chat(bool32 registering)
{
    const u16 *palette = &sUnionRoomChatInterfacePal_union_room_chat[registering * 2 + 1];
    u8 index = IndexOfSpritePaletteTag(PALTAG_INTERFACE_union_room_chat);
    LoadPalette(palette, OBJ_PLTT_ID(index) + 1, PLTT_SIZEOF(2));
}

static void StartKeyboardCursorAnim_union_room_chat(void)
{
    if (GetCurrentKeyboardPage_union_room_chat() != UNION_ROOM_KB_PAGE_REGISTER_union_room_chat)
        StartSpriteAnim(sSprites_union_room_chat->keyboardCursor, 1);
    else
        StartSpriteAnim(sSprites_union_room_chat->keyboardCursor, 3);

    sSprites_union_room_chat->cursorBlinkTimer = 0;
}

static bool32 TryKeyboardCursorReopen_union_room_chat(void)
{
    if (sSprites_union_room_chat->cursorBlinkTimer > 3)
        return FALSE;

    if (++sSprites_union_room_chat->cursorBlinkTimer > 3)
    {
        if (GetCurrentKeyboardPage_union_room_chat() != UNION_ROOM_KB_PAGE_REGISTER_union_room_chat)
            StartSpriteAnim(sSprites_union_room_chat->keyboardCursor, 0);
        else
            StartSpriteAnim(sSprites_union_room_chat->keyboardCursor, 2);

        return FALSE;
    }

    return TRUE;
}

static void CreateTextEntrySprites_union_room_chat(void)
{
    u8 spriteId = CreateSprite(&sSpriteTemplate_TextEntryCursor_union_room_chat, 76, 152, 2);
    sSprites_union_room_chat->textEntryCursor = &gSprites[spriteId];
    spriteId = CreateSprite(&sSpriteTemplate_TextEntryArrow_union_room_chat, 64, 152, 1);
    sSprites_union_room_chat->textEntryArrow = &gSprites[spriteId];
}

static void SpriteCB_TextEntryCursor_union_room_chat(struct Sprite *sprite)
{
    int pos = GetTextEntryCursorPosition_union_room_chat();
    if (pos == MAX_MESSAGE_LENGTH_union_room_chat)
    {
        sprite->invisible = TRUE;
    }
    else
    {
        sprite->invisible = FALSE;
        sprite->x = pos * 8 + 76;
    }
}

static void SpriteCB_TextEntryArrow_union_room_chat(struct Sprite *sprite)
{
    if (++sprite->data[0] > 4)
    {
        sprite->data[0] = 0;
        if (++sprite->x2 > 4)
            sprite->x2 = 0;
    }
}

static void CreateRButtonSprites_union_room_chat(void)
{
    u8 spriteId = CreateSprite(&sSpriteTemplate_RButtonIcon_union_room_chat, 8, 152, 3);
    sSprites_union_room_chat->rButtonIcon = &gSprites[spriteId];
    spriteId = CreateSprite(&sSpriteTemplate_RButtonLabels_union_room_chat, 32, 152, 4);
    sSprites_union_room_chat->rButtonLabel = &gSprites[spriteId];
    sSprites_union_room_chat->rButtonLabel->invisible = TRUE;
}

static void UpdateRButtonLabel_union_room_chat(void)
{
    if (GetCurrentKeyboardPage_union_room_chat() == UNION_ROOM_KB_PAGE_REGISTER_union_room_chat)
    {
        if (GetLengthOfMessageEntry_union_room_chat() != 0)
        {
            // REGISTER
            sSprites_union_room_chat->rButtonLabel->invisible = FALSE;
            StartSpriteAnim(sSprites_union_room_chat->rButtonLabel, 3);
        }
        else
        {
            sSprites_union_room_chat->rButtonLabel->invisible = TRUE;
        }
    }
    else
    {
        int anim = GetShouldShowCaseToggleIcon_union_room_chat();
        if (anim == 3)
        {
            sSprites_union_room_chat->rButtonLabel->invisible = TRUE;
        }
        else
        {
            // A <--> a (toggle case)
            sSprites_union_room_chat->rButtonLabel->invisible = FALSE;
            StartSpriteAnim(sSprites_union_room_chat->rButtonLabel, anim);
        }
    }

}
