    struct Sprite *condition[2];
    u8 toLoadSelection;
    u8 locationStrings[NUM_SELECTIONS_LOADED_use_pokeblock][24]; // Gets an "in party" or "in box #" string that never gets printed
    u8 monNameStrings[NUM_SELECTIONS_LOADED_use_pokeblock][64];
    struct ConditionGraph graph;
    u8 numSparkles[NUM_SELECTIONS_LOADED_use_pokeblock];
