static void PrintFirstEnhancement_use_pokeblock(void)
{
    DrawTextBorderOuter(WIN_TEXT_use_pokeblock, 151, 14);
    FillWindowPixelBuffer(WIN_TEXT_use_pokeblock, 17);

    for (sInfo_use_pokeblock->condition = 0; sInfo_use_pokeblock->condition < CONDITION_COUNT; sInfo_use_pokeblock->condition++)
    {
        if (sInfo_use_pokeblock->enhancements[sInfo_use_pokeblock->condition] != 0)
            break;
    }

    if (sInfo_use_pokeblock->condition < CONDITION_COUNT)
        BufferEnhancedText_use_pokeblock(gStringVar4, sInfo_use_pokeblock->condition, sInfo_use_pokeblock->enhancements[sInfo_use_pokeblock->condition]);
    else
        BufferEnhancedText_use_pokeblock(gStringVar4, sInfo_use_pokeblock->condition, 0);

    PrintMenuWindowText_use_pokeblock(gStringVar4);
    PutWindowTilemap(WIN_TEXT_use_pokeblock);
    CopyWindowToVram(WIN_TEXT_use_pokeblock, COPYWIN_FULL);
}

static bool8 TryPrintNextEnhancement_use_pokeblock(void)
{
    FillWindowPixelBuffer(WIN_TEXT_use_pokeblock, 17);

    while (1)
    {
        sInfo_use_pokeblock->condition++;
        if (sInfo_use_pokeblock->condition < CONDITION_COUNT)
        {
            if (sInfo_use_pokeblock->enhancements[sInfo_use_pokeblock->condition] != 0)
                break;
        }
        else
        {
            sInfo_use_pokeblock->condition = CONDITION_COUNT;
            return FALSE;
        }
    }

    BufferEnhancedText_use_pokeblock(gStringVar4, sInfo_use_pokeblock->condition, sInfo_use_pokeblock->enhancements[sInfo_use_pokeblock->condition]);
    PrintMenuWindowText_use_pokeblock(gStringVar4);
    CopyWindowToVram(WIN_TEXT_use_pokeblock, COPYWIN_GFX);

    return TRUE;
}

