static void SpriteCB_SelectionIconPokeball_use_pokeblock(struct Sprite *sprite)
{
    if (sprite->data[0] == sMenu_use_pokeblock->info.curSelection)
        StartSpriteAnim(sprite, CONDITION_ICON_SELECTED);
    else
        StartSpriteAnim(sprite, CONDITION_ICON_UNSELECTED);
}

