static void StartAllRespondantIdleMovements_vs_seeker(void)
{
#if FREE_MATCH_CALL == FALSE
    s32 i;
    s32 j;

    for (i = 0; i < sVsSeeker_vs_seeker->numRematchableTrainers; i++)
    {
        for (j = 0; sVsSeeker_vs_seeker->trainerInfo[j].localId != 0xFF; j++)
        {
            if (sVsSeeker_vs_seeker->trainerInfo[j].trainerIdx == sVsSeeker_vs_seeker->trainerIdxArray[i])
            {
                struct ObjectEvent *objectEvent = &gObjectEvents[sVsSeeker_vs_seeker->trainerInfo[j].objectEventId];

                if (ObjectEventIdIsSane_vs_seeker(sVsSeeker_vs_seeker->trainerInfo[j].objectEventId) == 1)
                    SetTrainerMovementType(objectEvent, sVsSeeker_vs_seeker->runningBehaviourEtcArray[i]);
                TryOverrideTemplateCoordsForObjectEvent(objectEvent, sVsSeeker_vs_seeker->runningBehaviourEtcArray[i]);
                gSaveBlock1Ptr->trainerRematches[VsSeekerConvertLocalIdToTableId(sVsSeeker_vs_seeker->trainerInfo[j].localId)] = GetRematchTrainerIdFromTable(gRematchTable, sVsSeeker_vs_seeker->trainerInfo[j].trainerIdx);
            }
        }
    }
#endif //FREE_MATCH_CALL
}
