static void VBlankCB_WallClock_wallclock(void)
{
    LoadOam();
    ProcessSpriteCopyRequests();
    TransferPlttBuffer();
}

static void LoadWallClockGraphics_wallclock(void)
{
    SetVBlankCallback(NULL);
    SetGpuReg(REG_OFFSET_DISPCNT, 0);
    SetGpuReg(REG_OFFSET_BG3CNT, 0);
    SetGpuReg(REG_OFFSET_BG2CNT, 0);
    SetGpuReg(REG_OFFSET_BG1CNT, 0);
    SetGpuReg(REG_OFFSET_BG0CNT, 0);
    ChangeBgX(0, 0, BG_COORD_SET);
    ChangeBgY(0, 0, BG_COORD_SET);
    ChangeBgX(1, 0, BG_COORD_SET);
    ChangeBgY(1, 0, BG_COORD_SET);
    ChangeBgX(2, 0, BG_COORD_SET);
    ChangeBgY(2, 0, BG_COORD_SET);
    ChangeBgX(3, 0, BG_COORD_SET);
    ChangeBgY(3, 0, BG_COORD_SET);
    DmaFillLarge16(3, 0, (void *)VRAM, VRAM_SIZE, 0x1000);
    DmaClear32(3, (void *)OAM, OAM_SIZE);
    DmaClear16(3, (void *)PLTT, PLTT_SIZE);
    LZ77UnCompVram(gWallClock_Gfx, (void *)VRAM);

    if (gSpecialVar_0x8004 == MALE)
        LoadPalette(gWallClockMale_Pal, BG_PLTT_ID(0), PLTT_SIZE_4BPP);
    else
        LoadPalette(gWallClockFemale_Pal, BG_PLTT_ID(0), PLTT_SIZE_4BPP);

    LoadPalette(GetOverworldTextboxPalettePtr(), BG_PLTT_ID(14), PLTT_SIZE_4BPP);
    LoadPalette(sTextPrompt_Pal_wallclock, BG_PLTT_ID(12), PLTT_SIZEOF(4));
    ResetBgsAndClearDma3BusyFlags(0);
    InitBgsFromTemplates(0, sBgTemplates_wallclock, ARRAY_COUNT(sBgTemplates_wallclock));
    InitWindows(sWindowTemplates_wallclock);
    DeactivateAllTextPrinters();
    LoadUserWindowBorderGfx(0, 0x250, BG_PLTT_ID(13));
    ClearScheduledBgCopiesToVram();
    ScanlineEffect_Stop();
    ResetTasks();
    ResetSpriteData();
    ResetPaletteFade();
    FreeAllSpritePalettes();
    LoadCompressedSpriteSheet(&sSpriteSheet_ClockHand_wallclock);
    LoadSpritePalettes(sSpritePalettes_Clock_wallclock);
}

static void WallClockInit_wallclock(void)
{
    BeginNormalPaletteFade(PALETTES_ALL, 0, 16, 0, RGB_BLACK);
    EnableInterrupts(INTR_FLAG_VBLANK);
    SetVBlankCallback(VBlankCB_WallClock_wallclock);
    SetMainCallback2(CB2_WallClock_wallclock);
    SetGpuReg(REG_OFFSET_BLDCNT, 0);
    SetGpuReg(REG_OFFSET_BLDALPHA, 0);
    SetGpuReg(REG_OFFSET_BLDY, 0);
    SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_OBJ_1D_MAP | DISPCNT_OBJ_ON);
    ShowBg(0);
    ShowBg(2);
    ShowBg(3);
}

void CB2_StartWallClock(void)
{
    u8 taskId;
    u8 spriteId;

    LoadWallClockGraphics_wallclock();
    LZ77UnCompVram(gWallClockStart_Tilemap, (u16 *)BG_SCREEN_ADDR(7));

    taskId = CreateTask(Task_SetClock_WaitFadeIn_wallclock, 0);
    gTasks[taskId].tHours_wallclock = 10;
    gTasks[taskId].tMinutes_wallclock = 0;
    gTasks[taskId].tMoveDir_wallclock = 0;
    gTasks[taskId].tPeriod_wallclock = 0;
    gTasks[taskId].tMoveSpeed_wallclock = 0;
    gTasks[taskId].tMinuteHandAngle_wallclock = 0;
    gTasks[taskId].tHourHandAngle_wallclock = 300;

    spriteId = CreateSprite(&sSpriteTemplate_MinuteHand_wallclock, 120, 80, 1);
    gSprites[spriteId].sTaskId_wallclock = taskId;
    gSprites[spriteId].oam.affineMode = ST_OAM_AFFINE_NORMAL;
    gSprites[spriteId].oam.matrixNum = 0;

    spriteId = CreateSprite(&sSpriteTemplate_HourHand_wallclock, 120, 80, 0);
    gSprites[spriteId].sTaskId_wallclock = taskId;
    gSprites[spriteId].oam.affineMode = ST_OAM_AFFINE_NORMAL;
    gSprites[spriteId].oam.matrixNum = 1;

    spriteId = CreateSprite(&sSpriteTemplate_PM_wallclock, 120, 80, 2);
    gSprites[spriteId].sTaskId_wallclock = taskId;
    gSprites[spriteId].data[1] = 45;

    spriteId = CreateSprite(&sSpriteTemplate_AM_wallclock, 120, 80, 2);
    gSprites[spriteId].sTaskId_wallclock = taskId;
    gSprites[spriteId].data[1] = 90;

    WallClockInit_wallclock();

    AddTextPrinterParameterized(WIN_BUTTON_LABEL_wallclock, FONT_NORMAL, gText_Confirm3, 0, 1, 0, NULL);
    PutWindowTilemap(WIN_BUTTON_LABEL_wallclock);
    ScheduleBgCopyTilemapToVram(2);
}

void CB2_ViewWallClock(void)
{
    u8 taskId;
    u8 spriteId;
    u8 angle1;
    u8 angle2;

    LoadWallClockGraphics_wallclock();
    LZ77UnCompVram(gWallClockView_Tilemap, (u16 *)BG_SCREEN_ADDR(7));

    taskId = CreateTask(Task_ViewClock_WaitFadeIn_wallclock, 0);
    InitClockWithRtc_wallclock(taskId);
    if (gTasks[taskId].tPeriod_wallclock == PERIOD_AM_wallclock)
    {
        angle1 = 45;
        angle2 = 90;
    }
    else
    {
        angle1 = 90;
        angle2 = 135;
    }

    spriteId = CreateSprite(&sSpriteTemplate_MinuteHand_wallclock, 120, 80, 1);
    gSprites[spriteId].sTaskId_wallclock = taskId;
    gSprites[spriteId].oam.affineMode = ST_OAM_AFFINE_NORMAL;
    gSprites[spriteId].oam.matrixNum = 0;

    spriteId = CreateSprite(&sSpriteTemplate_HourHand_wallclock, 120, 80, 0);
    gSprites[spriteId].sTaskId_wallclock = taskId;
    gSprites[spriteId].oam.affineMode = ST_OAM_AFFINE_NORMAL;
    gSprites[spriteId].oam.matrixNum = 1;

    spriteId = CreateSprite(&sSpriteTemplate_PM_wallclock, 120, 80, 2);
    gSprites[spriteId].sTaskId_wallclock = taskId;
    gSprites[spriteId].data[1] = angle1;

    spriteId = CreateSprite(&sSpriteTemplate_AM_wallclock, 120, 80, 2);
    gSprites[spriteId].sTaskId_wallclock = taskId;
    gSprites[spriteId].data[1] = angle2;

    WallClockInit_wallclock();

    AddTextPrinterParameterized(WIN_BUTTON_LABEL_wallclock, FONT_NORMAL, gText_Cancel4, 0, 1, 0, NULL);
    PutWindowTilemap(WIN_BUTTON_LABEL_wallclock);
    ScheduleBgCopyTilemapToVram(2);
}

static void CB2_WallClock_wallclock(void)
{
    RunTasks();
    AnimateSprites();
    BuildOamBuffer();
    DoScheduledBgTilemapCopiesToVram();
    UpdatePaletteFade();
}

static void Task_SetClock_WaitFadeIn_wallclock(u8 taskId)
{
    if (!gPaletteFade.active)
    {
        gTasks[taskId].func = Task_SetClock_HandleInput_wallclock;
    }
}

static void Task_SetClock_HandleInput_wallclock(u8 taskId)
{
    if (gTasks[taskId].tMinuteHandAngle_wallclock % 6)
    {
        gTasks[taskId].tMinuteHandAngle_wallclock = CalcNewMinHandAngle_wallclock(gTasks[taskId].tMinuteHandAngle_wallclock, gTasks[taskId].tMoveDir_wallclock, gTasks[taskId].tMoveSpeed_wallclock);
    }
    else
    {
        gTasks[taskId].tMinuteHandAngle_wallclock = gTasks[taskId].tMinutes_wallclock * 6;
        gTasks[taskId].tHourHandAngle_wallclock = (gTasks[taskId].tHours_wallclock % 12) * 30 + (gTasks[taskId].tMinutes_wallclock / 10) * 5;
        if (JOY_NEW(A_BUTTON))
        {
            gTasks[taskId].func = Task_SetClock_AskConfirm_wallclock;
        }
        else
        {
            gTasks[taskId].tMoveDir_wallclock = MOVE_NONE_wallclock;

            if (JOY_HELD(DPAD_LEFT))
                gTasks[taskId].tMoveDir_wallclock = MOVE_BACKWARD_wallclock;

            if (JOY_HELD(DPAD_RIGHT))
                gTasks[taskId].tMoveDir_wallclock = MOVE_FORWARD_wallclock;

            if (gTasks[taskId].tMoveDir_wallclock != MOVE_NONE_wallclock)
            {
                if (gTasks[taskId].tMoveSpeed_wallclock < 0xFF)
                    gTasks[taskId].tMoveSpeed_wallclock++;

                gTasks[taskId].tMinuteHandAngle_wallclock = CalcNewMinHandAngle_wallclock(gTasks[taskId].tMinuteHandAngle_wallclock, gTasks[taskId].tMoveDir_wallclock, gTasks[taskId].tMoveSpeed_wallclock);
                AdvanceClock_wallclock(taskId, gTasks[taskId].tMoveDir_wallclock);
            }
            else
            {
                gTasks[taskId].tMoveSpeed_wallclock = 0;
            }
        }
    }
}

static void Task_SetClock_AskConfirm_wallclock(u8 taskId)
{
    DrawStdFrameWithCustomTileAndPalette(WIN_MSG_wallclock, FALSE, 0x250, 0x0d);
    AddTextPrinterParameterized(WIN_MSG_wallclock, FONT_NORMAL, gText_IsThisTheCorrectTime, 0, 1, 0, NULL);
    PutWindowTilemap(WIN_MSG_wallclock);
    ScheduleBgCopyTilemapToVram(0);
    CreateYesNoMenu(&sWindowTemplate_ConfirmYesNo_wallclock, 0x250, 0x0d, 1);
    gTasks[taskId].func = Task_SetClock_HandleConfirmInput_wallclock;
}

static void Task_SetClock_HandleConfirmInput_wallclock(u8 taskId)
{
    switch (Menu_ProcessInputNoWrapClearOnChoose())
    {
    case 0: // YES
        PlaySE(SE_SELECT);
        gTasks[taskId].func = Task_SetClock_Confirmed_wallclock;
        break;
    case 1: // NO
    case MENU_B_PRESSED:
        PlaySE(SE_SELECT);
        ClearStdWindowAndFrameToTransparent(WIN_MSG_wallclock, FALSE);
        ClearWindowTilemap(WIN_MSG_wallclock);
        gTasks[taskId].func = Task_SetClock_HandleInput_wallclock;
        break;
    }
}

static void Task_SetClock_Confirmed_wallclock(u8 taskId)
{
    RtcInitLocalTimeOffset(gTasks[taskId].tHours_wallclock, gTasks[taskId].tMinutes_wallclock);
    BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
    gTasks[taskId].func = Task_SetClock_Exit_wallclock;
}

static void Task_SetClock_Exit_wallclock(u8 taskId)
{
    if (!gPaletteFade.active)
    {
        FreeAllWindowBuffers();
        SetMainCallback2(gMain.savedCallback);
    }
}

static void Task_ViewClock_WaitFadeIn_wallclock(u8 taskId)
{
    if (!gPaletteFade.active)
        gTasks[taskId].func = Task_ViewClock_HandleInput_wallclock;
}

static void Task_ViewClock_HandleInput_wallclock(u8 taskId)
{
    InitClockWithRtc_wallclock(taskId);
    if (JOY_NEW(A_BUTTON | B_BUTTON))
        gTasks[taskId].func = Task_ViewClock_FadeOut_wallclock;
}

static void Task_ViewClock_FadeOut_wallclock(u8 taskId)
{
    BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
    gTasks[taskId].func = Task_ViewClock_Exit_wallclock;
}

static void Task_ViewClock_Exit_wallclock(u8 taskId)
{
    if (!gPaletteFade.active)
        SetMainCallback2(gMain.savedCallback);
}

static u8 CalcMinHandDelta_wallclock(u16 speed)
{
    if (speed > 60)
        return 6;
    if (speed > 30)
        return 3;
    if (speed > 10)
        return 2;

    return 1;
}

static u16 CalcNewMinHandAngle_wallclock(u16 angle, u8 direction, u8 speed)
{
    u8 delta = CalcMinHandDelta_wallclock(speed);
    switch (direction)
    {
    case MOVE_BACKWARD_wallclock:
        if (angle)
            angle -= delta;
        else
            angle = 360 - delta;
        break;
    case MOVE_FORWARD_wallclock:
        if (angle < 360 - delta)
            angle += delta;
        else
            angle = 0;
        break;
    }
    return angle;
}

static bool32 AdvanceClock_wallclock(u8 taskId, u8 direction)
{
    switch (direction)
    {
    case MOVE_BACKWARD_wallclock:
        if (gTasks[taskId].tMinutes_wallclock > 0)
        {
            gTasks[taskId].tMinutes_wallclock--;
        }
        else
        {
            gTasks[taskId].tMinutes_wallclock = 59;

            if (gTasks[taskId].tHours_wallclock > 0)
                gTasks[taskId].tHours_wallclock--;
            else
                gTasks[taskId].tHours_wallclock = 23;

            UpdateClockPeriod_wallclock(taskId, direction);
        }
        break;
    case MOVE_FORWARD_wallclock:
        if (gTasks[taskId].tMinutes_wallclock < 59)
        {
            gTasks[taskId].tMinutes_wallclock++;
        }
        else
        {
            gTasks[taskId].tMinutes_wallclock = 0;

            if (gTasks[taskId].tHours_wallclock < 23)
                gTasks[taskId].tHours_wallclock++;
            else
                gTasks[taskId].tHours_wallclock = 0;

            UpdateClockPeriod_wallclock(taskId, direction);
        }
        break;
    }
    return FALSE;
}

static void UpdateClockPeriod_wallclock(u8 taskId, u8 direction)
{
    u8 hours = gTasks[taskId].tHours_wallclock;
    switch (direction)
    {
    case MOVE_BACKWARD_wallclock:
        switch (hours)
        {
        case 11:
            gTasks[taskId].tPeriod_wallclock = PERIOD_AM_wallclock;
            break;
        case 23:
            gTasks[taskId].tPeriod_wallclock = PERIOD_PM_wallclock;
            break;
        }
        break;
    case MOVE_FORWARD_wallclock:
        switch (hours)
        {
        case 0:
            gTasks[taskId].tPeriod_wallclock = PERIOD_AM_wallclock;
            break;
        case 12:
            gTasks[taskId].tPeriod_wallclock = PERIOD_PM_wallclock;
            break;
        }
        break;
    }
}

static void InitClockWithRtc_wallclock(u8 taskId)
{
    RtcCalcLocalTime();
    gTasks[taskId].tHours_wallclock = gLocalTime.hours;
    gTasks[taskId].tMinutes_wallclock = gLocalTime.minutes;
    gTasks[taskId].tMinuteHandAngle_wallclock = gTasks[taskId].tMinutes_wallclock * 6;
    gTasks[taskId].tHourHandAngle_wallclock = (gTasks[taskId].tHours_wallclock % 12) * 30 + (gTasks[taskId].tMinutes_wallclock / 10) * 5;

    if (gLocalTime.hours < 12)
        gTasks[taskId].tPeriod_wallclock = PERIOD_AM_wallclock;
    else
        gTasks[taskId].tPeriod_wallclock = PERIOD_PM_wallclock;
}

static void SpriteCB_MinuteHand_wallclock(struct Sprite *sprite)
{
    u16 angle = gTasks[sprite->sTaskId_wallclock].tMinuteHandAngle_wallclock;
    s16 sin = Sin2(angle) / 16;
    s16 cos = Cos2(angle) / 16;
    u16 x, y;

    SetOamMatrix(0, cos, sin, -sin, cos);
    x = sClockHandCoords_wallclock[angle][0];
    y = sClockHandCoords_wallclock[angle][1];

    if (x > 128)
        x |= 0xff00;
    if (y > 128)
        y |= 0xff00;

    sprite->x2 = x;
    sprite->y2 = y;
}

static void SpriteCB_HourHand_wallclock(struct Sprite *sprite)
{
    u16 angle = gTasks[sprite->sTaskId_wallclock].tHourHandAngle_wallclock;
    s16 sin = Sin2(angle) / 16;
    s16 cos = Cos2(angle) / 16;
    u16 x, y;

    SetOamMatrix(1, cos, sin, -sin, cos);
    x = sClockHandCoords_wallclock[angle][0];
    y = sClockHandCoords_wallclock[angle][1];

    if (x > 128)
        x |= 0xff00;
    if (y > 128)
        y |= 0xff00;

    sprite->x2 = x;
    sprite->y2 = y;
}

#define sAngle_wallclock data[1]

static void SpriteCB_PMIndicator_wallclock(struct Sprite *sprite)
{
    if (gTasks[sprite->sTaskId_wallclock].tPeriod_wallclock != PERIOD_AM_wallclock)
    {
        if (sprite->sAngle_wallclock >= 60 && sprite->sAngle_wallclock < 90)
            sprite->sAngle_wallclock += 5;
        if (sprite->sAngle_wallclock < 60)
            sprite->sAngle_wallclock++;
    }
    else
    {
        if (sprite->sAngle_wallclock >= 46 && sprite->sAngle_wallclock < 76)
            sprite->sAngle_wallclock -= 5;
        if (sprite->sAngle_wallclock > 75)
            sprite->sAngle_wallclock--;
    }
    sprite->x2 = Cos2(sprite->sAngle_wallclock) * 30 / 0x1000;
    sprite->y2 = Sin2(sprite->sAngle_wallclock) * 30 / 0x1000;
}

static void SpriteCB_AMIndicator_wallclock(struct Sprite *sprite)
{
    if (gTasks[sprite->sTaskId_wallclock].tPeriod_wallclock != PERIOD_AM_wallclock)
    {
        if (sprite->sAngle_wallclock >= 105 && sprite->sAngle_wallclock < 135)
            sprite->sAngle_wallclock += 5;
        if (sprite->sAngle_wallclock < 105)
            sprite->sAngle_wallclock++;
    }
    else
    {
        if (sprite->sAngle_wallclock >= 91 && sprite->sAngle_wallclock < 121)
            sprite->sAngle_wallclock -= 5;
        if (sprite->sAngle_wallclock > 120)
            sprite->sAngle_wallclock--;
    }
    sprite->x2 = Cos2(sprite->sAngle_wallclock) * 30 / 0x1000;
    sprite->y2 = Sin2(sprite->sAngle_wallclock) * 30 / 0x1000;
}
