static void CB2_RunWirelessCommunicationScreen_wireless_communication_status_screen(void)
{
    if (!IsDma3ManagerBusyWithBgCopy())
    {
        RunTasks();
        RunTextPrinters();
        AnimateSprites();
        BuildOamBuffer();
        UpdatePaletteFade();
    }
}

static void VBlankCB_WirelessCommunicationScreen_wireless_communication_status_screen(void)
{
    LoadOam();
    ProcessSpriteCopyRequests();
    TransferPlttBuffer();
}

void ShowWirelessCommunicationScreen(void)
{
    SetMainCallback2(CB2_InitWirelessCommunicationScreen_wireless_communication_status_screen);
}

static void CB2_InitWirelessCommunicationScreen_wireless_communication_status_screen(void)
{
    SetGpuReg(REG_OFFSET_DISPCNT, 0);
    sStatusScreen_wireless_communication_status_screen = AllocZeroed(sizeof(struct WirelessCommunicationStatusScreen));
    SetVBlankCallback(NULL);
    ResetBgsAndClearDma3BusyFlags(0);
    InitBgsFromTemplates(0, sBgTemplates_wireless_communication_status_screen, ARRAY_COUNT(sBgTemplates_wireless_communication_status_screen));
    SetBgTilemapBuffer(1, Alloc(BG_SCREEN_SIZE));
    SetBgTilemapBuffer(0, Alloc(BG_SCREEN_SIZE));
    DecompressAndLoadBgGfxUsingHeap(1, sBgTiles_Gfx_wireless_communication_status_screen, 0, 0, 0);
    CopyToBgTilemapBuffer(1, sBgTiles_Tilemap_wireless_communication_status_screen, 0, 0);
    InitWindows(sWindowTemplates_wireless_communication_status_screen);
    DeactivateAllTextPrinters();
    ResetPaletteFade();
    ResetSpriteData();
    ResetTasks();
    ScanlineEffect_Stop();
    m4aSoundVSyncOn();
    SetVBlankCallback(VBlankCB_WirelessCommunicationScreen_wireless_communication_status_screen);
    sStatusScreen_wireless_communication_status_screen->taskId = CreateTask(Task_WirelessCommunicationScreen_wireless_communication_status_screen, 0);
    sStatusScreen_wireless_communication_status_screen->rfuTaskId = CreateTask_ListenToWireless();
    sStatusScreen_wireless_communication_status_screen->prevGroupCounts[GROUPTYPE_TOTAL_wireless_communication_status_screen] = 1;
    ChangeBgX(0, 0, BG_COORD_SET);
    ChangeBgY(0, 0, BG_COORD_SET);
    ChangeBgX(1, 0, BG_COORD_SET);
    ChangeBgY(1, 0, BG_COORD_SET);
    LoadPalette(sPalettes_wireless_communication_status_screen, BG_PLTT_ID(0), PLTT_SIZE_4BPP);
    Menu_LoadStdPalAt(BG_PLTT_ID(15));
    DynamicPlaceholderTextUtil_Reset();
    FillBgTilemapBufferRect(0, 0, 0, 0, 32, 32, 15);
    CopyBgTilemapBufferToVram(1);
    SetMainCallback2(CB2_RunWirelessCommunicationScreen_wireless_communication_status_screen);
    RunTasks();
    RunTextPrinters();
    AnimateSprites();
    BuildOamBuffer();
    UpdatePaletteFade();
}

static void CB2_ExitWirelessCommunicationStatusScreen_wireless_communication_status_screen(void)
{
    s32 i;
    FreeAllWindowBuffers();
    for (i = 0; i < (int)ARRAY_COUNT(sBgTemplates_wireless_communication_status_screen); i++)
    {
        Free(GetBgTilemapBuffer(i));
    }
    Free(sStatusScreen_wireless_communication_status_screen);
    SetMainCallback2(CB2_ReturnToFieldContinueScriptPlayMapMusic);
}

// Cycle through palettes that relocate various shades of blue to create the wave effect at the bottom of the screen.
static void CyclePalette_wireless_communication_status_screen(s16 * counter, s16 * palIdx)
{
    s32 idx;
    if (++(*counter) > 5)
    {
        if (++(*palIdx) == (int)ARRAY_COUNT(sPalettes_wireless_communication_status_screen) - 2)
            *palIdx = 0;

        *counter = 0;
    }
    idx = *palIdx + 2; // +2 skips over default.pal and the empty black palette after it
    LoadPalette(sPalettes_wireless_communication_status_screen[idx], BG_PLTT_ID(0), PLTT_SIZEOF(8));
}

static void PrintHeaderTexts_wireless_communication_status_screen(void)
{
    s32 i;
    FillWindowPixelBuffer(WIN_TITLE_wireless_communication_status_screen, PIXEL_FILL(0));
    FillWindowPixelBuffer(WIN_GROUP_NAMES_wireless_communication_status_screen, PIXEL_FILL(0));
    FillWindowPixelBuffer(WIN_GROUP_COUNTS_wireless_communication_status_screen, PIXEL_FILL(0));

    // Print title
    WCSS_AddTextPrinterParameterized_wireless_communication_status_screen(WIN_TITLE_wireless_communication_status_screen, FONT_NORMAL, sHeaderTexts[0], GetStringCenterAlignXOffset(FONT_NORMAL, sHeaderTexts[0], 0xC0), 6, COLORMODE_GREEN_wireless_communication_status_screen);

    // Print label for each group (excluding total)
    for (i = 0; i < NUM_GROUPTYPES_wireless_communication_status_screen - 1; i++)
        WCSS_AddTextPrinterParameterized_wireless_communication_status_screen(WIN_GROUP_NAMES_wireless_communication_status_screen, FONT_NORMAL, sHeaderTexts[i + 1], 0, 30 * i + 8, COLORMODE_WHITE_LGRAY_wireless_communication_status_screen);

    // Print label for total
    WCSS_AddTextPrinterParameterized_wireless_communication_status_screen(WIN_GROUP_NAMES_wireless_communication_status_screen, FONT_NORMAL, sHeaderTexts[i + 1], 0, 30 * i + 8, COLORMODE_RED_wireless_communication_status_screen);

    PutWindowTilemap(WIN_TITLE_wireless_communication_status_screen);
    CopyWindowToVram(WIN_TITLE_wireless_communication_status_screen, COPYWIN_GFX);
    PutWindowTilemap(WIN_GROUP_NAMES_wireless_communication_status_screen);
    CopyWindowToVram(WIN_GROUP_NAMES_wireless_communication_status_screen, COPYWIN_GFX);
}

#define tState_wireless_communication_status_screen data[0]

static void Task_WirelessCommunicationScreen_wireless_communication_status_screen(u8 taskId)
{
    s32 i;
    switch (gTasks[taskId].tState_wireless_communication_status_screen)
    {
    case 0:
        PrintHeaderTexts_wireless_communication_status_screen();
        gTasks[taskId].tState_wireless_communication_status_screen++;
        break;
    case 1:
        BeginNormalPaletteFade(PALETTES_ALL, 0, 16, 0, RGB_BLACK);
        ShowBg(1);
        CopyBgTilemapBufferToVram(0);
        ShowBg(0);
        gTasks[taskId].tState_wireless_communication_status_screen++;
        break;
    case 2:
        if (!gPaletteFade.active)
            gTasks[taskId].tState_wireless_communication_status_screen++;
        break;
    case 3:
        if (UpdateCommunicationCounts_wireless_communication_status_screen(sStatusScreen_wireless_communication_status_screen->groupCounts, sStatusScreen_wireless_communication_status_screen->prevGroupCounts, sStatusScreen_wireless_communication_status_screen->activities, sStatusScreen_wireless_communication_status_screen->rfuTaskId))
        {
            FillWindowPixelBuffer(WIN_GROUP_COUNTS_wireless_communication_status_screen, PIXEL_FILL(0));
            for (i = 0; i < NUM_GROUPTYPES_wireless_communication_status_screen; i++)
            {
                ConvertIntToDecimalStringN(gStringVar4, sStatusScreen_wireless_communication_status_screen->groupCounts[i], STR_CONV_MODE_RIGHT_ALIGN, 2);
                if (i != GROUPTYPE_TOTAL_wireless_communication_status_screen)
                    WCSS_AddTextPrinterParameterized_wireless_communication_status_screen(WIN_GROUP_COUNTS_wireless_communication_status_screen, FONT_NORMAL, gStringVar4, 12, 30 * i + 8, COLORMODE_WHITE_LGRAY_wireless_communication_status_screen);
                else
                    WCSS_AddTextPrinterParameterized_wireless_communication_status_screen(WIN_GROUP_COUNTS_wireless_communication_status_screen, FONT_NORMAL, gStringVar4, 12, 98, COLORMODE_RED_wireless_communication_status_screen);
            }
            PutWindowTilemap(WIN_GROUP_COUNTS_wireless_communication_status_screen);
            CopyWindowToVram(WIN_GROUP_COUNTS_wireless_communication_status_screen, COPYWIN_FULL);
        }
        if (JOY_NEW(A_BUTTON) || JOY_NEW(B_BUTTON))
        {
            PlaySE(SE_SELECT);
            gTasks[sStatusScreen_wireless_communication_status_screen->rfuTaskId].data[15] = 0xFF;
            gTasks[taskId].tState_wireless_communication_status_screen++;
        }
        CyclePalette_wireless_communication_status_screen(&gTasks[taskId].data[7], &gTasks[taskId].data[8]);
        break;
    case 4:
        BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
        gTasks[taskId].tState_wireless_communication_status_screen++;
        break;
    case 5:
        if (!gPaletteFade.active)
        {
            SetMainCallback2(CB2_ExitWirelessCommunicationStatusScreen_wireless_communication_status_screen);
            DestroyTask(taskId);
        }
        break;
    }
}

#undef tState_wireless_communication_status_screen

static void WCSS_AddTextPrinterParameterized_wireless_communication_status_screen(u8 windowId, u8 fontId, const u8 *str, u8 x, u8 y, u8 mode)
{
    u8 color[3];

    switch (mode)
    {
    case COLORMODE_NORMAL_wireless_communication_status_screen:
        color[0] = TEXT_COLOR_TRANSPARENT;
        color[1] = TEXT_COLOR_DARK_GRAY;
        color[2] = TEXT_COLOR_LIGHT_GRAY;
        break;
    case COLORMODE_WHITE_LGRAY_wireless_communication_status_screen:
        color[0] = TEXT_COLOR_TRANSPARENT;
        color[1] = TEXT_COLOR_WHITE;
        color[2] = TEXT_COLOR_LIGHT_GRAY;
        break;
    case COLORMODE_RED_wireless_communication_status_screen:
        color[0] = TEXT_COLOR_TRANSPARENT;
        color[1] = TEXT_COLOR_RED;
        color[2] = TEXT_COLOR_LIGHT_RED;
        break;
    case COLORMODE_GREEN_wireless_communication_status_screen:
        color[0] = TEXT_COLOR_TRANSPARENT;
        color[1] = TEXT_COLOR_LIGHT_GREEN;
        color[2] = TEXT_COLOR_GREEN;
        break;
    case COLORMODE_WHITE_DGRAY_wireless_communication_status_screen:
        color[0] = TEXT_COLOR_TRANSPARENT;
        color[1] = TEXT_COLOR_WHITE;
        color[2] = TEXT_COLOR_DARK_GRAY;
        break;
    }

    AddTextPrinterParameterized4(windowId, fontId, x, y, 0, 0, color, TEXT_SKIP_DRAW, str);
}

static u32 CountPlayersInGroupAndGetActivity_wireless_communication_status_screen(struct RfuPlayer * player, u32 * groupCounts)
{
    int i, j, k;
    u32 activity = player->rfu.data.activity;

    #define group_activity_wireless_communication_status_screen(i) (sActivityGroupInfo_wireless_communication_status_screen[(i)][0])
    #define group_type_wireless_communication_status_screen(i)     (sActivityGroupInfo_wireless_communication_status_screen[(i)][1])
    #define group_players_wireless_communication_status_screen(i)  (sActivityGroupInfo_wireless_communication_status_screen[(i)][2])

    for (i = 0; i < ARRAY_COUNT(sActivityGroupInfo_wireless_communication_status_screen); i++)
    {
#ifdef UBFIX
        // GROUPTYPE_NONE_wireless_communication_status_screen is 0xFF, and shouldn't be used as an index into groupCounts.
        // In theory the only activity with this group type (ACTIVITY_SEARCH) wouldn't
        // satisfy the condition below, but not necessarily.
        if (group_type_wireless_communication_status_screen(i) == GROUPTYPE_NONE_wireless_communication_status_screen)
            continue;
#endif
        if (activity == group_activity_wireless_communication_status_screen(i) && player->groupScheduledAnim == UNION_ROOM_SPAWN_IN)
        {
            if (group_players_wireless_communication_status_screen(i) == 0)
            {
                k = 0;
                for (j = 0; j < RFU_CHILD_MAX; j++)
                    if (player->rfu.data.partnerInfo[j] != 0) k++;
                k++;
                groupCounts[group_type_wireless_communication_status_screen(i)] += k;
            }
            else
            {
                groupCounts[group_type_wireless_communication_status_screen(i)] += group_players_wireless_communication_status_screen(i);
            }
        }
    }
    return activity;

    #undef group_activity_wireless_communication_status_screen
    #undef group_type_wireless_communication_status_screen
    #undef group_players_wireless_communication_status_screen
}

static bool32 HaveCountsChanged_wireless_communication_status_screen(u32 * currCounts, u32 * prevCounts)
{
    s32 i;
    for (i = 0; i < NUM_GROUPTYPES_wireless_communication_status_screen; i++)
    {
        if (currCounts[i] != prevCounts[i])
            return TRUE;
    }
    return FALSE;
}

static bool32 UpdateCommunicationCounts_wireless_communication_status_screen(u32 * groupCounts, u32 * prevGroupCounts, u32 * activities, u8 taskId)
{
    bool32 activitiesChanged = FALSE;
    u32 groupCountBuffer[NUM_GROUPTYPES_wireless_communication_status_screen] = {0, 0, 0, 0};
    struct RfuPlayer ** players = (void *)gTasks[taskId].data;
    s32 i;

    for (i = 0; i < NUM_TASK_DATA; i++)
    {
        u32 activity = CountPlayersInGroupAndGetActivity_wireless_communication_status_screen(&(*players)[i], groupCountBuffer);
        if (activity != activities[i])
        {
            activities[i] = activity;
            activitiesChanged = TRUE;
        }
    }

    if (!HaveCountsChanged_wireless_communication_status_screen(groupCountBuffer, prevGroupCounts))
    {
        if (activitiesChanged == TRUE)
            return TRUE;
        else
            return FALSE;
    }
    else
    {
        memcpy(groupCounts,     groupCountBuffer, sizeof(groupCountBuffer));
        memcpy(prevGroupCounts, groupCountBuffer, sizeof(groupCountBuffer));

        groupCounts[GROUPTYPE_TOTAL_wireless_communication_status_screen] = groupCounts[GROUPTYPE_TRADE_wireless_communication_status_screen]
                                     + groupCounts[GROUPTYPE_BATTLE_wireless_communication_status_screen]
                                     + groupCounts[GROUPTYPE_UNION_wireless_communication_status_screen]
                                     + groupCounts[GROUPTYPE_TOTAL_wireless_communication_status_screen];
        return TRUE;
    }
}
// Contents of wonder_news.c
#include "global.h"
#include "mystery_gift.h"
#include "random.h"
#include "event_data.h"
#include "wonder_news.h"
#include "constants/items.h"

// Every 4th reward for sending Wonder News to a link partner is a "big" reward.
#define MAX_SENT_REWARD_wonder_news 4

// Only up to 5 rewards can be received in a short period. After this the player
// must take 500 steps before any more rewards can be received.
#define MAX_REWARD_wonder_news 5

static u32 GetRewardItem_wonder_news(struct WonderNewsMetadata *);
static u32 GetRewardType_wonder_news(struct WonderNewsMetadata *);
static void IncrementRewardCounter_wonder_news(struct WonderNewsMetadata *);
static void IncrementSentRewardCounter_wonder_news(struct WonderNewsMetadata *);
static void ResetSentRewardCounter_wonder_news(struct WonderNewsMetadata *);

void WonderNews_SetReward(u32 newsType)
{
    struct WonderNewsMetadata *data = GetSavedWonderNewsMetadata();

    data->newsType = newsType;
    switch (newsType)
    {
    case WONDER_NEWS_NONE:
        break;
    case WONDER_NEWS_RECV_FRIEND:
    case WONDER_NEWS_RECV_WIRELESS:
        // Random berry between ITEM_RAZZ_BERRY and ITEM_NOMEL_BERRY
        data->berry = (Random() % 15) + ITEM_TO_BERRY(ITEM_RAZZ_BERRY);
        break;
    case WONDER_NEWS_SENT:
        // Random berry between ITEM_CHERI_BERRY and ITEM_IAPAPA_BERRY
        data->berry = (Random() % 15) + ITEM_TO_BERRY(ITEM_CHERI_BERRY);
        break;
    }
}

void WonderNews_Reset(void)
{
    struct WonderNewsMetadata *data = GetSavedWonderNewsMetadata();

    data->newsType = WONDER_NEWS_NONE;
    data->sentRewardCounter = 0;
    data->rewardCounter = 0;
    data->berry = 0;
    VarSet(VAR_WONDER_NEWS_STEP_COUNTER, 0);
}

// Only used in FRLG
void WonderNews_IncrementStepCounter(void)
{
    u16 *stepCounter = GetVarPointer(VAR_WONDER_NEWS_STEP_COUNTER);
    struct WonderNewsMetadata *data = GetSavedWonderNewsMetadata();

    // If the player has reached the reward limit, start counting steps.
    // When they reach 500 steps reset the reward counter to allow them to
    // receive rewards again.
    if (data->rewardCounter >= MAX_REWARD_wonder_news && ++(*stepCounter) >= 500)
    {
        data->rewardCounter = 0;
        *stepCounter = 0;
    }
}

// Only used in FRLG
u16 WonderNews_GetRewardInfo(void)
{
    u16 *result = &gSpecialVar_Result;
    struct WonderNewsMetadata *data = GetSavedWonderNewsMetadata();
    u16 rewardType;

    // Checks if Mystery Event is enabled, not Mystery Gift?
    if (!IsMysteryEventEnabled() || !ValidateSavedWonderNews())
        return NEWS_REWARD_NONE;

    rewardType = GetRewardType_wonder_news(data);

    switch (rewardType)
    {
    case NEWS_REWARD_RECV_SMALL:
    case NEWS_REWARD_RECV_BIG:
        *result = GetRewardItem_wonder_news(data);
        break;
    case NEWS_REWARD_SENT_SMALL:
        *result = GetRewardItem_wonder_news(data);
        IncrementSentRewardCounter_wonder_news(data);
        break;
    case NEWS_REWARD_SENT_BIG:
        *result = GetRewardItem_wonder_news(data);
        ResetSentRewardCounter_wonder_news(data);
        break;
    case NEWS_REWARD_NONE:
    case NEWS_REWARD_WAITING:
    case NEWS_REWARD_AT_MAX:
        break;
    }

    return rewardType;
}

static u32 GetRewardItem_wonder_news(struct WonderNewsMetadata *data)
{
    u32 itemId;
    data->newsType = WONDER_NEWS_NONE;
    itemId = data->berry + FIRST_BERRY_INDEX - 1;
    data->berry = 0;
    IncrementRewardCounter_wonder_news(data);
    return itemId;
}

static void ResetSentRewardCounter_wonder_news(struct WonderNewsMetadata *data)
{
    data->sentRewardCounter = 0;
}

// Track number of times a reward was received (or attmepted to receive) for sending Wonder News to a link partner.
static void IncrementSentRewardCounter_wonder_news(struct WonderNewsMetadata *data)
{
    data->sentRewardCounter++;
    if (data->sentRewardCounter > MAX_SENT_REWARD_wonder_news)
        data->sentRewardCounter = MAX_SENT_REWARD_wonder_news;
}

static void IncrementRewardCounter_wonder_news(struct WonderNewsMetadata *data)
{
    data->rewardCounter++;
    if (data->rewardCounter > MAX_REWARD_wonder_news)
        data->rewardCounter = MAX_REWARD_wonder_news;
}

static u32 GetRewardType_wonder_news(struct WonderNewsMetadata *data)
{
    if (data->rewardCounter == MAX_REWARD_wonder_news)
        return NEWS_REWARD_AT_MAX;

    switch (data->newsType)
    {
    case WONDER_NEWS_NONE:
        return NEWS_REWARD_WAITING;
    case WONDER_NEWS_RECV_FRIEND:
        return NEWS_REWARD_RECV_SMALL;
    case WONDER_NEWS_RECV_WIRELESS:
        return NEWS_REWARD_RECV_BIG;
    case WONDER_NEWS_SENT:
        if (data->sentRewardCounter < MAX_SENT_REWARD_wonder_news - 1)
            return NEWS_REWARD_SENT_SMALL;
        return NEWS_REWARD_SENT_BIG;
    default:
        AGB_ASSERT(0);
        return NEWS_REWARD_NONE;
    }
}
